#!/usr/bin/env python3
#
# qnxprobe - decide whether an extraction holds a QNX6 filesystem
# Copyright (c) 2026 Alexis Brignoni
# SPDX-License-Identifier: MIT
#
"""
Is this extraction QNX?

Every constant and every field offset below is read out of the Linux kernel's
own qnx6 driver, not assumed:

  QNX6_SUPER_MAGIC   0x68191122   include/uapi/linux/magic.h:55
  QNX6_BOOTBLOCK_SIZE    0x2000   include/linux/qnx6_fs.h:23
  QNX6_SUPERBLOCK_SIZE    0x200   include/linux/qnx6_fs.h:21
  struct qnx6_super_block          include/linux/qnx6_fs.h:94

fs/qnx6/inode.c reads the first superblock at QNX6_BOOTBLOCK_SIZE and, if the
magic is wrong there, retries at offset 0. It tries little endian first, then
big endian, so both are live in the wild.

A bare 4-byte magic match is NOT a finding: across a 256 MiB scan you expect
about one hit by chance. Each candidate is therefore parsed as a superblock and
its fields checked for internal consistency before it is reported CONFIRMED.

Read-only throughout. Never writes to the image.
"""
import os, re, struct, sys, datetime, json, time, uuid, zipfile, bisect, collections, itertools
import binascii
import getpass
import plistlib
import array

# ewfprobe is vendored beside this file (see vendored.json) so an EnCase/EWF
# .E01 acquisition can be read as an ordinary image. It is optional: without it
# everything else works exactly as before, and an .E01 is refused with a message
# saying what is missing rather than being read as raw bytes, which would find
# no filesystem and look like an empty image.
try:
    import ewfprobe
except ImportError:                  # not on sys.path when imported as a module
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    try:
        import ewfprobe
    except ImportError:
        ewfprobe = None

QNXPROBE_VERSION = "1.76"

QNX6_MAGIC     = 0x68191122
BOOTBLOCK_SIZE = 0x2000
SECTOR         = 512
# How many FAT entries free_extents() reads at once. Four bytes each, so a
# megabyte a pass, which keeps one read per 262,144 clusters instead of one
# per cluster.
FAT_SCAN_ENTRIES = 262144

MBR_QNX_TYPES = {   # util-linux include/pt-mbr-partnames.h v2.40
    0x4d: "QNX4.x", 0x4e: "QNX4.x 2nd part", 0x4f: "QNX4.x 3rd part",
}

# offsets into struct qnx6_super_block, in declaration order
F = dict(magic=0, checksum=4, serial=8, ctime=16, atime=20, flags=24,
         version1=28, version2=30, volumeid=32, blocksize=48,
         num_inodes=52, free_inodes=56, num_blocks=60, free_blocks=64,
         allocgroup=68)

# A filesystem created before QNX6 existed or far in the future is not real.
T_MIN = int(datetime.datetime(1995, 1, 1, tzinfo=datetime.timezone.utc).timestamp())
T_MAX = int(datetime.datetime(2050, 1, 1, tzinfo=datetime.timezone.utc).timestamp())



def sb_slots(fh, base, label, sized_regions):
    """Every offset in this region that could hold a superblock copy.

    Measured on a Ford Sync G4 image: the 0x1000 area reserved for a superblock
    holds TWO 512-byte slots, 0xE00 apart, carrying the current and the previous
    committed generation. Documentation/filesystems/qnx6.rst puts one reserved
    area at 0x2000 (after the bootblock) and a second near the end of the
    filesystem, so both are probed. Yields (absolute offset, offset-in-region).
    """
    rels = [BOOTBLOCK_SIZE, BOOTBLOCK_SIZE + 0xE00, 0, 0xE00]

    # The trailing reserved area. Measured on a Ford Sync G4 image it sits at
    # (partition size - 0x1000), not at (num_blocks * blocksize - 0x1000), so
    # the declared partition size is tried first and the filesystem's own size
    # second.
    ends = []
    for rlabel, rbase, rsize in sized_regions:
        if rbase == base and rsize:
            ends.append(rsize)
    head = check(fh, base + BOOTBLOCK_SIZE) or check(fh, base)
    if head and not head[2]:
        total = head[1]["num_blocks"] * head[1]["blocksize"]
        if 0 < total < (1 << 42):
            ends.append(total)
            # Where the kernel itself reads the second superblock: block
            # sb_num_blocks + (QNX6_BOOTBLOCK_SIZE + QNX6_SUPERBLOCK_AREA) /
            # blocksize, fs/qnx6/inode.c qnx6_fill_super, with the area 0x1000
            # from include/linux/qnx6_fs.h. The region-size candidates above
            # reach the same place only when the partition is exactly
            # BOOTBLOCK + area + volume + area long; this reaches it when the
            # partition is larger, or when there is no partition at all.
            second = BOOTBLOCK_SIZE + 0x1000 + total
            rels += [second, second + 0xE00]
    for e in ends:
        rels += [e - 0x1000, e - 0x200]

    seen = set()
    for rel in rels:
        if rel < 0 or rel in seen:
            continue
        seen.add(rel)
        yield base + rel, rel


def report_generations(copies, sized_regions, how_of):
    """copies: list of (off, how, endian, sb). Group by serial and diff."""
    gens = {}
    for off, how, endian, sb in copies:
        gens.setdefault(sb["serial"], {"sb": sb, "endian": endian, "at": []})
        gens[sb["serial"]]["at"].append(off)
    order = sorted(gens, reverse=True)
    return order, gens


# read_at() is the only path from a walker to the image, so a short answer from
# it is the one signal that a read reached past the end of the file. The walkers
# pad a short block with zeros, which is right for a sector an acquisition could
# not read and hides a cut image completely; this tally lets extract_to_zip()
# tell the two apart, per file, without each walker having to know.
EOF_SHORTFALL = {"bytes": 0}


def read_at(fh, off, n):
    try:
        fh.seek(off); data = fh.read(n)
    except OSError:
        return b""
    if len(data) < n:
        EOF_SHORTFALL["bytes"] += n - len(data)
    return data


class ImageUnreadable(Exception):
    """This tool cannot open the image, and the message says why."""


class ImagePasswordError(ImageUnreadable):
    """An encrypted image (an Apple disk image, an acquisition FTK Imager wrote
    with AD encryption, or an encrypted AFF) was opened without its password
    (``wrong`` is False) or with one that does not open it (``wrong`` is True). A
    caller that asks for the password can tell the two apart and ask again.
    ``needs`` is "password", or "private key" for an AFF, an Apple disk image or an
    AD-encrypted set sealed only to a certificate, which opens with that
    certificate's private key instead."""

    def __init__(self, message, wrong, needs="password"):
        super().__init__(message)
        self.wrong = wrong
        self.needs = needs


# The first eight bytes of each acquisition container the vendored ewfprobe
# knows, as libewf and AFFLIB write them. They are checked here rather than in
# ewfprobe so an acquisition is still recognised, and refused with a useful
# message, when the reader is absent.
EWF_SIGNATURE  = b"EVF\x09\x0d\x0a\xff\x00"     # EWF-E01, and SMART .s01
EWF2_SIGNATURE = b"EVF2\x0d\x0a\x81\x00"        # EWF2-Ex01
AFF_SIGNATURE  = b"AFF10\x0d\x0a\x00"           # AFF, and every file of an AFD
L01_SIGNATURE  = b"LVF\x09\x0d\x0a\xff\x00"     # EnCase logical evidence (L01)
LX01_SIGNATURE = b"LEF2\x0d\x0a\x81\x00"        # EWF2 logical evidence (Lx01)
AD1_SIGNATURE  = b"ADSEGMENTEDFILE\x00"        # FTK Imager logical evidence, every file
# Virtual machine disks. A VHD ends in a 512-byte footer beginning "conectix" (511
# bytes in images older than Virtual PC 2004), and a dynamic or differencing one also
# begins with a copy of it; a VHDX begins "vhdxfile"; a VMDK is a text descriptor
# beginning "# Disk DescriptorFile" or a sparse extent beginning "KDMV" (ESXi's
# "COWD"); a QCOW begins "QFI\xfb" and its version, 1, 2 or 3.
VHD_COOKIE = b"conectix"
VHDX_SIGNATURE = b"vhdxfile"
VMDK_DESCRIPTOR_START = b"# Disk DescriptorFile"
VMDK_SPARSE_MAGIC = b"KDMV"
VMDK_COWD_MAGIC = b"COWD"
QCOW_MAGIC = b"QFI\xfb"
# Apple disk images. A UDIF image (.dmg) ends in a 512-byte trailer beginning
# "koly"; an uncompressed read-write image has none and is plain disk bytes, read
# as raw. A .dmgpart segment of a split .dmg ends in one too, and the reader names
# the .dmg to open instead. A sparse image begins "sprs", an encrypted one
# "encrcdsa". A sparse bundle is a folder whose Info.plist names the sparse bundle
# type; an encrypted one keeps the encrcdsa header in its token file.
UDIF_TRAILER = b"koly"
SPARSEIMAGE_SIGNATURE = b"sprs"
DMG_ENCRYPTED_SIGNATURE = b"encrcdsa"
SPARSEBUNDLE_TYPE = "com.apple.diskimage.sparsebundle"
# FTK Imager's AD encryption wraps every file of an E01, SMART or raw (dd) set; only
# the first file begins with this header, so a later numbered file of a raw set is
# recognised by its first sibling.
ADCRYPT_SIGNATURE = b"ADCRYPT\x00"
# The containers that open only with a password, by acquisition_format()'s label.
PASSWORD_FORMATS = ("DMG_ENCRYPTED", "AD_ENCRYPTED")

# What each container is called in a message, by acquisition_format()'s label.
_ACQUISITION_NAMES = {
    "EWF": "an EnCase/EWF acquisition (.E01, or SMART .s01)",
    "EWF2": "an EWF2 acquisition (.Ex01)",
    "AFF": "an AFF acquisition (.aff)",
    "AFD": "an AFD acquisition (a .afd folder of AFF files)",
    "AFF4": "an AFF4 acquisition (.aff4)",
    "UDIF": "an Apple disk image (.dmg)",
    "SPARSEIMAGE": "an Apple sparse image (.sparseimage)",
    "SPARSEBUNDLE": "an Apple sparse bundle (a .sparsebundle folder)",
    "DMG_ENCRYPTED": "an encrypted Apple disk image (.dmg, .sparseimage or .sparsebundle)",
    "AD_ENCRYPTED": "an acquisition FTK Imager encrypted with AD encryption (.E01, .s01, "
                    ".001 or .ad1)",
    "VHD": "a Microsoft virtual hard disk (.vhd)",
    "VHDX": "a Microsoft virtual hard disk (.vhdx)",
    "VMDK": "a VMware virtual disk (.vmdk)",
    "QCOW": "a QEMU virtual disk (.qcow or .qcow2)",
}


ZIP_SIGNATURE = b"PK\x03\x04"


def _is_aff4(path):
    """ewfprobe's test when it is here; without it, the same two places it reads
    (the first member's name, and the ZIP comment), so an AFF4 is still refused as
    an acquisition rather than read as the bytes of a ZIP."""
    if ewfprobe is not None and hasattr(ewfprobe, "is_aff4"):
        return ewfprobe.is_aff4(path)
    try:
        with open(path, "rb") as fh:
            head = fh.read(30)
            if head[:4] != ZIP_SIGNATURE:
                return False
            if fh.read(struct.unpack_from("<H", head, 26)[0]) == b"container.description":
                return True
            fh.seek(0, os.SEEK_END)
            fh.seek(max(0, fh.tell() - 65557))
            tail = fh.read()
    except (OSError, struct.error):
        return False
    at = tail.rfind(b"PK\x05\x06")
    return at >= 0 and tail[at + 22:at + 29] == b"aff4://"


def _virtual_disk_kind(path):
    """ewfprobe's answer when it is here ("VHD", "VHDX", "VMDK", "QCOW" or None);
    without it, the same bytes it reads (the first 512 and the last 512), so a
    virtual disk is still refused as one rather than read as its container's bytes."""
    if ewfprobe is not None and hasattr(ewfprobe, "virtual_disk_kind"):
        return ewfprobe.virtual_disk_kind(path)
    if os.path.isdir(path):
        return None
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as fh:
            head = fh.read(512)
            fh.seek(max(0, size - 512))
            tail = fh.read(512)
    except OSError:
        return None
    text = head[3:] if head.startswith(b"\xef\xbb\xbf") else head
    if head[:8] == VHDX_SIGNATURE:
        return "VHDX"
    if (head[:4] in (VMDK_SPARSE_MAGIC, VMDK_COWD_MAGIC)
            or text[:len(VMDK_DESCRIPTOR_START)].lower() == VMDK_DESCRIPTOR_START.lower()):
        return "VMDK"
    if head[:4] == QCOW_MAGIC and head[4:8] in (b"\0\0\0\1", b"\0\0\0\2", b"\0\0\0\3"):
        return "QCOW"
    if VHD_COOKIE in (tail[:8], tail[1:9], head[:8]):
        return "VHD"
    return None


def _aff_header_lost(path):
    """True when an AFF segment stands where the AFF header belongs and its tail is
    where its lengths put it, which is how AFFLIB 3.7.22's affcrypto -e leaves a file
    it encrypts in place. ewfprobe reads such a file from its segments."""
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as fh:
            head = fh.read(16)
            if len(head) < 16 or head[:4] != b"AFF\x00":
                return False
            name_len, data_len = struct.unpack_from(">II", head, 4)
            tail = 16 + name_len + data_len
            if name_len > 1024 or tail + 8 > size:
                return False
            fh.seek(tail)
            trailer = fh.read(8)
    except (OSError, struct.error):
        return False
    return trailer[:4] == b"ATT\x00" and struct.unpack(">I", trailer[4:])[0] == tail + 8


def _first_bytes(path, n=8):
    try:
        with open(path, "rb") as fh:
            return fh.read(n)
    except OSError:
        return b""


def _afd_folder(path):
    """The .afd folder path names, as the folder itself or as an .aff file in
    it, the same rule ewfprobe opens a whole AFD by."""
    full = os.path.abspath(path)
    if os.path.isdir(full):
        return full if full.lower().endswith(".afd") else None
    parent = os.path.dirname(full)
    if full.lower().endswith(".aff") and parent.lower().endswith(".afd"):
        return parent
    return None


def _sparsebundle_kind(path):
    """"SPARSEBUNDLE" or "DMG_ENCRYPTED" for a sparse bundle folder, else None."""
    plist = os.path.join(path, "Info.plist")
    try:
        if os.path.getsize(plist) > 1 << 20:
            return None
        with open(plist, "rb") as fh:
            info = plistlib.load(fh)
    except Exception:   # pylint: disable=broad-exception-caught  # a bad plist, any kind
        return None
    if not isinstance(info, dict) or info.get("diskimage-bundle-type") != SPARSEBUNDLE_TYPE:
        return None
    if _first_bytes(os.path.join(path, "token")) == DMG_ENCRYPTED_SIGNATURE:
        return "DMG_ENCRYPTED"
    return "SPARSEBUNDLE"


def _numbered_first(path):
    """The first file (.000 or .001, with the same stem and number of digits) of the
    numbered set path would belong to, when it is on disk, else None."""
    folder, name = os.path.split(os.path.abspath(path))
    stem, dot, suffix = name.rpartition(".")
    if not dot or not stem or not (suffix.isascii() and suffix.isdigit()):
        return None
    for number in (0, 1):
        first = os.path.join(folder, f"{stem}.{number:0{len(suffix)}d}")
        if os.path.isfile(first):
            return first
    return None


def _ad1_first(path):
    """The .ad1 of the AD1 set path would belong to (.ad1, .ad2, ...), when it is on
    disk, else None."""
    folder, name = os.path.split(os.path.abspath(path))
    stem, dot, suffix = name.rpartition(".")
    number = suffix[2:]
    if not dot or suffix[:2].lower() != "ad" or not (number.isascii() and number.isdigit()):
        return None
    try:
        present = {entry.lower(): entry for entry in os.listdir(folder)}
    except OSError:
        return None
    first = present.get(f"{stem}.ad1".lower())
    return os.path.join(folder, first) if first else None


def _opens_with(path):
    """What an encrypted image opens with, "password" or "private key", found by
    opening it with neither, since an AD-encrypted set, an encrypted AFF or an Apple
    disk image sealed only to a certificate asks for its private key instead. None
    for an image that is not encrypted, or that the reader refuses for another reason
    (which opening it will then report)."""
    kind = acquisition_format(path)
    if kind not in ("AD_ENCRYPTED", "AFF", "AFD", "DMG_ENCRYPTED"):
        return None
    if ewfprobe is None:        # refused on opening, naming the missing reader
        return "password" if kind in ("AD_ENCRYPTED", "DMG_ENCRYPTED") else None
    try:
        ewfprobe.open_ewf(path).close()
    except ewfprobe.EwfPasswordRequiredError as exc:
        return getattr(exc, "needs", "password")
    except ewfprobe.EwfError:
        return None
    return None


def needs_password(path):
    """True when path is an image that opens only with its password: an encrypted
    Apple disk image, an acquisition FTK Imager encrypted with AD encryption, or an
    AFF encrypted with a passphrase. An image that a password or a certificate's
    private key opens counts here, since either will do."""
    return _opens_with(path) == "password"


def needs_private_key(path):
    """True when path is an AFF or an Apple disk image sealed only to a certificate,
    which opens with that certificate's RSA private key rather than a password."""
    return _opens_with(path) == "private key"


def acquisition_format(path):
    """What acquisition container path is: "EWF", "EWF2", "AFF", "AFD", "AFF4",
    "UDIF", "SPARSEIMAGE", "SPARSEBUNDLE", "L01", "Lx01", "AD1", "DMG_ENCRYPTED",
    "AD_ENCRYPTED", or a virtual machine disk, "VHD", "VHDX", "VMDK" or "QCOW", or
    None for anything else, which is read as a raw image. An
    AFF4 is a ZIP, and is told from any other ZIP by the volume URI the AFF4
    Standard (5.4) has its writer put in the ZIP comment or in a first member
    named container.description.

    An AFD is a folder whose name ends .afd holding AFF files, the form AFFLIB
    writes when an image is split; it is recognised from the folder or from any
    AFF file in it, because one file holds only some of the image. A sparse bundle
    is a folder too, recognised by its Info.plist whatever it is called. L01, Lx01
    and FTK Imager's AD1 are logical evidence: they hold copies of files, not a
    disk. An AD-encrypted AD1 set is recognised from any of its files by its .ad1.
    A VMDK is recognised from its descriptor or from any of its sparse extents; a
    flat extent holds the disk's bytes as they are and is read as raw.
    """
    if os.path.isdir(path):
        bundle = _sparsebundle_kind(path)
        if bundle:
            return bundle
        folder = _afd_folder(path)
        try:
            names = os.listdir(folder) if folder else []
        except OSError:
            return None
        if any(n.lower().endswith(".aff")
               and _first_bytes(os.path.join(folder, n)) == AFF_SIGNATURE
               for n in names):
            return "AFD"
        return None
    head = _first_bytes(path)
    if head == EWF_SIGNATURE:
        return "EWF"
    if head == EWF2_SIGNATURE:
        return "EWF2"
    if head == AFF_SIGNATURE or _aff_header_lost(path):
        return "AFD" if _afd_folder(path) else "AFF"
    if head == L01_SIGNATURE:
        return "L01"
    if head == LX01_SIGNATURE:
        return "Lx01"
    if head == AD1_SIGNATURE[:8] and _first_bytes(path, 16) == AD1_SIGNATURE:
        return "AD1"
    if head == DMG_ENCRYPTED_SIGNATURE:
        return "DMG_ENCRYPTED"
    if head == ADCRYPT_SIGNATURE:
        return "AD_ENCRYPTED"
    if head[:4] == SPARSEIMAGE_SIGNATURE:
        return "SPARSEIMAGE"
    if head[:4] == ZIP_SIGNATURE and _is_aff4(path):
        return "AFF4"
    virtual = _virtual_disk_kind(path)
    if virtual:
        return virtual
    try:
        size = os.path.getsize(path)
        if size >= 512:
            with open(path, "rb") as fh:
                fh.seek(size - 512)
                if fh.read(4) == UDIF_TRAILER:
                    return "UDIF"
    except OSError:
        return None
    first = _numbered_first(path) or _ad1_first(path)
    if first and _first_bytes(first) == ADCRYPT_SIGNATURE:
        return "AD_ENCRYPTED"
    return None


def _ewf_refused_by_reader(path):
    """True when the vendored reader rejects a damaged acquisition rather than
    returning something that would be walked as though it were an image."""
    if ewfprobe is None:
        return True
    try:
        ewfprobe.open_ewf(path)
    except ewfprobe.EwfError:
        return True
    except Exception:
        return False
    return False


def looks_like_ewf(path):
    """True when the file begins with the EWF (.E01, SMART .s01) or EWF2 (.Ex01)
    signature: a set whose segments ewfprobe.ewf_segments names.

    AFF and AFD are acquisitions too, but not EWF sets, so they are not answered
    here; acquisition_format() names every container open_image() reads.
    """
    return acquisition_format(path) in ("EWF", "EWF2")


class SplitImageError(Exception):
    """A numbered segment set that cannot be joined as it stands: a hole in
    the numbering, no first segment beside the file given, or segments of the
    same stem numbered with a different width."""


class SplitSegmentSizeError(SplitImageError):
    """A numbered segment set whose segments are not one size (split_segments),
    refused unless the caller allows it. Its own class, so a program that offers no
    --allow-unequal-segments can say what to do instead: ``segments`` are the paths
    in order, ``sizes`` their byte counts and ``odd`` the indexes of those that do
    not fit."""

    def __init__(self, message, segments=(), sizes=(), odd=()):
        super().__init__(message)
        self.segments, self.sizes, self.odd = list(segments), list(sizes), list(odd)


def split_segments(path, allow_unequal=False):
    """The segment files of the split raw image that path belongs to, in order.

    FTK Imager and its peers write a raw image as numbered segments (.001,
    .002, ...) unless told to write one file. Handed any one of them, this finds
    the rest beside it: same directory, same stem, a suffix of the same number
    of digits. Returns [] when path is not that (the suffix is not all digits,
    or no other segment of the set is beside it), so a lone first segment is
    still read as the one file it is, and the short-image warning in main() is
    what says so.

    A set is joined only when it is whole from its first segment. A hole in the
    numbering, a set whose lowest segment is not .000 or .001, and segments of
    the same stem numbered with a different width are each refused with
    SplitImageError naming what is missing or odd, rather than joined around:
    a join with a gap reads every volume past it at the wrong offset and
    answers wrong, not empty.

    Since 1.75 so is a set whose segments before the last differ in size, or
    whose last is larger than the first. A segment cut short (or padded) moves
    every byte after it the same way a hole does, and a cut that falls in space
    no volume uses draws no other warning. A tool that splits at a fixed segment
    size writes no such set. ``allow_unequal`` joins
    such a set as it is, for one known to be whole (``--allow-unequal-segments``
    on the command line).
    """
    folder, name = os.path.split(os.path.abspath(path))
    stem, dot, suffix = name.rpartition(".")
    if not dot or not stem or not (suffix.isascii() and suffix.isdigit()):
        return []
    width = len(suffix)
    present, other_width = {}, []
    for entry in os.listdir(folder):
        s, d, n = entry.rpartition(".")
        if not (d and s == stem and n.isascii() and n.isdigit()):
            continue
        if not os.path.isfile(os.path.join(folder, entry)):
            continue
        if len(n) == width:
            present[int(n)] = os.path.join(folder, entry)
        else:
            other_width.append(entry)
    if len(present) < 2 and not other_width:
        return []
    if other_width:
        raise SplitImageError(
            f"{name} sits beside segments of the same stem numbered with a "
            f"different number of digits ({', '.join(sorted(other_width)[:3])}"
            f"{', ...' if len(other_width) > 3 else ''}). Not joined: check the "
            f"numbering and rename the set to one width.")
    first = min(present)
    if first > 1:
        raise SplitImageError(
            f"{name} is one segment of a split image and the first segment, "
            f"{stem}.{1:0{width}d}, is not beside it (the lowest here is "
            f"{stem}.{first:0{width}d}). Put the whole set in one folder.")
    run, n = [], first
    while n in present:
        run.append(present[n])
        n += 1
    if len(run) < len(present):
        raise SplitImageError(
            f"{name} is one segment of a split image with a hole in it: "
            f"{stem}.{n:0{width}d} is missing while {stem}.{max(present):0{width}d} "
            f"is here. Put the whole set in one folder; a set joined around a "
            f"hole reads every volume past it at the wrong offset.")
    if not allow_unequal:
        sizes = [os.path.getsize(p) for p in run]
        odd = [i for i, s in enumerate(sizes[:-1]) if s != sizes[0]]
        if sizes[-1] > sizes[0]:
            odd.append(len(run) - 1)
        if odd:
            shown = ", ".join(f"{os.path.basename(run[i])} is {sizes[i]:,} bytes"
                              for i in odd[:3])
            raise SplitSegmentSizeError(
                f"{name} is one segment of a split image whose segments are not one "
                f"size: {os.path.basename(run[0])} is {sizes[0]:,} bytes and {shown}"
                f"{', ...' if len(odd) > 3 else ''}. Not joined: a segment cut short "
                f"or padded reads every byte after it at the wrong offset. Compare the "
                f"segments with the acquisition's own record; if the set is whole as "
                f"it is, read it with --allow-unequal-segments.", run, sizes, odd)
    return run


def disk_identity(path):
    """What says two paths open the same disk: (device, inode) of the file the
    image is read from first, after links are resolved. A split raw set and an
    EWF set are read from their first segment whichever segment is named, so two
    segments of one set are one disk, as are a hard link, a symbolic link and two
    spellings of one path; an AFD is its folder. None when the path cannot be
    stat'ed. Two different files holding the same bytes are two disks here."""
    full = os.path.realpath(os.fspath(path))
    first = full
    try:
        kind = acquisition_format(full)
        if kind in ("EWF", "EWF2") and ewfprobe is not None:
            first = (ewfprobe.ewf_segments(full) or [full])[0]
        elif kind == "AFD":
            first = _afd_folder(full) or full
        elif kind is None:
            first = (split_segments(full, allow_unequal=True) or [full])[0]
    except (SplitImageError, OSError, ValueError,
            *((ewfprobe.EwfError,) if ewfprobe is not None else ())):
        first = full
    try:
        st = os.stat(os.path.realpath(first))
    except OSError:
        return None
    return (st.st_dev, st.st_ino)


def same_disk_paths(paths):
    """[(path, None or the path given before it that opens the same disk)] for
    the image paths given, in order: a path that opens a disk already given
    (disk_identity) is read once, as the one given first."""
    out, seen = [], {}
    for img_path in paths:
        ident = disk_identity(img_path)
        if ident is not None and ident in seen:
            out.append((img_path, seen[ident]))
            continue
        if ident is not None:
            seen[ident] = img_path
        out.append((img_path, None))
    return out


def same_disk_note(img_path, first):
    """What the report says of `img_path`, left out because it opens the disk
    `first` opens (same_disk_paths): the same file, or one file of the set
    opened from `first`, which is not the same thing as the same disk."""
    def own(where):
        try:
            st = os.stat(os.path.realpath(os.fspath(where)))
        except OSError:
            return None
        return (st.st_dev, st.st_ino)
    if own(img_path) is not None and own(img_path) == own(first):
        return f"the same disk as {first}, read once"
    try:
        kind = acquisition_format(os.path.realpath(img_path))
    except OSError:
        kind = None
    what = {"EWF": "the EWF set", "EWF2": "the EWF set", "AFD": "the AFD",
            None: "the split set"}.get(kind, "the image")
    return f"read as a segment of {what} opened from {first}, not on its own"


SPLIT_STRUCTURE_CHECKED = 64     # later segments of a split set looked at for a disk's start


def split_segment_starts(segments):
    """[(segment path, what it begins with)] for the segments after the first
    of a split raw set that begin as a disk does: an md superblock where a
    member keeps one (for the last segment, only at its start) or a partition
    table. A segment of one image starts wherever the cut fell, so this
    suggests separate disks named like a split set (split_segments joins files
    by name alone). Only the first SPLIT_STRUCTURE_CHECKED are looked at."""
    out = []
    last = list(segments)[-1] if segments else None
    for seg in list(segments)[1:SPLIT_STRUCTURE_CHECKED + 1]:
        try:
            with open(seg, "rb") as fh:
                size = image_size(fh)
                sb = md_member(fh, 0, size)
                # the last segment ends where the disk does, so a 0.90 or 1.0
                # superblock at its end is the disk's own; only one at its start
                # (1.1, 1.2) says the segment begins as a member does
                if sb is not None and (seg != last or sb.at < 8192):
                    out.append((seg, "an md superblock"))
                elif parse_gpt(fh) is not None:
                    out.append((seg, "a GPT partition table"))
                elif parse_mbr(fh):
                    out.append((seg, "an MBR partition table"))
                # A filesystem at a segment's first byte is not counted: a
                # volume, an md member's data or an XFS allocation group can
                # start where a cut falls in one image (seen on fixtures cut
                # at 1 MiB and into six pieces).
        except Exception:                              # pylint: disable=broad-except
            continue
    return out


def split_structure_warning(segments):
    """The report's WARNING line for split_segment_starts(), or None."""
    hits = split_segment_starts(segments)
    if not hits:
        return None
    named = ", ".join(f"{os.path.basename(p)} ({what})" for p, what in hits)
    stem = os.path.basename(segments[0]).rpartition(".")[0]
    return (f"WARNING  later segments of this split set begin as a disk does: "
            f"{named}. They may be separate disks whose names only look like one split "
            f"image. Files named {stem}.001, {stem}.002 ... in one folder are always joined "
            f"as one image; to read them as separate images, give copies named otherwise "
            f"(such as {stem}-1.img, {stem}-2.img)")


class SegmentedImage:
    """The numbered segments of a split raw image, read as one file.

    Every walker reaches the image through read_at(), which only seeks and
    reads, so this stands in for the file object: a byte offset is mapped onto
    the segment that holds it and a read that crosses a segment boundary is
    served from both sides. A read past the end of the last segment comes back
    short, exactly as it does from one file, so read_at()'s shortfall tally and
    the short-image warning keep their meaning on a set whose last segments are
    missing (which no numbering check can see: the set simply ends early).

    At most MAX_OPEN segment files are held open at once, least recently used
    closed first, so a set of hundreds of segments does not exhaust the
    process's file descriptors.
    """
    MAX_OPEN = 16

    def __init__(self, paths):
        self.paths = [os.fspath(p) for p in paths]
        self.sizes = [os.path.getsize(p) for p in self.paths]
        self.starts, total = [], 0
        for s in self.sizes:
            self.starts.append(total)
            total += s
        self.size = total
        self.name = self.paths[0]
        self._pos = 0
        self._open = collections.OrderedDict()

    def _handle(self, i):
        fh = self._open.get(i)
        if fh is None:
            fh = open(self.paths[i], "rb")
            self._open[i] = fh
            while len(self._open) > self.MAX_OPEN:
                self._open.popitem(last=False)[1].close()
        else:
            self._open.move_to_end(i)
        return fh

    def seek(self, offset, whence=0):
        if whence == 0:
            pos = offset
        elif whence == 1:
            pos = self._pos + offset
        elif whence == 2:
            pos = self.size + offset
        else:
            raise ValueError(f"invalid whence ({whence!r}, should be 0, 1 or 2)")
        if pos < 0:
            raise OSError(22, "Invalid argument")
        self._pos = pos
        return pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if n is None or n < 0:
            n = max(self.size - self._pos, 0)
        out, pos = [], self._pos
        while n > 0 and pos < self.size:
            # bisect_right lands on the last segment starting at or before pos,
            # which steps over any zero-length segment sharing that start
            i = bisect.bisect_right(self.starts, pos) - 1
            fh = self._handle(i)
            fh.seek(pos - self.starts[i])
            chunk = fh.read(min(n, self.starts[i] + self.sizes[i] - pos))
            if not chunk:
                break                  # the segment is shorter on disk than when measured
            out.append(chunk)
            pos += len(chunk)
            n -= len(chunk)
        self._pos = pos
        return b"".join(out)

    def close(self):
        for fh in self._open.values():
            fh.close()
        self._open.clear()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


def image_size(fh):
    """Byte length of the image behind fh, one file or a joined segment set."""
    size = getattr(fh, "size", None)
    if size is not None:
        return size
    try:
        return os.fstat(fh.fileno()).st_size
    except (AttributeError, OSError, ValueError):
        # No file descriptor behind it. Anything seekable can still say where
        # its end is, which is what a reader over a container answers to.
        here = fh.tell()
        try:
            fh.seek(0, os.SEEK_END)
            return fh.tell()
        finally:
            fh.seek(here)


def open_image(path, segments=None, password=None, private_key=None,
               allow_unequal_segments=False):
    """Open an image read-only: the one file, or every segment of the split
    image it belongs to, joined. segments is split_segments(path) when the
    caller already has it. password opens an encrypted Apple disk image, an
    acquisition FTK Imager encrypted with AD encryption or an encrypted AFF (a str,
    used as UTF-8, or bytes), and private_key (a path to, or the bytes of, an
    unencrypted PEM or DER RSA key) an AFF, an Apple disk image or an AD-encrypted set
    sealed to a certificate; without what
    opens it, or with one that does not, ImagePasswordError is raised. Other
    images ignore both. allow_unequal_segments joins a split set whose segments
    are not one size (split_segments)."""
    kind = acquisition_format(path)
    name = os.path.basename(os.path.normpath(path))
    if kind in ("L01", "Lx01", "AD1"):
        # Read as raw bytes this would hold no partition table and no
        # filesystem, and the run would report an empty disk.
        raise ImageUnreadable(_logical_refusal(name, kind))
    if kind:
        if ewfprobe is None:
            raise ImageUnreadable(
                f"{name} is {_ACQUISITION_NAMES[kind]}. "
                f"Reading one needs ewfprobe.py beside this script; it is "
                f"normally vendored here (see vendored.json) and is missing. "
                f"Export the image to raw, or put ewfprobe.py back.")
        # ewfprobe joins the segments or files of the set itself, from the
        # format's own records rather than from the file names, and refuses an
        # incomplete set. It decrypts an encrypted image given what opens it; without
        # the optional cipher package it refuses the image, naming the package.
        given = {"password": password}
        if private_key is not None:
            given["private_key"] = private_key
        try:
            image = ewfprobe.open_ewf(path, **given)
        except ewfprobe.EwfPasswordError as exc:
            raise ImagePasswordError(
                str(exc), isinstance(exc, ewfprobe.EwfWrongPasswordError),
                getattr(exc, "needs", "password")) from None
        # What an AD-encrypted set decrypts to can be logical evidence as well
        inner = {"EWF-L01": "L01", "AD1": "AD1"}.get(getattr(image, "format", None))
        if inner:
            image.close()
            raise ImageUnreadable(_logical_refusal(name, inner, encrypted=True))
        return image
    if os.path.isdir(path):
        # Before 1.74 a folder reached open() and the run ended in an
        # IsADirectoryError traceback.
        raise ImageUnreadable(_folder_refusal(path))
    if segments is None:
        segments = split_segments(path, allow_unequal=allow_unequal_segments)
    if segments:
        return SegmentedImage(segments)
    return open(path, "rb")


def _folder_refusal(path):
    """Why a folder given as an image is not read. The two folder forms that are
    read, a sparse bundle and an AFD, never get here: acquisition_format() has
    already named them."""
    why = ("a .afd folder with no file in it that starts with the AFF signature, so "
           "it is not an AFD" if _afd_folder(path) else "a folder, not a disk image")
    return (f"{path} is {why}. The folders read as images are an Apple sparse bundle "
            f"(recognised by its Info.plist) and an AFD (a .afd folder of AFF files); "
            f"give the image file itself for anything else")


def _logical_refusal(name, kind, encrypted=False):
    """Why logical evidence is not read as a disk, and what reads its files."""
    maker = "FTK Imager" if kind == "AD1" else "EnCase"
    reader = ("the vendored ewfprobe does not read Lx01" if kind == "Lx01" else
              "ewfprobe lists and exports them (ewfprobe.py files, "
              "ewfprobe.py export --entry)")
    locked = ", encrypted with AD encryption" if encrypted else ""
    return (f"{name} is {maker} logical evidence ({kind}){locked}: it holds copies of "
            f"files, not a disk, so there is no partition table or filesystem in it "
            f"to read. For its files, {reader}.")


# The container ewfprobe reports, by its format label, as a run describes it.
_ACQUISITION_LABELS = {
    "EWF-E01": "an EWF acquisition",
    "EWF-S01": "a SMART (EWF-S01) acquisition",
    "EWF2-Ex01": "an EWF2 (Ex01) acquisition",
    "AFF": "an AFF acquisition",
    "AFD": "an AFD acquisition",
    "AFF4": "an AFF4 acquisition",
    "UDIF": "an Apple disk image",
    "SPARSEIMAGE": "an Apple sparse image",
    "SPARSEBUNDLE": "an Apple sparse bundle",
    "UDRW": "an Apple read-write disk image",
    "AFM": "an AFM acquisition",
    "RAW": "a raw (dd) image",
    "VHD": "a VHD virtual disk",
    "VHDX": "a VHDX virtual disk",
    "VMDK": "a VMDK virtual disk",
    "QCOW": "a QCOW virtual disk",
}


def describe_acquisition(image):
    """'an EWF acquisition of 3 segments, joined by the reader: x.E01 .. x.E03'
    for an image open_image() handed to ewfprobe."""
    parts = list(getattr(image, "paths", []) or [])
    fmt = getattr(image, "format", None)
    crypt = getattr(image, "encryption", None)
    opener = ("its private key" if str((crypt or {}).get("opened_with", ""))
              .startswith("private key") else "its password")
    locked = (f", encrypted ({crypt['cipher']}) and opened with {opener}"
              if crypt else "")
    if fmt == "SPARSEBUNDLE":
        bundle = getattr(image, "sparsebundle", None) or {}
        stored = bundle.get("bands_stored", 0)
        return (f"an Apple sparse bundle of {stored:,} stored band "
                f"file{'' if stored == 1 else 's'}, read by the reader{locked}")
    label = _ACQUISITION_LABELS.get(fmt, "an acquisition")
    unit = ("files" if fmt in ("AFF", "AFD", "AFM", "AFF4", "UDIF", "SPARSEIMAGE",
                               "UDRW", "VHD", "VHDX", "VMDK", "QCOW")
            else "segments")
    # a differencing disk, delta or overlay is read through the disks under it
    parents = [os.path.basename((getattr(q, "paths", None) or ["?"])[0])
               for q in _parent_chain(image)]
    over = ""
    if len(parents) == 1:
        over = f", over its parent {parents[0]}"
    elif parents:
        over = f", over its parents {', '.join(parents)} (nearest first)"
    if len(parts) > 1:
        return (f"{label} of {len(parts)} {unit}, joined by the reader: "
                f"{os.path.basename(parts[0])} .. {os.path.basename(parts[-1])}"
                f"{over}{locked}")
    return f"{label} of one {unit[:-1]}{over}{locked}"


def _parent_chain(image):
    """The disks a virtual disk is read over (a differencing VHD or VHDX's parent, a
    VMDK delta's, a QCOW overlay's backing file), nearest first; [] for any other
    image. The reader caps a chain's length, and so does this."""
    out, parent = [], getattr(image, "parent", None)
    while parent is not None and len(out) < 64:
        out.append(parent)
        parent = getattr(parent, "parent", None)
    return out


def image_parents(image):
    """Every file of the disks a virtual disk is read over, nearest disk first, each
    as {"name", "bytes"}; [] for any other image."""
    out = []
    for parent in _parent_chain(image):
        for q in list(getattr(parent, "paths", []) or []):
            try:
                out.append({"name": os.path.basename(q), "bytes": os.path.getsize(q)})
            except OSError:
                out.append({"name": os.path.basename(q), "bytes": None})
    return out


def describe_segment_sizes(sizes):
    """'19 x 1,572,864,000 bytes, then 1,384,120,320 bytes' for the shape an
    imaging tool writes; every size listed when they do not follow it."""
    if len(sizes) > 1 and len(set(sizes[:-1])) == 1:
        return f"{len(sizes) - 1} x {sizes[0]:,} bytes, then {sizes[-1]:,} bytes"
    return ", ".join(f"{s:,}" for s in sizes) + " bytes"


def short_regions(size, sized_regions, skip=()):
    """Regions the partition table describes that the file does not hold in full.

    Returns [(label, start, region_size, missing)] for every region whose end
    lies past the end of the file, missing being how many of its bytes are not
    here; missing == region_size means the region begins past the end of the
    file. A file that holds only the first segment of a split acquisition has
    this shape, and nothing else in a probe can tell that case from a small disk.
    """
    out = []
    for label, start, rsize in sized_regions:
        if not rsize or label in skip:
            continue
        end = start + rsize
        if end > size:
            out.append((label, start, rsize, min(rsize, end - size)))
    return out


def ts(v):
    if not (T_MIN <= v <= T_MAX):
        return None
    return datetime.datetime.fromtimestamp(v, datetime.timezone.utc)


def duration(sec):
    """Largest two sensible units, e.g. '3 days 4 hours', '2 seconds'."""
    sec = abs(int(sec))
    if sec == 0:
        return "0 seconds"
    units = (("year", 31557600), ("day", 86400), ("hour", 3600),
             ("minute", 60), ("second", 1))
    parts, rem = [], sec
    for name, size in units:
        if rem >= size:
            n, rem = divmod(rem, size)
            parts.append(f"{n:,} {name}{'' if n == 1 else 's'}")
            if len(parts) == 2:
                break
    return " ".join(parts)


def delta_line(label, new, old):
    """One line describing how a stored time changed between two commits.

    A value outside the plausible range is an unset placeholder, not a date,
    so the difference against it is not a duration and is not reported as one.
    Measured on a Ford Sync G4 image: the previous generation of dps_os holds
    sb_atime 1, which naively differs from the active value by 54 years.
    """
    if new == old:
        return f"        {label:<12} unchanged"
    new_ok, old_ok = ts(new) is not None, ts(old) is not None
    if not old_ok and new_ok:
        return (f"        {label:<12} was unset (raw {old}), now "
                f"{ts(new):%Y-%m-%d %H:%M:%S} UTC   (not a duration)")
    if old_ok and not new_ok:
        return (f"        {label:<12} was {ts(old):%Y-%m-%d %H:%M:%S} UTC, "
                f"now unset (raw {new})   (not a duration)")
    if not new_ok and not old_ok:
        return f"        {label:<12} raw {old} -> raw {new}   (neither is a date)"
    d = new - old
    return (f"        {label:<12} {d:+,} s   ({'forward' if d > 0 else 'back'} "
            f"{duration(d)})")


def stamp(v):
    d = ts(v)
    return (f"{d:%Y-%m-%d %H:%M:%S} UTC" if d
            else f"raw {v}  (no valid clock when written)")


def parse_sb(buf, endian):
    """Parse a candidate superblock. Returns (dict, [reasons it failed])."""
    e = "<" if endian == "little endian" else ">"
    g32 = lambda k: struct.unpack_from(e + "I", buf, F[k])[0]
    g16 = lambda k: struct.unpack_from(e + "H", buf, F[k])[0]
    sb = dict(
        checksum=g32("checksum"),
        serial=struct.unpack_from(e + "Q", buf, F["serial"])[0],
        ctime=g32("ctime"), atime=g32("atime"), flags=g32("flags"),
        version1=g16("version1"), version2=g16("version2"),
        volumeid=buf[F["volumeid"]:F["volumeid"] + 16],
        blocksize=g32("blocksize"), num_inodes=g32("num_inodes"),
        free_inodes=g32("free_inodes"), num_blocks=g32("num_blocks"),
        free_blocks=g32("free_blocks"), allocgroup=g32("allocgroup"),
    )
    bad = []
    bs = sb["blocksize"]
    if not (512 <= bs <= 65536 and (bs & (bs - 1)) == 0):
        bad.append(f"blocksize {bs} not a power of two in 512..65536")
    # An embedded filesystem is often built on a host with no clock, so ctime
    # legitimately reads as a few seconds past the epoch. Measured on a Ford
    # Sync G4 dps_os partition: ctime 308, atime 2024-04-04, everything else
    # consistent and the volume size an exact match for its GPT entry.
    # Requiring BOTH timestamps rejected a real filesystem, so require one.
    if ts(sb["ctime"]) is None and ts(sb["atime"]) is None:
        bad.append(f"neither ctime ({sb['ctime']}) nor atime ({sb['atime']}) "
                   f"is a plausible date")
    if sb["free_blocks"] > sb["num_blocks"]:
        bad.append("free_blocks > num_blocks")
    if sb["free_inodes"] > sb["num_inodes"]:
        bad.append("free_inodes > num_inodes")
    if sb["num_blocks"] == 0:
        bad.append("num_blocks is zero")
    if sb["num_inodes"] == 0:
        bad.append("num_inodes is zero")
    return sb, bad


def check(fh, off):
    """Return (endian, sb, bad) if magic is at off, else None."""
    buf = read_at(fh, off, 512)
    if len(buf) < 512:
        return None
    for e, pk in (("little endian", "<I"), ("big endian", ">I")):
        if struct.unpack_from(pk, buf, 0)[0] == QNX6_MAGIC:
            sb, bad = parse_sb(buf, e)
            return e, sb, bad
    return None


def parse_mbr(fh):
    mbr = read_at(fh, 0, 512)
    if len(mbr) < 512 or mbr[510:512] != b"\x55\xaa":
        return None
    # A FAT, exFAT, NTFS or BitLocker boot sector also ends in 0x55AA, and its
    # boot code sits where MBR partition entries would be, so it parses as four
    # nonsense partitions. Its own type string at bytes 3..11 (exFAT, NTFS,
    # BitLocker's "-FVE-FS-"), 82..90 (FAT32) or 54..62 (FAT16, FAT12) says it is a volume, not a
    # partition table.
    if (mbr[3:11] in (b"EXFAT   ", b"NTFS    ", BDE_SIGNATURE)
            or mbr[82:90] in (b"FAT32   ", b"TFAT32  ")
            or mbr[54:62] in (b"FAT16   ", b"FAT12   ", b"TFAT16  ")):
        return None
    # A QNX4 boot block can also end in 0x55AA (the dinit boot sector does).
    # The QNX4 superblock is the NEXT sector: its first entry is the root
    # directory inode, di_fname "/" and a directory mode, fs/qnx4/inode.c
    # qnx4_checkroot() and qnx4_iget(). If that is what follows, this sector
    # is a filesystem's boot block, not a partition table.
    nxt = read_at(fh, 512, 64)
    if (len(nxt) == 64 and nxt[0:2] == b"/\x00"
            and (struct.unpack_from("<H", nxt, 50)[0] & 0o170000) == S_IFDIR):
        return None
    # A qnx6 boot block can end in 0x55AA as well. On qnxmount's qnx6
    # reference image sector 0 is x86 boot code, and bytes 446..478 of that
    # code parse as two partitions starting 1.5 and 1.8 TB into a 400 KB file.
    # Accepting them costs the whole filesystem: the qnx6 at offset 0 then has
    # no region to be listed or extracted from, and the end-of-volume
    # superblock, the active generation, is never probed. The Linux driver
    # never reads sector 0; it reads the superblock at QNX6_BOOTBLOCK_SIZE
    # (fs/qnx6/inode.c qnx6_fill_super). A consistent superblock there means
    # this sector is that filesystem's boot block, not a partition table.
    q6 = check(fh, BOOTBLOCK_SIZE)
    if q6 and not q6[2]:
        return None
    out = []
    for i in range(4):
        ent = mbr[446 + i * 16: 446 + (i + 1) * 16]
        t = ent[4]
        start, cnt = struct.unpack("<II", ent[8:16])
        if t and cnt:
            out.append((i + 1, t, start, cnt))
    # Whatever else ends in 0x55AA: a table none of whose partitions begins
    # inside the image is not describing this image, so the bytes at 446 are
    # code or data. The boot indicator byte is deliberately not a test: neither
    # util-linux's libfdisk nor The Sleuth Kit rejects a table on its value.
    try:
        size = image_size(fh)
    except (OSError, AttributeError, ValueError):
        size = None
    if out and size and all(start * SECTOR >= size for _, _, start, _ in out):
        return None
    return out


# The GPT header is at LBA 1, the second logical block (UEFI 2.10 section
# 5.3.1), so its byte offset IS the logical sector size, and every LBA in the
# header, in the partition entries and in the protective MBR counts sectors of
# that size. Most disks use 512. 4Kn drives and UFS LUN images use 4096, and
# read as 512 they show no partition table at all. Only these two are probed.
GPT_SECTOR_SIZES = (512, 4096)
# The largest partition entry array read. The header's CRC is checked before
# the array is, so this bounds a table that is valid but absurd, not noise.
GPT_MAX_ARRAY_BYTES = 16 << 20


class GptTable(list):
    """What parse_gpt returns: [(idx, name, type_guid, first, last)] as before,
    plus sector_size, the logical sector the header was found in, and
    header_lba, 1 for the primary header or the last LBA when the backup was
    read. first and last count sectors of sector_size, so a partition starts
    at byte first * table.sector_size, which is first * SECTOR only at 512."""
    sector_size = SECTOR
    header_lba = 1


def _gpt_header_problem(hdr, ss, lba):
    """Why the header read from this LBA cannot be trusted, or "" if it can.

    The checks and offsets are UEFI 2.10 section 5.3.2, Table 5.5 (GPT Header):
    HeaderSize at 12 must be at least 92 and no larger than the logical block;
    HeaderCRC32 at 16 is the CRC32 of HeaderSize bytes with that field set to
    zero; MyLBA at 24 must name the block the header was read from. The same
    checks, in the same order, are is_gpt_valid() in Linux
    block/partitions/efi.c (v6.12, commit adc21867, lines 355 to 391). The
    kernel also requires the usable range to lie within the disk; that check
    is left out here on purpose, because the first segment of a split image
    holds a table describing more than the file holds, and that has to be
    reported as a short image (short_regions), not as a disk with no table.
    """
    hsize = struct.unpack_from("<I", hdr, 12)[0]
    if not 92 <= hsize <= ss:
        return f"HeaderSize {hsize} is not between 92 and the {ss}-byte sector"
    want = struct.unpack_from("<I", hdr, 16)[0]
    # binascii.crc32 is the CRC the spec names: the Ethernet polynomial seeded
    # with ~0 and inverted at the end, which is how efi.c's efi_crc32 (lines
    # 119 to 123) builds it from the kernel's own crc32.
    got = binascii.crc32(hdr[:16] + b"\x00" * 4 + hdr[20:hsize]) & 0xFFFFFFFF
    if got != want:
        return f"HeaderCRC32 0x{want:08x} does not match the header (0x{got:08x})"
    my_lba = struct.unpack_from("<Q", hdr, 24)[0]
    if my_lba != lba:
        return f"MyLBA is {my_lba}, and the header was read from LBA {lba}"
    return ""


def _gpt_at(fh, ss, lba):
    """(GptTable or None, why) for a header at this LBA of ss-byte sectors.

    why is None when there is no "EFI PART" signature there at all, a reason
    when there is one and it fails a check, and "" when the table is used.
    Entries are read per Table 5.6 (GPT Partition Entry): PartitionTypeGUID at
    0 (all zero means the entry is unused), StartingLBA at 32, EndingLBA at 40,
    PartitionName at 56 for 72 bytes.
    """
    hdr = read_at(fh, lba * ss, ss)
    if len(hdr) < 92 or hdr[0:8] != b"EFI PART":
        return None, None
    why = _gpt_header_problem(hdr, ss, lba)
    if why:
        return None, why
    # Table 5.5: PartitionEntryLBA at 72, NumberOfPartitionEntries at 80,
    # SizeOfPartitionEntry at 84 (128 x 2^n now; earlier versions of the spec
    # allowed any multiple of 8), and at 88 the CRC32 of
    # NumberOfPartitionEntries * SizeOfPartitionEntry bytes.
    ent_lba, n_ent, ent_sz, arr_crc = struct.unpack_from("<QIII", hdr, 72)
    nbytes = n_ent * ent_sz
    if ent_sz < 128 or ent_sz % 8:
        return None, f"SizeOfPartitionEntry {ent_sz} is not a multiple of 8 of at least 128"
    if nbytes > GPT_MAX_ARRAY_BYTES:
        return None, (f"the entry array would be {nbytes:,} bytes, more than "
                      f"the {GPT_MAX_ARRAY_BYTES:,} read")
    arr = read_at(fh, ent_lba * ss, nbytes)
    if len(arr) < nbytes:
        return None, f"the entry array at LBA {ent_lba} lies past the end of the file"
    if binascii.crc32(arr) & 0xFFFFFFFF != arr_crc:
        return None, (f"PartitionEntryArrayCRC32 0x{arr_crc:08x} does not match "
                      f"the entry array")
    table = GptTable()
    table.sector_size, table.header_lba = ss, lba
    for i in range(n_ent):
        raw = arr[i * ent_sz:(i + 1) * ent_sz]
        tguid = raw[0:16]
        if tguid == b"\x00" * 16:
            continue
        first, last = struct.unpack_from("<QQ", raw, 32)
        name = raw[56:128].decode("utf-16-le", "replace").rstrip("\x00").strip()
        g = uuid.UUID(bytes_le=tguid)
        table.append((i + 1, name, str(g), first, last))
    return table, ""


def _has_protective_mbr(fh):
    """True when sector 0 ends 0x55AA and one of its four records is type 0xEE,
    the GPT protective type (UEFI 2.10 section 5.2.2 and Table 5.4)."""
    mbr = read_at(fh, 0, 512)
    return (len(mbr) == 512 and mbr[510:512] == b"\x55\xaa"
            and any(mbr[446 + 16 * i + 4] == 0xEE for i in range(4)))


def read_gpt(fh):
    """(table, rejected): the GPT to use, and every header that was refused.

    table is a GptTable, or None when no header validates. rejected lists
    (byte offset, reason) for every "EFI PART" signature found that failed a
    check, so a report can say a table was there and why it was not used,
    rather than showing a disk with no partition table.

    The primary header at LBA 1 is tried at 512 and then at 4096 bytes a
    sector; the first that validates, with an entry array matching its CRC,
    is used. When none does, section 5.3.2 says "the backup GPT is used
    instead and it is located on the last logical block on the disk", so that
    block is tried at each size. The same section warns that a disk
    reformatted to a legacy MBR can keep a stale GPT in its last block, so the
    backup is only read when sector 0 holds a 0xEE record. Linux likewise
    reads no GPT unless sector 0 is a protective or hybrid MBR (efi.c
    find_valid_gpt, lines 597 to 612), and reads the backup only when forced
    to (lines 617 to 622); util-linux sfdisk 2.41.3 reads the backup when the
    primary is corrupt, as the spec says. Nothing is ever written back.
    """
    rejected = []
    for ss in GPT_SECTOR_SIZES:
        table, why = _gpt_at(fh, ss, 1)
        if table is not None:
            return table, rejected
        if why:
            rejected.append((ss, why))
    if _has_protective_mbr(fh):
        try:
            size = image_size(fh)
        except (OSError, AttributeError, ValueError):
            size = None
        for ss in GPT_SECTOR_SIZES:
            last = (size // ss - 1) if size else 0
            if last < 2:
                continue
            table, why = _gpt_at(fh, ss, last)
            if table is not None:
                return table, rejected
            if why:
                rejected.append((last * ss, why))
    return None, rejected


def parse_gpt(fh):
    """The primary GPT as a GptTable of (idx, name, type_guid, first, last), or None.

    first and last are in the table's own logical sectors: multiply by the
    returned table's sector_size, not by SECTOR, to reach a byte offset.
    """
    return read_gpt(fh)[0]


def disk_sector_size(fh):
    """The logical sector size partition LBAs on this image count: the one a
    valid GPT was found at, else 512. The legacy and protective MBR count the
    same logical blocks (UEFI 2.10 Table 5.2, SizeInLBA "in LBA units of logical
    blocks"; Table 5.4, the protective StartingLBA is 1, "the LBA of the GPT
    Partition Header"), so this is the unit for both tables."""
    gpt = parse_gpt(fh)
    # An empty table is falsy: a valid GPT with no used entry still names the
    # sector size, so the test is for no table, not for no entries.
    return gpt.sector_size if gpt is not None else SECTOR


# ---------------------------------------------------------------------------
# What is actually in a partition, when it is not qnx6.
#
# A partition type byte is a label, not a fact. The BMW MGU image carries
# twelve partitions marked 0x83 "Linux"; ten hold ext4, one holds an ipk
# container with a Linux bzImage inside it, and one is the extended-partition
# container itself. So the type byte is reported, and then the bytes are read.
#
# ext offsets below were derived from struct ext4_super_block in the kernel's
# fs/ext4/ext4.h and cross-checked against that header's own /*NN*/ offset
# markers, all 15 of which agreed, with the struct totalling 1024 bytes.
# EXT2_SUPER_MAGIC 0xEF53 is from include/uapi/linux/magic.h:24.
# ---------------------------------------------------------------------------
EXT_SB_OFF   = 1024
EXT_MAGIC    = 0xEF53
EXT_F = dict(inodes_count=0, blocks_count=4, free_blocks=12, first_data_block=20,
             log_block_size=24, inodes_per_group=40, mtime=44, wtime=48,
             mnt_count=52, magic=56, state=58, lastcheck=64, inode_size=88,
             feature_compat=92, feature_incompat=96, uuid=104, volume_name=120,
             last_mounted=136, desc_size=254, mkfs_time=264, kbytes_written=376,
             error_count=404)
EXT_INCOMPAT_EXTENTS  = 0x0040   # ext4.h
EXT_COMPAT_HAS_JOURNAL = 0x0004  # ext4.h
EXT_VALID_FS = 0x0001            # ext4.h
EXT_GOOD_OLD_INODE_SIZE = 128    # ext4.h EXT4_GOOD_OLD_INODE_SIZE
EXT4_EPOCH_BITS = 2              # ext4.h; the low bits of an i_*time_extra field
EXT4_EPOCH_MASK = (1 << EXT4_EPOCH_BITS) - 1
EXT4_EA_INODE_FL = 0x200000      # ext4.h; the inode holds an extended attribute value


def _e(sb, k, n=4):
    o = EXT_F[k]
    return int.from_bytes(sb[o:o + n], "little")


# ---------------------------------------------------------------------------
# Directory listing (--list)
#
# qnx6 block resolution follows fs/qnx6/inode.c qnx6_block_map():
#   ptrbits  = ilog2(blocksize / 4)                          inode.c:431
#   blks_off = (0x2000 >> bits) + (0x1000 >> bits)            inode.c:374
#   devblock = stored_block + blks_off                        inode.c:68
# Structure layouts are struct qnx6_inode_entry, qnx6_dir_entry,
# qnx6_long_dir_entry and qnx6_root_node in include/linux/qnx6_fs.h.
#
# ext4 layouts are struct ext4_super_block, ext4_group_desc, ext4_inode and
# ext4_dir_entry_2 in fs/ext4/ext4.h, plus the extent structures in
# fs/ext4/ext4_extents.h (EXT4_EXT_MAGIC 0xf30a).
# ---------------------------------------------------------------------------
QNX6_INODE_SIZE  = 0x80
QNX6_DIRENT_SIZE = 0x20
QNX6_ROOT_INO    = 1
QNX6_ROOTNODE    = dict(Inode=72, Bitmap=152, Longfile=232)   # offsets inside the superblock
S_IFDIR, S_IFLNK = 0o040000, 0o120000
S_IFMT, S_IFREG = 0o170000, 0o100000     # the format bits, and a regular file


def _fmt_time(v):
    """Per-file mtime. Unlike a superblock stamp, an epoch-era value here is
    ordinary on an embedded image (files staged before the clock was set), so
    it is shown rather than suppressed. None is a time the filesystem does not
    record at all (a raw UBI volume, YAFFS's built-in directories), and is
    shown as nothing rather than as a date."""
    if v is None:
        return ""
    try:
        return datetime.datetime.fromtimestamp(
            v, datetime.timezone.utc).strftime("%Y-%m-%d")
    except (OverflowError, OSError, ValueError):
        return "-"


def _fmt_reading(recorded):
    """A file's modified reading from a walker that keeps readings, as text.

    FAT32 and exFAT store a wall clock and no zone, so ``entry()`` gives them an
    mtime of 0 and the readings arrive through listdir_records() instead. A
    listing prints the reading as stored, marked so it cannot be read as an
    instant, and prints nothing rather than 1970-01-01 when there is none. exFAT
    also stores a UTC offset beside each stamp; it is shown and not applied, the
    stance GLEAPP takes on the same field, since one writer has been measured
    and a listing should not assert an instant from it.
    """
    when = (recorded or {}).get("modified")
    if not when:
        return ""
    off = recorded.get("modified utc offset")
    return f"modified {when} (as stored, {'offset ' + off + ' not applied' if off else 'no zone'})"


class Qnx6Walker:
    def __init__(self, fh, base, sb_off):
        self.fh, self.base = fh, base
        sb = read_at(fh, base + sb_off, 512)
        self.bs = struct.unpack_from("<I", sb, 48)[0]
        bits = self.bs.bit_length() - 1
        self.ptrbits = (self.bs // 4).bit_length() - 1
        self.blks_off = (0x2000 >> bits) + (0x1000 >> bits)
        self.inode_rn = self._rn(sb, QNX6_ROOTNODE["Inode"])
        self.long_rn = self._rn(sb, QNX6_ROOTNODE["Longfile"])
        # what free_extents() reads: sb_num_blocks, sb_free_blocks and the
        # Bitmap root node with its size in bytes
        self.num_blocks, self.free_blocks = struct.unpack_from("<II", sb, F["num_blocks"])
        self.bitmap_rn = self._rn(sb, QNX6_ROOTNODE["Bitmap"])
        self.bitmap_bytes = struct.unpack_from("<Q", sb, QNX6_ROOTNODE["Bitmap"])[0]

    @staticmethod
    def _rn(sb, o):
        return dict(ptr=list(struct.unpack_from("<16I", sb, o + 8)), levels=sb[o + 72])

    def _blk(self, b):
        return read_at(self.fh, self.base + b * self.bs, self.bs)

    def _map(self, ptrs, levels, n):
        bitdelta = self.ptrbits * levels
        mask = (1 << self.ptrbits) - 1
        lp = n >> bitdelta
        if lp > 15:
            return None
        blk = ptrs[lp] + self.blks_off
        for _ in range(levels):
            buf = self._blk(blk)
            if len(buf) < self.bs:
                return None
            bitdelta -= self.ptrbits
            ptr = struct.unpack_from("<I", buf, ((n >> bitdelta) & mask) * 4)[0]
            if ptr in (0, 0xFFFFFFFF):
                return None
            blk = ptr + self.blks_off
        return blk

    def _tree(self, rn, logical):
        b = self._map(rn["ptr"], rn["levels"], logical)
        return self._blk(b) if b is not None else None

    def inode(self, num):
        byte = (num - 1) * QNX6_INODE_SIZE
        buf = self._tree(self.inode_rn, byte // self.bs)
        if not buf:
            return None
        raw = buf[byte % self.bs:][:QNX6_INODE_SIZE]
        if len(raw) < QNX6_INODE_SIZE:
            return None
        return dict(size=struct.unpack_from("<Q", raw, 0)[0],
                    mtime=struct.unpack_from("<I", raw, 20)[0],
                    mode=struct.unpack_from("<H", raw, 32)[0],
                    ptr=list(struct.unpack_from("<16I", raw, 36)),
                    levels=raw[100])

    def _longname(self, blk):
        buf = self._tree(self.long_rn, blk)
        if not buf:
            return "<longname unreadable>"
        n = struct.unpack_from("<H", buf, 0)[0]
        return buf[2:2 + min(n, 510)].decode("utf-8", "replace")

    def listdir(self, num):
        ino = self.inode(num)
        if not ino or not (ino["mode"] & S_IFDIR):
            return []
        out = []
        for lb in range((ino["size"] + self.bs - 1) // self.bs):
            b = self._map(ino["ptr"], ino["levels"], lb)
            if b is None:
                continue
            buf = self._blk(b)
            for p in range(0, len(buf) - QNX6_DIRENT_SIZE + 1, QNX6_DIRENT_SIZE):
                de_ino = struct.unpack_from("<I", buf, p)[0]
                de_size = buf[p + 4]
                if not de_ino or not de_size:
                    continue
                if de_size == 0xFF:
                    name = self._longname(struct.unpack_from("<I", buf, p + 8)[0])
                else:
                    name = buf[p + 5:p + 5 + min(de_size, 27)].decode("utf-8", "replace")
                if name not in (".", ".."):
                    out.append((name, de_ino))
        return sorted(out)

    def entry(self, num):
        ino = self.inode(num)
        if not ino:
            return None
        return ino["mode"], ino["size"], ino["mtime"]

    def read_file(self, num, size):
        """Yield the file's bytes a block at a time. An unmapped block is a
        hole and is emitted as zeros, so offsets stay correct."""
        ino = self.inode(num)
        if not ino:
            return
        left = size
        for lb in range((size + self.bs - 1) // self.bs):
            b = self._map(ino["ptr"], ino["levels"], lb)
            buf = self._blk(b) if b is not None else bytes(self.bs)
            if len(buf) < self.bs:
                buf = buf + bytes(self.bs - len(buf))
            take = min(self.bs, left)
            yield buf[:take]
            left -= take
            if left <= 0:
                return

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        qnx6 keeps one bit per block in a tree under the Bitmap root node, the
        second root node of struct qnx6_super_block (include/linux/qnx6_fs.h).
        Documentation/filesystems/qnx6.rst gives the numbering: each bit is one
        filesystem block, block 0 is where file blocks start (blks_off here), and
        the bits past the last block are set. The Linux driver has no write path
        and never reads the bitmap, so two things are measured rather than
        sourced: a set bit is a block in use, and bit 0 is the least significant
        bit of byte 0. See "QNX6 free space" in the README for the measurement:
        read that way, on four volumes, the clear bits equal the superblock's own
        sb_free_blocks and no block a live file or metadata tree occupies is
        clear; read most-significant-first, live blocks land in free space on
        every one of them.

        The bitmap is the one of the superblock this walker was opened on, the
        newest generation. Nothing is reported unless that bitmap can be read for
        every block and its clear bits equal sb_free_blocks: a bitmap that is cut
        short, unmapped, or at odds with its own superblock is no answer, and is
        not turned into one.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.
        """
        nb, bs = self.num_blocks, self.bs
        need = (nb + 7) // 8
        if not nb or self.bitmap_bytes < need:
            return []
        raw = bytearray()
        for lb in range((need + bs - 1) // bs):
            b = self._map(self.bitmap_rn["ptr"], self.bitmap_rn["levels"], lb)
            buf = self._blk(b) if b is not None else b""
            if len(buf) < bs:
                return []
            raw += buf
        del raw[need:]
        if nb & 7:
            # the last byte's bits past sb_num_blocks are not blocks
            raw[-1] |= (0xFF << (nb & 7)) & 0xFF
        if need * 8 - bin(int.from_bytes(raw, "little")).count("1") != self.free_blocks:
            return []
        runs, start = [], None
        for i, val in enumerate(raw):
            if val == 0xFF:
                if start is not None:
                    runs.append((start, i * 8))
                    start = None
            elif val == 0:
                if start is None:
                    start = i * 8
            else:
                for k in range(8):
                    if (val >> k) & 1:
                        if start is not None:
                            runs.append((start, i * 8 + k))
                            start = None
                    elif start is None:
                        start = i * 8 + k
        if start is not None:
            runs.append((start, nb))
        first = self.base + self.blks_off * bs
        return [(first + s * bs, (e - s) * bs) for s, e in runs
                if (e - s) * bs >= min_bytes]

    root = QNX6_ROOT_INO


class ExtUnreadable(Exception):
    """An ext file this reader cannot hand back whole; the message says why."""


class ExtWalker:
    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        sb = read_at(fh, base + EXT_SB_OFF, 1024)
        self.bs = 1024 << _e(sb, "log_block_size")
        self.ipg = _e(sb, "inodes_per_group")
        self.fdb = _e(sb, "first_data_block")
        self.isz = _e(sb, "inode_size", 2)
        is64 = bool(_e(sb, "feature_incompat") & 0x80)
        self.dsz = _e(sb, "desc_size", 2) if is64 else 32
        self.is64 = is64

    def _blk(self, b):
        return read_at(self.fh, self.base + b * self.bs, self.bs)

    def inode(self, num):
        g, idx = divmod(num - 1, self.ipg)
        gd = read_at(self.fh, self.base + (self.fdb + 1) * self.bs + g * self.dsz, self.dsz)
        if len(gd) < 12:
            return None
        it = int.from_bytes(gd[8:12], "little")
        if self.is64 and self.dsz >= 44:
            it |= int.from_bytes(gd[40:44], "little") << 32
        raw = read_at(self.fh, self.base + it * self.bs + idx * self.isz, self.isz)
        if len(raw) < 60:
            return None
        return raw

    def _runs(self, raw):
        """[(logical block, block count, physical block or None)] in logical order.

        A file's content is addressed by logical block; where a run's physical
        block is None the run is an extent the kernel wrote as uninitialized,
        which reads as zeros, and a logical range no run covers is a hole, which
        also reads as zeros. Returns None for a file whose data lives inline in
        the inode. Two layouts are read:

        - the extent tree (EXT4_EXTENTS_FL), each leaf carrying its own logical
          start (ee_block) and length, with bit 15 of the length marking an
          uninitialized extent: linux/fs/ext4/ext4_extents.h;
        - the classic block map of ext2 and ext3, twelve direct pointers then a
          single, double and triple indirect block, a zero pointer being a
          hole: linux/fs/ext2/ext2.h (i_block), linux/fs/ext4/ext4.h EXT4_*_BLOCK.

        Reading the extents as a flat list of physical blocks, which this did
        before, dropped every hole: a 32 KiB SQLite shared-memory file with two
        written pages came back as 8 KiB, and its bytes in the wrong order.
        """
        flags = int.from_bytes(raw[32:36], "little")
        if flags & 0x10000000:                                 # EXT4_INLINE_DATA_FL
            return None
        runs = []
        if flags & 0x80000:                                    # EXT4_EXTENTS_FL
            def walk(buf, off, depth_left=8):
                if depth_left <= 0 or len(buf) < off + 12:
                    return
                if struct.unpack_from("<H", buf, off)[0] != 0xF30A:
                    return
                ent = struct.unpack_from("<H", buf, off + 2)[0]
                depth = struct.unpack_from("<H", buf, off + 6)[0]
                for i in range(ent):
                    o = off + 12 + i * 12
                    if len(buf) < o + 12:
                        return
                    if depth == 0:
                        lblk = struct.unpack_from("<I", buf, o)[0]
                        raw_len = struct.unpack_from("<H", buf, o + 4)[0]
                        st = (struct.unpack_from("<I", buf, o + 8)[0]
                              | struct.unpack_from("<H", buf, o + 6)[0] << 32)
                        if raw_len > 0x8000:                   # uninitialized extent
                            runs.append((lblk, raw_len - 0x8000, None))
                        elif raw_len:
                            runs.append((lblk, raw_len, st))
                    else:
                        leaf = (struct.unpack_from("<I", buf, o + 4)[0]
                                | struct.unpack_from("<H", buf, o + 8)[0] << 32)
                        walk(self._blk(leaf), 0, depth_left - 1)
            walk(raw, 40)
            runs.sort()
            return runs

        per = self.bs // 4                                      # pointers per indirect block

        def add(lblk, phys):
            if not phys:                                        # a zero pointer is a hole
                return
            if runs and runs[-1][2] is not None:
                l0, n0, p0 = runs[-1]
                if l0 + n0 == lblk and p0 + n0 == phys:
                    runs[-1] = (l0, n0 + 1, p0)
                    return
            runs.append((lblk, 1, phys))

        def indirect(block, level, lbase):
            if not block:
                return
            buf = self._blk(block)
            span = per ** (level - 1)                           # logical blocks per pointer
            for i in range(min(per, len(buf) // 4)):
                ptr = struct.unpack_from("<I", buf, 4 * i)[0]
                if level == 1:
                    add(lbase + i * span, ptr)
                elif ptr:
                    indirect(ptr, level - 1, lbase + i * span)

        for i in range(12):
            add(i, struct.unpack_from("<I", raw, 40 + 4 * i)[0])
        indirect(struct.unpack_from("<I", raw, 88)[0], 1, 12)
        indirect(struct.unpack_from("<I", raw, 92)[0], 2, 12 + per)
        indirect(struct.unpack_from("<I", raw, 96)[0], 3, 12 + per + per * per)
        return runs

    def _blocks(self, raw):
        """The physical blocks holding a directory's entries, in logical order.

        Directories have no holes, so a run that reads as zeros is skipped.
        """
        runs = self._runs(raw)
        if not runs:
            return []
        out = []
        for _lblk, count, phys in runs:
            if phys is not None:
                out.extend(range(phys, phys + count))
        return out

    def listdir(self, num):
        raw = self.inode(num)
        if not raw:
            return []
        out = []
        for b in self._blocks(raw):
            buf = self._blk(b)
            p = 0
            while p < len(buf) - 8:
                i = struct.unpack_from("<I", buf, p)[0]
                rec = struct.unpack_from("<H", buf, p + 4)[0]
                nl = buf[p + 6]
                if rec < 8 or p + rec > len(buf):
                    break
                if i and nl:
                    nm = buf[p + 8:p + 8 + nl].decode("utf-8", "replace")
                    if nm not in (".", ".."):
                        out.append((nm, i))
                p += rec
        return sorted(out)

    def entry(self, num):
        raw = self.inode(num)
        if not raw:
            return None
        mode = struct.unpack_from("<H", raw, 0)[0]
        size = (struct.unpack_from("<I", raw, 4)[0]
                | struct.unpack_from("<I", raw, 108)[0] << 32)
        return mode, size, struct.unpack_from("<I", raw, 16)[0]

    def times(self, num):
        """{"modified", "accessed", "changed", "created"} as (seconds,
        nanoseconds) since 1970-01-01 UTC, each None where the inode does not
        hold it, or None for an inode that cannot be read. The shape
        BtrfsWalker.times() gives. entry() keeps its unsigned 32-bit mtime.

        Read the way the kernel reads them (fs/ext4/ext4.h and fs/ext4/inode.c
        at v7.3, c03c1a14507dfaf8b856c2608f9ac216021fc222; the layout in
        Documentation/filesystems/ext4/inodes.rst at the same commit):

        - i_atime, i_ctime and i_mtime (0x08, 0x0C, 0x10) are signed 32-bit
          seconds (EXT4_INODE_GET_XTIME_VAL casts them signed). The kernel has
          no unset value for them, so a stored 0 is returned as stored.
        - i_ctime_extra, i_mtime_extra and i_atime_extra (0x84, 0x88, 0x8C) and
          i_crtime with i_crtime_extra (0x90, 0x94) are read only when they fit
          in 128 + i_extra_isize bytes (EXT4_FITS_IN_INODE). An extra field's
          low two bits add that many 2^32 seconds and its upper 30 bits are the
          nanoseconds (ext4_decode_extra_time, EXT4_EPOCH_BITS).
        - created is None unless i_crtime fits; the kernel then reports no
          birth time (ext4_getattr sets STATX_BTIME only when it fits).
        - i_extra_isize is read only when the superblock's inode size is past
          128 (on a 128-byte inode the next inode starts there). A value that
          runs past the inode or is not a multiple of 4 makes the kernel refuse
          the inode ("iget: bad extra_isize" in __ext4_iget), and this returns
          None for it.
        - An inode flagged EXT4_EA_INODE_FL (0x200000 in i_flags, 0x20) holds an
          extended attribute value, and inodes.rst says its atime, ctime and
          mtime fields then hold a checksum, a reference count and an owner, so
          those three are None.

        e2fsprogs 1.47.4 reads the base as unsigned (ext2fs_inode_xtime_get), so
        debugfs disagrees with this for a base with its top bit set: a time
        before 1970, or one the kernel encodes between 2038 and 2106."""
        raw = self.inode(num)
        if not raw:
            return None
        extra = 0
        if self.isz > EXT_GOOD_OLD_INODE_SIZE:
            if len(raw) < EXT_GOOD_OLD_INODE_SIZE + 2:
                return None
            extra = struct.unpack_from("<H", raw, EXT_GOOD_OLD_INODE_SIZE)[0]
            if EXT_GOOD_OLD_INODE_SIZE + extra > self.isz or extra & 3:
                return None
        room = min(EXT_GOOD_OLD_INODE_SIZE + extra, len(raw))

        def stamp(base_at, extra_at):
            sec = struct.unpack_from("<i", raw, base_at)[0]
            if extra_at + 4 > room:
                return (sec, 0)
            bits = struct.unpack_from("<I", raw, extra_at)[0]
            return (sec + ((bits & EXT4_EPOCH_MASK) << 32), bits >> EXT4_EPOCH_BITS)

        out = {"modified": None, "accessed": None, "changed": None, "created": None}
        if not struct.unpack_from("<I", raw, 0x20)[0] & EXT4_EA_INODE_FL:
            out["accessed"] = stamp(0x08, 0x8C)
            out["changed"] = stamp(0x0C, 0x84)
            out["modified"] = stamp(0x10, 0x88)
        if 0x90 + 4 <= room:
            out["created"] = stamp(0x90, 0x94)
        return out

    def read_file(self, num, size):
        """Yield the file's bytes, exactly ``size`` of them, holes and all."""
        raw = self.inode(num)
        if not raw:
            return
        runs = self._runs(raw)
        if runs is None:
            # Inline data keeps the first 60 bytes in the inode's block field and
            # the rest in the system.data extended attribute, which is not read
            # here. A short file is whole; a longer one is refused rather than
            # handed back cut, because a cut file parses as a smaller one.
            if size <= 60:
                yield raw[40:40 + size]
                return
            raise ExtUnreadable(f"{size:,} bytes of inline data, of which only the 60 "
                                "in the inode are read")
        left = size
        pos = 0                                                 # next logical block to deliver
        for lblk, count, phys in runs:
            if left <= 0:
                return
            if lblk > pos:                                      # a hole reads as zeros
                for chunk in self._zeros(min(lblk - pos, -(-left // self.bs)) * self.bs, left):
                    yield chunk
                    left -= len(chunk)
                pos = lblk
            skip = pos - lblk                                   # an overlapping run, never expected
            for i in range(skip, count):
                if left <= 0:
                    return
                if phys is None:
                    buf = bytes(self.bs)
                else:
                    buf = self._blk(phys + i)
                    if len(buf) < self.bs:
                        buf = buf + bytes(self.bs - len(buf))
                take = min(self.bs, left)
                yield buf[:take]
                left -= take
                pos += 1
        if left > 0:                                            # a trailing hole
            for chunk in self._zeros(left, left):
                yield chunk
                left -= len(chunk)

    @staticmethod
    def _zeros(n, cap):
        """Zero bytes for a hole, at most cap, in pieces that do not sit in memory at once."""
        n = min(n, cap)
        while n > 0:
            piece = min(n, 1 << 20)
            yield bytes(piece)
            n -= piece

    root = 2


# ---------------------------------------------------------------------------
# F2FS (Flash-Friendly File System).
#
# F2FS is the filesystem Android uses for /data on most phones, so an Android
# image or a userdata partition can carry one where an older device would have
# ext4. It is read here directly, no mounting.
#
# The layout is sourced from the Linux kernel's own F2FS at v7.0 (commit
# 028ef9c96e96197026887c0f092424679298aae8): the on-disk structures in
# include/linux/f2fs_fs.h (f2fs_super_block, f2fs_checkpoint, f2fs_inode,
# node_footer, f2fs_dir_entry, f2fs_dentry_block, f2fs_nat_entry), node
# resolution in fs/f2fs/node.{c,h} (current_nat_addr, get_node_path),
# checkpoint selection in fs/f2fs/checkpoint.c (validate_checkpoint) and
# fs/f2fs/super.c (sanity_check_raw_super), the NAT journal in
# fs/f2fs/segment.c (read_normal_summaries), the inode read in
# fs/f2fs/inode.c (do_read_inode) and the directory walk in fs/f2fs/dir.c
# (f2fs_fill_dentries). No F2FS implementation's code was copied; qnxprobe is
# MIT and both the kernel driver and f2fs-tools are GPL. f2fs-tools' dump.f2fs
# is used only as an independent oracle to validate this reader.
#
# To find a file this reader has to resolve a node id (nid) to the block that
# holds its node. That mapping lives in the NAT (Node Address Table), and the
# current copy of each NAT block is chosen by a bitmap in the active
# checkpoint, with recent updates overriding it from a journal in the
# checkpoint's data summary. Once the inode block is read, its data is
# addressed the way ext is: pointers in the inode, then direct, indirect and
# double-indirect node blocks. Small files and directories keep their content
# inline in the inode instead.
# ---------------------------------------------------------------------------
F2FS_MAGIC = 0xF2F52010
F2FS_SUPER_OFF = 1024               # the superblock sits 1024 bytes into block 0
F2FS_BLKSIZE_BITS_MIN = 12          # only block == page size is valid: 4K or 16K
F2FS_BLKSIZE_BITS_MAX = 16
# i_inline flags (f2fs_fs.h)
F2FS_INLINE_XATTR, F2FS_INLINE_DATA = 0x01, 0x02
F2FS_INLINE_DENTRY, F2FS_EXTRA_ATTR = 0x04, 0x20
F2FS_COMPR_FL = 0x00000004          # i_flags: file is compressed
F2FS_FADVISE_ENCRYPT = 0x04         # i_advise: file is encrypted
# superblock feature flags (f2fs_fs.h F2FS_FEATURE_*)
F2FS_FEAT_ENCRYPT = 0x0001
F2FS_FEAT_EXTRA_ATTR = 0x0008
F2FS_FEAT_FLEX_INLINE_XATTR = 0x0040
F2FS_FEAT_INODE_CRTIME = 0x0100
F2FS_FEAT_COMPRESSION = 0x2000
F2FS_FEAT_CASEFOLD = 0x1000
F2FS_FEAT_PACKED_SSA = 0x10000
# checkpoint flags (f2fs_fs.h CP_*)
F2FS_CP_UMOUNT = 0x0001
F2FS_CP_COMPACT_SUM = 0x0004
F2FS_CP_FASTBOOT = 0x0020
F2FS_CP_ERROR = 0x0008
F2FS_CP_LARGE_NAT_BITMAP = 0x0400
# reserved data-block-address markers (f2fs_fs.h)
F2FS_NULL_ADDR, F2FS_NEW_ADDR, F2FS_COMPRESS_ADDR = 0, 0xFFFFFFFF, 0xFFFFFFFE
F2FS_DEFAULT_INLINE_XATTR_ADDRS = 50
F2FS_NAT_ENTRY_SIZE = 9             # f2fs_nat_entry: u8 version, le32 ino, le32 block_addr
F2FS_ENC_NAME_MARKERS = ()          # names are not decoded; encryption is reported per file


def f2fs_time(v):
    """An F2FS timestamp (le64 Unix seconds, UTC) as a Unix second count, or 0."""
    return v if 0 < v < (1 << 40) else 0


class F2fsUnreadable(Exception):
    """A file this reader will not hand back whole (encrypted or compressed);
    the message says which."""


class F2fsWalker:
    """List and read files from an F2FS volume. Nodes are addressed by nid, so
    listdir()/entry()/read_file() take a nid and the shared collect() and
    extract_to_zip() work unchanged; the root is the superblock's root_ino."""

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        sb = self._sb(base)
        if sb is None:
            raise F2fsUnreadable("no valid F2FS superblock")
        self.log_bs = struct.unpack_from("<I", sb, 16)[0]
        self.bs = 1 << self.log_bs
        self.seg_blocks = 1 << struct.unpack_from("<I", sb, 20)[0]   # always 512
        self.cp_blkaddr = struct.unpack_from("<I", sb, 76)[0]
        self.sit_blkaddr = struct.unpack_from("<I", sb, 80)[0]
        self.nat_blkaddr = struct.unpack_from("<I", sb, 84)[0]
        self.main_blkaddr = struct.unpack_from("<I", sb, 92)[0]
        self.sit_segs_total = struct.unpack_from("<I", sb, 56)[0]   # segment_count_sit, both copies
        self.main_segs = struct.unpack_from("<I", sb, 68)[0]        # segment_count_main
        self.root_ino = struct.unpack_from("<I", sb, 96)[0]
        self.cp_payload = struct.unpack_from("<I", sb, 1664)[0]
        self.feature = struct.unpack_from("<I", sb, 2180)[0]
        # NAT entry is 9 bytes; DEF_ADDRS_PER_INODE and the node capacity follow
        # the same arithmetic the kernel uses, parameterised by block size.
        self.nepb = self.bs // F2FS_NAT_ENTRY_SIZE
        self.def_addrs = (self.bs - 360 - 20 - 24) // 4     # DEF_ADDRS_PER_INODE
        self.addrs_per_block = (self.bs - 24) // 4          # direct/indirect node capacity
        self._cache = {}
        self._load_checkpoint()

    root = property(lambda self: self.root_ino)

    @staticmethod
    def _sb_ok(b):
        """True if b holds a superblock that passes the reserved-value checks
        sanity_check_raw_super applies: the magic, a supported block size, 512
        blocks per segment, and node/meta/root inode numbers of 1/2/3."""
        return (len(b) >= 200
                and struct.unpack_from("<I", b, 0)[0] == F2FS_MAGIC
                and F2FS_BLKSIZE_BITS_MIN <= struct.unpack_from("<I", b, 16)[0] <= F2FS_BLKSIZE_BITS_MAX
                and struct.unpack_from("<I", b, 20)[0] == 9
                and struct.unpack_from("<I", b, 96)[0] == 3
                and struct.unpack_from("<I", b, 100)[0] == 1
                and struct.unpack_from("<I", b, 104)[0] == 2)

    def _sb(self, base):
        """The raw superblock bytes, from copy 1 (1024 bytes into block 0) or,
        if that copy is unreadable, copy 2 (1024 bytes into block 1). The block
        size is not known until a copy is read, so copy 2 is tried at both the
        4K and 16K block offsets."""
        b = read_at(self.fh, base + F2FS_SUPER_OFF, 3072)
        if self._sb_ok(b):
            return b
        for blk_bytes in (4096, 16384):
            c = read_at(self.fh, base + blk_bytes + F2FS_SUPER_OFF, 3072)
            if self._sb_ok(c):
                return c
        return None

    def block(self, blkaddr):
        b = self._cache.get(blkaddr)
        if b is None:
            b = read_at(self.fh, self.base + blkaddr * self.bs, self.bs)
            if len(self._cache) < 4096:
                self._cache[blkaddr] = b
        return b

    def _load_checkpoint(self):
        """Pick the newer of the two checkpoint packs, then read the NAT bitmap
        and NAT journal it points at. A pack is only valid when the version at
        its first block equals the version at its last, meaning it was written
        whole (fs/f2fs/checkpoint.c validate_checkpoint)."""
        best = None
        for pack, addr in ((1, self.cp_blkaddr), (2, self.cp_blkaddr + self.seg_blocks)):
            head = self.block(addr)
            if len(head) < self.bs:
                continue
            ver = int.from_bytes(head[0:8], "little")
            total = struct.unpack_from("<I", head, 136)[0]   # cp_pack_total_block_count
            if not (2 < total <= self.seg_blocks):
                continue
            tail = self.block(addr + total - 1)
            if len(tail) < self.bs or int.from_bytes(tail[0:8], "little") != ver:
                continue
            if best is None or ver > best[0]:
                best = (ver, pack, head, total)
        if best is None:
            raise F2fsUnreadable("no valid F2FS checkpoint")
        self.cp_ver, self.cur_pack, self.ckpt, self.cp_total = best
        self.start_cp = self.cp_blkaddr + (self.seg_blocks if self.cur_pack == 2 else 0)
        self.cp_flags = struct.unpack_from("<I", self.ckpt, 132)[0]
        sit_bm = struct.unpack_from("<I", self.ckpt, 156)[0]   # sit_ver_bitmap_bytesize
        # The version bitmap region begins at offset 192 (after alloc_type[16]).
        # NAT bitmap placement follows f2fs.h __bitmap_ptr(NAT_BITMAP).
        if self.cp_flags & F2FS_CP_LARGE_NAT_BITMAP:
            self.nat_bitmap = self.ckpt[192 + 4:]
        elif self.cp_payload > 0:
            self.nat_bitmap = self.ckpt[192:]
        else:
            self.nat_bitmap = self.ckpt[192 + sit_bm:]
        self._load_nat_journal()

    def _load_nat_journal(self):
        """Recent NAT updates not yet flushed to the on-disk table live in a
        journal inside the checkpoint's hot-data summary (fs/f2fs/segment.c
        read_normal_summaries / read_compacted_summaries). They override the
        on-disk NAT, so a nid found here wins."""
        self.nat_j = {}
        sum_bs = 4096 if (self.feature & F2FS_FEAT_PACKED_SSA) else self.bs
        sum_entry_size = 7 * (sum_bs // 8)     # entries_in_sum summaries of 7 bytes
        if self.cp_flags & F2FS_CP_COMPACT_SUM:
            blk = self.start_cp + struct.unpack_from("<I", self.ckpt, 140)[0]
            joff = 0
        elif self.cp_flags & (F2FS_CP_UMOUNT | F2FS_CP_FASTBOOT):
            blk = self.start_cp + self.cp_total - 7    # HOT_DATA summary, base 6
            joff = sum_entry_size
        else:
            blk = self.start_cp + self.cp_total - 4    # base 3, no node summaries
            joff = sum_entry_size
        buf = self.block(blk)
        if len(buf) < self.bs or joff + 2 > len(buf):
            return
        n_nats = struct.unpack_from("<H", buf, joff)[0]
        p = joff + 2
        for _ in range(n_nats):
            if p + 13 > len(buf):
                break
            nid = struct.unpack_from("<I", buf, p)[0]
            # nat_journal_entry: nid(4) then f2fs_nat_entry{ver(1) ino(4) blkaddr(4)}
            self.nat_j[nid] = struct.unpack_from("<I", buf, p + 9)[0]
            p += 13

    @staticmethod
    def _test_bit(bm, i):
        """Bit i of a little-endian bitmap: the kernel's set_bit_le and
        find_next_bit_le, which F2FS uses for a directory's validity bitmap
        (fs/f2fs/dir.c f2fs_update_dentry sets it, f2fs_fill_dentries reads it).
        Bit 0 is the least significant bit of byte 0. Not the order of the SIT
        valid_map or of the version bitmaps, which f2fs_set_bit writes the other
        way round; see _f2fs_test_bit."""
        j = i >> 3
        return (bm[j] >> (i & 7)) & 1 if j < len(bm) else 0

    @staticmethod
    def _f2fs_test_bit(bm, i):
        """Bit i the way F2FS's own f2fs_test_bit reads it: bit 0 is the MOST
        significant bit of byte 0 (fs/f2fs/f2fs.h: mask = BIT(7 - (nr & 7))).
        This is the order of the NAT and SIT version bitmaps in the checkpoint,
        which say which of a block's two on-disk copies is current
        (node.h current_nat_addr, segment.h current_sit_addr). Reading them
        little-endian picks the stale copy whenever the two orders disagree, and
        a fresh volume, whose bitmaps are all zero, cannot show the difference."""
        j = i >> 3
        return (bm[j] >> (7 - (i & 7))) & 1 if j < len(bm) else 0

    def resolve(self, nid):
        """The block address holding node nid, or 0 if it is unallocated."""
        if nid in self.nat_j:
            return self.nat_j[nid]
        start = (nid // self.nepb) * self.nepb
        block_off = start // self.nepb
        addr = self.nat_blkaddr + (block_off << 1) - (block_off & (self.seg_blocks - 1))
        if self._f2fs_test_bit(self.nat_bitmap, block_off):
            addr += self.seg_blocks
        blk = self.block(addr)
        eo = (nid - start) * F2FS_NAT_ENTRY_SIZE
        if eo + F2FS_NAT_ENTRY_SIZE > len(blk):
            return 0
        return struct.unpack_from("<I", blk, eo + 5)[0]     # f2fs_nat_entry.block_addr

    def _node(self, nid):
        blkaddr = self.resolve(nid)
        if blkaddr in (F2FS_NULL_ADDR, F2FS_NEW_ADDR):
            return None
        b = self.block(blkaddr)
        return b if len(b) >= self.bs else None

    def inode(self, nid):
        """The parsed inode for nid, or None. A node whose footer nid equals its
        footer ino is an inode (f2fs.h RAW_IS_INODE)."""
        b = self._node(nid)
        if b is None:
            return None
        if struct.unpack_from("<I", b, self.bs - 24)[0] != struct.unpack_from("<I", b, self.bs - 20)[0]:
            return None
        i_inline = b[3]
        extra = struct.unpack_from("<H", b, 360)[0] if (i_inline & F2FS_EXTRA_ATTR) else 0
        if self.feature & F2FS_FEAT_FLEX_INLINE_XATTR:
            ix = struct.unpack_from("<H", b, 362)[0]
        elif i_inline & (F2FS_INLINE_XATTR | F2FS_INLINE_DENTRY):
            ix = F2FS_DEFAULT_INLINE_XATTR_ADDRS
        else:
            ix = 0
        base = extra // 4                                   # offset_in_addr
        addrs_in_inode = (self.def_addrs - base) - ix       # ADDRS_PER_INODE
        crtime = (struct.unpack_from("<Q", b, 372)[0]
                  if (extra and (self.feature & F2FS_FEAT_INODE_CRTIME)) else 0)
        return dict(
            raw=b, mode=struct.unpack_from("<H", b, 0)[0], advise=b[2], inline=i_inline,
            size=struct.unpack_from("<Q", b, 16)[0], flags=struct.unpack_from("<I", b, 80)[0],
            atime=struct.unpack_from("<Q", b, 32)[0], mtime=struct.unpack_from("<Q", b, 48)[0],
            crtime=crtime, base=base, addrs_in_inode=addrs_in_inode,
            iaddr_off=360 + base * 4)

    def _iaddr(self, ino, k):
        return struct.unpack_from("<I", ino["raw"], ino["iaddr_off"] + k * 4)[0]

    def _nid_slot(self, ino, k):        # i_nid[k], the five node-id pointers
        return struct.unpack_from("<I", ino["raw"], self.bs - 44 + k * 4)[0]

    def _node_word(self, nid, idx):
        """Word idx of a direct/indirect node's array (addr[] or nid[]), 0 when
        the node itself is unallocated (a hole covering that whole subtree)."""
        b = self._node(nid)
        if b is None or idx * 4 + 4 > len(b):
            return 0
        return struct.unpack_from("<I", b, idx * 4)[0]

    def _block_of(self, ino, L):
        """The data block address for logical block L of a file, following
        fs/f2fs/node.c get_node_path; 0/NEW mark a hole that reads as zeros."""
        n = ino["addrs_in_inode"]
        if L < n:
            return self._iaddr(ino, L)
        L -= n
        apb = self.addrs_per_block
        if L < apb:
            return self._node_word(self._nid_slot(ino, 0), L)
        L -= apb
        if L < apb:
            return self._node_word(self._nid_slot(ino, 1), L)
        L -= apb
        if L < apb * apb:
            ind = self._node_word(self._nid_slot(ino, 2), L // apb)
            return self._node_word(ind, L % apb)
        L -= apb * apb
        if L < apb * apb:
            ind = self._node_word(self._nid_slot(ino, 3), L // apb)
            return self._node_word(ind, L % apb)
        L -= apb * apb
        dind = self._nid_slot(ino, 4)
        l1 = self._node_word(dind, L // (apb * apb))
        rem = L % (apb * apb)
        ind = self._node_word(l1, rem // apb)
        return self._node_word(ind, rem % apb)

    def _encrypted(self, ino):
        return bool((self.feature & F2FS_FEAT_ENCRYPT) and (ino["advise"] & F2FS_FADVISE_ENCRYPT))

    def _compressed(self, ino):
        return bool((self.feature & F2FS_FEAT_COMPRESSION) and (ino["flags"] & F2FS_COMPR_FL))

    def entry(self, nid):
        ino = self.inode(nid)
        if ino is None:
            return None
        return ino["mode"], ino["size"], f2fs_time(ino["mtime"])

    def stamps(self, nid):
        """(created, modified, accessed) in Unix seconds, 0 where unset. F2FS
        stores real UTC instants, so unlike a FAT reading these sit on a
        timeline; created needs the inode_crtime feature and an extra_attr
        inode, else it is 0."""
        ino = self.inode(nid)
        if ino is None:
            return (0, 0, 0)
        return (f2fs_time(ino["crtime"]), f2fs_time(ino["mtime"]), f2fs_time(ino["atime"]))

    def _dentry_geom(self, span):
        """(entries, bitmap bytes, dentry offset, filename offset) for a dentry
        area of `span` bytes (f2fs_fs.h NR_DENTRY_IN_BLOCK and friends): a
        validity bitmap, reserved padding, an 11-byte dir entry per slot, then
        an 8-byte filename slot per slot."""
        nr = (8 * span) // ((11 + 8) * 8 + 1)
        bmsize = (nr + 7) // 8
        reserved = span - ((11 + 8) * nr + bmsize)
        return nr, bmsize, bmsize + reserved, bmsize + reserved + 11 * nr

    def _parse_dentry(self, buf, off, span):
        nr, bmsize, doff, foff = self._dentry_geom(span)
        out, bit = [], 0
        while bit < nr:
            if not self._test_bit(buf[off:off + bmsize], bit):
                bit += 1
                continue
            de = off + doff + bit * 11
            child = struct.unpack_from("<I", buf, de + 4)[0]
            name_len = struct.unpack_from("<H", buf, de + 8)[0]
            if name_len == 0 or name_len > 255:
                bit += 1
                continue
            slots = (name_len + 7) // 8
            ns = off + foff + bit * 8
            name = buf[ns:ns + name_len].decode("utf-8", "replace")
            bit += slots
            if name not in (".", ".."):
                out.append((name, child))
        return out

    def listdir(self, nid):
        ino = self.inode(nid)
        if ino is None or not (ino["mode"] & S_IFDIR):
            return []
        if ino["inline"] & F2FS_INLINE_DENTRY:
            off = ino["iaddr_off"] + 4                      # DEF_INLINE_RESERVED_SIZE
            span = 4 * (ino["addrs_in_inode"] - 1)          # MAX_INLINE_DATA
            return sorted(self._parse_dentry(ino["raw"], off, span))
        out = []
        for L in range((ino["size"] + self.bs - 1) // self.bs):
            addr = self._block_of(ino, L)
            if addr in (F2FS_NULL_ADDR, F2FS_NEW_ADDR, F2FS_COMPRESS_ADDR):
                continue
            buf = self.block(addr)
            if len(buf) >= self.bs:
                out.extend(self._parse_dentry(buf, 0, self.bs))
        return sorted(out)

    def read_file(self, nid, size):
        """Yield exactly `size` bytes, holes emitted as zeros so offsets stay
        correct. Inline data lives in the inode; encrypted or compressed content
        is refused rather than guessed at."""
        ino = self.inode(nid)
        if ino is None:
            return
        if self._encrypted(ino):
            raise F2fsUnreadable("the file is encrypted and the volume holds no key")
        if self._compressed(ino):
            raise F2fsUnreadable("the file is compressed (F2FS compression is not read here)")
        if ino["inline"] & F2FS_INLINE_DATA:
            off = ino["iaddr_off"] + 4                      # skip DEF_INLINE_RESERVED_SIZE
            yield ino["raw"][off:off + size]
            return
        left, L = size, 0
        while left > 0:
            addr = self._block_of(ino, L)
            if addr in (F2FS_NULL_ADDR, F2FS_NEW_ADDR, F2FS_COMPRESS_ADDR):
                buf = bytes(self.bs)
            else:
                buf = self.block(addr)
                if len(buf) < self.bs:
                    buf = buf + bytes(self.bs - len(buf))
            take = min(self.bs, left)
            yield buf[:take]
            left -= take
            L += 1

    def _sit_bitmap(self):
        """The SIT version bitmap: which of a SIT block's two copies is current.
        Placement follows f2fs.h __bitmap_ptr(SIT_BITMAP): with the large-NAT-
        bitmap flag it follows the NAT bitmap after a 4-byte checksum; with a
        checkpoint payload it is the block after the checkpoint header; else it
        is first in the version-bitmap region at offset 192."""
        if self.cp_flags & F2FS_CP_LARGE_NAT_BITMAP:
            nat_len = struct.unpack_from("<I", self.ckpt, 160)[0]
            return self.ckpt[192 + nat_len + 4:]
        if self.cp_payload > 0:
            return self.block(self.start_cp + 1)
        return self.ckpt[192:]

    def _load_sit_journal(self):
        """SIT entries updated since the table was last written live in the
        checkpoint's cold-data summary journal and override the on-disk table
        (segment.c build_sit_entries applies them after reading it). Same
        placement rules as the NAT journal, one summary type along: normal
        summaries keep it in the COLD_DATA block, compact ones keep the two
        journals back to back at the start of the summary area."""
        self.sit_j = {}
        sum_bs = 4096 if (self.feature & F2FS_FEAT_PACKED_SSA) else self.bs
        sum_entry_size = 7 * (sum_bs // 8)
        sum_journal_size = sum_bs - 5 - sum_entry_size       # SUM_FOOTER_SIZE is 5
        if self.cp_flags & F2FS_CP_COMPACT_SUM:
            blk = self.start_cp + struct.unpack_from("<I", self.ckpt, 140)[0]
            joff = sum_journal_size                          # the second journal
        elif self.cp_flags & (F2FS_CP_UMOUNT | F2FS_CP_FASTBOOT):
            blk = self.start_cp + self.cp_total - 7 + 2      # COLD_DATA summary, base 6
            joff = sum_entry_size
        else:
            blk = self.start_cp + self.cp_total - 4 + 2      # base 3
            joff = sum_entry_size
        buf = self.block(blk)
        if len(buf) < self.bs or joff + 2 > len(buf):
            return
        n_sits = struct.unpack_from("<H", buf, joff)[0]
        p = joff + 2
        for _ in range(n_sits):
            if p + 78 > len(buf):
                break
            # sit_journal_entry: segno(4) then f2fs_sit_entry (74 bytes)
            self.sit_j[struct.unpack_from("<I", buf, p)[0]] = buf[p + 4:p + 78]
            p += 78

    def _sit_entry(self, segno):
        """The raw 74-byte f2fs_sit_entry for main-area segment segno, journal
        first, else the current on-disk copy (segment.h current_sit_addr); None
        past the end of the image."""
        raw = self.sit_j.get(segno)
        if raw is not None:
            return raw
        sents = self.bs // 74                                # SIT_ENTRY_PER_BLOCK
        block_off = segno // sents
        addr = self.sit_blkaddr + block_off
        if self._f2fs_test_bit(self._sit_bitmap(), block_off):
            addr += (self.sit_segs_total >> 1) * self.seg_blocks   # sit_blocks: the second copy
        buf = self.block(addr)
        eo = (segno % sents) * 74
        if eo + 74 > len(buf):
            return None
        return buf[eo:eo + 74]

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        F2FS keeps one validity bit per block of the main area, 512 bits per
        segment in f2fs_sit_entry.valid_map. The bits are set by the filesystem's
        own f2fs_set_bit (segment.c update_sit_entry), so bit 0 is the MOST
        significant bit of byte 0; segment.h check_block_count reads the same map
        with the little-endian helpers, but only to count clear bits, which no
        order changes. Position does change: read least-significant-first, this
        map put 14 live blocks of one test volume inside "free" runs while the
        total still matched the checkpoint's own count. A clear bit is a block no
        live node or data occupies, which is where deleted content survives until
        the log wraps round to it. The current copy of each SIT block is chosen by
        the checkpoint's SIT version bitmap, read the same most-significant-first
        way, and an entry still in the cold-data summary journal overrides the
        table. Only the main area is reported: the superblock, checkpoint, SIT,
        NAT and SSA areas are the filesystem's own bookkeeping and hold no user
        content.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.
        """
        if not self.main_segs or not self.seg_blocks:
            return []
        self._load_sit_journal()
        # per byte of a valid_map, the (first block, count) runs of clear bits,
        # bit 0 being the most significant bit (f2fs_set_bit's order)
        table = []
        for byte in range(256):
            runs, start = [], None
            for bit in range(8):
                if (byte >> (7 - bit)) & 1:
                    if start is not None:
                        runs.append((start, bit - start))
                        start = None
                elif start is None:
                    start = bit
            if start is not None:
                runs.append((start, 8 - start))
            table.append(tuple(runs))
        out, run_start, run_len = [], None, 0
        for segno in range(self.main_segs):
            raw = self._sit_entry(segno)
            if raw is None:                                  # the image ends inside the SIT
                break
            base_blk = self.main_blkaddr + segno * self.seg_blocks
            vmap = raw[2:2 + (self.seg_blocks >> 3)]
            for i, byte in enumerate(vmap):
                for first, n in table[byte]:
                    blk = base_blk + i * 8 + first
                    if run_start is not None and run_start + run_len == blk:
                        run_len += n
                    else:
                        if run_start is not None:
                            out.append((run_start, run_len))
                        run_start, run_len = blk, n
        if run_start is not None:
            out.append((run_start, run_len))
        result = []
        for first, n in out:
            length = n * self.bs
            if length >= min_bytes:
                result.append((self.base + first * self.bs, length))
        return result


# ---------------------------------------------------------------------------
# FAT32, FAT16, FAT12 and exFAT.
#
# FAT is the file system of removable media and of many embedded devices, so a
# vehicle image can carry one beside its QNX and ext volumes. All of them are
# read here directly, no mounting. Fat16Walker, after Fat32Walker, says what
# FAT16 does differently and how Windows CE's transaction-safe FAT is read,
# and Fat12Walker what FAT12 adds to that.
#
# Field offsets are from Microsoft's own specifications: the FAT32 BPB from the
# "Microsoft Extensible Firmware Initiative FAT32 File System Specification"
# v1.03, and the exFAT structures from the "exFAT file system specification"
# (Microsoft, 2019). Long file names on FAT are the VFAT scheme (UTF-16 across
# 0x0F entries); exFAT names are UTF-16 in a chain of file-name directory
# entries. Only the fields needed to list and read files are parsed.
# ---------------------------------------------------------------------------

class FatDeletedFile:
    """One deleted FAT32, FAT16, FAT12 or exFAT directory entry that still describes a file.

    ``recoverable`` says whether the content can be read back: the entry keeps
    its first cluster and size, so the data is readable while those clusters
    are still free. ``assumed_contiguous`` is True when the chain that said
    where the rest of the file lay is gone (FAT32 zeroes it on delete; exFAT
    keeps one only for a fragmented file) and the read assumes the file was
    laid out in one run, which is how a driver writes a fresh file onto a
    card with room but is not something the volume can confirm. ``times`` are
    the readings as stored, text with no zone, the same as listdir_records().
    """

    __slots__ = ("name", "parent", "is_dir", "size", "first_cluster",
                 "recoverable", "reason", "assumed_contiguous", "times",
                 "in_deleted_dir", "_node")

    def __init__(self, name, parent, is_dir, size, first_cluster, recoverable,
                 reason, assumed_contiguous, times, in_deleted_dir, node):
        self.name, self.parent, self.is_dir = name, parent, is_dir
        self.size, self.first_cluster = size, first_cluster
        self.recoverable, self.reason = recoverable, reason
        self.assumed_contiguous, self.times = assumed_contiguous, times
        self.in_deleted_dir = in_deleted_dir
        self._node = node

    def __repr__(self):
        state = "recoverable" if self.recoverable else f"not recoverable ({self.reason})"
        extra = ", contiguity assumed" if self.assumed_contiguous else ""
        return (f"FatDeletedFile(name={self.name!r}, size={self.size}, "
                f"cluster={self.first_cluster}, {state}{extra})")


# Per FAT width: bytes in a table entry, its struct format, the bits that hold
# the cluster number, the lowest end-of-chain value, and the array typecode.
# FAT32 keeps the top four bits of an entry reserved; FAT16 uses all sixteen.
# A FAT12 entry is a byte and a half, so it has no width, format or typecode
# here: _fat12_entry() reads one.
_FAT_ENTRY = {
    32: (4, "<I", 0x0FFFFFFF, 0x0FFFFFF8, "I"),
    16: (2, "<H", 0xFFFF, 0xFFF8, "H"),
    12: (None, None, 0x0FFF, 0x0FF8, None),
}


def _fat12_entry(pair, odd):
    """A FAT12 table entry from the two bytes it lies in, or None when they are
    not both there.

    Microsoft's FAT specification: entry n starts at byte n + n // 2 of the
    table, the 16 bits there are read little-endian, and an odd n takes the
    high twelve of them while an even n takes the low twelve.
    """
    if len(pair) < 2:
        return None
    word = pair[0] | (pair[1] << 8)
    return (word >> 4) if odd else (word & 0x0FFF)

# Windows CE's transaction-safe FAT writes its own name where FAT writes
# "FAT16   " or "FAT32   ". The structures are FAT's.
TFAT_TYPE_STRINGS = (b"TFAT16  ", b"TFAT32  ")


class Fat32Walker:
    """List and read files from a FAT32 volume. inode() takes a (cluster, size,
    is_dir) tuple, so the shared collect()/extract_to_zip() work unchanged; the
    root is that tuple for the root cluster."""

    FAT_BITS = 32

    def __init__(self, fh, base):
        self.fh = fh
        self.base = base
        bpb = read_at(fh, base, 512)
        self.bps = struct.unpack_from("<H", bpb, 11)[0]
        self.spc = bpb[13]
        self.reserved = struct.unpack_from("<H", bpb, 14)[0]
        self.nfats = bpb[16]
        if self.FAT_BITS == 32:
            self.spf = struct.unpack_from("<I", bpb, 36)[0]
            self.root_entries = 0
        else:
            # FAT16 sizes its table in BPB_FATSz16 and keeps the root directory
            # as BPB_RootEntCnt entries in a fixed run between the tables and
            # cluster 2, not in a cluster chain.
            self.spf = struct.unpack_from("<H", bpb, 22)[0]
            self.root_entries = struct.unpack_from("<H", bpb, 17)[0]
        # BPB_TotSec16 is zero on FAT32 and the count lives in BPB_TotSec32, but
        # read both: a volume small enough to use the 16-bit field is still a
        # legal FAT32, and free_extents needs the count to size the cluster area.
        self.total_sectors = (struct.unpack_from("<H", bpb, 19)[0]
                              or struct.unpack_from("<I", bpb, 32)[0])
        # Cluster 0 is never a file's cluster, so on FAT16 it stands for the
        # fixed root directory in the root node.
        self.root_clus = struct.unpack_from("<I", bpb, 44)[0] if self.FAT_BITS == 32 else 0
        self.fat_start = base + self.reserved * self.bps
        self.root_dir_start = self.fat_start + self.nfats * self.spf * self.bps
        root_sectors = ((self.root_entries * 32 + self.bps - 1) // self.bps
                        if self.root_entries and self.bps else 0)
        self.root_dir_bytes = root_sectors * self.bps
        self.data_start = self.root_dir_start + self.root_dir_bytes
        self.cluster_bytes = self.spc * self.bps
        self.root = (self.root_clus, 0, True)

    def _fat_next(self, clus):
        width, fmt, mask, _eoc, _code = _FAT_ENTRY[self.FAT_BITS]
        if width is None:                            # FAT12: a byte and a half
            val = _fat12_entry(read_at(self.fh, self.fat_start + clus + clus // 2, 2),
                               clus & 1)
            return mask if val is None else val      # None: past the end of the image
        off = self.fat_start + clus * width
        raw = read_at(self.fh, off, width)
        if len(raw) < width:
            # Past the end of the image, which is what the first segment of a
            # split acquisition looks like. That is the end of the chain, not a
            # reason to raise: the volume is truncated, not unreadable.
            return mask
        return struct.unpack_from(fmt, raw, 0)[0] & mask

    def _chain(self, clus):
        eoc = _FAT_ENTRY[self.FAT_BITS][3]
        seen = set()
        while 0x2 <= clus < eoc and clus not in seen:
            seen.add(clus)
            yield clus
            clus = self._fat_next(clus)

    def _cluster_off(self, clus):
        return self.data_start + (clus - 2) * self.cluster_bytes

    def _read_chain(self, clus, size=None):
        if clus == 0 and self.FAT_BITS != 32:
            # the FAT16 root directory: its fixed run, whole
            raw = read_at(self.fh, self.root_dir_start, self.root_dir_bytes)
            return raw[:size] if size is not None else raw
        out = bytearray()
        for c in self._chain(clus):
            out += read_at(self.fh, self._cluster_off(c), self.cluster_bytes)
            if size is not None and len(out) >= size:
                break
        return bytes(out[:size]) if size is not None else bytes(out)

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        FAT keeps no separate allocation bitmap. The file allocation table is
        both the chain of every file and the record of what is in use, and an
        entry of zero is a free cluster. Numbering starts at 2, so entry n
        addresses the data area at (n - 2) cluster widths in, and entries 0 and
        1 are the media descriptor and the end-of-chain marker rather than
        clusters.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.

        The table is read a megabyte at a time and unpacked as machine words,
        because reading one entry per cluster through the image would be one
        seek per cluster.
        """
        cluster = self.cluster_bytes
        if not cluster or not self.total_sectors:
            return []
        width, _fmt, mask, _eoc, code = _FAT_ENTRY[self.FAT_BITS]
        root_sectors = self.root_dir_bytes // self.bps if self.bps else 0
        data_sectors = self.total_sectors - (self.reserved + self.nfats * self.spf
                                             + root_sectors)
        count = data_sectors // self.spc if self.spc else 0
        if count <= 0:
            return []
        last = count + 2                             # entries 0 .. count + 1

        def entries():
            """(cluster number, table entry) for 0 .. last - 1; an entry past
            the end of a truncated image reads as zero."""
            if width is None:
                # FAT12: at most 4,084 clusters, so the table is read whole
                table = read_at(self.fh, self.fat_start, last + last // 2 + 2)
                for num in range(last):
                    off = num + num // 2
                    val = _fat12_entry(table[off:off + 2], num & 1)
                    yield num, (val or 0)
                return
            pos = 0
            while pos < last:
                want = min(FAT_SCAN_ENTRIES, last - pos)
                raw = read_at(self.fh, self.fat_start + pos * width, want * width)
                if len(raw) < want * width:          # a truncated image stops here
                    raw += b"\x00" * (want * width - len(raw))
                words = array.array(code)
                words.frombytes(raw)
                if sys.byteorder != "little":
                    words.byteswap()
                for i, val in enumerate(words):
                    yield pos + i, val & mask
                pos += want

        runs, run_start = [], None
        for num, val in entries():
            if num < 2:
                continue
            if val:
                if run_start is not None:
                    runs.append((run_start, num - run_start))
                    run_start = None
            elif run_start is None:
                run_start = num
        if run_start is not None:
            runs.append((run_start, last - run_start))

        out = []
        for first, n in runs:
            length = n * cluster
            if length >= min_bytes:
                out.append((self._cluster_off(first), length))
        return out

    def inode(self, node):
        return node    # (cluster, size, is_dir) already carries what entry() needs

    def entry(self, node):
        clus, size, is_dir = node
        mode = 0o040000 if is_dir else 0o100000
        return (mode, size, 0)

    def listdir_records(self, node):
        """(name, node, recorded times as stored) for every entry.

        FAT records a wall-clock reading and no zone, so the times are text.
        """
        clus = node[0]
        raw = self._read_chain(clus)
        out, lfn = [], []
        for i in range(0, len(raw), 32):
            e = raw[i:i + 32]
            if len(e) < 32 or e[0] == 0x00:
                break
            if e[0] == 0xE5:
                lfn = []; continue
            attr = e[11]
            if attr == 0x0F:                       # VFAT long-name fragment
                seq = e[0] & 0x3F
                chars = e[1:11] + e[14:26] + e[28:32]
                lfn.append((seq, chars)); continue
            if attr & 0x08:                        # volume label
                lfn = []; continue
            name = _vfat_name(lfn) if lfn else _fat_short_name(e)
            lfn = []
            hi = struct.unpack_from("<H", e, 20)[0]
            lo = struct.unpack_from("<H", e, 26)[0]
            # the high word is FAT32's; FAT16 has no such field at offset 20
            first = ((hi << 16) | lo) if self.FAT_BITS == 32 else lo
            sz = struct.unpack_from("<I", e, 28)[0]
            is_sub = bool(attr & 0x10)
            if name in (".", ".."):
                continue
            node = (first or 2, sz, is_sub)
            out.append((name, node, {
                "modified": _dos_stamp(struct.unpack_from("<H", e, 24)[0],
                                       struct.unpack_from("<H", e, 22)[0]),
                "created": _dos_stamp(struct.unpack_from("<H", e, 16)[0],
                                      struct.unpack_from("<H", e, 14)[0], e[13]),
                "accessed date": _dos_date(struct.unpack_from("<H", e, 18)[0]),
            }))
        return out

    def _deleted_in(self, node, in_deleted_dir):
        """Deleted entries in one directory, in the driver's own order."""
        clus = node[0]
        raw = self._read_chain(clus)
        out, lfn = [], []
        for i in range(0, len(raw), 32):
            e = raw[i:i + 32]
            if len(e) < 32 or e[0] == 0x00:
                break
            attr = e[11]
            if attr == 0x0F:
                # A long-name fragment. Deletion overwrites its sequence byte
                # with 0xE5 too, so the ordinal is gone; fragments are stored
                # last-first, so disk order in reverse rebuilds the name.
                lfn.append((e[0] == 0xE5, e[1:11] + e[14:26] + e[28:32]))
                continue
            if attr & 0x08:
                lfn = []
                continue
            if e[0] != 0xE5:
                lfn = []
                continue                            # a live entry; the walk lists it
            hi = struct.unpack_from("<H", e, 20)[0]
            lo = struct.unpack_from("<H", e, 26)[0]
            # the high word is FAT32's; FAT16 has no such field at offset 20
            first = ((hi << 16) | lo) if self.FAT_BITS == 32 else lo
            sz = struct.unpack_from("<I", e, 28)[0]
            is_dir = bool(attr & 0x10)
            dead = [chars for was_deleted, chars in lfn if was_deleted]
            lfn = []
            if dead:
                name = "".join(c.decode("utf-16-le", "replace")
                               for c in reversed(dead)).split("\uffff")[0].rstrip("\x00")
            else:
                # the 0xE5 mark sat on the first character; "_" stands in for
                # it, the same placeholder The Sleuth Kit shows for these
                name = _fat_short_name(b"_" + e[1:])
            times = {
                "modified": _dos_stamp(struct.unpack_from("<H", e, 24)[0],
                                       struct.unpack_from("<H", e, 22)[0]),
                "created": _dos_stamp(struct.unpack_from("<H", e, 16)[0],
                                      struct.unpack_from("<H", e, 14)[0], e[13]),
                "accessed date": _dos_date(struct.unpack_from("<H", e, 18)[0]),
            }
            out.append((name, first, sz, is_dir, times))
        return out

    def deleted_files(self, *, min_size=0, max_depth=32):
        """Yield the deleted directory entries of the whole volume.

        A FAT32 delete writes 0xE5 over the first byte of the entry and frees
        its clusters in the FAT; everything else stays. So the name (rebuilt
        from the long-name fragments, whose ordinals the same 0xE5 destroys),
        the first cluster, the size and the recorded times are all still
        there. What is gone is the chain: the FAT entries that said where the
        second cluster onward lay are zeroed. Reading a file longer than one
        cluster therefore assumes it was written in one run, and the result
        says so in ``assumed_contiguous``, because the volume cannot confirm it.
        A file is ``recoverable`` only while every cluster that read would
        touch is still free; a cluster since handed to a live file means the
        assumption is already false, and the file is reported as having
        existed rather than read.

        Live directories are walked to find deleted files inside them, and a
        deleted directory whose first cluster is still free and still parses
        as a directory (it opens with "." and "..") is walked too, since a
        deleted folder of photographs is the common case on a card. A parent
        that was itself deleted is flagged with ``in_deleted_dir``.
        """
        seen = set()

        def walk(node, depth, in_deleted):
            if depth > max_depth or node[0] in seen:
                return
            seen.add(node[0])
            for name, first, sz, is_dir, times in self._deleted_in(node, in_deleted):
                if is_dir:
                    ok_dir = first >= 2 and self._fat_next(first) == 0 and self._looks_like_dir(first)
                    yield FatDeletedFile(name, node[0], True, 0, first, False,
                                         "directory", False, times, in_deleted, None)
                    if ok_dir:
                        yield from walk((first, 0, True), depth + 1, True)
                    continue
                if sz < min_size:
                    continue
                if first < 2 or not sz:
                    yield FatDeletedFile(name, node[0], False, sz, first, False,
                                         "no cluster recorded" if first < 2 else "empty",
                                         False, times, in_deleted, None)
                    continue
                need = (sz + self.cluster_bytes - 1) // self.cluster_bytes
                ok, reason = True, ""
                for k in range(need):
                    if self._fat_next(first + k) != 0:
                        # a cluster in the assumed run belongs to a live file:
                        # either this file was fragmented or it has since been
                        # overwritten, and either way the run cannot be read as it
                        ok, reason = False, ("the run its size would need crosses a live "
                                             "file, so it was fragmented or is overwritten")
                        break
                yield FatDeletedFile(name, node[0], False, sz, first, ok, reason,
                                     need > 1, times, in_deleted, (first, sz, False))
            # deleted files can sit in any live subdirectory too
            for _nm, child, _t in self.listdir_records(node):
                if child[2]:
                    yield from walk(child, depth + 1, in_deleted)

        yield from walk(self.root, 0, False)

    def _looks_like_dir(self, clus):
        """A FAT directory opens with its "." and ".." entries."""
        raw = read_at(self.fh, self._cluster_off(clus), 64)
        return len(raw) == 64 and raw[:11] == b".          " and raw[32:43] == b"..         "

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file, read from its first
        cluster on for its recorded size. Refuses one whose clusters have been
        reused, so overwritten bytes are never presented as the file."""
        if not entry.recoverable or entry._node is None:
            raise NtfsUnreadable(
                f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        first, sz, _ = entry._node
        want = sz if size is None else min(size, sz)
        need = (want + self.cluster_bytes - 1) // self.cluster_bytes
        out = bytearray()
        for k in range(need):
            out += read_at(self.fh, self._cluster_off(first + k), self.cluster_bytes)
        yield bytes(out[:want])

    def listdir(self, node):
        return [(name, child) for name, child, _times in self.listdir_records(node)]

    def read_file(self, node, size):
        clus, sz, _ = node
        yield self._read_chain(clus, sz)

    def chain_shortfall(self, node):
        """(clusters in the chain, clusters the recorded size needs) for a file
        whose cluster chain ends before its size is covered, else None.

        The directory entry records the size and the allocation table records
        where the data is, and nothing makes the two agree. When the chain is
        the shorter one read_file() returns only what the chain reaches. The
        walk is the one read_file() makes, so the two cannot disagree.
        """
        clus, sz, is_dir = node
        if is_dir or not sz:
            return None
        need = (sz + self.cluster_bytes - 1) // self.cluster_bytes
        have = 0
        for _c in self._chain(clus):
            have += 1
            if have >= need:
                return None
        return (have, need)


class Fat16Walker(Fat32Walker):
    """List and read files from a FAT16 volume, same interface as Fat32Walker.

    The directory entries, the long names and the deleted-entry rules are
    FAT32's. Three things differ, all from Microsoft's FAT specification: a
    table entry is 16 bits, the root directory is a fixed run of
    BPB_RootEntCnt entries ahead of cluster 2 (the root node carries cluster 0
    for it), and a directory entry has no high word for its first cluster.

    A volume Windows CE formatted as transaction-safe FAT ("TFAT16  ") reads
    the same way. Its files sit under a folder in the fixed root, named
    ``__TFAT_HIDDEN_ROOT_DIR__`` on the volumes measured, and that folder is
    listed as it is stored.
    """

    FAT_BITS = 16


class Fat12Walker(Fat16Walker):
    """List and read files from a FAT12 volume, same interface as Fat16Walker.

    Everything is FAT16's but the table, whose entries are twelve bits packed
    two to every three bytes (_fat12_entry).
    """

    FAT_BITS = 12


def _dos_stamp(date, time_, tenths=0):
    """A FAT date and time pair as text, exactly as stored, or "" if unset.

    FAT keeps a wall-clock reading and no zone at all, so this is a reading and
    not an instant, and it is returned as text so that nothing downstream can
    give it one. Seconds are stored in units of two, with an optional tenths
    byte carrying the odd second and hundredths on creation times.
    """
    if not date:
        return ""
    year = 1980 + ((date >> 9) & 0x7F)
    month = (date >> 5) & 0x0F
    day = date & 0x1F
    hour = (time_ >> 11) & 0x1F
    minute = (time_ >> 5) & 0x3F
    second = (time_ & 0x1F) * 2 + (tenths // 100)
    if not (1 <= month <= 12 and 1 <= day <= 31) or hour > 23 or minute > 59 or second > 59:
        return ""
    out = f"{year:04d}-{month:02d}-{day:02d} {hour:02d}:{minute:02d}:{second:02d}"
    hundredths = tenths % 100
    return f"{out}.{hundredths:02d}" if hundredths else out


def _dos_date(date):
    """A FAT date as text, with no time on it.

    FAT records a last-access DATE and no time of day. Rendering it as midnight
    would assert a reading the entry does not carry, so only the date is given.
    """
    if not date:
        return ""
    year = 1980 + ((date >> 9) & 0x7F)
    month = (date >> 5) & 0x0F
    day = date & 0x1F
    if not (1 <= month <= 12 and 1 <= day <= 31):
        return ""
    return f"{year:04d}-{month:02d}-{day:02d}"


def _exfat_stamp(value, tenths=0):
    """An exFAT timestamp as text, exactly as stored. Same packing as FAT."""
    if not value:
        return ""
    return _dos_stamp(value >> 16, value & 0xFFFF, tenths)


def _exfat_offset(byte):
    """An exFAT UTC offset byte as text, exactly as stored, or "" if not set.

    The low seven bits are a signed count of fifteen minute steps and the top
    bit says whether the field was written at all. This is reported rather than
    applied: on the one exFAT volume measured here the stored reading was not
    the writing machine's local clock and this field was the negation of its
    zone, so applying it would assert an instant the evidence does not support.
    """
    if not byte & 0x80:
        return ""
    quarters = byte & 0x7F
    if quarters & 0x40:
        quarters -= 0x80
    minutes = quarters * 15
    sign = "-" if minutes < 0 else "+"
    minutes = abs(minutes)
    return f"{sign}{minutes // 60:02d}:{minutes % 60:02d}"


def _exfat_set_checksum(raw):
    """The checksum of one exFAT directory entry set, as its File entry's
    SetChecksum field records it: a 16-bit rotate right and add over every
    byte of the set except the two bytes of the field itself (offsets 2 and 3
    of the first entry). From Microsoft's exFAT specification."""
    total = 0
    for byte in raw[:2] + raw[4:]:
        total = (((total << 15) | (total >> 1)) + byte) & 0xFFFF
    return total


def _fat_short_name(e):
    # Byte 12 carries Windows NT's case flags for a short name that had no long
    # entry: 0x08 lowercases the base, 0x10 the extension. Honouring them keeps
    # the recorded case of an 8.3 name, which a filename in evidence should hold.
    nt = e[12]
    base = e[0:8].decode("ascii", "replace").rstrip(" ")
    ext = e[8:11].decode("ascii", "replace").rstrip(" ")
    if nt & 0x08:
        base = base.lower()
    if nt & 0x10:
        ext = ext.lower()
    return f"{base}.{ext}" if ext else base


def _vfat_name(lfn):
    parts = sorted(lfn, key=lambda x: x[0])
    raw = b"".join(chunk for _, chunk in parts)
    name = raw.decode("utf-16-le", "replace")
    end = name.find("\uffff")
    if end != -1:
        name = name[:end]
    return name.split("\x00")[0]


class ExfatWalker:
    """List and read files from an exFAT volume, same interface as Fat32Walker.
    A node is (cluster, size, is_dir, fat_chain_flag)."""

    def __init__(self, fh, base):
        self.fh = fh
        self.base = base
        b = read_at(fh, base, 512)
        self.bps = 1 << b[108]
        self.spc = 1 << b[109]
        self.fat_off = struct.unpack_from("<I", b, 80)[0]
        self.heap_off = struct.unpack_from("<I", b, 88)[0]
        self.root_clus = struct.unpack_from("<I", b, 96)[0]
        self.cluster_count = struct.unpack_from("<I", b, 92)[0]
        self.cluster_bytes = self.bps * self.spc
        self.fat_start = base + self.fat_off * self.bps
        self.heap_start = base + self.heap_off * self.bps
        self.root = (self.root_clus, 0, True, False)
        self._orphan_cache = None                    # recover_deleted() fills it once

    def _fat_next(self, clus):
        raw = read_at(self.fh, self.fat_start + clus * 4, 4)
        if len(raw) < 4:
            return 0xFFFFFFFF                        # truncated image, end of chain
        return struct.unpack_from("<I", raw, 0)[0]

    def _cluster_off(self, clus):
        return self.heap_start + (clus - 2) * self.cluster_bytes

    def _read(self, clus, size, contiguous):
        out = bytearray()
        if contiguous:
            need = size if size else self.cluster_bytes
            n = (need + self.cluster_bytes - 1) // self.cluster_bytes
            for i in range(n):
                out += read_at(self.fh, self._cluster_off(clus + i), self.cluster_bytes)
        else:
            seen = set()
            c = clus
            while 0x2 <= c < 0xFFFFFFF7 and c not in seen:
                seen.add(c)
                out += read_at(self.fh, self._cluster_off(c), self.cluster_bytes)
                if size and len(out) >= size:
                    break
                c = self._fat_next(c)
        return bytes(out[:size]) if size else bytes(out)

    def inode(self, node):
        return node

    def entry(self, node):
        _, size, is_dir, _ = node
        return (0o040000 if is_dir else 0o100000, size, 0)

    def listdir_records(self, node):
        """(name, node, recorded times as stored) for every entry.

        exFAT carries a UTC offset beside each timestamp, unlike FAT. It is
        reported as stored rather than applied, so no instant is asserted.
        """
        clus, _, _, contig = node
        raw = self._read(clus, 0, contig)
        out = []
        i = 0
        while i < len(raw):
            etype = raw[i]
            if etype == 0x00:
                break
            if etype == 0x85:                       # File directory entry
                secs = raw[i + 1]
                s2 = raw[i + 32:i + 64]             # Stream extension (next entry)
                flags = s2[1]
                name_len = s2[3]
                first = struct.unpack_from("<I", s2, 20)[0]
                data_len = struct.unpack_from("<Q", s2, 24)[0]
                is_dir = bool(raw[i + 4] & 0x10)
                contiguous = bool(flags & 0x02)
                # name entries follow, 0xC1, 15 UTF-16 chars each
                name = ""
                for k in range(2, secs + 1):
                    ent = raw[i + 32 * k:i + 32 * k + 32]
                    if not ent or ent[0] != 0xC1:
                        break
                    name += ent[2:32].decode("utf-16-le", "replace")
                name = name[:name_len]
                if name not in (".", ".."):
                    cre, mod, acc = struct.unpack_from("<III", raw, i + 8)
                    out.append((name, (first, data_len, is_dir, contiguous), {
                        "modified": _exfat_stamp(mod, raw[i + 21]),
                        "created": _exfat_stamp(cre, raw[i + 20]),
                        "accessed": _exfat_stamp(acc),
                        "modified utc offset": _exfat_offset(raw[i + 23]),
                        "created utc offset": _exfat_offset(raw[i + 22]),
                        "accessed utc offset": _exfat_offset(raw[i + 24]),
                    }))
                i += 32 * (secs + 1)
            else:
                i += 32
        return out

    def _cluster_in_use(self, clus):
        """True when the Allocation Bitmap marks this cluster used. Read once."""
        bits = getattr(self, "_alloc_bits", None)
        if bits is None:
            bits = b""
            clus_r, _, _, contig = self.root
            raw = self._read(clus_r, 0, contig)
            for i in range(0, len(raw), 32):
                if raw[i] == 0x81:                   # Allocation Bitmap entry
                    first = struct.unpack_from("<I", raw, i + 20)[0]
                    length = struct.unpack_from("<Q", raw, i + 24)[0]
                    bits = self._read(first, length, True)
                    break
            self._alloc_bits = bits
        idx = clus - 2
        if idx < 0 or (idx >> 3) >= len(bits):
            return True                              # off the bitmap: treat as used
        return bool(bits[idx >> 3] & (1 << (idx & 7)))

    def _deleted_in(self, node, in_deleted_dir):
        clus, _, _, contig = node
        raw = self._read(clus, 0, contig)
        out = []
        i = 0
        while i < len(raw):
            etype = raw[i]
            if etype == 0x00:
                break
            if etype == 0x05:                        # File entry with the in-use bit cleared
                secs = raw[i + 1]
                s2 = raw[i + 32:i + 64]
                if len(s2) < 32 or s2[0] not in (0x40, 0xC0):
                    i += 32
                    continue
                flags = s2[1]
                name_len = s2[3]
                first = struct.unpack_from("<I", s2, 20)[0]
                data_len = struct.unpack_from("<Q", s2, 24)[0]
                is_dir = bool(raw[i + 4] & 0x10)
                contiguous = bool(flags & 0x02)
                name = ""
                for k in range(2, secs + 1):
                    ent = raw[i + 32 * k:i + 32 * k + 32]
                    if not ent or ent[0] not in (0x41, 0xC1):
                        break
                    name += ent[2:32].decode("utf-16-le", "replace")
                name = name[:name_len]
                cre, mod, acc = struct.unpack_from("<III", raw, i + 8)
                times = {
                    "modified": _exfat_stamp(mod, raw[i + 21]),
                    "created": _exfat_stamp(cre, raw[i + 20]),
                    "accessed": _exfat_stamp(acc),
                    "modified utc offset": _exfat_offset(raw[i + 23]),
                    "created utc offset": _exfat_offset(raw[i + 22]),
                    "accessed utc offset": _exfat_offset(raw[i + 24]),
                }
                out.append((name, first, data_len, is_dir, contiguous, times))
                i += 32 * (secs + 1)
            else:
                i += 32
        return out

    def deleted_files(self, *, min_size=0, max_depth=32):
        """Yield the deleted directory entries of the whole volume.

        An exFAT delete clears the in-use bit of the entry's type byte (0x85,
        0xC0 and 0xC1 become 0x05, 0x40 and 0x41) and clears the file's bits in
        the Allocation Bitmap; every field survives, including the stream's
        NoFatChain flag, first cluster and length. A file the driver wrote in
        one run carries NoFatChain and is read exactly from its first cluster
        for its length. A fragmented file kept its chain in the FAT; if that
        chain is still intact it is followed, and if it has been cleared the
        file is reported as not recoverable rather than read on an assumption
        the entry itself contradicts. Either way a file is ``recoverable`` only
        while every cluster the read would touch is still free.

        Live directories are walked for deleted files inside them, and a
        deleted directory whose first cluster is still free and still parses
        as a directory is walked too, flagged with ``in_deleted_dir``.
        """
        seen = set()

        def walk(node, depth, in_deleted):
            if depth > max_depth or node[0] in seen:
                return
            seen.add(node[0])
            for name, first, size, is_dir, contiguous, times in self._deleted_in(node, in_deleted):
                if is_dir:
                    ok_dir = (first >= 2 and not self._cluster_in_use(first)
                              and self._looks_like_dir(first))
                    yield FatDeletedFile(name, node[0], True, 0, first, False,
                                         "directory", False, times, in_deleted, None)
                    if ok_dir:
                        yield from walk((first, 0, True, contiguous), depth + 1, True)
                    continue
                if size < min_size:
                    continue
                if first < 2 or not size:
                    yield FatDeletedFile(name, node[0], False, size, first, False,
                                         "no cluster recorded" if first < 2 else "empty",
                                         False, times, in_deleted, None)
                    continue
                need = (size + self.cluster_bytes - 1) // self.cluster_bytes
                ok, reason, chain = True, "", None
                if contiguous:
                    chain = list(range(first, first + need))
                else:
                    chain, c, s2 = [], first, set()
                    while 0x2 <= c < 0xFFFFFFF7 and c not in s2 and len(chain) < need:
                        chain.append(c); s2.add(c); c = self._fat_next(c)
                    if len(chain) < need:
                        ok, reason, chain = False, "the FAT chain was cleared on delete", None
                if ok and any(self._cluster_in_use(c) for c in chain):
                    ok, reason = False, "clusters reused by a later file"
                yield FatDeletedFile(name, node[0], False, size, first, ok, reason,
                                     False, times, in_deleted,
                                     (chain, size) if ok else None)
            for _nm, child, _t in self.listdir_records(node):
                if child[2]:
                    yield from walk(child, depth + 1, in_deleted)

        yield from walk(self.root, 0, False)

    def _looks_like_dir(self, clus):
        """An exFAT directory's first entry is a real entry type (a set or a
        cleared in-use bit over the file, stream, name or bitmap kinds)."""
        raw = read_at(self.fh, self._cluster_off(clus), 32)
        return len(raw) == 32 and (raw[0] & 0x7F) in (0x05, 0x40, 0x41, 0x01, 0x02, 0x03)

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file, cluster by cluster along
        the chain that was kept or the run the entry declared. Refuses one whose
        clusters have been reused, so overwritten bytes are never presented as
        the file. Takes a deleted_files() record or a recover_deleted() one."""
        if isinstance(entry, FlashDeletedFile):      # an orphan entry
            if not entry.recoverable:
                raise NtfsUnreadable(
                    f"orphan file {entry.name!r} is not recoverable: {entry.reason}")
            left = entry.size if size is None else min(size, entry.size)
            for c in entry._plan:                    # pylint: disable=protected-access
                if left <= 0:
                    return
                data = read_at(self.fh, self._cluster_off(c), self.cluster_bytes)
                if len(data) < self.cluster_bytes:
                    raise NtfsUnreadable(
                        f"orphan file {entry.name!r}: cluster {c} lies past the end "
                        "of the image")
                yield data[:left]
                left -= len(data[:left])
            return
        if not entry.recoverable or entry._node is None:
            raise NtfsUnreadable(
                f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        chain, sz = entry._node
        want = sz if size is None else min(size, sz)
        out = bytearray()
        for c in chain:
            out += read_at(self.fh, self._cluster_off(c), self.cluster_bytes)
            if len(out) >= want:
                break
        yield bytes(out[:want])

    def listdir(self, node):
        return [(name, child) for name, child, _times in self.listdir_records(node)]

    def _first_bitmap(self):
        """The bytes of the first Allocation Bitmap, or b"" when the root
        directory names none. A TexFAT volume has two, and BitmapFlags bit 0
        marks the second."""
        raw = self._read(self.root_clus, 0, False)
        for i in range(0, len(raw) - 31, 32):
            if raw[i] == 0x00:                       # end of the directory
                break
            if raw[i] != 0x81:
                continue
            if raw[i + 1] & 0x01:                    # the second TexFAT bitmap
                continue
            first_clus = struct.unpack_from("<I", raw, i + 20)[0]
            length = struct.unpack_from("<Q", raw, i + 24)[0]
            if not first_clus or not length:
                return b""
            return self._read(first_clus, length, False)
        return b""

    # ---- orphan entry sets --------------------------------------------------
    # A directory cluster can stay allocated after the tree stops reaching it:
    # the entry that named the directory is gone, or the FAT link that led to
    # this cluster of it is. The entry sets in such a cluster are still marked
    # in use and still carry a valid checksum, and the files they name can
    # still be allocated too. Nothing in the live listing shows them. Measured
    # on four exFAT partition images (README, "exFAT: orphan directory entries").

    def _orphan_state(self):
        """(first FAT, reached flags, bitmap bytes, live files) for
        recover_deleted(), worked out once per walker.

        ``reached`` has one byte per cluster number, set for every cluster the
        live tree accounts for: the root directory's chain, each directory's
        clusters, each file's clusters (the run its size needs when NoFatChain
        is set, else its whole chain in the first FAT), both allocation bitmaps
        and the up-case table. ``live files`` is the (first cluster, size) of
        every live file, so an orphan entry that names the same allocation as
        a live one can say so."""
        if self._orphan_cache is not None:
            return self._orphan_cache
        total = self.cluster_count + 2
        cb = self.cluster_bytes
        raw = read_at(self.fh, self.fat_start, total * 4)
        raw += b"\x00" * (total * 4 - len(raw))      # a truncated image: no links
        fat = array.array("I")
        fat.frombytes(raw)
        if sys.byteorder != "little":
            fat.byteswap()
        reached = bytearray(total)

        def run(first, count):
            if first >= 2:
                for c in range(first, min(first + count, total)):
                    reached[c] = 1

        def chain(first):
            c, seen = first, set()
            while 2 <= c < total and c not in seen:
                seen.add(c)
                reached[c] = 1
                c = fat[c]

        chain(self.root_clus)
        root_raw = self._read(self.root_clus, 0, False)
        for i in range(0, len(root_raw) - 31, 32):
            if root_raw[i] == 0x00:
                break
            if root_raw[i] in (0x81, 0x82):          # allocation bitmap, up-case table
                first = struct.unpack_from("<I", root_raw, i + 20)[0]
                length = struct.unpack_from("<Q", root_raw, i + 24)[0]
                run(first, (length + cb - 1) // cb)
                chain(first)
        live = set()
        stack, seen_dirs = [self.root], {self.root_clus}
        while stack:
            node = stack.pop()
            try:
                listing = self.listdir_records(node)
            except (IndexError, struct.error):       # a directory cut short
                continue
            for _name, child, _times in listing:
                first, size, is_dir, contiguous = child
                need = (size + cb - 1) // cb
                if is_dir:
                    if contiguous:
                        run(first, max(need, 1))
                    else:
                        chain(first)
                    if 2 <= first < total and first not in seen_dirs:
                        seen_dirs.add(first)
                        stack.append(child)
                elif size and first >= 2:
                    live.add((first, size))
                    if contiguous:
                        run(first, need)
                    else:
                        chain(first)
        self._orphan_cache = (fat, reached, self._first_bitmap(), live)
        return self._orphan_cache

    @staticmethod
    def _entry_sets(raw, limit):
        """The in-use file entry sets that start in the first ``limit`` bytes
        of ``raw``: [(offset, set bytes)], and the offsets of those that run
        past the end of ``raw``. A set is a 0x85 File entry, its 0xC0 stream
        extension, and name entries enough for the name's length, with the
        checksum the File entry records."""
        sets, cut = [], []
        types = raw[:limit:32]
        k = types.find(0x85)
        while k != -1:
            at, step = k * 32, 1
            if at + 2 > len(raw):
                break
            secs = raw[at + 1]
            end = at + 32 * (secs + 1)
            if 2 <= secs <= 18:
                if end > len(raw):
                    cut.append(at)
                elif raw[at + 32] == 0xC0:
                    ent = raw[at:end]
                    names = 0
                    while names + 2 <= secs and ent[32 * (names + 2)] == 0xC1:
                        names += 1
                    if (0 < ent[35] <= 15 * names and _exfat_set_checksum(ent)
                            == struct.unpack_from("<H", ent, 2)[0]):
                        sets.append((at, ent))
                        step = secs + 1
            k = types.find(0x85, k + step)
        return sets, cut

    def recover_deleted(self):
        """Yield a FlashDeletedFile (``kind`` "exfat") for every orphan file
        entry: an in-use file entry set, checksum valid, in an allocated
        cluster the live tree does not reach.

        What counts as reached is in _orphan_state(). Every allocated cluster
        outside it is read and searched for entry sets, a set that runs off
        the end of its cluster being completed from the cluster the first FAT
        links next, or the one after it. Entries marked deleted are not
        included (deleted_files() lists those from live directories), free
        clusters are not searched, and the second FAT is not followed.

        An orphan directory entry is walked down: the clusters it names that
        are allocated and unreached are read as its directory, so a file under
        it has ``parent_path`` set to the names that lead to it, joined with
        "/", starting at the first orphan directory. A file whose entry sits
        in a directory cluster no orphan directory entry names has a
        ``parent_path`` of None: nothing on the volume says what that
        directory was called. ``parent`` is the cluster the entry set is in.

        A file is ``recoverable`` when its size is not zero and every cluster
        it names is allocated and unreached: the run its size needs when
        NoFatChain is set, else a chain in the first FAT that runs to an
        end-of-chain mark and is long enough for the size. Otherwise
        ``reason`` says what failed. A cluster a live file or directory holds
        refuses the read, so a live file's bytes are never given as the
        orphan's. Two orphan entries can name the same clusters and the volume
        does not say which wrote last, so both stay recoverable and ``note``
        says so.

        ``ident`` is the first cluster. ``mtime`` and ``mode`` are None: exFAT
        stores a wall clock and a UTC offset, and this reader reports both as
        stored and does not apply one to the other. They are in ``times``, the
        same readings listdir_records() gives. Entry sets that are byte for
        byte the same in several clusters are one entry, and ``note`` gives
        the count. These files are never part of the live listing."""
        fat, reached, bits, live = self._orphan_state()
        total = self.cluster_count + 2
        cb = self.cluster_bytes

        def allocated(c):
            idx = c - 2
            return (idx >> 3) < len(bits) and bool(bits[idx >> 3] & (1 << (idx & 7)))

        def orphan(c):
            return 2 <= c < total and not reached[c] and allocated(c)

        # every allocated, unreached cluster, read in runs
        by_cluster = {}                              # cluster -> [set bytes]
        set_starts = {}                              # cluster -> lowest set offset
        cut = []                                     # (cluster, offset, tail bytes)
        step = max(1, (1 << 22) // cb)
        c = 2
        while c < total and (c - 2) >> 3 < len(bits):
            if not (c - 2) & 7 and not bits[(c - 2) >> 3]:
                c += 8                               # eight free clusters
                continue
            if not orphan(c):
                c += 1
                continue
            end = c + 1
            while end < total and end - c < step and orphan(end):
                end += 1
            data = read_at(self.fh, self._cluster_off(c), (end - c) * cb)
            for n in range(len(data) // cb):
                one = data[n * cb:(n + 1) * cb]
                sets, tails = self._entry_sets(one, cb)
                if sets:
                    by_cluster[c + n] = [ent for _at, ent in sets]
                    set_starts[c + n] = sets[0][0]
                cut.extend((c + n, at, one[at:]) for at in tails)
            c = end
        for clus, _at, tail in cut:
            # the rest of the set is in the next cluster of the directory: the
            # one the first FAT links, or the one after when the directory is a
            # single run. The checksum decides whether a candidate is right.
            for nxt in (fat[clus], clus + 1):
                if not orphan(nxt):
                    continue
                more = read_at(self.fh, self._cluster_off(nxt), 32 * 19)
                sets, _tails = self._entry_sets(tail + more, 32)
                if sets:
                    by_cluster.setdefault(clus, []).append(sets[0][1])
                    set_starts.setdefault(clus, _at)
                    break

        def fields(ent):
            name = ""
            for k in range(2, ent[1] + 1):
                if ent[32 * k] != 0xC1:
                    break
                name += ent[32 * k + 2:32 * k + 32].decode("utf-16-le", "replace")
            return (name[:ent[35]], struct.unpack_from("<I", ent, 52)[0],
                    struct.unpack_from("<Q", ent, 56)[0], bool(ent[4] & 0x10),
                    bool(ent[33] & 0x02))

        def named(first, size, is_dir, contiguous):
            """(clusters the entry names, whether its FAT chain reached an
            end-of-chain mark). A run when NoFatChain is set, else the chain."""
            need = (size + cb - 1) // cb
            if is_dir:
                need = max(need, 1)
            if not 2 <= first < total:
                return [], True
            if contiguous:
                return list(range(first, min(first + need, total))), True
            out, seen, c = [], set(), first
            while 2 <= c < total and c not in seen:
                out.append(c)
                seen.add(c)
                c = fat[c]
            return out, c >= 0xFFFFFFF8

        # which orphan directory clusters an orphan directory entry leads to
        claimed = set()
        for sets in by_cluster.values():
            for ent in sets:
                _name, first, size, is_dir, contiguous = fields(ent)
                if is_dir:
                    for c in named(first, size, True, contiguous)[0]:
                        if not orphan(c):
                            break
                        claimed.add(c)
        linked = {fat[c] for c in by_cluster if fat[c] in by_cluster and fat[c] != c}
        heads = sorted(c for c in by_cluster if c not in claimed and c not in linked)

        found = {}                                   # set bytes -> [cluster, path, copies]
        visited = set()

        def walk(clusters, path):
            stack = [(clusters, path)]
            while stack:
                clusters, path = stack.pop()
                below = []
                for clus in clusters:
                    if clus in visited:
                        continue
                    visited.add(clus)
                    for ent in by_cluster.get(clus, ()):
                        name, first, size, is_dir, contiguous = fields(ent)
                        if is_dir:
                            kids = []
                            for c in named(first, size, True, contiguous)[0]:
                                if not orphan(c):
                                    break
                                kids.append(c)
                            if kids:
                                below.append((kids, name if path is None
                                              else f"{path}/{name}"))
                            continue
                        row = found.get(ent)
                        if row is None:
                            found[ent] = [clus, path, 1]
                        else:
                            row[2] += 1
                            if row[1] is None and path is not None:
                                row[0], row[1] = clus, path
                stack.extend(reversed(below))

        for head in heads + sorted(by_cluster):
            if head in visited:
                continue
            group, c = [], head
            while c in by_cluster and c not in visited and c not in group:
                group.append(c)
                c = fat[c]
            walk(group, None)

        entries, users = [], collections.Counter()
        for ent, (clus, path, copies) in found.items():
            name, first, size, _is_dir, contiguous = fields(ent)
            need = (size + cb - 1) // cb
            clusters, ended = named(first, size, False, contiguous)
            why = ""
            if not size:
                why = "empty"
            elif first < 2:
                why = "no cluster recorded"
            elif not clusters:
                why = "its first cluster is past the end of the volume"
            elif (first, size) in live:
                why = "a live file has the same first cluster and size"
            elif any(reached[c] for c in clusters):
                n = sum(1 for c in clusters if reached[c])
                why = (f"{n:,} of the {len(clusters):,} clusters it names belong to "
                       "live files or directories")
            elif not all(allocated(c) for c in clusters):
                n = sum(1 for c in clusters if not allocated(c))
                why = (f"{n:,} of the {len(clusters):,} clusters it names are free in "
                       "the allocation bitmap")
            elif len(clusters) < need:
                why = (f"it names {len(clusters):,} of the {need:,} clusters its size "
                       "needs")
            elif not ended:
                why = "its chain in the first FAT does not run to an end-of-chain mark"
            cre, mod, acc = struct.unpack_from("<III", ent, 8)
            e = FlashDeletedFile("exfat", first, name, clus, path, size, None, None, 0,
                                 [] if why else clusters[:need], self)
            if why:
                e.recoverable, e.reason = False, why
            else:
                users.update(e._plan)                # pylint: disable=protected-access
            e.times = {
                "modified": _exfat_stamp(mod, ent[21]),
                "created": _exfat_stamp(cre, ent[20]),
                "accessed": _exfat_stamp(acc),
                "modified utc offset": _exfat_offset(ent[23]),
                "created utc offset": _exfat_offset(ent[22]),
                "accessed utc offset": _exfat_offset(ent[24]),
            }
            e.note = ("an orphan entry: an in-use file entry set in an allocated "
                      "directory cluster the live tree does not reach. It is not in "
                      "the live listing.")
            if copies > 1:
                e.note += f" The same entry set is in {copies:,} such clusters."
            entries.append(e)
        for e in entries:
            # a cluster two entries name, or entry sets inside the bytes the
            # file's size covers (sets in the slack past its end do not count)
            plan = e._plan                           # pylint: disable=protected-access
            if any(users[c] > 1 or set_starts.get(c, e.size) < e.size - n * cb
                   for n, c in enumerate(plan)):
                e.note += (" Some of its clusters are also named by another orphan "
                           "entry or hold orphan entry sets themselves, so the bytes "
                           "may be another file's.")
        entries.sort(key=lambda e: (e.parent_path is None, e.parent_path or "",
                                    e.name, e.ident))
        yield from entries

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        exFAT does not use its FAT to say what is in use, the way FAT32 does. It
        keeps an Allocation Bitmap, one bit per cluster, and finds it through a
        directory entry of type 0x81 in the root directory. A set bit means the
        cluster is not available, so what is left is where deleted content
        survives until something overwrites it.

        Field offsets are from Microsoft's exFAT specification: the bitmap entry
        gives FirstCluster at 20 and DataLength at 24 (section 7.1), the boot
        sector gives ClusterCount at 92 (section 3.1), and the first bit of the
        bitmap is the lowest bit of the first byte and stands for cluster 2.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering. An empty list means the bitmap was not
        found, which a caller must not read as "nothing is free".
        """
        cluster = self.cluster_bytes
        if not cluster or not self.cluster_count:
            return []
        bits = self._first_bitmap()
        if not bits:
            return []
        total = min(len(bits) * 8, self.cluster_count)

        runs, run_start, pos = [], None, 0
        while pos < total:
            byte = bits[pos >> 3]
            if not (pos & 7) and pos + 8 <= total and byte in (0x00, 0xFF):
                if byte == 0x00:                     # eight free clusters
                    if run_start is None:
                        run_start = pos
                elif run_start is not None:          # eight used ones
                    runs.append((run_start, pos - run_start))
                    run_start = None
                pos += 8
                continue
            if byte & (1 << (pos & 7)):
                if run_start is not None:
                    runs.append((run_start, pos - run_start))
                    run_start = None
            elif run_start is None:
                run_start = pos
            pos += 1
        if run_start is not None:
            runs.append((run_start, total - run_start))

        out = []
        for first, n in runs:
            size = n * cluster
            if size >= min_bytes:
                out.append((self._cluster_off(first + 2), size))
        return out

    def read_file(self, node, size):
        clus, sz, _, contig = node
        if not sz:
            # _read() takes a size of zero to mean a directory, read to the end
            # of its allocation. An empty file has no first cluster, and read
            # that way it came back as one cluster of the volume's own bytes.
            yield b""
            return
        yield self._read(clus, sz, contig)

    def chain_shortfall(self, node):
        """(clusters in the chain, clusters the recorded size needs) for a file
        whose FAT chain ends before its size is covered, else None.

        Only a file whose stream extension leaves NoFatChain clear is described
        by the FAT; one that sets it is a single run and has no chain to fall
        short. The directory entry records the size, the FAT records where the
        data is, and nothing makes the two agree. When the chain is the shorter
        one read_file() returns only what the chain reaches. The walk is the
        one _read() makes, so the two cannot disagree.
        """
        clus, sz, is_dir, contig = node
        if contig or is_dir or not sz:
            return None
        need = (sz + self.cluster_bytes - 1) // self.cluster_bytes
        have = 0
        seen = set()
        c = clus
        while 0x2 <= c < 0xFFFFFFF7 and c not in seen:
            seen.add(c)
            have += 1
            if have >= need:
                return None
            c = self._fat_next(c)
        return (have, need)


# ---------------------------------------------------------------------------
# QNX4 (the QNX 4 filesystem, distinct from the qnx6 this tool is named for).
#
# QNX 4 shipped from 1990 and its filesystem is still met on older embedded
# and industrial systems. Every constant and field offset below is read out of
# the Linux kernel's own read-only qnx4 driver, the same sourcing as the qnx6
# code above:
#
#   QNX4_SUPER_MAGIC 0x002f          include/uapi/linux/magic.h:54
#   struct qnx4_inode_entry           include/uapi/linux/qnx4_fs.h:44
#   struct qnx4_link_info             include/uapi/linux/qnx4_fs.h:63
#   struct qnx4_xblk                  include/uapi/linux/qnx4_fs.h:71
#   field widths (le16/le32/u8)       include/uapi/linux/qnxtypes.h
#   union qnx4_directory_entry        fs/qnx4/qnx4.h:75
#
# The layout, in one paragraph. Blocks are 512 bytes and every block number
# stored on disk is 1-based: block 1 is the boot block at offset 0, block 2
# the superblock at offset 512. The superblock is four 64-byte inode entries,
# RootDir/Inode/Boot/AltBoot; RootDir's name "/" doubles as the 0x002f magic
# (fs/qnx4/inode.c qnx4_checkroot(), which also refuses to mount unless the
# root directory carries a ".bitmap" entry). A directory's data is a run of
# 64-byte entries: a name of up to 16 bytes is a full inode entry stored
# inline, a longer name (up to 48) is a qnx4_link_info pointing at the real
# inode entry by (block, index), conventionally inside the ".inodes" file
# (fs/qnx4/dir.c, fs/qnx4/namei.c; the status byte at offset 63 says which:
# 0x08 QNX4_FILE_LINK, else 0x01 QNX4_FILE_USED inline). A file's data is a
# run of extents: the first lives in the inode, extents 2..n in a chain of
# xblk blocks whose signature is "IamXblk" (fs/qnx4/inode.c qnx4_block_map()).
# The kernel addresses an inode entry as ino = block * 8 + index, and the same
# convention is used for the walker's node numbers, so root is inode 8
# (QNX4_ROOT_INO * QNX4_INODES_PER_BLOCK, fs/qnx4/inode.c:233).
#
# Validated by round-trip against the Linux kernel driver itself: a fixture
# populated with nested directories, a multi-extent file, a long name, a
# symlink, an empty file and distinct modes, owners and mtimes was mounted
# read-only with fs/qnx4 (kernel 7.0.0) and every name, mode, owner, size,
# mtime, symlink target and byte of content the kernel reported was required
# to match what this walker reads. The fixture generator is a separate
# program, not this parser, and its skeleton follows Peter Waechtler's dinit
# 0.1 (the Linux-side QNX4 formatter, GPL-2), a second, independent statement
# of the same layout. Synthetic-only validation: no confirmed real QNX4
# volume exists in the test corpus.
# ---------------------------------------------------------------------------
QNX4_BLOCK = 512
QNX4_DIRENT = 64
QNX4_ROOT_NODE = 8            # QNX4_ROOT_INO(1) * QNX4_INODES_PER_BLOCK(8)
QNX4_F_USED, QNX4_F_LINK = 0x01, 0x08
QNX4_XBLK_SIG = b"IamXblk"    # fs/qnx4/inode.c:110 checks these 7 bytes


# ---------------------------------------------------------------- NTFS
# Field offsets and structure layouts below come from the Linux-NTFS project's
# published NTFS documentation (Richard Russon and Yuval Fledel, "NTFS
# Documentation", https://flatcap.github.io/linux-ntfs/ntfs/), which describes
# the on-disk format independently of any implementation, and are confirmed
# against a volume written by mkntfs. No NTFS implementation's source was read
# for this: ntfs-3g and The Sleuth Kit are both under licences this file is not.

NTFS_OEM = b"NTFS    "
NTFS_ROOT = 5                       # the root directory is always MFT record 5
NTFS_FILE = b"FILE"
NTFS_INDX = b"INDX"

# attribute types this walker reads
NTFS_STANDARD_INFORMATION = 0x10
NTFS_ATTRIBUTE_LIST       = 0x20
NTFS_FILE_NAME            = 0x30
NTFS_DATA                 = 0x80
NTFS_INDEX_ROOT           = 0x90
NTFS_INDEX_ALLOCATION     = 0xA0
NTFS_END                  = 0xFFFFFFFF

NTFS_ATTR_COMPRESSED = 0x0001
NTFS_ATTR_ENCRYPTED  = 0x4000
NTFS_ATTR_SPARSE     = 0x8000

# A reparse point is attribute 0xC0: a 32-bit tag, a 16-bit data length, two
# reserved bytes, then the data. The tags and the file attribute bits below are
# Microsoft's, from [MS-FSCC] 2.1.2.1 (Reparse Tags) and 2.6 (File Attributes).
# Fifteen more cloud tags, IO_REPARSE_TAG_CLOUD_1 to _F, differ from the first
# only in the fourth hex digit (0x9000101A to 0x9000F01A).
NTFS_REPARSE_POINT        = 0xC0
IO_REPARSE_TAG_WOF        = 0x80000017
IO_REPARSE_TAG_CLOUD      = 0x9000001A
IO_REPARSE_TAG_CLOUD_MASK = 0xFFFF0FFF
NTFS_FILE_ATTRIBUTE_SPARSE_FILE           = 0x00000200
NTFS_FILE_ATTRIBUTE_REPARSE_POINT         = 0x00000400
NTFS_FILE_ATTRIBUTE_OFFLINE               = 0x00001000
NTFS_FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS = 0x00400000

# A file compressed by the Windows Overlay Filter (compact /exe; Store app and
# Defender platform files on real images) keeps an unnamed $DATA of the file's
# full size in which every
# cluster is a hole, its real content compressed in a stream named
# WofCompressedData, and a reparse point saying how. The reparse data is two
# pairs of 32-bit values: the overlay's version and provider (2 is the file
# provider; 1 is WIMBoot, whose content is in a WIM file elsewhere), then the
# provider's version and algorithm. Microsoft names the algorithms and their
# chunk sizes (FILE_PROVIDER_EXTERNAL_INFO_V1 and WOF_FILE_COMPRESSION_INFO_V1
# on learn.microsoft.com); the numbers are what compact /exe:<name> wrote for
# each on Windows 11 build 26200 (tests/fixtures/ntfs-windows.img.gz).
WOF_STREAM        = "WofCompressedData"
WOF_PROVIDER_FILE = 2
WOF_ALGORITHMS = {0: ("xpress4k", 4096), 1: ("lzx", 32768),
                  2: ("xpress8k", 8192), 3: ("xpress16k", 16384)}

NTFS_BITMAP       = 6            # $Bitmap: one bit per cluster, set when in use
NTFS_MFT_IN_USE   = 0x0001
NTFS_MFT_IS_DIR   = 0x0002

# FILETIME counts 100 ns ticks from 1601-01-01 UTC; this is the gap to the Unix epoch.
NTFS_EPOCH_DELTA = 11644473600


class NtfsUnreadable(Exception):
    """A file whose bytes this walker will not guess at (encrypted, or an
    attribute shape it does not implement). Raised rather than returning short
    data, because a short read here would be indistinguishable from a small file."""


def ntfs_time(v):
    """A FILETIME as Unix seconds, or 0 when it is unset or out of range."""
    if not v:
        return 0
    sec = v / 10_000_000 - NTFS_EPOCH_DELTA
    return sec if -12219292800 < sec < 253402300799 else 0


def _ntfs_file_names(attrs):
    """[(parent reference, name)] for every name a record's $FILE_NAME gives it.

    A record carries one $FILE_NAME per link, so a hard-linked file names every
    directory it appears in. Each holds the parent's reference, which is a
    record number in its low 48 bits and the sequence number the name was
    written for in its top 16.

    Namespace 2 is the 8.3 name of a file that also has a long one, indexed
    beside it. Reporting both lists every such file twice, once under a name
    nobody typed. Namespace 3 is a single entry serving as both, because the
    name is already 8.3-legal, and is kept. Neither committed fixture carries a
    namespace 2 name, because both were built on macOS, which writes POSIX
    names: a real Windows volume is full of them (93,048 of 249,943 on one
    7.4 GB acquisition), which is why this is exercised by a constructed
    control in the self-test rather than only by a fixture.
    """
    out = []
    for a in attrs:
        if a.type != NTFS_FILE_NAME or not a.resident:
            continue
        v = a.value
        if len(v) < 0x42:
            continue
        ref = struct.unpack_from("<Q", v, 0)[0]
        nlen, namespace = v[0x40], v[0x41]
        if namespace == 2:
            continue
        end = 0x42 + nlen * 2
        if end > len(v):
            continue                        # the record does not hold the name it declares
        name = v[0x42:end].decode("utf-16-le", "replace")
        if not name or name in (".", ".."):
            continue
        out.append((ref, name))
    return out


def _ntfs_std_times(attrs):
    """(created, modified, accessed) from a record's $STANDARD_INFORMATION, as
    Unix seconds, each 0 where the attribute is absent or too short to hold it.

    The attribute holds four FILETIMEs: created at 0, last written at 8, the
    record's own last change at 16, last read at 24. $FILE_NAME carries a second
    set of the same four, and the two are not kept in step: on the committed
    fixture a file's accessed time here is fifteen seconds later than the one its
    $FILE_NAME holds, which is what an examiner asking when a file was last read
    means. Every reader of the attribute goes through this one function so the
    three offsets cannot drift apart between a listing, a live file and a deleted
    record. Each field is guarded on its own length, so a short attribute yields
    the fields it does hold rather than nothing.
    """
    for a in attrs:
        if a.type == NTFS_STANDARD_INFORMATION and a.resident:
            v = a.value
            created = ntfs_time(struct.unpack_from("<Q", v, 0)[0]) if len(v) >= 8 else 0
            modified = ntfs_time(struct.unpack_from("<Q", v, 8)[0]) if len(v) >= 16 else 0
            accessed = ntfs_time(struct.unpack_from("<Q", v, 24)[0]) if len(v) >= 32 else 0
            return created, modified, accessed
    return 0, 0, 0


def _ntfs_fixup(buf, per, name):
    """Apply the update sequence array to a multi-sector record.

    NTFS stamps the last two bytes of every sector of a record with one value
    and keeps the real bytes in an array in the header, so a torn write is
    detectable. The record cannot be parsed until they are put back.
    """
    if len(buf) < 8:
        return None
    if buf[0:4] != name:
        return None
    off, count = struct.unpack_from("<HH", buf, 4)
    if count < 1 or off + count * 2 > len(buf):
        return None
    usn = buf[off:off + 2]
    out = bytearray(buf)
    for i in range(count - 1):
        end = (i + 1) * per
        if end > len(out):
            break
        if bytes(out[end - 2:end]) != usn:
            return None                 # a sector that was not written with the rest
        out[end - 2:end] = buf[off + 2 + i * 2: off + 4 + i * 2]
    return bytes(out)


def _ntfs_runs(data, offset, cluster_count):
    """Decode a mapping-pair list into [(lcn or None, clusters)], in VCN order.

    Each pair is a header byte giving the width of a length field and of an
    offset field, then those two fields. The offset is signed and relative to
    the previous run's start, and a zero-width offset means the run is sparse:
    it occupies VCNs and no clusters, and reads as zeros.
    """
    runs, pos, lcn, seen = [], offset, 0, 0
    while pos < len(data):
        head = data[pos]
        if head == 0:
            break
        len_size, off_size = head & 0x0F, head >> 4
        pos += 1
        if len_size == 0 or pos + len_size + off_size > len(data):
            return None
        length = int.from_bytes(data[pos:pos + len_size], "little", signed=False)
        pos += len_size
        if off_size:
            delta = int.from_bytes(data[pos:pos + off_size], "little", signed=True)
            pos += off_size
            lcn += delta
            runs.append((lcn, length))
        else:
            runs.append((None, length))     # sparse
        seen += length
        if cluster_count and seen > cluster_count + 1:
            return None                      # the list describes more than the attribute holds
    return runs


class _NtfsAttr:
    """One attribute of an MFT record, resident or not."""

    __slots__ = ("type", "name", "flags", "resident", "value", "runs",
                 "data_size", "alloc_size", "init_size", "comp_unit", "start_vcn")

    def __init__(self, type_, name, flags, resident):
        self.type, self.name, self.flags, self.resident = type_, name, flags, resident
        self.value = b""
        self.runs = []
        self.data_size = self.alloc_size = self.init_size = 0
        self.comp_unit = 0
        self.start_vcn = 0

    @property
    def compressed(self):
        return bool(self.flags & NTFS_ATTR_COMPRESSED) and self.comp_unit

    @property
    def encrypted(self):
        return bool(self.flags & NTFS_ATTR_ENCRYPTED)


class NtfsStreamRef(collections.namedtuple("NtfsStreamRef", "record name")):
    """The node of one alternate data stream: the MFT record that holds it and
    the stream's name.

    A walker's node is whatever its read_file(), entry() and stamps() take, and
    a caller that stages files hands the node back without looking inside it.
    Giving a stream a node of its own is what lets such a caller read one with
    no new call. It is a type of its own rather than a bare tuple so that a
    caller that must keep streams apart from files, because a pattern that
    matches a folder's files should not also match their streams, can tell
    which is which with isinstance().
    """

    __slots__ = ()


class NtfsDeletedFile:
    """One file whose MFT record is free but still describes it.

    ``recoverable`` says whether the content can still be read: a resident file
    always (its bytes are in the record), a non-resident one only while every
    cluster it used is still free. ``reason`` names why not, when it is False.
    """

    __slots__ = ("record", "name", "parent", "is_dir", "size", "resident",
                 "recoverable", "reason", "created", "modified", "accessed",
                 "has_attribute_list", "_data")

    def __init__(self, record, name, parent, is_dir, size, resident,
                 recoverable, reason, created, modified, accessed,
                 has_attribute_list, data):
        self.record, self.name, self.parent = record, name, parent
        self.is_dir, self.size = is_dir, size
        self.resident, self.recoverable, self.reason = resident, recoverable, reason
        self.created, self.modified, self.accessed = created, modified, accessed
        self.has_attribute_list = has_attribute_list
        self._data = data

    def __repr__(self):
        state = "recoverable" if self.recoverable else f"not recoverable ({self.reason})"
        return (f"NtfsDeletedFile(rec={self.record}, name={self.name!r}, "
                f"size={self.size}, {'resident' if self.resident else 'non-resident'}, "
                f"{state})")


class NtfsWalker:
    """List and read files from an NTFS volume, same interface as the walkers
    above. A node is the MFT record number, which is what a directory index
    stores and what makes two names for one file resolve to one record.

    What it reads: resident and non-resident $DATA, sparse runs, LZNT1
    compressed data, files the Windows Overlay Filter compressed with XPRESS
    (4K, 8K and 16K chunks), attributes that overflow into other records through
    $ATTRIBUTE_LIST, and directory indexes in both their resident ($INDEX_ROOT)
    and allocated ($INDEX_ALLOCATION) forms, with the sector fixups applied.

    What it does not read: an encrypted file's content, which needs a key the
    volume does not hold; a cloud provider's online-only placeholder, whose
    content is with the provider and not on the volume; and a file the overlay
    filter compressed with LZX. Those are listed with their recorded size and
    refuse to be read rather than yielding ciphertext, or the zeros of a hole,
    as though they were the file. allocation() says what the volume stores for
    a file beside the size it records.
    Only the unnamed $DATA stream is the file's content. A named stream, an
    alternate data stream, has a node of its own (NtfsStreamRef) that
    read_file(), entry() and stamps() take; streams() names a record's streams
    and listing(streams=True) lists them beside their files. Nothing lists a
    stream unless it is asked to.
    """

    root = NTFS_ROOT

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        boot = read_at(fh, base, 512)
        if len(boot) < 512 or boot[3:11] != NTFS_OEM:
            raise ValueError("not an NTFS boot sector")
        self.bps = struct.unpack_from("<H", boot, 11)[0]
        self.spc = boot[13]
        if not self.bps or not self.spc:
            raise ValueError("NTFS boot sector gives a zero sector or cluster size")
        self.cluster = self.bps * self.spc
        self.total_sectors = struct.unpack_from("<Q", boot, 40)[0]
        self.mft_lcn = struct.unpack_from("<Q", boot, 48)[0]
        self.mftmirr_lcn = struct.unpack_from("<Q", boot, 56)[0]
        self.rec_size = self._sized(struct.unpack_from("<b", boot, 64)[0])
        self.idx_size = self._sized(struct.unpack_from("<b", boot, 68)[0])
        self.serial = struct.unpack_from("<Q", boot, 72)[0]
        self.volume_size = self.total_sectors * self.bps
        self._records = {}                       # record number -> attributes
        self._alloc_bitmap = None                # $Bitmap bytes, read on first need
        self._mft_runs = None
        self._mft_runs = self._read_mft_runs()

    def _sized(self, raw):
        """A size field that is a cluster count when positive and a power of two
        byte count when negative, which is how a 1 KiB record fits a 4 KiB cluster."""
        return raw * self.cluster if raw > 0 else 1 << (-raw)

    # -- raw access --------------------------------------------------------
    def _read_runs(self, runs, want, start=0):
        """Bytes from a run list, sparse runs reading as the zeros they stand for."""
        out = bytearray()
        pos = 0
        for lcn, count in runs:
            span = count * self.cluster
            if pos + span <= start:
                pos += span
                continue
            skip = max(0, start - pos)
            take = min(span - skip, want - len(out))
            if lcn is None:
                out += b"\x00" * take
            else:
                out += read_at(self.fh, self.base + lcn * self.cluster + skip, take)
            pos += span
            if len(out) >= want:
                break
        return bytes(out[:want])

    def _read_mft_runs(self):
        """The $MFT's own data runs, read from record 0, which sits at a cluster
        the boot sector names. Every other record is then found through them."""
        off = self.base + self.mft_lcn * self.cluster
        raw = _ntfs_fixup(read_at(self.fh, off, self.rec_size), self.bps, NTFS_FILE)
        if raw is None:
            raise ValueError("the MFT's own record is unreadable")
        attrs = self._parse_attrs(raw, follow_list=False)
        for a in attrs:
            if a.type == NTFS_DATA and not a.name and not a.resident:
                return a.runs
        raise ValueError("the MFT record carries no non-resident data attribute")

    def _record(self, num):
        """The attributes of one MFT record, cached."""
        got = self._records.get(num)
        if got is None:
            off = num * self.rec_size
            raw = self._read_runs(self._mft_runs, self.rec_size, off) if self._mft_runs \
                else read_at(self.fh, self.base + self.mft_lcn * self.cluster + off,
                             self.rec_size)
            fixed = _ntfs_fixup(raw, self.bps, NTFS_FILE)
            got = self._parse_attrs(fixed, self_ref=num) if fixed else []
            self._records[num] = got
        return got

    def _parse_attrs(self, raw, follow_list=True, self_ref=None):
        """Every attribute in one record, plus those its $ATTRIBUTE_LIST points at.

        A record that runs out of room moves attributes into other records and
        leaves a list saying where they went. Following it is what makes a very
        fragmented file readable, since its run list is what overflowed.
        """
        if not raw or len(raw) < 0x30:
            return []
        seq = struct.unpack_from("<H", raw, 0x10)[0]
        first, flags = struct.unpack_from("<HH", raw, 0x14)
        used = struct.unpack_from("<I", raw, 0x18)[0]
        if not flags & NTFS_MFT_IN_USE:
            return []
        out, pos, limit = [], first, min(used or len(raw), len(raw))
        while pos + 4 <= limit:
            type_ = struct.unpack_from("<I", raw, pos)[0]
            if type_ == NTFS_END:
                break
            if pos + 16 > limit:
                break
            length = struct.unpack_from("<I", raw, pos + 4)[0]
            if length < 16 or pos + length > limit:
                break
            attr = self._parse_one(raw, pos, length)
            if attr:
                out.append(attr)
            pos += length
        marker = _NtfsAttr(-1, "", flags, True)          # carries the record flags
        marker.data_size = seq                           # and its sequence number
        out.append(marker)
        if follow_list:
            out.extend(self._follow_attribute_list(out, self_ref))
        return out

    def _parse_one(self, raw, pos, length):
        type_ = struct.unpack_from("<I", raw, pos)[0]
        nonres = raw[pos + 8]
        name_len = raw[pos + 9]
        name_off = struct.unpack_from("<H", raw, pos + 10)[0]
        flags = struct.unpack_from("<H", raw, pos + 12)[0]
        name = ""
        if name_len:
            end = pos + name_off + name_len * 2
            if end <= pos + length:
                name = raw[pos + name_off:end].decode("utf-16-le", "replace")
        attr = _NtfsAttr(type_, name, flags, not nonres)
        if not nonres:
            vlen, voff = struct.unpack_from("<IH", raw, pos + 16)
            if pos + voff + vlen > pos + length:
                return None
            attr.value = raw[pos + voff:pos + voff + vlen]
            attr.data_size = vlen
            return attr
        start_vcn, last_vcn = struct.unpack_from("<QQ", raw, pos + 16)
        run_off, comp = struct.unpack_from("<HH", raw, pos + 32)
        alloc, real, init = struct.unpack_from("<QQQ", raw, pos + 40)
        attr.start_vcn, attr.comp_unit = start_vcn, comp
        attr.alloc_size, attr.data_size, attr.init_size = alloc, real, init
        if run_off >= length:
            return None
        attr.runs = _ntfs_runs(raw[pos:pos + length], run_off,
                               last_vcn - start_vcn + 1) or []
        return attr

    def _follow_attribute_list(self, attrs, self_ref=None):
        """Attributes this record delegated to others, read from those records.

        The list names every attribute of the file, including the ones that
        stayed put, so it points back at this record too. Reading that one again
        would count its attributes twice: measured on a 333-run file, the data
        runs came out at 537 and the file read long and wrong.
        """
        extra, seen = [], set()
        for a in attrs:
            if a.type != NTFS_ATTRIBUTE_LIST:
                continue
            data = a.value if a.resident else self._read_runs(a.runs, a.data_size)
            pos = 0
            while pos + 26 <= len(data):
                rec_len = struct.unpack_from("<H", data, pos + 4)[0]
                if rec_len < 26 or pos + rec_len > len(data):
                    break
                ref = struct.unpack_from("<Q", data, pos + 16)[0] & 0xFFFFFFFFFFFF
                if ref and ref != self_ref and ref not in seen:
                    seen.add(ref)
                pos += rec_len
        for ref in seen:
            off = ref * self.rec_size
            raw = self._read_runs(self._mft_runs, self.rec_size, off)
            fixed = _ntfs_fixup(raw, self.bps, NTFS_FILE)
            if fixed:
                extra.extend(a for a in self._parse_attrs(fixed, follow_list=False)
                             if a.type not in (-1, NTFS_ATTRIBUTE_LIST))
        return extra

    # -- the walker surface ------------------------------------------------
    def _data_attr(self, num, name=""):
        """The named (or unnamed) $DATA attribute, with the runs of every piece
        joined: a file whose run list overflowed carries one $DATA per VCN span."""
        parts = [a for a in self._record(num)
                 if a.type == NTFS_DATA and a.name == name]
        if not parts:
            return None
        resident = [a for a in parts if a.resident]
        if resident:
            return resident[0]
        parts.sort(key=lambda a: a.start_vcn)
        head = parts[0]
        joined = _NtfsAttr(NTFS_DATA, name, head.flags, False)
        joined.comp_unit = head.comp_unit
        joined.alloc_size = max(a.alloc_size for a in parts)
        joined.data_size = max(a.data_size for a in parts)
        joined.init_size = max(a.init_size for a in parts)
        for a in parts:
            joined.runs.extend(a.runs)
        return joined

    def _index_allocation(self, num):
        """The $INDEX_ALLOCATION attribute of a directory's file name index ($I30),
        with the runs of every piece joined as _data_attr() joins a $DATA's, or
        None when the record has none: a directory whose index still fits in its
        $INDEX_ROOT, and every file."""
        parts = [a for a in self._record(num)
                 if a.type == NTFS_INDEX_ALLOCATION and a.name == "$I30" and not a.resident]
        if not parts:
            return None
        parts.sort(key=lambda a: a.start_vcn)
        head = parts[0]
        joined = _NtfsAttr(NTFS_INDEX_ALLOCATION, "$I30", head.flags, False)
        joined.comp_unit = head.comp_unit
        joined.alloc_size = max(a.alloc_size for a in parts)
        joined.data_size = max(a.data_size for a in parts)
        joined.init_size = max(a.init_size for a in parts)
        for a in parts:
            joined.runs.extend(a.runs)
        return joined

    def _cluster_in_use(self, lcn):
        """True when this cluster is marked allocated in $Bitmap. The bitmap is
        read once and kept: a deleted-file sweep asks about many clusters."""
        bits = self._alloc_bitmap
        if bits is None:
            attr = self._data_attr(NTFS_BITMAP)
            size = (len(attr.value) if attr.resident else attr.data_size) if attr else 0
            bits = b"".join(self.read_file(NTFS_BITMAP, size)) if size else b""
            self._alloc_bitmap = bits
        byte = lcn >> 3
        if byte >= len(bits):
            return True                              # off the end of the bitmap: treat as used
        return bool(bits[byte] & (1 << (lcn & 7)))

    def _parse_deleted(self, raw):
        """Attributes of one record, ignoring the in-use flag and NOT following
        its $ATTRIBUTE_LIST.

        The live parser stops at a record not in use; a deleted file is exactly
        such a record, so that guard is dropped here. The list is not followed
        on purpose: for a deleted record it points at other records that may
        since have been reused, so following it would splice a live file's
        attributes into this one.
        """
        if not raw or len(raw) < 0x30:
            return None
        first, flags = struct.unpack_from("<HH", raw, 0x14)
        used = struct.unpack_from("<I", raw, 0x18)[0]
        out, pos, limit = [], first, min(used or len(raw), len(raw))
        while pos + 16 <= limit:
            type_ = struct.unpack_from("<I", raw, pos)[0]
            if type_ == NTFS_END:
                break
            length = struct.unpack_from("<I", raw, pos + 4)[0]
            if length < 16 or pos + length > limit:
                break
            attr = self._parse_one(raw, pos, length)
            if attr:
                out.append(attr)
            pos += length
        return flags, out

    def _record_raw(self, num):
        off = num * self.rec_size
        raw = self._read_runs(self._mft_runs, self.rec_size, off) if self._mft_runs \
            else read_at(self.fh, self.base + self.mft_lcn * self.cluster + off,
                         self.rec_size)
        return _ntfs_fixup(raw, self.bps, NTFS_FILE)

    def deleted_files(self, *, include_system=False, min_size=0):
        """Yield the files whose MFT record is free but still names them.

        A deleted file whose record has not yet been handed to another file can
        be recovered from the record: its name, size, dates, and, when the data
        has not been overwritten, its content. This is the only route to a file
        whose data was **resident**, small enough to live inside the record and
        so never occupying a cluster a carver could find.

        Each result carries ``recoverable``: True when the bytes are still there
        (resident always; non-resident only while every cluster it used is still
        free), False when they have been reused, in which case the record is
        reported as evidence the file existed rather than its content offered.
        ``$ATTRIBUTE_LIST`` is not followed (see ``_parse_deleted``), so a file
        whose attributes overflowed its record is reported not recoverable rather
        than reconstructed from records that may now belong elsewhere.

        ``include_system`` keeps the ``$``-named metadata files; by default only
        ordinary files are yielded. ``min_size`` drops anything smaller.
        """
        data_attr = self._data_attr(0)              # $MFT's own $DATA
        if data_attr is None:
            return
        count = data_attr.data_size // self.rec_size
        for num in range(count):
            if num < 16 and not include_system:
                continue                            # 0-15 are the reserved metafiles
            raw = self._record_raw(num)
            if not raw or raw[:4] != NTFS_FILE:
                continue
            parsed = self._parse_deleted(raw)
            if parsed is None:
                continue
            flags, attrs = parsed
            if flags & NTFS_MFT_IN_USE:
                continue                            # a live file; the walk lists it
            names = []
            for a in attrs:
                if a.type == NTFS_FILE_NAME and a.resident and len(a.value) > 0x42:
                    nlen, ns = a.value[0x40], a.value[0x41]
                    parent = struct.unpack_from("<Q", a.value, 0)[0] & 0xFFFFFFFFFFFF
                    nm = a.value[0x42:0x42 + nlen * 2].decode("utf-16-le", "replace")
                    names.append((ns, nm, parent))
            if not names:
                continue                            # nothing names it
            names.sort(key=lambda n: n[0] == 2)     # prefer a long name over the 8.3 alias
            _ns, name, parent = names[0]
            if not include_system and name.startswith("$"):
                continue
            is_dir = bool(flags & NTFS_MFT_IS_DIR)
            has_list = any(a.type == NTFS_ATTRIBUTE_LIST for a in attrs)
            created, modified, accessed = _ntfs_std_times(attrs)
            data = next((a for a in attrs if a.type == NTFS_DATA and a.name == ""), None)
            if is_dir or data is None:
                yield NtfsDeletedFile(num, name, parent, is_dir, 0, True, False,
                                      "directory" if is_dir else "no data attribute",
                                      created, modified, accessed, has_list, None)
                continue
            size = len(data.value) if data.resident else data.data_size
            if size < min_size:
                continue
            if data.resident:
                yield NtfsDeletedFile(num, name, parent, is_dir, size, True, True, "",
                                      created, modified, accessed, has_list, data)
                continue
            reason, ok = "", True
            if data.encrypted:
                reason, ok = "encrypted", False
            elif has_list:
                reason, ok = "attributes overflowed the record", False
            else:
                for lcn, run in data.runs:
                    if lcn is None:
                        continue                    # a sparse run holds no data to lose
                    if any(self._cluster_in_use(lcn + i) for i in range(run)):
                        reason, ok = "clusters reused by a later file", False
                        break
            yield NtfsDeletedFile(num, name, parent, is_dir, size, False, ok, reason,
                                  created, modified, accessed, has_list, data)

    def read_deleted(self, entry, size=None):
        """Yield the content of a recoverable deleted file. Refuses one whose
        clusters have been reused, so overwritten data is never presented as the
        file. Reading is otherwise the same as for a live file."""
        if not entry.recoverable or entry._data is None:
            raise NtfsUnreadable(
                f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        data = entry._data
        want = entry.size if size is None else min(size, entry.size)
        if data.resident:
            yield data.value[:want]
            return
        yield from self._read_nonresident(data, want)

    def volume_label(self):
        """The volume label, from the $VOLUME_NAME attribute of record 3, or None
        when the record cannot be read. An empty string means the volume has none."""
        for a in self._record(3):
            if a.type == 0x60 and a.resident:
                return a.value.decode("utf-16-le", "replace")
        return "" if self._record(3) else None

    def _flags(self, num):
        for a in self._record(num):
            if a.type == -1:
                return a.flags
        return 0

    def _seq(self, num):
        """This record's sequence number, or None if the record is not in use.

        NTFS bumps it every time a record is freed and handed out again, so it
        is what tells a live directory entry from one naming a record that has
        since become something else."""
        for a in self._record(num):
            if a.type == -1:
                return a.data_size
        return None

    def inode(self, num):
        return num

    def entry(self, num):
        if isinstance(num, NtfsStreamRef):
            # A stream has no dates of its own: NTFS keeps them per record, so
            # a stream carries its file's, as a listing of it shows them.
            got = self._stream(num)
            if got is None:
                return None
            return (0o100644, got[2], _ntfs_std_times(self._record(num.record))[1])
        attrs = self._record(num)
        if not attrs:
            return None
        is_dir = bool(self._flags(num) & NTFS_MFT_IS_DIR)
        mtime = _ntfs_std_times(attrs)[1]
        if is_dir:
            return (S_IFDIR | 0o755, 0, mtime)
        data = self._data_attr(num)
        size = 0 if data is None else (len(data.value) if data.resident else data.data_size)
        return (0o100644, size, mtime)

    def stamps(self, num):
        """The instants a live file's $STANDARD_INFORMATION holds, as
        (created, modified, accessed) in Unix seconds, 0 where unset.

        ``entry`` returns only the modified time, which is what a listing needs.
        A caller carrying a file's dates into a record wants all three, and they
        are instants rather than readings: FILETIME counts from a UTC epoch, so
        unlike a FAT or exFAT stamp these can be placed on a timeline. The record
        is cached, so asking after ``entry`` reads nothing more from the image.
        A stream's are its file's, which is all NTFS records.
        """
        if isinstance(num, NtfsStreamRef):
            num = num.record
        return _ntfs_std_times(self._record(num))

    # -- the whole volume in one pass --------------------------------------

    # The record header's base file reference (low 48 bits of the eight bytes at
    # 0x20). Non-zero means the record holds overflow attributes for the record
    # it names and is not a file of its own.
    _BASE_REF = 0x20

    def attributes(self, num):
        """The file attribute bits $STANDARD_INFORMATION holds for this record
        (FILE_ATTRIBUTE_* in Microsoft's naming), 0 when it has none."""
        rec = num.record if isinstance(num, NtfsStreamRef) else num
        for a in self._record(rec):
            if a.type == NTFS_STANDARD_INFORMATION and a.resident and len(a.value) >= 0x24:
                return struct.unpack_from("<I", a.value, 0x20)[0]
        return 0

    def reparse(self, num):
        """(tag, data) of this record's reparse point, or None when it has none."""
        rec = num.record if isinstance(num, NtfsStreamRef) else num
        for a in self._record(rec):
            if a.type != NTFS_REPARSE_POINT:
                continue
            raw = a.value if a.resident else b"".join(
                self._read_nonresident(a, min(a.data_size, 1 << 16)))
            if len(raw) < 8:
                return None
            tag, length = struct.unpack_from("<IH", raw, 0)
            return tag, raw[8:8 + length]
        return None

    def _wof(self, num):
        """(provider, algorithm, the WofCompressedData attribute) for a file the
        Windows Overlay Filter backs, or None for any other file."""
        got = self.reparse(num)
        if got is None or got[0] != IO_REPARSE_TAG_WOF or len(got[1]) < 8:
            return None
        provider = struct.unpack_from("<I", got[1], 4)[0]
        algorithm = struct.unpack_from("<I", got[1], 12)[0] if len(got[1]) >= 16 else None
        return provider, algorithm, self._data_attr(num, WOF_STREAM)

    @staticmethod
    def _stored(data, cluster):
        """The bytes of an attribute the volume holds: its length when it is
        resident, the clusters of its stored runs otherwise."""
        if data is None:
            return 0
        if data.resident:
            return len(data.value)
        return sum(count for lcn, count in data.runs if lcn is not None) * cluster

    def allocation(self, num):
        """What the volume stores for a file, beside the size it records.

        A file's recorded size and the bytes behind it are different numbers
        for a sparse file, a compressed one and a cloud provider's placeholder,
        and read_file() hands back the recorded size in every case it reads. A
        caller that copies files out needs both to know what it is about to
        write, and which files hold no content at all.

        Returns a dict:

        ``size``         the bytes read_file() returns, as entry() gives them
        ``stored``       the bytes the volume holds for the content: the stored
                         clusters of the unnamed $DATA, the length of a resident
                         one, or for an overlay-compressed file the stored
                         clusters of its WofCompressedData stream. Counted in
                         whole clusters, which is what Windows reports as size
                         on disk for a sparse or compressed file.
        ``sparse``       the stream is flagged sparse or its run list has a hole
        ``compression``  "", "lznt1", or "wof-" and the algorithm's name
        ``reparse_tag``  the reparse point's tag, or None
        ``attributes``   the file attribute bits of $STANDARD_INFORMATION
        ``placeholder``  True for a cloud provider's file whose content is not
                         all on the volume: a cloud reparse tag together with
                         FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS, or with a
                         recorded size and nothing stored. read_file() refuses
                         these. A cloud file that is all there (a hydrated
                         placeholder) keeps its tag and is not one.

        Measured against files Windows 11 wrote (the committed fixture): the
        stored figure equals Windows's own size on disk for every sparse, NTFS
        compressed and overlay-compressed file whose content lies in clusters,
        and the three online-only placeholders are the three Windows itself
        would not read. On a public Windows 11 acquisition the one OneDrive
        file kept online-only reads the same way: 1,151,898 bytes recorded,
        none stored. A file a provider holds in part, some ranges present and
        some not, is covered by the attribute test and is not exercised: no
        image holding one was found, and Windows would not make one without a
        provider running.

        For a stream (NtfsStreamRef) the size and stored figures are the
        stream's own and the rest describe its file.
        """
        attrs = self.attributes(num)
        got = self.reparse(num)
        tag = got[0] if got else None
        if isinstance(num, NtfsStreamRef):
            data = self._data_attr(num.record, num.name)
            found = self._stream(num)
            return {"size": found[2] if found else 0,
                    "stored": self._stored(data, self.cluster),
                    "sparse": bool(data is not None and not data.resident and (
                        data.flags & NTFS_ATTR_SPARSE
                        or any(lcn is None for lcn, _c in data.runs))),
                    "compression": "lznt1" if data is not None and not data.resident
                                   and data.compressed else "",
                    "reparse_tag": tag, "attributes": attrs, "placeholder": False}
        data = self._data_attr(num)
        size = 0 if data is None else (len(data.value) if data.resident else data.data_size)
        stored = self._stored(data, self.cluster)
        sparse = bool(data is not None and not data.resident and (
            data.flags & NTFS_ATTR_SPARSE or any(lcn is None for lcn, _c in data.runs)))
        compression = ""
        if data is not None and not data.resident and data.compressed:
            compression = "lznt1"
        wof = self._wof(num)
        if wof is not None:
            _provider, algorithm, stream = wof
            compression = "wof-" + WOF_ALGORITHMS.get(algorithm, (f"algorithm-{algorithm}",))[0]
            stored = self._stored(stream, self.cluster)
        cloud = tag is not None and tag & IO_REPARSE_TAG_CLOUD_MASK == IO_REPARSE_TAG_CLOUD
        placeholder = bool(cloud and (attrs & NTFS_FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS
                                      or (size and not stored)))
        return {"size": size, "stored": stored, "sparse": sparse, "compression": compression,
                "reparse_tag": tag, "attributes": attrs, "placeholder": placeholder}

    def listing(self, streams=False):
        """Every entry on the volume, built from $MFT in record order.

        With ``streams``, each entry's alternate data streams follow it as
        entries of their own, named "path:stream" as Windows names them, with an
        NtfsStreamRef as the node, a regular file's mode, the size streams()
        gives and the file's modified time. A stream on the root directory is
        named ":stream". Off by default, so a caller that asked for the files
        of a volume is never handed their streams as though they were files.

        A tree walk learns a directory's children by reading its index, so it
        reads an $INDEX_ALLOCATION block per directory and reaches MFT records
        in directory order. Every record already carries its own $FILE_NAME,
        which names it and names its parent, so the same listing can be built
        from one sequential pass over $MFT with no index read at all.

        Measured on a 7.4 GB Windows acquisition holding 156,894 entries: the
        tree walk plus stamps() takes 3.54 s and this takes 1.07 s, and the
        paths, kinds, sizes and all three dates are identical. Reading the
        whole 130 MB $MFT is 0.13 s of that; the parse is the cost, not the
        read.

        Two things a scan of $MFT has to get right, and both fail quietly:

        An **extension record** carries the FILE signature, is flagged in use,
        and holds copies of its base record's $FILE_NAME. Counting it names
        the same path a second time from a record with no $STANDARD_INFORMATION
        behind it, so the dates come back empty. On that acquisition 4,665 of
        126,976 records are extension records and they would have added 8,435
        such rows, every one disagreeing with the real record on modified time.
        They are skipped here on the base reference in the record header.

        A **$FILE_NAME's parent reference carries the parent's sequence
        number**, exactly as a directory index entry carries the child's. A
        parent record that has since been freed and handed to another file
        carries a different one, and resolving through it would file the entry
        under whatever that record became. Those names are dropped. That guard
        is the one thing here no image in the test set exercises: a stale
        parent reference was looked for and not found on any of them, on
        249,943 names of a 7.4 GB Windows acquisition among others. It is kept
        because the same staleness on the child reference is real and measured
        (see _index_entries, where it put an update installer under a browser
        cache folder on one volume), and it is reported here as code present
        and unexercised rather than as something proven.

        Yields (path, record, mode, size, mtime, None) for every entry,
        directories included. A record whose parent chain does not lead to the
        root cannot be given a path and is left out, which is what a tree walk
        does with it too. NTFS records instants, so there is never a stored
        reading and the last element is always None.

        **This asks the volume a different question from a tree walk, and on a
        volume whose index and records disagree it gets a different answer.**
        A tree walk reads what each directory says is in it; this reads what
        each record says about itself. They agree exactly on a consistent
        volume: 156,894 of 156,894 entries on a 7.4 GB Windows acquisition and
        every entry of every committed fixture, on paths, kinds, sizes and all
        three dates.

        On a 49 GB Windows 11 acquisition they disagree on 4 of 313,652, and
        neither reader is wrong. Three are files whose record names a parent
        whose sequence number matches, while that parent's index holds only a
        stale entry for the name, which _index_entries rightly refuses; a tree
        walk reports nothing at those paths and this reports the file. In the
        fourth the index and the record disagree on the name: the index files
        record 3057 under HxCommAlwaysOnLog_Old.etl and the record's own
        $FILE_NAME says HxCommAlwaysOnLog.etl. A Windows 10 acquisition shows
        the first shape three times, all files in a Chrome profile. What put
        these indexes and records out of step is not established: the volume's
        own dirty flag is clear on both. Reconciling them would mean reading
        the indexes, which is the work this exists to avoid; the difference is
        reported here instead so a caller knows which question the answer
        belongs to.
        """
        mft = self._data_attr(0)
        if mft is None or not mft.runs:
            return
        total = mft.data_size // self.rec_size
        if not total:
            return

        # One sequential pass. Each record is parsed once and kept in the cache
        # entry(), stamps() and _seq() already read, so nothing below this line
        # goes back to the image for it.
        names = {}                                  # record -> [(parent, name)]
        is_dir = {}
        per_read = max(1, (1 << 20) // self.rec_size)
        for first in range(0, total, per_read):
            count = min(per_read, total - first)
            raw = self._read_runs(mft.runs, count * self.rec_size,
                                  first * self.rec_size)
            for i in range(count):
                num = first + i
                rec = raw[i * self.rec_size:(i + 1) * self.rec_size]
                if len(rec) < 0x30 or rec[:4] != NTFS_FILE:
                    continue
                flags = struct.unpack_from("<H", rec, 22)[0]
                if not flags & NTFS_MFT_IN_USE:
                    # _parse_attrs refuses a freed record too, so this is what
                    # keeps the fixup and the parse off every free record
                    # rather than what keeps a deleted file out of the listing.
                    # deleted_files() is where a freed record is read on purpose.
                    continue
                if struct.unpack_from("<Q", rec, self._BASE_REF)[0] & 0xFFFFFFFFFFFF:
                    continue                        # an extension record, not a file
                fixed = _ntfs_fixup(rec, self.bps, NTFS_FILE)
                if not fixed:
                    continue
                attrs = self._parse_attrs(fixed, self_ref=num)
                if not attrs:
                    continue
                self._records[num] = attrs
                is_dir[num] = bool(flags & NTFS_MFT_IS_DIR)
                here = _ntfs_file_names(attrs)
                if here:
                    names[num] = here

        # Second pass: turn each parent reference into a path. Only a directory
        # can be one, and the root is the one record that has no path of its own.
        # A directory has one name, so its own parent reference is the link in
        # the chain. A file can have several, which is what a hard link is.
        up_from = {num: here[0] for num, here in names.items()
                   if is_dir.get(num) and num != NTFS_ROOT}
        resolved = {NTFS_ROOT: ""}

        def path_of(ref, depth=0):
            """The path of the directory this reference names, or None when the
            chain does not reach the root or the record it names was reused."""
            num = ref & 0xFFFFFFFFFFFF
            want_seq = ref >> 48
            if want_seq:
                got_seq = self._seq(num)
                if got_seq is not None and want_seq != got_seq:
                    return None
            if num in resolved:
                return resolved[num]
            if depth > 64 or num not in up_from:
                return None
            resolved[num] = None                    # breaks a cycle in the chain
            parent_ref, name = up_from[num]
            above = path_of(parent_ref, depth + 1)
            got = None if above is None else (f"{above}/{name}" if above else name)
            resolved[num] = got
            return got

        if streams:
            # The root is the one directory with no name of its own, so it is
            # never an entry below and its streams are given here.
            root_mtime = _ntfs_std_times(self._record(NTFS_ROOT))[1]
            for sname, sref, ssize in self.streams(NTFS_ROOT):
                yield (f":{sname}", sref, 0o100644, ssize, root_mtime, None)

        for num, here in names.items():
            if num == NTFS_ROOT:
                continue
            ent = self.entry(num)
            if not ent:
                continue
            mode, size, mtime = ent
            extra = self.streams(num) if streams else ()
            for ref, name in here:
                base = path_of(ref)
                if base is None:
                    continue                        # no path to the root
                path = f"{base}/{name}" if base else name
                yield (path, num, mode, size, mtime, None)
                for sname, sref, ssize in extra:
                    yield (f"{path}:{sname}", sref, 0o100644, ssize, mtime, None)

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        NTFS records one bit per cluster in $Bitmap, the unnamed $DATA of MFT
        record 6, set when the cluster is in use. What is left is where deleted
        content survives until something overwrites it, and it is the only part
        of a volume a carver can tell apart from a live file: a signature found
        inside an allocated run belongs to a file the tree already names.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.

        Whole bytes of the bitmap are tested before their bits are, because a
        volume of this size has tens of millions of clusters and almost all of
        them sit in runs: on a 237.6 GiB volume that is 62,289,344 clusters, and
        looking at each one individually is not worth doing.
        """
        attr = self._data_attr(NTFS_BITMAP)
        if attr is None:
            return []
        size = len(attr.value) if attr.resident else attr.data_size
        if not size:
            return []
        bits = b"".join(self.read_file(NTFS_BITMAP, size))
        clusters = (self.total_sectors * self.bps) // self.cluster
        total = min(len(bits) * 8, clusters or len(bits) * 8)

        runs, run_start = [], None
        pos = 0
        while pos < total:
            byte = bits[pos >> 3]
            if not (pos & 7) and pos + 8 <= total and byte in (0x00, 0xFF):
                if byte == 0x00:                     # eight free clusters
                    if run_start is None:
                        run_start = pos
                else:                                # eight used ones
                    if run_start is not None:
                        runs.append((run_start, pos - run_start))
                        run_start = None
                pos += 8
                continue
            if byte & (1 << (pos & 7)):
                if run_start is not None:
                    runs.append((run_start, pos - run_start))
                    run_start = None
            elif run_start is None:
                run_start = pos
            pos += 1
        if run_start is not None:
            runs.append((run_start, total - run_start))

        out = []
        for first, count in runs:
            length = count * self.cluster
            if length >= min_bytes:
                out.append((self.base + first * self.cluster, length))
        return out

    def named_streams(self, num):
        """[(name, size)] for every alternate data stream on this record. A named
        stream is content the file's own size does not account for, so it is worth
        reporting; it is not listed as a file, because it has no name of its own.
        The size is the recorded one, holes included: this is what --list prints
        beside a file. streams() is what reads them.

        A stream whose run list outgrew its record is in several attributes,
        one per record, and is named once: $UsnJrnl:$J on a volume of any age
        is, and before 1.37 --list printed it once per record, the rest at 0 B."""
        out, seen = [], set()
        for a in self._record(num):
            if a.type == NTFS_DATA and a.name and a.name not in seen:
                seen.add(a.name)
                data = self._data_attr(num, a.name)
                out.append((a.name, len(data.value) if data.resident else data.data_size))
        return out

    def streams(self, num):
        """[(name, NtfsStreamRef, size)] for the alternate data streams of this
        record that store anything, in the order the record holds them. The
        NtfsStreamRef is the node read_file(), entry() and stamps() take.

        ``size`` is what read_file() returns for the stream, and it is not
        always the recorded size, because of two rules about holes:

        **A hole at the front of a stream is not read.** The stream is read
        from its first stored cluster. $Extend/$UsnJrnl:$J is why: Windows
        frees the front of the change journal as it grows and leaves a hole
        where it was, so the stream's recorded size runs to gigabytes and all
        but its last few megabytes read as zeros. Handing those zeros to a
        caller that copies the stream to disk writes gigabytes for nothing, and
        a USN journal parser loses nothing without them, because every record
        carries its own offset in the stream as its USN. front_hole() gives the
        bytes skipped, so the true offset of anything read is never lost.

        **A stream that is all hole is not listed.** $BadClus:$Bad is why: its
        recorded size is the whole volume and a healthy disk stores none of it.
        A stream of no bytes is listed, since it is not a hole but a stream that
        was created empty, and its being there can be the evidence.

        A hole after the first stored cluster is content and reads as zeros, as
        it does in a file.
        """
        out, seen = [], set()
        for a in self._record(num):
            if a.type != NTFS_DATA or not a.name or a.name in seen:
                continue
            seen.add(a.name)                    # a stream split over records is one stream
            ref = NtfsStreamRef(num, a.name)
            got = self._stream(ref)
            if got is not None:
                out.append((a.name, ref, got[2]))
        return out

    def directory_index(self, num):
        """[("$I30", NtfsStreamRef, size)] for a directory whose file name index
        has grown into an $INDEX_ALLOCATION attribute, and [] for any other
        record. The NtfsStreamRef is the node read_file(), entry() and stamps()
        take, as for a stream, and ``size`` is what read_file() returns.

        The index is not an alternate data stream and streams() does not list
        it: a caller asks for it here. What is read is the attribute as the
        volume stores it, one index block after another (``idx_size`` bytes
        each, starting "INDX"), with the update sequence array of each block
        not applied. That is the form in which the space past a block's last
        entry still holds entries NTFS has since removed, which is what a caller
        reads this for; listdir() is what lists the directory.

        A record that holds a $DATA stream named $I30 gives [], since that name
        then reads as the stream."""
        if isinstance(num, NtfsStreamRef) or self._data_attr(num, "$I30") is not None:
            return []
        ref = NtfsStreamRef(num, "$I30")
        got = self._stream(ref)
        return [] if got is None else [("$I30", ref, got[2])]

    def front_hole(self, ref):
        """The bytes of hole read_file() skips at the front of this stream, 0
        when it starts with stored data, None when there is no such stream or
        it stores nothing. Add it to an offset into what read_file() returned
        to have the offset into the stream as NTFS records it."""
        got = self._stream(ref)
        return None if got is None else got[1]

    def _stream(self, ref):
        """(attribute, bytes of hole at the front, bytes read_file() returns)
        for one named stream, or None when the record holds no stream of that
        name or the stream stores nothing. See streams() for the rules."""
        if not ref.name:
            return None                         # the unnamed stream is the file itself
        data = self._data_attr(ref.record, ref.name)
        if data is None and ref.name == "$I30":
            data = self._index_allocation(ref.record)      # see directory_index()
        if data is None:
            return None
        if data.resident:
            return data, 0, len(data.value)
        if not data.data_size:
            return data, 0, 0
        vcn = 0
        for lcn, count in data.runs:
            if lcn is not None:
                break
            vcn += count
        else:
            return None                         # every cluster of it is a hole
        skip = vcn * self.cluster
        if skip >= data.data_size:
            return None
        return data, skip, data.data_size - skip

    def listdir(self, num):
        """(name, record) for every entry of a directory index.

        The index lives in $INDEX_ROOT while it is small and moves into
        $INDEX_ALLOCATION blocks when it grows; both hold the same entry shape,
        so both are walked with one reader.
        """
        out, seen = [], set()
        root = alloc = None
        for a in self._record(num):
            if a.type == NTFS_INDEX_ROOT and a.name == "$I30":
                root = a
            elif a.type == NTFS_INDEX_ALLOCATION and a.name == "$I30":
                alloc = a
        if root is None:
            return out
        # $INDEX_ROOT: a small header, then the index header at 0x10
        if len(root.value) >= 0x20:
            self._index_entries(root.value, 0x10, out, seen)
        if alloc is not None and alloc.runs:
            total = alloc.data_size or alloc.alloc_size
            step = self.idx_size
            for off in range(0, total, step):
                block = _ntfs_fixup(self._read_runs(alloc.runs, step, off),
                                    self.bps, NTFS_INDX)
                if block and len(block) >= 0x28:
                    self._index_entries(block, 0x18, out, seen)
        return out

    def _index_entries(self, buf, header_off, out, seen):
        """Append the entries of one index header. Entry offsets are relative to
        the header, not to the record, which is why the caller passes its offset."""
        if header_off + 16 > len(buf):
            return
        first, total = struct.unpack_from("<II", buf, header_off)
        pos = header_off + first
        end = min(header_off + total, len(buf))
        while pos + 0x52 <= end:
            ref, elen, klen, eflags = struct.unpack_from("<QHHH", buf, pos)
            if elen < 0x10 or pos + elen > end:
                break
            if eflags & 0x02:                       # the last entry holds no name
                break
            rec = ref & 0xFFFFFFFFFFFF
            want_seq = ref >> 48
            if klen >= 0x42:
                name_len = buf[pos + 0x50]
                namespace = buf[pos + 0x51]
                nstart = pos + 0x52
                nend = nstart + name_len * 2
                if nend <= pos + elen:
                    name = buf[nstart:nend].decode("utf-16-le", "replace")
                    # Namespace 2 is the 8.3 name of a file that also has a long
                    # one, indexed beside it. Reporting both would list every such
                    # file twice under two names. The root's index also carries an
                    # entry for the root itself, which is a loop, not a child.
                    # The top 16 bits of the reference are the generation the
                    # entry was written for. A record that has since been freed
                    # and reused carries a different one, and following it
                    # attaches whatever the record became to this name: on one
                    # Windows volume that put a 501 KB update installer, and the
                    # directory holding it, under a browser cache folder.
                    # A zero means the writer asked for no check.
                    got_seq = self._seq(rec)
                    stale = (want_seq and got_seq is not None and want_seq != got_seq)
                    if (namespace != 2 and name not in (".", "..") and not stale
                            and (rec, name) not in seen):
                        seen.add((rec, name))
                        out.append((name, rec))
            pos += elen

    def read_file(self, num, size):
        if isinstance(num, NtfsStreamRef):
            yield from self._read_stream(num, size)
            return
        data = self._data_attr(num)
        if data is None:
            return
        if data.resident:
            yield data.value[:size] if size else data.value
            return
        if data.encrypted:
            raise NtfsUnreadable("the file is encrypted and the volume holds no key")
        want = size if size is not None else data.data_size
        want = min(want, data.data_size) if data.data_size else want
        # Two kinds of file record a size over an unnamed stream that is all
        # hole, and reading the hole would hand back zeros as though they were
        # the file. A cloud provider's placeholder has no content here at all;
        # Windows itself answers a read of one with "the cloud file provider is
        # not running". An overlay-compressed file has its content in another
        # stream, and is read from there.
        got = self.reparse(num)
        if got is not None:
            tag = got[0]
            if tag & IO_REPARSE_TAG_CLOUD_MASK == IO_REPARSE_TAG_CLOUD:
                if (self.attributes(num) & NTFS_FILE_ATTRIBUTE_RECALL_ON_DATA_ACCESS
                        or (data.data_size and not self._stored(data, self.cluster))):
                    raise NtfsUnreadable(
                        f"the file is a cloud provider's online-only placeholder (reparse "
                        f"tag 0x{tag:08X}): it records {data.data_size:,} bytes and the "
                        f"volume stores {self._stored(data, self.cluster):,} of them")
            elif tag == IO_REPARSE_TAG_WOF:
                yield from self._read_wof(num, data.data_size, want)
                return
        yield from self._read_nonresident(data, want)

    def _read_wof(self, num, size, want):
        """The content of a file the Windows Overlay Filter compressed.

        The WofCompressedData stream is a table of 32-bit offsets, one for each
        chunk but the first, giving where the chunk starts counted from the end
        of the table, and then the chunks. A chunk covers a fixed span of the
        file, the last one what is left. One stored at its plain length was
        left uncompressed; any other is one LZ77+Huffman block ([MS-XCA]).

        Refused rather than guessed at: LZX, which is not decoded here; a file
        of 4 GiB or more, whose table this reader has not seen; WIMBoot, whose
        content is in a WIM file and not on this record; and a stream whose
        table or chunks do not fit it.
        """
        provider, algorithm, stream = self._wof(num)
        if provider != WOF_PROVIDER_FILE:
            raise NtfsUnreadable(f"the file is backed by overlay provider {provider} (WIMBoot "
                                 "keeps the content in a WIM file), which is not read here")
        name, chunk = WOF_ALGORITHMS.get(algorithm, (None, 0))
        if name is None:
            raise NtfsUnreadable(f"the file is overlay-compressed with algorithm {algorithm}, "
                                 "which is not one this reader knows")
        if name == "lzx":
            raise NtfsUnreadable("the file is overlay-compressed with LZX (compact /exe:lzx), "
                                 "which is not decoded here")
        if stream is None:
            raise NtfsUnreadable("the file is overlay-compressed and has no "
                                 f"{WOF_STREAM} stream")
        if stream.encrypted:
            raise NtfsUnreadable("the file's compressed stream is encrypted")
        if size >= 1 << 32:
            raise NtfsUnreadable("the file is overlay-compressed and 4 GiB or larger, "
                                 "which is not read here")
        total = len(stream.value) if stream.resident else stream.data_size

        def at(offset, length):
            if stream.resident:
                return stream.value[offset:offset + length]
            return b"".join(self._read_nonresident(stream, length, offset))

        chunks = -(-size // chunk)
        table_len = max(chunks - 1, 0) * 4
        if table_len > total:
            raise NtfsUnreadable("the compressed stream is shorter than its chunk table")
        ends = list(struct.unpack(f"<{chunks - 1}I", at(0, table_len))) if chunks > 1 else []
        ends.append(total - table_len)
        produced, start, held, held_at = 0, 0, b"", 0
        for index, end in enumerate(ends):
            if produced >= want:
                break
            plain = min(chunk, size - index * chunk)
            if end < start or end > total - table_len:
                raise NtfsUnreadable("the compressed stream's chunk table is out of order")
            if start < held_at or end > held_at + len(held):
                # read ahead about a megabyte of chunks at a time
                held_at = start
                held = at(table_len + start, min(max(end - start, 1 << 20),
                                                 total - table_len - start))
            piece = held[start - held_at:end - held_at]
            if len(piece) == plain:
                out = piece
            else:
                try:
                    out = _xpress_huffman_decompress(piece, plain)
                except (ValueError, IndexError, struct.error) as exc:
                    raise NtfsUnreadable(f"chunk {index} of the compressed stream does not "
                                         f"decode: {exc}") from None
            out = out[:want - produced]
            yield out
            produced += len(out)
            start = end

    def _read_stream(self, ref, size):
        """An alternate data stream's bytes, from its first stored cluster:
        the rules are in streams(). Nothing at all for a stream that stores
        nothing, which streams() does not list."""
        got = self._stream(ref)
        if got is None:
            return
        data, skip, total = got
        want = total if size is None else min(size, total)
        if data.resident:
            yield data.value[:want]
            return
        if data.encrypted:
            raise NtfsUnreadable(
                f"the stream {ref.name!r} is encrypted and the volume holds no key")
        yield from self._read_nonresident(data, want, skip)

    def _read_nonresident(self, data, want, start=0):
        """Yield ``want`` bytes of a non-resident attribute from byte ``start``.

        Everything past the initialized size reads as zero even though the
        clusters are allocated and still hold whatever was there before. A
        database that preallocates its file is the common case: two on a
        Windows volume differed from The Sleuth Kit's reading by exactly that
        tail until it was honoured. The stale bytes are slack, not content.
        """
        if data.compressed:
            yield from self._read_compressed(data, want, start)
            return
        end = start + want
        real = max(start, min(end, data.init_size)) if data.init_size else start
        pos = start
        while pos < real:
            chunk = self._read_runs(data.runs, min(1 << 20, real - pos), pos)
            if not chunk:
                break
            yield chunk
            pos += len(chunk)
        while pos < end:
            take = min(1 << 20, end - pos)
            yield b"\x00" * take
            pos += take

    def _read_compressed(self, data, want, start=0):
        """A compressed $DATA is stored in units of 2**comp_unit clusters. A unit
        whose runs are shorter than the unit is compressed and inflated with
        LZNT1; one stored at full length was left uncompressed. ``start`` is a
        byte offset; reading begins at the unit that holds it. A unit whose
        stored bytes are not an LZNT1 stream raises NtfsUnreadable."""
        unit = (1 << data.comp_unit) * self.cluster
        vcn_per_unit = 1 << data.comp_unit
        produced = 0
        # index the run list by VCN so a unit's clusters can be found
        table, vcn = [], 0
        for lcn, count in data.runs:
            table.append((vcn, lcn, count))
            vcn += count
        total_vcn = vcn
        drop = start % unit
        for first in range((start // unit) * vcn_per_unit, total_vcn, vcn_per_unit):
            if produced >= want:
                break
            raw = self._unit_bytes(table, first, vcn_per_unit)
            if raw is None:                       # wholly sparse unit
                out = b"\x00" * unit
            elif len(raw) >= unit:
                out = raw[:unit]
            else:
                try:
                    out = _lznt1_decompress(raw, unit)
                except ValueError as exc:
                    raise NtfsUnreadable(
                        f"the compression unit at cluster {first} of the file does "
                        f"not decode: {exc}") from None
            if drop:
                out, drop = out[drop:], 0
            take = min(len(out), want - produced)
            yield out[:take]
            produced += take

    def _unit_bytes(self, table, start_vcn, count):
        """The stored bytes of one compression unit, or None if it is all sparse.
        A compressed unit occupies fewer clusters than the unit, and the rest of
        its VCN span is a sparse run, so the stored length is what says so."""
        out, any_real = bytearray(), False
        for vcn, lcn, span in table:
            lo, hi = max(vcn, start_vcn), min(vcn + span, start_vcn + count)
            if lo >= hi:
                continue
            if lcn is None:
                continue
            any_real = True
            out += read_at(self.fh, self.base + (lcn + (lo - vcn)) * self.cluster,
                           (hi - lo) * self.cluster)
        return bytes(out) if any_real else None


def _xpress_huffman_decompress(data, out_size):
    """Inflate one LZ77+Huffman block, the XPRESS form the Windows Overlay
    Filter stores each chunk of a compressed file in.

    The block begins with 256 bytes giving a 4-bit code length for each of 512
    symbols, low nibble first ([MS-XCA] 2.1: "The first 256 bytes indicate the
    bit length of each of the 512 Huffman symbols"). Codes are canonical:
    shorter first, and by symbol within a length. Symbols below 256 are
    literals. Any other is a match: its low four bits are the length less 3,
    where 15 means a byte follows holding more and 255 there means a 16-bit
    length follows instead, and its next four bits say how many bits of
    distance come after it, below an implied leading one.

    Bits are taken from 16-bit little-endian words, most significant bit
    first, and the order of the reads is part of the format: a word is taken in
    whenever fewer than 16 bits are held, and that happens after a symbol and
    before its extra length bytes, then again after its distance bits.

    Checked against files Windows wrote in all three chunk sizes and against
    Windows's own reading of them (see the self-test), not only against the
    description. Raises ValueError for a block that does not decode.
    """
    if len(data) < 256:
        raise ValueError("the block is shorter than its table of code lengths")
    by_length = [[] for _ in range(16)]
    for index in range(256):
        byte = data[index]
        by_length[byte & 15].append(2 * index)
        by_length[byte >> 4].append(2 * index + 1)
    # every 15-bit window of the stream names its symbol and the code's length
    table = [0] * 32768
    filled = 0
    for length in range(1, 16):
        span = 1 << (15 - length)
        for symbol in sorted(by_length[length]):
            if filled + span > 32768:
                raise ValueError("the code lengths describe more codes than fit")
            table[filled:filled + span] = [symbol * 16 + length] * span
            filled += span
    end = len(data)
    pos = 256

    def word():
        nonlocal pos
        got = data[pos] | (data[pos + 1] << 8) if pos + 2 <= end else 0
        pos += 2
        return got

    bits = (word() << 16) | word()
    count = 32
    out = bytearray()
    while len(out) < out_size:
        entry = table[(bits >> (count - 15)) & 0x7FFF]
        if not entry:
            raise ValueError("a run of bits is no symbol's code")
        count -= entry & 15
        bits &= (1 << count) - 1
        if count < 16:
            bits = (bits << 16) | word()
            count += 16
        symbol = entry >> 4
        if symbol < 256:
            out.append(symbol)
            continue
        symbol -= 256
        length = symbol & 15
        distance_bits = symbol >> 4
        if length == 15:
            if pos >= end:
                raise ValueError("a match length runs past the end of the block")
            length = data[pos]
            pos += 1
            if length == 255:
                if pos + 2 > end:
                    raise ValueError("a match length runs past the end of the block")
                length = data[pos] | (data[pos + 1] << 8)
                pos += 2
                if length < 15:
                    raise ValueError("a long match length is shorter than a short one")
                length -= 15
            length += 15
        length += 3
        distance = (bits >> (count - distance_bits)) & ((1 << distance_bits) - 1)
        count -= distance_bits
        bits &= (1 << count) - 1
        if count < 16:
            bits = (bits << 16) | word()
            count += 16
        distance += 1 << distance_bits
        if distance > len(out):
            raise ValueError("a match reaches back before the start of the block")
        begin = len(out) - distance
        if distance >= length:
            out += out[begin:begin + length]
        else:
            piece = bytes(out[begin:])
            out += (piece * (-(-length // distance)))[:length]
    return bytes(out[:out_size])


def _lznt1_decompress(src, limit):
    """Inflate an LZNT1 stream, the compression NTFS applies to a $DATA unit.

    The format is a series of chunks, each a 16-bit header giving its stored
    length and whether it is compressed, then either the literal bytes or a
    stream of flag bytes where each bit says whether the next item is a literal
    or a back reference. The split of a back reference into length and offset
    bits widens as the output grows, which is what the shifting below tracks.
    Described in the Linux-NTFS documentation, "Compressed files".

    Always returns ``limit`` bytes. A unit can stop before its output is full:
    a header of zero ends it, and so does the end of the stored bytes, and the
    rest of the unit reads as zeros. A compressed chunk that inflates to fewer
    than 4096 bytes is filled with zeros to 4096, so the next chunk starts
    where it belongs. Both are what ntfs-3g's ntfs_decompress() does, and The
    Sleuth Kit read the two such units found on four public images as zeros
    (see "NTFS compression units that stop early" in the README). Until 1.57
    the bytes decoded so far were returned and the file read short.

    Raises ValueError for bytes that are not an LZNT1 stream: a chunk that
    runs past the stored bytes, a stored chunk that is not 4096 bytes long, or
    a back reference to before its own chunk. Until 1.57 those ended the unit
    without a word; ntfs-3g refuses all three.
    """
    out = bytearray()
    pos = 0
    while pos + 2 <= len(src) and len(out) < limit:
        header = struct.unpack_from("<H", src, pos)[0]
        pos += 2
        if header == 0:
            break
        size = (header & 0x0FFF) + 1
        if pos + size > len(src):
            raise ValueError("a chunk runs past the bytes stored for its unit")
        chunk, pos = src[pos:pos + size], pos + size
        if not header & 0x8000:                    # stored, not compressed
            if size != 4096:
                raise ValueError(f"a stored chunk is {size} bytes long, not 4096")
            out += chunk
            continue
        start = len(out)
        i = 0
        while i < len(chunk) and len(out) - start < 4096:
            flags = chunk[i]
            i += 1
            for bit in range(8):
                if i >= len(chunk) or len(out) - start >= 4096:
                    break
                if not flags & (1 << bit):
                    out.append(chunk[i])
                    i += 1
                    continue
                if i + 2 > len(chunk):
                    i = len(chunk)
                    break
                pair = struct.unpack_from("<H", chunk, i)[0]
                i += 2
                produced = len(out) - start
                shift = 12
                while shift > 4 and produced > (1 << (16 - shift)):
                    shift -= 1
                length = (pair & ((1 << shift) - 1)) + 3
                delta = (pair >> shift) + 1
                if delta > produced:
                    raise ValueError("a back reference reaches before the start "
                                     "of its chunk")
                src_pos = len(out) - delta
                for _ in range(length):
                    out.append(out[src_pos])
                    src_pos += 1
        if len(out) - start < 4096:                # a chunk that inflates short
            out += bytes(4096 - (len(out) - start))
    del out[limit:]
    return bytes(out) + bytes(limit - len(out))


# ---------------------------------------------------------------- APFS
# Field offsets and structure layouts below come from Apple's published "Apple
# File System Reference". No APFS implementation's source was read for this.

APFS_NX_MAGIC   = b"NXSB"
APFS_VOL_MAGIC  = b"APSB"
APFS_OBJ_HDR    = 32            # every object begins with obj_phys_t
APFS_ROOT_INO   = 2             # ROOT_DIR_INO_NUM
# A container holds several volumes and the walker interface above is one tree
# per region, so the container itself is presented as a directory whose children
# are its volumes. A node is the volume's index in the high bits and the
# file-system object id in the low ones; the container is a value no volume can
# produce.
# A file-system object id is 60 bits, because the record type takes the top
# four of the 64-bit key field. The sealed system volume of macOS 11 and later
# uses ids near the top of that range (0x0FFFFFFF...), so a narrower field
# silently drops every one of its directory entries. A walker node is a plain
# Python integer with no width to run out of, so the volume index simply sits
# above the full 60 bits, and the container sentinel is put where no volume and
# object id can reach it.
APFS_VOL_SHIFT  = 60
APFS_OID_MASK   = (1 << APFS_VOL_SHIFT) - 1
APFS_CONTAINER  = 1 << 127
APFS_BTREE_INFO = 40            # a root node carries btree_info_t at its end

APFS_OBJ_TYPE_MASK = 0x0000FFFF
APFS_OBJECT_TYPE_NX_SUPERBLOCK = 0x0001
APFS_OBJECT_TYPE_SPACEMAN      = 0x0005
APFS_OBJECT_TYPE_CHECKPOINT_MAP = 0x000C
APFS_NX_SPACEMAN_OID_OFF = 152   # nx_spaceman_oid in the container superblock
APFS_SM_DEV_MAIN_OFF     = 48    # sm_dev[SD_MAIN] in spaceman_phys_t
APFS_CI_SIZE             = 32    # sizeof(chunk_info_t)
APFS_CPM_SIZE            = 40    # sizeof(checkpoint_mapping_t)
APFS_OBJECT_TYPE_BTREE_NODE    = 0x0003
APFS_OBJECT_TYPE_OMAP          = 0x000B
APFS_OBJECT_TYPE_FS            = 0x000D

APFS_BTNODE_ROOT     = 0x0001
APFS_BTNODE_LEAF     = 0x0002
APFS_BTNODE_FIXED_KV = 0x0004

# btree_info sits in the last 40 bytes of a root node and declares the tree's
# own shape. BTREE_HASHED marks the integrity-checked tree of a sealed volume,
# where an index node's value carries a hash after the child pointer.
APFS_BTREE_INFO      = 40
APFS_BTREE_HASHED    = 0x00000080
APFS_BTREE_PHYSICAL  = 0x00000010

# A sealed volume keeps its file extents in a tree of its own, keyed by the
# stream id and the offset within the file, instead of as records in the
# file-system tree. The volume superblock names it; the offset below was found
# by looking for the field that resolves to a physical B-tree root, and the
# reader checks that it is one before using it rather than trusting the offset.
APFS_FEXT_TREE_OFF   = 1032

# record types, the high four bits of a file-system key's object id
APFS_TYPE_INODE       = 3
APFS_TYPE_XATTR       = 4
APFS_TYPE_DSTREAM_ID  = 6
APFS_TYPE_FILE_EXTENT = 8
APFS_TYPE_DIR_REC     = 9

# The record types a listing asks for, over and over, one object id at a time:
# a directory's children, an inode, and the extended attribute that carries a
# compressed file's real size. prime_records() reads all of them in one pass
# over the tree's leaves. File extents are left out on purpose: only reading a
# file's content needs them, a listing never asks, and on a volume of any size
# they are the bulk of the tree.
APFS_PRIMED_TYPES = frozenset((APFS_TYPE_INODE, APFS_TYPE_XATTR, APFS_TYPE_DIR_REC))

# How many records prime_records() will hold for one volume before giving up on
# it and leaving the tree to be searched the ordinary way. The table is a
# Python object per record and per key, which is most of what it costs: the
# 1,853,807 records of a 625,543-entry macOS volume are 155 MB of bytes and
# about 900 MB of process. This cap is roughly twice that volume, so a volume
# large enough to exhaust a machine is walked slowly instead of not at all.
APFS_PRIME_MAX_RECORDS = 4_000_000

APFS_INCOMPAT_CASE_INSENSITIVE          = 0x0000000000000001
# apfs_superblock_t.apfs_fs_flags, and its "volume isn't encrypted" bit (Apple File
# System Reference, 2020-06-22: apfs_superblock_t and Volume Flags). A volume
# without the bit is encrypted; whether its blocks are ciphertext in an image is
# a separate question, answered from the blocks (ApfsWalker.encryption).
APFS_FS_FLAGS_OFF                       = 264
APFS_FS_UNENCRYPTED                     = 0x0000000000000001
APFS_INCOMPAT_NORMALIZATION_INSENSITIVE = 0x0000000000000008

# What opening an encrypted volume with its password needs (Apple File System
# Reference, 2020-06-22, "Encryption" and "Accessing Encrypted Objects", and the
# constants beside the structures named here). APFS_FS_ONEKEY is the volume flag
# saying every file uses the volume key, which is the software encryption that
# reference describes; apfs_er_state_oid, at 976 in apfs_superblock_t, is nonzero
# while a volume is being encrypted or decrypted; om_flags, at 32 in omap_phys_t,
# carries the same state for the volume's object map; OMAP_VAL_ENCRYPTED marks a
# mapping whose object is encrypted. The container's keybag is the prange_t at
# 1296 in nx_superblock_t (nx_keylocker; the offset as libfsapfs's format notes
# give it, and the keybag sits there on both fixtures).
APFS_FS_ONEKEY                          = 0x0000000000000008
APFS_ER_STATE_OFF                       = 976
APFS_NX_KEYLOCKER_OFF                   = 1296
APFS_OMAP_FLAGS_OFF                     = 32
APFS_OMAP_ENCRYPTING                    = 0x2
APFS_OMAP_DECRYPTING                    = 0x4
APFS_OMAP_KEYROLLING                    = 0x8
APFS_OMAP_VAL_ENCRYPTED                 = 0x4

APFS_INO_EXT_TYPE_DSTREAM = 8   # the extended field holding a file's size
# What says how much of a file the volume stores (Apple File System Reference:
# j_inode_flags, the inode's extended fields and j_dstream_t). The data stream
# field holds the size and then alloced_size, and for a sparse file alloced_size
# is the logical size, holes included: the bytes stored are alloced_size less
# the sparse-bytes field. Measured on a volume macOS 27 wrote: that difference
# equals the blocks stat reports on five of five sparse files.
APFS_INODE_INTERNAL_FLAGS_OFF   = 48
APFS_INODE_BSD_FLAGS_OFF        = 68
APFS_INODE_IS_SPARSE            = 0x00000200
APFS_INO_EXT_TYPE_SPARSE_BYTES  = 13
# SF_DATALESS in the inode's BSD flags (sys/stat.h: "file is dataless object")
# marks a file whose content a file provider holds, iCloud Drive with optimised
# storage for one. Read from the header; no image holding one has been read.
APFS_SF_DATALESS                = 0x40000000

APFS_XATTR_DATA_STREAM = 0x0001
APFS_XATTR_DATA_EMBEDDED = 0x0002

APFS_DECMPFS = "com.apple.decmpfs"
APFS_SYMLINK = "com.apple.fs.symlink"
APFS_RESOURCE_FORK = "com.apple.ResourceFork"

# APFS timestamps are nanoseconds since the Unix epoch.
APFS_NANO = 1_000_000_000


# ---------------------------------------------------------------------------
# LZVN and LZFSE, the two codecs macOS file compression (decmpfs) keeps most
# compressed files in. Neither is in the standard library, so both are carried
# here as pure-Python decoders, written for this file from Apple's reference
# implementation, github.com/lzfse/lzfse at commit
# e634ca58b4821d9f3d560cdc6df5dec02ffc93fd (BSD-3-Clause). The C was read, not
# translated line for line; the places each rule comes from are cited by file
# and line at that commit.
#
# Both decoders are strict where the reference is silent. Every stream must end
# with its own end marker, every block must give exactly the bytes its header
# says, a match may not reach before the first byte or repeat a distance never
# set, and output is capped at the size the caller expects. Each of those is a
# DecompressError naming what was wrong, never a short or zero-filled result.
# ---------------------------------------------------------------------------

# LZVN opcode kinds, the jump table in src/lzvn_decode_base.c lines 50 to 82.
_LZVN_SML_D, _LZVN_MED_D, _LZVN_LRG_D, _LZVN_PRE_D = 0, 1, 2, 3
_LZVN_SML_M, _LZVN_LRG_M, _LZVN_SML_L, _LZVN_LRG_L = 4, 5, 6, 7
_LZVN_NOP, _LZVN_EOS, _LZVN_UDEF = 8, 9, 10


def _lzvn_kinds():
    kinds = []
    for opc in range(256):
        if opc >= 0xF0:
            kind = _LZVN_LRG_M if opc == 0xF0 else _LZVN_SML_M
        elif opc >= 0xE0:
            kind = _LZVN_LRG_L if opc == 0xE0 else _LZVN_SML_L
        elif 0x70 <= opc < 0x80 or 0xD0 <= opc < 0xE0:
            kind = _LZVN_UDEF
        elif 0xA0 <= opc < 0xC0:
            kind = _LZVN_MED_D
        elif opc & 7 == 7:
            kind = _LZVN_LRG_D
        elif opc & 7 == 6:
            kind = {0x06: _LZVN_EOS, 0x0E: _LZVN_NOP, 0x16: _LZVN_NOP}.get(
                opc, _LZVN_UDEF if opc < 0x40 else _LZVN_PRE_D)
        else:
            kind = _LZVN_SML_D
        kinds.append(kind)
    return bytes(kinds)


_LZVN_KIND = _lzvn_kinds()


def lzvn_decompress(src, limit, out=None, start=0, end=None):
    """Decode one LZVN stream, src[start:end], onto the end of ``out`` (a
    bytearray, new when None), and return (out, the offset just past the
    stream's end-of-stream opcode).

    ``out`` may already hold earlier output, which a match may reach back
    into: an LZVN block inside an LZFSE stream copies from the blocks before it
    (src/lzfse_decode_base.c line 584, dst_begin is the whole output). At most
    ``limit`` bytes are added.

    The opcodes are those of src/lzvn_decode_base.c: small, medium, large and
    previous distance (lines 129 to 385), the shared literal and match copy
    (387 to 489), the match-only opcodes (491 to 540), the literal-only opcodes
    (542 to 630), nop (632) and end of stream (649), which is the opcode 0x06
    and seven bytes after it. Every other opcode is undefined (664).

    Two checks go past the reference. A match-only opcode is held to the same
    distance test as the others (the reference applies line 431 only to the
    opcodes that carry a literal), so a distance of zero or one reaching before
    the output fails instead of copying bytes that were never written. And a
    stream that runs off the end of its bytes without an end-of-stream opcode
    is an error here, where the reference returns what it had (lines 268, 316,
    354 and the others marked "source truncated").
    """
    if out is None:
        out = bytearray()
    n = len(src) if end is None else end
    pos, cap = start, len(out) + limit
    dist = 0                          # d_prev starts at zero (lzfse_decode_base.c 370)
    kind_of = _LZVN_KIND
    while True:
        if pos >= n:
            raise DecompressError("the LZVN stream ends without its end-of-stream opcode")
        opc = src[pos]
        kind = kind_of[opc]
        match = 0
        if kind <= _LZVN_PRE_D:
            if kind == _LZVN_SML_D:
                lit, match, oplen = opc >> 6, ((opc >> 3) & 7) + 3, 2
            elif kind == _LZVN_MED_D:
                lit, oplen = (opc >> 3) & 3, 3
            elif kind == _LZVN_LRG_D:
                lit, match, oplen = opc >> 6, ((opc >> 3) & 7) + 3, 3
            else:
                lit, match, oplen = opc >> 6, ((opc >> 3) & 7) + 3, 1
            if n - pos <= oplen + lit:
                raise DecompressError("the LZVN stream ends inside an opcode")
            if kind == _LZVN_SML_D:
                dist = (opc & 7) << 8 | src[pos + 1]
            elif kind == _LZVN_MED_D:
                word = src[pos + 1] | src[pos + 2] << 8
                match = ((opc & 7) << 2 | (word & 3)) + 3
                dist = word >> 2
            elif kind == _LZVN_LRG_D:
                dist = src[pos + 1] | src[pos + 2] << 8
            pos += oplen
            if len(out) + lit + match > cap:
                raise DecompressError(f"the LZVN stream decodes to more than {limit:,} bytes")
            if lit:
                out += src[pos:pos + lit]
                pos += lit
        elif kind == _LZVN_SML_M or kind == _LZVN_LRG_M:
            oplen = 1 if kind == _LZVN_SML_M else 2
            if n - pos <= oplen:
                raise DecompressError("the LZVN stream ends inside an opcode")
            match = opc & 15 if kind == _LZVN_SML_M else src[pos + 1] + 16
            pos += oplen
            if len(out) + match > cap:
                raise DecompressError(f"the LZVN stream decodes to more than {limit:,} bytes")
        elif kind == _LZVN_SML_L or kind == _LZVN_LRG_L:
            if kind == _LZVN_SML_L:
                lit, oplen = opc & 15, 1
            else:
                if n - pos <= 2:
                    raise DecompressError("the LZVN stream ends inside an opcode")
                lit, oplen = src[pos + 1] + 16, 2
            if n - pos <= oplen + lit:
                raise DecompressError("the LZVN stream ends inside a literal")
            if len(out) + lit > cap:
                raise DecompressError(f"the LZVN stream decodes to more than {limit:,} bytes")
            out += src[pos + oplen:pos + oplen + lit]
            pos += oplen + lit
            continue
        elif kind == _LZVN_NOP:
            if n - pos <= 1:
                raise DecompressError("the LZVN stream ends inside an opcode")
            pos += 1
            continue
        elif kind == _LZVN_EOS:
            if n - pos < 8:
                raise DecompressError("the LZVN end-of-stream opcode is cut short")
            return out, pos + 8
        else:
            raise DecompressError(f"undefined LZVN opcode 0x{opc:02x} at byte {pos - start:,}")
        if match:
            if dist == 0 or dist > len(out):
                raise DecompressError(f"an LZVN match reaches {dist:,} bytes back, before "
                                      f"the start of the output")
            _copy_match(out, dist, match)


# LZFSE block magics, src/lzfse_internal.h lines 276 to 281.
_LZFSE_END, _LZFSE_RAW = b"bvx$", b"bvx-"
_LZFSE_V1, _LZFSE_V2, _LZFSE_LZVN = b"bvx1", b"bvx2", b"bvxn"
# Symbols and states of the four FSE streams (lzfse_internal.h 89 to 96), and
# the most literals and matches one block may carry (97 and 98).
_LZFSE_L_SYMBOLS, _LZFSE_M_SYMBOLS, _LZFSE_D_SYMBOLS, _LZFSE_LIT_SYMBOLS = 20, 20, 64, 256
_LZFSE_L_STATES, _LZFSE_M_STATES, _LZFSE_D_STATES, _LZFSE_LIT_STATES = 64, 64, 256, 1024
_LZFSE_MATCHES_PER_BLOCK = 10000
_LZFSE_LITERALS_PER_BLOCK = 4 * _LZFSE_MATCHES_PER_BLOCK
# The extra bits and base value of each L, M and D symbol (lzfse_internal.h 588
# to 614).
_LZFSE_L_BITS = (0,) * 16 + (2, 3, 5, 8)
_LZFSE_L_BASE = tuple(range(16)) + (16, 20, 28, 60)
_LZFSE_M_BITS = (0,) * 16 + (3, 5, 8, 11)
_LZFSE_M_BASE = tuple(range(16)) + (16, 24, 56, 312)
_LZFSE_D_BITS = tuple(i // 4 for i in range(64))
_LZFSE_D_BASE = (
    0, 1, 2, 3, 4, 6, 8, 10, 12, 16, 20, 24, 28, 36, 44, 52, 60, 76, 92, 108,
    124, 156, 188, 220, 252, 316, 380, 444, 508, 636, 764, 892, 1020, 1276, 1532,
    1788, 2044, 2556, 3068, 3580, 4092, 5116, 6140, 7164, 8188, 10236, 12284, 14332,
    16380, 20476, 24572, 28668, 32764, 40956, 49148, 57340, 65532, 81916, 98300,
    114684, 131068, 163836, 196604, 229372)
# The v1 header is a C struct of seven 32-bit counts, the literal bits and four
# states, the L, M, D bits and three states, then 360 16-bit frequencies
# (lzfse_internal.h 291 to 330): 770 bytes, which the compiler rounds up to 772
# for its 4-byte alignment, and sizeof() is what lzfse_decode_base.c 400 skips.
_LZFSE_V1_HEADER = 772
_LZFSE_V1_FREQ_AT = 50
_LZFSE_FREQ_COUNT = _LZFSE_L_SYMBOLS + _LZFSE_M_SYMBOLS + _LZFSE_D_SYMBOLS + _LZFSE_LIT_SYMBOLS
# The v2 header's frequencies are a prefix code (lzfse_decode_base.c 28 to 48):
# the low five bits pick the length and, up to five bits, the value.
_LZFSE_FREQ_NBITS = (2, 3, 2, 5, 2, 3, 2, 8, 2, 3, 2, 5, 2, 3, 2, 14) * 2
_LZFSE_FREQ_VALUE = (0, 2, 1, 4, 0, 3, 1, -1, 0, 2, 1, 5, 0, 3, 1, -1,
                     0, 2, 1, 6, 0, 3, 1, -1, 0, 2, 1, 7, 0, 3, 1, -1)


def _lzfse_v2_freqs(head, size):
    """The 360 frequencies packed after a v2 header's three fixed fields, as
    lzfse_decode_v1() reads them (lzfse_decode_base.c 105 to 142): none at all
    when the header is just its fixed part, else exactly enough bits to fill
    every table, ending inside the header's last byte."""
    if size == 32:
        return [0] * _LZFSE_FREQ_COUNT
    freqs, accum, nbits, at = [], 0, 0, 32
    for _ in range(_LZFSE_FREQ_COUNT):
        while at < size and nbits + 8 <= 32:
            accum |= head[at] << nbits
            nbits, at = nbits + 8, at + 1
        low = accum & 31
        take = _LZFSE_FREQ_NBITS[low]
        if take == 8:
            value = 8 + ((accum >> 4) & 0xF)
        elif take == 14:
            value = 24 + ((accum >> 4) & 0x3FF)
        else:
            value = _LZFSE_FREQ_VALUE[low]
        if take > nbits:
            raise DecompressError("an LZFSE block header's frequency tables are cut short")
        freqs.append(value)
        accum, nbits = accum >> take, nbits - take
    if nbits >= 8 or at != size:
        raise DecompressError("an LZFSE block header's frequency tables do not fill it exactly")
    return freqs


def _fse_spread(nstates, freqs):
    """(symbol, freq, j, k, delta) per state, the layout fse_init_decoder_table()
    and fse_init_value_decoder_table() share (lzfse_fse.c 57 to 147): each
    symbol takes ``freq`` consecutive states; the first j0 of them read k bits
    and the rest k - 1. A table whose frequencies sum short of nstates leaves
    states no symbol owns, which the reference never initialises; here they
    are None, and reaching one is an error."""
    if sum(freqs) > nstates:
        raise DecompressError("an LZFSE frequency table holds more states than it may")
    top = nstates.bit_length()
    table = []
    for sym, f in enumerate(freqs):
        if not f:
            continue
        k = top - f.bit_length()
        j0 = ((2 * nstates) >> k) - f
        for j in range(f):
            if j < j0:
                table.append((sym, k, ((f + j) << k) - nstates))
            else:
                table.append((sym, k - 1, (j - j0) << (k - 1)))
    table += [None] * (nstates - len(table))
    return table


class _FseBits:
    """The backward bit reader of lzfse_fse.h, in its 64-bit form (the one the
    header selects on x86_64 and arm64, line 38). Initialising takes eight
    bytes, or seven when the stream's final byte is full (300 to 325), and must
    leave the bits above the count zero; a flush tops the accumulator back up
    to between 56 and 63 bits a byte at a time (361 to 378), and may not read
    before ``floor``; a pull takes bits off the top (407 to 413)."""

    __slots__ = ("buf", "pos", "floor", "accum", "nbits")

    def __init__(self, buf, end, floor, extra):
        if not -7 <= extra <= 0:
            raise DecompressError("an LZFSE bit stream's final bit count is out of range")
        take = 8 if extra else 7
        if end - take < floor:
            raise DecompressError("an LZFSE bit stream is shorter than its first load")
        self.buf, self.floor, self.pos = buf, floor, end - take
        self.accum = int.from_bytes(buf[self.pos:end], "little")
        self.nbits = extra + 64 if extra else 56
        if self.accum >> self.nbits:
            raise DecompressError("an LZFSE bit stream carries bits past its stated end")

    def flush(self):
        add = (63 - self.nbits) & ~7
        if add:
            pos = self.pos - (add >> 3)
            if pos < self.floor:
                raise DecompressError("an LZFSE bit stream runs out before its symbols do")
            self.accum = (self.accum << add) | int.from_bytes(self.buf[pos:self.pos], "little")
            self.nbits += add
            self.pos = pos

    def pull(self, n):
        if n > self.nbits:
            raise DecompressError("an LZFSE bit stream runs out before its symbols do")
        self.nbits -= n
        value = self.accum >> self.nbits
        self.accum &= (1 << self.nbits) - 1
        return value


def _lzfse_value_table(nstates, freqs, vbits, vbase):
    """fse_init_value_decoder_table() (lzfse_fse.c 109 to 147): per state, the
    bits to pull (state bits plus the symbol's extra bits), the extra bits, the
    state base and the value base."""
    out = []
    for item in _fse_spread(nstates, freqs):
        if item is None:
            out.append(None)
        else:
            sym, k, delta = item
            out.append((k + vbits[sym], vbits[sym], delta, vbase[sym]))
    return out


def _lzfse_block(src, pos, n, out, cap, v2):
    """Decode one compressed LZFSE block (bvx1 or bvx2) at src[pos], appending to
    out. Returns the offset after it. lzfse_decode() lines 376 to 512 for the
    header and literals, lzfse_decode_lmd() lines 156 to 329 for the matches."""
    if v2:
        if pos + 32 > n:
            raise DecompressError("an LZFSE block header is cut short")
        raw, v0, v1, v2f = struct.unpack_from("<IQQQ", src, pos + 4)
        size = v2f & 0xFFFFFFFF
        if size < 32 or pos + size > n:
            raise DecompressError("an LZFSE block header is cut short")
        n_lit, n_lit_payload, n_match = v0 & 0xFFFFF, (v0 >> 20) & 0xFFFFF, (v0 >> 40) & 0xFFFFF
        lit_bits = ((v0 >> 60) & 7) - 7
        lit_state = [(v1 >> s) & 0x3FF for s in (0, 10, 20, 30)]
        n_lmd_payload, lmd_bits = (v1 >> 40) & 0xFFFFF, ((v1 >> 60) & 7) - 7
        l_state, m_state, d_state = (v2f >> 32) & 0x3FF, (v2f >> 42) & 0x3FF, (v2f >> 52) & 0x3FF
        freqs = _lzfse_v2_freqs(src[pos:pos + size], size)
    else:
        size = _LZFSE_V1_HEADER
        if pos + size > n:
            raise DecompressError("an LZFSE block header is cut short")
        (raw, _payload, n_lit, n_match, n_lit_payload, n_lmd_payload, lit_bits) = \
            struct.unpack_from("<IIIIIIi", src, pos + 4)
        lit_state = list(struct.unpack_from("<4H", src, pos + 32))
        lmd_bits, l_state, m_state, d_state = struct.unpack_from("<iHHH", src, pos + 40)
        freqs = list(struct.unpack_from(f"<{_LZFSE_FREQ_COUNT}H", src, pos + _LZFSE_V1_FREQ_AT))
    if pos + size + n_lit_payload + n_lmd_payload > n:
        raise DecompressError("an LZFSE block is cut short")
    # lzfse_check_block_header_v1(), lzfse_internal.h 511 to 567
    if (n_lit > _LZFSE_LITERALS_PER_BLOCK or n_match > _LZFSE_MATCHES_PER_BLOCK
            or any(s >= _LZFSE_LIT_STATES for s in lit_state) or l_state >= _LZFSE_L_STATES
            or m_state >= _LZFSE_M_STATES or d_state >= _LZFSE_D_STATES):
        raise DecompressError("an LZFSE block header is out of range")
    if len(out) + raw > cap:
        raise DecompressError(f"an LZFSE block decodes to more than the {cap:,} bytes expected")
    a = _LZFSE_L_SYMBOLS
    b = a + _LZFSE_M_SYMBOLS
    c = b + _LZFSE_D_SYMBOLS
    l_tab = _lzfse_value_table(_LZFSE_L_STATES, freqs[:a], _LZFSE_L_BITS, _LZFSE_L_BASE)
    m_tab = _lzfse_value_table(_LZFSE_M_STATES, freqs[a:b], _LZFSE_M_BITS, _LZFSE_M_BASE)
    d_tab = _lzfse_value_table(_LZFSE_D_STATES, freqs[b:c], _LZFSE_D_BITS, _LZFSE_D_BASE)
    lit_tab = _fse_spread(_LZFSE_LIT_STATES, freqs[c:])
    # Literals: four interleaved states over one stream read backwards from the
    # end of the literal payload, which may read back into the bytes before it
    # (the stream's floor is the start of the whole buffer, line 443).
    pos += size
    lit_end = pos + n_lit_payload
    # The bit reader is _FseBits, its flush and pull written out inline in both
    # loops below: the same rules, a quarter of the time.
    bits = _FseBits(src, lit_end, 0, lit_bits)
    acc, nb, bpos, floor = bits.accum, bits.nbits, bits.pos, 0
    lits = bytearray()
    s0, s1, s2, s3 = lit_state
    short = "an LZFSE bit stream runs out before its symbols do"
    try:
        for _ in range(0, n_lit, 4):
            add = (63 - nb) & ~7
            if add:
                npos = bpos - (add >> 3)
                if npos < floor:
                    raise DecompressError(short)
                acc = (acc << add) | int.from_bytes(src[npos:bpos], "little")
                nb, bpos = nb + add, npos
            sym, k, delta = lit_tab[s0]
            if k > nb:
                raise DecompressError(short)
            nb -= k
            s0 = delta + (acc >> nb)
            acc &= (1 << nb) - 1
            lits.append(sym)
            sym, k, delta = lit_tab[s1]
            if k > nb:
                raise DecompressError(short)
            nb -= k
            s1 = delta + (acc >> nb)
            acc &= (1 << nb) - 1
            lits.append(sym)
            sym, k, delta = lit_tab[s2]
            if k > nb:
                raise DecompressError(short)
            nb -= k
            s2 = delta + (acc >> nb)
            acc &= (1 << nb) - 1
            lits.append(sym)
            sym, k, delta = lit_tab[s3]
            if k > nb:
                raise DecompressError(short)
            nb -= k
            s3 = delta + (acc >> nb)
            acc &= (1 << nb) - 1
            lits.append(sym)
    except (TypeError, IndexError):
        raise DecompressError("an LZFSE literal reaches a state no symbol owns") from None
    # Matches: L, M, D triples from the second stream, which the encoder pads
    # with eight zero bytes at its start (lzfse_encode_base.c 320 to 326).
    pos = lit_end
    bits = _FseBits(src, pos + n_lmd_payload, pos, lmd_bits)
    acc, nb, bpos, floor = bits.accum, bits.nbits, bits.pos, pos
    start_len, used, dist, n_lits = len(out), 0, -1, len(lits)
    olen = start_len
    try:
        for _ in range(n_match):
            add = (63 - nb) & ~7
            if add:
                npos = bpos - (add >> 3)
                if npos < floor:
                    raise DecompressError(short)
                acc = (acc << add) | int.from_bytes(src[npos:bpos], "little")
                nb, bpos = nb + add, npos
            total, vb, delta, base = l_tab[l_state]
            if total > nb:
                raise DecompressError(short)
            nb -= total
            got = acc >> nb
            acc &= (1 << nb) - 1
            l_state, lit = delta + (got >> vb), base + (got & ((1 << vb) - 1))
            total, vb, delta, base = m_tab[m_state]
            if total > nb:
                raise DecompressError(short)
            nb -= total
            got = acc >> nb
            acc &= (1 << nb) - 1
            m_state, match = delta + (got >> vb), base + (got & ((1 << vb) - 1))
            total, vb, delta, base = d_tab[d_state]
            if total > nb:
                raise DecompressError(short)
            nb -= total
            got = acc >> nb
            acc &= (1 << nb) - 1
            d_state, new_d = delta + (got >> vb), base + (got & ((1 << vb) - 1))
            dist = new_d or dist
            if used + lit > n_lits:
                raise DecompressError("an LZFSE match uses more literals than its block holds")
            # line 221: the distance may not reach before the first output byte
            if dist < 0 or dist > olen + lit:
                raise DecompressError(f"an LZFSE match reaches {dist:,} bytes back, before "
                                      f"the start of the output")
            if olen + lit + match > cap:
                raise DecompressError(f"an LZFSE block decodes to more than the {cap:,} "
                                      f"bytes expected")
            if lit:
                out += lits[used:used + lit]
                used += lit
                olen += lit
            if match:
                if dist == 0:
                    raise DecompressError("an LZFSE match has a distance of zero")
                if dist >= match:
                    at = olen - dist
                    out += out[at:at + match]
                else:
                    _copy_match(out, dist, match)
                olen += match
    except (TypeError, IndexError):
        raise DecompressError("an LZFSE match reaches a state no symbol owns") from None
    if len(out) - start_len != raw:
        raise DecompressError(f"an LZFSE block gives {len(out) - start_len:,} bytes where its "
                              f"header says {raw:,}")
    return pos + n_lmd_payload


def lzfse_decompress(src, limit):
    """Decode one LZFSE stream, which is a run of blocks ending in the bvx$
    marker (lzfse_decode_base.c 332 to 630), into at most ``limit`` bytes.

    Blocks are raw (bvx-), LZVN (bvxn), or LZFSE proper with its frequency
    tables either packed (bvx2, what the reference encoder writes) or plain
    (bvx1). A raw or LZVN block must hold every byte its header names, and an
    LZVN block must end with its end-of-stream opcode exactly at the end of
    its payload, having produced exactly its stated bytes (lines 571 to 620).
    A stream that stops before bvx$ is an error, not a short result."""
    out, pos, n = bytearray(), 0, len(src)
    while True:
        if pos + 4 > n:
            raise DecompressError("the LZFSE stream ends without its end-of-stream block")
        magic = bytes(src[pos:pos + 4])
        if magic == _LZFSE_END:
            return bytes(out)
        if magic == _LZFSE_RAW:
            if pos + 8 > n:
                raise DecompressError("an LZFSE raw block header is cut short")
            raw = struct.unpack_from("<I", src, pos + 4)[0]
            if pos + 8 + raw > n:
                raise DecompressError("an LZFSE raw block is cut short")
            if len(out) + raw > limit:
                raise DecompressError(f"the LZFSE stream decodes to more than {limit:,} bytes")
            out += src[pos + 8:pos + 8 + raw]
            pos += 8 + raw
        elif magic == _LZFSE_LZVN:
            if pos + 12 > n:
                raise DecompressError("an LZFSE LZVN block header is cut short")
            raw, payload = struct.unpack_from("<II", src, pos + 4)
            pos += 12
            if pos + payload > n:
                raise DecompressError("an LZFSE LZVN block is cut short")
            if len(out) + raw > limit:
                raise DecompressError(f"the LZFSE stream decodes to more than {limit:,} bytes")
            before = len(out)
            _out, after = lzvn_decompress(src, raw, out, pos, pos + payload)
            if after != pos + payload or len(out) - before != raw:
                raise DecompressError("an LZFSE LZVN block does not end where its header says")
            pos = after
        elif magic in (_LZFSE_V1, _LZFSE_V2):
            pos = _lzfse_block(src, pos, n, out, limit, magic == _LZFSE_V2)
        else:
            raise DecompressError(f"unknown LZFSE block magic {magic!r} at byte {pos:,}")


# ---------------------------------------------------------------------------
# decmpfs: a file whose data fork is empty and whose content is held, compressed
# or not, in its com.apple.decmpfs attribute or in its resource fork.
#
# The attribute starts with a 16-byte header, little endian: "fpmc", the
# method, and the size the file reports (xnu bsd/sys/decmpfs.h lines 114 to 123
# at apple-oss-distributions/xnu f6217f891ac0bb64f3d375211650a4c1ff8ca1ea).
# xnu itself defines only method 1, the content stored as it is after the
# header (decmpfs.h 163 to 168, checked against the attribute's length in
# bsd/kern/decmpfs.c 2289 to 2342); the rest belong to Apple's closed
# AppleFSCompression kernel extension. Their numbers and layouts here are those
# documented in libfsapfs's "Apple File System (APFS)" format notes (sections
# "Compression method" and "Compressed data extended attribute with resource
# fork", libyal/libfsapfs cc122619a0fa5cecf7c077742ac62251fb85fb6c), and each
# one read here was confirmed by having macOS itself read files built to them
# (tools/make_decmpfs_fixture.py):
#
#   3, 7, 9, 11   the whole content in the attribute after the header: zlib,
#                 LZVN, stored, LZFSE
#   4             zlib in the resource fork, 64 KiB per block, behind a resource
#                 map's block table
#   8, 10, 12     LZVN, stored or LZFSE in the resource fork, 64 KiB per block,
#                 behind a table of little-endian 32-bit offsets, one more than
#                 there are blocks, the first of which is the table's own size
#
# A block whose first byte is a marker holds its bytes as they are after it:
# 0xFF for zlib and LZFSE, 0x06 for LZVN (that is its end-of-stream opcode,
# which no stream that holds anything starts with), 0xCC for the stored types.
#
# Not read, and named when met: 5 (seen holding 12 bytes after the header for
# a non-empty file; what it stands for is not established), 13 and 14
# (LZBITMAP, whose format Apple has not published; macOS reads such files, but
# this reader has no published, permissively licensed description to decode
# them from), and any other number.
# ---------------------------------------------------------------------------
DECMPFS_MAGIC = b"fpmc"
DECMPFS_BLOCK = 0x10000
# A file is compressed only when its BSD flags carry UF_COMPRESSED (sys/stat.h
# 0x00000020): decmpfs_file_is_compressed() reads the attribute only then, and
# otherwise treats the file as not compressed and reads its data fork
# (bsd/kern/decmpfs.c lines 838 to 862). An attribute on a file without the flag
# is not the file's content.
UF_COMPRESSED = 0x00000020
# The longest a resource-fork block may be here: twice a block's 64 KiB. A stored
# block is one byte longer than the block (65,537 bytes, the longest of every
# block of 4,712 method 4 and 8 files measured on a Mac running macOS 27); a
# table naming anything far longer is refused rather than read into memory.
DECMPFS_MAX_PIECE = 2 * DECMPFS_BLOCK
# A file's size is an off_t, a signed 64-bit count (sys/_types.h, __int64_t).
DECMPFS_MAX_SIZE = (1 << 63) - 1
# The largest attribute the kernel will read (MAX_DECMPFS_XATTR_SIZE, decmpfs.h
# line 71, enforced at decmpfs.c 561). It also bounds what an attribute-held
# file can decode to.
DECMPFS_MAX_ATTR = 3802
DECMPFS_METHODS = {
    1: ("stored", "attribute"), 3: ("zlib", "attribute"), 4: ("zlib", "fork"),
    7: ("LZVN", "attribute"), 8: ("LZVN", "fork"), 9: ("stored", "attribute"),
    10: ("stored", "fork"), 11: ("LZFSE", "attribute"), 12: ("LZFSE", "fork"),
}
DECMPFS_REFUSED = {
    5: "method 5, which libfsapfs's notes describe only as an unknown, sparse form; "
       "what its bytes stand for is not established, so it is not read here",
    13: "method 13 (LZBITMAP, in the attribute), a format Apple has not published; "
        "it is not read here rather than decoded from a guess",
    14: "method 14 (LZBITMAP, in the resource fork), a format Apple has not published; "
        "it is not read here rather than decoded from a guess",
}


def decmpfs_header(blob):
    """(method, size) from the first 16 bytes of a com.apple.decmpfs attribute,
    or None when they are not one."""
    if len(blob) < 16 or blob[:4] != DECMPFS_MAGIC:
        return None
    return struct.unpack_from("<IQ", blob, 4)


def _decmpfs_block(codec, piece, want, where):
    """The ``want`` bytes one block (or the whole attribute) holds. Anything
    else, more or fewer, is an error naming the block."""
    import zlib                                    # pylint: disable=import-outside-toplevel
    marker = piece[:1]
    try:
        if codec == "stored":
            # A stored block is the marker and its bytes (the attribute's
            # length is 16 + 1 + size on every one of 60,386 method 9 files
            # measured on one macOS 11 volume).
            if marker != b"\xcc":
                raise DecompressError(f"does not start with the 0xCC marker a stored block "
                                      f"carries (0x{piece[0]:02x})" if piece else "is empty")
            out = piece[1:]
        elif marker == (b"\x06" if codec == "LZVN" else b"\xff"):
            out = piece[1:]
        elif codec == "zlib":
            # A resource-fork block need not end its zlib stream. Of the 2,425
            # blocks of 937 method 4 files found on a Mac running macOS 27,
            # 1,473 do not (934 of them not a file's last block, 539 the last),
            # 923 do and 29 are stored, and macOS reads all 937 files. The byte
            # count is what is held to, so the stream is not required to end.
            out = zlib.decompressobj().decompress(piece, min(want + 1, DECMPFS_MAX_SIZE))
        elif codec == "LZVN":
            out, _end = lzvn_decompress(piece, want)
        else:
            out = lzfse_decompress(piece, want)
    except zlib.error as exc:
        raise DecompressError(f"{where} is not a zlib stream: {exc}") from None
    except DecompressError as exc:
        raise DecompressError(f"{where} {exc}" if str(exc).startswith(("does", "is")) else
                              f"{where}: {exc}") from None
    if len(out) != want:
        raise DecompressError(f"{where} gives {len(out):,} bytes where {want:,} belong")
    return bytes(out)


def decmpfs_read(method, size, body, fork):
    """Yield the content of a decmpfs file, a block at a time.

    ``body`` is the attribute's bytes after its 16-byte header. ``fork`` is
    None or an object with ``size`` and ``read(offset, length)`` giving the
    resource fork; it is asked for its bytes in order. A file that cannot be
    read in full raises DecompressError saying why, before or part way through
    what it yields: a reader of this must treat the file as not read, never as
    the bytes it was given so far."""
    if 16 + len(body) > DECMPFS_MAX_ATTR:
        raise DecompressError(f"the compression attribute is {16 + len(body):,} bytes, more than "
                              f"the {DECMPFS_MAX_ATTR:,} macOS itself will read")
    if size > DECMPFS_MAX_SIZE:
        raise DecompressError(f"the compression attribute gives the file a size of {size:,} "
                              f"bytes, more than a file's size can be")
    if method in DECMPFS_REFUSED:
        raise DecompressError(f"the file is compressed with {DECMPFS_REFUSED[method]}")
    if method not in DECMPFS_METHODS:
        raise DecompressError(f"the file is compressed with method {method}, which is not "
                              f"one this reader knows")
    codec, home = DECMPFS_METHODS[method]
    if home == "attribute":
        if method == 1:
            # xnu's own check: the attribute is the header and the content
            # (decmpfs.c 2300)
            if len(body) != size:
                raise DecompressError(f"a method 1 attribute holds {len(body):,} bytes for "
                                      f"a file of {size:,}")
            yield bytes(body)
            return
        if size:
            yield _decmpfs_block(codec, body, size, f"the {codec} attribute")
        return
    if fork is None:
        raise DecompressError("the file's compressed resource fork is not there")
    blocks = -(-size // DECMPFS_BLOCK)
    if codec == "zlib":
        table = _decmpfs_zlib_table(fork, blocks)
    else:
        head = fork.read(0, 4)
        if len(head) < 4:
            raise DecompressError("the compressed resource fork is shorter than its block table")
        first = struct.unpack_from("<I", head)[0]
        if first % 4 or first // 4 != blocks + 1:
            raise DecompressError(f"the compressed resource fork's block table holds "
                                  f"{first // 4 - 1 if first >= 4 else 0:,} blocks where a file "
                                  f"of {size:,} bytes needs {blocks:,}")
        raw = head + fork.read(4, first - 4)
        if len(raw) < first:
            raise DecompressError("the compressed resource fork is shorter than its block table")
        offs = struct.unpack_from(f"<{blocks + 1}I", raw)
        table = [(offs[i], offs[i + 1] - offs[i]) for i in range(blocks)]
    done = 0
    for i, (off, length) in enumerate(table):
        if length < 0 or off + length > fork.size:
            raise DecompressError(f"block {i:,} of the compressed resource fork lies outside it")
        if length > DECMPFS_MAX_PIECE:
            raise DecompressError(f"block {i:,} of the compressed resource fork is {length:,} "
                                  f"bytes, more than the {DECMPFS_MAX_PIECE:,} a 64 KiB block "
                                  f"can take")
        piece = fork.read(off, length)
        if len(piece) != length:
            raise DecompressError(f"block {i:,} of the compressed resource fork is cut short")
        want = min(DECMPFS_BLOCK, size - done)
        yield _decmpfs_block(codec, piece, want, f"block {i:,} of {blocks:,}")
        done += want


def _decmpfs_zlib_table(fork, blocks):
    """[(offset, length)] of a method 4 resource fork's blocks, offsets from the
    start of the fork. The fork is a classic resource file whose one resource
    holds a block count and (offset, length) pairs, little endian, offsets
    counted from just after the resource's own length field."""
    head = fork.read(0, 16)
    if len(head) < 16:
        raise DecompressError("the compressed resource fork is shorter than its header")
    data_off = struct.unpack_from(">I", head, 0)[0]
    lead = fork.read(data_off, 8)
    if len(lead) < 8:
        raise DecompressError("the compressed resource fork has no block table")
    count = struct.unpack_from("<I", lead, 4)[0]
    if count != blocks:
        raise DecompressError(f"the compressed resource fork's block table holds {count:,} "
                              f"blocks where the file's size needs {blocks:,}")
    raw = fork.read(data_off + 8, count * 8)
    if len(raw) < count * 8:
        raise DecompressError("the compressed resource fork's block table is cut short")
    base = data_off + 4
    return [(base + off, length) for off, length in struct.iter_unpack("<II", raw)]


class _ForwardFork:
    """A resource fork read through an iterator of its bytes, for a caller whose
    offsets only move forward, so that a fork of gigabytes is never held whole.
    A block table whose offsets go backwards is refused rather than re-read."""

    def __init__(self, pieces, size):
        self.size, self._it, self._buf, self._at = size, iter(pieces), bytearray(), 0

    def read(self, off, length):
        if off < self._at:
            raise DecompressError("the compressed resource fork's blocks are not in order")
        end = min(off + length, self.size)
        while self._at + len(self._buf) < end:
            piece = next(self._it, None)
            if not piece:
                break
            self._buf += piece
        if off > self._at:
            del self._buf[:off - self._at]
            self._at = off
        return bytes(self._buf[:max(end - off, 0)])


class _BytesFork:
    """A resource fork already in memory."""

    def __init__(self, data):
        self.size, self._data = len(data), data

    def read(self, off, length):
        return bytes(self._data[off:off + length])


class ApfsUnreadable(Exception):
    """A file whose bytes this walker will not guess at: encrypted, or a
    compression this reader does not implement."""


def apfs_time(v):
    """A nanosecond APFS timestamp as Unix seconds, or 0 when unset."""
    if not v:
        return 0
    sec = v // APFS_NANO
    return sec if 0 < sec < 4102444800 else 0


def _apfs_fletcher_ok(block):
    """True when a block's Fletcher-64 checksum is the one it carries.

    The checksum is the first eight bytes of the object header and covers
    everything after it, in 32-bit words. Checking it is what makes "the newest
    checkpoint" a decision rather than a guess: a half-written checkpoint is
    still on disk and still carries a high transaction id.
    """
    if len(block) < APFS_OBJ_HDR:
        return False
    return struct.unpack_from("<Q", block, 0)[0] == _apfs_fletcher(block)


def _apfs_fletcher(block):
    """The Fletcher-64 checksum of everything after a block's first eight bytes."""
    lo = hi = 0
    for off in range(8, len(block) - 3, 4):
        lo = (lo + struct.unpack_from("<I", block, off)[0]) % 0xFFFFFFFF
        hi = (hi + lo) % 0xFFFFFFFF
    c1 = (0xFFFFFFFF - ((lo + hi) % 0xFFFFFFFF)) % 0xFFFFFFFF
    c2 = (0xFFFFFFFF - ((lo + c1) % 0xFFFFFFFF)) % 0xFFFFFFFF
    return (c2 << 32) | c1


class _ApfsBtree:
    """One B-tree, read through whatever resolves an object id to a block."""

    def __init__(self, vol, root_block, physical=False, base_oid=0):
        # An object map's own tree points at blocks; the file-system tree points
        # at virtual object ids that the volume's map has to turn into blocks.
        # Reading the map itself therefore cannot go through the map.
        #
        # base_oid is for the sealed system volume of macOS 11 and later, whose
        # tree stores each child pointer relative to the tree's own root id
        # rather than as the id itself. Left at zero the arithmetic is a no-op,
        # so an ordinary tree is unaffected.
        self.vol, self.root_block, self.physical = vol, root_block, physical
        self.base_oid = base_oid
        self._leaves_cache = None
        self._leaf_keys = []

    @staticmethod
    def _layout(node, node_size):
        flags, _level, nkeys = struct.unpack_from("<HHI", node, APFS_OBJ_HDR)
        toc_off, toc_len = struct.unpack_from("<HH", node, APFS_OBJ_HDR + 8)
        keys_at = APFS_OBJ_HDR + 24 + toc_off + toc_len
        ends_at = node_size - (APFS_BTREE_INFO if flags & APFS_BTNODE_ROOT else 0)
        return flags, nkeys, APFS_OBJ_HDR + 24 + toc_off, keys_at, ends_at

    def records(self, node):
        """[(key bytes, value bytes)] for one node, in key order."""
        size = len(node)
        flags, nkeys, toc_at, keys_at, ends_at = self._layout(node, size)
        fixed = bool(flags & APFS_BTNODE_FIXED_KV)
        leaf = bool(flags & APFS_BTNODE_LEAF)
        step = 4 if fixed else 8
        out = []
        for i in range(nkeys):
            at = toc_at + i * step
            if at + step > size:
                break
            if fixed:
                k, v = struct.unpack_from("<HH", node, at)
                klen = self.vol.fixed_key_size
                vlen = 8 if not leaf else self.vol.fixed_val_size
            else:
                k, klen, v, vlen = struct.unpack_from("<HHHH", node, at)
            ks, vs = keys_at + k, ends_at - v
            if not (0 <= ks <= size - klen and 0 <= vs <= size - vlen):
                continue
            out.append((node[ks:ks + klen], node[vs:vs + vlen]))
        return flags, out

    def leaves(self, key_of):
        """[(first key, block)] for every leaf, in key order, worked out once.

        APFS does not chain its leaves the way HFS+ does, so a reader either
        descends afresh for every lookup or writes the order down. Descending
        each time turns a walk of N files into N walks of the tree; this walks it
        once and every later lookup is a search of the list.
        """
        if self._leaves_cache is None:
            out = []
            self._collect_leaves(self.root_block, key_of, out, 0)
            self._leaves_cache = out
            # The first keys are kept separately because every lookup bisects
            # them: rebuilding that list per lookup makes the walk quadratic in
            # the number of leaves, which is what it was until this was split out.
            self._leaf_keys = [k for k, _b in out]
        return self._leaves_cache

    def _collect_leaves(self, block, key_of, out, depth):
        if depth > 32 or len(out) > 1 << 20:
            return
        node = self.vol.block(block)
        flags, recs = self.records(node)
        if flags & APFS_BTNODE_LEAF:
            if recs:
                out.append((key_of(recs[0][0]), block))
            return
        for _key, val in recs:
            oid = struct.unpack_from("<Q", val, 0)[0]
            # A sealed volume's index value is the child pointer followed by a
            # hash, so it is longer than eight bytes; the pointer itself still
            # sits at the front, and base_oid is what makes it an object id.
            child = oid if self.physical else self.vol.resolve(oid + self.base_oid)
            if child is not None:
                self._collect_leaves(child, key_of, out, depth + 1)

    def search(self, want, key_of):
        """Every leaf record from the first one not less than ``want`` onward."""
        leaves = self.leaves(key_of)
        if not leaves:
            return
        # Start at the last leaf whose first key is strictly less than what is
        # wanted. The run can begin part way through that leaf, so starting at
        # the first leaf whose first key equals the target misses whatever sits
        # at the tail of the one before it. Measured on a 400-entry directory:
        # 387 children found instead of 400.
        i = bisect.bisect_left(self._leaf_keys, want) - 1
        if i < 0:
            i = 0
        for _first, block in leaves[i:]:
            _flags, recs = self.records(self.vol.block(block))
            for key, val in recs:
                k = key_of(key)
                if k is None or k < want:
                    continue
                yield key, val


class ApfsWalker:
    """List and read files from an APFS volume, same interface as the walkers
    above. A node is the file-system object id, which is what a directory record
    stores and what an inode is keyed by.

    An APFS container holds one or more volumes. This walker reads one of them,
    chosen by index, because the walker interface above is per filesystem; the
    identification lines say how many the container holds and name each.

    What it reads: the container's newest checkpoint, its object map, the
    volume's own object map and file-system B-tree, directory records, inodes
    and their extended fields, file extents including sparse ones, symbolic
    links, and files compressed with the decmpfs attribute: zlib, LZVN, LZFSE
    or stored, in the attribute or in the resource fork (decmpfs_read()).

    What it does not read: an encrypted volume whose blocks are ciphertext in
    the image and whose key it was not given, and a file compressed with
    LZBITMAP or with a decmpfs method this reader does not know. Both are
    reported rather than guessed at. An encrypted volume whose blocks the image holds decrypted is
    read (see encryption()), and so is one whose key unlock_apfs() derived from a
    password: fh then carries the keys, and every walker over it decrypts.
    """

    root = APFS_CONTAINER

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        # what was found while reading that is not as it should be: here, a
        # compression attribute on a file not flagged compressed (_decmpfs_of)
        self.damage, self._unflagged = [], set()
        # (container uuid, volume uuid) -> (volume key, what opened it), from
        # unlock_apfs(); block number -> the volume's AES-XTS pair, for every
        # encrypted node of a volume opened with one (see encryption()); and the
        # locks unlock_apfs() found, which say why a volume stayed locked.
        self._keys = dict(getattr(fh, "apfs_keys", None) or {})
        self._locks = {(lk.container_uuid, lk.uuid): lk
                       for lk in getattr(fh, "apfs_found", None) or ()}
        self._dec = {}
        self._vol_cipher = {}                       # volume index -> AES-XTS pair
        self._vol_by = {}                           # volume index -> what opened it
        self._cipher = None                         # the current volume's pair
        self._omap_enc = {}                         # object map oid -> encrypted blocks
        self.fixed_key_size, self.fixed_val_size = 16, 16      # the omap's shape
        head = read_at(fh, base, 4096)
        if len(head) < 4096 or head[32:36] != APFS_NX_MAGIC:
            raise ValueError("not an APFS container superblock")
        self.block_size = struct.unpack_from("<I", head, 36)[0]
        if not self.block_size or self.block_size & (self.block_size - 1):
            raise ValueError("the container superblock gives an impossible block size")
        nx = self._newest_checkpoint(head)
        self._nx = nx
        self.block_count = struct.unpack_from("<Q", nx, 40)[0]
        self.container_size = self.block_count * self.block_size
        self.uuid = uuid.UUID(bytes=nx[72:88])
        omap_oid = struct.unpack_from("<Q", nx, 160)[0]
        max_fs = struct.unpack_from("<I", nx, 180)[0]
        fs_oids = [struct.unpack_from("<Q", nx, 184 + i * 8)[0]
                   for i in range(min(max_fs, 100))]
        self.volume_oids = [o for o in fs_oids if o]
        self._omap_cache = {}
        self._container_omap = self._read_omap(omap_oid)
        self.volumes = []
        self.volume_uuids = []                      # apfs_vol_uuid, by volume index
        for oid in self.volume_oids:
            block = self._container_omap.get(oid)
            if block is None:
                continue
            sb = self.block(block)
            if sb[32:36] != APFS_VOL_MAGIC:
                continue
            self.volumes.append((oid, block, _apfs_volume_name(sb),
                                 struct.unpack_from("<Q", sb, 56)[0]))
            self.volume_uuids.append(uuid.UUID(bytes=sb[240:256]))
        if not self.volumes:
            raise ValueError("the container names no readable volume")
        self._state = {}
        self._crypt = {}                            # volume index -> encryption()
        self._current = None
        self._primed = None                         # prime_records() fills it
        self._fext = None
        # what _open_volume sets, for a container whose every volume is locked
        self._volume_omap, self._tree, self._inodes = {}, None, {}
        self._hashed_names = self.case_insensitive = self.sealed = False
        self.volume_name, self.fs_root_block = None, None
        first = next((i for i in range(len(self.volumes))
                      if self.encryption(i) != "locked"), None)
        if first is not None:
            self._open_volume(first)

    # -- volumes -----------------------------------------------------------
    def _open_volume(self, index):
        """Make one volume of the container the current one, reading its object
        map and file-system tree the first time it is asked for."""
        if self._current == index:
            return
        if self.encryption(index) == "locked":
            # every route to a volume's tree comes through here, so a locked one is
            # never parsed: ciphertext read as a tree returns nothing, silently
            raise ApfsUnreadable(f"volume {index} is encrypted and its blocks are "
                                 f"ciphertext in this image")
        got = self._state.get(index)
        if got is None:
            _oid, block, _name, incompat = self.volumes[index]
            sb = self.block(block)
            vol_omap_oid, root_oid = struct.unpack_from("<QQ", sb, 128)
            # Reading the volume's own map has to happen while nothing else is
            # current, because resolve() consults whatever is.
            self._current, self._volume_omap = None, {}
            omap = self._read_omap(vol_omap_oid)
            root_block = omap.get(root_oid)
            if root_block is None:
                raise ValueError(f"volume {index}'s file-system tree is not in its map")
            # A sealed system volume declares its tree hashed, in the
            # btree_info that sits in the last 40 bytes of the root node, and
            # stores its child pointers relative to the tree's own root id.
            # Reading that declaration is what decides it: the alternative is
            # keying on a macOS version, which the volume does not carry.
            root_node = self.block(root_block)
            sealed = False
            if len(root_node) >= APFS_BTREE_INFO:
                bt_flags = struct.unpack_from(
                    "<I", root_node, len(root_node) - APFS_BTREE_INFO)[0]
                sealed = bool(bt_flags & APFS_BTREE_HASHED)
            got = {
                "omap": omap,
                "tree": None,
                "root_block": root_block,
                "base_oid": root_oid if sealed else 0,
                "sealed": sealed,
                "fext": self._read_fext(sb) if sealed else None,
                # A directory record's key carries the name's length alone, or a
                # length and a hash together, and the volume decides which.
                # Reading the wrong shape puts bytes of hash on the front of
                # every name, which is what it did until this was sourced.
                "hashed": bool(incompat & (APFS_INCOMPAT_CASE_INSENSITIVE
                                           | APFS_INCOMPAT_NORMALIZATION_INSENSITIVE)),
                "case_insensitive": bool(incompat & APFS_INCOMPAT_CASE_INSENSITIVE),
                "inodes": {},
                # filled by prime_records(), and None until it is asked for
                "primed": None,
                # set when the volume held more records than the cap allows, so
                # a second call does not pay for the same abandoned pass again
                "prime_capped": False,
            }
            self._state[index] = got
        self._current = index
        self._volume_omap = got["omap"]
        if got["tree"] is None:
            got["tree"] = _ApfsBtree(self, got["root_block"],
                                     base_oid=got["base_oid"])
        self._tree = got["tree"]
        self._inodes = got["inodes"]
        self._primed = got["primed"]
        self._hashed_names = got["hashed"]
        self.case_insensitive = got["case_insensitive"]
        self.volume_name = self.volumes[index][2]
        self.fs_root_block = got["root_block"]
        self.sealed = got["sealed"]
        self._fext = got["fext"]
        self._cipher = self._vol_cipher.get(index)

    def _split(self, node):
        """(volume index, object id) for a walker node."""
        return node >> APFS_VOL_SHIFT, node & APFS_OID_MASK

    def _select(self, node):
        vol, oid = self._split(node)
        if vol >= len(self.volumes) or self.encryption(vol) == "locked":
            return None
        self._open_volume(vol)
        return oid

    def encryption(self, index):
        """None for a volume its flags say is not encrypted. For an encrypted one,
        "clear" when its file-system tree's root node passes its checksum here, so
        the image holds its blocks decrypted (an acquisition read through the Mac's
        own decryption, as BlackBag's Digital Collector reads one, stores them so);
        "unlocked" when its blocks are ciphertext and the key unlock_apfs() derived
        for it decrypts that root node to one that passes; and "locked" otherwise.
        A locked volume is not walked: parsing ciphertext as a tree returns
        nothing, and returning nothing reads as an empty volume."""
        if index in self._crypt:
            return self._crypt[index]
        _oid, block, _name, _incompat = self.volumes[index]
        sb = self.block(block)
        state = None
        if not struct.unpack_from("<Q", sb, APFS_FS_FLAGS_OFF)[0] & APFS_FS_UNENCRYPTED:
            vol_omap_oid, root_oid = struct.unpack_from("<QQ", sb, 128)
            saved = self._current, self._volume_omap
            ok = False
            try:
                # as in _open_volume: the volume's own map is read with nothing current
                self._current, self._volume_omap = None, {}
                root_block = self._read_omap(vol_omap_oid).get(root_oid)
                ok = root_block is not None and _apfs_fletcher_ok(self.block(root_block))
            except (ValueError, OSError, struct.error):
                ok = False
            finally:
                self._current, self._volume_omap = saved
            state = "clear" if ok else "locked"
            key = self._keys.get((self.uuid, self.volume_uuids[index]))
            if state == "locked" and key is not None and self._apply_key(index, sb, key):
                state = "unlocked"
        self._crypt[index] = state
        return state

    def crypto_blocker(self, sb):
        """Why a volume's key, even known, would not be used to read it, or "".

        Apple's reference describes opening a volume whose files all use the
        volume key (APFS_FS_ONEKEY); per-file keys go with hardware encryption.
        A volume being encrypted, decrypted or given a new key is part way through
        a transition, its blocks not all in one state until it finishes, which the
        volume (apfs_er_state_oid) and its object map (om_flags) record while it
        lasts."""
        flags = struct.unpack_from("<Q", sb, APFS_FS_FLAGS_OFF)[0]
        if not flags & APFS_FS_ONEKEY:
            return ("its files use per-file keys, which Apple's reference ties to hardware "
                    "encryption; this reads a volume whose files all use the volume key")
        vol_omap_oid = struct.unpack_from("<Q", sb, 128)[0]
        om = self.block(vol_omap_oid)
        om_flags = struct.unpack_from("<I", om, APFS_OMAP_FLAGS_OFF)[0] if len(om) >= 36 else 0
        if (struct.unpack_from("<Q", sb, APFS_ER_STATE_OFF)[0]
                or om_flags & (APFS_OMAP_ENCRYPTING | APFS_OMAP_DECRYPTING
                               | APFS_OMAP_KEYROLLING)):
            return ("it was being encrypted, decrypted or given a new key when it was "
                    "imaged, so its blocks are not all in one state, which this does not "
                    "read")
        return ""

    def _apply_key(self, index, sb, key):
        """Decrypt a volume's encrypted nodes with its key from now on, if the key
        turns the root node of its file-system tree into one whose Fletcher-64
        checksum holds. Its tree nodes are the blocks its object map marks
        OMAP_VAL_ENCRYPTED, each decrypted as AES-XTS with the volume key and its
        512-byte sector number in the container as the tweak."""
        vek, by = key
        if _BDE_AES is None or len(vek) != 32 or self.crypto_blocker(sb):
            return False
        vol_omap_oid, root_oid = struct.unpack_from("<QQ", sb, 128)
        pair = (_BDE_AES.new(vek[:16], _BDE_AES.MODE_ECB),
                _BDE_AES.new(vek[16:], _BDE_AES.MODE_ECB))
        saved = self._current, self._volume_omap
        added, ok = [], False
        try:
            self._current, self._volume_omap = None, {}
            root_block = self._read_omap(vol_omap_oid).get(root_oid)
            enc = self._omap_enc.get(vol_omap_oid, ())
            if root_block is not None and root_block in enc:
                for blk in enc:
                    if blk not in self._dec:
                        self._dec[blk] = pair
                        added.append(blk)
                ok = _apfs_fletcher_ok(self.block(root_block))
        except (ValueError, OSError, struct.error):
            ok = False
        finally:
            self._current, self._volume_omap = saved
        if not ok:
            for blk in added:
                del self._dec[blk]
            return False
        self._vol_cipher[index], self._vol_by[index] = pair, by
        return True

    def lock(self, index):
        """The ApfsLock unlock_apfs() made for a volume, or None."""
        return self._locks.get((self.uuid, self.volume_uuids[index]))

    @property
    def note(self):
        """What a report should say about the container's encrypted volumes, or
        None when none is encrypted."""
        parts = []
        for state, text in (
                ("locked", "{} encrypted, and {} blocks are ciphertext in this image, "
                           "so {} files are not listed or extracted"),
                ("clear", "{} flagged encrypted, but {} blocks read in the clear in "
                          "this image, as an acquisition made through the Mac's own "
                          "decryption stores them, so {} files are read as they are")):
            which = [i for i in range(len(self.volumes)) if self.encryption(i) == state]
            names = [self.volumes[i][2] or f"volume {i}" for i in which]
            if names:
                one = len(names) == 1
                parts.append(text.format(f"{', '.join(names)} {'is' if one else 'are'}",
                                         "its" if one else "their",
                                         "its" if one else "their"))
            if state == "locked":
                for i in which:
                    lk = self.lock(i)
                    if lk is not None:
                        parts.append(f"{self.volumes[i][2] or f'volume {i}'}: "
                                     f"{lk.locked_note()}")
        for i in range(len(self.volumes)):
            if self.encryption(i) == "unlocked":
                parts.append(f"{self.volumes[i][2] or f'volume {i}'} is encrypted and was "
                             f"opened with {_apfs_opened_with(self._vol_by.get(i))}, so its "
                             f"files are read decrypted")
        return "; ".join(parts) or None

    # -- blocks and object maps -------------------------------------------
    def block(self, n):
        raw = read_at(self.fh, self.base + n * self.block_size, self.block_size)
        pair = self._dec.get(n) if self._dec else None
        if pair is None:
            return raw
        # an encrypted node of an opened volume: its tweak is the node's own
        # position, in 512-byte sectors from the start of the container
        return _xts_crypt(pair, raw, n * (self.block_size // 512))

    def resolve(self, oid):
        """A child pointer inside the file-system tree is a virtual object id,
        which the volume's object map turns into a block. An id the map does not
        hold is not a block number to fall back on: guessing there would read
        whatever happens to sit at that offset and call it a node."""
        return self._volume_omap.get(oid)

    def _newest_checkpoint(self, head):
        """The container superblock with the highest transaction id that checks out.

        Block zero is a copy that can be older than the newest checkpoint, so the
        checkpoint descriptor area is scanned and the best one taken. Block zero
        stands in when nothing there is usable.
        """
        best, best_xid = head, struct.unpack_from("<Q", head, 16)[0]
        base = struct.unpack_from("<Q", head, 112)[0]
        blocks = struct.unpack_from("<I", head, 104)[0]
        for i in range(min(blocks, 512)):
            raw = self.block(base + i)
            if len(raw) < 40 or raw[32:36] != APFS_NX_MAGIC:
                continue
            otype = struct.unpack_from("<I", raw, 24)[0] & APFS_OBJ_TYPE_MASK
            if otype != APFS_OBJECT_TYPE_NX_SUPERBLOCK:
                continue
            xid = struct.unpack_from("<Q", raw, 16)[0]
            if xid > best_xid and _apfs_fletcher_ok(raw):
                best, best_xid = raw, xid
        self.xid = best_xid
        return best

    def _ephemeral(self, oid):
        """The block an ephemeral object sits in, or None.

        An ephemeral object is not in the object map. It is written into the
        checkpoint data area and located through the checkpoint map blocks that
        share its checkpoint, so the descriptor area is scanned for maps carrying
        this walker's transaction id and their entries are read.
        """
        desc_base = struct.unpack_from("<Q", self._nx, 112)[0]
        desc_blocks = struct.unpack_from("<I", self._nx, 104)[0]
        for i in range(min(desc_blocks, 4096)):
            raw = self.block(desc_base + i)
            if len(raw) < 40:
                continue
            if (struct.unpack_from("<I", raw, 24)[0] & APFS_OBJ_TYPE_MASK
                    != APFS_OBJECT_TYPE_CHECKPOINT_MAP):
                continue
            if struct.unpack_from("<Q", raw, 16)[0] != self.xid:
                continue
            count = struct.unpack_from("<I", raw, 36)[0]
            for k in range(min(count, (len(raw) - 40) // APFS_CPM_SIZE)):
                at = 40 + k * APFS_CPM_SIZE
                cpm_oid, cpm_paddr = struct.unpack_from("<QQ", raw, at + 24)
                if cpm_oid == oid:
                    return cpm_paddr
        return None

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the container says are free.

        APFS tracks free space per container rather than per volume, in the space
        manager. The space manager is an ephemeral object, so it is found through
        the checkpoint map rather than the object map, and it points at chunk-info
        blocks. Each chunk covers a fixed run of blocks and carries a bitmap
        address; a chunk with no bitmap is entirely free.

        **The bits run least significant first**, the same way round as NTFS and
        the opposite of HFS+. A count of free blocks cannot tell the two orders
        apart, because a byte holds the same number of zero bits either way. What
        tells them apart is position: read the other way round, this container
        reports its own superblock at block zero as free.

        Offsets are into the image rather than the container, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering. An empty list means the space manager
        could not be read, which a caller must not read as "nothing is free".
        """
        block = self.block_size
        oid = struct.unpack_from("<Q", self._nx, APFS_NX_SPACEMAN_OID_OFF)[0]
        at = self._ephemeral(oid) if oid else None
        if not at:
            return []
        sm = self.block(at)
        if len(sm) < 96 or (struct.unpack_from("<I", sm, 24)[0] & APFS_OBJ_TYPE_MASK
                            != APFS_OBJECT_TYPE_SPACEMAN):
            return []
        dev = APFS_SM_DEV_MAIN_OFF
        cib_count, cab_count = struct.unpack_from("<II", sm, dev + 16)
        addr_off = struct.unpack_from("<I", sm, dev + 32)[0]
        count = cab_count or cib_count
        if not count or addr_off + count * 8 > len(sm):
            return []
        addrs = list(struct.unpack_from(f"<{count}Q", sm, addr_off))
        if cab_count:                                # one more level of indirection
            cibs = []
            for a in addrs:
                cab = self.block(a)
                if len(cab) < 40:
                    continue
                n = struct.unpack_from("<I", cab, 36)[0]
                n = min(n, (len(cab) - 40) // 8)
                cibs += list(struct.unpack_from(f"<{n}Q", cab, 40))
            addrs = cibs

        runs = []
        for a in addrs:
            cib = self.block(a)
            if len(cib) < 40:
                continue
            n = struct.unpack_from("<I", cib, 36)[0]
            for k in range(min(n, (len(cib) - 40) // APFS_CI_SIZE)):
                o = 40 + k * APFS_CI_SIZE
                ci_addr = struct.unpack_from("<Q", cib, o + 8)[0]
                ci_blocks, ci_free = struct.unpack_from("<II", cib, o + 16)
                ci_bitmap = struct.unpack_from("<Q", cib, o + 24)[0]
                if ci_addr >= self.block_count or not ci_blocks:
                    continue
                ci_blocks = min(ci_blocks, self.block_count - ci_addr)
                if not ci_bitmap:                    # no bitmap means wholly free
                    if ci_free:
                        runs.append((ci_addr, ci_blocks))
                    continue
                bits = self.block(ci_bitmap)
                total = min(len(bits) * 8, ci_blocks)
                start, pos = None, 0
                while pos < total:
                    byte = bits[pos >> 3]
                    if not (pos & 7) and pos + 8 <= total and byte in (0x00, 0xFF):
                        if byte == 0x00:
                            if start is None:
                                start = pos
                        elif start is not None:
                            runs.append((ci_addr + start, pos - start))
                            start = None
                        pos += 8
                        continue
                    if byte & (1 << (pos & 7)):
                        if start is not None:
                            runs.append((ci_addr + start, pos - start))
                            start = None
                    elif start is None:
                        start = pos
                    pos += 1
                if start is not None:
                    runs.append((ci_addr + start, total - start))

        runs.sort()
        merged = []
        for first, n in runs:                        # chunks abut, so their runs do
            if merged and merged[-1][0] + merged[-1][1] == first:
                merged[-1] = (merged[-1][0], merged[-1][1] + n)
            else:
                merged.append((first, n))
        out = []
        for first, n in merged:
            length = n * block
            if length >= min_bytes:
                out.append((self.base + first * block, length))
        return out

    def _read_omap(self, oid):
        """An object map as a plain dict: every virtual id it holds, to a block.

        The map of a volume this size is small, and reading it once removes a
        tree descent from every block lookup on the walk.
        """
        got = self._omap_cache.get(oid)
        if got is not None:
            return got
        raw = self.block(oid)
        if len(raw) < 56:
            raise ValueError("the object map is unreadable")
        tree_oid = struct.unpack_from("<Q", raw, 48)[0]
        out = {}
        self._omap_cache[oid] = out
        tree = _ApfsBtree(self, tree_oid, physical=True)
        for key, val in tree.search((0, 0), _apfs_omap_key):
            if len(key) < 16 or len(val) < 16:
                continue
            o, xid = struct.unpack_from("<QQ", key, 0)
            flags, _size, paddr = struct.unpack_from("<IIQ", val, 0)
            prev = out.get(o)
            if prev is None or xid >= prev[0]:
                out[o] = (xid, paddr, flags)
        # the blocks whose objects the map marks encrypted, which an opened
        # volume's key decrypts (see _apply_key)
        self._omap_enc[oid] = {p for _x, p, f in out.values() if f & APFS_OMAP_VAL_ENCRYPTED}
        out = {o: p for o, (_x, p, _f) in out.items()}
        self._omap_cache[oid] = out
        return out

    # -- records -----------------------------------------------------------
    def prime_records(self, max_records=APFS_PRIME_MAX_RECORDS):
        """Read every volume's directory records, inodes and extended
        attributes once, in one pass over the tree's leaves.

        The tree is keyed on (object id, record type), so a lookup is a bisect
        of the leaf list and a parse of the leaf it lands in. That is cheap on
        its own and a listing does it several times per file, which means the
        same leaf block is read and parsed again for every entry that happens
        to live in it. Measured over the first 40,000 entries of a 32 GB macOS
        acquisition: 216,889 searches, 5.4 per entry, and 88,566 leaf parses,
        2.2 per entry, for 4.48 s of 5.19 s.

        One ordered pass parses each leaf exactly once and answers every later
        lookup from memory. Nothing else changes: listdir(), entry() and the
        rest read the same records through the same code and only the route
        they arrive by is different.

        The cost is memory, roughly proportional to the number of files, and
        it is worth it for a full listing and not for reading a few files. A
        volume with more than ``max_records`` of them is left unprimed and
        searched the ordinary way, so a volume too large to hold is slow rather
        than fatal. Nothing calls this on its own; walk_all() does when it is
        asked for a whole volume.

        Returns the volume indexes it primed, which is what a test asserts
        against and what tells a caller the cap was reached.
        """
        was = self._current
        done = []
        for index in range(len(self.volumes)):
            state = self._state.get(index, {})
            if state.get("primed") is not None:
                done.append(index)
                continue
            if state.get("prime_capped"):
                continue
            try:
                self._open_volume(index)
            except Exception:                       # pylint: disable=broad-except
                continue                            # identification says why
            table, held = {}, 0
            tree = self._tree
            for _first, block in tree.leaves(_apfs_fs_key):
                _flags, recs = tree.records(self.block(block))
                for key, val in recs:
                    k = _apfs_fs_key(key)
                    if k is not None and k[1] in APFS_PRIMED_TYPES:
                        table.setdefault(k, []).append((key, val))
                        held += 1
                if held > max_records:
                    break
            if held > max_records:
                table = None                        # too large to hold; walk it
                self._state[index]["prime_capped"] = True
            self._state[index]["primed"] = table
            self._primed = table
            if table is not None:
                done.append(index)
        if was is not None and was != self._current:
            self._open_volume(was)
        return done

    def _records(self, oid, rtype):
        """Every file-system record of one object id and one record type."""
        want = (oid, rtype)
        primed = self._primed
        if primed is not None and rtype in APFS_PRIMED_TYPES:
            for key, val in primed.get(want, ()):
                yield key, val
            return
        for key, val in self._tree.search(want, _apfs_fs_key):
            k = _apfs_fs_key(key)
            if k is None or k < want:
                continue
            if k != want:
                if k > want:
                    return
                continue
            yield key, val

    def _inode(self, oid):
        got = self._inodes.get(oid)
        if got is None:
            for _key, val in self._records(oid, APFS_TYPE_INODE):
                got = val
                break
            self._inodes[oid] = got
        return got

    def _dstream(self, oid):
        """(size, private id) for a file, from the inode's extended fields.

        The size lives in an extended field rather than in the inode's fixed
        part, and the private id is what the file's extents are keyed by, which
        is not always the object id itself.
        """
        val = self._inode(oid)
        if not val or len(val) < 92:
            return 0, oid
        private = struct.unpack_from("<Q", val, 8)[0]
        fields = _apfs_xfields(val, 92)
        blob = fields.get(APFS_INO_EXT_TYPE_DSTREAM)
        size = struct.unpack_from("<Q", blob, 0)[0] if blob and len(blob) >= 8 else 0
        return size, (private or oid)

    def _read_fext(self, sb):
        """{stream id: [(logical, block, length)]} from a sealed volume's own
        extent tree, or None when the field does not name one.

        The tree is keyed by (stream id, offset within the file) and its value
        is a length with flags and a physical block, the same pair a file
        extent record carries in an ordinary volume. It is read once: a sealed
        system volume has a few hundred thousand extents and a descent per file
        would walk the tree once per file.
        """
        if len(sb) < APFS_FEXT_TREE_OFF + 8:
            return None
        oid = struct.unpack_from("<Q", sb, APFS_FEXT_TREE_OFF)[0]
        if not oid:
            return None
        try:
            node = self.block(oid)
        except Exception:                            # pylint: disable=broad-except
            return None
        if len(node) < self.block_size:
            return None
        flags = struct.unpack_from("<H", node, APFS_OBJ_HDR)[0]
        info = struct.unpack_from("<I", node, len(node) - APFS_BTREE_INFO)[0]
        # The field is only believed when what it points at is a physical
        # B-tree root. Anything else and the offset is wrong for this volume,
        # which must read as "no extent tree" rather than as whatever sits there.
        if not (flags & APFS_BTNODE_ROOT) or not (info & APFS_BTREE_PHYSICAL):
            return None
        out = {}
        tree = _ApfsBtree(self, oid, physical=True)
        for key, val in tree.search(
                (0, 0), lambda k: struct.unpack_from("<QQ", k, 0)
                if len(k) >= 16 else (0, 0)):
            if len(key) < 16 or len(val) < 16:
                continue
            stream, logical = struct.unpack_from("<QQ", key, 0)
            len_flags, phys = struct.unpack_from("<QQ", val, 0)
            out.setdefault(stream, []).append(
                (logical, phys, len_flags & 0x00FFFFFFFFFFFFFF))
        for runs in out.values():
            runs.sort()
        return out

    def _extents(self, private_id):
        """[(logical offset, block, length)] for a stream, in order."""
        return [(logical, phys, length)
                for logical, phys, length, _crypto in self._runs(private_id)]

    def _runs(self, private_id):
        """[(logical offset, block, length, crypto_id)] for a stream, in order.

        crypto_id is the field after the physical block in j_file_extent_val_t.
        On a volume whose files all use the volume key it is where the extent's
        AES-XTS tweak starts, in blocks (see _iter_stream); a sealed volume's own
        extent tree carries no such field, and 0 stands in."""
        if self._fext is not None:
            return [(logical, phys, length, 0)
                    for logical, phys, length in self._fext.get(private_id, [])]
        out = []
        for key, val in self._records(private_id, APFS_TYPE_FILE_EXTENT):
            if len(key) < 16 or len(val) < 16:
                continue
            logical = struct.unpack_from("<Q", key, 8)[0]
            len_flags, phys = struct.unpack_from("<QQ", val, 0)
            crypto = struct.unpack_from("<Q", val, 16)[0] if len(val) >= 24 else 0
            out.append((logical, phys, len_flags & 0x00FFFFFFFFFFFFFF, crypto))
        out.sort()
        return out

    def _xattr(self, oid, name):
        """One extended attribute: its bytes when it is embedded, or the stream
        it names when it is not."""
        for key, val in self._records(oid, APFS_TYPE_XATTR):
            if len(key) < 12 or len(val) < 4:
                continue
            nlen = struct.unpack_from("<H", key, 8)[0]
            got = key[10:10 + nlen].split(b"\x00")[0].decode("utf-8", "replace")
            if got != name:
                continue
            flags, xlen = struct.unpack_from("<HH", val, 0)
            body = val[4:4 + xlen]
            if flags & APFS_XATTR_DATA_EMBEDDED:
                return ("data", body)
            if flags & APFS_XATTR_DATA_STREAM and len(body) >= 16:
                stream_id = struct.unpack_from("<Q", body, 0)[0]
                size = struct.unpack_from("<Q", body, 8)[0]
                return ("stream", (stream_id, size))
        return None

    def _read_stream(self, private_id, want, size_cap=None):
        """Bytes of a stream, sparse extents reading as the zeros they stand for."""
        out = b"".join(self._iter_stream(private_id, want))
        if size_cap is not None:
            return out[:size_cap]
        return out[:want]

    def _iter_stream(self, private_id, want, piece=1 << 20):
        """A stream's first ``want`` bytes, in pieces of at most ``piece`` bytes.

        On a volume opened with its key each extent is decrypted as AES-XTS with
        the volume key, and the tweak of its first 512-byte sector is its
        crypto_id counted in blocks, not its current block: libfsapfs computes
        a data block's tweak as the extent's crypto_id plus the block's offset
        in the extent (libfsapfs_file_system_data_handle.c, lines 274 to 307 at
        f63c83b), times the sectors per block (libfsapfs_data_block.c, lines
        388 and 389). On every extent of both test volumes the two are equal;
        the self-test moves one extent to prove the tweak follows crypto_id."""
        cipher, bs = self._cipher, self.block_size
        if cipher is not None and self._fext is not None:
            raise ApfsUnreadable("a sealed volume's extents carry no tweak to decrypt "
                                 "them with")
        pos = 0
        for logical, phys, length, crypto in self._runs(private_id):
            if pos >= want:
                break
            if logical > pos:
                gap = min(logical - pos, want - pos)
                while gap:
                    n = min(gap, piece)
                    yield b"\x00" * n
                    pos, gap = pos + n, gap - n
            take = min(length, want - pos)
            if take <= 0:
                continue
            done = 0
            while done < take:
                n = min(piece, take - done)
                if phys == 0:
                    data = b"\x00" * n
                elif cipher is None:
                    data = read_at(self.fh, self.base + phys * bs + done, n)
                else:
                    raw = read_at(self.fh, self.base + phys * bs + done, -(-n // 512) * 512)
                    data = _xts_crypt(cipher, raw, crypto * (bs // 512) + done // 512)[:n]
                if data:
                    yield data
                done, pos = done + len(data), pos + len(data)
                if len(data) < n:
                    break

    # -- the walker surface ------------------------------------------------
    def inode(self, node):
        return node

    def entry(self, node):
        if node == APFS_CONTAINER:
            return (S_IFDIR | 0o755, 0, 0)
        oid = self._select(node)
        if oid is None:
            return None
        val = self._inode(oid)
        if not val or len(val) < 82:
            return None
        mode = struct.unpack_from("<H", val, 80)[0]
        mtime = apfs_time(struct.unpack_from("<Q", val, 24)[0])
        if mode & S_IFDIR == S_IFDIR:
            return (mode, 0, mtime)
        size, _private = self._dstream(oid)
        blob = self._decmpfs_of(oid, val)
        if blob:
            head = blob[1] if blob[0] == "data" else self._read_stream(blob[1][0], 16)
            if len(head) >= 16 and head[0:4] == b"fpmc":
                size = struct.unpack_from("<Q", head, 8)[0]
        return (mode or 0o100644, size, mtime)

    def times(self, node):
        """{"modified", "accessed", "changed", "created"} as (seconds,
        nanoseconds) since 1970-01-01 UTC, or None for the container or a node
        with no inode. The shape BtrfsWalker.times() gives.

        j_inode_val_t (Apple File System Reference, edition 2020-06-22, pages
        74-75) holds create_time, mod_time, change_time and access_time at
        offsets 16, 24, 32 and 40, each a uint64_t count of nanoseconds since
        1970-01-01 00:00 UTC, disregarding leap seconds: "the time that this
        record was created", "last modified", "attributes were last modified"
        (the change time) and "last accessed". The reference gives no unset
        value, so each is returned as stored, 0 included. entry() keeps its
        whole-second mod_time with 0 for a value it treats as unset."""
        if node == APFS_CONTAINER:
            return None
        oid = self._select(node)
        if oid is None:
            return None
        val = self._inode(oid)
        if not val or len(val) < 48:
            return None
        created, modified, changed, accessed = struct.unpack_from("<4Q", val, 16)
        return {"modified": divmod(modified, APFS_NANO), "accessed": divmod(accessed, APFS_NANO),
                "changed": divmod(changed, APFS_NANO), "created": divmod(created, APFS_NANO)}

    def allocation(self, node):
        """What the volume stores for a file, beside the size it records. The
        same dict NtfsWalker.allocation() returns, less the two NTFS fields:

        ``size``         the bytes read_file() returns, as entry() gives them
        ``stored``       the bytes the volume holds for the content: the data
                         stream's alloced_size less its sparse bytes, or for a
                         decmpfs file the compressed bytes in the attribute or
                         in the resource fork it names
        ``sparse``       the inode is flagged sparse or records sparse bytes
        ``compression``  "decmpfs" or ""
        ``bsd_flags``    the inode's BSD flags
        ``placeholder``  True when the BSD flags carry SF_DATALESS, a file
                         whose content a file provider holds. Taken from the
                         published flag and not exercised: no image holding
                         such a file has been read, so what its data stream
                         records is not known here.

        None for the container, a directory, or a node with no inode.
        """
        if node == APFS_CONTAINER:
            return None
        ent = self.entry(node)
        oid = self._select(node)
        val = self._inode(oid) if oid is not None else None
        if not ent or not val or len(val) < 92 or ent[0] & S_IFMT != S_IFREG:
            return None
        internal = struct.unpack_from("<Q", val, APFS_INODE_INTERNAL_FLAGS_OFF)[0]
        bsd = struct.unpack_from("<I", val, APFS_INODE_BSD_FLAGS_OFF)[0]
        fields = _apfs_xfields(val, 92)
        blob = fields.get(APFS_INO_EXT_TYPE_DSTREAM)
        alloced = struct.unpack_from("<Q", blob, 8)[0] if blob and len(blob) >= 16 else 0
        blob = fields.get(APFS_INO_EXT_TYPE_SPARSE_BYTES)
        holes = struct.unpack_from("<Q", blob, 0)[0] if blob and len(blob) >= 8 else 0
        stored = max(alloced - holes, 0)
        compression = ""
        packed = self._decmpfs_of(oid, val)
        if packed:
            compression = "decmpfs"
            # the attribute is embedded in the record, or kept in a stream of its own
            stored = len(packed[1]) if packed[0] == "data" else packed[1][1]
            fork = self._xattr(oid, APFS_RESOURCE_FORK)
            if fork and fork[0] == "stream":
                stored += fork[1][1]
            elif fork:
                stored += len(fork[1])
        return {"size": ent[1], "stored": stored,
                "sparse": bool(internal & APFS_INODE_IS_SPARSE or holes),
                "compression": compression, "bsd_flags": bsd,
                "placeholder": bool(bsd & APFS_SF_DATALESS)}

    def listdir(self, node):
        if node == APFS_CONTAINER:
            # The container's children are its volumes, so every one of them is
            # reachable from a single walk and lands under its own name.
            return [(name or f"volume{i}", (i << APFS_VOL_SHIFT) | APFS_ROOT_INO)
                    for i, (_o, _b, name, _f) in enumerate(self.volumes)]
        vol, _ = self._split(node)
        oid = self._select(node)
        if oid is None:
            return []
        out = []
        for key, val in self._records(oid, APFS_TYPE_DIR_REC):
            if len(val) < 8:
                continue
            if self._hashed_names:
                if len(key) < 12:
                    continue
                nlen = struct.unpack_from("<I", key, 8)[0] & 0x3FF
                name = key[12:12 + nlen]
            else:
                if len(key) < 10:
                    continue
                nlen = struct.unpack_from("<H", key, 8)[0]
                name = key[10:10 + nlen]
            name = name.split(b"\x00")[0].decode("utf-8", "replace")
            child = struct.unpack_from("<Q", val, 0)[0]
            if child > APFS_OID_MASK:
                continue                        # an id too large to carry a volume
            if name and name not in (".", ".."):
                out.append((name, (vol << APFS_VOL_SHIFT) | child))
        return out

    def named_streams(self, node):
        """[(name, size)] for every extended attribute held in its own stream.
        Those are bytes the file's own size does not account for."""
        if node == APFS_CONTAINER:
            return []
        oid = self._select(node)
        if oid is None:
            return []
        out = []
        for key, val in self._records(oid, APFS_TYPE_XATTR):
            if len(key) < 12 or len(val) < 4:
                continue
            nlen = struct.unpack_from("<H", key, 8)[0]
            name = key[10:10 + nlen].split(b"\x00")[0].decode("utf-8", "replace")
            flags, xlen = struct.unpack_from("<HH", val, 0)
            if flags & APFS_XATTR_DATA_STREAM and xlen >= 16:
                size = struct.unpack_from("<Q", val, 12)[0]
                if name != APFS_RESOURCE_FORK or size:
                    out.append((name, size))
        return out

    def read_file(self, node, size):
        if node == APFS_CONTAINER:
            return
        vol = self._split(node)[0]
        if vol < len(self.volumes) and self.encryption(vol) == "locked":
            # A node the walk listed while the volume was open, asked for in a session
            # without its key: its bytes are ciphertext, and nothing read back is not
            # an empty file.
            raise ApfsUnreadable(f"{self.volumes[vol][2] or f'volume {vol}'} is encrypted "
                                 f"and locked here, so this file is not read")
        oid = self._select(node)
        if oid is None:
            return
        val = self._inode(oid)
        if not val:
            return
        # A symbolic link keeps its target in an attribute rather than in a
        # stream, so a link has no extents to read and the target is the content.
        if len(val) >= 82 and (struct.unpack_from("<H", val, 80)[0] & 0o170000) == S_IFLNK:
            link = self._xattr(oid, APFS_SYMLINK)
            if link and link[0] == "data":
                yield link[1].split(b"\x00")[0]
            return
        blob = self._decmpfs_of(oid, val)
        if blob:
            yield from self._read_compressed(oid, blob)
            return
        stream_size, private = self._dstream(oid)
        want = stream_size if size is None else min(size, stream_size or size)
        # A file that says it holds bytes and has no extent anywhere must not
        # read as an empty file. On a sealed volume the extents live in their
        # own tree, and if that tree is not found this is the shape the failure
        # takes: every uncompressed file comes back zero bytes, which an
        # extraction would write out as a real empty file and nothing would say
        # otherwise.
        if want and private and not self._extents(private):
            raise ApfsUnreadable(
                f"the file says it holds {want:,} bytes and no extent records "
                f"for it were found" + (", which is what a sealed volume looks "
                "like when its extent tree was not read" if self.sealed else ""))
        # One pass over the extents, a piece at a time. This used to read the whole
        # stream again for every megabyte it handed back.
        yield from self._iter_stream(private, want)

    def _decmpfs_of(self, oid, val):
        """The compression attribute of a file macOS reads as compressed, or None.
        A file is compressed only when its BSD flags carry UF_COMPRESSED; an
        attribute on a file without the flag is not its content, so the data
        stream is read as stored and the attribute is recorded in damage, once."""
        blob = self._xattr(oid, APFS_DECMPFS)
        if not blob or not val or len(val) < APFS_INODE_BSD_FLAGS_OFF + 4:
            return None
        if struct.unpack_from("<I", val, APFS_INODE_BSD_FLAGS_OFF)[0] & UF_COMPRESSED:
            return blob
        if oid not in self._unflagged:
            self._unflagged.add(oid)
            self.damage.append(f"object {oid}: carries a com.apple.decmpfs attribute but is not "
                               f"flagged compressed (UF_COMPRESSED clear), so its data stream is "
                               f"read as stored, as macOS reads it, and the attribute is not decoded")
        return None

    def _read_compressed(self, oid, blob):
        """A file whose data is held by the decmpfs attribute, in the attribute
        itself or in the resource fork it names: see decmpfs_read() for the
        methods read and refused. The fork is read a piece at a time, in order,
        so a compressed file of gigabytes is not held in memory whole."""
        kind, payload = blob
        if kind != "data" and payload[1] > DECMPFS_MAX_ATTR:
            raise ApfsUnreadable(f"the compression attribute is {payload[1]:,} bytes, more than "
                                 f"the {DECMPFS_MAX_ATTR:,} macOS itself will read")
        attr = payload if kind == "data" else self._read_stream(payload[0], payload[1])
        head = decmpfs_header(attr)
        if head is None:
            raise ApfsUnreadable("the compression attribute is not one this reader knows")
        method, size = head
        fork = None
        if DECMPFS_METHODS.get(method, ("", ""))[1] == "fork":
            got = self._xattr(oid, APFS_RESOURCE_FORK)
            if got and got[0] == "stream":
                fork = _ForwardFork(self._iter_stream(got[1][0], got[1][1]), got[1][1])
            elif got:
                fork = _BytesFork(got[1])
        try:
            yield from decmpfs_read(method, size, attr[16:], fork)
        except (DecompressError, struct.error) as exc:
            raise ApfsUnreadable(str(exc)) from None



def _apfs_omap_key(key):
    return struct.unpack_from("<QQ", key, 0) if len(key) >= 16 else None


def _apfs_fs_key(key):
    """(object id, record type) for a file-system tree key, which is the order
    the tree is sorted in: the id first, then the kind of record."""
    if len(key) < 8:
        return None
    raw = struct.unpack_from("<Q", key, 0)[0]
    return (raw & ((1 << 60) - 1), raw >> 60)


def _apfs_volume_name(sb):
    return sb[704:768].split(b"\x00")[0].decode("utf-8", "replace")


def _apfs_xfields(blob, off):
    """{type: bytes} for an inode's extended fields.

    A count and a used length, then one descriptor per field, then the values
    one after another, each padded up to eight bytes.
    """
    out = {}
    if off + 4 > len(blob):
        return out
    count, _used = struct.unpack_from("<HH", blob, off)
    if count > 64:
        return out
    data = off + 4 + count * 4
    for i in range(count):
        at = off + 4 + i * 4
        if at + 4 > len(blob):
            break
        x_type, _flags, size = struct.unpack_from("<BBH", blob, at)
        if data + size > len(blob):
            break
        out[x_type] = blob[data:data + size]
        data += size + (-size % 8)
    return out


# ---------------------------------------------------------------- HFS+
# Field offsets and structure layouts below come from Apple's Technical Note
# TN1150, "HFS Plus Volume Format", which is the published description of the
# format. No HFS implementation's source was read for this.

HFSP_SIG    = 0x482B          # 'H+', HFS Plus
HFSX_SIG    = 0x4858          # 'HX', HFSX, which differs only in case handling
HFSP_VH_OFF = 1024            # the volume header sits 1024 bytes into the volume
HFSP_ROOT   = 2               # kHFSRootFolderID
HFSP_ALLOC  = 6               # kHFSAllocationFileID
HFSP_ALLOC_FORK = 112         # the allocation file's fork record in the volume header

# B-tree node kinds, TN1150 "B-Trees"
HFSP_LEAF, HFSP_INDEX, HFSP_HEADER, HFSP_MAP = -1, 0, 1, 2

# catalog record types
HFSP_FOLDER, HFSP_FILE, HFSP_FOLDER_THREAD, HFSP_FILE_THREAD = 1, 2, 3, 4

# HFS+ counts seconds from 1904-01-01; this is the gap to the Unix epoch.
HFSP_EPOCH_DELTA = 2082844800
# A catalog file or folder record's flags bit saying its dates are Unix seconds
# rather than seconds since 1904 (kHFSCatExpandedTimesMask, core/hfs_format.h in
# Apple's hfs-715.120.4, 124b970fd5390f1c2cd6f985478616a04f6eeb1f).
HFSP_CAT_EXPANDED_TIMES = 0x1000

# A hard link is a file whose Finder type and creator say so; the number of the
# indirect node it points at is in the BSD info's special field.
HFSP_HARD_LINK_TYPE    = b"hlnk"
HFSP_HARD_LINK_CREATOR = b"hfs+"
HFSP_PRIVATE_DATA = "\x00\x00\x00\x00HFS+ Private Data"

HFSP_DECMPFS = "com.apple.decmpfs"
HFSP_DECMPFS_MAGIC = b"fpmc"


class HfsUnreadable(Exception):
    """A file whose bytes this walker will not guess at: a compression this
    reader does not implement. Raised rather than returning short data, because
    a short read would be indistinguishable from a small file."""


def hfs_time(v):
    """An HFS+ date as Unix seconds, or 0 when unset or out of range."""
    if not v:
        return 0
    sec = v - HFSP_EPOCH_DELTA
    return sec if -2208988800 < sec < 4102444800 else 0


def _hfs_fork(buf, off):
    """(logical size, [(start block, block count)]) from an 80-byte fork record.

    The eight descriptors here are the whole fork for most files; a file with
    more fragments than that keeps the rest in the extents overflow tree.
    """
    size, _clump, _blocks = struct.unpack_from(">QII", buf, off)
    extents = []
    for i in range(8):
        start, count = struct.unpack_from(">II", buf, off + 16 + i * 8)
        if count:
            extents.append((start, count))
    return size, extents


def _hfs_name(buf, off, posix=False):
    """An HFSUniStr255: a length in UTF-16 units, then that many big-endian units.

    With ``posix``, a catalog name as macOS's POSIX layer shows it: a file created
    there as "a:b.txt" is stored in the catalog as "a/b.txt" (newfs_hfs and macOS
    27, measured), and macOS swaps the two characters back, so it is one name,
    not a folder "a" holding "b.txt"."""
    n = struct.unpack_from(">H", buf, off)[0]
    if n > 255:
        return "", off + 2
    end = off + 2 + n * 2
    name = buf[off + 2:end].decode("utf-16-be", "replace")
    if posix:
        name = name.translate(_HFS_POSIX_SWAP)
    return name, end


_HFS_POSIX_SWAP = str.maketrans({"/": ":", ":": "/"})


class _HfsTree:
    """One B-tree of the volume, addressed by node number through its own fork."""

    def __init__(self, vol, size, extents, name):
        self.vol, self.size, self.extents, self.name = vol, size, extents, name
        head = self._raw(0, 512)
        if len(head) < 120:
            raise ValueError(f"the {name} tree has no header node")
        (depth, root, _leaf_recs, first_leaf, _last_leaf, node_size,
         self.max_key, _total, _free) = struct.unpack_from(">HIIIIHHII", head, 14)
        self.depth, self.root, self.first_leaf = depth, root, first_leaf
        self.node_size = node_size or 4096
        self.key_compare = head[14 + 33] if len(head) > 47 else 0

    def _raw(self, offset, count):
        """Bytes at a byte offset within the tree's fork."""
        out, pos = bytearray(), 0
        block = self.vol.block_size
        for start, blocks in self.extents:
            span = blocks * block
            if pos + span <= offset:
                pos += span
                continue
            skip = max(0, offset - pos)
            take = min(span - skip, count - len(out))
            out += read_at(self.vol.fh,
                           self.vol.base + start * block + skip, take)
            pos += span
            if len(out) >= count:
                break
        return bytes(out)

    def node(self, number):
        return self._raw(number * self.node_size, self.node_size)

    @staticmethod
    def records(node):
        """[(key, data)] for one node, plus its descriptor.

        A node keeps an array of record offsets at its very end, one per record
        and one more for the free space, counted backwards from the end.
        """
        if len(node) < 14:
            return None, []
        f_link, _b_link, kind, _height, count = struct.unpack_from(">IIbBH", node, 0)
        out = []
        for i in range(count):
            at = len(node) - 2 * (i + 1)
            end_at = len(node) - 2 * (i + 2)
            if end_at < 0:
                break
            start = struct.unpack_from(">H", node, at)[0]
            end = struct.unpack_from(">H", node, end_at)[0]
            if not 14 <= start < end <= len(node):
                continue
            rec = node[start:end]
            klen = struct.unpack_from(">H", rec, 0)[0]
            key = rec[2:2 + klen]
            data_at = 2 + klen + ((2 + klen) & 1)     # records are word aligned
            out.append((key, rec[data_at:]))
        return (kind, f_link), out

    def find(self, want, key_of):
        """Walk down to the first leaf record whose key is not less than ``want``.

        ``key_of`` turns a raw key into something comparable, and the comparison
        is deliberately strict. Every record of one directory shares a parent id,
        so several index entries can carry that id with different names; taking
        the last one that is not GREATER would land on the last leaf of the run
        and lose everything before it. Measured on a 400-entry directory: 10
        children found instead of 400. Taking the last entry strictly less lands
        at or before the first of them, and the caller skips what comes early.
        """
        node_no = self.root
        for _ in range(max(self.depth, 1) + 8):
            node = self.node(node_no)
            desc, recs = self.records(node)
            if not desc or not recs:
                return None
            kind = desc[0]
            if kind == HFSP_LEAF:
                return node_no
            if kind != HFSP_INDEX:
                # Only an index node carries pointers to follow. A tree that is
                # allocated but empty says root 0, depth 0, and node 0 is its
                # own header, so a descent lands here and would otherwise read
                # the header's records as pointers. Every HFS+ volume with no
                # extended attributes and no fragmented file has that shape.
                return None
            nxt = struct.unpack_from(">I", recs[0][1], 0)[0]
            for key, data in recs:
                if key_of(key) is None:
                    continue
                if key_of(key) < want:
                    nxt = struct.unpack_from(">I", data, 0)[0]
                else:
                    break
            if nxt == node_no:
                return None
            node_no = nxt
        return None

    def walk_from(self, node_no):
        """Leaf records from this node onward, following the leaf chain."""
        seen = 0
        while node_no and seen < 1 << 20:
            node = self.node(node_no)
            desc, recs = self.records(node)
            if not desc or desc[0] != HFSP_LEAF:
                return
            for key, data in recs:
                yield key, data
                seen += 1
            node_no = desc[1]


class HfsPlusWalker:
    """List and read files from an HFS+ or HFSX volume, same interface as the
    walkers above. A node is the catalog node id, which is what the catalog
    indexes children by and what makes two names for one file resolve to one
    record.

    What it reads: the catalog B-tree in both its index and leaf forms, forks
    whose fragments outgrew the eight descriptors a catalog record holds and
    continue in the extents overflow tree, symbolic links, hard links through
    the private directory the volume keeps them in, and files compressed with
    the decmpfs attribute: zlib, LZVN, LZFSE or stored, in the attribute or in
    the resource fork (decmpfs_read()).

    What it does not read: a file compressed with LZBITMAP or with a decmpfs
    method this reader does not know. Those are listed with their recorded size
    and refuse to be read rather than yielding the compressed bytes as though
    they were the file.
    """

    root = HFSP_ROOT

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        # a compression attribute on a file not flagged compressed (_decmpfs_of)
        self.damage, self._unflagged = [], set()
        vh = read_at(fh, base + HFSP_VH_OFF, 512)
        if len(vh) < 512:
            raise ValueError("no HFS+ volume header")
        sig, self.version = struct.unpack_from(">HH", vh, 0)
        if sig not in (HFSP_SIG, HFSX_SIG):
            raise ValueError("not an HFS+ volume header")
        self.case_sensitive = sig == HFSX_SIG
        (self.create_date, self.modify_date, _backup, _checked,
         self.file_count, self.folder_count, self.block_size,
         self.total_blocks, self.free_blocks) = struct.unpack_from(">IIIIIIIII", vh, 16)
        if not self.block_size or self.block_size & (self.block_size - 1):
            raise ValueError("the volume header gives an impossible block size")
        self.volume_size = self.total_blocks * self.block_size
        self._catalog = _HfsTree(self, *_hfs_fork(vh, 272), "catalog")
        self._extents = _HfsTree(self, *_hfs_fork(vh, 192), "extents overflow")
        try:
            self._attrs = _HfsTree(self, *_hfs_fork(vh, 352), "attributes")
        except (ValueError, struct.error):
            self._attrs = None                 # a volume with no attributes tree
        self.catalog_node_size = self._catalog.node_size
        self.catalog_depth = self._catalog.depth
        self._cache = {}
        self._private = None

    # -- catalog -----------------------------------------------------------
    @staticmethod
    def _cat_parent(key):
        return struct.unpack_from(">I", key, 0)[0] if len(key) >= 4 else None

    def _children(self, cnid):
        """[(name, child cnid, record)] for one folder, from the catalog."""
        node = self._catalog.find(cnid, self._cat_parent)
        if node is None:
            return []
        out = []
        for key, data in self._catalog.walk_from(node):
            parent = self._cat_parent(key)
            if parent is None or parent < cnid:
                continue
            if parent > cnid:
                break
            if len(data) < 2:
                continue
            kind = struct.unpack_from(">H", data, 0)[0]
            if kind not in (HFSP_FOLDER, HFSP_FILE):
                continue                        # thread records are not children
            name, _ = _hfs_name(key, 4, posix=True)
            if not name:
                continue
            child = struct.unpack_from(">I", data, 8)[0]
            self._cache[child] = data
            out.append((name, child, data))
        return out

    def _record(self, cnid):
        """One catalog record by node id, through its thread record when the
        walk has not already passed it."""
        got = self._cache.get(cnid)
        if got is not None:
            return got
        node = self._catalog.find(cnid, self._cat_parent)
        if node is None:
            return None
        for key, data in self._catalog.walk_from(node):
            parent = self._cat_parent(key)
            if parent is None or parent < cnid:
                continue
            if parent > cnid:
                break
            if len(data) >= 2 and struct.unpack_from(">H", data, 0)[0] in (
                    HFSP_FOLDER_THREAD, HFSP_FILE_THREAD):
                owner = struct.unpack_from(">I", data, 4)[0]
                name, _ = _hfs_name(data, 8, posix=True)
                for child_name, child, rec in self._children(owner):
                    if child_name == name and child == cnid:
                        return rec
        return None

    def _private_dir(self):
        """The node id of the directory a hard link's indirect nodes live in."""
        if self._private is None:
            self._private = 0
            for name, cnid, _rec in self._children(HFSP_ROOT):
                if name == HFSP_PRIVATE_DATA:
                    self._private = cnid
                    break
        return self._private

    def _resolve(self, cnid, rec):
        """A hard link's indirect node, or the record as it stands.

        A hard link is a catalog file carrying the Finder type and creator that
        say so; the file it names lives under the private directory as
        iNode<number>, and the number is in the BSD info.
        """
        if len(rec) < 128 or struct.unpack_from(">H", rec, 0)[0] != HFSP_FILE:
            return cnid, rec
        user_info = rec[48:64]
        if user_info[0:4] != HFSP_HARD_LINK_TYPE or user_info[4:8] != HFSP_HARD_LINK_CREATOR:
            return cnid, rec
        inode = struct.unpack_from(">I", rec, 44)[0]        # permissions.special
        parent = self._private_dir()
        if not parent:
            return cnid, rec
        for name, child, child_rec in self._children(parent):
            if name == f"iNode{inode}":
                return child, child_rec
        return cnid, rec

    # -- forks -------------------------------------------------------------
    def _overflow(self, cnid, resource=False):
        """The extents a fork continues into, from the extents overflow tree."""
        want = (0xFF if resource else 0x00, cnid, 0)

        def key_of(key):
            if len(key) < 10:
                return None
            fork_type = key[0]
            file_id, start = struct.unpack_from(">II", key, 2)
            return (fork_type, file_id, start)

        node = self._extents.find(want, key_of)
        if node is None:
            return []
        out = []
        for key, data in self._extents.walk_from(node):
            k = key_of(key)
            if k is None or k < want:
                continue
            if k[0] != want[0] or k[1] != cnid:
                break
            for i in range(8):
                if 8 * i + 8 > len(data):
                    break
                start, count = struct.unpack_from(">II", data, i * 8)
                if count:
                    out.append((start, count))
        return out

    def _fork(self, cnid, rec, resource=False):
        """(size, extents) for a file's data or resource fork, overflow included."""
        off = 168 if resource else 88
        if len(rec) < off + 80:
            return 0, []
        size, extents = _hfs_fork(rec, off)
        covered = sum(c for _s, c in extents)
        need = -(-size // self.block_size) if self.block_size else 0
        if covered < need:
            extents += self._overflow(cnid, resource)
        return size, extents

    def _read_extents(self, extents, want, start=0):
        out, pos = bytearray(), 0
        for first, count in extents:
            span = count * self.block_size
            if pos + span <= start:
                pos += span
                continue
            skip = max(0, start - pos)
            take = min(span - skip, want - len(out))
            out += read_at(self.fh,
                           self.base + first * self.block_size + skip, take)
            pos += span
            if len(out) >= want:
                break
        return bytes(out[:want])

    # -- attributes --------------------------------------------------------
    def _xattr(self, cnid, name):
        """One extended attribute's bytes, or None. Only the inline form is
        read: an attribute large enough to need its own fork is not one this
        walker consumes."""
        if self._attrs is None:
            return None

        def key_of(key):
            if len(key) < 8:
                return None
            return struct.unpack_from(">I", key, 2)[0]

        node = self._attrs.find(cnid, key_of)
        if node is None:
            return None
        for key, data in self._attrs.walk_from(node):
            k = key_of(key)
            if k is None or k < cnid:
                continue
            if k > cnid:
                break
            # HFSPlusAttrKey with its length word already stripped: pad, file
            # id, start block, then the name's length in UTF-16 units at 10 and
            # the name itself at 12.
            got, _ = _hfs_name(key, 10)
            if got != name or len(data) < 16:
                continue
            if struct.unpack_from(">I", data, 0)[0] != 0x10:    # inline data
                continue
            size = struct.unpack_from(">I", data, 12)[0]
            return data[16:16 + size]
        return None

    # -- the walker surface ------------------------------------------------
    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        HFS+ keeps an allocation file, one bit per allocation block, set when the
        block is in use. Its fork record sits in the volume header, so it is read
        the same way any other fork is, and it continues into the extents
        overflow tree if it outgrew its eight descriptors.

        **The bits run most significant first**, which is the opposite of NTFS
        and exFAT: the first bit of the bitmap is the top bit of the first byte
        (Apple TN1150). A count of free blocks cannot tell the two orders apart,
        because a byte holds the same number of zero bits either way. What tells
        them apart is position, and reading this volume the wrong way round
        reports blocks that live files occupy as free.

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.
        """
        block = self.block_size
        if not block or not self.total_blocks:
            return []
        vh = read_at(self.fh, self.base + HFSP_VH_OFF, 512)
        if len(vh) < 512:
            return []
        size, extents = _hfs_fork(vh, HFSP_ALLOC_FORK)
        need = (self.total_blocks + 7) // 8
        if sum(c for _s, c in extents) * block < min(size or need, need):
            try:
                extents = extents + self._overflow(HFSP_ALLOC)
            except (ValueError, struct.error):
                pass                             # what the header holds is all there is
        bits = self._read_extents(extents, need, 0)
        if not bits:
            return []
        total = min(len(bits) * 8, self.total_blocks)

        runs, run_start, pos = [], None, 0
        while pos < total:
            byte = bits[pos >> 3]
            if not (pos & 7) and pos + 8 <= total and byte in (0x00, 0xFF):
                if byte == 0x00:                 # eight free blocks
                    if run_start is None:
                        run_start = pos
                elif run_start is not None:      # eight used ones
                    runs.append((run_start, pos - run_start))
                    run_start = None
                pos += 8
                continue
            if byte & (0x80 >> (pos & 7)):
                if run_start is not None:
                    runs.append((run_start, pos - run_start))
                    run_start = None
            elif run_start is None:
                run_start = pos
            pos += 1
        if run_start is not None:
            runs.append((run_start, total - run_start))

        out = []
        for first, n in runs:
            length = n * block
            if length >= min_bytes:
                out.append((self.base + first * block, length))
        return out

    def inode(self, cnid):
        return cnid

    def entry(self, cnid):
        rec = self._record(cnid)
        if not rec or len(rec) < 2:
            return None
        kind = struct.unpack_from(">H", rec, 0)[0]
        if kind == HFSP_FOLDER:
            mtime = hfs_time(struct.unpack_from(">I", rec, 16)[0])
            mode = struct.unpack_from(">H", rec, 42)[0] or (S_IFDIR | 0o755)
            return (mode | S_IFDIR, 0, mtime)
        if kind != HFSP_FILE:
            return None
        target, rec = self._resolve(cnid, rec)
        mtime = hfs_time(struct.unpack_from(">I", rec, 16)[0])
        mode = struct.unpack_from(">H", rec, 42)[0]
        size, _extents = self._fork(target, rec)
        blob = self._decmpfs_of(target, rec)
        if blob and len(blob) >= 16:
            size = struct.unpack_from("<Q", blob, 8)[0]
        return (mode or 0o100644, size, mtime)

    def times(self, cnid):
        """{"modified", "accessed", "changed", "created", "backup"} as (seconds,
        0) since 1970-01-01 UTC, each None where the record holds no date, or
        None for a node with no file or folder record. A hard link gives its
        indirect node's dates, as entry() gives its size. The four shared names
        are the shape BtrfsWalker.times() gives; "backup" has no counterpart.

        TN1150 ("HFS Plus Volume Format", HFSPlusCatalogFolder and
        HFSPlusCatalogFile, and "HFS Plus Dates") puts createDate,
        contentModDate, attributeModDate, accessDate and backupDate at the same
        offsets, 12 to 28, in both records: UInt32 seconds since 1904-01-01 GMT.
        Only the volume header's createDate is local time, and it is not read
        here. attributeModDate is "the last date and time that any field in the
        file's catalog record was changed", which TN1150 says the Mac OS X BSD
        APIs return as st_ctime, so it is the change time.

        Apple's HFS (hfs-715.120.4, 124b970fd5390f1c2cd6f985478616a04f6eeb1f)
        adds two rules TN1150 predates. A record whose flags carry
        kHFSCatExpandedTimesMask stores Unix seconds instead (hfs_catalog.c reads
        each record's own bit; to_bsd_time in core/MacOSStubs.c returns them
        unconverted, and to_hfs_time says zero is then 1970-01-01). Otherwise
        to_hfs_time stores an unset time as 0 ("treat as uninitialized"), so a
        stored 0 is None. A date stored before 1970 is returned as TN1150 counts
        it, negative; macOS's own to_bsd_time shows it as 1970-01-01."""
        rec = self._record(cnid)
        if not rec or len(rec) < 2:
            return None
        kind = struct.unpack_from(">H", rec, 0)[0]
        if kind == HFSP_FILE:
            _target, rec = self._resolve(cnid, rec)
        elif kind != HFSP_FOLDER:
            return None
        if len(rec) < 32:
            return None
        expanded = struct.unpack_from(">H", rec, 2)[0] & HFSP_CAT_EXPANDED_TIMES

        def stamp(v):
            if expanded:
                return (v, 0)
            return (v - HFSP_EPOCH_DELTA, 0) if v else None

        created, content, attributes, accessed, backup = struct.unpack_from(">5I", rec, 12)
        return {"modified": stamp(content), "accessed": stamp(accessed),
                "changed": stamp(attributes), "created": stamp(created),
                "backup": stamp(backup)}

    def listdir(self, cnid):
        out = []
        for name, child, _rec in self._children(cnid):
            out.append((name, child))
        return out

    def named_streams(self, cnid):
        """[(name, size)] for a resource fork carrying anything. A resource fork
        is content the file's own size does not account for, so it is worth
        saying it is there; it is not listed as a file of its own."""
        rec = self._record(cnid)
        if not rec or len(rec) < 2 or struct.unpack_from(">H", rec, 0)[0] != HFSP_FILE:
            return []
        target, rec = self._resolve(cnid, rec)
        size, _extents = self._fork(target, rec, resource=True)
        return [("rsrc", size)] if size else []

    def read_file(self, cnid, size):
        rec = self._record(cnid)
        if not rec or len(rec) < 2 or struct.unpack_from(">H", rec, 0)[0] != HFSP_FILE:
            return
        target, rec = self._resolve(cnid, rec)
        blob = self._decmpfs_of(target, rec)
        if blob:
            yield from self._read_compressed(target, rec, blob)
            return
        fork_size, extents = self._fork(target, rec)
        want = fork_size if size is None else min(size, fork_size)
        done = 0
        while done < want:
            chunk = self._read_extents(extents, min(1 << 20, want - done), done)
            if not chunk:
                break
            yield chunk
            done += len(chunk)

    def _decmpfs_of(self, cnid, rec):
        """The compression attribute of a file macOS reads as compressed, or None.
        The flag is the catalog record's ownerFlags, the low byte of the BSD
        flags, at byte 41 (HFSPlusBSDInfo at 32: ownerID, groupID, adminFlags,
        ownerFlags; Apple TN1150). Without UF_COMPRESSED the data fork is the
        content and the attribute is recorded in damage, once."""
        blob = self._xattr(cnid, HFSP_DECMPFS)
        if not blob or len(rec) < 42:
            return None
        if rec[41] & UF_COMPRESSED:
            return blob
        if cnid not in self._unflagged:
            self._unflagged.add(cnid)
            self.damage.append(f"catalog id {cnid}: carries a com.apple.decmpfs attribute but is "
                               f"not flagged compressed (UF_COMPRESSED clear), so its data fork is "
                               f"read as stored, as macOS reads it, and the attribute is not decoded")
        return None

    def _read_compressed(self, cnid, rec, blob):
        """A file whose data lives in the decmpfs attribute or its resource
        fork: see decmpfs_read() for the methods read and refused."""
        head = decmpfs_header(blob)
        if head is None:
            raise HfsUnreadable("the compression attribute is not one this reader knows")
        method, size = head
        fork = None
        if DECMPFS_METHODS.get(method, ("", ""))[1] == "fork":
            rsize, extents = self._fork(cnid, rec, resource=True)
            if rsize:
                fork = _ExtentFork(self, extents, rsize)
        try:
            yield from decmpfs_read(method, size, blob[16:], fork)
        except (DecompressError, struct.error) as exc:
            raise HfsUnreadable(str(exc)) from None


class _ExtentFork:
    """An HFS+ resource fork read through its extents."""

    def __init__(self, walker, extents, size):
        self.size, self._w, self._extents = size, walker, extents

    def read(self, off, length):
        length = max(min(length, self.size - off), 0)
        return (self._w._read_extents(self._extents, length, off)  # pylint: disable=protected-access
                if length else b"")


class Qnx4Walker:
    """List and read files from a QNX4 filesystem, same interface as the
    walkers above. A node is the kernel's inode number: block * 8 + index of
    the 64-byte inode entry, blocks counted from the partition start."""

    root = QNX4_ROOT_NODE

    def __init__(self, fh, base):
        self.fh, self.base = fh, base

    def _raw(self, num):
        blk, ndx = divmod(num, 8)
        raw = read_at(self.fh,
                      self.base + blk * QNX4_BLOCK + ndx * QNX4_DIRENT,
                      QNX4_DIRENT)
        return raw if len(raw) == QNX4_DIRENT else None

    def inode(self, num):
        return self._raw(num)

    def entry(self, num):
        raw = self._raw(num)
        if not raw:
            return None
        mode = struct.unpack_from("<H", raw, 50)[0]      # di_mode
        size = struct.unpack_from("<I", raw, 16)[0]      # di_size
        mtime = struct.unpack_from("<I", raw, 36)[0]     # di_mtime
        return mode, size, mtime

    def _extents(self, raw):
        """Yield (first_block_1based, size_in_blocks) per extent, following
        the xblk chain exactly as fs/qnx4/inode.c qnx4_block_map() does."""
        first_blk, first_sz = struct.unpack_from("<II", raw, 20)
        nx = struct.unpack_from("<H", raw, 48)[0]        # di_num_xtnts
        if nx >= 1 and first_blk and first_sz:
            yield first_blk, first_sz
        left = nx - 1
        xblk = struct.unpack_from("<I", raw, 28)[0]      # di_xblk
        seen = set()
        while left > 0 and xblk and xblk not in seen:
            seen.add(xblk)
            buf = read_at(self.fh, self.base + (xblk - 1) * QNX4_BLOCK,
                          QNX4_BLOCK)
            if len(buf) < QNX4_BLOCK or buf[496:503] != QNX4_XBLK_SIG:
                return                                   # not a valid xblk
            for i in range(min(buf[8], 60)):             # xblk_num_xtnts
                if left <= 0:
                    return
                b, s = struct.unpack_from("<II", buf, 16 + i * 8)
                if b and s:
                    yield b, s
                left -= 1
            xblk = struct.unpack_from("<I", buf, 0)[0]   # xblk_next_xblk

    def listdir(self, num):
        raw = self._raw(num)
        if not raw:
            return []
        if (struct.unpack_from("<H", raw, 50)[0] & 0o170000) != S_IFDIR:
            return []
        size = struct.unpack_from("<I", raw, 16)[0]
        out, done = [], 0
        for blk, nblks in self._extents(raw):
            for j in range(nblks):
                if done >= size:
                    break
                sbnum = blk - 1 + j
                buf = read_at(self.fh, self.base + sbnum * QNX4_BLOCK,
                              QNX4_BLOCK)
                if len(buf) < QNX4_BLOCK:
                    break
                for ix in range(8):
                    e = buf[ix * QNX4_DIRENT:(ix + 1) * QNX4_DIRENT]
                    if e[0] == 0 or not (e[63] & (QNX4_F_USED | QNX4_F_LINK)):
                        continue                         # fs/qnx4/qnx4.h:94-97
                    if e[63] & QNX4_F_LINK:
                        name = e[0:48].split(b"\x00")[0]
                        iblk = struct.unpack_from("<I", e, 48)[0]
                        child = (iblk - 1) * 8 + e[52]   # fs/qnx4/namei.c:103
                    else:
                        name = e[0:16].split(b"\x00")[0]
                        child = sbnum * 8 + ix
                    name = name.decode("utf-8", "replace")
                    if name not in (".", ".."):
                        out.append((name, child))
                done += QNX4_BLOCK
        return out

    def read_file(self, num, size):
        raw = self._raw(num)
        if not raw:
            return
        left = size
        for blk, nblks in self._extents(raw):
            if left <= 0:
                return
            off = self.base + (blk - 1) * QNX4_BLOCK
            avail = min(nblks * QNX4_BLOCK, left)
            pos = 0
            while pos < avail:
                take = min(1 << 20, avail - pos)
                buf = read_at(self.fh, off + pos, take)
                if len(buf) < take:
                    buf += bytes(take - len(buf))
                yield buf
                pos += take
            left -= avail


def identify_qnx4(fh, base, size=None):
    """Return ("qnx4", lines) if a QNX4 filesystem starts at base, else None.

    Mirrors what the kernel itself requires to mount (fs/qnx4/inode.c
    qnx4_checkroot and qnx4_iget): the superblock's RootDir entry must be
    named "/" with a directory mode and a sane first extent, and the root
    directory's first extent must carry a ".bitmap" entry. Two bytes of "/"
    alone would be a coincidence; the resolved .bitmap name is not.
    """
    sb = read_at(fh, base + QNX4_BLOCK, QNX4_DIRENT)
    if len(sb) < QNX4_DIRENT or sb[0:2] != b"/\x00":
        return None
    if (struct.unpack_from("<H", sb, 50)[0] & 0o170000) != S_IFDIR:
        return None
    first_blk, first_sz = struct.unpack_from("<II", sb, 20)
    if not (1 <= first_blk and 1 <= first_sz <= 65536):
        return None
    bitmap = None
    for j in range(first_sz):
        buf = read_at(fh, base + (first_blk - 1 + j) * QNX4_BLOCK, QNX4_BLOCK)
        if len(buf) < QNX4_BLOCK:
            break
        for ix in range(8):
            e = buf[ix * QNX4_DIRENT:(ix + 1) * QNX4_DIRENT]
            if e[0:8] == b".bitmap\x00":                 # strcmp in checkroot
                bitmap = e
                break
        if bitmap:
            break
    if bitmap is None:
        return None
    bsize = struct.unpack_from("<I", bitmap, 16)[0]      # .bitmap di_size, bytes
    total = bsize * 8         # one bit per block, fs/qnx4/inode.c:142 (statfs)
    mtime = struct.unpack_from("<I", sb, 36)[0]          # RootDir di_mtime
    return "qnx4", [
        f"root dir     block {first_blk:,}, {first_sz} block(s), "
        f"modified {stamp(mtime)}",
        f"volume       {total:,} blocks of 512 ({human(total * QNX4_BLOCK)}) "
        f"per the .bitmap",
        "layout       64-byte inode entries inline in directories; names over "
        "16 bytes linked via .inodes",
    ]


# ---------------------------------------------------------------------------
# QNX flash filesystems: ETFS and EFS.
#
# These are QNX's two on-flash filesystems, the kind a head unit stores its
# manufacturing and configuration data on. QNX does not publish either byte
# layout. Both structures below are transcribed from the Kaitai .ksy specs in
# NetherlandsForensicInstitute/qnxmount (Apache-2.0), a peer institute's
# vehicle-forensics reader. Its ETFS spec cross-references QNX's own fs/etfs.h
# and its EFS spec fs/f3s_spec.h, the same way the qnx6 code above is sourced
# to the Linux driver. The Kaitai runtime is NOT taken as a dependency; only
# the field layouts are transcribed, into the same hand-written struct style,
# so this stays standard library only.
#
# Validated by round-trip against qnxmount's own committed test images: every
# file name, mode, owner, mtime, symlink target and byte of file content
# matched the tar archive built from the same live filesystem, ETFS 32 of 32
# entries and EFS 31 of 31. The tar archives were produced by qnxmount's build
# scripts on QNX, an implementation independent of this one.
#
# Both are typically imaged bare, with no partition table, so they arrive as
# the whole-image region and are read at base 0.
#
# ETFS is transaction based. The flash is a run of fixed-size pages, each
# holding <pagesize> bytes of user data followed by a 16-byte transaction
# record, which on real NAND lives in the spare/out-of-band area:
#     fid u4, cluster u4, nclusters u2, tacode u1, dacode u1, sequence u4
# The live state is rebuilt by keeping, for every (fid, cluster), the record
# with the highest sequence number, and ignoring pages whose transaction code
# is not "ok" or "ecc" (erased and 0xFF-filler pages carry a junk cluster).
# Files are addressed by a fixed file-id scheme from fs/etfs.h: root 0,
# .filetable 1, .badblks 2, .counts 3, .lost+found 4, .reserved 5, first real
# file 6. The .filetable (fid 1) is itself a file whose data is 64-byte entries
# indexed by fid, each carrying a file's parent id, mode, owner, times, size
# and short name; a name longer than 32 bytes is continued in an extension
# entry the short entry points at.
# Source: qnxmount/etfs/parser.ksy and qnxmount/etfs/interface.py, fs/etfs.h.
# ---------------------------------------------------------------------------
ETFS_TRANS_SIZE = 16
ETFS_ENTRY_SIZE = 64
ETFS_FID_ROOT, ETFS_FID_FTABLE = 0, 1
ETFS_RESERVED = {1: ".filetable", 2: ".badblks", 3: ".counts",
                 4: ".lost+found", 5: ".reserved"}
ETFS_PAGE_SIZES = (512, 1024, 2048, 4096, 8192, 16384)


def _etfs_scan_transactions(fh, base, pagesize, n, want_fid=None, cap=None):
    """Yield (page_index, fid, cluster, tacode, sequence) for pages whose
    transaction code is ok or ecc. Reads in blocks to avoid a syscall per page.
    Stops after cap pages if given, and filters to want_fid if given."""
    unit = pagesize + ETFS_TRANS_SIZE
    limit = n if cap is None else min(n, cap)
    BLK = 4096
    start = 0
    while start < limit:
        count = min(BLK, limit - start)
        buf = read_at(fh, base + start * unit, count * unit)
        if len(buf) < count * unit:
            count = len(buf) // unit
        for k in range(count):
            t = buf[k * unit + pagesize: k * unit + unit]
            if len(t) < ETFS_TRANS_SIZE:
                break
            fid, cluster = struct.unpack_from("<II", t, 0)
            if fid == 0xFFFFFFFF:
                continue
            if (t[10] & 0x0F) not in (0, 1):     # keep only ok / ecc pages
                continue
            if want_fid is not None and fid != want_fid:
                continue
            seq = struct.unpack_from("<I", t, 12)[0]
            yield start + k, fid, cluster, t[10], seq
        start += count
        if count == 0:
            break


def _etfs_parse_entry(raw):
    """One 64-byte .filetable entry, or None."""
    if len(raw) < ETFS_ENTRY_SIZE:
        return None
    efid, pfid = struct.unpack_from("<HH", raw, 0)
    is_ext = efid == 0x8000
    no_parent = pfid == 0xFFFF
    etype = int(is_ext) + int(no_parent) * 2
    e = dict(efid=efid, pfid=pfid, is_ext=is_ext, is_solo=efid == 0x0000,
             is_valid=efid != 0xFFFF, body=None, full=None)
    if etype == 0:                                # file entry
        mode, uid, gid, atime, mtime, ctime, size = struct.unpack_from("<7I", raw, 4)
        name = raw[32:64].split(b"\x00", 1)[0].decode("utf-8", "replace")
        e["body"] = dict(mode=mode, uid=uid, gid=gid, mtime=mtime,
                         ctime=ctime, size=size, name=name)
    elif etype == 1:                              # extension-name entry
        e["body"] = dict(name=raw[4:63].split(b"\x00", 1)[0].decode("utf-8", "replace"))
    return e


class EtfsWalker:
    """Reconstruct an ETFS filesystem by replaying its transactions, then walk
    it through the shared collect()/extract interface. A node is a file id."""

    root = ETFS_FID_ROOT

    def __init__(self, fh, base, size, pagesize):
        self.fh, self.base, self.bs = fh, base, pagesize
        self.unit = pagesize + ETFS_TRANS_SIZE
        self.n = size // self.unit
        # current page for every (fid, cluster): the highest sequence wins, and
        # for equal sequences the later physical page, matching qnxmount.
        cur = {}
        for pi, fid, cluster, ta, seq in _etfs_scan_transactions(fh, base, pagesize, self.n):
            d = cur.setdefault(fid, {})
            if cluster not in d or seq >= d[cluster][0]:
                d[cluster] = (seq, pi)
        self.cur = cur
        self.ftable = self._build_ftable()
        self._resolve_names()
        self.kids = self._build_children()

    def _page_data(self, page_index):
        return read_at(self.fh, self.base + page_index * self.unit, self.bs)

    def _build_ftable(self):
        per = self.bs // ETFS_ENTRY_SIZE
        pages = self.cur.get(ETFS_FID_FTABLE, {})
        if not pages:
            return []
        ftable = []
        for cluster in range(max(pages) + 1):
            if cluster not in pages:
                ftable.extend([None] * per)
                continue
            data = self._page_data(pages[cluster][1])
            for k in range(per):
                ftable.append(_etfs_parse_entry(data[k * ETFS_ENTRY_SIZE:
                                                     (k + 1) * ETFS_ENTRY_SIZE]))
        return ftable

    def _resolve_names(self):
        ft = self.ftable
        for e in ft:
            if e is None or e["body"] is None:
                continue
            if e["is_ext"] or not e["is_valid"]:
                e["full"] = None
            elif e["is_solo"]:
                e["full"] = e["body"]["name"]
            else:
                ext = ft[e["efid"]] if e["efid"] < len(ft) else None
                if ext is not None and ext["is_ext"] and ext["body"]:
                    e["full"] = e["body"]["name"] + ext["body"]["name"]
                else:
                    e["full"] = e["body"]["name"]

    def _build_children(self):
        """parent fid -> [(name, fid)]. An entry whose parent id no longer
        resolves to a real named entry (its page was lost, or the slot is
        unallocated) is an orphan; qnxmount routes those to /recovered_files, so
        they are attached to the root under that name rather than dropped."""
        kids = {}
        ft = self.ftable
        self.orphans = []
        for fid, e in enumerate(ft):
            if fid == ETFS_FID_ROOT or e is None or e["full"] is None:
                continue
            pf = e["pfid"]
            parent_ok = (0 <= pf < len(ft) and ft[pf] is not None
                         and ft[pf]["full"] is not None)
            if parent_ok:
                kids.setdefault(pf, []).append((e["full"], fid))
            else:
                self.orphans.append((e["full"], fid))
        return kids

    def listdir(self, fid):
        if fid == -1:                             # synthetic recovered_files dir
            return sorted(self.orphans)
        out = list(self.kids.get(fid, []))
        if fid == ETFS_FID_ROOT and self.orphans:
            out.append(("recovered_files", -1))
        return sorted(out)

    def entry(self, fid):
        if fid == -1:                             # synthetic recovered_files dir
            return (S_IFDIR | 0o755, 0, 0)
        e = self.ftable[fid] if 0 <= fid < len(self.ftable) else None
        if e is None or e["body"] is None:
            return None
        b = e["body"]
        return (b["mode"], b["size"], b["mtime"])

    def read_file(self, fid, size):
        if fid == -1:
            return
        pages = self.cur.get(fid, {})
        left = size
        if not pages:
            return
        for cluster in range(max(pages) + 1):
            if left <= 0:
                return
            if cluster in pages:
                buf = self._page_data(pages[cluster][1])
            else:
                buf = b"\xff" * self.bs           # a hole reads as 0xFF on flash
            if len(buf) < self.bs:
                buf = buf + bytes(self.bs - len(buf))
            take = min(self.bs, left)
            yield buf[:take]
            left -= take


# ---------------------------------------------------------------------------
# EFS is QNX's other flash filesystem, the F3S "flash 3" format. It is not
# transaction based: the flash is divided into erase units, each unit carries a
# growing-downward array of 32-byte extent headers at its end and the extent
# data (text) packed from the front. An extent header names the data's offset
# and size, a "next" pointer chaining the extents of one object, and a "super"
# pointer to a newer version that supersedes it, which is how EFS does its
# copy-on-write. Physical units are mapped to logical numbers through a per-unit
# logi record, so a pointer is (logical unit, extent index).
#
# A directory's first extent points at its first child; each child extent's
# "next" chains to the following sibling, and each child's own "first" descends
# into it. A file's extents chained by "next" are its data. Source:
# qnxmount/efs/parser.ksy and interface.py at commit 11c8a7f9, and fs/f3s_spec.h
# as that spec pins it (RunZeJustin/qnx660 at 47c4158e).
#
# Byte order. f3s_unit_info_t carries an endian byte, 'L' or 'B', and every
# multi-byte field of the partition is stored in that order. It is taken here
# from the boot record, whose struct_size reads 0x18 in one order only. qnxmount
# reads little-endian only, so the big-endian reading has no reference
# implementation behind it: it is the same code with the other struct prefix,
# checked on a fixture written in both orders and on big-endian flash images.
#
# Finding a partition. The boot record (f3s_boot_t, signature "QSSL_F3S") is
# the text of header index 2 (F3S_BOOT_INDEX) of the unit that holds logical
# unit 1. Wear levelling moves that unit, so the record is not always in the
# partition's first unit. Its unit_index field is the physical index of the
# unit holding it, so the partition starts unit_index units before that unit.
# A signature is taken for a boot record only when the unit it sits in opens
# with a unit_info of the same byte order and that unit's header 2 points at
# the record; the signature string also occurs elsewhere in flash images.
#
# Extent status, status[0] of f3s_head_t, from fs/f3s_spec.h: the condition
# (mask 0x70) is free, allocated, deleted or bad, and a clear NO_SUPER bit means
# a superseding extent exists. The header's comments are all the format says
# about them. What a deleted or superseded extent's text still holds, and which
# pointers still lead to it, is measured, not specified: see recover_deleted().
# ---------------------------------------------------------------------------
EFS_SIG = b"QSSL_F3S"
EFS_EXTHDR = 32
EFS_BOOT_INDEX = 2                 # F3S_BOOT_INDEX
EFS_BOOT_SCAN = 512                # the record follows two short system texts
EFS_NO_NEXT, EFS_NO_SUPER, EFS_LAST = 0x0002, 0x0004, 0x0080
EFS_COND, EFS_FREE, EFS_ALLOC, EFS_DELETE, EFS_BAD = 0x0070, 0x0070, 0x0030, 0x0010, 0x0000
EFS_TYPE, EFS_FILE, EFS_DIR, EFS_SYS = 0x0300, 0x0300, 0x0200, 0x0100
EFS_COND_NAMES = {EFS_FREE: "free", EFS_ALLOC: "allocated", EFS_DELETE: "deleted",
                  EFS_BAD: "bad"}


def _efs_boot_at(buf, at):
    """The boot_info whose signature is at buf[at:], or None. The record starts
    4 bytes before the signature (struct_size u2, rev_major u1, rev_minor u1);
    struct_size is 0x18 in the partition's byte order, which is how the order
    is told."""
    o = at - 4
    if o < 0 or o + 24 > len(buf) or buf[at:at + 8] != EFS_SIG:
        return None
    for e in "<>":
        if struct.unpack_from(e + "H", buf, o)[0] == 0x18:
            break
    else:
        return None
    if buf[o + 2] != 3 or buf[o + 3] != 0:
        return None
    unit_index, unit_total, unit_spare, align_pow2 = struct.unpack_from(e + "HHHH", buf, o + 12)
    return dict(endian=e, unit_index=unit_index, unit_total=unit_total,
                unit_spare=unit_spare, align_pow2=align_pow2,
                root=struct.unpack_from(e + "HH", buf, o + 20))


def _efs_unit_info(b):
    """(byte order, unit size) from the unit_info that opens a unit, or None.
    The pad byte and the reserve word must read 0xFF, and unit_pow2 is in range
    in one byte order only."""
    if len(b) < 16 or b[3] != 0xFF or b[6:8] != b"\xff\xff":
        return None
    for e in "<>":
        unit_pow2 = struct.unpack_from(e + "H", b, 4)[0]
        if 9 <= unit_pow2 <= 30:
            return e, 1 << unit_pow2
    return None


def _efs_partition_from_sig(fh, sig, limit):
    """The partition whose boot record has its signature at byte sig of the
    image, or None. limit is the offset the partition must end by."""
    if sig < 4:
        return None
    boot = _efs_boot_at(read_at(fh, sig - 4, 24), 4)
    if boot is None:
        return None
    e = boot["endian"]
    unit_size, tried = None, set()
    for pow2 in range(9, 31):
        ustart = sig - sig % (1 << pow2)
        if ustart in tried:
            continue                          # the same unit start, already read
        tried.add(ustart)
        info = _efs_unit_info(read_at(fh, ustart, 16))
        if info and info[0] == e and sig - 4 - ustart < info[1] and sig - sig % info[1] == ustart:
            unit_size = info[1]
            break
    if unit_size is None:
        return None
    # header 2 of that unit has to point at the record
    h = read_at(fh, ustart + unit_size - EFS_EXTHDR * (EFS_BOOT_INDEX + 1), EFS_EXTHDR)
    if len(h) < EFS_EXTHDR:
        return None
    toff = ((h[19] << 16) + struct.unpack_from(e + "H", h, 20)[0]) << boot["align_pow2"]
    if toff != sig - 4 - ustart:
        return None
    base = ustart - boot["unit_index"] * unit_size
    if (base < 0 or boot["unit_total"] < 1 or boot["unit_index"] >= boot["unit_total"]
            or base + boot["unit_total"] * unit_size > limit):
        return None
    boot.update(base=base, size=boot["unit_total"] * unit_size, unit_size=unit_size,
                sig_at=sig - base)
    return boot


def _efs_locate(fh, base, size):
    """The EFS partition that starts at base and fits in size bytes, or None.

    The first unit has to open with a unit_info, which sizes the units; the boot
    record is then looked for at the front of every unit, since the unit holding
    it moves. A partition whose first unit carries no unit_info is not found
    from its start; efs_partitions() finds it from the record."""
    info = _efs_unit_info(read_at(fh, base, 16))
    if info is None:
        return None
    us = info[1]
    for u in range(min(size // us, 0x10000)):         # unit_total is a u2
        head = read_at(fh, base + u * us, EFS_BOOT_SCAN)
        j = head.find(EFS_SIG)
        while j >= 0:
            part = _efs_partition_from_sig(fh, base + u * us + j, base + size)
            if part and part["base"] == base:
                return part
            j = head.find(EFS_SIG, j + 1)
    return None


def efs_partitions(fh, size):
    """Every EFS partition in an image, wherever it starts, in image order.

    A raw NOR dump holds its EFS partitions one after another behind the boot
    code, with no table. Each is found by its boot record and placed by the
    record's unit_index (see the section comment). Returns a list of dicts:
    base and size in bytes, unit_size, endian ("<" or ">"), unit_index,
    unit_total, unit_spare, align_pow2, root, and sig_at, the signature's offset
    from base. Two records that place the same partition count once, and a
    partition that overlaps one already found is left out."""
    sigs, step, pos = [], 1 << 20, 0
    while pos < size:
        chunk = read_at(fh, pos, min(step + len(EFS_SIG), size - pos))
        if not chunk:
            break
        j = chunk.find(EFS_SIG)
        while 0 <= j < step:
            sigs.append(pos + j)
            j = chunk.find(EFS_SIG, j + 1)
        pos += step
    return _efs_partitions_from_sigs(fh, size, sigs)


def _efs_partitions_from_sigs(fh, size, sigs):
    parts = {}
    for sig in sigs:
        part = _efs_partition_from_sig(fh, sig, size)
        if part:
            parts.setdefault(part["base"], part)
    out, end = [], 0
    for base in sorted(parts):
        if base >= end:
            out.append(parts[base])
            end = base + parts[base]["size"]
    return out


class EfsWalker:
    """Reconstruct an EFS (F3S) filesystem, of either byte order, and walk it
    through the shared interface. A node is a parsed directory entry.

    An extent is a dict: u and i (physical unit and header index), s0
    (status[0]), status1, off and tsize (its text within the unit), next and
    super (extent pointers). recover_deleted() lists what the flash still holds
    of deleted and superseded files; unaccounted() is the consistency check."""

    def __init__(self, fh, base, size=None):
        self.fh, self.base = fh, base
        if size is None:
            size = image_size(fh) - base
        boot = _efs_locate(fh, base, size)
        if boot is None:
            raise ValueError("no EFS boot record places a partition at this offset")
        self.boot = boot
        self.e = boot["endian"]
        self.unit_size = boot["unit_size"]
        self.align = boot["align_pow2"]
        self.units = []
        for u in range(boot["unit_total"]):
            raw = read_at(fh, base + u * self.unit_size, self.unit_size)
            self.units.append((raw, self._extents(raw, u)))
        self.logi_map = self._logi_map()
        root = self._dirent(self._get_ext(boot["root"]))
        if root is None:
            raise ValueError("the EFS root directory entry does not read")
        self.root = root[1]

    def _extents(self, unit, u):
        """The unit's extent headers, index 0 first. They run down from the end
        of the unit to the one flagged last; a unit with no such header (not
        formatted, or cut short) has none."""
        e, us, exts = self.e, self.unit_size, []
        for i in range(us // EFS_EXTHDR):
            off = us - EFS_EXTHDR * (i + 1)
            if off + EFS_EXTHDR > len(unit):
                return []
            s0, status1 = struct.unpack_from(e + "II", unit, off)
            toff_lo, tsize, n0, n1, p0, p1 = struct.unpack_from(e + "6H", unit, off + 20)
            exts.append(dict(u=u, i=i, s0=s0, status1=status1,
                             off=((unit[off + 19] << 16) + toff_lo) << self.align,
                             tsize=tsize, next=(n0, n1), super=(p0, p1)))
            if s0 & EFS_LAST:
                return exts
        return []

    def _text(self, ext):
        unit = self.units[ext["u"]][0]
        return unit[ext["off"]:ext["off"] + ext["tsize"]]

    def _text_ok(self, ext):
        """Whether the extent's text lies in front of its unit's header array."""
        raw, exts = self.units[ext["u"]]
        return ext["off"] + ext["tsize"] <= min(len(raw), self.unit_size - EFS_EXTHDR * len(exts))

    @staticmethod
    def _is_spare(exts):
        return (len(exts) == 1
                or (len(exts) == 2 and exts[1]["status1"] == 0xFFFFFFFF))

    def _logi_map(self):
        logi = {}
        for u, (_raw, exts) in enumerate(self.units):
            if len(exts) < 2 or self._is_spare(exts):   # no logi record to read
                continue
            t = self._text(exts[1])                  # unit_logi: struct_size, logi
            if len(t) >= 4:
                logi[struct.unpack_from(self.e + "H", t, 2)[0]] = u
        return logi

    def _raw_ext(self, ptr):
        """The extent a pointer names, as written, or None when the logical unit
        or the header index is not there."""
        u = self.logi_map.get(ptr[0])
        if u is None:
            return None
        exts = self.units[u][1]
        return exts[ptr[1]] if ptr[1] < len(exts) else None

    def _get_ext(self, ptr):
        """The current version of the extent a pointer names: the supersede
        chain followed to its end. None when a pointer on the way does not
        resolve, or the chain loops."""
        ext, seen = self._raw_ext(ptr), set()
        while ext is not None and not ext["s0"] & EFS_NO_SUPER:
            if (ext["u"], ext["i"]) in seen:
                return None
            seen.add((ext["u"], ext["i"]))
            ext = self._raw_ext(ext["super"])
        return ext

    def _dirent(self, ext):
        """(name, node, first) for an extent whose text is a directory entry
        (f3s_dirent_t, the name, then f3s_stat_t), or None when it is not one.
        The node is the hashable (first_logi, first_index, mode, mtime) the
        shared walker interface passes around, hashable so collect()'s
        cycle-guard set can hold it; first identifies the object. The name is
        returned by listdir, not carried in the node."""
        if ext is None:
            return None
        t = self._text(ext)
        if len(t) < 8:
            return None
        namelen = t[3]
        so = 8 + ((namelen + 3) & 0xFC)              # name+pad is 4-byte aligned
        if so + 16 > len(t):
            return None
        first = struct.unpack_from(self.e + "HH", t, 4)
        name = t[8:8 + namelen].split(b"\x00", 1)[0].decode("utf-8", "replace")
        mode = struct.unpack_from(self.e + "H", t, so + 2)[0]
        mtime = struct.unpack_from(self.e + "I", t, so + 12)[0]
        return name, (first[0], first[1], mode, mtime), first

    def _chain_from(self, first):
        """(extents, why) for the chain a first pointer opens, every extent in
        its current version. why is "" when the chain ends at an extent flagged
        NO_NEXT, else what stopped it."""
        out, seen = [], set()
        ext = self._get_ext(first)
        while True:
            if ext is None:
                return out, "a pointer in its extent chain no longer resolves"
            if (ext["u"], ext["i"]) in seen:
                return out, "its extent chain loops"
            seen.add((ext["u"], ext["i"]))
            out.append(ext)
            if ext["s0"] & EFS_NO_NEXT:
                return out, ""
            ext = self._get_ext(ext["next"])

    def _chain(self, node):
        return self._chain_from((node[0], node[1]))[0]

    def listdir(self, node):
        out = []
        for ext in self._chain(node):
            if not ext["tsize"]:
                break
            d = self._dirent(ext)
            if d:
                out.append(d[:2])
        return out

    def _size(self, node):
        return sum(ext["tsize"] for ext in self._chain(node))

    def entry(self, node):
        mode = node[2]
        size = self._size(node) if (mode & 0o170000) in (0o100000, 0o120000) else 0
        return (mode, size, node[3])

    def read_file(self, node, size):
        out = bytearray()
        for ext in self._chain(node):
            out += self._text(ext)
        yield bytes(out[:size]) if size else bytes(out)

    def unaccounted(self):
        """(bytes no extent covers, how many of them are not 0xFF).

        Every byte of a unit is an extent header, the text of an extent whose
        header is not free, or neither. Flash that was never programmed reads
        0xFF, so the second number is 0 when the extent table accounts for
        everything written. A unit with no header array counts whole."""
        total = stray = 0
        for raw, exts in self.units:
            spans = sorted((x["off"], x["off"] + x["tsize"]) for x in exts
                           if x["s0"] & EFS_COND != EFS_FREE and x["tsize"]
                           and self._text_ok(x))
            spans.append((self.unit_size - EFS_EXTHDR * len(exts), self.unit_size))
            pos = 0
            for a, b in spans:
                if a > pos:
                    gap = raw[pos:a]
                    total += len(gap)
                    stray += len(gap) - gap.count(b"\xff")
                pos = max(pos, b)
        return total, stray

    # -- deleted and superseded data -------------------------------------------
    def _live(self):
        """What the live tree holds: (positions of every extent a live object
        uses, {first-extent position: (extent, name, node, first)} for the
        directory entry of every live file, {directory node: its first
        pointer})."""
        used, files, dirs = set(), {}, {self.root: (self.root[0], self.root[1])}
        boot_root = self._get_ext(self.boot["root"])
        used.add((boot_root["u"], boot_root["i"]))
        stack, seen = [self.root], {self.root}
        while stack:
            node = stack.pop()
            for ext in self._chain(node):
                used.add((ext["u"], ext["i"]))
                if not ext["tsize"]:
                    break
                d = self._dirent(ext)
                if d is None:
                    continue
                child = d[1]
                if child[2] & S_IFMT == S_IFDIR:
                    if child not in seen:
                        seen.add(child)
                        dirs[child] = d[2]
                        stack.append(child)
                    continue
                chain = self._chain(child)
                used.update((x["u"], x["i"]) for x in chain)
                if chain and child[2] & S_IFMT == S_IFREG:
                    files[(chain[0]["u"], chain[0]["i"])] = (ext,) + d
        return used, files, dirs

    def _reach(self, first, typ):
        """Positions of the extents of one type reached from a first pointer by
        next and supersede pointers, each as written."""
        out, stack = set(), [self._raw_ext(first)]
        while stack:
            ext = stack.pop()
            if ext is None or (ext["u"], ext["i"]) in out or ext["s0"] & EFS_TYPE != typ:
                continue
            out.add((ext["u"], ext["i"]))
            if not ext["s0"] & EFS_NO_NEXT:
                stack.append(self._raw_ext(ext["next"]))
            if not ext["s0"] & EFS_NO_SUPER:
                stack.append(self._raw_ext(ext["super"]))
        return out

    def recover_deleted(self):
        """Yield a FlashDeletedFile for the file data this partition still
        holds that no live file uses: deleted files, and deleted or superseded
        extents. Every such extent with text is in exactly one entry.

        EFS marks an extent deleted in its header, and on every image measured
        the text was still in place behind it. An extent that was overwritten
        has its supersede pointer set to the extent that replaced it. A
        directory entry is an extent too, so a deleted file's name, mode and
        times can stay on the flash the same way.
        Three kinds of entry come back, told apart by ``note``:

        * a deleted file: a directory entry no live directory reaches, naming a
          file whose extent chain still reads from its first pointer to its
          end. The content is the chain in its current version, as read_file()
          reads a live file, and the entry carries the name, mode and mtime of
          the newest directory entry that named it. On six flash images this
          gave 390 of the 527 distinct file contents the acquisitions' own
          tools had extracted, and live files 108 (README, "QNX EFS in a raw
          flash image");
        * a deleted file whose chain does not read whole (a pointer no longer
          resolves, or it runs into a free header or a live file's extent): the
          name is reported, not recoverable, with the reason;
        * a run of deleted or superseded extents chained by their next pointers
          that no entry above took. It is named after the file a directory
          entry still leads to it from, live or deleted, when exactly one does;
          otherwise the name is empty. These are pieces: an earlier version of
          part of a file, or what is left of a file whose directory entry is
          gone.

        ``parent`` is the live directory whose chain of entries still reaches
        the file's directory entry, and None when no live directory's does.

        The directory records no size, so ``size`` is the bytes the entry's
        extents hold. An extent pointer is a logical unit and a header index
        and nothing says whether that unit was rewritten since the pointer was
        written, so a name is what the directory data leads to, not a proof of
        ownership. deleted_extents(entry) gives where each extent lies."""
        used, live_files, live_dirs = self._live()
        old = {}                                     # position -> extent
        dirents = collections.defaultdict(list)      # file key -> [(ext, name, node, first)]
        for _raw, exts in self.units:
            for ext in exts:
                cond, typ = ext["s0"] & EFS_COND, ext["s0"] & EFS_TYPE
                pos = (ext["u"], ext["i"])
                if cond not in (EFS_ALLOC, EFS_DELETE) or pos in used or not self._text_ok(ext):
                    continue
                if typ == EFS_FILE:
                    if ext["tsize"]:
                        old[pos] = ext
                elif typ == EFS_DIR:
                    d = self._dirent(ext)
                    if d and d[1][2] & S_IFMT == S_IFREG:
                        head = self._get_ext(d[2])
                        key = (head["u"], head["i"]) if head else ("unresolved",) + d[2]
                        dirents[key].append((ext,) + d)
        # which live directory each directory entry extent hangs from
        parent_of = {}
        for node, first in live_dirs.items():
            for pos in self._reach(first, EFS_DIR):
                parent_of.setdefault(pos, node)
        paths = _live_dir_paths(self)

        def named(key):
            """The newest directory entry of a file: the live one, else one
            nothing supersedes, then the latest mtime."""
            ext, name, node, _first = live_files.get(key) or max(
                dirents[key], key=lambda r: (bool(r[0]["s0"] & EFS_NO_SUPER), r[2][3],
                                             r[0]["u"], r[0]["i"]))
            parent = parent_of.get((ext["u"], ext["i"]))
            return name, parent, paths.get(parent), node[2], node[3]

        entries, claimed = [], set()
        for key in sorted(dirents, key=str):
            if key in live_files:
                continue
            name, parent, ppath, mode, mtime = named(key)
            chain, why = self._chain_from(dirents[key][0][3])
            if not why:
                for x in chain:
                    pos = (x["u"], x["i"])
                    if x["s0"] & EFS_COND == EFS_FREE:
                        why = "its extent chain runs into a free header"
                    elif pos in used:
                        why = ("its extent chain runs into extents a live file holds (the "
                               "file was renamed or moved, or the header was used again)")
                    elif x["s0"] & EFS_TYPE != EFS_FILE or pos not in old and x["tsize"]:
                        why = "its extent chain runs into an extent that is not file data"
                    elif pos in claimed:
                        why = "its extent chain runs into another deleted file's extents"
                    if why:
                        break
            ident = (f"unit {key[0]} extent {key[1]}" if key[0] != "unresolved"
                     else f"logical unit {key[1]} extent {key[2]}")
            if why:
                e = FlashDeletedFile("efs", ident, name, parent, ppath, 0, mode, mtime,
                                     0, [], self)
                e.recoverable, e.reason = False, why
                e.note = "a deleted file, named by a directory entry that is still on the flash"
            else:
                chain = [x for x in chain if x["tsize"]]
                claimed.update((x["u"], x["i"]) for x in chain)
                e = FlashDeletedFile("efs", ident, name, parent, ppath,
                                     sum(x["tsize"] for x in chain), mode, mtime, 0, chain, self)
                e.note = "a deleted file, its extent chain read from its directory entry"
            entries.append(e)
        # what is left: name each extent after the one file that leads to it
        owner = {}
        for key in sorted(set(dirents) | set(live_files), key=str):
            rows = dirents.get(key, []) + [r for r in (live_files.get(key),) if r]
            for first in sorted({r[3] for r in rows}):
                for pos in self._reach(first, EFS_FILE):
                    if pos in old and pos not in claimed:
                        owner[pos] = key if owner.get(pos, key) == key else None
        left = {pos: x for pos, x in old.items() if pos not in claimed}
        follows = {}
        for pos, x in left.items():
            if x["s0"] & EFS_NO_NEXT:
                continue
            nxt = self._raw_ext(x["next"])
            npos = (nxt["u"], nxt["i"]) if nxt else None
            if npos in left and npos != pos and owner.get(npos) == owner.get(pos):
                follows[pos] = npos
        heads = set(left) - set(follows.values())
        done = set()
        for start in sorted(heads) + sorted(left):
            run, pos = [], start
            while pos is not None and pos not in done:
                done.add(pos)
                run.append(left[pos])
                pos = follows.get(pos)
            if not run:
                continue
            key = owner.get(start)
            ident = f"unit {start[0]} extent {start[1]}"
            size = sum(x["tsize"] for x in run)
            if key is None:
                e = FlashDeletedFile("efs", ident, "", None, None, size, None, None, 0,
                                     run, self)
                e.note = ("deleted or superseded file extents no directory entry on the "
                          "flash leads to" if start not in owner else
                          "deleted or superseded file extents more than one file's "
                          "directory entries lead to")
            else:
                name, parent, ppath, mode, mtime = named(key)
                e = FlashDeletedFile("efs", ident, name, parent, ppath, size, mode, mtime,
                                     0, run, self)
                e.note = ("deleted or superseded extents of a file that still exists: "
                          "earlier data, not the file" if key in live_files else
                          "deleted or superseded extents of a deleted file, apart from "
                          "its last version")
            entries.append(e)
        yield from entries

    def read_deleted(self, entry, size=None):
        """The bytes of a recover_deleted() entry: its extents' text, in chain
        order."""
        if not entry.recoverable:
            raise ValueError(f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        left = entry.size if size is None else min(size, entry.size)
        for ext in entry._plan:                      # pylint: disable=protected-access
            if left <= 0:
                return
            text = self._text(ext)[:left]
            left -= len(text)
            yield text

    def deleted_extents(self, entry):
        """[(offset in the image, length, state)] for the extents of a
        recover_deleted() entry, in the order read_deleted() joins them. state
        is the header's condition ("deleted" or "allocated"), followed by
        ", superseded" when its supersede pointer is set."""
        out = []
        for ext in entry._plan:                      # pylint: disable=protected-access
            state = EFS_COND_NAMES[ext["s0"] & EFS_COND]
            if not ext["s0"] & EFS_NO_SUPER:
                state += ", superseded"
            out.append((self.base + ext["u"] * self.unit_size + ext["off"],
                        ext["tsize"], state))
        return out


# ---------------------------------------------------------------------------
# Decompressors for the Linux flash filesystems (SquashFS, JFFS2, UBIFS)
#
# zlib, raw deflate, xz and legacy lzma are in the standard library. LZO and
# LZ4 are not, and both are small enough to carry as pure-Python decoders, the
# same way the UCL decoder above is carried for QNX IFS. zstd is in the
# standard library from Python 3.14 (compression.zstd); on an older Python a
# zstd-compressed file is named and reported as not read, never guessed at.
# ---------------------------------------------------------------------------
class DecompressError(Exception):
    """Compressed bytes this reader could not turn back into the original."""


def _copy_match(out, dist, length):
    """Append `length` bytes copied from `dist` bytes back in `out`. A copy
    that overlaps what it writes (dist < length) repeats the last `dist` bytes,
    which is what a byte-at-a-time copy does."""
    if dist <= 0 or dist > len(out):
        raise DecompressError(f"match reaches {dist} bytes back, before the start")
    start = len(out) - dist
    if dist >= length:
        out += out[start:start + length]
    else:
        pat = bytes(out[start:])
        reps, rem = divmod(length, dist)
        out += pat * reps + pat[:rem]


def _lzo_ext(src, ip, base):
    """A variable-length count: every zero byte adds 255, then the first
    non-zero byte and `base` are added. Returns (count, ip)."""
    zeros = 0
    while src[ip] == 0:
        zeros += 1
        ip += 1
    return base + zeros * 255 + src[ip], ip + 1


def lzo1x_decompress(src, limit=None):
    """Decode an LZO1X stream, both bitstream versions the Linux kernel reads.

    Written from Documentation/staging/lzo.rst, which describes the stream
    lib/lzo/lzo1x_decompress_safe.c accepts; the end-of-stream test follows
    that file. The stream ends at a 16..31 instruction whose distance works out
    to zero, which is 0x11 0x00 0x00. `limit` caps the output, as a block's
    known size does.

    Only bitstream version 0 is read. Version 1 (LZO-RLE, announced by a
    leading 17 and a version byte) is what zram writes; SquashFS, JFFS2 and
    UBIFS are written with plain LZO1X (squashfs-tools through liblzo2, the
    kernel's jffs2 and ubifs through lzo1x_1_compress), so a version 1 stream
    is refused rather than decoded by untested code.
    """
    src = bytes(src)
    n = len(src)
    if n < 3:
        raise DecompressError("LZO stream shorter than its end marker")
    out = bytearray()
    ip = 0
    if n >= 5 and src[0] == 17:
        raise DecompressError("LZO-RLE (bitstream version 1) is not read here")
    try:
        t = src[ip]
        state = 0
        if t > 17:                                   # first byte: a literal run
            ip += 1
            t -= 17
            out += src[ip:ip + t]
            ip += t
            state = t if t < 4 else 4
        while True:
            t = src[ip]
            ip += 1
            if t < 16:
                if state == 0:                       # 0000LLLL: long literal run
                    if t == 0:
                        t, ip = _lzo_ext(src, ip, 15)
                    t += 3
                    if ip + t > n:
                        raise DecompressError("literal run past the end of the input")
                    out += src[ip:ip + t]
                    ip += t
                    state = 4
                    continue
                if state != 4:                       # 0000DDSS: 2 bytes, <= 1 KiB back
                    nxt = t & 3
                    dist = (t >> 2) + (src[ip] << 2) + 1
                    ip += 1
                    _copy_match(out, dist, 2)
                else:                                # 0000DDSS: 3 bytes, 2..3 KiB back
                    nxt = t & 3
                    dist = (t >> 2) + (src[ip] << 2) + 2049
                    ip += 1
                    _copy_match(out, dist, 3)
            elif t >= 64:                            # 01LDDDSS / 1LLDDDSS
                nxt = t & 3
                dist = ((t >> 2) & 7) + (src[ip] << 3) + 1
                ip += 1
                _copy_match(out, dist, (t >> 5) + 1)
            elif t >= 32:                            # 001LLLLL + LE16
                length = t & 31
                if length == 0:
                    length, ip = _lzo_ext(src, ip, 31)
                v = src[ip] | (src[ip + 1] << 8)
                ip += 2
                nxt = v & 3
                _copy_match(out, (v >> 2) + 1, length + 2)
            else:                                    # 0001HLLL + LE16
                length = t & 7
                if length == 0:
                    length, ip = _lzo_ext(src, ip, 7)
                v = src[ip] | (src[ip + 1] << 8)
                ip += 2
                nxt = v & 3
                dist = ((t & 8) << 11) + (v >> 2)
                if dist == 0:                        # end of stream
                    if length + 2 != 3:
                        raise DecompressError("malformed LZO end marker")
                    break
                _copy_match(out, dist + 0x4000, length + 2)
            state = nxt                              # then copy 0..3 literals
            if nxt:
                out += src[ip:ip + nxt]
                ip += nxt
            if limit is not None and len(out) > limit:
                raise DecompressError("LZO output larger than the block it fills")
    except IndexError:
        raise DecompressError("LZO stream ends inside an instruction") from None
    return bytes(out)


def lz4_block_decompress(src, limit=None):
    """Decode one LZ4 block (no frame), as lz4/doc/lz4_Block_format.md at
    v1.10.0 defines it: sequences of a token, literals, a 2-byte offset and a
    match; the last sequence carries literals only."""
    src = bytes(src)
    n = len(src)
    out = bytearray()
    ip = 0
    try:
        while True:
            token = src[ip]
            ip += 1
            lit = token >> 4
            if lit == 15:
                while True:
                    b = src[ip]
                    ip += 1
                    lit += b
                    if b != 255:
                        break
            if ip + lit > n:
                raise DecompressError("LZ4 literals run past the end of the input")
            out += src[ip:ip + lit]
            ip += lit
            if ip >= n:
                break                                # the last sequence has no match
            off = src[ip] | (src[ip + 1] << 8)
            ip += 2
            if off == 0:
                raise DecompressError("LZ4 match offset of zero")
            ml = token & 15
            if ml == 15:
                while True:
                    b = src[ip]
                    ip += 1
                    ml += b
                    if b != 255:
                        break
            _copy_match(out, off, ml + 4)
            if limit is not None and len(out) > limit:
                raise DecompressError("LZ4 output larger than the block it fills")
    except IndexError:
        raise DecompressError("LZ4 block ends inside a sequence") from None
    return bytes(out)


# What a zstd SquashFS says on a Python with no zstd. identify_fs() reports it
# among its lines and the walker carries it as its note, which volumes() passes
# on, so a listing that comes back empty says why wherever the volume is shown.
SQUASHFS_NO_ZSTD_NOTE = ("zstd compressed; this Python has no zstd (3.14 adds it), so "
                         "the listing may be short and no file can be read")


def _zstd_module():
    try:
        from compression import zstd              # Python 3.14 and later
        return zstd
    except ImportError:
        return None


def zstd_decompress(src):
    z = _zstd_module()
    if z is None:
        raise DecompressError("zstd needs Python 3.14 or later (compression.zstd); "
                              "this Python does not carry it")
    try:
        return z.decompress(bytes(src))
    except Exception as exc:                        # ZstdError, not a stable name
        raise DecompressError(f"zstd: {exc}") from None


# ---------------------------------------------------------------------------
# SquashFS 4.0
#
# Every structure and constant is read from the Linux kernel's own driver at
# v7.0 (commit 028ef9c96e96197026887c0f092424679298aae8):
#
#   SQUASHFS_MAGIC 0x73717368 ("hsqs")      include/uapi/linux/magic.h:20
#   struct squashfs_super_block             fs/squashfs/squashfs_fs.h:241
#   inode layouts, dir header and entry     fs/squashfs/squashfs_fs.h:270-422
#   fragment entry                          fs/squashfs/squashfs_fs.h:424
#   metadata block: le16 length, bit 15     fs/squashfs/block.c squashfs_read_data
#     set = stored uncompressed, 8 KiB max  fs/squashfs/squashfs_fs.h:19,106
#   data block: le32 length, bit 24 set =   fs/squashfs/squashfs_fs.h:113
#     stored uncompressed; 0 = a hole       fs/squashfs/file.c
#   the stored mode carries no type bits;   fs/squashfs/inode.c squashfs_new_inode
#     the type comes from inode_type
#   a directory's size counts 3 bytes for   fs/squashfs/dir.c squashfs_readdir
#     the "." and ".." it does not store
#   inode reference = metadata block << 16  fs/squashfs/squashfs_fs.h:130,
#     | offset, relative to the inode table   fs/squashfs/namei.c
#
# Version 4.0 is always little endian. The 1.x to 3.x layouts (and their big
# endian "sqsh" form) are recognised and reported, not walked.
# ---------------------------------------------------------------------------
SQUASHFS_MAGIC = 0x73717368
SQFS_METADATA_SIZE = 8192
SQFS_INVALID_FRAG = 0xFFFFFFFF
SQFS_COMP = {1: "gzip", 2: "lzma", 3: "lzo", 4: "xz", 5: "lz4", 6: "zstd"}
SQFS_TYPE_MODE = {1: S_IFDIR, 2: S_IFREG, 3: S_IFLNK, 4: 0o060000, 5: 0o020000,
                  6: 0o010000, 7: 0o140000, 8: S_IFDIR, 9: S_IFREG, 10: S_IFLNK,
                  11: 0o060000, 12: 0o020000, 13: 0o010000, 14: 0o140000}
SQFS_FLAGS = ((0, "inodes stored uncompressed"), (1, "data stored uncompressed"),
              (3, "fragments stored uncompressed"), (4, "no fragments"),
              (5, "always fragments"), (6, "duplicates removed"),
              (7, "exportable (NFS)"), (10, "compressor options present"))


class SquashfsUnreadable(Exception):
    """A SquashFS structure or file this reader cannot hand back; the message
    says which and why."""


def _sqfs_decompress(comp, data, limit):
    """Turn one compressed SquashFS block back into its bytes. The wrappers are
    fs/squashfs/{zlib,xz,lzo,lz4,zstd}_wrapper.c: gzip is a zlib stream with its
    header, xz is the .xz container, lzo is raw LZO1X and lz4 a raw LZ4 block.
    lzma (id 2) is not read by the kernel at all (decompressor.c lists it as
    unsupported). squashfs-tools 4.7.5 writes it as an lzma-alone stream
    encoded with its size unknown, so it ends in an end marker, then overwrites
    the header's 8-byte size field with the real size; its own decoder puts the
    "unknown" value (all 0xFF) back before decoding and keeps that many bytes
    (squashfs-tools/lzma_xz_wrapper.c lzma_compress and lzma_uncompress, at
    708c59ae), and so does this."""
    import lzma, zlib
    try:
        if comp == 1:
            return zlib.decompress(data)
        if comp == 4:
            return lzma.decompress(data, format=lzma.FORMAT_XZ)
        if comp == 2:
            if len(data) < 13:
                raise DecompressError("lzma block shorter than its header")
            want = struct.unpack_from("<I", data, 5)[0]
            out = lzma.decompress(data[:5] + b"\xff" * 8 + data[13:],
                                  format=lzma.FORMAT_ALONE)
            return out[:want]
        if comp == 3:
            return lzo1x_decompress(data, limit)
        if comp == 5:
            return lz4_block_decompress(data, limit)
        if comp == 6:
            return zstd_decompress(data)
    except (zlib.error, lzma.LZMAError) as exc:
        raise DecompressError(f"{SQFS_COMP.get(comp)}: {exc}") from None
    raise DecompressError(f"compression id {comp} is not one SquashFS defines")


class SquashfsWalker:
    """List and read a SquashFS 4.0 image. A node is an inode reference (the
    metadata block's offset in the inode table, shifted left 16, plus the byte
    offset inside it), which is what a directory entry records, so a hard link
    is one node reached by two names."""

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        sb = read_at(fh, base, 96)
        if len(sb) < 96 or struct.unpack_from("<I", sb, 0)[0] != SQUASHFS_MAGIC:
            raise SquashfsUnreadable("no SquashFS superblock")
        (self.inodes, self.mkfs_time, self.block_size, self.fragments,
         self.comp, self.block_log, self.flags, self.no_ids, major, minor) = \
            struct.unpack_from("<IIIIHHHHHH", sb, 4)
        if (major, minor) != (4, 0):
            raise SquashfsUnreadable(f"version {major}.{minor}; only 4.0 is read")
        if not (4096 <= self.block_size <= 1048576) or \
                self.block_size != 1 << self.block_log:
            raise SquashfsUnreadable("block size and block log disagree")
        (self.root_ref, self.bytes_used, self.id_table, self.xattr_table,
         self.inode_table, self.dir_table, self.frag_table, self.lookup_table) = \
            struct.unpack_from("<QQQQQQQQ", sb, 32)
        if not (self.inode_table < self.dir_table <= self.bytes_used):
            raise SquashfsUnreadable("inode and directory tables out of order")
        self._meta = {}
        self._ids = None
        self._frag_index = None
        # Many small files share one fragment block, so the last few blocks are
        # kept decompressed, as the kernel's fragment cache does (super.c,
        # SQUASHFS_CACHED_FRAGMENTS).
        self._frags = collections.OrderedDict()

    root = property(lambda self: self.root_ref)

    # -- metadata ----------------------------------------------------------
    def _meta_block(self, pos):
        """(bytes, next_pos) for the metadata block starting `pos` bytes into
        the image: a le16 header then up to 8 KiB, compressed unless bit 15."""
        hit = self._meta.get(pos)
        if hit is not None:
            return hit
        hdr = read_at(self.fh, self.base + pos, 2)
        if len(hdr) < 2:
            raise SquashfsUnreadable(f"metadata block at {pos:#x} lies past the image")
        raw = struct.unpack("<H", hdr)[0]
        length = raw & 0x7FFF or 0x8000
        stored = read_at(self.fh, self.base + pos + 2, length)
        if len(stored) < length:
            raise SquashfsUnreadable(f"metadata block at {pos:#x} is cut short")
        data = stored if raw & 0x8000 else _sqfs_decompress(self.comp, stored, SQFS_METADATA_SIZE)
        out = (data, pos + 2 + length)
        if len(self._meta) < 8192:
            self._meta[pos] = out
        return out

    def _meta_read(self, pos, off, n):
        """n bytes of metadata starting `off` bytes into the block at `pos`,
        following on into the next blocks. Returns (bytes, pos, off) with the
        position just past what was read."""
        out = bytearray()
        while True:
            data, nxt = self._meta_block(pos)
            take = data[off:off + n - len(out)]
            out += take
            off += len(take)
            if len(out) >= n:
                if off >= len(data):
                    pos, off = nxt, off - len(data)
                return bytes(out), pos, off
            if not data:
                raise SquashfsUnreadable("empty metadata block")
            pos, off = nxt, off - len(data)

    def _table(self, start, count, entry_size):
        """A lookup table: a list of le64 pointers at `start`, each to a
        metadata block holding the next 8 KiB of `count` fixed-size entries."""
        nblocks = (count * entry_size + SQFS_METADATA_SIZE - 1) // SQFS_METADATA_SIZE
        ptrs = read_at(self.fh, self.base + start, nblocks * 8)
        if len(ptrs) < nblocks * 8:
            raise SquashfsUnreadable("lookup table lies past the image")
        out = bytearray()
        for (p,) in struct.iter_unpack("<Q", ptrs):
            out += self._meta_block(p)[0]
        return bytes(out[:count * entry_size])

    def uid_gid(self, idx):
        if self._ids is None:
            raw = self._table(self.id_table, self.no_ids, 4)
            self._ids = [v for (v,) in struct.iter_unpack("<I", raw)]
        return self._ids[idx] if idx < len(self._ids) else None

    def _fragment(self, index):
        """(start, stored_size_word) for a fragment table entry."""
        if self._frag_index is None:
            self._frag_index = self._table(self.frag_table, self.fragments, 16)
        if index >= self.fragments:
            raise SquashfsUnreadable(f"fragment {index} is beyond the table")
        start, size = struct.unpack_from("<QI", self._frag_index, index * 16)
        return start, size

    def _fragment_block(self, index):
        hit = self._frags.get(index)
        if hit is not None:
            self._frags.move_to_end(index)
            return hit
        fstart, fword = self._fragment(index)
        if fword >> 25:
            raise SquashfsUnreadable(f"fragment {index} records an impossible length")
        stored = fword & 0xFFFFFF
        raw = read_at(self.fh, self.base + fstart, stored)
        block = raw if fword & (1 << 24) else \
            _sqfs_decompress(self.comp, raw, self.block_size)
        self._frags[index] = block
        while len(self._frags) > 8:
            self._frags.popitem(last=False)
        return block

    # -- inodes ------------------------------------------------------------
    def inode(self, ref):
        pos, off = self.inode_table + (ref >> 16), ref & 0xFFFF
        base, pos, off = self._meta_read(pos, off, 16)
        itype, mode, uid, gid, mtime, number = struct.unpack("<HHHHII", base)
        if itype not in SQFS_TYPE_MODE:
            raise SquashfsUnreadable(f"inode {ref:#x} has unknown type {itype}")
        ino = dict(type=itype, mode=(mode & 0o7777) | SQFS_TYPE_MODE[itype],
                   uid=uid, gid=gid, mtime=mtime, number=number, size=0)
        if itype == 2:                               # basic file
            b, pos, off = self._meta_read(pos, off, 16)
            start, frag, foff, size = struct.unpack("<IIII", b)
            ino.update(start=start, frag=frag, frag_off=foff, size=size, sparse=0)
        elif itype == 9:                             # extended file
            b, pos, off = self._meta_read(pos, off, 40)
            start, size, sparse, nlink, frag, foff, _xattr = struct.unpack("<QQQIIII", b)
            ino.update(start=start, frag=frag, frag_off=foff, size=size, sparse=sparse)
        elif itype == 1:                             # basic directory
            b, pos, off = self._meta_read(pos, off, 16)
            start, _nlink, size, doff, parent = struct.unpack("<IIHHI", b)
            ino.update(dir_start=start, dir_off=doff, size=size, parent=parent)
        elif itype == 8:                             # extended directory
            b, pos, off = self._meta_read(pos, off, 24)
            _nlink, size, start, parent, _icount, doff, _xattr = struct.unpack("<IIIIHHI", b)
            ino.update(dir_start=start, dir_off=doff, size=size, parent=parent)
        elif itype in (3, 10):                       # symlink
            b, pos, off = self._meta_read(pos, off, 8)
            _nlink, tlen = struct.unpack("<II", b)
            if tlen > 65536:
                raise SquashfsUnreadable(f"symlink {ref:#x} claims {tlen} bytes")
            target, pos, off = self._meta_read(pos, off, tlen)
            ino.update(target=target, size=tlen)
        if itype in (2, 9):
            ino["list_pos"], ino["list_off"] = pos, off
        return ino

    def entry(self, ref):
        try:
            ino = self.inode(ref)
        except (SquashfsUnreadable, DecompressError, struct.error):
            return None
        return ino["mode"], ino["size"], ino["mtime"]

    def readlink(self, ref):
        ino = self.inode(ref)
        return ino.get("target", b"").decode("utf-8", "surrogateescape")

    @property
    def note(self):
        """Why this volume cannot be read on this Python, or None. listdir()
        answers an empty list when its directory table cannot be decompressed,
        so volumes() carries this beside the volume to say why."""
        if self.comp == 6 and _zstd_module() is None:
            return SQUASHFS_NO_ZSTD_NOTE
        return None

    def listdir(self, ref):
        try:
            ino = self.inode(ref)
        except (SquashfsUnreadable, DecompressError, struct.error):
            return []
        if ino["type"] not in (1, 8):
            return []
        out = []
        pos, off = self.dir_table + ino["dir_start"], ino["dir_off"]
        left = ino["size"] - 3                       # "." and ".." are not stored
        try:
            while left > 0:
                hdr, pos, off = self._meta_read(pos, off, 12)
                left -= 12
                count, start, base_num = struct.unpack("<III", hdr)
                if count + 1 > 256:
                    raise SquashfsUnreadable("directory header counts more than 256")
                for _ in range(count + 1):
                    ent, pos, off = self._meta_read(pos, off, 8)
                    ioff, _delta, _dtype, nlen = struct.unpack("<HhHH", ent)
                    if nlen + 1 > 256:
                        raise SquashfsUnreadable("directory entry name over 256 bytes")
                    name, pos, off = self._meta_read(pos, off, nlen + 1)
                    left -= 8 + nlen + 1
                    out.append((name.decode("utf-8", "surrogateescape"),
                                (start << 16) | ioff))
        except (SquashfsUnreadable, DecompressError, struct.error):
            pass                                     # report what was read
        return out

    # -- file data ---------------------------------------------------------
    def read_file(self, ref, size):
        ino = self.inode(ref)
        if ino["type"] not in (2, 9):
            return
        fsize, bs = ino["size"], self.block_size
        has_frag = ino["frag"] != SQFS_INVALID_FRAG
        nblocks = fsize // bs if has_frag else (fsize + bs - 1) // bs
        sizes = b""
        if nblocks:
            sizes, _p, _o = self._meta_read(ino["list_pos"], ino["list_off"], nblocks * 4)
        pos = ino["start"]
        left = min(size, fsize)
        for i in range(nblocks):
            if left <= 0:
                return
            word = struct.unpack_from("<I", sizes, i * 4)[0]
            want = min(bs, fsize - i * bs)
            if word == 0:                            # a hole: no bytes stored
                data = bytes(want)
            else:
                if word >> 25:
                    raise SquashfsUnreadable(f"block {i} of inode {ref:#x} records an "
                                             f"impossible length word {word:#x}")
                stored = word & 0xFFFFFF
                raw = read_at(self.fh, self.base + pos, stored)
                pos += stored
                data = raw if word & (1 << 24) else _sqfs_decompress(self.comp, raw, bs)
                if len(data) < want:
                    data += bytes(want - len(data))
            take = data[:min(want, left)]
            yield take
            left -= len(take)
        if has_frag and left > 0:
            block = self._fragment_block(ino["frag"])
            tail = block[ino["frag_off"]:ino["frag_off"] + left]
            if len(tail) < left:
                tail += bytes(left - len(tail))
            yield tail


def identify_squashfs(fh, base, size=None):
    """Return ("squashfs", lines) for a SquashFS image at base, else None.

    "hsqs" at offset 0 names the little-endian layout and "sqsh" the big-endian
    one of the 1.x to 3.x versions; s_major/s_minor sit at offset 28 in every
    version. Only 4.0 is walked, and it is accepted only when its block size is
    a power of two in 4 KiB..1 MiB that agrees with block_log, its compression
    id is one the format defines, and its root inode reads back as a
    directory, the checks super.c applies before it will mount.
    """
    sb = read_at(fh, base, 96)
    if len(sb) < 32:
        return None
    if sb[:4] not in (b"hsqs", b"sqsh"):
        return None
    endian = "<" if sb[:4] == b"hsqs" else ">"
    major, minor = struct.unpack_from(endian + "HH", sb, 28)
    if (major, minor) != (4, 0) or endian == ">":
        if not (1 <= major <= 3):
            return None
        return "squashfs", [
            f"version      {major}.{minor} "
            f"({'big' if endian == '>' else 'little'} endian)",
            "contents     a pre-4.0 layout, reported here but not walked; the Linux "
            "kernel's own driver refuses them too (fs/squashfs/super.c)"]
    try:
        w = SquashfsWalker(fh, base)
    except SquashfsUnreadable:
        return None
    if w.comp not in SQFS_COMP:
        return None
    try:
        root = w.inode(w.root)
        root_ok = root["type"] in (1, 8)
    except (SquashfsUnreadable, DecompressError, struct.error, ValueError):
        root_ok = False
    flags = [name for bit, name in SQFS_FLAGS if w.flags >> bit & 1]
    lines = [
        "version      4.0",
        f"compression  {SQFS_COMP[w.comp]}",
        f"block size   {w.block_size:,} bytes",
        f"made         {stamp(w.mkfs_time)}   (mkfs_time as stored; mksquashfs "
        "records its build time here unless told otherwise)",
        f"inodes       {w.inodes:,}   fragments {w.fragments:,}   ids {w.no_ids:,}",
        f"bytes used   {human(w.bytes_used)}",
    ]
    if flags:
        lines.append("flags        " + ", ".join(flags))
    if size is not None and w.bytes_used > size:
        lines.append(f"note         the image records {human(w.bytes_used)} but the region "
                     f"holds {human(size)}, so its end is missing")
    if w.comp == 6 and _zstd_module() is None:
        lines.append("note         " + SQUASHFS_NO_ZSTD_NOTE)
    if not root_ok:
        if w.comp == 6 and _zstd_module() is None:
            return "squashfs", lines
        return None
    return "squashfs", lines


class NandDataView:
    """A raw NAND dump read as its page data alone: after each `page` bytes of
    data the dump holds `spare` bytes of spare (OOB) area, which a chip-off
    reader captures and a filesystem never sees. UBI and JFFS2 lay their
    structures across pages, so they are read through this view; YAFFS reads
    the spare itself and needs no view."""

    def __init__(self, fh, base, size, page, spare):
        self.fh, self.base, self.page, self.spare = fh, base, page, spare
        self.size = (size // (page + spare)) * page
        self.name = getattr(fh, "name", "")
        self._pos = 0

    def seek(self, offset, whence=0):
        self._pos = offset if whence == 0 else (self._pos + offset if whence == 1
                                                else self.size + offset)
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if n is None or n < 0:
            n = max(self.size - self._pos, 0)
        out = bytearray()
        pos, end = self._pos, min(self._pos + n, self.size)
        while pos < end:
            pg, off = divmod(pos, self.page)
            take = min(self.page - off, end - pos)
            chunk = read_at(self.fh, self.base + pg * (self.page + self.spare) + off, take)
            out += chunk
            if len(chunk) < take:
                break
            pos += take
        self._pos = pos
        return bytes(out)


def nand_views(fh, base, size):
    """(page, spare, view) for each common NAND geometry whose whole pages fill
    the region exactly, the same geometries the YAFFS layout search tries."""
    for page, spare in YAFFS_GEOMETRIES:
        if size and size % (page + spare) == 0:
            yield page, spare, NandDataView(fh, base, size, page, spare)


# ---------------------------------------------------------------------------
# JFFS2
#
# A log of nodes with no superblock: the filesystem is whatever nodes the
# region holds. Every structure is read from the Linux kernel at v7.0 (commit
# 028ef9c96e96197026887c0f092424679298aae8):
#
#   magic 0x1985, the old 0x1984, node types  include/uapi/linux/jffs2.h:24-69
#   struct jffs2_unknown_node (12 bytes)      include/uapi/linux/jffs2.h:102
#   struct jffs2_raw_dirent (40 + name)       include/uapi/linux/jffs2.h:111
#   struct jffs2_raw_inode (68 + data)        include/uapi/linux/jffs2.h:135
#   compression ids                           include/uapi/linux/jffs2.h:41-48
#   header CRC: crc32 of the first 8 bytes    fs/jffs2/scan.c jffs2_scan_eraseblock
#     with the ACCURATE bit (0x2000) set; a
#     node with that bit cleared is obsolete
#   nodes are 4-byte aligned (PAD)            fs/jffs2/nodelist.h
#   the newest version of a name in a         fs/jffs2/readinode.c
#     directory wins, and ino 0 unlinks it;     read_direntry, jffs2_add_fd_to_list
#   the newest inode node carries the mode,   fs/jffs2/readinode.c
#     owner and times, and a regular file is    jffs2_do_read_inode_internal
#     cut to that node's isize; data ranges
#     from newer versions overwrite older ones
#   the root is inode 1 and may have no inode fs/jffs2/readinode.c:1199-1201
#     node of its own
#   a node whose data fails its CRC is        fs/jffs2/readinode.c
#     obsolete, and older data shows through    check_node_data
#
# Kernel crc32() is crc32_le with seed 0 and no inversion, which is zlib's
# crc32 with its pre- and post-inversion undone.
# ---------------------------------------------------------------------------
JFFS2_MAGIC = 0x1985
JFFS2_OLD_MAGIC = 0x1984
JFFS2_ACCURATE = 0x2000
JFFS2_DIRENT, JFFS2_INODE = 0xE001, 0xE002
JFFS2_CLEANMARKER, JFFS2_PADDING, JFFS2_SUMMARY = 0x2003, 0x2004, 0x2006
JFFS2_XATTR, JFFS2_XREF = 0xE008, 0xE009
JFFS2_COMPR = {0: "none", 1: "zero", 2: "rtime", 3: "rubinmips", 4: "copy",
               5: "dynrubin", 6: "zlib", 7: "lzo", 8: "lzma"}
JFFS2_ROOT_INO = 1
JFFS2_SCAN_CHUNK = 1 << 22


class FlashDeletedFile:
    """One deleted file a YAFFS2, JFFS2 or UBIFS volume still holds.

    These filesystems never rewrite in place: a change goes to a new page or
    node and the old one stays until garbage collection erases its block, so a
    deleted file's last name, size and content can outlive the deletion.

    ``name`` and ``parent`` (the parent directory's node in the walker) come
    from the newest record that named the file before it was deleted;
    ``parent_path`` is that directory's path when it still exists, else None.
    ``size``, ``mode`` and ``mtime`` (Unix seconds, as the filesystem stores
    them) come from its newest header or inode before the deletion.
    ``recoverable`` says whether every page or block that size needs is still
    on the flash; ``missing`` counts the ones that are not. A block that was
    erased and one that was never written (a hole) look the same, so either
    refuses the read, and ``reason`` says so. ``ident`` is the YAFFS object id
    or the inode number, as ``kind`` ("yaffs2", "jffs2", "ubifs") names it.
    ``is_dir`` is always False: only files are recovered. ``note`` is empty,
    or says what the recovery had to decide that the flash does not record.

    An EFS entry (``kind`` "efs", EfsWalker.recover_deleted) differs where the
    format does. Its directory records no size, so ``size`` is the bytes the
    entry's extents hold and ``missing`` stays 0; an entry that is not
    recoverable says why in ``reason``. ``ident`` is the physical unit and
    header index of its first extent. ``note`` always says which kind of entry
    it is, and an entry no directory entry names has an empty ``name`` and
    None for ``mode`` and ``mtime``.

    An exFAT entry (``kind`` "exfat", ExfatWalker.recover_deleted) is not a
    deleted file. It is an orphan: an in-use file entry set in an allocated
    directory cluster the live tree does not reach. ``ident`` is its first
    cluster and ``parent`` the cluster its entry set is in. ``parent_path`` is
    the chain of orphan directory names that leads to it, or None when no
    orphan directory entry names its directory cluster. ``mode`` and ``mtime``
    are None, because exFAT stores a wall clock and not an instant: ``times``
    holds the readings as stored, as listdir_records() gives them. ``times``
    is None for every other kind. ``missing`` stays 0 and ``reason`` says why
    an entry is not recoverable.
    """

    __slots__ = ("name", "parent", "parent_path", "is_dir", "size", "mode", "mtime",
                 "recoverable", "reason", "missing", "ident", "kind", "note", "times",
                 "_plan", "_walker")

    def __init__(self, kind, ident, name, parent, parent_path, size, mode, mtime,
                 n_missing, plan, walker):
        self.kind, self.ident, self.name = kind, ident, name
        self.parent, self.parent_path = parent, parent_path
        self.is_dir = False
        self.size, self.mode, self.mtime = size, mode, mtime
        self.missing = n_missing
        self.recoverable = not n_missing
        unit = "page" if kind == "yaffs2" else "block" if kind == "ubifs" else "byte"
        self.reason = "" if not n_missing else (
            f"{n_missing:,} {unit}{'s' if n_missing != 1 else ''} of its recorded size "
            "no longer on the flash (erased, or a hole never written)")
        self.note = ""
        self.times = None
        self._plan, self._walker = plan, walker

    def __repr__(self):
        state = "recoverable" if self.recoverable else f"not recoverable ({self.reason})"
        return (f"FlashDeletedFile({self.kind} {self.ident}, name={self.name!r}, "
                f"size={self.size}, {state})")


def _live_dir_paths(walker, limit=1_000_000):
    """{directory node: path under the root} for every live directory, so a
    deleted file can say where its folder is. The root's path is ""."""
    paths, stack, seen = {walker.root: ""}, [walker.root], 0
    while stack and seen < limit:
        node = stack.pop()
        for name, child in walker.listdir(node):
            seen += 1
            if child in paths:
                continue
            ent = walker.entry(child)
            if ent and ent[0] & S_IFMT == S_IFDIR:
                base = paths[node]
                paths[child] = f"{base}/{name}" if base else name
                stack.append(child)
    return paths


class Jffs2Unreadable(Exception):
    """JFFS2 content this reader cannot hand back; the message says why."""


def _jffs2_accurate(raw, e):
    """A node's bytes with the ACCURATE bit of its node type set again, as they
    were when its CRCs were computed: jffs2_mark_node_obsolete clears only
    that bit, on flash that allows it (fs/jffs2/nodemgmt.c:787 at v7.0)."""
    ntype = struct.unpack_from(e + "H", raw, 2)[0] | JFFS2_ACCURATE
    return raw[:2] + struct.pack(e + "H", ntype) + raw[4:]


def _kcrc32(data):
    """The kernel's crc32(0, data, len): crc32_le, no pre- or post-inversion."""
    import zlib
    return zlib.crc32(data, 0xFFFFFFFF) ^ 0xFFFFFFFF


def _rtime_decompress(src, dsize):
    """fs/jffs2/compr_rtime.c: pairs of (literal byte, repeat count). After
    each literal the decoder copies `repeat` bytes starting where the previous
    occurrence of that same literal value ended, byte by byte."""
    out = bytearray()
    positions = [0] * 256
    ip = 0
    try:
        while len(out) < dsize:
            value = src[ip]
            repeat = src[ip + 1]
            ip += 2
            out.append(value)
            back = positions[value]
            positions[value] = len(out)
            if repeat:
                if len(out) + repeat > dsize:
                    raise DecompressError("rtime run past the node's data size")
                for _ in range(repeat):
                    out.append(out[back])
                    back += 1
    except IndexError:
        raise DecompressError("rtime data ends early") from None
    return bytes(out)


def _jffs2_zlib(src, dsize):
    """fs/jffs2/compr_zlib.c: a stream with a valid zlib header and no preset
    dictionary is inflated raw after the header (so the Adler-32 is not
    checked), anything else as a zlib stream."""
    import zlib
    if (len(src) > 2 and not (src[1] & 0x20) and (src[0] & 0x0F) == 8
            and not ((src[0] << 8) + src[1]) % 31):
        d = zlib.decompressobj(-((src[0] >> 4) + 8))
        body = src[2:]
    else:
        d = zlib.decompressobj()
        body = src
    try:
        return d.decompress(body, dsize)
    except zlib.error as exc:
        raise DecompressError(f"zlib: {exc}") from None


def _jffs2_lzma(src, dsize):
    """OpenWrt's JFFS2 LZMA (compression 0x08, not in the mainline kernel): a raw
    LZMA stream with no header, its properties fixed in the code rather than
    stored, lc 0, lp 0, pb 0 and an 8 KiB dictionary, decoded to exactly the
    node's decompressed size, with nothing left over: a stream that stops short,
    or that would go on past that size (LZMA_STATUS_NOT_FINISHED), is refused
    (target/linux/generic/pending-6.12/530-jffs2_make_lzma_available.patch at
    OpenWrt d9f8ecc3, lines 200 to 214 for the decoder and 229 to 237 and 342
    to 348 for the properties)."""
    import lzma
    try:
        d = lzma.LZMADecompressor(lzma.FORMAT_RAW, filters=[{
            "id": lzma.FILTER_LZMA1, "lc": 0, "lp": 0, "pb": 0, "dict_size": 0x2000}])
        out = d.decompress(src, dsize)
        more = d.decompress(b"", 1) if len(out) == dsize else b""
    except lzma.LZMAError as exc:
        raise DecompressError(f"lzma: {exc}") from None
    if len(out) != dsize:
        raise DecompressError(f"lzma gave {len(out):,} bytes where the node records {dsize:,}")
    if more:
        raise DecompressError(f"lzma stream runs past the {dsize:,} bytes the node records")
    return out


def jffs2_decompress(compr, src, dsize):
    compr &= 0xFF
    if compr == 0:
        return bytes(src[:dsize])
    if compr == 1:
        return bytes(dsize)
    if compr == 2:
        return _rtime_decompress(src, dsize)
    if compr == 6:
        return _jffs2_zlib(src, dsize)
    if compr == 7:
        return lzo1x_decompress(src, dsize)[:dsize]
    if compr == 8:
        return _jffs2_lzma(src, dsize)
    raise DecompressError(f"JFFS2 compression {JFFS2_COMPR.get(compr, hex(compr))} "
                          "is not read here")


class Jffs2Walker:
    """List and read a JFFS2 filesystem by scanning every node in the region.
    A node is an inode number; the root is inode 1."""

    root = JFFS2_ROOT_INO

    def __init__(self, fh, base, size=None, endian=None, nand_fallback=True):
        self.fh, self.base = fh, base
        if size is None:
            size = image_size(fh) - base
        self.size = size
        self.endian = endian
        self.nand = None
        self._reset()
        self._scan()
        if not self.stats["valid"]:
            raise Jffs2Unreadable("no JFFS2 node with a valid header CRC")
        # On a raw NAND dump the spare bytes after each page split any node
        # that crosses a page: its header CRC still holds and its body or data
        # does not. When any node fails that way, each common NAND geometry is
        # tried with the spare stripped; one is kept only if it reads strictly
        # fewer failing nodes and at least as many good ones, so damage on a
        # dump with no spare never turns into a geometry.
        if nand_fallback and self.stats["bad"]:
            best = (self.stats["inode"] + self.stats["dirent"], self.stats["bad"], None)
            for page, spare, view in nand_views(fh, base, size):
                trial = Jffs2Walker(view, 0, view.size, endian=self.endian,
                                    nand_fallback=False)
                good = trial.stats["inode"] + trial.stats["dirent"]
                if trial.stats["bad"] < best[1] and good >= best[0]:
                    best = (good, trial.stats["bad"], trial)
                    trial.nand = (page, spare)
            if best[2] is not None:
                self.__dict__.update(best[2].__dict__)
        self._resolved = {}

    def _reset(self):
        self.inodes = collections.defaultdict(list)   # ino -> [inode node records]
        self.dirents = collections.defaultdict(dict)  # pino -> {name: (version, ino, type, mctime)}
        self.stats = collections.Counter()
        # For recover_deleted(): every dirent the scan read, and where each node
        # the kernel marked obsolete sits (on NOR, JFFS2 marks a node it
        # supersedes or frees by clearing one bit; its bytes are untouched).
        self.all_dirents = []                         # (version, pino, name, ino, mctime)
        self.obsolete = []                            # (offset, node type, endian)
        # For jffs2_filesystems(): where each clean marker and each valid
        # dirent sits, region-relative (in the spare-stripped view on NAND).
        self.cleanmarkers = []                        # offset
        self.dirent_nodes = []                        # (offset, pino, version, ino, dtype, name, mctime)

    def _scan(self):
        """Walk the region a 4 MiB chunk at a time, checking every 4-byte
        aligned magic for a header whose CRC holds. A node the header vouches
        for is read whole (it may cross into the next chunk) and skipped past;
        anything else moves the search on by 4 bytes."""
        magics = [m for m, e in ((b"\x85\x19", "<"), (b"\x19\x85", ">"))
                  if self.endian in (None, e)]
        pos = 0
        while pos < self.size:
            chunk = read_at(self.fh, self.base + pos, min(JFFS2_SCAN_CHUNK, self.size - pos))
            if not chunk:
                break
            i = 0
            while i < len(chunk):
                hits = [h for h in (chunk.find(m, i) for m in magics) if h >= 0]
                if not hits:
                    i = len(chunk)
                    break
                j = min(hits)
                if j % 4:
                    i = j + 1
                    continue
                hdr = chunk[j:j + 12]
                if len(hdr) < 12:
                    hdr = read_at(self.fh, self.base + pos + j, 12)
                e = "<" if chunk[j] == 0x85 else ">"
                i = j + (self._node(pos + j, hdr, e) or 4)
            pos += i

    def _node(self, off, hdr, e):
        """Record the node at `off` if its header CRC holds. Returns how far to
        advance (its padded length), or 0 if this is not a node."""
        if len(hdr) < 12:
            return 0
        magic, ntype, totlen, hcrc = struct.unpack(e + "HHII", hdr)
        if magic != JFFS2_MAGIC:
            return 0
        check = struct.pack(e + "HHI", magic, ntype | JFFS2_ACCURATE, totlen)
        if _kcrc32(check) != hcrc or totlen < 12 or totlen > self.size - off:
            return 0
        if self.endian is None:
            self.endian = e
        self.stats["valid"] += 1
        padded = (totlen + 3) & ~3
        if not ntype & JFFS2_ACCURATE:
            self.stats["obsolete"] += 1
            if (ntype | JFFS2_ACCURATE) in (JFFS2_DIRENT, JFFS2_INODE):
                self.obsolete.append((off, ntype | JFFS2_ACCURATE, e))
            return padded
        if ntype == JFFS2_DIRENT:
            self._dirent(off, totlen, e)
        elif ntype == JFFS2_INODE:
            self._inode(off, totlen, e)
        else:
            if ntype == JFFS2_CLEANMARKER:
                self.cleanmarkers.append(off)
            self.stats[{JFFS2_CLEANMARKER: "cleanmarker", JFFS2_PADDING: "padding",
                        JFFS2_SUMMARY: "summary", JFFS2_XATTR: "xattr",
                        JFFS2_XREF: "xref"}.get(ntype, "other")] += 1
        return padded

    def _parse_dirent(self, off, totlen, e, obsolete=False):
        """(pino, version, ino, mctime, dtype, name) for a dirent whose CRCs
        hold, else None. The header CRC is checked by the caller. An obsolete
        node's CRCs were computed with the ACCURATE bit still set, which the
        kernel cleared afterwards, so it is set again before they are checked."""
        raw = read_at(self.fh, self.base + off, totlen)
        if len(raw) < 40:
            return None
        if obsolete:
            raw = _jffs2_accurate(raw, e)
        pino, version, ino, mctime, nsize, dtype = struct.unpack_from(e + "IIIIBB", raw, 12)
        node_crc, name_crc = struct.unpack_from(e + "II", raw, 32)
        name = raw[40:40 + nsize]
        if (_kcrc32(raw[:32]) != node_crc or len(name) < nsize
                or _kcrc32(name) != name_crc or 40 + nsize > totlen):
            return None
        return pino, version, ino, mctime, dtype, name.decode("utf-8", "surrogateescape")

    def _dirent(self, off, totlen, e):
        d = self._parse_dirent(off, totlen, e)
        if d is None:
            self.stats["bad"] += 1
            return
        pino, version, ino, mctime, dtype, name = d
        self.stats["dirent"] += 1
        self.all_dirents.append((version, pino, name, ino, mctime))
        self.dirent_nodes.append((off, pino, version, ino, dtype, name, mctime))
        cur = self.dirents[pino].get(name)
        if cur is None or version > cur[0]:
            self.dirents[pino][name] = (version, ino, dtype, mctime)

    def _parse_inode(self, off, totlen, e, obsolete=False):
        """(ino, record) for an inode node whose node CRC holds, else None;
        the record's "data_ok" says whether its data CRC holds too. See
        _parse_dirent for `obsolete`."""
        raw = read_at(self.fh, self.base + off, 68)
        if len(raw) < 68:
            return None
        if obsolete:
            raw = _jffs2_accurate(raw, e)
        (ino, version, mode, uid, gid, isize, atime, mtime, ctime, doff, csize,
         dsize, compr, usercompr, flags, data_crc, node_crc) = \
            struct.unpack_from(e + "IIIHHIIIIIIIBBHII", raw, 12)
        if (_kcrc32(raw[:60]) != node_crc or doff > isize
                or ((csize + 68 + 3) & ~3) != ((totlen + 3) & ~3)):
            return None
        data = read_at(self.fh, self.base + off + 68, csize) if csize else b""
        return ino, dict(off=off, version=version, mode=mode, uid=uid,
                         gid=gid, isize=isize, mtime=mtime, ctime=ctime,
                         atime=atime, doff=doff, csize=csize, dsize=dsize,
                         compr=compr, data_crc=data_crc,
                         data_ok=len(data) == csize and _kcrc32(data) == data_crc)

    def _inode(self, off, totlen, e):
        got = self._parse_inode(off, totlen, e)
        if got is None:
            self.stats["bad"] += 1
            return
        ino, rec = got
        # A node whose data fails its CRC is dropped as the kernel drops it
        # (fs/jffs2/readinode.c check_node_data marks it obsolete), so an older
        # node for the same range shows through rather than the file failing.
        if not rec.pop("data_ok"):
            self.stats["bad"] += 1
            self.stats["data CRC failures"] += 1
            return
        self.stats["inode"] += 1
        compr = JFFS2_COMPR.get(rec["compr"], hex(rec["compr"]))
        self.stats["compr_" + compr] += bool(rec["csize"])
        self.inodes[ino].append(rec)

    # -- the tree ------------------------------------------------------------
    def _latest(self, ino):
        nodes = self.inodes.get(ino)
        return max(nodes, key=lambda n: n["version"]) if nodes else None

    def entry(self, ino):
        latest = self._latest(ino)
        if latest is None:
            if ino == JFFS2_ROOT_INO or self.dirents.get(ino):
                return (S_IFDIR | 0o755, 0, 0)
            return None
        mode, mtime = latest["mode"], latest["mtime"]
        if mode & S_IFMT == S_IFDIR:
            ents = self.dirents.get(ino, {})
            newest = max(ents.values(), key=lambda v: v[0], default=None)
            if newest and newest[0] > latest["version"]:
                mtime = newest[3]
            return (mode, 0, mtime)
        if mode & S_IFMT == S_IFLNK:
            return (mode, latest["isize"] or latest["dsize"], mtime)
        return (mode, latest["isize"], mtime)

    def listdir(self, ino):
        out = []
        for name, (_ver, target, _t, _m) in self.dirents.get(ino, {}).items():
            if target and target != ino:
                out.append((name, target))
        return sorted(out)

    def _data(self, node):
        raw = read_at(self.fh, self.base + node["off"] + 68, node["csize"])
        if len(raw) < node["csize"] or _kcrc32(raw) != node["data_crc"]:
            raise Jffs2Unreadable(f"data of node at {node['off']:#x} fails its CRC")
        return jffs2_decompress(node["compr"], raw, node["dsize"])

    def readlink(self, ino):
        latest = self._latest(ino)
        return self._data(latest).decode("utf-8", "surrogateescape") if latest else ""

    def read_file(self, ino, size):
        """The file rebuilt from every data node, oldest version first so a
        newer range overwrites an older one; unwritten ranges are holes."""
        latest = self._latest(ino)
        if latest is None or latest["mode"] & S_IFMT != S_IFREG:
            return
        isize = latest["isize"]
        buf = bytearray(isize)
        for node in sorted(self.inodes[ino], key=lambda n: n["version"]):
            if not node["dsize"] or node["doff"] >= isize:
                continue
            data = self._data(node)
            end = min(node["doff"] + node["dsize"], isize)
            buf[node["doff"]:end] = data[:end - node["doff"]].ljust(end - node["doff"], b"\0")
        view = memoryview(buf)[:min(size, isize)]
        for i in range(0, len(view), 1 << 20):
            yield bytes(view[i:i + (1 << 20)])

    # -- more than one filesystem in the region --------------------------------
    def node_conflicts(self, unit=1):
        """(conflicts, links, same_unit, units) for telling apart JFFS2
        filesystems that sit side by side in one region, with node offsets
        grouped into units of `unit` bytes.

        Within one filesystem an inode number and version name one node, and a
        directory's version and the name it records one dirent: the kernel takes
        each new version as ++highest_version of the inode (fs/jffs2/write.c,
        fs/jffs2/dir.c, fs/jffs2/gc.c at the commit cited above), garbage
        collection copies a pristine node as it is (gc.c:696), and the one
        rewrite that keeps a version, a partly obsoleted hole, keeps its range
        and takes only the mode bits, size and times anew (gc.c:1030-1098). So
        two nodes with the same inode number and version but a different file
        type, range or data CRC, or two dirents with the same parent and version
        but a different name or target, cannot share a filesystem. `conflicts` is the
        set of unit pairs holding such nodes, and `same_unit` counts the pairs
        that fall in one unit, which no split along units can separate. Nodes
        the kernel marked obsolete count too: their bytes are untouched and they
        belong to the filesystem that wrote them. `units` is every unit holding
        a node.

        `links` counts, per unit pair, a dirent and a node of the inode it
        names, of the file type the dirent records, or of the directory it sits
        in, whose ctime or mtime is the dirent's mctime. The kernel writes a new
        file's name with the new inode's ctime (write.c:518 jffs2_do_create); for
        a symlink, directory or device it reads the clock again for the name a
        moment after the inode (dir.c:412, 557, 733; fs.c:479), so the two
        usually agree to the second; and it gives the directory the name's time
        (dir.c:430-431), which the directory's next inode node carries. A name
        meeting a number the other filesystem also uses almost never matches.
        Only inode numbers that carry no conflicting node and no second file
        type count."""
        sigs = collections.defaultdict(lambda: collections.defaultdict(set))
        for ino, nodes in self.inodes.items():
            for n in nodes:
                sigs[("i", ino, n["version"])][(n["mode"] & S_IFMT, n["doff"], n["dsize"],
                                                  n["data_crc"])].add(n["off"] // unit)
        for off, pino, version, ino, _dt, name, _mct in self.dirent_nodes:
            sigs[("d", pino, version)][(name, ino)].add(off // unit)
        for off, ntype, e in self.obsolete:
            totlen = struct.unpack(e + "HHII", read_at(self.fh, self.base + off, 12))[2]
            if ntype == JFFS2_INODE:
                got = self._parse_inode(off, totlen, e, obsolete=True)
                if got:
                    ino, n = got
                    sigs[("i", ino, n["version"])][(n["mode"] & S_IFMT, n["doff"], n["dsize"],
                                                    n["data_crc"])].add(off // unit)
            else:
                d = self._parse_dirent(off, totlen, e, obsolete=True)
                if d:
                    pino, version, ino, _mct, _dt, name = d
                    sigs[("d", pino, version)][(name, ino)].add(off // unit)
        units = {u for by_sig in sigs.values() for held in by_sig.values() for u in held}
        conflicts, same_unit, reused = set(), 0, set()
        for key, by_sig in sigs.items():
            if len(by_sig) < 2:
                continue
            if key[0] == "i":
                reused.add(key[1])
            groups = list(by_sig.values())
            for i, first in enumerate(groups):
                for second in groups[i + 1:]:
                    for u in first:
                        for v in second:
                            if u == v:
                                same_unit += 1
                            else:
                                conflicts.add((min(u, v), max(u, v)))
        for ino, nodes in self.inodes.items():
            if len({n["mode"] & S_IFMT for n in nodes}) > 1:
                reused.add(ino)
        dtype_mode = {4: S_IFDIR, 8: S_IFREG, 10: S_IFLNK}
        links = collections.Counter()
        for off, pino, _version, ino, dtype, _name, mctime in self.dirent_nodes:
            u = off // unit
            ends = []
            if ino and ino not in reused:
                ends += [n for n in self.inodes.get(ino, ())
                         if n["mode"] & S_IFMT == dtype_mode.get(dtype)
                         and mctime in (n["ctime"], n["mtime"])]
            if pino not in reused:
                ends += [n for n in self.inodes.get(pino, ())
                         if n["mode"] & S_IFMT == S_IFDIR and mctime in (n["ctime"], n["mtime"])]
            for n in ends:
                v = n["off"] // unit
                if v != u:
                    links[(min(u, v), max(u, v))] += 1
        return conflicts, links, same_unit, units


    # -- deleted files ---------------------------------------------------------
    def recover_deleted(self):
        """Yield a FlashDeletedFile for every regular file whose inode nodes
        are still on the flash but that no live name reaches.

        JFFS2 deletes a name by writing a dirent pointing at inode 0, and frees
        the inode's nodes without erasing them: on NOR it clears their
        ACCURATE bit (their bytes are untouched), on NAND it cannot, so they
        stay valid. A deleted file is rebuilt from all of its nodes, obsolete
        or not, oldest version first, as read_file() rebuilds a live one, and
        named from the newest dirent that pointed at it. JFFS2 writes a hole as
        a node too, so a range no node covers is missing, not a hole. Two nodes
        of one inode with the same version mean the number served more than one
        file, and that inode is refused rather than mixed."""
        live, stack = {JFFS2_ROOT_INO}, [JFFS2_ROOT_INO]
        while stack:
            for _name, (_v, ino, _t, _m) in self.dirents.get(stack.pop(), {}).items():
                if ino and ino not in live:
                    live.add(ino)
                    stack.append(ino)
        nodes = collections.defaultdict(list)
        for ino, recs in self.inodes.items():
            if ino not in live:
                nodes[ino].extend(recs)
        names = list(self.all_dirents)
        for off, ntype, e in self.obsolete:
            hdr = read_at(self.fh, self.base + off, 12)
            if len(hdr) < 12:
                continue
            totlen = struct.unpack_from(e + "I", hdr, 4)[0]
            if ntype == JFFS2_INODE:
                got = self._parse_inode(off, totlen, e, obsolete=True)
                if got and got[0] not in live and got[1].pop("data_ok"):
                    nodes[got[0]].append(got[1])
            else:
                d = self._parse_dirent(off, totlen, e, obsolete=True)
                if d:
                    pino, version, ino, mctime, _dtype, name = d
                    names.append((version, pino, name, ino, mctime))
        named = {}
        for version, pino, name, ino, _mctime in names:
            if ino in nodes and (ino not in named or version > named[ino][0]):
                named[ino] = (version, pino, name)
        paths = _live_dir_paths(self)
        for ino in sorted(nodes):
            recs = sorted(nodes[ino], key=lambda n: n["version"])
            latest = recs[-1]
            if latest["mode"] & S_IFMT != S_IFREG:
                continue
            isize = latest["isize"]
            covered = bytearray(isize)
            for n in recs:
                if n["dsize"] and n["doff"] < isize:
                    end = min(n["doff"] + n["dsize"], isize)
                    covered[n["doff"]:end] = b"\x01" * (end - n["doff"])
            gap = isize - sum(covered)
            if len({n["version"] for n in recs}) != len(recs):
                gap = gap or isize or 1
            _v, pino, name = named.get(ino, (0, None, ""))
            e = FlashDeletedFile("jffs2", ino, name, pino, paths.get(pino), isize,
                                 latest["mode"], latest["mtime"], gap, recs, self)
            if gap and len({n["version"] for n in recs}) != len(recs):
                e.reason = "the inode number was used by more than one file"
            yield e

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file (recover_deleted())."""
        if not entry.recoverable:
            raise Jffs2Unreadable(f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        # pylint: disable=protected-access
        buf = bytearray(entry.size)
        for node in entry._plan:                       # oldest version first
            if not node["dsize"] or node["doff"] >= entry.size:
                continue
            data = self._data(node)
            end = min(node["doff"] + node["dsize"], entry.size)
            buf[node["doff"]:end] = data[:end - node["doff"]].ljust(end - node["doff"], b"\0")
        view = memoryview(buf)[:entry.size if size is None else min(size, entry.size)]
        for i in range(0, len(view), 1 << 20):
            yield bytes(view[i:i + (1 << 20)])

JFFS2_LEAD_MAX = 64 << 20      # how much erased flash may come before the first node


JFFS2_SPLIT_MAX_UNITS = 2048


def jffs2_filesystems(fh, base, size):
    """[(base, size)] of the JFFS2 filesystems in a region, in order.

    A flash dump with no partition table can hold two JFFS2 partitions side by
    side (an OpenWrt overlay and a vendor's settings, for example), and read as
    one region they mix: each filesystem numbers its inodes and versions from
    1, so a name from one would show the content of the other's file of the
    same number. Nodes that cannot share a filesystem (Jffs2Walker.
    node_conflicts) say the region holds more than one. It is then cut, along
    erase blocks, into contiguous pieces with no conflict inside any of them,
    choosing the cut that separates the fewest dirents from the inodes and
    directories they name. A partition is a contiguous run of erase blocks. A
    region with no conflicts, or one that cannot be cut cleanly, is returned
    whole.

    The erase block is the spacing of the clean markers the kernel writes at
    the start of each erased block (their greatest common divisor); with none
    (on NAND they live in the spare bytes) 4 KiB, no larger than any erase
    block, is the unit."""
    import math
    whole = [(base, size)]
    try:
        w = Jffs2Walker(fh, base, size)
    except (Jffs2Unreadable, OSError, struct.error):
        return whole
    unit = 0
    for off in w.cleanmarkers:
        unit = math.gcd(unit, off)
    # A whole page at least, so a boundary in the spare-stripped view maps to
    # the start of a page in the image (image_offset below).
    page = w.nand[0] if w.nand else 1
    unit = max(unit if unit >= 4096 else 4096, page)
    conflicts, links, same_unit, held = w.node_conflicts(unit)
    if not conflicts or same_unit:
        return whole
    units = sorted(held)
    m = len(units)
    if m > JFFS2_SPLIT_MAX_UNITS:
        return whole
    at = {u: i for i, u in enumerate(units)}
    last_conflict = [-1] * m                    # latest earlier unit it conflicts with
    for u, v in conflicts:
        last_conflict[at[v]] = max(last_conflict[at[v]], at[u])
    earlier = collections.defaultdict(list)     # unit index -> [(earlier index, links)]
    for (u, v), count in links.items():
        earlier[at[v]].append((at[u], count))
    # best[i] = (links cut, pieces, start of the last piece) for units[:i]
    best = [None] * (m + 1)
    best[0] = (0, 0, 0)
    for a in range(m):
        if best[a] is None:
            continue
        cut, reach = best[a][0], -1
        for b in range(a, m):
            reach = max(reach, last_conflict[b])
            if reach >= a:
                break
            cut += sum(c for i, c in earlier[b] if i < a)
            cand = (cut, best[a][1] + 1, a)
            if best[b + 1] is None or cand[:2] < best[b + 1][:2]:
                best[b + 1] = cand
    if best[m] is None or best[m][1] < 2:
        return whole
    starts, i = [], m
    while i > 0:
        starts.append(best[i][2])
        i = best[i][2]
    starts.reverse()

    def image_offset(view_off):
        if w.nand:
            pg, spare = w.nand
            return (view_off // pg) * (pg + spare)
        return view_off
    # Each piece opens at the first unit holding its own nodes, so a piece holds
    # exactly the units the split gave it and no conflicting pair.
    bounds = [0] + [image_offset(units[s] * unit) for s in starts[1:]] + [size]
    return [(base + lo, hi - lo) for lo, hi in zip(bounds, bounds[1:])]


def _jffs2_first_node(fh, base, size):
    """(endian, magic) of the node a JFFS2 region opens with, or None.

    The region may open with erased flash (0xFF): after garbage collection whole
    eraseblocks at the start can be empty. The first byte that is not 0xFF must
    begin a 4-byte aligned node magic whose header CRC holds."""
    pos, limit = 0, min(size, JFFS2_LEAD_MAX)
    while pos < limit:
        chunk = read_at(fh, base + pos, min(65536, limit - pos))
        if not chunk:
            return None
        rest = chunk.lstrip(b"\xff")
        if rest:
            pos += len(chunk) - len(rest)
            break
        pos += len(chunk)
    else:
        return None
    pos -= pos % 4
    head = read_at(fh, base + pos, 12)
    for m, e in ((b"\x85\x19", "<"), (b"\x19\x85", ">"), (b"\x84\x19", "<"), (b"\x19\x84", ">")):
        j = head.find(m)
        if j < 0 or j % 4 or len(head) - j < 12 or head[:j].strip(b"\xff"):
            continue
        magic, ntype, totlen, hcrc = struct.unpack_from(e + "HHII", head, j)
        chk = struct.pack(e + "HHI", magic, ntype | JFFS2_ACCURATE, totlen)
        if _kcrc32(chk) == hcrc:
            return e, magic
    return None


def identify_jffs2(fh, base, size=None):
    """Return ("jffs2", lines) when the region starts with JFFS2 nodes.

    JFFS2 has no superblock, so the test is structural: the region's first
    bytes that are not erased flash (0xFF) must open a 4-byte aligned node whose
    header CRC holds, and a scan of the whole region must find inode or
    directory nodes. The old 0x1984 magic (the first JFFS2 layout) is reported,
    not walked.

    A raw NAND dump holds each page's spare bytes after its data, and on NAND
    JFFS2 keeps its clean markers there, so the spare is not 0xFF and the test
    fails on the dump as taken. Each common NAND geometry is then tried with
    the spare stripped, and the one that reads the most inode and directory
    nodes, then the fewest damaged ones, is kept.
    """
    if size is None:
        size = image_size(fh) - base
    found = _jffs2_first_node(fh, base, size)
    if found is not None:
        e, magic = found
        if magic == JFFS2_OLD_MAGIC:
            return "jffs2", ["layout       the pre-release 0x1984 magic; reported, not walked"]
        try:
            w = Jffs2Walker(fh, base, size, endian=e)
        except Jffs2Unreadable:
            return None
    else:
        best = None
        for page, spare, view in nand_views(fh, base, size):
            f = _jffs2_first_node(view, 0, view.size)
            if f is None or f[1] == JFFS2_OLD_MAGIC:
                continue
            try:
                trial = Jffs2Walker(view, 0, view.size, endian=f[0], nand_fallback=False)
            except Jffs2Unreadable:
                continue
            rank = (trial.stats["inode"] + trial.stats["dirent"], -trial.stats["bad"])
            if best is None or rank > best[0]:
                trial.nand = (page, spare)
                best = (rank, trial)
        if best is None:
            return None
        w = best[1]
    _remember_walker(fh, base, size, "jffs2", w)
    s = w.stats
    if not (s["inode"] or s["dirent"]):
        return None
    comps = sorted(k[6:] for k, v in s.items() if k.startswith("compr_") and v)
    live = sum(1 for ents in w.dirents.values() for v in ents.values() if v[1])
    orphans = sum(1 for ents in w.dirents.values() for v in ents.values()
                  if v[1] and v[1] not in w.inodes and not w.dirents.get(v[1]))
    lines = [
        f"byte order   {'little' if w.endian == '<' else 'big'} endian",
    ] + ([f"NAND         a raw dump: {w.nand[0]}-byte pages each followed by {w.nand[1]} "
          "spare bytes, read with the spare stripped"] if w.nand else []) + [
        f"nodes        {s['valid']:,} with a valid header: {s['inode']:,} inode, "
        f"{s['dirent']:,} directory entry, {s['obsolete']:,} marked obsolete",
        f"entries      {live:,} names currently linked, {len(w.inodes):,} inodes "
        "with data nodes",
        f"compression  {', '.join(comps) if comps else 'none used'}",
    ]
    if s["bad"]:
        lines.append(f"damaged      {s['bad']:,} nodes whose header CRC held but whose body "
                     f"or data CRC did not ({s['data CRC failures']:,} data); dropped, as the "
                     "kernel drops them")
    if orphans:
        lines.append(f"note         {orphans:,} linked names lead to an inode with no readable "
                     "node; they are not listed")
    unread = [c for c in comps if c not in ("none", "zero", "rtime", "zlib", "lzo", "lzma")]
    if unread:
        lines.append(f"note         {', '.join(unread)} compressed data is not read here")
    return "jffs2", lines


# ---------------------------------------------------------------------------
# UBI and UBIFS
#
# UBI is the volume layer under UBIFS on raw NAND: every physical eraseblock
# (PEB) opens with an erase counter (EC) header and, once mapped, a volume
# identifier (VID) header naming the volume and logical eraseblock (LEB) it
# holds. Read from the Linux kernel at v7.0 (commit
# 028ef9c96e96197026887c0f092424679298aae8):
#
#   struct ubi_ec_hdr, "UBI#", 64 bytes     drivers/mtd/ubi/ubi-media.h:29,147
#   struct ubi_vid_hdr, "UBI!", 64 bytes    drivers/mtd/ubi/ubi-media.h:31,268
#   header CRCs: crc32 seeded 0xFFFFFFFF     drivers/mtd/ubi/ubi-media.h:26,
#     over all but the last 4 bytes             110-111
#   layout volume 0x7FFFEFFF holds the        drivers/mtd/ubi/ubi-media.h:294,298
#     volume table, 172-byte records          drivers/mtd/ubi/ubi-media.h:312,355
#   of two copies of a LEB the higher sqnum   drivers/mtd/ubi/attach.c
#     wins, unless it is a copy (copy_flag)     ubi_compare_lebs
#     whose data CRC fails
#   a static volume's LEB holds data_size     drivers/mtd/ubi/attach.c,
#     bytes; an unmapped LEB reads as 0xFF      drivers/mtd/ubi/eba.c
#
# The PEB size is recorded nowhere; it is the distance between EC headers.
# ---------------------------------------------------------------------------
UBI_EC_MAGIC, UBI_VID_MAGIC = b"UBI#", b"UBI!"
UBI_LAYOUT_VOL = 0x7FFFEFFF
UBI_VTBL_REC = 172
UBI_VOL_NAMES = {1: "dynamic", 2: "static"}
UBI_NODE_SHIFT = 56
UBI_CONTAINER = (1 << 63) - 1


class UbiUnreadable(Exception):
    """A UBI structure this reader cannot use; the message says which."""


def _ubi_crc(data):
    """The kernel's crc32(UBI_CRC32_INIT, ...): crc32_le seeded 0xFFFFFFFF
    with no final inversion, which is zlib's crc32 with its output inverted."""
    import zlib
    return zlib.crc32(data) ^ 0xFFFFFFFF


_CRC32_TABLE = []
# The shortest CRC-32 codeword of weight three is 91,640 bits long (the self-test
# finds it), so on a message of at most 11,450 bytes two flipped bits never give
# the CRC change one flipped bit gives, and a one-bit repair cannot turn a
# two-bit error into wrong bytes. UBIFS nodes are far shorter.
CRC32_ONE_BIT_MAX = 11450


def crc32_one_bit(data, want):
    """(byte, bit) of the single bit whose flip gives `data` the zlib-style CRC-32
    `want`, or None. A raw NAND dump holds the bits as the cells gave them, before
    the controller's ECC corrected them, so a node the device read cleanly can
    fail its CRC here by one flipped bit. CRC-32 is linear, so the change a flip
    at each position makes to the CRC is computed once per position (a register
    started at zero and clocked through the zero bytes after it) and compared
    with the change needed; for the lengths flash nodes have, two different
    single-bit flips never give the same change, so at most one position fits
    (no two collide within 2 MB, measured)."""
    import zlib
    if not _CRC32_TABLE:
        for n in range(256):
            c = n
            for _ in range(8):
                c = (c >> 1) ^ 0xEDB88320 if c & 1 else c >> 1
            _CRC32_TABLE.append(c)
    t = _CRC32_TABLE
    need = zlib.crc32(data) ^ want
    if not need:
        return None
    states = [t[1 << b] for b in range(8)]
    for k in range(len(data) - 1, -1, -1):
        if need in states:
            return k, states.index(need)
        states = [t[x & 0xFF] ^ (x >> 8) for x in states]
    return None


def _ubifs_repair(raw):
    """`raw` (a UBIFS node whose CRC failed) with one bit restored, or None. A
    flip inside the stored CRC itself leaves the node's bytes as they are."""
    if len(raw) - 8 > CRC32_ONE_BIT_MAX:
        return None
    stored = struct.unpack_from("<I", raw, 4)[0]
    if bin(stored ^ _ubi_crc(raw[8:])).count("1") == 1:
        return bytes(raw)
    fix = crc32_one_bit(raw[8:], stored ^ 0xFFFFFFFF)
    if fix is None:
        return None
    fixed = bytearray(raw)
    fixed[8 + fix[0]] ^= 1 << fix[1]
    return bytes(fixed)


def _ubi_ec(raw):
    """(vid_hdr_offset, data_offset, image_seq, ec) of a valid EC header, or None."""
    if len(raw) < 64 or raw[:4] != UBI_EC_MAGIC:
        return None
    if _ubi_crc(raw[:60]) != struct.unpack_from(">I", raw, 60)[0]:
        return None
    ec, vid, data, seq = struct.unpack_from(">QIII", raw, 8)
    return vid, data, seq, ec


def _ubi_vid(raw):
    if len(raw) < 64 or raw[:4] != UBI_VID_MAGIC:
        return None
    if _ubi_crc(raw[:60]) != struct.unpack_from(">I", raw, 60)[0]:
        return None
    vol_type, copy_flag, compat, vol_id, lnum = struct.unpack_from(">BBBII", raw, 5)
    data_size, used_ebs, data_pad, data_crc = struct.unpack_from(">IIII", raw, 20)
    sqnum = struct.unpack_from(">Q", raw, 40)[0]
    return dict(vol_type=vol_type, copy_flag=copy_flag, vol_id=vol_id, lnum=lnum,
                data_size=data_size, used_ebs=used_ebs, data_pad=data_pad,
                data_crc=data_crc, sqnum=sqnum)


def ubi_peb_size(fh, base, size):
    """The PEB size, found as the distance to the next valid EC header of the
    same image, tried at every 1 KiB step up to 8 MiB. None when there is
    only one PEB (a region that small cannot be told apart)."""
    first = _ubi_ec(read_at(fh, base, 64))
    if first is None:
        return None
    step = 1024
    limit = min(size, 8 << 20)
    pos = step
    while pos < limit:
        chunk = read_at(fh, base + pos, min(1 << 20, limit - pos))
        if not chunk:
            break
        j = chunk.find(UBI_EC_MAGIC)
        while j >= 0:
            if (pos + j) % step == 0:
                ec = _ubi_ec(chunk[j:j + 64] if j + 64 <= len(chunk)
                             else read_at(fh, base + pos + j, 64))
                if ec and ec[2] == first[2]:
                    return pos + j
            j = chunk.find(UBI_EC_MAGIC, j + 1)
        pos += len(chunk)
    return None


class UbiImage:
    """The PEB map and volume table of a UBI image at `base`."""

    def __init__(self, fh, base, size=None):
        self.fh, self.base = fh, base
        if size is None:
            size = image_size(fh) - base
        ec0 = _ubi_ec(read_at(fh, base, 64))
        if ec0 is None:
            raise UbiUnreadable("no UBI erase counter header at the start")
        self.vid_off, self.data_off, self.image_seq, _ = ec0
        self.peb = ubi_peb_size(fh, base, size) or size
        if not (0 < self.vid_off < self.peb and 0 < self.data_off < self.peb):
            raise UbiUnreadable("EC header offsets do not fit the eraseblock")
        self.leb_size = self.peb - self.data_off
        self.npebs = size // self.peb
        self.stats = collections.Counter()
        cands = collections.defaultdict(list)
        for p in range(self.npebs):
            at = base + p * self.peb
            ec = _ubi_ec(read_at(fh, at, 64))
            if ec is None:
                self.stats["no EC header"] += 1
                continue
            if ec[2] != self.image_seq:
                self.stats["other image_seq"] += 1
                continue
            vid = _ubi_vid(read_at(fh, at + ec[0], 64))
            if vid is None:
                self.stats["free"] += 1
                continue
            self.stats["mapped"] += 1
            vid["peb"] = p
            vid["data_at"] = at + ec[1]
            cands[(vid["vol_id"], vid["lnum"])].append(vid)
        self.map = {}
        for key, vids in cands.items():
            vids.sort(key=lambda v: v["sqnum"], reverse=True)
            for i, v in enumerate(vids):
                # The kernel checks a copy's data CRC only against another copy
                # of the same LEB (attach.c ubi_compare_lebs); a LEB seen once is
                # attached as it is (ubi_add_to_av).
                if v["copy_flag"] and i + 1 < len(vids) and not self._data_ok(v):
                    self.stats["copy with a bad data CRC, older copy used"] += 1
                    continue
                if v["copy_flag"] and i + 1 == len(vids) and not self._data_ok(v):
                    self.stats["copy with a bad data CRC, the only copy, used"] += 1
                self.map[key] = v
                # An older copy still on the flash (left by a rewrite or a move
                # that was cut short) holds that block's earlier contents.
                if len(vids) - i - 1:
                    self.stats["an older copy of a block, not the one read"] += len(vids) - i - 1
                break
        self.volumes = self._volume_table()

    def _data_ok(self, vid):
        data = read_at(self.fh, vid["data_at"], vid["data_size"])
        return len(data) == vid["data_size"] and _ubi_crc(data) == vid["data_crc"]

    def _volume_table(self):
        """The volume table from whichever layout volume copy reads, with
        vtbl_ok saying whether one did."""
        self.vtbl_ok = True
        for lnum in (0, 1):
            vid = self.map.get((UBI_LAYOUT_VOL, lnum))
            if vid is None:
                continue
            raw = read_at(self.fh, vid["data_at"], self.leb_size)
            vols = []
            ok = True
            for i in range(min(128, len(raw) // UBI_VTBL_REC)):
                rec = raw[i * UBI_VTBL_REC:(i + 1) * UBI_VTBL_REC]
                if _ubi_crc(rec[:168]) != struct.unpack_from(">I", rec, 168)[0]:
                    ok = False
                    break
                reserved, align, data_pad, vtype, upd, nlen = struct.unpack_from(">IIIBBH", rec, 0)
                if not reserved:
                    continue
                name = rec[16:16 + min(nlen, 127)].decode("utf-8", "replace")
                vols.append(dict(id=i, name=name, type=vtype, reserved=reserved,
                                 data_pad=data_pad, update_marker=upd,
                                 flags=rec[144]))
            if ok:
                return vols
        # No readable table: offer every volume id that has mapped LEBs.
        self.vtbl_ok = False
        ids = sorted({k[0] for k in self.map if k[0] < UBI_LAYOUT_VOL})
        return [dict(id=i, name=f"vol{i}", type=0, reserved=0, data_pad=0,
                     update_marker=0, flags=0) for i in ids]

    def volume_view(self, vol):
        return UbiVolumeView(self, vol)


class UbiVolumeView:
    """One UBI volume read as a flat file: LEB n at n * usable LEB size, an
    unmapped LEB as 0xFF, a static volume ending where its data ends."""

    def __init__(self, ubi, vol):
        self.ubi, self.vol = ubi, vol
        self.leb = ubi.leb_size - vol["data_pad"]
        lebs = {k[1]: v for k, v in ubi.map.items() if k[0] == vol["id"]}
        self.lebs = lebs
        self.name = vol["name"]
        if vol["type"] == 2 and lebs:
            used = next(iter(lebs.values()))["used_ebs"]
            last = lebs.get(used - 1)
            self.size = (used - 1) * self.leb + (last["data_size"] if last else self.leb)
        else:
            self.size = ((max(lebs) + 1) if lebs else 0) * self.leb
        self._pos = 0

    def seek(self, offset, whence=0):
        self._pos = offset if whence == 0 else (self._pos + offset if whence == 1
                                                else self.size + offset)
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if n is None or n < 0:
            n = max(self.size - self._pos, 0)
        out = bytearray()
        pos = self._pos
        end = min(pos + n, self.size)
        while pos < end:
            lnum, off = divmod(pos, self.leb)
            take = min(self.leb - off, end - pos)
            vid = self.lebs.get(lnum)
            if vid is None:
                out += b"\xff" * take
            else:
                chunk = read_at(self.ubi.fh, vid["data_at"] + off, take)
                out += chunk
                if len(chunk) < take:
                    break
            pos += take
        self._pos = pos
        return bytes(out)


class UbiWalker:
    """A UBI image as a directory of its volumes. A volume that holds UBIFS or
    SquashFS is walked as that filesystem under the volume's name; any other
    volume (a kernel, a device tree, an environment) is one regular file of
    the volume's bytes. A node carries the volume index in its top bits and
    the inner filesystem's own node below them."""

    root = UBI_CONTAINER

    def __init__(self, fh, base, size=None):
        if size is None:
            size = image_size(fh) - base
        self.ubi, self.nand = UbiImage(fh, base, size), None
        # On a raw NAND dump the spare bytes after each page shift everything
        # past an eraseblock's first page. The EC and VID headers may still read
        # (a VID header in a 512-byte subpage lies inside the first page), but
        # the volume table, whose data starts at a later page, cannot. When it
        # does not read, each common NAND geometry is tried with the spare
        # stripped, and the first whose volume table reads is kept.
        if not self.ubi.vtbl_ok:
            for page, spare, view in nand_views(fh, base, size):
                try:
                    trial = UbiImage(view, 0, view.size)
                except UbiUnreadable:
                    continue
                if trial.vtbl_ok:
                    self.ubi, self.nand = trial, (page, spare)
                    break
        self.inner = []                        # (volume, view, walker or None, note)
        for vol in self.ubi.volumes:
            view = self.ubi.volume_view(vol)
            walker, kind = None, "raw"
            head = view.read(8) if view.size else b""
            view.seek(0)
            try:
                if head[:4] == b"hsqs":
                    walker, kind = SquashfsWalker(view, 0), "squashfs"
                elif struct.unpack_from("<I", head.ljust(4, b"\0"))[0] == UBIFS_MAGIC:
                    walker, kind = UbifsWalker(view, 0), "ubifs"
            except Exception as exc:          # a volume that will not open is a file
                walker, kind = None, f"raw ({type(exc).__name__}: {exc})"
            self.inner.append((vol, view, walker, kind))

    def _split(self, node):
        return node >> UBI_NODE_SHIFT, node & ((1 << UBI_NODE_SHIFT) - 1)

    def _vol_node(self, i):
        vol, view, walker, _ = self.inner[i]
        return (i << UBI_NODE_SHIFT) | (walker.root if walker else 0)

    def listdir(self, node):
        if node == UBI_CONTAINER:
            return [(vol["name"] or f"vol{vol['id']}", self._vol_node(i))
                    for i, (vol, _v, _w, _k) in enumerate(self.inner)]
        i, inner = self._split(node)
        walker = self.inner[i][2]
        if walker is None:
            return []
        return [(name, (i << UBI_NODE_SHIFT) | child) for name, child in walker.listdir(inner)]

    def entry(self, node):
        # UBI records no time for a volume, so a volume that is not a
        # filesystem, and the container above the volumes, have none (None).
        if node == UBI_CONTAINER:
            return (S_IFDIR | 0o755, 0, None)
        i, inner = self._split(node)
        vol, view, walker, _ = self.inner[i]
        if walker is None:
            return (S_IFREG | 0o444, view.size, None)
        return walker.entry(inner)

    def readlink(self, node):
        i, inner = self._split(node)
        return self.inner[i][2].readlink(inner)

    def read_file(self, node, size):
        i, inner = self._split(node)
        vol, view, walker, _ = self.inner[i]
        if walker is None:
            view.seek(0)
            left = min(size, view.size)
            while left > 0:
                chunk = view.read(min(left, 1 << 20))
                if not chunk:
                    return
                yield chunk
                left -= len(chunk)
            return
        for chunk in walker.read_file(inner, size):
            yield chunk

    def recover_deleted(self):
        """Deleted files from every UBIFS volume (UbifsWalker.recover_deleted),
        with the parent's node and path given the way this walker lists them:
        under the volume's name."""
        for i, (vol, _view, walker, kind) in enumerate(self.inner):
            if kind != "ubifs":
                continue
            top = vol["name"] or f"vol{vol['id']}"
            for e in walker.recover_deleted():
                if e.parent is not None:
                    e.parent = (i << UBI_NODE_SHIFT) | e.parent
                if e.parent_path is not None:
                    e.parent_path = f"{top}/{e.parent_path}" if e.parent_path else top
                yield e

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file, read by the UBIFS walker
        of the volume it came from."""
        # pylint: disable=protected-access
        return entry._walker.read_deleted(entry, size)


def identify_ubi(fh, base, size=None):
    """Return ("ubi", lines) for a UBI image at base: an EC header whose CRC
    holds, a volume table that reads, and at least one mapped eraseblock."""
    if _ubi_ec(read_at(fh, base, 64)) is None:
        return None
    if size is None:
        size = image_size(fh) - base
    try:
        w = UbiWalker(fh, base, size)
    except UbiUnreadable:
        return None
    _remember_walker(fh, base, size, "ubi", w)
    u = w.ubi
    if not u.stats["mapped"]:
        return None
    lines = [
        f"eraseblocks  {u.npebs:,} of {human(u.peb)}   ({u.stats['mapped']:,} mapped, "
        f"{u.stats['free']:,} free)",
        f"layout       VID header at {u.vid_off}, data at {u.data_off}, so each "
        f"logical eraseblock holds {human(u.leb_size)}",
        f"image_seq    {u.image_seq:#010x}",
    ]
    if w.nand:
        lines.insert(0, f"NAND         a raw dump: {w.nand[0]}-byte pages each followed by "
                        f"{w.nand[1]} spare bytes, read with the spare stripped")
    for vol, view, walker, kind in w.inner:
        lines.append(f"volume {vol['id']:<5} {vol['name'] or '(no name)'}: "
                     f"{UBI_VOL_NAMES.get(vol['type'], 'unknown')}, {human(view.size)}, {kind}"
                     + ("; interrupted update marker set" if vol["update_marker"] else ""))
        if getattr(walker, "bit_repairs", None):
            lines.append(UBIFS_BIT_REPAIR_NOTE.format(
                n=len(walker.bit_repairs), where=f" in volume {vol['id']}"))
    odd = {k: v for k, v in u.stats.items() if k not in ("mapped", "free")}
    for k, v in sorted(odd.items()):
        lines.append(f"note         {v:,} eraseblock(s): {k}")
    return "ubi", lines


# ---------------------------------------------------------------------------
# UBIFS, from the same kernel tree:
#
#   struct ubifs_ch, magic 0x06101831        fs/ubifs/ubifs-media.h:25, ubifs_ch
#   node CRC: crc32 seeded 0xFFFFFFFF over    fs/ubifs/io.c ubifs_check_node
#     the node from byte 8 to its end
#   superblock LEB 0, master LEBs 1 and 2,    fs/ubifs/ubifs-media.h:227-231
#     log from LEB 3
#   inode, data, dent, trun, idx node layouts fs/ubifs/ubifs-media.h
#   8-byte key: le32 inode, then type << 29   fs/ubifs/key.h, ubifs-media.h:199
#     | block or name hash
#   index branch: lnum, offs, len, key and    fs/ubifs/misc.h ubifs_idx_branch
#     (on authenticated volumes) a hash
#   journal: from the master's log LEB, a CS  fs/ubifs/replay.c replay_log_leb,
#     node then REF nodes naming bud LEBs;      replay_bud, apply_replay_entry,
#     bud nodes are applied in sqnum order;     inode_still_linked,
#     nlink 0 removes an inode unless its       trun_remove_range
#     last inode node relinks it; a dent with
#     inum 0 removes the name; a truncation
#     node drops the whole blocks past new_size
#   data node compression: LZO1X, raw deflate fs/ubifs/compress.c,
#     (the kernel's "deflate"), zstd            crypto/deflate.c
#   a missing data block is a hole            fs/ubifs/file.c read_block
# ---------------------------------------------------------------------------
UBIFS_MAGIC = 0x06101831
UBIFS_BIT_REPAIR_NOTE = ("bit errors   {n:,} node(s){where} failed their CRC by one flipped bit "
                         "and were read with that bit restored, as the NAND controller's "
                         "ECC would have done")
(UBIFS_INO_NODE, UBIFS_DATA_NODE, UBIFS_DENT_NODE, UBIFS_XENT_NODE, UBIFS_TRUN_NODE,
 UBIFS_PAD_NODE, UBIFS_SB_NODE, UBIFS_MST_NODE, UBIFS_REF_NODE, UBIFS_IDX_NODE,
 UBIFS_CS_NODE) = range(11)
UBIFS_KEY_INO, UBIFS_KEY_DATA, UBIFS_KEY_DENT, UBIFS_KEY_XENT = range(4)
UBIFS_COMPR = {0: "none", 1: "lzo", 2: "zlib", 3: "zstd"}
UBIFS_BLOCK = 4096
UBIFS_LOG_LNUM = 3
UBIFS_XATTR_FL = 0x20                  # fs/ubifs/ubifs-media.h:330
UBIFS_CRYPT_FL = 0x40
UBIFS_FLG_ENCRYPTION = 0x10
UBIFS_FLG_AUTHENTICATION = 0x20
UBIFS_MST_DIRTY = 1


class UbifsUnreadable(Exception):
    """A UBIFS structure or file this reader cannot hand back."""


def ubifs_decompress(ctype, data, limit):
    import zlib
    if ctype == 0:
        return bytes(data)
    if ctype == 1:
        return lzo1x_decompress(data, limit)
    if ctype == 2:
        try:
            return zlib.decompress(bytes(data), -15)
        except zlib.error as exc:
            raise DecompressError(f"deflate: {exc}") from None
    if ctype == 3:
        return zstd_decompress(data)
    raise DecompressError(f"UBIFS compression type {ctype} is not one the format defines")


def _ubifs_truncate(blocks, old, new):
    """Drop from {block: location} the whole blocks a truncation node from
    size `old` to `new` removes, as fs/ubifs/replay.c trun_remove_range does.
    The journal replay and deleted-file recovery share it."""
    lo = (new + UBIFS_BLOCK - 1) // UBIFS_BLOCK
    hi = old // UBIFS_BLOCK - (0 if old % UBIFS_BLOCK else 1)
    for blk in [b for b in blocks if lo <= b <= hi]:
        del blocks[blk]


class UbifsWalker:
    """List and read a UBIFS volume: the committed index, with the journal
    replayed over it. The volume is a flat file of LEBs (a UBI volume view, or
    the output of mkfs.ubifs itself); a node is an inode number."""

    root = 1

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        self.leb_size = 0                      # LEB 0 is read before the size is known
        self.stats = collections.Counter()
        self.bit_repairs = set()               # (lnum, offs) of nodes read with one bit restored
        sb = self._node(0, 0)
        if sb is None or sb[20] != UBIFS_SB_NODE:
            raise UbifsUnreadable("no UBIFS superblock node at LEB 0")
        (self.key_hash, self.key_fmt, self.flags, self.min_io, self.leb_size,
         self.leb_cnt, _max_leb, _max_bud, self.log_lebs, self.lpt_lebs,
         self.orph_lebs, _jheads, self.fanout, _lsave, self.fmt_version,
         self.default_compr) = struct.unpack_from("<BBIIIIIQIIIIIIIH", sb, 26)
        self.uuid = sb[108:124].hex()
        if self.key_fmt != 0:
            raise UbifsUnreadable(f"key format {self.key_fmt}; only the simple format exists")
        if not (4096 <= self.leb_size <= 16 << 20):
            raise UbifsUnreadable("implausible LEB size")
        self.master = self._master()
        if self.master is None:
            raise UbifsUnreadable("no master node reads in LEB 1 or 2")
        self.inodes, self.data, self.dents = {}, collections.defaultdict(dict), \
            collections.defaultdict(dict)
        self._walk_index()
        self._replay()
        self._ino_cache = {}

    # -- nodes ---------------------------------------------------------------
    def _node(self, lnum, offs, length=None, want=None):
        """The node at lnum:offs if its magic and CRC hold, else None."""
        at = self.base + lnum * self.leb_size + offs
        head = read_at(self.fh, at, 24)
        if len(head) < 24 or struct.unpack_from("<I", head, 0)[0] != UBIFS_MAGIC:
            return None
        nlen = struct.unpack_from("<I", head, 16)[0]
        if nlen < 24 or nlen > 1 << 20 or (length is not None and nlen != length):
            return None
        raw = read_at(self.fh, at, nlen)
        if len(raw) < nlen:
            return None
        if _ubi_crc(raw[8:]) != struct.unpack_from("<I", raw, 4)[0]:
            raw = _ubifs_repair(raw)
            if raw is None:
                return None
            self.bit_repairs.add((lnum, offs))
        if want is not None and raw[20] != want:
            return None
        return raw

    def _unread(self, blk, lnum, offs):
        """Why the data node for `blk` at lnum:offs did not read."""
        head = read_at(self.fh, self.base + lnum * self.leb_size + offs, 24)
        where = f"data node for block {blk} (LEB {lnum}, offset {offs:,})"
        if head[:4] == b"\xff" * 4:
            return f"{where} is erased flash: no copy of it is in the image"
        if len(head) == 24 and struct.unpack_from("<I", head, 0)[0] == UBIFS_MAGIC:
            return f"{where} fails its CRC, by more than one flipped bit"
        return f"{where} does not read"

    def _scan_leb(self, lnum, offs):
        """Every valid node in LEB lnum from offs on, as (offs, raw), stepping
        over padding nodes and 0xCE padding bytes, stopping at erased space or
        at the first thing that is not a node."""
        buf = read_at(self.fh, self.base + lnum * self.leb_size, self.leb_size)
        out = []
        while offs + 24 <= len(buf):
            magic = struct.unpack_from("<I", buf, offs)[0]
            if magic == 0xFFFFFFFF:
                break
            if magic != UBIFS_MAGIC:
                pad = 0
                while pad < 28 and offs + pad < len(buf) and buf[offs + pad] == 0xCE:
                    pad += 1
                if not pad or pad & 7:
                    break
                offs += pad
                continue
            nlen = struct.unpack_from("<I", buf, offs + 16)[0]
            raw = buf[offs:offs + nlen]
            if nlen < 24 or len(raw) < nlen:
                break
            if _ubi_crc(raw[8:]) != struct.unpack_from("<I", raw, 4)[0]:
                raw = _ubifs_repair(raw)
                if raw is None:
                    break
                self.bit_repairs.add((lnum, offs))
            if raw[20] == UBIFS_PAD_NODE:
                offs += nlen + struct.unpack_from("<I", raw, 24)[0]
                continue
            out.append((offs, raw))
            offs += (nlen + 7) & ~7
        return out

    def _master(self):
        best = None
        for lnum in (1, 2):
            for _offs, raw in self._scan_leb(lnum, 0):
                if raw[20] != UBIFS_MST_NODE:
                    continue
                sq = struct.unpack_from("<Q", raw, 8)[0]
                if best is None or sq > best[0]:
                    best = (sq, raw)
            if best:
                break
        if best is None:
            return None
        raw = best[1]
        (highest, cmt_no, flags, log_lnum, root_lnum, root_offs, root_len, _gc,
         _ihl, _iho, _isize, total_free, total_dirty, total_used, total_dead,
         total_dark) = struct.unpack_from("<QQIIIIIIIIQQQQQQ", raw, 24)
        return dict(highest_inum=highest, cmt_no=cmt_no, flags=flags, log_lnum=log_lnum,
                    root=(root_lnum, root_offs, root_len), total_free=total_free,
                    total_used=total_used, total_dirty=total_dirty)

    @staticmethod
    def _key(raw, at):
        inum, word = struct.unpack_from("<II", raw, at)
        return inum, word >> 29, word & 0x1FFFFFFF

    # -- the committed index -------------------------------------------------
    def _walk_index(self):
        stack = [self.master["root"]]
        seen = set()
        while stack:
            lnum, offs, nlen = stack.pop()
            if (lnum, offs) in seen or len(seen) > 5_000_000:
                continue
            seen.add((lnum, offs))
            raw = self._node(lnum, offs, nlen, UBIFS_IDX_NODE)
            if raw is None:
                self.stats["unreadable index nodes"] += 1
                continue
            count, level = struct.unpack_from("<HH", raw, 24)
            if not count:
                continue
            bsz = (nlen - 28) // count
            for b in range(count):
                at = 28 + b * bsz
                blnum, boffs, blen = struct.unpack_from("<III", raw, at)
                if level:
                    stack.append((blnum, boffs, blen))
                else:
                    self._leaf(raw, at + 12, (blnum, boffs, blen))

    def _leaf(self, raw, key_at, loc):
        inum, ktype, low = self._key(raw, key_at)
        if ktype == UBIFS_KEY_INO:
            self.inodes[inum] = loc
        elif ktype == UBIFS_KEY_DATA:
            self.data[inum][low] = loc
        elif ktype == UBIFS_KEY_DENT:
            node = self._node(loc[0], loc[1], loc[2], UBIFS_DENT_NODE)
            if node is None:
                self.stats["unreadable directory entries"] += 1
                return
            target, dtype, name = self._dent(node)
            self.dents[inum][name] = (target, dtype)
        elif ktype == UBIFS_KEY_XENT:
            self.stats["extended attributes"] += 1

    @staticmethod
    def _dent(raw):
        target = struct.unpack_from("<Q", raw, 40)[0]
        dtype, nlen = raw[49], struct.unpack_from("<H", raw, 50)[0]
        return target, dtype, raw[56:56 + nlen].decode("utf-8", "surrogateescape")

    # -- the journal ---------------------------------------------------------
    def _replay(self):
        m = self.master
        buds, seen_buds = [], set()
        lnum = m["log_lnum"]
        cs_sqnum = None
        for _ in range(self.log_lebs):
            nodes = self._scan_leb(lnum, 0)
            if not nodes:
                break
            if cs_sqnum is None:
                first = nodes[0][1]
                if first[20] != UBIFS_CS_NODE or \
                        struct.unpack_from("<Q", first, 24)[0] != m["cmt_no"]:
                    self.stats["log does not open with this commit"] += 1
                    return
                cs_sqnum = struct.unpack_from("<Q", first, 8)[0]
            elif struct.unpack_from("<Q", nodes[0][1], 8)[0] < cs_sqnum:
                break                               # older, already committed
            for _offs, raw in nodes:
                if raw[20] == UBIFS_REF_NODE:
                    blnum, boffs, jhead = struct.unpack_from("<III", raw, 24)
                    if blnum not in seen_buds:
                        seen_buds.add(blnum)
                        buds.append((blnum, boffs))
            lnum += 1
            if lnum >= UBIFS_LOG_LNUM + self.log_lebs:
                lnum = UBIFS_LOG_LNUM
            if lnum == m["log_lnum"]:
                break
        entries = []
        for blnum, boffs in buds:
            for offs, raw in self._scan_leb(blnum, boffs):
                sq = struct.unpack_from("<Q", raw, 8)[0]
                entries.append((sq, blnum, offs, raw))
        entries.sort(key=lambda e: e[0])
        self.stats["journal nodes replayed"] = len(entries)
        last_ino = {}
        for sq, blnum, offs, raw in entries:
            if raw[20] == UBIFS_INO_NODE:
                last_ino[struct.unpack_from("<I", raw, 24)[0]] = struct.unpack_from("<I", raw, 92)[0]
        for sq, blnum, offs, raw in entries:
            loc = (blnum, offs, len(raw))
            t = raw[20]
            if t == UBIFS_INO_NODE:
                inum = struct.unpack_from("<I", raw, 24)[0]
                if struct.unpack_from("<I", raw, 92)[0] == 0:        # nlink 0
                    if last_ino.get(inum, 0) == 0:
                        self.inodes.pop(inum, None)
                        self.data.pop(inum, None)
                else:
                    self.inodes[inum] = loc
            elif t == UBIFS_DATA_NODE:
                inum, _kt, block = self._key(raw, 24)
                self.data[inum][block] = loc
            elif t == UBIFS_DENT_NODE:
                parent = self._key(raw, 24)[0]
                target, dtype, name = self._dent(raw)
                if target:
                    self.dents[parent][name] = (target, dtype)
                else:
                    self.dents[parent].pop(name, None)
            elif t == UBIFS_TRUN_NODE:
                inum = struct.unpack_from("<I", raw, 24)[0]
                old, new = struct.unpack_from("<QQ", raw, 40)
                _ubifs_truncate(self.data.get(inum, {}), old, new)

    # -- the tree -----------------------------------------------------------
    def _ino(self, inum):
        hit = self._ino_cache.get(inum)
        if hit is not None:
            return hit
        loc = self.inodes.get(inum)
        raw = self._node(loc[0], loc[1], loc[2], UBIFS_INO_NODE) if loc else None
        if raw is None:
            return None
        size, _at, _ct, mtime = struct.unpack_from("<QQQQ", raw, 48)
        nlink, uid, gid, mode, flags, dlen = struct.unpack_from("<IIIIII", raw, 92)
        ino = dict(size=size, mtime=mtime, nlink=nlink, uid=uid, gid=gid, mode=mode,
                   flags=flags, data=raw[160:160 + dlen])
        if len(self._ino_cache) < 65536:
            self._ino_cache[inum] = ino
        return ino

    def entry(self, inum):
        ino = self._ino(inum)
        if ino is None:
            return None
        return ino["mode"], ino["size"], ino["mtime"]

    def listdir(self, inum):
        return sorted((name, t) for name, (t, _dt) in self.dents.get(inum, {}).items())

    def readlink(self, inum):
        ino = self._ino(inum)
        return ino["data"].decode("utf-8", "surrogateescape") if ino else ""

    def read_file(self, inum, size):
        ino = self._ino(inum)
        if ino is None or ino["mode"] & S_IFMT != S_IFREG:
            return
        if ino["flags"] & UBIFS_CRYPT_FL:
            raise UbifsUnreadable("the file is encrypted (fscrypt); its content is not read")
        fsize = ino["size"]
        blocks = self.data.get(inum, {})
        left = min(size, fsize)
        for blk in range((fsize + UBIFS_BLOCK - 1) // UBIFS_BLOCK):
            if left <= 0:
                return
            loc = blocks.get(blk)
            if loc is None:
                out = bytes(UBIFS_BLOCK)                    # a hole
            else:
                raw = self._node(loc[0], loc[1], loc[2], UBIFS_DATA_NODE)
                if raw is None:
                    raise UbifsUnreadable(self._unread(blk, loc[0], loc[1]))
                dsize, ctype = struct.unpack_from("<IH", raw, 40)
                out = ubifs_decompress(ctype, raw[48:], UBIFS_BLOCK)
                if len(out) != dsize:
                    raise UbifsUnreadable(f"block {blk} inflates to {len(out)} bytes, "
                                          f"not the {dsize} its node records")
                out = out.ljust(UBIFS_BLOCK, b"\0")
            take = out[:min(UBIFS_BLOCK, left)]
            yield take
            left -= len(take)

    # -- deleted files ---------------------------------------------------------
    def recover_deleted(self):
        """Yield a FlashDeletedFile for every regular file whose inode node is
        still in the main area but that the index and journal no longer hold.

        UBIFS deletes a file by writing an inode node with nlink 0 and a
        directory entry node pointing at inode 0; its data nodes stay in their
        LEBs until garbage collection moves the live nodes out and erases the
        LEB. Every node carries a sequence number that orders all writes on the
        volume, so a deleted inode's data and truncation nodes are replayed in
        that order up to the deletion, as _replay() replays the journal. Its
        size and mode come from its newest inode node with a link, and its name
        from the newest directory entry that pointed at it. Only the LEBs the
        volume maps now are read: an older copy of a LEB that UBI still holds is
        not. An extended attribute's inode is not a file and is skipped."""
        main_first = UBIFS_LOG_LNUM + self.log_lebs + self.lpt_lebs + self.orph_lebs
        inos, datas, truns = (collections.defaultdict(list) for _ in range(3))
        names = collections.defaultdict(list)
        for lnum in range(main_first, self.leb_cnt):
            for offs, raw in self._scan_leb(lnum, 0):
                t = raw[20]
                sq = struct.unpack_from("<Q", raw, 8)[0]
                if t == UBIFS_DENT_NODE:
                    parent = self._key(raw, 24)[0]
                    target, _dtype, name = self._dent(raw)
                    if target and target not in self.inodes:
                        names[target].append((sq, parent, name))
                    continue
                inum = struct.unpack_from("<I", raw, 24)[0]
                if inum in self.inodes:
                    continue
                if t == UBIFS_INO_NODE:
                    size, _at, _ct, mtime = struct.unpack_from("<QQQQ", raw, 48)
                    nlink, _uid, _gid, mode, flags = struct.unpack_from("<IIIII", raw, 92)
                    inos[inum].append((sq, nlink, size, mtime, mode, flags))
                elif t == UBIFS_DATA_NODE:
                    datas[inum].append((sq, self._key(raw, 24)[2], (lnum, offs, len(raw))))
                elif t == UBIFS_TRUN_NODE:
                    old, new = struct.unpack_from("<QQ", raw, 40)
                    truns[inum].append((sq, old, new))
        paths = _live_dir_paths(self)
        for inum in sorted(inos):
            recs = sorted(set(inos[inum]))
            linked = [r for r in recs if r[1]]
            if not linked:
                continue
            last = linked[-1]
            _sq, _nl, size, mtime, mode, flags = last
            if mode & S_IFMT != S_IFREG or flags & UBIFS_XATTR_FL:
                continue
            cut = next((r[0] for r in recs if r[0] > last[0] and not r[1]), None)
            events = sorted([(sq, 0, blk, loc) for sq, blk, loc in datas.get(inum, ())]
                            + [(sq, 1, old, new) for sq, old, new in truns.get(inum, ())])
            blocks = {}
            for sq, kind, a, b in events:
                if cut is not None and sq >= cut:
                    break
                if kind == 0:
                    blocks[a] = b
                else:
                    _ubifs_truncate(blocks, a, b)
            need = (size + UBIFS_BLOCK - 1) // UBIFS_BLOCK
            gap = sum(1 for blk in range(need) if blk not in blocks)
            named = [n for n in names.get(inum, ()) if cut is None or n[0] < cut]
            _nsq, parent, name = max(named) if named else (0, None, "")
            e = FlashDeletedFile("ubifs", inum, name, parent, paths.get(parent), size, mode,
                                 mtime, gap, dict(blocks=blocks), self)
            if flags & UBIFS_CRYPT_FL:
                e.recoverable, e.reason = False, "the file was encrypted (fscrypt)"
            yield e

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file (recover_deleted())."""
        if not entry.recoverable:
            raise UbifsUnreadable(f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        # pylint: disable=protected-access
        blocks = entry._plan["blocks"]
        left = entry.size if size is None else min(size, entry.size)
        for blk in range((entry.size + UBIFS_BLOCK - 1) // UBIFS_BLOCK):
            if left <= 0:
                return
            lnum, offs, nlen = blocks[blk]
            raw = self._node(lnum, offs, nlen, UBIFS_DATA_NODE)
            if raw is None:
                raise UbifsUnreadable(self._unread(blk, lnum, offs))
            dsize, ctype = struct.unpack_from("<IH", raw, 40)
            out = ubifs_decompress(ctype, raw[48:], UBIFS_BLOCK)
            if len(out) != dsize:
                raise UbifsUnreadable(f"block {blk} inflates to {len(out)} bytes, "
                                      f"not the {dsize} its node records")
            take = out.ljust(UBIFS_BLOCK, b"\0")[:min(UBIFS_BLOCK, left)]
            yield take
            left -= len(take)


def identify_ubifs(fh, base, size=None):
    """Return ("ubifs", lines) for a UBIFS volume whose superblock node sits at
    base, as mkfs.ubifs writes it before ubinize wraps it in UBI."""
    head = read_at(fh, base, 24)
    if len(head) < 24 or struct.unpack_from("<I", head, 0)[0] != UBIFS_MAGIC \
            or head[20] != UBIFS_SB_NODE:
        return None
    try:
        w = UbifsWalker(fh, base)
    except UbifsUnreadable:
        return None
    if size is None:
        size = image_size(fh) - base
    _remember_walker(fh, base, size, "ubifs", w)
    return "ubifs", ubifs_lines(w)


def ubifs_lines(w):
    m = w.master
    lines = [
        f"format       version {w.fmt_version}, {human(w.leb_size)} LEBs, "
        f"{w.leb_cnt:,} in use",
        f"compression  {UBIFS_COMPR.get(w.default_compr, w.default_compr)} by default",
        f"uuid         {w.uuid}",
        f"inodes       {len(w.inodes):,} in the index and journal, "
        f"highest number {m['highest_inum']:,}",
        f"commit       number {m['cmt_no']:,}, "
        + ("NOT cleanly unmounted, so it may have been live at acquisition"
           if m["flags"] & UBIFS_MST_DIRTY else "cleanly unmounted"),
    ]
    if w.stats["journal nodes replayed"]:
        lines.append(f"journal      {w.stats['journal nodes replayed']:,} nodes written "
                     "since the last commit, replayed over the index")
    if w.flags & UBIFS_FLG_ENCRYPTION:
        lines.append("note         fscrypt is enabled; encrypted files and their names "
                     "are not read")
    if w.flags & UBIFS_FLG_AUTHENTICATION:
        lines.append("note         authenticated volume; hashes are not checked here")
    for k in ("unreadable index nodes", "unreadable directory entries",
              "log does not open with this commit"):
        if w.stats[k]:
            lines.append(f"damaged      {w.stats[k]:,} {k}")
    if w.bit_repairs:
        lines.append(UBIFS_BIT_REPAIR_NOTE.format(n=len(w.bit_repairs), where=""))
    return lines


# ---------------------------------------------------------------------------
# YAFFS1 and YAFFS2
#
# NAND filesystems with no superblock: each page (a "chunk") carries its tags
# in the page's spare (OOB) bytes, and the filesystem is rebuilt from the tags.
# Read from Aleph One's yaffs2 at commit 474b3acb927d27b2305618aaf24456b9d33fe91b
# (github.com/Aleph-One-Ltd/yaffs2), and the on-disk offsets were printed with
# offsetof() from that tree's own headers:
#
#   struct yaffs_obj_hdr, 512 bytes; name at    core/yaffs_guts.h yaffs_obj_hdr
#     10 (256), mode 268, uid 272, gid 276,
#     atime 280, mtime 284, ctime 288, size
#     292, equiv 296, alias 300 (160), rdev
#     460, 64-bit times 464/472/480, size
#     high 496, is_shrink 508
#   object ids: root 1, lost+found 2,          core/yaffs_guts.h:94-100
#     unlinked 3, deleted 4, block summary 0x10
#   sequence numbers 0x1000..0xefffff00        core/yaffs_guts.h:123-124
#   YAFFS2 packed tags: seq, obj, chunk,       core/yaffs_packedtags2.h/.c
#     n_bytes (16 bytes) then tag ECC; an
#     object header's tags may carry its type
#     (obj id top nibble) and parent (chunk id
#     with 0x80000000 set)
#   YAFFS2 scan: blocks newest sequence first, core/yaffs_yaffs2.c yaffs2_scan_chunk
#     chunks last first; the first header and
#     the first copy of each data chunk win;
#     data past a shrink or past the newest
#     header's size (for older chunks) is dead;
#     size is the newest header's, or the data
#     written after it when that runs longer;
#     summary chunks, tags failing their ECC and
#     data chunks over a page are ignored
#   YAFFS1 spare: tags in bytes 0-3, 6-7, 11-12 core/yaffs_guts.h yaffs_spare,
#     page_status (byte 4) with fewer than 7    core/yaffs_tagscompat.c,
#     bits set marks a deleted chunk; of two    core/yaffs_yaffs1.c
#     copies the newer has serial (old + 1) % 4;
#     a file's size is where its furthest live
#     chunk ends (the header's size only under a
#     driver setting the flash does not record)
#   64-bit size and time: used unless their    core/yaffs_guts.c yaffs_oh_to_size,
#     high word is 0xffffffff                   yaffs_oh_time_fetch
#
# The page and spare sizes are recorded nowhere, and on a device the tags sit
# wherever the NAND controller leaves the spare free, so both are found by
# trying the common geometries and every tag offset and keeping the one whose
# tags are consistent.
# ---------------------------------------------------------------------------
YAFFS_ROOT, YAFFS_LOSTNFOUND, YAFFS_UNLINKED, YAFFS_DELETED = 1, 2, 3, 4
YAFFS_OBJECTID_SUMMARY = 0x10
YAFFS_SEQ_LO, YAFFS_SEQ_HI = 0x00001000, 0xEFFFFF00
YAFFS_TYPES = {1: "file", 2: "symlink", 3: "directory", 4: "hardlink", 5: "special"}
YAFFS_TYPE_MODE = {1: S_IFREG, 2: S_IFLNK, 3: S_IFDIR}
YAFFS_EXTRA_HDR, YAFFS_EXTRA_SHRINK = 0x80000000, 0x40000000
YAFFS_GEOMETRIES = ((2048, 64), (4096, 128), (4096, 224), (4096, 256), (512, 16),
                    (8192, 256), (8192, 448), (8192, 512), (8192, 640), (2048, 128),
                    (16384, 1280))


class YaffsUnreadable(Exception):
    """A YAFFS image this reader cannot rebuild; the message says why."""


def _yaffs2_line_parity(b):
    """The two line parities YAFFS2 stores in its tag ECC (core/yaffs_ecc.c
    yaffs_ecc_calc_other): over the 16 tag bytes, the XOR of the index of
    every byte with an odd number of set bits, and of its complement."""
    lp = lpp = 0
    for i, v in enumerate(b):
        if bin(v).count("1") & 1:
            lp ^= i
            lpp ^= ~i & 0xFFFFFFFF
    return lp, lpp


def _yaffs2_tags(spare, off, e):
    """Packed YAFFS2 tags at `off` in the spare, or None when they are not
    plausible tags (erased, or values no writer produces)."""
    raw = spare[off:off + 16]
    if len(raw) < 16 or raw == b"\xff" * 16:
        return None
    seq, obj, chunk, nbytes = struct.unpack(e + "IIII", raw)
    if not (YAFFS_SEQ_LO <= seq < YAFFS_SEQ_HI):
        return None
    t = dict(seq=seq, obj=obj & 0x0FFFFFFF, chunk=chunk, n_bytes=nbytes, extra=None)
    if chunk & YAFFS_EXTRA_HDR:
        t.update(chunk=0, n_bytes=0,
                 extra=dict(parent=chunk & 0x0FFFFFFF, shrink=bool(chunk & YAFFS_EXTRA_SHRINK),
                            type=obj >> 28, size_or_equiv=nbytes))
    elif obj >> 28:
        return None
    if not 0 < t["obj"] < (1 << 18) or t["chunk"] >= (1 << 20):
        return None
    ecc = spare[off + 16:off + 28]
    if len(ecc) == 12 and ecc != b"\xff" * 12:
        lp, lpp = struct.unpack_from(e + "II", ecc, 4)
        t["ecc_ok"] = (lp, lpp) == _yaffs2_line_parity(raw)
    return t


def _yaffs1_tags(spare):
    """YAFFS1 tags from a 16-byte spare, or None: the 8 tag bytes are spread
    through the spare (struct yaffs_spare) and carry a 12-bit ECC that must
    hold (mkyaffsimage.c yaffs_calc_tags_ecc: the XOR of the 1-based index
    of every set bit, with the ECC field itself cleared)."""
    if len(spare) < 16 or spare == b"\xff" * 16:
        return None
    b = bytes(spare[0:4] + spare[6:8] + spare[11:13])
    w0, w1 = struct.unpack("<II", b)
    stored = (w1 >> 18) & 0xFFF
    clear = struct.pack("<II", w0, w1 & ~(0xFFF << 18))
    ecc = bit = 0
    for v in clear:
        for j in range(8):
            bit += 1
            if v >> j & 1:
                ecc ^= bit
    if ecc != stored:
        return None
    return dict(obj=w1 & 0x3FFFF, chunk=w0 & 0xFFFFF, serial=(w0 >> 20) & 3,
                n_bytes=(w0 >> 22) & 0x3FF,
                deleted=bin(spare[4]).count("1") < 7)


def _yaffs_header(data, e):
    """The fields of a struct yaffs_obj_hdr, or None if it is not one."""
    if len(data) < 512:
        return None
    otype, parent = struct.unpack_from(e + "II", data, 0)
    if otype not in YAFFS_TYPES:
        return None
    name = data[10:10 + 255].split(b"\0")[0]         # YAFFS_MAX_NAME_LENGTH
    (mode, uid, gid, atime, mtime, ctime, size_lo, equiv) = struct.unpack_from(e + "IIIIIIIi", data, 268)
    alias = data[300:300 + 159].split(b"\0")[0]      # YAFFS_MAX_ALIAS_LENGTH
    rdev = struct.unpack_from(e + "I", data, 460)[0]
    wm = struct.unpack_from(e + "II", data, 480)
    size_hi, _res, shadows, shrink = struct.unpack_from(e + "IIiI", data, 496)
    return dict(type=otype, parent=parent, name=name.decode("utf-8", "surrogateescape"),
                mode=mode, uid=uid, gid=gid, rdev=rdev, equiv=equiv,
                mtime=mtime if wm[1] == 0xFFFFFFFF else (wm[1] << 32) | wm[0],
                size=size_lo if size_hi == 0xFFFFFFFF else (size_hi << 32) | size_lo,
                alias=alias.decode("utf-8", "surrogateescape"),
                shrink=shrink not in (0, 0xFFFFFFFF))


def _yaffs_tag_trials(chunk, spare):
    """(version, tag offset, byte order, decoder) for every tag placement a
    geometry allows: YAFFS1 tags on 512+16, and YAFFS2 packed tags at every
    offset in the spare in both byte orders."""
    trials = []
    if (chunk, spare) == (512, 16):
        trials.append((1, 0, "<", lambda s: _yaffs1_tags(s)))
    for off in range(0, spare - 15):
        for e in ("<", ">"):
            trials.append((2, off, e, lambda s, off=off, e=e: _yaffs2_tags(s, off, e)))
    return trials


def _yaffs_tags_fit(decode, used):
    """True when the decoder finds plausible tags on at least 90% of the
    first 16 used pages; it gives up as soon as that is out of reach."""
    first = used[:16]
    allowed = len(first) - 0.9 * len(first)
    misses = 0
    for _d, s in first:
        if not decode(s):
            misses += 1
            if misses > allowed:
                return False
    return True


def _yaffs_pages(fh, base, size, chunk, spare, n, windows):
    """(data, spare) for the used pages of `windows` runs of n pages spread
    evenly over the region, the first at its start and the last at its end."""
    page = chunk + spare
    total = size // page
    if windows <= 1 or total <= n * windows:
        spans = [(0, min(n, total) if windows <= 1 else total)]
    else:
        spans = [((total - n) * i // (windows - 1), n) for i in range(windows)]
    used = []
    for first, count in spans:
        raw = read_at(fh, base + first * page, count * page)
        used += [(raw[i * page:i * page + chunk], raw[i * page + chunk:(i + 1) * page])
                 for i in range(len(raw) // page)]
    return [(d, s) for d, s in used if s != b"\xff" * spare]


def yaffs_layout(fh, base, size, sample=256, windows=16):
    """(version, chunk, spare, tag offset, tag byte order, header byte order)
    for a YAFFS image at base, or None.

    Every common page/spare geometry the region allows is tried over its first
    `sample` pages, and for YAFFS2 every tag offset in the spare and both byte
    orders. A geometry with no page shaped like an object header is skipped, and
    a tag offset whose first 16 used pages mostly fail is dropped early. A
    layout qualifies when at least 90% of the non-erased spares (and
    at least 8) hold plausible tags, and at least 90% of the chunks those tags
    call object headers parse as object headers; among those, the one whose
    tag ECC line parities hold, then the one explaining the most headers, wins.
    The tag and header byte orders are decided apart: upstream mkyaffs2image's
    "convert" swaps its headers and, at the pinned commit, not its tags
    (utils/mkyaffs2image.c little_to_big_endian is compiled out).

    YAFFS writes to whichever block garbage collection freed, and its scan
    orders blocks by sequence number, not by place, so the start of a real
    partition can hold only data chunks, or only erased blocks. On the DFRWS
    2011 Case 2 /cache partition the first object header is at page 3,968.
    When the first pages hold tags that fit but no header, or too few used
    pages, the same test is run again over `windows` runs spread across the
    whole region. Those runs cover the same stretch of bytes for every
    geometry (`sample` pages of 2048+64 each), so a geometry that is a
    multiple of the real one (8192+256 over 2048+64 pages) cannot see more
    headers than the real one does; sampling more pages from the start alone
    let exactly that alias win on the Case 2 partition."""
    best, hint = _yaffs_layout_in(
        fh, base, size, lambda chunk, spare: min(sample, size // (chunk + spare)), 1)
    if best is None and hint:
        span = sample * (2048 + 64)
        best, _hint = _yaffs_layout_in(
            fh, base, size, lambda chunk, spare: max(8, span // (chunk + spare)), windows)
    return best


def _yaffs_layout_in(fh, base, size, pages_for, windows):
    """The best layout over the sampled pages, and whether the pages hinted
    at YAFFS without settling it (see yaffs_layout)."""
    best = None
    hint = False
    for chunk, spare in YAFFS_GEOMETRIES:
        n = pages_for(chunk, spare)
        if n < 8:
            continue
        used = _yaffs_pages(fh, base, size, chunk, spare, n, windows)
        if len(used) < 8:
            # Erased flash: nothing to decide from here, but more of the
            # region may hold YAFFS.
            hint = hint or n * (chunk + spare) < size
            continue
        trials = _yaffs_tag_trials(chunk, spare)
        # A geometry with no page shaped like an object header cannot be YAFFS
        # on these pages; checking that first keeps the tag search off regions
        # that are not. Tags that fit anyway say the headers may lie further on.
        if not any(_yaffs_header(d, he) for d, _s in used for he in ("<", ">")):
            if not hint and any(_yaffs_tags_fit(dec, used) for _v, _o, _e, dec in trials):
                hint = True
            continue
        for version, off, e, decode in trials:
            if not _yaffs_tags_fit(decode, used):
                continue                   # most tag offsets fail on the first pages
            good = claimed = eccs = 0
            parsed = {"<": 0, ">": 0}
            for d, s in used:
                t = decode(s)
                if not t:
                    continue
                good += 1
                eccs += t.get("ecc_ok", False)
                if t["chunk"] == 0:
                    claimed += 1
                    for he in ("<", ">"):
                        if _yaffs_header(d, he):
                            parsed[he] += 1
            hdr_e = max(parsed, key=parsed.get)
            if not (good >= 8 and good >= 0.9 * len(used) and claimed
                    and parsed[hdr_e] >= 0.9 * claimed):
                if good >= 0.9 * len(used) and not claimed:
                    hint = True
                continue
            rank = (version == 1 or eccs >= 0.9 * good, parsed[hdr_e], good / len(used))
            if best is None or rank > best[0]:
                best = (rank, (version, chunk, spare, off, e, hdr_e))
    return (best[1] if best else None), hint


class YaffsWalker:
    """List and read a YAFFS1 or YAFFS2 image. A node is an object id; the
    root is object 1."""

    root = YAFFS_ROOT

    def __init__(self, fh, base, size=None, layout=None):
        self.fh, self.base = fh, base
        if size is None:
            size = image_size(fh) - base
        layout = layout or yaffs_layout(fh, base, size)
        if layout is None:
            raise YaffsUnreadable("no YAFFS page and spare layout fits this region")
        self.version, self.chunk, self.spare, self.tag_off, self.e, self.he = layout
        self.page = self.chunk + self.spare
        self.npages = size // self.page
        self.stats = collections.Counter()
        self.objs = {}
        if self.version == 2:
            self._scan2()
        else:
            self._scan1()
        self.children = collections.defaultdict(list)
        for oid, o in self.objs.items():
            h = o.get("hdr")
            if h and oid != YAFFS_ROOT:
                # An unlinked or deleted object's parent is 3 or 4, which no
                # listing reaches from the root.
                self.children[h["parent"]].append(oid)

    def _pages(self):
        """(page index, data, spare) for every page, read 64 pages at a time."""
        step = 64
        for first in range(0, self.npages, step):
            n = min(step, self.npages - first)
            raw = read_at(self.fh, self.base + first * self.page, n * self.page)
            for i in range(len(raw) // self.page):
                at = i * self.page
                yield first + i, raw[at:at + self.chunk], raw[at + self.chunk:at + self.page]

    def _obj(self, oid):
        o = self.objs.get(oid)
        if o is None:
            o = self.objs[oid] = dict(chunks={}, stored=0, shrink=None, hdr=None)
        return o

    def _scan2(self):
        entries = []
        for idx, data, spare in self._pages():
            t = _yaffs2_tags(spare, self.tag_off, self.e)
            if t is None:
                continue
            self.stats["chunks"] += 1
            # What yaffs2_scan_chunk ignores: a block summary chunk, tags whose
            # ECC does not hold, a data chunk claiming more than a page.
            if t["obj"] == YAFFS_OBJECTID_SUMMARY:
                self.stats["block summary chunks"] += 1
                continue
            if t.get("ecc_ok") is False:
                self.stats["chunks whose tag ECC does not hold"] += 1
                continue
            if t["chunk"] > 0 and t["n_bytes"] > self.chunk:
                self.stats["data chunks claiming more than a page"] += 1
                continue
            hdr = None
            if t["chunk"] == 0:
                hdr = _yaffs_header(data, self.he)
                if hdr is None:
                    self.stats["headers that do not parse"] += 1
                    continue
            entries.append((t["seq"], idx, t, hdr))
        entries.sort(key=lambda x: (x[0], x[1]), reverse=True)   # newest first
        self.max_seq = entries[0][0] if entries else 0
        self._entries = entries
        for _seq, idx, t, hdr in entries:
            self._take2(self._obj(t["obj"]), idx, t, hdr, self.stats)

    def _take2(self, o, idx, t, hdr, stats):
        """Apply one chunk to its object, the chunks coming newest first, as
        yaffs2_scan_chunk does. recover_deleted() replays a deleted object's
        chunks through the same rules."""
        if hdr is None:                                        # a data chunk
            base = (t["chunk"] - 1) * self.chunk
            if o["hdr"] is not None and o["hdr"]["type"] != 1:
                return
            if o["shrink"] is not None and base >= o["shrink"]:
                stats["data chunks past a shrink or resize"] += 1
                return
            if t["chunk"] not in o["chunks"]:
                o["chunks"][t["chunk"]] = (idx, t["n_bytes"])
                if o["hdr"] is None:
                    o["stored"] = max(o["stored"], base + t["n_bytes"])
            return
        if o["hdr"] is not None:                               # an older header
            if o["hdr"]["type"] == 1 and hdr["type"] == 1:
                this, shrink = hdr["size"], hdr["shrink"]
                if hdr["parent"] in (YAFFS_DELETED, YAFFS_UNLINKED):
                    this, shrink = 0, True
                if shrink and (o["shrink"] is None or o["shrink"] > this):
                    o["shrink"] = this
            stats["older headers"] += 1
            return
        o["hdr"] = hdr
        if hdr["type"] == 1:
            if o["stored"] < hdr["size"]:
                o["stored"] = hdr["size"]
            if o["shrink"] is None or o["shrink"] > hdr["size"]:
                o["shrink"] = hdr["size"]

    def _scan1(self):
        for idx, data, spare in self._pages():
            t = _yaffs1_tags(spare)
            if t is None:
                continue
            self.stats["chunks"] += 1
            if t["deleted"]:
                self.stats["chunks marked deleted"] += 1
                continue
            o = self._obj(t["obj"])
            if t["chunk"] == 0:
                hdr = _yaffs_header(data, self.he)
                if hdr is None:
                    self.stats["headers that do not parse"] += 1
                    continue
                cur = o.get("hdr_serial")
                if o["hdr"] is None or (cur + 1) & 3 == t["serial"]:
                    o["hdr"], o["hdr_serial"] = hdr, t["serial"]
                continue
            cur = o["chunks"].get(t["chunk"])
            if cur is not None and cur[2] == t["serial"]:
                # Two live copies with one serial: nothing on the flash orders
                # them. YAFFS's scan keeps the first it finds, and so does this.
                self.stats["duplicate chunks their serial numbers do not order"] += 1
            if cur is None or (cur[2] + 1) & 3 == t["serial"]:
                o["chunks"][t["chunk"]] = (idx, t["n_bytes"], t["serial"])
        self.max_seq = 0
        # YAFFS1 sizes a file by where its furthest live data chunk ends, not by
        # its header, unless the driver sets use_header_file_size
        # (core/yaffs_yaffs1.c yaffs1_scan), a setting the flash does not record.
        for o in self.objs.values():
            ends = [(c - 1) * self.chunk + v[1] for c, v in o["chunks"].items()]
            o["stored"] = max(ends, default=0)

    # -- the tree -----------------------------------------------------------
    def _resolve(self, oid, depth=0):
        """A hard link's object is the object it names."""
        o = self.objs.get(oid)
        if o and o["hdr"] and o["hdr"]["type"] == 4 and depth < 8:
            return self._resolve(o["hdr"]["equiv"], depth + 1)
        return oid

    def entry(self, oid):
        if oid in (YAFFS_ROOT, YAFFS_LOSTNFOUND) and not (self.objs.get(oid) or {}).get("hdr"):
            # With no header on the flash, YAFFS makes these at mount time
            # (core/yaffs_guts.c yaffs_create_fake_dir) with the modes of
            # direct/ydirectenv.h:99-100 and the clock of that mount, which is
            # not evidence, so no time is reported for them (None).
            return (S_IFDIR | (0o755 if oid == YAFFS_ROOT else 0o700), 0, None)
        o = self.objs.get(self._resolve(oid))
        h = o and o["hdr"]
        if not h:
            return None
        # The type comes from the header, as YAFFS's own stat does it
        # (direct/yaffsfs.c yaffsfs_DoStat): YAFFS's direct interface stores only
        # permission bits in yst_mode while the Linux driver and mkyaffs2image
        # store the whole mode. A special file keeps the type yst_mode carries.
        mode = (h["mode"] & 0o7777) | YAFFS_TYPE_MODE.get(h["type"], h["mode"] & S_IFMT)
        if h["type"] == 1:
            return (mode, o["stored"], h["mtime"])
        if h["type"] == 2:
            return (mode, len(h["alias"].encode("utf-8", "surrogateescape")), h["mtime"])
        return (mode, 0, h["mtime"])

    def listdir(self, oid):
        out = []
        if oid == YAFFS_ROOT:
            # lost+found is a directory YAFFS keeps for every volume and lists
            # under the root whether or not it has a header on the flash.
            out.append(("lost+found", YAFFS_LOSTNFOUND))
        for child in self.children.get(oid, ()):
            if child == YAFFS_LOSTNFOUND:
                continue
            name = self.objs[child]["hdr"]["name"]
            if name:
                out.append((name, child))
        return sorted(out)

    def readlink(self, oid):
        o = self.objs.get(self._resolve(oid))
        return o["hdr"]["alias"] if o and o["hdr"] else ""

    def read_file(self, oid, size):
        o = self.objs.get(self._resolve(oid))
        if not o or not o["hdr"] or o["hdr"]["type"] != 1:
            return
        fsize = o["stored"]
        left = min(size, fsize)
        for c in range(1, (fsize + self.chunk - 1) // self.chunk + 1):
            if left <= 0:
                return
            hit = o["chunks"].get(c)
            if hit is None:
                data = bytes(self.chunk)                      # never written: a hole
            else:
                data = read_at(self.fh, self.base + hit[0] * self.page, self.chunk)
                data = data[:hit[1]].ljust(self.chunk, b"\0")
            take = data[:min(self.chunk, left)]
            yield take
            left -= len(take)

    # -- deleted files ---------------------------------------------------------
    def recover_deleted(self):
        """Yield a FlashDeletedFile for every deleted YAFFS2 file whose header
        from before the deletion is still on the flash.

        YAFFS2 deletes a file by writing a new header that files it under the
        unlinked or deleted directory (objects 3 and 4); its old headers and
        data chunks stay until garbage collection erases their blocks. Each
        object's headers are read oldest first and cut at every such header,
        so an object id YAFFS reused for a later file still gives back the
        file it held before. A deleted file is rebuilt by replaying, newest
        first and through the same rules as the live scan, the chunks written
        before its deletion. Those rules keep an earlier file with the same id
        out: its own deletion header counts as a shrink to 0, as it does in
        YAFFS's scan (core/yaffs_yaffs2.c:1357-1361 at the pinned commit), so
        none of its data chunks is taken.

        YAFFS1 is not recovered: its chunks are ordered only by a 2-bit
        serial number, which cannot say which copy of a page a deleted file
        last held."""
        if self.version != 2:
            return
        by_obj = collections.defaultdict(list)
        for seq, idx, t, hdr in self._entries:
            by_obj[t["obj"]].append((seq, idx, t, hdr))
        paths = _live_dir_paths(self)
        for oid in sorted(by_obj):
            if oid in (YAFFS_ROOT, YAFFS_LOSTNFOUND, YAFFS_UNLINKED, YAFFS_DELETED):
                continue
            ents = sorted(by_obj[oid], key=lambda x: (x[0], x[1]))  # oldest first
            lives = []
            for seq, idx, _t, hdr in ents:
                if hdr is None:
                    continue
                if hdr["parent"] not in (YAFFS_DELETED, YAFFS_UNLINKED):
                    lives.append(((seq, idx), hdr))
                    continue
                if lives and lives[-1][1]["type"] == 1:
                    end, note = (seq, idx), ""
                    # Deleting a YAFFS2 file first resizes it to 0, which writes
                    # a header in its own directory with size 0 and no shrink
                    # flag (core/yaffs_guts.c:3664 in yaffs_del_file, and :3598 in
                    # yaffs_resize_file), and only then files it under the
                    # deleted directory. That header is the deletion's, so the
                    # file is rebuilt as the header before it describes it.
                    last, hdr_used = lives[-1][1], lives[-1][1]
                    if (len(lives) > 1 and last["size"] == 0 and not last["shrink"]
                            and lives[-2][1]["parent"] == last["parent"]
                            and lives[-2][1]["name"] == last["name"]):
                        end, hdr_used = lives[-1][0], lives[-2][1]
                        note = ("the header just before the deletion records size 0; YAFFS2 "
                                "writes that header itself when it deletes a file, and a file "
                                "truncated to 0 just before its deletion leaves the same header, "
                                "so this is the file as the header before that one describes it")
                    e = self._deleted2(oid, ents, end, hdr_used, paths)
                    e.note = note if e.size else ""
                    yield e
                lives = []

    def _deleted2(self, oid, ents, end, h, paths):
        """The file object `oid` held just before `end`, whose newest header
        before `end` is `h`."""
        o = dict(chunks={}, stored=0, shrink=None, hdr=None)
        scratch = collections.Counter()
        for seq, idx, t, hdr in reversed(ents):                 # newest first
            if (seq, idx) < end:
                self._take2(o, idx, t, hdr, scratch)
        need = (o["stored"] + self.chunk - 1) // self.chunk
        gap = sum(1 for c in range(1, need + 1) if c not in o["chunks"])
        return FlashDeletedFile("yaffs2", oid, h["name"], h["parent"], paths.get(h["parent"]),
                                o["stored"], (h["mode"] & 0o7777) | S_IFREG, h["mtime"],
                                gap, o, self)

    def read_deleted(self, entry, size=None):
        """The content of a recoverable deleted file (recover_deleted())."""
        if not entry.recoverable:
            raise YaffsUnreadable(f"deleted file {entry.name!r} is not recoverable: {entry.reason}")
        # pylint: disable=protected-access
        o = entry._plan
        left = entry.size if size is None else min(size, entry.size)
        for c in range(1, (entry.size + self.chunk - 1) // self.chunk + 1):
            if left <= 0:
                return
            idx, nbytes = o["chunks"][c]
            data = read_at(self.fh, self.base + idx * self.page, self.chunk)
            data = data[:nbytes].ljust(self.chunk, b"\0")
            take = data[:min(self.chunk, left)]
            yield take
            left -= len(take)


def identify_yaffs(fh, base, size=None):
    """Return ("yaffs2" or "yaffs1", lines) when the region holds YAFFS pages
    with their spare bytes; see yaffs_layout for how the layout is decided."""
    if size is None:
        size = image_size(fh) - base
    lay = yaffs_layout(fh, base, size)
    if lay is None:
        return None
    try:
        w = YaffsWalker(fh, base, size, lay)
    except YaffsUnreadable:
        return None
    _remember_walker(fh, base, size, f"yaffs{w.version}", w)
    s = w.stats
    live = sum(1 for oid, o in w.objs.items() if o["hdr"] and
               o["hdr"]["parent"] not in (YAFFS_UNLINKED, YAFFS_DELETED))
    gone = sum(1 for o in w.objs.values() if o["hdr"] and
               o["hdr"]["parent"] in (YAFFS_UNLINKED, YAFFS_DELETED))
    kind = f"yaffs{w.version}"
    lines = [
        f"layout       {w.chunk}-byte pages with {w.spare}-byte spare"
        + (f", tags at spare offset {w.tag_off} ({'little' if w.e == '<' else 'big'} endian)"
           if w.version == 2 else "")
        + f", headers {'little' if w.he == '<' else 'big'} endian",
        f"chunks       {s['chunks']:,} in use of {w.npages:,} pages",
        f"objects      {live:,} with a live name, {gone:,} whose newest header files "
        "them as unlinked or deleted",
    ]
    if w.version == 2:
        lines.append(f"sequence     highest block sequence number {w.max_seq:#x}")
    if s["data chunks past a shrink or resize"]:
        lines.append(f"note         {s['data chunks past a shrink or resize']:,} data chunks lie "
                     "outside their object's current extent (a later truncation or "
                     "deletion); their bytes are still on the flash and are not listed")
    for k in ("headers that do not parse", "chunks marked deleted",
              "chunks whose tag ECC does not hold", "data chunks claiming more than a page",
              "duplicate chunks their serial numbers do not order"):
        if s[k]:
            lines.append(f"note         {s[k]:,} {k}")
    return kind, lines


# identify_fs() builds a flash filesystem's whole tree to decide what it is, so
# the walker it built is kept for the walker_for() call that usually follows on
# the same image and offset, rather than scanning the flash a second time.
_FLASH_WALKERS = collections.OrderedDict()


def _remember_walker(fh, base, size, kind, walker):
    _FLASH_WALKERS[(id(fh), base, size, kind)] = (fh, walker)
    while len(_FLASH_WALKERS) > 4:
        _FLASH_WALKERS.popitem(last=False)
    return walker


def _cached_walker(fh, base, size, kind, build):
    hit = _FLASH_WALKERS.get((id(fh), base, size, kind))
    if hit is not None and hit[0] is fh:
        return hit[1]
    return _remember_walker(fh, base, size, kind, build())


def print_tree(w, num, depth, maxdepth, budget, indent=0, pad=6):
    # A walker that keeps readings rather than instants (FAT32, FAT16, FAT12, exFAT) is listed
    # through listdir_records(), so the reading is printed and not the 0 that
    # entry() returns for its mtime, which _fmt_time() shows as 1970-01-01.
    readings = hasattr(w, "listdir_records")
    listing = w.listdir_records(num) if readings else [(n, i, None) for n, i in w.listdir(num)]
    for name, ino, recorded in listing:
        if budget[0] <= 0:
            print(f"{' '*pad}{'  '*indent}... listing truncated, raise --list-max")
            return
        budget[0] -= 1
        ent = w.entry(ino)
        if not ent:
            continue
        mode, size, mtime = ent
        fmt = mode & S_IFMT
        isdir = fmt == S_IFDIR          # the format bits: a block device shares S_IFDIR's bit
        kind = ("dir " if isdir else "link" if fmt == S_IFLNK
                else "file" if fmt == S_IFREG else "spec")
        col = max(12, 44 - 2 * indent)
        shown = "" if isdir else f"{human(size):>11}"
        when = _fmt_reading(recorded) if readings else _fmt_time(mtime)
        print(f"{' '*pad}{'  '*indent}{kind} {name:<{col}} {shown}  {when}")
        # A file can carry content its own size does not account for. NTFS calls
        # those alternate data streams; the walker that has them says so here,
        # because nothing else in the listing would show that the bytes exist.
        for sname, ssize in (getattr(w, "named_streams", lambda _n: [])(ino) or []):
            print(f"{' '*pad}{'  '*indent}     stream {sname:<{max(6, col - 7)}} "
                  f"{human(ssize):>11}")
        if isdir and depth < maxdepth:
            print_tree(w, ino, depth + 1, maxdepth, budget, indent + 1, pad)


# ---------------------------------------------------------------------------
# QNX IFS boot images.
#
# An IFS is not a mountable filesystem, it is a bootable image: a startup
# header, the startup code, then the image filesystem, usually compressed.
# Constants and field order from sys/startup.h:
#     STARTUP_HDR_SIGNATURE 0x00ff7eeb   startup.h:88
#     STARTUP_HDR_VERSION   1            startup.h:89
# and QNX's own "The startup header" page, which lists the same fields in the
# same order. Summing those field widths gives 256 bytes, which the header's
# own header_size field confirms on every image tested.
#
# machine is documented as "Machine type from sys/elf.h", so it is reported
# through the ELF constants (EM_AARCH64 183, EM_ARM 40, EM_386 3, EM_X86_64 62
# from linux/include/uapi/linux/elf-em.h).
#
# The image filesystem begins at startup_size. flags1 carries the compression
# method (COMPRESS_MASK 0x1c: none 0x00, zlib 0x04, lzo 0x08, ucl 0x0c;
# startup.h:73-80). When compressed, the imagefs is a run of blocks, each a
# 2-byte big-endian compressed length followed by that many bytes, decompressing
# to at most 64 KiB, terminated by a zero length. dumpifs.c:563-595. All real
# evidence to hand is UCL, and there is no UCL decompressor in the standard
# library, so a small one is carried below rather than taking a dependency: this
# tool's whole point is that it installs nothing. zlib is handled through the
# standard library. lzo and the Harman Becker HBCIFS container are recognised but
# not decompressed here, because no sample exists to validate a reader against.
# ---------------------------------------------------------------------------
QNX_IFS_SIG = 0x00FF7EEB
QNX_IFS_VER = 1
IFS_F = dict(signature=0, version=4, flags1=6, flags2=7, header_size=8,
             machine=10, startup_vaddr=12, paddr_bias=16, image_paddr=20,
             ram_paddr=24, ram_size=28, startup_size=32, stored_size=36,
             imagefs_paddr=40, imagefs_size=44, preboot_size=48)
IFS_HDR_SIZE = 256
ELF_MACHINE = {3: "x86", 40: "ARM 32 bit", 62: "x86-64", 183: "ARM 64 bit"}

# startup_header flags1, sys/startup.h:73-80. dumpifs.c:533 switches on the
# masked value directly, so the names below are the masked constants, not shifted.
IFS_COMPRESS_MASK  = 0x1c
IFS_COMPRESS = {0x00: "none", 0x04: "zlib", 0x08: "lzo", 0x0c: "ucl"}
IFS_FLAG_BIGENDIAN = 0x02

# image_header, the "imagefs" filesystem header, sys/image.h:42-56. Every field
# is a 4-byte unsigned long (32-bit target, ILP32; dumpifs.c byte-swaps each with
# ENDIAN_RET32). image_size runs from this header to the end of the trailer;
# dir_offset is the first directory entry, hdr_dir_size the byte past the last.
IMG_SIG = b"imagefs"
IMGH = dict(flags=7, image_size=8, hdr_dir_size=12, dir_offset=16,
            boot_ino=20, script_ino=36, chain_paddr=40, mountflags=84)

# union image_dirent, sys/image.h:75-108. A flat, contiguous table of variable
# length records; each starts with the 24-byte image_attr, then a type-specific
# tail keyed on mode & S_IFMT, then the entry's full path relative to the image
# root (no leading slash). attr.size is the whole record's length and steps to
# the next entry; size 0 ends the table. attr.ino 0 means skip. There is no
# per-directory child list: the tree is carried entirely in the path strings.
IFS_ATTR = dict(size=0, extattr_offset=2, ino=4, mode=8, gid=12, uid=16, mtime=20)
IFS_ATTR_LEN = 24
# QNX sys/stat.h:210-218. S_IFNAM 0x5000 is QNX specific; the rest match Unix,
# so the shared collect()/print_tree() read dir, regular and link modes as usual.
IFS_S_IFMT, IFS_S_IFREG, IFS_S_IFDIR, IFS_S_IFLNK = 0xF000, 0x8000, 0x4000, 0xA000


def ucl_nrv2b_decompress(src):
    """Decompress one UCL NRV2B block. This is the _8 (byte at a time, MSB first)
    variant that dumpifs links as ucl_nrv2b_decompress_8. Ported field for field
    from Markus Oberhumer's UCL, src/n2b_d.c and src/getbit.h (getbit_8). The bit
    stream and the literal and offset bytes share one input cursor.

    A wrong port almost never lands on the exact target length, so the caller
    checks the concatenated output against the header's imagefs_size and the
    image trailer checksum rather than trusting this in isolation.
    """
    out = bytearray()
    ilen = 0
    bb = 0
    bits = 0
    last_m_off = 1

    def getbit():
        nonlocal bb, bits, ilen
        if bits == 0:
            bb = src[ilen]
            ilen += 1
            bits = 8
        bits -= 1
        return (bb >> bits) & 1

    while True:
        while getbit():                         # literal run
            out.append(src[ilen])
            ilen += 1
        m_off = 1                               # match offset, high part
        while True:
            m_off = m_off * 2 + getbit()
            if getbit():
                break
        if m_off == 2:                          # reuse the previous offset
            m_off = last_m_off
        else:
            m_off = (m_off - 3) * 256 + src[ilen]
            ilen += 1
            if m_off == 0xFFFFFFFF:             # end of stream
                break
            m_off += 1
            last_m_off = m_off
        m_len = getbit() * 2 + getbit()         # match length
        if m_len == 0:
            m_len = 1
            while True:
                m_len = m_len * 2 + getbit()
                if getbit():
                    break
            m_len += 2
        if m_off > 0xd00:
            m_len += 1
        pos = len(out) - m_off
        out.append(out[pos])                    # copy m_len + 1 bytes, forward,
        pos += 1                                # so overlapping runs work
        for _ in range(m_len):
            out.append(out[pos])
            pos += 1
    return bytes(out)


def ifs_decompress_blocks(stored, decompress):
    """Concatenate the decompressed blocks. Each block is a 2-byte big-endian
    compressed length then that many bytes; a zero length ends the run.
    dumpifs.c:563-595."""
    out = bytearray()
    pos = 0
    while pos + 2 <= len(stored):
        ln = struct.unpack_from(">H", stored, pos)[0]
        if ln == 0:
            break
        out += decompress(stored[pos + 2:pos + 2 + ln])
        pos += 2 + ln
    return bytes(out)


class IfsUnsupported(Exception):
    """Raised when an IFS is recognised but its contents cannot be read here,
    for example an lzo-compressed image or the HBCIFS container. The header is
    still reported; only the walk is declined, and the reason is said out loud."""


class IfsWalker:
    """List and read files from a QNX IFS boot image. The whole image filesystem
    is decompressed into memory once (a compressed block cannot be seeked into),
    then the flat directory table is parsed and a tree is built from the full
    path strings. Same interface as the other walkers, so collect(), print_tree()
    and extract_to_zip() drive it unchanged. A node is the entry's full path."""

    root = ""

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        hdr = read_at(fh, base, IFS_HDR_SIZE)
        if len(hdr) < IFS_HDR_SIZE or \
                struct.unpack_from("<I", hdr, IFS_F["signature"])[0] != QNX_IFS_SIG:
            raise IfsUnsupported("not a startup header")
        flags1 = hdr[IFS_F["flags1"]]
        if flags1 & IFS_FLAG_BIGENDIAN:
            # No big-endian IFS is to hand to validate the swap against, so the
            # walk is declined rather than guessed. The header still reports.
            raise IfsUnsupported("big-endian image, not read here")
        self.compress = IFS_COMPRESS.get(flags1 & IFS_COMPRESS_MASK, "unknown")
        ss = struct.unpack_from("<I", hdr, IFS_F["startup_size"])[0]
        st = struct.unpack_from("<I", hdr, IFS_F["stored_size"])[0]
        isz = struct.unpack_from("<I", hdr, IFS_F["imagefs_size"])[0]
        stored = read_at(fh, base + ss, st - ss)
        if self.compress == "none":
            img = stored[:isz]
        elif self.compress == "ucl":
            img = ifs_decompress_blocks(stored, ucl_nrv2b_decompress)
        elif self.compress == "zlib":
            import zlib
            img = zlib.decompress(stored)       # a single gzip stream, dumpifs.c:534
        else:
            raise IfsUnsupported(f"{self.compress} compression not read here")
        if img[:len(IMG_SIG)] != IMG_SIG:
            raise IfsUnsupported("no imagefs header after decompression")
        self.img = img
        self.image_size = struct.unpack_from("<I", img, IMGH["image_size"])[0]
        self.hdr_dir_size = struct.unpack_from("<I", img, IMGH["hdr_dir_size"])[0]
        self.dir_offset = struct.unpack_from("<I", img, IMGH["dir_offset"])[0]
        self.decompressed = len(img)
        # A byte-exact self-check that does not depend on this reader: the image
        # trailer holds a 32-bit checksum such that the 32-bit words from the
        # header to the end of the trailer sum to zero (image.h:110, and observed
        # to hold on every Sync G4 volume). A single wrong byte breaks it.
        n = self.image_size // 4
        if n * 4 <= len(img):
            total = sum(struct.unpack_from("<%dI" % n, img, 0)) & 0xFFFFFFFF
            self.cksum_ok = total == 0
        else:
            self.cksum_ok = None
        self._parse_dir()

    def _parse_dir(self):
        img = self.img
        root_mode, root_mtime = IFS_S_IFDIR, 0
        self.nodes = {}                          # path -> (mode, size, mtime)
        self.files = {}                          # path -> (offset, size)
        self.links = {}                          # path -> target string
        self.kids = {"": []}                     # path -> [(name, childpath)]
        dpos = self.dir_offset
        while dpos + IFS_ATTR_LEN <= self.hdr_dir_size:
            size = struct.unpack_from("<H", img, dpos)[0]
            if size < IFS_ATTR_LEN:              # 0 ends the table; <24 is invalid
                break
            ino = struct.unpack_from("<I", img, dpos + IFS_ATTR["ino"])[0]
            mode = struct.unpack_from("<I", img, dpos + IFS_ATTR["mode"])[0]
            mtime = struct.unpack_from("<I", img, dpos + IFS_ATTR["mtime"])[0]
            rec = img[dpos:dpos + size]
            dpos += size
            if ino == 0:
                continue
            typ = mode & IFS_S_IFMT
            if typ == IFS_S_IFREG:
                foff, fsize = struct.unpack_from("<II", rec, IFS_ATTR_LEN)
                path = rec[IFS_ATTR_LEN + 8:].split(b"\x00")[0]
                self._add(path, mode, fsize, mtime)
                self.files[path.decode("utf-8", "replace")] = (foff, fsize)
            elif typ == IFS_S_IFDIR:
                path = rec[IFS_ATTR_LEN:].split(b"\x00")[0]
                self._add(path, mode, 0, mtime)
                if path:
                    self.kids.setdefault(path.decode("utf-8", "replace"), [])
                else:
                    root_mode, root_mtime = mode, mtime
            elif typ == IFS_S_IFLNK:
                soff, ssize = struct.unpack_from("<HH", rec, IFS_ATTR_LEN)
                nb = IFS_ATTR_LEN + 4                 # name and target follow the two u16
                path = rec[nb:].split(b"\x00")[0]
                self.links[path.decode("utf-8", "replace")] = \
                    rec[nb + soff:nb + soff + ssize].decode("utf-8", "replace")
                self._add(path, mode, 0, mtime)
            else:                                # device, fifo, or QNX name special
                path = rec[IFS_ATTR_LEN + 8:].split(b"\x00")[0]
                self._add(path, mode, 0, mtime)
        self.nodes[""] = (root_mode, 0, root_mtime)

    def _add(self, path_b, mode, size, mtime):
        """Place one entry, materialising any parent directories the flat table
        left implicit (a file at a/b/c with no dirent for a or a/b)."""
        path = path_b.decode("utf-8", "replace")
        if path == "":
            return
        parts = path.split("/")
        parent = ""
        for i in range(len(parts) - 1):
            ap = "/".join(parts[:i + 1])
            if ap not in self.nodes:
                self.nodes[ap] = (IFS_S_IFDIR, 0, mtime)
                self.kids.setdefault(parent, [])
                self.kids[parent].append((parts[i], ap))
                self.kids.setdefault(ap, [])
            parent = ap
        if path not in self.nodes:
            self.kids.setdefault(parent, [])
            self.kids[parent].append((parts[-1], path))
        self.nodes[path] = (mode, size, mtime)

    def inode(self, node):
        return self.nodes.get(node)

    def listdir(self, node):
        return sorted(self.kids.get(node, []))

    def entry(self, node):
        return self.nodes.get(node)

    def read_file(self, node, size):
        off, fsize = self.files.get(node, (None, None))
        if off is None:
            return
        yield self.img[off:off + fsize]


# ---------------------------------------------------------------------------
# Extraction (--extract)
#
# Mounting a qnx6 volume is a Linux-only trick. macOS ships no qnx6 driver,
# the WSL2 kernel is built with CONFIG_QNX6FS_FS unset, and the FUSE options
# are Linux-tested. So rather than mount, the same readers that back --list
# copy the logical files straight out into a zip. Pure standard library, so it
# behaves the same on macOS, Windows and Linux, needs no administrator rights,
# and cannot write to the evidence.
# ---------------------------------------------------------------------------
def _zip_time(v):
    d = None
    if v is None:                       # no time recorded: the zip's earliest
        return (1980, 1, 1, 0, 0, 0)
    try:
        d = datetime.datetime.fromtimestamp(v, datetime.timezone.utc)
    except (OverflowError, OSError, ValueError):
        pass
    if d is None or d.year < 1980:      # the zip format cannot hold earlier
        return (1980, 1, 1, 0, 0, 0)
    return (d.year, d.month, d.day, d.hour, d.minute, d.second)


def allocation(w, node):
    """What a volume stores for one file beside the size it records, as a dict,
    or None when the walker cannot say.

    NTFS and APFS can (see NtfsWalker.allocation and ApfsWalker.allocation):
    ``size`` is what read_file() returns, ``stored`` the bytes the volume holds
    for it, ``sparse`` and ``compression`` say why the two differ, and
    ``placeholder`` marks a cloud provider's file whose content is not on the
    volume. A caller copying files out can total ``stored`` to know what the
    files really occupy, and can keep a placeholder's name and dates without
    writing a file for it. Any other walker answers None, which means not
    known, not that nothing is stored.
    """
    report = getattr(w, "allocation", None)
    if report is None:
        return None
    try:
        return report(node)
    except Exception:                                # pylint: disable=broad-except
        return None


def chain_shortfall(w, node):
    """(clusters in the chain, clusters the recorded size needs) when a FAT32
    or exFAT file's cluster chain ends before its recorded size is covered,
    else None.

    A caller whose read came back shorter than the size, with nothing lost past
    the end of the image, can ask this to tell a volume that contradicts itself
    from a reader that went wrong. None means the chain covers the size or the
    walker has no such chain, not that the file is whole.
    """
    report = getattr(w, "chain_shortfall", None)
    if report is None:
        return None
    try:
        return report(node)
    except Exception:                                # pylint: disable=broad-except
        return None


def collect(w, num, prefix="", depth=0, seen=None, out=None, times=None):
    """Every regular file under this inode, as (path, inode, size, mtime).

    Pass a dict as ``times`` to also receive each path's recorded times, as the
    filesystem stores them, from walkers that keep readings rather than instants.
    FAT and exFAT are those: they hold a wall-clock reading and no zone, so
    ``mtime`` above stays zero for them and the readings arrive here as text
    instead, where nothing downstream can put a zone on them.
    """
    if seen is None:
        seen, out = set(), []
    if depth > 64 or num in seen:
        return out
    seen.add(num)
    if times is not None and hasattr(w, "listdir_records"):
        listing = w.listdir_records(num)
    else:
        listing = [(name, ino, None) for name, ino in w.listdir(num)]
    for name, ino, recorded in listing:
        ent = w.entry(ino)
        if not ent:
            continue
        mode, size, mtime = ent
        path = f"{prefix}/{name}" if prefix else name
        if times is not None and recorded:
            kept = {k: v for k, v in recorded.items() if v}
            if kept:
                times[path] = kept
        if mode & S_IFMT == S_IFDIR:    # not mode & S_IFDIR, which a block device also has
            collect(w, ino, path, depth + 1, seen, out, times)
        elif (mode & 0o170000) == 0o100000:          # regular files only
            out.append((path, ino, size, mtime))
        else:
            out.append((path, ino, None, mtime))     # symlink or special
    return out


def walk_all(w):
    """Every entry under this volume, directories included, as
    (path, node, mode, size, mtime, recorded).

    ``collect()`` returns the regular files, which is what an extraction needs,
    and reports them in tree order. A listing wants the directories as well,
    and wants them quickly. A walker that can produce its whole tree from one
    pass over its own records says so with a ``listing()`` method and this uses
    it; a walker that can only make its lookups cheaper says so with
    ``prime_records()``; anything else is walked the ordinary way.

    ``recorded`` is the dates as the filesystem stores them, for FAT and exFAT,
    which keep a wall-clock reading and no zone, and None for the rest.

    **The order is not promised** and is not the same by both routes: a
    walker's own ``listing()`` reports in the order its records sit in rather
    than in tree order. Sort by path where the order matters. ``collect()``
    is unchanged and still walks the tree, so nothing that relies on its order
    is affected by this.

    A fast route can also answer a slightly different question. NTFS is the
    one that does: see ``NtfsWalker.listing``, which reads what each record
    says about itself rather than what each directory says is in it. The two
    agree on every consistent volume measured and differ on 4 entries of
    313,652 on one acquisition whose directory indexes and records disagree.

    A directory is decided here, as in ``collect()``, by the format bits of the
    mode rather than by ``mode & S_IFDIR``, which is also true of a block
    device, whose format bits share that one. The JFFS2 fixtures carry a block
    device, which the looser test would have walked into as a directory.
    """
    fast = getattr(w, "listing", None)
    if fast is not None:
        for item in fast():
            yield item
        return
    prime = getattr(w, "prime_records", None)
    if prime is not None:
        prime()
    records = hasattr(w, "listdir_records")
    seen = set()

    def walk(node, prefix, depth):
        if depth > 64:
            return
        key = node[0] if isinstance(node, tuple) else node
        if key in seen:
            return
        seen.add(key)
        if records:
            listing = w.listdir_records(node)
        else:
            listing = [(name, ino, None) for name, ino in w.listdir(node)]
        for name, ino, recorded in listing:
            ent = w.entry(ino)
            if not ent:
                continue
            mode, size, mtime = ent
            path = f"{prefix}/{name}" if prefix else name
            yield (path, ino, mode, size, mtime, recorded)
            if mode & S_IFMT == S_IFDIR:
                for item in walk(ino, path, depth + 1):
                    yield item

    for item in walk(w.root, "", 0):
        yield item


def apply_exclude(entries, exclude):
    """Drop entries whose path contains any excluded substring."""
    if not exclude:
        return entries, 0
    keep = [e for e in entries if not any(x in e[0] for x in exclude)]
    return keep, len(entries) - len(keep)


class ProgressEmitter:
    """Throttled machine-readable extraction progress, one JSON object per line.

    Extraction of a head unit volume runs for minutes with nothing on stdout
    until the volume finishes, which reads as a hang to anything driving this
    as a subprocess. --progress emits to STDERR so the human report on stdout
    is untouched and a caller can consume one stream without parsing the other.

    Each line carries exact counts for the volume being written, not estimates:

        {"volume": "@13168672", "files": 1234, "total_files": 1629,
         "bytes": 123456789, "total_bytes": 297023717}

    Throttled to one line per interval, plus a final line per volume so a
    consumer always sees the completed state whatever the timing.
    """

    def __init__(self, stream=None, interval=1.0, clock=time.monotonic):
        self.stream = stream if stream is not None else sys.stderr
        self.interval = interval
        self.clock = clock
        self.last = 0.0

    def __call__(self, volume, files, written, total_files, total_bytes):
        now = self.clock()
        done = total_files and files >= total_files
        if not done and now - self.last < self.interval:
            return
        self.last = now
        self.stream.write(json.dumps({
            "volume": volume, "files": files, "total_files": total_files,
            "bytes": written, "total_bytes": total_bytes,
        }) + "\n")
        self.stream.flush()


# Characters a zip member name must not carry as they are: a backslash or a colon
# that an extracting tool on Windows reads as a separator or a stream, and
# control characters (NUL ends the name early in some tools).
_ZIP_UNSAFE = set(range(0x20)) | {0x7F, ord("\\"), ord(":")}


def _zip_safe_component(part):
    """One path component as a zip member may hold it: '.', '..' and an empty
    component (a '/' that was part of a stored name, or a leading one) are
    written escaped, and so is any character in _ZIP_UNSAFE, as %XX of its
    UTF-8 bytes. A '%' is escaped too, but only in a component that needs other
    escaping, so ordinary names stay exactly as stored."""
    if part in ("", ".", ".."):
        return {"": "%2F", ".": "%2E", "..": "%2E%2E"}[part]
    if not any(ord(c) in _ZIP_UNSAFE for c in part):
        return part
    return "".join("".join(f"%{b:02X}" for b in c.encode("utf-8"))
                   if ord(c) in _ZIP_UNSAFE or c == "%" else c for c in part)


def zip_member_name(volume, path):
    """The zip member name for a file at ``path`` (components joined by '/') in
    ``volume``: every component made safe by _zip_safe_component, so no member
    can climb out of the folder it is extracted into, start at a root, or be cut
    short, whatever names the filesystem stored."""
    return "/".join([_zip_safe_component(volume)]
                    + [_zip_safe_component(c) for c in path.split("/")])


def damage_lines(w, limit=5):
    """(count, first ``limit`` entries as text) of what a walker recorded as
    damage while it was read: an unreadable record, a structure that failed its
    check, a name it could not resolve. Walkers without such a list give (0, [])."""
    damage = getattr(w, "damage", None) or []
    return len(damage), [str(d)[:240] for d in list(damage)[:limit]]


def extract_to_zip(zf, w, volume, entries, log, progress=None):
    """Stream each regular file into the open zipfile. Returns a tally.

    Returns (files, written, skipped, failed, short). progress, when given, is
    called after each file with (volume, files_done, written_bytes,
    total_files, total_bytes). The totals are exact rather than estimated:
    entries is already the full list for this volume, so both are known before
    the first file is written.

    Member names come from zip_member_name(): a stored name that would climb out
    of the extraction folder ('..'), start at a root, carry a backslash, a colon
    or a control character is written escaped, and logged as RENAMED with the
    name as stored.

    A file whose blocks lie past the end of the image is a SHORT read: read_at()
    answers a seek past the end of the file with empty bytes, so the walker
    hands back fewer bytes than the inode says and raises nothing. Such a file
    is counted in short, not in files, and logged, and it is stored under a name
    that says how much of it is here: <path>.SHORT-<got>-of-<size>-bytes.

    Each file is read in full into a spool before anything is written, because
    zipfile cannot remove a member once it is written. A file whose read raises
    partway is therefore left out of the zip entirely, counted in failed and
    logged with the reason; streaming it would have left a member holding only
    the bytes read so far under the file's real name, which a reader of the zip
    cannot tell from an ordinary, shorter file. The spool stays in memory up to
    32 MiB and moves to a temporary file above that, so a larger file is written
    to disk twice and needs its own size free in the temporary folder.
    """
    import shutil
    import tempfile
    total_files = sum(1 for _, _, size, _ in entries if size is not None)
    total_bytes = sum(size for _, _, size, _ in entries if size is not None)
    files = written = skipped = failed = short = 0
    for path, ino, size, mtime in entries:
        arc = zip_member_name(volume, path)
        if arc != f"{volume}/{path}":
            log.append(f"        RENAMED {volume}/{path!r} stored as {arc}: the stored name "
                       f"carries characters a zip member cannot hold safely")
        if size is None:
            skipped += 1
            continue
        try:
            info = zipfile.ZipInfo(arc, date_time=_zip_time(mtime))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            got = 0
            before = EOF_SHORTFALL["bytes"]
            with tempfile.SpooledTemporaryFile(max_size=32 << 20) as spool:
                for chunk in w.read_file(ino, size):
                    spool.write(chunk)
                    got += len(chunk)
                # Only now, with the whole file read, does anything reach the zip.
                past_end = EOF_SHORTFALL["bytes"] - before
                got = min(got, max(size - past_end, 0))
                if got < size:
                    info.filename = f"{arc}.SHORT-{got}-of-{size}-bytes"
                spool.seek(0)
                with zf.open(info, "w") as dst:
                    shutil.copyfileobj(spool, dst)
            # A walker pads a block the image ends inside with zeros, so the bytes
            # it handed back are not the bytes that were there; the shortfall
            # read_at() tallied while this file was read is.
            if got < size:
                short += 1
                written += got
                cut = None if past_end else chain_shortfall(w, ino)
                if cut:
                    log.append(f"        SHORT {arc}: {got:,} of {size:,} bytes read, "
                               f"its cluster chain ends after {cut[0]:,} of the "
                               f"{cut[1]:,} clusters that size needs")
                else:
                    log.append(f"        SHORT {arc}: {got:,} of {size:,} bytes are in "
                               f"the image, the rest lies past its end")
            else:
                files += 1
                written += size
        except Exception as exc:
            failed += 1
            log.append(f"        could not extract {arc}: {exc}")
        if progress is not None:
            progress(volume, files, written, total_files, total_bytes)
    return files, written, skipped, failed, short


# ---------------------------------------------------------------------------
# Triage (--triage)
#
# A head unit can run to tens of gigabytes and most of it is not evidence.
# This ranks what was found so an examiner can decide what to pull first,
# using only what the probe already read.
#
# Two axes, because they disagree and that is the point:
#   ACTIVITY  how much the volume has been written. qnx6 exposes a commit
#             counter in the superblock serial; ext exposes mount count and
#             lifetime kilobytes written. This finds the user-data volume.
#   DENSITY   value per byte. A 4 MiB manufacturing volume holding the unit's
#             addresses, serials and keys outranks 25 GiB of map data on any
#             question an examiner is likely to ask.
#
# Ranking on size alone gets this backwards, which is why both are printed
# rather than combined into one score.
# ---------------------------------------------------------------------------
ENCRYPTED_NAME_MARKERS = ("ECRYPTFS_FNEK_ENCRYPTED",)


def sample_encryption(w, limit=400):
    """Fraction of sampled names that look like encrypted filenames."""
    from collections import deque
    seen = enc = 0
    queue = deque([w.root])
    while queue and seen < limit:
        num = queue.popleft()
        try:
            kids = w.listdir(num)
        except Exception:
            continue
        for name, ino in kids:
            seen += 1
            if any(mk in name for mk in ENCRYPTED_NAME_MARKERS):
                enc += 1
            if seen >= limit:
                break
            ent = w.entry(ino)
            if ent and ent[0] & S_IFMT == S_IFDIR and len(queue) < 512:
                queue.append(ino)
    return enc, seen


def triage_row(label, kind, size, used, activity, act_note, when, enc):
    return dict(label=label, kind=kind, size=size, used=used,
                activity=activity, act_note=act_note, when=when, enc=enc)


def print_triage(rows):
    if not rows:
        return
    print("\n" + "=" * 78)
    print("  TRIAGE  what to pull first")
    print("=" * 78)
    print("  Ranked by how much each volume has been written. Read the density")
    print("  column too: a small volume can outrank a large one.\n")
    rows = sorted(rows, key=lambda r: -(r["activity"] or 0))
    print(f"  {'volume':<26}{'type':<10}{'used':>11}{'activity':>14}  last write")
    print("  " + "-" * 74)
    for r in rows:
        act = f"{r['activity']:,}" if r["activity"] is not None else "-"
        print(f"  {r['label'][:25]:<26}{r['kind'][:9]:<10}{human(r['used']):>11}"
              f"{act:>14}  {r['when']}")
        notes = []
        if r["act_note"]:
            notes.append(r["act_note"])
        if r["enc"] and r["enc"][1]:
            e, t = r["enc"]
            if e:
                notes.append(f"{100*e//t}% of sampled names are ENCRYPTED, "
                             f"so contents are not parseable without keys")
        if r["size"]:
            pct = 100.0 * (r["used"] or 0) / r["size"]
            notes.append(f"{pct:.0f}% full of {human(r['size'])}")
        for nline in notes:
            print(f"  {'':<26}{nline}")
    print()
    print("  Pull the top of this list first, then any small volume whose name")
    print("  suggests manufacturing, identity or configuration. Skip volumes")
    print("  that are mostly empty bulk, and do not spend time on encrypted")
    print("  ones until you have the keys.")
    print()


def identify_ifs(fh, base):
    """Return detail lines if a QNX IFS boot image starts here, else None."""
    h = read_at(fh, base, IFS_HDR_SIZE)
    if len(h) < IFS_HDR_SIZE:
        return None
    g32 = lambda k: struct.unpack_from("<I", h, IFS_F[k])[0]
    g16 = lambda k: struct.unpack_from("<H", h, IFS_F[k])[0]
    if g32("signature") != QNX_IFS_SIG:
        return None
    hsz, ver, mach = g16("header_size"), g16("version"), g16("machine")
    ss, st, ifs_sz = g32("startup_size"), g32("stored_size"), g32("imagefs_size")
    flags1 = h[IFS_F["flags1"]]
    method = IFS_COMPRESS.get(flags1 & IFS_COMPRESS_MASK, "unknown")
    endian = "big" if flags1 & IFS_FLAG_BIGENDIAN else "little"

    lines = [f"version      {ver}" + ("" if ver == QNX_IFS_VER
                                      else f"   (STARTUP_HDR_VERSION is {QNX_IFS_VER})"),
             f"header_size  {hsz}" + ("   agrees with the 256-byte struct"
                                      if hsz == IFS_HDR_SIZE else
                                      "   DOES NOT match the 256-byte struct"),
             f"machine      {mach}  ({ELF_MACHINE.get(mach, 'unrecognised ELF machine')})",
             f"flags        0x{flags1:02x} 0x{h[IFS_F['flags2']]:02x}"
             f"   {endian} endian, {method} compression"
             f"   startup_vaddr 0x{g32('startup_vaddr'):08x}",
             f"startup      {human(ss)} of startup code, image filesystem begins at "
             f"0x{ss:x}"]

    stored_ifs = st - ss
    if stored_ifs == ifs_sz:
        how = "stored uncompressed"
    elif 0 < stored_ifs < ifs_sz:
        how = f"stored {method} compressed, {human(ifs_sz)} into {human(stored_ifs)}"
    else:
        how = "stored size and imagefs size disagree"
    lines.append(f"imagefs      {human(ifs_sz)} uncompressed, {how}")
    lines.append(f"total        {human(st)} stored on the partition")

    if method in ("ucl", "zlib", "none") and endian == "little":
        lines.append("contents     listed and extracted with --list and --extract")
    elif endian == "big":
        lines.append("contents     big-endian image, header reported but not walked here")
    elif method == "lzo":
        lines.append("contents     lzo compressed, not read here (no sample to "
                     "validate a reader), see --help")
    else:
        lines.append(f"contents     {method} compression, not read here, see --help")
    return lines


# ---------------------------------------------------------------------------
# XFS.
#
# XFS is the default filesystem of Red Hat Enterprise Linux and its rebuilds,
# and common on Linux servers, NAS units and storage appliances. It is read here
# directly, no mounting, and read only.
#
# The layout is sourced from xfsprogs v6.18.0 (commit
# 8b892adad226bb9fef4009c4cba4dbc25b70b011), the same release as the mkfs.xfs
# that wrote the fixtures. Line numbers below are at that commit:
#   libxfs/xfs_format.h    struct xfs_dsb (193), feature bits (35-87, 373-416),
#                          struct xfs_agf (517) and its sector (610), struct
#                          xfs_dinode (901), fork sizes (1093-1121), timestamps
#                          and the bigtime epoch (780-857), inode numbers
#                          (1270-1289), fsblock numbers (702-707), remote symlink
#                          header (1502), allocation btree records (1543), bmap
#                          records and roots (1843-1910), btree block headers
#                          (1928-1982)
#   libxfs/xfs_da_format.h directory blocks: shortform (214), data block header
#                          and entries (332-375), leaf (423-470), block tail
#                          (540), the three 32 GiB spaces (292-294, 418, 483)
#   libxfs/xfs_cksum.h     the CRC32C rule for every checksummed structure
#   libxfs/xfs_bmap_btree.c  xfs_bmbt_disk_get_all (77), xfs_bmdr_maxrecs (782),
#                          xfs_bmbt_maxrecs (747)
#   libxfs/xfs_dir2_sf.c   xfs_dir2_sf_entsize (41), xfs_dir2_sf_get_ino (72)
#   libxfs/xfs_dir2_priv.h xfs_dir2_data_entsize (200)
#   libxfs/xfs_dir2_data.c __xfs_dir3_data_check (96), xfs_dir3_data_end_offset (1231)
#   libxfs/xfs_dir2.c      the directory geometry (132-162), xfs_dir2_format (264)
#   libxfs/xfs_inode_buf.c xfs_inode_from_disk (175), xfs_dinode_verify (586)
#   libxfs/xfs_symlink_remote.c  xfs_symlink_verify (86), xfs_symlink_remote_read (236)
#   libxfs/xfs_alloc_btree.c xfs_allocbt_maxrecs (563)
#   libxfs/xfs_sb.c        xfs_sb_good_version (82), xfs_validate_sb_read (192),
#                          xfs_validate_sb_common (475), xfs_sb_read_verify (1072)
#   libxfs/xfs_log_format.h, libxlog/xfs_log_recover.c and libxlog/util.c for
#                          whether the log is clean (xlog_is_dirty, util.c:46)
# No xfsprogs code was copied; qnxprobe is MIT and xfsprogs is GPL. xfs_db and
# xfs_repair are used only as independent oracles for the fixtures.
#
# A file is found from its inode number alone: the number names the allocation
# group, the block in it and the slot in the block. Its data fork then holds the
# content inline (directories and symlinks only), a list of extents, or the root
# of a B+tree of extents. A directory larger than its inode keeps its entries in
# data blocks in the first 32 GiB of its own address space, with hash-ordered
# leaf blocks after 32 GiB and free-space blocks after 64 GiB. Listing needs only
# the data blocks, whatever the format; the leaf blocks are read to cross-check
# the count.
# ---------------------------------------------------------------------------
XFS_SB_MAGIC = b"XFSB"
XFS_DINODE_MAGIC = b"IN"
XFS_NULL_INO = 0xFFFFFFFFFFFFFFFF
XFS_MAXINUMBER = (1 << 56) - 1                  # xfs_format.h:1298
# sb_versionnum bits (xfs_format.h:35-48) and sb_features2 (74-87)
XFS_SB_VERSION_NUMBITS = 0x000F
XFS_SB_VERSION_SHAREDBIT = 0x0200
XFS_SB_VERSION_SECTORBIT = 0x0800
XFS_SB_VERSION_EXTFLGBIT = 0x1000
XFS_SB_VERSION_DIRV2BIT = 0x2000
XFS_SB_VERSION_MOREBITSBIT = 0x8000
XFS_SB_VERSION2_FTYPE = 0x0200
XFS_SB_VERSION2_OKBITS = 0x0002 | 0x0008 | 0x0080 | 0x0200
# v5 feature bits (xfs_format.h:373-416, 425)
XFS_RO_COMPAT = {0x1: "finobt", 0x2: "rmapbt", 0x4: "reflink", 0x8: "inobtcnt"}
XFS_INCOMPAT = {0x001: "ftype", 0x002: "sparse inodes", 0x004: "meta uuid",
                0x008: "bigtime", 0x010: "needsrepair", 0x020: "nrext64",
                0x040: "exchange range", 0x080: "parent pointers",
                0x100: "metadata directory", 0x200: "zoned realtime",
                0x400: "zone gaps"}
XFS_LOG_INCOMPAT = {0x1: "log xattrs"}
# The incompatible features this reader follows. Each changes something it
# reads (ftype, bigtime, nrext64), changes only what it does not read (sparse
# inode chunks change how inodes are allocated, not where a number puts one;
# exchange range and parent pointers add log items and attributes; the metadata
# directory moves quota and realtime inodes out of the root tree), or is a flag
# it reports (meta uuid, needsrepair). The zoned realtime allocator and its zone
# gaps are refused: they belong to a realtime section this reader does not read.
XFS_INCOMPAT_READ = 0x001 | 0x002 | 0x004 | 0x008 | 0x010 | 0x020 | 0x040 | 0x080 | 0x100
XFS_INCOMPAT_FTYPE, XFS_INCOMPAT_META_UUID = 0x001, 0x004
XFS_INCOMPAT_NEEDSREPAIR, XFS_INCOMPAT_NREXT64 = 0x010, 0x020
# di_flags, di_flags2 and di_format (xfs_format.h:1012-1017, 1145-1238)
XFS_DIFLAG_REALTIME = 0x1
XFS_DIFLAG2_BIGTIME, XFS_DIFLAG2_NREXT64 = 0x8, 0x10
XFS_FMT_DEV, XFS_FMT_LOCAL, XFS_FMT_EXTENTS, XFS_FMT_BTREE = 0, 1, 2, 3
XFS_FMT_NAMES = {0: "dev", 1: "local", 2: "extents", 3: "btree", 4: "uuid", 5: "meta_btree"}
XFS_BIGTIME_EPOCH_OFFSET = 1 << 31              # xfs_format.h:845
# btree block magics (xfs_format.h:1535-1538, 1837-1838)
XFS_BMAP_MAGIC, XFS_BMAP_CRC_MAGIC = b"BMAP", b"BMA3"
XFS_ABTB_MAGIC, XFS_ABTB_CRC_MAGIC = b"ABTB", b"AB3B"
XFS_AGF_MAGIC = b"XAGF"
XFS_SYMLINK_MAGIC = b"XSLM"
XFS_SYMLINK_HDR = 56                            # struct xfs_dsymlink_hdr
# directory blocks (xfs_da_format.h)
XFS_DIR_DATA_MAGICS = {b"XD2B": "block", b"XDB3": "block", b"XD2D": "data", b"XDD3": "data"}
XFS_DIR_LEAF_MAGICS = (0xD2F1, 0xD2FF, 0x3DF1, 0x3DFF)    # leaf1 and leafn, v2 and v3
XFS_DIR2_DATA_FREE_TAG = 0xFFFF
XFS_DIR2_SPACE_BYTES = 1 << 35                   # XFS_DIR2_SPACE_SIZE, 32 GiB
XFS_DA_NODE_MAGICS = (0xFEBE, 0x3EBE)            # xfs_da_format.h:16, 36
XFS_MAX_FILEOFF = (1 << 54) - 1 + (1 << 21) - 1  # xfs_format.h:1869
XFS_SYMLINK_MAXLEN = 1024                        # xfs_format.h:1515
# the file types a mode may carry (xfs_mode_to_ftype, xfs_dir2.c:43)
XFS_MODE_FORMATS = (0o100000, 0o040000, 0o020000, 0o060000, 0o010000, 0o140000, 0o120000)
# the log (xfs_log_format.h:26, 105, 128)
XLOG_HEADER_MAGIC = 0xFEEDBABE
XLOG_UNMOUNT_TRANS = 0x20
XLOG_HEADER_CYCLE_SIZE = 32 * 1024
XLOG_BBSIZE = 512

_CRC32C_TABLE = []


def xfs_crc32c(data, crc=0xFFFFFFFF):
    """CRC32C (Castagnoli, reflected polynomial 0x82F63B78) over data, with no
    final inversion, which is how xfs_cksum.h chains it."""
    if not _CRC32C_TABLE:
        for i in range(256):
            c = i
            for _ in range(8):
                c = (c >> 1) ^ 0x82F63B78 if c & 1 else c >> 1
            _CRC32C_TABLE.append(c)
    t = _CRC32C_TABLE
    for b in data:
        crc = t[(crc ^ b) & 0xFF] ^ (crc >> 8)
    return crc


def xfs_cksum_ok(buf, off):
    """True when the le32 at ``off`` is the XFS checksum of buf: CRC32C seeded
    with ~0 over the whole buffer with that field read as zero, then inverted
    (xfs_cksum.h xfs_start_cksum_safe, xfs_end_cksum, xfs_verify_cksum)."""
    if len(buf) < off + 4:
        return False
    crc = xfs_crc32c(buf[:off])
    crc = xfs_crc32c(b"\0\0\0\0", crc)
    crc = xfs_crc32c(buf[off + 4:], crc)
    return struct.unpack_from("<I", buf, off)[0] == (~crc & 0xFFFFFFFF)


class XfsUnreadable(Exception):
    """An XFS volume or file this reader will not hand back; the message says why."""


def _xfs_zeros(n):
    """n zero bytes for a hole, in pieces that do not sit in memory at once."""
    while n > 0:
        piece = min(n, 1 << 20)
        yield bytes(piece)
        n -= piece


def _xfs_sb(raw):
    """The superblock fields this reader uses, by name (struct xfs_dsb, xfs_format.h:193)."""
    g = lambda fmt, off: struct.unpack_from(">" + fmt, raw, off)[0]
    return dict(
        blocksize=g("I", 4), dblocks=g("Q", 8), rblocks=g("Q", 16), uuid=raw[32:48],
        logstart=g("Q", 48), rootino=g("Q", 56), agblocks=g("I", 84), agcount=g("I", 88),
        logblocks=g("I", 96), versionnum=g("H", 100), sectsize=g("H", 102),
        inodesize=g("H", 104), inopblock=g("H", 106),
        fname=raw[108:120].split(b"\0")[0].decode("utf-8", "replace"),
        blocklog=raw[120], sectlog=raw[121], inodelog=raw[122], inopblog=raw[123],
        agblklog=raw[124], inprogress=raw[126], icount=g("Q", 128), ifree=g("Q", 136),
        fdblocks=g("Q", 144), dirblklog=raw[192], features2=g("I", 200),
        compat=g("I", 208), ro_compat=g("I", 212), incompat=g("I", 216),
        log_incompat=g("I", 220), crc=g("I", 224), meta_uuid=raw[248:264])


def _xfs_sb_geometry(sb):
    """The superblock geometry fields that do not hold as the kernel requires
    them (xfs_validate_sb_common, xfs_sb.c:475), as text, or [] when all do."""
    bs, ss, isz = sb["blocksize"], sb["sectsize"], sb["inodesize"]
    bad = []
    if not (512 <= bs <= 65536) or bs != 1 << sb["blocklog"]:
        bad.append(f"block size {bs}")
    if not (512 <= ss <= 32768) or ss != 1 << sb["sectlog"]:
        bad.append(f"sector size {ss}")
    if not (256 <= isz <= 2048) or isz != 1 << sb["inodelog"] or sb["inopblock"] != bs // max(isz, 1) \
            or sb["blocklog"] - sb["inodelog"] != sb["inopblog"]:
        bad.append(f"inode size {isz}")
    ag = sb["agblocks"]
    if not ag or not sb["agcount"] or sb["agblklog"] != (ag - 1).bit_length() \
            or -(-sb["dblocks"] // ag) != sb["agcount"]:
        bad.append(f"{sb['agcount']} allocation groups of {ag} blocks for {sb['dblocks']} blocks")
    if sb["dirblklog"] + sb["blocklog"] > 16:
        bad.append(f"directory block log {sb['dirblklog']}")
    return bad


def _xfs_sb_refusal(sb, raw):
    """Why this superblock is not one to walk, or None. The checks are the
    geometry the kernel insists on (xfs_validate_sb_common, xfs_sb.c:475), the
    versions it accepts (xfs_sb_good_version, xfs_sb.c:82), the CRC it requires
    of a v5 primary superblock (xfs_sb_read_verify, xfs_sb.c:1072) and the
    incompatible features it refuses (xfs_validate_sb_read, xfs_sb.c:192)."""
    ver = sb["versionnum"] & XFS_SB_VERSION_NUMBITS
    if ver not in (4, 5):
        return f"superblock version {ver}; only versions 4 and 5 are read, as the kernel reads only those"
    if ver == 5 and not xfs_cksum_ok(raw[:sb["sectsize"]], 224):
        return "the superblock CRC does not hold, and the kernel will not mount a v5 volume on that"
    bad = _xfs_sb_geometry(sb)
    if bad:
        return "the superblock geometry does not hold: " + ", ".join(bad)
    if ver == 4:
        vn = sb["versionnum"]
        if vn & XFS_SB_VERSION_SHAREDBIT or (vn & XFS_SB_VERSION_MOREBITSBIT
                                             and sb["features2"] & ~XFS_SB_VERSION2_OKBITS):
            return f"v4 feature bits the kernel does not know (versionnum 0x{vn:04x}, features2 0x{sb['features2']:x})"
        if not vn & XFS_SB_VERSION_DIRV2BIT or not vn & XFS_SB_VERSION_EXTFLGBIT:
            return "a v4 volume without version 2 directories or unwritten extents, which the kernel does not mount"
        return None
    not_read = sb["incompat"] & ~XFS_INCOMPAT_READ
    if not_read:
        names = [XFS_INCOMPAT.get(1 << k, f"unknown bit 0x{1 << k:x}") for k in range(32) if not_read >> k & 1]
        return "incompatible features not read here: " + ", ".join(names)
    return None


def _xfs_features(sb):
    """The feature names the superblock carries, for the report."""
    if sb["versionnum"] & XFS_SB_VERSION_NUMBITS != 5:
        ftype = sb["versionnum"] & XFS_SB_VERSION_MOREBITSBIT and sb["features2"] & XFS_SB_VERSION2_FTYPE
        return ["ftype"] if ftype else []
    out = [n for b, n in XFS_INCOMPAT.items() if sb["incompat"] & b]
    out += [n for b, n in XFS_RO_COMPAT.items() if sb["ro_compat"] & b]
    out += [f"unknown read-only-compatible bit 0x{1 << k:x}" for k in range(32)
            if sb["ro_compat"] >> k & 1 and (1 << k) not in XFS_RO_COMPAT]
    out += [n for b, n in XFS_LOG_INCOMPAT.items() if sb["log_incompat"] & b]
    return out


def _xfs_log_state(fh, base, sb):
    """(state, detail, head, tail) for the internal log: state is "clean",
    "dirty", "external" or "unknown", head and tail are 512-byte log block
    numbers (None when not found).

    This follows xlog_is_dirty (libxlog/util.c:46): find the head of the log
    (xlog_find_head, xfs_log_recover.c:400) and its tail (xlog_find_tail, 671),
    and the log is dirty when they differ. The head is found the way
    xlog_find_head finds it first, by the cycle number stamped in each 512-byte
    block (xlog_get_cycle, xfs_log_format.h:62) and a binary search for where it
    drops (xlog_find_cycle_start, 178). The passes the kernel then makes to step
    back over a torn write at the head (xlog_find_verify_cycle and
    xlog_find_verify_log_record) are not made, so on a log cut mid-write the
    head found here can be later than the kernel's. The tail is the block after
    the last record when that record is an unmount record alone, else the tail
    the last record names.
    """
    if sb["logstart"] == 0:
        return "external", "the log is on a separate device, not in this image", None, None
    bs, agblk = sb["blocksize"], sb["agblocks"]
    fsb = sb["logstart"]
    start = base + ((fsb >> sb["agblklog"]) * agblk + (fsb & ((1 << sb["agblklog"]) - 1))) * bs
    nbb = sb["logblocks"] * bs // XLOG_BBSIZE
    if nbb < 2:
        return "unknown", "the log is too small to hold a record", None, None

    def blk(i, n=1):
        b = read_at(fh, start + i * XLOG_BBSIZE, n * XLOG_BBSIZE)
        if len(b) < n * XLOG_BBSIZE:
            raise XfsUnreadable("the log lies past the end of the image")
        return b

    def cycle(i):
        w0, w1 = struct.unpack_from(">II", blk(i), 0)
        return w1 if w0 == XLOG_HEADER_MAGIC else w0

    def cycle_start(first, last, want):
        mid = (first + last) // 2
        while mid not in (first, last):
            if cycle(mid) == want:
                last = mid
            else:
                first = mid
            mid = (first + last) // 2
        return last

    try:
        first, last = cycle(0), cycle(nbb - 1)
        if last == 0:                                   # xlog_find_zeroed
            if first == 0:
                return "clean", "the log has never been written", 0, 0
            if first != 1:
                return ("unknown", "the log is neither written through nor zeroed past its first cycle",
                        None, None)
            head = cycle_start(0, nbb - 1, 0)
        elif first == last:
            head = 0                                    # the head wrapped to the start
        else:
            head = cycle_start(0, nbb - 1, last)
        # xlog_find_tail: the last record header before the head
        found = None
        order = itertools.chain(range(head - 1, -1, -1), range(nbb - 1, head - 1, -1))
        for n, i in enumerate(order):
            if n > 8192:                                # 4 MiB, far more than one record
                return "unknown", "no log record header within 4 MiB before the head", head, None
            if struct.unpack_from(">I", blk(i), 0)[0] == XLOG_HEADER_MAGIC:
                found = i
                break
        if found is None:
            return "unknown", "no log record header found", head, None
        h = blk(found)
        version, h_len = struct.unpack_from(">II", h, 8)
        tail_lsn = struct.unpack_from(">Q", h, 24)[0]
        num_logops = struct.unpack_from(">I", h, 40)[0]
        h_size = struct.unpack_from(">I", h, 320)[0]
        hblks = -(-h_size // XLOG_HEADER_CYCLE_SIZE) if version & 2 and h_size > XLOG_HEADER_CYCLE_SIZE else 1
        after = (found + hblks + -(-h_len // XLOG_BBSIZE)) % nbb
        tail = tail_lsn & 0xFFFFFFFF
        if head == after and num_logops == 1:
            op = blk((found + hblks) % nbb)
            if op[9] & XLOG_UNMOUNT_TRANS:
                tail = after
    except XfsUnreadable as exc:
        return "unknown", str(exc), None, None
    if head == tail:
        return "clean", f"head and tail at log block {head}", head, tail
    return "dirty", f"head at log block {head}, tail at {tail}", head, tail


def _xfs_root_is_dir(fh, base, sb):
    """True when the root inode the superblock names reads as a directory inode
    (inode magic, a version the volume allows, a directory mode). A v4
    superblock has no CRC, so this is what stands in for one before the volume
    is claimed."""
    ino = sb["rootino"]
    agino_log = sb["inopblog"] + sb["agblklog"]
    agno, agino = ino >> agino_log, ino & ((1 << agino_log) - 1)
    agbno, slot = agino >> sb["inopblog"], agino & ((1 << sb["inopblog"]) - 1)
    if not ino or agno >= sb["agcount"] or agbno >= sb["agblocks"]:
        return False
    raw = read_at(fh, base + (agno * sb["agblocks"] + agbno) * sb["blocksize"]
                  + slot * sb["inodesize"], 8)
    return (len(raw) == 8 and raw[:2] == XFS_DINODE_MAGIC and raw[4] in (1, 2, 3)
            and struct.unpack_from(">H", raw, 2)[0] & S_IFMT == S_IFDIR)


def identify_xfs(fh, base, size=None):
    """Return ("xfs", lines) for an XFS volume at base, else None.

    The magic and a block size that agrees with its own base-2 logarithm
    (sb_blocklog) make a candidate. It is claimed only once it is verified: the
    superblock geometry holds as the kernel requires it (xfs_validate_sb_common,
    xfs_sb.c:475), and on v5 the superblock CRC holds (xfs_sb_read_verify,
    xfs_sb.c:1072). A v4 superblock has no CRC, so its root inode must also read
    as a directory. A candidate that fails is not claimed, and the identifiers
    after this one get their turn. A verified volume this reader will not walk
    (an incompatible feature, say) is still named XFS, with the reason.
    """
    head = read_at(fh, base, 512)
    if len(head) < 512 or head[:4] != XFS_SB_MAGIC:
        return None
    bs, blocklog = struct.unpack_from(">I", head, 4)[0], head[120]
    if not (512 <= bs <= 65536) or bs != 1 << blocklog:
        return None
    sectsize = struct.unpack_from(">H", head, 102)[0]
    raw = read_at(fh, base, max(512, min(sectsize, 32768)))
    sb = _xfs_sb(raw)
    ver = sb["versionnum"] & XFS_SB_VERSION_NUMBITS
    if ver not in (4, 5) or _xfs_sb_geometry(sb):
        return None
    if ver == 5 and not xfs_cksum_ok(raw[:sectsize], 224):
        return None
    if ver == 4 and not _xfs_root_is_dir(fh, base, sb):
        return None
    total = sb["dblocks"] * bs
    used = total - sb["fdblocks"] * bs
    feats = _xfs_features(sb)
    lines = [
        f"label        {sb['fname'] or '(none)'}",
        f"uuid         {sb['uuid'].hex()}",
        f"version      {ver}" + ("   metadata CRCs" if ver == 5 else "   no metadata CRCs"),
        f"features     {', '.join(feats) or '(none)'}",
        f"geometry     {bs:,}-byte blocks, {sb['agcount']} allocation groups of "
        f"{sb['agblocks']:,} blocks, {sb['inodesize']}-byte inodes, {sectsize}-byte sectors",
        (f"used         {human(used)} of {human(total)} ({100.0 * used / total:.1f}%), "
         "by the superblock's free count" if total and 0 <= used <= total else "used         unknown"),
        f"inodes       {sb['icount']:,} allocated, {sb['ifree']:,} of them free",
    ]
    if size is not None and total > size:
        lines.append(f"INCOMPLETE   the volume is {human(total)} but its region holds "
                     f"{human(size)}: its end is missing")
    if sb["rblocks"]:
        lines.append(f"realtime     a realtime section of {sb['rblocks']:,} blocks, on its own "
                     "device; its files are listed but not read")
    why = _xfs_sb_refusal(sb, raw)
    if why is None:
        try:
            state, detail = _xfs_log_state(fh, base, sb)[:2]
        except (struct.error, ValueError) as exc:
            state, detail = "unknown", str(exc)
        lines.append(f"log          {state}: {detail}" + (
            "; it was not replayed, so the volume is read as it is stored" if state == "dirty" else ""))
        if ver == 5 and sb["incompat"] & XFS_INCOMPAT_NEEDSREPAIR:
            lines.append("state        flagged as needing xfs_repair before the kernel will mount it")
        if sb["inprogress"]:
            lines.append("state        mkfs had not finished writing it (sb_inprogress)")
    else:
        lines.append(f"walk         not possible: {why}")
    return "xfs", lines


class XfsWalker:
    """List and read an XFS volume. A node is an inode number, which is what a
    directory entry records, so a hard link is one node reached by two names.

    What the kernel checks before it uses a structure is checked here: the CRC,
    block number, owner and uuid of every v5 metadata block, the inode core and
    its forks (xfs_dinode_verify), and that every block number points inside the
    volume and not at an AG's own headers (xfs_verify_fsbext). What fails is not
    used, and is counted in ``damage`` (shown in ``note``): an inode that fails
    reads as absent, a directory block that fails is skipped and the rest of the
    directory still listed, and a file whose extent map or symlink block fails
    raises rather than come back cut.

    ``size`` is the byte length of the region the volume sits in. When the
    volume says it is larger, the note says its end is missing, a structure
    past the end is counted as damage, and file data past it reads short.
    """

    def __init__(self, fh, base, size=None):
        self.fh, self.base = fh, base
        head = read_at(fh, base, 512)
        if len(head) < 512 or head[:4] != XFS_SB_MAGIC:
            raise XfsUnreadable("no XFS superblock")
        ss = struct.unpack_from(">H", head, 102)[0]
        raw = read_at(fh, base, max(512, min(ss, 32768)))
        sb = _xfs_sb(raw)
        why = _xfs_sb_refusal(sb, raw)
        if why:
            raise XfsUnreadable(why)
        self.sb = sb
        self.v5 = sb["versionnum"] & XFS_SB_VERSION_NUMBITS == 5
        self.bs, self.blocklog = sb["blocksize"], sb["blocklog"]
        self.dblocks = sb["dblocks"]
        self.agblocks, self.agblklog, self.agcount = sb["agblocks"], sb["agblklog"], sb["agcount"]
        self.isz, self.inopblog = sb["inodesize"], sb["inopblog"]
        self.agino_log = sb["inopblog"] + sb["agblklog"]       # xfs_ialloc.c:2987
        self.sectsize = sb["sectsize"]
        # the AGFL's block: blocks up to it hold the AG headers (XFS_AGFL_BLOCK,
        # xfs_format.h:689), which no extent may point at (xfs_types.c:24)
        self.agfl_block = 3 * self.sectsize // self.bs
        self.ftype = bool(sb["incompat"] & XFS_INCOMPAT_FTYPE) if self.v5 else bool(
            sb["versionnum"] & XFS_SB_VERSION_MOREBITSBIT and sb["features2"] & XFS_SB_VERSION2_FTYPE)
        # the uuid stamped in checksummed metadata (xfs_dinode_verify, xfs_symlink_verify)
        self.meta_uuid = sb["meta_uuid"] if self.v5 and sb["incompat"] & XFS_INCOMPAT_META_UUID \
            else sb["uuid"]
        self.core = 176 if self.v5 else 100                     # xfs_dinode_size()
        self.litino = self.isz - self.core                      # XFS_LITINO
        # directory geometry (xfs_dir2.c:132-162)
        self.dir_fsbcount = 1 << sb["dirblklog"]
        self.dir_blksize = self.bs << sb["dirblklog"]
        self.data_entry_offset = 64 if self.v5 else 16
        self.leafblk = XFS_DIR2_SPACE_BYTES >> self.blocklog
        self.freeblk = 2 * XFS_DIR2_SPACE_BYTES >> self.blocklog
        # the largest file size and extent B+tree height the format allows
        self.max_size = min((1 << 63) - 1, XFS_MAX_FILEOFF << self.blocklog)
        self.large_extents = bool(self.v5 and sb["incompat"] & XFS_INCOMPAT_NREXT64)
        self.bmbt_hdr = 72 if self.v5 else 24
        self.bm_maxlevels = self._bm_maxlevels()
        self.root = sb["rootino"]
        self.damage = []
        self._damage_seen = set()
        self._inodes = collections.OrderedDict()
        self.end = base + size if size is not None else None
        self.log_state = _xfs_log_state(fh, base, sb)
        state, detail = self.log_state[:2]
        notes = []
        vol = self.dblocks * self.bs
        if size is not None and vol > size:
            notes.append(f"the volume is {human(vol)} but its region holds {human(size)}: its end "
                         "is missing, so what was stored past that is counted as damaged or read short")
        if state == "dirty":
            notes.append(f"the log is dirty ({detail}): what it holds was not replayed, "
                         "so the volume is read as it is stored")
        if self.v5 and sb["incompat"] & XFS_INCOMPAT_NEEDSREPAIR:
            notes.append("the volume is flagged as needing xfs_repair")
        if sb["rblocks"]:
            notes.append("files on its realtime device are listed but not read")
        self._static_note = "; ".join(notes)

    def _bm_maxlevels(self):
        """The tallest data-fork extent B+tree the volume can hold, computed as
        xfs_bmap_compute_maxlevels does (xfs_bmap.c:50): the most extents a fork
        may count (xfs_format.h:1062-1064), blocks half full, a root of three
        records (MINDBTPTRS)."""
        maxleafents = (1 << 48) - 1 if self.large_extents else (1 << 31) - 1
        per = (self.bs - self.bmbt_hdr) // 16           # xfs_bmbt_maxrecs, leaf and node alike
        minrecs = max(per // 2, 1)
        maxblocks = -(-maxleafents // minrecs)
        level = 1
        while maxblocks > 1:
            maxblocks = 1 if maxblocks <= 3 else -(-maxblocks // minrecs)
            level += 1
        return level

    @property
    def note(self):
        """A missing end, a dirty log, a needsrepair flag, a realtime section,
        and any structure that failed its check so far, or None."""
        parts = [self._static_note] if self._static_note else []
        if self.damage:
            parts.append(f"{len(self.damage)} damaged structure(s) skipped, first: {self.damage[0]}")
        return "; ".join(parts) or None

    def _damaged(self, what):
        if what not in self._damage_seen and len(self.damage) < 1000:
            self._damage_seen.add(what)
            self.damage.append(what)

    # -- addressing --------------------------------------------------------
    def ag_length(self, agno):
        """Blocks in AG ``agno``: agblocks, except the last, which ends where
        the volume does (__xfs_ag_block_count, xfs_ag.c:136)."""
        return self.agblocks if agno < self.agcount - 1 else self.dblocks - agno * self.agblocks

    def _fsb_ok(self, fsb):
        """Whether ``fsb`` is a block an extent or btree pointer may name: in an
        AG of the volume, before that AG's end, and past its headers
        (xfs_verify_fsbno and xfs_verify_agno_agbno, xfs_types.c:24-52)."""
        agno, agbno = fsb >> self.agblklog, fsb & ((1 << self.agblklog) - 1)
        return agno < self.agcount and self.agfl_block < agbno < self.ag_length(agno)

    def _ext_ok(self, fsb, count):
        """xfs_verify_fsbext (xfs_types.c:60): both ends valid, in one AG."""
        last = fsb + count - 1
        return (count > 0 and self._fsb_ok(fsb) and self._fsb_ok(last)
                and fsb >> self.agblklog == last >> self.agblklog)

    def _fsb_off(self, fsb):
        """Byte offset in the image of filesystem block ``fsb``, which is an
        AG number above agblklog bits of block-in-AG (XFS_FSB_TO_AGNO,
        XFS_FSB_TO_AGBNO, xfs_format.h:702-707); None when it is not a block
        an extent may name."""
        if not self._fsb_ok(fsb):
            return None
        agno, agbno = fsb >> self.agblklog, fsb & ((1 << self.agblklog) - 1)
        return self.base + (agno * self.agblocks + agbno) * self.bs

    def _meta(self, off, n, what):
        """n bytes of metadata at ``off``, or None, counted as damage, when any
        of them lie past the end of the volume's region or of the image."""
        if self.end is not None and off + n > self.end:
            self._damaged(f"{what} lies past the end of the volume's region")
            return None
        buf = read_at(self.fh, off, n)
        if len(buf) < n:
            self._damaged(f"{what} lies past the end of the image")
            return None
        return buf

    def _data(self, off, n):
        """n bytes of file data at ``off``. What lies past the region's end is
        not read, since it belongs to whatever follows the region, and is zeros
        here, counted in EOF_SHORTFALL as a read past the image's end is, so an
        extraction names the file short rather than whole."""
        if self.end is not None and off + n > self.end:
            keep = max(0, self.end - off)
            buf = read_at(self.fh, off, keep) if keep else b""
            EOF_SHORTFALL["bytes"] += n - len(buf)
            return buf + bytes(n - len(buf))
        buf = read_at(self.fh, off, n)
        if len(buf) < n:
            buf += bytes(n - len(buf))
        return buf

    # -- inodes ------------------------------------------------------------
    def inode_offset(self, ino):
        """Byte offset in the image of inode ``ino``, or None when the number
        is out of range. The number is the AG, then the block in the AG, then
        the slot in the block (XFS_INO_TO_AGNO, XFS_INO_TO_AGBNO and
        XFS_INO_TO_OFFSET, xfs_format.h:1277-1285)."""
        agno = ino >> self.agino_log
        agino = ino & ((1 << self.agino_log) - 1)
        agbno, slot = agino >> self.inopblog, agino & ((1 << self.inopblog) - 1)
        if not ino or agno >= self.agcount or not self.agfl_block < agbno < self.ag_length(agno):
            return None
        return self.base + (agno * self.agblocks + agbno) * self.bs + slot * self.isz

    def inode(self, ino):
        """The inode's fields as a dict, or None, counted as damage, when it
        cannot be used: its number out of range, the inode past the end of the
        region, or a check of xfs_dinode_verify (xfs_inode_buf.c:586) that
        fails, in the kernel's order: the magic, then on v5 the CRC, inode
        number and uuid, then the size, mode, fork offset and forks."""
        hit = self._inodes.get(ino)
        if hit is not None:
            self._inodes.move_to_end(ino)
            return hit
        off = self.inode_offset(ino)
        if off is None:
            self._damaged(f"inode {ino} is outside the volume")
            return None
        raw = self._meta(off, self.isz, f"inode {ino}")
        if raw is None:
            return None
        why = self._dinode_problem(ino, raw)
        if why:
            self._damaged(f"inode {ino} {why}")
            return None
        version = raw[4]
        flags2 = struct.unpack_from(">Q", raw, 120)[0] if version == 3 else 0
        big = flags2 & XFS_DIFLAG2_NREXT64
        d = dict(
            ino=ino, mode=struct.unpack_from(">H", raw, 2)[0], version=version, format=raw[5],
            nlink=(struct.unpack_from(">H", raw, 6)[0] if version == 1
                   else struct.unpack_from(">I", raw, 16)[0]),
            uid=struct.unpack_from(">I", raw, 8)[0], gid=struct.unpack_from(">I", raw, 12)[0],
            size=struct.unpack_from(">Q", raw, 56)[0], nblocks=struct.unpack_from(">Q", raw, 64)[0],
            nextents=(struct.unpack_from(">Q", raw, 24)[0] if big
                      else struct.unpack_from(">I", raw, 76)[0]),
            forkoff=raw[82], flags=struct.unpack_from(">H", raw, 90)[0], flags2=flags2)
        bigtime = flags2 & XFS_DIFLAG2_BIGTIME
        for name, at in (("atime", 32), ("mtime", 40), ("ctime", 48), ("crtime", 144)):
            if name == "crtime" and version != 3:
                d[name] = None
            elif bigtime:                               # ns since 1901-12-13 (xfs_format.h:845-857)
                v = struct.unpack_from(">Q", raw, at)[0]
                d[name] = (v // 10**9 - XFS_BIGTIME_EPOCH_OFFSET) * 10**9 + v % 10**9
            else:                                       # signed seconds, nanoseconds
                sec, nsec = struct.unpack_from(">iI", raw, at)
                d[name] = sec * 10**9 + nsec
        dsize = d["forkoff"] << 3 if d["forkoff"] else self.litino      # XFS_DFORK_DSIZE
        d["fork"] = raw[self.core:self.core + dsize]
        self._inodes[ino] = d
        while len(self._inodes) > 4096:
            self._inodes.popitem(last=False)
        return d

    def _dinode_problem(self, ino, raw):
        """What xfs_dinode_verify (xfs_inode_buf.c:586) would reject this inode
        for, or None. A free inode (mode 0) is not rejected here."""
        if raw[:2] != XFS_DINODE_MAGIC:
            return "has no inode magic"
        version = raw[4]
        if self.v5:
            if version != 3:
                return f"is version {version} on a v5 volume"
            if not xfs_cksum_ok(raw, 100):
                return "fails its CRC"
            if struct.unpack_from(">Q", raw, 152)[0] != ino or raw[160:176] != self.meta_uuid:
                return "names another inode or volume"
        elif version not in (1, 2):
            return f"is version {version} on a v4 volume"
        mode, = struct.unpack_from(">H", raw, 2)
        size, = struct.unpack_from(">Q", raw, 56)
        if size > self.max_size:                        # bit 63 (xfs_inode_buf.c:635), XFS_MAX_FILEOFF
            return f"records a size of {size:,} bytes, past the largest the format allows"
        if not mode:
            return None
        fmt_bits = mode & S_IFMT
        if fmt_bits not in XFS_MODE_FORMATS:          # xfs_mode_to_ftype (xfs_inode_buf.c:639)
            return f"has mode {mode:o}, which is no file type"
        forkoff, fmt = raw[82], raw[5]
        flags2 = struct.unpack_from(">Q", raw, 120)[0] if version == 3 else 0
        big = flags2 & XFS_DIFLAG2_NREXT64
        nextents = (struct.unpack_from(">Q", raw, 24)[0] if big
                    else struct.unpack_from(">I", raw, 76)[0])
        if fmt_bits in (S_IFREG, S_IFDIR, S_IFLNK):
            # xfs_dinode_verify_forkoff (xfs_inode_buf.c:476)
            if forkoff and forkoff >= self.litino >> 3:
                return f"has a fork offset of {forkoff << 3} bytes, past its literal area"
            dsize = forkoff << 3 if forkoff else self.litino
            # xfs_dinode_verify_fork (xfs_inode_buf.c:369)
            if fmt == XFS_FMT_LOCAL:
                if fmt_bits == S_IFREG:
                    return "is a regular file stored in its inode, which XFS does not write"
                if nextents:
                    return f"is stored in its inode but counts {nextents} extents"
                if size > dsize:
                    return f"is stored in its inode but records {size} bytes, more than fit"
            elif fmt == XFS_FMT_EXTENTS:
                if nextents > dsize // 16:
                    return f"counts {nextents:,} extents in a fork that holds {dsize // 16}"
                if fmt_bits == S_IFDIR and size and size <= dsize:
                    return "is a directory small enough for its inode but not stored there"
            elif fmt == XFS_FMT_BTREE:
                if nextents > ((1 << 48) - 1 if big else (1 << 31) - 1):
                    return f"counts {nextents:,} extents, more than a fork may"
            else:
                return f"has data fork format {XFS_FMT_NAMES.get(fmt, fmt)}, which a "\
                       f"{'directory' if fmt_bits == S_IFDIR else 'file'} cannot have"
        return None

    def entry(self, ino):
        d = self.inode(ino)
        if d is None:
            return None
        if not d["mode"]:
            self._damaged(f"inode {ino} is named by a directory but is free")
            return None
        return d["mode"], d["size"], d["mtime"] // 10**9

    def inode_info(self, ino):
        """Every time in nanoseconds (crtime None before v5), the link count and
        the data fork format, for a caller that wants more than entry()."""
        d = self.inode(ino)
        if d is None:
            return None
        return {k: d[k] for k in ("ino", "mode", "size", "nlink", "uid", "gid", "atime",
                                  "mtime", "ctime", "crtime", "nextents")} | {
            "format": XFS_FMT_NAMES.get(d["format"], str(d["format"])),
            "realtime": bool(d["flags"] & XFS_DIFLAG_REALTIME)}

    # -- block maps --------------------------------------------------------
    def _extents(self, d):
        """[(file block, fs block, count, unwritten)] sorted by file block, from
        an extents or B+tree data fork; None for a fork held inline. A record is
        two be64 words: bit 63 of the first the unwritten flag, then 54 bits of
        file offset, 52 of start block and 21 of length (xfs_bmbt_disk_get_all,
        xfs_bmap_btree.c:77). Each extent must lie within the largest file offset
        and, on the data device, inside one AG and clear of its headers
        (xfs_bmap_validate_extent_raw, xfs_bmap.c:6081); two extents may not map
        the same file block. One that fails is counted and raises."""
        fmt = d["format"]
        if fmt == XFS_FMT_EXTENTS:
            recs = [d["fork"][i * 16:i * 16 + 16] for i in range(d["nextents"])]
        elif fmt == XFS_FMT_BTREE:
            recs = self._bmbt_records(d)
        elif fmt == XFS_FMT_LOCAL:
            return None
        else:
            raise XfsUnreadable(f"data fork format {XFS_FMT_NAMES.get(fmt, fmt)} is not read")
        rt = d["flags"] & XFS_DIFLAG_REALTIME
        out = []
        for r in recs:
            l0, l1 = struct.unpack(">QQ", r)
            count = l1 & ((1 << 21) - 1)
            start = ((l0 & 0x1FF) << 43) | (l1 >> 21)
            off = (l0 & ((1 << 63) - 1)) >> 9
            if not count or off + count - 1 > XFS_MAX_FILEOFF or (not rt and not self._ext_ok(start, count)):
                what = f"inode {d['ino']}: extent of {count} blocks at block {start} for file block {off}"
                self._damaged(what + " lies outside its AG or the volume")
                raise XfsUnreadable(what + " lies outside its AG or the volume")
            out.append((off, start, count, bool(l0 >> 63)))
        out.sort()
        for a, b in zip(out, out[1:]):
            if a[0] + a[2] > b[0]:
                self._damaged(f"inode {d['ino']}: two extents map file block {b[0]}")
                raise XfsUnreadable(f"inode {d['ino']}: two extents map file block {b[0]}")
        return out

    def _bmbt_records(self, d):
        """The leaf records of a B+tree data fork, left to right. The root sits in
        the inode as a short header, keys, then pointers placed after room for as
        many keys as the fork holds (xfs_bmdr_maxrecs, xfs_bmap_btree.c:782);
        each block below has a long btree header (xfs_format.h:1940), and on v5
        its CRC, owner, block number and uuid must hold. No tree is taller than
        the volume allows (xfs_bmbt_verify, xfs_bmap_btree.c:423), and the walk
        keeps its own stack, so a forged deep chain cannot exhaust Python's."""
        ino = d["ino"]
        fork = d["fork"]
        level, numrecs = struct.unpack_from(">HH", fork, 0)
        maxrecs = (len(fork) - 4) // 16
        if not 0 < level < self.bm_maxlevels or not 0 < numrecs <= maxrecs:
            self._damaged(f"inode {ino}: an extent B+tree root of level {level} with {numrecs} records")
            raise XfsUnreadable(f"inode {ino}: B+tree root of level {level} with {numrecs} records, "
                                f"where the volume allows at most {self.bm_maxlevels} levels")
        hdr = self.bmbt_hdr
        magic = XFS_BMAP_CRC_MAGIC if self.v5 else XFS_BMAP_MAGIC
        mx = (self.bs - hdr) // 16                      # xfs_bmbt_maxrecs, xfs_bmap_btree.c:747
        out, seen = [], set()
        todo = [(struct.unpack_from(">Q", fork, 4 + maxrecs * 8 + i * 8)[0], level - 1)
                for i in reversed(range(numrecs))]

        def bad(fsb, why):
            self._damaged(f"inode {ino}: extent B+tree block {fsb} {why}")
            return XfsUnreadable(f"inode {ino}: extent B+tree block {fsb} {why}")

        while todo:
            fsb, want_level = todo.pop()
            if fsb in seen:
                raise bad(fsb, "is reached twice")
            seen.add(fsb)
            off = self._fsb_off(fsb)
            if off is None:
                raise bad(fsb, "is outside its AG or the volume")
            blk = self._meta(off, self.bs, f"inode {ino}: extent B+tree block {fsb}")
            if blk is None:
                raise XfsUnreadable(f"inode {ino}: extent B+tree block {fsb} is past the end")
            lvl, n = struct.unpack_from(">HH", blk, 4)
            if blk[:4] != magic or lvl != want_level:
                raise bad(fsb, "is not the B+tree block expected there")
            if self.v5:
                if not xfs_cksum_ok(blk, 64):
                    raise bad(fsb, "fails its CRC")
                blkno, = struct.unpack_from(">Q", blk, 24)
                owner, = struct.unpack_from(">Q", blk, 56)
                if blkno != (off - self.base) // 512 or owner != ino or blk[40:56] != self.meta_uuid:
                    raise bad(fsb, "names another block, inode or volume")
            if n > mx:
                raise bad(fsb, f"counts {n} records, more than fit")
            if lvl == 0:
                out.extend(blk[hdr + i * 16:hdr + i * 16 + 16] for i in range(n))
            else:
                todo.extend((struct.unpack_from(">Q", blk, hdr + mx * 8 + i * 8)[0], lvl - 1)
                            for i in reversed(range(n)))
        return out

    # -- file data ---------------------------------------------------------
    def read_file(self, ino, size):
        """Yield the file's bytes, exactly ``size`` of them. A hole, and an
        extent allocated but never written (the unwritten flag), read as zeros."""
        d = self.inode(ino)
        if d is None:
            raise XfsUnreadable(f"inode {ino} cannot be read")
        if d["flags"] & XFS_DIFLAG_REALTIME:
            raise XfsUnreadable("a realtime file: its blocks are on the realtime device, "
                                "which is not read")
        runs = self._extents(d)
        if runs is None:
            # xfs_dinode_verify_fork (xfs_inode_buf.c:369) allows no local regular file
            raise XfsUnreadable("a regular file whose data is in its inode, which XFS does not write")
        bs, left, pos = self.bs, size, 0                # pos is the next file block to deliver
        for lblk, pblk, count, unwritten in runs:
            if left <= 0:
                return
            if lblk > pos:
                gap = min((lblk - pos) * bs, left)
                for chunk in _xfs_zeros(gap):
                    yield chunk
                left -= gap
                pos = lblk
            if left <= 0:
                return
            if unwritten:
                n = min(count * bs, left)
                for chunk in _xfs_zeros(n):
                    yield chunk
                left -= n
                pos += count
                continue
            off = self._fsb_off(pblk)
            todo = count
            while todo and left > 0:
                n = min(todo, 256)                      # 1 MiB at 4 KiB blocks
                buf = self._data(off, n * bs)
                take = min(len(buf), left)
                yield buf[:take]
                left -= take
                off += n * bs
                todo -= n
                pos += n
        if left > 0:                                    # a trailing hole
            for chunk in _xfs_zeros(left):
                yield chunk

    def readlink(self, ino):
        """The symlink target. Inline in the inode when it fits, else in blocks of
        its own: the kernel maps only the blocks the target needs
        (xfs_symlink_blocks) and reads each mapped extent as one buffer, with a
        header on v5 whose CRC, offset, length, owner, uuid and block number must
        hold (xfs_symlink_remote_read, xfs_symlink_remote.c:236, and
        xfs_symlink_verify, 86)."""
        d = self.inode(ino)
        if d is None:
            raise XfsUnreadable(f"inode {ino} cannot be read")
        size = d["size"]
        if not 0 < size <= XFS_SYMLINK_MAXLEN:
            raise XfsUnreadable(f"symlink {ino} records a target of {size} bytes")
        if d["format"] == XFS_FMT_LOCAL:
            return bytes(d["fork"][:size]).decode("utf-8", "surrogateescape")
        hdr = XFS_SYMLINK_HDR if self.v5 else 0
        fsblocks = -(-size // (self.bs - hdr))           # xfs_symlink_blocks
        out, offset = bytearray(), 0
        for lblk, pblk, count, _unw in self._extents(d) or []:
            if lblk >= fsblocks or offset >= size:
                break
            count = min(count, fsblocks - lblk)
            off = self._fsb_off(pblk)
            buf = self._meta(off, count * self.bs, f"symlink {ino}: block {pblk}")
            if buf is None:
                raise XfsUnreadable(f"symlink {ino}: block {pblk} is past the end")
            take = min(len(buf) - hdr, size - offset)
            if self.v5:
                sl_off, sl_bytes = struct.unpack_from(">II", buf, 4)
                owner, blkno = struct.unpack_from(">QQ", buf, 32)
                if buf[:4] != XFS_SYMLINK_MAGIC or not xfs_cksum_ok(buf, 12) or \
                        (sl_off, sl_bytes, owner) != (offset, take, ino) or buf[16:32] != self.meta_uuid \
                        or blkno != (off - self.base) // 512:
                    self._damaged(f"symlink {ino}: its block fails its header or CRC check")
                    raise XfsUnreadable(f"symlink {ino}: its block fails its header or CRC check")
                buf = buf[hdr:]
            out += buf[:take]
            offset += take
        if offset != size:
            raise XfsUnreadable(f"symlink {ino}: {offset} of {size} target bytes found")
        return bytes(out).decode("utf-8", "surrogateescape")

    # -- directories -------------------------------------------------------
    def _dir_blocks(self, d, lo, hi):
        """[(directory block number, disk address, bytes)] for every whole
        directory block mapped between file blocks lo and hi. A directory block
        is dir_fsbcount filesystem blocks, which need not be contiguous on disk;
        its disk address (512-byte units, as v5 headers record it) is that of
        its first."""
        runs = self._extents(d) or []
        mapped = {}
        for lblk, pblk, count, unwritten in runs:
            if lblk + count <= lo or lblk >= hi or unwritten:
                continue
            for k in range(max(lblk, lo), min(lblk + count, hi)):
                mapped[k] = pblk + (k - lblk)
        out = []
        for db in sorted({k // self.dir_fsbcount for k in mapped}):
            parts = []
            for k in range(db * self.dir_fsbcount, (db + 1) * self.dir_fsbcount):
                off = self._fsb_off(mapped[k]) if k in mapped else None
                buf = self._meta(off, self.bs, f"directory {d['ino']}: block {db}") if off is not None else None
                if buf is None:
                    parts = None
                    break
                parts.append(buf)
            if parts is None:
                self._damaged(f"directory {d['ino']}: block {db} is not wholly mapped and readable")
                continue
            daddr = (self._fsb_off(mapped[db * self.dir_fsbcount]) - self.base) // 512
            out.append((db, daddr, b"".join(parts)))
        return out

    def _v3_header_ok(self, ino, db, daddr, buf, crc_off, blkno_at, uuid_at, owner_at, what):
        """The v5 header of a directory block: its CRC, its own disk address,
        the volume's uuid and the owning inode (xfs_dir3_data_verify,
        xfs_dir2_data.c:310, and xfs_dir3_data_header_check, 417;
        xfs_da3_blkinfo_verify, xfs_da_btree.c:194; the leaf and node header
        checks, xfs_dir2_leaf.c:210, xfs_da_btree.c:252)."""
        if not xfs_cksum_ok(buf, crc_off):
            self._damaged(f"directory {ino}: {what} {db} fails its CRC")
            return False
        blkno, = struct.unpack_from(">Q", buf, blkno_at)
        owner, = struct.unpack_from(">Q", buf, owner_at)
        if blkno != daddr or buf[uuid_at:uuid_at + 16] != self.meta_uuid or owner != ino:
            self._damaged(f"directory {ino}: {what} {db} records block {blkno} of inode {owner}, "
                          f"not block {daddr} of inode {ino} on this volume")
            return False
        return True

    def _dir_entries(self, ino):
        """[(name bytes, inode, ftype or None)] of a directory, "." and ".."
        left out, or None when it is not a readable directory."""
        d = self.inode(ino)
        if d is None or d["mode"] & S_IFMT != S_IFDIR:
            return None
        if d["format"] == XFS_FMT_LOCAL:
            return self._sf_entries(d)
        try:
            blocks = self._dir_blocks(d, 0, self.leafblk)
        except XfsUnreadable as exc:
            self._damaged(f"directory {ino}: {exc}")
            return []
        out = []
        for db, daddr, buf in blocks:
            out.extend(self._data_block_entries(ino, db, daddr, buf))
        return out

    def _sf_entries(self, d):
        """A shortform directory: a header with the entry count, whether inode
        numbers are 8 bytes, and the parent, then entries of name length, a
        2-byte offset, the name, the file type (ftype only) and the inode number
        (xfs_da_format.h:214, xfs_dir2_sf.c:41-140)."""
        fork, size = d["fork"], d["size"]
        if size > len(fork) or size < 6:
            self._damaged(f"directory {d['ino']}: shortform size {size} does not fit its fork")
            return []
        count, i8 = fork[0], fork[1]
        isz = 8 if i8 else 4
        parent = int.from_bytes(fork[2:2 + isz], "big") & XFS_MAXINUMBER
        wide = int(parent > 0xFFFFFFFF)                 # XFS_DIR2_MAX_SHORT_INUM
        pos = 2 + isz
        out = []
        for _ in range(count):
            if pos + 3 > size:
                break
            nl = fork[pos]
            name = bytes(fork[pos + 3:pos + 3 + nl])
            q = pos + 3 + nl
            ft = None
            if self.ftype:
                ft = fork[q] if q < size else None
                q += 1
            if q + isz > size or not nl:
                break
            child = int.from_bytes(fork[q:q + isz], "big") & XFS_MAXINUMBER
            wide += child > 0xFFFFFFFF
            out.append((name, child, ft))
            pos = q + isz
        # xfs_dir2_sf_verify (xfs_dir2_sf.c:698): the header's count of 8-byte
        # numbers must be the count of numbers that need 8 bytes, and the
        # entries must end exactly at the directory's size
        if wide != i8:
            self._damaged(f"directory {d['ino']}: its shortform header counts {i8} 8-byte inode "
                          f"numbers where {wide} need 8 bytes")
            return []
        if len(out) != count or pos != size:
            self._damaged(f"directory {d['ino']}: {len(out)} of {count} shortform entries read, "
                          f"ending at byte {pos} of {size}")
        return out

    def _data_block_entries(self, ino, db, daddr, buf):
        """The entries of one directory data block (single-block or multi-block
        form), walking entries and free regions the way __xfs_dir3_data_check
        does (xfs_dir2_data.c:96): a free region starts with tag 0xffff and its
        length; an entry is the inode number, name length, name, file type
        (ftype only) and a tag that must equal the entry's own offset, rounded
        up to 8 bytes (xfs_dir2_data_entsize, xfs_dir2_priv.h:200)."""
        kind = XFS_DIR_DATA_MAGICS.get(bytes(buf[:4]))
        if kind is None or (self.v5 != (buf[3:4] == b"3")):
            self._damaged(f"directory {ino}: block {db} is not a directory data block")
            return []
        if self.v5 and not self._v3_header_ok(ino, db, daddr, buf, 4, 8, 24, 40, "block"):
            return []
        end = len(buf)
        if kind == "block":                             # xfs_dir3_data_end_offset
            count, = struct.unpack_from(">I", buf, end - 8)
            end = end - 8 - count * 8
            if end < self.data_entry_offset:
                self._damaged(f"directory {ino}: block {db} counts {count} leaf entries")
                return []
        out, pos = [], self.data_entry_offset
        while pos + 8 <= end:
            if struct.unpack_from(">H", buf, pos)[0] == XFS_DIR2_DATA_FREE_TAG:
                length, = struct.unpack_from(">H", buf, pos + 2)
                if length < 8 or length % 8 or pos + length > end:
                    self._damaged(f"directory {ino}: block {db} has a bad free region at {pos}")
                    break
                pos += length
                continue
            child, = struct.unpack_from(">Q", buf, pos)
            nl = buf[pos + 8]
            size = (8 + 1 + nl + (1 if self.ftype else 0) + 2 + 7) & ~7
            if not nl or pos + size > end:
                self._damaged(f"directory {ino}: block {db} has a bad entry at {pos}")
                break
            if struct.unpack_from(">H", buf, pos + size - 2)[0] != pos:
                self._damaged(f"directory {ino}: block {db}: the entry at {pos} has a tag "
                              "that is not its own offset")
                break
            name = bytes(buf[pos + 9:pos + 9 + nl])
            ft = buf[pos + 9 + nl] if self.ftype else None
            if name not in (b".", b".."):
                out.append((name, child & XFS_MAXINUMBER, ft))
            pos += size
        return out

    def listdir(self, ino):
        ents = self._dir_entries(ino) or []
        return sorted((n.decode("utf-8", "surrogateescape"), c) for n, c, _ft in ents)

    def dir_report(self, ino):
        """How a directory is stored, for a check: its format named the way
        xfs_dir2_format decides it (xfs_dir2.c:264), its data fork format, the
        entries listed, and the live entries its own hash index counts ("." and
        ".." included), from the block tail or the leaf blocks; None for a
        shortform directory, which has no index. Leaf and node blocks are held
        to the same v5 header checks as data blocks."""
        d = self.inode(ino)
        if d is None or d["mode"] & S_IFMT != S_IFDIR:
            return None
        ents = self._dir_entries(ino) or []
        rep = dict(fork=XFS_FMT_NAMES.get(d["format"]), entries=len(ents), indexed=None)
        if d["format"] == XFS_FMT_LOCAL:
            rep["format"] = "shortform"
            return rep
        runs = self._extents(d) or []
        eof = max((lb + n for lb, _pb, n, _u in runs), default=0)
        rep["format"] = ("block" if eof == self.dir_fsbcount else
                         "leaf" if eof == self.leafblk + self.dir_fsbcount else "node")
        if rep["format"] == "block":
            blocks = self._dir_blocks(d, 0, self.dir_fsbcount)
            if blocks:
                count, stale = struct.unpack_from(">II", blocks[0][2], self.dir_blksize - 8)
                rep["indexed"] = count - stale
            return rep
        total = 0
        for db, daddr, buf in self._dir_blocks(d, self.leafblk, self.freeblk):
            magic, = struct.unpack_from(">H", buf, 8)
            if magic not in XFS_DIR_LEAF_MAGICS and magic not in XFS_DA_NODE_MAGICS:
                self._damaged(f"directory {ino}: block {db} is not a leaf or node block")
                return rep
            if self.v5 and not self._v3_header_ok(ino, db, daddr, buf, 12, 16, 32, 48,
                                                  "leaf or node block"):
                return rep
            if magic in XFS_DA_NODE_MAGICS:
                continue                                # a da node block: no entries
            at = 56 if self.v5 else 12                 # struct xfs_dir3_leaf_hdr / xfs_dir2_leaf_hdr
            count, stale = struct.unpack_from(">HH", buf, at)
            total += count - stale
        rep["indexed"] = total
        return rep

    # -- free space ----------------------------------------------------------
    def _bnobt_runs(self, agno, agbase, length, root, levels):
        """[(start block in the group, blocks)] from one group's bnobt, raising
        XfsUnreadable at the first block that fails its checks."""
        bs = self.bs
        hdr = 56 if self.v5 else 16                     # XFS_BTREE_SBLOCK_CRC_LEN / _LEN
        magic = XFS_ABTB_CRC_MAGIC if self.v5 else XFS_ABTB_MAGIC
        runs, seen = [], set()
        todo = [(root, levels - 1)]
        while todo:
            agbno, want = todo.pop()
            if agbno in seen or agbno >= length or len(seen) > 1 << 20:
                raise XfsUnreadable(f"AG {agno}: bnobt block {agbno} repeats or is out of range")
            seen.add(agbno)
            blk = read_at(self.fh, agbase + agbno * bs, bs)
            if len(blk) < bs or blk[:4] != magic:
                raise XfsUnreadable(f"AG {agno}: bnobt block {agbno} is not one")
            lvl, n = struct.unpack_from(">HH", blk, 4)
            if lvl != want:
                raise XfsUnreadable(f"AG {agno}: bnobt block {agbno} is at the wrong level")
            if self.v5:
                blkno, = struct.unpack_from(">Q", blk, 16)
                owner, = struct.unpack_from(">I", blk, 48)
                if not xfs_cksum_ok(blk, 52) or owner != agno or blk[32:48] != self.meta_uuid \
                        or blkno != (agbase + agbno * bs - self.base) // 512:
                    raise XfsUnreadable(f"AG {agno}: bnobt block {agbno} fails its checks")
            if lvl == 0:
                for i in range(min(n, (bs - hdr) // 8)):
                    runs.append(struct.unpack_from(">II", blk, hdr + i * 8))
                continue
            mx = (bs - hdr) // 12                       # xfs_allocbt_maxrecs, xfs_alloc_btree.c:563
            for i in range(min(n, mx)):
                todo.append((struct.unpack_from(">I", blk, hdr + mx * 8 + i * 4)[0], lvl - 1))
        return runs

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] for the runs of space the volume says are free.

        Each allocation group's AGF (one sector after its superblock,
        XFS_AGF_DADDR, xfs_format.h:610) roots a B+tree of free extents by block
        number (the bnobt), whose leaf records are a start block in the group and
        a length (struct xfs_alloc_rec, xfs_format.h:1543) under a short btree
        header (xfs_format.h:1928). The blocks held on the AGFL for the btrees'
        own growth are not in it, and are not reported.

        Nothing is reported unless every group's AGF and every bnobt block passes
        its checks (magic, level, and on v5 the CRC, block number, owner and
        uuid) and the free blocks the tree records add up to the AGF's own
        agf_freeblks, the same comparison xfs_repair makes (repair/scan.c:3173).

        Offsets are into the image rather than the volume, so a caller reading
        the whole disk can use them directly. ``min_bytes`` drops runs too short
        to hold anything worth recovering.
        """
        bs, out = self.bs, []
        for agno in range(self.agcount):
            agbase = self.base + agno * self.agblocks * bs
            agf = read_at(self.fh, agbase + self.sectsize, self.sectsize)
            if len(agf) < self.sectsize or agf[:4] != XFS_AGF_MAGIC:
                return []
            version, seqno, length, root = struct.unpack_from(">IIII", agf, 4)
            level, = struct.unpack_from(">I", agf, 28)
            freeblks, = struct.unpack_from(">I", agf, 52)
            if version != 1 or seqno != agno or (self.v5 and not xfs_cksum_ok(agf, 216)):
                return []
            try:
                runs = self._bnobt_runs(agno, agbase, length, root, level)
            except XfsUnreadable:
                return []
            if sum(n for _s, n in runs) != freeblks:
                return []
            out.extend((agbase + s * bs, n * bs) for s, n in sorted(runs) if n * bs >= min_bytes)
        return out


# ---------------------------------------------------------------------------
# Btrfs
#
# Btrfs is read here directly, no mounting, from its on-disk format as
# btrfs-progs defines it at v6.17.1 (commit
# 06981428c08f78f019a2f4956407fd84b495e21e, https://github.com/kdave/btrfs-progs),
# with the kernel's own fs/btrfs at v7.0 (commit
# 028ef9c96e96197026887c0f092424679298aae8) where only the kernel settles a
# rule. Line numbers below are at those commits. No code was copied; qnxprobe
# is MIT and both are GPL.
#
#   superblock at 64 KiB, 4 KiB long          kernel-shared/ctree.h:72-73
#   mirrors at 16 KiB << (12 * n), n = 1, 2   kernel-shared/disk-io.h:35-36,148-156
#   struct btrfs_super_block, BTRFS_MAGIC     kernel-shared/uapi/btrfs_tree.h:668-726, 14
#   checksum types and sizes                  btrfs_tree.h:381-384, kernel-shared/ctree.c:49-55
#   crc32c stored as ~crc, little endian;     crypto/hash.c:32-40, 42-50
#     xxhash64 with seed 0, little endian
#   sha256; blake2b with a 32-byte digest     crypto/hash.c:64-81, crypto/hash.h:23
#   a block's checksum covers its bytes from  kernel-shared/disk-io.c:186-216, 1785
#     32 to the end; the superblock's 32..4096
#   struct btrfs_header, item, key_ptr        btrfs_tree.h:482-497, 549-580
#   a leaf's item offsets count from the end  btrfs_tree.h:549-567
#     of the header
#   a child's generation must equal the one   kernel-shared/disk-io.c:275 (verify_parent_transid)
#     its parent's pointer records
#   sys_chunk_array: key then chunk, repeated kernel-shared/volumes.c:2577-2666
#   struct btrfs_chunk, btrfs_stripe          btrfs_tree.h:629-663
#   logical to physical, every profile        kernel-shared/volumes.c:2093-2313
#   block group profile bits                  btrfs_tree.h:1154-1185
#   object ids and item types                 btrfs_tree.h:38-132, 141-282
#   struct btrfs_root_item, root_ref          btrfs_tree.h:921-982
#   struct btrfs_inode_item, timespec         btrfs_tree.h:867-899
#   struct btrfs_inode_ref, inode_extref      btrfs_tree.h:853-865
#   struct btrfs_dir_item (several share an   btrfs_tree.h:905-911, kernel-shared/ctree.h:901
#     item when their crc32c name hashes collide)
#   file extent types and item; inline data   btrfs_tree.h:1063-1119
#     starts at disk_bytenr
#   compression types                         kernel-shared/compression.h:108-111
#   incompat and compat_ro feature bits       kernel-shared/uapi/btrfs.h:322-362
#   reading a file's extents                  cmds/restore.c:292-471, 617-760
#   LZO framing: total length, then segments  linux fs/btrfs/lzo.c:24-59, 429-546
#     of one sector, none crossing a sector
#   zlib: a stream with or without header     linux fs/btrfs/zlib.c:351-384
#   a subvolume is entered only through a     linux fs/btrfs/inode.c:5811-5875, 6096-6102
#     matching ROOT_REF; otherwise an empty
#     directory stands in its place
#   readdir walks DIR_INDEX items             linux fs/btrfs/inode.c:6304-6349
#
# What is read: one device's superblock (the primary when it holds, as a
# normal open reads only the primary; otherwise the copy SBREAD_RECOVER would
# take, disk-io.c:1933-2017: see _btrfs_pick_super), the chunk tree, the root
# tree, and every file tree reachable from the top-level subvolume (id 5):
# subvolumes and snapshots are directories in it, as the kernel and "btrfs
# restore -s" present them. Inline, regular and preallocated extents, holes
# both explicit and implied (NO_HOLES), and zlib, LZO and zstd extents are
# read; zstd needs Python 3.14 (compression.zstd). Every tree block's
# checksum, address, filesystem id and structure are checked, and on every
# read the level, generation and first key its parent records; a DUP copy is
# tried when the first fails. Items are held to the kernel's tree checker
# (linux fs/btrfs/tree-checker.c) where a wrong one would misread a file.
#
# What is refused, each by name: RAID0, RAID10, RAID5 and RAID6 chunks (their
# data is striped across devices, so one image does not hold it); a chunk with
# no copy on this device; an extent whose encryption or other_encoding field is
# set (btrfs_tree.h:1084-1088: a reader that does not understand them treats
# them as incompatible); extent tree v2. A log tree is not replayed: the volume
# is read as of its last committed transaction, and the note says a log tree
# is present.
# ---------------------------------------------------------------------------
BTRFS_SUPER_OFF = 0x10000
BTRFS_SUPER_SIZE = 4096
BTRFS_SUPER_MIRRORS = (0x10000, 0x4000 << 12, 0x4000 << 24)
BTRFS_MAGIC = b"_BHRfS_M"
BTRFS_CSUM_NAMES = {0: "crc32c", 1: "xxhash64", 2: "sha256", 3: "blake2b"}
BTRFS_CSUM_SIZES = {0: 4, 1: 8, 2: 32, 3: 32}
BTRFS_HEADER_SIZE = 101                 # struct btrfs_header, packed
BTRFS_ITEM_SIZE = 25                    # btrfs_disk_key (17) + offset + size
BTRFS_KEY_PTR_SIZE = 33                 # btrfs_disk_key + blockptr + generation
BTRFS_MAX_LEVEL = 8                     # kernel-shared/ctree.h BTRFS_MAX_LEVEL
BTRFS_RESERVED_1M = 1 << 20             # kernel-shared/ctree.h:200
BTRFS_STRIPE_LEN = 64 << 10             # kernel-shared/volumes.h BTRFS_STRIPE_LEN
# object ids
BTRFS_ROOT_TREE_OBJECTID, BTRFS_EXTENT_TREE_OBJECTID = 1, 2
BTRFS_CHUNK_TREE_OBJECTID, BTRFS_DEV_TREE_OBJECTID = 3, 4
BTRFS_FS_TREE_OBJECTID, BTRFS_ROOT_TREE_DIR_OBJECTID = 5, 6
BTRFS_FREE_SPACE_TREE_OBJECTID, BTRFS_BLOCK_GROUP_TREE_OBJECTID = 10, 11
BTRFS_FIRST_FREE_OBJECTID = 256
BTRFS_LAST_FREE_OBJECTID = (1 << 64) - 256
BTRFS_FIRST_CHUNK_TREE_OBJECTID = 256
BTRFS_EMPTY_SUBVOL_DIR_OBJECTID = 2
# item types
BTRFS_INODE_ITEM_KEY, BTRFS_INODE_REF_KEY, BTRFS_INODE_EXTREF_KEY = 1, 12, 13
BTRFS_XATTR_ITEM_KEY, BTRFS_ORPHAN_ITEM_KEY = 24, 48
BTRFS_DIR_ITEM_KEY, BTRFS_DIR_INDEX_KEY, BTRFS_EXTENT_DATA_KEY = 84, 96, 108
BTRFS_ROOT_ITEM_KEY, BTRFS_ROOT_BACKREF_KEY, BTRFS_ROOT_REF_KEY = 132, 144, 156
BTRFS_EXTENT_ITEM_KEY, BTRFS_METADATA_ITEM_KEY = 168, 169
BTRFS_BLOCK_GROUP_ITEM_KEY = 192
BTRFS_FREE_SPACE_INFO_KEY, BTRFS_FREE_SPACE_EXTENT_KEY = 198, 199
BTRFS_FREE_SPACE_BITMAP_KEY = 200
BTRFS_DEV_EXTENT_KEY, BTRFS_DEV_ITEM_KEY, BTRFS_CHUNK_ITEM_KEY = 204, 216, 228
# block group (chunk) type and profile bits
BTRFS_BG_DATA, BTRFS_BG_SYSTEM, BTRFS_BG_METADATA = 1 << 0, 1 << 1, 1 << 2
BTRFS_BG_PROFILES = ((1 << 3, "RAID0"), (1 << 4, "RAID1"), (1 << 5, "DUP"),
                     (1 << 6, "RAID10"), (1 << 7, "RAID5"), (1 << 8, "RAID6"),
                     (1 << 9, "RAID1C3"), (1 << 10, "RAID1C4"))
BTRFS_BG_MIRRORED = (1 << 4) | (1 << 5) | (1 << 9) | (1 << 10)    # RAID1, DUP, RAID1C3/4
BTRFS_BG_STRIPED = (1 << 3) | (1 << 6) | (1 << 7) | (1 << 8)      # RAID0, RAID10, RAID5/6
# feature bits (kernel-shared/uapi/btrfs.h)
BTRFS_INCOMPAT_NAMES = ((0, "mixed_backref"), (1, "default_subvol"), (2, "mixed_groups"),
                        (3, "compress_lzo"), (4, "compress_zstd"), (5, "big_metadata"),
                        (6, "extended_iref"), (7, "raid56"), (8, "skinny_metadata"),
                        (9, "no_holes"), (10, "metadata_uuid"), (11, "raid1c34"),
                        (12, "zoned"), (13, "extent_tree_v2"), (14, "raid_stripe_tree"),
                        (16, "simple_quota"))
BTRFS_INCOMPAT_METADATA_UUID = 1 << 10
BTRFS_INCOMPAT_EXTENT_TREE_V2 = 1 << 13
BTRFS_INCOMPAT_RAID_STRIPE_TREE = 1 << 14
BTRFS_INCOMPAT_COMPRESS_ZSTD = 1 << 4
BTRFS_COMPAT_RO_BLOCK_GROUP_TREE = 1 << 3
# file extents
BTRFS_FILE_EXTENT_INLINE, BTRFS_FILE_EXTENT_REG, BTRFS_FILE_EXTENT_PREALLOC = 0, 1, 2
BTRFS_FILE_EXTENT_INLINE_DATA_START = 21    # offsetof(btrfs_file_extent_item, disk_bytenr)
BTRFS_COMPRESS = {0: "none", 1: "zlib", 2: "lzo", 3: "zstd"}
BTRFS_ROOT_SUBVOL_RDONLY = 1 << 0
_BTRFS_KEY_MAX = ((1 << 64) - 1, 255, (1 << 64) - 1)
# linux fs/btrfs/compression.h:34-40
BTRFS_MAX_COMPRESSED = BTRFS_MAX_UNCOMPRESSED = 128 << 10
# the largest i_size: sb->s_maxbytes = MAX_LFS_FILESIZE (linux fs/btrfs/super.c:963),
# LLONG_MAX on a 64-bit kernel
BTRFS_MAX_FILE_SIZE = (1 << 63) - 1
# item sizes the kernel's tree checker requires (linux fs/btrfs/tree-checker.c)
BTRFS_INODE_ITEM_SIZE = 160                 # check_inode_item, 1141-1145
BTRFS_FILE_EXTENT_ITEM_SIZE = 53            # check_extent_data_item, 296-302
BTRFS_DEV_EXTENT_SIZE = 48                  # struct btrfs_dev_extent, btrfs_tree.h:845-851
BTRFS_ROOT_ITEM_LEGACY_SIZE = 239           # btrfs_legacy_root_item_size, btrfs_tree.h:970-973
# directory entry types to file type bits, btrfs_tree.h:395-402
BTRFS_FT_MODE = {1: 0o100000, 2: 0o040000, 3: 0o020000, 4: 0o060000, 5: 0o010000,
                 6: 0o140000, 7: 0o120000}

_BTRFS_CRC32C_TABLE = None


def btrfs_crc32c(data, crc=0xFFFFFFFF):
    """The CRC-32C (Castagnoli, reflected polynomial 0x82F63B78) register after
    ``data``, starting from ``crc``, with no final inversion: crypto/crc32c.c
    (the polynomial at line 34, the table walk at line 204). btrfs stores the
    inverted value (crypto/hash.c:32-40) and hashes names from a seed of ~1
    (kernel-shared/ctree.h:901-903)."""
    global _BTRFS_CRC32C_TABLE                            # pylint: disable=global-statement
    if _BTRFS_CRC32C_TABLE is None:
        table = []
        for i in range(256):
            c = i
            for _ in range(8):
                c = (c >> 1) ^ 0x82F63B78 if c & 1 else c >> 1
            table.append(c)
        _BTRFS_CRC32C_TABLE = table
    t = _BTRFS_CRC32C_TABLE
    for b in data:
        crc = t[(crc ^ b) & 0xFF] ^ (crc >> 8)
    return crc


_XXH_P1, _XXH_P2 = 0x9E3779B185EBCA87, 0xC2B2AE3D27D4EB4F
_XXH_P3, _XXH_P4, _XXH_P5 = 0x165667B19E3779F9, 0x85EBCA77C2B2AE63, 0x27D4EB2F165667C5
_M64 = (1 << 64) - 1


def _xxh_rotl(x, r):
    return ((x << r) | (x >> (64 - r))) & _M64


def _xxh_round(acc, lane):
    acc = (acc + lane * _XXH_P2) & _M64
    return (_xxh_rotl(acc, 31) * _XXH_P1) & _M64


def btrfs_xxh64(data, seed=0):
    """XXH64 of ``data``, as crypto/xxhash.h defines it: the primes at lines
    1238-1242, XXH64_round and XXH64_mergeRound at 1252-1266, the avalanche at
    1268-1276, the tail at 1296-1338 and the four-lane body at 1340-1373."""
    data = bytes(data)
    n, i = len(data), 0
    if n >= 32:
        v1 = (seed + _XXH_P1 + _XXH_P2) & _M64
        v2 = (seed + _XXH_P2) & _M64
        v3 = seed & _M64
        v4 = (seed - _XXH_P1) & _M64
        lanes = struct.unpack_from(f"<{(n // 32) * 4}Q", data)
        for j in range(0, len(lanes), 4):
            v1 = _xxh_round(v1, lanes[j])
            v2 = _xxh_round(v2, lanes[j + 1])
            v3 = _xxh_round(v3, lanes[j + 2])
            v4 = _xxh_round(v4, lanes[j + 3])
        i = (n // 32) * 32
        h = (_xxh_rotl(v1, 1) + _xxh_rotl(v2, 7) + _xxh_rotl(v3, 12) + _xxh_rotl(v4, 18)) & _M64
        for v in (v1, v2, v3, v4):
            h ^= _xxh_round(0, v)
            h = (h * _XXH_P1 + _XXH_P4) & _M64
    else:
        h = (seed + _XXH_P5) & _M64
    h = (h + n) & _M64
    while i + 8 <= n:
        h ^= _xxh_round(0, struct.unpack_from("<Q", data, i)[0])
        h = (_xxh_rotl(h, 27) * _XXH_P1 + _XXH_P4) & _M64
        i += 8
    if i + 4 <= n:
        h ^= (struct.unpack_from("<I", data, i)[0] * _XXH_P1) & _M64
        h = (_xxh_rotl(h, 23) * _XXH_P2 + _XXH_P3) & _M64
        i += 4
    while i < n:
        h ^= (data[i] * _XXH_P5) & _M64
        h = (_xxh_rotl(h, 11) * _XXH_P1) & _M64
        i += 1
    h ^= h >> 33
    h = (h * _XXH_P2) & _M64
    h ^= h >> 29
    h = (h * _XXH_P3) & _M64
    h ^= h >> 32
    return h


def btrfs_csum(csum_type, data):
    """The checksum btrfs stores for ``data``, as many bytes as the type keeps
    (btrfs_csum_data, kernel-shared/disk-io.c:165-184), or None for a type this
    does not know."""
    if csum_type == 0:
        return struct.pack("<I", btrfs_crc32c(data) ^ 0xFFFFFFFF)
    if csum_type == 1:
        return struct.pack("<Q", btrfs_xxh64(data))
    if csum_type == 2:
        import hashlib                              # pylint: disable=import-outside-toplevel
        return hashlib.sha256(data).digest()
    if csum_type == 3:
        import hashlib                              # pylint: disable=import-outside-toplevel
        return hashlib.blake2b(data, digest_size=32).digest()
    return None


def _btrfs_uuid(b):
    h = bytes(b).hex()
    return f"{h[:8]}-{h[8:12]}-{h[12:16]}-{h[16:20]}-{h[20:]}"


def _btrfs_super(buf, at):
    """The fields of a superblock read at byte ``at`` of its device, with
    ``csum_ok`` saying whether its checksum holds, or None when the magic is not
    there. Offsets are those of struct btrfs_super_block (btrfs_tree.h:668-726)."""
    if len(buf) < BTRFS_SUPER_SIZE or buf[64:72] != BTRFS_MAGIC:
        return None
    (bytenr, flags, _magic, generation, root, chunk_root, log_root, _unused, total_bytes,
     bytes_used, root_dir, num_devices, sectorsize, nodesize, _leafsize, stripesize,
     sys_size, chunk_gen, compat, compat_ro, incompat, csum_type, root_level,
     chunk_level, log_level) = struct.unpack_from("<QQ8sQQQQQQQQQIIIIIQQQQHBBB", buf, 48)
    devid, dev_total, dev_used = struct.unpack_from("<QQQ", buf, 201)
    label = buf[299:299 + 256].split(b"\x00")[0].decode("utf-8", "replace")
    csum = btrfs_csum(csum_type, buf[32:BTRFS_SUPER_SIZE])
    size = BTRFS_CSUM_SIZES.get(csum_type, 0)
    return dict(
        at=at, bytenr=bytenr, flags=flags, generation=generation, root=root,
        chunk_root=chunk_root, log_root=log_root, total_bytes=total_bytes,
        bytes_used=bytes_used, root_dir=root_dir, num_devices=num_devices,
        sectorsize=sectorsize, nodesize=nodesize, stripesize=stripesize,
        sys_array=bytes(buf[811:811 + min(sys_size, 2048)]), sys_size=sys_size,
        chunk_generation=chunk_gen, compat=compat, compat_ro=compat_ro, incompat=incompat,
        csum_type=csum_type, root_level=root_level, chunk_level=chunk_level,
        log_level=log_level, devid=devid, dev_total=dev_total, dev_used=dev_used,
        dev_uuid=bytes(buf[267:283]), fsid=bytes(buf[32:48]),
        metadata_uuid=bytes(buf[571:587]), label=label,
        csum_ok=csum is not None and csum == bytes(buf[:size]))


def _btrfs_super_sane(sb):
    """Why a superblock whose checksum holds still cannot be used, or None. The
    limits are the ones btrfs_check_super applies (kernel-shared/disk-io.c)."""
    def pow2(v):
        return v > 0 and v & (v - 1) == 0
    if sb["csum_type"] not in BTRFS_CSUM_NAMES:
        return f"checksum type {sb['csum_type']} is not one btrfs defines"
    if not (pow2(sb["sectorsize"]) and 4096 <= sb["sectorsize"] <= 65536):
        return f"sector size {sb['sectorsize']} is out of range"
    if not (pow2(sb["nodesize"]) and sb["sectorsize"] <= sb["nodesize"] <= 65536):
        return f"node size {sb['nodesize']} is out of range"
    if sb["sys_size"] > 2048:
        return f"sys_chunk_array_size {sb['sys_size']} is over 2048"
    if sb["bytenr"] != sb["at"]:
        return f"it records its own place as {sb['bytenr']:#x}, not {sb['at']:#x}"
    return None


def _btrfs_pick_super(fh, base):
    """(superblock, [(byte offset, generation, csum_ok)], why) for a device at
    ``base``; the superblock is None when no copy can be used, and ``why``
    says so.

    The primary copy at 64 KiB must carry the magic: "btrfs only recognizes
    disks with a valid 0x1 0000 superblock" (Documentation/dev/
    On-disk-format.rst:78-79), so a device without it is not Btrfs and its
    mirrors are not looked at. A primary whose checksum holds and which passes
    the sanity checks is used, as a normal open reads only the primary
    (disk-io.c:1942, max_super is 1 without SBREAD_RECOVER). Otherwise every
    copy is tried as SBREAD_RECOVER does (disk-io.c:1974-2014): a copy is
    skipped when its checksum or its checks fail, the first good copy sets the
    fsid every later one must carry, and the good copy with the highest
    generation is taken."""
    found = []
    primary = _btrfs_super(read_at(fh, base + BTRFS_SUPER_OFF, BTRFS_SUPER_SIZE),
                           BTRFS_SUPER_OFF)
    if primary is None:
        return None, found, "no Btrfs magic in the superblock at 64 KiB"
    found.append((BTRFS_SUPER_OFF, primary["generation"], primary["csum_ok"]))
    if primary["csum_ok"] and not _btrfs_super_sane(primary):
        return primary, found, None
    best, fsid = None, None
    for at in BTRFS_SUPER_MIRRORS:
        sb = primary if at == BTRFS_SUPER_OFF else \
            _btrfs_super(read_at(fh, base + at, BTRFS_SUPER_SIZE), at)
        if sb is None:
            continue
        if at != BTRFS_SUPER_OFF:
            found.append((at, sb["generation"], sb["csum_ok"]))
        if not sb["csum_ok"] or _btrfs_super_sane(sb):
            continue
        if fsid is None:
            fsid = sb["fsid"]
        elif sb["fsid"] != fsid:
            continue
        if best is None or sb["generation"] > best["generation"]:   # pylint: disable=unsubscriptable-object
            best = sb
    if best is None:
        why = ("its superblock checksum does not hold" if not primary["csum_ok"]
               else _btrfs_super_sane(primary))
        return None, found, f"{why}, and no mirror copy holds either"
    return best, found, None


class BtrfsUnreadable(Exception):
    """A Btrfs structure or file this reader cannot hand back whole; the message says why."""


def _btrfs_check_block(buf, nodesize, sectorsize):
    """Why a tree block's own structure is wrong, or None: the checks the
    kernel's tree checker makes before any item is used (linux
    fs/btrfs/tree-checker.c, __btrfs_check_leaf 2018-2166 and
    __btrfs_check_node 2179-2234). A leaf's keys rise strictly, its items'
    data is packed from the end of the block with no gap or overlap, and no
    item's data overlaps the item headers; a node holds 1 to the most
    pointers that fit, its keys rise strictly, and no pointer is 0 or off a
    sector boundary."""
    nritems = struct.unpack_from("<I", buf, 96)[0]
    level = buf[100]
    if level >= BTRFS_MAX_LEVEL:
        return f"level {level} is not below {BTRFS_MAX_LEVEL}"
    if level == 0:
        if BTRFS_HEADER_SIZE + nritems * BTRFS_ITEM_SIZE > nodesize:
            return f"a leaf claims {nritems:,} items, more than fit"
        data_size = nodesize - BTRFS_HEADER_SIZE
        prev, expect_end = (0, 0, 0), data_size
        for i in range(nritems):
            o = BTRFS_HEADER_SIZE + i * BTRFS_ITEM_SIZE
            key = _btrfs_key(buf, o)
            if key <= prev:
                return f"item {i} key {key} does not follow {prev}"
            ioff, isz = struct.unpack_from("<II", buf, o + 17)
            if ioff + isz != expect_end or ioff + isz > data_size:
                return f"item {i} ends at {ioff + isz}, not {expect_end}"
            if BTRFS_HEADER_SIZE + ioff < o + BTRFS_ITEM_SIZE:
                return f"item {i} data overlaps the item headers"
            prev, expect_end = key, ioff
        return None
    most = (nodesize - BTRFS_HEADER_SIZE) // BTRFS_KEY_PTR_SIZE
    if not 1 <= nritems <= most:
        return f"a node claims {nritems:,} pointers, not 1 to {most}"
    prev = None
    for i in range(nritems):
        o = BTRFS_HEADER_SIZE + i * BTRFS_KEY_PTR_SIZE
        key = _btrfs_key(buf, o)
        ptr = struct.unpack_from("<Q", buf, o + 17)[0]
        if prev is not None and key <= prev:
            return f"pointer {i} key {key} does not follow {prev}"
        if not ptr or ptr % sectorsize:
            return f"pointer {i} is {ptr:#x}, 0 or off a sector boundary"
        prev = key
    return None


def _btrfs_key(buf, off):
    return struct.unpack_from("<QBQ", buf, off)


def _btrfs_profile(chunk_type):
    names = [n for bit, n in BTRFS_BG_PROFILES if chunk_type & bit]
    return "/".join(names) if names else "single"


def _btrfs_decompress(comp, data, ram_bytes, sectorsize):
    """The bytes a compressed extent (or compressed inline data) holds.

    zlib: a zlib stream, or, when its first two bytes are a zlib header, the
    raw deflate after them, its adler32 not checked: fs/btrfs/zlib.c:351-384.
    LZO: a le32 total length, then segments of a le32 length and an LZO1X
    stream of at most one sector, a segment header never crossing a sector
    boundary (up to 3 padding bytes skipped): fs/btrfs/lzo.c:24-59, 429-546.
    zstd: one zstd frame; anything past it (the rest of the last sector) is not
    read: fs/btrfs/zstd.c.

    The kernel never makes a compressed extent that holds more than 128 KiB,
    stored or decompressed (BTRFS_MAX_COMPRESSED and BTRFS_MAX_UNCOMPRESSED,
    linux fs/btrfs/compression.h:34-40; inode.c:9934-9935 refuses an encoded
    write past them), so a ``ram_bytes`` or a stored length outside 1 byte to
    128 KiB is refused before anything is decompressed. That also bounds what
    a damaged stream can make this decompress."""
    if not 0 < ram_bytes <= BTRFS_MAX_UNCOMPRESSED:
        raise DecompressError(f"ram_bytes {ram_bytes:,} is outside the 1 to "
                              f"{BTRFS_MAX_UNCOMPRESSED:,} a compressed extent holds")
    if not 0 < len(data) <= BTRFS_MAX_COMPRESSED:
        raise DecompressError(f"{len(data):,} stored bytes is outside the 1 to "
                              f"{BTRFS_MAX_COMPRESSED:,} a compressed extent holds")
    if comp == 1:
        import zlib                                 # pylint: disable=import-outside-toplevel
        d = data
        if (len(d) > 2 and not d[1] & 0x20 and (d[0] & 0x0F) == 8
                and ((d[0] << 8) + d[1]) % 31 == 0):
            z = zlib.decompressobj(-((d[0] >> 4) + 8))
            d = d[2:]
        else:
            z = zlib.decompressobj()
        try:
            out = z.decompress(d, ram_bytes)
        except zlib.error as exc:
            raise DecompressError(f"zlib: {exc}") from None
        return out
    if comp == 2:
        if len(data) < 4:
            raise DecompressError("LZO extent shorter than its header")
        total = struct.unpack_from("<I", data, 0)[0]
        if total > len(data) or total < 4:
            raise DecompressError(f"LZO header records {total:,} bytes, the extent holds "
                                  f"{len(data):,}")
        out, pos = bytearray(), 4
        while pos < total and len(out) < ram_bytes:
            if pos + 4 > total:
                raise DecompressError("LZO segment header past the recorded length")
            seg = struct.unpack_from("<I", data, pos)[0]
            pos += 4
            if seg == 0 or pos + seg > total:
                raise DecompressError(f"LZO segment of {seg:,} bytes does not fit the extent")
            out += lzo1x_decompress(data[pos:pos + seg], limit=sectorsize)
            pos += seg
            left = sectorsize - pos % sectorsize
            if left < 4:
                pos += left
        return bytes(out)
    if comp == 3:
        z = _zstd_module()
        if z is None:
            raise DecompressError("zstd needs Python 3.14 or later (compression.zstd); "
                                  "this Python does not carry it")
        try:
            dec = z.ZstdDecompressor()
            return dec.decompress(bytes(data), ram_bytes)
        except Exception as exc:                    # ZstdError, not a stable name
            raise DecompressError(f"zstd: {exc}") from None
    raise DecompressError(f"compression type {comp} is not one btrfs defines")


def btrfs_extent_bytes(extents, isize, read_logical, sectorsize, cap=None):
    """Yield a file's bytes from its parsed extent items, ``isize`` of them at
    most (``cap`` lowers that), zeros wherever no extent covers a range.

    ``extents`` is [(file offset, extent dict)] in key order, each dict as
    BtrfsWalker._extent() parses an EXTENT_DATA item. A range no item covers is
    a hole (NO_HOLES drops hole items, btrfs.h:356); so is a REG extent with
    disk_bytenr 0 (restore.c:376-378). A PREALLOC extent reads as zeros, as
    restore.c:721 skips it. An uncompressed extent's bytes start ``offset``
    into the disk extent; a compressed one is decompressed whole and then
    ``offset`` into the result (restore.c:350-471). Inline data starts the file
    and is ram_bytes long (restore.c:292-348).

    ``read_logical(addr, n)`` returns n bytes at a logical address. Kept apart
    from the walker so the self-test can drive it with extents no fixture
    writes."""
    limit = isize if cap is None else min(isize, cap)
    pos = 0

    def zeros(n):
        while n > 0:
            piece = min(n, 1 << 20)
            yield bytes(piece)
            n -= piece

    for off, ext in extents:
        if pos >= limit:
            return
        if off > pos:                                   # a hole up to this extent
            for z in zeros(min(off, limit) - pos):
                yield z
            pos = min(off, limit)
            if pos >= limit:
                return
        if ext["encryption"] or ext["other_encoding"]:
            raise BtrfsUnreadable(f"extent at file offset {off:,} is encrypted or encoded "
                                  f"(encryption {ext['encryption']}, other_encoding "
                                  f"{ext['other_encoding']}), which this does not read")
        if ext["type"] == BTRFS_FILE_EXTENT_INLINE:
            data = ext["inline"]
            if ext["compression"]:
                try:
                    data = _btrfs_decompress(ext["compression"], data, ext["ram_bytes"],
                                             sectorsize)
                except DecompressError as exc:
                    raise BtrfsUnreadable(f"inline extent: {exc}") from None
            data = data[:ext["ram_bytes"]]
            length = len(data)
        elif ext["type"] in (BTRFS_FILE_EXTENT_REG, BTRFS_FILE_EXTENT_PREALLOC):
            length = ext["num_bytes"]
            data = None
        else:
            raise BtrfsUnreadable(f"extent at file offset {off:,} has type {ext['type']}, "
                                  "which btrfs does not define")
        end = off + length
        if end <= pos:                                  # wholly behind what was given
            continue
        skip = pos - off                                # an overlap, never expected
        want = min(end, limit) - pos
        if data is not None:
            yield data[skip:skip + want]
        elif ext["type"] == BTRFS_FILE_EXTENT_PREALLOC or ext["disk_bytenr"] == 0:
            for z in zeros(want):
                yield z
        elif ext["compression"] == 0:
            at = ext["disk_bytenr"] + ext["offset"] + skip
            left = want
            while left > 0:
                n = min(left, 1 << 20)
                chunk = read_logical(at, n)
                if len(chunk) < n:
                    raise BtrfsUnreadable(f"extent at logical {at:#x} reads {len(chunk):,} "
                                          f"of {n:,} bytes")
                yield chunk
                at += n
                left -= n
        else:
            if not 0 < ext["disk_num_bytes"] <= BTRFS_MAX_COMPRESSED:
                raise BtrfsUnreadable(
                    f"compressed extent at logical {ext['disk_bytenr']:#x} records "
                    f"{ext['disk_num_bytes']:,} stored bytes, outside the 1 to "
                    f"{BTRFS_MAX_COMPRESSED:,} a compressed extent holds")
            raw = read_logical(ext["disk_bytenr"], ext["disk_num_bytes"])
            try:
                full = _btrfs_decompress(ext["compression"], raw, ext["ram_bytes"],
                                         sectorsize)
            except DecompressError as exc:
                raise BtrfsUnreadable(f"extent at logical {ext['disk_bytenr']:#x}: "
                                      f"{exc}") from None
            piece = full[ext["offset"] + skip:ext["offset"] + skip + want]
            if len(piece) < want:
                raise BtrfsUnreadable(
                    f"compressed extent at logical {ext['disk_bytenr']:#x} gives "
                    f"{len(full):,} bytes, short of the {ext['offset'] + skip + want:,} "
                    "its file needs")
            yield piece
        pos += want
    if pos < limit:                                     # a hole to the end of the file
        for z in zeros(limit - pos):
            yield z


class BtrfsWalker:
    """List and read a Btrfs volume from one device.

    A node is an int: the file tree's id shifted left 64, plus the inode
    number in it. A hard link is one node reached by two names; a subvolume or
    snapshot is a directory whose node is in its own tree. ``damage`` collects
    what could not be read, each as text, as the walk finds it."""

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        self.damage = []
        self._seen_damage = set()
        self._cache = collections.OrderedDict()
        self._named = {}                            # node -> (dir entry type, name)
        best, self.superblocks, why = _btrfs_pick_super(fh, base)
        if best is None:
            raise BtrfsUnreadable(why)
        self.sb = sb = best
        self.nodesize, self.sectorsize = sb["nodesize"], sb["sectorsize"]
        self.csum_type = sb["csum_type"]
        self.csum_size = BTRFS_CSUM_SIZES[self.csum_type]
        self.fsid = (sb["metadata_uuid"] if sb["incompat"] & BTRFS_INCOMPAT_METADATA_UUID
                     else sb["fsid"])
        self.devid = sb["devid"]
        if sb["incompat"] & BTRFS_INCOMPAT_EXTENT_TREE_V2:
            raise BtrfsUnreadable("extent tree v2 (an experimental format) is not read")
        # chunk map: logical start -> (length, type, [(devid, physical)], num_stripes)
        self.chunks = {}
        self._chunk_starts = []
        self._bootstrap_chunks(sb["sys_array"])
        for (_obj, typ, logical), data in self._items(sb["chunk_root"], sb["chunk_level"],
                                                      (BTRFS_FIRST_CHUNK_TREE_OBJECTID,
                                                       BTRFS_CHUNK_ITEM_KEY, 0),
                                                      (BTRFS_FIRST_CHUNK_TREE_OBJECTID,
                                                       BTRFS_CHUNK_ITEM_KEY, _BTRFS_KEY_MAX[2]),
                                                      sb["chunk_generation"]):
            if typ == BTRFS_CHUNK_ITEM_KEY:
                try:
                    self._add_chunk(logical, data, 0, len(data))
                except BtrfsUnreadable as exc:
                    self._hurt(f"chunk tree: {exc}")
        self._roots = {}
        fs = self.root_item(BTRFS_FS_TREE_OBJECTID)
        if fs is None:
            raise BtrfsUnreadable("the root tree has no item for the top-level file tree (5)")
        self.root = (BTRFS_FS_TREE_OBJECTID << 64) | fs["root_dirid"]

    def _hurt(self, msg):
        """Record damage once, however often the walk meets it."""
        if msg not in self._seen_damage:
            self._seen_damage.add(msg)
            self.damage.append(msg)

    # -- address translation ------------------------------------------------
    def _add_chunk(self, logical, buf, off, room):
        """Add the chunk item at ``off`` in ``buf``, which has ``room`` bytes
        from ``off`` for it; returns its size."""
        if room < 80:
            raise BtrfsUnreadable(f"chunk item at logical {logical:#x} is {room} bytes")
        length, _owner, stripe_len, ctype = struct.unpack_from("<QQQQ", buf, off)
        num_stripes, sub_stripes = struct.unpack_from("<HH", buf, off + 44)
        if not num_stripes or 48 + 32 * num_stripes > room or not length:
            raise BtrfsUnreadable(f"chunk at logical {logical:#x} has {num_stripes} stripes "
                                  f"and length {length:,} in {room} bytes")
        stripes = [struct.unpack_from("<QQ", buf, off + 48 + 32 * i)
                   for i in range(num_stripes)]
        if logical not in self.chunks:
            bisect.insort(self._chunk_starts, logical)
        self.chunks[logical] = dict(length=length, type=ctype, stripes=stripes,
                                    stripe_len=stripe_len, sub_stripes=sub_stripes)
        return 48 + 32 * num_stripes

    def _bootstrap_chunks(self, arr):
        """The SYSTEM chunks the superblock carries, enough to read the chunk
        tree: a disk key then a chunk item, repeated (volumes.c:2577-2666)."""
        pos = 0
        while pos + 17 <= len(arr):
            _obj, typ, logical = _btrfs_key(arr, pos)
            pos += 17
            if typ != BTRFS_CHUNK_ITEM_KEY:
                raise BtrfsUnreadable(f"sys_chunk_array holds item type {typ}, not a chunk")
            if pos + 80 > len(arr):
                raise BtrfsUnreadable("sys_chunk_array is cut inside a chunk")
            n = struct.unpack_from("<H", arr, pos + 44)[0]
            if not n or pos + 48 + 32 * n > len(arr):
                raise BtrfsUnreadable("sys_chunk_array is cut inside a chunk's stripes")
            pos += self._add_chunk(logical, arr, pos, len(arr) - pos)
        if not self.chunks:
            raise BtrfsUnreadable("sys_chunk_array holds no chunk")

    def _chunk(self, logical):
        i = bisect.bisect_right(self._chunk_starts, logical) - 1
        if i < 0:
            return None, None
        start = self._chunk_starts[i]
        ch = self.chunks[start]
        if logical >= start + ch["length"]:
            return None, None
        return start, ch

    def copies(self, logical):
        """[(image byte offset, bytes to the end of this stripe)] for each copy
        of ``logical`` that lies on this device, first copy first.

        A SINGLE chunk has one stripe, a DUP chunk two on the same device, a
        RAID1, RAID1C3 or RAID1C4 chunk one per device; each stripe holds the
        chunk whole, at stripe offset + (logical - chunk start)
        (volumes.c:2168-2290, the num_stripes = 1, DUP and RAID1 cases). A
        striped profile (RAID0, RAID10, RAID5, RAID6) is refused by name."""
        start, ch = self._chunk(logical)
        if ch is None:
            raise BtrfsUnreadable(f"logical address {logical:#x} lies in no chunk")
        if ch["type"] & BTRFS_BG_STRIPED:
            raise BtrfsUnreadable(f"logical address {logical:#x} is in a "
                                  f"{_btrfs_profile(ch['type'])} chunk, striped across devices, "
                                  "which one image does not hold")
        if len(ch["stripes"]) > 1 and not ch["type"] & BTRFS_BG_MIRRORED:
            raise BtrfsUnreadable(f"chunk at {start:#x} has {len(ch['stripes'])} stripes "
                                  "and no mirrored profile")
        off = logical - start
        out = [(self.base + phys + off, ch["length"] - off)
               for devid, phys in ch["stripes"] if devid == self.devid]
        if not out:
            raise BtrfsUnreadable(f"logical address {logical:#x} has no copy on this device "
                                  f"(devid {self.devid})")
        return out

    def read_logical(self, logical, n):
        """n bytes at a logical address, from the first copy on this device,
        across chunk boundaries."""
        out = bytearray()
        while len(out) < n:
            phys, room = self.copies(logical + len(out))[0]
            take = min(n - len(out), room)
            if take <= 0:                           # a stripe that holds nothing past here
                raise BtrfsUnreadable(f"logical address {logical + len(out):#x} is past the "
                                      "end of its chunk's stripe")
            got = read_at(self.fh, phys, take)
            out += got
            if len(got) < take:
                break
        return bytes(out)

    # -- tree blocks ----------------------------------------------------------
    def _copy(self, logical, phys):
        """The block at one copy with its own checks done (checksum, the
        address it records, filesystem id, structure), cached by copy; or the
        reason it fails, as a str."""
        key = (logical, phys)
        hit = self._cache.get(key)
        if hit is not None:
            self._cache.move_to_end(key)
            return hit
        buf = read_at(self.fh, phys, self.nodesize)
        if len(buf) < self.nodesize:
            return f"copy at {phys:#x} lies past the end of the image"
        if btrfs_csum(self.csum_type, buf[32:]) != buf[:self.csum_size]:
            return f"copy at {phys:#x}: checksum does not hold"
        hbytenr = struct.unpack_from("<Q", buf, 48)[0]
        if hbytenr != logical:
            return f"copy at {phys:#x} records address {hbytenr:#x}"
        if buf[32:48] != self.fsid:
            return f"copy at {phys:#x} belongs to another filesystem"
        bad = _btrfs_check_block(buf, self.nodesize, self.sectorsize)
        if bad:
            return f"copy at {phys:#x}: {bad}"
        self._cache[key] = buf
        while len(self._cache) > 4096:
            self._cache.popitem(last=False)
        return buf

    def _block(self, logical, level=None, generation=None, first_key=None):
        """The tree block at ``logical`` from the first copy that passes every
        check: its own (``_copy``), and, on every read whether cached or not,
        the level, generation and first key its parent records for it
        (verify_parent_transid, disk-io.c:275; btrfs_verify_level_key, linux
        fs/btrfs/tree-checker.c:2302-2355, which compares the first key only
        for a block no newer than the last committed transaction). A copy that
        fails is recorded as damage when another copy is read instead."""
        why = []
        for phys, _room in self.copies(logical):
            buf = self._copy(logical, phys)
            if isinstance(buf, str):
                why.append(buf)
                continue
            hgen = struct.unpack_from("<Q", buf, 80)[0]
            nritems, hlevel = struct.unpack_from("<IB", buf, 96)
            if level is not None and hlevel != level:
                why.append(f"copy at {phys:#x} is level {hlevel}, its parent says {level}")
                continue
            if generation is not None and hgen != generation:
                why.append(f"copy at {phys:#x} is generation {hgen}, its parent says "
                           f"{generation}")
                continue
            if first_key is not None and hgen <= self.sb["generation"]:
                if not nritems:
                    why.append(f"copy at {phys:#x} holds nothing, its parent names a first key")
                    continue
                got = _btrfs_key(buf, BTRFS_HEADER_SIZE)
                if got != first_key:
                    why.append(f"copy at {phys:#x} starts at key {got}, its parent says "
                               f"{first_key}")
                    continue
            if why:
                self._hurt(f"tree block at logical {logical:#x}: " + "; ".join(why)
                           + f"; read from the copy at {phys:#x}")
            return buf
        raise BtrfsUnreadable(f"tree block at logical {logical:#x}: " + "; ".join(why))

    def _items(self, bytenr, level, lo, hi, generation=None, first_key=None):
        """Yield (key, item bytes) for every item whose key is in [lo, hi], in
        key order, from the tree whose root block is at ``bytenr``. A child
        block that cannot be read is recorded as damage and passed over, so
        what the rest of the tree holds is still returned; the root block not
        being readable raises."""
        buf = self._block(bytenr, level, generation, first_key)
        nritems = struct.unpack_from("<I", buf, 96)[0]
        if level == 0:
            for i in range(nritems):
                o = BTRFS_HEADER_SIZE + i * BTRFS_ITEM_SIZE
                key = _btrfs_key(buf, o)
                if key < lo:
                    continue
                if key > hi:
                    return
                ioff, isz = struct.unpack_from("<II", buf, o + 17)
                start = BTRFS_HEADER_SIZE + ioff
                yield key, buf[start:start + isz]
            return
        ptrs = []
        for i in range(nritems):
            o = BTRFS_HEADER_SIZE + i * BTRFS_KEY_PTR_SIZE
            ptrs.append((_btrfs_key(buf, o),) + struct.unpack_from("<QQ", buf, o + 17))
        for i, (key, child, gen) in enumerate(ptrs):
            nxt = ptrs[i + 1][0] if i + 1 < len(ptrs) else None
            if nxt is not None and nxt <= lo:
                continue                            # everything below is before lo
            if key > hi:
                return
            try:
                for item in self._items(child, level - 1, lo, hi, gen, key):
                    yield item
            except BtrfsUnreadable as exc:
                self._hurt(f"under node {bytenr:#x}: {exc}")

    def _tree_items(self, tree, lo, hi):
        if tree == BTRFS_ROOT_TREE_OBJECTID:
            return self._items(self.sb["root"], self.sb["root_level"], lo, hi,
                               self.sb["generation"])
        r = self.root_item(tree)
        if r is None:
            raise BtrfsUnreadable(f"the root tree has no item for tree {tree}")
        # a tree's root block carries the generation its ROOT_ITEM records
        # (btrfs_root_generation, as read_tree_root_path reads it)
        return self._items(r["bytenr"], r["level"], lo, hi, r["generation"])

    def _root_items(self, lo, hi):
        return self._tree_items(BTRFS_ROOT_TREE_OBJECTID, lo, hi)

    def root_item(self, tree):
        """The newest ROOT_ITEM for ``tree`` (largest key offset, as
        btrfs_find_last_root takes it), parsed, or None."""
        if tree in self._roots:
            return self._roots[tree]
        found = None
        for key, data in self._root_items((tree, BTRFS_ROOT_ITEM_KEY, 0),
                                          (tree, BTRFS_ROOT_ITEM_KEY, _BTRFS_KEY_MAX[2])):
            if len(data) >= BTRFS_ROOT_ITEM_LEGACY_SIZE:
                found = (key, data)
            else:
                self._hurt(f"ROOT_ITEM of tree {tree} is {len(data)} bytes, under "
                           f"{BTRFS_ROOT_ITEM_LEGACY_SIZE}")
        r = None
        if found is not None:
            key, data = found
            mtime = struct.unpack_from("<Q", data, 136)[0]
            r = dict(generation=struct.unpack_from("<Q", data, 160)[0],
                     root_dirid=struct.unpack_from("<Q", data, 168)[0],
                     bytenr=struct.unpack_from("<Q", data, 176)[0],
                     flags=struct.unpack_from("<Q", data, 208)[0],
                     refs=struct.unpack_from("<I", data, 216)[0],
                     level=data[238], offset=key[2], mtime=mtime)
        self._roots[tree] = r
        return r

    # -- inodes and directories ----------------------------------------------
    @staticmethod
    def _split(node):
        return node >> 64, node & _M64

    def inode(self, node):
        """The INODE_ITEM of a node, parsed (btrfs_tree.h:872-899), or None
        when there is none. An item that is not 160 bytes, a mode with bits
        outside the type, set-id, sticky and permission bits (both as
        check_inode_item refuses, linux fs/btrfs/tree-checker.c:1141-1174),
        or a size past the largest file the kernel allows (super.c:963)
        raises BtrfsUnreadable."""
        tree, ino = self._split(node)
        for _key, d in self._tree_items(tree, (ino, BTRFS_INODE_ITEM_KEY, 0),
                                        (ino, BTRFS_INODE_ITEM_KEY, 0)):
            if len(d) != BTRFS_INODE_ITEM_SIZE:
                raise BtrfsUnreadable(f"inode {ino} of tree {tree} is {len(d)} bytes, "
                                      f"not {BTRFS_INODE_ITEM_SIZE}")
            size, nbytes = struct.unpack_from("<QQ", d, 16)
            nlink, uid, gid, mode = struct.unpack_from("<IIII", d, 40)
            rdev, flags = struct.unpack_from("<QQ", d, 56)
            if mode & ~(S_IFMT | 0o7777):
                raise BtrfsUnreadable(f"inode {ino} of tree {tree} has mode {mode:#o}, with "
                                      "bits no mode has")
            if size > BTRFS_MAX_FILE_SIZE:
                raise BtrfsUnreadable(f"inode {ino} of tree {tree} records size {size:,}, past "
                                      f"the largest file btrfs allows ({BTRFS_MAX_FILE_SIZE:,})")
            t = {name: struct.unpack_from("<QI", d, at)
                 for name, at in (("atime", 112), ("ctime", 124), ("mtime", 136),
                                  ("otime", 148))}
            return dict(size=size, nbytes=nbytes, nlink=nlink, uid=uid, gid=gid, mode=mode,
                        rdev=rdev, flags=flags, **t)
        return None

    def entry(self, node):
        """(mode, size, mtime) of a node. A directory entry whose inode item is
        missing or unreadable is still an entry: readdir lists a name from its
        DIR_INDEX item alone (linux fs/btrfs/inode.c btrfs_real_readdir,
        6304-6425, reads no inode item), so it is returned with the file
        type its directory entry records, no permission bits, size 0 and time
        0, and the damage is recorded. Reading it then fails, by name."""
        tree, ino = self._split(node)
        if ino == BTRFS_EMPTY_SUBVOL_DIR_OBJECTID:
            # A subvolume link with no matching ROOT_REF: the kernel shows an
            # empty directory, mode S_IFDIR | 0755, with no time on the disk
            # (inode.c new_simple_dir, 6008-6040), so its time here is 0.
            return S_IFDIR | 0o755, 0, 0
        why = None
        try:
            ino_item = self.inode(node)
        except BtrfsUnreadable as exc:
            ino_item, why = None, str(exc)
        if ino_item is not None:
            return ino_item["mode"], ino_item["size"], ino_item["mtime"][0]
        named = self._named.get(node)
        if named is None:
            if why:
                self._hurt(f"inode {ino} of tree {tree}: {why}")
            return None
        ftype, name = named
        self._hurt(f"inode {ino} of tree {tree}, named {name!r} by its directory: "
                   + (why or "no INODE_ITEM") + "; listed with the type its directory "
                   "entry records")
        return BTRFS_FT_MODE.get(ftype, 0), 0, 0

    def times(self, node):
        """{"modified", "accessed", "changed", "created"} as (seconds,
        nanoseconds) from the inode item, or None."""
        try:
            i = self.inode(node)
        except BtrfsUnreadable:
            return None
        if i is None:
            return None
        return {"modified": i["mtime"], "accessed": i["atime"], "changed": i["ctime"],
                "created": i["otime"]}

    def _dir_entries(self, data, where=""):
        """(location key, type, name) for each btrfs_dir_item packed in one
        item; a DIR_ITEM holds more than one when names share a hash. An entry
        whose name or data runs past the item is recorded as damage and ends
        the item."""
        out, at = [], 0
        while at < len(data):
            if at + 30 > len(data):
                self._hurt(f"directory item {where}: {len(data) - at} bytes left, short of "
                           "an entry")
                break
            loc = _btrfs_key(data, at)
            data_len, name_len, ftype = struct.unpack_from("<HHB", data, at + 25)
            if at + 30 + name_len + data_len > len(data) or not name_len:
                self._hurt(f"directory item {where}: an entry of name {name_len} and data "
                           f"{data_len} bytes does not fit its {len(data)} bytes")
                break
            name = bytes(data[at + 30:at + 30 + name_len])
            out.append((loc, ftype, name))
            at += 30 + name_len + data_len
        return out

    def _subvol_ref(self, parent_tree, child, dirid, name):
        """True when the root tree links subvolume ``child`` into directory
        ``dirid`` of ``parent_tree`` under ``name`` (fixup_tree_root_location,
        inode.c:5836-5857). A ROOT_REF too short for what it holds is damage,
        and links nothing."""
        for _key, d in self._root_items((parent_tree, BTRFS_ROOT_REF_KEY, child),
                                        (parent_tree, BTRFS_ROOT_REF_KEY, child)):
            if len(d) < 18 or 18 + struct.unpack_from("<H", d, 16)[0] > len(d):
                self._hurt(f"ROOT_REF of tree {parent_tree} to {child} is {len(d)} bytes, "
                           "short of what it records")
                return False
            ref_dir, _seq, nlen = struct.unpack_from("<QQH", d, 0)
            return ref_dir == dirid and bytes(d[18:18 + nlen]) == name
        return False

    def listdir(self, node):
        """[(name, node)] for a directory, sorted by name, from its DIR_INDEX
        items, as readdir reads them. A subvolume or snapshot entry leads into
        its own tree. If a directory has no DIR_INDEX items its DIR_ITEMs are
        read instead."""
        tree, ino = self._split(node)
        if ino == BTRFS_EMPTY_SUBVOL_DIR_OBJECTID:
            return []
        out = []
        try:
            for kind in (BTRFS_DIR_INDEX_KEY, BTRFS_DIR_ITEM_KEY):
                for key, d in self._tree_items(tree, (ino, kind, 0),
                                               (ino, kind, _BTRFS_KEY_MAX[2])):
                    for loc, ftype, name in self._dir_entries(d, f"{key} of tree {tree}"):
                        out.append((name, loc, ftype))
                if out:
                    break
        except BtrfsUnreadable as exc:
            self._hurt(f"directory {ino} of tree {tree}: {exc}")
        result, seen = [], set()
        for name, loc, ftype in out:
            if name in seen:
                continue
            seen.add(name)
            text = name.decode("utf-8", "surrogateescape")
            if loc[1] == BTRFS_ROOT_ITEM_KEY:
                child = loc[0]
                if child == tree:
                    continue                        # a snapshot's entry for itself
                try:
                    linked = self._subvol_ref(tree, child, ino, name)
                    r = self.root_item(child) if linked else None
                except BtrfsUnreadable as exc:
                    self._hurt(f"subvolume {child}: {exc}")
                    r = None
                if r is None:
                    result.append((text, (child << 64) | BTRFS_EMPTY_SUBVOL_DIR_OBJECTID))
                else:
                    result.append((text, (child << 64) | r["root_dirid"]))
            else:
                child = (tree << 64) | loc[0]
                self._named.setdefault(child, (ftype, text))
                result.append((text, child))
        return sorted(result)

    def links(self, node):
        """[(parent directory inode, name)] for every name the inode records for
        itself: its INODE_REF items, keyed by parent, each holding one or more
        (index, name) pairs, and its INODE_EXTREF items, each holding (parent,
        index, name) entries (btrfs_tree.h:853-865). A file with many names in
        one directory keeps the overflow as extended refs."""
        tree, ino = self._split(node)
        out = []
        for (_o, typ, off), d in self._tree_items(tree, (ino, BTRFS_INODE_REF_KEY, 0),
                                                  (ino, BTRFS_INODE_EXTREF_KEY,
                                                   _BTRFS_KEY_MAX[2])):
            at = 0
            if typ == BTRFS_INODE_REF_KEY:
                while at + 10 <= len(d):
                    _index, nlen = struct.unpack_from("<QH", d, at)
                    if at + 10 + nlen > len(d):
                        self._hurt(f"INODE_REF of inode {ino} in tree {tree}: a name runs "
                                   "past the item")
                        break
                    out.append((off, bytes(d[at + 10:at + 10 + nlen])))
                    at += 10 + nlen
            elif typ == BTRFS_INODE_EXTREF_KEY:
                while at + 18 <= len(d):
                    parent, _index, nlen = struct.unpack_from("<QQH", d, at)
                    if at + 18 + nlen > len(d):
                        self._hurt(f"INODE_EXTREF of inode {ino} in tree {tree}: a name runs "
                                   "past the item")
                        break
                    out.append((parent, bytes(d[at + 18:at + 18 + nlen])))
                    at += 18 + nlen
        return out

    # -- file content ---------------------------------------------------------
    @staticmethod
    def _extent(d, file_off=0, sectorsize=4096):
        """An EXTENT_DATA item, parsed (btrfs_tree.h:1069-1119), refused with
        BtrfsUnreadable where the kernel's check_extent_data_item refuses it
        (linux fs/btrfs/tree-checker.c:207-321): a file offset off a sector
        boundary, an item shorter than the inline header, a type or
        compression btrfs does not define, an inline extent anywhere but file
        offset 0, an uncompressed inline extent whose ram_bytes is not the
        bytes it holds, a regular or preallocated item that is not 53 bytes or
        whose sizes and offsets are off a sector boundary, and an end past
        2^64. Also refused, as btrfs restore refuses it (cmds/restore.c:381-
        388): an offset past the extent it reads from."""
        if file_off % sectorsize:
            raise BtrfsUnreadable(f"file extent at {file_off:,} is off a sector boundary")
        if len(d) < BTRFS_FILE_EXTENT_INLINE_DATA_START:
            raise BtrfsUnreadable(f"file extent item of {len(d)} bytes, under the "
                                  f"{BTRFS_FILE_EXTENT_INLINE_DATA_START} of its header")
        gen, ram, comp, enc, other, typ = struct.unpack_from("<QQBBHB", d, 0)
        if typ > BTRFS_FILE_EXTENT_PREALLOC or comp not in BTRFS_COMPRESS:
            raise BtrfsUnreadable(f"file extent at {file_off:,} has type {typ} and "
                                  f"compression {comp}, which btrfs does not define")
        ext = dict(generation=gen, ram_bytes=ram, compression=comp, encryption=enc,
                   other_encoding=other, type=typ)
        if typ == BTRFS_FILE_EXTENT_INLINE:
            if file_off:
                raise BtrfsUnreadable(f"inline extent at file offset {file_off:,}; an inline "
                                      "extent is only ever at offset 0")
            ext["inline"] = bytes(d[BTRFS_FILE_EXTENT_INLINE_DATA_START:])
            if not comp and len(ext["inline"]) != ram:
                raise BtrfsUnreadable(f"inline extent holds {len(ext['inline']):,} bytes "
                                      f"but records ram_bytes {ram:,}")
        else:
            if len(d) != BTRFS_FILE_EXTENT_ITEM_SIZE:
                raise BtrfsUnreadable(f"file extent item of {len(d)} bytes, not "
                                      f"{BTRFS_FILE_EXTENT_ITEM_SIZE}")
            (ext["disk_bytenr"], ext["disk_num_bytes"], ext["offset"],
             ext["num_bytes"]) = struct.unpack_from("<QQQQ", d, 21)
            for name in ("ram_bytes", "disk_bytenr", "disk_num_bytes", "offset", "num_bytes"):
                if ext[name] % sectorsize:
                    raise BtrfsUnreadable(f"file extent at {file_off:,}: {name} "
                                          f"{ext[name]:,} is off a sector boundary")
            if file_off + ext["num_bytes"] > _M64:
                raise BtrfsUnreadable(f"file extent at {file_off:,} ends past 2^64")
            if ext["disk_bytenr"] and typ == BTRFS_FILE_EXTENT_REG and (
                    (not comp and ext["offset"] >= ext["disk_num_bytes"])
                    or ext["offset"] > ram):
                raise BtrfsUnreadable(f"file extent at {file_off:,} starts {ext['offset']:,} "
                                      "into an extent that does not reach that far")
        return ext

    def extents(self, node):
        """[(file offset, extent dict)] for a file, in offset order. An item
        the kernel would refuse makes the file unreadable, and is recorded."""
        tree, ino = self._split(node)
        out, prev_end = [], 0
        for key, d in self._tree_items(tree, (ino, BTRFS_EXTENT_DATA_KEY, 0),
                                       (ino, BTRFS_EXTENT_DATA_KEY, _BTRFS_KEY_MAX[2])):
            try:
                ext = self._extent(d, key[2], self.sectorsize)
                # consecutive extents do not overlap (tree-checker.c:323-341;
                # an inline extent ends at ram_bytes rounded up to a sector,
                # file_extent_end)
                if key[2] < prev_end:
                    raise BtrfsUnreadable(f"file extent at {key[2]:,} starts before the one "
                                          f"before it ends ({prev_end:,})")
                if ext["type"] == BTRFS_FILE_EXTENT_INLINE:
                    prev_end = -(-ext["ram_bytes"] // self.sectorsize) * self.sectorsize
                else:
                    prev_end = key[2] + ext["num_bytes"]
                out.append((key[2], ext))
            except BtrfsUnreadable as exc:
                self._hurt(f"inode {ino} of tree {tree}: {exc}")
                raise
        return out

    def read_file(self, node, size):
        """Yield the file's bytes, the inode's size of them (at most ``size``),
        holes and preallocated ranges as zeros."""
        tree, ino = self._split(node)
        try:
            ino_item = self.inode(node)
            if ino_item is None:
                raise BtrfsUnreadable("no inode item")
            for chunk in btrfs_extent_bytes(self.extents(node), ino_item["size"],
                                            self.read_logical, self.sectorsize, cap=size):
                yield chunk
        except BtrfsUnreadable as exc:
            # A zstd extent on a Python without zstd is not damage: the note
            # says so once for the volume.
            if not ("zstd needs Python" in str(exc) and _zstd_module() is None):
                self._hurt(f"inode {ino} of tree {tree} not read: {exc}")
            raise

    def readlink(self, node):
        ino_item = self.inode(node)
        if ino_item is None:
            return ""
        # mkfs.btrfs --rootdir stores the target with a trailing NUL
        # (mkfs/rootdir.c:368-370), the kernel without; the inode's size is
        # the target's length either way.
        data = b"".join(btrfs_extent_bytes(self.extents(node), ino_item["size"],
                                           self.read_logical, self.sectorsize))
        return data.decode("utf-8", "surrogateescape")

    # -- the volume -------------------------------------------------------------
    def default_subvolume(self):
        """The subvolume id the root tree's "default" entry names, or None
        (Documentation/dev/On-disk-format.rst, BTRFS_ROOT_TREE_DIR_OBJECTID)."""
        h = btrfs_crc32c(b"default", 0xFFFFFFFE)
        for _key, d in self._root_items((BTRFS_ROOT_TREE_DIR_OBJECTID, BTRFS_DIR_ITEM_KEY, h),
                                        (BTRFS_ROOT_TREE_DIR_OBJECTID, BTRFS_DIR_ITEM_KEY, h)):
            for loc, _t, name in self._dir_entries(d, "default"):
                if name == b"default":
                    return loc[0]
        return None

    def subvolumes(self):
        """[(id, read-only, snapshot)] for every file tree the root tree holds
        other than the top level. A snapshot's ROOT_ITEM key carries the
        transaction it was taken in, a subvolume's carries 0 (restore.c:1058-1061)."""
        out = []
        for (obj, _t, off), d in self._root_items(
                (BTRFS_FIRST_FREE_OBJECTID, BTRFS_ROOT_ITEM_KEY, 0),
                (BTRFS_LAST_FREE_OBJECTID, BTRFS_ROOT_ITEM_KEY, _BTRFS_KEY_MAX[2])):
            if _t != BTRFS_ROOT_ITEM_KEY or len(d) < BTRFS_ROOT_ITEM_LEGACY_SIZE:
                continue
            flags = struct.unpack_from("<Q", d, 208)[0]
            out.append((obj, bool(flags & BTRFS_ROOT_SUBVOL_RDONLY), off != 0))
        return out

    def profiles(self):
        """{"data"/"metadata"/"system": set of profile names} over the chunks."""
        out = collections.defaultdict(set)
        for ch in self.chunks.values():
            for bit, name in ((BTRFS_BG_DATA, "data"), (BTRFS_BG_METADATA, "metadata"),
                              (BTRFS_BG_SYSTEM, "system")):
                if ch["type"] & bit:
                    out[name].add(_btrfs_profile(ch["type"]))
        return dict(out)

    @property
    def note(self):
        """What a reader of this volume needs to know before trusting a listing,
        or None."""
        parts = []
        sb = self.sb
        if sb["at"] != BTRFS_SUPER_OFF:
            parts.append(f"the primary superblock does not hold, so the mirror at "
                         f"{sb['at']:#x} (generation {sb['generation']:,}) was read")
        if sb["log_root"]:
            parts.append("a log tree is present (changes fsync'd after the last commit); "
                         "it is not replayed, so the volume reads as of its last commit")
        if sb["num_devices"] != 1:
            parts.append(f"one device (devid {self.devid}) of {sb['num_devices']}; only data "
                         "with a copy on this device is read")
        striped = sorted({_btrfs_profile(c["type"]) for c in self.chunks.values()
                          if c["type"] & BTRFS_BG_STRIPED})
        if striped:
            parts.append(f"{', '.join(striped)} chunks are not read")
        if sb["incompat"] & BTRFS_INCOMPAT_COMPRESS_ZSTD and _zstd_module() is None:
            parts.append("zstd compressed; this Python has no zstd (3.14 adds it), so a "
                         "zstd-compressed file cannot be read")
        try:
            default = self.default_subvolume()
        except BtrfsUnreadable:
            default = None
        if default not in (None, BTRFS_FS_TREE_OBJECTID):
            parts.append(f"the default subvolume is id {default}; it is listed where the "
                         "top-level tree (id 5) links it")
        return "; ".join(parts) or None

    def unallocated(self):
        """[(device offset, length)] of this device that no chunk is allocated
        on: from 1 MiB, below which btrfs allocates nothing (ctree.h:200), to
        the device's size, less the DEV_EXTENT items of the device tree
        (btrfs_tree.h:845-851) and the superblock copies."""
        dev_total = self.sb["dev_total"]
        used = []
        for (_d, _t, phys), d in self._tree_items(BTRFS_DEV_TREE_OBJECTID,
                                                  (self.devid, BTRFS_DEV_EXTENT_KEY, 0),
                                                  (self.devid, BTRFS_DEV_EXTENT_KEY,
                                                   _BTRFS_KEY_MAX[2])):
            if len(d) != BTRFS_DEV_EXTENT_SIZE:
                # Its length is not known, so the space it would cover is not
                # called free: the run up to the next one is left out.
                self._hurt(f"DEV_EXTENT at {phys:#x} is {len(d)} bytes, not "
                           f"{BTRFS_DEV_EXTENT_SIZE}; the space after it is not reported free")
                used.append((phys, _BTRFS_KEY_MAX[0]))
                continue
            used.append((phys, phys + struct.unpack_from("<Q", d, 24)[0]))
        for m in BTRFS_SUPER_MIRRORS:
            used.append((m, m + BTRFS_SUPER_SIZE))
        used.sort()
        out, pos = [], BTRFS_RESERVED_1M
        for s, e in used:
            if pos >= dev_total:
                break
            if s > pos:
                out.append((pos, min(s, dev_total) - pos))
            pos = max(pos, e)
        if pos < dev_total:
            out.append((pos, dev_total - pos))
        return [(s, n) for s, n in out if n > 0]

    def free_logical(self):
        """[(logical start, length)] inside the block groups that no
        EXTENT_ITEM or METADATA_ITEM of the extent tree covers. A superblock
        copy inside a chunk is not taken out here (free_extents() takes it out
        at its place on the device), so this is the same account the free
        space tree keeps, which the self-test checks. A block group is a
        BLOCK_GROUP_ITEM keyed (start, 192, length), in the extent tree or, with
        the block-group-tree feature, in tree 11 (btrfs_tree.h:257, 1217-1221;
        btrfs.h:339). A METADATA_ITEM (skinny metadata) covers one node."""
        bg_tree = (BTRFS_BLOCK_GROUP_TREE_OBJECTID
                   if self.sb["compat_ro"] & BTRFS_COMPAT_RO_BLOCK_GROUP_TREE
                   else BTRFS_EXTENT_TREE_OBJECTID)
        groups = [(k[0], k[2]) for k, _d in self._tree_items(
            bg_tree, (0, BTRFS_BLOCK_GROUP_ITEM_KEY, 0), _BTRFS_KEY_MAX)
            if k[1] == BTRFS_BLOCK_GROUP_ITEM_KEY]
        taken = []
        for (obj, typ, off), _d in self._tree_items(BTRFS_EXTENT_TREE_OBJECTID,
                                                    (0, 0, 0), _BTRFS_KEY_MAX):
            if typ == BTRFS_EXTENT_ITEM_KEY:
                taken.append((obj, obj + off))
            elif typ == BTRFS_METADATA_ITEM_KEY:
                taken.append((obj, obj + self.nodesize))
        taken.sort()
        out = []
        for gstart, glen in groups:
            gend, pos = gstart + glen, gstart
            i = bisect.bisect_left(taken, (gstart, 0))
            if i > 0 and taken[i - 1][1] > gstart:
                i -= 1
            while i < len(taken) and taken[i][0] < gend:
                s, e = taken[i]
                if s > pos:
                    if out and out[-1][0] + out[-1][1] == pos:
                        out[-1] = (out[-1][0], out[-1][1] + s - pos)
                    else:
                        out.append((pos, s - pos))
                pos = max(pos, e)
                i += 1
            if pos < gend:
                if out and out[-1][0] + out[-1][1] == pos:
                    out[-1] = (out[-1][0], out[-1][1] + gend - pos)
                else:
                    out.append((pos, gend - pos))
        return out

    def free_space_tree(self):
        """[(logical start, length)] the free space tree records as free, or
        None when the volume has none: FREE_SPACE_EXTENT items keyed (start,
        199, length), and FREE_SPACE_BITMAP items keyed (start, 200, length)
        whose bit n, least significant first, marks sector n free
        (btrfs_tree.h:264-278; free-space-tree.c:100-118, extent_io.c:664-668).
        A second account of the same space, kept by the filesystem; the
        self-test holds free_logical() against it."""
        if self.root_item(BTRFS_FREE_SPACE_TREE_OBJECTID) is None:
            return None
        out = []
        for (obj, typ, off), d in self._tree_items(BTRFS_FREE_SPACE_TREE_OBJECTID,
                                                   (0, 0, 0), _BTRFS_KEY_MAX):
            if typ == BTRFS_FREE_SPACE_EXTENT_KEY:
                out.append((obj, off))
            elif typ == BTRFS_FREE_SPACE_BITMAP_KEY:
                if len(d) * 8 < off // self.sectorsize:
                    self._hurt(f"free space bitmap at {obj:#x} is {len(d)} bytes, short of "
                               f"{off // self.sectorsize} bits")
                    continue
                run = None
                for n in range(off // self.sectorsize):
                    if d[n >> 3] >> (n & 7) & 1:
                        if run is None:
                            run = obj + n * self.sectorsize
                    elif run is not None:
                        out.append((run, obj + n * self.sectorsize - run))
                        run = None
                if run is not None:
                    out.append((run, obj + off - run))
        merged = []
        for s, n in sorted(out):
            if merged and merged[-1][0] + merged[-1][1] == s:
                merged[-1] = (merged[-1][0], merged[-1][1] + n)
            else:
                merged.append((s, n))
        return merged

    def free_extents(self, min_bytes=0):
        """[(byte offset, length)] of this device's space the volume says is
        free, offsets into the image: what unallocated() gives, and each range
        free_logical() gives at every copy of its chunk on this device (both
        copies of a DUP chunk), less the 4 KiB of each superblock copy. Ranges
        in striped chunks are not mapped and so not reported. ``min_bytes``
        drops runs shorter than that."""
        try:
            runs = list(self.unallocated())
        except BtrfsUnreadable as exc:
            self._hurt(f"device tree: {exc}; unallocated space not reported")
            runs = []
        try:
            inside = self.free_logical()
        except BtrfsUnreadable as exc:
            self._hurt(f"extent tree: {exc}; free space inside block groups not reported")
            inside = []
        for s, n in inside:
            try:
                cps = self.copies(s)
            except BtrfsUnreadable:
                continue
            for phys, _room in cps:
                runs.append((phys - self.base, n))
        runs.sort()
        out = []
        for s, n in runs:
            pieces = [(s, s + n)]
            for m in BTRFS_SUPER_MIRRORS:
                cut = []
                for a, b in pieces:
                    if a < m + BTRFS_SUPER_SIZE and m < b:
                        cut += [(a, m), (m + BTRFS_SUPER_SIZE, b)]
                    else:
                        cut.append((a, b))
                pieces = [(a, b) for a, b in cut if b > a]
            out += [(self.base + a, b - a) for a, b in pieces]
        return [(s, n) for s, n in out if n >= max(min_bytes, 1)]


def _btrfs_chunk_root_present(fh, base, sb):
    """True when the chunk tree root block ``sb`` names, mapped through the
    superblock's own SYSTEM chunks, has a checksum that holds and records its
    own address and the superblock's filesystem id, at any of its copies; or
    when every copy lies past the end of the image, so an image cut short is
    still named for what it holds. False when a copy is there and is not that
    block."""
    try:
        w = BtrfsWalker.__new__(BtrfsWalker)
        w.fh, w.base, w.devid = fh, base, sb["devid"]
        w.chunks, w._chunk_starts = {}, []                      # pylint: disable=protected-access
        w._bootstrap_chunks(sb["sys_array"])                    # pylint: disable=protected-access
        w.nodesize, w.sectorsize = sb["nodesize"], sb["sectorsize"]
        w.csum_type, w.csum_size = sb["csum_type"], BTRFS_CSUM_SIZES[sb["csum_type"]]
        w.fsid = (sb["metadata_uuid"] if sb["incompat"] & BTRFS_INCOMPAT_METADATA_UUID
                  else sb["fsid"])
        w._cache = collections.OrderedDict()                    # pylint: disable=protected-access
        got = [w._copy(sb["chunk_root"], phys)                  # pylint: disable=protected-access
               for phys, _r in w.copies(sb["chunk_root"])]
        return any(not isinstance(g, str) for g in got) or all(
            g.endswith("lies past the end of the image") for g in got)
    except (BtrfsUnreadable, struct.error, ValueError, KeyError):
        return False


def identify_btrfs(fh, base, size=None):
    """Return ("btrfs", lines) for a Btrfs volume at base, else None.

    Claimed only when the magic is at 64 KiB + 64, a superblock copy can be
    used (_btrfs_pick_super: the primary's checksum holds, or a mirror's does
    and agrees with the others on the fsid), and the chunk tree's root block
    that superblock names is there: a tree block whose checksum holds and
    which records its own address and this filesystem's id (without it
    nothing on the volume can be found, and btrfs-progs' open_ctree fails
    too). Eight magic bytes alone are not enough, and neither is a whole
    superblock copied or left behind where its filesystem is not, so such a
    volume falls through to the identifiers after this one."""
    sb, _found, _why = _btrfs_pick_super(fh, base)
    if sb is None:
        return None
    try:
        w = BtrfsWalker(fh, base)
    except (BtrfsUnreadable, struct.error, ValueError) as exc:
        if not _btrfs_chunk_root_present(fh, base, sb):
            return None                     # the superblock's filesystem is not here
        return "btrfs", [f"uuid         {_btrfs_uuid(sb['fsid'])}",
                         f"walk         not possible: {exc}"]
    sb = w.sb
    feats = [n for bit, n in BTRFS_INCOMPAT_NAMES if sb["incompat"] >> bit & 1]
    prof = w.profiles()
    lines = [
        f"label        {sb['label'] or '(none)'}",
        f"uuid         {_btrfs_uuid(sb['fsid'])}",
        f"generation   {sb['generation']:,}   checksum {BTRFS_CSUM_NAMES[sb['csum_type']]}",
        f"used         {human(sb['bytes_used'])} of {human(sb['total_bytes'])}",
        f"devices      {sb['num_devices']}   this one devid {sb['devid']}, "
        f"{human(sb['dev_total'])}",
        f"blocks       node {sb['nodesize']:,}, sector {sb['sectorsize']:,} bytes",
        "profiles     " + ", ".join(f"{k} {'/'.join(sorted(v))}" for k, v in sorted(prof.items())),
        "features     " + (", ".join(feats) or "(none)"),
    ]
    try:
        subs = w.subvolumes()
        if subs:
            snaps = sum(1 for _i, _ro, snap in subs if snap)
            lines.append(f"subvolumes   {len(subs) - snaps} and {snaps} snapshots, besides the "
                         "top level")
    except BtrfsUnreadable as exc:
        lines.append(f"subvolumes   not read: {exc}")
    if size is not None and sb["dev_total"] > size:
        lines.append(f"note         the device records {human(sb['dev_total'])} but the region "
                     f"holds {human(size)}, so its end is missing")
    note = w.note
    if note:
        lines.append(f"note         {note}")
    return "btrfs", lines


# ---------------------------------------------------------------------------
# ReFS, Microsoft's Resilient File System, format 3.x. Read only.
#
# Microsoft publishes no specification of ReFS. The structures below follow
# two public descriptions, and every field this reads was checked against
# volumes Windows 11 (build 26200, ReFS 3.14) wrote, listed and hashed on the
# mounted volume (tools/make_refs_fixtures.ps1), and against forefst's own
# inventory of its four sample volumes (_refs_forefst_checks):
#
#   [forefst]   xbqt/forefst, commit d4d5fd28942eb14ebe11d90f4eb9342f5e3d7b92,
#               docs/structures/{vbr,supb,chkp,page_header,page_references,
#               btree_node,object_table,container_table,directory_entries,
#               extent_descriptors,volume_info,mlog,system_oids}.md,
#               docs/attributes/{NAMED_DATA,STANDARD_INFORMATION}.md and
#               docs/concepts/{checksum_architecture,virtual_addressing,
#               hard_links,snapshots_versioning}.md.
#               GPL-3.0; the documentation is read, no code is taken from it.
#   [libfsrefs] libyal/libfsrefs, commit 77e1b7ba68cf225ec888a61e9784fb9a93a0156f,
#               "documentation/Resilient File System (ReFS).asciidoc" (GFDL 1.3):
#               the volume header, the metadata block reference, the ministore
#               node header and node record, and the version list.
#   [MS-FSCC]   Microsoft's File System Control Codes, 2.1.2.4 and 2.1.2.5, for
#               the symbolic link and mount point reparse buffers, which ReFS
#               stores as NTFS does.
#
# The chain from the boot sector to a file:
#   boot sector (sector 0)   "ReFS" at 3, "FSRS" at 0x10, sector size 0x20,
#                            sectors per cluster 0x24, version 0x28/0x29
#   superblock (cluster 30)  the two checkpoint locations; carries its own
#                            checksum over one cluster with its descriptor zeroed
#   checkpoint               the newer of two by the clock at 0x60, each with the
#                            same kind of self checksum; holds 13 root references
#   container table (root 7) maps the virtual cluster numbers everything else
#                            uses to the clusters they occupy
#   object table (root 0)    directory and system object id -> its table
#   directory table          name rows (0x30), split-out file records (0x40)
#                            and the directory's own record (0x10)
#   file record              a table of its own inside the name row: $DATA
#                            inline or as extents, named streams, reparse data
# Every metadata page is checked against the checksum its parent's reference
# records for it (CRC-64/NVME on these volumes; CRC32-C and SHA-256 are the
# other kinds [forefst page_references.md]). A page that fails is reported, and
# the rows under it are left out rather than read from bytes that do not match.
#
# What is not done: the metadata log is not replayed. ReFS commits changes to
# the log first and folds them into a checkpoint later, and a volume detached
# before that keeps its newest files only in the log (the first Windows fixture,
# detached seconds after its files were written, is one). The reader shows the
# volume as of its newest checkpoint and says how many log records follow it.
# Deleted files are not recovered. ReFS 1.x and 2.x use other structures
# [libfsrefs "format version 1"] and are identified and refused.
# ---------------------------------------------------------------------------
REFS_FS_NAME = b"ReFS\x00\x00\x00\x00"           # boot sector +3 [libfsrefs, forefst vbr.md]
REFS_FSRS = b"FSRS"                              # boot sector +0x10
REFS_SUPERBLOCK_LCN = 30                         # [forefst supb.md]
REFS_PAGE_BYTES = 0x4000                         # a metadata page: 4 clusters of 4 KiB, or one 64 KiB cluster
REFS_ROOT_OBJECTS, REFS_ROOT_OBJECTS_COPY = 0, 5      # checkpoint roots [forefst chkp.md]
REFS_ROOT_CONTAINERS, REFS_ROOT_CONTAINERS_COPY = 7, 8
REFS_ROOT_DIR = 0x600                            # the root directory's object id
REFS_VOLUME_INFO = 0x500                         # its row 0x510 holds the label [forefst volume_info.md]
REFS_LIVE_STREAM = 0x1000                        # sub-stream id of a file's current $DATA [forefst extent_descriptors.md]
REFS_ATTR_DIRECTORY = 0x10000000                 # set on a directory's name row [forefst directory_entries.md]
REFS_ATTR_REPARSE = 0x400                        # FILE_ATTRIBUTE_REPARSE_POINT
REFS_TAG_SYMLINK, REFS_TAG_MOUNT_POINT = 0xA000000C, 0xA0000003
REFS_LOGFILE_INFO = 0x9                          # the logfile information table [forefst system_oids.md]
REFS_LOG_CONTROL_LCNS = (0x30, 0x31)             # where the control pages were on four of six volumes
REFS_CRC64_SENTINEL = (0xABBAFFFFABBAFFFE, 0xABBAFFFFABBAFFFF)   # [forefst checksum_architecture.md]
REFS_NEWEST_MINOR = 14                           # 3.14, the newest version forefst documents and Windows wrote here
REFS_DAMAGE_CAP = 1000                           # damage lines kept; damage_count counts them all
REFS_MAX_FILE_BYTES = 35 << 50                   # 35 PB, Microsoft's ReFS maximum file size, taken as PiB
REFS_CONTAINER_COMPRESSED = 0x800                # [forefst concepts/compression.md], see _clusters
REFS_ATTR_SPARSE, REFS_ATTR_ENCRYPTED = 0x200, 0x4000   # FILE_ATTRIBUTE_* [MS-FSCC] 2.6
# The checksum kind a page reference must carry, by the boot sector's selector
# (0x2A) and, for a volume upgraded with the selector left at 0, by the
# checkpoint's page reference size (0x5C) [forefst vbr.md, page_references.md].
REFS_KIND_BY_SELECTOR = {2: 2, 4: 4}
REFS_KIND_BY_REFSIZE = {0x30: 2, 0x48: 4, 0x68: 2}

_REFS_CRC_TABLES = {}


def _refs_crc(data, poly, width):
    """A reflected CRC with all-ones initial value and final xor, which is the
    shape of both CRC32-C (poly 0x82F63B78) and CRC-64/NVME (0x9A6C9329AC4BC9B5),
    the two ReFS uses [forefst checksum_architecture.md]."""
    table = _REFS_CRC_TABLES.get(poly)
    if table is None:
        table = []
        for i in range(256):
            c = i
            for _ in range(8):
                c = (c >> 1) ^ poly if c & 1 else c >> 1
            table.append(c)
        _REFS_CRC_TABLES[poly] = table
    mask = (1 << width) - 1
    c = mask
    for b in data:
        c = table[(c ^ b) & 0xFF] ^ (c >> 8)
    return c ^ mask


def refs_crc32c(data):
    return _refs_crc(data, 0x82F63B78, 32)


def refs_crc64(data):
    return _refs_crc(data, 0x9A6C9329AC4BC9B5, 64)


def _refs_digest_matches(kind, digest, data):
    """True or False for a checksum kind this computes, None for one it does not.
    Kind 0 records no checksum and also answers None."""
    if kind == 1 and len(digest) == 4:
        return struct.unpack("<I", digest)[0] == refs_crc32c(data)
    if kind == 2 and len(digest) == 8:
        got = refs_crc64(data)
        if got == REFS_CRC64_SENTINEL[0]:
            got = REFS_CRC64_SENTINEL[1]
        return struct.unpack("<Q", digest)[0] == got
    if kind == 4 and len(digest) == 32:
        import hashlib
        return hashlib.sha256(data).digest() == digest
    return None


def _refs_reference(buf, off):
    """(four cluster numbers, checksum kind, digest) of the page reference at
    off: four u64 slots, then flags, kind at +0x22, the digest's offset from
    +0x20 at +0x23, its length at +0x24 [forefst page_references.md, libfsrefs
    "metadata block reference - format version 3"]."""
    if off < 0 or off + 0x28 > len(buf):
        raise RefsDamage(f"a page reference at {off:#x} runs past its page")
    slots = struct.unpack_from("<4Q", buf, off)
    kind, doff = buf[off + 0x22], buf[off + 0x23]
    dlen = struct.unpack_from("<H", buf, off + 0x24)[0]
    digest = bytes(buf[off + 0x20 + doff:off + 0x20 + doff + dlen])
    if len(digest) != dlen:
        raise RefsDamage(f"a page reference at {off:#x} has a digest past its page")
    return slots, kind, digest


def _refs_self_checksum(page, cluster, desc_off, desc_len):
    """Whether a superblock's or checkpoint's own checksum holds: computed over
    its first cluster with the descriptor that holds it zeroed [forefst supb.md,
    checksum_architecture.md]. None when it records a kind this does not compute,
    which the callers treat as not holding."""
    if desc_off + desc_len > len(page) or desc_off + 0x28 > len(page):
        return False
    _slots, kind, digest = _refs_reference(page, desc_off)
    body = bytearray(page[:cluster])
    body[desc_off:desc_off + desc_len] = bytes(desc_len)
    return _refs_digest_matches(kind, digest, bytes(body))


def _refs_node(buf, hoff, where="a node"):
    """(level, flags, [(key, value, row flags)]) of the B+ tree node whose
    header is at hoff in buf.

    The header [libfsrefs "node header", forefst btree_node.md]: level at +0x0C
    (0 is a leaf), flags at +0x0D, the key index from +0x10 to +0x20 and its
    count at +0x14. The index holds a u32 per row whose low 16 bits are the
    row's offset from the header. A row: its size, then the key's offset and
    length, row flags, the value's offset and length, all from the row's start.
    The index is the authority; bytes it does not name are not rows. An end
    of 0 means not set (libfsrefs); every node on the six volumes measured
    here sets it, as forefst measured on 118,351 pages.
    """
    if hoff < 0 or hoff + 0x24 > len(buf):
        raise RefsDamage(f"{where}: its node header lies outside it")
    level, flags = buf[hoff + 0x0C], buf[hoff + 0x0D]
    start, count = struct.unpack_from("<II", buf, hoff + 0x10)
    end = struct.unpack_from("<I", buf, hoff + 0x20)[0]
    if end == 0:            # "or 0 if not set" [libfsrefs "node header"]
        end = start + 4 * count
    if end < start or (end - start) // 4 != count or hoff + end > len(buf):
        raise RefsDamage(f"{where}: its key index ({start:#x} to {end:#x}) does not "
                         f"hold the {count} rows its header counts")
    rows = []
    for i in range(count):
        pos = hoff + (struct.unpack_from("<I", buf, hoff + start + 4 * i)[0] & 0xFFFF)
        if pos + 16 > len(buf):
            raise RefsDamage(f"{where}: row {i} lies outside it")
        size, koff, klen, rflags, voff, vlen = struct.unpack_from("<IHHHHH", buf, pos)
        if (size < 16 or pos + size > len(buf) or koff + klen > size
                or voff + vlen > size):
            raise RefsDamage(f"{where}: row {i} runs past its own size")
        rows.append((bytes(buf[pos + koff:pos + koff + klen]),
                     bytes(buf[pos + voff:pos + voff + vlen]), rflags))
    return level, flags, rows


class RefsDamage(ValueError):
    """A ReFS structure that does not check out: a checksum that does not hold,
    or a field that points outside what holds it."""


class RefsEntry(collections.namedtuple("RefsEntry", "dir key")):
    """A file, link or reparse directory: the directory that names it and its
    name as stored (UTF-16LE). Directories are their object id, an int."""

    __slots__ = ()


class RefsStreamRef(collections.namedtuple("RefsStreamRef", "file name")):
    """An alternate data stream: its file's node and the stream's name. A type
    of its own, as NtfsStreamRef is, so a caller can keep streams apart."""

    __slots__ = ()


class _RefsDir:
    """One directory table, read whole: its name rows in key order, its
    split-out file records by (file id, home directory), and its own record."""

    __slots__ = ("names", "records", "own")

    def __init__(self):
        self.names, self.records, self.own = collections.OrderedDict(), {}, None


class RefsWalker:
    """List and read files from a ReFS 3.x volume, same interface as the other
    walkers: root, listdir, entry, read_file, stamps, readlink, named_streams,
    allocation.

    A directory's node is its object id. A file's is a RefsEntry, the directory
    that names it and the name. A file is stored one of two ways
    [forefst directory_entries.md]: its whole record inside its name row (the
    row's key flag is 1), or, once it has been moved or given a second name, a
    short name row (flag 2) that points at its record, kept in the directory it
    was created in under its id there. Windows reports that pair, the id and the
    directory's object id, as the file's 128-bit file id, and file_id() gives
    the same two numbers.

    Read: $DATA held inline in the record, $DATA in extents (sparse runs read as
    zeros), named streams inline and in extents, symbolic links and junctions
    (mode S_IFLNK, target from readlink()), hard links (each name lists the one
    record). Not read, and refused with a reason rather than guessed: a stream
    record laid out other than as ReFS 3.14 writes it. ``note`` says when the metadata log
    holds changes newer than the checkpoint, which are not applied.
    """

    root = REFS_ROOT_DIR

    def __init__(self, fh, base):
        self.fh, self.base = fh, base
        boot = read_at(fh, base, 512)
        if len(boot) < 512 or boot[3:11] != REFS_FS_NAME or boot[0x10:0x14] != REFS_FSRS:
            raise ValueError("not a ReFS boot sector")
        self.total_sectors, self.bps, self.spc = struct.unpack_from("<QII", boot, 0x18)
        self.version = (boot[0x28], boot[0x29])
        self.serial = struct.unpack_from("<Q", boot, 0x38)[0]
        self.cluster = self.bps * self.spc
        why_not = _refs_version_refusal(*self.version)
        if why_not:
            raise ValueError(why_not)
        self.checksum_selector = struct.unpack_from("<H", boot, 0x2A)[0]
        if self.cluster < 512 or self.cluster & (self.cluster - 1):
            raise ValueError(f"a cluster of {self.cluster} bytes is not a power of two")
        self.boot_checksum_ok = struct.unpack_from("<H", boot, 0x16)[0] == _refs_boot_checksum(boot)
        self.total_clusters = self.total_sectors * self.bps // self.cluster
        self.page_clusters = max(1, REFS_PAGE_BYTES // self.cluster)
        self.damage, self.damage_count, self._where = [], 0, ""
        self._pages = collections.OrderedDict()
        self._dirs = collections.OrderedDict()
        self._index_rows = {}                   # directory object id -> its name row in its parent
        self._dir_parent = {REFS_ROOT_DIR: None}  # directory object id -> the directory naming it
        self.pages_checked = collections.Counter()   # checksum kind -> pages that matched it
        self.superblock_lcn, sb = self._superblock()
        self.volume_guid = sb[0x50:0x60]
        ref_off, ref_count = struct.unpack_from("<II", sb, 0x70)
        if ref_count < 1 or ref_off + 8 * ref_count > self.cluster:
            raise RefsDamage("the superblock's checkpoint list lies outside it")
        self.checkpoint_lcns = struct.unpack_from(f"<{ref_count}Q", sb, ref_off)
        self.checkpoint_lcn, cp, self.checkpoint_tie = self._checkpoint()
        self.checkpoint_version = struct.unpack_from("<HH", cp, 0x54)
        refsize = struct.unpack_from("<I", cp, 0x5C)[0]
        self.page_kind = (REFS_KIND_BY_SELECTOR.get(self.checksum_selector)
                          if self.checksum_selector else REFS_KIND_BY_REFSIZE.get(refsize))
        if self.page_kind is None:
            raise RefsDamage(f"a checksum selector {self.checksum_selector} with page "
                             f"references of {refsize} bytes, which no source describes")
        self.clock, _allocator, self.checkpoint_lsn = struct.unpack_from("<QQQ", cp, 0x60)
        self.checkpoint_flags = struct.unpack_from("<I", cp, 0x78)[0]
        nroots = struct.unpack_from("<I", cp, 0x90)[0]
        if self.checkpoint_flags & 0x200:        # the root list is reached through an offset
            at = struct.unpack_from("<I", cp, 0x94)[0]
        else:
            at = 0x94
        if nroots < 13 or at + 4 * nroots > len(cp):
            raise RefsDamage("the checkpoint's root list lies outside it")
        self.root_offsets = struct.unpack_from(f"<{nroots}I", cp, at)
        self._cp = cp
        self.containers = {}
        self.containers = self._containers()
        self.bad_containers = self._check_containers()
        self.compression_format = self._compression_format()
        self.objects = self._objects()
        self.logged = self._logged_after_checkpoint()
        notes = []
        if self.logged:
            notes.append(
                f"{self.logged:,} metadata log "
                f"{'records follow' if self.logged != 1 else 'record follows'} "
                "the newest checkpoint. Windows applies them when it mounts the volume; "
                "this reader does not, so it shows the volume as of that checkpoint, and "
                "what changed after it is missing or older here")
        self.note = "; ".join(notes) or None

    def _hurt(self, what):
        """Record one thing that did not check out. The first REFS_DAMAGE_CAP
        are kept in ``damage``; ``damage_count`` counts every one."""
        self.damage_count += 1
        if len(self.damage) < REFS_DAMAGE_CAP:
            self.damage.append(self._where + what)

    # -- the bootstrap ------------------------------------------------------

    def _superblock(self):
        """Of the three superblock copies, at cluster 30 and two and three
        clusters from the end, the one with the highest clock (+0x68) among
        those whose own checksum holds, the first in that order on a tie
        [forefst supb.md: CmsVolume::ChooseSuperBlock]."""
        best_clock, best_lcn, best_sb = -1, None, None
        for lcn in (REFS_SUPERBLOCK_LCN, self.total_clusters - 2, self.total_clusters - 3):
            sb = read_at(self.fh, self.base + lcn * self.cluster, self.cluster)
            if len(sb) < 0x100 or sb[:4] != b"SUPB":
                continue
            doff, dlen = struct.unpack_from("<II", sb, 0x78)
            if _refs_self_checksum(sb, self.cluster, doff, dlen) is not True:
                self._hurt(f"the superblock at cluster {lcn:,} fails its own checksum")
                continue
            clock = struct.unpack_from("<Q", sb, 0x68)[0]
            if clock > best_clock:
                best_clock, best_lcn, best_sb = clock, lcn, sb
        if best_sb is None:
            raise RefsDamage("no superblock with a checksum that holds (cluster 30 and the "
                             "two backups at the end of the volume)")
        return best_lcn, best_sb

    def _checkpoint(self):
        """(cluster, page, tied clock or None) of the checkpoint with the higher
        clock (+0x60) of those whose own checksum holds [forefst chkp.md]. On
        an equal clock the driver signals a tie rather than choosing; this reads
        the first and reports the tie."""
        best_clock, best_lcn, best_cp, tie = -1, None, None, None
        size = max(self.cluster, REFS_PAGE_BYTES)
        for lcn in self.checkpoint_lcns:
            cp = read_at(self.fh, self.base + lcn * self.cluster, size)
            if len(cp) < 0x100 or cp[:4] != b"CHKP":
                self._hurt(f"no checkpoint at cluster {lcn:,}")
                continue
            doff, dlen = struct.unpack_from("<II", cp, 0x58)
            if _refs_self_checksum(cp, self.cluster, doff, dlen) is not True:
                self._hurt(f"the checkpoint at cluster {lcn:,} fails its own checksum")
                continue
            clock = struct.unpack_from("<Q", cp, 0x60)[0]
            if clock == best_clock:
                tie = clock
            elif clock > best_clock:
                best_clock, best_lcn, best_cp, tie = clock, lcn, cp, None
        if best_cp is None:
            raise RefsDamage("neither checkpoint has a checksum that holds")
        return best_lcn, best_cp, tie

    def _root(self, index):
        return self._cp, self.root_offsets[index]

    def _containers(self):
        """{container id: (first cluster, clusters in it, flags)} from the container
        table, which is addressed by real cluster numbers where the other roots
        this reads are virtual [forefst chkp.md]. The first
        cluster is the u64 16 bytes before the value's end, the count at +0x18
        [forefst container_table.md], the flags at +0x14. Its copy (root 8) is
        read if it fails."""
        out = {}
        for index in (REFS_ROOT_CONTAINERS, REFS_ROOT_CONTAINERS_COPY):
            before = self.damage_count
            try:
                for key, value, _f in self._table(*self._root(index), virtual=False):
                    if len(key) >= 8 and len(value) >= 0x20:
                        out[struct.unpack_from("<Q", key, 0)[0]] = (
                            struct.unpack_from("<Q", value, len(value) - 16)[0],
                            struct.unpack_from("<I", value, 0x18)[0],
                            struct.unpack_from("<I", value, 0x14)[0])
            except RefsDamage as exc:
                self._hurt(f"container table (root {index}): {exc}")
            if out and self.damage_count == before:
                return out
            out = {}
        raise RefsDamage("neither copy of the container table reads whole")

    def _objects(self):
        """{object id: its object table value}, from root 0 or its copy, root 5.
        A key is 16 bytes, the id in its second half [forefst object_table.md]."""
        for index in (REFS_ROOT_OBJECTS, REFS_ROOT_OBJECTS_COPY):
            before = self.damage_count
            out = {}
            try:
                for key, value, _f in self._table(*self._root(index), virtual=True):
                    if len(key) == 16 and len(value) >= 0x50:
                        out[struct.unpack_from("<Q", key, 8)[0]] = value
            except RefsDamage as exc:
                self._hurt(f"object table (root {index}): {exc}")
            if out and self.damage_count == before:
                return out
        raise RefsDamage("neither copy of the object table reads whole")

    def _check_containers(self):
        """{container id: why} for containers whose clusters cannot be where
        the table says: a first cluster not a multiple of the container size,
        a range past the end of the volume, or one overlapping another. None of
        the 34,000 containers on the six volumes measured is any of these, so
        each is reported and reading from it refused rather than trusted."""
        bad = {}
        spans = sorted((first, first + count, cid) for cid, (first, count, _f) in
                       self.containers.items())
        for i, (first, end, cid) in enumerate(spans):
            count = end - first
            if i + 1 < len(spans) and spans[i + 1][0] < end:
                bad[cid] = f"overlaps container {spans[i + 1][2]}"
                bad[spans[i + 1][2]] = f"overlaps container {cid}"
            if not count or first % count:
                bad[cid] = f"starts at cluster {first:,}, not a multiple of its {count:,} clusters"
            elif end > self.total_clusters:
                bad[cid] = f"reaches cluster {end:,}, past the volume's {self.total_clusters:,}"
        for cid, why in sorted(bad.items()):
            self._hurt(f"container {cid} {why}")
        return bad

    def _compression_format(self):
        """The volume's compression policy, the u16 at 0xA4 of the container
        table's root page (0 none, 1 LZ4, 2 ZSTD, 3 LZ4QAT) [forefst
        concepts/compression.md, container_table.md]. 0 on every volume measured."""
        try:
            page = self._page(*_refs_reference(*self._root(REFS_ROOT_CONTAINERS)), virtual=False)
        except RefsDamage:
            return None
        return struct.unpack_from("<H", page, 0xA4)[0]

    def translate(self, vlcn):
        """The cluster a virtual cluster number stands for: the container is
        the number shifted right by the bit length of the clusters in one
        container, the cluster within it the low bits [forefst
        virtual_addressing.md]."""
        if not self.containers:
            return vlcn
        cpc = next(iter(self.containers.values()))[1]
        if not cpc or cpc & (cpc - 1):
            raise RefsDamage(f"the container table gives {cpc} clusters a container")
        got = self.containers.get(vlcn >> cpc.bit_length())
        if got is None:
            raise RefsDamage(f"virtual cluster {vlcn:#x} is in no container the table maps")
        why = getattr(self, "bad_containers", {}).get(vlcn >> cpc.bit_length())
        if why:
            raise RefsDamage(f"virtual cluster {vlcn:#x} is in container "
                             f"{vlcn >> cpc.bit_length()}, which {why}")
        return got[0] + (vlcn & (got[1] - 1))

    def _page(self, slots, kind, digest, virtual):
        """One metadata page, its clusters read in slot order and checked
        against the digest its parent recorded, which must be of the kind the
        volume uses. Pages are cached under the digest they were checked
        against, so a reference carrying another digest is checked afresh."""
        if kind != self.page_kind:
            raise RefsDamage(f"a page reference records checksum kind {kind} where this volume "
                             f"uses kind {self.page_kind}, so the page cannot be checked")
        key = (slots[0], virtual, digest)
        hit = self._pages.get(key)
        if hit is not None:
            self._pages.move_to_end(key)
            return hit
        lcns = [self.translate(s) if virtual else s for s in slots[:self.page_clusters]]
        page = b"".join(read_at(self.fh, self.base + lcn * self.cluster, self.cluster)
                        for lcn in lcns)
        where = f"the page at cluster {lcns[0]:,}"
        if len(page) != self.page_clusters * self.cluster:
            raise RefsDamage(f"{where} lies past the end of the image")
        if _refs_digest_matches(kind, digest, page) is not True:
            raise RefsDamage(f"{where} does not match the checksum its parent records")
        self.pages_checked[kind] += 1
        if page[:4] != b"MSB+":
            raise RefsDamage(f"{where} is not a B+ tree page")
        self._pages[key] = page
        if len(self._pages) > 512:
            self._pages.popitem(last=False)
        return page

    def _table(self, buf, ref_off, virtual, depth=0, seen=None):
        """Every leaf row of the tree whose root page the reference at ref_off
        in buf names. An index row's value is the reference of a child page. A
        child page that does not check out is recorded in ``damage`` and its rows
        are left out; the rest of the table is still read. A page is read at
        most once in one walk, so no arrangement of references can loop, and a
        walk reads at most as many pages as the volume holds."""
        if seen is None:
            seen = set()
        slots, kind, digest = _refs_reference(buf, ref_off)
        if (slots[0], virtual) in seen:
            raise RefsDamage(f"a table names its page at cluster {slots[0]:,} twice")
        if len(seen) > self.total_clusters // self.page_clusters:
            raise RefsDamage("a table names more pages than the volume holds")
        seen.add((slots[0], virtual))
        page = self._page(slots, kind, digest, virtual=virtual)
        hoff = 0x50 + struct.unpack_from("<I", page, 0x50)[0]
        yield from self._node_rows(page, hoff, virtual, depth, "a table page", seen)

    def _node_rows(self, buf, hoff, virtual, depth, where, seen=None):
        if depth > 16:
            raise RefsDamage("a table nests deeper than any volume measured")
        if seen is None:
            seen = set()
        level, _flags, rows = _refs_node(buf, hoff, where)
        if not level:
            yield from rows
            return
        for _key, value, _f in rows:
            try:
                yield from self._table(value, 0, virtual, depth + 1, seen)
            except (RefsDamage, struct.error) as exc:
                self._hurt(str(exc))

    def _embedded(self, value, where="a record"):
        """The rows of the table held inside a row's value: its node header is
        at the u32 the value begins with, as a page's is at 0x50 [forefst
        directory_entries.md]. A node of a higher level points at child pages."""
        if len(value) < 4:
            raise RefsDamage(f"{where} is too short to hold a table")
        return list(self._node_rows(value, struct.unpack_from("<I", value, 0)[0],
                                    True, 0, where))

    # -- directories --------------------------------------------------------

    def _dir(self, oid):
        hit = self._dirs.get(oid)
        if hit is not None:
            self._dirs.move_to_end(oid)
            return hit
        value = self.objects.get(oid)
        if value is None:
            raise RefsDamage(f"directory {oid:#x} has no row in the object table")
        d = _RefsDir()
        outer, self._where = self._where, f"directory {oid:#x}: "
        try:
            rows = list(self._table(value, 0x20, virtual=True))
        finally:
            self._where = outer
        for key, val, _f in rows:
            if len(key) < 2:
                continue
            rtype = struct.unpack_from("<H", key, 0)[0]
            if rtype == 0x30 and len(key) >= 4:
                d.names[key[4:]] = (struct.unpack_from("<H", key, 2)[0], val)
            elif rtype == 0x40 and len(key) >= 24:
                d.records[struct.unpack_from("<QQ", key, 8)] = val
            elif rtype == 0x10:
                d.own = val
        self._dirs[oid] = d
        if len(self._dirs) > 32:
            self._dirs.popitem(last=False)
        return d

    def _row(self, node):
        d = self._dir(node.dir)
        got = d.names.get(node.key)
        if got is None:
            raise RefsDamage(f"no name row for {node.key.decode('utf-16-le', 'replace')!r} "
                             f"in directory {node.dir:#x}")
        return got

    def _record(self, node):
        """(record value, ordinal, home directory) for a file: the name row's own
        value when the record is in it (flag 1), else the record its directory
        of creation keeps under (ordinal, home) (flag 2)."""
        kf, val = self._row(node)
        if kf == 1:
            if len(val) < 0x88:
                raise RefsDamage("a file record shorter than its fixed fields")
            return val, struct.unpack_from("<Q", val, 0x80)[0], node.dir
        if kf == 2 and len(val) >= 0x48:
            ordinal, home = struct.unpack_from("<QQ", val, 0)
            rec = self._dir(home).records.get((ordinal, home))
            if rec is None:
                raise RefsDamage(f"file id {ordinal:#x} has no record in directory {home:#x}")
            return rec, ordinal, home
        raise RefsDamage(f"a name row with key flag {kf}, which this reader does not read")

    @staticmethod
    def _is_dir_row(kf, val):
        return (kf == 2 and len(val) >= 0x44
                and struct.unpack_from("<I", val, 0x40)[0] & REFS_ATTR_DIRECTORY)

    def _dir_reparse(self, oid):
        """(tag, data) of the reparse point a directory's own record holds, or None."""
        own = self._dir(oid).own
        return None if own is None else self._reparse_of(own)

    def listdir(self, node):
        oid = node if isinstance(node, int) else self._link_dir(node)
        out = []
        for key, (kf, val) in self._dir(oid).names.items():
            name = key.decode("utf-16-le", "replace")
            if self._is_dir_row(kf, val):
                child = struct.unpack_from("<Q", val, 8)[0]
                # A directory has one name: a row naming the root, the
                # directory itself, or a directory another one already names
                # is a tree that does not hold together. Each such row is
                # reported and left out, so no loop forms and nothing is
                # silently skipped by a walk that has seen the directory.
                had = self._dir_parent.get(child, oid) if child != REFS_ROOT_DIR else -1
                if child == oid or had != oid:
                    self._hurt(f"directory {oid:#x} names {name!r} as directory {child:#x}, "
                               + ("the root" if child == REFS_ROOT_DIR else
                                  "itself" if child == oid else
                                  f"which directory {had:#x} already names"))
                    continue
                self._dir_parent[child] = oid
                self._index_rows[child] = val
                if struct.unpack_from("<I", val, 0x40)[0] & REFS_ATTR_REPARSE:
                    got = self._dir_reparse(child)
                    if got is not None and got[0] in (REFS_TAG_SYMLINK, REFS_TAG_MOUNT_POINT):
                        out.append((name, RefsEntry(oid, key)))
                        continue
                out.append((name, child))
            elif kf in (1, 2):
                out.append((name, RefsEntry(oid, key)))
        return out

    def _link_dir(self, node):
        kf, val = self._row(node)
        if not self._is_dir_row(kf, val):
            raise RefsDamage("not a directory")
        return struct.unpack_from("<Q", val, 8)[0]

    # -- one file -----------------------------------------------------------

    def _attributes_of(self, record):
        """The rows of a file record's own table, as (marker, type, key, value).
        A key begins with a u64 this does not use, then the marker
        (0x80000001 or 0x80000002) and the attribute type [forefst
        directory_entries.md, NAMED_DATA.md]; other keys read as marker 0."""
        out = []
        for key, value, _f in self._embedded(record):
            if len(key) >= 16:
                marker, atype = struct.unpack_from("<IH", key, 8)
                if marker not in (0x80000001, 0x80000002):
                    marker, atype = 0, None
            else:
                marker, atype = 0, None
            out.append((marker, atype, key, value))
        return out

    @staticmethod
    def _inline(value):
        """(size, bytes) of an attribute held in its row: size at +0x20, the
        content at +8's offset plus +0x0C's summary size [forefst
        NAMED_DATA.md, which the $DATA row shares]."""
        if len(value) < 0x28:
            raise RefsDamage("an inline stream row shorter than its header")
        size = struct.unpack_from("<Q", value, 0x20)[0]
        start = sum(struct.unpack_from("<II", value, 8))
        if size > REFS_MAX_FILE_BYTES:
            raise RefsDamage(f"a stream of {size:,} bytes, more than ReFS allows a file")
        data = value[start:start + size]
        if len(data) != size:
            raise RefsDamage("an inline stream runs past its row")
        return size, data

    def _extent_stream(self, value):
        """(size, valid length, value) of a stream held in extents. The value
        is a table: a header with the sizes (total allocation +0x30, size +0x38,
        valid length +0x40 [forefst extent_descriptors.md, ReFS 3.7+ layout])
        and a node of extent records, which _extents() reads. The sizes are
        read here and the map only when it is needed, so a file whose map does
        not check out is still listed with its size."""
        if len(value) < 0x58:
            raise RefsDamage("a stream record shorter than its header")
        if struct.unpack_from("<I", value, 0x0C)[0] != 0x200:
            raise RefsDamage("a stream record laid out other than as ReFS 3.14 writes it "
                             f"(summary size {struct.unpack_from('<I', value, 0x0C)[0]:#x})")
        size, valid = struct.unpack_from("<QQ", value, 0x38)
        if size > REFS_MAX_FILE_BYTES or valid > REFS_MAX_FILE_BYTES:
            raise RefsDamage(f"a stream of {max(size, valid):,} bytes, more than ReFS allows a "
                             "file (35 PB, Microsoft's ReFS overview)")
        return size, valid, value, ()

    def _extents(self, value, older=()):
        """The sorted (file cluster, run length, virtual cluster, flags) of a
        stream record's map, with the clusters it does not hold itself taken
        from the snapshot records in ``older``, newest first (see
        _main_stream). A record of a level-0 node of 24-byte extent
        records: the virtual cluster, flags, record size, the file's cluster
        and the run length. Once the map outgrows the record its node is of a
        higher level, each row's value the reference of a child page that holds
        the same kind of node [forefst extent_descriptors.md]."""
        out = []
        self._extent_node(value, struct.unpack_from("<I", value, 0)[0], out, 0, set())
        out.sort()
        _refs_no_overlap(out)
        for snap in older:
            held = [(vcn, vcn + run) for vcn, run, _v, f in out if not f & 0x20]
            theirs = []
            self._extent_node(snap, struct.unpack_from("<I", snap, 0)[0], theirs, 0, set())
            theirs.sort()
            _refs_no_overlap(theirs)
            for vcn, run, vlcn, eflags in theirs:
                if eflags & 0x20:
                    continue
                for a, b in _refs_uncovered(vcn, vcn + run, held):
                    out.append((a, b - a, vlcn + (a - vcn), eflags))
            out.sort()
        if older:                               # a hole is now a gap no version fills
            out = [e for e in out if not e[3] & 0x20]
        return out

    def _extent_node(self, buf, hoff, out, depth, seen):
        if hoff + 0x24 > len(buf):
            raise RefsDamage("a stream's extent node lies outside what holds it")
        level, flags = buf[hoff + 0x0C], buf[hoff + 0x0D]
        if level:
            if depth > 8:
                raise RefsDamage("an extent map nests deeper than any volume measured")
            for _key, val, _f in _refs_node(buf, hoff, "an extent map")[2]:
                slots, kind, digest = _refs_reference(val, 0)
                if slots[0] in seen:
                    raise RefsDamage(f"an extent map names its page at cluster {slots[0]:,} twice")
                seen.add(slots[0])
                page = self._page(slots, kind, digest, virtual=True)
                self._extent_node(page, 0x50 + struct.unpack_from("<I", page, 0x50)[0],
                                  out, depth + 1, seen)
            return
        if not flags & 0x04:
            raise RefsDamage("a stream's extent node is not marked as one")
        start, count = struct.unpack_from("<II", buf, hoff + 0x10)
        end = struct.unpack_from("<I", buf, hoff + 0x20)[0]
        if end == 0:
            end = start + 4 * count
        if end < start or (end - start) // 4 != count or hoff + end > len(buf):
            raise RefsDamage("a stream's extent index does not hold the rows it counts")
        for i in range(count):
            pos = hoff + (struct.unpack_from("<I", buf, hoff + start + 4 * i)[0] & 0xFFFF)
            if pos + 24 > len(buf):
                raise RefsDamage("an extent record runs past what holds it")
            vlcn, eflags, _rsize, vcn, _pad, run = struct.unpack_from("<QHHIII", buf, pos)
            out.append((vcn, run, vlcn, eflags))

    def _main_stream(self, record):
        """("inline", size, bytes), ("extents", size, valid, record) or
        ("empty", 0) for the unnamed $DATA: an inline row (marker 0x80000001,
        type 0x80) or the row of sub-stream 0x1000 (marker 0x80000002), the
        live one beside any snapshots [forefst extent_descriptors.md]."""
        attrs = self._attributes_of(record)
        for marker, atype, key, value in attrs:
            if atype == 0x80 and marker == 0x80000001:
                return ("inline",) + self._inline(value)
        live, snaps = None, []
        for marker, atype, key, value in attrs:
            if atype == 0x80 and marker == 0x80000002 and len(key) >= 0x18:
                sub = struct.unpack_from("<Q", key, 0x10)[0]
                if sub == REFS_LIVE_STREAM:
                    live = value
                elif sub > REFS_LIVE_STREAM:
                    snaps.append((sub, value))
        if live is not None:
            # A snapshotted file's live stream holds only the clusters written
            # since the last snapshot; for the rest the driver reads the most
            # recent snapshot that holds them, and the snapshots' sub-stream ids
            # rise with age, 0x1001 the oldest [forefst concepts/
            # snapshots_versioning.md, structures/extent_descriptors.md].
            size, valid, value, _none = self._extent_stream(live)
            older = []
            for sub, v in sorted(snaps, reverse=True):
                if len(v) < 0x58 or struct.unpack_from("<I", v, 0x0C)[0] != 0x200:
                    raise RefsDamage(f"the record of snapshot stream {sub:#x} is not one this "
                                     "reader can read, so the file's live content cannot be "
                                     "put together")
                older.append(v)
            older = tuple(older)
            return ("extents", size, valid, value, older)
        size = struct.unpack_from("<Q", record, 0x58)[0] if len(record) >= 0x60 else 0
        if size:
            raise RefsDamage(f"a record of {size:,} bytes with no $DATA this reader finds")
        return ("empty", 0)

    def _named(self, record):
        """{name: (row value, attrs)} of the alternate data streams: type 0xB0
        rows whose stream summary flags (+0x10) are 0, not 2, which marks a
        snapshot [forefst NAMED_DATA.md]."""
        attrs = self._attributes_of(record)
        out = collections.OrderedDict()
        for marker, atype, key, value in attrs:
            if atype == 0xB0 and marker == 0x80000002 and len(value) >= 0x28:
                if struct.unpack_from("<H", value, 0x10)[0] == 0:
                    out[key[0x10:].decode("utf-16-le", "replace")] = value
        return out, attrs

    def _stream_owner(self, ref):
        """The record that holds a stream: its file's, or a directory's own."""
        if isinstance(ref.file, int):
            own = self._dir(ref.file).own
            if own is None:
                raise RefsDamage(f"directory {ref.file:#x} has no record of its own")
            return own
        return self._record(ref.file)[0]

    def _named_stream(self, record, name):
        named, attrs = self._named(record)
        value = named.get(name)
        if value is None:
            raise RefsDamage(f"no stream named {name!r}")
        if not struct.unpack_from("<H", value, 2)[0] & 0x1000:
            return ("inline",) + self._inline(value)
        # Held in extents: the extents are in a row of their own that names no
        # stream. forefst (NAMED_DATA.md) ties the two by the stream's size; the
        # allocation is required to agree as well, and a tie is refused.
        size, alloc = struct.unpack_from("<Q", value, 0x20)[0], struct.unpack_from("<Q", value, 0x18)[0]
        found = []
        for marker, _atype, _key, val in attrs:
            if marker == 0 and len(val) >= 0x58 and struct.unpack_from("<I", val, 0x0C)[0] == 0x200:
                if struct.unpack_from("<QQ", val, 0x30) == (alloc, size):
                    found.append(val)
        if len(found) != 1:
            raise RefsDamage(f"the stream {name!r} is held in extents and "
                             f"{len(found)} extent records match its size, so which one "
                             "holds it cannot be told")
        return ("extents",) + self._extent_stream(found[0])

    def _read_stream(self, stream, want, sparse=True, name=""):
        if stream[0] == "empty":
            return
        if stream[0] == "inline":
            if want:
                yield stream[2][:want]
            return
        size, valid, extents = stream[1], stream[2], self._extents(stream[3], stream[4])
        want = min(want, size)
        reach = max((vcn + run for vcn, run, _l, _f in extents), default=0) * self.cluster
        if reach > struct.unpack_from("<Q", stream[3], 0x30)[0]:
            # On every stream of the six volumes measured the map ends within
            # the stream's total allocation (+0x30).
            self._hurt(f"{name}: its extents reach {reach:,} bytes, past the "
                       f"{struct.unpack_from('<Q', stream[3], 0x30)[0]:,} its record allocates")
        if not sparse:
            # A file that is not sparse has an extent, written or not, for
            # every cluster of its size; a range none covers is a map that
            # does not hold together [forefst extent_descriptors.md, "A sparse
            # file's entries tile only its allocated clusters"]. It still reads
            # as zeros, and is reported.
            covered = [(vcn, vcn + run) for vcn, run, _l, _f in extents]
            need = -(-size // self.cluster)
            for a, b in _refs_uncovered(0, need, covered):
                self._hurt(f"{name}: no extent covers clusters {a:,} to {b - 1:,} of a file not "
                           "marked sparse; they read as zeros")
                break
        for piece, at in self._stream_pieces(extents, want):
            if at + len(piece) > valid:                   # past the valid length reads as zeros
                keep = max(0, valid - at)
                piece = piece[:keep] + bytes(len(piece) - keep)
            yield piece

    def _stream_pieces(self, extents, want):
        """(bytes, offset) over the first want bytes of a stream in extents,
        in file order. A range no extent covers is a hole and reads as zeros."""
        cl = self.cluster
        pos = 0
        for vcn, run, vlcn, eflags in extents:
            if pos >= want:
                break
            at, end = vcn * cl, min((vcn + run) * cl, want)
            if at > pos:                                  # a hole before this run
                for z in _refs_zeros(min(at, want) - pos):
                    yield z, pos
                    pos += len(z)
            if end <= pos:
                continue
            # bit 0x20 is a sparse hole; a known flags word without bit 0x10 is a
            # run allocated but not yet written, which reads as zeros [forefst
            # extent_descriptors.md]. Both occur on forefst's sample volumes, where
            # 32 unwritten runs lie over clusters holding bytes that are not the
            # file's (a script's file header mid-file, a B+ tree page).
            if eflags & 0x20 or (eflags and not eflags & 0x10):
                for z in _refs_zeros(end - pos):
                    yield z, pos
                    pos += len(z)
                continue
            if not vlcn:
                raise RefsDamage("an extent at virtual cluster 0 that is not marked a hole")
            first, skip = divmod(pos - at, cl)
            for chunk in self._clusters(vlcn + first, (end - pos + skip + cl - 1) // cl):
                piece = chunk[skip:skip + end - pos]
                skip = 0
                yield piece, pos
                pos += len(piece)
                if pos >= end:
                    break
        for z in _refs_zeros(want - pos):
            yield z, pos
            pos += len(z)

    def _container_flags(self, vlcn):
        """The container table's flags (+0x14) for the container holding vlcn.
        forefst (concepts/compression.md) says a container holding compressed
        data is marked by bit 0x800 of the in-memory flags word loaded from the
        container table row; that the bit is this field's is inferred, and no
        container on the six volumes measured carries it."""
        if not self.containers:
            return 0
        cpc = next(iter(self.containers.values()))[1]
        got = self.containers.get(vlcn >> cpc.bit_length())
        return got[2] if got is not None and len(got) > 2 else 0

    def _clusters(self, vlcn, n):
        """Bytes of n clusters from virtual cluster vlcn, at most 1 MiB a read.
        A run must end within its container: the virtual number of the
        cluster after a container's last is not a cluster of the next one,
        since translation shifts by one bit more than the in-container offset
        holds [forefst virtual_addressing.md, IsValidContainerLcn]. No run on
        the six volumes measured crosses, so one that does is refused."""
        step = max(1, (1 << 20) // self.cluster)
        if self.containers:
            cpc = next(iter(self.containers.values()))[1]
            if (vlcn & (cpc - 1)) + n > cpc:
                raise RefsDamage(f"a run of {n:,} clusters from virtual cluster {vlcn:#x} "
                                 "crosses the end of its container")
        while n > 0:
            take = min(n, step)
            lcn = self.translate(vlcn)
            if self._container_flags(vlcn) & REFS_CONTAINER_COMPRESSED:
                raise RefsDamage(f"virtual cluster {vlcn:#x} lies in a container marked compressed, "
                                 "whose clusters this reader does not decompress")
            data = read_at(self.fh, self.base + lcn * self.cluster, take * self.cluster)
            if len(data) < take * self.cluster:
                data += bytes(take * self.cluster - len(data))
            yield data
            vlcn += take
            n -= take

    def _reparse_of(self, record):
        """(tag, data) of a record's reparse row (type 0xC0): the reparse buffer
        at the row's content offset, tag then data length then data, as NTFS
        keeps it [MS-FSCC 2.1.2]."""
        for marker, atype, _key, value in self._attributes_of(record):
            if atype == 0xC0 and marker == 0x80000001 and len(value) >= 0x10:
                at = struct.unpack_from("<I", value, 8)[0]
                if at + 8 <= len(value):
                    tag, length = struct.unpack_from("<IH", value, at)
                    return tag, value[at + 8:at + 8 + length]
        return None

    @staticmethod
    def _link_target(tag, data):
        """The target a symbolic link or mount point names: its print name, or
        the substitute name when that is empty [MS-FSCC 2.1.2.4, 2.1.2.5]."""
        if len(data) < 8:
            return ""
        so, sl, po, pl = struct.unpack_from("<4H", data, 0)
        path = data[12:] if tag == REFS_TAG_SYMLINK else data[8:]
        name = path[po:po + pl] or path[so:so + sl]
        return name.decode("utf-16-le", "replace")

    def _kind(self, node):
        """("link", target) or ("file", record, ordinal, home) for a RefsEntry."""
        kf, val = self._row(node)
        if self._is_dir_row(kf, val):
            got = self._dir_reparse(struct.unpack_from("<Q", val, 8)[0])
            return ("link", self._link_target(*got) if got else "")
        rec, ordinal, home = self._record(node)
        got = self._reparse_of(rec)
        if got is not None and got[0] in (REFS_TAG_SYMLINK, REFS_TAG_MOUNT_POINT):
            return ("link", self._link_target(*got))
        return ("file", rec, ordinal, home)

    def _times_of(self, value):
        if len(value) < 0x48:
            return (0, 0, 0, 0)
        return struct.unpack_from("<4Q", value, 0x28)

    def filetimes(self, node):
        """The four FILETIMEs as stored, (created, modified, changed, accessed).

        A file's are the four at +0x28 to +0x40 of its record, which ReFS
        updates at once; a name row of a moved or linked file keeps a copy that
        is refreshed only when that name is opened, so it can be older
        [forefst concepts/hard_links.md, directory_entries.md]. A directory's are
        those of its own record, except the change time: Windows reports the
        copy in the directory's name row in its parent (+0x20), which forefst
        measured against PowerShell (attributes/STANDARD_INFORMATION.md, 0x10);
        on the fixture Windows wrote here the two copies never differ. The
        root has no name row. A stream has its file's times."""
        if isinstance(node, RefsStreamRef):
            node = node.file
        if isinstance(node, int):
            return self._dir_times(node, self._index_rows.get(node))
        kf, val = self._row(node)
        if self._is_dir_row(kf, val):
            return self._dir_times(struct.unpack_from("<Q", val, 8)[0], val)
        return self._times_of(self._record(node)[0])

    def _dir_times(self, oid, row):
        own = self._dir(oid).own
        times = list(self._times_of(own)) if own is not None else [0, 0, 0, 0]
        if row is not None and len(row) >= 0x28:
            times[2] = struct.unpack_from("<Q", row, 0x20)[0]
        return tuple(times)

    def stamps(self, node):
        """(created, modified, accessed) in Unix seconds, 0 where unset, as
        NtfsWalker.stamps gives them."""
        c, m, _ch, a = self.filetimes(node)
        return ntfs_time(c), ntfs_time(m), ntfs_time(a)

    def inode(self, node):
        return node

    def entry(self, node):
        """(mode, size, mtime). When a file's record does not check out, what is
        wrong is added to ``damage`` and the file is still listed, with the size
        and modified time its name row holds, so a listing shows it and reading
        it fails with the reason; None only when not even that row is there."""
        try:
            return self._entry(node)
        except (RefsDamage, struct.error, IndexError) as exc:
            self._hurt(f"{self._name_of(node)}: {exc}")
        if isinstance(node, RefsEntry):
            try:
                kf, val = self._row(node)
            except (RefsDamage, struct.error, IndexError):
                return None
            if kf == 2 and len(val) >= 0x40:            # an index entry: size +0x38, times +0x10
                return (0o100644, struct.unpack_from("<Q", val, 0x38)[0],
                        ntfs_time(struct.unpack_from("<Q", val, 0x18)[0]))
            if kf == 1 and len(val) >= 0x60:            # its own record: size +0x58, times +0x28
                return (0o100644, struct.unpack_from("<Q", val, 0x58)[0],
                        ntfs_time(self._times_of(val)[1]))
        return None

    @staticmethod
    def _name_of(node):
        if isinstance(node, RefsStreamRef):
            return f"{RefsWalker._name_of(node.file)}:{node.name}"
        if isinstance(node, RefsEntry):
            return f"{node.key.decode('utf-16-le', 'replace')!r} in directory {node.dir:#x}"
        return f"directory {node:#x}"

    def _entry(self, node):
        if isinstance(node, int):
            if node not in self.objects:
                raise RefsDamage("no row in the object table")
            return (S_IFDIR | 0o755, 0, ntfs_time(self.filetimes(node)[1]))
        if isinstance(node, RefsStreamRef):
            rec = self._stream_owner(node)
            stream = self._named_stream(rec, node.name)
            return (0o100644, stream[1], ntfs_time(self._times_of(rec)[1]))
        got = self._kind(node)
        mtime = ntfs_time(self.filetimes(node)[1])
        if got[0] == "link":
            return (S_IFLNK | 0o777, len(got[1].encode("utf-8")), mtime)
        return (0o100644, self._main_stream(got[1])[1], mtime)

    def data_form(self, node):
        """How a file's unnamed $DATA is held: "inline" in its record, in
        "extents", or "empty"; None for a directory or a link."""
        if not isinstance(node, RefsEntry):
            return None
        got = self._kind(node)
        return self._main_stream(got[1])[0] if got[0] == "file" else None

    def readlink(self, node):
        got = self._kind(node) if isinstance(node, RefsEntry) else ("file",)
        return got[1] if got[0] == "link" else ""

    def read_file(self, node, size):
        """The content, refused with a reason (RefsDamage) when the records do
        not check out, the file is encrypted (FILE_ATTRIBUTE_ENCRYPTED: what is
        on disk is ciphertext), or the data lies in a compressed container."""
        try:
            if isinstance(node, RefsStreamRef):
                rec = self._stream_owner(node)
                stream = self._named_stream(rec, node.name)
            else:
                got = self._kind(node)
                if got[0] != "file":
                    return
                rec = got[1]
                stream = self._main_stream(rec)
            attrs = self._refuse_unreadable(rec)
            yield from self._read_stream(stream, size, bool(attrs & REFS_ATTR_SPARSE),
                                         self._name_of(node))
        except (struct.error, IndexError) as exc:
            raise RefsDamage(f"{self._name_of(node)}: a record field lies outside its row "
                             f"({exc})") from exc

    @staticmethod
    def _refuse_unreadable(record):
        """The record's attributes, after refusing a file whose content is
        ciphertext: FILE_ATTRIBUTE_ENCRYPTED [MS-FSCC] 2.6, which ReFS sets for
        EFS on Windows Server 2025 (Microsoft's ReFS overview)."""
        attrs = struct.unpack_from("<I", record, 0x48)[0]
        if attrs & REFS_ATTR_ENCRYPTED:
            raise RefsDamage("the file is encrypted (EFS), so what is on disk is ciphertext "
                             "and is not read")
        return attrs

    def named_streams(self, node):
        """[(name, size)] of a file's alternate data streams, or of a directory's.
        A record that does not check out is added to ``damage`` and gives []."""
        try:
            return self._named_streams(node)
        except (RefsDamage, struct.error, IndexError) as exc:
            self._hurt(f"{self._name_of(node)}: {exc}")
            return []

    def _named_streams(self, node):
        if isinstance(node, int):
            own = self._dir(node).own
            if own is None:
                return []
            rec = own
        elif isinstance(node, RefsEntry):
            got = self._kind(node)
            if got[0] != "file":
                return []
            rec = got[1]
        else:
            return []
        out = []
        for name, value in self._named(rec)[0].items():
            out.append((name, struct.unpack_from("<Q", value, 0x20)[0]))
        return out

    def stream_ref(self, node, name):
        """The node of one alternate data stream, for entry() and read_file()."""
        return RefsStreamRef(node, name)

    def attributes(self, node):
        """The file attribute bits a record stores (+0x48), as stored. A
        directory's name row sets 0x10000000 where Windows reports 0x10."""
        if isinstance(node, RefsStreamRef):
            node = node.file
        if isinstance(node, int):
            own = self._dir(node).own
            return struct.unpack_from("<I", own, 0x48)[0] if own is not None else 0
        kf, val = self._row(node)
        if self._is_dir_row(kf, val):
            return struct.unpack_from("<I", val, 0x40)[0]
        return struct.unpack_from("<I", self._record(node)[0], 0x48)[0]

    def file_id(self, node):
        """(id, directory object id), the two halves of the 128-bit file id
        Windows reports: 0 and its own object id for a directory, the file's id
        in its directory of creation and that directory's for a file."""
        if isinstance(node, int):
            return (0, node)
        kf, val = self._row(node)
        if self._is_dir_row(kf, val):
            return (0, struct.unpack_from("<Q", val, 8)[0])
        _rec, ordinal, home = self._record(node)
        return (ordinal, home)

    def link_count(self, node):
        """How many names a file's record lists (type 0x39 rows, each a parent
        and a name), or 1 for a record that lists none, which is how a file
        never moved or linked is kept. Measured, not documented: it matches the
        link count Windows reports for every file of the fixture."""
        if isinstance(node, int):
            return 1
        got = self._kind(node)
        if got[0] != "file":
            return 1
        n = sum(1 for _m, atype, _k, _v in self._attributes_of(got[1]) if atype == 0x39)
        return n or 1

    def allocation(self, node):
        """What the volume stores for a file beside the size it records, with
        the keys NtfsWalker.allocation uses. ``stored`` is the stream's own
        allocation as its record holds it, which counts reserved runs that
        read as zeros, plus any clusters a snapshotted file reads from its
        snapshots; or the bytes of an inline stream. It equals the allocation
        Windows reported for every file in extents on the fixture, and
        forefst's allocated size on its four sample volumes. ``sparse`` is the
        file's sparse attribute."""
        if isinstance(node, RefsStreamRef):
            rec = self._stream_owner(node)
            stream = self._named_stream(rec, node.name)
        else:
            got = self._kind(node)
            if got[0] != "file":
                return None
            rec = got[1]
            stream = self._main_stream(rec)
        attrs = struct.unpack_from("<I", rec, 0x48)[0]
        reparse = self._reparse_of(rec)
        stored = 0
        if stream[0] == "inline":
            stored = len(stream[2])
        elif stream[0] == "extents":
            # The stream's own allocation (+0x48 of its record [forefst
            # extent_descriptors.md]) counts runs reserved as well as written;
            # a snapshotted file adds the clusters it reads from its snapshots,
            # which the record counts as the snapshots' [forefst
            # concepts/snapshots_versioning.md].
            own = sum(run for _v, run, _l, f in self._extents(stream[3]) if not f & 0x20)
            merged = sum(run for _v, run, _l, f in self._extents(stream[3], stream[4])
                         if not f & 0x20)
            stored = struct.unpack_from("<Q", stream[3], 0x48)[0] + (merged - own) * self.cluster
        return {"size": stream[1], "stored": stored,
                "sparse": bool(attrs & 0x200), "compression": "",
                "reparse_tag": reparse[0] if reparse else None,
                "attributes": attrs, "placeholder": False}

    def volume_label(self):
        """The label from the volume information table (object 0x500, row
        0x510), or None when it cannot be read [forefst volume_info.md]."""
        value = self.objects.get(REFS_VOLUME_INFO)
        if value is None:
            return None
        try:
            for key, val, _f in self._table(value, 0x20, virtual=True):
                if key[:2] == b"\x10\x05":
                    return val.decode("utf-16-le", "replace").split("\x00")[0]
        except RefsDamage:
            return None
        return ""

    # -- the metadata log ---------------------------------------------------

    def _log_control_lcns(self):
        """Where the log's two control pages are: the fourth and fifth u64 of
        row 1 of the logfile information table (object 0x9), which forefst
        (mlog.md) says holds the log's areas. That those two are the control
        pages is measured, not documented: they name the pages forefst's mlog
        report shows on two of its sample volumes, and 0x30 and 0x31 on the
        other two and on both Windows 11 fixtures here. When the row cannot be
        read, 0x30 and 0x31 are tried."""
        value = self.objects.get(REFS_LOGFILE_INFO)
        try:
            for key, val, _f in (self._table(value, 0x20, virtual=True) if value else ()):
                if key[:4] == b"\x01\x00\x00\x00" and len(val) >= 0x28:
                    return struct.unpack_from("<QQ", val, 0x18)
        except RefsDamage as exc:
            self._hurt(f"logfile information table: {exc}")
        return REFS_LOG_CONTROL_LCNS

    def _logged_after_checkpoint(self):
        """How many log records follow the checkpoint's log position (+0x70),
        each found where that position puts it, carrying that position, the one
        before it as its predecessor, and a check value that holds; or None when
        the log's control page is not found.

        The control page (signature "MLog", type 1) gives the data area's first
        cluster at +8 of its payload; a record is at that cluster plus the low
        32 bits of its position in 4 KiB log blocks, and its length in blocks is
        at +0x38 [forefst mlog.md]. A volume Windows detached cleanly has no
        record there; refs-test.vhdx, detached seconds after its files were
        written, has 16. This counts what is present; it decodes none of it.
        """
        ctl_seq, area, block = -1, None, 0x1000
        for lcn in self._log_control_lcns():
            page = read_at(self.fh, self.base + lcn * self.cluster, 0x1000)
            if len(page) < 0x1000 or page[:4] != b"MLog" or not _refs_log_check(page):
                continue
            eh = struct.unpack_from("<I", page, 0x54)[0]
            if eh + 0x38 > len(page) or struct.unpack_from("<I", page, eh + 0x30)[0] != 1:
                continue
            pay = eh + struct.unpack_from("<I", page, eh + 0x28)[0]
            if pay + 0x18 > len(page):
                continue
            seq = struct.unpack_from("<Q", page, 0x20)[0]
            if seq > ctl_seq:
                ctl_seq, area = seq, struct.unpack_from("<QQ", page, pay + 8)
                block = struct.unpack_from("<I", page, 0x0C)[0] or 0x1000
        if area is None:
            return None
        start, end = area
        lsn, prev, count = self.checkpoint_lsn, None, 0
        while count < 1 << 20:
            off = start * self.cluster + (lsn & 0xFFFFFFFF) * block
            if off >= end * self.cluster:
                break
            rec = read_at(self.fh, self.base + off, block)
            if len(rec) < block or rec[:4] != b"MLog" or not _refs_log_check(rec):
                break
            got, before, length = struct.unpack_from("<QQI", rec, 0x28)
            if got != lsn or (prev is not None and before != prev) or not length:
                break
            count += 1
            prev, lsn = lsn, lsn + length
        return count


def _refs_version_refusal(major, minor):
    """Why a volume of this version is not read, or None. Format 1 and 2 keep
    their metadata in another layout [libfsrefs]; past 3.14 nothing describes
    the format, and the boot sector's version is critical to a mount [forefst
    vbr.md], so a newer one is refused by name rather than read as 3.14."""
    if major < 3:
        return (f"ReFS {major}.{minor}: volumes before format 3 keep their metadata in "
                "another layout (libfsrefs documents it as format version 1), which this "
                "reader does not read")
    if major > 3 or minor > REFS_NEWEST_MINOR:
        return (f"ReFS {major}.{minor}: newer than ReFS 3.{REFS_NEWEST_MINOR}, the newest "
                "version any source describes or any volume this was checked against carries")
    return None


def _refs_no_overlap(extents):
    """Refuse a sorted map in which two extents cover one file cluster, or a
    run that reaches past the largest file ReFS allows."""
    end = 0
    for vcn, run, _vlcn, _flags in extents:
        if vcn < end:
            raise RefsDamage(f"two extents of the map cover file cluster {vcn:,}, so which "
                             "holds its bytes cannot be told")
        end = vcn + run
    if end and end > REFS_MAX_FILE_BYTES // 512:
        raise RefsDamage("an extent reaches past the largest file ReFS allows")


def _refs_uncovered(lo, hi, held):
    """The parts of [lo, hi) that no (start, end) in held covers."""
    out, pos = [], lo
    for a, b in sorted(held):
        if b <= pos or a >= hi:
            continue
        if a > pos:
            out.append((pos, a))
        pos = max(pos, b)
        if pos >= hi:
            break
    if pos < hi:
        out.append((pos, hi))
    return out


def _refs_zeros(n):
    while n > 0:
        take = min(n, 1 << 20)
        yield bytes(take)
        n -= take


def _refs_boot_checksum(boot):
    """The boot sector's own 16-bit check: rotate right one bit, then add each
    byte from 3 to 511 except the field at 0x16 [forefst vbr.md]."""
    c = 0
    for i in range(3, 512):
        if i in (0x16, 0x17):
            continue
        c = (((c >> 1) | (c << 15)) + boot[i]) & 0xFFFF
    return c


def _refs_log_check(page):
    """Whether a log block's check value (+8 of the entry header named at 0x54)
    holds: the block's u64 words folded by xor into four lanes, the lanes
    xored together and the halves folded [forefst mlog.md, "Verifying a record"].
    A record is one log block, so the chained seed is always 0 here."""
    eh = struct.unpack_from("<I", page, 0x54)[0]
    if eh + 0x10 > len(page) or len(page) % 32:
        return False
    body = bytearray(page)
    want = struct.unpack_from("<Q", body, eh + 8)[0]
    body[eh + 8:eh + 16] = bytes(8)
    lanes = [0, 0, 0, 0]
    for i, word in enumerate(struct.unpack(f"<{len(body) // 8}Q", body)):
        lanes[i & 3] ^= word
    v = lanes[0] ^ lanes[1] ^ lanes[2] ^ lanes[3]
    return want == (v >> 32) ^ (v & 0xFFFFFFFF)


class _RefsSparseImage:
    """The committed ReFS fixtures: a partition of which only the bytes the
    reader reads are kept, each at its own offset (tools/make_refs_fixture.py).
    A gzip of b"QNXPROBE-SPARSE 1\\n", a line of JSON with the partition size
    and the [offset, length] runs, then the runs' bytes. Every other byte reads
    as zero. Read only, like every image this tool opens."""

    def __init__(self, raw):
        magic, rest = raw.split(b"\n", 1)
        if magic != b"QNXPROBE-SPARSE 1":
            raise ValueError("not a qnxprobe sparse fixture")
        head, self.data = rest.split(b"\n", 1)
        self.head = json.loads(head)
        self.size, self.pos = self.head["size"], 0
        self.starts, self.runs, at = [], [], 0
        for off, n in self.head["runs"]:
            self.starts.append(off)
            self.runs.append((off, n, at))
            at += n
        if at != len(self.data):
            raise ValueError("the fixture's runs do not add up to its bytes")

    def patched(self, off, data):
        """A copy with data written at off, for the checks that break the
        fixture on purpose: within one run, or wholly outside every run, where
        it becomes a run of its own."""
        copy = object.__new__(_RefsSparseImage)
        copy.__dict__.update(self.__dict__)
        i = bisect.bisect_right(self.starts, off) - 1
        if i >= 0 and off + len(data) <= self.runs[i][0] + self.runs[i][1]:
            start, _n, at = self.runs[i]
            body = bytearray(self.data)
            body[at + off - start:at + off - start + len(data)] = data
            copy.data, copy.pos = bytes(body), 0
            return copy
        if (i >= 0 and off < self.runs[i][0] + self.runs[i][1]) or (
                i + 1 < len(self.runs) and off + len(data) > self.runs[i + 1][0]):
            raise ValueError("a patch that straddles the fixture's runs")
        runs = sorted([(o, n) for o, n, _a in self.runs] + [(off, len(data))])
        pieces, copy.starts, copy.runs, at = [], [], [], 0
        for o, n in runs:
            pieces.append(data if o == off else self._run_bytes(o, n))
            copy.starts.append(o)
            copy.runs.append((o, n, at))
            at += n
        copy.data, copy.pos = b"".join(pieces), 0
        return copy

    def _run_bytes(self, off, n):
        for start, length, at in self.runs:
            if start == off and length == n:
                return self.data[at:at + n]
        raise ValueError("no such run")

    def seek(self, off, whence=0):
        self.pos = off if whence == 0 else self.pos + off if whence == 1 else self.size + off
        return self.pos

    def tell(self):
        return self.pos

    def read(self, n=-1):
        end = self.size if n is None or n < 0 else min(self.size, self.pos + n)
        out = bytearray(max(0, end - self.pos))
        i = max(0, bisect.bisect_right(self.starts, self.pos) - 1)
        while i < len(self.runs) and self.runs[i][0] < end:
            start, length, at = self.runs[i]
            lo, hi = max(start, self.pos), min(start + length, end)
            if lo < hi:
                out[lo - self.pos:hi - self.pos] = self.data[at + lo - start:at + hi - start]
            i += 1
        self.pos = end
        return bytes(out)


def identify_refs(fh, base, size=None):
    """("refs", lines) for a ReFS volume at base, else None.

    ReFS names itself at byte 3 of its boot sector and carries "FSRS" at 0x10;
    both are required. A format 1.x or 2.x volume is named and refused.
    """
    del size
    b = read_at(fh, base, 512)
    if len(b) < 512 or b[3:11] != REFS_FS_NAME or b[0x10:0x14] != REFS_FSRS:
        return None
    sectors, bps, spc = struct.unpack_from("<QII", b, 0x18)
    major, minor = b[0x28], b[0x29]
    lines = [f"version      ReFS {major}.{minor} (boot sector)",
             f"bytes/sector {bps}   sectors/cluster {spc}   cluster {bps * spc:,} bytes",
             f"volume       {human(sectors * bps)} ({sectors:,} sectors)",
             f"serial       {struct.unpack_from('<Q', b, 0x38)[0]:016x}"]
    if struct.unpack_from("<H", b, 0x16)[0] != _refs_boot_checksum(b):
        lines.append("boot sector  its checksum does not hold")
    why_not = _refs_version_refusal(major, minor)
    if why_not:
        lines.append(f"contents     not read: {why_not}")
        return "refs", lines
    try:
        w = RefsWalker(fh, base)
    except (ValueError, OSError, struct.error) as exc:
        lines.append(f"walk         not possible: {exc}")
        return "refs", lines
    label = w.volume_label()
    if label is not None:
        lines.append(f"label        {label or '(none)'}")
    lines.append(f"checkpoint   clock {w.clock:,} at cluster {w.checkpoint_lcn:,}, "
                 f"written as ReFS {w.checkpoint_version[0]}.{w.checkpoint_version[1]}")
    if w.checkpoint_tie is not None:
        lines.append(f"checkpoint   both checkpoints carry clock {w.checkpoint_tie:,}; the driver "
                     "reports such a tie rather than choosing, and the first listed was read")
    if w.compression_format:
        lines.append(f"compression  the volume's policy names format {w.compression_format}; "
                     "data in a container marked compressed is not read")
    if w.logged is None:
        lines.append("log          its control page was not found, so whether changes "
                     "follow the checkpoint is not known")
    elif w.logged:
        lines.append(f"log          {w.note}")
    else:
        lines.append("log          no record follows the checkpoint")
    for d in w.damage[:3]:
        lines.append(f"damage       {d}")
    if w.damage_count > 3:
        lines.append(f"damage       {w.damage_count - 3:,} more")
    return "refs", lines


def walker_for(kind, fh, base, size=None):
    """The walker class for a filesystem kind, or None if it has no walker.

    ETFS needs the region size (to page the flash) and its detected page size,
    so callers that want an ETFS walker must pass size.
    """
    if kind and kind.startswith("ext"):
        return ExtWalker(fh, base)
    if kind == "fat32":
        return Fat32Walker(fh, base)
    if kind == "fat16":
        return Fat16Walker(fh, base)
    if kind == "fat12":
        return Fat12Walker(fh, base)
    if kind == "exfat":
        return ExfatWalker(fh, base)
    if kind == "ntfs":
        return NtfsWalker(fh, base)
    if kind == "refs":
        return RefsWalker(fh, base)
    if kind == "f2fs":
        return F2fsWalker(fh, base)
    if kind in ("hfs+", "hfsx"):
        return HfsPlusWalker(fh, base)
    if kind == "apfs":
        return ApfsWalker(fh, base)
    if kind == "efs":
        return EfsWalker(fh, base, size)
    if kind == "qnx4":
        return Qnx4Walker(fh, base)
    if kind == "etfs" and size is not None:
        P = etfs_pagesize(fh, base, size)
        return EtfsWalker(fh, base, size, P) if P else None
    if kind == "QNX IFS boot image":
        return IfsWalker(fh, base)
    if kind == "squashfs":
        return SquashfsWalker(fh, base)
    if kind == "xfs":
        return XfsWalker(fh, base, size)
    if kind == "btrfs":
        return BtrfsWalker(fh, base)
    if kind == "ubifs":
        return _cached_walker(fh, base, size, kind, lambda: UbifsWalker(fh, base))
    if kind == "ubi":
        return _cached_walker(fh, base, size, kind, lambda: UbiWalker(fh, base, size))
    if kind == "jffs2":
        return _cached_walker(fh, base, size, kind, lambda: Jffs2Walker(fh, base, size))
    if kind in ("yaffs1", "yaffs2"):
        return _cached_walker(fh, base, size, kind, lambda: YaffsWalker(fh, base, size))
    room = CFG_STORE_MAX if size is None else size
    if kind == "nvram":
        st = nvram_store(fh, base, room)
        return ConfigStoreWalker(fh, base, st[0], "nvram.bin") if st else None
    if kind == "uboot-env":
        st = uboot_env_store(fh, base, room)
        return ConfigStoreWalker(fh, base, st[0], "uboot-env.bin") if st else None
    return None


def _etfs_reserved_match(fh, base, pagesize, n, need=3):
    """True if a fid==1 cluster-0 page parses into a .filetable carrying the
    fixed reserved names at their fixed ids and a directory at the root id.

    The reserved-name check is what makes ETFS detection specific: ETFS has no
    magic number, so a bare page-count match would be a coincidence, but the
    names .filetable/.badblks/.counts at fixed file ids are not.
    """
    per = pagesize // ETFS_ENTRY_SIZE
    if per < 6:                                      # too small to hold fids 0..5
        return False
    unit = pagesize + ETFS_TRANS_SIZE
    for pi, fid, cluster, ta, seq in _etfs_scan_transactions(
            fh, base, pagesize, n, want_fid=ETFS_FID_FTABLE, cap=min(n, 200000)):
        if cluster != 0:
            continue
        data = read_at(fh, base + pi * unit, pagesize)
        r = _etfs_parse_entry(data[0:ETFS_ENTRY_SIZE])
        if not (r and r["body"] and (r["body"]["mode"] & 0o170000) == S_IFDIR):
            continue
        hits = 0
        for rid, name in ETFS_RESERVED.items():
            e = _etfs_parse_entry(data[rid * ETFS_ENTRY_SIZE:(rid + 1) * ETFS_ENTRY_SIZE])
            if e and e["body"] and e["body"].get("name") == name:
                hits += 1
        if hits >= need:
            return True
    return False


def etfs_pagesize(fh, base, size):
    """The ETFS page size for the region, or None. A candidate is accepted only
    when the region divides evenly into (pagesize + 16)-byte pages AND the
    .filetable carries its reserved names, so a chance size match is rejected.
    """
    for P in ETFS_PAGE_SIZES:
        unit = P + ETFS_TRANS_SIZE
        if size < unit or size % unit != 0:
            continue
        if _etfs_reserved_match(fh, base, P, size // unit):
            return P
    return None


def identify_etfs(fh, base, size):
    """Return ("etfs", lines) if an ETFS filesystem fills this region, else None."""
    P = etfs_pagesize(fh, base, size)
    if P is None:
        return None
    return "etfs", [
        f"page size    {P:,} bytes data + {ETFS_TRANS_SIZE} bytes transaction",
        f"pages        {size // (P + ETFS_TRANS_SIZE):,}",
        "layout       transaction based, live state replayed from the spare area",
        "reserved     .filetable/.badblks/.counts/.lost+found/.reserved present",
    ]


def identify_efs(fh, base, size):
    """Return ("efs", lines) if an EFS (F3S) partition starts at base and fits in
    size bytes, else None. The boot record may sit in any of its units."""
    part = _efs_locate(fh, base, size)
    if part is None:
        return None
    us = part["unit_size"]
    return "efs", [
        f"unit size    {human(us)}   {part['unit_total']} units, "
        f"{part['unit_spare']} spare",
        f"byte order   {'little' if part['endian'] == '<' else 'big'}-endian",
        f"alignment    text offsets shifted left by {part['align_pow2']}",
        f"boot record  QSSL_F3S at +0x{part['sig_at']:x}, in unit {part['unit_index']}",
        f"root         logical unit {part['root'][0]}, extent {part['root'][1]}",
    ]


def identify_apfs(fh, base):
    """Return ("apfs", lines) for an APFS container at base, else None.

    A container is claimed by the NXSB magic in the first block's object header
    together with a block size that is a power of two, and it is only reported
    once its newest checkpoint and object map have been read far enough to name
    the volumes inside it. A container that cannot get that far is not one this
    tool can offer to walk.
    """
    head = read_at(fh, base, 4096)
    if len(head) < 4096 or head[32:36] != APFS_NX_MAGIC:
        return None
    block = struct.unpack_from("<I", head, 36)[0]
    if not block or block & (block - 1) or block > (1 << 24):
        return None
    try:
        w = ApfsWalker(fh, base)
    except (ValueError, OSError, struct.error) as exc:
        return "apfs", [f"container    {human(struct.unpack_from('<Q', head, 40)[0] * block)}",
                        f"walk         not possible: {exc}"]
    lines = [
        f"block size   {w.block_size:,}",
        f"container    {human(w.container_size)}   uuid {w.uuid}",
        f"checkpoint   transaction {w.xid:,}",
        f"volumes      {len(w.volumes)}",
    ]
    for i, (_oid, blk, name, incompat) in enumerate(w.volumes):
        sb = w.block(blk)
        used = struct.unpack_from("<Q", sb, 88)[0] * w.block_size
        state = w.encryption(i)
        lines.append(f"  {i}  {name or '(unnamed)'}   {human(used)} used"
                     + ("   case sensitive"
                        if not incompat & APFS_INCOMPAT_CASE_INSENSITIVE else "")
                     + ("   encrypted, read in the clear" if state == "clear" else
                        f"   encrypted, opened with {_apfs_opened_with(w._vol_by.get(i))}"   # pylint: disable=protected-access
                        if state == "unlocked" else
                        "   encrypted and locked, not read" if state == "locked" else ""))
    if w.note:
        lines.append(f"note         {w.note}")
    return "apfs", lines


def identify_hfsplus(fh, base):
    """Return ("hfs+", lines) for an HFS+ or HFSX volume at base, else None.

    The signature sits 1024 bytes in, where a partition's boot blocks leave it,
    and the geometry that follows has to be self-consistent for the volume to be
    readable at all, so both are required rather than the signature alone.
    """
    vh = read_at(fh, base + HFSP_VH_OFF, 512)
    if len(vh) < 512:
        return None
    sig, version = struct.unpack_from(">HH", vh, 0)
    if sig not in (HFSP_SIG, HFSX_SIG):
        return None
    block, total, free = struct.unpack_from(">III", vh, 40)
    if not block or block & (block - 1) or block > (1 << 24) or not total:
        return None
    files, folders = struct.unpack_from(">II", vh, 32)
    # The header records creation in local time and modification in GMT,
    # TN1150 "Volume Header", so only the second can be shown as an instant.
    modified = struct.unpack_from(">I", vh, 20)[0]
    kind = "hfsx" if sig == HFSX_SIG else "hfs+"
    used = (total - free) * block
    lines = [
        f"format       {'HFSX, case sensitive' if sig == HFSX_SIG else 'HFS+'}"
        f"   version {version}",
        f"block size   {block:,}",
        f"volume       {human(total * block)}",
        f"used         {human(used)} of {human(total * block)}"
        + (f" ({100.0 * used / (total * block):.1f}%)" if total else ""),
        f"counts       {files:,} files, {folders:,} folders",
        f"last write   {stamp(hfs_time(modified))}",
    ]
    try:
        w = HfsPlusWalker(fh, base)
    except (ValueError, OSError, struct.error) as exc:
        lines.append(f"walk         not possible: {exc}")
        return kind, lines
    lines.append(f"catalog      node size {w.catalog_node_size:,}, "
                 f"depth {w.catalog_depth}")
    return kind, lines


def identify_ntfs(fh, base):
    """Return ("ntfs", lines) for an NTFS volume at base, else None.

    NTFS names itself in bytes 3..11 of its boot sector, and the geometry that
    follows has to be self-consistent for the volume to be readable at all, so
    both are required rather than the name alone.
    """
    b = read_at(fh, base, 512)
    if len(b) < 512 or b[3:11] != NTFS_OEM or b[510:512] != b"\x55\xaa":
        return None
    bps = struct.unpack_from("<H", b, 11)[0]
    spc = b[13]
    if bps not in (512, 1024, 2048, 4096) or spc not in (1, 2, 4, 8, 16, 32, 64, 128):
        return None
    sectors = struct.unpack_from("<Q", b, 40)[0]
    mft = struct.unpack_from("<Q", b, 48)[0]
    mirr = struct.unpack_from("<Q", b, 56)[0]
    serial = struct.unpack_from("<Q", b, 72)[0]
    if not sectors or not mft:
        return None
    lines = [
        f"bytes/sector {bps}   sectors/cluster {spc}",
        f"volume       {human(sectors * bps)} ({sectors:,} sectors)",
        f"$MFT         cluster {mft:,}   $MFTMirr cluster {mirr:,}",
        f"serial       {serial:016x}",
    ]
    try:
        w = NtfsWalker(fh, base)
    except (ValueError, OSError, struct.error) as exc:
        lines.append(f"walk         not possible: {exc}")
        return "ntfs", lines
    lines.append(f"record size  {w.rec_size} bytes   index block {w.idx_size} bytes")
    label = w.volume_label()
    if label is not None:
        lines.append(f"label        {label or '(none)'}")
    return "ntfs", lines


def _fat_fixed_root_geometry(b):
    """(bits, cluster count) for a FAT12 or FAT16 boot sector, or None when its
    BPB is not one.

    Microsoft's FAT specification types a volume by its count of clusters and
    nothing else: fewer than 4,085 is FAT12 and 4,085 to 65,524 is FAT16. The
    type string does not decide it. The fields that count is computed from
    have to be usable first.
    """
    bps = struct.unpack_from("<H", b, 11)[0]
    spc = b[13]
    reserved = struct.unpack_from("<H", b, 14)[0]
    nfats = b[16]
    root_entries = struct.unpack_from("<H", b, 17)[0]
    total = struct.unpack_from("<H", b, 19)[0] or struct.unpack_from("<I", b, 32)[0]
    spf = struct.unpack_from("<H", b, 22)[0]
    if bps not in (512, 1024, 2048, 4096) or spc not in (1, 2, 4, 8, 16, 32, 64, 128):
        return None
    if not reserved or not nfats or not root_entries or not spf:
        return None
    first_data = reserved + nfats * spf + (root_entries * 32 + bps - 1) // bps
    if total <= first_data:
        return None
    clusters = (total - first_data) // spc
    if not 1 <= clusters < 65525:
        return None
    return (12 if clusters < 4085 else 16), clusters


def _tfat_lines(fh, base, b, bits):
    """What to say about a transaction-safe FAT volume: its type string and
    whether its two tables agree.

    Microsoft's TFAT overview has FAT1 as the table current operations are
    made in and FAT0 as the stable copy of the last known good table, with
    FAT1 copied to FAT0 once a transaction completes. The walker reads FAT0,
    so when the two differ the listing is the last committed state and the
    difference is the work that was in progress.
    """
    name = (b[82:90] if bits == 32 else b[54:62]).decode("ascii", "replace").rstrip(" ")
    lines = [f"type string  {name} (transaction-safe FAT, Windows CE)"]
    bps = struct.unpack_from("<H", b, 11)[0]
    reserved = struct.unpack_from("<H", b, 14)[0]
    nfats = b[16]
    spf = (struct.unpack_from("<I", b, 36)[0] if bits == 32
           else struct.unpack_from("<H", b, 22)[0])
    if nfats < 2 or not bps or not spf:
        lines.append(f"FAT copies   {nfats}")
        return lines
    width = _FAT_ENTRY[bits][0]
    length = spf * bps
    first = read_at(fh, base + reserved * bps, length)
    second = read_at(fh, base + reserved * bps + length, length)
    if len(first) < length or len(second) < length:
        lines.append(f"FAT copies   {nfats}, not compared: the image ends inside them")
        return lines
    if first == second:
        lines.append(f"FAT copies   {nfats}, the first two identical")
        return lines
    if bits == 12:
        differ = sum(1 for n in range(length * 2 // 3)
                     if _fat12_entry(first[n + n // 2:n + n // 2 + 2], n & 1)
                     != _fat12_entry(second[n + n // 2:n + n // 2 + 2], n & 1))
    else:
        differ = sum(1 for i in range(0, length, width)
                     if first[i:i + width] != second[i:i + width])
    lines.append(f"FAT copies   {nfats}, the first two differ in {differ:,} entries; "
                 f"the first is read")
    return lines


def identify_fat(fh, base):
    """Return (kind, lines) for a FAT32, FAT16, FAT12 or exFAT volume at base, else None.

    exFAT names itself in bytes 3..11 of the boot sector. FAT32 is recognised
    by its "FAT32   " filesystem-type string at offset 82 together with a 0x55AA
    boot signature, rather than by the OEM name, which is set by whatever tool
    wrote the volume. FAT16 and FAT12 are recognised by "FAT16   " or
    "FAT12   " at offset 54, the same signature, and a usable BPB; which of
    the two it is comes from the cluster count, as Microsoft's specification
    has it, and not from the string. Windows CE's transaction-safe FAT writes
    "TFAT32  " and "TFAT16  " in the same places and is read as the FAT it is.
    """
    b = read_at(fh, base, 512)
    if b[3:11] == BDE_SIGNATURE or (b[3:11] == BDE_TOGO_SIGNATURE and b[424:440] == BDE_GUID):
        return None                  # a BitLocker header: identify_bitlocker's, not a FAT volume
    if len(b) < 512 or b[510:512] != b"\x55\xaa":
        if b[3:11] != b"EXFAT   ":
            return None
    if b[3:11] == b"EXFAT   ":
        bps = 1 << b[108]
        spc = 1 << b[109]
        clusters = struct.unpack_from("<I", b, 92)[0]
        vol = struct.unpack_from("<Q", b, 72)[0] * bps
        return "exfat", [
            f"bytes/sector {bps}   sectors/cluster {spc}",
            f"clusters     {clusters:,}",
            f"volume       {human(vol)}",
        ]
    if b[82:90] in (b"FAT32   ", b"TFAT32  "):
        bps = struct.unpack_from("<H", b, 11)[0]
        spc = b[13]
        total = struct.unpack_from("<I", b, 32)[0] * bps
        label = b[71:82].decode("ascii", "replace").rstrip(" ")
        lines = [
            f"label        {label or '(none)'}",
            f"bytes/sector {bps}   sectors/cluster {spc}",
            f"volume       {human(total)}",
        ]
        if b[82:90] in TFAT_TYPE_STRINGS:
            lines += _tfat_lines(fh, base, b, 32)
        return "fat32", lines
    if b[54:62] in (b"FAT16   ", b"FAT12   ", b"TFAT16  "):
        geometry = _fat_fixed_root_geometry(b)
        if geometry is None:
            return None
        bits, clusters = geometry
        bps = struct.unpack_from("<H", b, 11)[0]
        spc = b[13]
        total = (struct.unpack_from("<H", b, 19)[0]
                 or struct.unpack_from("<I", b, 32)[0]) * bps
        label = b[43:54].decode("ascii", "replace").rstrip(" ")
        lines = [
            f"label        {label or '(none)'}",
            f"bytes/sector {bps}   sectors/cluster {spc}",
            f"clusters     {clusters:,}",
            f"volume       {human(total)}",
        ]
        said = b[54:62].decode("ascii", "replace").rstrip(" ")
        if said.lstrip("T") != f"FAT{bits}":
            lines.append(f"type string  {said}; the cluster count makes it FAT{bits}")
        if b[54:62] in TFAT_TYPE_STRINGS:
            lines += _tfat_lines(fh, base, b, bits)
        return f"fat{bits}", lines
    return None


def identify_f2fs(fh, base):
    """Return ("f2fs", lines) for an F2FS volume at base, else None.

    F2FS names itself with a 4-byte magic 1024 bytes into the volume, and the
    reserved inode numbers that follow (node 1, meta 2, root 3) are fixed, so
    both are required rather than the magic alone (fs/f2fs/super.c
    sanity_check_raw_super). Block size and blocks-per-segment must also be the
    values the format allows.
    """
    b = read_at(fh, base + F2FS_SUPER_OFF, 3072)
    if len(b) < 200 or struct.unpack_from("<I", b, 0)[0] != F2FS_MAGIC:
        return None
    log_bs = struct.unpack_from("<I", b, 16)[0]
    if not (F2FS_BLKSIZE_BITS_MIN <= log_bs <= F2FS_BLKSIZE_BITS_MAX):
        return None
    if struct.unpack_from("<I", b, 20)[0] != 9:              # log blocks per segment
        return None
    if (struct.unpack_from("<I", b, 96)[0] != 3
            or struct.unpack_from("<I", b, 100)[0] != 1
            or struct.unpack_from("<I", b, 104)[0] != 2):
        return None
    bs = 1 << log_bs
    total = struct.unpack_from("<Q", b, 36)[0] * bs          # block_count, user blocks
    label = b[124:124 + 1024].decode("utf-16-le", "replace").split("\x00")[0]
    uid = b[108:124].hex()
    kver = b[1668:1668 + 256].split(b"\x00")[0].decode("ascii", "replace")
    feat = struct.unpack_from("<I", b, 2180)[0]
    names = [(F2FS_FEAT_ENCRYPT, "encrypt"), (F2FS_FEAT_COMPRESSION, "compression"),
             (F2FS_FEAT_CASEFOLD, "casefold"), (F2FS_FEAT_EXTRA_ATTR, "extra_attr"),
             (F2FS_FEAT_INODE_CRTIME, "inode_crtime")]
    flags = " ".join(n for bit, n in names if feat & bit) or "(none)"
    lines = [
        f"label        {label or '(none)'}",
        f"block size   {bs:,} bytes",
        f"volume       {human(total)}",
        f"uuid         {uid}",
        f"features     {flags}",
    ]
    if kver:
        lines.append(f"made by      {kver}")
    try:
        w = F2fsWalker(fh, base)
    except (F2fsUnreadable, ValueError, OSError, struct.error) as exc:
        lines.append(f"walk         not possible: {exc}")
        return "f2fs", lines
    used = int.from_bytes(w.ckpt[16:24], "little") * bs      # valid_block_count
    if total:
        lines.insert(3, f"used         {human(used)} of {human(total)} "
                        f"({100.0 * used / total:.1f}%)")
    clean = "cleanly unmounted" if (w.cp_flags & F2FS_CP_UMOUNT) else \
            "NOT cleanly unmounted, so it may have been live at acquisition"
    if w.cp_flags & F2FS_CP_ERROR:
        clean += "; checkpoint carries an error flag"
    lines.append(f"checkpoint   {clean}")
    if feat & F2FS_FEAT_ENCRYPT:
        lines.append("note         per-file encryption is enabled; encrypted files "
                     "are named and their content is not read")
    return "f2fs", lines


# ---------------------------------------------------------------- BitLocker
#
# Layout from Joachim Metz, "BitLocker Drive Encryption (BDE) format
# specification", in libyal/libbde at 96e3c5dce6143c2702c90f3903018fb8c12a8956
# (documentation/BitLocker Drive Encryption (BDE) format.asciidoc). How a sector
# is read back follows libbde/libbde_sector_data.c at the same commit (lines
# 274-420): the three metadata blocks and the area the first sectors were moved
# to read as zeros; the first sectors are read from where BitLocker moved them and
# decrypted with that location's sector number; and a sector past the encrypted
# size, or in a range an unfinished conversion has not reached, is read as
# stored. The Encrypt-on-Write map that records that range is read as
# libbde/libbde_volume.c at the same commit reads it
# (libbde_internal_volume_open_read_encrypt_on_write_data, line 1668).
#
# Measured on volumes Windows 11 Pro (build 26200) wrote: NTFS, FAT32 and exFAT;
# AES-CBC and AES-XTS at 128 and 256 bits; opened with a password, a recovery
# password, a startup key (.BEK) file, and the clear key a suspended volume keeps;
# and three volumes whose conversion was paused (while encrypting, while encrypting
# used space only, and while decrypting), each of which carries an Encrypt-on-Write
# map. Not read: the Elephant diffuser (Windows Vista and 7 only), the Windows
# Vista layout, and a TPM protector, whose key never leaves the device.

try:
    from Crypto.Cipher import AES as _BDE_AES                  # pycryptodome
except ImportError:
    try:
        from Cryptodome.Cipher import AES as _BDE_AES          # pycryptodomex
    except ImportError:
        _BDE_AES = None

BDE_SIGNATURE = b"-FVE-FS-"
BDE_TOGO_SIGNATURE = b"MSWIN4.1"
# 4967d63b-2e29-4ad8-8399-f6a339e3d001, and the identifier a volume carries while
# an Encrypt-on-Write conversion is unfinished, 92a84d3b-dd80-4d0e-9e4e-b1e3284eaed8,
# both as stored (the first three fields little-endian).
BDE_GUID = bytes.fromhex("3bd66749292ed84a8399f6a339e3d001")
BDE_EOW_GUID = bytes.fromhex("3b4da89280dd0e4d9e4eb1e3284eaed8")
BDE_METADATA_SIZE = 65536
BDE_STRETCH_ROUNDS = 0x100000
BDE_CHUNK = 65536                    # decrypted and cached in 64 KiB pieces
BDE_CACHE_CHUNKS = 256               # 16 MiB of plaintext kept per volume
BDE_METHODS = {0x8000: "AES-128-CBC with the Elephant diffuser",
               0x8001: "AES-256-CBC with the Elephant diffuser",
               0x8002: "AES-128-CBC", 0x8003: "AES-256-CBC",
               0x8004: "AES-128-XTS", 0x8005: "AES-256-XTS"}
BDE_READ_METHODS = (0x8002, 0x8003, 0x8004, 0x8005)
# libbde lists all but 0x0300 and 0x0700. Those two are the codes Windows 11 (build
# 26200) wrote for the protectors manage-bde calls "TPM And Startup Key" and "TPM
# And PIN And Startup Key" (tests/fixtures/bitlocker-win11-tpm, from a test VM).
BDE_PROTECTORS = {0x0000: "clear key", 0x0100: "TPM", 0x0200: "startup key",
                  0x0300: "TPM and startup key", 0x0500: "TPM and PIN",
                  0x0700: "TPM, PIN and startup key", 0x0800: "recovery password",
                  0x2000: "password"}


def _bde_entries(data):
    """The FVE metadata entries in data: (entry type, value type, value bytes)."""
    out, i = [], 0
    while i + 8 <= len(data):
        size, etype, vtype, _version = struct.unpack_from("<HHHH", data, i)
        if size < 8 or i + size > len(data):
            break
        out.append((etype, vtype, bytes(data[i + 8:i + size])))
        i += size
    return out


def _bde_guid(raw):
    return str(uuid.UUID(bytes_le=bytes(raw))).upper()


# A TPM-protected key (value type 6) as dissect.fve declares it
# (dissect/fve/bde/c_tpm.py at 0b3caf20c1e95136cb2eb4494303604e7629616b, lines 44-53,
# FVE_DATUM_TPM_ENC_BLOB): a 32-bit PCR bitmap, the sealed object's public and
# private parts and the PCR digest, each behind a 16-bit size, then the PCR
# selection behind an 8-bit size. Sizes are big-endian. dissect reads the policy
# from that selection, little-endian (information.py, pcr_policy, line 522). On
# the five TPM protectors Windows 11 wrote for tests/fixtures/bitlocker-win11-tpm,
# the leading bitmap read little-endian names the same PCRs, and both are the
# PCR Validation Profile manage-bde printed (7, 11 and 0, 2, 4, 11).
BDE_TPM_DIGESTS = {20: "SHA-1", 32: "SHA-256", 48: "SHA-384", 64: "SHA-512"}


def _bde_tpm(val):
    """The PCRs a TPM-protected key is sealed to, as stored, or None when the value
    does not have the layout above. ``agree`` is False when the leading bitmap and
    the selection name different PCRs; ``pcrs`` is then empty, since neither is
    known to be the one the TPM checks. Nothing is unsealed: the TPM keeps that key."""
    if len(val) < 4:
        return None
    pos, parts = 4, []
    for width in (2, 2, 2, 1):
        if pos + width > len(val):
            return None
        n = int.from_bytes(val[pos:pos + width], "big")
        pos += width
        if pos + n > len(val):
            return None
        parts.append(val[pos:pos + n])
        pos += n
    if pos != len(val) or not 1 <= len(parts[3]) <= 4:
        return None
    selection = int.from_bytes(parts[3], "little")
    agree = selection == int.from_bytes(val[:4], "little")
    return dict(pcrs=[i for i in range(8 * len(parts[3])) if selection >> i & 1] if agree else [],
                agree=agree, digest=BDE_TPM_DIGESTS.get(len(parts[2]), f"{len(parts[2])} bytes"))


def _bde_ccm_open(key, value):
    """The key data an AES-CCM encrypted key (value type 5) holds, or None when this
    key does not open it: 12 bytes of nonce, a 16-byte tag, then the data, whose
    first 12 bytes are its size, a version and the method."""
    if _BDE_AES is None or len(value) < 40:
        return None
    try:
        plain = _BDE_AES.new(key, _BDE_AES.MODE_CCM, nonce=value[:12],
                             mac_len=16).decrypt_and_verify(value[28:], value[12:28])
    except ValueError:
        return None
    size = struct.unpack_from("<I", plain, 0)[0]
    return plain[12:size] if 12 < size <= len(plain) else None


def bde_recovery_key(text):
    """The 128-bit key a recovery password stands for, or None when text is not
    one: 48 digits in eight groups (dashes and spaces are ignored), each group a
    multiple of 11 whose quotient fits 16 bits."""
    digits = "".join(ch for ch in text if ch not in "- ")
    if len(digits) != 48 or not digits.isdigit():
        return None
    groups = [int(digits[i:i + 6]) for i in range(0, 48, 6)]
    if any(g % 11 or g // 11 > 0xFFFF for g in groups):
        return None
    return b"".join(struct.pack("<H", g // 11) for g in groups)


def _bde_stretch(initial, salt):
    """BitLocker's key stretch: SHA-256 over (last, initial, salt, count), 2**20 times."""
    import hashlib                              # pylint: disable=import-outside-toplevel
    sha, pack, last, tail = hashlib.sha256, struct.Struct("<Q").pack, bytes(32), initial + salt
    for count in range(BDE_STRETCH_ROUNDS):
        last = sha(last + tail + pack(count)).digest()
    return last


def _bde_text(secret):
    if isinstance(secret, (bytes, bytearray)):
        try:
            return bytes(secret).decode("utf-8")
        except UnicodeDecodeError:
            return None
    return secret


def _xts_crypt(pair, data, first, bps=512, encrypt=False):
    """AES-XTS (IEEE 1619) over whole sectors of ``bps`` bytes, the first of them
    sector number ``first``: pair is (the data key, the tweak key) as AES-ECB
    ciphers. Decrypts, or encrypts when asked (the self-test builds ciphertext
    with it). A tail shorter than a sector is dropped, as a short read ends."""
    k1, k2 = pair
    n = len(data) // bps
    if n == 0:
        return b""
    data = data[:n * bps]
    # XTS tweaks for every sector at once: lane i of v (128 bits each) holds
    # sector i's tweak for block j, doubled in GF(2**128) for each next block
    # (the carry out of a lane folds back in as 0x87), and each block's
    # tweaks are laid into place with strided copies.
    per, width = bps // 16, 16 * n
    v = int.from_bytes(k2.encrypt(
        b"".join((first + i).to_bytes(16, "little") for i in range(n))), "little")
    low = int.from_bytes((b"\x01" + bytes(15)) * n, "little")
    keep = ((1 << (128 * n)) - 1) ^ low
    tw = bytearray(len(data))
    for j in range(per):
        vb = v.to_bytes(width, "little")
        for k in range(16):
            tw[16 * j + k::bps] = vb[k::16]
        carry = (v >> 127) & low
        v = ((v << 1) & keep) ^ carry ^ (carry << 1) ^ (carry << 2) ^ (carry << 7)
    tweak = int.from_bytes(tw, "little")
    x = (int.from_bytes(data, "little") ^ tweak).to_bytes(len(data), "little")
    y = k1.encrypt(x) if encrypt else k1.decrypt(x)
    return (int.from_bytes(y, "little") ^ tweak).to_bytes(len(data), "little")


class BitLocker:
    """A BitLocker volume at base in fh, read before any key is given: its method,
    protectors and description, and, once unlock() finds a key, its plaintext.
    BitLocker.open() returns None for anything that is not BitLocker."""

    @classmethod
    def open(cls, fh, base, size=None):
        head = read_at(fh, base, 512)
        if len(head) < 512 or not (
                (head[3:11] == BDE_SIGNATURE
                 and (head[160:176] in (BDE_GUID, BDE_EOW_GUID) or head[:3] == b"\xeb\x52\x90"))
                or (head[3:11] == BDE_TOGO_SIGNATURE and head[424:440] == BDE_GUID)):
            return None
        if size is None:
            size = image_size(fh) - base
        return cls(fh, base, size, head)

    def __init__(self, fh, base, size, head):
        self.fh, self.base, self.size = fh, base, size
        self.fvek, self.unlocked_by, self.tried, self.why = None, None, [], ""
        self._k1 = self._k2 = None
        self.label = "BitLocker volume"   # replaced by unlock_bitlocker with where it sits
        self.method, self.description, self.created, self.volume_id = 0, "", 0, ""
        self.protectors, self.vmks, self.eow_meta, self.eow_plain = [], [], [], []
        self._fvek_value, self._cache = None, collections.OrderedDict()
        if head[:3] == b"\xeb\x52\x90" and head[3:11] == BDE_SIGNATURE:
            self.layout, offsets = "Windows Vista", ()
        elif head[3:11] == BDE_TOGO_SIGNATURE:
            self.layout, offsets = "To Go", struct.unpack_from("<QQQ", head, 440)
        elif head[160:176] == BDE_EOW_GUID:
            self.layout, offsets = "conversion unfinished", struct.unpack_from("<QQQ", head, 176)
        else:
            self.layout, offsets = "Windows 7 and later", struct.unpack_from("<QQQ", head, 176)
        self.meta_offsets = offsets
        self.bps = struct.unpack_from("<H", head, 11)[0]
        self.enc_size = self.vh_offset = self.vh_size = self.vh_sectors = 0
        entries = None
        for off in offsets:
            blk = read_at(fh, base + off, BDE_METADATA_SIZE)
            if len(blk) < 112 or blk[:8] != BDE_SIGNATURE or struct.unpack_from("<H", blk, 10)[0] != 2:
                continue
            self.enc_size, self.vh_sectors = struct.unpack_from("<Q", blk, 16)[0], struct.unpack_from("<I", blk, 28)[0]
            self.vh_offset = struct.unpack_from("<Q", blk, 56)[0]
            msize, _mver, mhsize = struct.unpack_from("<III", blk, 64)
            self.volume_id = _bde_guid(blk[80:96])
            self.method = struct.unpack_from("<I", blk, 100)[0] & 0xFFFF
            self.created = struct.unpack_from("<Q", blk, 104)[0]
            entries = _bde_entries(blk[64 + mhsize:64 + msize])
            break
        if entries is None:
            self.why = ("its metadata is in the Windows Vista layout, which this does not read"
                        if self.layout == "Windows Vista" else "none of its three metadata blocks could be read")
            return
        for etype, vtype, val in entries:
            if etype == 7 and vtype == 2:
                self.description = val.decode("utf-16-le", "replace").rstrip("\x00")
            elif etype == 2 and vtype == 8 and len(val) >= 28:
                vmk = dict(id=_bde_guid(val[:16]), protection=struct.unpack_from("<H", val, 26)[0],
                           modified=struct.unpack_from("<Q", val, 16)[0],
                           props=_bde_entries(val[28:]))
                tpm = [_bde_tpm(v) for _e, vt, v in vmk["props"] if vt == 6]
                vmk["tpm"] = tpm[0] if tpm else None
                vmk["tpm_unread"] = bool(tpm) and tpm[0] is None
                self.vmks.append(vmk)
                self.protectors.append((BDE_PROTECTORS.get(vmk["protection"],
                                                           f"protection 0x{vmk['protection']:04x}"),
                                        vmk["id"]))
            elif etype == 3 and vtype == 5:
                self._fvek_value = val
            elif etype == 15 and vtype == 15 and len(val) >= 16:
                self.vh_offset, self.vh_size = struct.unpack_from("<QQ", val, 0)
        if not self.bps:
            # The header of a BitLocker exFAT volume leaves bytes per sector 0;
            # libbde_volume.c (lines 1497-1506) takes it from the moved header and
            # accepts only 512 or 4096.
            self.bps = (self.vh_size // self.vh_sectors
                        if self.vh_size and self.vh_sectors else 512)
        if self.bps not in (512, 4096) and not self.why:
            self.why = f"its sector size, {self.bps} bytes, is not one BitLocker uses"
            self.bps = 512
        if not self.vh_size:
            self.vh_size = self.vh_sectors * self.bps
        if self.layout == "conversion unfinished":
            try:
                self._read_eow(head)
            except (ValueError, struct.error) as exc:
                self.why = f"its Encrypt-on-Write map could not be read ({exc})"
        # Known from the metadata alone, so said whether or not a key is ever tried.
        if not self.why and self.method not in BDE_READ_METHODS:
            self.why = (f"it uses {BDE_METHODS.get(self.method, f'method 0x{self.method:04x}')}, "
                        f"which this does not read")
        elif not self.why and _BDE_AES is None:
            self.why = ("reading it needs the optional pycryptodome package, which this "
                        "Python does not have")

    def _read_eow(self, head):
        """The ranges an unfinished conversion has not reached, and the map's own
        areas, which read as zeros like the rest of BitLocker's metadata."""
        first, second = struct.unpack_from("<QQ", head, 200)
        desc = read_at(self.fh, self.base + first, 4096)
        if desc[:8] != b"FVE-EOW\x00":
            raise ValueError("no FVE-EOW descriptor")
        block, log_size = struct.unpack_from("<II", desc, 20)
        count = struct.unpack_from("<I", desc, 32)[0]
        if not block or count > 512:
            raise ValueError("an implausible descriptor")
        self.eow_meta = [(first, 4096)] + ([(second, 4096)] if second else [])
        for off in struct.unpack_from(f"<{count}Q", desc, 56):
            bm = read_at(self.fh, self.base + off, 4096)
            if bm[:10] != b"FVE-EOWBM\x00":
                raise ValueError(f"no block map at byte {off:,}")
            bm_size, _index, region, region_size, log_off, r1, r2, rsize = \
                struct.unpack_from("<IIQQQIII", bm, 12)
            self.eow_meta.append((off, -(-bm_size // 4096) * 4096))
            if log_off:
                self.eow_meta.append((log_off, -(-log_size // 4096) * 4096))
            best = None
            for roff in (r1, r2):
                rec = read_at(self.fh, self.base + off + roff, rsize)
                if rec[:10] == b"FVE-EOWBR\x00":
                    bits, seq = struct.unpack_from("<IQ", rec, 16)
                    if best is None or seq > best[0]:
                        best = (seq, bits, rec[36:])
            if best is None:
                raise ValueError(f"no block record in the map at byte {off:,}")
            _seq, bits, bitmap = best
            # A set bit is a block already encrypted; the newest record decides.
            for i in range(min(bits, len(bitmap) * 8)):
                start = i * block
                if start >= region_size:
                    break
                if not bitmap[i // 8] >> (i % 8) & 1:
                    end = region + min(start + block, region_size)
                    if self.eow_plain and self.eow_plain[-1][1] == region + start:
                        self.eow_plain[-1] = (self.eow_plain[-1][0], end)
                    else:
                        self.eow_plain.append((region + start, end))

    def lines(self):
        """What the volume says about itself before any key is given."""
        out = [f"encryption   {BDE_METHODS.get(self.method, f'method 0x{self.method:04x}') if self.method else 'not read'}"
               + (f", {self.layout} layout" if self.layout != "Windows 7 and later" else "")]
        if self.eow_plain:
            out.append(f"conversion   unfinished: {human(sum(e - s for s, e in self.eow_plain))} "
                       f"not yet encrypted (the rest reads through its key)")
        if self.description:
            out.append(f"description  {self.description}")
        if self.created:
            out.append(f"created      {stamp(int(ntfs_time(self.created)))}")
        if self.volume_id:
            out.append(f"volume id    {self.volume_id}")
        for (kind, pid), vmk in zip(self.protectors, self.vmks):
            line = f"protector    {kind:<18} id {pid}"
            if vmk["tpm"] is not None and not vmk["tpm"]["agree"]:
                line += "   PCRs not read: its two stored PCR lists disagree"
            elif vmk["tpm"] is not None:
                line += (f"   PCRs {', '.join(map(str, vmk['tpm']['pcrs'])) or 'none'}"
                         f" ({vmk['tpm']['digest']} policy digest)")
            elif vmk["tpm_unread"]:
                line += "   PCRs not read: its TPM entry has a layout this does not know"
            out.append(line)
        if any(kind == "clear key" for kind, _pid in self.protectors):
            # Windows lists no clear key among a volume's protectors; it is what
            # suspending protection leaves (manage-bde -protectors -disable).
            out.append("suspended    protection is off: the volume keeps its key in the clear, "
                       "so it opens with no key given")
        return out

    def unlock(self, passwords=(), key_files=()):
        """True once a key opens the volume: its clear key, a startup key file, or a
        password or recovery password among passwords. Records what was tried."""
        if self.fvek is not None:
            return True
        if self.why:
            return False
        texts = [t for t in (_bde_text(p) for p in passwords) if t]
        keyfiles = []
        for kf in key_files:
            try:
                keyfiles.append(kf if isinstance(kf, (bytes, bytearray)) else open(kf, "rb").read())
            except OSError:
                continue
        order = sorted(self.vmks, key=lambda v: {0x0000: 0, 0x0200: 1}.get(v["protection"], 2))
        for vmk in order:
            prot, key = vmk["protection"], None
            ccm = next((val for _e, vt, val in vmk["props"] if vt == 5), None)
            if ccm is None:
                continue
            if prot == 0x0000:
                clear = next((val for _e, vt, val in vmk["props"] if vt == 1), None)
                key = _bde_ccm_open(clear[4:36], ccm) if clear else None
            elif prot == 0x0200:
                for raw in keyfiles:
                    for _e, vt, val in _bde_entries(raw[48:]):
                        if vt == 9 and len(val) >= 24 and _bde_guid(val[:16]) == vmk["id"]:
                            kd = next((v for _e2, t2, v in _bde_entries(val[24:]) if t2 == 1), None)
                            key = _bde_ccm_open(kd[4:36], ccm) if kd else None
                    if key:
                        break
            elif prot in (0x0800, 0x2000):
                stretch = next((val for _e, vt, val in vmk["props"] if vt == 3), None)
                if stretch is None or not texts:
                    continue
                import hashlib                  # pylint: disable=import-outside-toplevel
                for text in texts:
                    if prot == 0x0800:
                        rk = bde_recovery_key(text)
                        if rk is None:
                            continue
                        initial = hashlib.sha256(rk).digest()
                    else:
                        initial = hashlib.sha256(hashlib.sha256(text.encode("utf-16-le")).digest()).digest()
                    key = _bde_ccm_open(_bde_stretch(initial, stretch[4:20]), ccm)
                    if key:
                        break
            else:
                continue
            # Recorded only when something given was tried against it, so a locked
            # volume's note never claims keys were given when none were.
            if prot == 0x0200 and keyfiles or prot in (0x0800, 0x2000) and texts:
                self.tried.append(BDE_PROTECTORS.get(prot, hex(prot)))
            if key and len(key) >= 32:
                fvek = _bde_ccm_open(key[:32], self._fvek_value or b"")
                if fvek:
                    half = 16 if self.method in (0x8002, 0x8004) else 32
                    self._k1 = _BDE_AES.new(fvek[:half], _BDE_AES.MODE_ECB)
                    self._k2 = (_BDE_AES.new(fvek[half:2 * half], _BDE_AES.MODE_ECB)
                                if self.method in (0x8004, 0x8005) else None)
                    self.fvek, self.unlocked_by = fvek, BDE_PROTECTORS.get(prot)
                    return True
        return False

    def _decrypt(self, phys, data):
        """Whole sectors read at volume offset phys, decrypted with the key and the
        sector position libbde_sector_data.c uses: the byte offset for AES-CBC, the
        sector number for AES-XTS."""
        bps, n = self.bps, len(data) // self.bps
        if self._k2 is not None:
            return _xts_crypt((self._k1, self._k2), data, phys // bps, bps)
        ivs = self._k1.encrypt(b"".join((phys + i * bps).to_bytes(16, "little") for i in range(n)))
        prev = b"".join(ivs[16 * i:16 * i + 16] + data[i * bps:(i + 1) * bps - 16] for i in range(n))
        return (int.from_bytes(self._k1.decrypt(data), "little")
                ^ int.from_bytes(prev, "little")).to_bytes(len(data), "little")

    def _sector_source(self, pos):
        """("zero", 0), ("raw", phys) or ("dec", phys) for the sector at pos."""
        if (any(mo <= pos < mo + BDE_METADATA_SIZE for mo in self.meta_offsets)
                or self.vh_offset <= pos < self.vh_offset + self.vh_size
                or any(s <= pos < s + n for s, n in self.eow_meta)):
            return "zero", 0
        phys = pos + self.vh_offset if pos < self.vh_size else pos
        if (self.enc_size and phys >= self.enc_size) or any(s <= phys < e for s, e in self.eow_plain):
            return "raw", phys
        return "dec", phys

    def _plain(self, start, length):
        bps, out, pos, end = self.bps, bytearray(), start, start + length
        while pos < end:
            kind, phys = self._sector_source(pos)
            run = bps
            while pos + run < end:
                k2, p2 = self._sector_source(pos + run)
                if k2 != kind or (kind != "zero" and p2 != phys + run):
                    break
                run += bps
            if kind == "zero":
                out += bytes(run)
            else:
                data = read_at(self.fh, self.base + phys, run)
                whole = len(data) - len(data) % bps
                out += (self._decrypt(phys, data[:whole]) + data[whole:]) if kind == "dec" else data
                if len(data) < run:
                    break
            pos += run
        return bytes(out)

    def read(self, off, n):
        """n plaintext bytes at volume offset off (short at the end of the volume)."""
        out, pos, end = bytearray(), off, min(off + n, self.size)
        while pos < end:
            ci = pos // BDE_CHUNK
            chunk = self._cache.get(ci)
            if chunk is None:
                start = ci * BDE_CHUNK
                chunk = self._plain(start, min(BDE_CHUNK, self.size - start))
                self._cache[ci] = chunk
                if len(self._cache) > BDE_CACHE_CHUNKS:
                    self._cache.popitem(last=False)
            else:
                self._cache.move_to_end(ci)
            s = pos - ci * BDE_CHUNK
            take = min(len(chunk) - s, end - pos)
            if take <= 0:
                break
            out += chunk[s:s + take]
            pos += take
        return bytes(out)

    def summary(self):
        return (f"BitLocker {BDE_METHODS.get(self.method, '')}, unlocked with its {self.unlocked_by}"
                if self.fvek is not None else "BitLocker, locked")

    def facts(self):
        """What the metadata says, as data, for a caller that reports it (volumes()
        puts it under "bitlocker"): the layout, method, description, created and
        volume id, and one dict per protector with its kind, code, id, last-modified
        FILETIME and, for a TPM, the PCRs its key is sealed to as stored. ``why`` is
        why the metadata or the volume could not be read, else empty."""
        protectors = []
        for (kind, pid), vmk in zip(self.protectors, self.vmks):
            tpm = vmk["tpm"]
            protectors.append(dict(kind=kind, code=vmk["protection"], id=pid,
                                   modified=vmk["modified"],
                                   pcrs=list(tpm["pcrs"]) if tpm and tpm["agree"] else None,
                                   pcr_digest=tpm["digest"] if tpm else "",
                                   pcrs_disagree=bool(tpm) and not tpm["agree"],
                                   tpm_unread=vmk["tpm_unread"]))
        return dict(layout=self.layout, method=self.method,
                    method_name=BDE_METHODS.get(self.method, f"method 0x{self.method:04x}") if self.method else "",
                    description=self.description, created=self.created, volume_id=self.volume_id,
                    protectors=protectors, unlocked_by=self.unlocked_by or "", why=self.why)

    def locked_note(self):
        """Why the volume was not read, and what would open it."""
        if self.why:
            return f"BitLocker-encrypted and not read: {self.why}"
        kinds = [k for k, _i in self.protectors]
        if kinds and all(k.startswith("TPM") for k in kinds):
            return ("BitLocker-encrypted and not read: its only protector is the device's "
                    "TPM, whose key does not leave the device")
        usable = []
        for kind, pid in self.protectors:
            if kind == "recovery password":
                usable.append(f"recovery password (protector id {pid})")
            elif kind in ("password", "startup key") and kind not in usable:
                usable.append(kind)
        tried = "none of the passwords or key files given opens it; " if self.tried else ""
        return (f"BitLocker-encrypted and not read: {tried}it opens with its "
                + " or its ".join(usable or ["key"]))


def identify_bitlocker(fh, base, size=None):
    """Return ("bitlocker", lines) for a BitLocker volume at base, else None."""
    bl = BitLocker.open(fh, base, size)
    return ("bitlocker", bl.lines()) if bl else None


class BitLockerImage:
    """An image read through read_at() with its unlocked BitLocker volumes
    decrypted in place, so identify_fs() and every walker read the plaintext at
    the volume's own offset. ``bitlocker`` maps each such volume's byte offset to
    its BitLocker object; anything else is the image's own attribute."""

    def __init__(self, fh, opened, found=()):
        self._fh, self.bitlocker, self.bitlocker_found = fh, dict(opened), list(found)
        self.size = image_size(fh)
        self._spans = sorted((b, b + v.size, v) for b, v in self.bitlocker.items())
        self._pos = 0

    def __getattr__(self, name):
        return getattr(self._fh, name)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self._fh.close()

    def seek(self, off, whence=0):
        self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        end = self.size if n is None or n < 0 else min(self.size, self._pos + n)
        out = bytearray()
        while self._pos < end:
            span = next((s for s in self._spans if s[0] <= self._pos < s[1]), None)
            if span is not None:
                take = min(end, span[1]) - self._pos
                got = span[2].read(self._pos - span[0], take)
            else:
                nxt = min([s[0] for s in self._spans if s[0] > self._pos] + [end])
                self._fh.seek(self._pos)
                got = self._fh.read(nxt - self._pos)
            if not got:
                break
            out += got
            self._pos += len(got)
        return bytes(out)


def unlock_bitlocker(fh, size=None, passwords=(), key_files=()):
    """Find the BitLocker volumes in an opened image and open those the passwords
    (tried as passwords and as recovery passwords) or startup key files open.
    Returns (fh, found): fh is a BitLockerImage when there is any BitLocker volume
    (``bitlocker`` holds those opened, ``bitlocker_found`` every one, so volumes()
    can say why a locked one was not read), else the image unchanged; found holds
    one BitLocker per volume, opened or not."""
    if size is None:
        size = image_size(fh)
    regions, _names, containers, protective = partition_regions(fh, size)
    found, opened = [], {}
    for label, base, rsize in regions:
        if label in containers or label in protective:
            continue
        bl = BitLocker.open(fh, base, rsize)
        if bl is None:
            continue
        bl.label = label
        if bl.unlock(passwords, key_files):
            opened[base] = bl
        found.append(bl)
    return (BitLockerImage(fh, opened, found) if found else fh), found


# ---- encrypted APFS volumes, opened with a password -----------------------
#
# Apple File System Reference, 2020-06-22, "Encryption" and "Accessing Encrypted
# Objects", describes software encryption, which a Mac uses for external storage
# and for internal storage without hardware encryption: the container's keybag
# holds each volume's wrapped volume key (VEK) and where the volume's own keybag
# is; the volume's keybag holds its key encryption key (KEK), wrapped once per
# user password and once for a personal recovery key; the KEK unwraps the VEK;
# and the VEK decrypts the volume's tree and files as AES-XTS. What that
# reference leaves out comes from libfsapfs's format notes ("Apple File System
# (APFS).asciidoc" at f63c83b): each keybag is itself AES-XTS encrypted with its
# container's or volume's identifier as both keys and its 512-byte sector number
# in the container as the tweak (the reference says RFC 3394 for that step, and
# the keybags on both fixtures read as AES-XTS and not as RFC 3394); and a KEK
# record's packed fields, among them the PBKDF2 iteration count and salt that
# turn a password into the key that unwraps it. PBKDF2 there is HMAC-SHA256, the one that
# unwraps the KEK on both fixtures. Not read: a volume with per-file keys
# (hardware encryption), a volume caught mid-way through being encrypted,
# decrypted or re-keyed, a KEK record in the CoreStorage-compatible form
# (libfsapfs: flag 0x2, AES-128), and an institutional recovery key. On a Mac
# with a T2 chip or Apple silicon, Apple Platform Security's FileVault page says
# the KEK "is protected by a combination of the user's password and hardware
# UID", so an image of its internal storage does not open with a password.

APFS_OBJECT_TYPE_CONTAINER_KEYBAG = 0x6B657973          # 'keys'
APFS_OBJECT_TYPE_VOLUME_KEYBAG = 0x72656373             # 'recs'
APFS_KB_TAG_VOLUME_KEY = 2
APFS_KB_TAG_VOLUME_UNLOCK_RECORDS = 3
APFS_KB_TAG_VOLUME_PASSPHRASE_HINT = 4
APFS_FV_PERSONAL_RECOVERY_KEY_UUID = uuid.UUID("EBC6C064-0000-11AA-AA11-00306543ECAC")
APFS_KEK_COMPAT_FLAG = 0x2          # libfsapfs: CoreStorage-compatible, AES-128
APFS_MAX_PBKDF2_ROUNDS = 100_000_000


def _aes_unwrap(kek, wrapped):
    """RFC 3394 AES key unwrap, or None when the integrity value does not come
    out as A6A6A6A6A6A6A6A6, which is how a wrong password shows."""
    if len(wrapped) < 24 or len(wrapped) % 8:
        return None
    n = len(wrapped) // 8 - 1
    a, r = wrapped[:8], [wrapped[8 * i:8 * i + 8] for i in range(1, n + 1)]
    aes = _BDE_AES.new(kek, _BDE_AES.MODE_ECB)
    for j in range(5, -1, -1):
        for i in range(n, 0, -1):
            t = (n * j + i).to_bytes(8, "big")
            b = aes.decrypt(bytes(x ^ y for x, y in zip(a, t)) + r[i - 1])
            a, r[i - 1] = b[:8], b[8:]
    return b"".join(r) if a == b"\xa6" * 8 else None


def _apfs_packed(buf):
    """{tag: value} for one level of a keybag entry's packed values: a tag byte,
    a length byte whose top bit says the length runs on in the next (length &
    0x7f) bytes, big-endian, then the value; a zero tag and length ends them."""
    out, i = {}, 0
    while i + 2 <= len(buf):
        tag, ln = buf[i], buf[i + 1]
        i += 2
        if ln & 0x80:
            k = ln & 0x7F
            ln = int.from_bytes(buf[i:i + k], "big")
            i += k
        if tag == 0 and ln == 0:
            break
        out[tag] = buf[i:i + ln]
        i += ln
    return out


def _apfs_wrapped(blob):
    """(flags, wrapped key, iterations, salt) from a keybag entry holding a
    wrapped key, whose 0x30 value holds a 0xa3 value holding them (libfsapfs's
    format notes, "Key encryption key (KEK) packed object"), or None."""
    try:
        inner = _apfs_packed(_apfs_packed(_apfs_packed(blob)[0x30])[0xA3])
        flags = struct.unpack_from("<I", inner[0x82], 0)[0]
    except (KeyError, struct.error):
        return None
    iters = int.from_bytes(inner.get(0x84, b""), "big")
    return flags, inner.get(0x83, b""), iters, inner.get(0x85, b"")


def _apfs_keybag(w, prange, key_uuid, otype):
    """[(uuid, tag, data)] from the keybag at prange (block, count), decrypted with
    key_uuid as both AES-XTS keys, or None when it does not decrypt to a keybag
    object of type otype whose checksum holds."""
    base, count = prange
    if not base or not count or count > 64:
        return None
    raw = read_at(w.fh, w.base + base * w.block_size, count * w.block_size)
    if len(raw) < count * w.block_size:
        return None
    pair = (_BDE_AES.new(key_uuid.bytes, _BDE_AES.MODE_ECB),
            _BDE_AES.new(key_uuid.bytes, _BDE_AES.MODE_ECB))
    plain = _xts_crypt(pair, raw, base * (w.block_size // 512))
    if (struct.unpack_from("<I", plain, 24)[0] != otype or not _apfs_fletcher_ok(plain)):
        return None
    version, nkeys, nbytes = struct.unpack_from("<HHI", plain, 32)
    if version != 2:
        return None
    out, at, end = [], 48, min(len(plain), 32 + nbytes)
    for _ in range(nkeys):
        if at + 24 > end:
            break
        tag, keylen = struct.unpack_from("<HH", plain, at + 16)
        out.append((uuid.UUID(bytes=plain[at:at + 16]), tag, plain[at + 24:at + 24 + keylen]))
        at += (24 + keylen + 15) & ~15
    return out


def _apfs_opened_with(by):
    """How a report names what opened a volume: a volume can hold a record for each
    user's password, so a password is "a password", and the recovery key is its own."""
    return "a password" if by == "password" else f"its {by or 'key'}"


class ApfsLock:
    """One encrypted APFS volume whose blocks are ciphertext in the image: what its
    keybags hold, and whether a password given opened it.

    vek is the volume key once a password or the personal recovery key has
    unwrapped it (and it decrypts the volume's tree to one that checks out), else
    None; unlocked_by says which; why says what stops it being opened at all;
    hint is the passphrase hint the volume stores, as stored."""

    def __init__(self, w, index, label=""):
        self.label = label or "APFS container"
        self.base, self.index = w.base, index
        self.container_uuid, self.uuid = w.uuid, w.volume_uuids[index]
        self.name = w.volumes[index][2] or f"volume {index}"
        self.vek, self.unlocked_by, self.tried, self.why, self.hint = None, None, False, "", ""
        self.records = []                           # (user uuid, wrapped KEK entry)
        self._w, self._vek_blob = w, None
        sb = w.block(w.volumes[index][1])
        self._sb = sb
        if _BDE_AES is None:
            self.why = ("reading it needs the optional pycryptodome package, which this "
                        "Python does not have")
            return
        self.why = w.crypto_blocker(sb)
        if self.why:
            return
        kl = struct.unpack_from("<QQ", w._nx, APFS_NX_KEYLOCKER_OFF)   # pylint: disable=protected-access
        if not kl[0]:
            self.why = "its container holds no keybag"
            return
        entries = _apfs_keybag(w, kl, w.uuid, APFS_OBJECT_TYPE_CONTAINER_KEYBAG)
        if entries is None:
            self.why = ("its container's keybag does not decrypt with the container's "
                        "identifier, so its keys cannot be read here")
            return
        mine = [(t, d) for u, t, d in entries if u == self.uuid]
        self._vek_blob = next((d for t, d in mine if t == APFS_KB_TAG_VOLUME_KEY), None)
        where = next((d for t, d in mine if t == APFS_KB_TAG_VOLUME_UNLOCK_RECORDS), None)
        if self._vek_blob is None or where is None or len(where) < 16:
            self.why = "its container's keybag holds no key for it"
            return
        vol_entries = _apfs_keybag(w, struct.unpack_from("<QQ", where, 0), self.uuid,
                                   APFS_OBJECT_TYPE_VOLUME_KEYBAG)
        if vol_entries is None:
            self.why = "its own keybag does not decrypt with its identifier"
            return
        for u, t, d in vol_entries:
            if t == APFS_KB_TAG_VOLUME_UNLOCK_RECORDS:
                self.records.append((u, d))
            elif t == APFS_KB_TAG_VOLUME_PASSPHRASE_HINT:
                self.hint = d.split(b"\x00")[0].decode("utf-8", "replace")
        if not self.records:
            self.why = "its keybag holds no password or recovery key record"
        elif all((_apfs_wrapped(d) or (APFS_KEK_COMPAT_FLAG,))[0] & APFS_KEK_COMPAT_FLAG
                 for _u, d in self.records):
            self.why = ("its only unlock records are in the CoreStorage-compatible form, "
                        "which this does not read")

    def unlock(self, passwords):
        """Try each password (or personal recovery key) on each unlock record; True
        once one opens the volume."""
        if self.vek is not None:
            return True
        if self.why:
            return False
        import hashlib                              # pylint: disable=import-outside-toplevel
        vek_wrapped = _apfs_wrapped(self._vek_blob)
        for secret in passwords:
            text = _bde_text(secret)
            if text is None:
                continue
            self.tried = True
            for user, blob in self.records:
                rec = _apfs_wrapped(blob)
                if rec is None or rec[0] & APFS_KEK_COMPAT_FLAG:
                    continue
                _flags, wrapped, iters, salt = rec
                if not 0 < iters <= APFS_MAX_PBKDF2_ROUNDS or not salt:
                    continue
                derived = hashlib.pbkdf2_hmac("sha256", text.encode("utf-8"), salt, iters, 32)
                kek = _aes_unwrap(derived, wrapped)
                if kek is None or vek_wrapped is None or vek_wrapped[0] & APFS_KEK_COMPAT_FLAG:
                    continue
                vek = _aes_unwrap(kek, vek_wrapped[1])
                if vek is None or len(vek) != 32 or not self._opens(vek):
                    continue
                self.vek = vek
                self.unlocked_by = ("personal recovery key"
                                    if user == APFS_FV_PERSONAL_RECOVERY_KEY_UUID else "password")
                return True
        return False

    def _opens(self, vek):
        """True when vek decrypts the volume's tree root to a node that checks out,
        read without touching the walker's own state."""
        w = self._w
        vol_omap_oid, root_oid = struct.unpack_from("<QQ", self._sb, 128)
        saved = w._current, w._volume_omap                             # pylint: disable=protected-access
        try:
            w._current, w._volume_omap = None, {}                      # pylint: disable=protected-access
            root = w._read_omap(vol_omap_oid).get(root_oid)            # pylint: disable=protected-access
        except (ValueError, OSError, struct.error):
            root = None
        finally:
            w._current, w._volume_omap = saved                         # pylint: disable=protected-access
        if root is None:
            return False
        pair = (_BDE_AES.new(vek[:16], _BDE_AES.MODE_ECB),
                _BDE_AES.new(vek[16:], _BDE_AES.MODE_ECB))
        raw = read_at(w.fh, w.base + root * w.block_size, w.block_size)
        return _apfs_fletcher_ok(_xts_crypt(pair, raw, root * (w.block_size // 512)))

    def summary(self):
        return (f"APFS encrypted, opened with {_apfs_opened_with(self.unlocked_by)}"
                if self.vek is not None else "APFS encrypted, locked")

    def locked_note(self):
        """Why the volume was not read, and what would open it."""
        if self.vek is not None:
            return f"opened with {_apfs_opened_with(self.unlocked_by)}"
        if self.why:
            return f"not read: {self.why}"
        prk = any(u == APFS_FV_PERSONAL_RECOVERY_KEY_UUID for u, _d in self.records)
        what = "a password or its personal recovery key" if prk else "a password"
        text = ("none of the passwords given opens it" if self.tried
                else f"it opens with {what}")
        if self.hint:
            text += f' (its passphrase hint, as stored: "{self.hint}")'
        return text


class ApfsImage:
    """An image with the keys unlock_apfs() derived for its encrypted APFS volumes:
    ``apfs_keys`` maps (container uuid, volume uuid) to (volume key, what opened
    it) and ``apfs_found`` holds every ApfsLock, opened or not. An ApfsWalker made
    over it reads those volumes decrypted; reads are the image's own."""

    def __init__(self, fh, found):
        self._fh = fh
        self.apfs_found = list(found)
        self.apfs_keys = {(lk.container_uuid, lk.uuid): (lk.vek, lk.unlocked_by)
                          for lk in found if lk.vek is not None}
        self.read, self.seek, self.tell = fh.read, fh.seek, fh.tell

    def __getattr__(self, name):
        return getattr(self._fh, name)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self._fh.close()


def unlock_apfs(fh, size=None, passwords=()):
    """Find the encrypted APFS volumes whose blocks are ciphertext in an opened
    image and open those one of the passwords opens (tried as a user's password
    and as the personal recovery key). Returns (fh, found): fh is an ApfsImage when
    there is any such volume, so the walkers made over it read the opened ones
    decrypted and say why the others were not read, else the image unchanged;
    found holds one ApfsLock per such volume, opened or not."""
    if size is None:
        size = image_size(fh)
    regions, _names, containers, protective = partition_regions(fh, size)
    found = []
    for label, base, _rsize in regions:
        if label in containers or label in protective:
            continue
        head = read_at(fh, base, 4096)
        if len(head) < 4096 or head[32:36] != APFS_NX_MAGIC:
            continue
        try:
            w = ApfsWalker(fh, base)
        except (ValueError, OSError, struct.error):
            continue
        for i in range(len(w.volumes)):
            if w.encryption(i) != "locked":
                continue
            lk = ApfsLock(w, i, label)
            lk.unlock(passwords)
            found.append(lk)
    return (ApfsImage(fh, found) if found else fh), found


# ---------------------------------------------------------------------------
# LUKS1 and LUKS2
# ---------------------------------------------------------------------------
# The layouts are cryptsetup's (gitlab.com/cryptsetup/cryptsetup, docs/
# on-disk-format.pdf for LUKS1 and docs/on-disk-format-luks2.pdf for LUKS2).
# LUKS1 is a big-endian header: the cipher name and mode, the hash, the payload
# offset in sectors, the master key's length, a PBKDF2 digest of the master key
# (its salt and iterations), and eight keyslots of 48 bytes from byte 208, each
# active or not, with its PBKDF2 iterations and salt, the offset of its key
# material in sectors and its anti-forensic stripe count. LUKS2 is a binary
# header, twice (the second at the first's size), each with a SHA checksum over
# itself and its JSON area, the copy with the higher sequence id in force; the
# JSON names the keyslots (their KDF, PBKDF2 or Argon2, their anti-forensic
# split, and the area their key material is in, with the cipher it is encrypted
# with), the digests that confirm a master key, and the data segments.
#
# A passphrase opens a keyslot: the KDF gives the key the slot's material is
# encrypted with, in 512-byte sectors numbered from 0; the material is the
# master key split into stripes (AF, luks1 style: each stripe XORed into a
# running block that is diffused with the hash, the last stripe XORed on top);
# the master key is right when its PBKDF2 digest matches the one stored. The
# data is then decrypted sector by sector, its IV the sector number, counted
# from the start of the data in 512-byte units (dm-crypt's default; a LUKS2
# segment's larger sector_size changes how much one IV covers, not its units).
#
# Read: AES in XTS (plain64, plain) and CBC (essiv:<hash>, plain64, plain);
# PBKDF2 with the hashes hashlib has; Argon2i and Argon2id when argon2-cffi is
# installed. Not read: other ciphers, a LUKS2 header kept apart from the data
# (detached), a keyslot type other than luks2, and a volume still being
# re-encrypted. AES needs pycryptodome, as BitLocker does.

try:
    from argon2 import low_level as _ARGON2                    # argon2-cffi
except ImportError:
    _ARGON2 = None

LUKS_MAGIC = b"LUKS\xba\xbe"
LUKS_MAX_KEY_BYTES = 128             # a 512-bit XTS key is 64; nothing cryptsetup writes is longer
LUKS_MAX_STRIPES = 65536             # cryptsetup writes 4000
LUKS_MAX_PBKDF2 = 50_000_000         # benchmarks give single millions
LUKS_MAX_ARGON2_KIB = 4 * 1024 * 1024    # cryptsetup's --pbkdf-memory maximum


def _luks_cipher_problem(spec):
    """Why a LUKS cipher spec is not one this reads, else ''."""
    parts = (spec or "").lower().split("-", 1)
    if len(parts) != 2 or parts[0] != "aes":
        return f"its {spec or 'unnamed'} cipher is not one this reads (only AES)"
    mode = parts[1]
    if mode in ("xts-plain64", "xts-plain", "cbc-plain64", "cbc-plain") or mode.startswith("cbc-essiv:"):
        return ""
    return f"its {spec} mode is not one this reads"


def _luks2_shape(meta):
    """Raise ValueError unless the LUKS2 JSON has the shape cryptsetup writes."""
    def need(cond, what):
        if not cond:
            raise ValueError(f"its LUKS2 metadata has {what}")
    need(isinstance(meta, dict), "no object at its top")
    for key in ("keyslots", "segments", "digests"):
        need(isinstance(meta.get(key), dict), f"{key} that are not an object")
    for kid, ks in meta["keyslots"].items():
        need(isinstance(ks, dict), f"keyslot {kid} that is not an object")
        if ks.get("type") != "luks2":
            continue
        for part in ("kdf", "af", "area"):
            need(isinstance(ks.get(part), dict), f"keyslot {kid} with no {part} object")
        kdf = ks["kdf"]
        need(isinstance(kdf.get("salt"), str), f"keyslot {kid} with no salt")
        fields = (("iterations", "hash") if kdf.get("type") == "pbkdf2" else ("time", "memory", "cpus"))
        for f in fields:
            need(f in kdf, f"keyslot {kid} with no {f}")
        for f in ("offset", "encryption", "key_size"):
            need(f in ks["area"], f"keyslot {kid} whose area has no {f}")
        need(str(ks.get("key_size", "")).isdigit() and str(ks["area"]["key_size"]).isdigit()
             and str(ks["area"]["offset"]).isdigit() and str(ks["af"].get("stripes", "")).isdigit(),
             f"keyslot {kid} with a size, offset or stripe count that is not a number")
    for sid, sg in meta["segments"].items():
        need(isinstance(sg, dict), f"segment {sid} that is not an object")
        if sg.get("type") == "crypt":
            need(str(sg.get("offset", "")).isdigit() and (sg.get("size") == "dynamic"
                                                         or str(sg.get("size", "")).isdigit())
                 and isinstance(sg.get("encryption"), str),
                 f"segment {sid} with an offset, size or cipher that does not read")
    for did, dg in meta["digests"].items():
        need(isinstance(dg, dict) and isinstance(dg.get("keyslots", []), list),
             f"digest {did} that does not read")
        if dg.get("type") == "pbkdf2":
            need(str(dg.get("iterations", "")).isdigit() and isinstance(dg.get("salt"), str)
                 and isinstance(dg.get("digest"), str), f"digest {did} that does not read")
LUKS_CHUNK = 65536
LUKS_CACHE_CHUNKS = 256


def _luks_af_merge(material, key_bytes, stripes, hash_name):
    """The master key from its anti-forensic split (luks1 AF: af.c AF_merge)."""
    import hashlib                                  # pylint: disable=import-outside-toplevel

    def diffuse(block):
        size = hashlib.new(hash_name).digest_size
        out = bytearray()
        for i in range(-(-len(block) // size)):
            piece = block[i * size:(i + 1) * size]
            out += hashlib.new(hash_name, struct.pack(">I", i) + piece).digest()[:len(piece)]
        return bytes(out)
    d = bytes(key_bytes)
    for i in range(stripes - 1):
        stripe = material[i * key_bytes:(i + 1) * key_bytes]
        d = diffuse(bytes(a ^ b for a, b in zip(d, stripe)))
    last = material[(stripes - 1) * key_bytes:stripes * key_bytes]
    return bytes(a ^ b for a, b in zip(d, last))


class _LuksCipher:
    """One LUKS cipher spec (cipher-mode-iv, as cryptsetup names them) with its
    key: decrypt() takes whole sectors and the IV number of the first. Raises
    ValueError for a spec this does not read."""

    def __init__(self, spec, key):
        import hashlib                              # pylint: disable=import-outside-toplevel
        if _BDE_AES is None:
            raise ValueError("AES needs the pycryptodome package")
        parts = spec.lower().split("-", 1)
        if len(parts) != 2 or parts[0] != "aes":
            raise ValueError(f"the {spec} cipher is not one this reads (only AES)")
        mode = parts[1]
        self.spec = spec
        if mode in ("xts-plain64", "xts-plain"):
            half = len(key) // 2
            self.kind = "xts"
            self.pair = (_BDE_AES.new(key[:half], _BDE_AES.MODE_ECB),
                         _BDE_AES.new(key[half:], _BDE_AES.MODE_ECB))
            self.wrap = mode.endswith("-plain")
        elif mode in ("cbc-plain64", "cbc-plain") or mode.startswith("cbc-essiv:"):
            self.kind = "cbc"
            self.key = key
            self.essiv = None
            if mode.startswith("cbc-essiv:"):
                hname = mode.split(":", 1)[1]
                if hname not in hashlib.algorithms_available:
                    raise ValueError(f"the ESSIV hash {hname} is not available here")
                self.essiv = _BDE_AES.new(hashlib.new(hname, key).digest(), _BDE_AES.MODE_ECB)
            self.wrap = mode == "cbc-plain"
        else:
            raise ValueError(f"the {spec} mode is not one this reads")

    def decrypt(self, data, first, unit=512, iv_unit=512):
        """Whole `unit`-byte sectors; sector i's IV is first + i * unit / iv_unit."""
        n = len(data) // unit
        step = unit // iv_unit
        if self.kind == "xts":
            if step == 1 and not self.wrap:
                return _xts_crypt(self.pair, data[:n * unit], first, unit)
            out = bytearray()
            for i in range(n):
                iv = first + i * step
                out += _xts_crypt(self.pair, data[i * unit:(i + 1) * unit],
                                  iv & 0xFFFFFFFF if self.wrap else iv, unit)
            return bytes(out)
        out = bytearray()
        for i in range(n):
            iv = first + i * step
            if self.wrap:
                iv &= 0xFFFFFFFF
            ivb = iv.to_bytes(16, "little")
            if self.essiv is not None:
                ivb = self.essiv.encrypt(ivb)
            out += _BDE_AES.new(self.key, _BDE_AES.MODE_CBC, ivb).decrypt(data[i * unit:(i + 1) * unit])
        return bytes(out)


class Luks:
    """A LUKS1 or LUKS2 container at base in fh: its header, read before any
    passphrase is given, and once unlock() finds one, its data in plaintext.
    Luks.open() returns None for anything that is not LUKS."""

    @classmethod
    def open(cls, fh, base, size=None):
        head = read_at(fh, base, 4096)
        if len(head) < 1024 or head[:6] != LUKS_MAGIC:
            return None
        if size is None:
            size = image_size(fh) - base
        return cls(fh, base, size, head)

    def __init__(self, fh, base, size, head):
        # Everything lines(), summary() and unlock() read has a value before the
        # header is parsed, so a header that does not parse leaves a container
        # that is reported as not read, and why, rather than an exception.
        self.fh, self.base, self.size = fh, base, size
        self.version = struct.unpack_from(">H", head, 6)[0]
        self.mk, self.why, self.tried, self.unlocked_by = None, "", [], None
        self.label, self.problems, self.uuid, self.cipher, self.hash = "LUKS", [], "", "", ""
        self.offset, self.data_size, self.sector_size, self.iv_tweak = 0, 0, SECTOR, 0
        self.key_bytes, self.keyslots, self.digests = 0, [], []
        self._cache = collections.OrderedDict()
        self._cipher = None
        try:
            if self.version == 1:
                self._luks1(head)
            elif self.version == 2:
                self._luks2()
            else:
                raise ValueError(f"LUKS version {self.version}")
            self.data_size = max(0, self.size - self.offset) if self.data_size is None else self.data_size
            unread = _luks_cipher_problem(self.cipher)
            if unread:
                raise ValueError(unread)
        except Exception as exc:                       # pylint: disable=broad-except
            self.keyslots, self.digests, self.data_size = [], [], 0
            self.why = f"its header does not read ({type(exc).__name__}: {exc})" \
                if not isinstance(exc, ValueError) else str(exc)
        if not self.why and _BDE_AES is None:
            # known before any passphrase is tried, as for BitLocker and APFS
            self.why = ("reading it needs the optional pycryptodome package, which this "
                        "Python does not have")

    def _luks1(self, h):
        name = h[8:40].split(b"\0")[0].decode("ascii", "replace")
        mode = h[40:72].split(b"\0")[0].decode("ascii", "replace")
        self.hash = h[72:104].split(b"\0")[0].decode("ascii", "replace")
        payload, self.key_bytes = struct.unpack_from(">II", h, 104)
        self.mk_digest, self.mk_salt = h[112:132], h[132:164]
        self.mk_iterations, = struct.unpack_from(">I", h, 164)
        self.uuid = h[168:208].split(b"\0")[0].decode("ascii", "replace")
        self.cipher = f"{name}-{mode}"
        self.offset, self.data_size, self.sector_size = payload * SECTOR, None, SECTOR
        self.keyslots = []
        for i in range(8):
            active, iters = struct.unpack_from(">II", h, 208 + 48 * i)
            salt = h[208 + 48 * i + 8:208 + 48 * i + 40]
            off, stripes = struct.unpack_from(">II", h, 208 + 48 * i + 40)
            if active == 0x00AC71F3:
                self.keyslots.append(dict(id=str(i), kdf=dict(type="pbkdf2", hash=self.hash,
                                                             iterations=iters, salt=salt),
                                          offset=off * SECTOR, stripes=stripes, af_hash=self.hash,
                                          cipher=self.cipher, key_bytes=self.key_bytes,
                                          kdf_bytes=self.key_bytes))
        self.digests = [dict(hash=self.hash, iterations=self.mk_iterations, salt=self.mk_salt,
                             digest=self.mk_digest, keyslots=None)]

    def _luks2(self):
        import base64                               # pylint: disable=import-outside-toplevel
        import hashlib                              # pylint: disable=import-outside-toplevel
        # The second copy is at the first's size; when the first does not give a
        # size that reads, cryptsetup looks for the second at fixed offsets
        # (luks2_disk_metadata.c, LUKS2_HDR2_OFFSETS), and so does this.
        first = read_at(self.fh, self.base, 4096)
        hdr_size, = struct.unpack_from(">Q", first, 8)
        places = [0]
        if 16384 <= hdr_size <= 4 << 20:
            places.append(hdr_size)
        places += [o for o in (0x4000, 0x8000, 0x10000, 0x20000, 0x40000, 0x80000, 0x100000,
                               0x200000, 0x400000) if o not in places]
        best_seq, best_raw, best_size = -1, None, 0
        for at in places:
            head = read_at(self.fh, self.base + at, 512)
            if len(head) < 512 or head[:6] not in (LUKS_MAGIC, b"SKUL\xba\xbe"):
                continue
            size, seqid = struct.unpack_from(">QQ", head, 8)
            stored_at, = struct.unpack_from(">Q", head, 256)
            if not 16384 <= size <= 4 << 20 or stored_at != at:
                self.problems.append(f"the header copy at byte {at:,} names another size or place")
                continue
            raw = read_at(self.fh, self.base + at, size)
            alg = raw[72:104].split(b"\0")[0].decode("ascii", "replace")
            if alg not in hashlib.algorithms_available:
                self.problems.append(f"header copy at byte {at:,}: checksum {alg} not available")
                continue
            body = bytearray(raw)
            body[448:512] = bytes(64)
            digest = hashlib.new(alg, bytes(body)).digest()
            if len(raw) < size or raw[448:448 + len(digest)] != digest:
                self.problems.append(f"the header copy at byte {at:,} fails its checksum")
                continue
            if best_raw is None or seqid > best_seq:
                best_seq, best_raw, best_size = seqid, raw, size
        if best_raw is None:
            raise ValueError("no LUKS2 header copy passes its checksum")
        raw = best_raw
        self.uuid = raw[168:208].split(b"\0")[0].decode("ascii", "replace")
        self.label = raw[24:72].split(b"\0")[0].decode("utf-8", "replace") or "LUKS"
        meta = json.loads(raw[4096:best_size].split(b"\0", 1)[0])
        _luks2_shape(meta)
        if meta.get("requirements", {}).get("mandatory"):
            raise ValueError("its header names requirements this does not meet "
                             f"({', '.join(map(str, meta['requirements']['mandatory']))})")
        segs = meta["segments"]
        if len(segs) != 1 or any(sg.get("type") != "crypt" for sg in segs.values()):
            raise ValueError("a volume being re-encrypted, or with more than one data segment")
        seg = next(iter(segs.values()))
        if seg.get("integrity"):
            raise ValueError("its data carries dm-integrity, which this does not read")
        self.cipher = seg["encryption"]
        self.offset = int(seg["offset"])
        self.data_size = None if seg["size"] == "dynamic" else int(seg["size"])
        self.sector_size = int(seg.get("sector_size", 512))
        if self.sector_size not in (512, 1024, 2048, 4096):
            raise ValueError(f"a sector size of {self.sector_size}")
        self.iv_tweak = int(seg.get("iv_tweak", 0))
        b64 = base64.b64decode
        for kid, ks in sorted(meta["keyslots"].items(), key=lambda kv: int(kv[0])):
            if ks.get("type") != "luks2" or ks.get("af", {}).get("type") != "luks1":
                self.problems.append(f"keyslot {kid} is of a type this does not read")
                continue
            kdf = dict(ks["kdf"])
            kdf["salt"] = b64(kdf["salt"])
            # The key the keyslot's material is encrypted with is the area's own
            # length (luks2_keyslot_luks2.c), which need not be the volume key's.
            self.keyslots.append(dict(id=kid, kdf=kdf, offset=int(ks["area"]["offset"]),
                                      stripes=int(ks["af"]["stripes"]), af_hash=ks["af"]["hash"],
                                      cipher=ks["area"]["encryption"], key_bytes=int(ks["key_size"]),
                                      kdf_bytes=int(ks["area"]["key_size"])))
        self.digests = [dict(hash=d["hash"], iterations=int(d["iterations"]), salt=b64(d["salt"]),
                             digest=b64(d["digest"]), keyslots=set(d["keyslots"]))
                        for d in meta["digests"].values() if d.get("type") == "pbkdf2"]
        self.key_bytes = self.keyslots[0]["key_bytes"] if self.keyslots else 0

    def _derive(self, kdf, password, length):
        import hashlib                              # pylint: disable=import-outside-toplevel
        # Costs past cryptsetup's own limits (its --pbkdf-memory maximum of 4 GiB,
        # and time and iteration counts no benchmark gives) are refused rather than
        # run: a crafted keyslot could otherwise hang the reader or exhaust memory.
        if kdf["type"] == "pbkdf2":
            if not 0 < int(kdf["iterations"]) <= LUKS_MAX_PBKDF2:
                raise ValueError(f"a PBKDF2 iteration count of {kdf['iterations']}, past what this runs")
            return hashlib.pbkdf2_hmac(kdf["hash"], password, kdf["salt"], int(kdf["iterations"]), length)
        if kdf["type"] in ("argon2i", "argon2id"):
            if not (0 < int(kdf["memory"]) <= LUKS_MAX_ARGON2_KIB and 0 < int(kdf["time"]) <= 1000
                    and 0 < int(kdf["cpus"]) <= 64):
                raise ValueError("Argon2 costs past cryptsetup's own limits")
            if _ARGON2 is None:
                raise ValueError("its Argon2 keyslot needs the argon2-cffi package")
            kind = _ARGON2.Type.ID if kdf["type"] == "argon2id" else _ARGON2.Type.I
            return _ARGON2.hash_secret_raw(password, kdf["salt"], int(kdf["time"]), int(kdf["memory"]),
                                           int(kdf["cpus"]), length, kind, 19)
        raise ValueError(f"the {kdf['type']} key derivation is not one this reads")

    def _try(self, slot, password):
        """The master key a passphrase opens in a keyslot, else None."""
        import hashlib                              # pylint: disable=import-outside-toplevel
        kb, stripes = slot["key_bytes"], slot["stripes"]
        if not (0 < kb <= LUKS_MAX_KEY_BYTES and 0 < slot["kdf_bytes"] <= LUKS_MAX_KEY_BYTES
                and 0 < stripes <= LUKS_MAX_STRIPES):
            raise ValueError(f"keyslot {slot['id']} has a key size or stripe count past what "
                             "cryptsetup writes")
        length = -(-kb * stripes // SECTOR) * SECTOR
        material = read_at(self.fh, self.base + slot["offset"], length)
        if len(material) < length:
            raise ValueError("its key material lies past the end of the image")
        key = self._derive(slot["kdf"], password, slot["kdf_bytes"])
        plain = _LuksCipher(slot["cipher"], key).decrypt(material, 0)
        mk = _luks_af_merge(plain, kb, stripes, slot["af_hash"])
        for d in self.digests:
            listed = d["keyslots"] or ()
            if d["keyslots"] is not None and slot["id"] not in listed:
                continue
            if not 0 < d["iterations"] <= LUKS_MAX_PBKDF2:
                raise ValueError(f"a digest iteration count of {d['iterations']}, past what this runs")
            if hashlib.pbkdf2_hmac(d["hash"], mk, d["salt"], d["iterations"], len(d["digest"])) == d["digest"]:
                return mk
        return None

    def unlock(self, passwords):
        """Try each passphrase on each keyslot; True once one opens the volume."""
        if self.mk is not None:
            return True
        if not self.keyslots:
            self.why = self.why or "no keyslot this reads"
            return False
        for pw in passwords:
            pwb = pw.encode("utf-8") if isinstance(pw, str) else pw
            for slot in self.keyslots:
                try:
                    mk = self._try(slot, pwb)
                except Exception as exc:                   # pylint: disable=broad-except
                    # a keyslot this cannot use is said, and the next one tried
                    self.why = (str(exc) if isinstance(exc, ValueError)
                                else f"keyslot {slot['id']}: {type(exc).__name__}: {exc}")
                    continue
                self.tried.append(slot["id"])
                if mk is not None:
                    try:
                        self._cipher = _LuksCipher(self.cipher, mk)
                    except ValueError as exc:
                        self.why = str(exc)
                        return False
                    self.mk, self.unlocked_by, self.why = mk, f"keyslot {slot['id']}", ""
                    return True
        return False

    def read(self, off, n):
        """n plaintext bytes at data offset off (short at the end of the data)."""
        out, pos, end = bytearray(), off, min(off + n, self.data_size)
        while pos < end:
            ci = pos // LUKS_CHUNK
            chunk = self._cache.get(ci)
            if chunk is None:
                start = ci * LUKS_CHUNK
                raw = read_at(self.fh, self.base + self.offset + start,
                              min(LUKS_CHUNK, self.data_size - start))
                whole = len(raw) - len(raw) % self.sector_size
                tweak = getattr(self, "iv_tweak", 0)
                chunk = self._cipher.decrypt(raw[:whole], tweak + start // SECTOR, self.sector_size)
                self._cache[ci] = chunk
                if len(self._cache) > LUKS_CACHE_CHUNKS:
                    self._cache.popitem(last=False)
            else:
                self._cache.move_to_end(ci)
            s = pos - ci * LUKS_CHUNK
            take = min(len(chunk) - s, end - pos)
            if take <= 0:
                break
            out += chunk[s:s + take]
            pos += take
        return bytes(out)

    def lines(self):
        return [f"LUKS{self.version}, {self.cipher}, {self.key_bytes * 8}-bit key, "
                f"data at byte {self.offset:,}" + (f", {self.sector_size}-byte sectors"
                                                   if self.sector_size != SECTOR else ""),
                f"{len(self.keyslots)} keyslot(s) in use; uuid {self.uuid}"] + self.problems

    def summary(self):
        return (f"LUKS{self.version} {self.cipher}, opened with {self.unlocked_by}"
                if self.mk is not None else f"LUKS{self.version}, locked")

    def locked_note(self):
        if self.why:
            return f"LUKS-encrypted and not read: {self.why}"
        if self.tried:
            return "LUKS-encrypted and not read: no passphrase given opens a keyslot"
        return "LUKS-encrypted and not read: give its passphrase"


class LuksImage:
    """An image read through read_at() with its opened LUKS volumes' data
    decrypted in place, at the data's own offset, so identify_fs() and every
    walker read the plaintext there. ``luks`` maps each opened container's base to
    its Luks object, ``luks_found`` lists every one; anything else is the
    image's own attribute."""

    def __init__(self, fh, opened, found=()):
        self._fh, self.luks, self.luks_found = fh, dict(opened), list(found)
        self.size = image_size(fh)
        self._spans = sorted((b + lk.offset, b + lk.offset + lk.data_size, lk)
                             for b, lk in self.luks.items())
        self._pos = 0

    def __getattr__(self, name):
        return getattr(self._fh, name)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self._fh.close()

    def seek(self, off, whence=0):
        self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        end = self.size if n is None or n < 0 else min(self.size, self._pos + n)
        out = bytearray()
        while self._pos < end:
            span = next((s for s in self._spans if s[0] <= self._pos < s[1]), None)
            if span is not None:
                take = min(end, span[1]) - self._pos
                got = span[2].read(self._pos - span[0], take)
            else:
                nxt = min([s[0] for s in self._spans if s[0] > self._pos] + [end])
                self._fh.seek(self._pos)
                got = self._fh.read(nxt - self._pos)
            if not got:
                break
            out += got
            self._pos += len(got)
        return bytes(out)


def unlock_luks(fh, size=None, passwords=()):
    """Find the LUKS containers in an opened image and open those a passphrase
    opens. Returns (fh, found): fh is a LuksImage when there is any LUKS container
    (``luks`` holds the opened ones, ``luks_found`` every one), else the image
    unchanged; found holds one Luks per container, opened or not. Apply it
    before lvm_image(), so a physical volume inside a LUKS container is seen."""
    if size is None:
        size = image_size(fh)
    regions, _names, containers, protective = partition_regions(fh, size)
    found, opened = [], {}
    for label, base, rsize in regions:
        if label in containers or label in protective:
            continue
        lk = Luks.open(fh, base, rsize)
        if lk is None:
            continue
        lk.label = label
        if lk.mk is None and not lk.why and lk.unlock(passwords):
            opened[base] = lk
        found.append(lk)
    if not found:
        return fh, found
    return LuksImage(fh, opened, found), found


def identify_luks(fh, base, size=None):
    """("luks", lines) for a LUKS container at base, else None."""
    head = read_at(fh, base, 8)
    if head[:6] != LUKS_MAGIC:
        return None
    opened = getattr(fh, "luks", {}).get(base)
    lk = opened or next((x for x in getattr(fh, "luks_found", ()) if x.base == base), None) \
        or Luks.open(fh, base, size)
    if lk is None:
        return None
    return "luks", ([lk.summary()] + lk.lines())


# ---------------------------------------------------------------------------
# LVM2 physical volumes and their linear logical volumes
# ---------------------------------------------------------------------------
# The layout is lvm2's own (github.com/lvmteam/lvm2 at tag v2_03_43, commit
# 7b0bce6909611966bdc1e17c2408e1ec3b0f8c17): a label in one of the first four
# 512-byte sectors (lib/label/label.h, "LABELONE", struct label_header) whose
# contents are a pv_header (lib/format_text/layout.h): the PV's id, its size, a
# zero-ended list of data areas and a zero-ended list of metadata areas. A
# metadata area starts with an mda_header (magic " LVM2 x[5A%r0N*>") whose first
# raw_locn is the committed metadata text, a circular buffer that wraps past the
# end of the area back to just after the header (format-text.c
# _vg_read_raw_area). Every checksum is lvm2's calc_crc (lib/misc/crc.c): the
# CRC-32 table step from 0xf597a6cf, with no inversion before or after. The text
# is lvm2's configuration syntax (export.c writes it): sections in braces,
# "key = value", strings, integers and bracketed lists, # comments.
#
# A logical volume is read only when it is linear and its extents lie one after
# another on one physical volume in this image: it is then a byte range of the
# image like a partition, and is walked as one, at its true offset. Any other
# (split into separate runs, striped, mirrored, thin, a snapshot, a cache, or on
# a physical volume not in this image) is listed with why it was not read.

LVM_LABEL_ID = b"LABELONE"
LVM2_LABEL = b"LVM2 001"
LVM_FMTT_MAGIC = b" LVM2 x[5A%r0N*>"
LVM_INITIAL_CRC = 0xf597a6cf
LVM_MDA_HEADER_SIZE = 512
LVM_RAW_LOCN_IGNORED = 0x1
LVM_MAX_SECTION_DEPTH = 128            # libdm-config.c MAX_SECTION_DEPTH


def lvm_crc(data, initial=LVM_INITIAL_CRC):
    """lvm2's calc_crc: the CRC-32 table step with no inversion either side."""
    return (~binascii.crc32(data, ~initial & 0xffffffff)) & 0xffffffff


# Whitespace and comments, a comment running to the end of its line: a pattern
# that let one stop short would hand its last digits to the next token (a
# trailing "# ... 2026" read as a value), and one whose pieces could split a
# run of "#" two ways would backtrack exponentially on a long one.
_LVM_SKIP = r'(?:\s|#[^\n]*(?:\n|$))*'
_LVM_TOKEN = re.compile(_LVM_SKIP + r'(?:("(?:[^"\\]|\\.)*")|([-+]?\d+(?![\w.])|[\w.+-]+)|([={}\[\],]))')
_LVM_REST = re.compile(_LVM_SKIP)


def _lvm_tokens(text):
    pos, out = 0, []
    while True:
        m = _LVM_TOKEN.match(text, pos)
        if not m or m.end() == pos:
            break
        pos = m.end()
        s, word, punct = m.groups()
        if s is not None:
            # dm_unescape_double_quotes undoes only \" and \\.
            out.append(("s", re.sub(r'\\(["\\])', r"\1", s[1:-1])))
        elif word is not None:
            if re.fullmatch(r"[-+]?0\d+", word):
                # lvm2 reads numbers with strtoll(..., 0), so a leading zero is
                # octal; lvm2 never writes one, and it is refused, not misread.
                raise ValueError(f"a number with a leading zero ({word}) in LVM metadata")
            out.append(("i", int(word)) if re.fullmatch(r"[-+]?\d+", word) else ("w", word))
        elif punct is not None:
            out.append(("p", punct))
    if _LVM_REST.match(text, pos).end() != len(text):
        raise ValueError(f"LVM metadata text does not parse near byte {pos}")
    return out


def lvm_config(text):
    """lvm2 metadata text as nested dicts: a section is a dict, a list a list,
    a string a str and a number an int. Raises ValueError for text that does
    not parse, never anything else."""
    toks, i = _lvm_tokens(text), 0

    def take():
        nonlocal i
        if i >= len(toks):
            raise ValueError("LVM metadata text ends inside a value or section")
        i += 1
        return toks[i - 1]

    def peek():
        if i >= len(toks):
            raise ValueError("LVM metadata text ends inside a value or section")
        return toks[i]

    def value():
        kind, v = take()
        if (kind, v) == ("p", "["):
            items = []
            while peek() != ("p", "]"):
                if peek() == ("p", ","):
                    take()
                    continue
                items.append(value())
            take()
            return items
        if kind in ("s", "i"):
            return v
        raise ValueError(f"unexpected {v!r} in LVM metadata")

    def section(end, depth):
        if depth > LVM_MAX_SECTION_DEPTH:
            raise ValueError("LVM metadata sections nest too deep")
        out = {}
        while i < len(toks) if end is None else peek() != end:
            kind, key = take()
            if kind != "w":
                raise ValueError(f"unexpected {key!r} in LVM metadata")
            nxt = take()
            if nxt == ("p", "{"):
                out[key] = section(("p", "}"), depth + 1)
                take()
            elif nxt == ("p", "="):
                out[key] = value()
            else:
                raise ValueError(f"expected = or {{ after {key!r} in LVM metadata")
        return out

    return section(None, 0)


class LvmPv:
    """The label, pv_header and newest readable metadata of an LVM2 physical
    volume at `base`. A label is accepted as lvm2 accepts it (label.c
    _find_lvm_header): "LABELONE" in one of the first four sectors, naming that
    sector and passing its checksum, and of type "LVM2 001"; a label that fails
    is passed over and the next sector tried. Raises ValueError when none is
    accepted. `mda_ok` counts the metadata area headers that check out."""

    def __init__(self, fh, base, size=None):   # pylint: disable=unused-argument
        # size is taken for the same signature as the identifiers; the label
        # and the pv_header say where everything is.
        self.base = base
        self.problems = []
        for sector in range(4):
            raw = read_at(fh, base + sector * SECTOR, SECTOR)
            if len(raw) < SECTOR or raw[:8] != LVM_LABEL_ID:
                continue
            sector_xl, crc_xl, offset_xl = struct.unpack_from("<QII", raw, 8)
            if sector_xl != sector or lvm_crc(raw[20:]) != crc_xl or raw[24:32] != LVM2_LABEL:
                continue
            if 32 <= offset_xl <= SECTOR - 72:
                break
        else:
            raise ValueError("no LVM2 label lvm2 would accept in the first four sectors")
        self.label_sector = sector
        self.uuid = raw[offset_xl:offset_xl + 32].decode("ascii", "replace")
        self.device_size, = struct.unpack_from("<Q", raw, offset_xl + 32)
        pos, lists = offset_xl + 40, ([], [])
        for which in (0, 1):
            while pos + 16 <= SECTOR:
                off, n = struct.unpack_from("<QQ", raw, pos)
                pos += 16
                if not off:                # lvm2 ends each list on a zero offset
                    break
                lists[which].append((off, n))
        self.data_areas, self.metadata_areas = lists
        self.mda_ok = 0
        self.vg = None                 # (vg name, vg section, seqno) of the newest copy
        for off, n in self.metadata_areas:
            try:
                found = self._metadata(fh, off, n)
            except ValueError as exc:
                self.problems.append(f"metadata area at byte {off:,}: {exc}")
                continue
            if found and (self.vg is None or found[2] > self.vg[2]):
                self.vg = found

    def _metadata(self, fh, off, _n):
        head = read_at(fh, self.base + off, LVM_MDA_HEADER_SIZE)
        if len(head) < LVM_MDA_HEADER_SIZE:
            raise ValueError("header past the end of the image")
        crc_xl, magic, _version, start, size = struct.unpack_from("<I16sIQQ", head, 0)
        if magic != LVM_FMTT_MAGIC:
            raise ValueError("no metadata area magic")
        if lvm_crc(head[4:]) != crc_xl:
            raise ValueError("metadata area header checksum does not match")
        if start != off or size < LVM_MDA_HEADER_SIZE:
            raise ValueError("metadata area header disagrees with the pv_header")
        self.mda_ok += 1
        r_off, r_size, checksum, flags = struct.unpack_from("<QQII", head, 40)
        if not r_off and not r_size:
            return None                # an area with no metadata written yet
        if flags & LVM_RAW_LOCN_IGNORED:
            return None                # lvm2 keeps this copy but does not use it
        if r_off >= size or r_size > size - LVM_MDA_HEADER_SIZE:
            raise ValueError("metadata location outside the area")
        wrap = max(0, r_off + r_size - size)
        text = read_at(fh, self.base + off + r_off, r_size - wrap)
        if wrap:
            text += read_at(fh, self.base + off + LVM_MDA_HEADER_SIZE, wrap)
        if lvm_crc(text) != checksum:
            raise ValueError("metadata text checksum does not match")
        cfg = lvm_config(text.split(b"\0", 1)[0].decode("utf-8", "replace"))
        vgs = [(k, v) for k, v in cfg.items() if isinstance(v, dict)]
        if len(vgs) != 1:
            raise ValueError(f"{len(vgs)} volume group sections in the metadata text")
        name, vg = vgs[0]
        _lvm_vg_shape(vg)
        return name, vg, vg.get("seqno", 0)


def _lvm_vg_shape(vg):
    """Raise ValueError unless the volume group section has the shape lvm2
    writes: numbers where it writes numbers, sections where it writes sections,
    a list of words for a status. A copy that does not is refused like one whose
    checksum fails, so nothing later meets a value of the wrong kind."""
    def need(cond, what):
        if not cond:
            raise ValueError(f"the volume group metadata has {what}")

    def num(sec, key, where):
        need(isinstance(sec.get(key, 0), int), f"a {key} that is not a number in {where}")

    num(vg, "seqno", "the volume group")
    num(vg, "extent_size", "the volume group")
    need(isinstance(vg.get("id", ""), str), "an id that is not a string")
    for key in ("physical_volumes", "logical_volumes"):
        need(isinstance(vg.get(key, {}), dict), f"a {key} that is not a section")
    for name, pv in (vg.get("physical_volumes") or {}).items():
        need(isinstance(pv, dict), f"physical volume {name} that is not a section")
        need(isinstance(pv.get("id", ""), str), f"physical volume {name} with an id that is not a string")
        for key in ("pe_start", "pe_count"):
            num(pv, key, f"physical volume {name}")
    for name, lv in (vg.get("logical_volumes") or {}).items():
        need(isinstance(lv, dict), f"logical volume {name} that is not a section")
        status = lv.get("status", [])
        need(isinstance(status, list) and all(isinstance(x, str) for x in status),
             f"logical volume {name} with a status that is not a list of words")
        for key, seg in lv.items():
            if not key.startswith("segment") or key == "segment_count":
                continue
            need(isinstance(seg, dict), f"{name} {key} that is not a section")
            for k in ("start_extent", "extent_count", "stripe_count"):
                num(seg, k, f"{name} {key}")
            need(isinstance(seg.get("type", ""), str), f"{name} {key} with a type that is not a string")
            for listed in ("stripes", "mirrors", "raids"):
                areas = seg.get(listed, [])
                need(isinstance(areas, list), f"{name} {key} with {listed} that are not a list")
                need(all(isinstance(x, (str, int)) for x in areas),
                     f"{name} {key} with {listed} of another kind")


def _lvm_shown(lvname, segs):
    """The name lvm2 shows for a logical volume: a snapshot's visible volume is
    stored as snapshotN with its segment naming the volume (cow_store) lvs lists."""
    if segs and segs[0].get("type") == "snapshot" and segs[0].get("cow_store"):
        return f"{segs[0]['cow_store']} (stored as {lvname})"
    return lvname


def _lvm_id(text):
    return str(text).replace("-", "")


def _lvm_pv(fh, base, rsize):
    """An LvmPv for a region with a label lvm2 accepts, else None."""
    try:
        return LvmPv(fh, base, rsize)
    except ValueError:
        return None


def lvm_volumes(fh, regions, ss=SECTOR):
    """[(lv label, base, size, name)] for the logical volumes of the LVM2
    physical volumes among `regions` ([(label, base, size)]) that this reads,
    and {pv base: [lines]} saying, per physical volume, what its volume group
    holds and why any logical volume was not read. A volume that is one run of
    extents on one physical volume is a byte range of the image and its base is
    that range's start; one that is split into runs or striped is read through
    lvm_image(), and its base is where that places it, past the image's end.
    `ss` is the disk's sector size, the unit of the LBA in a name."""
    found, notes, _remap, _free = _lvm_scan(fh, regions, ss)
    return found, notes


def _lvm_scan(fh, regions, ss=SECTOR):
    """(found, notes, remap, free) for lvm_volumes, lvm_image and volumes():
    remap is [(key, LvmMap, label, name)] for each volume that needs a map,
    free is {pv base: [(image offset, length)]} of the extents no logical
    volume holds."""
    pvs = {}
    for _label, base, rsize in regions:
        pv = _lvm_pv(fh, base, rsize)
        if pv is not None:
            pvs[base] = pv
    # A label with no metadata area header that checks out behind it counts only
    # when a volume group read from another physical volume names its id, the
    # way lvm2 still uses such a physical volume: a stray label alone does not
    # turn a region into a physical volume.
    named = {_lvm_id(rec.get("id", "")) for pv in pvs.values() if pv.vg
             for rec in (pv.vg[1].get("physical_volumes") or {}).values() if isinstance(rec, dict)}
    pvs = {b: pv for b, pv in pvs.items() if pv.mda_ok or _lvm_id(pv.uuid) in named}
    notes = {base: [f"LVM2 physical volume, id {pv.uuid}"] + pv.problems
             for base, pv in pvs.items()}
    by_uuid = {}
    for base, pv in pvs.items():
        key = _lvm_id(pv.uuid)
        if key in by_uuid:
            notes[base].append(f"the same physical volume id as the one at byte "
                               f"{by_uuid[key][0]:,}; that one is used")
            continue
        by_uuid[key] = (base, pv)
    groups = {}
    for base, pv in pvs.items():
        if pv.vg is None:
            notes[base].append("no volume group metadata read on it")
            continue
        name, vg, seqno = pv.vg
        key = vg.get("id", name)
        if key not in groups or seqno > groups[key][2]:
            groups[key] = (name, vg, seqno)
    found, remap, free = [], [], {}
    virtual = getattr(fh, "lvm_virtual", None) or {}
    for name, vg, seqno in groups.values():
        home = [b for b, pv in pvs.items() if pv.vg and pv.vg[1].get("id") == vg.get("id")]
        try:
            lines, lvs, maps, spare = _lvm_group(name, vg, seqno, by_uuid, ss, virtual, fh)
        except (TypeError, AttributeError, KeyError, ValueError) as exc:
            # _lvm_vg_shape refuses the shapes known to fail; anything it misses
            # is said here rather than costing the image its other volumes.
            lines, lvs, maps, spare = [f"volume group {name}: its metadata could not be used "
                                       f"({type(exc).__name__}: {exc})"], [], [], {}
        found += lvs
        remap += maps
        for b, runs in spare.items():
            free.setdefault(b, []).extend(runs)
        for b in home:
            notes[b] += lines
    return found, notes, remap, free


class LvmMap:
    """Where each byte of a logical volume lies in the image. `segments` are in
    the volume's order, each (start, size, chunk, bases): one run starting at
    bases[0] when chunk is None, else striped in chunks of `chunk` bytes across
    the runs that start at each of bases, as lvm2's striped segment type lays
    them out (lib/striped/striped.c, dm-stripe: chunk i of the segment is on
    stripe i mod n, in that stripe's row i div n)."""

    def __init__(self, segments):
        self.segments = segments
        self.size = sum(s[1] for s in segments)
        self.copy_name = self.copy_kind = None     # set for a RAID1 or mirror copy (_lvm_copy)
        self.copy_skipped = ""                     # the copies _lvm_copy passed over, and why
        self._starts = [s[0] for s in segments]

    def locate(self, off):
        """(image offset, bytes that follow it there) for volume offset `off`."""
        i = bisect.bisect_right(self._starts, off) - 1
        start, size, chunk, bases = self.segments[i]
        x = off - start
        if chunk is None:
            return bases[0] + x, size - x
        c, within = divmod(x, chunk)
        row, stripe = divmod(c, len(bases))
        return bases[stripe] + row * chunk + within, min(chunk - within, size - x)

    def image_runs(self, off, n):
        """[(image offset, length)] for `n` bytes from volume offset `off`, the
        runs that touch merged."""
        out, end = [], min(off + n, self.size)
        while off < end:
            at, here = self.locate(off)
            take = min(here, end - off)
            if out and out[-1][0] + out[-1][1] == at:
                out[-1] = (out[-1][0], out[-1][1] + take)
            else:
                out.append((at, take))
            off += take
        return out

    def missing(self, size):
        """Bytes of the volume that lie past `size`, the end of the image."""
        lost = 0
        for _start, seg, chunk, bases in self.segments:
            per = seg if chunk is None else seg // len(bases)
            for b in bases:
                lost += max(0, min(per, b + per - size))
        return lost

    def describe(self):
        """The map as records for a manifest: per segment, its place in the
        volume and the image offset of each run it is on."""
        return [{"volume_offset": start, "length": size,
                 "image_offsets": list(bases),
                 **({"stripe_size": chunk} if chunk is not None else {})}
                for start, size, chunk, bases in self.segments]

    def contiguous(self):
        """The image offset the whole volume starts at, when it is one run."""
        if len(self.segments) == 1 and self.segments[0][2] is None:
            return self.segments[0][3][0]
        return None


def _lvm_group(name, vg, seqno, by_uuid, ss, virtual=None, fh=None):
    """(report lines, [(lv label, base, size, name)], [(key, LvmMap, label,
    name)] of the volumes that need a map, {pv base: free runs}) for one volume
    group. `virtual` maps a key to the base lvm_image() placed that volume at."""
    virtual = virtual or {}
    found, maps = [], []
    ext = vg.get("extent_size", 0) * SECTOR
    where = {}                       # pv name in the metadata -> (base, pe_start bytes, pe_count)
    for pvname, rec in (vg.get("physical_volumes") or {}).items():
        hit = by_uuid.get(_lvm_id(rec.get("id", "")))
        if hit:
            where[pvname] = (hit[0], rec.get("pe_start", 0) * SECTOR, rec.get("pe_count", 0))
    pv_names = set(vg.get("physical_volumes") or {})
    lines = [f"volume group {name}, metadata seqno {seqno}, extent {human(ext)}, "
             f"{len(pv_names)} physical volume(s), {len(where)} of them in this image"]
    used = collections.defaultdict(list)     # pv name -> [(first extent, extents)]
    for lvname, lv in (vg.get("logical_volumes") or {}).items():
        for key, seg in lv.items():
            if not (key.startswith("segment") and isinstance(seg, dict)):
                continue
            # lvm2 writes a segment's areas on physical volumes as "pvN", extent
            # pairs (export.c out_areas): a striped segment under stripes, each
            # area holding its share of the extents, and a mirror (a pvmove in
            # progress among them, mirrored.c) under mirrors, each area holding
            # them all. Areas that name another logical volume are counted there.
            count = seg.get("extent_count", 0)
            for listed, per in (("stripes", count // max(1, seg.get("stripe_count", 1) or 1)),
                                ("mirrors", count)):
                areas = seg.get(listed) or []
                for i in range(0, len(areas) - 1, 2):
                    if areas[i] in pv_names and isinstance(areas[i + 1], int):
                        used[areas[i]].append((areas[i + 1], per))
        if "VISIBLE" not in (lv.get("status") or []):
            continue                 # an internal volume (a pool's data, a mirror's image)
        segs = sorted((v for k, v in lv.items() if k.startswith("segment") and isinstance(v, dict)),
                      key=lambda s: s.get("start_extent", 0))
        shown = _lvm_shown(lvname, segs)
        why, lmap = _lvm_layout(segs, where, pv_names, ext, vg.get("logical_volumes") or {},
                                ctx=_lvm_raid_context(vg, fh))
        total = sum(s.get("extent_count", 0) for s in segs if isinstance(s.get("extent_count"), int)) * ext
        if why:
            lines.append(f"logical volume {shown}, {human(total)}: not read ({why})")
            continue
        label = f"LVM {name}/{lvname}"
        first = lmap.first_at() if hasattr(lmap, "first_at") else lmap.locate(0)[0]
        stem = f"lvm_lba{first // ss}"
        suffix = sanitize_volume_label(f"{name}_{lvname}", 40)
        vname = f"{stem}_{suffix}" if suffix else stem
        base = lmap.contiguous()
        if base is not None:
            how = (f" ({_lvm_shape_words(lmap)})" if getattr(lmap, "copy_name", None) else "")
            lines.append(f"logical volume {lvname}, {human(lmap.size)}: read as {label}{how}")
            found.append((label, base, lmap.size, vname))
            continue
        key = (vg.get("id", name), lvname)
        how = _lvm_shape_words(lmap)
        maps.append((key, lmap, label, vname))
        if key in virtual:
            lines.append(f"logical volume {lvname}, {human(lmap.size)}: {how}, read as {label} "
                         "through a map of its runs")
            found.append((label, virtual[key], lmap.size, vname))
        else:
            lines.append(f"logical volume {lvname}, {human(lmap.size)}: not read here ({how}; "
                         "lvm_image() reads it through a map of its runs)")
    spare = {}
    for pvname, (pv_base, pe_start, pe_count) in where.items():
        taken = sorted(used.get(pvname, []))
        runs, at = [], 0
        for first, count in taken + [(pe_count, 0)]:
            if first > at:
                runs.append((pv_base + pe_start + at * ext, (first - at) * ext))
            at = max(at, first + count)
        if runs:
            spare[pv_base] = runs
            lines.append(f"{sum(n for _o, n in runs) // ext if ext else 0:,} extent(s) of "
                         f"{pvname}, the physical volume at byte {pv_base:,}, allocated to no "
                         "logical volume")
    return lines, found, maps, spare


def _lvm_copy(seg, where, pv_names, ext, lvs, depth, ctx=None):
    """A RAID1 or mirror segment, read from the first copy whose extents are all
    in the image. lvm2 lists a raid1 segment's copies under raids, metadata and
    image volume in turn (raid.c, out_areas "raid"), and a mirror's under
    mirrors, each with its first extent (mirrored.c, out_areas "mirror"). Every
    copy holds the volume's data from its start, unless the segment records a
    data_offset (raid.c, written while a reshape moves the data), which is not
    read. For a raid1 segment, a copy that _lvm_raid_legs finds missing (marked
    REBUILD, on a physical volume marked MISSING or not in the image, or failed,
    still recovering or behind by its dm-raid superblock) is passed over, and
    with no good copy the volume is refused. A mirror's copies are read as they
    are; the same marks are not sourced for that segment type here."""
    if depth > 4:
        return "copies nested too deep", None
    kind = seg["type"]
    if seg.get("data_offset"):
        return f"a {kind} segment with a data offset (written while a reshape moves its data)", None
    skipped = {}
    if kind == "raid1":
        listed = seg.get("raids") or []
        names = [(listed[i], 0) for i in range(1, len(listed), 2)]
        why, _imgs, missing_roles, _fresh = _lvm_raid_legs(
            kind, [n for n, _f in names], [listed[i] for i in range(0, len(listed), 2)],
            where, pv_names, ext, lvs, depth, dict(ctx or {}, lenient=True))
        if why:
            return why, None
        skipped = {names[r][0]: w for r, w in missing_roles.items()}
    else:
        listed = seg.get("mirrors") or []
        names = [(listed[i], listed[i + 1]) for i in range(0, len(listed) - 1, 2)]
    size = seg.get("extent_count", 0) * ext
    reasons = []
    for name, first in names:
        copy = lvs.get(name) if isinstance(name, str) else None
        if not isinstance(copy, dict) or first:
            reasons.append(f"{name}: not a copy this reads")
            continue
        if name in skipped:
            reasons.append(skipped[name])
            continue
        csegs = sorted((v for k, v in copy.items() if k.startswith("segment") and isinstance(v, dict)),
                       key=lambda c: c.get("start_extent", 0))
        why, cmap = _lvm_layout(csegs, where, pv_names, ext, lvs, depth + 1)
        if why or cmap.size < size:
            reasons.append(f"{name}: {why or 'shorter than the volume'}")
            continue
        segs_out, left = [], size
        for start, length, chunk, bases in cmap.segments:
            if left <= 0:
                break
            segs_out.append((start, min(length, left), chunk, bases))
            left -= length
        lmap = LvmMap(segs_out)
        lmap.copy_name, lmap.copy_kind = name, kind
        lmap.copy_skipped = "; ".join(reasons)
        return None, lmap
    return f"a {kind} volume none of whose copies is read ({'; '.join(reasons) or 'none listed'})", None


def _lvm_shape_words(lmap):
    """How a volume that needs a map is laid out, in a few words."""
    if getattr(lmap, "raid_words", None):
        return lmap.raid_words
    if getattr(lmap, "copy_name", None):
        return (f"{lmap.copy_kind}, read from its copy {lmap.copy_name}"
                + (f" (not from: {lmap.copy_skipped})" if getattr(lmap, "copy_skipped", "") else ""))
    striped = [s for s in lmap.segments if s[2] is not None]
    if striped:
        return (f"striped across {len(striped[0][3])} physical volumes in "
                f"{human(striped[0][2])} stripes")
    return f"in {len(lmap.segments)} separate runs of extents"


def _lvm_layout(segs, where, pv_names, ext, lvs=None, depth=0, ctx=None):
    """(why not, None) or (None, LvmMap) for an LV's segments: linear and
    striped segments whose every run is on a physical volume in the image, or a
    RAID1 or mirror volume, read from the first of its copies that is.
    `where` maps a physical volume's name in the metadata to (base, pe_start
    bytes, pe_count) for those in the image; `pv_names` names every one; `lvs`
    is the volume group's logical_volumes, where the copies are."""
    if not segs:
        return "no segments", None
    if len(segs) == 1 and segs[0].get("type") in ("raid1", "mirror") and lvs is not None:
        return _lvm_copy(segs[0], where, pv_names, ext, lvs, depth, ctx)
    if len(segs) == 1 and segs[0].get("type") in LVM_RAID_TYPES and lvs is not None:
        return _lvm_raid(segs[0], where, pv_names, ext, lvs, depth, ctx)
    out, start = [], 0
    for seg in segs:
        kind = seg.get("type", "")
        if kind != "striped":
            return f"a {kind or 'untyped'} segment", None
        stripes = seg.get("stripes") or []
        count, n = seg.get("extent_count", 0), seg.get("stripe_count", 1)
        if (not isinstance(n, int) or n < 1 or len(stripes) != 2 * n
                or not all(isinstance(stripes[i], int) for i in range(1, len(stripes), 2))
                or not isinstance(count, int) or not isinstance(seg.get("start_extent", 0), int)):
            return "a segment's extents do not read", None
        if seg.get("start_extent", 0) != start:
            return "its segments leave a gap in the volume", None
        chunk = None
        if n > 1:
            chunk = seg.get("stripe_size", 0) * SECTOR
            if not chunk or count % n or (count // n * ext) % chunk:
                return "a striped segment whose stripes do not divide its extents", None
        bases = []
        for i in range(0, 2 * n, 2):
            pvname, pe = stripes[i], stripes[i + 1]
            if pvname not in pv_names:
                return f"its extents are on {pvname}, which is not a physical volume of the group", None
            if pvname not in where:
                return f"on {pvname}, a physical volume not in this image", None
            pv_base, pe_start, pe_count = where[pvname]
            if pe_count and pe + count // n > pe_count:
                return f"its extents run past the {pe_count:,} its physical volume holds", None
            bases.append(pv_base + pe_start + pe * ext)
        size = count * ext
        if (chunk is None and out and out[-1][2] is None
                and out[-1][3][0] + out[-1][1] == bases[0]):
            p_start, p_size, _c, p_bases = out[-1]
            out[-1] = (p_start, p_size + size, None, p_bases)    # one run lvm2 keeps as two segments
        else:
            out.append((start * ext, size, chunk, bases))
        start += count
    return None, LvmMap(out)


class LvmImage:
    """An image read through read_at() with the logical volumes that need a map
    (split into runs, or striped) placed past its end, each at the base in
    ``lvm_virtual`` ({(volume group id, name): base}), read through its LvmMap.
    ``size`` stays the image's own, so nothing reads the placed volumes as part
    of the disk; an offset at or past it belongs to a placed volume and is
    translated (lvm_map_for) wherever one is reported. Any other attribute is the
    image's own."""

    def __init__(self, fh, size, placed):
        self._fh, self.size = fh, size
        self.lvm_virtual = {key: base for key, (base, _m) in placed.items()}
        self._spans = sorted((base, base + m.size, m) for base, m in placed.values())
        self._pos = 0

    def __getattr__(self, name):
        return getattr(self._fh, name)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self._fh.close()

    def lvm_map_for(self, base):
        """The LvmMap of the volume placed at `base`, else None."""
        return next((m for b, _e, m in self._spans if b == base), None)

    def seek(self, off, whence=0):
        self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if self._pos < self.size:
            want = self.size - self._pos if n is None or n < 0 else min(n, self.size - self._pos)
            self._fh.seek(self._pos)
            got = self._fh.read(want)
            self._pos += len(got)
            return got
        span = next((s for s in self._spans if s[0] <= self._pos < s[1]), None)
        if span is None:
            return b""
        start, end, lmap = span
        want = end - self._pos if n is None or n < 0 else min(n, end - self._pos)
        if hasattr(lmap, "read_via"):                  # an LVM RAID volume (RaidLvMap)
            out = lmap.read_via(self._fh, self._pos - start, want)
            self._pos += len(out)
            return out
        out = bytearray()
        for at, length in lmap.image_runs(self._pos - start, want):
            self._fh.seek(at)
            got = self._fh.read(length)
            out += got
            if len(got) < length:
                break
        self._pos += len(out)
        return bytes(out)


def lvm_image(fh, size=None):
    """The image with each logical volume that needs a map (split into runs, or
    striped) readable past its end (LvmImage), or the image unchanged when there
    is none. volumes() and main() call it, so their volumes include those, and
    a placed volume's base is valid only through the handle it returns (calling
    it again on that handle returns it unchanged). Apply it after
    unlock_bitlocker() and unlock_apfs(): their wrappers read only up to the
    image's own size, so wrapping this one inside them hides every placed volume,
    and a BitLocker or APFS volume inside a mapped logical volume is not opened."""
    if getattr(fh, "lvm_virtual", None) is not None:
        return fh
    if size is None:
        size = image_size(fh)
    regions, _names, containers, protective = partition_regions(fh, size)
    ss = disk_sector_size(fh)
    _found, _notes, remap, _free = _lvm_scan(
        fh, [r for r in regions if r[0] not in containers and r[0] not in protective
             and not r[0].startswith("LVM ")], ss)
    if not remap:
        return fh
    # Past anything the image can describe: its end, and the end of every region
    # its tables name (on a partial image those reach past the file, and a read
    # there has to come back empty, not with a placed volume's data), and never
    # below 2**60 bytes, rounded up to a GiB and a GiB further, each volume then
    # starting on a MiB.
    reach = max([size, 1 << 60] + [b + (n or 0) for _l, b, n in regions])
    at = ((reach + (1 << 30) - 1) >> 30 << 30) + (1 << 30)
    placed = {}
    for key, lmap, _label, _name in remap:
        placed[key] = (at, lmap)
        at = (at + lmap.size + (1 << 20) - 1) >> 20 << 20
    return LvmImage(fh, size, placed)


def lvm_free_extents(fh, regions, ss=SECTOR):
    """{pv base: [(image offset, length)]} of each LVM2 physical volume's extents
    that no logical volume, hidden ones included, is allocated."""
    return _lvm_scan(fh, regions, ss)[3]


def identify_lvm(fh, base, size=None):
    """("lvm2 pv", lines) for an LVM2 physical volume at base, else None: a
    label lvm2 accepts, and either a metadata area header that checks out or a
    volume group elsewhere in the image that names it (lvm_volumes)."""
    pv = _lvm_pv(fh, base, size)
    if pv is None:
        return None
    # The volume group may span other physical volumes in the same image, so
    # its logical volumes are judged against every region the partition tables
    # give (table_regions reads only the tables, never a filesystem, so this
    # cannot come back here).
    try:
        regions = [r for r in table_regions(fh)[0] if r[1] != base]
    except Exception:                              # pylint: disable=broad-except
        regions = []
    _found, notes = lvm_volumes(fh, [("pv", base, size or 0)] + regions)
    if base not in notes:
        return None
    return "lvm2 pv", notes[base][1:] + [f"id {pv.uuid}"]


# ---------------------------------------------------------------------------
# RAID: Linux md arrays and LVM RAID volumes, inside one image or across several
# ---------------------------------------------------------------------------
# What a RAID member holds and how an array lays its data out is the Linux
# kernel's own (git.kernel.org torvalds/linux, tag v7.0, commit
# 028ef9c96e96197026887c0f092424679298aae8) and mdadm's (tag mdadm-4.5, commit
# 8f0c7692d48414ff7b3fe927ce75799c65ef24b1):
#
#   include/uapi/linux/raid/md_p.h
#     44-47    MD_RESERVED_BYTES, MD_NEW_SIZE_SECTORS: a 0.90 superblock sits in the
#              last 64 KiB-aligned 64 KiB of the member
#     95-98    the 1.x roles: 0xffff spare, 0xfffe faulty, 0xfffd journal, below
#              0xff00 a slot in the array
#     109      MD_SB_MAGIC 0xa92b4efc
#     131-209  mdp_superblock_s, the 0.90 superblock, in the writing host's byte order
#     225-304  mdp_superblock_1, the 1.x superblock, little-endian
#     306-343  the 1.x feature_map bits
#     388-402  r5l_meta_block, R5LOG_MAGIC 0x6433c509, the RAID5/6 write journal
#   drivers/md/md.c
#     1054-1058  calc_dev_sboffset: where a 0.90 superblock is
#     1249-1281  md_csum_fold, calc_sb_csum: the 0.90 checksum
#     1353-1450  super_90_load: magic, version 0.90 or 0.91, checksum, data at 0
#     1471-1590  super_90_validate: level 0 has no layout (1519-1520); a member
#                more than one event behind the freshest is refused (1550-1554);
#                a member's state in its own disks[] table gives its role
#     1774-1794  calc_sb_1_csum
#     1796-1977  super_1_load: 1.0 at the end (8 KiB to 12 KiB from it, 4 KiB
#                aligned), 1.1 at 0, 1.2 at 4 KiB (1814-1826); super_offset must
#                name that place; data_offset, data_size
#     1979-2180  super_1_validate: RAID0 without the layout feature has no
#                layout (2060-2061); a member more than one event behind the
#                freshest is refused (2087); one event behind takes its role from
#                the freshest superblock (2111-2133)
#   drivers/md/md-linear.c 113-150   members end to end, in role order
#   drivers/md/raid0.c     65-298    strip zones; 304-352 find_zone, map_sector;
#                          560-590   the original and alternate layouts
#   drivers/md/raid10.c    581-642   __raid10_find_phys; 3712-3760 raid10_size,
#                          calc_sectors; 3763-3815 setup_geo
#   drivers/md/raid5.c     124-161   raid6_d0, raid6_idx_to_slot; 1603-1640
#                          set_syndrome_sources; 2946-3149 raid5_compute_sector;
#                          7309-7321 raid5_size
#   drivers/md/raid5-cache.c 1722-1752 r5l_recovery_read_meta_block; 2941-3000
#                          r5l_load_log; 3079 the checksum seed
#   drivers/md/dm-raid.c   294-313   the dm-raid types lvm2 asks for and the md
#                          level and layout each is (raid4 is RAID5 with parity
#                          first, raid10 is near)
#   drivers/md/dm-raid.c   1953-1975 the dm-raid superblock at the start of each
#                          metadata volume: failed_devices, array_resync_offset
#   drivers/md/md.c        1890-1920 a 1.x member's bad block log; md.h 300-312 its
#                          sectors count from the device's start
#   lib/raid6/mktables.c   21-34, 108-171  GF(2^8) over 0x11d, exp/inv/exi tables
#   lib/raid6/recov.c      19-89     two data blocks, or data and P, from P and Q
#   lib/raid6/int.uc       79-100    the Q syndrome, highest data slot first
#   mdadm util.c 1259-1300 guess_super_type: of several superblocks on one device
#                          the one with the latest creation time
#   mdadm super-ddf.c 145, 977-1000   the DDF anchor, 0xDE11DE11 in the last sector
#   mdadm super-intel.c 38, 4594      the Intel IMSM anchor, two sectors from the end
# lvm2 (tag v2_03_43, commit 7b0bce6909611966bdc1e17c2408e1ec3b0f8c17; every key and
# flag below is the same in v2_03_31, commit 3a6e221c569eb253fa38a772b15e53b5de65b5d1,
# the lvm2 that wrote the fixtures: raid.c 45-185 and 197-229, libdm-deptree.c 86-103):
#   lib/raid/raid.c 45-190, 202-224   a raid segment's device_count, stripe_size,
#                          data_offset and its raids list of metadata and image
#                          volumes in turn
#   libdm/libdm-deptree.c 92-109      "raid5" is raid5_ls and "raid6" is raid6_zr
#   lib/format_text/flags.c 50-51, 65-66  MISSING on a physical volume, NOTSYNCED and
#                          REBUILD on a logical volume
# GPT partition types named here, not read: util-linux v2.41.6 (commit
# 02822c9374fc72d38baf8a1f859eb0813970bf3f) include/pt-gpt-partnames.h 37-41,
# 72, 193-194, and Microsoft's PARTITION_INFORMATION_GPT documentation.
#
# Every array is read only from members whose superblocks agree on the array
# and whose event counts are the freshest or one behind it, as the kernel
# assembles it. With every member there, each level is a mapping. A RAID4/5
# array missing one member, and a RAID6 array missing one or two, has the
# missing chunks rebuilt from parity, but only when its superblocks say it was
# stopped clean. What is refused is named: a reshape in progress, a write
# journal that holds writes not yet on the members, a missing journal device,
# too many missing members, a layout this does not read, and metadata this does
# not read (DDF, Intel IMSM, Windows LDM and Storage Spaces, Apple RAID).

MD_SB_MAGIC = 0xa92b4efc
MD_RESERVED = 64 * 1024                                    # md_p.h 44
MD_ROLE_SPARE, MD_ROLE_FAULTY, MD_ROLE_JOURNAL, MD_ROLE_MAX = 0xffff, 0xfffe, 0xfffd, 0xff00
MD_DISK_FAULTY, MD_DISK_ACTIVE, MD_DISK_SYNC = 0, 1, 2      # md_p.h 74-76
MD_SB_CLEAN, MD_SB_BITMAP_PRESENT = 0, 8                    # md_p.h 114, 118
MD_FEATURE = {1: "bitmap", 2: "recovery offset", 4: "reshape active", 8: "bad blocks",
              16: "replacement", 32: "reshape backwards", 64: "new offset",
              128: "recovery bitmap", 256: "clustered", 512: "journal", 1024: "PPL",
              2048: "multiple PPLs", 4096: "RAID0 layout"}
MD_FEATURE_ALL = sum(MD_FEATURE)
MD_MAX_SECTOR = (1 << 64) - 1
MD_LEVELS = {-1: "linear", 0: "raid0", 1: "raid1", 4: "raid4", 5: "raid5", 6: "raid6",
             10: "raid10", -4: "multipath", -5: "faulty", -1000000: "container"}
# raid5.h 727-764 and mdadm maps.c 28-70: each layout number and mdadm's name for it
MD_R5_LAYOUTS = {0: "left-asymmetric", 1: "right-asymmetric", 2: "left-symmetric",
                 3: "right-symmetric", 4: "parity-first", 5: "parity-last"}
MD_R6_LAYOUTS = {**MD_R5_LAYOUTS, 8: "ddf-zero-restart", 9: "ddf-N-restart",
                 10: "ddf-N-continue", 16: "left-asymmetric-6", 17: "right-asymmetric-6",
                 18: "left-symmetric-6", 19: "right-symmetric-6", 20: "parity-first-6"}
R5LOG_MAGIC = 0x6433c509
# dm-raid.c 294-313: the md level and layout each lvm2 RAID segment type runs as;
# libdm-deptree.c 108-109: "raid5" and "raid6" are raid5_ls and raid6_zr.
LVM_RAID_TYPES = {"raid4": (5, 4), "raid5_n": (5, 5), "raid5_ls": (5, 2), "raid5": (5, 2),
                  "raid5_rs": (5, 3), "raid5_la": (5, 0), "raid5_ra": (5, 1),
                  "raid6_zr": (6, 8), "raid6": (6, 8), "raid6_nr": (6, 9), "raid6_nc": (6, 10),
                  "raid6_n_6": (6, 5), "raid6_ls_6": (6, 18), "raid6_rs_6": (6, 19),
                  "raid6_la_6": (6, 16), "raid6_ra_6": (6, 17), "raid10": (10, None)}
# GPT partition types of RAID and volume managers this tool does not read
RAID_GPT_TYPES = {"5808c8aa-7e8f-42e0-85d2-e1e90434cfb3": "Windows LDM metadata",
                  "af9b60a0-1431-4f62-bc68-3311714a69ad": "Windows LDM data",
                  "e75caf8f-f680-4cee-afa3-b001e56efc2d": "Windows Storage Spaces",
                  "52414944-0000-11aa-aa11-00306543ecac": "Apple RAID",
                  "52414944-5f4f-11aa-aa11-00306543ecac": "Apple RAID offline"}
RAID_JOURNAL_WALK_MAX = 4096           # meta blocks looked at past the journal's tail


class MdSuper:
    """One md superblock, as read from one member. Offsets and sizes are bytes
    from the start of the member; `role` is the slot this superblock gives its
    own device (None for a spare, "faulty", "journal")."""

    def __init__(self, **kw):
        self.uuid = b""
        self.version = self.at = self.name = self.level = self.layout = None
        self.major = self.minor = self.ctime = self.utime = self.chunk = self.raid_disks = None
        self.dev_size = self.events = self.state = self.role = self.raw_role = None
        self.dev_number = self.data_offset = self.data_size = self.feature_map = None
        self.roles = self.reshape_position = self.delta_disks = self.bitmap = None
        self.resync_offset = self.recovery_offset = self.journal_tail = None
        self.refused = self.bad_blocks = self.dev_uuid = None
        self.new_level = self.new_layout = None
        self.bblog = None                    # (shift, sectors, offset) of a 1.x bad block log
        self.bblog_cut = False               # the image ends inside that log
        self.bad_ranges = []                 # [(first byte, end)] it lists, on the member
        self.disks = []                      # 0.90: [(number, raid_disk, state)] per slot
        self.max_dev = 0
        for key, value in kw.items():
            setattr(self, key, value)

    def uuid_text(self):
        """As mdadm prints it: four groups of eight hex digits; for 0.90 each
        group is one of its four native words (set_uuid0..3)."""
        return ":".join(self.uuid[i:i + 4].hex() for i in range(0, 16, 4))

    def clean(self):
        return self.resync_offset == MD_MAX_SECTOR if self.major == 1 else bool(self.state & 1)


def _md_csum_fold(c):
    c = (c & 0xffff) + (c >> 16)
    return (c & 0xffff) + (c >> 16)


def _md_sb090(blob, at):
    """The 0.90 superblock in `blob` (4096 bytes read at byte `at` of the member),
    or None. Its byte order is the writing host's (md_p.h 131-175): the
    little-endian form is read; a big-endian one is parsed far enough to be
    grouped with its array and is then refused, since no fixture holds one."""
    if len(blob) < 4096:
        return None
    if struct.unpack_from("<I", blob, 0)[0] == MD_SB_MAGIC:
        e = "<"
    elif struct.unpack_from(">I", blob, 0)[0] == MD_SB_MAGIC:
        e = ">"
    else:
        return None
    w = struct.unpack_from(f"{e}1024I", blob, 0)
    if w[1] != 0 or w[2] not in (90, 91) or w[10] <= 0:
        return None
    total = sum(w) - w[32 + 6]                     # calc_sb_csum, sb_csum as zero
    total = (total & 0xffffffff) + (total >> 32)
    if _md_csum_fold(total & 0xffffffff) != _md_csum_fold(w[32 + 6]):
        return None
    level = struct.unpack_from(f"{e}i", blob, 7 * 4)[0]
    # events_lo then events_hi on a little-endian host, the other way round on a
    # big-endian one (md_p.h 163-172)
    events = (w[32 + 8] << 32) | w[32 + 7] if e == "<" else (w[32 + 7] << 32) | w[32 + 8]
    disks = [w[128 + 32 * i:128 + 32 * i + 5] for i in range(27)]   # MD_SB_DISKS, md_p.h 66
    this = w[992:997]
    number = this[0]
    own = disks[number] if number < 27 else this
    if own[4] & (1 << MD_DISK_FAULTY):
        role = "faulty"
    elif own[4] & (1 << MD_DISK_SYNC):
        role = own[3]
    else:
        role = None
    reshape = struct.unpack_from(f"{e}Q", blob, (32 + 12) * 4)[0] if w[2] >= 91 else None
    sb = MdSuper(version="0.90", major=0, minor=w[2], at=at,
                   uuid=struct.pack(">4I", w[5], w[13], w[14], w[15]),
                   name="", ctime=w[6], utime=w[32], level=level, layout=w[64],
                   chunk=w[65], raid_disks=w[10], dev_size=w[8] * 1024, events=events,
                   state=w[33], role=role, dev_number=number,
                   data_offset=0, data_size=None, feature_map=0, roles=None,
                   reshape_position=reshape,
                   delta_disks=struct.unpack_from(f"{e}i", blob, (32 + 15) * 4)[0] if reshape is not None else 0,
                   bitmap=bool(w[33] & (1 << MD_SB_BITMAP_PRESENT)), resync_offset=None,
                   recovery_offset=None, journal_tail=None, bad_blocks=False,
                   disks=[(d[0], d[3], d[4]) for d in disks], max_dev=27,
                   refused=None if e == "<" else (
                       "a 0.90 superblock in big-endian byte order (written by a big-endian "
                       "host), which this does not read"))
    if sb.refused is None and sb.raid_disks > 27:
        sb.refused = (f"its superblock records {sb.raid_disks:,} members, more than the 27 a "
                      "0.90 superblock holds")
    return sb


def _md_sb1(blob, at, minor, lbs=SECTOR):
    """The 1.x superblock in `blob` (4096 bytes read at byte `at`), or None:
    magic, major version 1, max_dev, super_offset equal to where it was read,
    no feature bit the kernel does not know, and the checksum (super_1_load)."""
    if len(blob) < 256:
        return None
    magic, major, feature_map, _pad0 = struct.unpack_from("<4I", blob, 0)
    if magic != MD_SB_MAGIC or major != 1:
        return None
    max_dev, = struct.unpack_from("<I", blob, 220)
    super_offset, = struct.unpack_from("<Q", blob, 144)
    if max_dev > (4096 - 256) // 2 or super_offset * SECTOR != at or feature_map & ~MD_FEATURE_ALL:
        return None
    n = 256 + max_dev * 2
    body = bytearray(blob[:n])
    stored = struct.unpack_from("<I", body, 216)[0]
    body[216:220] = b"\0\0\0\0"
    total = sum(struct.unpack_from(f"<{n // 4}I", body, 0))
    if n % 4 == 2:
        total += struct.unpack_from("<H", body, n - 2)[0]
    if ((total & 0xffffffff) + (total >> 32)) & 0xffffffff != stored:
        return None
    (ctime, level, layout, size, chunk, raid_disks, _bitmap_offset, new_level, reshape_pos,
     delta, new_layout, _new_chunk, _new_offset) = struct.unpack_from("<QiIQIIIIQiIIi", blob, 64)
    data_offset, data_size, _so, recovery_offset, dev_number = struct.unpack_from("<QQQQI", blob, 128)
    if data_size < 10:
        return None
    # 1.1 and 1.2 keep their data past the superblock and its role table
    # (md.c 1872-1882): sb_size rounded up to the device's logical block size,
    # `lbs`, which an image says only through a GPT header found at 4096; for
    # any other image 512 bytes is assumed.
    sb_size = -(-(max_dev * 2 + 256) // lbs) * lbs
    if minor and data_offset * SECTOR < at + sb_size:
        return None
    bb_shift, bb_size, bb_offset = struct.unpack_from("<BHi", blob, 185)
    utime, events, resync_offset = struct.unpack_from("<QQQ", blob, 192)
    roles = list(struct.unpack_from(f"<{max_dev}H", blob, 256))
    raw = roles[dev_number] if dev_number < max_dev else MD_ROLE_SPARE
    role = (None if raw == MD_ROLE_SPARE else "faulty" if raw == MD_ROLE_FAULTY
            else "journal" if raw == MD_ROLE_JOURNAL else raw if raw < MD_ROLE_MAX else None)
    return MdSuper(version=f"1.{minor}", major=1, minor=minor, at=at, uuid=bytes(blob[16:32]),
                   name=blob[32:64].split(b"\0", 1)[0].decode("utf-8", "replace"),
                   ctime=ctime & ((1 << 40) - 1), utime=utime & ((1 << 40) - 1), level=level,
                   layout=layout, chunk=chunk * SECTOR, raid_disks=raid_disks,
                   dev_size=size * SECTOR, events=events, state=0, role=role, raw_role=raw,
                   dev_number=dev_number, data_offset=data_offset * SECTOR,
                   data_size=data_size * SECTOR, feature_map=feature_map, roles=roles,
                   reshape_position=reshape_pos if feature_map & 4 else None,
                   delta_disks=delta if feature_map & 4 else 0,
                   bitmap=bool(feature_map & 1), resync_offset=resync_offset,
                   recovery_offset=recovery_offset if feature_map & 2 else None,
                   journal_tail=recovery_offset if raw == MD_ROLE_JOURNAL else None,
                   bad_blocks=bool(feature_map & 8), max_dev=max_dev,
                   bblog=(bb_shift, bb_size, bb_offset) if feature_map & 8 else None,
                   dev_uuid=bytes(blob[168:184]), new_level=new_level, new_layout=new_layout,
                   refused=(f"its superblock records {raid_disks:,} members, more than the "
                            f"{max_dev} its role table holds" if raid_disks > max_dev else None))


def _md_places(size):
    """[(metadata version, byte offset)] where the kernel looks for each md
    superblock on a member of `size` bytes, each a 4096-byte read that fits."""
    sectors = size // SECTOR
    places = []
    if sectors >= 2 * (MD_RESERVED // SECTOR):
        places.append(("0.90", ((sectors & ~(MD_RESERVED // SECTOR - 1)) - MD_RESERVED // SECTOR) * SECTOR))
    if sectors > 16:
        places.append(("1.0", ((sectors - 16) & ~7) * SECTOR))
    places += [("1.1", 0), ("1.2", 4096)]
    return [(version, at) for version, at in places if 0 <= at and at + 4096 <= size]


def md_superblocks(fh, base, size, lbs=SECTOR):
    """[MdSuper] for every md superblock that checks out on the member at `base`
    of `size` bytes, at the places the kernel looks for each version. `lbs` is
    the member's logical block size (512 unless the image says otherwise)."""
    out = []
    for version, at in _md_places(size):
        blob = read_at(fh, base + at, 4096)
        sb = _md_sb090(blob, at) if version == "0.90" else _md_sb1(blob, at, int(version[2]), lbs)
        if sb is not None and sb.bblog is not None and not _md_bad_blocks(fh, base, sb):
            continue
        if sb is not None:
            out.append(sb)
    return out


def _md_bad_blocks(fh, base, sb):
    """Read a 1.x member's bad block log into sb.bad_ranges (byte ranges on the
    member), as super_1_load does (md.c 1890-1920): at most one page, at
    bblog_offset sectors from the superblock (metadata reads are relative to
    sb_start, md.c 1180-1181), entries of sector << 10 | count, both scaled by
    bblog_shift, ending at an entry of all ones. False when the kernel would
    refuse the superblock for it (a log longer than a page, or at offset 0)."""
    shift, sectors, offset = sb.bblog
    if sectors > 4096 // SECTOR or offset == 0:
        return False
    raw = read_at(fh, base + sb.at + offset * SECTOR, sectors * SECTOR)
    if len(raw) < sectors * SECTOR:
        # md would fail to load it (sync_page_io, md.c 1907-1909): the member is
        # left out and says why, rather than read with fewer entries
        sb.bblog_cut = True
        return True
    out = []
    for i in range(len(raw) // 8):
        bb, = struct.unpack_from("<Q", raw, 8 * i)
        if bb == (1 << 64) - 1:
            break
        start, count = (bb >> 10) << shift, (bb & 0x3ff) << shift
        if count:
            out.append((start * SECTOR, (start + count) * SECTOR))
    sb.bad_ranges = out
    return True


def md_member(fh, base, size, lbs=SECTOR):
    """The superblock mdadm would use on this member: of several, the one made
    last (util.c guess_super_type), else None."""
    found = md_superblocks(fh, base, size, lbs)
    if not found:
        return None
    return max(found, key=lambda s: s.ctime)          # max keeps the first of equals


def raid_foreign(fh, base, size):
    """The name of RAID metadata at the end of this region that is not md's and
    is not read here, else None: DDF's anchor in the last sector (super-ddf.c
    977-1000; the last 4096-byte sector too, for a 4Kn disk), Intel IMSM's two
    sectors from the end (super-intel.c 4594, sector_size * 2, for 512 and 4096)."""
    for ss in (SECTOR, 4096):
        if size < 2 * ss:
            continue
        if read_at(fh, base + size - ss, 4) == b"\xde\x11\xde\x11":
            return "DDF"
        if read_at(fh, base + size - 2 * ss, 24) == b"Intel Raid ISM Cfg Sig. ":
            return "Intel IMSM (RST)"
    return None


DDF_LEVELS = {0x00: "RAID0", 0x01: "RAID1", 0x03: "RAID3", 0x04: "RAID4", 0x05: "RAID5",
              0x06: "RAID6", 0x0f: "JBOD", 0x11: "RAID1E", 0x15: "RAID5E", 0x1f: "CONCAT",
              0x25: "RAID5EE"}          # mdadm-4.5 super-ddf.c 107-118, ddf_level 1484-1496


def _ddf_crc_ok(blob):
    """The CRC of a DDF structure, as mdadm's calc_crc (super-ddf.c 571-585):
    over it with its crc field (bytes 4-8) read as 0xffffffff, by mdadm's
    crc32 (crc32.c), the CRC-32 table step from 0 with no inversion before
    or after."""
    if len(blob) < 8:
        return False
    body = bytes(blob[:4]) + b"\xff\xff\xff\xff" + bytes(blob[8:])
    raw = (binascii.crc32(body, 0xffffffff) ^ 0xffffffff) & 0xffffffff
    return raw == struct.unpack_from(">I", blob, 4)[0]


DDF_SECONDARY = {0x00: "striped", 0x01: "mirrored", 0x02: "concatenated",
                 0x03: "spanned"}        # mdadm-4.5 super-ddf.c 138-142 (SRL)
DDF_VD_STATES = {0x0: "optimal", 0x1: "degraded", 0x2: "deleted", 0x3: "missing",
                 0x4: "failed", 0x5: "partially optimal"}   # super-ddf.c 305-315


def _ddf_header(fh, base, size):
    """(header, lba) of the DDF header mdadm-4.5 uses on this region, or None
    (super-ddf.c): the anchor in the last 512-byte sector with its CRC and
    revision (1058-1068); each of the primary and secondary headers loaded
    only when inside the region, with its CRC, and matching the anchor's guid,
    revision, primary_lba, secondary_lba and pad2, of its own type
    (load_ddf_header 815-845); the secondary used when the primary did not
    load, or its seq is newer and it is not open, or the seqs are equal and
    only the primary is open (1079-1091)."""
    if size < 1024:
        return None
    anchor = read_at(fh, base + size - 512, 512)
    if (len(anchor) < 512 or anchor[:4] != b"\xde\x11\xde\x11" or not _ddf_crc_ok(anchor)
            or anchor[32:40] not in (b"01.00.00", b"01.02.00")):
        return None
    loaded = {}
    for field, kind in ((96, 1), (104, 2)):
        lba, = struct.unpack_from(">Q", anchor, field)
        if lba >= size // 512 - 1:
            continue
        hdr = read_at(fh, base + lba * 512, 512)
        if (len(hdr) == 512 and hdr[:4] == anchor[:4] and _ddf_crc_ok(hdr)
                and hdr[8:40] == anchor[8:40] and hdr[96:112] == anchor[96:112]
                and hdr[112] == kind and hdr[113:116] == anchor[113:116]):
            loaded[kind] = (hdr, lba)
    primary, secondary = loaded.get(1), loaded.get(2)
    if secondary is not None:
        pseq = struct.unpack_from(">I", primary[0], 40)[0] if primary else None
        sseq = struct.unpack_from(">I", secondary[0], 40)[0]
        if (primary is None or (pseq < sseq and not secondary[0][48])
                or (pseq == sseq and primary[0][48] and not secondary[0][48])):
            return secondary
    return primary


def _ddf_section(fh, base, header, field, sized):
    """A section the DDF header names at `field` (offset, length in sectors),
    as load_section reads it (super-ddf.c 848-880): from the header's own
    lba, at most 1024 sectors, and with `sized` (its `check`) a length of 2,
    8, 32, 128 or 512 sectors; None otherwise."""
    hdr, lba = header
    off, length = struct.unpack_from(">II", hdr, field)
    if (sized and length not in (2, 8, 32, 128, 512)) or length > 1024 or not length:
        return None
    data = read_at(fh, base + (lba + off) * 512, length * 512)
    return data if len(data) == length * 512 else None


def ddf_records(fh, base, size):
    """[(guid, level name)] of the virtual disk configuration records the DDF
    metadata at the end of this region holds, the newest (seqnum) of each
    guid, each with its CRC (1576); None when the metadata cannot be read.
    The level is prl (334-372), named as mdadm's ddf_level (1484-1496); a
    record with more than one secondary element is named by both levels, so
    mdadm's RAID10, which it writes as RAID1 with sec_elmnt_count disks/2 and
    srl spanned (layout_md2ddf 665-678), reads as "RAID10" and is no mirror."""
    header = _ddf_header(fh, base, size)
    if header is None:
        return None
    rec_len, = struct.unpack_from(">H", header[0], 134)
    conf = _ddf_section(fh, base, header, 216, False)
    if not rec_len or conf is None:
        return None
    newest = {}
    for at in range(0, len(conf) - rec_len * 512 + 1, rec_len * 512):
        rec = conf[at:at + rec_len * 512]
        if rec[:4] != b"\xee\xee\xee\xee" or not _ddf_crc_ok(rec):
            continue
        guid, seq = bytes(rec[8:32]), struct.unpack_from(">I", rec, 36)[0]
        prl, sec_count, srl = rec[67], rec[69], rec[71]
        name = DDF_LEVELS.get(prl, f"primary RAID level 0x{prl:02x}")
        if sec_count > 1:
            name = ("RAID10" if prl == 0x01 and srl in (0x00, 0x03) else
                    f"{name}, {DDF_SECONDARY.get(srl, f'secondary level 0x{srl:02x}')} over "
                    f"{sec_count} sets")
        if guid not in newest or seq > newest[guid][0]:
            newest[guid] = (seq, name)
    return [(guid, name) for guid, (_seq, name) in newest.items()]


def ddf_levels(fh, base, size):
    """The RAID level of each virtual disk the DDF metadata at the end of this
    region records (ddf_records), as names ("RAID5"); a RAID1 whose virtual
    disk is not optimal, or on which this disk is not online, is named with
    that state ("RAID1 (degraded)"), and is then no mirror to walk: the
    virtual disk's state from the virtual disk records (struct virtual_disk
    280-316, its state 0 with no morphing or inconsistent bit), and this
    disk's from the physical disk records (phys_disk 232-275) by the guid in
    its own disk data (disk_data 404-413, matched as 1235-1239), online and
    not failed, rebuilding, in transition or missing (mdadm reads a disk as
    usable when online and neither failed nor missing, 2620). None when the metadata
    cannot be read."""
    records = ddf_records(fh, base, size)
    if records is None:
        return None
    header = _ddf_header(fh, base, size)
    out = []
    virt = phys = disk = None
    if any(name == "RAID1" for _g, name in records):
        virt = _ddf_section(fh, base, header, 208, True)
        phys = _ddf_section(fh, base, header, 200, True)
        disk = _ddf_section(fh, base, header, 224, False)
    for guid, name in records:
        if name != "RAID1":
            out.append(name)
            continue
        states = []
        vstate = None
        if virt is not None and virt[:4] == b"\xdd\xdd\xdd\xdd":
            count, = struct.unpack_from(">H", virt, 10)
            for i in range(min(count, (len(virt) - 64) // 64)):
                ent = virt[64 + 64 * i:128 + 64 * i]
                if bytes(ent[:24]) == guid:
                    vstate = ent[32]
        if vstate is None:
            states.append("its virtual disk record not read")
        elif vstate & 0x1f:
            states.append("virtual disk " + DDF_VD_STATES.get(vstate & 0x7, f"state {vstate & 0x7}")
                          + (", morphing" if vstate & 0x8 else "")
                          + (", inconsistent" if vstate & 0x10 else ""))
        pstate = None
        if (phys is not None and disk is not None and phys[:4] == b"\x22\x22\x22\x22"
                and disk[:4] == b"\x33\x33\x33\x33"):
            for i in range((len(phys) - 64) // 64):
                ent = phys[64 + 64 * i:128 + 64 * i]
                if bytes(ent[:24]) == bytes(disk[8:32]):
                    pstate, = struct.unpack_from(">H", ent, 30)
        if pstate is None:
            states.append("this disk's record not read")
        elif not pstate & 0x1 or pstate & (0x2 | 0x4 | 0x8 | 0x40):
            flags = [w for bit, w in ((0x2, "failed"), (0x4, "rebuilding"),
                                      (0x8, "in transition"), (0x40, "missing")) if pstate & bit]
            states.append("this disk " + ", ".join(flags + ([] if pstate & 0x1 else ["not online"])))
        out.append(name + (f" ({'; '.join(states)})" if states else ""))
    return out


def raid_foreign_article(foreign):
    """`foreign` (what raid_foreign() names) with its indefinite article:
    "a DDF", "an Intel IMSM (RST)"."""
    return ("an " if foreign[:1].upper() in "AEIOU" else "a ") + foreign


IMSM_SIGNATURE = b"Intel Raid ISM Cfg Sig. "      # mdadm-4.5 super-intel.c 38
IMSM_MPB_MAX = 1 << 20      # larger than this is not read (mdadm sets no limit)


def imsm_levels(fh, base, size):
    """(levels, why) for the IMSM metadata at the end of this region: the
    RAID level of each volume it records ("RAID1", "RAID0", ...), or None and
    why it was not read. Read as mdadm-4.5 super-intel.c loads it
    (load_imsm_mpb 4577-4685): the anchor sector two sectors from the end
    (512 or 4096 bytes), the extended part of the metadata, mpb_size rounded
    up to sectors (mpb_sectors 441-445), in the sectors before it; the
    checksum, the sum of the metadata's 32-bit little-endian words less the
    stored one (__gen_imsm_checksum 888-900); the disk table (imsm_disk, 48
    bytes, 146-160) at 0xD8, then each volume (imsm_dev 226-277, its
    imsm_vol 199-224 at byte 80, map 0 at 112: imsm_map 169-197) sized as
    sizeof_imsm_dev (941-952, sizeof_imsm_map 902-905); and each volume's
    level as get_imsm_raid_level (1354-1363): level 1 with two members is
    RAID1, with more RAID10. A volume migrating between two maps, or whose
    map_state is not NORMAL (169-178: uninitialized, degraded, failed), is
    named with that and is no mirror to walk: which member a degraded map has
    lost (failed_disk_num) is a disk number this one disk cannot be matched
    to without the serial number the controller reads from the drive."""
    for ss in (SECTOR, 4096):
        if size < 2 * ss:
            continue
        anchor = read_at(fh, base + size - 2 * ss, ss)
        if anchor[:len(IMSM_SIGNATURE)] == IMSM_SIGNATURE:
            break
    else:
        return None, "no IMSM metadata was found"
    mpb_size, = struct.unpack_from("<I", anchor, 0x24)
    if mpb_size < 0xD8 or mpb_size > IMSM_MPB_MAX:
        return None, f"its metadata gives a size of {mpb_size:,} bytes, which is not read"
    extra = -(-mpb_size // ss) - 1
    if extra * ss + 2 * ss > size:
        return None, "its metadata reaches past the start of the region"
    buf = anchor + (read_at(fh, base + size - ss * (2 + extra), extra * ss) if extra else b"")
    if len(buf) < mpb_size:
        return None, "its metadata could not be read in full"
    words = struct.unpack_from(f"<{mpb_size // 4}I", buf, 0)
    stored = words[8]
    if (sum(words) - stored) & 0xffffffff != stored:
        return None, "its metadata checksum does not match"
    num_disks, num_devs = buf[0x38], buf[0x39]
    at = 0xD8 + 48 * num_disks
    levels = []
    for _i in range(num_devs):
        if at + 164 > mpb_size:
            return None, "its volume records run past the end of its metadata"
        migrating = buf[at + 88]
        level, members = buf[at + 112 + 15], buf[at + 112 + 16]
        if not members:
            return None, "a volume record names no member disks"
        size_ = 164 - 52 + 52 + 4 * (members - 1)
        if migrating:
            m1 = at + 112 + 52 + 4 * (members - 1)
            if m1 + 52 > mpb_size:
                return None, "its volume records run past the end of its metadata"
            size_ += 52 + 4 * (buf[m1 + 16] - 1) if buf[m1 + 16] else 52
        name = ({0: "RAID0", 5: "RAID5", 10: "RAID10"}.get(level) if level != 1 else
                ("RAID1" if members == 2 else "RAID10")) or f"IMSM RAID level {level}"
        state = buf[at + 112 + 14]          # map_state (imsm_map 169-197)
        qualifiers = (["migrating"] if migrating else []) + (
            [{1: "uninitialized", 2: "degraded", 3: "failed"}.get(state, f"map state {state}")]
            if state else [])
        levels.append(name + (f" ({', '.join(qualifiers)})" if qualifiers else ""))
        at += size_
    if not levels:
        return None, "its metadata records no volume"
    return levels, None


def raid_foreign_levels(fh, base, size, foreign):
    """(levels, why) the DDF or IMSM metadata at the end of this region
    records (ddf_levels, imsm_levels)."""
    try:
        if foreign == "DDF":
            levels = ddf_levels(fh, base, size)
            if levels is None:
                return None, ("its DDF metadata could not be read (an anchor, header or "
                              "configuration record that does not check out)")
            if not levels:
                return None, "its DDF metadata records no virtual disk"
            return levels, None
        return imsm_levels(fh, base, size)
    except (struct.error, ValueError, OSError) as exc:
        return None, f"its metadata could not be read ({type(exc).__name__}: {exc})"


def raid_foreign_mirror(levels):
    """True when every array the metadata records is a mirror (RAID1): the
    one case where a single member holds the whole of the data."""
    return bool(levels) and set(levels) == {"RAID1"}


def raid_foreign_note(foreign, levels=None, why=None, found=None, subject="this disk"):
    """What is said of a region (or, with `subject`, a disk's partitions)
    that carries DDF or IMSM metadata, whose array this does not assemble.
    A mirror (raid_foreign_mirror) is read from the one member; anything
    else is not walked: `found` names what is at its start, not walked."""
    head = (f"a member of {raid_foreign_article(foreign)} RAID set, whose array is not "
            "assembled here")
    verb = "are" if subject.endswith("s") else "is"
    if raid_foreign_mirror(levels):
        return (f"{head}: its metadata records RAID1 (a mirror), so this disk alone holds the "
                f"whole of the array's data, and {subject} {verb} read")
    named = ", ".join(sorted(set(levels or [])))
    if levels and all(lv.startswith("RAID1 (") for lv in levels):
        reason = (f"its metadata records {named}: a mirror not in its normal state, whose copy "
                  "on this disk may not be current")
    elif levels:
        reason = (f"its metadata records {named}, and one member of such an array alone does "
                  "not hold the whole of its data")
    else:
        reason = f"{why}, so whether it is a mirror is not known"
    return (f"{head}: {reason}; {subject} {verb} not walked"
            + (f" (it starts with {found})" if found else ""))


def raid_foreign_disk(fh, size):
    """For a disk that ends in DDF or IMSM metadata: {"foreign", "levels",
    "why", "mirror"}; else None. Read from the image's own bytes: through an
    opened LUKS or BitLocker volume, or a logical volume map, the end of the
    disk can read as something else (the wrappers keep the image as _fh)."""
    while type(fh).__name__ in ("LuksImage", "BitLockerImage", "LvmImage"):
        fh = object.__getattribute__(fh, "_fh")
    try:
        foreign = raid_foreign(fh, 0, size)
    except (struct.error, ValueError, OSError):
        foreign = None
    if not foreign:
        return None
    levels, why = raid_foreign_levels(fh, 0, size, foreign)
    return {"foreign": foreign, "levels": levels, "why": why,
            "mirror": raid_foreign_mirror(levels)}


def identify_md(fh, base, size=None):
    """("linux md member", lines) for a member of an md array whose data is not a
    filesystem at the start of the region, else None. A RAID1 member with its
    superblock at the end (metadata 0.90 or 1.0) holds the filesystem itself
    from its first byte, so it is left to the filesystem identifiers, as
    before. DDF and IMSM metadata is not answered here: identify_fs() reads
    such a region as any other and names its metadata (raid_foreign_note)."""
    if size is None:
        size = image_size(fh) - base
    sb = md_member(fh, base, size)
    if sb is None:
        return None
    if getattr(sb, "refused", None):
        return "linux md member", [f"Linux md member: {sb.refused}"]
    if sb.major == 0 or sb.minor == 0:
        if sb.level == 1 and sb.data_offset == 0:
            return None
    role = sb.role if isinstance(sb.role, int) else (sb.role or "spare")
    lines = [f"Linux md member, metadata {sb.version}, {MD_LEVELS.get(sb.level, sb.level)}, "
             f"array {sb.uuid_text()}" + (f" ({sb.name})" if sb.name else ""),
             f"role {role} of {sb.raid_disks}, events {sb.events:,}, data from byte "
             f"{sb.data_offset:,}; read as part of its array when the other members are "
             "given with it"]
    return "linux md member", lines


# --- GF(2^8) for RAID6 (lib/raid6/mktables.c) ----------------------------------

def _gf_mul(a, b):
    v = 0
    while b:
        if b & 1:
            v ^= a
        a = ((a << 1) ^ (0x1d if a & 0x80 else 0)) & 0xff
        b >>= 1
    return v


_GF = {}


def _gf_tables():
    """(exp, inv) tables: exp[i] = 2**i, inv[x] = x**254, mktables.c 108-150."""
    if not _GF:
        exp, v = [], 1
        for _ in range(256):
            exp.append(v)
            v = _gf_mul(v, 2)
            if v == 1:
                v = 0
        inv = [0] * 256
        for x in range(256):
            r, a, b = 1, x, 254
            while b:
                if b & 1:
                    r = _gf_mul(r, a)
                a = _gf_mul(a, a)
                b >>= 1
            inv[x] = r
        _GF["exp"], _GF["inv"], _GF["mul"] = exp, inv, {}
    return _GF["exp"], _GF["inv"]


def _gf_scale(c, data):
    """Every byte of data multiplied by c in GF(2^8)."""
    _gf_tables()
    table = _GF["mul"].get(c)
    if table is None:
        table = _GF["mul"][c] = bytes(_gf_mul(c, x) for x in range(256))
    return data.translate(table)


def _xor(blocks, n):
    acc = 0
    for b in blocks:
        acc ^= int.from_bytes(b, "little")
    return acc.to_bytes(n, "little")


# --- the layouts ---------------------------------------------------------------

class RaidGeometry:
    """How an array of `n` members lays out its data. `level` is "linear", 0, 1,
    4, 5, 6 or 10 (5 also for dm-raid's raid4, layout 4); `chunk` in bytes;
    `dev_bytes` the size each member gives the array (md's dev_sectors);
    `member_bytes` per role, which linear and RAID0 use. `size` is the
    array's length (linear_conf, raid0_size, raid1_size, raid5_size,
    raid10_size). `why` is set instead when the layout is not one this reads."""

    def __init__(self, level, n, chunk, layout, dev_bytes, member_bytes=None):
        self.level, self.n, self.chunk, self.layout = level, n, chunk, layout
        self.dev_bytes, self.member_bytes = dev_bytes, member_bytes or []
        self.why, self.size, self.zones, self.ends = None, 0, [], []
        self.nc = self.fc = 1                  # RAID10's near and far copies
        self.fo, self.far_set, self.stride = False, n, 0
        try:
            self._setup()
        except (ValueError, ZeroDivisionError, IndexError) as exc:
            self.why = self.why or f"its geometry does not hold together ({exc})"

    def _setup(self):
        level, n, chunk = self.level, self.n, self.chunk
        if n < 1:
            self.why = "no members"
            return
        if level == "linear":
            # md-linear.c 113-150: each member, rounded down to the chunk when
            # there is one, after the last, in role order
            at = 0
            for b in self.member_bytes:
                at += b - b % chunk if chunk else b
                self.ends.append(at)
            self.size = at
            return
        if level != 1 and (not chunk or chunk % SECTOR):
            self.why = f"a chunk of {chunk} bytes"
            return
        if level == 0:
            self._raid0()
        elif level == 1:
            self.size = self.dev_bytes
        elif level in (4, 5, 6):
            maxdeg = 2 if level == 6 else 1
            if level == 5 and self.layout not in MD_R5_LAYOUTS:
                self.why = f"RAID5 layout {self.layout}, which is not one md defines"
                return
            if level == 6 and self.layout not in MD_R6_LAYOUTS:
                self.why = f"RAID6 layout {self.layout}, which is not one md defines"
                return
            if n <= maxdeg:
                self.why = f"{n} members, too few for {MD_LEVELS[level]}"
                return
            self.size = (self.dev_bytes - self.dev_bytes % chunk) * (n - maxdeg)
        elif level == 10:
            self._raid10()
        else:
            self.why = f"level {MD_LEVELS.get(level, level)}"

    def _raid0(self):
        """create_strip_zones (raid0.c 65-298): members rounded down to the chunk;
        one zone per distinct size, each over the members still longer than the
        last zone's end on the smallest."""
        chunk = self.chunk
        sizes = [b - b % chunk for b in self.member_bytes]
        distinct = sorted(set(sizes))
        start, end = 0, 0
        for s in distinct:
            devs = [r for r, b in enumerate(sizes) if b > start]
            end += (s - start) * len(devs)
            self.zones.append((end, start, devs))
            start = s
        if len(self.zones) > 1 and len(self.zones[1][2]) > 1:
            if self.layout not in (1, 2):
                self.why = ("a RAID0 array of members of different sizes that records no "
                            "layout (made before Linux 5.4), whose zone layout is not "
                            "settled by its metadata")
                return
        else:
            self.layout = 1
        self.size = end

    def _raid10(self):
        """setup_geo and calc_sectors (raid10.c 3732-3815)."""
        layout, n, chunk = self.layout, self.n, self.chunk
        if layout >> 17:
            self.why = (f"a RAID10 layout with far sets (layout 0x{layout:x}), which this "
                        "does not read")
            return
        if layout >> 19 or chunk & (chunk - 1) or chunk < 4096:
            self.why = f"a RAID10 layout 0x{layout:x} with a {chunk}-byte chunk"
            return
        nc, fc, fo = layout & 255, (layout >> 8) & 255, bool(layout & (1 << 16))
        if nc * fc < 2 or nc * fc > n:
            self.why = (f"a RAID10 layout 0x{layout:x} with {nc * fc} copies over {n} members, "
                        "which md does not run (raid10.c 3848: at least two, at most one a member)")
            return
        self.nc, self.fc, self.fo, self.far_set = nc, fc, fo, n
        chunks = self.dev_bytes // chunk // fc * n // nc
        self.size = chunks * chunk
        per_dev = -(-chunks * nc * fc // n)
        self.stride = chunk if fo else per_dev // fc * chunk

    def copies10(self, off):
        """[(role, member offset)] of each copy of array byte `off`, and the bytes
        that follow it in this chunk (__raid10_find_phys, raid10.c 581-642)."""
        chunk = self.chunk
        c, within = divmod(off, chunk)
        c *= self.nc
        stripe, dev = divmod(c, self.n)
        if self.fo:
            stripe *= self.fc
        sector = within + stripe * chunk
        out = []
        n, fs = self.n, self.far_set
        last_start = (n // fs - 1) * fs
        last_size = fs + n % fs
        for _ in range(self.nc):
            d, s = dev, sector
            out.append((d, s))
            for _f in range(1, self.fc):
                group = d // fs
                d += self.nc
                if n % fs and d > last_start:
                    d = (d - last_start) % last_size + last_start
                else:
                    d = d % fs + fs * group
                s += self.stride
                out.append((d, s))
            dev += 1
            if dev >= n:
                dev = 0
                sector += chunk
        return out, chunk - within

    def place(self, off):
        """For array byte `off`: (role, member offset, run) for linear and RAID0."""
        if self.level == "linear":
            i = bisect.bisect_right(self.ends, off)
            start = self.ends[i - 1] if i else 0
            return i, off - start, self.ends[i] - off
        for zi, (end, dev_start, devs) in enumerate(self.zones):
            if off < end:
                zoff = off - (self.zones[zi - 1][0] if zi else 0)
                s = off if self.layout == 1 else zoff          # raid0.c 566-571
                within = s % self.chunk
                role = devs[(s // self.chunk) % len(devs)]
                row = zoff // (self.chunk * len(devs))
                run = min(self.chunk - within, end - off)
                return role, dev_start + row * self.chunk + within, run
        raise ValueError(f"byte {off:,} is past the array")

    def stripe(self, off):
        """For RAID4/5/6: (data role, parity role, Q role or -1, member offset,
        run, ddf) for array byte `off` (raid5_compute_sector, raid5.c 2946-3149)."""
        chunk, n, algo = self.chunk, self.n, self.layout
        cnum, within = divmod(off, chunk)
        data_disks = n - (2 if self.level == 6 else 1)
        stripe, dd = divmod(cnum, data_disks)
        s2 = stripe
        pd = qd = -1
        ddf = False
        if self.level == 4:
            pd = data_disks
        elif self.level == 5:
            if algo == 0:
                pd = data_disks - s2 % n
                dd += dd >= pd
            elif algo == 1:
                pd = s2 % n
                dd += dd >= pd
            elif algo == 2:
                pd = data_disks - s2 % n
                dd = (pd + 1 + dd) % n
            elif algo == 3:
                pd = s2 % n
                dd = (pd + 1 + dd) % n
            elif algo == 4:
                pd = 0
                dd += 1
            elif algo == 5:
                pd = data_disks
        else:
            if algo in (0, 1, 8, 9):
                if algo == 9:
                    s2 += 1
                pd = (n - 1 - s2 % n) if algo in (0, 9) else s2 % n
                qd = pd + 1
                if pd == n - 1:
                    dd += 1
                    qd = 0
                elif dd >= pd:
                    dd += 2
                ddf = algo in (8, 9)
            elif algo in (2, 3):
                pd = (n - 1 - s2 % n) if algo == 2 else s2 % n
                qd = (pd + 1) % n
                dd = (pd + 2 + dd) % n
            elif algo == 4:
                pd, qd = 0, 1
                dd += 2
            elif algo == 5:
                pd, qd = data_disks, data_disks + 1
            elif algo == 10:
                pd = n - 1 - s2 % n
                qd = (pd + n - 1) % n
                dd = (pd + 1 + dd) % n
                ddf = True
            elif algo in (16, 17, 18, 19):
                pd = (data_disks - s2 % (n - 1)) if algo in (16, 18) else s2 % (n - 1)
                if algo in (16, 17):
                    dd += dd >= pd
                else:
                    dd = (pd + 1 + dd) % (n - 1)
                qd = n - 1
            elif algo == 20:
                pd = 0
                dd += 1
                qd = n - 1
        return dd, pd, qd, stripe * chunk + within, chunk - within, ddf


def _raid6_slots(n, pd, qd, ddf):
    """{member: slot} for the data members of one RAID6 stripe and the number of
    syndrome slots (raid6_d0, raid6_idx_to_slot, set_syndrome_sources)."""
    d0 = 0 if ddf or qd == n - 1 else qd + 1
    slots, count, i = {}, 0, d0
    for _ in range(n):
        if ddf:
            slot = count
            count += 1
            if i not in (pd, qd):
                slots[i] = slot
        elif i not in (pd, qd):
            slots[i] = count
            count += 1
        i = (i + 1) % n
    return slots


class _RaidMemberFailed(OSError):
    """A member's read failed during a rebuild; `role` says which."""

    def __init__(self, role, why):
        super().__init__(why)
        self.role = role


class RaidReader:
    """Reads an array's bytes from its members. `members` is {role: (fh, byte
    offset of that member's data)}; a role that is not there is missing. `bad`
    is {role: [(start, end)]}, byte ranges of a member's data that its bad
    block log lists (super_1_load, md.c 1890-1920): md does not read those, and
    neither does this. A range listed on one member is read from another copy
    (RAID1, RAID10) or rebuilt from parity (RAID4/5/6), as for a missing
    member; with neither, the read fails."""

    def __init__(self, geom, members, bad=None, clean=True):
        self.g, self.m = geom, members
        self.bad = {r: sorted(v) for r, v in (bad or {}).items() if v}
        self.clean = clean        # stopped clean: parity may be trusted to rebuild a failed read
        self.last_error = None

    def unreadable(self, limit=1 << 20):
        """[(role, first byte, end)] of each listed bad range whose array bytes
        neither another copy nor parity can supply, found by reading every
        array chunk the range touches (strictly); None when the ranges touch
        more than `limit` chunks to check."""
        g, out, probes = self.g, [], 0
        chunk = g.chunk or (1 << 16)
        for role, ranges in self.bad.items():
            for s, e in ranges:
                s, e = max(0, s), min(e, g.dev_bytes if g.level != 1 else g.size)
                if s >= e:
                    continue
                spans = []
                if g.level == 1:
                    spans = [(s, e - s)]
                elif g.level in (4, 5, 6):
                    dd = g.n - (2 if g.level == 6 else 1)
                    for row in range(s // chunk, (e - 1) // chunk + 1):
                        spans.append((row * dd * chunk, dd * chunk))
                else:                                   # RAID10: the chunks with a copy there
                    cands = set()
                    for at in sorted({s} | set(range((s // chunk + 1) * chunk, e, chunk))):
                        for f in range(g.fc):
                            row = (at - f * g.stride) // chunk if not g.fo else (at // chunk - f)
                            if row < 0 or (g.fo and row % g.fc):
                                continue
                            stripe = row // g.fc if g.fo else row
                            for st in (stripe - 1, stripe):
                                lo = max(0, st * g.n // g.nc - 1)
                                cands.update(range(lo, (st + 1) * g.n // g.nc + 2))
                    spans = [(c * chunk, chunk) for c in sorted(cands)]
                for a, n in spans:
                    probes += 1
                    if probes > limit:
                        return None
                    a, n = max(0, a), min(n, g.size - max(0, a))
                    if n <= 0:
                        continue
                    try:
                        self.read(a, n, strict=True)
                    except OSError:
                        out.append((role, s, e))
                        break
        return out

    def _member(self, role, off, n):
        """`n` bytes of member `role`'s data from `off`, read directly (not
        through read_at, whose shortfall tally belongs to the array's reader),
        tried a second time before the member counts as failed there."""
        fh, base = self.m[role]
        for _attempt in range(2):
            try:
                fh.seek(base + off)
                data = fh.read(n)
            except OSError:
                continue
            if len(data) == n:
                return data
        raise OSError(f"member {role} does not read at byte {off:,}")

    def _has(self, role, at, n):
        """True when member `role` is there and no listed bad range touches
        [at, at + n) on it."""
        if role not in self.m:
            return False
        return not any(s < at + n and at < e for s, e in self.bad.get(role, ()))

    def _edge(self, role, at):
        """Bytes from `at` on member `role` to where its listed bad ranges next
        begin or end, so a read is cut there."""
        out = None
        for s, e in self.bad.get(role, ()):
            for edge in (s, e):
                if edge > at and (out is None or edge - at < out):
                    out = edge - at
        return out

    def _cut(self, take, places):
        """`take` shortened so that no member at [(role, offset)] crosses a
        listed bad range's edge."""
        if not self.bad:
            return take
        for role, at in places:
            edge = self._edge(role, at)
            if edge is not None:
                take = min(take, edge)
        return take

    def read(self, off, n, strict=False):
        """The bytes from array byte `off`. Where a piece cannot be read (no
        copy, nor parity to rebuild it from) the read stops there and returns
        what came before it, so a caller sees a short read, which extraction
        counts and names (EOF_SHORTFALL, .SHORT), never zeros; `strict` raises
        OSError instead."""
        out = bytearray()
        try:
            self._read(off, n, out)
        except OSError as exc:
            self.last_error = f"array byte {off + len(out):,}: {exc}"
            if strict:
                raise
        return bytes(out)

    def _read(self, off, n, out):
        g = self.g
        n = max(0, min(n, g.size - off))
        while n > 0:
            if g.level in ("linear", 0):
                role, at, run = g.place(off)
                take = self._cut(min(run, n), [(role, at)])
                if not self._has(role, at, take):
                    raise OSError(f"array byte {off:,} lies in a bad block range of member {role}")
                out += self._member(role, at, take)
            elif g.level == 1:
                # in pieces of at most 64 KiB, so a read that fails on every copy
                # ends at that piece and what came before it is kept
                take = self._cut(min(n, 1 << 16), [(r, off) for r in self.m])
                out += self._first_copy([(r, off) for r in sorted(self.m)], take, off)
            elif g.level == 10:
                copies, run = g.copies10(off)
                take = self._cut(min(run, n), copies)
                out += self._first_copy(copies, take, off)
            else:
                dd, pd, qd, at, run, ddf = g.stripe(off)
                take = self._cut(min(run, n), [(r, at) for r in range(g.n)])
                got = None
                if self._has(dd, at, take):
                    try:
                        got = self._member(dd, at, take)
                    except OSError:                    # md reads around a failed read too
                        if not self.clean:
                            # parity of an array not stopped clean may be out of
                            # step: no rebuild, the read ends short here
                            raise OSError(f"member {dd} does not read at byte {at:,}, and the "
                                          "array was not stopped clean, so it is not rebuilt "
                                          "from parity") from None
                        got = None
                out += got if got is not None else self._rebuild(
                    dd, pd, qd, at, take, ddf, skip={dd})
            off += take
            n -= take

    def _first_copy(self, copies, take, off):
        """The first of `copies` [(member, offset)] that is there, lists no bad
        range over the bytes and reads without an error, as md tries another
        mirror when a read fails (raid1.c, raid10.c read_balance)."""
        for role, at in copies:
            if self._has(role, at, take):
                try:
                    return self._member(role, at, take)
                except OSError:
                    continue
        raise OSError(f"no copy of array byte {off:,} can be read")

    def _rebuild(self, want, pd, qd, at, n, ddf, skip=frozenset()):
        """The `n` bytes at member offset `at` of member `want`, missing, with
        a bad range there or failing to read, from the others in its stripe:
        XOR with P (raid5), or from P and Q (lib/raid6/recov.c). A member that
        fails to read here is left out and the rebuild tried without it."""
        try:
            return self._rebuild_from(want, pd, qd, at, n, ddf, set(skip))
        except _RaidMemberFailed as exc:
            if exc.role in skip:
                raise OSError(str(exc)) from None
            return self._rebuild(want, pd, qd, at, n, ddf, set(skip) | {exc.role})

    def _read_or_flag(self, role, at, n):
        try:
            return self._member(role, at, n)
        except OSError as exc:
            raise _RaidMemberFailed(role, str(exc)) from None

    def _rebuild_from(self, want, pd, qd, at, n, ddf, skip):
        g = self.g
        here = {r for r in range(g.n) if r != want and r not in skip and self._has(r, at, n)}
        if g.level != 6:
            others = [r for r in range(g.n) if r not in (want, qd)]
            if not set(others) <= here:
                raise OSError("more than one member of the stripe missing")
            return _xor([self._read_or_flag(r, at, n) for r in others], n)
        exp, inv = _gf_tables()
        slots = _raid6_slots(g.n, pd, qd, ddf)
        data = {r: self._read_or_flag(r, at, n) for r in slots if r in here}
        lost_data = sorted((slots[r], r) for r in slots if r not in here)
        if pd in here and len(lost_data) == 1:
            return _xor([self._read_or_flag(pd, at, n)] + list(data.values()), n)
        if qd not in here:
            raise OSError("too many members of the stripe missing")
        q = self._read_or_flag(qd, at, n)
        qx = _xor([q] + [_gf_scale(exp[slots[r]], d) for r, d in data.items()], n)
        if len(lost_data) == 1:                         # data and P (recov.c 59-83)
            a = lost_data[0][0]
            return _gf_scale(inv[exp[a]], qx)
        if len(lost_data) == 2 and pd in here:          # two data (recov.c 19-56)
            (a, ra), (b, _rb) = lost_data
            px = _xor([self._read_or_flag(pd, at, n)] + list(data.values()), n)
            db = _xor([_gf_scale(inv[exp[b - a] ^ 1], px), _gf_scale(inv[exp[a] ^ exp[b]], qx)], n)
            return db if want != ra else _xor([db, px], n)
        raise OSError("too many members of the stripe missing")


class RaidImage:
    """An assembled array (or a logical volume read across several images) as a
    read-only image: seek, tell, read and size, like any image open_image()
    returns, so volumes(), main(), the walkers, extraction and free space read
    it unchanged. `read_fn(off, n)` gives its bytes. Closing it closes nothing:
    its members belong to the RaidSet that opened them."""

    def __init__(self, read_fn, size, label, info=None):
        self._read, self.size, self.label = read_fn, size, label
        self.raid_info = info or {}
        self._pos = 0

    def seek(self, off, whence=0):
        self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        if self._pos >= self.size:
            return b""
        want = self.size - self._pos if n is None or n < 0 else min(n, self.size - self._pos)
        data = self._read(self._pos, want)
        self._pos += len(data)
        return data

    def close(self):
        pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False


class _ConcatImage:
    """Several images read as one address space, each starting on a GiB past
    the end of the one before, so a volume group spread over several images is
    read with the same code as one inside a single image."""

    def __init__(self, parts):
        self.parts, at = [], 0
        for label, fh, size in parts:
            self.parts.append((at, size, fh, label))
            at = ((at + size + (1 << 30) - 1) >> 30 << 30) + (1 << 30)
        self.size = at
        self._pos = 0

    def seek(self, off, whence=0):
        self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
        return self._pos

    def tell(self):
        return self._pos

    def read(self, n=-1):
        for start, size, fh, _label in self.parts:
            if start <= self._pos < start + size:
                want = start + size - self._pos if n is None or n < 0 else min(n, start + size - self._pos)
                fh.seek(self._pos - start)
                got = fh.read(want)
                self._pos += len(got)
                return got
        return b""


# --- assembly ------------------------------------------------------------------

class MdArray:
    """One md array assembled from the members found: what its superblocks say,
    which member holds which role, what is missing or left out and why, and,
    when it can be read, `image`, a RaidImage of its bytes."""

    def __init__(self, sb):
        self.sb = sb                      # the freshest superblock
        self.uuid = sb.uuid_text()
        self.members, self.left_out, self.notes = [], [], []
        self.missing, self.image, self.refused = [], None, None
        self.geom = None
        self.incomplete = False   # too few members given to read it, whatever became of them
        self.not_given = []       # roles no image given claims
        self.same_as = None       # a RAID1 member whose own listing shows the same bytes

    @property
    def level_name(self):
        return MD_LEVELS.get(self.sb.level, f"level {self.sb.level}")

    @property
    def label(self):
        return f"md array {self.sb.name or self.uuid}"

    @property
    def safe_name(self):
        """The name the array is read under: a run's header, volumes.json's
        image, the prefix of its extraction folders and free-space files."""
        stem = sanitize_volume_label(self.sb.name, 32) if self.sb.name else ""
        return f"md_{stem}_{self.uuid[:8]}" if stem else f"md_{self.uuid[:8]}"

    def layout_name(self):
        sb = self.sb
        if sb.level == 5:
            return MD_R5_LAYOUTS.get(sb.layout, f"layout {sb.layout}")
        if sb.level == 6:
            return MD_R6_LAYOUTS.get(sb.layout, f"layout {sb.layout}")
        if sb.level == 10:
            nc, fc = sb.layout & 255, (sb.layout >> 8) & 255
            kind = "offset" if sb.layout & (1 << 16) else "far"
            return (f"near={nc}" if fc == 1 else f"{kind}={fc}" if nc == 1
                    else f"near={nc}, {kind}={fc}")
        if sb.level == 0 and self.geom is not None and len(self.geom.zones) > 1:
            return {1: "original", 2: "alternate"}.get(self.geom.layout, "none recorded")
        return ""

    def lines(self):
        sb = self.sb
        head = (f"{self.label}: {self.level_name}"
                + (f" {self.layout_name()}" if self.layout_name() else "")
                + (f", {human(sb.chunk)} chunks" if sb.chunk and sb.level not in (1,) else "")
                + f", metadata {sb.version}, uuid {self.uuid}, {sb.raid_disks} member(s), "
                f"events {sb.events:,}, {'clean' if sb.clean() else 'NOT clean'}")
        out = [head]
        for m in sorted(self.members, key=lambda x: x["role"]):
            out.append(f"  role {m['role']}: {m['where']} (events {m['events']:,}, data from "
                       f"byte {m['data_offset']:,}" + (f", {m['note']}" if m.get("note") else "") + ")")
        for m in self.left_out:
            out.append(f"  left out: {m['where']}: {m['why']}")
        for r in self.missing:
            out.append(f"  role {r}: missing")
        out += [f"  {n}" for n in self.notes]
        if self.refused:
            out.append(f"  NOT READ: {self.refused}")
        elif self.image is not None:
            out.append(f"  read as an image of {self.image.size:,} bytes ({human(self.image.size)})")
        return out

    def describe(self):
        sb = self.sb
        return {"kind": "md", "uuid": self.uuid, "name": sb.name, "metadata": sb.version,
                "level": self.level_name, "layout": self.layout_name() or None,
                "chunk_bytes": sb.chunk or None, "raid_disks": sb.raid_disks,
                "events": sb.events, "clean": sb.clean(),
                "members": [{"role": m["role"], "where": m["where"], "events": m["events"],
                             "data_offset": m["data_offset"]} for m in sorted(self.members, key=lambda x: x["role"])],
                "missing_roles": list(self.missing),
                "left_out": [{"where": m["where"], "why": m["why"]} for m in self.left_out],
                "notes": list(self.notes), "refused": self.refused,
                "bytes": self.image.size if self.image is not None else None}


def _md_journal_pending(fh, base, jsb, array_uuid, geom, clean):
    """None when the RAID5/6 write journal on member `jsb` (at `base`) holds no
    write the members may lack, else why. The log is walked as the kernel
    replays it when the array starts (raid5-cache.c): from the meta block at the
    journal's tail, each block valid by magic, version, position, sequence and
    a CRC32C seeded with one over the array uuid (r5l_load_log 2941-3000,
    r5l_recovery_read_meta_block 1722-1752); a block whose data pages fail
    their checksums is passed over (r5c_recovery_flush_log 2226-2246). Per
    stripe, data logged after its parity is a write held only in the journal
    (r5l_recovery_load_data 1800-1820 marks it caching, load_parity 1822-1846
    clears that), and a flush payload says the stripe is on the members. A
    stripe whose data and parity are both logged is rewritten by the kernel
    from the log; on an array stopped clean those writes had finished, so the
    members hold them."""
    seed = xfs_crc32c(array_uuid, 0xFFFFFFFF)                 # raid5-cache.c 3079
    data = base + jsb.data_offset
    ring = jsb.data_size // 4096 * 4096
    pos = (jsb.journal_tail or 0) * SECTOR
    if not ring:
        return "its write journal device holds no log"
    if pos >= ring or pos % 4096:
        pos = 0
    maxdeg = 2 if geom.level == 6 else 1
    state, seq, blocks = {}, None, 0
    for _ in range(RAID_JOURNAL_WALK_MAX):
        mb = bytearray(read_at(fh, data + pos, 4096))
        if len(mb) < 4096:
            return "its write journal could not be read"
        magic, crc, version, _p1, _p2, meta_size, mseq, position = struct.unpack_from("<IIBBHIQQ", mb, 0)
        mb[4:8] = b"\0\0\0\0"
        if (magic != R5LOG_MAGIC or version != 1 or position * SECTOR != pos
                or (seq is not None and mseq != seq) or meta_size > 4096
                or xfs_crc32c(bytes(mb), seed) != crc):
            break                        # the log ends here
        blocks += 1
        payloads, off, total, page_at, good = [], 32, 4096, (pos + 4096) % ring, True
        while off + 8 <= meta_size:
            ptype, _flags, psize = struct.unpack_from("<HHI", mb, off)
            if ptype == 2:                                    # R5LOG_PAYLOAD_FLUSH
                count = psize // 8
                if off + 8 + 8 * count > meta_size:
                    return (f"its write journal has a meta block at journal byte {pos:,} whose "
                            "payloads run past the block")
                payloads.append(("flush", [struct.unpack_from("<Q", mb, off + 8 + 8 * i)[0]
                                           for i in range(count)]))
                off += 8 + psize
                continue
            if ptype not in (0, 1):
                return f"its write journal holds a payload of type {ptype}, which this does not read"
            pages = psize >> 3
            if off + 16 + 4 * pages > meta_size or pages * 4096 > ring:
                return (f"its write journal has a meta block at journal byte {pos:,} whose "
                        "payloads run past the block")
            location, = struct.unpack_from("<Q", mb, off + 8)
            sums = struct.unpack_from(f"<{pages}I", mb, off + 16)
            for i in range(pages):
                page = read_at(fh, data + (page_at + i * 4096) % ring, 4096)
                if xfs_crc32c(page, seed) != sums[i]:
                    good = False
            payloads.append(("data" if ptype == 0 else "parity", location))
            span = 4096 if ptype == 0 else 4096 * maxdeg
            page_at = (page_at + psize * SECTOR) % ring
            total += span
            off += 16 + 4 * pages
        if good:
            for kind, what in payloads:
                if kind == "flush":
                    for s in what:
                        state.pop(s, None)
                elif kind == "data":
                    state[geom.stripe(what * SECTOR)[3] // SECTOR] = "data"
                else:
                    state[what] = "parity"
        seq = mseq + 1
        pos = (pos + total) % ring
    else:
        return "its write journal runs on further than this follows"
    only = sum(1 for v in state.values() if v == "data")
    logged = len(state) - only
    if only:
        return (f"its write journal holds data for {only} stripe(s) not yet written to the "
                "members (a write-back journal)")
    if logged and not clean:
        return (f"its write journal holds {logged} stripe(s) that the kernel would rewrite "
                "onto the members, and the array was not stopped clean")
    return None, blocks, logged


def _md_assemble(found):
    """[MdArray] from `found`, [(where, fh, base, size, MdSuper)], every member
    seen, grouped by array uuid as the kernel's analyze_sbs and validate_super
    do. Each array is judged on its own: a fault in one is said on that array
    and never costs the others."""
    groups = collections.OrderedDict()
    for item in found:
        groups.setdefault(item[4].uuid, []).append(item)
    arrays = []
    for _uuid, items in groups.items():
        active = [it for it in items if it[4].role is not None]
        fresh = max(active or items, key=lambda it: it[4].events)[4]
        arr = MdArray(fresh)
        arrays.append(arr)
        try:
            journal = _md_roles(arr, items)
            _md_judge(arr, journal)
        except Exception as exc:                       # pylint: disable=broad-except
            arr.image = None
            arr.refused = f"its metadata could not be used ({type(exc).__name__}: {exc})"
    return arrays


def _md_roles(arr, items):
    """Fill arr.members, arr.left_out and arr.missing from the members found, as
    the kernel's validate_super does; return the journal member, if any, as
    (fh, base, MdSuper, where)."""
    sb = arr.sb
    roles = {}
    journal = journal_sb = None
    if sb.refused:
        arr.left_out = [{"where": w, "events": s.events, "data_offset": s.data_offset,
                         "image": getattr(s, "image_label", w),
                         "partition": getattr(s, "partition", False),
                         "why": "its array is not read"} for w, _f, _b, _z, s in items]
        # too few members here to read it even if its superblock were usable
        have = len({it[4].dev_number for it in items})
        allowed = {1: max(0, (sb.raid_disks or 1) - 1), 4: 1, 5: 1, 6: 2}.get(sb.level, 0)
        arr.incomplete = have < (sb.raid_disks or 0) - allowed
        return None
    for where, fh, base, size, s in items:
        rec = {"where": where, "events": s.events, "data_offset": s.data_offset,
               "image": getattr(s, "image_label", where),
               "partition": getattr(s, "partition", False)}
        if (s.level, s.layout if s.level != 0 else 0, s.chunk, s.raid_disks) != \
                (sb.level, sb.layout if sb.level != 0 else 0, sb.chunk, sb.raid_disks):
            arr.left_out.append(dict(rec, why="its superblock gives the array a different "
                                     "level, layout, chunk or member count"))
            continue
        role = s.role
        if s is not sb and s.events + 1 == sb.events and role is not None:
            # One event behind: its own superblock may predate its being marked
            # faulty, so its role is the freshest superblock's (md.c 2111-2133;
            # for 0.90, the freshest disks[] entry of its device number, whose
            # state must still say in sync).
            if s.major == 1:
                if s.dev_number >= sb.max_dev:
                    arr.left_out.append(dict(rec, why=f"device number {s.dev_number}, past the "
                                             f"freshest superblock's {sb.max_dev} (md.c 2125-2130)"))
                    continue
                raw = sb.roles[s.dev_number]
                role = (raw if raw < MD_ROLE_MAX else "faulty" if raw == MD_ROLE_FAULTY
                        else "journal" if raw == MD_ROLE_JOURNAL else None)
            else:
                entry = sb.disks[s.dev_number] if s.dev_number < len(sb.disks) else None
                if entry is None or entry[2] & (1 << MD_DISK_FAULTY) or not entry[2] & (1 << MD_DISK_SYNC):
                    arr.left_out.append(dict(rec, why="one event behind, and the freshest "
                                             "superblock no longer has it in sync"))
                    continue
                role = entry[1]
            rec["note"] = "one event behind, its role from the freshest superblock"
        if role is not None and s.events + 1 < sb.events:
            arr.left_out.append(dict(rec, why=f"stale: events {s.events:,}, the array is at "
                                     f"{sb.events:,} (a member failed or removed, whose data "
                                     "stopped being kept)"))
            continue
        if role is None:
            arr.left_out.append(dict(rec, why="a spare, which holds no data of the array"))
            continue
        if role == "faulty":
            arr.left_out.append(dict(rec, why="marked faulty"))
            continue
        if role == "journal":
            if not s.feature_map & 512:
                arr.left_out.append(dict(rec, why="a journal device whose own superblock has no "
                                         "journal feature (md.c 2146-2150)"))
                continue
            if journal_sb is None or journal_sb.events < s.events:
                journal, journal_sb = (fh, base, s, where), s
            continue
        if s.bblog_cut:
            arr.left_out.append(dict(rec, why="its bad block log runs past the end of the image, "
                                     "so md would not load it (md.c 1907-1909)"))
            continue
        if s.feature_map & 2 or s.feature_map & 16:
            arr.left_out.append(dict(rec, why="still being rebuilt (recovery offset "
                                     f"{(s.recovery_offset or 0) * SECTOR:,})"))
            continue
        if role >= sb.raid_disks:
            arr.left_out.append(dict(rec, why=f"role {role}, past the array's {sb.raid_disks} members"))
            continue
        need = s.data_offset + (sb.dev_size if sb.level not in (0, -1) else
                                (s.data_size if s.data_size is not None else s.at))
        if size < need:
            arr.left_out.append(dict(rec, why=f"the image holds {size:,} bytes of it and the "
                                     f"array needs {need:,} (a member image cut short)"))
            continue
        if role in roles:
            if roles[role]["events"] >= s.events:
                arr.left_out.append(dict(rec, why=f"role {role} again, held by {roles[role]['where']}"))
                continue
            arr.left_out.append(dict(roles[role], why=f"role {role} again, held by {where}"))
        roles[role] = dict(rec, role=role, fh=fh, base=base, size=size, sb=s)
    arr.members = list(roles.values())
    arr.missing = [r for r in range(sb.raid_disks) if r not in roles]
    # Incomplete means too few members were GIVEN, whatever became of them: the
    # roles no image given claims, by its own superblock or the freshest role
    # table. A member given and left out (stale, faulty, cut short) still
    # counts as given. RAID10's copies are checked against its layout in
    # _md_judge.
    given = set()
    for _w, _f, _b, _z, s in items:
        role = s.role
        if not isinstance(role, int) and s.major == 1 and sb.roles and s.dev_number < len(sb.roles):
            raw = sb.roles[s.dev_number]
            role = raw if raw < MD_ROLE_MAX else None
        if isinstance(role, int):
            given.add(role)
    arr.not_given = [r for r in range(sb.raid_disks) if r not in given]
    copies = (sb.layout & 255) * ((sb.layout >> 8) & 255) if sb.level == 10 else 0
    allowed = {-1: 0, 0: 0, 1: sb.raid_disks - 1, 4: 1, 5: 1, 6: 2, 10: max(0, copies - 1)}
    arr.incomplete = len(arr.not_given) > allowed.get(sb.level, 0)
    return journal


def _md_judge(arr, journal):
    """Decide whether `arr` is read, and build its image when it is."""
    sb = arr.sb
    level = sb.level
    if getattr(sb, "refused", None):
        arr.refused = sb.refused
        return
    if sb.feature_map & 1024 or sb.feature_map & 2048:
        arr.notes.append("a partial parity log (PPL): it matters only for an array stopped "
                         "unclean, which is not rebuilt here")
    if sb.bitmap:
        arr.notes.append("a write-intent bitmap, which marks regions to resync when a member "
                         "is re-added; no stale member is read here")
    if sb.feature_map & 256:
        arr.refused = "a clustered md array, whose state is shared with other nodes"
        return
    if sb.reshape_position is not None and sb.reshape_position != MD_MAX_SECTOR:
        arr.refused = (f"a reshape is in progress (reshape position {sb.reshape_position * SECTOR:,} "
                       f"bytes, members changing by {sb.delta_disks:+d}): part of the array is "
                       "in the old layout and part in the new")
        return
    if level not in (-1, 0, 1, 4, 5, 6, 10):
        arr.refused = f"md level {arr.level_name}, which this does not read"
        return
    if level in (4, 5, 6) and (sb.chunk < 4096 or sb.chunk & (sb.chunk - 1)):
        arr.refused = (f"a {sb.chunk:,}-byte chunk, which md does not run a RAID{level} array "
                       "with (raid5.c 7492-7497: a power of two, at least a page)")
        return
    sizes = []
    for r in range(sb.raid_disks):
        m = next((x for x in arr.members if x["role"] == r), None)
        if m is None:
            sizes.append(0)
        else:
            s = m["sb"]
            sizes.append(s.data_size if s.data_size is not None else s.at)
    geom = RaidGeometry("linear" if level == -1 else level, sb.raid_disks, sb.chunk,
                        sb.layout if not (level == 0 and not sb.feature_map & 4096) else -1,
                        sb.dev_size, sizes)
    if level == 0 and geom.layout == -1 and len(geom.zones) <= 1:
        geom.layout = 1
    arr.geom = geom
    if geom.why:
        arr.refused = geom.why
        return
    lost = len(arr.missing)
    allowed = {-1: 0, 0: 0, 1: sb.raid_disks - 1, 4: 1, 5: 1, 6: 2}.get(level)
    if level == 10:
        # the copies of chunk c fall on the same members as those of c + n
        # (__raid10_find_phys), so n chunks show every pattern
        def short_of_copies(gone):
            return bool(gone) and not all(
                any(r not in gone for r, _o in geom.copies10(c * geom.chunk)[0])
                for c in range(sb.raid_disks))
        too_few = short_of_copies(set(arr.missing))
        arr.incomplete = (too_few if set(arr.not_given) == set(arr.missing)
                          else short_of_copies(set(arr.not_given)))
    else:
        too_few = lost > allowed
    if sb.feature_map & 512 or journal:
        if journal is None:
            arr.refused = ("it has a write journal, and no usable journal device is among the "
                           "members given (one left out is named above)")
            return
        fh, base, jsb, where = journal
        got = _md_journal_pending(fh, base, jsb, sb.uuid, geom, sb.clean())
        if isinstance(got, str):
            arr.refused = got
            return
        _none, blocks, logged = got
        arr.notes.append(f"a write journal on {where}: {blocks} log block(s) past its tail"
                         + (f", {logged} logged stripe(s) whose writes finished before the "
                            "array was stopped clean" if logged else "")
                         + "; nothing in it is missing from the members")
    if lost:
        left = lost - len(arr.not_given)
        how = (f" ({left} given and left out above, {len(arr.not_given)} not given)"
               if left else "")
        if too_few and level == 10:
            arr.refused = (f"{lost} of {sb.raid_disks} members missing{how}, and with them every "
                           "copy of some chunks")
            return
        if too_few:
            arr.refused = (f"{lost} of {sb.raid_disks} members missing{how}; {arr.level_name} can "
                           f"lose at most {allowed}")
            return
        if level in (4, 5, 6) and not sb.clean():
            arr.refused = ("members missing from an array that was not stopped clean: its "
                           "parity may not match its data, so a missing member cannot be "
                           "rebuilt from it")
            return
        if level in (4, 5, 6):
            arr.notes.append(f"{lost} member(s) missing: their chunks are rebuilt from parity")
    if not sb.clean():
        arr.notes.append("not stopped clean: copies or parity may disagree in the region "
                         "being resynced; data is read from the members as they are")
    # A member's bad block log lists ranges md does not read from it
    # (super_1_load, md.c 1890-1920): read elsewhere, or not at all.
    bad = {}
    for m in arr.members:
        ranges = [(s - m["data_offset"], e - m["data_offset"]) for s, e in m["sb"].bad_ranges
                  if e > m["data_offset"]]
        if ranges:
            bad[m["role"]] = ranges
            shown = ", ".join(f"{max(0, s):,}-{e:,}" for s, e in ranges[:6])
            arr.notes.append(f"member {m['where']} (role {m['role']}) lists {len(ranges)} bad "
                             f"block range(s), bytes of its data {shown}"
                             + (" ..." if len(ranges) > 6 else "")
                             + "; those are read from another copy or rebuilt from parity, "
                             "and the array is refused if any of them can be read from neither")
    if bad:
        if level in (-1, 0):
            arr.refused = (f"a member lists bad blocks, and {arr.level_name} keeps no other "
                           "copy to read them from")
            return
        if level in (4, 5, 6) and not sb.clean():
            arr.refused = ("a member lists bad blocks, and the array was not stopped clean, "
                           "so they cannot be rebuilt from parity")
            return
    members = {m["role"]: (m["fh"], m["base"] + m["data_offset"]) for m in arr.members}
    reader = RaidReader(geom, members, bad, clean=sb.clean())
    if bad:
        lost_ranges = reader.unreadable()
        if lost_ranges is None:
            arr.refused = ("its members' bad block ranges cover more chunks than this checks, so "
                           "whether every one can be read from elsewhere is not settled")
            return
        if lost_ranges:
            where = {m["role"]: m["where"] for m in arr.members}
            arr.refused = ("a bad block range that neither another copy nor parity can supply: "
                           + "; ".join(f"member {where[r]} (role {r}), bytes {max(0, s):,}-{e:,} "
                                       "of its data" for r, s, e in lost_ranges[:6])
                           + (" ..." if len(lost_ranges) > 6 else ""))
            return
    arr.image = RaidImage(reader.read, geom.size, arr.label, None)
    if level == 1 and not bad:
        first = min(arr.members, key=lambda m: m["role"])
        if first["data_offset"] == 0:
            arr.same_as = first["where"]
    arr.image.raid_info = arr.describe()


# --- LVM RAID ------------------------------------------------------------------

DM_RAID_MAGIC = 0x64526D44                   # dm-raid.c 1953, "DmRd"


class RaidLvMap(LvmMap):
    """Where each byte of an LVM RAID4/5/6/10 volume lies in the image: the md
    layout dm-raid runs it as (dm-raid.c 294-313) over the maps of its image
    volumes, in the order lvm2 lists them. `images` has None for an image
    volume that is missing or not to be read; its bytes are then read from the
    other copy (RAID10) or rebuilt from parity (read_via)."""

    def __init__(self, kind, geom, images, size, words, clean=False):
        super().__init__([])
        self.kind, self.geom, self.images, self.size = kind, geom, images, size
        self.raid_words = words
        self.clean = clean        # the dm-raid superblock says in sync, and not NOTSYNCED
        self._readers = {}

    def locate(self, off):
        """(image offset, bytes that follow) for volume byte `off`, from an image
        volume that holds it; (None, run) where it has to be rebuilt."""
        g = self.geom
        if g.level == 10:
            copies, run = g.copies10(off)
            have = [c for c in copies if self.images[c[0]] is not None]
            if not have:
                return None, min(run, self.size - off)
            role, at = have[0]
        else:
            role, _pd, _qd, at, run, _ddf = g.stripe(off)
            if self.images[role] is None:
                return None, min(run, self.size - off)
        img_off, here = self.images[role].locate(at)
        return img_off, min(run, here, self.size - off)

    def first_at(self):
        """The image offset of the volume's first byte that lies in an image
        volume (its first chunk may have to be rebuilt), for its name."""
        off = 0
        while off < self.size:
            at, here = self.locate(off)
            if at is not None:
                return at
            off += here
        return 0

    def image_runs(self, off, n):
        """As LvmMap's, leaving out what has to be rebuilt (it lies nowhere)."""
        out, end = [], min(off + n, self.size)
        while off < end:
            at, here = self.locate(off)
            take = min(here, end - off)
            if at is not None:
                if out and out[-1][0] + out[-1][1] == at:
                    out[-1] = (out[-1][0], out[-1][1] + take)
                else:
                    out.append((at, take))
            off += take
        return out

    def read_via(self, fh, off, n):
        """`n` bytes from volume byte `off`, read from `fh` (the image the maps
        point into), rebuilt where an image volume is missing."""
        reader = self._readers.get(id(fh))
        if reader is None:
            members = {}
            for role, m in enumerate(self.images):
                if m is None:
                    continue
                members[role] = (RaidImage(
                    lambda o, k, mm=m: b"".join((fh.seek(a), fh.read(ln))[1]
                                                for a, ln in mm.image_runs(o, k)),
                    m.size, f"image {role}"), 0)
            reader = self._readers[id(fh)] = RaidReader(self.geom, members, clean=self.clean)
        # a piece that cannot be read ends the read short (RaidReader.read), so
        # read_at counts the shortfall and extraction names the file .SHORT
        return reader.read(off, max(0, min(n, self.size - off)))

    def missing(self, size):
        return sum(m.missing(size) for m in self.images if m is not None)

    def describe(self):
        return [{"raid": self.kind, "stripe_size": self.geom.chunk, "length": self.size,
                 "images": [m.describe() if m is not None else {"missing": True}
                            for m in self.images]}]

    def contiguous(self):
        return None


def _lvm_raid_context(vg, fh):
    """What _lvm_raid needs beyond a segment: the image to read RAID metadata
    volumes from, and the physical volumes lvm2 marks MISSING (flags.c 50-51,
    under status or flags)."""
    marked = set()
    for name, rec in (vg.get("physical_volumes") or {}).items():
        if isinstance(rec, dict) and "MISSING" in ((rec.get("status") or []) + (rec.get("flags") or [])):
            marked.add(name)
    return {"fh": fh, "missing_pvs": marked}


def _lvm_seg_pvs(lv):
    """The physical volume names an LV's segments name."""
    out = set()
    for k, v in lv.items():
        if k.startswith("segment") and isinstance(v, dict):
            areas = (v.get("stripes") or []) + (v.get("mirrors") or [])
            out |= {areas[i] for i in range(0, len(areas), 2) if isinstance(areas[i], str)}
    return out


def _dm_raid_sb(fh, rmeta):
    """(events, failed_devices, array_resync_offset) from the dm-raid
    superblock at the start of a RAID metadata volume (dm-raid.c 1954-1975),
    else None."""
    if fh is None or rmeta is None:
        return None
    at, _here = rmeta.locate(0)
    raw = read_at(fh, at, 48)
    if len(raw) < 48 or struct.unpack_from("<I", raw, 0)[0] != DM_RAID_MAGIC:
        return None
    events, failed, disk_rec, resync = struct.unpack_from("<QQQQ", raw, 16)
    return events, failed, resync, disk_rec


def _lvm_raid_legs(kind, names, metas, where, pv_names, ext, lvs, depth, ctx):
    """(why not, [map or None per image volume], {role: why missing}, freshest
    dm-raid superblock or None) for the image volumes `names` of an LVM RAID
    segment, with their metadata volumes `metas` (raid.c 166-180). An image
    volume is missing when lvm2 marks it REBUILD (flags.c 66) or its physical
    volume MISSING (flags.c 50-51), when that physical volume is not in the
    image, and, from the dm-raid superblocks in the metadata volumes
    (dm-raid.c 1954-1975): when the freshest one lists it as failed
    (2408-2453), when its own disk_recovery_offset says it is still being
    recovered (2499-2508: not MaxSector means not in sync), or when its own
    events are more than one behind the freshest's. dm-raid itself takes the
    array's state from the freshest superblock alone (super_load 2232-2234);
    leaving out a device whose superblock fell behind is md's rule for its own
    superblocks (md.c 2087), applied here as the stricter reading."""
    ctx = ctx or {}
    images, why_missing, metamaps = [], {}, []
    for role, name in enumerate(names):
        lv = lvs.get(name) if isinstance(name, str) else None
        if not isinstance(lv, dict):
            return f"a {kind} segment naming {name}, which is not a volume of the group", None, None, None
        csegs = sorted((v for k, v in lv.items() if k.startswith("segment") and isinstance(v, dict)),
                       key=lambda c: c.get("start_extent", 0))
        why, cmap = _lvm_layout(csegs, where, pv_names, ext, lvs, depth + 1, ctx)
        on_missing = _lvm_seg_pvs(lv) & ctx.get("missing_pvs", set())
        if "REBUILD" in (lv.get("status") or []):
            why_missing[role] = f"{name} is marked REBUILD"
        elif on_missing:
            why_missing[role] = f"{name} is on {', '.join(sorted(on_missing))}, marked MISSING"
        elif why and "not in this image" in why:
            why_missing[role] = f"{name} is {why}"
        elif why and "nest more than four deep" in why:
            return why, None, None, None      # said once, not once per level of nesting
        elif why and ctx.get("lenient"):
            why_missing[role] = f"{name}: {why}"   # a raid1 copy: the next one is tried
        elif why:
            return f"a {kind} volume whose image volume {name} is not read ({why})", None, None, None
        images.append(None if role in why_missing else cmap)
        mlv = lvs.get(metas[role]) if role < len(metas) and isinstance(metas[role], str) else None
        mmap = None
        if isinstance(mlv, dict) and role not in why_missing:
            msegs = sorted((v for k, v in mlv.items() if k.startswith("segment") and isinstance(v, dict)),
                           key=lambda c: c.get("start_extent", 0))
            _w, mmap = _lvm_layout(msegs, where, pv_names, ext, lvs, depth + 1)
        metamaps.append(mmap)
    sbs = [_dm_raid_sb(ctx.get("fh"), m) for m in metamaps]
    fresh = max((s for s in sbs if s is not None), default=None)
    if fresh is not None:
        for role, name in enumerate(names):
            if role in why_missing:
                continue
            own = sbs[role] if role < len(sbs) else None
            if own is None:
                why_missing[role] = (f"{name}'s metadata volume holds no dm-raid superblock, so "
                                     "dm-raid would take it as a new device and rebuild it "
                                     "(super_load, dm-raid.c 2207-2222)")
            elif fresh[1] >> role & 1:
                why_missing[role] = f"{name} is listed as failed in the dm-raid superblock"
            elif own is not None and own[3] != MD_MAX_SECTOR:
                why_missing[role] = (f"{name} is still being recovered (its dm-raid superblock's "
                                     f"disk_recovery_offset is {own[3] * SECTOR:,} bytes)")
            elif own is not None and own[0] + 1 < fresh[0]:
                why_missing[role] = (f"{name}'s dm-raid superblock is at events {own[0]:,}, the "
                                     f"freshest at {fresh[0]:,}")
            if role in why_missing:
                images[role] = None
    return None, images, why_missing, fresh


def _lvm_raid(seg, where, pv_names, ext, lvs, depth, ctx=None):
    """(why not, None) or (None, RaidLvMap) for an LVM RAID4/5/6/10 segment: each
    image volume named in its raids list (raid.c 166-180 at v2_03_43, 161-175
    at v2_03_31) read through its own map. An image volume lvm2 marks REBUILD
    (flags.c 66), one on a physical volume marked MISSING or not in the image,
    and one dm-raid's superblock lists as failed, is missing: a RAID10 volume is
    read from the other copy, and a RAID4/5/6 one rebuilt from parity when the
    dm-raid superblock says the array is in sync and lvm2 does not mark the
    volume NOTSYNCED (flags.c 65); otherwise the volume is refused."""
    kind = seg.get("type")
    if depth > 4:
        return (f"a {kind} segment whose image volumes nest more than four deep, or name "
                "the volume itself"), None
    level, layout = LVM_RAID_TYPES[kind]
    if seg.get("data_offset"):
        return f"a {kind} segment with a data offset (written while a reshape moves its data)", None
    listed = seg.get("raids") or []
    names = [listed[i] for i in range(1, len(listed), 2)]
    metas = [listed[i] for i in range(0, len(listed), 2)]
    count = seg.get("device_count")
    if not isinstance(count, int) or count != len(names) or count < 2 or count > 64:
        return f"a {kind} segment whose image volumes do not match its device count", None
    chunk = (seg.get("stripe_size") or 0) * SECTOR
    top = next((lv for lv in lvs.values() if isinstance(lv, dict)
                and any(v is seg for v in lv.values())), {})
    why, images, why_missing, fresh = _lvm_raid_legs(kind, names, metas, where, pv_names,
                                                     ext, lvs, depth, ctx)
    if why:
        return why, None
    present = [m for m in images if m is not None]
    if not present:
        return f"a {kind} volume none of whose image volumes is read", None
    per = min(m.size for m in present)
    if level == 10:
        copies = seg.get("data_copies") or 2
        layout = copies | (1 << 8)                     # dm-raid: raid10 is near
    geom = RaidGeometry(level, count, chunk, layout, per)
    if geom.why:
        return f"a {kind} segment: {geom.why}", None
    size = seg.get("extent_count", 0) * ext
    if size > geom.size:
        return f"a {kind} volume longer than its image volumes hold", None
    words = f"{kind} across {count} image volumes in {human(chunk)} stripes"
    lost = sorted(why_missing)
    if lost:
        said = "; ".join(why_missing[r] for r in lost)
        if level == 10:
            if not all(any(images[r] is not None for r, _o in geom.copies10(c * chunk)[0])
                       for c in range(count)):
                return f"a {kind} volume missing every copy of some chunks ({said})", None
            words += f", read from the other copies ({said})"
        else:
            if len(lost) > (2 if level == 6 else 1):
                return f"a {kind} volume with {len(lost)} image volumes missing ({said})", None
            if "NOTSYNCED" in (top.get("status") or []):
                return (f"a {kind} volume lvm2 marks NOTSYNCED (its parity was never "
                        f"computed), with an image volume missing ({said})"), None
            if fresh is None or fresh[2] != MD_MAX_SECTOR:
                return (f"a {kind} volume with an image volume missing ({said}) whose dm-raid "
                        "superblock does not say the array is in sync, so it is not rebuilt "
                        "from parity"), None
            words += f", rebuilt from parity ({said})"
    else:
        words += ", read with all of them present"
    in_sync = (fresh is not None and fresh[2] == MD_MAX_SECTOR
               and "NOTSYNCED" not in (top.get("status") or []))
    return None, RaidLvMap(kind, geom, images, size, words, clean=in_sync)


# --- several images ------------------------------------------------------------

class RaidSet:
    """What raid_assemble() found across the images given: `arrays`, each an
    MdArray or an LVM volume read across images (both with `label`, `lines()`,
    `describe()`, `refused` and `image`), `members` {image label: [lines]} for
    every image that holds a RAID member, and `foreign` [(image label, line)]
    for metadata this does not read."""

    def __init__(self):
        self.arrays, self.members, self.foreign, self._owned = [], {}, [], []

    def close(self):
        for fh in self._owned:
            try:
                fh.close()
            except Exception:                              # pylint: disable=broad-except
                pass
        self._owned = []

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


class LvmSpanned:
    """An LVM logical volume whose physical volumes lie in more than one of the
    images given, read across them."""

    def __init__(self, label, image, how, why=None, absent=(), incomplete=None):
        self.label, self.image, self.how, self.refused = label, image, how, why
        # `absent`: the physical volumes its metadata names under this volume
        # that are not among the images given. It is incomplete only when the
        # legs on them are more than its level can lose (_lvm_lv_incomplete),
        # as for md: a leg given but unusable (REBUILD, a failed device) counts
        # as given, and a refusal for the group's own marks is not incomplete.
        self.absent = sorted(absent)
        self.incomplete = bool(self.absent) if incomplete is None else incomplete
        self.members, self.left_out, self.sb, self.same_as = [], [], None, None
        self.safe_name = "lvm_" + sanitize_volume_label(label[len("LVM "):], 48)

    def lines(self):
        out = [f"{self.label}: {self.how}"]
        if self.refused:
            out.append(f"  NOT READ: {self.refused}")
        else:
            out.append(f"  read as an image of {self.image.size:,} bytes ({human(self.image.size)})")
        return out

    def describe(self):
        return {"kind": "lvm", "label": self.label, "how": self.how, "refused": self.refused,
                "bytes": self.image.size if self.image is not None else None}


def _raid_places(fh, size):
    """[(label, base, size)] where a RAID member may begin on one image: the
    whole image and each partition its tables give."""
    try:
        regions, _names, containers, protective, _ss = table_regions(fh)
    except Exception:                                  # pylint: disable=broad-except
        regions, containers, protective = [], set(), set()
    out = [("whole image", 0, size)]
    out += [r for r in regions if r[0] not in containers and r[0] not in protective
            and r[1] < size and r[2]]
    return out


def raid_assemble(images):
    """A RaidSet for `images`, [(label, fh)] of images already open (each what
    open_image() returns): the md members on each, whole disk or partition,
    assembled into arrays by array uuid and role; the LVM volume groups whose
    physical volumes lie in more than one of the images, their logical volumes
    read across them (a group inside one image is read by volumes() as
    before); and RAID metadata this does not read, by name. An image that
    holds no member of anything is not changed by this; read it as before."""
    rs = RaidSet()
    found, parts = [], []
    for label, fh in images:
        size = image_size(fh)
        parts.append((label, fh, size))
        gpt = parse_gpt(fh)
        lbs = gpt.sector_size if gpt is not None else SECTOR      # disk_sector_size()
        for _idx, pname, tguid, first, _last in (gpt or []):
            kind = RAID_GPT_TYPES.get(tguid.lower())
            if kind:
                rs.foreign.append((label, f"GPT partition {_idx} ({pname or 'no name'}) at LBA "
                                          f"{first:,} is a {kind} partition, which this does not read"))
        hits = {}
        for plabel, base, psize in _raid_places(fh, size):
            psize = min(psize, size - base)
            where = label if plabel == "whole image" else f"{label} {plabel}"
            try:
                sb = md_member(fh, base, psize, lbs)
                foreign = None if sb is not None else raid_foreign(fh, base, psize)
            except (struct.error, ValueError, OSError) as exc:
                rs.foreign.append((label, f"{where}: its RAID metadata could not be read "
                                          f"({type(exc).__name__}: {exc})"))
                continue
            if sb is not None:
                # where it was found, recorded rather than read back from the
                # name shown: the image given and whether it is a partition
                sb.image_label, sb.partition = label, plabel != "whole image"
                # The same superblock seen from the whole disk and from a
                # partition that ends where the disk does (0.90 or 1.0 at the
                # end): the member is the partition, the innermost region.
                key = base + sb.at
                if key not in hits or psize < hits[key][3]:
                    hits[key] = (where, fh, base, psize, sb)
                continue
            if foreign and plabel == "whole image":
                # A mirror member in its normal state is read on its own (the
                # report above walks it): named as a member, not as NOT READ.
                levels, why = raid_foreign_levels(fh, base, psize, foreign)
                if raid_foreign_mirror(levels):
                    rs.members.setdefault(label, []).append(
                        f"{where}: {raid_foreign_article(foreign)} RAID member, whose array this "
                        "does not assemble: its metadata records RAID1 (a mirror) in its normal "
                        "state, so this member is read on its own, as a copy of the mirror")
                else:
                    rs.foreign.append((label, f"{where}: {raid_foreign_article(foreign)} RAID "
                                              "member, whose array this does not assemble: "
                                              + raid_foreign_note(foreign, levels, why, None,
                                                                  "this disk").split(": ", 1)[1]))
        for where, fh_, base, psize, sb in sorted(hits.values(), key=lambda h: h[2]):
            found.append((where, fh_, base, psize, sb))
            rs.members.setdefault(label, []).append(
                f"{where}: md member of {sb.uuid_text()}"
                + (f" ({sb.name})" if sb.name else "")
                + f", metadata {sb.version}")
    rs.arrays += _md_assemble(found)
    if len(parts) > 1:
        try:
            rs.arrays += _lvm_spanned(parts, rs)
        except Exception as exc:                       # pylint: disable=broad-except
            rs.foreign.append(("", "LVM volume groups across the images were not read "
                                   f"({type(exc).__name__}: {exc})"))
    return rs


def _lvm_spanned(parts, rs):
    """The logical volumes of each volume group whose physical volumes are in
    more than one of `parts`, read through one address space over them all."""
    cat = _ConcatImage(parts)
    regions, owner = [], {}
    for start, size, fh, label in cat.parts:
        for plabel, base, psize in _raid_places(fh, size):
            regions.append((f"{label} {plabel}", start + base, min(psize, size - base)))
            owner[start + base] = label
    pvs, first, kept = {}, {}, []
    for reg in regions:
        _l, base, psize = reg
        pv = _lvm_pv(cat, base, psize)
        if pv is not None:
            # the same physical volume given twice (the same image, or two
            # copies of one disk) is read once, and the second named
            key = _lvm_id(pv.uuid)
            if key in first:
                rs.members.setdefault(owner[base], []).append(
                    f"{_l}: the same LVM2 physical volume (id {pv.uuid}) as {first[key]}, "
                    "which is the one read")
                continue
            first[key] = _l
            if pv.vg:
                pvs.setdefault(pv.vg[1].get("id"), set()).add(owner[base])
        kept.append(reg)
    regions = kept
    spanned = [vid for vid, labels in pvs.items() if len(labels) > 1]
    if not spanned:
        return []
    present = set(first)                 # the ids of the physical volumes given
    # Each volume group is matched and read by its id alone: two groups that
    # share a name (a default such as "vg0") are two groups, each read through
    # its own physical volumes, and their labels carry the start of the id.
    by_region, ids_of_name, group_name = {}, {}, {}
    for reg in regions:
        pv = _lvm_pv(cat, reg[1], reg[2])
        by_region[reg[1]] = pv
        if pv is not None and pv.vg:
            ids_of_name.setdefault(pv.vg[0], set()).add(pv.vg[1].get("id"))
            group_name[pv.vg[1].get("id")] = pv.vg[0]
    out = []
    for vid in spanned:
        name = group_name.get(vid, "")
        shared = len(ids_of_name.get(name, ())) > 1
        shown = f"{name}@{_lvm_id(vid)[:6]}" if shared else name
        listed = set()
        for pv in by_region.values():
            if pv is not None and pv.vg and pv.vg[1].get("id") == vid:
                listed |= {_lvm_id(rec.get("id", "")) for rec in
                           (pv.vg[1].get("physical_volumes") or {}).values()
                           if isinstance(rec, dict)}
        mine = [reg for reg in regions if by_region.get(reg[1]) is not None and (
            (by_region[reg[1]].vg and by_region[reg[1]].vg[1].get("id") == vid)
            or (not by_region[reg[1]].vg and _lvm_id(by_region[reg[1]].uuid) in listed))]
        out += _lvm_spanned_group(cat, mine, vid, name, shown, shared, owner, present, rs)
    return out


def _lvm_spanned_group(cat, regions, vid, name, shown, shared, owner, present, rs):
    """The logical volumes of the one volume group `vid` (named `name`, shown
    as `shown`), read from its own physical volumes among `regions`."""
    def relabel(vlabel):
        return f"LVM {shown}/" + vlabel[len(f"LVM {name}/"):] if vlabel.startswith(
            f"LVM {name}/") else vlabel
    found, notes, remap, _free = _lvm_scan(cat, regions)
    out = []
    for _l, base, psize in regions:
        pv = _lvm_pv(cat, base, psize)
        if pv is not None and pv.vg and pv.vg[1].get("id") == vid:
            rs.members.setdefault(owner[base], []).append(
                f"{_l}: LVM2 physical volume of volume group {name}"
                + (f" (id {vid}; another volume group among the images has the same name, so "
                   f"this one is shown as {shown})" if shared else "")
                + ", which spans several images")
    for vlabel, base, vsize, _name in found:
        img = RaidImage(lambda o, n, b=base: (cat.seek(b + o), cat.read(n))[1], vsize,
                        relabel(vlabel))
        out.append(LvmSpanned(relabel(vlabel), img, "linear, read across the images"))
    for _key, lmap, vlabel, _name in remap:

        def rd(o, n, m=lmap):
            if hasattr(m, "read_via"):
                return m.read_via(cat, o, n)
            buf = bytearray()
            for at, length in m.image_runs(o, n):
                cat.seek(at)
                got = cat.read(length)
                buf += got
                if len(got) < length:
                    break
            return bytes(buf)
        how = getattr(lmap, "raid_words", None) or _lvm_shape_words(lmap)
        out.append(LvmSpanned(relabel(vlabel), RaidImage(rd, lmap.size, relabel(vlabel)), how))
    said = set()
    for base, lines in notes.items():
        pv = _lvm_pv(cat, base, None)
        if pv is None or not pv.vg or pv.vg[1].get("id") != vid:
            continue
        for ln in lines:
            if ln.startswith("logical volume ") and ": not read (" in ln and ln not in said:
                said.add(ln)
                lv = ln[len("logical volume "):].split(",", 1)[0]
                vg = pv.vg[1]
                out.append(LvmSpanned(f"LVM {shown}/{lv}", None, "not read",
                                      why=ln.split(": not read (", 1)[1][:-1],
                                      absent=_lvm_absent_pvs(vg, lv, present),
                                      incomplete=_lvm_lv_incomplete(vg, lv, present)))
    return out


def _lvm_lv_incomplete(vg, lvname, present):
    """True when too few of logical volume `lvname`'s legs were given to read
    it, whatever became of the legs given: for a RAID segment, more legs on
    physical volumes not among `present` than its level can lose (raid4 and
    raid5 one, raid6 two, raid10 its data copies less one, raid1 all but one);
    for anything else, any physical volume it names not given."""
    lv = (vg.get("logical_volumes") or {}).get(lvname)
    segs = [v for k, v in (lv or {}).items() if k.startswith("segment") and isinstance(v, dict)]
    if len(segs) != 1 or segs[0].get("type") not in tuple(LVM_RAID_TYPES) + ("raid1",):
        return bool(_lvm_absent_pvs(vg, lvname, present))
    seg = segs[0]
    listed = seg.get("raids") or []
    legs = [listed[i] for i in range(1, len(listed), 2)]
    gone = sum(1 for leg in legs if isinstance(leg, str) and _lvm_absent_pvs(vg, leg, present))
    kind = seg["type"]
    if kind == "raid1":
        tolerate = len(legs) - 1
    elif kind == "raid10":
        tolerate = (seg.get("data_copies") or 2) - 1
    else:
        tolerate = 2 if LVM_RAID_TYPES[kind][0] == 6 else 1
    return gone > tolerate


def _lvm_absent_pvs(vg, lvname, present):
    """The physical volumes the metadata names under logical volume `lvname`
    (its segments' areas, and those of the image, metadata and copy volumes
    they name, to any depth, each looked at once) whose ids are not among
    `present`."""
    pvs = vg.get("physical_volumes") or {}
    lvs = vg.get("logical_volumes") or {}
    seen, todo, absent = set(), [lvname], set()
    while todo and len(seen) < 4096:
        name = todo.pop()
        if name in seen or not isinstance(lvs.get(name), dict):
            continue
        seen.add(name)
        for key, seg in lvs[name].items():
            if not (key.startswith("segment") and isinstance(seg, dict)):
                continue
            for listed in ("stripes", "mirrors", "raids"):
                for item in seg.get(listed) or []:
                    if not isinstance(item, str):
                        continue
                    if item in pvs:
                        if _lvm_id(pvs[item].get("id", "")) not in present:
                            absent.add(item)
                    else:
                        todo.append(item)
    return absent


def raid_display_names(paths):
    """The name the RAID section gives each image path: its file name, or, when
    two paths given share a file name, as many of its parent folders as tell it
    apart from the others (the shortest that does; the whole path at most)."""
    parts = [os.path.abspath(os.path.normpath(os.fspath(p))).split(os.sep) for p in paths]
    depth = [1] * len(parts)

    def name(i):
        return os.sep.join(parts[i][-depth[i]:])
    while True:
        groups = collections.defaultdict(list)
        for i in range(len(parts)):
            groups[name(i)].append(i)
        grow = [i for same in groups.values() if len(same) > 1 for i in same
                if depth[i] < len(parts[i])]
        if not grow:
            return [name(i) for i in range(len(parts))]
        for i in grow:
            depth[i] += 1


def raid_open(paths, passwords=(), private_keys=()):
    """raid_assemble() over the images at `paths`, each opened read-only as
    main() opens it. An image that will not open is left out here (main()
    says why when it reads it)."""
    images = []
    owned = []
    shown = raid_display_names(paths)
    for img_path, name in zip(paths, shown):
        try:
            segments = [] if acquisition_format(img_path) else split_segments(img_path)
            fh = open_image_trying(img_path, segments, passwords, private_keys)
        except Exception:                              # pylint: disable=broad-except
            continue
        owned.append(fh)
        images.append((name, fh))
    try:
        rs = raid_assemble(images)
    except Exception as exc:                           # pylint: disable=broad-except
        # Whatever went wrong is said, and the images are still read one by one.
        rs = RaidSet()
        rs.foreign.append(("", f"RAID members were not assembled ({type(exc).__name__}: {exc})"))
    rs._owned = owned                                  # pylint: disable=protected-access
    return rs


# --- the other members of a RAID set, found beside one of them -----------------
#
# Given one member image, raid_siblings() looks in the same folder for the other
# members by what each file records about itself, never by its name: an md
# member by the array uuid in its superblock, an LVM2 physical volume by the
# volume group id in its metadata and its own id among the physical volumes
# that metadata lists. Every file in the folder is accounted for in the result:
# added (and the identity that matched), part of a set opened from another
# file, rejected (opened, and why it is not used), or skipped (not opened, and
# why). Nothing is added without being named.

RAID_SIBLING_MAX_CANDIDATES = 256      # files opened per search; the rest are named, not opened
RAID_SIBLING_MIN_BYTES = 2048          # the four 512-byte sectors an LVM2 label may sit in (LvmPv)
RAID_SIBLING_READ_BUDGET = 64 << 20    # bytes read from any one other file before it is given up


class _SiblingBudget(Exception):
    """A candidate asked for more bytes than the search reads from one file."""


class _BudgetReader:
    """A read-only view of an open image that refuses any read that would take
    it past `budget` bytes in all, so a hostile file (a metadata area that says
    it is gigabytes long) costs at most the budget."""

    def __init__(self, fh, budget):
        self._fh = fh
        self.size = image_size(fh)
        self.left = budget
        self.spent = 0
        self.over = False

    def seek(self, offset, whence=0):
        return self._fh.seek(offset, whence)

    def tell(self):
        return self._fh.tell()

    def read(self, n=-1):
        if n is None or n < 0:
            n = max(0, self.size - self._fh.tell())
        if n > self.left:
            self.over = True
            raise _SiblingBudget(f"a read of {n:,} bytes would pass the {self.spent + self.left:,} "
                                 "bytes this search reads from one file")
        self.left -= n
        data = self._fh.read(n)
        self.spent += len(data)
        return data


def _raid_identity_scan(fh):
    """[(where, MdSuper or None, LvmPv or None, [problems], (base, size))] for each place a
    member may begin on one open image, the whole image and each partition its
    tables give (_raid_places), read with the same functions raid_assemble()
    uses, so a match here is a member there. `problems` is [(code, text)]
    naming RAID metadata that is present and does not check out
    ("bad-metadata"), and RAID metadata of a kind this does not read
    ("foreign-metadata"). A superblock found both from the whole image and from a
    partition that ends where the image does belongs to the partition."""
    size = image_size(fh)
    gpt = parse_gpt(fh)
    lbs = gpt.sector_size if gpt is not None else SECTOR      # as raid_assemble()
    out, md_at = [], {}
    for plabel, base, psize in _raid_places(fh, size):
        psize = min(psize, size - base)
        where = plabel.strip()
        sb = md_member(fh, base, psize, lbs)
        pv = _lvm_pv(fh, base, psize)
        problems = []
        if sb is None:
            for version, at in _md_places(psize):
                head = read_at(fh, base + at, 4)
                if len(head) == 4 and MD_SB_MAGIC in struct.unpack("<I", head) + struct.unpack(">I", head):
                    problems.append(("bad-metadata",
                                     f"{where}: an md superblock magic at byte {base + at:,} (where "
                                     f"metadata {version} puts it) whose superblock does not check "
                                     "out (checksum or fields)"))
            foreign = raid_foreign(fh, base, psize) if plabel == "whole image" else None
            if foreign:
                problems.append(("foreign-metadata",
                                 f"{where}: {foreign} RAID metadata, which this does not read"))
        if pv is None:
            for sector in range(4):
                if read_at(fh, base + sector * SECTOR, 8) == LVM_LABEL_ID:
                    problems.append(("bad-metadata",
                                     f"{where}: an LVM2 label in sector {sector} that lvm2 would "
                                     "not accept (its sector number, checksum or type)"))
                    break
        if sb is not None:
            key = base + sb.at
            if key in md_at:
                prev = md_at[key]
                if psize < prev[1]:
                    out[prev[0]] = (out[prev[0]][0], None) + out[prev[0]][2:]
                else:
                    sb = None
            if sb is not None:
                md_at[key] = (len(out), psize)
        out.append((where, sb, pv, problems, (base, psize)))
    return out


def _md_member_key(sb):
    """What names one device of an md array: its array uuid with, for metadata
    1.x, the device uuid each member's superblock records (dev_uuid), and for
    0.90, which records none, its device number."""
    return ("md", sb.uuid, sb.dev_uuid if sb.major == 1 else sb.dev_number)


def _md_identity(sb, where):
    role = sb.role if isinstance(sb.role, int) else (sb.role or "spare")
    out = {"kind": "md", "where": where, "array_uuid": sb.uuid_text(), "name": sb.name,
           "metadata": sb.version, "level": MD_LEVELS.get(sb.level, sb.level),
           "raid_disks": sb.raid_disks, "role": role, "events": sb.events}
    if sb.major == 1:
        out["device_uuid"] = ":".join(sb.dev_uuid[i:i + 4].hex() for i in range(0, 16, 4))
    else:
        out["device_number"] = sb.dev_number
    return out


def _lvm_listed(vg):
    """{pv id without dashes: (pv name, pv id as written)} that a volume group
    section lists."""
    out = {}
    for name, rec in (vg.get("physical_volumes") or {}).items():
        if isinstance(rec, dict) and rec.get("id"):
            out[_lvm_id(rec["id"])] = (name, rec["id"])
    return out


def _lvm_identity(pv, where, vg=None, listed=None):
    """The identity of one physical volume: its own id, and the volume group
    `vg` (name, section, seqno) it is matched to, its own metadata's when None."""
    vg = vg or pv.vg
    out = {"kind": "lvm", "where": where, "pv_uuid": pv.uuid}
    if listed and _lvm_id(pv.uuid) in listed:
        out["pv_name"], out["pv_uuid"] = listed[_lvm_id(pv.uuid)]
    if vg:
        out.update(vg_name=vg[0], vg_uuid=vg[1].get("id"), seqno=vg[2])
    out["own_metadata"] = pv.vg is not None
    return out


class RaidSiblings:
    """What raid_siblings() found. `start` is the image given; `folder` the
    folder searched (that folder only); `given` the files the image given and
    `also_given` are read from (a split set's segments, an acquisition's
    files); `identities` the md arrays and LVM volume groups the image given
    holds members of, which are what is looked for; `checked` a record per
    other entry of the folder, in the order they were looked at, each
    {"path", "status", "code", "why"} with status "added", "part-of",
    "rejected" or "skipped", and for an added file "files" (every file read
    for it) and "identities" (each member it holds that matched); `missing`
    the members those identities name that no file given or found holds;
    `warnings` what an examiner must see first (a newer copy, or one as new
    with other bytes, of a member the image given holds); `ambiguous` each
    member two or more files hold, as new as each other, with different bytes
    ({"key", "files", "identity"}), none of which is used; `error` why the
    image given could not be searched from, else None. An added record may
    carry "not_searched": members of other arrays or volume groups in the
    same file, which the run reads with it but were not looked for."""

    def __init__(self, start, folder):
        self.start, self.folder = start, folder
        self.given, self.identities, self.checked, self.missing = [], [], [], []
        self.error = None
        self.notes, self.warnings, self.ambiguous = [], [], []
        self.read_budget = RAID_SIBLING_READ_BUDGET

    @property
    def added(self):
        return [c for c in self.checked if c["status"] == "added"]

    @property
    def rejected(self):
        return [c for c in self.checked if c["status"] in ("rejected", "skipped")]

    def paths(self):
        """The image given, then each file added, as raid_open() takes them."""
        return [self.start] + [c["path"] for c in self.added]

    def describe(self):
        return {"start": self.start, "folder": self.folder, "given": list(self.given),
                "identities": list(self.identities), "checked": list(self.checked),
                "missing": list(self.missing), "error": self.error, "notes": list(self.notes),
                "warnings": list(self.warnings), "ambiguous": list(self.ambiguous),
                "read_budget": self.read_budget}

    def lines(self):
        name = os.path.basename(self.start)
        out = [f"folder    {self.folder} (this folder only, not its subfolders)"]
        if len(self.given) > 1:
            out.append(f"given     {name}, read from {len(self.given)} files: "
                       + ", ".join(os.path.basename(g) for g in self.given))
        if self.error:
            out.append(f"NOT SEARCHED: {self.error}")
            return out
        for ident in self.identities:
            out.append("looked for " + _sibling_identity_words(ident, short=False))
        for warning in self.warnings:
            out.append(f"WARNING   {warning}")
        for note in self.notes:
            out.append(f"note      {note}")
        for c in self.checked:
            label = {"added": "added", "part-of": "part of", "rejected": "not used",
                     "skipped": "skipped"}[c["status"]]
            text = f"{label:<9} {os.path.basename(c['path'])}: {c['why']}"
            if c["status"] == "added" and len(c.get("files") or ()) > 1:
                text += " (read from " + ", ".join(os.path.basename(f) for f in c["files"]) + ")"
            out.append(text)
            for other in c.get("not_searched") or ():
                out.append(f"  also    {other}: not an identity of the image given, so it was "
                           "not searched for; it is read with this file all the same")
        for m in self.missing:
            out.append(f"missing   {m['why']}")
        if not self.identities:
            return out
        opened = sum(1 for c in self.checked if c["status"] in ("added", "rejected"))
        out.append(f"checked   {len(self.checked)} other entries in the folder, opened "
                   f"{opened}, added {len(self.added)}; at most {self.read_budget:,} bytes "
                   "read from each file opened")
        return out


def _sibling_identity_words(ident, short=True):
    if ident["kind"] == "md":
        words = f"md member of array {ident['array_uuid']}"
        if ident.get("name"):
            words += f" ({ident['name']})"
        if ident.get("where") not in (None, "", "whole image"):
            words = f"{ident['where']}: {words}"
        if short:
            role = ident["role"]
            words += (f", role {role}" if isinstance(role, int) else f", {role}")
            words += f", metadata {ident['metadata']}, events {ident['events']:,}"
            words += (f", device uuid {ident['device_uuid']}" if "device_uuid" in ident
                      else f", device number {ident['device_number']}")
        else:
            words = (f"md array {ident['array_uuid']}"
                     + (f" ({ident['name']})" if ident.get("name") else "")
                     + f", {ident['level']} of {ident['raid_disks']} members, metadata "
                     f"{ident['metadata']}")
        return words
    if short:
        words = f"LVM2 physical volume {ident.get('pv_name') or ''} (id {ident['pv_uuid']})".replace("  ", " ")
        if ident.get("where") not in (None, "", "whole image"):
            words = f"{ident['where']}: {words}"
        words += f" of volume group {ident.get('vg_name')} (id {ident.get('vg_uuid')})"
        if not ident.get("own_metadata"):
            words += ", which carries no volume group metadata of its own; its id is listed in the group's"
        return words
    return (f"LVM2 volume group {ident['vg_name']} (id {ident['vg_uuid']}), seqno "
            f"{ident['seqno']}, {ident['pvs']} physical volume(s) listed")


def _sibling_image_files(fh, path):
    """Every file an open image is read from, as absolute paths."""
    files = list(getattr(fh, "paths", None) or [])
    return [os.path.abspath(f) for f in files] or [os.path.abspath(path)]


def _sibling_inode(path):
    try:
        st = os.stat(path)
    except OSError:
        return None
    return (st.st_dev, st.st_ino)


def _sibling_open(path, passwords, private_keys):
    segments = [] if acquisition_format(path) else split_segments(path)
    return open_image_trying(path, segments, passwords, private_keys)


class _SiblingChanged(Exception):
    """A file of the folder did not open, or is not, when opened, the regular
    file it was when listed. `code` says which ("unreadable", "not-regular",
    "changed"). Not an OSError, so read_at() does not turn it into a short read."""

    def __init__(self, text, code="changed"):
        super().__init__(text)
        self.code = code


def _sibling_fd_open(path, expect=None):
    """(file object, (device, inode), size) for `path`, opened without
    blocking and without following a final symbolic link, and checked through
    the descriptor itself: anything that is not a regular file, or not the
    file `expect` names, is refused before a byte is read. A pipe opened this
    way returns at once instead of waiting for a writer, so a file swapped for
    one after it was listed cannot hang the search."""
    import stat
    flags = (os.O_RDONLY | getattr(os, "O_NONBLOCK", 0) | getattr(os, "O_NOFOLLOW", 0)
             | getattr(os, "O_BINARY", 0))
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise _SiblingChanged(f"it did not open ({type(exc).__name__}: {exc})",
                              "unreadable") from None
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode):
            raise _SiblingChanged("when opened it was not a regular file (a device, pipe or "
                                  "socket), so nothing was read from it", "not-regular")
        if expect is not None and (st.st_dev, st.st_ino) != tuple(expect):
            raise _SiblingChanged("when opened it was a different file from the one listed "
                                  "(another device and inode), so nothing was read from it")
        return os.fdopen(fd, "rb"), (st.st_dev, st.st_ino), st.st_size
    except BaseException:
        os.close(fd)
        raise


class _SiblingSegments(SegmentedImage):
    """A split raw set read as SegmentedImage reads it, each segment opened by
    _sibling_fd_open() and held to the device and inode it had when first
    opened (and the candidate's own to the one it had when listed)."""

    def __init__(self, paths, first=None):
        super().__init__(paths)
        self._ino = {}
        if first is not None:
            self._ino[0] = first

    def _handle(self, i):
        fh = self._open.get(i)
        if fh is not None:
            self._open.move_to_end(i)
            return fh
        fh, ino, size = _sibling_fd_open(self.paths[i], self._ino.get(i))
        if size != self.sizes[i]:
            fh.close()
            raise _SiblingChanged(f"{os.path.basename(self.paths[i])} changed size while it "
                                  "was looked at")
        self._ino[i] = ino
        self._open[i] = fh
        while len(self._open) > self.MAX_OPEN:
            self._open.popitem(last=False)[1].close()
        return fh


def _sibling_kind(fh, size, name):
    """"container" when the first or last 512 bytes, read through the open
    descriptor, carry a signature of a container open_image() hands to the
    vendored reader (the ones acquisition_format() and virtual_disk_kind()
    test), "split" for a name ending in a number, else "raw"."""
    head = read_at(fh, 0, 512)
    tail = read_at(fh, max(0, size - 512), 512)
    text = head[3:] if head.startswith(b"\xef\xbb\xbf") else head
    if (head[:8] in (EWF_SIGNATURE, EWF2_SIGNATURE, AFF_SIGNATURE, L01_SIGNATURE, LX01_SIGNATURE,
                     AD1_SIGNATURE[:8], DMG_ENCRYPTED_SIGNATURE, ADCRYPT_SIGNATURE, VHDX_SIGNATURE)
            or head[:4] in (b"AFF\x00", SPARSEIMAGE_SIGNATURE, ZIP_SIGNATURE, VMDK_SPARSE_MAGIC,
                            VMDK_COWD_MAGIC, QCOW_MAGIC)
            or text[:len(VMDK_DESCRIPTOR_START)].lower() == VMDK_DESCRIPTOR_START.lower()
            or VHD_COOKIE in (tail[:8], tail[1:9], head[:8])
            or tail[:4] == UDIF_TRAILER):
        return "container"
    _stem, dot, suffix = name.rpartition(".")
    if dot and suffix.isascii() and suffix.isdigit():
        return "split"
    return "raw"


def _sibling_open_candidate(full, kind, listed, passwords, private_keys):
    """(open image, [files it is read from]) for one file of the folder, opened
    as `kind` says. A raw file is read only through the descriptor opened and
    checked by _sibling_fd_open(); a split set through _SiblingSegments. An
    acquisition container is read by its reader, which opens its files by name:
    just before that, the file is checked to be the regular file it was when
    listed, and every entry of the folder whose name starts with its stem
    (where a container's other files are) to be a regular file or a folder."""
    import stat
    if kind == "split":
        try:
            segments = split_segments(full)
        except SplitImageError as exc:
            raise _SiblingChanged(f"it did not open (SplitImageError: {exc})",
                                  "unreadable") from None
        if segments:
            image = _SiblingSegments(segments, listed if segments[0] == full else None)
            return image, [os.path.abspath(p) for p in segments]
        kind = "raw"
    if kind == "raw":
        fh, _ino, _size = _sibling_fd_open(full, listed)
        return fh, [os.path.abspath(full)]
    st = os.lstat(full)
    if not stat.S_ISREG(st.st_mode) or (st.st_dev, st.st_ino) != tuple(listed):
        raise _SiblingChanged("it changed after it was listed (not the same regular file), "
                              "so it was not handed to its reader")
    folder, name = os.path.split(full)
    stem = name.split(".", 1)[0]
    for entry in os.listdir(folder):
        if entry.startswith(stem):
            est = os.lstat(os.path.join(folder, entry))
            if not (stat.S_ISREG(est.st_mode) or stat.S_ISDIR(est.st_mode)):
                raise _SiblingChanged(f"{entry}, beside it under the same name, is not a "
                                      "regular file, and its reader opens a container's "
                                      "files by name, so it was not opened")
    image = _sibling_open(full, passwords, private_keys)
    if _sibling_inode(full) != tuple(listed):
        image.close()
        raise _SiblingChanged("it changed while its reader opened it")
    return image, _sibling_image_files(image, full)


def _sibling_scan_file(opener, budget):
    """(files, regions, error) for one image opened by `opener()`, which
    returns (image, files): _raid_identity_scan() of it within the read
    budget (None for no limit), or why it could not be opened or read."""
    try:
        fh, files = opener()
    except ImagePasswordError as exc:
        return None, None, ("unreadable", f"it did not open: {exc} (give its password or "
                                          "key to use it)")
    except _SiblingChanged as exc:
        return None, None, (exc.code, str(exc))
    except Exception as exc:                           # pylint: disable=broad-except
        return None, None, ("unreadable", f"it did not open ({type(exc).__name__}: {exc})")
    try:
        view = _BudgetReader(fh, budget) if budget is not None else fh
        try:
            regions = _raid_identity_scan(view)
        except _SiblingBudget as exc:
            return files, None, ("over-budget", f"not read past the search's limit: {exc}")
        except _SiblingChanged as exc:
            return files, None, (exc.code, str(exc))
        except Exception as exc:                       # pylint: disable=broad-except
            return files, None, ("unreadable", f"its RAID metadata could not be read "
                                               f"({type(exc).__name__}: {exc})")
        if getattr(view, "over", False):
            return files, None, ("over-budget", "not read past the search's limit of "
                                                f"{budget:,} bytes from one file")
        return files, regions, None
    finally:
        try:
            fh.close()
        except Exception:                              # pylint: disable=broad-except
            pass


def _sibling_same_bytes(open_a, span_a, open_b, span_b, step=1 << 20):
    """True when two members hold the same bytes over their whole region
    (the partition or image the superblock or label was found on): equal
    length, then compared a MiB at a time to the first difference. Each
    opener returns (image, files). False when either cannot be read."""
    if span_a[1] != span_b[1]:
        return False
    try:
        a, _fa = open_a()
    except Exception:                                  # pylint: disable=broad-except
        return False
    try:
        b, _fb = open_b()
    except Exception:                                  # pylint: disable=broad-except
        a.close()
        return False
    try:
        off, size = 0, span_a[1]
        while off < size:
            n = min(step, size - off)
            x, y = read_at(a, span_a[0] + off, n), read_at(b, span_b[0] + off, n)
            if len(x) != n or x != y:
                return False
            off += n
        return True
    except Exception:                                  # pylint: disable=broad-except
        return False
    finally:
        a.close()
        b.close()


def raid_siblings(path, passwords=(), private_keys=(), also_given=(),
                  max_candidates=RAID_SIBLING_MAX_CANDIDATES,
                  min_bytes=RAID_SIBLING_MIN_BYTES, read_budget=RAID_SIBLING_READ_BUDGET,
                  _ignore=()):
    """A RaidSiblings for the image at `path`: the other members of the md
    arrays and LVM2 volume groups it holds members of, found in its folder by
    the identity each file records. Never raises for a file it cannot read; an
    image given that cannot be opened is said in `error`.

    The rule: an md member is added when its superblock checks out at a place
    the kernel looks (md_member(), as raid_assemble() reads it) and its array
    uuid is one the image given holds. An LVM2 physical volume is added when
    its label is one lvm2 accepts and its own id is listed under
    physical_volumes in the newest metadata (highest seqno) of a volume group
    the image given holds, and its own metadata, when it has any, names that
    group's id.

    One file per member (the same md array and device uuid, 0.90's device
    number, or the same physical volume id). A member the image given or
    `also_given` holds is never taken from another file; a newer copy of it
    (md events, lvm2 metadata seqno), or one as new whose bytes differ, is
    named in `warnings`. Of other files holding one member, the newest is
    used, as md keeps the newer of two members claiming one role (mdadm
    Assemble.c 841-843); when the newest are as new as each other, they are
    compared over the member's whole region: byte for byte the same, the
    first looked at is used and the others named as copies of it; otherwise
    none is used, each is rejected as "ambiguous-member", and the member is
    reported missing (mdadm refuses two 0.90 members with one role and equal
    events, Assemble.c 820-838; this applies that to 1.x and LVM too).

    A file that is the same file as one given or one looked at already (same
    device and inode) is not opened. Only the folder itself is searched;
    symbolic links, folders and anything that is not a regular file are
    skipped and named. Every other file is opened without blocking and checked
    through its descriptor (_sibling_fd_open), and raw files and split sets
    are read only through descriptors so checked; an acquisition container is
    checked again just before its reader opens it by name
    (_sibling_open_candidate). Containers are opened first, then split sets,
    then the rest, each by name; a file one of them is read from is named as
    part of it. At most `max_candidates` files are opened (the first by name;
    the rest are named, not opened), and at most `read_budget` bytes read from
    each through qnxprobe's own reads (the image given is read as it needs,
    and so are two copies of a member compared byte for byte). `_ignore` turns
    a rule off, for the self-test's controls only."""
    import stat
    start = os.path.abspath(path)
    res = RaidSiblings(start, os.path.dirname(start))
    res.read_budget = read_budget
    ign = set(_ignore)

    def given_opener(image_path):
        def opener():
            image = _sibling_open(image_path, passwords, private_keys)
            return image, _sibling_image_files(image, image_path)
        return opener

    try:
        fh = _sibling_open(path, passwords, private_keys)
    except Exception as exc:                           # pylint: disable=broad-except
        res.error = f"{os.path.basename(start)} did not open ({type(exc).__name__}: {exc})"
        res.given = [start]
        return res
    try:
        res.given = _sibling_image_files(fh, path)
        try:
            # read in full where it needs: the examiner named this image
            start_regions = _raid_identity_scan(fh)
        except Exception as exc:                       # pylint: disable=broad-except
            res.error = (f"the RAID metadata of {os.path.basename(start)} could not be read "
                         f"({type(exc).__name__}: {exc})")
            return res
    finally:
        try:
            fh.close()
        except Exception:                              # pylint: disable=broad-except
            pass

    # What is present already: the image given, and any the caller also has.
    present_files = set(res.given)
    present_inodes = {}
    for f in res.given:
        ino = _sibling_inode(f)
        if ino is not None:
            present_inodes.setdefault(ino, f)
    held = {}                         # member key: (file holding it, score, span, opener)
    present_regions = []              # (file, where, sb, pv, span, opener)
    for where, sb, pv, _p, span in start_regions:
        present_regions.append((start, where, sb, pv, span, given_opener(path)))
    for other in also_given:
        other_abs = os.path.abspath(other)
        files, regions, err = _sibling_scan_file(given_opener(other), None)
        for f in files or [other_abs]:
            present_files.add(f)
            ino = _sibling_inode(f)
            if ino is not None:
                present_inodes.setdefault(ino, f)
        if err is None:
            for where, sb, pv, _p, span in regions:
                present_regions.append((other_abs, where, sb, pv, span, given_opener(other)))
    for owner, _where, sb, pv, span, opener in present_regions:
        if sb is not None:
            held.setdefault(_md_member_key(sb), (owner, sb.events, span, opener))
        if pv is not None:
            held.setdefault(("lvm", _lvm_id(pv.uuid)), (owner, pv.vg[2] if pv.vg else -1,
                                                        span, opener))

    md_targets = collections.OrderedDict()            # array uuid: first MdSuper seen
    for _w, sb, _pv, _p, _s in start_regions:
        if sb is not None and sb.uuid not in md_targets:
            md_targets[sb.uuid] = sb
    vg_targets = collections.OrderedDict()            # vg id: (name, section, seqno), newest
    start_pv_ids = set()
    for _w, _sb, pv, _p, _s in start_regions:
        if pv is None:
            continue
        start_pv_ids.add(_lvm_id(pv.uuid))
        if pv.vg:
            vid = pv.vg[1].get("id")
            if vid not in vg_targets or pv.vg[2] > vg_targets[vid][2]:
                vg_targets[vid] = pv.vg
    for _w, _sb, _pv, problems, _s in start_regions:
        res.notes += [text for _code, text in problems]

    if not md_targets and not any(pv is not None for _w, _sb, pv, _p, _s in start_regions):
        res.notes.append(f"{os.path.basename(start)} holds no md member or LVM2 physical "
                         "volume this reads, so nothing was looked for")
        return res

    # The folder's entries, by name; each one is accounted for.
    try:
        names = sorted(os.listdir(res.folder))
    except OSError as exc:
        res.error = f"the folder could not be listed ({type(exc).__name__}: {exc})"
        return res
    entries = []
    for name in names:
        full = os.path.join(res.folder, name)
        if full in present_files:
            continue
        try:
            st = os.lstat(full)
        except OSError as exc:
            res.checked.append({"path": full, "status": "skipped", "code": "unreadable",
                                "why": f"it could not be looked at ({type(exc).__name__}: {exc})"})
            continue
        if stat.S_ISLNK(st.st_mode) and "symlink" not in ign:
            res.checked.append({"path": full, "status": "skipped", "code": "symlink",
                                "why": "a symbolic link, which this does not follow"})
            continue
        if stat.S_ISLNK(st.st_mode):
            try:
                st = os.stat(full)
            except OSError:
                continue
        if stat.S_ISDIR(st.st_mode):
            if "directory" not in ign:
                res.checked.append({"path": full, "status": "skipped", "code": "directory",
                                    "why": "a folder; only this folder is searched, not "
                                           "its subfolders"})
                continue
            try:
                for inner in sorted(os.listdir(full)):
                    inner_full = os.path.join(full, inner)
                    if os.path.isfile(inner_full) and not os.path.islink(inner_full):
                        entries.append((inner_full, os.stat(inner_full)))
            except OSError:
                pass
            continue
        if not stat.S_ISREG(st.st_mode):
            res.checked.append({"path": full, "status": "skipped", "code": "not-regular",
                                "why": "not a regular file (a device, pipe or socket), "
                                       "which this does not open"})
            continue
        entries.append((full, st))
    candidates = []
    for full, st in entries:
        ino = (st.st_dev, st.st_ino)
        if ino in present_inodes and "same_file" not in ign:
            res.checked.append({"path": full, "status": "skipped", "code": "same-file",
                                "why": f"the same file as {os.path.basename(present_inodes[ino])} "
                                       "(same device and inode), which is already given"})
            continue
        if st.st_size < min_bytes and "size" not in ign:
            res.checked.append({"path": full, "status": "skipped", "code": "too-small",
                                "why": f"{st.st_size:,} bytes, smaller than the {min_bytes:,} an "
                                       "LVM2 label or an md superblock needs"})
            continue
        candidates.append((full, ino))
    for full, _ino in candidates[max_candidates:]:
        res.checked.append({"path": full, "status": "skipped", "code": "over-limit",
                            "why": f"not opened: this search opens at most {max_candidates:,} "
                                   "files"})
    # What each is, from its own bytes read through a checked descriptor.
    kinds = []
    for full, ino in candidates[:max_candidates]:
        try:
            fh, _i, size = _sibling_fd_open(full, ino)
        except _SiblingChanged as exc:
            res.checked.append({"path": full, "status": "skipped", "code": exc.code,
                                "why": str(exc)})
            continue
        try:
            kind = _sibling_kind(fh, size, os.path.basename(full))
        finally:
            fh.close()
        _stem, _dot, suffix = os.path.basename(full).rpartition(".")
        rank = (0 if kind == "container" else
                1 if kind == "split" and int(suffix) in (0, 1) else 2)
        kinds.append((rank, os.path.basename(full), full, ino, kind))
    kinds.sort()

    def candidate_opener(full, kind, ino):
        return lambda: _sibling_open_candidate(full, kind, ino, passwords, private_keys)

    # Open and read each, in that order; a file another one's image is read
    # from is part of that one.
    consumed = {}
    scanned = []
    seen_inodes = {}
    for _rank, _name, full, ino, kind in kinds:
        if ino in seen_inodes and "same_file" not in ign:
            res.checked.append({"path": full, "status": "skipped", "code": "same-file",
                                "why": f"the same file as {os.path.basename(seen_inodes[ino])} "
                                       "(same device and inode), looked at already"})
            continue
        seen_inodes.setdefault(ino, full)
        if full in consumed:
            res.checked.append({"path": full, "status": "part-of", "code": "segment",
                                "why": f"one of the files {os.path.basename(consumed[full])} is "
                                       "read from, looked at with it"})
            continue
        opener = candidate_opener(full, kind, ino)
        files, regions, err = _sibling_scan_file(opener, read_budget)
        files = files or [full]
        rec = {"path": full, "files": files}
        clash = None
        for f in files:
            if f != full:
                consumed.setdefault(f, full)
            fino = _sibling_inode(f)
            if f in present_files or (fino in present_inodes and "same_file" not in ign):
                clash = present_inodes.get(fino, f)
        if clash is not None:
            rec.update(status="skipped", code="same-file",
                       why=f"its image is read from {os.path.basename(clash)}, a file already given")
            res.checked.append(rec)
            continue
        if err is not None:
            rec.update(status="rejected", code=err[0], why=err[1])
            res.checked.append(rec)
            continue
        res.checked.append(rec)
        scanned.append((rec, regions, opener))

    # A start whose physical volume carries no metadata: the volume groups
    # whose metadata lists it.
    for _rec, regions, _o in scanned:
        for _w, _sb, pv, _p, _s in regions:
            if pv is not None and pv.vg and start_pv_ids & set(_lvm_listed(pv.vg[1])):
                vid = pv.vg[1].get("id")
                if vid not in vg_targets or pv.vg[2] > vg_targets[vid][2]:
                    vg_targets[vid] = pv.vg
    # The newest copy of each volume group's metadata among the files that name it.
    for _rec, regions, _o in scanned:
        for _w, _sb, pv, _p, _s in regions:
            if pv is not None and pv.vg and pv.vg[1].get("id") in vg_targets:
                vid = pv.vg[1].get("id")
                if pv.vg[2] > vg_targets[vid][2]:
                    vg_targets[vid] = pv.vg
    listed = {vid: _lvm_listed(vg[1]) for vid, vg in vg_targets.items()}

    # Each file's members that match, before any is chosen.
    hits_of = []
    for rec, regions, opener in scanned:
        hits, other, bad = [], [], []
        for index, (where, sb, pv, problems, span) in enumerate(regions):
            bad += problems
            if sb is not None:
                if sb.uuid in md_targets or "identity" in ign:
                    hits.append((_md_member_key(sb), _md_identity(sb, where), "md-array-uuid",
                                 sb.events, "events", span, index))
                else:
                    other.append(("different-array",
                                  f"{where}: an md member of a different array, "
                                  f"{sb.uuid_text()}" + (f" ({sb.name})" if sb.name else "")))
            if pv is not None:
                vid = pv.vg[1].get("id") if pv.vg else None
                pid = _lvm_id(pv.uuid)
                group = None
                if vid is not None and (vid in vg_targets or "identity" in ign):
                    group = vg_targets.get(vid, pv.vg)
                    if pid not in listed.get(vid, _lvm_listed(pv.vg[1])) and "pv_listed" not in ign:
                        other.append(("pv-not-listed",
                                      f"{where}: an LVM2 physical volume (id {pv.uuid}) whose own "
                                      f"metadata names volume group {pv.vg[0]} (id {vid}), but the "
                                      f"newest metadata of that group (seqno {group[2]}) does not "
                                      "list its id"))
                        group = None
                elif vid is None:
                    for tid, ids in listed.items():
                        if pid in ids:
                            group = vg_targets[tid]
                            break
                    if group is None:
                        other.append(("pv-not-listed",
                                      f"{where}: an LVM2 physical volume (id {pv.uuid}) with no "
                                      "volume group metadata of its own, whose id no volume group "
                                      "looked for lists"))
                else:
                    other.append(("different-vg",
                                  f"{where}: an LVM2 physical volume of a different volume group, "
                                  f"{pv.vg[0]} (id {vid})"))
                if group is not None:
                    hits.append((("lvm", pid), _lvm_identity(pv, where, group, _lvm_listed(group[1])),
                                 "lvm-vg-pv", pv.vg[2] if pv.vg else -1, "metadata seqno", span,
                                 index))
        hits_of.append((rec, hits, other, bad, opener))

    # Which file each member is taken from (see the docstring).
    by_key = collections.OrderedDict()
    for order, (rec, hits, _o, _b, opener) in enumerate(hits_of):
        for key, ident, _code, score, unit, span, _i in hits:
            by_key.setdefault(key, []).append((order, rec, score, unit, span, opener, ident))
    verdict = {}                    # (order, key): ("use", None) or (code, why)
    for key, holders in by_key.items():
        if "duplicate" in ign:
            for h in holders:
                verdict[(h[0], key)] = ("use", None)
            continue
        if key in held:
            owner, gscore, gspan, gopen = held[key]
            gname = os.path.basename(owner)
            for order, rec, score, unit, span, opener, ident in holders:
                name = os.path.basename(rec["path"])
                if score > gscore:
                    res.warnings.append(
                        f"a newer copy of the member you gave is beside it: {name}, {unit} "
                        f"{score:,} > {gscore:,} in {gname}; {gname} is used as given, and "
                        f"its copy of that member is stale ({_sibling_identity_words(ident)})")
                    why = (f"a newer copy ({unit} {score:,}) of the member {gname} holds "
                           f"({unit} {gscore:,}); {gname} is used as given")
                elif score == gscore and _sibling_same_bytes(gopen, gspan, opener, span):
                    why = f"a byte-for-byte copy of the member {gname} holds, which is used"
                elif score == gscore:
                    res.warnings.append(
                        f"{name} holds the member {gname} holds, as new ({unit} {score:,}) "
                        f"but with different bytes; {gname} is used as given "
                        f"({_sibling_identity_words(ident)})")
                    why = (f"the member {gname} holds, as new ({unit} {score:,}) but with "
                           f"different bytes; {gname} is used as given")
                else:
                    why = (f"an older copy ({unit} {score:,}) of the member {gname} holds "
                           f"({unit} {gscore:,}), which is used")
                verdict[(order, key)] = ("duplicate-member",
                                         f"{why} ({_sibling_identity_words(ident)})")
            continue
        top = max(h[2] for h in holders)
        tops = [h for h in holders if h[2] == top]
        first = tops[0]
        same = all(_sibling_same_bytes(first[5], first[4], h[5], h[4]) for h in tops[1:])
        names = ", ".join(os.path.basename(h[1]["path"]) for h in tops)
        if len(tops) > 1 and not same:
            names = ", ".join(os.path.basename(h[1]["path"]) for h in tops)
            res.ambiguous.append({"key": list(key), "files": [h[1]["path"] for h in tops],
                                  "identity": first[6]})
        for order, rec, score, unit, span, opener, ident in holders:
            fname = os.path.basename(first[1]["path"])
            words = _sibling_identity_words(ident)
            if len(tops) > 1 and not same and score == top:
                verdict[(order, key)] = ("ambiguous-member",
                                         f"{names} each hold this member, as new as each other "
                                         f"({unit} {top:,}) but with different bytes, so none "
                                         f"of them is used and the member counts as missing "
                                         f"({words})")
            elif score < top:
                verdict[(order, key)] = ("duplicate-member",
                                         f"an older copy ({unit} {score:,}) of the member "
                                         + (f"{fname} holds ({unit} {top:,}), which is used"
                                            if same or len(tops) == 1 else
                                            f"whose newest copies differ ({names})")
                                         + f" ({words})")
            elif order == first[0]:
                verdict[(order, key)] = ("use", None)
            else:
                verdict[(order, key)] = ("duplicate-member",
                                         f"a byte-for-byte copy of the member {fname} holds, "
                                         f"which is used ({words})")

    used_regions = {}
    for order, (rec, hits, other, bad, _op) in enumerate(hits_of):
        matched, dup, amb = [], [], []
        for key, ident, code, _score, _unit, _span, index in hits:
            v = verdict[(order, key)]
            if v[0] == "use":
                matched.append((key, ident, code, index))
            elif v[0] == "ambiguous-member":
                amb.append(v[1])
            else:
                dup.append(v[1])
        not_searched = [t for c, t in other if c in ("different-array", "different-vg")]
        if matched:
            used_regions[order] = [m[3] for m in matched]
            rec.update(status="added", code=matched[0][2],
                       identities=[m[1] for m in matched],
                       why="; ".join(_sibling_identity_words(m[1]) for m in matched)
                       + ("; also " + "; ".join(amb + dup) if amb or dup else ""))
            if not_searched:
                rec["not_searched"] = not_searched
        elif amb:
            rec.update(status="rejected", code="ambiguous-member", why="; ".join(amb + dup))
        elif dup:
            rec.update(status="rejected", code="duplicate-member", why="; ".join(dup))
        elif other:
            rec.update(status="rejected", code=other[0][0], why="; ".join(t for _c, t in other))
        elif bad:
            codes = [code for code, _t in bad]
            rec.update(status="rejected",
                       code="bad-metadata" if "bad-metadata" in codes else codes[0],
                       why="; ".join(text for _c, text in bad))
        else:
            rec.update(status="rejected", code="no-raid-metadata",
                       why="no md superblock or LVM2 label that checks out, on the whole "
                           "image or any partition its tables give")

    # What is still missing: the members no file given or used holds.
    have = [(sb, pv) for _o, _w, sb, pv, _s, _op in present_regions]
    for order, (rec, regions, _op) in enumerate(scanned):
        for index in used_regions.get(order, []):
            have.append((regions[index][1], regions[index][2]))
    amb_md = {}
    amb_lvm = {}
    for a in res.ambiguous:
        names = ", ".join(os.path.basename(f) for f in a["files"])
        if a["identity"]["kind"] == "md":
            amb_md.setdefault(a["identity"]["array_uuid"], []).append(
                f"role {a['identity']['role']} (in {names}, which differ)")
        else:
            amb_lvm.setdefault(a["identity"]["vg_uuid"], []).append(
                f"{a['identity'].get('pv_name') or a['identity']['pv_uuid']} (in {names}, "
                "which differ)")
    for uuid_, first in md_targets.items():
        sbs = [sb for sb, _pv in have if sb is not None and sb.uuid == uuid_]
        active = [sb for sb in sbs if sb.role is not None]
        fresh = max(active or sbs or [first], key=lambda s: s.events)
        roles = {sb.role for sb in sbs if isinstance(sb.role, int)}
        gone = [r for r in range(fresh.raid_disks) if r not in roles]
        ident = _md_identity(fresh, "")
        res.identities.append(ident)
        if gone:
            extra = amb_md.get(ident["array_uuid"])
            res.missing.append({"kind": "md", "array_uuid": ident["array_uuid"], "roles": gone,
                                "why": f"array {ident['array_uuid']}: role(s) "
                                       f"{', '.join(map(str, gone))} of {fresh.raid_disks} are in "
                                       "no file given or used"
                                       + (f"; ambiguous: {'; '.join(extra)}" if extra else "")})
    for vid, vg in vg_targets.items():
        ids = listed[vid]
        res.identities.append({"kind": "lvm", "vg_name": vg[0], "vg_uuid": vid, "seqno": vg[2],
                               "pvs": len(ids)})
        found_ids = {_lvm_id(pv.uuid) for _sb, pv in have if pv is not None}
        gone = [g for k, g in sorted(ids.items(), key=lambda kv: kv[1][0]) if k not in found_ids]
        if gone:
            extra = amb_lvm.get(vid)
            res.missing.append({"kind": "lvm", "vg_uuid": vid, "pvs": [list(g) for g in gone],
                                "why": f"volume group {vg[0]}: physical volume(s) "
                                       + ", ".join(f"{n} (id {i})" for n, i in gone)
                                       + " are in no file given or used"
                                       + (f"; ambiguous: {'; '.join(extra)}" if extra else "")})
    if start_pv_ids and not vg_targets:
        res.notes.append("the LVM2 physical volume(s) given carry no volume group metadata, "
                         "and no file here has metadata that lists them")
    return res


def _cli_find_members(paths, passwords, private_keys, say=print):
    """--find-members: the images given, then each file the search beside each
    of them added, named before anything is read; each is then read exactly as
    if it had been given."""
    images = list(paths)
    found = []
    for path in paths:
        res = raid_siblings(path, passwords, private_keys,
                            also_given=[other for other in images if other != path])
        found.append(res)
        for rec in res.added:
            ino = _sibling_inode(rec["path"])
            if not any(ino == _sibling_inode(other) for other in images):
                images.append(rec["path"])
    raid_siblings_report(found, say=say)
    return images


def raid_siblings_report(found, say=print):
    """Print what raid_siblings() found for each image, before the run reads them."""
    for res in found:
        say("=" * 78)
        say(f"RAID members beside {os.path.basename(res.start)}, by recorded identity "
            "(--find-members)")
        say("=" * 78)
        for ln in res.lines():
            say("  " + ln)
        say("")


def raid_unread(arr, images_given=None):    # pylint: disable=unused-argument
    """True when `arr` counts as not read for the exit status: it has every
    member it needs among the images given, and is still not read. An image
    that holds part of an array, given alone or beside unrelated images, is a
    member, and leaves the exit status as it was before this read RAID."""
    if arr.image is not None:
        return False
    return not getattr(arr, "incomplete", False)


def _raid_report_lines(arr, images_given, find_members=False):
    """The report lines for one array or spanned volume."""
    lines = arr.lines()
    # what would find the members not given; not offered once it has looked
    look = ("" if find_members else
            ", or add --find-members to look for them beside the "
            + ("image given" if images_given == 1 else "images given"))
    if arr.image is None and not raid_unread(arr, images_given):
        lines = [ln for ln in lines if not ln.startswith("  NOT READ: ")]
        if isinstance(arr, LvmSpanned):
            lines.append(f"  not read from the images given: its physical volume(s) "
                         f"{', '.join(arr.absent)} are not among them; give those images to "
                         f"read it ({arr.refused}){look}")
        else:
            # from where each member was found (raid_assemble), never from its name
            parts = [m.get("partition", False) for m in list(arr.members) + list(arr.left_out)]
            roles = ", ".join(map(str, arr.not_given))
            absent = (f"role(s) {roles} of {arr.sb.raid_disks} are in none of them"
                      if roles else "too few of its members are among them to read it")
            if images_given == 1 and any(parts):
                # its members are partitions of the one image given: the
                # roles not on it are on another disk
                why = (" (the members left out above say why the others on it cannot)"
                       if arr.left_out else "")
                lines.append(f"  not read: {len(arr.members)} of {arr.sb.raid_disks} members on "
                             "this image's partitions can be used, and "
                             + (f"role(s) {roles} are not on this image"
                                if roles else "too few of its members are on it to read it")
                             + f"{why}; give the image(s) that hold the others with it{look}")
            else:
                lines.append(f"  not read from the images given: {absent}; give the other "
                             f"member images with them to read the array{look}")
    if getattr(arr, "same_as", None):
        lines.append(f"  not read again: its data starts at the first byte of {arr.same_as}, "
                     "whose listing above shows the same bytes")
    elif arr.image is not None:
        lines.append(f"  read below as {arr.safe_name}")
    return lines


def raid_run(rs, images_given, run_main, say=print, find_members=False):
    """The command line's RAID step: the report, then `run_main(arr)` for each
    array or spanned volume that is read. Returns the labels that count as not
    read for the exit status (raid_unread). A fault in one array's report or
    read is said and never stops the others."""
    unread = []
    try:
        raid_report(rs, say=say, images_given=images_given, find_members=find_members)
    except Exception as exc:                           # pylint: disable=broad-except
        say(f"  the RAID report could not be printed ({type(exc).__name__}: {exc})")
    for arr in rs.arrays:
        try:
            if arr.image is None:
                if raid_unread(arr, images_given):
                    unread.append(arr.label)
                continue
            if getattr(arr, "same_as", None):
                continue
            run_main(arr)
        except Exception as exc:                       # pylint: disable=broad-except
            say("=" * 78)
            say(getattr(arr, "safe_name", "an array"))
            say(f"  REFUSED: {type(exc).__name__}: {exc}")
            say("=" * 78)
            unread.append(getattr(arr, "label", "an array"))
    return unread


def raid_report(rs, say=print, images_given=2, find_members=False):
    """Print what raid_assemble() found: each image's RAID members, each array
    or spanned volume with its members, what is missing or left out, and what
    is not read and why. Prints nothing when nothing was found. The heading
    counts as assembled only the arrays that are read."""
    if not (rs.arrays or rs.foreign or rs.members):
        return
    built = sum(1 for arr in rs.arrays if getattr(arr, "image", None) is not None)
    say("=" * 78)
    if built == len(rs.arrays):
        say(f"RAID: {len(rs.arrays)} array(s) or spanned volume(s) assembled from the images given")
    else:
        say(f"RAID: {len(rs.arrays)} array(s) or spanned volume(s) found in the images given, "
            f"{built} of them assembled")
    say("=" * 78)
    for lines in rs.members.values():
        for ln in lines:
            say(f"  member  {ln}")
    for arr in rs.arrays:
        say("")
        try:
            for ln in _raid_report_lines(arr, images_given, find_members):
                say("  " + ln)
        except Exception as exc:                       # pylint: disable=broad-except
            # one array's report never stops the others being reported or read
            say(f"  {getattr(arr, 'label', 'an array')}: its report could not be printed "
                f"({type(exc).__name__}: {exc})")
    for _label, ln in rs.foreign:
        say(f"  NOT READ: {ln}")
    say("")


def _raid_files_match(image, hashes, listing):
    """(files matched, files expected, listing agrees) for the one filesystem
    volumes() finds on `image`, against the source tree's sha256 and listing."""
    import hashlib
    vols = [v for v in volumes(image, image.size) if v.get("walker")]
    if len(vols) != 1:
        return 0, len(hashes), False
    w = vols[0]["walker"]
    have = {p: (node, size) for p, node, size, _m in collect(w, w.root) if size is not None}
    matched = 0
    for path, digest in hashes.items():
        got = have.get(path)
        if got is None:
            continue
        h = hashlib.sha256()
        for chunk in w.read_file(got[0], got[1]):
            h.update(chunk)
        matched += h.hexdigest() == digest
    files = {p: s for p, (_n, s) in have.items() if not p.startswith("lost+found/")}
    dirs = {p.rsplit("/", 1)[0] for p in files if "/" in p}
    dirs |= {d.rsplit("/", i)[0] for d in list(dirs) for i in range(1, d.count("/") + 1)}
    want_files = {p: s for p, (s, k) in listing.items() if k == "f"}
    want_dirs = {p for p, (_s, k) in listing.items() if k == "d"}
    return matched, len(hashes), files == want_files and dirs == want_dirs


def _raid_sha(image):
    import hashlib
    h = hashlib.sha256()
    off = 0
    while off < image.size:
        image.seek(off)
        got = image.read(min(1 << 20, image.size - off))
        if not got:
            return None, off               # a read that ends early is no digest of the array
        h.update(got)
        off += len(got)
    return h.hexdigest(), off


def _md_resum(blob, at):
    """`blob` (a member image, bytearray) with the 1.x superblock at `at` given
    a checksum again after a test changed it (calc_sb_1_csum)."""
    max_dev, = struct.unpack_from("<I", blob, at + 220)
    n = 256 + max_dev * 2
    struct.pack_into("<I", blob, at + 216, 0)
    total = sum(struct.unpack_from(f"<{n // 4}I", blob, at))
    if n % 4 == 2:
        total += struct.unpack_from("<H", blob, at + n - 2)[0]
    struct.pack_into("<I", blob, at + 216, ((total & 0xffffffff) + (total >> 32)) & 0xffffffff)
    return blob


def _raid_self_checks():
    """[(label, passed)] for the RAID reader, from the arrays mdadm, lvm2 and the
    kernel wrote (tools/make_raid_fixtures.sh) and what they reported about them
    while assembled (raid-fixtures.json). No fixture folder is one SKIP."""
    import gzip
    import io
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures", "raid")
    man = os.path.join(here, "raid-fixtures.json")
    if not os.path.isfile(man):
        return [("the RAID fixtures are not beside this script (tests/fixtures/raid), so the "
                 "RAID reader was not checked against them", None)]
    with open(man, encoding="utf-8") as fh:
        doc = json.load(fh)
    hashes, listing = collections.defaultdict(dict), collections.defaultdict(dict)
    with open(os.path.join(here, "raid-trees.sha256"), encoding="utf-8") as fh:
        for line in fh:
            digest, path = line.rstrip("\n").split("  ", 1)
            arr, rel = path.split("/", 1)
            hashes[arr][rel] = digest
    with open(os.path.join(here, "raid-trees.list"), encoding="utf-8") as fh:
        for line in fh:
            path, size, kind = line.rstrip("\n").split("\t")
            arr, rel = path.split("/", 1)
            listing[arr][rel] = (int(size), kind)
    cache = {}

    def blob(name):
        if name not in cache:
            with gzip.open(os.path.join(here, name), "rb") as gz:
                cache[name] = gz.read()
        return cache[name]

    def assemble(entry, skip=(), change=None):
        imgs = []
        for i, m in enumerate(entry["members"]):
            if not m["file"] or i in skip:
                continue
            data = blob(m["file"])
            if change is not None:
                data = change(i, bytearray(data))
            imgs.append((m["file"], io.BytesIO(bytes(data))))
        return raid_assemble(imgs)

    out = []
    md = {n: a for n, a in doc["arrays"].items() if a.get("kind") == "md" and not a.get("skipped")}
    lvm = {n: a for n, a in doc["arrays"].items() if a.get("kind") == "lvm" and not a.get("skipped")}

    # Every array mdadm built is assembled from its member images alone, and
    # read back to the bytes the kernel presented while it ran it.
    read_ok, file_ok, list_ok, role_ok, nfiles, bad = 0, 0, 0, 0, 0, []
    # The arrays md runs itself; the reshape is not known data (its bytes were
    # moving while they were hashed) and DDF is external metadata, not read.
    readable = [n for n, a in md.items()
                if not str(a["sysfs"].get("metadata_version", "")).startswith("external")
                and not any("Reshape pos'n" in (m.get("examine") or "") for m in a["members"])]
    for name in sorted(readable):
        entry = md[name]
        rs = assemble(entry)
        arr = rs.arrays[0] if len(rs.arrays) == 1 else None
        if arr is None or arr.image is None:
            bad.append(name)
            continue
        digest, n = _raid_sha(arr.image)
        if digest == entry["device_sha256"] and n == entry["device_size"] == arr.image.size:
            read_ok += 1
        else:
            bad.append(name)
        got, want, same = _raid_files_match(arr.image, hashes[name], listing[name])
        nfiles += want
        file_ok += got == want and want > 0
        list_ok += same
        # each kept member holds the role mdadm --examine gives it; a stale
        # member is left out as stale; a member created missing is missing
        # a member on a partition is named by its image and the partition
        roles = {m["image"]: m["role"] for m in arr.members}
        stale = {m["image"] for m in arr.left_out if m["why"].startswith("stale")}
        fine, held = True, set()
        for m in entry["members"]:
            # the stopped image's own examine, or (a member on a partition, which
            # mdadm examined through its partition device) the assembled one
            text = (m.get("examine") or "") + (m.get("examine_assembled") or "")
            if m["status"] in ("omitted", "journal"):
                continue
            if m["status"] == "stale":
                fine &= m["file"] in stale
                continue
            role = re.search(r"Device Role : Active device (\d+)", text)
            if role is None:
                this = re.search(r"^this\s+\d+\s+\d+\s+\d+\s+(\d+)", text, re.M)
                role = this
            fine &= role is not None and roles.get(m["file"]) == int(role.group(1))
            if role is not None:
                held.add(int(role.group(1)))
        # the roles no kept member holds are the missing ones (mdadm need not
        # leave missing the slot it was given "missing" in: md-r6-missing1's
        # last device was rebuilt into slot 1, leaving slot 4 missing)
        fine &= set(arr.missing) == set(range(arr.sb.raid_disks)) - held
        role_ok += fine
    out.append((f"each md array mdadm built reads back from its member images to the "
                f"bytes the kernel presented, by sha256 and size ({read_ok} of {len(readable)}"
                + (f"; not: {', '.join(bad)}" if bad else "") + ")",
                read_ok == len(readable) and len(readable) >= 45))
    out.append((f"every file in every md array's ext4 reads back to the sha256 of its source "
                f"({file_ok} of {len(readable)} arrays, {nfiles} files)", file_ok == len(readable)))
    out.append((f"each md array's listing is the source tree's ({list_ok} of {len(readable)})",
                list_ok == len(readable)))
    out.append((f"each member holds the role mdadm --examine gives it, stale members are left "
                f"out as stale and the roles no member holds are missing ({role_ok} of "
                f"{len(readable)} arrays)", role_ok == len(readable)))
    levels = collections.Counter(a["sysfs"].get("level") for n, a in md.items() if n in readable)
    out.append((f"the arrays read cover linear, RAID0, RAID1, RAID4, RAID5, RAID6 and RAID10 "
                f"({', '.join(f'{k} {v}' for k, v in sorted(levels.items()))}) and metadata "
                f"0.90, 1.0, 1.1 and 1.2",
                {"linear", "raid0", "raid1", "raid4", "raid5", "raid6", "raid10"} <= set(levels)
                and {a["sysfs"].get("metadata_version") for n, a in md.items() if n in readable}
                >= {"0.90", "1.0", "1.1", "1.2"}))

    # The control: the same comparison fails when one RAID5 layout is read as
    # another, so a passing hash is evidence of the layout, not of the code path.
    ls = md["md-r5-ls"]
    arr = assemble(ls).arrays[0]
    wrong = RaidGeometry(5, 4, arr.geom.chunk, 0, arr.geom.dev_bytes)
    wrong_img = RaidImage(RaidReader(wrong, {m["role"]: (m["fh"], m["base"] + m["data_offset"])
                                             for m in arr.members}).read, wrong.size, "control")
    wrong_digest, wrong_n = _raid_sha(wrong_img)
    out.append(("read as left-asymmetric, the left-symmetric RAID5 array reads in full and does "
                "not hash to what the kernel presented (the control)",
                wrong_digest is not None and wrong_n == wrong.size == ls["device_size"]
                and wrong_digest != ls["device_sha256"]))

    # Parity: each full array with redundancy, read with every member left out
    # in turn (and every pair for RAID6), still reads to the kernel's bytes,
    # rebuilt from the parity mdadm's own check found consistent.
    tried, ok = 0, 0
    for name in sorted(readable):
        entry = md[name]
        level = entry["sysfs"].get("level")
        if any(m["status"] != "kept" for m in entry["members"]) or level not in (
                "raid1", "raid4", "raid5", "raid6", "raid10"):
            continue
        n = len(entry["members"])
        sets = [(i,) for i in range(n)]
        if level == "raid6":
            sets += [(i, j) for i in range(n) for j in range(i + 1, n)]
        for skip in sets:
            rs = assemble(entry, skip=set(skip))
            arr = rs.arrays[0] if rs.arrays else None
            if arr is None or arr.image is None:
                if level == "raid10":
                    continue
                tried += 1
                continue
            tried += 1
            ok += _raid_sha(arr.image)[0] == entry["device_sha256"]
    out.append((f"with one member of each full RAID1/4/5/10 array left out, and one or two "
                f"of each RAID6, every array still reads to the kernel's bytes ({ok} of "
                f"{tried} member sets)", ok == tried and tried >= 150))

    # The md signature where each metadata version puts it, checked from the
    # raw bytes beside the reader: the positive control for a survey.
    seen, right = collections.Counter(), 0
    total = 0
    for name, entry in md.items():
        for m in entry["members"]:
            if not m["file"]:
                continue
            data = blob(m["file"])
            text = m.get("examine") or ""
            base, size = 0, len(data)
            if "Magic : a92b4efc" not in text:
                # a member on a partition, which mdadm examined through its
                # partition device: the partition's own offsets
                text = m.get("examine_assembled") or ""
                parts = table_regions(io.BytesIO(data))[0]
                gpt = [r for r in parts if r[0].startswith("GPT")]
                if not gpt:
                    continue
                base, size = gpt[0][1], gpt[0][2]
            ver = re.search(r"Version : (\S+)", text)
            ver = ver.group(1) if ver else ""
            if ver.startswith("0.90"):
                at = (size & ~(MD_RESERVED - 1)) - MD_RESERVED
                ver = "0.90"
            else:
                so = re.search(r"Super Offset : (\d+) sectors", text)
                if so is None:
                    continue
                at = int(so.group(1)) * SECTOR
            total += 1
            found = md_superblocks(io.BytesIO(data), base, size)
            if data[base + at:base + at + 4] == b"\xfc\x4e\x2b\xa9" and any(
                    s.at == at and s.version == ver for s in found):
                right += 1
                seen[ver] += 1
    out.append((f"the md signature is found where each metadata version puts it, as mdadm "
                f"--examine places it, on every member image ({right} of {total}: "
                + ", ".join(f"{k} {v}" for k, v in sorted(seen.items())) + ")",
                right == total and set(seen) == {"0.90", "1.0", "1.1", "1.2"}))

    # A reshape in progress is refused by name, never read.
    rs = assemble(md["md-r5-reshape"])
    arr = rs.arrays[0] if rs.arrays else None
    out.append(("an array stopped during a reshape is not read, and says a reshape is in "
                "progress", arr is not None and arr.image is None
                and "reshape is in progress" in (arr.refused or "")))

    # DDF members are named, not read; a member is identified as one.
    ddf = doc["arrays"].get("md-ddf")
    if ddf and not ddf.get("skipped"):
        rs = assemble(ddf)
        out.append(("the members of a DDF set are each named as DDF and not read",
                    not rs.arrays and len(rs.foreign) == 3
                    and all("DDF" in ln for _l, ln in rs.foreign)))
    member = blob(md["md-r5-ls"]["members"][0]["file"])
    mirror = blob(md["md-r1-090"]["members"][0]["file"])
    out.append(("an md member reads as one in identify_fs(), and a RAID1 member whose "
                "superblock is at its end still reads as the filesystem it starts with",
                identify_fs(io.BytesIO(member), 0, len(member))[0] == "linux md member"
                and (identify_fs(io.BytesIO(mirror), 0, len(mirror))[0] or "").startswith("ext")))

    # LVM RAID inside one image: volumes() reads each, as the kernel presented it.
    single = blob("lvm-raid-single-0.img.gz")
    vols = volumes(io.BytesIO(single), len(single))
    fh = lvm_image(io.BytesIO(single), len(single))
    got, files, total, good = 0, 0, 0, set()
    for v in vols:
        if not v["label"].startswith("LVM qpraid1/"):
            continue
        name = "lvm-raid-single-" + v["label"].split("/")[1]
        entry = lvm.get(name)
        if entry is None:
            continue
        total += 1
        sub = RaidImage(lambda o, n, b=v["base"]: (fh.seek(b + o), fh.read(n))[1], v["size"], name)
        same_bytes = _raid_sha(sub) == (entry["device_sha256"], entry["device_size"])
        got += same_bytes
        m, w, same = _raid_files_match(sub, hashes[name], listing[name])
        files += m == w and same
        if same_bytes and m == w and same:
            good.add(name)
    want = sum(1 for n in lvm if n.startswith("lvm-raid-single-"))
    out.append((f"each LVM RAID4/5/6/10 volume inside one image reads to the bytes the kernel "
                f"presented, and its files and listing to its source ({got} and {files} of "
                f"{want})", got == files == total == want and want >= 10))
    r10 = lvm.get("lvm-raid-single-r10")
    out.append(("the LVM RAID10 volume inside one image (raid10, two stripes, two copies, "
                "near) is read through its four image volumes to the kernel's bytes, its files "
                "and its listing", r10 is not None and "lvm-raid-single-r10" in good))

    # LVM RAID across five images: raid_assemble() reads each volume.
    multi = [(f"lvm-raid-multi-{i}", io.BytesIO(blob(f"lvm-raid-multi-{i}.img.gz"))) for i in range(5)]
    rs = raid_assemble(multi)
    got = files = 0
    for arr in rs.arrays:
        name = "lvm-raid-multi-" + arr.label.split("/")[1]
        entry = lvm.get(name)
        if entry is None or arr.image is None:
            continue
        got += _raid_sha(arr.image) == (entry["device_sha256"], entry["device_size"])
        m, w, same = _raid_files_match(arr.image, hashes[name], listing[name])
        files += m == w and same
    want = sum(1 for n in lvm if n.startswith("lvm-raid-multi-"))
    out.append((f"each LVM RAID5/6/10 volume across five member images reads to the kernel's "
                f"bytes, and its files and listing to its source ({got} and {files} of {want})",
                got == files == want == len(rs.arrays) and want >= 3))
    alone = volumes(io.BytesIO(blob("lvm-raid-multi-0.img.gz")))
    out.append(("one of those images read alone says its volumes are on physical volumes "
                "not in the image", any("not in this image" in (v.get("note") or "") for v in alone)))

    # main() reads an array as an image of its own, and extracts it under the
    # array's name.
    import contextlib
    arr = assemble(md["md-r6-missing2"]).arrays[0]
    zbuf = io.BytesIO()
    say = io.StringIO()
    with zipfile.ZipFile(zbuf, "w") as zout, contextlib.redirect_stdout(say):
        main(arr.safe_name, extract="(memory)", zf=zout, manifest=[], image=arr.image,
             name_prefix=arr.safe_name + "_", image_info={"raid": arr.describe()})
    with zipfile.ZipFile(io.BytesIO(zbuf.getvalue())) as zin:
        names = zin.namelist()
    out.append(("main() reads an assembled array given as an image, and extracts its files "
                "under the array's name",
                f"{arr.safe_name}_lba0" in say.getvalue()
                and any(n.startswith(arr.safe_name + "_lba0") and n.endswith("/hello.txt") for n in names)))

    return (out + _raid_hostile_checks(md, assemble, blob)
            + _raid_review_checks(md, lvm, blob) + _raid_review2_checks(md, lvm, blob)
            + _raid_review3_checks(md, lvm, blob, doc) + _raid_review4_checks(md, blob)
            + _raid_review5_checks(md, blob)
            + _raid_sibling_checks(md, lvm, blob) + _raid_foreign_checks(md, blob)
            + _lvm_same_name_checks(lvm, blob))


def _sibling_write(path, data):
    """Write `data` to `path`, leaving runs of zeros as holes where the
    filesystem keeps them, so the member images cost little disk."""
    step = 1 << 20
    zero = bytes(step)
    with open(path, "wb") as fh:
        for off in range(0, len(data), step):
            chunk = data[off:off + step]
            if chunk == zero[:len(chunk)]:
                fh.seek(off + len(chunk))
            else:
                fh.seek(off)
                fh.write(chunk)
        fh.truncate(len(data))


def _sibling_rm(top):
    """Remove a folder this self-test made, links unfollowed. (The CI build
    replaces shutil.rmtree with a no-op to keep its fixtures; these are not
    among them.)"""
    for root, dirs, files in os.walk(top, topdown=False):
        for name in files + [d for d in dirs if os.path.islink(os.path.join(root, d))]:
            try:
                os.remove(os.path.join(root, name))
            except OSError:
                pass
        for name in dirs:
            try:
                os.rmdir(os.path.join(root, name))
            except OSError:
                pass
    try:
        os.rmdir(top)
    except OSError:
        pass


def _md_resum090(blob, at):
    """`blob` with the 0.90 superblock at `at` given its checksum again
    (calc_sb_csum)."""
    words = list(struct.unpack_from("<1024I", blob, at))
    words[32 + 6] = 0
    total = sum(words)
    total = (total & 0xffffffff) + (total >> 32)
    struct.pack_into("<I", blob, at + (32 + 6) * 4, total & 0xffffffff)
    return blob


def _lvm_label_resum(blob, base, sector):
    """`blob` with the LVM2 label in `sector` of the region at `base` given its
    checksum again (calc_crc over the label from byte 20)."""
    at = base + sector * SECTOR
    struct.pack_into("<I", blob, at + 16, lvm_crc(bytes(blob[at + 20:at + SECTOR])))
    return blob


def _sibling_dispositions(res, top):
    """{path relative to the folder: "status:code"} for one raid_siblings() result."""
    return {os.path.relpath(c["path"], top): f"{c['status']}:{c['code']}" for c in res.checked}


def _raid_sibling_checks(md, lvm, blob):
    """The members of each md set and of the LVM RAID set across five images,
    put in a folder of their own with decoys beside them, are found from each
    member by recorded identity, and only they; each rule is shown to matter
    by turning it off (the control) and seeing the check fail."""
    import gzip
    import io
    import tempfile
    out = []
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    with gzip.open(os.path.join(here, "fat12-fixture.img.gz"), "rb") as gz:
        fs_image = gz.read()
    # A folder of its own inside the temporary one: the CI build replaces
    # mkdtemp with one shared folder whose top-level images it counts.
    parent = tempfile.mkdtemp(prefix="qnxprobe-siblings-")
    top = os.path.join(parent, "raid-siblings")
    os.makedirs(top, exist_ok=True)

    def examine(m):
        return (m.get("examine") or "") + (m.get("examine_assembled") or "")

    def mdadm_uuid(m):
        exp = m.get("examine_export") or m.get("examine_assembled_export") or {}
        return (exp.get("MD_UUID") or "").lower()

    def mdadm_role(m):
        text = examine(m)
        role = re.search(r"Device Role : Active device (\d+)", text)
        if role is None:
            role = re.search(r"^this\s+\d+\s+\d+\s+\d+\s+(\d+)", text, re.M)
        return int(role.group(1)) if role else None

    def mdadm_disks(entry):
        for m in entry["members"]:
            exp = m.get("examine_export") or m.get("examine_assembled_export") or {}
            if exp.get("MD_DEVICES"):
                return int(exp["MD_DEVICES"])
        return None

    made = {"symlink": True, "hardlink": True}

    def decoys(folder, other, corrupt, copy_of, link_to, extra=()):
        """Write the decoys beside the members; {relative name: expected disposition}."""
        exp = {}
        _sibling_write(os.path.join(folder, "decoy-other.img"), other[1])
        exp["decoy-other.img"] = other[0]
        _sibling_write(os.path.join(folder, "decoy-corrupt.img"), corrupt)
        exp["decoy-corrupt.img"] = "rejected:bad-metadata"
        for name, data, want in extra:
            _sibling_write(os.path.join(folder, name), data)
            exp[name] = want
        _sibling_write(os.path.join(folder, "fs.img"), fs_image)
        exp["fs.img"] = "rejected:no-raid-metadata"
        with open(os.path.join(folder, "notes.txt"), "w", encoding="utf-8") as fh:
            fh.write("case notes, not an image\n")
        exp["notes.txt"] = "skipped:too-small"
        try:
            os.symlink(link_to, os.path.join(folder, "link.img"))
            exp["link.img"] = "skipped:symlink"
        except (OSError, NotImplementedError, AttributeError):
            made["symlink"] = False
        os.makedirs(os.path.join(folder, "sub"))
        with open(os.path.join(folder, link_to), "rb") as fh:
            _sibling_write(os.path.join(folder, "sub", os.path.basename(link_to)), fh.read())
        exp["sub"] = "skipped:directory"
        try:
            os.link(os.path.join(folder, link_to), os.path.join(folder, "zz-hardlink.img"))
            exp["zz-hardlink.img"] = "skipped:same-file"
        except (OSError, NotImplementedError, AttributeError):
            made["hardlink"] = False
        with open(os.path.join(folder, copy_of), "rb") as fh:
            _sibling_write(os.path.join(folder, "zz-copy.img"), fh.read())
        exp["zz-copy.img"] = "rejected:duplicate-member"
        for name in ("zz-hole.001", "zz-hole.003"):          # a split set with a hole
            _sibling_write(os.path.join(folder, name), b"\1" * 4096)
            exp[name] = "rejected:unreadable"
        return exp

    def expect(member_files, start, base_exp, added):
        want = dict(base_exp)
        for f in member_files:
            if f != start:
                want[f] = "added:" + added
        return want

    def sb_place(data):
        """(byte offset of the md superblock the assembly uses, version) on a
        member image, the innermost region first, by the assembly's own reads."""
        fh = io.BytesIO(data)
        for _l, base, size in sorted(_raid_places(fh, len(data)), key=lambda r: r[2]):
            sb = md_member(fh, base, min(size, len(data) - base))
            if sb is not None:
                return base + sb.at, sb.version
        return None, None

    try:
        # --- every md set ----------------------------------------------------
        sets_ok = sets_n = starts = hash_ok = hash_n = alone_red = alone_n = 0
        uuid_ok = missing_ok = same_level = resum_red = resum_n = 0
        bad_sets, bad_hash = [], []
        readable = {n for n, a in md.items()
                    if not str(a["sysfs"].get("metadata_version", "")).startswith("external")
                    and not any("Reshape pos'n" in (m.get("examine") or "") for m in a["members"])}
        native = [n for n, a in sorted(md.items())
                  if not str(a["sysfs"].get("metadata_version", "")).startswith("external")]
        ctl_folder = ctl_exp = ctl_start = None
        for name in native:
            entry = md[name]
            members = [m for m in entry["members"] if m["file"]]
            folder = os.path.join(top, name)
            os.makedirs(folder)
            files = []
            for m in members:
                fname = m["file"][:-3]
                _sibling_write(os.path.join(folder, fname), blob(m["file"]))
                files.append(fname)
            level = entry["sysfs"].get("level")
            partners = [n for n in native if n != name and md[n]["sysfs"].get("level") == level]
            same_level += bool(partners)
            partner = md[(partners or [n for n in native if n != name])[0]]
            pdata = blob(next(m["file"] for m in partner["members"] if m["file"]))
            corrupt = bytearray(blob(members[0]["file"]))
            at, version = sb_place(bytes(corrupt))
            corrupt[at + 32] ^= 0xff
            extra = []
            if name == "md-r5-ls":
                # an older copy of member 2 (one event behind), named to be
                # looked at first: member 2 itself, the newer, is used
                older = bytearray(blob(members[2]["file"]))
                ev, = struct.unpack_from("<Q", older, 4096 + 200)
                struct.pack_into("<Q", older, 4096 + 200, ev - 1)
                extra = [("a-older-copy.img", bytes(_md_resum(older, 4096)),
                          "rejected:duplicate-member")]
            base_exp = decoys(folder, ("rejected:different-array", pdata), bytes(corrupt),
                              files[-1], files[1 % len(files)], extra=extra)
            sets_n += 1
            fine = True
            want_missing = sorted(set(range(mdadm_disks(entry) or 0))
                                  - {mdadm_role(m) for m in members})
            first = None
            for m, f in zip(members, files):
                starts += 1
                res = raid_siblings(os.path.join(folder, f))
                got = _sibling_dispositions(res, folder)
                # the member files mdadm puts in this array, by its own --examine
                same = [g for mm, g in zip(members, files) if mdadm_uuid(mm) == mdadm_uuid(m)]
                want = expect(same, f, base_exp, "md-array-uuid")
                ok = got == want
                ids = [i for c in res.added for i in c["identities"]]
                uuid_ok += ok and bool(ids) and all(i["array_uuid"] == mdadm_uuid(m) for i in ids)
                gone = [r for x in res.missing for r in x.get("roles", [])]
                missing_ok += ok and gone == want_missing
                fine &= ok
                if name == "md-r5-ls" and ctl_folder is None:
                    ctl_folder, ctl_exp, ctl_start = folder, want, os.path.join(folder, f)
                if f == files[0]:
                    first = res
            sets_ok += fine
            if not fine:
                bad_sets.append(name)
            # The decoy differs from member 0 only by its checksum: given its
            # checksum again it is a copy of member 0, and no longer rejected
            # as bad metadata (the control for the checksum rule).
            fixed = bytearray(corrupt)
            if version == "0.90":
                _md_resum090(fixed, at)
            else:
                _md_resum(fixed, at)
            _sibling_write(os.path.join(folder, "decoy-corrupt.img"), bytes(fixed))
            res = raid_siblings(os.path.join(folder, files[1 % len(files)]))
            resum_n += 1
            # (named before member 0, it is the copy used, and member 0 the
            # duplicate; either way it is a member again)
            # (the name byte changed differs from member 0, so as new as it,
            # the two are ambiguous; named before member 0 it may be used)
            resum_red += _sibling_dispositions(res, folder).get("decoy-corrupt.img") in (
                "rejected:duplicate-member", "added:md-array-uuid", "rejected:ambiguous-member")
            _sibling_write(os.path.join(folder, "decoy-corrupt.img"), bytes(corrupt))
            if name in readable:
                hash_n += 1
                with raid_open(first.paths() if first is not None else []) as rs:
                    arr = [a for a in rs.arrays if getattr(a, "sb", None) is not None
                           and a.sb.uuid_text() == mdadm_uuid(members[0])]
                    got = _raid_sha(arr[0].image) if len(arr) == 1 and arr[0].image is not None else None
                    good = got == (entry["device_sha256"], entry["device_size"])
                hash_ok += good
                if not good:
                    bad_hash.append(name)
                if level in ("linear", "raid0"):
                    # the control: the start alone does not read to those bytes
                    alone_n += 1
                    with raid_open([os.path.join(folder, files[0])]) as rs:
                        alone_red += all(a.image is None for a in rs.arrays)
            if folder != ctl_folder:
                _sibling_rm(folder)
        out.append((f"from each member of each md set ({starts} members of {sets_n} sets), the "
                    "other members in its folder are added and each decoy is not used, for the "
                    "reason it is there (a member of another array, a copy whose superblock "
                    "checksum fails, a filesystem image, a small text file, a symbolic link, a "
                    "subfolder holding a member, a hard link, a byte copy of a member, a split "
                    f"set with a hole) ({sets_ok} of {sets_n}"
                    + (f"; not: {', '.join(bad_sets)}" if bad_sets else "") + ")",
                    sets_ok == sets_n and sets_n >= 49))
        out.append((f"every member added holds the array uuid mdadm --examine gives the start "
                    f"({uuid_ok} of {starts} starts)", uuid_ok == starts))
        out.append((f"the roles reported missing are those no member file holds by mdadm "
                    f"--examine ({missing_ok} of {starts} starts)", missing_ok == starts))
        out.append((f"the decoy from another array is of the same level wherever the fixtures "
                    f"hold one ({same_level} of {sets_n} sets)", same_level >= sets_n - 3))
        out.append((f"each md array read from the members found reads to the bytes the kernel "
                    f"presented, by sha256 and size ({hash_ok} of {hash_n}"
                    + (f"; not: {', '.join(bad_hash)}" if bad_hash else "") + ")",
                    hash_ok == hash_n and hash_n >= 45))
        out.append((f"the control: a linear or RAID0 member given alone is not read as its "
                    f"array ({alone_red} of {alone_n})", alone_red == alone_n and alone_n >= 5))
        out.append((f"the control for the checksum rule: each corrupted copy given its checksum "
                    f"again is no longer rejected as bad metadata but as a copy of a member "
                    f"({resum_red} of {resum_n})", resum_red == resum_n))

        # A DDF member names no md array: nothing is looked for.
        ddf = md.get("md-ddf")
        if ddf:
            folder = os.path.join(top, "md-ddf")
            os.makedirs(folder)
            ddf_files = []
            for m in ddf["members"]:
                if m["file"]:
                    _sibling_write(os.path.join(folder, m["file"][:-3]), blob(m["file"]))
                    ddf_files.append(m["file"][:-3])
            res = raid_siblings(os.path.join(folder, ddf_files[0]))
            out.append(("a DDF member names no array this reads: nothing is looked for or added, "
                        "and its DDF metadata is named",
                        not res.checked and not res.identities
                        and any("DDF" in n for n in res.notes)))
            _sibling_rm(folder)

        # --- the rules, each turned off: the comparison above fails ------------
        if ctl_folder is not None:
            red = {}
            for rule in ("identity", "symlink", "directory", "same_file", "duplicate", "size"):
                if (rule == "symlink" and not made["symlink"]) or \
                        (rule == "same_file" and not made["hardlink"]):
                    continue
                res = raid_siblings(ctl_start, _ignore=(rule,))
                red[rule] = _sibling_dispositions(res, ctl_folder) != ctl_exp
            res = raid_siblings(ctl_start)
            same = _sibling_dispositions(res, ctl_folder) == ctl_exp
            out.append(("the control: with each rule turned off in turn (array uuid, symbolic "
                        "link, subfolder, same file, a second copy of a member, size) the same "
                        f"comparison fails ({sum(red.values())} of {len(red)})"
                        + ("" if made["symlink"] and made["hardlink"] else
                           "; links not made on this platform"),
                        same and all(red.values()) and len(red) >= 4))
            # A cap and a read limit: files past them are named, never used.
            res = raid_siblings(ctl_start, max_candidates=2)
            codes = collections.Counter(c["code"] for c in res.checked)
            out.append(("past the number of files a search opens, the rest are named as not "
                        "opened, and the members among them are reported missing",
                        sum(1 for c in res.checked if c["status"] in ("added", "rejected")) == 2
                        and codes["over-limit"] >= 5
                        # the two opened, by name: the older copy of member 2 (the only
                        # file opened that holds member 2, so it is the one added) and
                        # the corrupted copy
                        and [os.path.basename(c["path"]) for c in res.added] == ["a-older-copy.img"]
                        and [r for x in res.missing for r in x.get("roles", [])] == [1, 3]))
            res = raid_siblings(ctl_start, read_budget=4096)
            opened = [c for c in res.checked if c["status"] in ("added", "rejected")]
            out.append(("with a read limit too small for any file, every file that opens is "
                        "rejected as over the limit (the split set with a hole does not open) "
                        "and none is added",
                        len(opened) >= 8 and not res.added and all(
                            c["code"] == ("unreadable" if os.path.basename(c["path"]).startswith(
                                "zz-hole.") else "over-budget") for c in opened)))

            # Members in other containers: a fixed VHD (read by the vendored
            # reader) and a split raw set, found and assembled from the others.
            ls = md["md-r5-ls"]
            folder = os.path.join(top, "containers")
            os.makedirs(folder)
            data = [blob(m["file"]) for m in ls["members"]]
            _sibling_write(os.path.join(folder, "a-member0.img"), data[0])

            def vhd_footer(size):
                f = bytearray(512)
                struct.pack_into(">8sIIQIIII", f, 0, b"conectix", 2, 0x00010000,
                                 0xFFFFFFFFFFFFFFFF, 0, 0, 0, 0)
                struct.pack_into(">QQHBBI", f, 40, size, size, 30, 4, 17, 2)
                f[68:84] = bytes(range(16))
                struct.pack_into(">I", f, 64, (~sum(f)) & 0xFFFFFFFF)
                return bytes(f)
            _sibling_write(os.path.join(folder, "b-member1.vhd"), data[1] + vhd_footer(len(data[1])))
            half = len(data[2]) // 2
            _sibling_write(os.path.join(folder, "c-member2.001"), data[2][:half])
            _sibling_write(os.path.join(folder, "c-member2.002"), data[2][half:])
            _sibling_write(os.path.join(folder, "d-member3.img"), data[3])
            res = raid_siblings(os.path.join(folder, "a-member0.img"))
            got = _sibling_dispositions(res, folder)
            split = next((c for c in res.added if c["path"].endswith("c-member2.001")), None)
            if ewfprobe is None:
                out.append(("members in a VHD and a split raw set are found (needs the vendored "
                            "ewfprobe for the VHD)", None))
            else:
                ok = (got == {"b-member1.vhd": "added:md-array-uuid",
                              "c-member2.001": "added:md-array-uuid",
                              "c-member2.002": "part-of:segment",
                              "d-member3.img": "added:md-array-uuid"}
                      and split is not None and len(split["files"]) == 2)
                with raid_open(res.paths()) as rs:
                    arr = [a for a in rs.arrays if a.image is not None]
                    ok &= len(arr) == 1 and _raid_sha(arr[0].image) == (ls["device_sha256"],
                                                                         ls["device_size"])
                res2 = raid_siblings(os.path.join(folder, "c-member2.002"))
                ok &= (len(res2.given) == 2 and _sibling_dispositions(res2, folder) == {
                    "a-member0.img": "added:md-array-uuid", "b-member1.vhd": "added:md-array-uuid",
                    "d-member3.img": "added:md-array-uuid"})
                out.append(("members in a fixed VHD and in a split raw set are found, the split "
                            "set's second segment is named as part of it, the array read from "
                            "them reads to the kernel's bytes, and a search from that second "
                            "segment reads the whole set as the image given", ok))
            _sibling_rm(folder)
            _sibling_rm(ctl_folder)

        # --- the LVM RAID set across five images ------------------------------
        folder = os.path.join(top, "lvm-raid-multi")
        os.makedirs(folder)
        files = []
        for i in range(5):
            files.append(f"lvm-raid-multi-{i}.img")
            _sibling_write(os.path.join(folder, files[-1]), blob(f"lvm-raid-multi-{i}.img.gz"))
        one = bytearray(blob("lvm-raid-multi-1.img.gz"))
        pv = LvmPv(io.BytesIO(bytes(one)), 0)
        label_at = pv.label_sector * SECTOR
        offset_xl, = struct.unpack_from("<I", one, label_at + 20)
        corrupt = bytearray(one)
        corrupt[label_at + offset_xl] ^= 0x01          # the PV id, under the label checksum
        forged = bytearray(corrupt)
        _lvm_label_resum(forged, 0, pv.label_sector)   # a PV id its group does not list
        base_exp = decoys(folder, ("rejected:different-vg",
                                          blob("lvm-raid-single-0.img.gz")),
                          bytes(corrupt), files[4], files[1],
                          extra=[("decoy-forged.img", bytes(forged), "rejected:pv-not-listed"),
                                 # pv1 under the group's previous seqno, named to be looked
                                 # at first: the image with the newer metadata is used
                                 ("a-older-pv1.img", _lvm_text_change(
                                     bytes(one), lambda t: t.replace("seqno = 7", "seqno = 6", 1)),
                                  "rejected:duplicate-member")])
        ok_n = hash_ok = 0
        lvm_names = sorted(n for n in lvm if n.startswith("lvm-raid-multi-"))
        for f in files:
            res = raid_siblings(os.path.join(folder, f))
            want = expect(files, f, base_exp, "lvm-vg-pv")
            ok = (_sibling_dispositions(res, folder) == want and not res.missing
                  and all(i["vg_uuid"] == pv.vg[1].get("id") for c in res.added
                          for i in c["identities"]))
            ok_n += ok
            with raid_open(res.paths()) as rs:
                got = 0
                for arr in rs.arrays:
                    entry = lvm.get("lvm-raid-multi-" + arr.label.split("/")[1])
                    if entry is not None and arr.image is not None:
                        got += _raid_sha(arr.image) == (entry["device_sha256"], entry["device_size"])
                hash_ok += got == len(lvm_names) >= 3
        out.append((f"from each of the five LVM RAID member images, the other four are added "
                    f"by volume group id and a physical volume id its metadata lists, and each "
                    f"decoy is not used for the reason it is there (a physical volume of another "
                    f"group, a label whose checksum fails, a physical volume id the group does "
                    f"not list, and the others above) ({ok_n} of 5)", ok_n == 5))
        out.append((f"each LVM RAID volume read from the images found reads to the kernel's "
                    f"bytes ({hash_ok} of 5 starts, {len(lvm_names)} volumes each)", hash_ok == 5))
        start = os.path.join(folder, files[0])
        with raid_open([start]) as rs:
            alone = not any(a.image is not None for a in rs.arrays)
        want = expect(files, files[0], base_exp, "lvm-vg-pv")
        red = {}
        for rule in ("identity", "pv_listed", "duplicate"):
            res = raid_siblings(start, _ignore=(rule,))
            red[rule] = _sibling_dispositions(res, folder) != want
        fixed = bytearray(corrupt)
        _lvm_label_resum(fixed, 0, pv.label_sector)    # the label checks out again
        _sibling_write(os.path.join(folder, "decoy-corrupt.img"), bytes(fixed))
        res = raid_siblings(start)
        red["checksum"] = _sibling_dispositions(res, folder) != want
        out.append((f"the control: one LVM image alone reads no volume, and with the group id, "
                    f"the physical volume listing, the second-copy rule or the label checksum "
                    f"turned off the comparison fails ({sum(red.values())} of {len(red)})",
                    alone and all(red.values())))
    finally:
        _sibling_rm(top)
    out.append(("the member search checks leave no temporary folder behind, their own "
                "parent included", _selftest_parent_gone(parent, "qnxprobe-siblings-")
                and not os.path.exists(top)))
    return out + _raid_sibling_review_checks(md, blob)


def _selftest_parent_gone(parent, prefix):
    """Remove a temporary folder a self-check made with mkdtemp(prefix=...),
    once it is empty. A folder whose name does not start with that prefix is
    not one mkdtemp made for this check (the CI build replaces mkdtemp with
    one shared folder it keeps), and is left alone. True when nothing of this
    check's is left: the folder is gone, or was never this check's own."""
    if not os.path.basename(os.path.normpath(parent)).startswith(prefix):
        return True
    try:
        os.rmdir(parent)
    except OSError:
        pass
    return not os.path.exists(parent)


def _raid_sibling_review_checks(md, blob):
    """The cases an independent review of the sibling search raised: a file
    swapped for a pipe after it is listed, two copies of one member as new as
    each other, a newer copy of the member given, and an added file that also
    holds a member of another array."""
    import io
    import tempfile
    import threading
    out = []
    parent = tempfile.mkdtemp(prefix="qnxprobe-siblings-review-")
    top = os.path.join(parent, "raid-siblings-review")
    os.makedirs(top, exist_ok=True)

    def folder_of(name, files):
        d = os.path.join(top, name)
        os.makedirs(d)
        for fname, data in files:
            _sibling_write(os.path.join(d, fname), bytes(data))
        return d

    def disp(res, d):
        return _sibling_dispositions(res, d)

    ls = md["md-r5-ls"]
    ls_data = [blob(m["file"]) for m in ls["members"]]
    try:
        # --- a file swapped for a pipe after it is listed ---------------------
        if not hasattr(os, "mkfifo"):
            out.append(("a file swapped for a pipe after it is listed is not read and does not "
                        "hang the search (no pipes on this platform)", None))
        else:
            vhd = bytearray(ls_data[3]) + bytes(512)
            struct.pack_into(">8sIIQIIII", vhd, len(ls_data[3]), b"conectix", 2, 0x00010000,
                             0xFFFFFFFFFFFFFFFF, 0, 0, 0, 0)
            d = folder_of("swap", [("m0.img", ls_data[0]), ("m1.img", ls_data[1]),
                                   ("m2.img", ls_data[2]), ("x-swap.img", bytes(8192)),
                                   ("y-swap.vhd", vhd)])
            victims = {os.path.join(d, "x-swap.img"), os.path.join(d, "y-swap.vhd")}
            real_lstat = os.lstat

            def swapping_lstat(name, *a, **k):
                st = real_lstat(name, *a, **k)
                if name in victims:           # swapped right after it is looked at
                    victims.discard(name)
                    os.remove(name)
                    os.mkfifo(name)
                return st
            box = {}

            def run():
                box["res"] = raid_siblings(os.path.join(d, "m0.img"))
            os.lstat = swapping_lstat
            try:
                worker = threading.Thread(target=run, daemon=True)
                worker.start()
                worker.join(60)
            finally:
                os.lstat = real_lstat
            res = box.get("res")
            got = disp(res, d) if res is not None else {}
            out.append(("two files swapped for pipes after they are listed (one of them a VHD) "
                        "are opened without blocking, refused through their descriptors as not "
                        "regular files, and the search goes on",
                        not worker.is_alive() and got.get("x-swap.img") == "skipped:not-regular"
                        and got.get("y-swap.vhd") == "skipped:not-regular"
                        and [os.path.basename(c["path"]) for c in res.added] == ["m1.img", "m2.img"]))

        # --- two copies of one member, as new as each other --------------------
        e090 = md["md-r5ls-090"]
        d090 = [blob(m["file"]) for m in e090["members"]]
        changed = bytearray(d090[2])
        changed[1 << 20:(1 << 20) + 4096] = b"\x55" * 4096
        d = folder_of("tie090", [("m0.img", d090[0]), ("m1.img", d090[1]), ("m3.img", d090[3]),
                                 ("copyA-m2.img", d090[2]), ("copyB-m2.img", changed)])
        res = raid_siblings(os.path.join(d, "m0.img"))
        got = disp(res, d)
        with raid_open(res.paths()) as rs:
            arr = [a for a in rs.arrays if a.image is not None]
            digest = _raid_sha(arr[0].image) if len(arr) == 1 else None
        out.append(("two copies of a 0.90 member as new as each other with different bytes: "
                    "neither is used, both are named as ambiguous, the role is reported missing, "
                    "and the RAID5 array is rebuilt without it to the kernel's bytes",
                    got.get("copyA-m2.img") == got.get("copyB-m2.img") == "rejected:ambiguous-member"
                    and [r for x in res.missing for r in x.get("roles", [])] == [2]
                    and "ambiguous" in res.missing[0]["why"] and len(res.ambiguous) == 1
                    and digest == (e090["device_sha256"], e090["device_size"])))
        # the same from copyA: the image given is used, and the other copy is a warning
        res = raid_siblings(os.path.join(d, "copyA-m2.img"))
        out.append(("given one of those copies, it is used as given, and the other copy, as new "
                    "with different bytes, is named and raised as a warning",
                    disp(res, d).get("copyB-m2.img") == "rejected:duplicate-member"
                    and len(res.warnings) == 1 and "copyB-m2.img" in res.warnings[0]
                    and "different bytes" in res.warnings[0]))

        changed12 = bytearray(ls_data[2])
        changed12[(1 << 20) + 8192:(1 << 20) + 12288] = b"\xaa" * 4096
        d = folder_of("tie12", [("m0.img", ls_data[0]), ("m1.img", ls_data[1]),
                                ("m3.img", ls_data[3]), ("copyA-m2.img", ls_data[2]),
                                ("copyB-m2.img", ls_data[2]), ("copyC-m2.img", changed12)])
        res = raid_siblings(os.path.join(d, "m0.img"))
        amb = disp(res, d)
        os.remove(os.path.join(d, "copyC-m2.img"))
        res2 = raid_siblings(os.path.join(d, "m0.img"))
        same = disp(res2, d)
        with raid_open(res2.paths()) as rs:
            arr = [a for a in rs.arrays if a.image is not None]
            digest = _raid_sha(arr[0].image) if len(arr) == 1 else None
        out.append(("for metadata 1.2 too: three copies as new as each other, one with other "
                    "bytes, are all ambiguous; two byte-for-byte copies give one member, the "
                    "first looked at, the other named as its copy, and the array reads to the "
                    "kernel's bytes",
                    all(amb.get(f) == "rejected:ambiguous-member"
                        for f in ("copyA-m2.img", "copyB-m2.img", "copyC-m2.img"))
                    and same.get("copyA-m2.img") == "added:md-array-uuid"
                    and same.get("copyB-m2.img") == "rejected:duplicate-member"
                    and "byte-for-byte" in next(c["why"] for c in res2.checked
                                                if c["path"].endswith("copyB-m2.img"))
                    and digest == (ls["device_sha256"], ls["device_size"])))

        pvs = [blob(f"lvm-raid-multi-{i}.img.gz") for i in range(5)]
        pv1b = bytearray(pvs[1])
        pv1b[8 << 20:(8 << 20) + 4096] = b"\x33" * 4096
        d = folder_of("tielvm", [("pv0.img", pvs[0]), ("pv2.img", pvs[2]), ("pv3.img", pvs[3]),
                                 ("pv4.img", pvs[4]), ("copyA-pv1.img", pvs[1]),
                                 ("copyB-pv1.img", pv1b)])
        res = raid_siblings(os.path.join(d, "pv0.img"))
        got = disp(res, d)
        out.append(("two copies of an LVM2 physical volume with the same metadata seqno and "
                    "different bytes: neither is used, and the physical volume is reported "
                    "missing as ambiguous",
                    got.get("copyA-pv1.img") == got.get("copyB-pv1.img") == "rejected:ambiguous-member"
                    and len(res.missing) == 1 and res.missing[0]["pvs"][0][0] == "pv1"
                    and "ambiguous" in res.missing[0]["why"]))

        # --- a newer copy of the member given -------------------------------------
        older = bytearray(ls_data[2])
        ev, = struct.unpack_from("<Q", older, 4096 + 200)
        struct.pack_into("<Q", older, 4096 + 200, ev - 1)
        _md_resum(older, 4096)
        d = folder_of("newer", [("m0.img", ls_data[0]), ("m1.img", ls_data[1]),
                                ("m2.img", ls_data[2]), ("m3.img", ls_data[3]),
                                ("old-m2.img", older)])
        res = raid_siblings(os.path.join(d, "old-m2.img"))
        lines = res.lines()
        out.append(("given an older copy of a member while a newer one is beside it, the copy "
                    "given is used, never replaced, and the newer one is named in a warning "
                    "that says the copy given is stale",
                    disp(res, d).get("m2.img") == "rejected:duplicate-member"
                    and os.path.join(d, "m2.img") not in res.paths()
                    and len(res.warnings) == 1 and "m2.img" in res.warnings[0]
                    and "stale" in res.warnings[0]
                    and any(ln.startswith("WARNING") and "m2.img" in ln for ln in lines)))

        # --- an added file that also holds a member of another array ------------
        combo = bytearray(pvs[1])
        r110 = blob(md["md-r1-10"]["members"][0]["file"])
        old_at = ((len(r110) // SECTOR - 16) & ~7) * SECTOR
        new_at = ((len(combo) // SECTOR - 16) & ~7) * SECTOR
        sbb = bytearray(8192)
        sbb[:4096] = r110[old_at:old_at + 4096]
        struct.pack_into("<Q", sbb, 144, new_at // SECTOR)
        _md_resum(sbb, 0)
        combo[new_at:new_at + 4096] = sbb[:4096]
        other_uuid = md_member(io.BytesIO(bytes(combo)), 0, len(combo)).uuid_text()
        d = folder_of("combo", [("pv0.img", pvs[0]), ("pv2.img", pvs[2]), ("pv3.img", pvs[3]),
                                ("pv4.img", pvs[4]), ("combo-pv1.img", combo)])
        res = raid_siblings(os.path.join(d, "pv0.img"))
        rec = next((c for c in res.checked if c["path"].endswith("combo-pv1.img")), {})
        out.append(("an added file that also holds a member of another array says so, naming "
                    "that array as not searched for",
                    rec.get("status") == "added" and any(other_uuid in t for t in rec.get(
                        "not_searched") or ())
                    and any("not searched for" in ln and other_uuid in ln for ln in res.lines())))
    finally:
        _sibling_rm(top)
    out.append(("the sibling checks leave no temporary folder behind, their own parent "
                "included", _selftest_parent_gone(parent, "qnxprobe-siblings-review-")
                and not os.path.exists(top)))
    return out


def _imsm_test_tail(level, members=2, bad_sum=False, map_state=0):
    """1024 bytes ending a test disk: an IMSM anchor (one-sector metadata of
    two disks and one volume of `level`), then the last sector, laid out as
    mdadm-4.5 super-intel.c reads it (imsm_levels). Constructed: no fixture
    holds IMSM metadata."""
    mpb = bytearray(512)
    mpb[0:32] = (IMSM_SIGNATURE + b"1.0.00").ljust(32, b"\0")
    size = 0xD8 + 48 * 2 + 164 + 4 * (members - 1)
    struct.pack_into("<I", mpb, 0x24, size)
    mpb[0x38], mpb[0x39] = 2, 1
    dev = 0xD8 + 48 * 2
    mpb[dev:dev + 16] = b"Volume0".ljust(16, b"\0")
    mpb[dev + 112 + 15], mpb[dev + 112 + 16] = level, members
    mpb[dev + 112 + 14] = map_state
    words = struct.unpack_from(f"<{size // 4}I", mpb, 0)
    total = (sum(words) - words[8]) & 0xffffffff
    struct.pack_into("<I", mpb, 0x20, (total + (1 if bad_sum else 0)) & 0xffffffff)
    return bytes(mpb) + bytes(512)


def _ddf_test_edit(img, field=96, record=None, header=None):
    """`img` (bytearray, a DDF member) with the header the anchor names at
    `field` (96 primary, 104 secondary) passed through `header(bytearray)`
    and every virtual disk configuration record under it through
    `record(bytearray)`, each CRC made good as mdadm's calc_crc."""
    def resum(blob):
        struct.pack_into(">I", blob, 4, 0xffffffff)
        struct.pack_into(">I", blob, 4, (binascii.crc32(bytes(blob), 0xffffffff) ^ 0xffffffff)
                         & 0xffffffff)
        return blob
    lba, = struct.unpack_from(">Q", img, len(img) - 512 + field)
    at = lba * 512
    hdr = bytearray(img[at:at + 512])
    rec_len, = struct.unpack_from(">H", hdr, 134)
    off, length = struct.unpack_from(">II", hdr, 216)
    if record is not None:
        for r in range((lba + off) * 512, (lba + off + length) * 512, rec_len * 512):
            if img[r:r + 4] == b"\xee\xee\xee\xee":
                rec = bytearray(img[r:r + rec_len * 512])
                record(rec)
                img[r:r + rec_len * 512] = resum(rec)
    if header is not None:
        header(hdr)
        img[at:at + 512] = resum(hdr)
    return img


def _raid_foreign_checks(md, blob):
    """DDF and IMSM members, whose arrays this does not assemble (1.71): a
    member is walked only when its metadata, read and checked, records a
    mirror (RAID1); any other level, or metadata that cannot be read, leaves
    it named and not walked."""
    import contextlib
    import gzip
    import io
    import tempfile
    out = []
    ddf = md.get("md-ddf")
    if ddf:
        data = [blob(m["file"]) for m in ddf["members"] if m["file"]]
        kinds = [identify_fs(io.BytesIO(d), 0, len(d)) for d in data]
        vols = [volumes(io.BytesIO(d), len(d)) for d in data]
        one = [v[0] if len(v) == 1 else {} for v in vols]
        want = ddf.get("detail_export", {}).get("MD_LEVEL", "").upper()
        out.append((f"a DDF member whose metadata records {want} is not walked, even when it "
                    "starts with a filesystem: it is a raid member, and its note names the "
                    "level, says its array is not assembled, and names what it starts with",
                    want == "RAID5" and [k for k, _l in kinds] == ["raid member"] * 3
                    and all(v.get("walker") is None for v in one)
                    and all(want in (v.get("note") or "") and "not assembled" in v["note"]
                            for v in one)
                    and "it starts with ext4" in (one[1].get("note") or "")))
        levels = [ddf_levels(io.BytesIO(d), 0, len(d)) for d in data]
        spoiled = bytearray(data[0])
        anchor = len(spoiled) - 512
        lba, = struct.unpack_from(">Q", spoiled, anchor + 96)
        off, = struct.unpack_from(">I", spoiled, lba * 512 + 216)
        rec = (lba + off) * 512
        spoiled[rec + 67] ^= 0xff                       # prl, under the record's CRC
        out.append((f"the RAID level each DDF member's metadata records is read, and is the "
                    f"level mdadm reported for the array ({want}); a configuration record whose "
                    f"CRC fails is not used",
                    bool(want) and all(lv == [want] for lv in levels)
                    and ddf_levels(io.BytesIO(bytes(spoiled)), 0, len(spoiled)) == []))
        # The same member with its records changed to RAID1, CRCs made good: walked.
        def to_raid1(rec):
            rec[67] = 0x01
        mirror = _ddf_test_edit(_ddf_test_edit(bytearray(data[1]), 96, to_raid1), 104, to_raid1)
        mk, _ml = identify_fs(io.BytesIO(bytes(mirror)), 0, len(mirror))
        mv = volumes(io.BytesIO(bytes(mirror)), len(mirror))
        names = []
        if len(mv) == 1 and mv[0].get("walker") is not None:
            w = mv[0]["walker"]
            names = [n for n, _i in w.listdir(w.root)]
        out.append(("the same DDF member with its configuration records changed to RAID1 (CRC "
                    "made good) is walked as the filesystem it starts with, and its note says "
                    "its metadata records a mirror",
                    mk == "ext4" and "hello.txt" in names
                    and "RAID1 (a mirror)" in (mv[0].get("note") or "")))

        # mdadm's own DDF RAID10: RAID1 over two-disk sets, spanned (layout_md2ddf)
        def to_raid10(rec):
            rec[67], rec[69], rec[70], rec[71] = 0x01, 2, 0, 0x03
            struct.pack_into(">H", rec, 64, 2)
        r10 = _ddf_test_edit(_ddf_test_edit(bytearray(data[1]), 96, to_raid10), 104, to_raid10)
        rv = volumes(io.BytesIO(bytes(r10)), len(r10))
        out.append(("a DDF record of RAID1 over two spanned two-disk sets (how mdadm writes "
                    "RAID10) reads as RAID10 and is not walked",
                    ddf_levels(io.BytesIO(bytes(r10)), 0, len(r10)) == ["RAID10"]
                    and [x.get("kind") for x in rv] == ["raid member"]
                    and all(x.get("walker") is None for x in rv)
                    and "RAID10" in (rv[0].get("note") or "")))

        # A RAID1 whose virtual disk is degraded, or on which this disk failed:
        # not walked, and the state is named.
        def vd_state(img, value):
            for field in (96, 104):
                lba, = struct.unpack_from(">Q", img, len(img) - 512 + field)
                hdr = img[lba * 512:lba * 512 + 512]
                off, = struct.unpack_from(">I", hdr, 208)
                img[(lba + off) * 512 + 64 + 32] = value      # entry 0's state
            return img

        def pd_failed(img):
            for field in (96, 104):
                lba, = struct.unpack_from(">Q", img, len(img) - 512 + field)
                hdr = img[lba * 512:lba * 512 + 512]
                poff, = struct.unpack_from(">I", hdr, 200)
                doff, = struct.unpack_from(">I", hdr, 224)
                guid = bytes(img[(lba + doff) * 512 + 8:(lba + doff) * 512 + 32])
                start = (lba + poff) * 512
                for i in range(64):
                    e = start + 64 + 64 * i
                    if bytes(img[e:e + 24]) == guid:
                        struct.pack_into(">H", img, e + 30, 0x1 | 0x2)
            return img
        degraded = vd_state(bytearray(mirror), 0x1)
        failed = pd_failed(bytearray(mirror))
        dv = volumes(io.BytesIO(bytes(degraded)), len(degraded))
        fv = volumes(io.BytesIO(bytes(failed)), len(failed))
        out.append(("a DDF RAID1 member whose virtual disk is degraded, or which its own record "
                    "marks failed, is not walked, and its note names the state",
                    all(x.get("walker") is None for x in dv + fv)
                    and "virtual disk degraded" in (dv[0].get("note") or "")
                    and "this disk failed" in (fv[0].get("note") or "")))

        # The header mdadm uses: the secondary when its seq is newer and it is
        # not open (super-ddf.c 1079-1091).
        def newer(hdr):
            struct.pack_into(">I", hdr, 40, struct.unpack_from(">I", hdr, 40)[0] + 1)

        def opened(hdr):
            newer(hdr)
            hdr[48] = 1
        sec = _ddf_test_edit(bytearray(data[1]), 104, to_raid1, newer)
        sec_open = _ddf_test_edit(bytearray(data[1]), 104, to_raid1, opened)
        out.append(("the DDF header used is the one mdadm uses: a newer secondary that is not "
                    "open (its records say RAID1 here), and the primary when the newer "
                    "secondary is open",
                    ddf_levels(io.BytesIO(bytes(sec)), 0, len(sec)) == ["RAID1"]
                    and ddf_levels(io.BytesIO(bytes(sec_open)), 0, len(sec_open)) == ["RAID5"]))
    lin = md.get("md-linear")
    if lin:
        d0 = blob(lin["members"][0]["file"])
        v = volumes(io.BytesIO(d0), len(d0))
        out.append(("the first member of an md linear array is not walked alone: the array's "
                    "filesystem continues on the next member (linear_conf), as 1.70 has it",
                    [x.get("kind") for x in v] == ["linux md member"]
                    and all(x.get("walker") is None for x in v)))
    # IMSM on a partitioned disk, constructed (no fixture): RAID1, RAID0, and
    # RAID1 with a checksum that does not match.
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    with gzip.open(os.path.join(here, "fat12-fixture.img.gz"), "rb") as gz:
        fat = gz.read()
    disk = bytearray(1 << 20) + bytearray(fat) + bytearray(1 << 20)
    struct.pack_into("<BBBBBBBBII", disk, 446, 0, 0, 0, 0, 0x01, 0, 0, 0, 2048, len(fat) // 512)
    disk[510:512] = b"\x55\xaa"
    plain = bytes(disk)
    disks = {"plain": plain}
    for name, tail in (("raid1", _imsm_test_tail(1)), ("raid0", _imsm_test_tail(0)),
                       ("badsum", _imsm_test_tail(1, bad_sum=True))):
        disks[name] = plain[:-1024] + tail
    lv = {n: imsm_levels(io.BytesIO(d), 0, len(d)) for n, d in disks.items()}
    out.append(("the IMSM level is read from its metadata with its checksum: RAID1 and RAID0 "
                "volumes are named, and a checksum that does not match is said",
                lv["raid1"] == (["RAID1"], None) and lv["raid0"] == (["RAID0"], None)
                and lv["badsum"][0] is None and "checksum" in lv["badsum"][1]
                and lv["plain"][0] is None))
    rs = raid_assemble([("imsm-disk", io.BytesIO(disks["raid0"]))])
    rs2 = raid_assemble([("ddf-disk", io.BytesIO(blob(ddf["members"][0]["file"])))]) if ddf else None
    say_m, say_n = [], []
    raid_report(raid_assemble([("mirror-disk", io.BytesIO(disks["raid1"]))]), say=say_m.append)
    raid_report(raid_assemble([("raid0-disk", io.BytesIO(disks["raid0"]))]), say=say_n.append)
    out.append(("the RAID section names a walked IMSM RAID1 member as a member read on its own "
                "as a copy of the mirror, not as NOT READ; a RAID0 member stays NOT READ with "
                "its level",
                any("member  " in ln and "as a copy of the mirror" in ln for ln in say_m)
                and not any("NOT READ" in ln for ln in say_m)
                and any("NOT READ" in ln and "RAID0" in ln and "not walked" in ln for ln in say_n)))
    out.append(("an IMSM member is named with \"an\", a DDF member with \"a\"",
                any("an Intel IMSM (RST) RAID member" in ln for _l, ln in rs.foreign)
                and (rs2 is None or any("a DDF RAID member" in ln for _l, ln in rs2.foreign))))
    parent = tempfile.mkdtemp(prefix="qnxprobe-foreign-")
    top = os.path.join(parent, "raid-foreign")
    os.makedirs(top, exist_ok=True)
    reports = {}
    try:
        for name, data in disks.items():
            path = os.path.join(top, f"{name}-disk.raw")
            with open(path, "wb") as fh:
                fh.write(data)
            say = io.StringIO()
            with contextlib.redirect_stdout(say):
                main(path, do_list=True)
            reports[name] = say.getvalue()
    finally:
        _sibling_rm(top)
    v = {n: volumes(io.BytesIO(d), len(d)) for n, d in disks.items()}
    out.append(("a partitioned disk ending in IMSM metadata that records RAID1: its partition "
                "is walked, and the note and the report say the metadata records a mirror",
                len(v["raid1"]) == 1 and v["raid1"][0].get("walker") is not None
                and "RAID1 (a mirror)" in (v["raid1"][0].get("note") or "")
                and "  RAID     a member of an Intel IMSM (RST) RAID set" in reports["raid1"]
                and "CONTENTS" in reports["raid1"]))
    out.append(("one that records RAID0: its partition is a raid member, not walked, named with "
                "the level and what it starts with, and the report lists no contents",
                len(v["raid0"]) == 1 and v["raid0"][0].get("walker") is None
                and v["raid0"][0].get("kind") == "raid member"
                and "RAID0" in (v["raid0"][0].get("note") or "")
                and "it starts with fat12" in v["raid0"][0]["note"]
                and "->  raid member" in reports["raid0"] and "CONTENTS" not in reports["raid0"]))
    out.append(("one whose IMSM checksum does not match: not walked, and the note says the "
                "checksum does not match; the same disk without metadata is read with no note "
                "(the control)",
                len(v["badsum"]) == 1 and v["badsum"][0].get("walker") is None
                and "checksum does not match" in (v["badsum"][0].get("note") or "")
                and "CONTENTS" not in reports["badsum"]
                and len(v["plain"]) == 1 and v["plain"][0].get("walker") is not None
                and not v["plain"][0].get("note") and "IMSM" not in reports["plain"]
                and "CONTENTS" in reports["plain"]))
    deg = plain[:-1024] + _imsm_test_tail(1, map_state=2)
    dg = volumes(io.BytesIO(deg), len(deg))
    out.append(("a partitioned disk whose IMSM RAID1 map is degraded: not walked, and the note "
                "names the state",
                imsm_levels(io.BytesIO(deg), 0, len(deg)) == (["RAID1 (degraded)"], None)
                and len(dg) == 1 and dg[0].get("walker") is None
                and "RAID1 (degraded)" in (dg[0].get("note") or "")))
    # Nothing found on such a disk is walked: a whole-disk LVM physical
    # volume's logical volume included, in volumes() and in an extraction.
    with gzip.open(os.path.join(here, "lvm-wholedisk.img.gz"), "rb") as gz:
        pv = gz.read() + bytes(1 << 20)
    pv0 = pv[:-1024] + _imsm_test_tail(0)
    lv_plain = [x["label"] for x in volumes(io.BytesIO(pv), len(pv)) if x.get("walker")]
    lv_raid0 = [x["label"] for x in volumes(io.BytesIO(pv0), len(pv0)) if x.get("walker")]
    runs = {}
    for name, img in (("plain", pv), ("raid0", pv0)):
        zbuf = io.BytesIO()
        say = io.StringIO()
        with zipfile.ZipFile(zbuf, "w") as zout, contextlib.redirect_stdout(say):
            main(f"lvm-{name}", extract="(memory)", zf=zout, manifest=[],
                 image=io.BytesIO(img), do_list=True)
        with zipfile.ZipFile(io.BytesIO(zbuf.getvalue())) as zin:
            runs[name] = (zin.namelist(), say.getvalue())
    out.append(("on a whole-disk LVM physical volume ending in IMSM RAID0 metadata, the "
                "logical volume is not walked or extracted either (it is without the "
                "metadata, the control)",
                any(lab.startswith("LVM ") for lab in lv_plain) and not lv_raid0
                and runs["plain"][0] and "CONTENTS" in runs["plain"][1]
                and not runs["raid0"][0] and "CONTENTS" not in runs["raid0"][1]))
    # The disk's own end is read from the image itself, not through an opened
    # LUKS volume whose data covers it.
    if _BDE_AES is None:
        out.append(("a whole-disk LUKS volume opened on a disk ending in IMSM RAID0 metadata "
                    "is not walked (needs the pycryptodome package)", None))
    else:
        meta = json.load(open(os.path.join(here, "luks-fixtures.json"), encoding="utf-8"))
        with gzip.open(os.path.join(here, "luks2-pbkdf2.img.gz"), "rb") as gz:
            lk = gz.read() + bytes(1 << 20)
        lk0 = lk[:-1024] + _imsm_test_tail(0)
        walked = {}
        for name, img in (("plain", lk), ("raid0", lk0)):
            ufh, _found = unlock_luks(io.BytesIO(img), len(img), meta["passphrases"][:1])
            walked[name] = [x["label"] for x in volumes(ufh, len(img)) if x.get("walker")]
        out.append(("a whole-disk LUKS volume opened on a disk ending in IMSM RAID0 metadata "
                    "is not walked: the metadata is read from the image itself, not through "
                    "the decrypted view (without it, the volume is walked: the control)",
                    bool(walked["plain"]) and not walked["raid0"]))
    out.append(("the foreign RAID checks leave no temporary folder behind",
                _selftest_parent_gone(parent, "qnxprobe-foreign-") and not os.path.exists(top)))
    return out


def _lvm_same_name_checks(lvm, blob):
    """Two LVM volume groups with one name and different ids, given together
    across images (1.71): each is matched by its id and read on its own."""
    import io
    out = []
    names = sorted(n for n in lvm if n.startswith("lvm-raid-multi-"))
    imgs = [blob(f"lvm-raid-multi-{i}.img.gz") for i in range(5)]
    pv0 = _lvm_pv(io.BytesIO(imgs[0]), 0, None)
    vg = pv0.vg[1]
    ids = [vg["id"]] + [r["id"] for r in vg["physical_volumes"].values()]

    def flip(x):
        return ("B" if x[0] != "B" else "C") + x[1:]

    def text(t):
        for i in ids:
            t = t.replace(i, flip(i))
        return t

    def other_group(img):
        # the same disks under another volume group id and other physical
        # volume ids, every checksum made good (metadata text and label)
        out_ = bytearray(_lvm_text_change(img, text))
        pv = _lvm_pv(io.BytesIO(bytes(out_)), 0, None)
        at = pv.label_sector * SECTOR
        off, = struct.unpack_from("<I", out_, at + 20)
        out_[at + off:at + off + 32] = flip(out_[at + off:at + off + 32].decode()).encode()
        struct.pack_into("<I", out_, at + 16, lvm_crc(bytes(out_[at + 20:at + SECTOR])))
        return bytes(out_)
    other = [other_group(b) for b in imgs]
    both = [(f"a{i}", io.BytesIO(b)) for i, b in enumerate(imgs)] + \
           [(f"b{i}", io.BytesIO(b)) for i, b in enumerate(other)]
    rs = raid_assemble(both)
    labels = [a.label for a in rs.arrays]
    good = 0
    for arr in rs.arrays:
        entry = lvm.get("lvm-raid-multi-" + arr.label.split("/")[1])
        good += (entry is not None and arr.image is not None
                 and _raid_sha(arr.image) == (entry["device_sha256"], entry["device_size"]))
    out.append((f"two LVM volume groups named alike with different ids, given together across "
                f"ten images, are each read on their own, told apart by id in their labels, "
                f"and every volume reads to the kernel's bytes ({good} of {2 * len(names)})",
                len(labels) == len(set(labels)) == 2 * len(names) == good
                and sum(1 for lab in labels if "@" in lab.split("/")[0]) == len(labels)
                and any("same name" in ln for lines in rs.members.values() for ln in lines)))
    # One group whole and the other with two of its five images: the whole one
    # reads; the other is its own, and is not read from the first group's disks.
    rs2 = raid_assemble(both[:5] + both[5:7])
    a_ok = [a for a in rs2.arrays if a.label.split("/")[0].endswith(
        "@" + _lvm_id(vg["id"])[:6]) and a.image is not None]
    b_read = [a for a in rs2.arrays if not a.label.split("/")[0].endswith(
        "@" + _lvm_id(vg["id"])[:6]) and a.image is not None]
    out.append(("with one of the two groups whole and two images of the other, the whole one "
                "reads to the kernel's bytes and none of the other's volumes is read through "
                "the first group's disks",
                len(a_ok) == len(names) and not b_read
                and all(_raid_sha(a.image) == (lvm["lvm-raid-multi-" + a.label.split("/")[1]]
                                               ["device_sha256"],
                                               lvm["lvm-raid-multi-" + a.label.split("/")[1]]
                                               ["device_size"]) for a in a_ok)))
    return out


def _raid_hostile_checks(md, assemble, blob):
    """Member sets that are damaged, incomplete or changed after mdadm wrote
    them: each is read or refused as the kernel's own rules say, and a refusal
    names its reason."""
    import io
    out = []
    ls = md["md-r5-ls"]
    at12 = 4096

    def one(rs):
        return rs.arrays[0] if len(rs.arrays) == 1 else None

    def flip(target):
        def change(i, b):
            if i == target:
                b[at12 + 100] ^= 0x40
            return b
        return change
    arr = one(assemble(ls, change=flip(2)))
    out.append(("a member whose superblock fails its checksum is not a member, and the "
                "array is read with that member rebuilt",
                arr is not None and 2 in arr.missing and arr.image is not None
                and _raid_sha(arr.image)[0] == ls["device_sha256"]))

    def dirty(_i, b):
        struct.pack_into("<Q", b, at12 + 208, 0)
        return _md_resum(b, at12)
    arr = one(assemble(ls, skip={1}, change=dirty))
    full = one(assemble(ls, change=dirty))
    out.append(("a degraded RAID5 array not stopped clean is refused, since its parity may "
                "not match; with every member it is read and says it was not stopped clean",
                arr is not None and arr.image is None and "not stopped clean" in (arr.refused or "")
                and full is not None and full.image is not None
                and any("not stopped clean" in n for n in full.notes)))

    arr = one(assemble(ls, skip={0, 2}))
    r0 = one(assemble(md["md-r0"], skip={1}))
    n2 = one(assemble(md["md-r10n2"], skip={0, 1}))
    out.append(("too many members missing is refused with the count: two of a RAID5, one of "
                "a RAID0, and both copies of a RAID10 near=2 chunk",
                arr is not None and "2 of 4 members missing" in (arr.refused or "")
                and r0 is not None and "1 of 3 members missing" in (r0.refused or "")
                and n2 is not None and "every copy" in (n2.refused or "")))

    jr = md["md-r5-journal"]
    arr = one(assemble(jr, skip={3}))
    out.append(("an array with a write journal is refused when the journal device is not "
                "given", arr is not None and arr.image is None
                and "no usable journal device" in (arr.refused or "")))

    def write_back(i, b):
        # the logged stripe's parity payload made a data payload: a stripe whose
        # data is held only in the journal (r5l_recovery_load_data)
        if i != 3:
            return b
        jsb = md_member(io.BytesIO(bytes(b)), 0, len(b))
        pos = jsb.data_offset + (jsb.journal_tail or 0) * SECTOR
        meta_size, = struct.unpack_from("<I", b, pos + 12)
        off = pos + 32
        while off < pos + meta_size:
            ptype, _f, psize = struct.unpack_from("<HHI", b, off)
            if ptype == 1:
                struct.pack_into("<H", b, off, 0)
            off += 8 + psize if ptype == 2 else 16 + 4 * (psize >> 3)
        struct.pack_into("<I", b, pos + 4, 0)
        seed = xfs_crc32c(jsb.uuid, 0xFFFFFFFF)
        struct.pack_into("<I", b, pos + 4, xfs_crc32c(bytes(b[pos:pos + 4096]), seed))
        return b
    arr = one(assemble(jr, change=write_back))
    out.append(("a write journal holding a stripe's data with no parity after it (a write "
                "only in the journal) is refused by name",
                arr is not None and arr.image is None and "not yet written" in (arr.refused or "")))

    def behind(target, by):
        def change(i, b):
            if i == target:
                ev, = struct.unpack_from("<Q", b, at12 + 200)
                struct.pack_into("<Q", b, at12 + 200, ev - by)
                _md_resum(b, at12)
            return b
        return change
    one_b = one(assemble(ls, change=behind(1, 1)))
    two_b = one(assemble(ls, change=behind(1, 2)))
    out.append(("a member one event behind is read, its role taken from the freshest "
                "superblock; two behind it is left out as stale and the array rebuilt",
                one_b is not None and one_b.image is not None and not one_b.missing
                and any("one event behind" in m.get("note", "") for m in one_b.members)
                and two_b is not None and 1 in two_b.missing
                and any(m["why"].startswith("stale") for m in two_b.left_out)
                and _raid_sha(two_b.image)[0] == ls["device_sha256"]))

    def cut(i, b):
        return b[:2 << 20] if i == 3 else b
    arr = one(assemble(ls, change=cut))
    out.append(("a member image cut short is left out with how much of it is there, and "
                "the array rebuilt without it",
                arr is not None and 3 in arr.missing
                and any("cut short" in m["why"] for m in arr.left_out)
                and _raid_sha(arr.image)[0] == ls["device_sha256"]))

    twice = [(m["file"], io.BytesIO(blob(m["file"]))) for m in ls["members"]]
    twice.append(("again", io.BytesIO(blob(ls["members"][0]["file"]))))
    arr = one(raid_assemble(twice))
    out.append(("the same member given twice is used once and the second named",
                arr is not None and not arr.missing and arr.image is not None
                and any("again" in m["why"] for m in arr.left_out)))

    def big_endian(_i, b):
        at = (len(b) & ~(MD_RESERVED - 1)) - MD_RESERVED
        words = struct.unpack_from("<1024I", b, at)
        struct.pack_into(">1024I", b, at, *words)
        return b
    arr = one(assemble(md["md-r1-090"], change=big_endian))
    out.append(("a 0.90 superblock in big-endian byte order is named and not read",
                arr is not None and arr.image is None and "big-endian" in (arr.refused or "")))

    def far_sets(_i, b):
        lay, = struct.unpack_from("<I", b, at12 + 76)
        struct.pack_into("<I", b, at12 + 76, lay | (1 << 17))
        return _md_resum(b, at12)
    arr = one(assemble(md["md-r10f2"], change=far_sets))
    out.append(("a RAID10 layout with far sets, which no fixture holds, is refused by name",
                arr is not None and arr.image is None and "far sets" in (arr.refused or "")))

    def no_layout(_i, b):
        fm, = struct.unpack_from("<I", b, at12 + 8)
        struct.pack_into("<I", b, at12 + 8, fm & ~4096)
        return _md_resum(b, at12)
    arr = one(assemble(md["md-r0-orig"], change=no_layout))
    out.append(("a RAID0 array of members of different sizes that records no layout is "
                "refused by name", arr is not None and arr.image is None
                and "records no layout" in (arr.refused or "")))

    def other_level(i, b):
        if i == 2:
            struct.pack_into("<i", b, at12 + 72, 1)
            _md_resum(b, at12)
        return b
    arr = one(assemble(ls, change=other_level))
    out.append(("a member whose superblock gives the array another level is left out, "
                "and the array rebuilt without it",
                arr is not None and 2 in arr.missing
                and any("different level" in m["why"] for m in arr.left_out)
                and _raid_sha(arr.image)[0] == ls["device_sha256"]))

    def clustered(_i, b):
        fm, = struct.unpack_from("<I", b, at12 + 8)
        struct.pack_into("<I", b, at12 + 8, fm | 256)
        return _md_resum(b, at12)
    arr = one(assemble(ls, change=clustered))
    out.append(("a clustered md array is refused by name",
                arr is not None and arr.image is None and "clustered" in (arr.refused or "")))

    imsm = bytearray(1 << 20)
    imsm[-1024:-1000] = b"Intel Raid ISM Cfg Sig. "
    rs = raid_assemble([("imsm", io.BytesIO(bytes(imsm)))])
    named = []
    for guid, kind in RAID_GPT_TYPES.items():
        disk = _gpt_test_image(SECTOR, bytes(64 << 10), 2048, "member", guid)
        got = raid_assemble([("gpt", io.BytesIO(bytes(disk)))])
        named.append(any(kind in ln for _l, ln in got.foreign))
    out.append(("an Intel IMSM anchor, and GPT partitions of Windows LDM, Storage Spaces and "
                "Apple RAID, are named and not read (constructed, no fixture holds them)",
                any("Intel IMSM" in ln for _l, ln in rs.foreign) and all(named)
                and not rs.arrays))
    plain = raid_assemble([("plain", io.BytesIO(bytes(4 << 20)))])
    out.append(("an image with no RAID member gives no array, member or name",
                not plain.arrays and not plain.members and not plain.foreign))
    return out


def _lvm_text_change(img, change):
    """`img` (a disk image, bytes) with the volume group text in every metadata
    area of every physical volume on it passed through `change(text)`, each
    copy's checksums made good again (raw_locn at 40, header CRC at 0)."""
    import io
    out = bytearray(img)
    fh = io.BytesIO(bytes(img))
    regions = [("whole", 0, len(img))] + [r[:3] for r in table_regions(fh)[0]]
    for _label, base, size in regions:
        pv = _lvm_pv(fh, base, size)
        if pv is None or not pv.vg:
            continue
        for moff, _n in pv.metadata_areas:
            at = base + moff
            h = bytearray(out[at:at + LVM_MDA_HEADER_SIZE])
            o, n, _c, f = struct.unpack_from("<QQII", h, 40)
            text = bytes(out[at + o:at + o + n]).split(b"\0", 1)[0].decode()
            new = change(text).encode() + b"\0"
            out[at + o:at + o + len(new)] = new
            struct.pack_into("<QQII", h, 40, o, len(new), lvm_crc(new), f)
            struct.pack_into("<I", h, 0, lvm_crc(bytes(h[4:])))
            out[at:at + LVM_MDA_HEADER_SIZE] = h
    return bytes(out)


def _lvm_extents(img, lvname):
    """[(image offset, length)] of logical volume `lvname`'s extents on the
    disk image `img`, from its volume group metadata, for a test to change."""
    import io
    fh = io.BytesIO(bytes(img))
    regions = [r[:3] for r in table_regions(fh)[0]]
    vg, bases = None, {}
    for _label, base, size in regions:
        pv = _lvm_pv(fh, base, size)
        if pv is not None and pv.vg:
            vg = pv.vg[1]
            bases[_lvm_id(pv.uuid)] = base
    ext = vg["extent_size"] * SECTOR
    pvs = {n: (bases[_lvm_id(r["id"])], r["pe_start"] * SECTOR)
           for n, r in vg["physical_volumes"].items()}
    out = []
    for k, seg in vg["logical_volumes"][lvname].items():
        if k.startswith("segment") and isinstance(seg, dict):
            stripes = seg["stripes"]
            for i in range(0, len(stripes), 2):
                base, pe_start = pvs[stripes[i]]
                out.append((base + pe_start + stripes[i + 1] * ext,
                            seg["extent_count"] // seg["stripe_count"] * ext))
    return out


def _lvm_spoil(img, lvname):
    """`img` with every byte of `lvname`'s extents overwritten, as a stale or
    failed image volume's would be wrong."""
    out = bytearray(img)
    for at, n in _lvm_extents(img, lvname):
        out[at:at + n] = b"\xaa" * n
    return bytes(out)


def _lvm_status_add(text, lv, flag):
    """`text` with `flag` added to the status list of logical volume `lv`."""
    head = re.search(r"\n(\s*)" + re.escape(lv) + r" \{\s*\n(?:.*\n)*?\s*status = \[", text)
    if head is None:
        raise ValueError(f"no status list for {lv}")
    return text[:head.end()] + f'"{flag}", ' + text[head.end():]


def _raid_review_checks(md, lvm, blob):
    """The cases an independent review found, each built from a fixture and
    checked against what the kernel or lvm2 would do with it."""
    import io
    out = []
    at12 = 4096

    def one(rs):
        return rs.arrays[0] if len(rs.arrays) == 1 else None

    def sets(name, change=None, skip=()):
        entry = md[name]
        bufs = [bytearray(blob(m["file"])) for m in entry["members"] if m["file"]]
        names = [m["file"] for m in entry["members"] if m["file"]]
        if change is not None:
            change(bufs)
        return [(n, io.BytesIO(bytes(b))) for i, (n, b) in enumerate(zip(names, bufs))
                if i not in skip]

    # A bad block log (md.c 1890-1920): the range it lists on a member is read
    # from the other copy or rebuilt from parity, never from that member.
    def bad_range(member, sector):
        def change(bufs):
            b = bufs[member]
            fm, = struct.unpack_from("<I", b, at12 + 8)
            bbo, = struct.unpack_from("<i", b, at12 + 188)
            do, = struct.unpack_from("<Q", b, at12 + 128)
            bad = do + sector
            entries = struct.pack("<Q", (bad << 10) | 8) + b"\xff" * 8
            b[at12 + bbo * SECTOR:at12 + bbo * SECTOR + len(entries)] = entries
            struct.pack_into("<I", b, at12 + 8, fm | 8)
            _md_resum(b, at12)
            b[bad * SECTOR:bad * SECTOR + 4096] = b"\xaa" * 4096    # what a failed write left
        return change
    r1 = one(raid_assemble(sets("md-r1", bad_range(0, 3000))))
    r5 = one(raid_assemble(sets("md-r5-ls", bad_range(1, 1000))))
    lin = one(raid_assemble(sets("md-linear", bad_range(0, 100))))
    out.append(("a range a member's bad block log lists is read from the other RAID1 copy, "
                "or rebuilt from RAID5 parity, never from that member, and the member and "
                "range are named; on a linear array, with no other copy, it is refused",
                r1 is not None and r1.image is not None
                and _raid_sha(r1.image)[0] == md["md-r1"]["device_sha256"]
                and any("bad block" in n for n in r1.notes)
                and r5 is not None and r5.image is not None
                and _raid_sha(r5.image)[0] == md["md-r5-ls"]["device_sha256"]
                and lin is not None and lin.image is None and "bad blocks" in (lin.refused or "")))

    # A 0.90 member one event behind that the freshest superblocks mark faulty
    # (md.c 2111-2133, the freshest table decides) is left out, so a chunk
    # written after it failed reads as written, rebuilt from parity.
    name = "md-r5ls-090"
    base = sets(name)
    arr0 = one(raid_assemble(base))
    g = arr0.geom
    off = next(o for o in range(0, g.size, g.chunk) if g.stripe(o)[0] == 3 and o > 1 << 20)
    _dd, pd, _qd, mo, _run, _ddf = g.stripe(off)

    def failed3(bufs):
        size = len(bufs[0])
        at = (size & ~(MD_RESERVED - 1)) - MD_RESERVED
        old = bytes(bufs[3][mo:mo + g.chunk])
        new = bytes(x ^ 0x5A for x in old)
        bufs[pd][mo:mo + g.chunk] = bytes(p ^ o ^ n for p, o, n in
                                          zip(bufs[pd][mo:mo + g.chunk], old, new))
        for i in (0, 1, 2):
            b = bufs[i]
            ev = struct.unpack_from("<I", b, at + 39 * 4)[0] | struct.unpack_from("<I", b, at + 40 * 4)[0] << 32
            ev += 1
            struct.pack_into("<II", b, at + 39 * 4, ev & 0xffffffff, ev >> 32)
            for k in range(27):
                slot = at + (128 + 32 * k) * 4
                _num, _maj, _mnr, rd, st = struct.unpack_from("<5I", b, slot)
                if rd == 3 and st & 6:
                    struct.pack_into("<I", b, slot + 16, 1)
            struct.pack_into("<I", b, at + 38 * 4, 0)
            w = struct.unpack_from("<1024I", b, at)
            t = sum(w)
            struct.pack_into("<I", b, at + 38 * 4, ((t & 0xffffffff) + (t >> 32)) & 0xffffffff)
        failed3.new = new[:16]
    arr = one(raid_assemble(sets(name, failed3)))
    arr.image.seek(off)
    out.append(("a 0.90 member one event behind, which the freshest superblocks mark faulty, "
                "is left out, and a chunk written on it after it failed reads as written "
                "(rebuilt from parity)",
                3 in arr.missing and arr.image.read(16) == failed3.new
                and any("no longer has it in sync" in m["why"] for m in arr.left_out)))

    # 0.90 members on MBR partitions that run to the end of their disks: the
    # member is the partition (innermost region), not the whole disk.
    def mbr(name):
        disks = []
        for m in md[name]["members"]:
            data = bytearray(2048 * SECTOR) + blob(m["file"])
            struct.pack_into("<B3sB3sII", data, 446, 0, b"\0\0\0", 0xfd, b"\0\0\0", 2048,
                             len(blob(m["file"])) // SECTOR)
            data[510:512] = b"\x55\xaa"
            disks.append((m["file"], io.BytesIO(bytes(data))))
        return one(raid_assemble(disks))
    ok = []
    for name in ("md-r1-090", "md-r5ls-090"):
        arr = mbr(name)
        ok.append(arr is not None and arr.image is not None
                  and all(m["base"] == 2048 * SECTOR for m in arr.members)
                  and _raid_sha(arr.image)[0] == md[name]["device_sha256"])
    out.append(("0.90 members on MBR partitions that end where their disks end are read "
                "from the partitions, a RAID1 and a RAID5 alike, to the kernel's bytes", all(ok)))

    # raid_disks past what the superblock can hold is refused before anything
    # is sized by it.
    def members_count(n):
        def change(bufs):
            for b in bufs:
                struct.pack_into("<I", b, at12 + 92, n)
                _md_resum(b, at12)
        return change
    t0 = time.time()
    big = one(raid_assemble(sets("md-r5-ls", members_count(4000000000))))
    took = time.time() - t0
    out.append(("an array whose superblock records more members than its role table holds is "
                "refused at once, named (4,000,000,000 members)",
                big is not None and big.image is None and "more than the" in (big.refused or "")
                and took < 10))

    # RAID10's missing-member check looks at n chunks, once each, not n chunks
    # times copies times a scan of the missing list. 950 of 1,900 members of a
    # near=2 array (every other one), each a copy of a fixture member's
    # superblock on an image of zeros: every chunk still has a copy.
    class Zeros:
        """An image of `size` bytes that holds `head` at its start and zeros after."""

        def __init__(self, head, size):
            self.head, self.size, self.pos = head, size, 0

        def seek(self, off, whence=0):
            self.pos = off if whence == 0 else self.pos + off if whence == 1 else self.size + off
            return self.pos

        def tell(self):
            return self.pos

        def read(self, n=-1):
            n = self.size - self.pos if n is None or n < 0 else min(n, self.size - self.pos)
            out = self.head[self.pos:self.pos + n]
            out += bytes(max(0, n - len(out)))
            self.pos += n
            return out
    tmpl = bytearray(blob(md["md-r10n2"]["members"][0]["file"])[:8192])
    struct.pack_into("<I", tmpl, at12 + 92, 1900)
    struct.pack_into("<I", tmpl, at12 + 220, 1920)
    struct.pack_into("<1900H", tmpl, at12 + 256, *range(1900))
    many = []
    for k in range(0, 1900, 2):
        b = bytearray(tmpl)
        struct.pack_into("<I", b, at12 + 160, k)
        _md_resum(b, at12)
        many.append((f"m{k}", Zeros(bytes(b), len(blob(md["md-r10n2"]["members"][0]["file"])))))
    looked = [0]
    real = RaidGeometry.copies10

    def counted(self, off):
        looked[0] += 1
        return real(self, off)
    RaidGeometry.copies10 = counted
    try:
        w10 = one(raid_assemble(many))
    finally:
        RaidGeometry.copies10 = real
    out.append((f"a RAID10 near=2 array of 1,900 members with every other one given is read, "
                f"its copies checked by looking at each of 1,900 chunks once ({looked[0]:,})",
                w10 is not None and w10.image is not None and len(w10.missing) == 950
                and looked[0] <= 1900))

    # A journal meta block whose payloads claim more than the block holds is
    # refused on that array alone; another array in the same run still reads.
    jr = md["md-r5-journal"]
    jidx = [m["file"] for m in jr["members"] if m["file"]].index("md-r5-journal-j.img.gz")

    def long_payload(bufs):
        b = bufs[jidx]
        jsb = md_member(io.BytesIO(bytes(b)), 0, len(b))
        pos = jsb.data_offset + (jsb.journal_tail or 0) * SECTOR
        struct.pack_into("<I", b, pos + 36, 8 * 5000)
        struct.pack_into("<I", b, pos + 4, 0)
        seed = xfs_crc32c(jsb.uuid, 0xFFFFFFFF)
        struct.pack_into("<I", b, pos + 4, xfs_crc32c(bytes(b[pos:pos + 4096]), seed))
    rs = raid_assemble(sets("md-r5-journal", long_payload) + sets("md-r1"))
    jarr = next((a for a in rs.arrays if a.sb.raid_disks == 3), None)
    r1arr = next((a for a in rs.arrays if a.sb.level == 1), None)
    out.append(("a journal meta block whose payloads run past it refuses that array by name, "
                "and an unrelated array in the same run still reads",
                jarr is not None and "run past the block" in (jarr.refused or "")
                and r1arr is not None and r1arr.image is not None
                and _raid_sha(r1arr.image)[0] == md["md-r1"]["device_sha256"]))

    # A stale journal device is left out (md.c 2082-2088), and so is a journal
    # device for an array without the journal feature (md.c 2146-2150).
    def stale_journal(bufs):
        b = bufs[jidx]
        ev, = struct.unpack_from("<Q", b, at12 + 200)
        struct.pack_into("<Q", b, at12 + 200, ev - 5)
        _md_resum(b, at12)

    def no_feature(bufs):
        # the journal device's own superblock without the journal feature
        # (md.c 2146: the device's own sb is what is tested)
        b = bufs[jidx]
        fm, = struct.unpack_from("<I", b, at12 + 8)
        struct.pack_into("<I", b, at12 + 8, fm & ~512)
        _md_resum(b, at12)
    st = one(raid_assemble(sets("md-r5-journal", stale_journal)))
    nf = one(raid_assemble(sets("md-r5-journal", no_feature)))
    out.append(("a journal device more than one event behind is left out as stale and the "
                "array refused for want of its journal; so is a journal device whose own "
                "superblock has no journal feature",
                st is not None and st.image is None
                and any(m["where"].startswith("md-r5-journal-j") and m["why"].startswith("stale")
                        for m in st.left_out)
                and nf is not None and nf.image is None
                and any("own superblock has no journal" in m["why"] for m in nf.left_out)))

    # The kernel's own refusals: a RAID5 chunk that is not a power of two, a
    # RAID10 layout of one copy, a 1.2 data offset inside the superblock, and a
    # member one event behind whose device number is past the freshest table.
    def chunk(bufs):
        for b in bufs:
            struct.pack_into("<I", b, at12 + 88, 96)
            _md_resum(b, at12)

    def one_copy(bufs):
        for b in bufs:
            struct.pack_into("<I", b, at12 + 76, 0x101)
            _md_resum(b, at12)

    def inside(bufs):
        struct.pack_into("<Q", bufs[0], at12 + 128, 8)
        _md_resum(bufs[0], at12)

    def far_number(bufs):
        # the freshest superblocks hold a 64-entry role table; the member one
        # event behind is device 100 in its own 128-entry one
        for i in (0, 1, 3):
            struct.pack_into("<I", bufs[i], at12 + 220, 64)
            _md_resum(bufs[i], at12)
        b = bufs[2]
        ev, = struct.unpack_from("<Q", b, at12 + 200)
        struct.pack_into("<Q", b, at12 + 200, ev - 1)
        struct.pack_into("<I", b, at12 + 160, 100)
        struct.pack_into("<H", b, at12 + 256 + 200, 2)
        _md_resum(b, at12)
    ch = one(raid_assemble(sets("md-r5-ls", chunk)))
    oc = one(raid_assemble(sets("md-r10n2", one_copy)))
    ins = raid_assemble(sets("md-r5-ls", inside))
    fn = one(raid_assemble(sets("md-r5-ls", far_number)))
    out.append(("the kernel's refusals hold: a RAID5 chunk that is not a power of two, a "
                "RAID10 layout of one copy, a 1.2 data offset inside its superblock (that "
                "member is not one), and a member one event behind whose device number is "
                "past the freshest superblock's table",
                ch is not None and ch.image is None and "power of two" in (ch.refused or "")
                and oc is not None and oc.image is None and "1 copies" in (oc.refused or "")
                and len(ins.arrays) == 1 and 0 in ins.arrays[0].missing
                and fn is not None and any("device number" in m["why"] for m in fn.left_out)))

    # The device uuid as mdadm --examine prints it (md_p.h: device_uuid at 168).
    member = md["md-r5-ls"]["members"][0]
    dev = md_member(io.BytesIO(blob(member["file"])), 0, len(blob(member["file"])))
    want = re.search(r"Device UUID : (\S+)", member.get("examine") or "")
    out.append(("a 1.x member's device uuid is read from where mdadm --examine finds it",
                want is not None and dev is not None
                and ":".join(dev.dev_uuid[i:i + 4].hex() for i in range(0, 16, 4)) == want.group(1)))

    # A degraded RAID1 not stopped clean says so.
    def unclean(bufs):
        for b in bufs:
            struct.pack_into("<Q", b, at12 + 208, 0)
            _md_resum(b, at12)
    dr1 = one(raid_assemble(sets("md-r1", unclean, skip={1})))
    out.append(("a degraded RAID1 not stopped clean is read and says it was not stopped clean",
                dr1 is not None and dr1.image is not None
                and any("not stopped clean" in n for n in dr1.notes)))

    # One image holding part of an array is a member, not a failure; a RAID1
    # member whose data starts at its first byte is not read twice.
    lone = one(raid_assemble(sets("md-r5-ls", skip={1, 2, 3})))
    say = []
    raid_report(raid_assemble(sets("md-r5-ls", skip={1, 2, 3})), say=say.append, images_given=1)
    r1090 = one(raid_assemble(sets("md-r1-090", skip={1})))
    say2 = []
    raid_report(raid_assemble(sets("md-r1-090", skip={1})), say=say2.append, images_given=1)
    whole = one(raid_assemble(sets("md-r5-reshape")))
    out.append(("one image holding one member of a RAID5 does not count as an array not read, "
                "and says to give the others; a whole array refused does; a lone RAID1 member "
                "whose data starts at its first byte is not read a second time",
                lone is not None and not raid_unread(lone, 1)
                and any("give the other member images" in s for s in say)
                and not any("NOT READ" in s for s in say)
                and whole is not None and raid_unread(whole, 4)
                and r1090 is not None and r1090.same_as is not None
                and any("not read again" in s for s in say2)))

    # 4Kn: the IMSM anchor two 4096-byte sectors from the end, DDF's in the last.
    imsm = bytearray(1 << 20)
    imsm[-8192:-8192 + 24] = b"Intel Raid ISM Cfg Sig. "
    ddf = bytearray(1 << 20)
    ddf[-4096:-4092] = b"\xde\x11\xde\x11"
    out.append(("on a 4096-byte-sector disk the IMSM and DDF anchors are found and named",
                raid_foreign(io.BytesIO(bytes(imsm)), 0, len(imsm)) == "Intel IMSM (RST)"
                and raid_foreign(io.BytesIO(bytes(ddf)), 0, len(ddf)) == "DDF"))

    # LVM: lvm2's own marks on an image volume or a physical volume, a
    # self-referencing raid segment, and a physical volume given twice.
    single = blob("lvm-raid-single-0.img.gz")

    def lvm_reads(img):
        vols = volumes(io.BytesIO(img), len(img))
        fh = lvm_image(io.BytesIO(img), len(img))
        got = {}
        for v in vols:
            if v["label"].startswith("LVM qpraid1/"):
                lv = v["label"].split("/")[1]
                sub = RaidImage(lambda o, n, b=v["base"]: (fh.seek(b + o), fh.read(n))[1], v["size"], lv)
                got[lv] = _raid_sha(sub) == (lvm["lvm-raid-single-" + lv]["device_sha256"],
                                             lvm["lvm-raid-single-" + lv]["device_size"])
        notes = " ".join(v.get("note") or "" for v in vols)
        return got, notes
    spoiled = _lvm_spoil(single, "r5ls_rimage_1")
    rb, _rb_notes = lvm_reads(_lvm_text_change(spoiled, lambda t: _lvm_status_add(t, "r5ls_rimage_1", "REBUILD")))
    out.append(("an LVM RAID5 image volume lvm2 marks REBUILD (its bytes spoiled here) is not "
                "read; its chunks are rebuilt from parity, and the volume reads to the kernel's "
                "bytes", rb.get("r5ls") is True and len(rb) == 10))

    # dm-raid's own superblock lists an image as failed (failed_devices, dm-raid.c 1962)
    def failed_bit(img):
        out_img = bytearray(img)
        for i in range(3):
            for at, _n in _lvm_extents(img, f"r5ls_rmeta_{i}"):
                if struct.unpack_from("<I", out_img, at)[0] == DM_RAID_MAGIC:
                    f, = struct.unpack_from("<Q", out_img, at + 24)
                    struct.pack_into("<Q", out_img, at + 24, f | 1 << 2)
        return bytes(out_img)
    fb, _fb_notes = lvm_reads(failed_bit(_lvm_spoil(single, "r5ls_rimage_2")))
    out.append(("an LVM RAID5 image volume dm-raid's superblock lists as failed (its bytes "
                "spoiled here) is rebuilt from parity, to the kernel's bytes",
                fb.get("r5ls") is True and len(fb) == 10))
    ns, ns_notes = lvm_reads(_lvm_text_change(single, lambda t: _lvm_status_add(
        _lvm_status_add(t, "r5ls_rimage_1", "REBUILD"), "r5ls", "NOTSYNCED")))
    out.append(("an LVM RAID5 volume lvm2 marks NOTSYNCED, with an image volume to rebuild, is "
                "refused by name",
                "r5ls" not in ns and "NOTSYNCED" in ns_notes and len(ns) == 9))

    def pv_missing(text):
        head = re.search(r"\n\s*pv1 \{\s*\n(?:.*\n)*?\s*status = \[", text)
        return text[:head.end()] + '"MISSING", ' + text[head.end():]
    # pv1's extents spoiled, its label and metadata kept (so it is the MISSING
    # mark, not the physical volume's absence, that is tested)
    # the image volumes on pv1 spoiled, their metadata volumes kept whole, so it
    # is the MISSING mark, not a missing dm-raid superblock, that is tested
    pv1 = single
    vgtext = None
    for _l, base, size in [r[:3] for r in table_regions(io.BytesIO(single))[0]]:
        pv = _lvm_pv(io.BytesIO(single), base, size)
        if pv is not None and pv.vg:
            vgtext = pv.vg[1]
    for lvname, lvrec in (vgtext or {}).get("logical_volumes", {}).items():
        if "_rimage_" in lvname and "pv1" in _lvm_seg_pvs(lvrec):
            pv1 = _lvm_spoil(pv1, lvname)
    pm, _pm_notes = lvm_reads(_lvm_text_change(pv1, pv_missing))
    out.append(("with a physical volume lvm2 marks MISSING, every RAID volume with an image "
                "volume on it is read from its other copies or rebuilt from parity, to the "
                "kernel's bytes", len(pm) == 10 and all(pm.values())))
    ref = _lvm_text_change(single, lambda t: t.replace('"r4_rimage_0"', '"r4"', 1))
    try:
        sr, sr_notes = lvm_reads(ref)
        selfref = "r4" not in sr and "nest more than four deep" in sr_notes and len(sr) == 9 \
            and all(sr.values())
    except RecursionError:
        selfref = False
    out.append(("a raid segment naming its own volume is refused by name and the group's other "
                "volumes still read", selfref))

    multi = [(f"lvm-raid-multi-{i}", blob(f"lvm-raid-multi-{i}.img.gz")) for i in range(5)]
    tot = good = 0
    for skip in range(5):
        rs = raid_assemble([(n, io.BytesIO(b)) for i, (n, b) in enumerate(multi) if i != skip])
        for a in rs.arrays:
            entry = lvm["lvm-raid-multi-" + a.label.split("/")[1]]
            tot += 1
            good += a.image is not None and _raid_sha(a.image) == (entry["device_sha256"],
                                                                    entry["device_size"])
    out.append((f"with any one of the five images not given, every LVM RAID volume across them "
                f"is still read to the kernel's bytes, from parity or the other copy ({good} of "
                f"{tot})", good == tot == 15))
    dup = raid_assemble([(n, io.BytesIO(b)) for n, b in multi] + [("copy", io.BytesIO(multi[0][1]))])
    out.append(("one of those images given twice is read once, and the second named",
                len(dup.arrays) == 3 and all(a.image is not None for a in dup.arrays)
                and any("the same LVM2 physical volume" in ln for ln in dup.members.get("copy", []))))
    return out


def _raid_review2_checks(md, lvm, blob):
    """The cases a second review found: bad block ranges nothing can supply,
    reads that fail, dm-raid recovery and events, LVM raid1 copies, the exit
    status, members on one image's partitions, the logical block size, a cut
    bad block log, and free space in rebuilt chunks."""
    import io
    import contextlib
    out = []
    at12 = 4096

    def one(rs):
        return rs.arrays[0] if len(rs.arrays) == 1 else None

    def setbad(b, entries, shift=0):
        fm, = struct.unpack_from("<I", b, at12 + 8)
        bbo, = struct.unpack_from("<i", b, at12 + 188)
        raw = b"".join(struct.pack("<Q", (s << 10) | c) for s, c in entries) + b"\xff" * 8
        b[at12 + bbo * SECTOR:at12 + bbo * SECTOR + len(raw)] = raw
        struct.pack_into("<B", b, at12 + 185, shift)
        struct.pack_into("<I", b, at12 + 8, fm | 8)
        _md_resum(b, at12)

    def spoil(b, s, c, shift=0):
        b[(s << shift) * SECTOR:((s + c) << shift) * SECTOR] = b"\xaa" * ((c << shift) * SECTOR)

    def run(name, plan, skip=()):
        files = [m["file"] for m in md[name]["members"] if m["file"]]
        bufs = [bytearray(blob(f)) for f in files]
        for i, ents, sh in plan:
            setbad(bufs[i], ents, sh)
            for s, c in ents:
                spoil(bufs[i], s, c, sh)
        arr = one(raid_assemble([(f, io.BytesIO(bytes(b))) for k, (f, b) in enumerate(zip(files, bufs))
                                 if k not in skip]))
        if arr is None or arr.image is None:
            return "refused", (arr.refused if arr is not None else "")
        return ("ok" if _raid_sha(arr.image)[0] == md[name]["device_sha256"] else "WRONG"), ""
    do = 2048
    readable = [run("md-r5-ls", [(1, [(do + 1030, 200)], 0)]),
                run("md-r5-ls", [(1, [(do - 16, 40)], 0)]),
                run("md-r5-ls", [(2, [((do + 2048) >> 3, 10)], 3)]),
                run("md-r5-ls", [(1, [(do + 1000, 8)], 0), (2, [(do + 3000, 8)], 0)]),
                run("md-r6-ls", [(1, [(do + 1000, 8)], 0), (2, [(do + 1000, 8)], 0)]),
                run("md-r10n2", [(0, [(do + 1000, 8)], 0)]),
                run("md-r10f2", [(0, [(do + 3000, 200)], 0)]),
                run("md-r1", [(0, [(do + 1000, 8)], 0), (1, [(do + 1008, 8)], 0)])]
    lost = [run("md-r5-ls", [(1, [(do + 1000, 8)], 0), (2, [(do + 1004, 8)], 0)]),
            run("md-r5-ls", [(1, [(do + 1000, 8)], 0)], skip={3}),
            run("md-r6-ls", [(1, [(do + 1000, 8)], 0), (2, [(do + 1000, 8)], 0)], skip={4}),
            run("md-r10n2", [(0, [(do + 1000, 8)], 0), (1, [(do + 1000, 8)], 0)]),
            run("md-r1", [(0, [(do + 1000, 8)], 0), (1, [(do + 1000, 8)], 0)])]
    out.append((f"bad block ranges another copy or parity can supply read to the kernel's bytes "
                f"({sum(r[0] == 'ok' for r in readable)} of {len(readable)}: across chunks, "
                "over the data offset, shifted, on two members apart, RAID6 two at once, RAID10 "
                "near and far, RAID1 side by side); ranges nothing can supply refuse the array "
                f"and name member and range ({sum(r[0] == 'refused' and 'bad block range' in r[1] for r in lost)} "
                f"of {len(lost)}: RAID5 two overlapping, RAID5 one with a member missing, RAID6 two "
                "with a member missing, RAID10 and RAID1 both copies)",
                all(r[0] == "ok" for r in readable)
                and all(r[0] == "refused" and "bad block range" in r[1] and "role" in r[1] for r in lost)))

    # A read that fails in the RAID read paths ends short, so extraction names
    # the file .SHORT: a RAID1 reader whose copies are both bad, built past the
    # refusal above, and an LVM RAID5 map with two image volumes gone.
    entry = md["md-r1"]
    arr = one(raid_assemble([(m["file"], io.BytesIO(blob(m["file"]))) for m in entry["members"]]))
    members = {m["role"]: (m["fh"], m["base"] + m["data_offset"]) for m in arr.members}
    arr.image.seek(0)
    hit = arr.image.read(arr.image.size).find(b"md-r1 block 00000100\n")   # inside blocks.bin
    both = {0: [(hit, hit + 4096)], 1: [(hit, hit + 4096)]}
    bad_img = RaidImage(RaidReader(arr.geom, members, both).read, arr.geom.size, "both bad")
    zbuf, said, man = io.BytesIO(), io.StringIO(), []
    with zipfile.ZipFile(zbuf, "w") as zout, contextlib.redirect_stdout(said):
        main("both_bad", extract="(memory)", zf=zout, manifest=man, image=bad_img)
    with zipfile.ZipFile(io.BytesIO(zbuf.getvalue())) as zin:
        names = zin.namelist()
    shorts = sum(int(v.get("short", 0) or 0) for v in man)
    single = blob("lvm-raid-single-0.img.gz")
    vols = volumes(io.BytesIO(single), len(single))
    fh = lvm_image(io.BytesIO(single), len(single))
    r5 = next(v for v in vols if v["label"] == "LVM qpraid1/r5ls")
    lmap = fh.lvm_map_for(r5["base"])
    broken = RaidLvMap(lmap.kind, lmap.geom, [lmap.images[0], None, None], lmap.size, "test")
    got = broken.read_via(fh, 0, lmap.size)
    out.append(("a RAID read that neither a copy nor parity can supply comes back short, so "
                "the file is named .SHORT and counted short, not filled with zeros; an LVM RAID "
                "read with too many image volumes gone comes back short too",
                any(".SHORT-" in n for n in names) and shorts >= 1
                and len(got) < lmap.size))

    # dm-raid: an image volume still being recovered, or whose superblock fell
    # behind, is read from parity, not as it is.
    def rmeta_set(img, lv, field, value):
        out_img = bytearray(img)
        for at, _n in _lvm_extents(img, lv):
            if struct.unpack_from("<I", out_img, at)[0] == DM_RAID_MAGIC:
                struct.pack_into("<Q", out_img, at + field, value)
        return bytes(out_img)

    def lvm_r5ls(img):
        vols2 = volumes(io.BytesIO(img), len(img))
        f2 = lvm_image(io.BytesIO(img), len(img))
        v = next((x for x in vols2 if x["label"] == "LVM qpraid1/r5ls"), None)
        if v is None:
            return False, vols2
        sub = RaidImage(lambda o, n, b=v["base"]: (f2.seek(b + o), f2.read(n))[1], v["size"], "r5ls")
        return _raid_sha(sub) == (lvm["lvm-raid-single-r5ls"]["device_sha256"],
                                  lvm["lvm-raid-single-r5ls"]["device_size"]), vols2
    spoiled = _lvm_spoil(single, "r5ls_rimage_1")
    rec_ok, _v = lvm_r5ls(rmeta_set(spoiled, "r5ls_rmeta_1", 32, 0))
    ev = None
    for at, _n in _lvm_extents(single, "r5ls_rmeta_0"):
        if struct.unpack_from("<I", single, at)[0] == DM_RAID_MAGIC:
            ev, = struct.unpack_from("<Q", single, at + 16)
    beh_ok, _v = lvm_r5ls(rmeta_set(spoiled, "r5ls_rmeta_1", 16, max(0, (ev or 2) - 2)))
    out.append(("an LVM RAID5 image volume whose dm-raid superblock says it is still being "
                "recovered, or is two events behind the freshest, is rebuilt from parity (its "
                "bytes spoiled here), to the kernel's bytes", rec_ok and beh_ok))

    # LVM raid1: a copy lvm2 marks REBUILD (spoiled here) is passed over for the
    # next; with every copy marked, the volume is refused.
    lf_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures",
                           "lvm-fixture.img.gz")
    if os.path.isfile(lf_path):
        import gzip
        with gzip.open(lf_path, "rb") as gz:
            lf = gz.read()

        def mirror(img):
            vols3 = volumes(io.BytesIO(img), len(img))
            f3 = lvm_image(io.BytesIO(img), len(img))
            v = next((x for x in vols3 if x["label"].endswith("/mirror")), None)
            if v is None:
                return None, " ".join(x.get("note") or "" for x in vols3)
            sub = RaidImage(lambda o, n, b=v["base"]: (f3.seek(b + o), f3.read(n))[1], v["size"], "m")
            return _raid_sha(sub)[0], ""
        before, _n = mirror(lf)
        first = _lvm_text_change(_lvm_spoil(lf, "mirror_rimage_0"),
                                 lambda t: _lvm_status_add(t, "mirror_rimage_0", "REBUILD"))
        after, _n = mirror(first)
        both_marked = _lvm_text_change(first, lambda t: _lvm_status_add(t, "mirror_rimage_1", "REBUILD"))
        none, notes = mirror(both_marked)
        out.append(("an LVM raid1 copy lvm2 marks REBUILD (spoiled here) is passed over and the "
                    "other copy read, to the same bytes; with both marked the volume is refused "
                    "by name", before is not None and after == before and none is None
                    and "marked REBUILD" in notes))
    else:
        out.append(("the LVM fixture is not beside this script, so the raid1 copy check did "
                    "not run", None))

    # Exit status: a member given alone, or beside an unrelated image, is a
    # member; a refused superblock with members missing is too; a complete set
    # still refused is not read.
    ls = md["md-r5-ls"]
    lone = one(raid_assemble([(ls["members"][0]["file"], io.BytesIO(blob(ls["members"][0]["file"]))),
                              ("other", io.BytesIO(bytes(1 << 20)))]))
    be = bytearray(blob(md["md-r5ls-090"]["members"][0]["file"]))     # one of four
    at90 = (len(be) & ~(MD_RESERVED - 1)) - MD_RESERVED
    words = struct.unpack_from("<1024I", be, at90)
    struct.pack_into(">1024I", be, at90, *words)
    be_lone = one(raid_assemble([("be", io.BytesIO(bytes(be)))]))
    whole = one(raid_assemble([(m["file"], io.BytesIO(blob(m["file"])))
                               for m in md["md-r5-reshape"]["members"] if m["file"]]))
    out.append(("one member beside an unrelated image, and a lone member whose superblock is "
                "refused, leave the exit status alone; a complete set still refused does not",
                lone is not None and not raid_unread(lone)
                and be_lone is not None and be_lone.image is None and not raid_unread(be_lone)
                and whole is not None and raid_unread(whole)))

    # Members on the partitions of one image: the report counts the ones on
    # its partitions that can be used, in its own wording for one image.
    disk = bytearray(1 << 20)
    parts = [blob(ls["members"][i]["file"]) for i in (0, 1)]
    for i, part in enumerate(parts):
        start = len(disk) // SECTOR
        struct.pack_into("<B3sB3sII", disk, 446 + 16 * i, 0, b"\0\0\0", 0xfd, b"\0\0\0",
                         start, len(part) // SECTOR)
        disk += part
    disk[510:512] = b"\x55\xaa"
    said2 = []
    rs = raid_assemble([("disk", io.BytesIO(bytes(disk)))])
    raid_report(rs, say=said2.append, images_given=1)
    out.append(("members that are partitions of the one image given are reported in the "
                "wording for one image, which says how many of them can be used",
                any("on this image's partitions" in s for s in said2)
                and not any("give the other member images" in s for s in said2)))

    # A 1.2 data offset just past a 512-byte superblock is inside a 4096-byte
    # logical block's (md.c 1872-1882 rounds to the device's block size).
    b = bytearray(blob(ls["members"][0]["file"]))
    struct.pack_into("<Q", b, at12 + 128, 9)
    _md_resum(b, at12)
    small = md_superblocks(io.BytesIO(bytes(b)), 0, len(b), 512)
    large = md_superblocks(io.BytesIO(bytes(b)), 0, len(b), 4096)
    out.append(("a 1.2 data offset one sector past the superblock is accepted with 512-byte "
                "logical blocks and refused with 4096-byte ones",
                any(s.version == "1.2" for s in small) and not any(s.version == "1.2" for s in large)))

    # A bad block log the image ends inside: the member is left out and says why.
    cut = bytearray(blob(ls["members"][0]["file"]))
    setbad(cut, [(2048 + 100, 8)])
    bbo, = struct.unpack_from("<i", cut, at12 + 188)
    cut = cut[:at12 + bbo * SECTOR + 1024]
    rs = raid_assemble([("cut", io.BytesIO(bytes(cut)))] +
                       [(m["file"], io.BytesIO(blob(m["file"]))) for m in ls["members"][1:]])
    arr = one(rs)
    out.append(("a member whose bad block log runs past the end of its image is left out and "
                "says so, never read with fewer entries",
                arr is not None and any("bad block log runs past" in m["why"] for m in arr.left_out)))

    # Free space of an LVM RAID volume with an image volume rebuilt: what lies
    # in rebuilt chunks is said and not written. One .bin is written, into a
    # folder of this check's own.
    import shutil
    import tempfile
    rb_img = _lvm_text_change(spoiled, lambda t: _lvm_status_add(t, "r5ls_rimage_1", "REBUILD"))
    vols4 = volumes(io.BytesIO(rb_img), len(rb_img))
    f4 = lvm_image(io.BytesIO(rb_img), len(rb_img))
    v = dict(next(x for x in vols4 if x["label"] == "LVM qpraid1/r5ls"))

    class Free:
        """A stand-in reader that reports the whole volume as free."""

        def __init__(self, base, size):
            self.base, self.size = base, size

        def free_extents(self):
            return [(self.base, self.size)]
    v["walker"] = Free(v["base"], v["size"])
    raid_parent = tempfile.mkdtemp(prefix="qnxprobe-raid-")
    top = os.path.join(raid_parent, "raid-unallocated")
    os.makedirs(top, exist_ok=True)
    said3 = []
    try:
        recs = write_unallocated(f4, f4.size, [v], top, "raid", say=said3.append)
    finally:
        shutil.rmtree(top, ignore_errors=True)
    # the folder mkdtemp made too (the CI build keeps its own shared one, and
    # replaces rmtree with a no-op, so there `top` stays and its parent with it)
    out.append(("the free-space check leaves no temporary folder behind, its parent included",
                _selftest_parent_gone(raid_parent, "qnxprobe-raid-")))
    out.append(("writing the free space of an LVM RAID volume with an image volume rebuilt "
                "says how much lies in rebuilt chunks, on no disk, and leaves it out",
                bool(recs) and recs[0].get("rebuilt_bytes_not_written", 0) > 0
                and any("rebuilt from parity, on no disk" in s for s in said3)))
    return out


def _raid_review3_checks(md, lvm, blob, doc):
    """The cases a third review found, and a sweep of the command line's RAID
    step over every subset of the member images of several sets."""
    import io
    import contextlib
    out = []
    at12 = 4096

    def one(rs):
        return rs.arrays[0] if len(rs.arrays) == 1 else None

    # The sweep: raid_run() with main() (the command line's own RAID step,
    # report included) over every non-empty subset of the images of one set
    # per level and of the five images of the volume group across images. What
    # should be read is worked out here from the level alone (and, for LVM,
    # from where lvs said each image volume was), not from the reader.
    def expect_md(level, n, have):
        lost = n - len(have)
        if level == "raid1":
            return bool(have)
        if level == "raid10":                          # near=2: members 0,1 and 2,3 hold copies
            return all(any(r in have for r in pair) for pair in ((0, 1), (2, 3)))
        return lost <= (2 if level == "raid6" else 1)
    loops = doc["lvm"]["lvm-raid-multi"]["loops"]
    pv_of = {}
    for seg in doc["lvm"]["lvm-raid-multi"]["report"]["segments"]["report"][0]["seg"]:
        name = seg["lv_name"].strip("[]")
        if "_rimage_" in name:
            pv_of[name] = loops.index(seg["seg_pe_ranges"].split(":")[0])

    def expect_lvm(lv, have):
        legs = sorted((k, pv) for k, pv in pv_of.items() if k.startswith(lv + "_rimage_"))
        gone = [i for i, (_k, pv) in enumerate(legs) if pv not in have]
        if lv == "r10":
            return all(any(r not in gone for r in pair) for pair in ((0, 1), (2, 3)))
        return len(gone) <= (2 if lv == "r6" else 1)

    def runner(ran):
        """main() as the command line calls it for an array, noting each one run."""
        def run_main(arr):
            main(arr.safe_name, image=arr.image, name_prefix=arr.safe_name + "_",
                 image_info={"raid": arr.describe()})
            ran.append(arr)
        return run_main

    def sweep(images, expect):
        """(subsets tried, subsets where all held) for `images` [(name, bytes)]."""
        tried = held = 0
        for k in range(1, len(images) + 1):
            for subset in itertools.combinations(range(len(images)), k):
                tried += 1
                rs = raid_assemble([(images[i][0], io.BytesIO(images[i][1])) for i in subset])
                said = io.StringIO()
                ran = []
                run_main = runner(ran)
                try:
                    with contextlib.redirect_stdout(said):
                        unread = raid_run(rs, len(subset), run_main, say=print)
                except Exception:                      # pylint: disable=broad-except
                    continue
                if "could not be printed" in said.getvalue() or "REFUSED:" in said.getvalue():
                    continue                           # a fault the safety net caught is still a fault
                want = expect(set(subset))
                got = {a.label.split("/")[-1] if a.label.startswith("LVM ") else "md": a for a in ran}
                ok = not unread and set(got) == {k for k, v in want.items() if v[0]}
                for key, arr in got.items():
                    ok &= _raid_sha(arr.image) == want[key][1]
                held += ok
        return tried, held
    results = []
    for name, level in (("md-r1", "raid1"), ("md-r5-ls", "raid5"), ("md-r6-ls", "raid6"),
                        ("md-r10n2", "raid10"), ("md-r5ls-090", "raid5")):
        entry = md[name]
        images = [(m["file"], blob(m["file"])) for m in entry["members"] if m["file"]]
        n = len(images)
        results.append(sweep(images, lambda have, e=entry, lv=level, n=n: {
            "md": (expect_md(lv, n, have), (e["device_sha256"], e["device_size"]))}))
    multi = [(f"lvm-raid-multi-{i}", blob(f"lvm-raid-multi-{i}.img.gz")) for i in range(5)]
    results.append(sweep(multi, lambda have: {
        lv: (len(have) > 1 and expect_lvm(lv, have),
             (lvm["lvm-raid-multi-" + lv]["device_sha256"], lvm["lvm-raid-multi-" + lv]["device_size"]))
        for lv in ("r5", "r6", "r10")}))
    tried = sum(t for t, _h in results)
    held = sum(h for _t, h in results)
    out.append((f"the command line's RAID step, report included, over every subset of the member "
                f"images of a RAID1, RAID5, RAID6, RAID10 and 0.90 RAID5 set and of the five "
                f"images of the volume group across images: nothing escapes, exactly the arrays "
                f"and volumes the subset can hold are read, each to the kernel's bytes, and none "
                f"counts against the exit status ({held} of {tried} subsets)",
                held == tried and tried == 3 + 15 + 31 + 15 + 15 + 31))

    # Exit status, decided by what was given: two stale members given with the
    # other two count; an LVM volume refused for its own metadata with every
    # image given counts; one refused for images not given does not.
    files = [m["file"] for m in md["md-r5-ls"]["members"]]
    bufs = [bytearray(blob(f)) for f in files]
    for i in (1, 2):
        ev, = struct.unpack_from("<Q", bufs[i], at12 + 200)
        struct.pack_into("<Q", bufs[i], at12 + 200, ev - 2)
        _md_resum(bufs[i], at12)
    stale = one(raid_assemble([(f, io.BytesIO(bytes(b))) for f, b in zip(files, bufs)]))
    marked = [(n, _lvm_text_change(b, lambda t: _lvm_status_add(
        _lvm_status_add(t, "r5_rimage_0", "REBUILD"), "r5_rimage_1", "REBUILD"))) for n, b in multi]
    rs_all = raid_assemble([(n, io.BytesIO(b)) for n, b in marked])
    rs_few = raid_assemble([(n, io.BytesIO(b)) for n, b in multi[2:]])
    r5_all = next((a for a in rs_all.arrays if a.label.endswith("/r5")), None)
    r5_few = next((a for a in rs_few.arrays if a.label.endswith("/r5")), None)
    out.append(("every member given, two of them stale, counts as an array not read and says "
                "they were given and left out; an LVM volume refused for its own marks with "
                "every image given counts, and one refused for images not given does not",
                stale is not None and raid_unread(stale) and "2 given and left out" in (stale.refused or "")
                and r5_all is not None and r5_all.image is None and raid_unread(r5_all)
                and r5_few is not None and r5_few.image is None and not raid_unread(r5_few)
                and r5_few.absent == ["pv0", "pv1"]))

    # A metadata volume with no dm-raid superblock is a new device to dm-raid:
    # its image volume is rebuilt, not read.
    single = blob("lvm-raid-single-0.img.gz")
    img = bytearray(_lvm_spoil(single, "r5ls_rimage_1"))
    for at, _n in _lvm_extents(single, "r5ls_rmeta_1"):
        if struct.unpack_from("<I", img, at)[0] == DM_RAID_MAGIC:
            struct.pack_into("<I", img, at, 0)
    vols = volumes(io.BytesIO(bytes(img)), len(img))
    fh = lvm_image(io.BytesIO(bytes(img)), len(img))
    v = next((x for x in vols if x["label"] == "LVM qpraid1/r5ls"), None)
    nomagic = v is not None and _raid_sha(RaidImage(
        lambda o, k, b=v["base"]: (fh.seek(b + o), fh.read(k))[1], v["size"], "r5ls")) == (
        lvm["lvm-raid-single-r5ls"]["device_sha256"], lvm["lvm-raid-single-r5ls"]["device_size"])
    out.append(("an LVM image volume whose metadata volume holds no dm-raid superblock (its bytes "
                "spoiled here) is rebuilt from parity, to the kernel's bytes", nomagic))

    # A member whose reads fail (a damaged container chunk) is read around,
    # from the other copy or parity, as md does; with nothing to read around
    # it the read ends short, and a short read is no digest.
    class Flaky(io.BytesIO):
        """A member image whose reads fail inside one byte range."""

        def __init__(self, data, lo, hi):
            super().__init__(data)
            self.lo, self.hi = lo, hi

        def read(self, n=-1):
            pos = self.tell()
            end = pos + (n if n is not None and n >= 0 else 1 << 62)
            if pos < self.hi and end > self.lo:
                raise OSError("simulated read error")
            return super().read(n)

    def flaky(name, which, lo, hi):
        imgs = [(m["file"], Flaky(blob(m["file"]), lo, hi) if i in which else io.BytesIO(blob(m["file"])))
                for i, m in enumerate(md[name]["members"]) if m["file"]]
        return one(raid_assemble(imgs))
    lo = (2048 << 9) + 300000
    r1 = flaky("md-r1", {0}, lo, lo + 10000)
    r5 = flaky("md-r5-ls", {1}, (2048 << 9) + 100000, (2048 << 9) + 110000)
    r1b = flaky("md-r1", {0, 1}, lo, lo + 10000)
    r1b.image.seek(0)
    part = r1b.image.read(r1b.image.size)
    out.append(("a member whose reads fail over a range is read around, from the other RAID1 "
                "copy or RAID5 parity, to the kernel's bytes; with both RAID1 copies failing the "
                "read ends short before the range and gives no digest",
                _raid_sha(r1.image)[0] == md["md-r1"]["device_sha256"]
                and _raid_sha(r5.image)[0] == md["md-r5-ls"]["device_sha256"]
                and 0 < len(part) <= 300000 and _raid_sha(r1b.image)[0] is None))
    return out


def _raid_review4_checks(md, blob):
    """The cases a fourth review found: a read-around on an array not stopped
    clean, the LVM exit rule by legs, and a member read retried once."""
    import io
    out = []
    at12 = 4096

    def one(rs):
        return rs.arrays[0] if len(rs.arrays) == 1 else None

    class Flaky(io.BytesIO):
        """A member image whose reads fail inside [lo, hi); with `every` 2, only
        every other read there fails (a read a retry would serve)."""

        def __init__(self, data, lo, hi, every=1):
            super().__init__(data)
            self.lo, self.hi, self.every, self.calls = lo, hi, every, 0

        def read(self, n=-1):
            pos = self.tell()
            end = pos + (n if n is not None and n >= 0 else 1 << 62)
            if pos < self.hi and end > self.lo:
                self.calls += 1
                if (self.calls - 1) % self.every == 0:    # the 1st, 3rd, ... read fails
                    raise OSError("simulated read error")
            return super().read(n)

    # RAID5 not stopped clean, a data chunk's parity out of step: when the data
    # member fails to read there, the read ends short rather than rebuild from
    # that parity. md reads an unclean mirror from its first readable copy and
    # moves to the next when that read fails (raid1-10.c 278-289, raid1.c
    # 589-612), and so does this.
    files = [m["file"] for m in md["md-r5-ls"]["members"]]
    bufs = [bytearray(blob(f)) for f in files]
    for b in bufs:
        struct.pack_into("<Q", b, at12 + 208, 0)
        _md_resum(b, at12)
    a0 = one(raid_assemble([(f, io.BytesIO(bytes(b))) for f, b in zip(files, bufs)]))
    off = 1 << 20
    dd, pd, _qd, mo, _run, _ddf = a0.geom.stripe(off)
    do = 2048 * SECTOR
    bufs[pd][do + mo:do + mo + 4096] = bytes(x ^ 0xFF for x in bufs[pd][do + mo:do + mo + 4096])
    arr = one(raid_assemble([(f, Flaky(bytes(b), do + mo, do + mo + 4096) if i == dd
                              else io.BytesIO(bytes(b))) for i, (f, b) in enumerate(zip(files, bufs))]))
    arr.image.seek(off)
    got = arr.image.read(16)
    r1files = [m["file"] for m in md["md-r1"]["members"]]
    r1bufs = [bytearray(blob(f)) for f in r1files]
    for b in r1bufs:
        struct.pack_into("<Q", b, at12 + 208, 0)
        _md_resum(b, at12)
    lo = do + 300000
    mirror = one(raid_assemble([(f, Flaky(bytes(b), lo, lo + 10000) if i == 0 else io.BytesIO(bytes(b)))
                                for i, (f, b) in enumerate(zip(r1files, r1bufs))]))
    out.append(("on a RAID5 array not stopped clean, a data member that fails to read is not "
                "rebuilt from parity that may be out of step: the read ends short there; an "
                "unclean RAID1 copy that fails is read from the next copy, as md does",
                got == b"" and _raid_sha(arr.image)[0] is None
                and _raid_sha(mirror.image)[0] == md["md-r1"]["device_sha256"]))

    # The LVM exit rule by legs: four of the five images given (pv0 not), r5's
    # leg on pv1 marked REBUILD. One leg absent is within raid5's tolerance, so
    # the volume counts as complete, and refused it counts as not read.
    multi = [(f"lvm-raid-multi-{i}", blob(f"lvm-raid-multi-{i}.img.gz")) for i in range(5)]
    marked = [(n, _lvm_text_change(b, lambda t: _lvm_status_add(t, "r5_rimage_1", "REBUILD")))
              for n, b in multi[1:]]
    rs = raid_assemble([(n, io.BytesIO(b)) for n, b in marked])
    r5 = next((a for a in rs.arrays if a.label.endswith("/r5")), None)
    out.append(("an LVM volume with one leg's image not given and another leg marked REBUILD "
                "has every leg it needs given, so refused it counts as not read",
                r5 is not None and r5.image is None and r5.absent == ["pv0"] and raid_unread(r5)))

    # A member read that fails once and serves on a second try (RAID0, so
    # nothing else could serve it) reads in full.
    files0 = [m["file"] for m in md["md-r0"]["members"]]
    once = one(raid_assemble([(f, Flaky(blob(f), do + 100000, do + 140000, every=2) if i == 1
                               else io.BytesIO(blob(f))) for i, f in enumerate(files0)]))
    import hashlib
    whole = b""
    if once is not None:
        once.image.seek(0)
        whole = once.image.read(once.image.size)          # one read, not resumed after a short one
    out.append(("a member read that fails once and serves when tried again is read in full, in "
                "one read, on a RAID0 array where nothing else could serve it",
                once is not None and len(whole) == once.image.size
                and hashlib.sha256(whole).hexdigest() == md["md-r0"]["device_sha256"]))
    return out


def _raid_review5_checks(md, blob):
    """The cases a validation run on 2026-10-16 found: an image holding part of
    an array on its partitions, the RAID heading's count, two paths that open
    one disk (two segments of one set, a link, the same path twice), and two
    images that share a file name in two folders."""
    import io
    import tempfile
    out = []
    ls = md["md-r5-ls"]
    files = [m["file"] for m in ls["members"]]

    def on_partitions(roles):
        disk = bytearray(1 << 20)
        for i, role in enumerate(roles):
            part = blob(files[role])
            struct.pack_into("<B3sB3sII", disk, 446 + 16 * i, 0, b"\0\0\0", 0xfd, b"\0\0\0",
                             len(disk) // SECTOR, len(part) // SECTOR)
            disk += part
        disk[510:512] = b"\x55\xaa"
        return bytes(disk)

    # Roles 0 and 1 on the partitions of one image, 2 and 3 on another disk not
    # given: the report names the roles as not on this image and what would
    # find them, and does not point at members left out when none were.
    said = []
    raid_report(raid_assemble([("diskA", io.BytesIO(on_partitions((0, 1))))]),
                say=said.append, images_given=1)
    line = next((s for s in said if "on this image's partitions" in s), "")
    out.append(("an image holding roles 0 and 1 of a RAID5 on its partitions says roles 2, 3 "
                "are not on it and suggests --find-members, with no word of members left out "
                "when none were; the heading counts no array as assembled",
                "role(s) 2, 3 are not on this image" in line and "--find-members" in line
                and not any("left out" in s for s in said)
                and any("found in the images given, 0 of them assembled" in s for s in said)))
    # The same with role 0 twice on it: the one left out is named, and pointed at.
    said = []
    raid_report(raid_assemble([("diskA", io.BytesIO(on_partitions((0, 1, 0))))]),
                say=said.append, images_given=1)
    line = next((s for s in said if "on this image's partitions" in s), "")
    out.append(("the same image with role 0 on a second partition too points at the member "
                "left out above",
                "left out above" in line and any("left out:" in s for s in said)))
    # The heading of a set read in full is as it was; --find-members already
    # used is not suggested again.
    said, said_fm, said_one = [], [], []
    raid_report(raid_assemble([(f, io.BytesIO(blob(f))) for f in files]), say=said.append,
                images_given=4)
    raid_report(raid_assemble([(files[0], io.BytesIO(blob(files[0])))]), say=said_fm.append,
                images_given=1, find_members=True)
    raid_report(raid_assemble([(files[0], io.BytesIO(blob(files[0])))]), say=said_one.append,
                images_given=1)
    out.append(("a RAID5 set given in full is headed as one array assembled; one member alone "
                "is headed as found and not assembled, suggests --find-members, and does not "
                "once --find-members has looked",
                any(s.startswith("RAID: 1 array(s) or spanned volume(s) assembled from") for s in said)
                and any("found in the images given, 0 of them assembled" in s for s in said_one)
                and any("--find-members" in s for s in said_one)
                and not any("--find-members" in s for s in said_fm)))

    # Paths that open one disk are read once. A folder of its own inside the
    # temporary one: the CI build replaces mkdtemp with one shared folder whose
    # top-level images it counts.
    parent = tempfile.mkdtemp(prefix="qnxprobe-same-disk-")
    top = os.path.join(parent, "same-disk")
    os.makedirs(top, exist_ok=True)
    try:
        def put(name, data):
            where = os.path.join(top, name)
            with open(where, "wb") as fh:
                fh.write(data)
            return where
        m0 = blob(files[0])
        s1 = put("m0.001", m0[:len(m0) // 2])
        s2 = put("m0.002", m0[len(m0) // 2:])
        m1 = put("m1.raw", blob(files[1]))
        m2 = put("m2.raw", blob(files[2]))
        m3 = put("m3.raw", blob(files[3]))
        copy3 = put("m3-copy.raw", blob(files[3]))
        given = [s1, s2, m1, m2, m3, os.path.join(top, ".", "m3.raw"), m3]
        want = {1: s1, 5: m3, 6: m3}
        try:
            hard = os.path.join(top, "m2-hard.raw")
            os.link(m2, hard)
            given.append(hard)
            want[len(given) - 1] = m2
        except (OSError, AttributeError):
            pass
        try:
            soft = os.path.join(top, "m1-soft.raw")
            os.symlink(m1, soft)
            given.append(soft)
            want[len(given) - 1] = m1
        except (OSError, NotImplementedError, AttributeError):
            pass
        # three files that each start as an EWF segment: E02 and E03 belong to
        # the set E01 opens, whichever is named
        sig = b"\x45\x56\x46\x09\x0d\x0a\xff\x00\x01"
        e1, _e2, e3 = (put(f"e.E0{i}", sig + bytes(4096)) for i in (1, 2, 3))
        pairs = same_disk_paths(given)
        ewf = same_disk_paths([e1, e3]) if ewfprobe is not None else [(e1, None), (e3, e1)]
        dups = {i: first for i, (_p, first) in enumerate(pairs) if first is not None}
        kept = [where for where, first in pairs if first is None]
        rs = raid_open(kept)
        try:
            arr = rs.arrays[0] if len(rs.arrays) == 1 else None
            read = (arr is not None and arr.image is not None and not arr.left_out
                    and _raid_sha(arr.image)[0] == ls["device_sha256"])
        finally:
            rs.close()
        out.append(("paths that open one disk (the second segment of a split raw set, the same "
                    "path twice and spelled another way, a hard and a symbolic link, the third "
                    "segment of an EWF set) are read once, as the first given; a byte copy "
                    "under another name is not; the RAID5 they make is read with no member "
                    "left out as given again",
                    dups == want and same_disk_paths([m3, copy3]) == [(m3, None), (copy3, None)]
                    and ewf == [(e1, None), (e3, e1)] and read))
        # Two acquisitions of one member under one file name in two folders: the
        # RAID section names each by as many parent folders as tell them apart.
        twins = []
        for sub in ("first", "second"):
            os.makedirs(os.path.join(top, sub, "disk"), exist_ok=True)
            twins.append(put(os.path.join(sub, "disk", "m1.raw"), blob(files[1])))
        said = []
        rs = raid_open([twins[0], m2, m3, twins[1]])
        try:
            raid_report(rs, say=said.append, images_given=4)
        finally:
            rs.close()
        one, two = (os.path.join(sub, "disk", "m1.raw") for sub in ("first", "second"))
        out.append(("two images of one member that share a file name in two folders are named "
                    "in the RAID section by the parent folders that tell them apart",
                    any(f"left out: {two}: role 1 again, held by {one}" in s for s in said)
                    and any(s.strip().startswith("member  m2.raw: md member of ") for s in said)
                    and raid_display_names(["/a/x/m.E01", "/b/x/m.E01", "/c/m.img"])
                    == [os.path.join("a", "x", "m.E01"), os.path.join("b", "x", "m.E01"), "m.img"]))
        # The wording for members on one image's partitions follows where each
        # member was found, never a space in the name shown: a whole-disk member
        # whose file name has a space, given alone, and two whole-disk copies in
        # folders whose names have spaces, do not get it; partitions of one
        # image whose name has a space do.
        def wording(paths):
            said = []
            rs = raid_open(paths)
            try:
                raid_report(rs, say=said.append, images_given=len(paths))
            finally:
                rs.close()
            return said
        spaced = put("member one.raw", blob(files[1]))
        pair = []
        for sub in ("first copy", "second copy"):
            os.makedirs(os.path.join(top, sub), exist_ok=True)
            pair.append(put(os.path.join(sub, "m 1.raw"), blob(files[1])))
        disk = put("disk A.raw", on_partitions((0, 1)))
        alone, both, parted = wording([spaced]), wording(pair), wording([disk])
        out.append(("the wording for members on one image's partitions follows where each was "
                    "found: not for a whole-disk member whose file name has a space, nor for two "
                    "copies in folders whose names have spaces; yes for partitions of one image "
                    "whose name has a space",
                    not any("this image's partitions" in s for s in alone + both)
                    and any("give the other member images" in s for s in alone)
                    and any("this image's partitions" in s for s in parted)
                    and any(os.path.join("second copy", "m 1.raw") + ": role 1 again, held by "
                            + os.path.join("first copy", "m 1.raw") in s for s in both)))
        # Four different member images named like one split set are joined by
        # name (split_segments): the others are said to be segments of the set
        # opened from the first, never the same disk, and the first's report
        # warns that later segments begin as a disk does. A real split set of
        # one member image gets no warning.
        os.makedirs(os.path.join(top, "numbered"), exist_ok=True)
        numbered = [put(os.path.join("numbered", f"m.{r + 1:03d}"), blob(files[r]))
                    for r in range(4)]
        warn = split_structure_warning(split_segments(numbered[0])) or ""
        out.append(("four member images named m.001 to m.004 are said to be segments of the "
                    "split set opened from m.001, not the same disk, and m.001's report warns "
                    "that m.002, m.003 and m.004 begin as a disk does; one member split in "
                    "two gets no warning, and the same path given twice is the same disk",
                    same_disk_note(numbered[1], numbered[0]).startswith(
                        "read as a segment of the split set opened from ")
                    and all(f"m.{r + 1:03d} (an md superblock)" in warn for r in (1, 2, 3))
                    and "m.001 (" not in warn
                    and split_structure_warning(split_segments(s1)) is None
                    and same_disk_note(m3, m3) == f"the same disk as {m3}, read once"))
    finally:
        _sibling_rm(top)
    out.append(("the paths-read-once checks leave no temporary folder behind",
                _selftest_parent_gone(parent, "qnxprobe-same-disk-") and not os.path.exists(top)))
    return out


def _encryption_message_checks():
    """What the report says of a LUKS container or BitLocker volume it did not
    open: the reader's own reason when a passphrase was given or nothing would
    open it here, and what to give only when nothing was given."""
    import contextlib
    import gzip
    import io
    import tempfile
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    need = ("luks1-cbc.img.gz", "luks-fixtures.json", "bitlocker-xts128.img.gz")
    if not all(os.path.isfile(os.path.join(here, n)) for n in need):
        return [("the LUKS and BitLocker fixtures are not beside this script, so what the "
                 "report says of a locked one was not checked", None)]
    p1 = json.load(open(os.path.join(here, "luks-fixtures.json"), encoding="utf-8"))["passphrases"][0]
    out = []
    hint = "(give its passphrase with --password-file or --password-env)"
    # A folder of its own inside the temporary one: the CI build replaces
    # mkdtemp with one shared folder it keeps, and shutil.rmtree with a no-op.
    parent = tempfile.mkdtemp(prefix="qnxprobe-locked-")
    top = os.path.join(parent, "locked")
    os.makedirs(top, exist_ok=True)
    try:
        def report(fixture, passwords):
            path = os.path.join(top, "locked-" + fixture.replace(".img.gz", ".dd"))
            if not os.path.exists(path):
                with gzip.open(os.path.join(here, fixture), "rb") as gz, open(path, "wb") as f:
                    f.write(gz.read())
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                main(path, passwords=passwords)
            return buf.getvalue()

        # Without pycryptodome (as on a Python that lacks it), the container
        # says what it needs, with or without its passphrase.
        global _BDE_AES                                 # pylint: disable=global-statement
        saved = _BDE_AES
        try:
            _BDE_AES = None
            none_given = report("luks1-cbc.img.gz", [])
            right_given = report("luks1-cbc.img.gz", [p1])
        finally:
            _BDE_AES = saved
        out.append(("without pycryptodome a LUKS container says AES needs it, given its right "
                    "passphrase or none, and is not told to give a passphrase",
                    all("needs the optional pycryptodome package" in t and hint not in t
                        for t in (none_given, right_given))))
        # A LUKS container inside a logical volume read through a map is not
        # opened (unlock_luks runs before lvm_image): with or without a
        # passphrase the report says so, and does not ask for one.
        need2 = ("lvm-fixture.img.gz", "luks1-xts.img.gz")
        if all(os.path.isfile(os.path.join(here, n)) for n in need2):
            with gzip.open(os.path.join(here, "lvm-fixture.img.gz"), "rb") as gz:
                disk = bytearray(gz.read())
            with gzip.open(os.path.join(here, "luks1-xts.img.gz"), "rb") as gz:
                luks = gz.read()
            placed = lvm_image(io.BytesIO(bytes(disk)), len(disk))
            data = next(v for v in volumes(io.BytesIO(bytes(disk)), len(disk))
                        if v["label"].endswith("/data"))
            lmap = placed.lvm_map_for(data["base"])
            pos = 0
            for at, n in lmap.image_runs(0, len(luks)):
                disk[at:at + n] = luks[pos:pos + n]
                pos += n
            said = {}
            for key, given in (("none", []), ("given", ["not the passphrase"])):
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    main("luks-in-mapped-lv", image=io.BytesIO(bytes(disk)), passwords=given)
                said[key] = buf.getvalue()
            note = "inside a logical volume read through a map, where a LUKS container is not opened"
            out.append(("a LUKS container inside a logical volume read through a map says it is "
                        "not opened there, and that a passphrase given was not tried, and is not "
                        "told to give one",
                        lmap is not None and pos == len(luks)
                        and all(note in t and hint not in t for t in said.values())
                        and "so the passphrase given was not tried on it" in said["given"]
                        and "so the passphrase given was not tried" not in said["none"]))
        if _BDE_AES is None:
            out.append(("a wrong passphrase is said as opening no keyslot, for LUKS and "
                        "BitLocker (needs the pycryptodome package)", None))
        else:
            wrong = report("luks1-cbc.img.gz", ["not the passphrase"])
            none_given = report("luks1-cbc.img.gz", [])
            out.append(("a LUKS container a wrong passphrase does not open says no passphrase given "
                        "opens a keyslot, and is not told to give one; with none given it is",
                        "LUKS-encrypted and not read: no passphrase given opens a keyslot" in wrong
                        and hint not in wrong and hint in none_given))
            bde_hint = "(give a password or recovery password with --password-file"
            wrong = report("bitlocker-xts128.img.gz", ["not the password"])
            none_given = report("bitlocker-xts128.img.gz", [])
            out.append(("a BitLocker volume a wrong password does not open says none given opens it, "
                        "and is not told to give one; with none given it is",
                        "none of the passwords or key files given opens it" in wrong
                        and bde_hint not in wrong and bde_hint in none_given))
    finally:
        _sibling_rm(top)
    out.append(("the locked-volume report checks leave no temporary folder behind",
                _selftest_parent_gone(parent, "qnxprobe-locked-") and not os.path.exists(top)))
    return out


def _luks2_rewritten(img, change, both=True):
    """A LUKS2 image whose JSON metadata `change(meta)` has edited, its checksum
    made good in both header copies (or only the first when `both` is False)."""
    import hashlib
    out = bytearray(img)
    size, = struct.unpack_from(">Q", out, 8)
    for at in ((0, size) if both else (0,)):
        meta = json.loads(bytes(out[at + 4096:at + size]).split(b"\0", 1)[0])
        change(meta)
        text = json.dumps(meta).encode()
        out[at + 4096:at + size] = text + bytes(size - 4096 - len(text))
        alg = out[at + 72:at + 104].split(b"\0")[0].decode()
        body = bytearray(out[at:at + size])
        body[448:512] = bytes(64)
        digest = hashlib.new(alg, bytes(body)).digest()
        out[at + 448:at + 448 + len(digest)] = digest
    return bytes(out)


def _luks_hostile_checks(images, p1, p2, want, walk):
    """Damaged and crafted LUKS headers cost nothing but that container, keyslot
    and digest rules hold, and the paths the fixtures alone do not reach."""
    import io
    out = []
    l2 = images["luks2-pbkdf2"]

    def state(img):
        """(volumes() ran, the container's note), never raising."""
        try:
            vols = volumes(io.BytesIO(img), len(img))
            luks = [v for v in vols if v["kind"] == "luks"]
            return True, (luks[0].get("note", "") if luks else "")
        except Exception as exc:                       # pylint: disable=broad-except
            return False, f"{type(exc).__name__}: {exc}"

    both_bad = bytearray(l2)
    size, = struct.unpack_from(">Q", both_bad, 8)
    both_bad[4096 + 10] ^= 1
    both_bad[size + 4096 + 10] ^= 1
    ok1, note1 = state(bytes(both_bad))
    v3 = bytearray(images["luks1-cbc"])
    struct.pack_into(">H", v3, 6, 3)
    ok2, note2 = state(bytes(v3))
    out.append(("a LUKS2 container with both header copies damaged, and a header of an "
                "unknown version, are listed as not read, and nothing else is lost",
                ok1 and "no LUKS2 header copy passes" in note1 and ok2 and "LUKS version 3" in note2))

    crafted = {
        "a kdf without iterations": lambda m: m["keyslots"]["0"]["kdf"].pop("iterations"),
        "keyslots as a list": lambda m: m.__setitem__("keyslots", []),
        "a segment size that is not a number": lambda m: m["segments"]["0"].__setitem__("size", "abc"),
        "a data segment with dm-integrity": lambda m: m["segments"]["0"].__setitem__(
            "integrity", {"type": "hmac(sha256)"}),
        "a serpent cipher": lambda m: m["segments"]["0"].__setitem__("encryption", "serpent-xts-plain64"),
    }
    held = []
    for what, change in crafted.items():
        img = _luks2_rewritten(l2, change)
        ok, note = state(img)
        lk = Luks.open(io.BytesIO(img), 0, len(img))
        held.append((what, ok and lk.why != "" and not lk.unlock([p1]) and "give its passphrase" not in note))
    out.append(("crafted LUKS2 metadata (" + ", ".join(w for w, _h in held) + ") is refused as not "
                "read, with why, before any passphrase is asked for",
                all(h for _w, h in held)
                and "dm-integrity" in Luks.open(io.BytesIO(_luks2_rewritten(l2, crafted["a data segment with dm-integrity"])), 0, len(l2)).why
                and "only AES" in Luks.open(io.BytesIO(_luks2_rewritten(l2, crafted["a serpent cipher"])), 0, len(l2)).why))

    huge = _luks2_rewritten(images["luks2-argon2id"], lambda m: m["keyslots"]["0"]["kdf"].update(
        memory=2 ** 32 - 1)) if _ARGON2 is not None else None
    if huge is not None:
        started = time.time()
        lk = Luks.open(io.BytesIO(huge), 0, len(huge))
        lk.unlock([p1])
        out.append(("an Argon2 keyslot asking for more memory than cryptsetup allows is refused, "
                    f"not run ({time.time() - started:.2f}s)",
                    lk.mk is None and "past cryptsetup's own limits" in lk.why
                    and time.time() - started < 30))
        # a digest applies to the keyslots it lists: limited to the second keyslot,
        # the first keyslot's passphrase no longer opens, the second's still does
        only1 = _luks2_rewritten(images["luks2-argon2id"],
                                 lambda m: m["digests"]["0"].__setitem__("keyslots", ["1"]))
        a, b = Luks.open(io.BytesIO(only1), 0, len(only1)), Luks.open(io.BytesIO(only1), 0, len(only1))
        out.append(("a digest confirms only the keyslots it lists",
                    not a.unlock([p1]) and b.unlock([p2]) and b.unlocked_by == "keyslot 1"))

    # A header copy records where it sits (hdr_offset, which cryptsetup checks):
    # a primary that names another place, its checksum made good, is passed over.
    import hashlib
    moved = bytearray(l2)
    struct.pack_into(">Q", moved, 256, 4096)
    alg = moved[72:104].split(b"\0")[0].decode()
    body = bytearray(moved[:size])
    body[448:512] = bytes(64)
    dg = hashlib.new(alg, bytes(body)).digest()
    moved[448:448 + len(dg)] = dg
    mlk = Luks.open(io.BytesIO(bytes(moved)), 0, len(moved))
    out.append(("a header copy that records another place than its own is passed over for the "
                "second copy", mlk.unlock([p1]) and any("names another size or place" in p
                                                         for p in mlk.problems)))

    # The key a keyslot's material is encrypted with is as long as the keyslot's
    # area says, which need not be the volume key's length.
    shorter = _luks2_rewritten(l2, lambda m: m["keyslots"]["0"]["area"].__setitem__("key_size", 16))
    lengths = []
    lk = Luks.open(io.BytesIO(shorter), 0, len(shorter))
    real = lk._derive                                   # pylint: disable=protected-access

    def recorded(kdf, password, length):
        lengths.append(length)
        return real(kdf, password, length)
    lk._derive = recorded                               # pylint: disable=protected-access
    lk.unlock([p1])
    out.append(("a keyslot's key is derived at its area's key size (16 here), not the volume "
                "key's (32)", lengths == [16]))

    # plain counts the IV in 32 bits and wraps; plain64 does not
    block = bytes(range(256)) * 2
    key = bytes(range(64))
    wraps = []
    for spec, k in (("aes-xts-plain", key), ("aes-cbc-plain", key[:32])):
        c = _LuksCipher(spec, k)
        c64 = _LuksCipher(spec + "64", k)
        wraps.append(c.decrypt(block, 1 << 32) == c.decrypt(block, 0)
                     and c64.decrypt(block, 1 << 32) != c64.decrypt(block, 0))
    out.append(("the plain IV wraps at 32 bits and plain64 does not, in XTS and in CBC", all(wraps)))

    # iv_tweak shifts every sector's IV
    lk = Luks.open(io.BytesIO(l2), 0, len(l2))
    if lk.unlock([p1]):
        raw = l2[lk.offset:lk.offset + 4096]
        lk.iv_tweak, lk._cache = 40, collections.OrderedDict()     # pylint: disable=protected-access
        out.append(("a LUKS2 segment's iv_tweak is added to every sector's IV",
                    lk.read(0, 4096) == lk._cipher.decrypt(raw, 40, 4096)))   # pylint: disable=protected-access

    # A LUKS container inside a logical volume: lvm-wholedisk's one volume holds
    # luks1-cbc here, written over it, and what it holds is found and read.
    import gzip
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    whole_gz = os.path.join(here, "lvm-wholedisk.img.gz")
    if os.path.isfile(whole_gz):
        with gzip.open(whole_gz, "rb") as gz:
            nested = bytearray(gz.read())
        inner = images["luks1-cbc"]
        nested[3 << 20:(3 << 20) + len(inner)] = inner
        fh, found = unlock_luks(io.BytesIO(bytes(nested)), len(nested), [p1])
        vols = volumes(fh, len(nested))
        inside = [v for v in vols if v["label"] == "LUKS LVM wholevg/root"]
        got = dict(walk(inside[0]["walker"], inside[0]["walker"].root)) if inside and inside[0].get("walker") else {}
        out.append(("a LUKS container inside a logical volume is opened and what it holds is "
                    "listed, read and marked as read decrypted",
                    len(found) == 1 and got == want and inside[0].get("encryption", "").startswith("LUKS1")))
    return out


def _luks_self_checks():
    """[(label, passed or None for a skip)] for the LUKS reader, from the images
    cryptsetup wrote (tools/make_luks_fixtures.sh), its own luksDump of each, and
    sha256sum over the tree each holds."""
    import gzip
    import hashlib
    import io
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    names = ("luks2-argon2id", "luks2-pbkdf2", "luks1-xts", "luks1-cbc")
    need = [f"{n}.img.gz" for n in names] + ["luks-fixtures.json", "luks-fixture.sha256"]
    absent = [n for n in need if not os.path.isfile(os.path.join(here, n))]
    if absent:
        return [(f"the LUKS fixtures are not beside this script ({', '.join(absent)}), so the "
                 "LUKS reader was not checked against them", None)]
    if _BDE_AES is None:
        return [("LUKS volumes open with their passphrases (needs the pycryptodome package)", None)]
    meta = json.load(open(os.path.join(here, "luks-fixtures.json"), encoding="utf-8"))
    p1, p2 = meta["passphrases"]
    want = {}
    with open(os.path.join(here, "luks-fixture.sha256"), encoding="utf-8") as lf:
        for line in lf:
            h, name = line.rstrip("\n").split("  ", 1)
            want[name] = h

    def walk(w, node, path=""):
        for name, child in w.listdir(node):
            if name in (".", "..", "lost+found"):
                continue
            mode, size = w.entry(child)[:2]
            rel = f"{path}/{name}" if path else name
            if mode & S_IFMT == S_IFDIR:
                yield from walk(w, child, rel)
            elif mode & S_IFMT == S_IFREG:
                yield rel, hashlib.sha256(b"".join(w.read_file(child, size))).hexdigest()

    out, images = [], {}
    for n in names:
        with gzip.open(os.path.join(here, f"{n}.img.gz"), "rb") as gz:
            images[n] = gz.read()
    for n in names:
        if n == "luks2-argon2id" and _ARGON2 is None:
            out.append((f"{n} opens with its passphrase (needs the argon2-cffi package)", None))
            continue
        img = images[n]
        lk = Luks.open(io.BytesIO(img), 0, len(img))
        dump = meta["images"][n]
        if "luks2_metadata" in dump:
            seg = dump["luks2_metadata"]["segments"]["0"]
            header_ok = (lk.version == 2 and lk.cipher == seg["encryption"]
                         and lk.offset == int(seg["offset"]) and lk.sector_size == seg["sector_size"]
                         and len(lk.keyslots) == len(dump["luks2_metadata"]["keyslots"]))
        else:
            text = dump["luksDump"]

            def field(key, text=text):
                return re.search(rf"^{key}:\s*(.+)$", text, re.M).group(1).strip()
            digest = re.search(r"MK digest:\s*((?:[0-9a-f]{2} ?){20})", text).group(1).replace(" ", "")
            header_ok = (lk.version == 1 and lk.cipher == f"{field('Cipher name')}-{field('Cipher mode')}"
                         and lk.offset == int(field("Payload offset")) * SECTOR
                         and lk.key_bytes * 8 == int(field("MK bits")) and lk.mk_digest.hex() == digest
                         and len(lk.keyslots) == text.count(": ENABLED"))
        out.append((f"{n}: the header reads as cryptsetup's own luksDump gives it", header_ok))
        fh, found = unlock_luks(io.BytesIO(img), len(img), ["not the passphrase", p1])
        vols = volumes(fh, len(img))
        data = [v for v in vols if v["label"].startswith("LUKS ")]
        got = {}
        if data and data[0].get("walker"):
            got = dict(walk(data[0]["walker"], data[0]["walker"].root))
        out.append((f"{n}: opened with its passphrase (a wrong one tried first), every file of "
                    f"the filesystem inside matches what sha256sum recorded ({len(got)} of {len(want)})",
                    len(found) == 1 and found[0].mk is not None and got == want))
        wrong = Luks.open(io.BytesIO(img), 0, len(img))
        out.append((f"{n}: a wrong passphrase leaves it locked, and the note says to give one",
                    not wrong.unlock(["not the passphrase"]) and "no passphrase given opens"
                    in wrong.locked_note()))
    if _ARGON2 is not None:
        img = images["luks2-argon2id"]
        second = Luks.open(io.BytesIO(img), 0, len(img))
        out.append(("luks2-argon2id: its second passphrase opens its second keyslot",
                    second.unlock([p2]) and second.unlocked_by == "keyslot 1"))
        # A primary header changed after cryptsetup wrote it fails its checksum, and
        # the second copy, which passes, is read instead.
        bad = bytearray(img)
        bad[4096 + 10] ^= 0x01
        fallback = Luks.open(io.BytesIO(bytes(bad)), 0, len(bad))
        out.append(("luks2-argon2id: a primary header that fails its checksum is passed over for "
                    "the second copy, and says so",
                    fallback.unlock([p1]) and any("fails its checksum" in p for p in fallback.problems)))
        # Of two copies that pass their checksums the one with the higher sequence
        # id is in force: give the second copy a higher one and its own label.
        newer = bytearray(img)
        hdr = struct.unpack_from(">Q", newer, 8)[0]
        seq = struct.unpack_from(">Q", newer, hdr + 16)[0]
        struct.pack_into(">Q", newer, hdr + 16, seq + 1)
        newer[hdr + 24:hdr + 72] = b"second copy".ljust(48, b"\0")
        alg = newer[hdr + 72:hdr + 104].split(b"\0")[0].decode()
        body = bytearray(newer[hdr:2 * hdr])
        body[448:512] = bytes(64)
        dg = hashlib.new(alg, bytes(body)).digest()
        newer[hdr + 448:hdr + 448 + len(dg)] = dg
        out.append(("luks2-argon2id: of two header copies that pass, the one with the higher "
                    "sequence id is read", Luks.open(io.BytesIO(bytes(newer)), 0, len(newer)).label
                    == "second copy" and second.label != "second copy"))
    # Control: the IV of a 4096-byte LUKS2 sector counts 512-byte units. Counting
    # it in 4096-byte units decrypts sector 0 the same and every later one wrong,
    # so the files above could not have matched; check that it does differ.
    img = images["luks2-pbkdf2"]
    lk = Luks.open(io.BytesIO(img), 0, len(img))
    if lk.unlock([p1]):
        raw = img[lk.offset:lk.offset + 2 * 4096]
        right = lk._cipher.decrypt(raw, 0, 4096)                    # pylint: disable=protected-access
        wrong_units = lk._cipher.decrypt(raw, 0, 4096, 4096)        # pylint: disable=protected-access
        out.append(("control: counting a 4096-byte sector's IV in 4096-byte units decrypts its "
                    "first sector alike and the next one differently",
                    right[:4096] == wrong_units[:4096] and right[4096:] != wrong_units[4096:]
                    and right == lk.read(0, 2 * 4096)))
    # The report main() prints, given the passphrase, names the filesystem inside.
    import contextlib
    import shutil
    import tempfile
    top = tempfile.mkdtemp(prefix="qnxprobe-luks-")
    try:
        path = os.path.join(top, "luks1-cbc.dd")
        with open(path, "wb") as f:
            f.write(images["luks1-cbc"])
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            main(path, passwords=["not the passphrase", p1])
        text = buf.getvalue()
    finally:
        shutil.rmtree(top, ignore_errors=True)
    out.append(("the report, given the passphrase, opens the container and names the "
                "filesystem inside", "->  luks" in text and "LUKS whole image" in text
                and "->  ext4" in text))
    out += _luks_hostile_checks(images, p1, p2, want, walk)
    # An image with no passphrase given: the container is listed, locked, with why.
    img = images["luks1-cbc"]
    locked = [v for v in volumes(io.BytesIO(img), len(img)) if v["kind"] == "luks"]
    out.append(("a LUKS container with no passphrase given is listed as locked, with what "
                "would open it", len(locked) == 1 and not locked[0].get("walker")
                and "give its passphrase" in locked[0].get("note", "")))
    return out


def _lvm_older_copy(disk, pv_at, m_off):
    """The fixture with the physical volume at pv_at holding an older metadata
    copy: seqno 1 and no volume onb, its checksums made good."""
    h = bytearray(disk[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE])
    o, n = struct.unpack_from("<QQ", h, 40)
    t = disk[pv_at + m_off + o:pv_at + m_off + o + n].split(b"\0", 1)[0].decode()
    cut = t.index("\nonb {")
    end = t.index("\n}\n}\n", t.index("segment1 {", cut)) + 5    # the segment's brace, then onb's
    stale = re.sub(r"seqno = \d+", "seqno = 1", t[:cut] + t[end:], count=1).encode()
    out = bytearray(disk)
    out[pv_at + m_off + o:pv_at + m_off + o + len(stale)] = stale
    struct.pack_into("<QQI", h, 40, o, len(stale), lvm_crc(stale))
    struct.pack_into("<I", h, 0, lvm_crc(bytes(h[4:])))
    out[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE] = h
    return bytes(out)


def _lvm_hostile_checks(disk, whole, regions, want, paths, parts, m_off, r_off):
    """The checks the review asked for: inputs lvm2 would refuse, damaged and
    crafted metadata, and the cases the fixtures alone do not reach."""
    import io
    out = []
    lvm_regions = [r for r in regions if not r[0].startswith("MBR")]
    pv1 = parts["1"]

    def with_header(img, pv_at, change):
        h = bytearray(img[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE])
        change(h)
        b = bytearray(img)
        b[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE] = h
        return bytes(b)

    # The whole-disk volume's extents start 3 MiB in, at the pe_start lvm2
    # reports, where the 1 MiB extent size would put them elsewhere.
    wpe = int(json.load(open(paths["lvm-wholedisk.pvs.json"], encoding="utf-8"))
              ["pvs"]["report"][0]["pv"][0]["pe_start"].rstrip("B"))
    wfound, _wn = lvm_volumes(io.BytesIO(whole), [("whole image", 0, len(whole))])
    out.append((f"the whole-disk volume starts at the pe_start lvm2 reports ({wpe:,} bytes), "
                "not at the extent size", wpe == 3 << 20 and [b for _l, b, _s, _n in wfound] == [wpe]))

    # A metadata area header changed after lvm2 wrote it, with its checksum left.
    bad = with_header(disk, pv1, lambda h: h.__setitem__(200, h[200] ^ 0xFF))
    bf, bn = lvm_volumes(io.BytesIO(bad), lvm_regions)
    out.append(("a metadata area header that fails its checksum is reported and the other "
                "physical volume's copy is used",
                {(a, b, c) for a, b, c, _n in bf} == want
                and any("metadata area header checksum does not match" in ln for ln in bn[pv1])))

    # A copy lvm2 marks ignored (RAW_LOCN_IGNORED) is not used.
    def ignore(h):
        o, n, c, f = struct.unpack_from("<QQII", h, 40)
        struct.pack_into("<QQII", h, 40, o, n, c, f | LVM_RAW_LOCN_IGNORED)
        struct.pack_into("<I", h, 0, lvm_crc(bytes(h[4:])))
    ign = with_header(disk, pv1, ignore)
    ipv = LvmPv(io.BytesIO(ign), pv1)
    igf, _ign = lvm_volumes(io.BytesIO(ign), lvm_regions)
    out.append(("a metadata copy lvm2 marks ignored is not used, and the other copy is",
                ipv.vg is None and not ipv.problems and {(a, b, c) for a, b, c, _n in igf} == want))

    # A label is accepted only as lvm2 accepts it: one that names another sector,
    # or fails its checksum, is passed over, and the next sector's is taken.
    label = disk[pv1 + SECTOR:pv1 + 2 * SECTOR]
    moved = bytearray(disk)
    moved[pv1 + SECTOR:pv1 + 2 * SECTOR] = bytes(SECTOR)
    moved[pv1 + 2 * SECTOR:pv1 + 3 * SECTOR] = label              # still says sector 1
    wrong_sector = _lvm_pv(io.BytesIO(bytes(moved)), pv1, None)
    fixed = bytearray(label)
    struct.pack_into("<Q", fixed, 8, 2)
    struct.pack_into("<I", fixed, 16, lvm_crc(bytes(fixed[20:])))
    moved[pv1 + 2 * SECTOR:pv1 + 3 * SECTOR] = fixed
    right_sector = _lvm_pv(io.BytesIO(bytes(moved)), pv1, None)
    flipped = bytearray(disk)
    flipped[pv1 + SECTOR + 40] ^= 0x01
    out.append(("a label naming another sector, or failing its checksum, is passed over as "
                "lvm2 passes it over, and a good one in the next sector is taken",
                wrong_sector is None and _lvm_pv(io.BytesIO(bytes(flipped)), pv1, None) is None
                and right_sector is not None and right_sector.label_sector == 2))

    # A stray label with no metadata area behind it does not hide the
    # filesystem the region holds.
    ext_fix = os.path.join(os.path.dirname(paths["lvm-fixture.sha256"]), "ext4-sparse.img.gz")
    if os.path.isfile(ext_fix):
        import gzip
        with gzip.open(ext_fix, "rb") as gz:
            ext = bytearray(gz.read())
        ext[SECTOR:2 * SECTOR] = label
        kind = identify_fs(io.BytesIO(bytes(ext)), 0, len(ext))[0]
        out.append(("an ext4 volume with a stray LVM label and no metadata area behind it is "
                    f"still ext4 (read as {kind})", kind == "ext4"))
    else:
        out.append(("the ext4-sparse fixture is beside this script for the stray-label check", False))

    # Crafted metadata text, with its checksums made good, is refused as a
    # problem and costs nothing else: every other partition is still listed.
    for text in (b"fixvg {\nseqno = 99\nx = [\n", b"a {" * 2000,
                 b"a = 1\n" + b"#" * 60 + b"\n;"):
        def craft(h, text=text):
            o, _n, _c, f = struct.unpack_from("<QQII", h, 40)
            struct.pack_into("<QQII", h, 40, o, len(text), lvm_crc(text), f)
            struct.pack_into("<I", h, 0, lvm_crc(bytes(h[4:])))
        o = struct.unpack_from("<Q", disk, pv1 + m_off + 40)[0]
        img = bytearray(with_header(disk, pv1, craft))
        img[pv1 + m_off + o:pv1 + m_off + o + len(text)] = text
        started = time.time()
        try:
            vols = volumes(io.BytesIO(bytes(img)), len(img))
            fine = {v["label"] for v in vols} >= {"GPT part 1 lvm-a", "GPT part 2 lvm-b"}
            cpv = LvmPv(io.BytesIO(bytes(img)), pv1)
            fine = fine and cpv.vg is None and any("metadata area" in p for p in cpv.problems)
        except Exception:                            # pylint: disable=broad-except
            fine = False
        took = time.time() - started
        out.append((f"crafted metadata text ({text[:18]!r}...) is refused as a problem in "
                    f"{took:.2f}s and every partition is still listed", fine and took < 60))

    # A whole-disk physical volume is identified without the reader calling
    # itself: count the calls volumes() makes to partition_regions.
    calls = [0]
    real = globals()["partition_regions"]

    def counting(*a, **k):
        calls[0] += 1
        return real(*a, **k)
    globals()["partition_regions"] = counting
    try:
        volumes(io.BytesIO(whole), len(whole))
    finally:
        globals()["partition_regions"] = real
    out.append((f"a whole-disk physical volume is listed with {calls[0]} call(s) to "
                "partition_regions, not one per recursion level", calls[0] <= 2))

    # Segments lvm2 keeps apart though they touch: the volume starts at the first.
    two = [{"type": "striped", "stripe_count": 1, "start_extent": 0, "extent_count": 2,
            "stripes": ["pv0", 5]},
           {"type": "striped", "stripe_count": 1, "start_extent": 2, "extent_count": 1,
            "stripes": ["pv0", 7]}]
    two_map = _lvm_layout(two, {"pv0": (1000, 100, 20)}, {"pv0"}, 10)[1]
    out.append(("a volume in two touching runs is one run, from its first extent",
                two_map is not None and two_map.contiguous() == 1000 + 100 + 50 and two_map.size == 30))
    out.append(("a volume whose extents are on something that is not one of the group's "
                "physical volumes (a move in progress) says so",
                "not a physical volume of the group"
                in (_lvm_layout([dict(two[0], stripes=["pvmove0", 0])], {"pv0": (0, 0, 9)},
                                {"pv0"}, 10)[0] or "")))
    out.append(("a volume that runs past its physical volume's extents is not read",
                "run past" in (_lvm_layout(two, {"pv0": (0, 0, 6)}, {"pv0"}, 10)[0] or "")))
    # Metadata that parses but holds a value of the wrong kind where lvm2 writes
    # a number, a section, a string or a list: that copy is refused, the other
    # physical volume's copy gives every volume, and nothing else is lost.
    o = struct.unpack_from("<Q", disk, pv1 + m_off + 40)[0]
    n = struct.unpack_from("<Q", disk, pv1 + m_off + 48)[0]
    good = disk[pv1 + m_off + o:pv1 + m_off + o + n].split(b"\0", 1)[0].decode()
    shapes = [("physical_volumes {", "physical_volumes = 5\nphysical_volumes_x {"),
              ("pv0 {", "pv0 = 5\npv0_x {"),
              ("logical_volumes {", "logical_volumes = [1]\nlogical_volumes_x {"),
              ("seqno = ", 'seqno = "9"\nseqno_x = '),
              ("extent_size = 2048", 'extent_size = "big"'),
              ('status = ["READ", "WRITE", "VISIBLE"]', "status = 5"),
              ("start_extent = 0", 'start_extent = "0"'),
              ("pe_start = 2048", 'pe_start = "a"')]
    held = []
    for old_text, new_text in shapes:
        text = good.replace(old_text, new_text, 1).encode()
        def craft_shape(h, text=text):
            o2, _n2, _c2, f2 = struct.unpack_from("<QQII", h, 40)
            struct.pack_into("<QQII", h, 40, o2, len(text), lvm_crc(text), f2)
            struct.pack_into("<I", h, 0, lvm_crc(bytes(h[4:])))
        img = bytearray(with_header(disk, pv1, craft_shape))
        img[pv1 + m_off + o:pv1 + m_off + o + len(text)] = text
        try:
            sf, _sn = lvm_volumes(io.BytesIO(bytes(img)), lvm_regions)
            cpv = LvmPv(io.BytesIO(bytes(img)), pv1)
            held.append(good != text.decode() and cpv.vg is None
                        and any("metadata has" in p for p in cpv.problems)
                        and {(a, b, c) for a, b, c, _n in sf} == want
                        and len(volumes(io.BytesIO(bytes(img)), len(img))) >= 6)
        except Exception:                            # pylint: disable=broad-except
            held.append(False)
    out.append((f"metadata that parses with a value of the wrong kind is refused and the "
                f"other copy is used ({sum(held)} of {len(shapes)} shapes)", all(held)))

    # Two partitions with the same physical volume id (a cloned disk): the first
    # is used and the second says so.
    twin = bytearray(disk)
    p2 = parts["2"]
    twin[p2:p2 + (20 << 20)] = disk[pv1:pv1 + (20 << 20)]
    tf, tn = lvm_volumes(io.BytesIO(bytes(twin)), lvm_regions)
    root = [b for lab, b, _s, _n in tf if lab == "LVM fixvg/root"]
    want_root = [b for lab, b, _s in want if lab == "LVM fixvg/root"]
    out.append(("a second partition with the same physical volume id is named and the "
                "first is used", root == want_root
                and any("same physical volume id" in ln for ln in tn.get(p2, []))))
    out.append(("a snapshot is shown by the volume lvm2 lists for it",
                _lvm_shown("snapshot0", [{"type": "snapshot", "cow_store": "snap1"}])
                == "snap1 (stored as snapshot0)"
                and _lvm_shown("root", [{"type": "striped"}]) == "root"))
    named4k, _n4 = lvm_volumes(io.BytesIO(disk), lvm_regions, 4096)
    out.append(("a logical volume's name counts the disk's sector size, as the partition "
                "names do", {nm for _l, _b, _s, nm in named4k}
                == {f"lvm_lba{b // 4096}_{sanitize_volume_label('fixvg_' + l.split('/')[1], 40)}"
                    for l, b, _s in want}))
    out.append(("a quoted string undoes only \\\" and \\\\, as lvm2 does",
                lvm_config('a = "x\\ny\\"z\\\\"') == {"a": 'x\\ny"z\\'}))
    try:
        lvm_config("a = 010")
        octal = False
    except ValueError:
        octal = True
    out.append(("a number with a leading zero, which lvm2 would read as octal, is refused",
                octal))
    two_runs = LvmMap([(0, 10, None, [100]), (10, 10, None, [110])])
    out.append(("runs that touch in the image are given as one", two_runs.image_runs(0, 20) == [(100, 20)]))
    cut = LvmMap([(0, 8, 2, [0, 100])])
    out.append(("bytes of a striped volume past the image's end are counted per stripe",
                cut.missing(102) == 2 and cut.missing(200) == 0))
    stripe = {"type": "striped", "stripe_count": 2, "start_extent": 0, "stripe_size": 2,
              "stripes": ["pv0", 0, "pv1", 0]}
    out.append(("a striped segment whose stripes do not divide its extents is not read",
                "do not divide" in (_lvm_layout([dict(stripe, extent_count=9)],
                                                {"pv0": (0, 0, 9), "pv1": (0, 0, 9)},
                                                {"pv0", "pv1"}, 1024)[0] or "")))
    out.append(("each stripe's extents are checked against its own physical volume",
                _lvm_layout([dict(stripe, extent_count=10)], {"pv0": (0, 0, 6), "pv1": (0, 0, 6)},
                            {"pv0", "pv1"}, 1024)[0] is None))
    wimg = lvm_image(io.BytesIO(disk), len(disk))
    wimg.seek(len(disk) - 4)
    tail = wimg.read(64)
    out.append(("a read that runs off the image's end stops there, and does not run on into a "
                "volume placed past it", len(tail) == 4 and wimg.read(64) == b""
                and min(wimg.lvm_virtual.values()) >= len(disk) + (1 << 30)))
    # A partial image: a GPT entry that names a partition 2 GiB in, past the end
    # of this 64 MiB file, the shape of a disk bigger than its acquisition. Its
    # place must read as missing, not as a placed volume's data.
    far = bytearray(disk)
    n_ent, ent_sz = struct.unpack_from("<II", far, SECTOR + 80)
    arr = 2 * SECTOR
    e3 = arr + 2 * ent_sz
    far[e3:e3 + ent_sz] = far[arr:arr + ent_sz]                 # entry 1's type and name
    far[e3 + 16:e3 + 32] = uuid.UUID(int=3).bytes_le
    struct.pack_into("<QQ", far, e3 + 32, 4194304, 4194304 + 4194303)
    struct.pack_into("<I", far, SECTOR + 88, binascii.crc32(bytes(far[arr:arr + n_ent * ent_sz])))
    hsize = struct.unpack_from("<I", far, SECTOR + 12)[0]
    struct.pack_into("<I", far, SECTOR + 16, 0)
    struct.pack_into("<I", far, SECTOR + 16, binascii.crc32(bytes(far[SECTOR:SECTOR + hsize])))
    fvols = volumes(io.BytesIO(bytes(far)), len(far))
    third = [v for v in fvols if v["label"].startswith("GPT part 3")]
    fwrap = lvm_image(io.BytesIO(bytes(far)), len(far))
    out.append(("on a partial image whose table names a partition past the file, that "
                "partition reads as missing, and the mapped volumes are placed past it",
                len(third) == 1 and not third[0].get("walker")
                and third[0].get("missing_past_end") == 4194304 * SECTOR
                and min(fwrap.lvm_virtual.values()) > (4194304 + 4194304) * SECTOR
                and min(fwrap.lvm_virtual.values()) >= 1 << 60))

    # A pvmove in progress: lvm2 moves the volume's extents through a hidden
    # mirror segment, whose areas are under mirrors, each holding all of them.
    moving = {"extent_size": 2048, "physical_volumes": {"pv0": {"id": "a", "pe_start": 2048,
                                                                "pe_count": 10}},
              "logical_volumes": {
                  "lv1": {"status": ["READ", "VISIBLE"], "segment1": {
                      "start_extent": 0, "extent_count": 5, "type": "striped",
                      "stripe_count": 1, "stripes": ["pvmove0", 0]}},
                  "pvmove0": {"status": ["READ"], "segment1": {
                      "start_extent": 0, "extent_count": 5, "type": "mirror",
                      "mirror_count": 2, "mirrors": ["pv0", 0, "pv0", 5]}}}}
    _vl, _vf, _vm, mspare = _lvm_group("vg", moving, 1, {"a": (0, None)}, SECTOR)
    # Two stripes of 4 extents each on two 4-extent volumes, and an allocation
    # that overlaps another: what is left free is what neither covers.
    halves = {"extent_size": 2048, "physical_volumes": {
                  "pv0": {"id": "a", "pe_start": 0, "pe_count": 4},
                  "pv1": {"id": "b", "pe_start": 0, "pe_count": 6}},
              "logical_volumes": {
                  "s": {"status": ["VISIBLE"], "segment1": {
                      "start_extent": 0, "extent_count": 4, "type": "striped", "stripe_count": 2,
                      "stripe_size": 128, "stripes": ["pv0", 0, "pv1", 0]}},
                  "o1": {"status": ["VISIBLE"], "segment1": {
                      "start_extent": 0, "extent_count": 4, "type": "striped",
                      "stripe_count": 1, "stripes": ["pv1", 0]}},
                  "o2": {"status": ["VISIBLE"], "segment1": {
                      "start_extent": 0, "extent_count": 1, "type": "striped",
                      "stripe_count": 1, "stripes": ["pv1", 1]}}}}
    _hl, _hf, _hm, hspare = _lvm_group("vg", halves, 1, {"a": (0, None), "b": (1 << 30, None)}, SECTOR)
    mib = 1 << 20
    out.append(("a pvmove's mirrored extents, and each stripe's share of a striped one, count "
                "as held, and allocations that overlap leave free only what neither holds",
                mspare == {} and hspare == {0: [(2 * mib, 2 * mib)], 1 << 30: [((1 << 30) + 4 * mib, 2 * mib)]}))

    # Cut the image at 30 MiB: the striped volume's run on the second physical
    # volume starts there, so 2 MiB of it is missing, and the split one is whole.
    cutv = {v["label"]: v for v in volumes(io.BytesIO(disk[:30 << 20]), 30 << 20)}
    out.append(("on an image cut short, a mapped volume's missing bytes are those its map "
                "puts past the cut, and it has no LBA",
                cutv.get("LVM fixvg/striped", {}).get("missing_past_end") == 2 * mib
                and cutv.get("LVM fixvg/data", {}).get("missing_past_end") == 0
                and cutv["LVM fixvg/data"].get("lba", 0) is None
                and cutv["LVM fixvg/striped"].get("lba", 0) is None))
    # RAID1: lvm2's report puts the two copies on the two physical volumes; in
    # this fixture they hold the same bytes, which is what makes either one the
    # volume. With the first physical volume left out, the second copy is read.
    report = json.load(open(paths["lvm-fixture.lvs.json"], encoding="utf-8"))
    pe_start = {pv["pv_name"][-1]: int(pv["pe_start"].rstrip("B")) for pv in report["pvs"]["report"][0]["pv"]}
    segs_all = report["segments"]["report"][0]["seg"]
    def ext_range(name):
        r = [x for x in segs_all if x["lv_name"] == f"[{name}]"][0]["seg_pe_ranges"]
        dev, span = r.split(":")
        a, b = (int(x) for x in span.split("-"))
        pv = dev[-1]
        return parts[pv] + pe_start[pv] + a * (1 << 20), (b - a + 1) << 20
    (c0, n0), (c1, n1) = ext_range("mirror_rimage_0"), ext_range("mirror_rimage_1")
    only2 = [r for r in lvm_regions if r[0].startswith("GPT part 2")]
    o2found, _o2 = lvm_volumes(io.BytesIO(disk), only2)
    mirror2 = [b for lab, b, _n, _nm in o2found if lab == "LVM fixvg/mirror"]
    out.append(("a RAID1 volume's two copies hold the same bytes, and with the first copy's "
                "physical volume missing the second is read",
                n0 == n1 and disk[c0:c0 + n0] == disk[c1:c1 + n1] and mirror2 == [c1]))
    longer = {"m_rimage_0": {"segment1": {"type": "striped", "stripe_count": 1, "start_extent": 0,
                                          "extent_count": 3, "stripes": ["pv0", 0]}}}
    cut_map = _lvm_layout([{"type": "raid1", "start_extent": 0, "extent_count": 2,
                            "raids": ["m_rmeta_0", "m_rimage_0"]}], {"pv0": (0, 0, 9)}, {"pv0"},
                          1 << 20, longer)[1]
    out.append(("a RAID1 copy longer than its volume is read only to the volume's size",
                cut_map is not None and cut_map.size == 2 << 20))
    raid = {"type": "raid1", "start_extent": 0, "extent_count": 2, "data_offset": 2048,
            "raids": ["m_rmeta_0", "m_rimage_0"]}
    copy = {"m_rimage_0": {"segment1": {"type": "striped", "stripe_count": 1, "start_extent": 0,
                                        "extent_count": 2, "stripes": ["pv0", 0]}}}
    out.append(("a RAID1 segment with a data offset (written while a reshape moves its data) "
                "is not read", "data offset" in (_lvm_layout([raid], {"pv0": (0, 0, 9)}, {"pv0"},
                                                             1 << 20, copy)[0] or "")))
    del r_off
    return out


class _XfsPatchedImage:
    """A read-only view of an image held in memory with some byte ranges
    replaced, so a self-check can damage a structure without copying the image."""

    def __init__(self, data, patches=()):
        self.data, self.patches, self.pos = data, list(patches), 0

    def seek(self, off, whence=0):
        self.pos = off if whence == 0 else self.pos + off if whence == 1 else len(self.data) + off
        return self.pos

    def tell(self):
        return self.pos

    def read(self, n=-1):
        end = len(self.data) if n is None or n < 0 else min(len(self.data), self.pos + n)
        buf = bytearray(self.data[self.pos:end])
        for at, rep in self.patches:
            lo, hi = max(at, self.pos), min(at + len(rep), end)
            if lo < hi:
                buf[lo - self.pos:hi - self.pos] = rep[lo - at:hi - at]
        self.pos = end
        return bytes(buf)


def _decmpfs_fixture_files(stem, walker_class):
    """[(path, method, sha256 macOS read, node, size, walker)] for one decmpfs
    fixture image (tools/make_decmpfs_fixture.py), or None when it is absent."""
    import gzip, io
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    image, listing = os.path.join(here, f"{stem}.img.gz"), os.path.join(here, f"{stem}.sha256")
    if not (os.path.isfile(image) and os.path.isfile(listing)):
        return None
    with gzip.open(image, "rb") as gz:
        img = io.BytesIO(gz.read())
    w = walker_class(img, 0)
    have = {}
    for path, node, size, _mtime in collect(w, w.root):
        if size is not None:
            # the APFS walk names the volume first, the HFS+ walk does not
            have[path.split("/", 1)[1] if walker_class is ApfsWalker else path] = (node, size)
    out = []
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            if line.startswith("#") or not line.strip():
                continue
            digest, method, path = line.split(None, 2)
            node, size = have.get(path.strip(), (None, None))
            out.append((path.strip(), int(method), digest, node, size, w))
    return out


def _decmpfs_self_checks():
    """[(label, passed or None for a skip)] for the LZVN and LZFSE decoders and
    the decmpfs reader. The good streams are Apple's encoder's output checked by
    Apple's decoder (tools/make_decmpfs_streams.py); the images are volumes
    macOS wrote whose every file macOS read back (tools/make_decmpfs_fixture.py).
    The damaged inputs are edits of those, and each must be refused, never
    returned as bytes."""
    import base64, hashlib, io
    out = []
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")

    def is_refused(fn, *parts):
        try:
            got = fn(*parts)
        except DecompressError as exc:
            return True, str(exc)
        except Exception as exc:                     # pylint: disable=broad-except
            return False, f"raised {type(exc).__name__}, not a refusal: {exc}"
        return False, f"returned {len(got if isinstance(got, (bytes, bytearray)) else got[0]):,} bytes"

    def fewer_literals(blob):
        """The stream with its first block's literal count cut by 64: the
        literals still decode, and the matches then ask for more of them than
        the block says it holds."""
        v0 = struct.unpack_from("<Q", blob, 8)[0]
        v0 = (v0 & ~0xFFFFF) | ((v0 & 0xFFFFF) - 64)
        return blob[:8] + struct.pack("<Q", v0) + blob[16:]

    def decode(codec, blob, limit):
        return (lzfse_decompress(blob, limit) if codec == "LZFSE"
                else bytes(lzvn_decompress(blob, limit)[0]))

    # -- the codecs, on Apple's own streams ------------------------------------
    path = os.path.join(here, "decmpfs-streams.json")
    streams = {}
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for e in json.load(fh)["streams"]:
                streams[e["name"]] = (e["codec"], base64.b64decode(e["stream"]), e["size"],
                                      e["sha256"], e["blocks"])
        for name, (codec, blob, size, digest, blocks) in streams.items():
            try:
                got = decode(codec, blob, size)
                cond = hashlib.sha256(got).hexdigest() == digest and len(got) == size
            except DecompressError as exc:
                cond = False
                name += f"; refused: {exc}"
            out.append((f"{codec} decodes Apple's {name}"
                        + (f" ({', '.join(blocks)})" if blocks else "")
                        + " to the bytes it was made from", cond))
    else:
        out.append(("the LZVN and LZFSE streams are not beside this script, so the decoders "
                    "were not checked against them", None))
    if streams:
        _c, lzfse2, size2, _d, _b = streams["text, one LZFSE block"]
        _c, lzfsen, sizen, _d, _b = streams["text, one LZVN block"]
        _c, lzvn, sizev, _d, _b = streams["LZVN, text"]
        damaged = [
            ("an LZFSE stream cut before its end-of-stream block", "LZFSE", lzfse2[:-4], size2),
            ("an LZFSE stream cut inside its block", "LZFSE", lzfse2[:len(lzfse2) // 2], size2),
            ("an LZFSE block whose header says one byte more than it holds", "LZFSE",
             lzfse2[:4] + struct.pack("<I", size2 + 1) + lzfse2[8:], size2 + 1),
            ("an LZFSE block whose packed frequency tables are damaged", "LZFSE",
             lzfse2[:32] + b"\xff\xff\xff\xff" + lzfse2[36:], size2),
            ("an LZFSE stream with an unknown block magic", "LZFSE", b"bvxZ" + lzfse2[4:], size2),
            ("an LZFSE block whose matches use more literals than it names", "LZFSE",
             fewer_literals(lzfse2), size2),
            ("an LZFSE stream that decodes to more than the caller expects", "LZFSE",
             lzfse2, size2 - 1),
            ("an LZFSE LZVN block whose payload is one byte longer than its stream", "LZFSE",
             lzfsen[:8] + struct.pack("<I", struct.unpack_from("<I", lzfsen, 8)[0] + 1)
             + lzfsen[12:-4] + b"\x0e" + lzfsen[-4:], sizen),
            ("an LZVN stream cut before its end-of-stream opcode", "LZVN", lzvn[:-8], sizev),
            ("an LZVN stream cut inside an opcode", "LZVN", lzvn[:len(lzvn) // 3], sizev),
            ("an LZVN stream that decodes to more than the caller expects", "LZVN", lzvn,
             sizev - 1),
            ("an LZVN match reaching before the first byte (literal 'a', then distance 2)",
             "LZVN", b"\x40\x02a" + b"\x06" + bytes(7), 16),
            ("an LZVN match-only opcode before any distance is set", "LZVN",
             b"\xe1a\xf3" + b"\x06" + bytes(7), 16),
            ("an undefined LZVN opcode (0x70)", "LZVN", b"\x70" + b"\x06" + bytes(7), 16),
        ]
        for label, codec, blob, limit in damaged:
            cond, detail = is_refused(decode, codec, blob, limit)
            out.append((f"{label} is refused ({detail})", cond))

    # -- the decmpfs layer, on attributes and forks built here -----------------
    def fork_of(pieces):
        at, offs = 4 * (len(pieces) + 1), []
        for piece in pieces:
            offs.append(at)
            at += len(piece)
        offs.append(at)
        return _BytesFork(struct.pack(f"<{len(offs)}I", *offs) + b"".join(pieces))

    class _HugeFork:
        """A fork whose one block the table says is 1 GiB long. It records the
        longest read asked of it, and gives nothing past its table."""
        size, asked = (1 << 30) + 8, 0

        def read(self, off, length):
            self.asked = max(self.asked, length)
            table = struct.pack("<II", 8, 8 + (1 << 30))
            return table[off:off + length]

    huge = _HugeFork()
    text = b"decmpfs block text " * 4000                      # 76,000 bytes, two blocks
    stored = [b"\xcc" + text[:DECMPFS_BLOCK], b"\xcc" + text[DECMPFS_BLOCK:]]
    whole = lambda *a: b"".join(decmpfs_read(*a))
    layer = [
        ("a stored (method 10) fork of two blocks reads whole", True,
         lambda: whole(10, len(text), b"", fork_of(stored)) == text),
        ("a fork whose table holds one block fewer than the size needs", False,
         lambda: whole(10, len(text), b"", fork_of(stored[:1]))),
        ("a fork block that lies past the end of the fork", False,
         lambda: whole(10, len(text), b"", _BytesFork(fork_of(stored).read(0, 1 << 20)[:-5]))),
        ("a stored block one byte short", False,
         lambda: whole(10, len(text), b"", fork_of([stored[0], stored[1][:-1]]))),
        ("a stored block without its 0xCC marker", False,
         lambda: whole(10, len(text), b"", fork_of([b"\x00" + stored[0][1:], stored[1]]))),
        ("a fork-held method whose resource fork is not there", False,
         lambda: whole(8, len(text), b"", None)),
        ("method 1 whose attribute holds fewer bytes than the file's size", False,
         lambda: whole(1, 10, b"123456789", None)),
        ("method 5", False, lambda: whole(5, 100, bytes(12), None)),
        ("method 13 (LZBITMAP)", False, lambda: whole(13, 100, b"x", None)),
        ("method 14 (LZBITMAP)", False,
         lambda: whole(14, 100, b"", fork_of([b"x"]))),
        ("an unknown method (6)", False, lambda: whole(6, 100, b"x", None)),
        ("an attribute larger than the 3,802 bytes macOS reads", False,
         lambda: whole(9, 4000, b"\xcc" + bytes(4000), None)),
        ("a size beyond any file's size (2**64 - 1, method 3)", False,
         lambda: whole(3, (1 << 64) - 1, __import__("zlib").compress(b"x"), None)),
        ("the largest size a file can have, given to a zlib attribute of one byte", False,
         lambda: whole(3, DECMPFS_MAX_SIZE, __import__("zlib").compress(b"x"), None)),
        ("a size beyond any file's size (2**63, method 7)", False,
         lambda: whole(7, 1 << 63, b"\x06" + bytes(7), None)),
        ("a fork block longer than twice a 64 KiB block", False,
         lambda: whole(10, 10, b"", fork_of([b"\xcc" + bytes(DECMPFS_MAX_PIECE)]))),
        ("a fork table naming a 1 GiB block, refused before anything that long is read",
         False, lambda: whole(10, 10, b"", huge)),
        ("a zlib block that inflates to more than its block holds", False,
         lambda: whole(3, 10, __import__("zlib").compress(bytes(11)), None)),
    ]
    for label, good, fn in layer:
        if good:
            try:
                cond, detail = bool(fn()), ""
            except DecompressError as exc:
                cond, detail = False, f" (refused: {exc})"
            out.append((label + detail, cond))
        else:
            cond, detail = is_refused(fn)
            out.append((f"{label} is refused ({detail})", cond))
    out.append((f"a fork block longer than the cap is never read (longest read asked: "
                f"{huge.asked:,} bytes)", 0 < huge.asked <= DECMPFS_MAX_PIECE))
    # The shape macOS writes for method 4: no block's zlib stream ends, and the
    # byte count is what decides (see _decmpfs_block).
    import zlib
    flush = zlib.compressobj()
    open_ended = flush.compress(text[:DECMPFS_BLOCK]) + flush.flush(zlib.Z_SYNC_FLUSH)
    try:
        cond = whole(3, DECMPFS_BLOCK, open_ended, None) == text[:DECMPFS_BLOCK]
    except DecompressError:
        cond = False
    out.append(("a zlib block whose stream does not end, as macOS writes method 4 blocks, "
                "reads when it gives exactly its block's bytes", cond))

    # -- the images macOS wrote ------------------------------------------------
    for stem, cls, fs in (("decmpfs-apfs", ApfsWalker, "APFS"),
                          ("decmpfs-hfsplus", HfsPlusWalker, "HFS+")):
        try:
            files = _decmpfs_fixture_files(stem, cls)
        except Exception as exc:                     # pylint: disable=broad-except
            out.append((f"the {fs} decmpfs fixture was walked ({type(exc).__name__}: {exc})",
                        False))
            continue
        if files is None:
            out.append((f"the {fs} decmpfs fixture is not beside this script, so the "
                        f"compressed-file reader was not checked against it", None))
            continue
        matched, refused_ok, wrong, methods = 0, 0, [], set()
        w = files[0][5]
        for path, method, digest, node, size, _w in files:
            methods.add(method)
            if node is None:
                wrong.append(f"{path} missing")
                continue
            try:
                got = b"".join(w.read_file(node, size))
            except (ApfsUnreadable, HfsUnreadable) as exc:
                if method in (13, 14) and "LZBITMAP" in str(exc):
                    refused_ok += 1
                else:
                    wrong.append(f"{path}: {exc}")
                continue
            if method in (13, 14):
                wrong.append(f"{path} read as {len(got):,} bytes")
            elif hashlib.sha256(got).hexdigest() == digest and len(got) == size:
                matched += 1
            else:
                wrong.append(f"{path} differs")
        out.append((f"every file of the {fs} decmpfs fixture reads as macOS read it "
                    f"({matched} files, methods "
                    f"{', '.join(str(m) for m in sorted(methods - {0, 13, 14}))}), and its "
                    f"{refused_ok} LZBITMAP files are refused by name"
                    + (f"; {'; '.join(wrong[:3])}" if wrong else ""),
                    bool(not wrong and matched and refused_ok)))
        # A compression attribute on a file not flagged compressed is not its
        # content: macOS read the data fork, one empty and one not.
        unflagged = [(p, d, n, sz) for p, _m, d, n, sz, _w in files if p.startswith("unflagged/")]
        try:
            unflagged_ok = len(unflagged) == 2 and all(
                n is not None and hashlib.sha256(b"".join(w.read_file(n, sz))).hexdigest() == d
                for _p, d, n, sz in unflagged)
            noted = sum("not flagged compressed" in str(x) for x in getattr(w, "damage", []))
        except Exception as exc:                     # pylint: disable=broad-except
            unflagged_ok, noted = False, f"raised {type(exc).__name__}: {exc}"
        out.append((f"on the {fs} fixture, a file carrying a compression attribute but not "
                    f"flagged compressed reads as its data fork, as macOS read it, and each is "
                    f"recorded ({noted} recorded)", bool(unflagged_ok and noted == 2)))
        # --extract must leave a refused file out and say why, never store it
        # under its own name as an empty or partial member
        lz = [(p, n, s) for p, m, _d, n, s, _w in files if m == 14 and n is not None]
        if lz:
            buf, log = io.BytesIO(), []
            with zipfile.ZipFile(buf, "w") as zout:
                tally = extract_to_zip(zout, w, "V", [(lz[0][0], lz[0][1], lz[0][2], 0)], log)
            with zipfile.ZipFile(buf) as zout:
                names = zout.namelist()
            out.append((f"--extract leaves an LZBITMAP file of the {fs} fixture out and logs "
                        f"why", tally[3] == 1 and not names
                        and any("LZBITMAP" in line for line in log)))
    return out


def _xfs_self_checks():
    """[(label, passed or None for a skip)] for the XFS reader, from the images
    mkfs.xfs wrote (tools/make_xfs_fixtures.sh) and what was recorded beside
    each: a listing and sha256 of every file from the source tree, and xfs_db's
    and xfs_logprint's own view of the image."""
    import gzip
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    names = ("xfs-v5", "xfs-v4", "xfs-v5-4kn")
    need = [f"{n}{ext}" for n in names for ext in (".img.gz", ".known.json.gz")]
    absent = [n for n in need if not os.path.isfile(os.path.join(here, n))]
    if absent:
        return [(f"the XFS fixtures are not beside this script ({', '.join(absent)}), so the "
                 "XFS reader was not checked against them", None)]
    # Fixtures the root-only builder makes (tools/make_xfs_root_fixtures.sh) are
    # checked the same way when they are present.
    extra = [n for n in ("xfs-mounted", "xfs-dirty")
             if os.path.isfile(os.path.join(here, f"{n}.img.gz"))
             and os.path.isfile(os.path.join(here, f"{n}.known.json.gz"))]
    out = []
    # The CRC32C check value from the CRC RevEng catalogue, written out so that a
    # wrong table cannot pass every checksum it is also used to make.
    out.append(("XFS checksums are CRC32C (check value 0xE3069283)",
                ~xfs_crc32c(b"123456789") & 0xFFFFFFFF == 0xE3069283))
    images = {}
    for n in tuple(extra) + names:
        with gzip.open(os.path.join(here, f"{n}.img.gz"), "rb") as gz:
            images[n] = gz.read()
        with gzip.open(os.path.join(here, f"{n}.known.json.gz"), "rt", encoding="utf-8") as kf:
            known = json.load(kf)
        out.extend(_xfs_fixture_checks(n, images[n], known))
        if n not in names:
            images.pop(n)                       # keep only the three the damage checks patch
    out.extend(_xfs_damage_checks(images["xfs-v5-4kn"]))
    out.extend(_xfs_structure_checks(images["xfs-v5"], images["xfs-v4"]))
    return out


def _xfs_fixture_checks(name, data, known):
    """The checks of one fixture against what was recorded when it was made."""
    import hashlib
    out = []
    fh = _XfsPatchedImage(data)
    kind = identify_fs(fh, 0, len(data))[0]
    try:
        w = walker_for(kind, fh, 0, len(data)) if kind else None
        why = ""
    except XfsUnreadable as exc:
        w, why = None, f", refused: {exc}"
    out.append((f"{name} is identified as xfs and walked ({kind}{why})",
                kind == "xfs" and w is not None))
    if w is None:
        return out
    got = {p: (node, mode, size) for p, node, mode, size, _mt, _r in walk_all(w)}
    ents = known["entries"]
    good, first = 0, []
    files = sum(1 for e in ents if e["type"] == "file")
    hashed = 0
    for e in ents:
        g = got.pop(e["path"], None)
        why = None
        if g is None:
            why = "missing"
        else:
            info = w.inode_info(g[0])
            if g[1] != e["mode"]:
                why = f"mode {g[1]:o}, not {e['mode']:o}"
            elif e["type"] != "dir" and g[2] != e["size"]:
                why = f"size {g[2]}, not {e['size']}"
            elif info["mtime"] != e["mtime_ns"]:
                why = f"mtime {info['mtime']}, not {e['mtime_ns']}"
            elif e["type"] == "symlink" and w.readlink(g[0]) != e["target"]:
                why = "symlink target"
            elif e["type"] == "file":
                h, n = hashlib.sha256(), 0
                try:
                    for chunk in w.read_file(g[0], g[2]):
                        h.update(chunk)
                        n += len(chunk)
                except XfsUnreadable as exc:
                    why = f"read refused: {exc}"
                if why is None and (n != e["size"] or h.hexdigest() != e["sha256"]):
                    why = f"content ({n} bytes read)"
                elif why is None:
                    hashed += 1
        if why:
            if len(first) < 3:
                first.append(f"{e['path'][:60]}: {why}")
        else:
            good += 1
    extras = sorted(got) if not known.get("allow_extra") else []
    out.append((f"{name}: every entry matches the source tree in path, type and mode, size, "
                f"mtime to the nanosecond and symlink target, and every regular file its sha256 "
                f"({good} of {len(ents)} entries, {hashed} of {files} files"
                + (f"; first: {'; '.join(first)}" if first else "")
                + (f"; {len(extras)} extra, first {extras[0]!r}" if extras else "") + ")",
                good == len(ents) and hashed == files and not extras))
    links = known.get("hard_links", [])
    nodes = {}
    for path, node, _m, _s, _mt, _r in walk_all(w):
        nodes[path] = node
    same = sum(1 for grp in links if len({nodes.get(q) for q in grp}) == 1 and nodes.get(grp[0]))
    if links:
        out.append((f"{name}: names the source tree gave one inode share one inode here "
                    f"({same} of {len(links)} groups)", same == len(links)))
    # Directory and file formats against xfs_db's own reading of the image.
    db = known.get("xfs_db", {})
    shown, wrong, counted = [], [], 0
    for path, rec in db.items():
        node = w.root if path == "/" else nodes.get(path)
        info = w.inode_info(node) if node is not None else None
        if info is None:
            wrong.append(f"{path}: not found")
            continue
        if info["format"] != rec["fork"]:
            wrong.append(f"{path}: fork {info['format']}, xfs_db {rec['fork']}")
        if "dir_format" in rec:
            rep = w.dir_report(node)
            if rep["format"] != rec["dir_format"]:
                wrong.append(f"{path}: {rep['format']}, xfs_db {rec['dir_format']}")
            elif rep["indexed"] is not None and rep["indexed"] != rep["entries"] + 2:
                wrong.append(f"{path}: {rep['entries']} entries, its index counts {rep['indexed']}")
            shown.append(f"{path} {rep['format']}" + (" (B+tree map)" if rec["fork"] == "btree" else ""))
        runs = w._extents(w.inode(node)) or []          # pylint: disable=protected-access
        if len(runs) != rec["extents"] or info["nextents"] != rec["extents"]:
            wrong.append(f"{path}: {len(runs)} extents mapped and {info['nextents']} counted, "
                         f"xfs_db {rec['extents']}")
        counted += len(runs)
    out.append((f"{name}: directory and fork formats, and every extent map ({counted} extents), "
                f"agree with xfs_db ({'; '.join(shown)})"
                + (f"; {'; '.join(wrong[:3])}" if wrong else ""), not wrong and bool(shown)))
    # A v5 inode's creation time is written once, when it is made; its change
    # time only moves on from there (xfs_format.h:969-971). Read from the wrong
    # place, the two would not sit within a day of each other on every inode.
    if w.v5:
        gaps = [w.inode_info(n)["ctime"] - w.inode_info(n)["crtime"] for n in nodes.values()]
        out.append((f"{name}: every inode's creation time is at or before its change time, within "
                    f"a day ({len(gaps)} inodes)", bool(gaps) and all(0 <= g < 86400 * 10**9 for g in gaps)))
    # Free space against xfs_db's freesp, which also lists the AGFL blocks.
    if "freesp" in known:
        ag_bytes = w.agblocks * w.bs
        mine = sorted(((off // ag_bytes), (off % ag_bytes) // w.bs, n // w.bs) for off, n in w.free_extents())
        theirs = sorted(tuple(r) for r in known["freesp"])
        left = list(theirs)
        unmatched = 0
        for r in mine:
            if r in left:
                left.remove(r)
            else:
                unmatched += 1
        agfl = sum(known.get("flcount", []))
        ok = bool(mine) and not unmatched and all(r[2] == 1 for r in left) and len(left) == agfl
        out.append((f"{name}: the free extents are xfs_db's, less the {agfl} free-list blocks it "
                    f"also lists ({len(mine)} runs, {sum(r[2] for r in mine):,} blocks)", ok))
    if "log" in known:
        st, _detail, head, tail = w.log_state
        lg = known["log"]
        out.append((f"{name}: the log is {st}, head {head}, tail {tail}, as xfs_logprint finds it "
                    f"({lg['state'].lower()}, head {lg['head']}, tail {lg['tail']})",
                    (st, head, tail) == (lg["state"].lower(), lg["head"], lg["tail"])))
    out.append((f"{name}: no structure failed its check ({len(w.damage)} did)", not w.damage))
    return out


def _xfs_damage_checks(data):
    """What the reader does when a structure is damaged or a feature refused,
    each made by patching the xfs-v5-4kn fixture in memory."""
    out = []
    base = XfsWalker(_XfsPatchedImage(data), 0)
    sb = base.sb
    nodes = {p: node for p, node, _m, _s, _mt, _r in walk_all(base)}
    hello, large, sparse = nodes["hello.txt"], nodes["data/large.bin"], nodes["data/sparse.bin"]
    want_large = b"".join(base.read_file(large, base.entry(large)[1]))
    want_sparse = b"".join(base.read_file(sparse, base.entry(sparse)[1]))

    def inode_patch(ino, edit):
        """The inode's bytes after edit(bytearray), with its CRC made to hold again."""
        at = base.inode_offset(ino)
        raw = bytearray(data[at:at + base.isz])
        edit(raw)
        raw[100:104] = b"\0\0\0\0"
        raw[100:104] = struct.pack("<I", ~xfs_crc32c(bytes(raw)) & 0xFFFFFFFF)
        return at, bytes(raw)

    def sb_patch(edit):
        raw = bytearray(data[:sb["sectsize"]])
        edit(raw)
        raw[224:228] = b"\0\0\0\0"
        raw[224:228] = struct.pack("<I", ~xfs_crc32c(bytes(raw)) & 0xFFFFFFFF)
        return 0, bytes(raw)

    # An extent marked unwritten reads as zeros, at full length.
    def unwritten(raw):
        raw[base.core] |= 0x80                       # bit 63 of the first extent's l0
    w = XfsWalker(_XfsPatchedImage(data, [inode_patch(sparse, unwritten)]), 0)
    got = b"".join(w.read_file(sparse, len(want_sparse)))
    runs = w._extents(w.inode(sparse))               # pylint: disable=protected-access
    lo, hi = runs[0][0] * w.bs, (runs[0][0] + runs[0][2]) * w.bs
    out.append(("an XFS extent flagged unwritten reads as zeros at its full length and the rest "
                f"of the file is unchanged ({len(runs)} extents, the first {hi - lo:,} bytes)",
                len(runs) >= 2 and runs[0][3] and not runs[1][3] and len(got) == len(want_sparse)
                and want_sparse[lo:hi] != bytes(hi - lo) and got[lo:hi] == bytes(hi - lo)
                and got[:lo] == want_sparse[:lo] and got[hi:] == want_sparse[hi:]
                and got[hi:] != bytes(len(got) - hi)))
    # An inode whose CRC fails is left out, counted, and the rest still lists.
    at = base.inode_offset(hello)
    w = XfsWalker(_XfsPatchedImage(data, [(at + 60, bytes([data[at + 60] ^ 0x01]))]), 0)
    listed = {p for p, *_r in walk_all(w)}
    out.append(("an XFS inode that fails its CRC is left out and counted as damage, and the "
                "rest of the volume still lists",
                "hello.txt" not in listed and len(listed) == len(nodes) - 1
                and any("fails its CRC" in x for x in w.damage) and "damaged" in (w.note or "")))
    # A realtime file is listed but not read.
    def realtime(raw):
        raw[91] |= XFS_DIFLAG_REALTIME
    w = XfsWalker(_XfsPatchedImage(data, [inode_patch(large, realtime)]), 0)
    try:
        list(w.read_file(large, 4096))
        why = ""
    except XfsUnreadable as exc:
        why = str(exc)
    out.append(("an XFS realtime file is listed but its read is refused, saying why",
                w.entry(large) is not None and "realtime" in why))
    # A log whose last record is not an unmount record is dirty, and is said so.
    lstart = base._fsb_off(sb["logstart"])            # pylint: disable=protected-access
    head = base.log_state[2]
    rec = next(i for i in range(head - 1, -1, -1)
               if data[lstart + i * 512:lstart + i * 512 + 4] == b"\xfe\xed\xba\xbe")
    op = lstart + (rec + 1) * 512 + 9
    fh = _XfsPatchedImage(data, [(op, bytes([data[op] & ~XLOG_UNMOUNT_TRANS & 0xFF]))])
    kind, lines = identify_fs(fh, 0, len(data))
    w = XfsWalker(fh, 0)
    tail_lsn = struct.unpack_from(">Q", data, lstart + rec * 512 + 24)[0] & 0xFFFFFFFF
    out.append(("an XFS log whose last record is not an unmount record is reported dirty and "
                "not replayed, in the volume's lines and its note",
                w.log_state[0] == "dirty" and w.log_state[3] == tail_lsn and kind == "xfs"
                and any(ln.startswith("log          dirty") for ln in lines)
                and "not replayed" in (w.note or "")))
    # Incompatible features outside the list read are refused by name.
    def zoned(raw):
        struct.pack_into(">I", raw, 216, struct.unpack_from(">I", raw, 216)[0] | 0x200 | 0x8000)
    fh = _XfsPatchedImage(data, [sb_patch(zoned)])
    kind, lines = identify_fs(fh, 0, len(data))
    try:
        XfsWalker(fh, 0)
        why = ""
    except XfsUnreadable as exc:
        why = str(exc)
    out.append(("an XFS volume with an incompatible feature not read here is named xfs and "
                "refused, by name or by bit",
                kind == "xfs" and "zoned realtime" in why and "unknown bit 0x8000" in why
                and any(ln.startswith("walk         not possible") for ln in lines)))
    # A v5 superblock whose CRC fails is not walked, as the kernel will not mount it.
    fh = _XfsPatchedImage(data, [(108, b"X")])     # the label, CRC left as it was
    try:
        XfsWalker(fh, 0)
        why = ""
    except XfsUnreadable as exc:
        why = str(exc)
    out.append(("an XFS v5 superblock whose CRC fails is not walked", "CRC" in why))
    # The control: one byte of file data changed is a file that no longer matches.
    runs = base._extents(base.inode(large))           # pylint: disable=protected-access
    off = base._fsb_off(runs[0][1]) + 100              # pylint: disable=protected-access
    w = XfsWalker(_XfsPatchedImage(data, [(off, bytes([data[off] ^ 0xFF]))]), 0)
    out.append(("the XFS content check can fail: one byte changed in a file's block changes "
                "what is read", b"".join(w.read_file(large, len(want_large))) != want_large))
    return out



def _xfs_fix_crc(buf, off):
    """buf with the XFS CRC at ``off`` made to hold again, for a self-check that
    damages a structure on purpose and wants only its other checks to see it."""
    buf = bytearray(buf)
    buf[off:off + 4] = b"\0\0\0\0"
    buf[off:off + 4] = struct.pack("<I", ~xfs_crc32c(bytes(buf)) & 0xFFFFFFFF)
    return bytes(buf)


def _xfs_structure_checks(v5, v4):
    """The kernel's checks of each structure, each shown to catch what it is for
    on a patched in-memory copy of the xfs-v5 fixture (v4 for the checks only a
    v4 volume needs), and each with whatever else would let the damage through
    left intact: a CRC made to hold again, say, so that only the check under
    test can see the change."""
    # pylint: disable=protected-access
    out = []
    base = XfsWalker(_XfsPatchedImage(v5), 0)
    nodes = {p: n for p, n, *_r in walk_all(base)}
    eo = base.data_entry_offset

    def walker(patches, data=v5, size=None):
        return XfsWalker(_XfsPatchedImage(data, patches), 0, size)

    def ipatch(w0, data, ino, edit):
        at = w0.inode_offset(ino)
        raw = bytearray(data[at:at + w0.isz])
        edit(raw)
        return at, (_xfs_fix_crc(raw, 100) if w0.v5 else bytes(raw))

    def refusal(fn):
        try:
            fn()
        except XfsUnreadable as exc:
            return str(exc)
        return ""

    def first_block(path):
        runs = base._extents(base.inode(nodes[path]))
        return base._fsb_off(runs[0][1])

    def entries_at(buf, n):
        """The offsets and sizes of the first n entries of a directory data block."""
        pos, found = eo, []
        while len(found) < n:
            nl = buf[pos + 8]
            size = (8 + 1 + nl + (1 if base.ftype else 0) + 2 + 7) & ~7
            found.append((pos, size))
            pos += size
        return found

    # Shortform directories with 8-byte inode numbers: the entries parse at that
    # width, and a header whose count of them is wrong is damage.
    sf = nodes["dirs/sf"]
    ents = base._sf_entries(base.inode(sf))
    wide = (1 << 40) | ents[0][1]
    parent = base.inode(sf)["fork"][2:6]

    def to_i8(i8):
        def edit(raw):
            body = bytearray([len(ents), i8]) + bytes(4) + parent
            at = 0x60
            for k, (nm, child, ft) in enumerate(ents):
                body += (bytes([len(nm)]) + struct.pack(">H", at) + nm
                         + (bytes([ft]) if base.ftype else b"")
                         + (wide if k == 0 else child).to_bytes(8, "big"))
                at += 16
            raw[base.core:base.core + len(body)] = body
            struct.pack_into(">Q", raw, 56, len(body))
        return edit
    w = walker([ipatch(base, v5, sf, to_i8(1))])
    got = w._sf_entries(w.inode(sf))
    w2 = walker([ipatch(base, v5, sf, to_i8(2))])
    bad = w2._sf_entries(w2.inode(sf))
    out.append(("an XFS shortform directory with 8-byte inode numbers parses at that width, and "
                "one whose header miscounts them is damage",
                got == [(nm, wide if k == 0 else c, ft) for k, (nm, c, ft) in enumerate(ents)]
                and bad == [] and any("8-byte inode numbers" in x for x in w2.damage)))

    # Directory data blocks: the CRC, and on a block whose CRC holds, its own
    # disk address, its owner and the volume's uuid; and each entry's tag.
    blk_off = first_block("dirs/block")
    blk = v5[blk_off:blk_off + base.dir_blksize]
    found = entries_at(blk, 3)
    p1, (p3, s3) = found[0][0], found[2]
    w = walker([(blk_off + p3 + 9, bytes([blk[p3 + 9] ^ 0x01]))])
    out.append(("an XFS directory block that fails its CRC is skipped and counted as damage",
                w.listdir(nodes["dirs/block"]) == []
                and any("block 0 fails its CRC" in x for x in w.damage)))

    def header(edit):
        b = bytearray(blk)
        edit(b)
        return [(blk_off, _xfs_fix_crc(b, 4))]
    owner = walker(header(lambda b: struct.pack_into(">Q", b, 40, nodes["hello.txt"])))
    uuid_ = walker(header(lambda b: b.__setitem__(24, b[24] ^ 0x01)))
    node = nodes["dirs/node"]
    blocks = base._dir_blocks(base.inode(node), 0, base.leafblk)
    nruns = base._extents(base.inode(node))

    def db_off(db):
        for lb, pb, c, _u in nruns:
            if lb <= db < lb + c:
                return base._fsb_off(pb + db - lb)
        return None
    a, b = blocks[0][0], blocks[1][0]
    moved = walker([(db_off(b), v5[db_off(a):db_off(a) + base.bs])])
    names = [n for n, _c in moved.listdir(node)]
    out.append(("an XFS directory block whose CRC holds but that names another owner, another "
                "volume or another disk address is skipped and counted as damage",
                owner.listdir(nodes["dirs/block"]) == [] and uuid_.listdir(nodes["dirs/block"]) == []
                and any("of inode" in x for x in owner.damage)
                and any("on this volume" in x for x in uuid_.damage)
                and len(names) == len(set(names)) < len(base.listdir(node))
                and any(f"not block {blocks[1][1]}" in x for x in moved.damage)))
    tagged = walker(header(lambda b: struct.pack_into(">H", b, p3 + s3 - 2, p1)))
    listed = tagged.listdir(nodes["dirs/block"])
    out.append(("an XFS directory entry whose tag is not its own offset stops the block there, "
                "counted as damage",
                len(listed) < len(base.listdir(nodes["dirs/block"]))
                and any("has a tag" in x for x in tagged.damage)))

    # Extent B+tree blocks: the CRC, and a height past what the volume allows.
    mext = nodes["data/manyext.bin"]
    md = base.inode(mext)
    maxrecs = (len(md["fork"]) - 4) // 16
    leaf = base._fsb_off(struct.unpack_from(">Q", md["fork"], 4 + maxrecs * 8)[0])
    w = walker([(leaf + base.bmbt_hdr + 3, bytes([v5[leaf + base.bmbt_hdr + 3] ^ 0x01]))])
    why = refusal(lambda: b"".join(w.read_file(mext, md["size"])))
    w2 = walker([ipatch(base, v5, mext, lambda r: struct.pack_into(">H", r, base.core, 1200))])
    why2 = refusal(lambda: b"".join(w2.read_file(mext, md["size"])))
    out.append(("an XFS extent B+tree block that fails its CRC refuses the file, and a root taller "
                f"than the volume allows ({base.bm_maxlevels} levels) is refused without recursing",
                "fails its CRC" in why and "levels" in why2
                and any("fails its CRC" in x for x in w.damage)))

    # Extents: one crossing the end of its AG, one on an AG's headers; an AG
    # shorter than agblocks when it is the last; more extents than the fork holds.
    large = nodes["data/large.bin"]

    def move_first(start):
        def edit(raw):
            l0, l1 = struct.unpack_from(">QQ", raw, base.core)
            l0 = (l0 & ~0x1FF) | (start >> 43)
            l1 = ((start & ((1 << 43) - 1)) << 21) | (l1 & 0x1FFFFF)
            struct.pack_into(">QQ", raw, base.core, l0, l1)
        return edit
    crossing = walker([ipatch(base, v5, large, move_first(base.agblocks - 1))])
    on_hdr = walker([ipatch(base, v5, large, move_first(0))])
    size = base.entry(large)[1]
    why = refusal(lambda: b"".join(crossing.read_file(large, size)))
    why2 = refusal(lambda: b"".join(on_hdr.read_file(large, size)))

    def short_last(raw):
        struct.pack_into(">Q", raw, 8, (base.agcount - 1) * base.agblocks + 10)
    shrunk = walker([(0, _xfs_fix_crc(_xfs_edit(v5[:base.sectsize], short_last), 224))])
    shrunk_list = [p for p, *_r in walk_all(shrunk)]
    in_last = sum(1 for n in nodes.values() if n >> base.agino_log == base.agcount - 1)
    many = walker([ipatch(base, v5, large, lambda r: struct.pack_into(">Q", r, 24, 1 << 40))])
    out.append(("an XFS extent that crosses its AG's end or lies on an AG's headers refuses the "
                "file; the last AG ends where the volume does; a fork counting more extents than "
                "it holds is damage",
                "outside its AG" in why and "outside its AG" in why2 and in_last > 0
                and len(shrunk_list) < len(nodes) and any("outside the volume" in x for x in shrunk.damage)
                and many.entry(large) is None and any("extents in a fork" in x for x in many.damage)))

    # Inode magic: the kernel's first check, and the inode is counted, not lost silently.
    one = nodes["data/one_block.bin"]
    at = base.inode_offset(one)
    w = walker([(at, b"XX")])
    listed = {p for p, *_r in walk_all(w)}
    out.append(("an XFS inode without its magic is left out and counted as damage",
                "data/one_block.bin" not in listed and len(listed) == len(nodes) - 1
                and any("no inode magic" in x for x in w.damage)))

    # Remote symlinks: the v5 header's offset, length, owner and disk address,
    # each with the CRC made to hold; and only the blocks the target needs are read.
    lnk = nodes["links/long"]
    target = base.readlink(lnk)
    loff = first_block("links/long")
    sblk = v5[loff:loff + base.bs]
    bad = []
    for at, val in ((4, struct.pack(">I", 1)), (8, struct.pack(">I", 1)),
                    (32, struct.pack(">Q", nodes["hello.txt"])), (40, struct.pack(">Q", 1))):
        b = bytearray(sblk)
        b[at:at + len(val)] = val
        w = walker([(loff, _xfs_fix_crc(b, 12))])
        bad.append(bool(refusal(lambda w=w: w.readlink(lnk))))

    class _Counting(_XfsPatchedImage):
        largest = 0

        def read(self, n=-1):
            _Counting.largest = max(_Counting.largest, n)
            return super().read(n)

    def big_count(raw):
        l0, l1 = struct.unpack_from(">QQ", raw, base.core)
        struct.pack_into(">QQ", raw, base.core, l0, (l1 & ~0x1FFFFF) | 2000)
    w = XfsWalker(_Counting(v5, [ipatch(base, v5, lnk, big_count)]), 0)
    _Counting.largest = 0
    same = w.readlink(lnk) == target
    out.append(("an XFS remote symlink whose header names another offset, length, owner or block "
                "is refused, and one mapped to 2,000 blocks reads only the block its target needs",
                all(bad) and len(bad) == 4 and same and _Counting.largest <= base.bs))

    # A volume larger than its region: said in the note and the lines, and what
    # lies past the end is counted rather than lost silently.
    cut = v4[:len(v4) // 2]
    w = XfsWalker(_XfsPatchedImage(cut), 0, len(cut))
    listed = [p for p, *_r in walk_all(w)]
    lines = identify_xfs(_XfsPatchedImage(cut), 0, len(cut))[1]
    full = sum(1 for _ in walk_all(XfsWalker(_XfsPatchedImage(v4), 0)))
    # The same volume in a region half its size inside a longer image (a
    # partition followed by another): nothing past the region is read as its own.
    full4 = XfsWalker(_XfsPatchedImage(v4), 0)
    n4 = {p: node for p, node, *_r in walk_all(full4)}
    big4 = n4["data/large.bin"]
    last = full4._extents(full4.inode(big4))[-1]
    region = full4._fsb_off(last[1]) + full4.bs     # the region ends one block into its last extent
    part = XfsWalker(_XfsPatchedImage(v4), 0, region)
    plisted = [p for p, *_r in walk_all(part)]
    before = EOF_SHORTFALL["bytes"]
    got = b"".join(part.read_file(big4, full4.entry(big4)[1]))
    short = EOF_SHORTFALL["bytes"] - before
    want = b"".join(full4.read_file(big4, full4.entry(big4)[1]))
    past = (last[2] - 1) * full4.bs
    out.append(("an XFS volume cut to half its size says its end is missing, and each structure "
                "past the cut is counted as damage; in a region shorter than the image, what lies "
                "past the region is not read as the volume's",
                "its end is missing" in (w.note or "") and bool(w.damage) and len(listed) < full
                and any(ln.startswith("INCOMPLETE") for ln in lines)
                and bool(part.damage) and len(plisted) < full and len(got) == len(want)
                and short >= past > 0 and got[:len(want) - past] == want[:len(want) - past]))

    # Identification: claimed only once verified.
    zeros = bytes(4 << 20)
    bad_crc = _XfsPatchedImage(v5, [(108, b"X")])
    graft = _XfsPatchedImage(zeros, [(0, v4[:512])])
    out.append(("an XFS superblock is claimed only once verified: a v5 one whose CRC fails and a "
                "v4 one whose root inode does not read as a directory are not; the v4 fixture is",
                identify_xfs(bad_crc, 0, len(v5)) is None and identify_xfs(graft, 0, len(zeros)) is None
                and (identify_xfs(_XfsPatchedImage(v4), 0, len(v4)) or [None])[0] == "xfs"))
    return out


def _xfs_edit(buf, edit):
    """A bytearray copy of buf after edit(copy)."""
    b = bytearray(buf)
    edit(b)
    return b


def _shared_extract_checks():
    """[(label, passed)] for what every walker's extraction shares: hostile stored
    names cannot reach a zip member as a path, and a walker's damage is counted."""
    import io
    import shutil
    import tempfile
    out = []
    cases = {"a/b.txt": "vol/a/b.txt", "sp ace/%pct": "vol/sp ace/%pct",
             "../../x": "vol/%2E%2E/%2E%2E/x", "dir/./f": "vol/dir/%2E/f",
             "/abs": "vol/%2F/abs", "c:d": "vol/c%3Ad", "x\x00y": "vol/x%00y",
             "..\\..\\a.txt": "vol/..%5C..%5Ca.txt"}
    got = {k: zip_member_name("vol", k) for k in cases}
    out.append(("a stored name that climbs out ('..'), starts at a root, or carries a backslash, "
                "colon or control character becomes a safe zip member name; ordinary names are "
                "kept as stored", got == cases))

    class _Hostile:
        """A walker whose names are what a damaged or hostile volume can store."""
        root = 0
        damage = ["structure one failed its check", "structure two failed its check"]
        names = {1: "../escaped.txt", 2: "ok.txt", 3: "..\\win.txt", 4: "nul\x00cut.txt"}

        def listdir(self, node):
            return [(n, i) for i, n in self.names.items()] if node == 0 else []

        def entry(self, node):
            return (0o040755, 0, 0) if node == 0 else (0o100644, 3, 0)

        def read_file(self, _node, _size):
            yield b"abc"

    w = _Hostile()
    buf, log = io.BytesIO(), []
    with zipfile.ZipFile(buf, "w") as out_zip:
        tally = extract_to_zip(out_zip, w, "vol", collect(w, w.root), log)
    names = zipfile.ZipFile(buf).namelist()
    # A folder of its own inside the temporary one: the CI build replaces mkdtemp
    # with one that always returns its fixtures folder, so count only what this
    # extraction wrote.
    parent = tempfile.mkdtemp(prefix="qnxprobe-zip-")
    dest = os.path.join(parent, "hostile-names")
    os.makedirs(dest, exist_ok=True)
    try:
        zipfile.ZipFile(buf).extractall(dest)
        inside = all(os.path.realpath(os.path.join(root, f)).startswith(os.path.realpath(dest) + os.sep)
                     for root, _d, fs in os.walk(dest) for f in fs)
        written = sum(len(fs) for _r, _d, fs in os.walk(dest))
    finally:
        # the temporary folder itself, which held only this extraction
        shutil.rmtree(parent, ignore_errors=True)
    renamed = [line for line in log if "RENAMED" in line]
    out.append((f"an extraction of four hostile names writes four members, all inside the folder "
                f"they are extracted into, and logs the three renamed ({tally[0]} written, "
                f"{len(renamed)} renamed, {written} on disk)",
                tally[0] == 4 and len(names) == 4 and written == 4 and inside and len(renamed) == 3
                and not any(n.startswith("/") or "/../" in "/" + n for n in names)))
    out.append(("a walker's recorded damage is counted and shown",
                damage_lines(w) == (2, ["structure one failed its check",
                                        "structure two failed its check"])
                and damage_lines(object()) == (0, [])))
    return out


def _lvm_self_checks():
    """[(label, passed)] for the LVM2 reader, from the fixtures lvm2 wrote. A
    absent fixture is one failed check that names it, not a silent skip."""
    import contextlib
    import gzip
    import hashlib
    import io
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    paths = {n: os.path.join(here, n) for n in ("lvm-fixture.img.gz", "lvm-wholedisk.img.gz",
                                                "lvm-fixture.lvs.json", "lvm-fixture.sha256",
                                                "lvm-wholedisk.pvs.json")}
    absent = [n for n, p in paths.items() if not os.path.isfile(p)]
    if absent:
        # A frozen executable has no fixtures beside it: say so, as the other
        # fixture checks do, rather than fail.
        return [(f"the LVM fixtures are not beside this script ({', '.join(absent)}), so the "
                 "LVM2 reader was not checked against them", None)]
    out = []
    with gzip.open(paths["lvm-fixture.img.gz"], "rb") as gz:
        disk = gz.read()
    with gzip.open(paths["lvm-wholedisk.img.gz"], "rb") as gz:
        whole = gz.read()
    report = json.load(open(paths["lvm-fixture.lvs.json"], encoding="utf-8"))
    hashes = {}
    with open(paths["lvm-fixture.sha256"], encoding="utf-8") as lf:
        for line in lf:
            h, name = line.rstrip("\n").split("  ", 1)
            hashes[name] = h

    # What lvm2 says: a volume is readable when its segments are linear and
    # their extents follow one another on one partition.
    parts = {p["node"][-1]: p["start"] * SECTOR
             for p in report["parts"]["partitiontable"]["partitions"]}
    pe_start = {pv["pv_name"][-1]: int(pv["pe_start"].rstrip("B")) for pv in report["pvs"]["report"][0]["pv"]}
    segs = collections.defaultdict(list)
    hidden = collections.defaultdict(list)
    for s in report["segments"]["report"][0]["seg"]:
        if not s["lv_name"].startswith("["):        # lvs -a shows a hidden volume in brackets
            segs[s["lv_name"]].append(s)
        else:
            hidden[s["lv_name"].strip("[]")].append(s)
    # A RAID1 volume is read from its first copy: lvm2's report lists its copies
    # as its ranges, and each copy's own extents under the copy's name.
    for lv, ss in segs.items():
        if [x["segtype"] for x in ss] == ["raid1"]:
            first = ss[0]["seg_pe_ranges"].split()[0].split(":")[0]
            segs[lv] = [dict(x, lv_name=lv) for x in hidden[first]]
    want, declined, mapped = set(), set(), {}
    for lv, ss in segs.items():
        ext = int(ss[0]["vg_extent_size"].rstrip("B"))
        ss.sort(key=lambda s: int(s["seg_start_pe"]))
        runs = [r for s in ss for r in s["seg_pe_ranges"].split()]
        pvs = {r.split(":")[0][-1] for r in runs}
        spans = [tuple(int(x) for x in r.split(":")[1].split("-")) for r in runs]
        joined = all(spans[i][1] + 1 == spans[i + 1][0] for i in range(len(spans) - 1))
        if all(s["segtype"] == "linear" for s in ss) and len(pvs) == 1 and joined:
            pv = pvs.pop()
            want.add((f"LVM fixvg/{lv}", parts[pv] + pe_start[pv] + spans[0][0] * ext,
                      (spans[-1][1] - spans[0][0] + 1) * ext))
        else:
            declined.add(lv)
            if all(s["segtype"] in ("linear", "striped") for s in ss):
                # Where lvm2 says its extents are, as image byte ranges.
                mapped[lv] = sorted((parts[r.split(":")[0][-1]] + pe_start[r.split(":")[0][-1]]
                                     + a * ext, (b - a + 1) * ext)
                                    for r in runs for a, b in [tuple(int(x) for x in
                                                                     r.split(":")[1].split("-"))])
    fh = io.BytesIO(disk)
    regions = partition_regions(fh, len(disk))[0]
    found, notes = lvm_volumes(fh, [r for r in regions if not r[0].startswith("MBR")])
    got = {(lab, b, n) for lab, b, n, _name in found}
    out.append((f"the logical volumes read from lvm-fixture are the ones lvm2's own report "
                f"lays out as one run on one physical volume, at the offsets and sizes it gives "
                f"({len(got)} of {len(want)})", got == want and len(want) == 5))
    lines = [ln for ls in notes.values() for ln in ls]
    not_read = {ln.split()[2].rstrip(",") for ln in lines if ": not read (" in ln}
    reasons = " ".join(ln for ln in lines if ": not read (" in ln)
    here = " ".join(ln for ln in lines if ": not read here (" in ln)
    out.append(("without lvm_image(), the volumes lvm2 split into two runs or striped are not "
                "read here and say how they are laid out, and the RAID1 one is read from its "
                "first copy", declined == {"data", "striped"} and not_read == set() and not reasons
                and "in 2 separate runs of extents" in here
                and "striped across 2 physical volumes in 64.0 KiB stripes" in here
                and any("logical volume mirror, " in ln and "raid1, read from its copy mirror_rimage_0" in ln
                        for ln in lines)))

    # Through lvm_image() the split and the striped volume are read, each
    # through a map that puts every byte where lvm2's report says its extents
    # are; their bases are past the image's end, where nothing on the disk is.
    wfh = lvm_image(io.BytesIO(disk), len(disk))
    wfound, wnotes = lvm_volumes(wfh, [r for r in regions if not r[0].startswith("MBR")])
    placed = {lab.split("/")[1]: (b, n) for lab, b, n, _name in wfound if b >= len(disk)}
    def covered(lmap):
        spans = sorted(lmap.image_runs(0, lmap.size))
        merged = []
        for at, n in spans:
            if merged and merged[-1][0] + merged[-1][1] == at:
                merged[-1] = (merged[-1][0], merged[-1][1] + n)
            else:
                merged.append((at, n))
        return merged
    maps_ok = set(placed) == set(mapped) == {"data", "striped"} and all(
        covered(wfh.lvm_map_for(placed[lv][0])) == mapped[lv] for lv in mapped)
    sm = wfh.lvm_map_for(placed["striped"][0]) if "striped" in placed else None
    out.append(("through lvm_image() the split and the striped volume are read, their maps "
                "covering exactly the extents lvm2's report gives each, the striped one in the "
                "64 KiB stripes make_lvm_fixtures.sh asks lvm2 for",
                maps_ok and sm is not None and sm.segments[0][2] == 64 << 10
                and sm.image_runs(0, 64 << 10) == [(mapped["striped"][0][0], 64 << 10)]
                and sm.image_runs(64 << 10, 64 << 10) == [(mapped["striped"][1][0], 64 << 10)]
                and {(a, b, c) for a, b, c, _n in wfound if b < len(disk)} == want))
    wlines = [ln for ls in wnotes.values() for ln in ls]
    out.append(("then no volume is listed as not read",
                not any(": not read" in ln for ln in wlines)))
    out.append(("the mirror's hidden image and metadata legs are not listed as volumes, though "
                "each is one run on one physical volume",
                not any(ln.startswith("logical volume mirror_r") for ln in lines)
                and not any("rimage" in f[0] or "rmeta" in f[0] for f in found)))
    pv_notes = [v.get("note", "") for v in volumes(io.BytesIO(disk), len(disk)) if v["kind"] == "lvm2 pv"]
    out.append(("no physical volume's note in volumes() names a volume as not read, when every "
                "one is read", len(pv_notes) == 2 and not any("not read" in n for n in pv_notes)))
    out.append(("both physical volumes name the volume group and both of its physical volumes",
                sum("2 of them in this image" in ln for ln in lines) == 2))

    def walk_hashes(w, node, path=""):
        for name, child in w.listdir(node):
            if name in (".", "..", "lost+found"):
                continue
            mode, size = w.entry(child)[:2]
            rel = f"{path}/{name}" if path else name
            if mode & S_IFMT == S_IFDIR:
                yield from walk_hashes(w, child, rel)
            elif mode & S_IFMT == S_IFREG:
                yield rel, hashlib.sha256(b"".join(w.read_file(child, size))).hexdigest()

    for img, tree in ((disk, {"LVM fixvg/root": "root", "LVM fixvg/onb": "onb",
                              "LVM fixvg/data": "data", "LVM fixvg/striped": "striped",
                              "LVM fixvg/mirror": "mirror"}),
                      (whole, {"LVM wholevg/root": "root"})):
        vols = volumes(io.BytesIO(img), len(img))
        seen = {v["label"] for v in vols}
        out.append((f"volumes() lists {', '.join(sorted(tree))} with a walker",
                    all(any(v["label"] == lab and v.get("walker") for v in vols) for lab in tree)
                    and set(tree) <= seen))
        for v in vols:
            if v["label"] not in tree:
                continue
            top = tree[v["label"]]
            try:
                gotf = {f"{top}/{p}": h for p, h in walk_hashes(v["walker"], v["walker"].root)}
            except Exception:                        # pylint: disable=broad-except
                gotf = {}
            wantf = {k: h for k, h in hashes.items() if k.startswith(top + "/")}
            out.append((f"every file of {v['label']} ({v['kind']}) matches what sha256sum "
                        f"recorded over its source tree ({len(gotf)} of {len(wantf)})",
                        bool(wantf) and gotf == wantf))

    # The report main() prints names each logical volume read, with its kind.
    import shutil
    import tempfile
    tmp = tempfile.mkdtemp(prefix="qnxprobe-lvm-")       # the form the CI fixture step replaces
    try:
        path = os.path.join(tmp, "lvm-fixture.img")
        with open(path, "wb") as f:
            f.write(disk)
        buf = io.StringIO()
        records = []
        with zipfile.ZipFile(io.BytesIO(), "w") as zmem, contextlib.redirect_stdout(buf):
            main(path, extract="(memory)", zf=zmem, manifest=records)
        text = buf.getvalue()
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    by_vol = {r.get("volume", ""): r for r in records}
    rec_data = next((r for v, r in by_vol.items() if "_fixvg_data" in v), {})
    rec_root = next((r for v, r in by_vol.items() if "_fixvg_root" in v), {})
    out.append(("volumes.json gives a volume read through a map no offset or LBA, and the image "
                "offset of each of its runs where lvm2's report puts them",
                rec_data.get("offset_bytes", 0) is None and rec_data.get("lba", 0) is None
                and [(m["image_offsets"][0], m["length"]) for m in rec_data.get("lvm_map", [])]
                == mapped.get("data")
                and rec_root.get("offset_bytes") == [b for lab, b, _n in want if lab == "LVM fixvg/root"][0]
                and "lvm_map" not in rec_root))
    out.append(("the report lists each logical volume read, identified as ext4 where it is, "
                "and gives the runs of the split one where lvm2's report puts them",
                all(f"{lab}   " in text for lab, _b, _n in want)
                and "LVM fixvg/root   6.0 MiB   ->  ext4" in text
                and "LVM fixvg/data   6.0 MiB   ->  ext4" in text
                and "LVM fixvg/striped   4.0 MiB   ->  ext4" in text
                and ", ".join(f"{n:,} bytes at {o:,}" for o, n in mapped.get("data", [])) in text
                and "->  lvm2 pv" in text))

    # Free space: each physical volume's extents no logical volume holds, hidden
    # ones included, are written at their own offsets; and a reader's free runs
    # inside a volume read through a map become the runs of the image they are.
    # lvm2 sizes a physical volume as (its size - pe_start) / extent size extents.
    top = tempfile.mkdtemp(prefix="qnxprobe-lvm-")
    # A folder of its own: the build workflow keeps the self-test's temp folder
    # and counts the images in it, and these .bin files are not images.
    tmp = os.path.join(top, "unallocated")
    os.makedirs(tmp, exist_ok=True)
    try:
        fvols = volumes(io.BytesIO(disk), len(disk))
        ext_b = 1 << 20
        spare_want = {}
        for pv in ("1", "2"):
            part = [p for p in report["parts"]["partitiontable"]["partitions"] if p["node"][-1] == pv][0]
            count = (part["size"] * SECTOR - pe_start[pv]) // ext_b
            taken = set()
            for sg in report["segments"]["report"][0]["seg"]:
                for r in sg["seg_pe_ranges"].split():
                    if r.split(":")[0].endswith("p" + pv):
                        a, b = (int(x) for x in r.split(":")[1].split("-"))
                        taken.update(range(a, b + 1))
            free = [e for e in range(count) if e not in taken]
            spare_want[parts[pv]] = sorted({(parts[pv] + pe_start[pv] + e * ext_b, ext_b) for e in free})
        striped_vol = [v for v in fvols if v["label"] == "LVM fixvg/striped"][0]

        class _Free:                                   # a reader that reports two chunks free
            def free_extents(self):
                return [(striped_vol["base"], 128 << 10)]
        recs = write_unallocated(io.BytesIO(disk), len(disk),
                                 [v for v in fvols if v["kind"] == "lvm2 pv"]
                                 + [dict(striped_vol, walker=_Free(), name="striped_free")],
                                 tmp, "lvm-fixture.img", say=lambda *a: None)
        maps = {}
        for name in os.listdir(tmp):
            if name.endswith(".tsv"):
                rows = open(os.path.join(tmp, name), encoding="utf-8").read().splitlines()[1:]
                maps[name] = [tuple(int(x) for x in r.split("\t")[1:]) for r in rows]
        def merged(runs):
            out_ = []
            for at, n in sorted(runs):
                if out_ and out_[-1][0] + out_[-1][1] == at:
                    out_[-1] = (out_[-1][0], out_[-1][1] + n)
                else:
                    out_.append((at, n))
            return out_
        pv_ok = all(merged(maps.get(f"lvm-fixture.img.{v['name']}.unallocated.tsv", []))
                    == merged(spare_want[v["base"]])
                    for v in fvols if v["kind"] == "lvm2 pv")
        stripe_ok = maps.get("lvm-fixture.img.striped_free.unallocated.tsv") == [
            (mapped["striped"][0][0], 64 << 10), (mapped["striped"][1][0], 64 << 10)]
        out.append(("free space: each physical volume's unallocated extents, as lvm2's report "
                    "leaves them, and a mapped volume's free runs at their places in the image",
                    pv_ok and stripe_ok and any(spare_want.values())
                    and all(r.get("offset_bytes") is None and r.get("lvm_map") == striped_vol["lvm_map"].describe()
                            for r in recs if r["volume"] == "striped_free")))
    finally:
        shutil.rmtree(top, ignore_errors=True)

    # Metadata that wraps past the end of its area continues just after the
    # area's header (format-text.c). Move the first PV's text to straddle the end.
    pv_at = parts["1"]
    mda = struct.unpack_from("<QQ", disk, pv_at + SECTOR + 32 + 40 + 16 * 2)
    m_off, m_size = mda
    head = bytearray(disk[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE])
    r_off, r_size, csum, flags = struct.unpack_from("<QQII", head, 40)
    text_b = disk[pv_at + m_off + r_off:pv_at + m_off + r_off + r_size]
    wrapped = bytearray(disk)
    new_off = m_size - r_size // 2
    first = m_size - new_off
    wrapped[pv_at + m_off + new_off:pv_at + m_off + m_size] = text_b[:first]
    wrapped[pv_at + m_off + LVM_MDA_HEADER_SIZE:pv_at + m_off + LVM_MDA_HEADER_SIZE + r_size - first] = text_b[first:]
    struct.pack_into("<QQII", head, 40, new_off, r_size, csum, flags)
    struct.pack_into("<I", head, 0, lvm_crc(bytes(head[4:])))
    wrapped[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE] = head
    try:
        wpv = LvmPv(io.BytesIO(bytes(wrapped)), pv_at)
        wrap_ok = wpv.vg is not None and wpv.vg[0] == "fixvg" and not wpv.problems
    except ValueError:
        wrap_ok = False
    out.append(("metadata text that wraps past the end of its area is read from the area's "
                "start, just after its header", wrap_ok))

    # A damaged copy on one physical volume: the other's copy still gives the
    # volume group, and the damage is said.
    bad = bytearray(disk)
    bad[pv_at + m_off + r_off + 10] ^= 0xFF
    bfound, bnotes = lvm_volumes(io.BytesIO(bytes(bad)), [r for r in regions if not r[0].startswith("MBR")])
    out.append(("a metadata copy whose checksum fails is reported, and the other physical "
                "volume's copy still gives every volume",
                {(a, b, c) for a, b, c, _n in bfound} == want
                and any("metadata text checksum does not match" in ln for ln in bnotes[pv_at])))
    # An older copy of the metadata (a lower seqno, without the volume onb) on
    # either physical volume: the newest copy, on the other, decides, whichever
    # of the two is read first.
    for which in ("1", "2"):
        older = _lvm_older_copy(disk, parts[which], m_off)
        ofound, _on = lvm_volumes(io.BytesIO(older), [r for r in regions if not r[0].startswith("MBR")])
        spv = LvmPv(io.BytesIO(older), parts[which])
        out.append((f"an older metadata copy (seqno 1, without onb) on physical volume {which} "
                    "gives way to the newest on the other",
                    spv.vg is not None and spv.vg[2] == 1
                    and {(a, b, c) for a, b, c, _n in ofound} == want))
    # A physical volume never added to a volume group has an area with no
    # metadata in it: no volume group, and nothing wrong to report.
    empty = bytearray(disk)
    eh = bytearray(disk[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE])
    eh[40:64] = bytes(24)
    struct.pack_into("<I", eh, 0, lvm_crc(bytes(eh[4:])))
    empty[pv_at + m_off:pv_at + m_off + LVM_MDA_HEADER_SIZE] = eh
    epv = LvmPv(io.BytesIO(bytes(empty)), pv_at)
    out.append(("a physical volume whose metadata area holds nothing yet has no volume group "
                "and no problem", epv.vg is None and not epv.problems))
    try:
        lvm_config("a = 1\n;")
        junk_ok = False
    except ValueError:
        junk_ok = True
    out.append(("text left over that is no token is refused, not dropped", junk_ok))
    out.append(("a comment after a value, its last word a number, is not read as a value",
                lvm_config('a = 1\t# Wed Oct 14 10:00:31 2026\nb {\nc = "x" # 7\n}\n')
                == {"a": 1, "b": {"c": "x"}}))
    out.append(("a volume whose segments leave a gap in it is not read",
                _lvm_layout([{"type": "striped", "stripe_count": 1, "start_extent": 0,
                                  "extent_count": 2, "stripes": ["pv0", 0]},
                                 {"type": "striped", "stripe_count": 1, "start_extent": 3,
                                  "extent_count": 1, "stripes": ["pv0", 2]}],
                                {"pv0": (0, 0, 0)}, {"pv0"}, 1 << 20)[0]
                == "its segments leave a gap in the volume"))
    return out + _lvm_hostile_checks(disk, whole, regions, want, paths, parts, m_off, r_off)


def _btrfs_find_item(w, tree, key):
    """(leaf logical address, item header offset, data offset, data size) of
    the item with exactly ``key`` in ``tree``, found by descending from the
    tree's root; for the self-test, which edits items in place."""
    if tree == BTRFS_ROOT_TREE_OBJECTID:
        bytenr, level = w.sb["root"], w.sb["root_level"]
    else:
        r = w.root_item(tree)
        bytenr, level = r["bytenr"], r["level"]
    while True:
        buf = w._block(bytenr)                                  # pylint: disable=protected-access
        n = struct.unpack_from("<I", buf, 96)[0]
        if level == 0:
            for i in range(n):
                o = BTRFS_HEADER_SIZE + i * BTRFS_ITEM_SIZE
                if _btrfs_key(buf, o) == key:
                    ioff, isz = struct.unpack_from("<II", buf, o + 17)
                    return bytenr, o, BTRFS_HEADER_SIZE + ioff, isz
            raise KeyError(key)
        child = None
        for i in range(n):
            o = BTRFS_HEADER_SIZE + i * BTRFS_KEY_PTR_SIZE
            if _btrfs_key(buf, o) <= key:
                child = struct.unpack_from("<Q", buf, o + 17)[0]
        if child is None:
            raise KeyError(key)
        bytenr, level = child, level - 1


def _btrfs_edit_block(raw, w, logical, fn):
    """Apply ``fn`` to every copy of the tree block at ``logical`` in the
    bytearray ``raw`` and write a checksum that holds over the result, so the
    edit reaches the reader's later checks rather than stopping at the first."""
    for phys, _room in w.copies(logical):
        blk = bytearray(raw[phys:phys + w.nodesize])
        fn(blk)
        cs = btrfs_csum(w.csum_type, bytes(blk[32:]))
        blk[:len(cs)] = cs
        raw[phys:phys + w.nodesize] = blk


def _btrfs_self_checks():
    """[(label, passed or None for a skip)] for the Btrfs reader, from the
    images mkfs.btrfs, btrfs-convert and the kernel wrote
    (tools/make_btrfs_fixtures.sh, tools/make_btrfs_root_fixtures.sh),
    sha256sum and lstat() over the source trees, the hash of the ext4 image
    before it was converted, the volume's own free space tree, and copies of
    those images changed in memory to break one rule each. Each group of
    checks runs on its own, so one that raises is one FAIL that names the
    exception and the rest still run."""
    import gzip
    import hashlib
    import io
    import zlib                                                 # pylint: disable=import-outside-toplevel
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    variants = ("none", "zlib", "zstd", "lzo", "xxhash", "sha256", "blake2")
    need = ([f"btrfs-{v}.img.gz" for v in variants]
            + ["btrfs-convert.img.gz", "btrfs-convert.sha256", "btrfs-raid1-dev2.img.gz",
               "btrfs.src.sha256", "btrfs.src.json"])
    absent = [n for n in need if not os.path.isfile(os.path.join(here, n))]
    if absent:
        return [(f"the Btrfs fixtures are not beside this script ({', '.join(absent)}), so the "
                 "Btrfs reader was not checked against them", None)]
    out = []
    zstd_ok = _zstd_module() is not None

    def sums(name):
        got = {}
        with open(os.path.join(here, name), encoding="utf-8") as fh:
            for line in fh:
                if line.strip():
                    h, rel = line.rstrip("\n").split("  ", 1)
                    got[rel] = h
        return got

    def load(name):
        with gzip.open(os.path.join(here, name), "rb") as gz:
            return gz.read()

    def walk(raw):
        w = BtrfsWalker(io.BytesIO(bytes(raw)), 0)
        return w, {p: (node, mode, sz, mt) for p, node, mode, sz, mt, _r in walk_all(w)}

    def section(name, fn):
        try:
            fn()
        except Exception as exc:                                # pylint: disable=broad-except
            out.append((f"the Btrfs checks of {name} ran ({type(exc).__name__}: {exc})", False))

    want = sums("btrfs.src.sha256")
    with open(os.path.join(here, "btrfs.src.json"), encoding="utf-8") as fh:
        listing = json.load(fh)
    none_raw = load("btrfs-none.img.gz")

    # Known values for the two checksums carried as pure Python: the CRC-32C
    # check value of "123456789" from the CRC catalogue (0xE3069283), and
    # XXH64 of nothing with seed 0 from xxHash's own sanity table.
    out.append(("crc32c and xxhash64 give their published check values",
                btrfs_crc32c(b"123456789") ^ 0xFFFFFFFF == 0xE3069283
                and btrfs_xxh64(b"") == 0xEF46DB3751D8E999))

    def variant(v):
        raw = load(f"btrfs-{v}.img.gz")
        img = io.BytesIO(raw)
        kind = (identify_fs(img, 0, len(raw)) or (None,))[0]
        w = walker_for(kind, img, 0, len(raw)) if kind == "btrfs" else None
        if w is None:
            out.append((f"btrfs-{v}: identified as btrfs (got {kind})", False))
            return
        got = {p: (node, mode, sz, mt) for p, node, mode, sz, mt, _r in walk_all(w)}
        bad = []
        for e in listing:
            g = got.get(e["path"])
            why = None
            if g is None:
                why = "missing"
            elif g[1] != e["mode"]:
                why = f"mode {g[1]:o}, not {e['mode']:o}"
            elif e["type"] == "file" and g[2] != e["size"]:
                why = f"size {g[2]}, not {e['size']}"
            elif g[3] != e["mtime"]:
                why = f"mtime {g[3]}, not {e['mtime']}"
            elif e["type"] == "symlink" and w.readlink(g[0]) != e["target"]:
                why = "symlink target"
            if why:
                bad.append(f"{e['path'][:40]}: {why}")
        extra = sorted(set(got) - {e["path"] for e in listing})
        out.append((f"btrfs-{v}: all {len(listing)} entries listed with the type, permission "
                    "bits, size, mtime and symlink target lstat() recorded at the source, and "
                    "nothing else" + (f" ({len(bad)} differ, e.g. {bad[:2]}; extra {extra[:2]})"
                                      if bad or extra else ""), not bad and not extra))
        if v == "zstd" and not zstd_ok:
            out.append(("btrfs-zstd: files read back (this Python has no zstd; 3.14 adds "
                        "compression.zstd)", None))
            out.append(("btrfs-zstd: the note says zstd cannot be read on this Python",
                        "zstd" in (w.note or "")))
        else:
            match = 0
            for rel, digest in want.items():
                g = got.get(rel)
                if g is None:
                    continue
                try:
                    data = b"".join(w.read_file(g[0], g[2]))
                except (BtrfsUnreadable, DecompressError):
                    continue
                if len(data) == g[2] and hashlib.sha256(data).hexdigest() == digest:
                    match += 1
            out.append((f"btrfs-{v}: every regular file reads back with the sha256 sha256sum "
                        f"recorded over the source ({match} of {len(want)})", match == len(want)))
        out.append((f"btrfs-{v}: no tree block failed its checks", not w.damage))
        fst = w.free_space_tree()
        out.append((f"btrfs-{v}: the space free_logical() finds free from the extent tree is "
                    "the space the volume's own free space tree records",
                    fst is not None and w.free_logical() == fst))

    for v in variants:
        section(f"btrfs-{v}", lambda v=v: variant(v))

    def lzo_paths():
        w = BtrfsWalker(io.BytesIO(load("btrfs-lzo.img.gz")), 0)
        items = list(w._tree_items(BTRFS_FS_TREE_OBJECTID, (0, 0, 0), _BTRFS_KEY_MAX))  # pylint: disable=protected-access
        exts = [w._extent(d, k[2]) for k, d in items if k[1] == BTRFS_EXTENT_DATA_KEY]  # pylint: disable=protected-access
        out.append(("btrfs-lzo holds LZO-compressed regular and inline extents, uncompressed "
                    "ones, and INODE_EXTREF items, so each of those paths was read",
                    any(e["compression"] == 2 and e["type"] == 1 for e in exts)
                    and any(e["compression"] == 2 and e["type"] == 0 for e in exts)
                    and any(e["compression"] == 0 and e["type"] == 1 for e in exts)
                    and any(k[1] == BTRFS_INODE_EXTREF_KEY for k, _d in items)))
    section("btrfs-lzo extent kinds", lzo_paths)

    def links_and_space():
        w = BtrfsWalker(io.BytesIO(none_raw), 0)
        got = {p: node for p, node, *_r in walk_all(w)}
        # Hard links: every name of one source inode is one node, and the
        # inode's own refs (INODE_REF and INODE_EXTREF) name exactly those paths.
        groups = collections.defaultdict(list)
        for e in listing:
            if e["type"] == "file" and e["nlink"] > 1:
                groups[e["ino"]].append(e["path"])
        dirs = {"": w.root}
        dirs.update({p: n for p, n in got.items() if p in {e["path"] for e in listing
                                                           if e["type"] == "dir"}})
        by_ino = {n & _M64: p for p, n in dirs.items() if n >> 64 == BTRFS_FS_TREE_OBJECTID}
        hl_ok = bool(groups)
        for paths in groups.values():
            nodes = {got.get(p) for p in paths}
            if len(nodes) != 1 or None in nodes:
                hl_ok = False
                continue
            named = sorted(((by_ino.get(parent, "?") + "/" if by_ino.get(parent, "?") else "")
                            + name.decode("utf-8", "surrogateescape"))
                           for parent, name in w.links(nodes.pop()))
            hl_ok = hl_ok and named == sorted(paths)
        out.append((f"btrfs-none: each of the {len(groups)} hard-linked inodes is one node under "
                    "all its names, and its INODE_REF and INODE_EXTREF items name exactly those "
                    "paths", hl_ok))
        # times(): mkfs.btrfs --rootdir stores seconds only, and no creation
        # time (mkfs/rootdir.c:288-295); btrfs-live, which the kernel wrote,
        # checks the nanoseconds.
        ns = [e for e in listing if e["mtime_ns"]]
        ns_ok = bool(ns) and all(w.times(got[e["path"]]) is not None
                                 and w.times(got[e["path"]])["modified"] == (e["mtime"], 0)
                                 and w.times(got[e["path"]])["created"] == (0, 0) for e in ns)
        out.append((f"btrfs-none: times() gives the modification second lstat() recorded, with "
                    f"the 0 nanoseconds and 0 creation time mkfs.btrfs --rootdir writes ({len(ns)} "
                    "entry set to the nanosecond at the source)", ns_ok))
        # Free space: nothing reported free overlaps a byte a file's extent
        # occupies; the unallocated total is what the superblock's device item
        # leaves.
        fe = w.free_extents()
        used = []
        for rel, node in got.items():
            for _off, fx_ext in (w.extents(node) if rel in want else []):
                if fx_ext["type"] != BTRFS_FILE_EXTENT_INLINE and fx_ext["disk_bytenr"]:
                    for phys, _room in w.copies(fx_ext["disk_bytenr"]):
                        used.append((phys, phys + fx_ext["disk_num_bytes"]))
        starts = [s for s, _n in fe]
        clash = 0
        for a, b in used:
            i = bisect.bisect_right(starts, a) - 1
            for s, n in fe[max(i, 0):max(i, 0) + 2]:
                if s < b and a < s + n:
                    clash += 1
        un = sum(n for _s, n in w.unallocated())
        expect = w.sb["dev_total"] - w.sb["dev_used"] - BTRFS_RESERVED_1M - sum(
            BTRFS_SUPER_SIZE for m in BTRFS_SUPER_MIRRORS[1:] if m < w.sb["dev_total"]
            and not any(phys <= m < phys + ch["length"] for ch in w.chunks.values()
                        for _d, phys in ch["stripes"]))
        out.append((f"btrfs-none: no free run overlaps any of the {len(used)} data extents, and "
                    "the unallocated space is the device size less what its device item records "
                    "used", bool(used) and clash == 0 and un == expect))
    section("btrfs-none hard links, times and free space", links_and_space)

    def superblocks():
        w = BtrfsWalker(io.BytesIO(none_raw), 0)
        # A broken first copy of a DUP tree block is read from the second and
        # recorded; both copies broken leaves an empty listing, not a crash.
        fs = w.root_item(BTRFS_FS_TREE_OBJECTID)
        c1, c2 = [p for p, _r in w.copies(fs["bytenr"])]
        bad1 = bytearray(none_raw)
        bad1[c1 + 200] ^= 0xFF
        w1, l1 = walk(bad1)
        bad1[c2 + 200] ^= 0xFF
        w2, l2 = walk(bad1)
        out.append(("btrfs-none: a tree block whose first copy fails its checksum is read from "
                    "its DUP copy and the repair recorded; with both copies broken the walk "
                    "lists nothing and records why",
                    len(l1) == len(listing) and any("read from the copy" in d for d in w1.damage)
                    and not l2 and any("checksum does not hold" in d for d in w2.damage)))

        def resum(buf, at):
            cs = btrfs_csum(w.csum_type, bytes(buf[at + 32:at + BTRFS_SUPER_SIZE]))
            buf[at:at + len(cs)] = cs
        mirror = BTRFS_SUPER_MIRRORS[1]
        # The primary's checksum fails: the mirror at 64 MiB is read, and said.
        bad_sb = bytearray(none_raw)
        bad_sb[BTRFS_SUPER_OFF + 300] ^= 0x01
        k_sb, lines_sb = identify_fs(io.BytesIO(bytes(bad_sb)), 0, len(bad_sb))
        out.append(("btrfs-none: a primary superblock whose checksum fails is passed over for the "
                    "mirror at 64 MiB, and the report says so",
                    k_sb == "btrfs" and any("mirror at 0x4000000" in ln for ln in lines_sb)))
        # A good primary is used even when a mirror records a later generation.
        newer = bytearray(none_raw)
        struct.pack_into("<Q", newer, mirror + 72, w.sb["generation"] + 5)
        resum(newer, mirror)
        pick, _f, _why = _btrfs_pick_super(io.BytesIO(bytes(newer)), 0)
        # ...and among mirrors, when the primary fails, the newer one is taken.
        newer[BTRFS_SUPER_OFF + 300] ^= 0x01
        pick2, _f2, _why2 = _btrfs_pick_super(io.BytesIO(bytes(newer)), 0)
        out.append(("btrfs-none: a primary superblock that holds is used though a mirror "
                    "records a later generation; with the primary broken, the mirror is used",
                    pick is not None and pick["at"] == BTRFS_SUPER_OFF
                    and pick2 is not None and pick2["at"] == mirror))

        # All three copies, on a sparse stand-in for a device of more than
        # 256 GiB: with the primary broken the good copy of the highest
        # generation is taken, and a copy with another fsid is not, however
        # new it is (disk-io.c:1974-2014).
        class Sparse:
            def __init__(self, parts):
                self.parts, self.pos = parts, 0

            def seek(self, pos, _whence=0):
                self.pos = pos

            def read(self, n):
                for at, blob in self.parts.items():
                    if at <= self.pos < at + len(blob):
                        return blob[self.pos - at:self.pos - at + n]
                return bytes(n)
        sbs = {}
        for at, gen in ((BTRFS_SUPER_OFF, w.sb["generation"]),
                        (mirror, w.sb["generation"] + 1),
                        (BTRFS_SUPER_MIRRORS[2], w.sb["generation"] + 2)):
            blob = bytearray(none_raw[BTRFS_SUPER_OFF:BTRFS_SUPER_OFF + BTRFS_SUPER_SIZE])
            struct.pack_into("<QQ", blob, 48, at, struct.unpack_from("<Q", blob, 56)[0])
            struct.pack_into("<Q", blob, 72, gen)
            resum(blob, 0)
            sbs[at] = blob
        sbs[BTRFS_SUPER_OFF][300] ^= 0x01                       # the primary fails
        three, _f3, _w3 = _btrfs_pick_super(Sparse({k: bytes(v) for k, v in sbs.items()}), 0)
        other = bytearray(sbs[BTRFS_SUPER_MIRRORS[2]])
        other[32] ^= 0x01                                       # another fsid
        resum(other, 0)
        sbs[BTRFS_SUPER_MIRRORS[2]] = other
        fsid_pick, _f4, _w4 = _btrfs_pick_super(Sparse({k: bytes(v) for k, v in sbs.items()}), 0)
        out.append(("with the primary superblock broken, the mirror of the highest generation "
                    "is taken, and not one carrying another fsid",
                    three is not None and three["at"] == BTRFS_SUPER_MIRRORS[2]
                    and fsid_pick is not None and fsid_pick["at"] == mirror))
        # The magic alone does not make a volume Btrfs: a broken primary with
        # no mirror that holds is not claimed, and neither is a device whose
        # primary has no magic though a mirror holds.
        both = bytearray(none_raw)
        both[BTRFS_SUPER_OFF + 300] ^= 0x01
        both[mirror + 300] ^= 0x01
        nomagic = bytearray(none_raw)
        nomagic[BTRFS_SUPER_OFF + 64:BTRFS_SUPER_OFF + 72] = bytes(8)
        bare = bytearray(1 << 20)
        bare[BTRFS_SUPER_OFF + 64:BTRFS_SUPER_OFF + 72] = BTRFS_MAGIC
        out.append(("Btrfs is claimed only with a superblock whose checksum holds: not on the "
                    "magic alone, not on a broken primary with no good mirror, not on mirrors "
                    "behind a primary with no magic",
                    identify_btrfs(io.BytesIO(bytes(both)), 0) is None
                    and identify_btrfs(io.BytesIO(bytes(nomagic)), 0) is None
                    and identify_btrfs(io.BytesIO(bytes(bare)), 0) is None))
        # A whole superblock whose checksum holds, where its filesystem is
        # not (copied into an image of something else), is not claimed; an
        # image cut short of the chunk tree is still named.
        graft = bytearray(len(none_raw) // 2)          # holds where the chunk tree was
        graft[BTRFS_SUPER_OFF:BTRFS_SUPER_OFF + BTRFS_SUPER_SIZE] = \
            none_raw[BTRFS_SUPER_OFF:BTRFS_SUPER_OFF + BTRFS_SUPER_SIZE]
        cut = identify_btrfs(io.BytesIO(none_raw[:2 << 20]), 0)
        out.append(("a Btrfs superblock copied where its filesystem is not is not claimed; an "
                    "image cut short of the chunk tree is",
                    identify_btrfs(io.BytesIO(bytes(graft)), 0) is None
                    and cut is not None and any("not possible" in ln for ln in cut[1])))
    section("superblocks and DUP copies", superblocks)

    def tree_checks():
        # Each of these breaks one rule in a tree block, with the checksum
        # rewritten so the block passes that check and reaches the one under
        # test. Each must be recorded as damage, and none may stop the walk.
        w0 = BtrfsWalker(io.BytesIO(none_raw), 0)
        fs = w0.root_item(BTRFS_FS_TREE_OBJECTID)
        root = w0._block(fs["bytenr"])                          # pylint: disable=protected-access
        c0, g0 = struct.unpack_from("<QQ", root, BTRFS_HEADER_SIZE + 17)
        ptr1 = BTRFS_HEADER_SIZE + BTRFS_KEY_PTR_SIZE
        cases = {
            # child 1 points at the node itself: one level too high
            "level": (fs["bytenr"], lambda b: struct.pack_into(
                "<QQ", b, ptr1 + 17, fs["bytenr"], struct.unpack_from("<Q", b, 80)[0])),
            # child 0's generation in its parent is one off
            "generation": (fs["bytenr"], lambda b: struct.pack_into(
                "<Q", b, BTRFS_HEADER_SIZE + 25, g0 + 1)),
            # child 1 points at child 0, whose first key is not the one named
            "starts at key": (fs["bytenr"], lambda b: struct.pack_into(
                "<QQ", b, ptr1 + 17, c0, g0)),
            # a leaf of this volume that names another filesystem
            "another filesystem": (c0, lambda b: b.__setitem__(slice(32, 48), bytes(16))),
            # a leaf that claims more items than fit
            "more than fit": (c0, lambda b: struct.pack_into("<I", b, 96, 0xFFFFFFFF)),
        }
        for want_text, (target, fn) in cases.items():
            raw = bytearray(none_raw)
            _btrfs_edit_block(raw, w0, target, fn)
            w, got = walk(raw)
            hit = any(want_text in d for d in w.damage)
            out.append((f"btrfs-none: a tree block that breaks one rule ({want_text}) is "
                        f"recorded as damage and the walk goes on ({len(got)} of "
                        f"{len(listing)} entries)", hit))
        # The cache does not excuse a block from its parent's checks: a block
        # read once as level 1 is refused when asked for as a leaf.
        w = BtrfsWalker(io.BytesIO(none_raw), 0)
        w._block(fs["bytenr"], fs["level"])                     # pylint: disable=protected-access
        try:
            w._block(fs["bytenr"], 0)                           # pylint: disable=protected-access
            cached_ok = False
        except BtrfsUnreadable:
            cached_ok = True
        out.append(("a cached tree block is still held to the level its parent records",
                    cached_ok))
    section("tree block checks", tree_checks)

    def item_checks():
        w0, l0 = walk(none_raw)
        node = l0["a_fifo"][0]
        ino = node & _M64
        key = None
        for k, d in w0._tree_items(BTRFS_FS_TREE_OBJECTID,          # pylint: disable=protected-access
                                   (256, BTRFS_DIR_INDEX_KEY, 0), (256, BTRFS_DIR_INDEX_KEY, _M64)):
            if _btrfs_key(d, 0)[0] == ino:
                key = k
        # A DIR_INDEX that names an inode with no INODE_ITEM is still listed,
        # with its directory entry's type, and recorded.
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, BTRFS_FS_TREE_OBJECTID, key)
        _btrfs_edit_block(raw, w0, leaf, lambda b: struct.pack_into("<Q", b, do, 99999))
        w, got = walk(raw)
        out.append(("a directory entry whose inode is missing is listed with the type its entry "
                    "records, and recorded as damage",
                    got.get("a_fifo", (0, 0))[1] == BTRFS_FT_MODE[5]
                    and any("99999" in d and "a_fifo" in d for d in w.damage)
                    and len(got) == len(l0)))
        # DIR_INDEX is what is read, not DIR_ITEM: a DIR_ITEM whose name is
        # changed changes nothing listed.
        h = btrfs_crc32c(b"tiny.txt", 0xFFFFFFFE)
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, BTRFS_FS_TREE_OBJECTID,
                                              (256, BTRFS_DIR_ITEM_KEY, h))
        _btrfs_edit_block(raw, w0, leaf, lambda b: b.__setitem__(do + 30, ord("X")))
        w, got = walk(raw)
        out.append(("names are read from DIR_INDEX, not DIR_ITEM (a changed DIR_ITEM name "
                    "changes nothing listed)", "tiny.txt" in got and "Xiny.txt" not in got))
        # A subvolume's entry for itself (a snapshot taken into itself) is not
        # followed (restore.c:1034-1043).
        sub = w0.root_item(256)
        skey = None
        for k, d in w0._tree_items(256, (sub["root_dirid"], BTRFS_DIR_INDEX_KEY, 0),  # pylint: disable=protected-access
                                   (sub["root_dirid"], BTRFS_DIR_INDEX_KEY, _M64)):
            if bytes(d[30:30 + struct.unpack_from("<H", d, 27)[0]]) == b"in_subvol.txt":
                skey = k
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, 256, skey)
        _btrfs_edit_block(raw, w0, leaf, lambda b: struct.pack_into(
            "<QBQ", b, do, 256, BTRFS_ROOT_ITEM_KEY, _M64))
        w, got = walk(raw)
        out.append(("a subvolume's directory entry for itself is not listed",
                    "subvol/in_subvol.txt" not in got and "subvol/inner" in got))
        # A ROOT_REF whose name runs past its item links nothing: the
        # subvolume shows as the empty directory the kernel shows, with no
        # exception, and is recorded.
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, BTRFS_ROOT_TREE_OBJECTID,
                                              (5, BTRFS_ROOT_REF_KEY, 256))
        _btrfs_edit_block(raw, w0, leaf, lambda b: struct.pack_into("<H", b, do + 16, 4000))
        w, got = walk(raw)
        out.append(("a ROOT_REF too short for its name is recorded, and its subvolume is the "
                    "empty directory an unlinked one is",
                    "subvol" in got and "subvol/inner" not in got
                    and any("ROOT_REF" in d for d in w.damage)))
        # An uncompressed inline extent whose ram_bytes is not what it holds is
        # refused, as is an inline extent past offset 0, and a regular one off
        # a sector boundary.
        tiny = l0["tiny.txt"]
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, BTRFS_FS_TREE_OBJECTID,
                                              (tiny[0] & _M64, BTRFS_EXTENT_DATA_KEY, 0))
        _btrfs_edit_block(raw, w0, leaf, lambda b: struct.pack_into("<Q", b, do + 8, 3))
        w, got = walk(raw)
        try:
            b"".join(w.read_file(got["tiny.txt"][0], 7))
            ram_refused = False
        except BtrfsUnreadable:
            ram_refused = any("ram_bytes" in d for d in w.damage)
        inline = struct.pack("<QQBBHB", 1, 4, 0, 0, 0, 0) + b"abcd"
        reg = struct.pack("<QQBBHBQQQQ", 1, 4096, 0, 0, 0, 1, 0x100000, 4096, 100, 4096)
        item_refused = []
        for d, off in ((inline, 4096), (reg, 0), (inline[:10], 0)):
            try:
                BtrfsWalker._extent(d, off, 4096)               # pylint: disable=protected-access
                item_refused.append(False)
            except BtrfsUnreadable:
                item_refused.append(True)
        out.append(("inline extents with a wrong ram_bytes or off offset 0, a regular extent off "
                    "a sector boundary and a short extent item are refused",
                    ram_refused and all(item_refused)
                    and BtrfsWalker._extent(inline, 0, 4096)["inline"] == b"abcd"))  # pylint: disable=protected-access
        # An inode size past the largest file btrfs allows is damage.
        raw = bytearray(none_raw)
        leaf, _ho, do, _sz = _btrfs_find_item(w0, BTRFS_FS_TREE_OBJECTID,
                                              (tiny[0] & _M64, BTRFS_INODE_ITEM_KEY, 0))
        _btrfs_edit_block(raw, w0, leaf, lambda b: struct.pack_into("<Q", b, do + 16, 1 << 63))
        w, got = walk(raw)
        out.append(("an inode size past the largest file btrfs allows is recorded, and the name "
                    "still listed", got.get("tiny.txt", (0, 0, -1))[2] == 0
                    and any("largest file" in d for d in w.damage)))
    section("item checks", item_checks)

    def mapping():
        # Address mapping, on a walker with chunks set by hand over a small
        # image: the copies of a DUP chunk in stripe order, a read that crosses
        # from one chunk to the next, a RAID1 chunk read from this device's
        # copy, and a RAID0 chunk refused by name.
        disk = bytearray(1 << 20)
        for i in range(len(disk) // 4096):
            disk[i * 4096:(i + 1) * 4096] = bytes([i]) * 4096
        w = BtrfsWalker.__new__(BtrfsWalker)
        w.fh, w.base, w.devid = io.BytesIO(bytes(disk)), 0, 2
        w.chunks, w._chunk_starts = {}, []                      # pylint: disable=protected-access

        def chunk(logical, length, ctype, stripes):
            w.chunks[logical] = dict(length=length, type=ctype, stripes=stripes,
                                     stripe_len=BTRFS_STRIPE_LEN, sub_stripes=1)
            bisect.insort(w._chunk_starts, logical)             # pylint: disable=protected-access
        chunk(0x100000, 0x8000, BTRFS_BG_DATA | (1 << 5), [(2, 0x10000), (2, 0x40000)])  # DUP
        chunk(0x200000, 0x2000, BTRFS_BG_DATA, [(2, 0x80000)])                         # SINGLE
        chunk(0x202000, 0x2000, BTRFS_BG_DATA, [(2, 0x20000)])                         # SINGLE
        chunk(0x300000, 0x4000, BTRFS_BG_DATA | (1 << 4), [(1, 0x90000), (2, 0xA0000)])  # RAID1
        chunk(0x400000, 0x4000, BTRFS_BG_DATA | (1 << 3), [(1, 0), (2, 0)])            # RAID0
        dup = [p for p, _r in w.copies(0x101000)]
        cross = w.read_logical(0x201000, 0x2000)
        raid1 = w.read_logical(0x301000, 0x1000)
        try:
            w.copies(0x400000)
            striped = False
        except BtrfsUnreadable as exc:
            striped = "RAID0" in str(exc)
        out.append(("chunk mapping: DUP copies in stripe order, a read across two chunks, a "
                    "RAID1 chunk read from this device's copy, a RAID0 chunk refused by name",
                    dup == [0x11000, 0x41000]
                    and cross == bytes([0x81]) * 4096 + bytes([0x20]) * 4096
                    and raid1 == bytes([0xA1]) * 4096 and striped))
    section("chunk mapping", mapping)

    def extent_shapes():
        # Extent shapes driven through the function read_file() uses: a hole no
        # item covers (NO_HOLES), a hole item (disk_bytenr 0), a preallocated
        # extent, a regular extent read from an offset into its disk extent, a
        # zlib extent read from an offset into what it decompresses to, an
        # extent that runs past the file's size, and an encrypted extent, which
        # is refused.
        disk = bytes(range(256)) * 64                           # logical 0x10000.., 16 KiB
        plain = b"".join(b"%06d" % i for i in range(3000))      # 18,000 bytes
        comp = zlib.compress(plain)
        space = {0x10000: disk, 0x40000: comp}

        def rd(addr, n):
            for base_, buf in space.items():
                if base_ <= addr < base_ + len(buf):
                    return buf[addr - base_:addr - base_ + n]
            return b""

        def ext(typ, **kw):
            d = dict(type=typ, compression=0, encryption=0, other_encoding=0, ram_bytes=0,
                     disk_bytenr=0, disk_num_bytes=0, offset=0, num_bytes=0)
            d.update(kw)
            return d
        shapes = [
            (0, ext(1, disk_bytenr=0x10000, disk_num_bytes=16384, offset=100, num_bytes=4096,
                    ram_bytes=16384)),
            (8192, ext(1, disk_bytenr=0, num_bytes=4096)),                   # hole item
            (12288, ext(2, disk_bytenr=0x10000, disk_num_bytes=16384, num_bytes=4096)),
            (16384, ext(1, compression=1, disk_bytenr=0x40000, disk_num_bytes=len(comp),
                        ram_bytes=len(plain), offset=600, num_bytes=12000)),
            (28384, ext(1, disk_bytenr=0x10000, disk_num_bytes=16384, num_bytes=16384,
                        ram_bytes=16384)),
        ]
        isize = 28384 + 1000
        expect = (disk[100:4196] + bytes(4096) + bytes(4096) + bytes(4096)
                  + plain[600:12600] + disk[:1000])
        got_b = b"".join(btrfs_extent_bytes(shapes, isize, rd, 4096))
        try:
            b"".join(btrfs_extent_bytes([(0, ext(1, encryption=1, disk_bytenr=0x10000,
                                                 disk_num_bytes=4096, num_bytes=4096))],
                                        4096, rd, 4096))
            enc = False
        except BtrfsUnreadable:
            enc = True
        tail = b"".join(btrfs_extent_bytes(shapes[:1], 9000, rd, 4096))
        out.append(("extents mkfs.btrfs --rootdir does not write (holes with and without an "
                    "item, preallocated, offsets into plain and zlib extents, past the size, a "
                    "trailing hole) read as the format says, and an encrypted extent is refused",
                    got_b == expect and enc and tail == disk[100:4196] + bytes(9000 - 4096)))
        # zlib: with a zlib header the adler32 is not checked, as the kernel
        # reads it (zlib.c:374-382); a stream whose adler32 is wrong still reads.
        bad_adler = bytearray(zlib.compress(plain))
        bad_adler[-1] ^= 0xFF
        zl = _btrfs_decompress(1, bytes(bad_adler), len(plain), 4096) == plain
        # A compressed extent past the kernel's 128 KiB, either way, is refused
        # before it is decompressed, so a small stream cannot ask for a large
        # output.
        bomb = zlib.compress(bytes(4 << 20))
        bounds = []
        for ram, data in ((0, bomb), (1 << 63, bomb), (4 << 20, bomb),
                          (4096, bytes(BTRFS_MAX_COMPRESSED + 1))):
            try:
                _btrfs_decompress(1, data, ram, 4096)
                bounds.append(False)
            except DecompressError:
                bounds.append(True)
        capped = len(_btrfs_decompress(1, bomb, BTRFS_MAX_UNCOMPRESSED, 4096))
        out.append(("zlib extents read without their adler32 check, and compressed extents "
                    "outside 1 to 128 KiB are refused before decompressing",
                    zl and all(bounds) and capped == BTRFS_MAX_UNCOMPRESSED))
        # LZO framing: a segment header never crosses a sector, so 1 to 3
        # bytes left in a sector are padding and 4 are not (lzo.c:533-542).
        # Segments made of literal-only LZO1X (lzo.rst: a first byte over 17
        # is a run of that many less 17 literals; 17 0 0 ends the stream).
        sector, payload, plan = 512, bytearray(4), []
        data_out = bytearray()
        pads_seen = set()
        seed = 0
        while len(payload) < 6 * sector:
            room = sector - len(payload) % sector
            # pick a segment length that leaves 1, 2, 3 or 4 bytes in turn
            leave = (seed % 4) + 1
            seed += 1
            total = room - leave                            # header + stream bytes
            lit = total - 4 - 4                             # minus seg header, op, end
            if lit < 1 or lit > 238:
                lit = 40
            stream = bytes([17 + lit]) + bytes((seed * 7 + i) & 0xFF for i in range(lit)) \
                + b"\x11\x00\x00"
            payload += struct.pack("<I", len(stream)) + stream
            data_out += stream[1:1 + lit]
            left = sector - len(payload) % sector
            if left < 4:
                pads_seen.add(left)
                payload += bytes(left)
            plan.append(lit)
        struct.pack_into("<I", payload, 0, len(payload))
        lzo_got = _btrfs_decompress(2, bytes(payload), len(data_out), sector)
        out.append((f"LZO segments are read across sector padding of {sorted(pads_seen)} bytes "
                    "and none", lzo_got == bytes(data_out) and pads_seen == {1, 2, 3}))
        # Compressed inline data that decompresses to more than ram_bytes is
        # cut to ram_bytes, the length the inline extent records.
        seg = bytes([17 + 40]) + bytes(range(40)) + b"\x11\x00\x00"
        lzo_inline = struct.pack("<II", 8 + len(seg), len(seg)) + seg
        inl = dict(type=0, compression=2, encryption=0, other_encoding=0, ram_bytes=10,
                   inline=lzo_inline)
        cut = b"".join(btrfs_extent_bytes([(0, inl)], 40, rd, 4096))
        out.append(("compressed inline data is cut to the ram_bytes it records, the rest of the "
                    "file read as a hole", cut == bytes(range(10)) + bytes(30)))
    section("extent shapes and decompression", extent_shapes)

    def convert_and_raid():
        raw = load("btrfs-convert.img.gz")
        img = io.BytesIO(raw)
        kind = (identify_fs(img, 0, len(raw)) or (None,))[0]
        cs = sums("btrfs-convert.sha256")
        match = 0
        if kind == "btrfs":
            w = walker_for(kind, img, 0, len(raw))
            got = {p: (node, sz) for p, node, _m, sz, _t, _r in walk_all(w)}
            for rel, digest in cs.items():
                if rel in got:
                    h = hashlib.sha256()
                    try:
                        for chunk in w.read_file(*got[rel]):
                            h.update(chunk)
                    except (BtrfsUnreadable, DecompressError):
                        continue
                    match += h.hexdigest() == digest
        out.append((f"btrfs-convert: an ext4 volume btrfs-convert converted is identified as "
                    f"btrfs, and its files and the saved ext4 image (holes included) read back "
                    f"with the sha256 they had before conversion ({match} of {len(cs)})",
                    kind == "btrfs" and match == len(cs)))
        raw = load("btrfs-raid1-dev2.img.gz")
        img = io.BytesIO(raw)
        kind = (identify_fs(img, 0, len(raw)) or (None,))[0]
        ok = False
        if kind == "btrfs":
            w = walker_for(kind, img, 0, len(raw))
            stripe_two = all(ch["stripes"][0][0] != 2 for ch in w.chunks.values())
            ok = (w.devid == 2 and w.entry(w.root) is not None and list(walk_all(w)) == []
                  and not w.damage and "of 2" in (w.note or "") and stripe_two)
        out.append(("btrfs-raid1-dev2: device 2 of a RAID1 pair, whose copy is never a chunk's "
                    "first stripe, reads its trees from its own copies", ok))
    section("btrfs-convert and btrfs-raid1-dev2", convert_and_raid)

    # The fixtures only root can make (tools/make_btrfs_root_fixtures.sh): a
    # volume the kernel wrote, with holes, preallocated and punched extents,
    # reflinks, partly overwritten compressed extents, snapshots and deleted
    # files, and a volume copied with a log tree not yet committed. Checked
    # when they are present, skipped when not.
    def live():
        raw = load("btrfs-live.img.gz")
        img = io.BytesIO(raw)
        w = walker_for("btrfs", img, 0, len(raw))
        got = {p: (node, mode, sz, mt) for p, node, mode, sz, mt, _r in walk_all(w)}
        lwant = sums("btrfs-live.src.sha256")
        with open(os.path.join(here, "btrfs-live.src.json"), encoding="utf-8") as fh:
            llist = json.load(fh)
        match = no_zstd = 0
        for rel, digest in lwant.items():
            g = got.get(rel)
            if g is not None:
                try:
                    data = b"".join(w.read_file(g[0], g[2]))
                except (BtrfsUnreadable, DecompressError) as exc:
                    no_zstd += _zstd_module() is None and "zstd" in str(exc)
                    continue
                match += hashlib.sha256(data).hexdigest() == digest
        out.append((f"btrfs-live: every file the kernel wrote reads back with the sha256 taken "
                    f"through the mount ({match} of {len(lwant)}"
                    + (f"; {no_zstd} zstd file(s) not read: this Python has no zstd"
                       if no_zstd else "") + ")", match + no_zstd == len(lwant)))
        bad = []
        for e in llist:
            g = got.get(e["path"])
            # A snapshot's link to a subvolume it does not hold is an empty
            # directory the kernel makes up on lookup (inode 2) with the time
            # of that lookup, which no disk records; its time is not compared.
            loose = e["type"] == "dir" and e["ino"] == BTRFS_EMPTY_SUBVOL_DIR_OBJECTID
            if g is None or g[1] != e["mode"] or (e["type"] == "file" and g[2] != e["size"]) \
                    or (not loose and g[3] != e["mtime"]):
                bad.append(e["path"])
            elif not loose and (w.times(g[0]) or {}).get("modified") != (e["mtime"],
                                                                         e["mtime_ns"]):
                bad.append(e["path"] + " (nanoseconds)")
        extra = sorted(set(got) - {e["path"] for e in llist})
        stale = sum(1 for e in llist if e["type"] == "dir"
                    and e["ino"] == BTRFS_EMPTY_SUBVOL_DIR_OBJECTID)
        out.append((f"btrfs-live: all {len(llist)} entries, snapshots and subvolumes included "
                    f"({stale} stale subvolume link(s)), listed as lstat() saw them through the "
                    "mount, to the nanosecond, and nothing else"
                    + (f" (differ: {bad[:3]}; extra {extra[:3]})" if bad or extra else ""),
                    not bad and not extra and stale > 0))
        # deleted files: each 64 KiB block of them is found, at a sector
        # boundary, inside the space free_extents() reports
        wanted = set(sums("btrfs-live.deleted.sha256").values())
        hits = set()
        for s0, n in w.free_extents(min_bytes=65536):
            run = read_at(img, s0, n)
            for at in range(0, n - 65536 + 1, 4096):
                h = hashlib.sha256(run[at:at + 65536]).hexdigest()
                if h in wanted:
                    hits.add(h)
        out.append((f"btrfs-live: every 64 KiB block of the deleted files is in the space "
                    f"free_extents() reports ({len(hits)} of {len(wanted)})",
                    bool(wanted) and hits == wanted))

    names = ["btrfs-live.img.gz", "btrfs-live.src.sha256", "btrfs-live.src.json",
             "btrfs-live.deleted.sha256"]
    if not all(os.path.isfile(os.path.join(here, n)) for n in names):
        out.append(("btrfs-live (holes, preallocated and punched extents, reflinks, overwritten "
                    "compressed extents, snapshots, deleted files) not checked: its fixtures "
                    "are made by tools/make_btrfs_root_fixtures.sh, which needs root", None))
    else:
        section("btrfs-live", live)

    def logtree():
        raw = load("btrfs-logtree.img.gz")
        img = io.BytesIO(raw)
        kind, _lines = identify_fs(img, 0, len(raw))
        w = walker_for(kind, img, 0, len(raw)) if kind == "btrfs" else None
        got = {p for p, *_r in walk_all(w)} if w else set()
        out.append(("btrfs-logtree: the note says a log tree is present and not replayed, the "
                    "file committed before it is listed, and the file only the log holds is not",
                    w is not None and "log tree is present" in (w.note or "")
                    and "committed.txt" in got and "fsynced.txt" not in got))
    if not os.path.isfile(os.path.join(here, "btrfs-logtree.img.gz")):
        out.append(("btrfs-logtree (a log tree not yet replayed) not checked: its fixture is "
                    "made by tools/make_btrfs_root_fixtures.sh, which needs root", None))
    else:
        section("btrfs-logtree", logtree)
    return out


def _refs_test_node(rows, flags=0, level=0, bare=False):
    """A B+ tree node as the reader expects one (header, rows, key index),
    built for the self-test's synthetic records. rows are (key, value) pairs,
    or for a stream node (bare) the 24-byte extent records themselves."""
    body = bytearray(0x28)
    offsets = []
    for row in rows:
        offsets.append(len(body))
        if bare:
            body += row
        else:
            key, value = row
            body += struct.pack("<IHHHHHH", 16 + len(key) + len(value), 16, len(key), 0,
                                16 + len(key), len(value), 0) + key + value
        while len(body) % 8:
            body += b"\x00"
    start = len(body)
    for o in offsets:
        body += struct.pack("<I", o | 0xFFFF0000)
    body[0x0C], body[0x0D] = level, flags
    struct.pack_into("<II", body, 0x10, start, len(rows))
    struct.pack_into("<I", body, 0x20, len(body))
    return bytes(body)


def _refs_test_record(rows, attrs=0x20):
    """A file record: fixed fields (attributes at +0x48), then its table at 0xA8."""
    head = bytearray(0xA8)
    struct.pack_into("<I", head, 0, 0xA8)
    struct.pack_into("<I", head, 0x48, attrs)
    return bytes(head) + _refs_test_node(rows)


def _refs_test_stream(extents, size, valid=None, alloc=None):
    """A stream record in extents: sizes at +0x30..+0x40, summary size 0x200
    at +0x0C, its extent node at 0x88; extents are (vcn, run, vlcn, flags)."""
    head = bytearray(0x88)
    struct.pack_into("<I", head, 0, 0x88)
    struct.pack_into("<I", head, 0x0C, 0x200)
    struct.pack_into("<QQQ", head, 0x30, size if alloc is None else alloc, size,
                     size if valid is None else valid)
    recs = [struct.pack("<QHHIII", vlcn, flags, 24, vcn, 0, run) for vcn, run, vlcn, flags in extents]
    return bytes(head) + _refs_test_node(recs, flags=0x04, bare=True)


def _refs_attr_key(marker, atype, sub, tail=b""):
    return struct.pack("<QIHH", 0, marker, atype, sub) + tail


def _refs_unit_checks(img, w, got, known):
    """Checks of single rules, on the fixture and on records built here, so
    that a change to any of them fails without forefst's volumes mounted.
    Each label names the rule."""
    import io
    out = []
    times = {k["path"]: k for k in known}
    fixed = times["times/fixed.txt"]
    node = got["times/fixed.txt"][1]
    unix = tuple((int(fixed[k]) - NTFS_EPOCH_DELTA * 10_000_000) / 10_000_000
                 for k in ("created", "modified", "accessed"))
    out.append(("stamps() gives created, modified and accessed in Unix seconds, as Windows "
                "reported them for times/fixed.txt",
                all(abs(a - b) < 1e-6 for a, b in zip(w.stamps(node), unix))))

    # Unwritten runs, valid data length, and the read of a real run.
    big = got["sizes/size_65537.bin"][1]
    stream = w._main_stream(w._record(big)[0])  # pylint: disable=protected-access
    first = w._extents(stream[3])[0]  # pylint: disable=protected-access
    real = b"".join(p for p, _a in w._stream_pieces([(0, 1, first[2], 0x50)], w.cluster))  # pylint: disable=protected-access
    unwritten = b"".join(p for p, _a in w._stream_pieces([(0, 1, first[2], 0x40)], w.cluster))  # pylint: disable=protected-access
    whole = b"".join(w._read_stream(stream, stream[1]))  # pylint: disable=protected-access
    short = b"".join(w._read_stream((stream[0], stream[1], 1000) + stream[3:], stream[1]))  # pylint: disable=protected-access
    out.append(("a run marked allocated but not written (flags 0x40) reads as zeros though its "
                "cluster holds bytes, and bytes past the valid data length read as zeros",
                real.strip(b"\x00") != b"" and unwritten == bytes(w.cluster)
                and short[:1000] == whole[:1000] and short[1000:] == bytes(len(whole) - 1000)))

    # Container arithmetic on a made-up volume: 512-byte clusters, 4 a container.
    t = RefsWalker.__new__(RefsWalker)
    disk = b"".join(bytes([i]) * 512 for i in range(64))
    t.fh, t.base, t.cluster, t.bad_containers = io.BytesIO(disk), 0, 512, {}
    t.damage, t.damage_count, t._where, t.total_clusters = [], 0, "", 64  # pylint: disable=protected-access
    t.containers = {2: (9, 4, 0), 3: (24, 4, 0), 4: (24, 8, 0), 5: (64, 8, 0)}
    odd = t._check_containers()  # pylint: disable=protected-access
    t.containers = {2: (8, 4, 0), 3: (32, 4, REFS_CONTAINER_COMPRESSED)}
    inside = b"".join(t._clusters((2 << 3) | 1, 3))  # pylint: disable=protected-access
    turned = []
    for vlcn, n in (((2 << 3) | 2, 3), ((3 << 3) | 0, 1)):
        try:
            b"".join(t._clusters(vlcn, n))  # pylint: disable=protected-access
            turned.append(False)
        except RefsDamage:
            turned.append(True)
    out.append(("virtual cluster translation: container = number >> bit length of its size, the "
                "rest the offset; a run past its container's end and a container marked "
                "compressed are refused; a container not aligned to its size, overlapping "
                "another or reaching past the volume is reported",
                inside == bytes([9]) * 512 + bytes([10]) * 512 + bytes([11]) * 512
                and turned == [True, True] and sorted(odd) == [2, 3, 4, 5]
                and "multiple" in odd[2] and "overlaps" in odd[3] and "past" in odd[5]))

    # A directory's change time comes from its name row in its parent.
    sizes = got["sizes"][1]
    row = w._index_rows[sizes]  # pylint: disable=protected-access
    own = w._times_of(w._dir(sizes).own)  # pylint: disable=protected-access
    w._index_rows[sizes] = row[:0x20] + struct.pack("<Q", 123456789) + row[0x28:]  # pylint: disable=protected-access
    moved = w.filetimes(sizes)
    w._index_rows[sizes] = row  # pylint: disable=protected-access
    out.append(("a directory's change time is the copy in its name row, its other times its "
                "own record's",
                moved == (own[0], own[1], 123456789, own[3])))

    # Streams and snapshots, on records built here.
    ads = struct.pack("<IIII", 0, 0x30 + 2, 0x0C, 0x30) + bytes(0x08) + struct.pack("<QQQQ", 2, 2, 2, 2) + bytes(4) + b"hi"
    snap = bytearray(ads)
    struct.pack_into("<H", snap, 0x10, 2)
    rec = _refs_test_record([(_refs_attr_key(0x80000002, 0xB0, 5, "one".encode("utf-16-le")), ads),
                             (_refs_attr_key(0x80000002, 0xB0, 5, "two".encode("utf-16-le")), bytes(snap))])
    named = list(w._named(rec)[0])  # pylint: disable=protected-access
    data = lambda sub, base: _refs_attr_key(0x80000002, 0x80, 0x0E, struct.pack("<QQ", sub, base))
    live = _refs_test_record([
        (data(0x1000, 0x1002), _refs_test_stream([], w.cluster)),
        (data(0x1001, 0x0008), _refs_test_stream([(0, 1, 0x1111, 0x50)], w.cluster)),
        (data(0x1002, 0x1001), _refs_test_stream([(0, 1, 0x2222, 0x50)], w.cluster))])
    merged = w._main_stream(live)  # pylint: disable=protected-access
    out.append(("a stream whose summary flags say snapshot (2) is not listed as an alternate "
                "stream, and a live stream with no clusters of its own reads from its newest "
                "snapshot (sub-stream 0x1002 before 0x1001)",
                named == ["one"]
                and [e[2] for e in w._extents(merged[3], merged[4])] == [0x2222]))  # pylint: disable=protected-access

    # Damaged and hostile records.
    broken = []
    shorted = _refs_test_record([(data(0x1000, 0x1001), _refs_test_stream([], 10)),
                                 (data(0x2000, 0x0008), b"\x00" * 8)])
    for build in (lambda: w._main_stream(shorted),  # pylint: disable=protected-access
                  lambda: w._extents(_refs_test_stream([(0, 2, first[2], 0x50), (1, 1, first[2], 0x50)], 3 * w.cluster)),  # pylint: disable=protected-access
                  lambda: w._extent_stream(_refs_test_stream([], 1 << 60))):  # pylint: disable=protected-access
        try:
            build()
            broken.append(False)
        except RefsDamage:
            broken.append(True)
        except Exception:                            # pylint: disable=broad-except
            broken.append(None)                      # raised, but not as damage
    before = w.damage_count
    gap = _refs_test_stream([(0, 1, first[2], 0x50), (2, 1, first[2] + 2, 0x50)], 3 * w.cluster)
    gapped = b"".join(w._read_stream(("extents", 3 * w.cluster, 3 * w.cluster, gap, ()),  # pylint: disable=protected-access
                                     3 * w.cluster, False, "made up"))
    gap_hurt = w.damage_count - before
    over = _refs_test_stream([(0, 3, first[2], 0x50)], 3 * w.cluster, alloc=w.cluster)
    b"".join(w._read_stream(("extents", 3 * w.cluster, 3 * w.cluster, over, ()),  # pylint: disable=protected-access
                            3 * w.cluster, True, "made up"))
    over_hurt = w.damage_count - before - gap_hurt
    encrypted = []
    for attrs in (0x20, 0x20 | REFS_ATTR_ENCRYPTED):
        try:
            w._refuse_unreadable(_refs_test_record([], attrs))  # pylint: disable=protected-access
            encrypted.append(False)
        except RefsDamage:
            encrypted.append(True)
    out.append(("a snapshot row too short for a stream, two extents over one cluster, a size "
                "past ReFS's 35 PB and an encrypted file's content are refused; a gap in a file "
                "not marked sparse, and extents past the stream's allocation, are reported, "
                "the gap reading as zeros",
                broken == [True, True, True] and gap_hurt == 1 and over_hurt == 1
                and encrypted == [False, True]
                and gapped[w.cluster:2 * w.cluster] == bytes(w.cluster)))

    fresh = RefsWalker(img, 0)
    many = got["many"][1]
    slots, kind, digest = _refs_reference(fresh.objects[many], 0x20)
    root = bytearray(fresh._page(slots, kind, digest, virtual=True))  # pylint: disable=protected-access
    hoff = 0x50 + struct.unpack_from("<I", root, 0x50)[0]
    start = struct.unpack_from("<I", root, hoff + 0x10)[0]
    places = []
    for i in range(struct.unpack_from("<I", root, hoff + 0x14)[0]):
        pos = hoff + (struct.unpack_from("<I", root, hoff + start + 4 * i)[0] & 0xFFFF)
        places.append(pos + struct.unpack_from("<H", root, pos + 0x0A)[0])
    root[places[1]:places[1] + 0x30] = root[places[0]:places[0] + 0x30]
    twice = list(fresh._node_rows(bytes(root), hoff, True, 0, "a made-up page"))  # pylint: disable=protected-access
    wrong = []
    page = fresh._page(slots, kind, digest, virtual=True)  # pylint: disable=protected-access
    for bad_kind, bad_digest in ((kind, bytes(len(digest))), (0, b""),
                                 (1, struct.pack("<I", refs_crc32c(page)))):
        try:
            fresh._page(slots, bad_kind, bad_digest, virtual=True)  # pylint: disable=protected-access
            wrong.append(False)
        except RefsDamage:
            wrong.append(True)
    capped = RefsWalker(img, 0)
    for _i in range(REFS_DAMAGE_CAP + 500):
        capped._hurt("made up")  # pylint: disable=protected-access
    out.append(("a table naming one child page twice reads it once and reports it; a cached page "
                "asked for under another digest, under checksum kind 0, or under a CRC32-C that "
                "matches it on a CRC-64 volume, is refused; damage "
                f"keeps {REFS_DAMAGE_CAP} lines and counts the rest",
                any("twice" in d for d in fresh.damage) and len(twice) > 0
                and wrong == [True, True, True] and len(capped.damage) == REFS_DAMAGE_CAP
                and capped.damage_count == REFS_DAMAGE_CAP + 500))

    loop = RefsWalker(img, 0)
    sizes_row = w._index_rows[sizes]  # pylint: disable=protected-access
    attrs = got["attrs"][1]
    loop._dir(attrs).names["loop".encode("utf-16-le")] = (2, sizes_row[:8] + struct.pack("<Q", REFS_ROOT_DIR) + sizes_row[16:])  # pylint: disable=protected-access
    loop._dir(attrs).names["twin".encode("utf-16-le")] = (2, sizes_row)  # pylint: disable=protected-access
    loop.listdir(loop.root)
    names = [n for n, _x in loop.listdir(attrs)]
    out.append(("a directory row naming the root, or a directory another one names, is "
                "reported and left out",
                "loop" not in names and "twin" not in names
                and sum(1 for d in loop.damage if "names" in d) == 2))

    # The boot sector's version, the superblock's clock, a checkpoint tie.
    def boot_with(major, minor):
        img.seek(0)
        b = bytearray(img.read(512))
        b[0x28], b[0x29] = major, minor
        struct.pack_into("<H", b, 0x16, _refs_boot_checksum(bytes(b)))
        return img.patched(0, bytes(b))
    newer = []
    for major, minor in ((3, 15), (9, 99)):
        kind_n, lines_n = identify_refs(boot_with(major, minor), 0)
        try:
            RefsWalker(boot_with(major, minor), 0)
            newer.append(False)
        except ValueError:
            newer.append(kind_n == "refs" and any("newer than ReFS 3.14" in x for x in lines_n))
    sb_at = (w.total_clusters - 2) * w.cluster
    img.seek(REFS_SUPERBLOCK_LCN * w.cluster)
    sb = bytearray(img.read(w.cluster))
    struct.pack_into("<Q", sb, 0x68, struct.unpack_from("<Q", sb, 0x68)[0] + 1)
    doff, dlen = struct.unpack_from("<II", sb, 0x78)
    body = bytearray(sb)
    body[doff:doff + dlen] = bytes(dlen)
    struct.pack_into("<I", sb, doff + 0x20 + sb[doff + 0x23], refs_crc32c(bytes(body)))
    later = RefsWalker(img.patched(sb_at, bytes(sb)), 0)
    # Both checkpoint slots holding the same checkpoint: equal clocks.
    other = [lcn for lcn in w.checkpoint_lcns if lcn != w.checkpoint_lcn][0]
    img.seek(w.checkpoint_lcn * w.cluster)
    tied = img.patched(other * w.cluster, img.read(max(w.cluster, REFS_PAGE_BYTES)))
    _k, tie_lines = identify_refs(tied, 0)
    out.append(("ReFS 3.15 and 9.99 are refused by name; of the superblock copies the one with "
                "the higher clock (+0x68) is read; a checkpoint clock tie is reported",
                newer == [True, True] and later.superblock_lcn == w.total_clusters - 2
                and RefsWalker(tied, 0).checkpoint_tie == w.clock
                and any("both checkpoints carry clock" in x for x in tie_lines)))
    return out


def _refs_fixture_checks():
    """[(label, passed or None for a skip)] for the ReFS reader, from the volumes
    Windows 11 wrote (tools/make_refs_fixtures.ps1, make-refs.ps1), shipped as the
    bytes the reader reads (tools/make_refs_fixture.py), against what Windows
    reported about each file while the volume was mounted."""
    import gzip
    import hashlib
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
    need = ("refs-fixture.bin.gz", "refs-fixture.known.tsv.gz", "refs-dirty.bin.gz")
    absent = [n for n in need if not os.path.isfile(os.path.join(here, n))]
    if absent:
        return [(f"the ReFS fixtures are not beside this script ({', '.join(absent)}), so the "
                 "ReFS reader was not checked against them", None)]
    with gzip.open(os.path.join(here, "refs-fixture.bin.gz"), "rb") as gz:
        img = _RefsSparseImage(gz.read())
    with gzip.open(os.path.join(here, "refs-dirty.bin.gz"), "rb") as gz:
        dirty = _RefsSparseImage(gz.read())
    with gzip.open(os.path.join(here, "refs-fixture.known.tsv.gz"), "rt", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    head = lines[0].split("\t")
    known = [dict(zip(head, line.split("\t"))) for line in lines[1:]]
    entries = [k for k in known if k["kind"] not in ("stream", "deleted")]
    unshipped = set(img.head.get("not_shipped", []))
    out = []

    kind, ident = identify_refs(img, 0)
    out.append(("the Windows 11 ReFS fixture is identified as refs, version 3.14, from its "
                "boot sector, with no log record after its checkpoint",
                kind == "refs" and ident[0].endswith("ReFS 3.14 (boot sector)")
                and "log          no record follows the checkpoint" in ident))
    w = RefsWalker(img, 0)
    got = {item[0]: item for item in walk_all(w)}
    kinds = {"file": S_IFREG, "dir": S_IFDIR, "filelink": S_IFLNK, "dirlink": S_IFLNK}
    wrong = collections.defaultdict(list)
    hashed = 0
    for k in entries:
        item = got.get(k["path"])
        if item is None:
            wrong["missing"].append(k["path"])
            continue
        node, mode, size = item[1], item[2], item[3]
        if mode & S_IFMT != kinds[k["kind"]]:
            wrong["type"].append(k["path"])
        if w.filetimes(node) != tuple(int(k[t]) for t in ("created", "modified", "changed", "accessed")):
            wrong["times"].append(k["path"])
        ordinal, oid = w.file_id(node)
        if struct.pack("<QQ", ordinal, oid).hex() != k["file_id"]:
            wrong["file id"].append(k["path"])
        if k["kind"] in ("filelink", "dirlink") and w.readlink(node) != k["target"]:
            wrong["link target"].append(k["path"])
        if k["kind"] != "file":
            continue
        if size != int(k["size"]):
            wrong["size"].append(k["path"])
        if w.link_count(node) != int(k["links"]):
            wrong["links"].append(k["path"])
        if w.attributes(node) & 0xFFFF != int(k["attributes"], 16):
            wrong["attributes"].append(k["path"])
        alloc = w.allocation(node)
        if w.data_form(node) == "extents" and alloc["stored"] != int(k["allocated"]):
            wrong["stored"].append(k["path"])
        if k["path"] in unshipped:
            continue
        digest = hashlib.sha256()
        for chunk in w.read_file(node, size):
            digest.update(chunk)
        hashed += 1
        if digest.hexdigest() != k["sha256"]:
            wrong["content"].append(k["path"])
    listed = {k["path"] for k in entries}
    extra = [p for p in got if p not in listed and not p.startswith("System Volume Information")]
    files = sum(1 for k in entries if k["kind"] == "file")
    out.append((f"every one of the {len(entries):,} entries Windows listed is walked with its "
                "type, size, four FILETIMEs to the 100 ns, 128-bit file id, link count, "
                "attributes and link target as Windows reported them, and nothing else is "
                "listed" + "".join(f"; {n} {what} wrong (first {v[0]!r})"
                                   for what, v in wrong.items() if what != "content"
                                   for n in [len(v)])
                + (f"; {len(extra)} not in Windows's listing (first {extra[0]!r})" if extra else ""),
                not [v for what, v in wrong.items() if what != "content"] and not extra))
    out.append((f"{hashed:,} of the {files:,} files read back with the SHA-256 Windows recorded "
                f"(the {len(unshipped)} whose random content is not shipped are left out by name: "
                f"{', '.join(sorted(unshipped))})"
                + (f"; {len(wrong['content'])} do not (first {wrong['content'][0]!r})"
                   if wrong["content"] else ""),
                hashed == files - len(unshipped) and not wrong["content"]))
    streams = [k for k in known if k["kind"] == "stream"]
    sgood = 0
    for k in streams:
        path, name = k["path"].rsplit(":", 1)
        node = got[path][1] if path in got else None
        if node is None or dict(w.named_streams(node)).get(name) != int(k["size"]):
            continue
        data = b"".join(w.read_file(w.stream_ref(node, name), int(k["size"])))
        sgood += hashlib.sha256(data).hexdigest() == k["sha256"]
    dnode = got.get("ads/dir_with_stream", (None, None))[1]
    on_dir = (dnode is not None and w.named_streams(dnode) == [("onadir", 25)]
              and b"".join(w.read_file(w.stream_ref(dnode, "onadir"), 25))
              == b"a stream on a directory\r\n")
    out.append((f"the {len(streams)} alternate data streams Windows listed (two inline, one in "
                f"extents) read back with the SHA-256 it recorded ({sgood} of {len(streams)}), and "
                "the stream the script wrote on a directory reads as written",
                sgood == len(streams) and on_dir))
    gone = [k["path"] for k in known if k["kind"] == "deleted" and k["path"] in got]
    out.append(("none of the 17 files and folders created and then deleted is listed"
                + (f" ({len(gone)} are: {gone[0]!r})" if gone else ""),
                not gone and sum(1 for k in known if k["kind"] == "deleted") == 17))
    out.append(("no page of the fixture fails its checksum", not w.damage))

    # The first fixture: detached seconds after its files were written, so they
    # are only in the log, after the checkpoint the reader reads.
    kind, ident = identify_refs(dirty, 0)
    wd = RefsWalker(dirty, 0)
    out.append(("a volume whose newest checkpoint predates its files says that 16 log records "
                "follow it and that they are not applied, and lists the checkpoint's empty root",
                kind == "refs" and wd.logged == 16 and wd.note is not None
                and any(line.startswith("log          16 metadata log records") for line in ident)
                and wd.listdir(wd.root) == []))

    # Broken on purpose: each must be reported, not read past.
    # One letter of one name in a leaf page of the 2,500-entry directory: the
    # page's structure still holds, so only its checksum can catch it.
    many = dict(w.listdir(w.root))["many"]
    ref = (w.objects[many], 0x20)
    while True:
        slots, ckind, digest = _refs_reference(*ref)
        page = w._page(slots, ckind, digest, virtual=True)  # pylint: disable=protected-access
        hoff = 0x50 + struct.unpack_from("<I", page, 0x50)[0]
        level, _f, rows = _refs_node(page, hoff)
        if not level:
            break
        ref = (rows[-1][1], 0)                          # name rows sort last
    index = hoff + struct.unpack_from("<I", page, hoff + 0x10)[0]
    i = next(n for n, row in enumerate(rows) if row[0][:2] == b"\x30\x00")
    key = rows[i][0]
    row = hoff + (struct.unpack_from("<I", page, index + 4 * i)[0] & 0xFFFF)
    in_page = row + struct.unpack_from("<H", page, row + 4)[0] + 0x10   # a letter of the name
    at = w.translate(slots[in_page // w.cluster]) * w.cluster + in_page % w.cluster
    name = key[4:].decode("utf-16-le")
    hurt = img.patched(at, bytes([page[in_page] ^ 0x01]))
    wb = RefsWalker(hurt, 0)
    seen = [n for n, _x in wb.listdir(many)]
    whole = [n for n, _x in w.listdir(many)]
    out.append((f"one letter of {name!r} changed in a leaf page of a 2,500-entry directory: the "
                "page fails its checksum and is reported, its rows are left out rather than "
                f"read with the wrong name, and the rest of the directory is still listed "
                f"({len(seen):,} of {len(whole):,} entries)",
                any(f"{many:#x}" in d and "checksum" in d for d in wb.damage)
                and name not in seen and set(seen) < set(whole) and len(seen) > 0))
    two = img.patched(0x28, b"\x02")
    kind2, lines2 = identify_refs(two, 0)
    try:
        RefsWalker(two, 0)
        turned_away = False
    except ValueError as exc:
        turned_away = "before format 3" in str(exc)
    out.append(("a boot sector that says ReFS 2.x is identified and refused by version",
                kind2 == "refs" and turned_away and any("not read: ReFS 2." in x for x in lines2)))
    first = wd.checkpoint_lsn
    rec_at = None
    for off, n, _a in dirty.runs:
        dirty.seek(off)
        blob = dirty.read(n)
        for b in range(0, n, 0x1000):
            if blob[b:b + 4] == b"MLog" and struct.unpack_from("<Q", blob, b + 0x28)[0] == first + 5:
                rec_at = off + b
    cut = dirty.patched(rec_at + 0x200, b"\xff") if rec_at is not None else dirty
    out.append(("a byte changed in the sixth log record after the checkpoint stops the count "
                "at five, the records whose check values hold",
                rec_at is not None and RefsWalker(cut, 0).logged == 5))
    out.extend(_refs_unit_checks(img, w, got, known))
    return out


REFS_FOREFST_SAMPLES = os.path.join("/Volumes", "Corpus", "Data for DLEAPP", "Public_Test_Images",
                                    "forefst-ReFS")
# name: (corpus key, cluster bytes, the checksum kind its metadata pages carry)
REFS_FOREFST_IMAGES = {
    "wininsiderrefs8gtest2": ("forefst_refs314_64k_sha256", 0x10000, 4),
    "win11refs2tspecials": ("forefst_refs314_specials", 0x1000, 2),
    "win11refs2tsnapshots": ("forefst_refs314_snapshots", 0x1000, 2),
    "win11refstestmftecmd": ("forefst_refs314_usn", 0x1000, 2),
}


def _refs_self_checks():
    """The ReFS checks: the committed fixtures, then forefst's sample volumes
    where they are mounted."""
    return _refs_fixture_checks() + _refs_forefst_checks()


def _refs_filetime_text(v):
    """A FILETIME as forefst prints one: UTC, to the 100 ns."""
    if not v:
        return None
    when = datetime.datetime(1601, 1, 1) + datetime.timedelta(microseconds=v // 10)
    return when.strftime("%Y-%m-%d %H:%M:%S") + ".%07d" % (v % 10_000_000)


def _refs_forefst_checks():
    """[(label, passed or None for a skip)] against xbqt/forefst's four sample
    volumes (GPL-3.0 data, never copied into this repository), read where the
    corpus keeps them, or under QNXPROBE_REFS_SAMPLES. Each is checked entry
    by entry against forefst's own inventory (forefst/files.jsonl beside it),
    an independent reader rather than Windows. Where forefst prints a file's
    times from a name row (a moved or linked file) the record's own differ
    from it, and the check requires the name row to hold exactly forefst's
    values, so each such difference is explained by the bytes rather than
    waved through."""
    root = os.environ.get("QNXPROBE_REFS_SAMPLES") or REFS_FOREFST_SAMPLES
    out = []
    for name, (key, cluster, ckind) in REFS_FOREFST_IMAGES.items():
        image = os.path.join(root, name, f"{name}.raw")
        listing = os.path.join(root, name, "forefst", "files.jsonl")
        if not (os.path.isfile(image) and os.path.isfile(listing)):
            out.append((f"forefst's sample volume {name} (corpus key {key}) is not at {root}, "
                        "so the ReFS reader was not checked against it", None))
            continue
        out.extend(_refs_forefst_check(name, key, cluster, ckind, image, listing))
    return out


def _refs_forefst_check(name, key, cluster, ckind, image, listing):
    with open(listing, encoding="utf-8") as fh:
        theirs = {r["full_path"]: r for r in (json.loads(line) for line in fh if line.strip())}
    img = open_image_trying(image)
    try:
        w = RefsWalker(img, 32768 * SECTOR)
        mine = {item[0]: item for item in walk_all(w)}
        wrong = collections.defaultdict(list)
        stale = 0
        for path, r in theirs.items():
            if path not in mine:
                wrong["missing"].append(path)
                continue
            node, mode = mine[path][1], mine[path][2]
            fmt = mode & S_IFMT
            # forefst marks directories (directory links among them) and gives
            # a reparse target for links; anything else is a file
            want_fmt = (S_IFLNK if r["reparse_target"] else
                        S_IFDIR if r["is_directory"] else S_IFREG)
            if fmt != want_fmt:
                wrong["type"].append(path)
            times = w.filetimes(node)
            text = [_refs_filetime_text(t) for t in times]
            want = [r[k] for k in ("created", "modified", "changed", "accessed")]
            if text != want:
                row = w._row(node) if isinstance(node, RefsEntry) else (0, b"")  # pylint: disable=protected-access
                copy = ([_refs_filetime_text(t) for t in struct.unpack_from("<4Q", row[1], 0x10)]
                        if row[0] == 2 and len(row[1]) >= 0x30 else None)
                if copy == want and not r["is_directory"]:
                    stale += 1
                else:
                    wrong["times"].append(path)
            ordinal, oid = w.file_id(node)
            if r["is_directory"] and fmt == S_IFDIR and int(r["oid"], 16) != oid:
                wrong["object id"].append(path)
            if fmt == S_IFREG:
                if mine[path][3] != r["file_size"]:
                    wrong["size"].append(path)
                if r["file_id"] and int(r["file_id"], 16) != ordinal:
                    wrong["file id"].append(path)
                if r["creation_dir_oid"] and int(r["creation_dir_oid"], 16) != oid:
                    wrong["home directory"].append(path)
                if r["hard_link_count"] is not None and w.link_count(node) != r["hard_link_count"]:
                    wrong["link count"].append(path)
                if (r["allocated_size"] is not None and w.data_form(node) == "extents"
                        and w.allocation(node)["stored"] != r["allocated_size"]):
                    wrong["allocation"].append(path)
            if fmt == S_IFLNK and w.readlink(node) != r["reparse_target"]:
                wrong["link target"].append(path)
            if sorted(n for n, _s in w.named_streams(node)) != sorted(
                    (r["ads_names"] or "").split(";") if r["ads_names"] else []):
                wrong["streams"].append(path)
        extra = [p for p in mine if p not in theirs]
        label = (f"{name} ({key}): all {len(theirs):,} entries forefst lists are walked, "
                 "none more, each with forefst's type, size, file id, directory, link count, "
                 "allocation, link target, stream names and four times"
                 + (f", except {stale} moved or linked files whose times forefst prints "
                    "from a name row, which holds exactly those values while the file's own "
                    "record holds others" if stale else "")
                 + "".join(f"; {len(v)} {what} wrong (first {v[0]!r})" for what, v in wrong.items())
                 + (f"; {len(extra)} not in forefst's list (first {extra[0]!r})" if extra else ""))
        out = [(label, not wrong and not extra)]
        checked = w.pages_checked.get(ckind, 0)
        out.append((f"{name}: {w.cluster:,}-byte clusters, every metadata page read checked "
                    f"against its {('CRC-64' if ckind == 2 else 'SHA-256')} ({checked:,} pages), "
                    "none failing, no damage, and no log record after the checkpoint",
                    w.cluster == cluster and checked > 0 and not w.damage and w.logged == 0
                    and set(w.pages_checked) == {ckind}))
        if name == "win11refstestmftecmd":
            out.append(_refs_integrity_check(w, mine))
        if name == "win11refs2tsnapshots":
            out.append(_refs_snapshot_check(w, mine))
    finally:
        getattr(img, "close", lambda: None)()
    return out


def _refs_integrity_check(w, mine, budget=3000):
    """Files written with integrity streams keep a CRC32-C of each cluster
    after its extent record [forefst extent_descriptors.md]. What read_file()
    returns for those clusters is checked against them, up to ``budget``
    clusters, among them the file whose extent map spans child pages."""
    paths = sorted(p for p, it in mine.items() if it[2] & S_IFMT == S_IFREG)
    paths = [p for p in paths if p.endswith("dotnet-sdk-9.0.314-win-x64.exe")] + paths
    good = bad = spanned = 0
    for path in paths:
        if good + bad >= budget:
            break
        node, size = mine[path][1], mine[path][3]
        if w.data_form(node) != "extents":
            continue
        value = w._main_stream(w._record(node)[0])[3]  # pylint: disable=protected-access
        sums = []
        _refs_checksummed_runs(w, value, struct.unpack_from("<I", value, 0)[0], sums)
        if not sums:
            continue
        spanned += bool(value[struct.unpack_from("<I", value, 0)[0] + 0x0C])
        reader = w.read_file(node, size)
        pending, at = b"", 0
        for vcn, crcs in sorted(sums):
            for k, crc in enumerate(crcs):
                if good + bad >= budget:
                    break
                want = (vcn + k) * w.cluster
                while at + len(pending) < want + w.cluster:
                    chunk = next(reader, None)
                    if chunk is None:
                        break
                    pending += chunk
                piece = pending[want - at:want - at + w.cluster]
                piece += bytes(w.cluster - len(piece))
                if refs_crc32c(piece) == crc:
                    good += 1
                else:
                    bad += 1
                drop = max(0, want + w.cluster - at)
                pending, at = pending[drop:], at + drop
    return (f"win11refstestmftecmd: {good:,} clusters of files with integrity streams read back "
            f"matching the CRC32-C ReFS stored for each" + (f", {bad} not" if bad else "")
            + (", the 226 MB file whose extent map spans child pages among them" if spanned else ""),
            good > 0 and not bad and spanned > 0)


def _refs_checksummed_runs(w, buf, hoff, out):
    """(file cluster, [CRC32-C per cluster]) of each extent record that carries
    them (flag 0x80): 24 bytes, then one u32 per cluster of its run."""
    if buf[hoff + 0x0C]:
        for _k, val, _f in _refs_node(buf, hoff)[2]:
            page = w._page(*_refs_reference(val, 0), virtual=True)  # pylint: disable=protected-access
            _refs_checksummed_runs(w, page, 0x50 + struct.unpack_from("<I", page, 0x50)[0], out)
        return
    start, count = struct.unpack_from("<II", buf, hoff + 0x10)
    for i in range(count):
        pos = hoff + (struct.unpack_from("<I", buf, hoff + start + 4 * i)[0] & 0xFFFF)
        _v, flags, size, vcn, _p, run = struct.unpack_from("<QHHIII", buf, pos)
        if flags & 0x80 and size >= 24 + 4 * run:
            out.append((vcn, list(struct.unpack_from(f"<{run}I", buf, pos + 24))))


def _refs_snapshot_check(w, mine):
    """A snapshotted file's live stream holds only what changed since its last
    snapshot. forefst's snapshots_versioning.md works this volume's test.txt
    through: four versions, the live one "abc\\r\\n", with no cluster of its own.
    arg.txt's two .bak copies,
    whole files of their own, hold what arg.txt held when they were made."""
    def read(path):
        node, size = mine[path][1], mine[path][3]
        return b"".join(w.read_file(node, size))
    test = read("testsnapshots/test.txt")
    arg = read("testsnapshots/arg.txt")
    baks = [read(p) for p in mine if p.startswith("testsnapshots/arg.txt.bak.")]
    return ("win11refs2tsnapshots: a snapshotted file's live stream is read through its "
            f"snapshots: test.txt, whose live stream holds no cluster of its own, reads {test!r} "
            f"as forefst documents, and arg.txt the same {len(arg)} bytes as its {len(baks)} "
            "backup copies",
            test == b"abc\r\n" and len(baks) == 2 and all(b == arg for b in baks) and arg != bytes(len(arg)))


def identify_fs(fh, base, size=None):
    """Return (name, [detail lines]) for whatever sits at this partition
    (_identify_fs). A region that ends in DDF or IMSM metadata (raid_foreign)
    is read as any other, and a line naming that metadata is added; when
    nothing else is recognised in it, it is a "raid member"."""
    kind, lines = _identify_fs(fh, base, size)
    if kind == "linux md member":
        return kind, lines
    if size is None:
        try:
            size = image_size(fh) - base
        except OSError:
            size = 0
    try:
        foreign = raid_foreign(fh, base, size)
    except (struct.error, ValueError, OSError):
        foreign = None
    if not foreign:
        return kind, lines
    levels, why = raid_foreign_levels(fh, base, size, foreign)
    if raid_foreign_mirror(levels):
        # a mirror member reads as any region would, recognised or not
        return kind, list(lines) + [raid_foreign_note(foreign, levels, why, subject="this region")]
    return "raid member", [raid_foreign_note(foreign, levels, why, kind, "this region")]


def _identify_fs(fh, base, size=None):
    """Return (name, [detail lines]) for whatever sits at this partition.

    size is the region's byte length, needed by the flash filesystems (ETFS/EFS)
    which have no header at a fixed offset and are sized by the region. When it
    is not given it is taken as the rest of the file from base.
    """
    if size is None:
        try:
            size = image_size(fh) - base
        except OSError:
            size = 0

    # QNX4 first: its acceptance is structural (root inode "/", directory
    # mode, a resolved .bitmap entry), while the ext test below is a bare
    # 2-byte magic at offset 1080, which on a QNX4 volume falls inside
    # .bitmap data where any bit pattern can occur. The more specific test
    # runs first so a chance pattern cannot shadow the real format.
    q4 = identify_qnx4(fh, base, size)
    if q4:
        return q4

    # The Linux flash filesystems next, for the same reason: each is accepted
    # only on a structure it checks (a SquashFS superblock that reads back to a
    # root directory, a UBI or UBIFS header whose CRC holds, a JFFS2 node whose
    # header CRC holds at the start of the region), where ext's test is a bare
    # magic that compressed or node data can carry by chance.
    for ident in (identify_squashfs, identify_ubi, identify_ubifs, identify_jffs2):
        found = ident(fh, base, size)
        if found:
            return found

    # A Linux md RAID member: its superblock where the kernel looks for each
    # metadata version, with its checksum. Its array is read from all its
    # members together (raid_assemble), not from this region. (DDF and IMSM
    # metadata is named by identify_fs() after everything else is tried.)
    found = identify_md(fh, base, size)
    if found:
        return found

    # A LUKS container: its magic at the start of the region. What it holds is
    # read, once a passphrase opens it (unlock_luks), as a region of its own.
    found = identify_luks(fh, base, size)
    if found:
        return found

    # An LVM2 physical volume: a label lvm2 itself would accept (the sector it
    # names and its checksum must hold), and either a metadata area header that
    # checks out or a volume group elsewhere in the image that names it. Its logical volumes are regions of their own (lvm_volumes), so the
    # PV itself is reported, not walked.
    found = identify_lvm(fh, base, size)
    if found:
        return found

    # BitLocker before the rest: its header is a FAT32 boot sector in all but its
    # signature and identifier (so identify_fat would take it for an empty FAT32
    # volume), and the ciphertext behind it can carry ext's 2-byte magic by chance.
    bde = identify_bitlocker(fh, base, size)
    if bde:
        return bde

    # The configuration stores a flash chip carries beside its filesystems. Each
    # is accepted only on a CRC-32 that holds over the store.
    for ident in (identify_nvram, identify_uboot_env):
        found = ident(fh, base, size)
        if found:
            return found

    # XFS before ext: it is accepted on its superblock's geometry, where ext's
    # 2-byte magic at 1080 falls inside XFS's own AG headers.
    xfs = identify_xfs(fh, base, size)
    if xfs:
        return xfs

    # Btrfs before ext, the more specific test first: an 8-byte magic and a
    # checksum over the superblock, against ext's 2-byte magic. mkfs.btrfs
    # 6.17.1 and mke2fs 1.47.2 each clear the other's signature (measured), so
    # the order decides something only on an image older tools wrote.
    found = identify_btrfs(fh, base, size)
    if found:
        return found

    sb = read_at(fh, base + EXT_SB_OFF, 1024)
    if len(sb) == 1024 and _e(sb, "magic", 2) == EXT_MAGIC:
        bs = 1024 << _e(sb, "log_block_size")
        total = _e(sb, "blocks_count") * bs
        free = _e(sb, "free_blocks") * bs
        inc, cmp_ = _e(sb, "feature_incompat"), _e(sb, "feature_compat")
        kind = ("ext4" if inc & EXT_INCOMPAT_EXTENTS
                else "ext3" if cmp_ & EXT_COMPAT_HAS_JOURNAL else "ext2")
        label = sb[EXT_F["volume_name"]:EXT_F["volume_name"] + 16]
        label = label.split(b"\x00")[0].decode("utf-8", "replace")
        lastm = sb[EXT_F["last_mounted"]:EXT_F["last_mounted"] + 64]
        lastm = lastm.split(b"\x00")[0].decode("utf-8", "replace")
        uid = sb[EXT_F["uuid"]:EXT_F["uuid"] + 16].hex()
        st = _e(sb, "state", 2)
        used = total - free
        lines = [
            f"label        {label or '(none)'}",
            f"last mounted {lastm or '(none)'}",
            f"uuid         {uid}",
            f"made         {stamp(_e(sb, 'mkfs_time'))}",
            f"last mount   {stamp(_e(sb, 'mtime'))}   mount count "
            f"{_e(sb, 'mnt_count', 2):,}",
            f"last write   {stamp(_e(sb, 'wtime'))}",
            f"used         {human(used)} of {human(total)} "
            f"({100.0*used/total:.1f}%)" if total else "used         unknown",
            f"written      {_e(sb, 'kbytes_written', 8)/1048576:,.1f} GiB over its life",
            f"state        0x{st:04x}  "
            + ("cleanly unmounted" if st & EXT_VALID_FS
               else "NOT cleanly unmounted, so it may have been live at acquisition"),
        ]
        ec = _e(sb, "error_count")
        if ec:
            lines.append(f"errors       {ec:,} recorded")
        return kind, lines

    ifs = identify_ifs(fh, base)
    if ifs:
        return "QNX IFS boot image", ifs

    apfs = identify_apfs(fh, base)
    if apfs:
        return apfs

    hfs = identify_hfsplus(fh, base)
    if hfs:
        return hfs

    refs = identify_refs(fh, base, size)
    if refs:
        return refs

    ntfs = identify_ntfs(fh, base)
    if ntfs:
        return ntfs

    fat = identify_fat(fh, base)
    if fat:
        return fat

    f2fs = identify_f2fs(fh, base)
    if f2fs:
        return f2fs

    efs = identify_efs(fh, base, size)
    if efs:
        return efs

    etfs = identify_etfs(fh, base, size)
    if etfs:
        return etfs

    # YAFFS last: it has no magic at all, so it is found by trying page and
    # spare layouts, which is the costliest test and the one least specific to
    # any single offset.
    yaffs = identify_yaffs(fh, base, size)
    if yaffs:
        return yaffs

    # Not ext, not qnx6, not IFS, not FAT, not a QNX flash filesystem. Report
    # the leading bytes so there is a lead to follow, rather than inventing a
    # signature for it.
    head = read_at(fh, base, 16)
    if not head:
        return None, []
    printable = "".join(chr(c) if 32 <= c < 127 else "." for c in head)
    ascii_magic = ""
    run = bytes(c for c in head[:8] if 32 <= c < 127)
    if len(run) >= 3:
        ascii_magic = f'   leading ascii "{run.decode()}"'
    return None, [f"first 16 bytes  {head.hex(' ')}",
                  f"                |{printable}|{ascii_magic}"]


def human(n):
    if abs(n) < 1024:
        return f"{n:,.0f} B"
    n /= 1024
    for u in ("KiB", "MiB", "GiB", "TiB"):
        if abs(n) < 1024:
            return f"{n:,.1f} {u}"
        n /= 1024
    return f"{n:,.1f} PiB"


def scan(fh, limit, size, cap=400):
    hits, step = [], 1 << 22
    pats = ((struct.pack("<I", QNX6_MAGIC), 1), (struct.pack(">I", QNX6_MAGIC), 1))
    off = 0
    while off < min(limit, size) and len(hits) < cap:
        buf = read_at(fh, off, step + 4)
        if not buf:
            break
        for pat, _ in pats:
            p = buf.find(pat)
            while p != -1 and len(hits) < cap:
                hits.append(off + p)
                p = buf.find(pat, p + 1)
        off += step
    return sorted(set(hits))


def sanitize_volume_label(label, max_len=24):
    """A partition or filesystem label, reduced to zip-and-shell-safe form."""
    cleaned = re.sub(r"[^A-Za-z0-9]+", "_", label).strip("_").lower()
    return cleaned[:max_len].rstrip("_")


def volume_name(part_idx, lba, label=""):
    """The canonical directory name a volume extracts under.

    Built from the partition table, not from the filesystem: the LBA is a
    physical fact about the image that any partition tool reproduces, so it is
    the identity, and it cannot collide because two volumes cannot share a
    start sector. The index gives readability where a table provides one, and
    a label rides along as a suffix, never as the identity, so two partitions
    labelled alike still extract into distinct directories.

        p2_lba65536                   MBR primary 2
        p5_lba4259872                 first logical volume (numbered from 5,
                                      as operating systems do)
        p9_lba737280_storage          GPT partition with its name
        lba0                          no partition table at all: a whole-disk
                                      filesystem or a bare region, which is
                                      how ETFS commonly arrives

    The earlier scheme took the last word of the display label, which made
    "...System Partition" and "...Data Partition" extract into the same
    directory and silently merge.
    """
    stem = f"p{part_idx}_lba{lba}" if part_idx is not None else f"lba{lba}"
    suffix = sanitize_volume_label(label) if label else ""
    return f"{stem}_{suffix}" if suffix else stem


# The MBR type bytes that mark an extended partition container. main() keeps
# the same tuple as a local; a consumer of volumes() needs it by name.
EXT_PARTITION_TYPES = (0x05, 0x0f, 0x85)


# ---------------------------------------------------------------------------
# Configuration stores on flash
#
# A flash chip also carries name=value stores that are not filesystems: the
# U-Boot environment, and on Belkin WeMo devices Belkin's libnvram store. The
# report names a store by its layout, which does not say which program wrote it.
# Neither has a directory, so each is given as a volume holding one file, the
# store's bytes as they sit on the chip, for a consumer to parse. Both are
# accepted only on a CRC-32 that holds over the store, and a store's size is the
# one its CRC holds for, tried in 4 KiB steps up to CFG_STORE_MAX.
#
# U-Boot's environment layout, env_t in include/env_internal.h at v2024.01
# (https://github.com/u-boot/u-boot/blob/866ca972d6c3cabeaf6dbac431e8e08bb30b3c8e/include/env_internal.h#L80-L86):
# a little-endian CRC-32, a flags byte only when the board keeps a redundant copy
# (ENV_HEADER_SIZE, lines 59-61), then CONFIG_ENV_SIZE less that header of
# NUL-separated name=value strings ending in an empty one. env_import() checks
# crc32(0, data, ENV_SIZE) before it reads them
# (https://github.com/u-boot/u-boot/blob/866ca972d6c3cabeaf6dbac431e8e08bb30b3c8e/env/common.c#L310).
#
# Belkin libnvram store, env_image_gemtek in Belkin's own libnvram source (its
# header carries Belkin's copyright), as found in a public copy of the WeMo firmware
# tree (https://github.com/svenschwermer/wemo/blob/46d0ccd248806e8e07210f9b34166b127e9d3d52/package/belkin_nvram_bd/src/libnvram.c#L97-L108):
# "NVRM", a CRC-32, an entry count and the offset of the end of the data, then
# NUL-separated name=value strings. The CRC covers the partition less the
# 16-byte header (lines 853-874); the count and end of data are written after it,
# from the index of strings (lines 420-450 and 1165-1178).
# ---------------------------------------------------------------------------
CFG_STORE_MAX = 256 << 10         # the largest store size tried
CFG_KINDS = ("nvram", "uboot-env")
NVRM_MAGIC = b"NVRM"
NVRM_HEADER = 16
_CFG_NAME = re.compile(rb"[A-Za-z0-9_.:+-]{1,64}=")   # what a store's first string opens with


def _cfg_crc_size(fh, base, start, crc, room):
    """The smallest size, a multiple of 4 KiB and at most room and CFG_STORE_MAX,
    for which the CRC-32 of the bytes from base + start to base + size is crc,
    or None. One read and one pass, whatever the number of sizes tried."""
    buf = read_at(fh, base, max(0, min(room, CFG_STORE_MAX)))
    c, done = 0, start
    for size in range(FLASH_ALIGN, len(buf) + 1, FLASH_ALIGN):
        if size <= start:
            continue
        c = binascii.crc32(buf[done:size], c)
        done = size
        if c == crc:
            return size
    return None


def cfg_strings(data):
    """(strings, ended): the NUL-separated strings of a store's data, up to the
    first empty one, and whether that empty one was found inside data."""
    items, pos = [], 0
    while pos < len(data):
        end = data.find(b"\x00", pos)
        if end < 0:
            return items, False
        if end == pos:
            return items, True
        items.append(data[pos:end])
        pos = end + 1
    return items, False


def nvram_store(fh, base, room):
    """(size, count, eod) for a libnvram store at base whose CRC-32 holds, else
    None. count and eod are as the header stores them; the CRC does not cover
    them, and libnvram rebuilds both from the strings, so they are reported and
    not checked."""
    head = read_at(fh, base, NVRM_HEADER)
    if len(head) < NVRM_HEADER or head[:4] != NVRM_MAGIC:
        return None
    crc, count, eod = struct.unpack_from("<III", head, 4)
    size = _cfg_crc_size(fh, base, NVRM_HEADER, crc, room)
    if size is None:
        return None
    return size, count, eod


def uboot_env_store(fh, base, room):
    """(size, header, flags) for a U-Boot environment at base whose CRC-32 holds
    and whose strings end inside it, else None. header is 4 for a single copy and
    5 for one of a redundant pair, whose flags byte is returned (else None)."""
    head = read_at(fh, base, 5 + 65)
    if len(head) < 8:
        return None
    crc = struct.unpack_from("<I", head)[0]
    for hdr in (4, 5):
        if not _CFG_NAME.match(head, hdr):
            continue
        size = _cfg_crc_size(fh, base, hdr, crc, room)
        if size is None:
            continue
        strings, ended = cfg_strings(read_at(fh, base + hdr, size - hdr))
        if ended and strings:
            return size, hdr, (head[4] if hdr == 5 else None)
    return None


def _erased_after(fh, start, end):
    """True when every byte from start to end (or the end of the image) is 0xFF."""
    pos = start
    while pos < end:
        chunk = read_at(fh, pos, min(1 << 20, end - pos))
        if not chunk:
            return True
        if chunk.strip(b"\xff"):
            return False
        pos += len(chunk)
    return True


def identify_nvram(fh, base, size):
    """Return ("nvram", lines) for a libnvram store at base that fills the region
    or is followed only by erased flash, else None."""
    st = nvram_store(fh, base, size)
    if not st or not _erased_after(fh, base + st[0], base + size):
        return None
    n, count, eod = st
    strings, _ = cfg_strings(read_at(fh, base + NVRM_HEADER, n - NVRM_HEADER))
    return "nvram", [
        "format       Belkin libnvram store (NVRM header), CRC-32 holds",
        f"store        {human(n)}, {len(strings)} name=value strings "
        f"(header count {count}, end of data at {eod})",
        "file         nvram.bin, the store's bytes as held on flash"]


def identify_uboot_env(fh, base, size):
    """Return ("uboot-env", lines) for a U-Boot environment at base that fills
    the region or is followed only by erased flash, else None. The second
    condition keeps a dump that merely begins with an environment from being
    taken for one, so its other regions are still searched (flash_regions)."""
    st = uboot_env_store(fh, base, size)
    if not st or not _erased_after(fh, base + st[0], base + size):
        return None
    n, hdr, flags = st
    strings, _ = cfg_strings(read_at(fh, base + hdr, n - hdr))
    layout = ("a 4-byte header, the single-copy layout" if hdr == 4 else
              f"a 5-byte header, the redundant-copy layout (flags byte {flags})")
    return "uboot-env", [
        "format       U-Boot's environment layout (env_t), CRC-32 holds; the layout "
        "does not say which program wrote the store",
        f"store        {human(n)}, {layout}, {len(strings)} name=value strings",
        "file         uboot-env.bin, the store's bytes as held on flash"]


class ConfigStoreWalker:
    """A configuration store as a volume holding one file: the store's bytes, as
    held on flash, under name. It records no time, so none is reported."""
    root = 1
    _FILE = 2

    def __init__(self, fh, base, size, name):
        self.fh, self.base, self.size, self.name = fh, base, size, name

    def listdir(self, node):
        return [(self.name, self._FILE)] if node == self.root else []

    def entry(self, node):
        if node == self.root:
            return (S_IFDIR | 0o555, 0, None)
        if node == self._FILE:
            return (S_IFREG | 0o444, self.size, None)
        return None

    def read_file(self, node, size):
        if node == self._FILE:
            yield read_at(self.fh, self.base, min(size, self.size))


# A raw NOR or NAND dump has no partition table: the kernel learns the MTD
# partitions from the device tree or its command line, which the dump does not
# carry. The bootloader usually sits at offset 0, so nothing is recognised
# there, and the filesystems start further in at eraseblock boundaries. They
# are found here by their own headers, each checked the way identification
# checks it, and each given its own extent.
FLASH_SCAN_MAX = 8 << 30          # a bigger unpartitioned image is not a flash chip
FLASH_ALIGN = 4096                # every eraseblock size is a multiple of this


def _ext_primary_size(fh, off, room):
    """The byte size of the ext2/3/4 filesystem whose primary superblock is at
    off + 1024, or None if what sits there is not one.

    The magic is two bytes, which data of any kind carries by chance, so the
    filesystem behind it has to read: its root directory, inode 2, has to come
    back as a directory through the group descriptors (struct ext4_super_block
    and ext4_group_desc, fs/ext4/ext4.h). Two fields are checked first. The
    block size has to be 1 to 64 KiB: it is computed as 1024 shifted by a
    stored number, and a random one builds an integer of hundreds of megabytes
    (480 MiB for 0xF0000000) before the read behind it fails. And the
    superblock has to name block group 0 (s_block_group_nr at 0x5A): a backup
    copy names its own group, and a copy of the filesystem behind it can read
    as well as the real one.
    """
    sb = read_at(fh, off + EXT_SB_OFF, 1024)
    if len(sb) < 1024 or _e(sb, "magic", 2) != EXT_MAGIC:
        return None
    lbs = _e(sb, "log_block_size")
    if lbs > 6 or int.from_bytes(sb[0x5A:0x5C], "little") != 0:
        return None
    bs = 1024 << lbs
    blocks = _e(sb, "blocks_count")
    if _e(sb, "feature_incompat") & 0x80:                     # EXT4_FEATURE_INCOMPAT_64BIT
        blocks |= int.from_bytes(sb[0x150:0x154], "little") << 32
    try:
        root = ExtWalker(fh, off).entry(2)
    except Exception:
        return None
    if not root or root[0] & S_IFMT != S_IFDIR:
        return None
    return min(blocks * bs, room) or None


def flash_regions(fh, size):
    """[(label, base, size)] for the flash filesystems found inside an image
    with no partition table, in image order. Only aligned offsets are tried:

      SquashFS  "hsqs" whose superblock and root inode read (identify_squashfs);
                its extent is the bytes_used it records, rounded up to 4 KiB
      UBI       an erase counter header whose CRC holds; its extent runs over
                the following eraseblocks that carry a header of the same
                image_seq or are erased
      JFFS2     a node whose header CRC holds; JFFS2 has no size of its own, so
                its extent runs to the next filesystem found, or the end, and a
                region holding two JFFS2 partitions side by side is cut into
                them (jffs2_filesystems)
      ext2/3/4  a primary superblock (block group 0) whose root directory reads
                (_ext_primary_size); its extent is the block count it records.
                An eMMC image from an embedded device can hold its partitions
                with no table the image carries (the kernel can take the layout
                from its command line, blkdevparts= in block/partitions/
                cmdline.c), and its writable data can sit in ext4 there
      NVRM      a Belkin libnvram store whose CRC-32 holds (nvram_store); its
                extent is the size that CRC holds for
      U-Boot    an environment whose first string opens with a name and "="
                and whose CRC-32 holds (uboot_env_store); its extent likewise
      EFS       a QNX F3S partition, found by its boot record wherever in the
                partition wear levelling left it and placed by the record's
                unit_index (efs_partitions); its extent is the unit count the
                record gives. The signature is looked for at every offset, not
                only aligned ones, and the partition's start is aligned to its
                own unit size

    A configuration store is not a filesystem, but it has an extent of its own
    and sits in its own MTD partition, so a JFFS2 in front of it ends there.
    A backup superblock names its own block group, so it is never taken for a
    filesystem, and a hit inside a filesystem already found (an ext image kept
    as a file, a backup copy) is skipped.

    Returns [] when the image is larger than FLASH_SCAN_MAX or holds none."""
    if size > FLASH_SCAN_MAX:
        return []
    hits = set()
    efs_sigs = []
    step = 1 << 20
    pos = 0
    while pos < size:
        chunk = read_at(fh, pos, min(step + EXT_SB_OFF + 64, size - pos))
        if not chunk:
            break
        j = chunk.find(EFS_SIG)
        while 0 <= j < step:
            efs_sigs.append(pos + j)
            j = chunk.find(EFS_SIG, j + 1)
        for magic in (b"hsqs", b"UBI#", b"\x85\x19", b"\x19\x85", NVRM_MAGIC):
            j = chunk.find(magic)
            while 0 <= j < step:
                if (pos + j) % FLASH_ALIGN == 0:
                    hits.add((pos + j, magic))
                j = chunk.find(magic, j + 1)
        m = EXT_SB_OFF + EXT_F["magic"]                # pos is a multiple of FLASH_ALIGN
        for k in range(0, min(step, len(chunk) - m - 1), FLASH_ALIGN):
            if chunk[k + m:k + m + 2] == b"\x53\xef":
                hits.add((pos + k, b"ext"))
            if _CFG_NAME.match(chunk, k + 4) or _CFG_NAME.match(chunk, k + 5):
                hits.add((pos + k, b"env"))       # a U-Boot environment's first string
        pos += step
    efs = {p["base"]: p["size"] for p in _efs_partitions_from_sigs(fh, size, efs_sigs)}
    hits.update((base, b"efs") for base in efs)
    found, taken_to = [], 0
    for off, magic in sorted(hits):
        if off < taken_to:
            continue
        if magic == b"efs":
            found.append(["efs", off, efs[off]])
        elif magic == b"hsqs":
            if not identify_squashfs(fh, off, size - off):
                continue
            used = struct.unpack("<Q", read_at(fh, off + 40, 8))[0]
            ext = min(size - off, -(-used // FLASH_ALIGN) * FLASH_ALIGN)
            found.append(["squashfs", off, ext])
        elif magic == b"UBI#":
            ec = _ubi_ec(read_at(fh, off, 64))
            if ec is None:
                continue
            peb = ubi_peb_size(fh, off, size - off) or (size - off)
            end = off + peb
            while end + peb <= size:
                head = read_at(fh, end, 64)
                nxt = _ubi_ec(head)
                if nxt is not None and nxt[2] == ec[2]:
                    end += peb
                elif head == b"\xff" * 64 and read_at(fh, end, peb).strip(b"\xff") == b"":
                    end += peb
                else:
                    break
            found.append(["ubi", off, end - off])
        elif magic == b"ext":
            ext = _ext_primary_size(fh, off, size - off)
            if not ext:
                continue
            kind = identify_fs(fh, off, ext)[0]
            if not (kind or "").startswith("ext"):
                continue
            found.append([kind, off, ext])
        elif magic == NVRM_MAGIC:
            st = nvram_store(fh, off, size - off)
            if not st:
                continue
            found.append(["nvram", off, st[0]])
        elif magic == b"env":
            st = uboot_env_store(fh, off, size - off)
            if not st:
                continue
            found.append(["uboot-env", off, st[0]])
        else:
            e = "<" if magic == b"\x85\x19" else ">"
            hdr = read_at(fh, off, 12)
            m, ntype, totlen, hcrc = struct.unpack(e + "HHII", hdr)
            if m != JFFS2_MAGIC or _kcrc32(struct.pack(e + "HHI", m, ntype | JFFS2_ACCURATE,
                                                       totlen)) != hcrc:
                continue
            if found and found[-1][0] == "jffs2":
                continue                          # still inside the same JFFS2
            found.append(["jffs2", off, None])
        if found[-1][2] is not None:
            taken_to = found[-1][1] + found[-1][2]
    for i, reg in enumerate(found):              # JFFS2 runs up to what follows it
        if reg[2] is None:
            nxt = next((r[1] for r in found[i + 1:] if r[1] > reg[1]), size)
            reg[2] = nxt - reg[1]
    out = []
    for kind, off, ext in found:                 # side-by-side JFFS2 partitions
        pieces = jffs2_filesystems(fh, off, ext) if kind == "jffs2" else [(off, ext)]
        out += [(f"flash @{o:#x} {kind}", o, n) for o, n in pieces]
    return out


def raw_flash_layout(fh, size):
    """The flash_regions() of an image with no partition table, or [] when a
    filesystem opens the image at offset 0 and holds it whole. An image that
    opens with JFFS2 is split with jffs2_filesystems() too, since a dump of two
    JFFS2 partitions side by side opens with the first of them."""
    kind = identify_fs(fh, 0, size)[0]
    if kind == "jffs2":
        pieces = jffs2_filesystems(fh, 0, size)
        return [(f"flash @{o:#x} jffs2", o, n) for o, n in pieces] if len(pieces) > 1 else []
    return [] if kind else flash_regions(fh, size)


def _luks_regions(fh, regions, names, ss):
    """Add the data region of each opened LUKS container whose own region is among
    ``regions`` and whose data is not yet; returns what was added."""
    added = []
    for base, lk in sorted((getattr(fh, "luks", None) or {}).items()):
        data = base + lk.offset
        if any(r[1] == base for r in regions) and not any(r[1] == data for r in regions):
            region = (f"LUKS {lk.label}", data, lk.data_size)
            regions.append(region)
            names[data] = f"luks_lba{data // ss}"
            added.append((region, lk))
    return added


def table_regions(fh):
    """(regions, names, containers, protective, sector size) from the image's
    partition tables alone: MBR primaries, the logical volumes of the EBR chain
    and GPT entries. Reads no filesystem, so an identifier may call it.
    """
    regions, names = [], {}
    containers, protective = set(), set()
    # Read first, reported last: the sector size the GPT header was found at is
    # the unit every LBA on this disk counts, the MBR's included.
    gpt = parse_gpt(fh)
    ss = gpt.sector_size if gpt is not None else SECTOR
    parts = parse_mbr(fh)
    if parts:
        for idx, t, st, cnt in parts:
            regions.append((f"MBR part {idx}", st * ss, cnt * ss))
            names[st * ss] = volume_name(idx, st)
            if t in EXT_PARTITION_TYPES:
                containers.add(f"MBR part {idx}")
            if t == 0xEE:
                protective.add(f"MBR part {idx}")
        logical_idx = 4               # logical volumes number from 5, as OSes do
        for idx, t, st, cnt in parts:
            if t not in EXT_PARTITION_TYPES:
                continue
            base, cur, n = st, st, 0
            while cur and n < 64:
                ebr = read_at(fh, cur * ss, 512)
                if len(ebr) < 512 or ebr[510:512] != b"\x55\xaa":
                    break
                e1, e2 = ebr[446:462], ebr[462:478]
                lst, lcnt = struct.unpack("<II", e1[8:16])
                if lcnt:
                    astart = cur + lst
                    regions.append((f"logical @{astart}", astart * ss, lcnt * ss))
                    logical_idx += 1
                    names[astart * ss] = volume_name(logical_idx, astart)
                nxt = struct.unpack("<I", e2[8:12])[0]
                cur = (base + nxt) if nxt else 0
                n += 1
    if gpt:
        for idx, name, _g, first, last in gpt:
            sz = (last - first + 1) * ss
            regions.append((f"GPT part {idx} {name[:20]}", first * ss, sz))
            names[first * ss] = volume_name(idx, first, name)
    return regions, names, containers, protective, ss


def partition_regions(fh, size):
    """(regions, names, containers, protective) for an image, as main() sees them.

    regions is [(label, base, size)] in report order: MBR primaries, then the
    logical volumes found by walking the EBR chain, then GPT entries, or the
    whole image as one region when no table is present. names maps a region's
    byte offset to the directory an extraction uses (volume_name); containers
    holds the labels of extended partition containers, which hold the logical
    volumes and are not themselves volumes; protective holds the 0xEE entry a
    GPT disk carries in its MBR.
    """
    regions, names, containers, protective, ss = table_regions(fh)
    if not regions:
        flash = raw_flash_layout(fh, size)
        for label, base, rsize in flash:
            regions.append((label, base, rsize))
            names[base] = volume_name(None, base // SECTOR)
        if not flash:
            regions.append(("whole image", 0, size))
            names[0] = volume_name(None, 0)
    # The data of each LUKS container unlock_luks() opened is a region too, at
    # its own offset, read decrypted there (LuksImage); and the linear logical
    # volumes of any LVM2 physical volume among them (lvm_volumes). A container
    # can sit inside a logical volume, so its data is looked for again after.
    _luks_regions(fh, regions, names, ss)
    lvs, _notes = lvm_volumes(fh, [r for r in regions
                                   if r[0] not in containers and r[0] not in protective], ss)
    for label, base, rsize, name in lvs:
        regions.append((label, base, rsize))
        names[base] = name
    _luks_regions(fh, regions, names, ss)
    return regions, names, containers, protective


def _ext_label(fh, base):
    """An ext volume's label, or its last mount point when it has no label."""
    sb = read_at(fh, base + EXT_SB_OFF, 1024)
    lab = sb[EXT_F["volume_name"]:EXT_F["volume_name"] + 16]
    lab = lab.split(b"\x00")[0].decode("utf-8", "replace")
    mnt = sb[EXT_F["last_mounted"]:EXT_F["last_mounted"] + 64]
    mnt = mnt.split(b"\x00")[0].decode("utf-8", "replace")
    return lab or mnt.strip("/").replace("/", "_")


def volumes(fh, size=None):
    """Every volume main() would list or extract, in report order, as dicts.

    This is the callable form of the discovery main() does while it prints.
    The window's Contents pane and the LEAPP tools read images through it, so
    a volume here is a volume in the report: `qnxprobe_gui.py --check-discovery
    IMAGE` proves that against the report text for any image.

    Each dict carries:
        label       the region as the report names it ("GPT part 3 storage")
        base, size  byte offset and byte length of the region
        lba         base in the disk's logical sectors (4096 bytes on a disk
                    whose GPT header is at byte 4096, else 512), the identity
                    an extraction is named by
        kind        "qnx6", "ext4", "fat32", "ntfs", ..., "extended container",
                    or "not recognised"
        name        the directory the volume extracts under (volume_name)
        detail      a short description from the identifier
        missing_past_end
                    bytes of the region that lie past the end of the image; a
                    positive value means the file holds only part of this
                    volume (a lone first segment of a split image reads so)
        walker      an object with root, listdir, entry and read_file, when the
                    kind is one this reads; else
        note        why there is no walker
        bitlocker   for a BitLocker volume, locked or opened, BitLocker.facts():
                    its protectors (kind, id, and for a TPM the stored PCRs)

    Brute-scan finds are report-only in main() too (they have no region and so
    no base to walk), so they are not here either. fh is what open_image()
    returns; size defaults to image_size(fh).
    """
    if size is None:
        size = image_size(fh)
    # The logical volumes that need a map (split into runs, or striped) are read
    # through one, placed past the image's end (lvm_image); a placed volume is
    # not "past the end" of anything, and its own map says what it misses.
    fh = lvm_image(fh, size)
    regions, names, containers, protective = partition_regions(fh, size)
    ss = disk_sector_size(fh)
    placed = set((getattr(fh, "lvm_virtual", None) or {}).values())
    missing = {start: gap for _lab, start, _rs, gap in
               short_regions(size, [r for r in regions if r[1] not in placed], skip=protective)}
    for b in placed:
        missing[b] = fh.lvm_map_for(b).missing(size)
    lvm_spare = None
    out, qnx6_labels = [], set()
    # A disk whose own end carries DDF or IMSM metadata: a mirror's volumes
    # are read and say so; any other's are named and not walked.
    disk_raid = raid_foreign_disk(fh, size)

    for label, base, rsize in regions:
        best = None
        for off, _rel in sb_slots(fh, base, label, regions):
            r = check(fh, off)
            if r and not r[2] and (best is None or r[1]["serial"] > best[1]["serial"]):
                best = (off, r[1])
        if best is None:
            continue
        qnx6_labels.add(label)
        vol = dict(label=label, base=base, size=rsize, lba=base // ss, kind="qnx6",
                   name=names.get(base) or f"lba{base // ss}",
                   detail=f"serial {best[1]['serial']:,}, "
                          f"volumeid {best[1]['volumeid'].hex()} (as stored)",
                   missing_past_end=missing.get(base, 0))
        try:
            vol["walker"] = Qnx6Walker(fh, base, best[0] - base)
        except Exception as exc:                        # report it, do not hide it
            vol["note"] = f"could not walk this filesystem: {exc}"
        out.append(vol)

    for label, base, rsize in regions:
        if label in qnx6_labels or label in protective:
            continue
        if label in containers:
            out.append(dict(label=label, base=base, size=rsize, lba=base // ss,
                            kind="extended container", name="", detail="",
                            missing_past_end=missing.get(base, 0),
                            note="holds the logical volumes, nothing to walk"))
            continue
        kind, lines = identify_fs(fh, base, rsize)
        stem = names.get(base) or f"lba{base // ss}"
        vol = dict(label=label, base=base, size=rsize, lba=base // ss,
                   kind=kind or "not recognised", name=stem,
                   detail="; ".join(lines[:2]), missing_past_end=missing.get(base, 0))
        # A BitLocker volume unlock_bitlocker() opened reads as the filesystem inside
        # it, and says so; one it did not open says why and what would open it.
        opened = getattr(fh, "bitlocker", {}).get(base)
        if opened is not None:
            vol["encryption"] = opened.summary()
            vol["detail"] = "; ".join([opened.summary()] + lines[:1])
            vol["bitlocker"] = opened.facts()
        if kind == "bitlocker":
            bl = next((b for b in getattr(fh, "bitlocker_found", ()) if b.base == base), None)
            bl = bl or BitLocker.open(fh, base, rsize)
            vol["encryption"] = "BitLocker, locked"
            vol["note"] = bl.locked_note() if bl else "BitLocker-encrypted and not read"
            if bl:
                vol["bitlocker"] = bl.facts()
            out.append(vol)
            continue
        try:
            if kind and kind.startswith("ext"):
                ext_name = _ext_label(fh, base)
                suffix = sanitize_volume_label(ext_name) if ext_name else ""
                if suffix and not stem.endswith(f"_{suffix}"):
                    vol["name"] = f"{stem}_{suffix}"
                vol["walker"] = ExtWalker(fh, base)
            elif kind == "QNX IFS boot image":
                vol["walker"] = IfsWalker(fh, base)
            elif kind == "luks":
                lk = (getattr(fh, "luks", None) or {}).get(base) or next(
                    (x for x in getattr(fh, "luks_found", ()) if x.base == base), None) \
                    or Luks.open(fh, base, rsize)
                vol["encryption"] = lk.summary() if lk else "LUKS"
                if base in placed:
                    # unlock_luks() reads the image's regions, and a volume read
                    # through a map is not one of them
                    vol["note"] = ("LUKS-encrypted and not read: it is inside a logical volume "
                                   "read through a map, where a LUKS container is not opened")
                else:
                    vol["note"] = (f"a LUKS container, opened: its data is listed as LUKS {lk.label}"
                                   if lk is not None and lk.mk is not None else
                                   (lk.locked_note() if lk is not None else "LUKS-encrypted and not read"))
            elif kind == "linux md member":
                vol["note"] = ("a RAID member: its array is read from all its members "
                               "together (raid_assemble, or several images on the command "
                               "line), not from this region alone")
            elif kind == "raid member":
                vol["note"] = lines[0] if lines else "a member of a RAID set this does not read"
            elif kind == "lvm2 pv":
                # The logical volumes not read are said here too, where a caller
                # that prints only the note (the LEAPP run log) will show them.
                skipped = [ln[len("logical volume "):].replace(": not read (", " (", 1) for ln in lines
                           if ln.startswith("logical volume ") and ": not read (" in ln]
                vol["note"] = ("an LVM2 physical volume: each logical volume read from it "
                               "is listed as a volume of its own"
                               + ("; not read: " + "; ".join(skipped) if skipped else ""))
                # Its extents no logical volume holds are its free space
                # (write_unallocated), at their own offsets in the image.
                if lvm_spare is None:
                    lvm_spare = lvm_free_extents(fh, [r for r in regions if not r[0].startswith("LVM ")
                                                      and r[0] not in containers
                                                      and r[0] not in protective], ss)
                vol["free_extents"] = list(lvm_spare.get(base, []))
            elif kind:
                vol["walker"] = walker_for(kind, fh, base, rsize)
                if vol["walker"] is None:
                    vol["note"] = "recognised, but no walker for this kind"
            else:
                vol["note"] = "not a filesystem this tool reads"
        except IfsUnsupported as exc:
            vol["note"] = f"contents not read: {exc}"
        except Exception as exc:
            vol["note"] = f"could not walk this filesystem: {exc}"
        # A walker that is built but cannot read its volume here says why, for
        # a zstd SquashFS on a Python without zstd, whose listing comes back
        # empty rather than raising.
        wnote = getattr(vol.get("walker"), "note", None)
        if wnote and "note" not in vol:
            vol["note"] = wnote
        # a mirror member's own region (identify_fs) is read, and says so
        if kind != "raid member":
            mirrored = [ln for ln in lines if ln.startswith("a member of ") and "RAID set" in ln]
            if mirrored:
                vol["note"] = f"{vol['note']}; {mirrored[0]}" if vol.get("note") else mirrored[0]
        out.append(vol)
    # A disk that ends in DDF or IMSM metadata: every volume found on it
    # (partitions, logical volumes, what an opened LUKS or BitLocker volume
    # holds, a qnx6 volume) is read from this one disk, so each is walked only
    # when the metadata records a mirror in its normal state, and says so.
    if disk_raid is not None:
        for vol in out:
            note = vol.get("note") or ""
            if vol.get("kind") == "raid member" or " RAID set, whose array is not assembled" in note:
                continue
            what = ("this volume" if vol.get("label", "").startswith(("LVM ", "LUKS "))
                    or vol.get("kind") == "qnx6" or vol.get("label") == "whole image"
                    else "this partition")
            line = raid_foreign_note(disk_raid["foreign"], disk_raid["levels"], disk_raid["why"],
                                     None if disk_raid["mirror"] else vol.get("kind"), what)
            if disk_raid["mirror"]:
                vol["note"] = f"{note}; {line}" if note else line
            else:
                for key in ("walker", "free_extents"):
                    vol.pop(key, None)
                vol["kind"], vol["note"] = "raid member", line
    # A volume read through a map has no single place on the disk: its base is
    # where lvm_image() put it, so it has no LBA, and the map says where each
    # run of it is in the image.
    luks_data = {b + lk.offset: lk for b, lk in (getattr(fh, "luks", None) or {}).items()}
    for vol in out:
        if vol.get("base") in placed:
            vol["lba"] = None
            vol["lvm_map"] = fh.lvm_map_for(vol["base"])
        if vol.get("base") in luks_data and vol.get("label", "").startswith("LUKS "):
            vol["encryption"] = luks_data[vol["base"]].summary()   # read decrypted
    return out


def open_image_trying(path, segments=None, passwords=(), private_keys=()):
    """open_image with the first of ``passwords`` that opens it, for an encrypted
    Apple disk image, an AD-encrypted acquisition or an encrypted AFF (which the
    first of ``private_keys`` that opens it also opens when it is sealed to a
    certificate); any other image opens with none. Raises ImagePasswordError when
    none of them does (wrong is True) or none was given (wrong is False)."""
    last = None
    for password in list(passwords) or [None]:
        for key in list(private_keys) or [None]:
            try:
                return open_image(path, segments, password=password, private_key=key)
            except ImagePasswordError as exc:
                last = exc
    raise last


UNALLOC_CHUNK = 1 << 20


def write_unallocated(fh, size, vols, out_dir, image_name, only=None, say=print):
    """Copy the free space of each volume in ``vols`` into ``out_dir``.

    ``vols`` is what volumes() returns. For every volume whose reader reports
    free space (free_extents()), the runs are written one after another to
    ``<image_name>.<volume name>.unallocated.bin``, with a tab-separated map
    beside it giving, per run, where it starts in that file, where it came from
    in the image, and its length, so a carve hit maps back to the disk. Returns
    one record per volume looked at, written or not, for unallocated.json.

    What is and is not written, each said in the record's ``status``:

    - a kind with no free_extents() is named as not reporting free space, and
      gets no file;
    - an empty answer gets no file and is called "no free space reported": a
      reader returns the same empty list when it cannot read its allocation map
      and when nothing is free;
    - a run that reaches past the end of the image is cut there, and the bytes
      left out are counted (a FAT32 volume on a partial image reports them);
    - an APFS container's free space is the container's, not a volume's, and is
      copied as stored: what an encrypted volume wrote there stays encrypted;
    - a BitLocker volume that was opened is read through its decryption;
    - space no recognised volume covers (gaps, reserved partitions, an
      unpartitioned tail) is no filesystem's free space and is not written;
    - an existing file is never overwritten.

    Offsets are into the image as open_image() presents it: for an E01, AFF,
    disk image or split set, the disk, not the container file.
    """
    import hashlib, shutil
    records = []
    for vol in vols:
        name = vol.get("name") or f"lba{vol.get('lba', 0)}"
        if only is not None and only.lower() not in f"{vol.get('label', '')} {name}".lower():
            continue
        rec = {"image": image_name, "volume": name, "label": vol.get("label", ""),
               "filesystem": vol.get("kind"), "lba": vol.get("lba"),
               "offset_bytes": None if vol.get("lvm_map") is not None else vol.get("base")}
        if vol.get("lvm_map") is not None:
            rec["lvm_map"] = vol["lvm_map"].describe()
        records.append(rec)
        w = vol.get("walker")
        fn = getattr(w, "free_extents", None)
        if fn is None and vol.get("free_extents") is not None:
            # An LVM2 physical volume: the extents no logical volume holds.
            fn = lambda spare=vol["free_extents"]: list(spare)        # noqa: E731
        if fn is None:
            rec["status"] = ("not written: " + (vol.get("note") or "no reader for this volume")
                             if w is None else
                             f"not written: the {vol.get('kind')} reader does not report free space")
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        try:
            runs = fn()
        except Exception as exc:                     # pylint: disable=broad-except
            rec["status"] = f"not written: the allocation map could not be read ({exc})"
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        lmap = vol.get("lvm_map")
        if lmap is not None:
            # A logical volume read through a map: its reader's runs are offsets
            # in the volume, placed past the image's end, so each becomes the
            # runs of the image it lies on.
            in_volume = sum(n for _o, n in runs)
            runs = [run for off, n in runs
                    for run in lmap.image_runs(off - vol["base"], n)]
            rebuilt = in_volume - sum(n for _o, n in runs)
            if hasattr(lmap, "read_via") and rebuilt > 0:
                # an LVM RAID volume with an image volume missing: free space in
                # its chunks lies on no disk, it is rebuilt, so it has no runs
                rec["rebuilt_bytes_not_written"] = rebuilt
                say(f"    {vol.get('label') or name}: {rebuilt:,} bytes of its free space lie in "
                    "chunks rebuilt from parity, on no disk, and are not written")
        reported = sum(n for _o, n in runs)
        rec["runs_reported"], rec["bytes_reported"] = len(runs), reported
        if not runs:
            rec["status"] = ("not written: no free space reported (the allocation map "
                             "could not be read, or nothing is free)")
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        kept = []
        for off, n in runs:
            if off < size:
                kept.append((off, min(n, size - off)))
        total = sum(n for _o, n in kept)
        if reported - total:
            rec["past_end_of_image_bytes_not_written"] = reported - total
        if not kept:
            rec["status"] = "not written: all the free space reported lies past the end of the image"
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        notes = []
        if vol.get("kind") == "lvm2 pv":
            notes.append("the volume group's extents on this physical volume that no logical "
                         "volume holds; the label and metadata before the first extent, and "
                         "any space past the last, are not included")
        if lmap is not None:
            notes.append("a logical volume read through a map of its runs; the runs written "
                         "are where its free space lies in the image")
        if vol.get("kind") == "apfs":
            notes.append("free space belongs to the APFS container, not to one volume")
            try:
                states = [w.encryption(i) for i in range(len(w.volumes))]
            except Exception:                        # pylint: disable=broad-except
                states = []
            if any(st in ("locked", "unlocked") for st in states):
                notes.append("the container holds an encrypted volume; what it wrote in "
                             "free space is copied as stored, encrypted")
        if vol.get("encryption"):
            notes.append(f"read through {vol['encryption']}")
        stem = f"{image_name}.{name}.unallocated"
        bin_path, map_path = (os.path.join(out_dir, stem + ext) for ext in (".bin", ".tsv"))
        if os.path.exists(bin_path) or os.path.exists(map_path):
            rec["status"] = f"not written: {stem}.bin or its map already exists"
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        room = shutil.disk_usage(out_dir).free
        if room < total:
            rec["status"] = (f"not written: {human(total)} of free space and "
                             f"{human(room)} of room in the output folder")
            say(f"    {vol.get('label') or name}: {rec['status']}")
            continue
        digest, written, short = hashlib.sha256(), 0, 0
        with open(bin_path, "xb") as out, open(map_path, "x", encoding="utf-8",
                                                newline="\n") as mp:
            mp.write("offset_in_file\toffset_in_image\tlength\n")
            for off, n in kept:
                got = 0
                while got < n:
                    data = read_at(fh, off + got, min(UNALLOC_CHUNK, n - got))
                    if not data:
                        break
                    out.write(data)
                    digest.update(data)
                    got += len(data)
                if got:
                    mp.write(f"{written}\t{off}\t{got}\n")
                written += got
                short += n - got
        if short:
            rec["unreadable_bytes_not_written"] = short
        rec.update(status="written", file=stem + ".bin", map=stem + ".tsv",
                   runs=len(kept), bytes=written, sha256=digest.hexdigest())
        if notes:
            rec["notes"] = notes
        say(f"    {vol.get('label') or name}: {len(kept):,} runs, {human(written)} "
            f"-> {stem}.bin")
        if reported - total:
            say(f"        {human(reported - total)} of the free space reported lies past "
                f"the end of the image and was not written")
        if short:
            say(f"        {human(short)} could not be read and was not written")
        for note in notes:
            say(f"        {note}")
    return records


def _cli_passwords(files, env_names):
    """The passwords the command line names: the first line of each file, then each
    environment variable, in that order. Exits naming what cannot be read."""
    out = []
    for path in files:
        try:
            with open(path, "rb") as handle:
                first = handle.read().split(b"\n", 1)[0]
        except OSError as exc:
            sys.exit(f"the password file could not be read: {exc.strerror or exc}")
        out.append(first[:-1] if first.endswith(b"\r") else first)
    for var in env_names:
        if var not in os.environ:
            sys.exit(f"the environment variable {var} is not set")
        out.append(os.environ[var])
    return out


def main(path, scan_limit_mib=256, do_list=False, list_depth=2, list_max=400,
         extract=None, only=None, zf=None, do_triage=False, exclude=None,
         reporter=None, manifest=None, passwords=(), key_files=(), private_keys=(),
         unallocated=None, unallocated_log=None, image=None, name_prefix="", image_info=None,
         allow_unequal_segments=False):
    # a set that is not whole raises SplitImageError; an acquisition's reader joins
    # its own files (an AD-encrypted raw set is numbered like a split image, and its
    # files are ciphertext until the reader decrypts them). An image already open
    # (an assembled RAID array, raid_assemble) is read as given, `path` naming it.
    if image is None:
        segments = [] if acquisition_format(path) else split_segments(
            path, allow_unequal=allow_unequal_segments)
        image = open_image_trying(path, segments, passwords, private_keys)
    else:
        segments = []
    # A BitLocker volume the passwords (as passwords or recovery passwords) or the
    # startup key files open is read decrypted in place; the rest stay locked and
    # the report says so.
    image, bitlocker_found = unlock_bitlocker(image, None, passwords, key_files)
    # An encrypted APFS volume the passwords (as a password or its personal recovery
    # key) open is read decrypted; the rest stay locked and the report says why.
    image, apfs_found = unlock_apfs(image, None, passwords)
    # A LUKS container a passphrase opens is read decrypted, its data a region of
    # its own; the rest stay locked and the report says why.
    image, _luks_found = unlock_luks(image, None, passwords)
    # The LVM2 logical volumes that need a map (split into runs, or striped) are
    # read through one, placed past the image's end (lvm_image).
    image = lvm_image(image)
    size = image_size(image)
    print("=" * 78)
    print(path)
    ewf_parts = [] if segments else list(getattr(image, "paths", []) or [])
    if segments:
        print(f"  one segment of a split image: {len(segments)} segments joined, "
              f"{os.path.basename(segments[0])} .. {os.path.basename(segments[-1])}")
        print(f"    {describe_segment_sizes(image.sizes)}")
        warn = split_structure_warning(segments)
        if warn:
            print(f"  {warn}")
    elif ewf_parts:
        print(f"  {describe_acquisition(image)}")
    print(f"  {size:,} bytes ({human(size)})")
    print("=" * 78)
    # what volumes.json ties each volume to: the one file, or the first
    # segment of the set, with every segment and its size beside it
    image_rec = {"image": os.path.basename(segments[0] if segments else path)}
    if image_info:
        image_rec.update(image_info)
    if segments or ewf_parts:
        # A joined raw set records its own segment sizes; a reader over a
        # container need not, so they are measured here rather than required.
        parts = list(image.paths)
        part_sizes = getattr(image, "sizes", None)
        if part_sizes is None:
            part_sizes = [os.path.getsize(q) for q in parts]
        image_rec["image_segments"] = [{"name": os.path.basename(q), "bytes": s}
                                       for q, s in zip(parts, part_sizes)]
        parent_files = image_parents(image)
        if parent_files:
            image_rec["image_parents"] = parent_files

    candidates, regions, sized_regions, triage = [], [], [], []
    containers, protective = set(), set()
    vol_names = {}                    # byte offset -> canonical extract name
    first_record = len(manifest) if manifest is not None else 0
    with image as fh:
        # The GPT is read before the MBR is reported, because the sector size
        # its header was found at is the unit of every LBA on this disk,
        # the MBR's included (disk_sector_size).
        gpt, gpt_rejected = read_gpt(fh)
        ss = gpt.sector_size if gpt is not None else SECTOR
        image_rec["sector_bytes"] = ss
        parts = parse_mbr(fh)
        if parts is None:
            print("  MBR      none (no 0x55AA signature at offset 510, or "
                  "sector 0 is a filesystem's own boot sector)")
        else:
            gpt_prot = any(t == 0xEE for _, t, _, _ in parts)
            print(f"  MBR      valid, {len(parts)} entries"
                  + ("  (0xEE = GPT protective)" if gpt_prot else ""))
            for idx, t, st, cnt in parts:
                tag = f"   <- {MBR_QNX_TYPES[t]}" if t in MBR_QNX_TYPES else ""
                print(f"    {idx}  type 0x{t:02x}  LBA {st:<12,} {human(cnt*ss):>10}{tag}")
                regions.append((f"MBR part {idx}", st * ss))
                sized_regions.append((f"MBR part {idx}", st * ss, cnt * ss))
                vol_names[st * ss] = volume_name(idx, st)
                if t in (0x05, 0x0f, 0x85):
                    containers.add(f"MBR part {idx}")
                if t == 0xEE:
                    protective.add(f"MBR part {idx}")

        # An extended partition holds the logical volumes; walk the EBR chain,
        # or the largest region of the image is never probed at all.
        EXT = (0x05, 0x0f, 0x85)
        logical_idx = 4               # logical volumes number from 5, as OSes do
        for idx, t, st, cnt in (parts or []):
            if t not in EXT:
                continue
            base, cur, n = st, st, 0
            while cur and n < 64:
                ebr = read_at(fh, cur * ss, 512)
                if len(ebr) < 512 or ebr[510:512] != b"\x55\xaa":
                    break
                e1 = ebr[446:462]; e2 = ebr[462:478]
                lt = e1[4]; lst, lcnt = struct.unpack("<II", e1[8:16])
                if lcnt:
                    astart = cur + lst
                    tag = f"   <- {MBR_QNX_TYPES[lt]}" if lt in MBR_QNX_TYPES else ""
                    print(f"      logical  type 0x{lt:02x}  LBA {astart:<12,}"
                          f" {human(lcnt*ss):>10}{tag}")
                    regions.append((f"logical @{astart}", astart * ss))
                    sized_regions.append((f"logical @{astart}", astart * ss,
                                          lcnt * ss))
                    logical_idx += 1
                    vol_names[astart * ss] = volume_name(logical_idx, astart)
                nxt = struct.unpack("<I", e2[8:12])[0]
                cur = (base + nxt) if nxt else 0
                n += 1

        for at, why in gpt_rejected:
            # A header that fails its own checks is not used, and saying so
            # keeps "not trusted" from reading as "no partition table".
            print(f"\n  GPT      header signature at byte {at:,} NOT USED: {why}")
        if gpt is not None:
            print(f"\n  GPT      valid, {len(gpt)} partition entries"
                  + (f", {ss}-byte logical sectors" if ss != SECTOR else "")
                  + (f", from the backup header at LBA {gpt.header_lba:,}"
                     if gpt.header_lba != 1 else ""))
            for idx, name, g, first, last in gpt:
                sz = (last - first + 1) * ss
                print(f"    {idx:>3}  {name[:26]:<26} {human(sz):>10}  LBA {first:,}")
                regions.append((f"GPT part {idx} {name[:20]}", first * ss))
                sized_regions.append((f"GPT part {idx} {name[:20]}", first * ss, sz))
                vol_names[first * ss] = volume_name(idx, first, name)

        # No partition table at all (a whole-disk filesystem, or a bare region
        # such as an ETFS flash dump) means no regions were recorded. Treat the
        # whole image as one region so it still reaches identify_fs and the
        # walkers, named lba0 by the volume_name fallback.
        if not sized_regions:
            # With nothing recognised at offset 0 either, it may be a raw flash
            # dump: look for the filesystems inside it (flash_regions).
            flash = raw_flash_layout(fh, size)
            if flash:
                print(f"\n  FLASH    no partition table and nothing recognised at offset 0; "
                      f"{len(flash)} flash filesystem(s) found by their own headers")
                for label, base, rsize in flash:
                    print(f"    {label[len('flash '):]:<22} {human(rsize):>10}  "
                          f"at byte {base:,}")
                    sized_regions.append((label, base, rsize))
                    regions.append((label, base))
                    vol_names[base] = volume_name(None, base // SECTOR)
            else:
                sized_regions.append(("whole image", 0, size))
                regions.append(("whole image", 0))
                vol_names[0] = volume_name(None, 0)

        # The data of each LUKS container a passphrase opened is a region of its
        # own, at its offset, read decrypted there.
        def luks_section():
            added = _luks_regions(fh, sized_regions, vol_names, ss)
            if added:
                print(f"\n  LUKS     {len(added)} container(s) opened")
            for (label, data, rsize), lk in added:
                print(f"    {lk.label:<26} {human(rsize):>10}  data at byte {data:,}, {lk.summary()}")
                regions.append((label, data))
        luks_section()
        # An LVM2 physical volume's linear logical volumes, each one run of
        # extents on one physical volume here, are byte ranges of the image like
        # partitions, so they are reported and read as regions of their own.
        lvs, _notes = lvm_volumes(fh, [r for r in sized_regions
                                       if r[0] not in containers and r[0] not in protective], ss)
        if lvs:
            print(f"\n  LVM      {len(lvs)} logical volume(s) read from LVM2 physical volumes")
            for label, base, rsize, name in lvs:
                lmap = getattr(fh, "lvm_map_for", lambda _b: None)(base)
                where = (f"at byte {base:,}" if lmap is None else
                         f"{_lvm_shape_words(lmap)}, read through a map: "
                         + ", ".join(f"{n:,} bytes at {o:,}" for o, n in lmap.image_runs(0, lmap.size)[:4])
                         + (" ..." if len(lmap.image_runs(0, lmap.size)) > 4 else ""))
                print(f"    {label[len('LVM '):]:<26} {human(rsize):>10}  {where}")
                sized_regions.append((label, base, rsize))
                regions.append((label, base))
                vol_names[base] = name
            luks_section()          # a LUKS container inside a logical volume

        # A partition table describes a whole disk and the file may hold only
        # the front of it. FTK Imager and its peers split a raw image into
        # numbered segments (.001, .002, ...) and the first segment carries the
        # table and the boot volumes, so it identifies cleanly and its front
        # volumes read correctly while the volume holding the user data ends
        # past the cut, where every read answers empty. Measured on a Ford Sync
        # G4 image cut at 1,500 MB: the boot partitions extracted in full and
        # the 28.8 GiB storage volume walked to 0 files with nothing raised.
        # Say so here, before any volume is reported as empty.
        short_by = {}                 # region start -> bytes past the end of the file
        # A logical volume read through a map is placed past the end on purpose;
        # what it misses is what its map puts past the end (LvmMap.missing).
        placed = set((getattr(fh, "lvm_virtual", None) or {}).values())
        placed_labels = {lab for lab, st, _rs in sized_regions if st in placed}
        for st in placed:
            if fh.lvm_map_for(st).missing(size):
                short_by[st] = fh.lvm_map_for(st).missing(size)
        short = short_regions(size, sized_regions, skip=set(protective) | placed_labels)
        short += [(lab, st, rs, short_by[st]) for lab, st, rs in sized_regions
                  if lab in placed_labels and short_by.get(st)]
        if short:
            reach = max(st + rs for lab, st, rs in sized_regions
                        if lab not in protective and lab not in placed_labels)
            print("\n  IMAGE IS SHORTER THAN ITS PARTITION TABLE")
            print(f"    the file holds {human(size)}; the partitions it describes "
                  f"reach {human(reach)}")
            for label, st, rs, missing in short:
                short_by[st] = missing
                if missing >= rs:
                    where = "begins past the end of the file  (none of it is here)"
                else:
                    where = f"ends {human(missing)} past the end of the file  (partly here)"
                print(f"    {label:<28} {where}")
            print("    A raw image split into numbered segments (.001, .002, ...) has to be")
            print("    joined before it is read; its first segment alone looks like this.")
            print("    Each volume above is marked INCOMPLETE below, and a file on it that")
            print("    reaches past the end is counted SHORT and stored under a name that")
            print("    says how much of it is here, not as an extracted file.")

        def missing_past_end(base, declared_end=None):
            """Bytes of the volume at base that lie past the end of the file."""
            if base in placed:
                return short_by.get(base, 0)   # a placed volume's own map says (LvmMap.missing)
            missing = short_by.get(base, 0)
            if declared_end is not None:
                missing = max(missing, declared_end - size)
            return max(missing, 0)

        # the two offsets the kernel itself probes, per region and whole-image
        print()
        for label, base in [("image start", 0)] + regions:
            for off, rel in sb_slots(fh, base, label, sized_regions):
                r = check(fh, off)
                if r:
                    candidates.append((off, f"{label} +0x{rel:x}", *r))

        if not candidates:
            print(f"  no superblock at the kernel's offsets; brute scanning first"
                  f" {scan_limit_mib} MiB ...")
            for off in scan(fh, scan_limit_mib << 20, size):
                r = check(fh, off)
                if r:
                    candidates.append((off, "brute scan", *r))

        print()
        # A candidate whose volume id, blocksize and block count match an
        # already-confirmed superblock in the SAME region is another copy of
        # that filesystem, not a chance 4-byte hit. Measured on a Ford Sync G4
        # image: the previous generation of dps_os carries ctime 308 and
        # atime 1, both unset because the build host had no clock, so a
        # timestamp heuristic rejects a genuine superblock. Recorded identity
        # is the stronger signal, so it wins.
        def region(h):
            return h.rsplit(" +0x", 1)[0]
        good = {}
        for off, how, endian, sb, bad in candidates:
            if not bad:
                good.setdefault(region(how), []).append(sb)
        promoted = 0
        for i, (off, how, endian, sb, bad) in enumerate(candidates):
            if not bad:
                continue
            for ref in good.get(region(how), []):
                if (sb["volumeid"] == ref["volumeid"]
                        and sb["blocksize"] == ref["blocksize"]
                        and sb["num_blocks"] == ref["num_blocks"]):
                    candidates[i] = (off, how, endian, sb, [])
                    promoted += 1
                    break

        confirmed = [c for c in candidates if not c[4]]
        rejected  = [c for c in candidates if c[4]]
        if promoted:
            print(f"  {promoted} further cop{'y' if promoted==1 else 'ies'} "
                  f"confirmed by matching volume id, blocksize and block count\n")

        print(f"  {len(candidates)} magic match(es): "
              f"{len(confirmed)} CONFIRMED, {len(rejected)} rejected as coincidence\n")

        # Group the copies by volume, then by serial. The highest serial is
        # the active generation; the one below it is the previous committed
        # state, still on disk.
        # A disk that ends in DDF or IMSM metadata: only a mirror's volumes are
        # walked (raid_foreign_disk); said once, before the volumes.
        disk_raid = raid_foreign_disk(fh, size) if sized_regions else None
        disk_partitioned = not any(lab == "whole image" for lab, _b, _s in sized_regions)
        raid_kind, raid_levels, raid_why, raid_mirror = (
            (disk_raid["foreign"], disk_raid["levels"], disk_raid["why"], disk_raid["mirror"])
            if disk_raid is not None else (None, None, None, False))
        vols = {}
        for off, how, endian, sb, _ in confirmed:
            key = how.rsplit(" +0x", 1)[0]
            vols.setdefault(key, []).append((off, endian, sb))

        if vols:
            print("  HOW TO READ THE TIMESTAMPS  (see --help for the sourcing)")
            print("    sb_ctime is written once when the filesystem is made.")
            print("    sb_atime moves when the filesystem is COMMITTED, not when a file")
            print("    is read. Do not read it as when the device was last used by a")
            print("    person. serial counts commits and is the better measure of how")
            print("    much a volume has been written.")
            print()

        for key, copies in vols.items():
            gens = {}
            for off, endian, sb in copies:
                g = gens.setdefault(sb["serial"], {"sb": sb, "endian": endian, "at": []})
                g["at"].append(off)
            serials = sorted(gens, reverse=True)
            act = gens[serials[0]]
            sb, endian = act["sb"], act["endian"]
            total = sb["num_blocks"] * sb["blocksize"]

            print(f"  CONFIRMED qnx6 filesystem on {key}  [{endian}]")
            print(f"      {len(copies)} superblock cop{'y' if len(copies)==1 else 'ies'}, "
                  f"{len(serials)} generation{'' if len(serials)==1 else 's'}\n")

            match = ""
            for rlabel, rbase, rsize in sized_regions:
                if key.startswith(rlabel) and rsize:
                    match = (f"   <- {100.0*total/rsize:.1f}% of the "
                             f"{human(rsize)} partition it sits in")
                    break

            print(f"      ACTIVE   serial {sb['serial']:,}   at "
                  + ", ".join(f"0x{o:x}" for o in sorted(act["at"])))
            print(f"        sb_ctime   {stamp(sb['ctime'])}")
            print(f"        sb_atime   {stamp(sb['atime'])}")
            print(f"        version    {sb['version1']}.{sb['version2']}   "
                  f"blocksize {sb['blocksize']:,}   flags 0x{sb['flags']:08x}")
            print(f"        volume     {human(total)}  ({sb['num_blocks']:,} blocks, "
                  f"{sb['free_blocks']:,} free){match}")
            print(f"        inodes     {sb['num_inodes']:,} total, "
                  f"{sb['free_inodes']:,} free, "
                  f"{sb['num_inodes']-sb['free_inodes']:,} used")
            print(f"        volumeid   {sb['volumeid'].hex()}  (as stored)")

            if len(serials) > 1:
                prev = gens[serials[1]]
                pb = prev["sb"]
                print(f"\n      PREVIOUS serial {pb['serial']:,}   at "
                      + ", ".join(f"0x{o:x}" for o in sorted(prev["at"]))
                      + "   (still on disk)")
                print(f"        sb_ctime   {stamp(pb['ctime'])}")
                print(f"        sb_atime   {stamp(pb['atime'])}")

                print(f"\n      WHAT CHANGED between the two generations")
                d_ser = sb['serial'] - pb['serial']
                print(f"        serial       +{d_ser:,}"
                      f"   ({'one commit' if d_ser==1 else str(d_ser)+' commits'})")
                print(delta_line("sb_ctime", sb['ctime'], pb['ctime']))
                print(delta_line("sb_atime", sb['atime'], pb['atime']))
                for f, lab in (("free_blocks","block"), ("free_inodes","inode")):
                    d = sb[f] - pb[f]
                    if d == 0:
                        print(f"        {f:<12} unchanged")
                    else:
                        word = lab + ("" if abs(d) == 1 else "s")
                        verb = "freed" if d > 0 else "allocated"
                        print(f"        {f:<12} {d:+,}  ({abs(d):,} {word} {verb})")

            base = next((b for lab, b, _ in sized_regions
                         if key.startswith(lab)), None)
            wanted = only is None or only.lower() in key.lower()
            if raid_kind:
                print("      " + raid_foreign_note(raid_kind, raid_levels, raid_why,
                                                   None if raid_mirror else "qnx6",
                                                   "this volume"))
                wanted = wanted and raid_mirror

            if do_triage and base is not None:
                encf = (0, 0)
                try:
                    tw = Qnx6Walker(fh, base, sorted(act["at"])[0] - base)
                    encf = sample_encryption(tw)
                except Exception:
                    pass
                used = (sb["num_blocks"] - sb["free_blocks"]) * sb["blocksize"]
                triage.append(triage_row(
                    key.split("part", 1)[-1].strip() if "part" in key else key,
                    "qnx6", sb["num_blocks"] * sb["blocksize"], used,
                    sb["serial"], f"{sb['serial']:,} commits, "
                    f"{sb['num_inodes'] - sb['free_inodes']:,} inodes used",
                    stamp(sb["atime"]).replace(" UTC", ""), encf))

            if do_list and base is not None and wanted:
                print(f"\n      CONTENTS  (depth {list_depth})")
                try:
                    w = Qnx6Walker(fh, base, sorted(act["at"])[0] - base)
                    print_tree(w, w.root, 1, list_depth, [list_max])
                except Exception as exc:
                    print(f"        could not walk this filesystem: {exc}")

            if zf is not None and base is not None and wanted:
                vol = name_prefix + (vol_names.get(base) or f"lba{base // ss}")
                print(f"\n      EXTRACTING to {extract}  as {vol}/")
                try:
                    w = Qnx6Walker(fh, base, sorted(act["at"])[0] - base)
                    ents = collect(w, w.root)
                    ents, dropped = apply_exclude(ents, exclude)
                    log = []
                    miss = missing_past_end(base, base + total)
                    f_, wr, sk, fa, sh = extract_to_zip(zf, w, vol, ents, log, reporter)
                    if manifest is not None:
                        rsize = next((r[2] for r in sized_regions if r[1] == base), None)
                        manifest.append({
                            "volume": vol, **image_rec,
                            "lba": base // ss, "offset_bytes": base,
                            "partition_size_bytes": rsize,
                            "filesystem": "qnx6",
                            "volume_id_as_stored": sb["volumeid"].hex(),
                            "superblock_serial": sb["serial"],
                            "files": f_, "bytes": wr,
                            "symlinks_or_special_skipped": sk,
                            "failed": fa, "short": sh, "excluded": dropped,
                        })
                    print(f"        {f_:,} files, {human(wr)}"
                          + (f", {sk:,} symlinks or special files skipped" if sk else "")
                          + (f", {fa:,} FAILED" if fa else "")
                          + (f", {sh:,} SHORT" if sh else "")
                          + (f", {dropped:,} excluded" if dropped else ""))
                    for line in log[:5]:
                        print(line)
                    if miss:
                        print(f"        INCOMPLETE: this volume reaches {human(miss)} past the end of the file")
                        if manifest is not None:
                            manifest[-1]["extends_past_image_by_bytes"] = miss
                except Exception as exc:
                    print(f"        could not extract this filesystem: {exc}")
            print()

        # A partitioned disk that ends in DDF or IMSM metadata: said once; a
        # mirror's partitions are read, any other's named and not walked.
        if raid_kind and disk_partitioned:
            print("  RAID     " + raid_foreign_note(raid_kind, raid_levels, raid_why, None,
                                                    "its partitions"))
            print()

        # A type byte is a label, not a fact, so read the partitions that did
        # not turn out to be qnx6 rather than trusting what they claim to be.
        others = [(lab, b, sz) for lab, b, sz in sized_regions
                  if lab not in vols and lab not in protective]
        if others:
            print("  WHAT IS IN THE OTHER PARTITIONS")
            for lab, b, sz in others:
                if lab in containers:
                    print(f"    {lab}   {human(sz)}   ->  extended partition "
                          f"container, holds the logical volumes below")
                    print()
                    continue
                kind, lines = identify_fs(fh, b, sz)
                if raid_kind and kind != "raid member" and not any(
                        " RAID set, whose array is not assembled" in ln for ln in lines):
                    what = ("this volume" if lab.startswith(("LVM ", "LUKS ")) or lab == "whole image"
                            else "this partition")
                    note = raid_foreign_note(raid_kind, raid_levels, raid_why,
                                             None if raid_mirror else kind, what)
                    if raid_mirror:
                        lines = list(lines) + [note]
                    else:
                        kind, lines = "raid member", [note]
                print(f"    {lab}   {human(sz)}   ->  {kind or 'not recognised'}")
                opened = getattr(fh, "bitlocker", {}).get(b)
                if opened is not None:
                    print(f"        {opened.summary()}; what follows is the decrypted volume")
                    for line in opened.lines():
                        print(f"          {line}")
                for line in lines:
                    print(f"        {line}")
                if kind == "bitlocker":
                    bl = next((x for x in bitlocker_found if x.base == b), None)
                    if bl is not None:
                        print(f"        {bl.locked_note()}")
                        # what to give is said only when nothing was given to try
                        if not bl.why and not bl.tried and any(
                                k in ("password", "recovery password", "startup key")
                                for k, _i in bl.protectors):
                            print("        (give a password or recovery password with --password-file "
                                  "or --password-env, a startup key with --bitlocker-key)")
                if kind == "luks":
                    lk = next((x for x in getattr(fh, "luks_found", ()) if x.base == b), None)
                    if lk is not None and lk.mk is None and (lk.why or lk.tried):
                        # the reader's own reason: a passphrase given that opens no
                        # keyslot, or what stops it being read whatever is given
                        print(f"        {lk.locked_note()}")
                    elif lk is None and (passwords or getattr(
                            fh, "lvm_map_for", lambda _b: None)(b) is not None):
                        # unlock_luks() reads the image's own regions, before
                        # lvm_image() places a mapped volume, so a container in
                        # one is never opened, whatever is given
                        mapped = getattr(fh, "lvm_map_for", lambda _b: None)(b) is not None
                        print("        LUKS-encrypted and not read: "
                              + ("it is inside a logical volume read through a map, where a "
                                 "LUKS container is not opened" if mapped else
                                 "the passphrase given was not tried on it")
                              + (", so the passphrase given was not tried on it"
                                 if mapped and passwords else ""))
                    elif lk is None or lk.mk is None:
                        print("        (give its passphrase with --password-file or --password-env)")
                if kind == "apfs" and any(lk.base == b and lk.vek is None and not lk.why
                                          and not lk.tried for lk in apfs_found):
                    print("        (give an encrypted volume's password or personal recovery "
                          "key with --password-file or --password-env)")
                ext_name = ""
                if kind and kind.startswith("ext"):
                    _sb = read_at(fh, b + EXT_SB_OFF, 1024)
                    _l = _sb[EXT_F["volume_name"]:EXT_F["volume_name"] + 16]
                    _l = _l.split(b"\x00")[0].decode("utf-8", "replace")
                    _m = _sb[EXT_F["last_mounted"]:EXT_F["last_mounted"] + 64]
                    _m = _m.split(b"\x00")[0].decode("utf-8", "replace")
                    ext_name = _l or _m.strip("/").replace("/", "_")
                wanted = (only is None or only.lower() in lab.lower()
                          or (ext_name and only.lower() in ext_name.lower()))

                if do_triage and kind and kind.startswith("ext"):
                    esb = read_at(fh, b + EXT_SB_OFF, 1024)
                    ebs = 1024 << _e(esb, "log_block_size")
                    etot = _e(esb, "blocks_count") * ebs
                    eused = etot - _e(esb, "free_blocks") * ebs
                    kb = _e(esb, "kbytes_written", 8)
                    lbl = esb[EXT_F["volume_name"]:EXT_F["volume_name"] + 16]
                    lbl = lbl.split(b"\x00")[0].decode("utf-8", "replace")
                    mnt = esb[EXT_F["last_mounted"]:EXT_F["last_mounted"] + 64]
                    mnt = mnt.split(b"\x00")[0].decode("utf-8", "replace")
                    encf = (0, 0)
                    try:
                        encf = sample_encryption(ExtWalker(fh, b))
                    except Exception:
                        pass
                    triage.append(triage_row(
                        lbl or mnt or lab, kind, etot, eused, kb,
                        f"{kb/1048576:,.0f} GiB written over its life, "
                        f"{_e(esb, 'mnt_count', 2):,} mounts"
                        + (f", mounts at {mnt}" if mnt else ""),
                        stamp(_e(esb, "mtime")).replace(" UTC", ""), encf))

                if do_list and kind and kind.startswith("ext") and wanted:
                    print(f"        CONTENTS  (depth {list_depth})")
                    try:
                        w = ExtWalker(fh, b)
                        print_tree(w, w.root, 1, list_depth, [list_max], pad=8)
                    except Exception as exc:
                        print(f"        could not walk this filesystem: {exc}")
                if zf is not None and kind and kind.startswith("ext") and wanted:
                    stem = name_prefix + (vol_names.get(b) or f"lba{b // ss}")
                    suffix = sanitize_volume_label(ext_name) if ext_name else ""
                    vol = (f"{stem}_{suffix}"
                           if suffix and not stem.endswith(f"_{suffix}") else stem)
                    print(f"        EXTRACTING to {extract}  as {vol}/")
                    try:
                        w = ExtWalker(fh, b)
                        ents = collect(w, w.root)
                        ents, dropped = apply_exclude(ents, exclude)
                        log = []
                        miss = missing_past_end(b)
                        f_, wr, sk, fa, sh = extract_to_zip(zf, w, vol, ents, log, reporter)
                        if manifest is not None:
                            _u = read_at(fh, b + EXT_SB_OFF, 1024)
                            manifest.append({
                                "volume": vol, **image_rec,
                                "lba": b // ss, "offset_bytes": b,
                                "partition_size_bytes": sz,
                                "filesystem": kind,
                                "uuid": _u[EXT_F["uuid"]:EXT_F["uuid"] + 16].hex(),
                                "label": ext_name,
                                "files": f_, "bytes": wr,
                                "symlinks_or_special_skipped": sk,
                                "failed": fa, "short": sh, "excluded": dropped,
                            })
                        print(f"            {f_:,} files, {human(wr)}"
                              + (f", {sk:,} symlinks or special files skipped" if sk else "")
                              + (f", {fa:,} FAILED" if fa else "")
                              + (f", {sh:,} SHORT" if sh else "")
                              + (f", {dropped:,} excluded" if dropped else ""))
                        for line in log[:5]:
                            print(line)
                        if miss:
                            print(f"            INCOMPLETE: this volume reaches {human(miss)} past the end of the file")
                            if manifest is not None:
                                manifest[-1]["extends_past_image_by_bytes"] = miss
                    except Exception as exc:
                        print(f"        could not extract: {exc}")

                if kind in ("fat32", "fat16", "fat12", "exfat", "ntfs", "refs", "f2fs", "hfs+", "hfsx", "apfs",
                            "etfs", "efs", "qnx4", "squashfs", "jffs2", "ubi",
                            "ubifs", "yaffs1", "yaffs2", "xfs", "btrfs") + CFG_KINDS and wanted:
                    if do_list:
                        print(f"        CONTENTS  (depth {list_depth})")
                        try:
                            w = walker_for(kind, fh, b, sz)
                            print_tree(w, w.root, 1, list_depth, [list_max], pad=8)
                            n_dmg, dmg = damage_lines(w)
                            if n_dmg:
                                print(f"        DAMAGE  {n_dmg:,} item(s) recorded while listing"
                                      + (", first:" if dmg else ""))
                                for line in dmg:
                                    print(f"          {line}")
                        except Exception as exc:
                            print(f"        could not walk this filesystem: {exc}")
                    if zf is not None:
                        vol = name_prefix + (vol_names.get(b) or f"lba{b // ss}")
                        print(f"        EXTRACTING to {extract}  as {vol}/")
                        try:
                            w = walker_for(kind, fh, b, sz)
                            ents = collect(w, w.root)
                            ents, dropped = apply_exclude(ents, exclude)
                            log = []
                            miss = missing_past_end(b)
                            f_, wr, sk, fa, sh = extract_to_zip(zf, w, vol, ents, log, reporter)
                            if manifest is not None:
                                manifest.append({
                                    "volume": vol, **image_rec,
                                    "lba": b // ss, "offset_bytes": b,
                                    "partition_size_bytes": sz, "filesystem": kind,
                                    "files": f_, "bytes": wr,
                                    "symlinks_or_special_skipped": sk,
                                    "failed": fa, "short": sh, "excluded": dropped,
                                })
                            n_dmg, dmg = damage_lines(w, 50)
                            if n_dmg and manifest is not None:
                                manifest[-1]["damage_recorded"] = n_dmg
                                manifest[-1]["damage_first"] = dmg
                            print(f"            {f_:,} files, {human(wr)}"
                                  + (f", {sk:,} symlinks or special files skipped" if sk else "")
                                  + (f", {fa:,} FAILED" if fa else "")
                                  + (f", {sh:,} SHORT" if sh else "")
                                  + (f", {dropped:,} excluded" if dropped else "")
                                  + (f", {n_dmg:,} DAMAGED structure(s) recorded" if n_dmg else ""))
                            for line in log[:5]:
                                print(line)
                            for line in dmg[:5]:
                                print(f"            DAMAGE {line}")
                            if miss:
                                print(f"            INCOMPLETE: this volume reaches {human(miss)} past the end of the file")
                                if manifest is not None:
                                    manifest[-1]["extends_past_image_by_bytes"] = miss
                        except Exception as exc:
                            print(f"        could not extract: {exc}")

                if (kind == "QNX IFS boot image" and wanted
                        and (do_list or zf is not None)):
                    w = None
                    try:
                        w = IfsWalker(fh, b)
                    except IfsUnsupported as exc:
                        print(f"        contents not read: {exc}")
                    except Exception as exc:
                        print(f"        could not read this image filesystem: {exc}")
                    if w is not None:
                        ck = ("image checksum balances" if w.cksum_ok
                              else "IMAGE CHECKSUM DOES NOT BALANCE" if w.cksum_ok is False
                              else "image checksum not checked")
                        print(f"        decoded {human(w.decompressed)} imagefs "
                              f"({w.compress}), {ck}")
                        if do_list:
                            print(f"        CONTENTS  (depth {list_depth})")
                            try:
                                print_tree(w, w.root, 1, list_depth, [list_max], pad=8)
                            except Exception as exc:
                                print(f"        could not walk this filesystem: {exc}")
                        if zf is not None:
                            vol = name_prefix + (vol_names.get(b) or f"lba{b // ss}")
                            print(f"        EXTRACTING to {extract}  as {vol}/")
                            try:
                                ents = collect(w, w.root)
                                ents, dropped = apply_exclude(ents, exclude)
                                log = []
                                miss = missing_past_end(b)
                                f_, wr, sk, fa, sh = extract_to_zip(zf, w, vol, ents, log, reporter)
                                if manifest is not None:
                                    manifest.append({
                                        "volume": vol, **image_rec,
                                        "lba": b // ss, "offset_bytes": b,
                                        "partition_size_bytes": sz,
                                        "filesystem": "qnx_ifs",
                                        "compression": w.compress,
                                        "imagefs_size_bytes": w.decompressed,
                                        "image_checksum_balances": w.cksum_ok,
                                        "files": f_, "bytes": wr,
                                        "symlinks_or_special_skipped": sk,
                                        "failed": fa, "short": sh, "excluded": dropped,
                                    })
                                print(f"            {f_:,} files, {human(wr)}"
                                      + (f", {sk:,} symlinks or special files skipped"
                                         if sk else "")
                                      + (f", {fa:,} FAILED" if fa else "")
                                      + (f", {sh:,} SHORT" if sh else "")
                                      + (f", {dropped:,} excluded" if dropped else ""))
                                for line in log[:5]:
                                    print(line)
                                if miss:
                                    print(f"            INCOMPLETE: this volume reaches {human(miss)} past the end of the file")
                                    if manifest is not None:
                                        manifest[-1]["extends_past_image_by_bytes"] = miss
                            except Exception as exc:
                                print(f"        could not extract: {exc}")
                print()

        if rejected:
            print(f"  rejected (magic present, fields inconsistent):")
            for off, how, endian, sb, bad in rejected[:6]:
                print(f"    0x{off:<10x} {how:<28} {bad[0]}")
            if len(rejected) > 6:
                print(f"    ... and {len(rejected)-6} more")
            print()

        if do_triage:
            print_triage(triage)

        if unallocated:
            print(f"  UNALLOCATED SPACE to {unallocated}")
            recs = write_unallocated(fh, size, volumes(fh, size), unallocated,
                                     image_rec["image"], only)
            if not recs:
                print("    no volume to read free space from")
            if unallocated_log is not None:
                unallocated_log.extend(recs)
            print()

        if confirmed:
            print("  VERDICT: QNX6 filesystem present.")
        elif candidates:
            print("  VERDICT: magic bytes seen but no valid superblock. Not QNX6"
                  " on this evidence.")
        else:
            print("  VERDICT: no QNX6 superblock found.")
    # A logical volume read through a map has no one offset on the disk: its
    # record in volumes.json says where each run of it is instead.
    for rec in (manifest or [])[first_record:]:
        lmap = getattr(image, "lvm_map_for", lambda _b: None)(rec.get("offset_bytes"))
        if lmap is not None:
            rec["offset_bytes"], rec["lba"] = None, None
            rec["lvm_map"] = lmap.describe()
    print()


def _apfs_fixture_check(image_gz, listing):
    """Walk the committed APFS fixture and compare every file against the hashes
    an independent reader recorded from the same image.

    Returns (matched, expected, missing, different). The paths in the listing are
    relative to the volume, and the walk presents the container's volumes as
    directories, so the volume name is dropped before comparing.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    w = ApfsWalker(img, 0)
    have = {}
    for path, node, size, _mtime in collect(w, w.root):
        if size is None:
            continue                      # a symbolic link, which has no stream
        have[path.split("/", 1)[1] if "/" in path else path] = (node, size)
    matched = missing = different = 0
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            missing += 1
            continue
        h = hashlib.sha256()
        read = 0
        try:
            for chunk in w.read_file(got[0], got[1]):
                h.update(chunk)
                read += len(chunk)
        except ApfsUnreadable:
            different += 1
            continue
        if read == got[1] and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return matched, len(want), missing, different


def _hfs_fixture_check(image_gz, listing):
    """Walk the committed HFS+ fixture and compare every file against the hashes
    an independent reader recorded from the same image.

    Returns (matched, expected, missing, different). The image is decompressed in
    memory, so no temporary file is written and nothing outside this process is
    touched.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    w = HfsPlusWalker(img, 0)
    have = {}
    for path, cnid, size, _mtime in collect(w, w.root):
        if "HFS+ Private" in path:
            continue
        have[path] = (cnid, size)
    matched = missing = different = 0
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            missing += 1
            continue
        h = hashlib.sha256()
        read = 0
        try:
            for chunk in w.read_file(got[0], got[1]):
                h.update(chunk)
                read += len(chunk)
        except HfsUnreadable:
            different += 1
            continue
        if (got[1] is None or read == got[1]) and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return matched, len(want), missing, different


def _fat_deleted_check(image_gz, listing, walker_cls):
    """Recover the deleted files a FAT32 or exFAT fixture builder created and
    then removed, and compare each against the sha256 recorded from its bytes
    before deletion. The listing names a file by its last path component; a
    FAT32 short-name-only entry loses its first character to the 0xE5 mark, so
    a listed name is also matched with that character replaced by "_".
    Returns (matched, expected, missing, different).
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, rest = line.split("  ", 1)
            want[rest.rsplit("/", 1)[-1]] = digest
    w = walker_cls(img, 0)
    have = {}
    for e in w.deleted_files():
        if e.recoverable and not e.is_dir:
            have[e.name] = e
    matched = missing = different = 0
    for name, digest in want.items():
        e = have.get(name) or have.get("_" + name[1:])
        if e is None:
            missing += 1
            continue
        h = hashlib.sha256()
        for chunk in w.read_deleted(e):
            h.update(chunk)
        if h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return matched, len(want), missing, different


def _ntfs_deleted_check(image_gz, listing):
    """Recover the deleted files the fixture builder created and then removed,
    and compare each against the sha256 recorded from its bytes before deletion.

    The expected hashes come from what was written, not from this reader, and
    the same files were confirmed recoverable by The Sleuth Kit's icat at build
    time. Returns (matched, expected, missing, different).
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, name = line.split("  ", 1)
            want[name] = digest
    w = NtfsWalker(img, 0)
    have = {e.name: e for e in w.deleted_files() if e.recoverable and not e.is_dir}
    matched = missing = different = 0
    for name, digest in want.items():
        e = have.get(name)
        if e is None:
            missing += 1
            continue
        h = hashlib.sha256()
        for chunk in w.read_deleted(e):
            h.update(chunk)
        if h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return matched, len(want), missing, different


def _times_fixture_checks(fixtures):
    """[(label, passed)] for times() of the ext, APFS and HFS+ walkers against
    known data no qnxprobe code produced: ext-times.json (debugfs's stored
    fields, decoded by the kernel's rule; tools/make_ext_times_fixture.sh) and
    mac-times.json (macOS's own getattrlist reading of images it wrote;
    tools/make_times_fixtures.sh). Every name each file lists is compared,
    None included, so a time read from the wrong field, a value invented where
    the volume holds none, or a hard link answered from its own record fails."""
    import gzip, io, json
    out = []

    def node_of(w, path):
        node = w.root
        for part in path.strip("/").split("/"):
            node = dict(w.listdir(node)).get(part)
            if node is None:
                return None
        return node

    for listing, stems in (("ext-times.json", ("ext4-times", "ext2-times128")),
                           ("mac-times.json", ("apfs-times", "hfsplus-times"))):
        with open(os.path.join(fixtures, listing), encoding="utf-8") as fh:
            known = json.load(fh)
        for stem in stems:
            with gzip.open(os.path.join(fixtures, stem + ".img.gz"), "rb") as gz:
                img = io.BytesIO(gz.read())
            size = img.getbuffer().nbytes
            kind = (identify_fs(img, 0, size) or (None,))[0]
            w = walker_for(kind, img, 0, size) if kind else None
            wrong, rows = [], known[stem]
            for path, row in sorted(rows.items()):
                if kind == "apfs":
                    path = "QNXTIMES/" + path
                node = node_of(w, path) if w is not None else None
                want = row["expected"]
                if want is not None:
                    want = {k: tuple(v) if v is not None else None for k, v in want.items()}
                got = None
                if node is not None:
                    try:
                        got = w.times(node)
                    except Exception as exc:         # pylint: disable=broad-except
                        wrong.append(f"{path}: times() raised {type(exc).__name__}: {exc}")
                        continue
                    if got is not None and want is not None:
                        got = {k: got.get(k) for k in want}
                if node is None or got != want:
                    wrong.append(f"{path}: {got} where {want}")
            out.append((f"{stem}: times() of {len(rows)} files and folders match the known "
                        f"data in {listing}" + (f"; {'; '.join(wrong)}" if wrong else ""),
                        not wrong))
            if kind == "hfs+" and w is not None:
                try:
                    out.append(_hfs_expanded_times_check(img, w, node_of(w, "plain.txt")))
                except Exception as exc:             # pylint: disable=broad-except
                    out.append(("an HFS+ record flagged for expanded times reads its dates as "
                                f"Unix seconds ({type(exc).__name__}: {exc})", False))
    return out


def _hfs_expanded_times_check(img, w, cnid):
    """A record flagged kHFSCatExpandedTimesMask holds Unix seconds (Apple's
    to_bsd_time returns them unconverted). macOS writes no such record here, so
    the bit is set in a copy of one the fixture holds: the same five stored
    words must then read 2082844800 seconds later, and a stored 0 as 1970."""
    import io
    rec = w._record(cnid)
    buf = bytearray(img.getvalue())
    at = buf.find(rec)
    ok = at >= 0 and buf.find(rec, at + 1) < 0
    label = "an HFS+ record flagged for expanded times reads its dates as Unix seconds"
    if not ok:
        return (label + " (the record was not found once in the image)", False)
    struct.pack_into(">H", buf, at + 2, struct.unpack_from(">H", rec, 2)[0]
                     | HFSP_CAT_EXPANDED_TIMES)
    struct.pack_into(">I", buf, at + 28, 0)                 # backupDate 0
    plain = w.times(cnid)
    got = HfsPlusWalker(io.BytesIO(bytes(buf)), 0).times(cnid)
    want = {k: (v[0] + HFSP_EPOCH_DELTA, 0) for k, v in plain.items() if k != "backup"}
    want["backup"] = (0, 0)
    return (label + ("" if got == want else f"; {got} where {want}"), got == want)


def _ext_fixture_check(image_gz, listing):
    """Walk a committed ext fixture and compare every file against the hashes
    sha256sum recorded over the tree the image was built from.

    Returns (kind, matched, expected, missing, different). The fixtures hold
    sparse files of every shape (a hole first, a hole in the middle, a trailing
    hole past the last block, a file that is nothing but hole, and a 3 MiB one
    whose data sits at both ends), so a reader that drops holes or loses the
    logical position of an extent fails here; the ext2 image reaches the same
    files through the classic block map instead of an extent tree.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    size = img.getbuffer().nbytes
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    kind = (identify_fs(img, 0, size) or (None,))[0]
    w = walker_for(kind, img, 0, size) if kind else None
    if w is None:
        return kind, 0, len(want), len(want), 0
    have = {path: (ino, sz) for path, ino, sz, _mtime in collect(w, w.root) if sz is not None}
    matched = missing = different = 0
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            missing += 1
            continue
        h = hashlib.sha256()
        read = 0
        try:
            for chunk in w.read_file(got[0], got[1]):
                h.update(chunk)
                read += len(chunk)
        except ExtUnreadable:
            different += 1
            continue
        if read == got[1] and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return kind, matched, len(want), missing, different


def _f2fs_fixture_check(image_gz, listing):
    """Walk the committed F2FS fixture and compare every file in `listing`
    against its recorded hash. Returns (kind, matched, expected, missing,
    different).

    Two listings are checked with this. The main one is sha256sum over the
    source tree, an oracle independent of the image and of this reader; it
    covers files that live inside the inode's own address list (inline data,
    inline directories, and files up to a few MiB), plus the multi-block
    directory and the symlink. The second is the one file large enough to run
    past the inode into direct and single-indirect node blocks: sload.f2fs
    relocates such a file's node blocks (it writes them as if the inode had no
    inline xattr while stamping the inode with one), so the source hash does
    not match, and the recorded hash is what f2fs-tools' own dump.f2fs, an
    independent reader, extracts from the committed image.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    size = img.getbuffer().nbytes
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    kind = (identify_fs(img, 0, size) or (None,))[0]
    w = walker_for(kind, img, 0, size) if kind else None
    if w is None:
        return kind, 0, len(want), len(want), 0
    have = {path: (ino, sz) for path, ino, sz, _mtime in collect(w, w.root) if sz is not None}
    matched = missing = different = 0
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            missing += 1
            continue
        h = hashlib.sha256()
        read = 0
        try:
            for chunk in w.read_file(got[0], got[1]):
                h.update(chunk)
                read += len(chunk)
        except F2fsUnreadable:
            different += 1
            continue
        if read == got[1] and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return kind, matched, len(want), missing, different


def _f2fs_free_check(image_gz):
    """Read a committed F2FS fixture's free space and hold it against the volume
    itself. Returns (kind, free_blocks, main_blocks, valid_blocks, named_blocks,
    named_in_free).

    Two statements, neither derived from free_extents: the checkpoint's own
    valid_block_count must equal the main area minus what is reported free (the
    filesystem's accounting), and no block a live file or node occupies may lie
    in a reported run (position, which is what tells a wrong bit order from a
    right one when the counts agree). named_blocks is every data block of every
    reachable file and directory plus every node block that addresses them; on
    both committed fixtures it equals valid_block_count, so the named blocks and
    the free runs together tile the whole main area.
    """
    import gzip, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    size = img.getbuffer().nbytes
    kind = (identify_fs(img, 0, size) or (None,))[0]
    if kind != "f2fs":
        return kind, 0, 0, 0, 0, 0
    w = F2fsWalker(img, 0)
    runs = w.free_extents()
    free_blocks = sum(n for _, n in runs) // w.bs
    main_blocks = w.main_segs * w.seg_blocks
    valid = struct.unpack_from("<Q", w.ckpt, 16)[0]
    named = set()

    def node(nid):
        b = w.resolve(nid)
        if b not in (F2FS_NULL_ADDR, F2FS_NEW_ADDR):
            named.add(b)

    seen = set()

    def walk(nid):
        if nid in seen:
            return
        seen.add(nid)
        node(nid)
        ino = w.inode(nid)
        if ino is None:
            return
        for k in range(5):
            n = w._nid_slot(ino, k)                 # pylint: disable=protected-access
            if n:
                node(n)
                if k >= 2:                          # an indirect node names direct nodes
                    nb = w._node(n)                 # pylint: disable=protected-access
                    for j in range(w.addrs_per_block if nb else 0):
                        child = struct.unpack_from("<I", nb, j * 4)[0]
                        if child:
                            node(child)
        isdir = bool(ino["mode"] & S_IFDIR)
        inline = F2FS_INLINE_DENTRY if isdir else F2FS_INLINE_DATA
        if not (ino["inline"] & inline):
            for L in range((ino["size"] + w.bs - 1) // w.bs):
                a = w._block_of(ino, L)             # pylint: disable=protected-access
                if a not in (F2FS_NULL_ADDR, F2FS_NEW_ADDR, F2FS_COMPRESS_ADDR):
                    named.add(a)
        if isdir:
            for _name, child in w.listdir(nid):
                walk(child)

    walk(w.root)
    starts = [a for a, _n in runs]
    import bisect

    def in_free(blk):
        off = w.base + blk * w.bs
        i = bisect.bisect_right(starts, off) - 1
        return i >= 0 and runs[i][0] <= off < runs[i][0] + runs[i][1]

    named_in_free = sum(1 for b in named if in_free(b))
    return kind, free_blocks, main_blocks, valid, len(named), named_in_free


def _f2fs_marker_check(image_gz):
    """The two properties only the kernel-written two-session fixture has.
    Returns (nat bitmap has a set bit, marker blocks found, marker blocks in
    free runs). The marker is a file of 256 blocks deleted before the last
    checkpoint, each block beginning ``F2FS-FREE-MARKER-<index>-``; its bytes
    are searched for directly, so the count is a fact about the image, and
    every block found must lie inside a run free_extents reports."""
    import gzip, io, re, bisect
    with gzip.open(image_gz, "rb") as gz:
        raw = gz.read()
    w = F2fsWalker(io.BytesIO(raw), 0)
    nat_len = struct.unpack_from("<I", w.ckpt, 160)[0]
    has_bit = any(bytes(w.nat_bitmap[:nat_len]))
    runs = w.free_extents()
    starts = [a for a, _n in runs]
    blocks = {m.start() // w.bs for m in re.finditer(rb"F2FS-FREE-MARKER-\d{4}-", raw)}
    in_free = 0
    for blk in blocks:
        off = w.base + blk * w.bs
        i = bisect.bisect_right(starts, off) - 1
        if i >= 0 and runs[i][0] <= off < runs[i][0] + runs[i][1]:
            in_free += 1
    return has_bit, len(blocks), in_free


def _ntfs_fixture_check(image_gz, listing):
    """Walk the committed NTFS fixture and compare every file against the
    hashes an independent reader recorded from the same image.

    Returns (matched, expected, missing, different). The image is decompressed
    in memory: the walker takes anything with seek and read, so no temporary
    file is written and nothing outside this process is touched.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    w = NtfsWalker(img, 0)
    matched = missing = different = 0
    have = {}
    for path, ino, size, _mtime in collect(w, w.root):
        have[path] = (ino, size)
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            missing += 1
            continue
        h = hashlib.sha256()
        read = 0
        try:
            for chunk in w.read_file(got[0], got[1]):
                h.update(chunk)
                read += len(chunk)
        except NtfsUnreadable:
            different += 1
            continue
        if read == got[1] and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
    return matched, len(want), missing, different


def _ntfs_streams_check(image_gz, listing, break_it=None):
    """Read every alternate data stream of the committed stream fixture through
    listing(streams=True) and compare each against the hash The Sleuth Kit's
    icat gave for the same stream from its first stored cluster on.

    The listing has to name exactly the streams the manifest does: one more is
    a stream that should not have been listed ($BadClus:$Bad, whose recorded
    size is the whole volume, is the one that matters), one fewer a stream
    lost. Around that it holds the rules a caller relies on: the default
    listing names no stream and is otherwise the same, a stream's entry()
    gives the size read_file() returns, its stamps() are its file's, and the
    hole at the front of the $J-shaped stream is the 1 MiB the fixture's
    writer left there. ``break_it`` takes the walker and returns one with a
    rule broken, for the control that proves the comparison can fail.

    Returns (matched, expected, missing, extra, different, failures).
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    want = {}
    with open(listing, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            digest, path = line.split("  ", 1)
            want[path] = digest
    w = NtfsWalker(img, 0)
    if break_it is not None:
        w = break_it(w)
    rows = list(w.listing(streams=True))
    have = {path: (node, size) for path, node, _m, size, _t, _r in rows
            if isinstance(node, NtfsStreamRef)}
    failures = []
    named = sum(1 for r in rows if isinstance(r[1], NtfsStreamRef))
    if named != len(have):
        # journal.bin:$J lies in two records, and is one stream
        failures.append(f"{named - len(have)} stream(s) listed more than once")
    files_only = [r for r in rows if not isinstance(r[1], NtfsStreamRef)]
    if list(w.listing()) != files_only:
        failures.append("the default listing is not the stream listing without its streams")
    matched = different = 0
    for path, digest in want.items():
        got = have.get(path)
        if got is None:
            continue
        node, size = got
        h, read = hashlib.sha256(), 0
        try:
            for chunk in w.read_file(node, size):
                h.update(chunk)
                read += len(chunk)
        except NtfsUnreadable:
            different += 1
            continue
        if read == size and h.hexdigest() == digest:
            matched += 1
        else:
            different += 1
        ent = w.entry(node)
        if not ent or ent[1] != size:
            failures.append(f"{path}: entry() gives {ent and ent[1]}, the listing {size}")
        if w.stamps(node) != w.stamps(node.record):
            failures.append(f"{path}: stamps() is not its file's")
    j = have.get("journal.bin:$J")
    if j is None or w.front_hole(j[0]) != 1 << 20:
        failures.append(f"journal.bin:$J: front_hole() is "
                        f"{j and w.front_hole(j[0])}, not the 1,048,576 bytes written")
    if j is not None:
        # what --list prints beside the file: each stream once, at its recorded size
        shown = w.named_streams(j[0].record)
        want_shown = [("$Max", 32), ("$J", (1 << 20) + j[1])]
        if sorted(shown) != sorted(want_shown):
            failures.append(f"journal.bin: named_streams() gives {shown}, not {want_shown}")
    missing = sum(1 for p in want if p not in have)
    extra = sum(1 for p in have if p not in want)
    return matched, len(want), missing, extra, different, failures


def _ntfs_directory_index_check(image_gz, break_it=None):
    """Read every directory's $I30 index allocation through directory_index()
    and check it is the index: whole blocks that start "INDX" and, once fixed
    up, hold with the directory's $INDEX_ROOT exactly the entries listdir()
    gives. ``break_it`` takes the walker and returns one with the call broken,
    for the control that proves the check can fail.

    Returns (directories with an index allocation, directories, failures).
    """
    import gzip, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    w = NtfsWalker(img, 0)
    if break_it is not None:
        w = break_it(w)
    failures, dirs, held = [], 0, 0
    stack, seen = [(w.root, "")], set()
    while stack:
        node, path = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        dirs += 1
        listed = w.listdir(node)
        for name, child in listed:
            ent = w.entry(child)
            if ent and ent[0] & S_IFMT == S_IFDIR:
                stack.append((child, f"{path}/{name}"))
            elif w.directory_index(child):
                failures.append(f"{path}/{name}: a file gave a directory index")
        if any(name == "$I30" for name, _ref, _size in w.streams(node)):
            failures.append(f"{path or '/'}: streams() lists the index")
        got = w.directory_index(node)
        if not got:
            continue
        held += 1
        (name, ref, size), = got
        data = b"".join(w.read_file(ref, size))
        if name != "$I30" or len(data) != size or not size or size % w.idx_size:
            failures.append(f"{path or '/'}: {len(data)} bytes read of {size}, in blocks "
                            f"of {w.idx_size}")
            continue
        out, got_names = [], set()
        for a in w._record(node):                    # pylint: disable=protected-access
            if a.type == NTFS_INDEX_ROOT and a.name == "$I30" and len(a.value) >= 0x20:
                w._index_entries(a.value, 0x10, out, got_names)   # pylint: disable=protected-access
        for off in range(0, size, w.idx_size):
            raw = data[off:off + w.idx_size]
            if raw[:4] != NTFS_INDX:
                failures.append(f"{path or '/'}: the block at {off} does not start INDX")
                continue
            block = _ntfs_fixup(raw, w.bps, NTFS_INDX)
            if block and len(block) >= 0x28:
                w._index_entries(block, 0x18, out, got_names)     # pylint: disable=protected-access
        if sorted(out) != sorted(listed):
            failures.append(f"{path or '/'}: the blocks hold {len(out)} entries, listdir() "
                            f"gives {len(listed)}")
        ent = w.entry(ref)
        if not ent or ent[1] != size:
            failures.append(f"{path or '/'}: entry() gives {ent and ent[1]}, not {size}")
        if w.stamps(ref) != w.stamps(node):
            failures.append(f"{path or '/'}: stamps() is not its directory's")
    return held, dirs, failures


def _ntfs_times_check(image_gz):
    """Compare the instants the walker reads for live and deleted NTFS files
    against what The Sleuth Kit's istat printed for the same records.

    The pins are istat's $STANDARD_INFORMATION block, not the $FILE_NAME block it
    prints beneath: on this fixture the two differ, most on the accessed time,
    so a reader that took the wrong attribute fails on the field that matters.
    Recorded 2026-09-12 with ``TZ=UTC istat -o 0 ntfs-fixture.img <record>`` on
    sleuthkit 4.x; the fixture is committed and never rewritten, so these values
    are fixed. Each is compared within a microsecond, which is below the
    precision a Unix-seconds float keeps at this epoch and above istat's 100 ns.

    Returns (failures, live files checked).
    """
    import gzip, io
    from datetime import datetime, timezone
    live = {
        "dir/mid.txt": ("2026-09-11 04:22:40.133550800", "2026-09-11 04:22:40.133580100",
                        "2026-09-11 04:22:55.233196100"),
        "many/file_0001.txt": ("2026-09-11 04:22:40.136710000", "2026-09-11 04:22:40.136739400",
                               "2026-09-11 04:22:55.279657800"),
    }
    deleted = {
        "h_9.bin": ("2026-09-11 04:22:40.754156700", "2026-09-11 04:22:40.754286000",
                    "2026-09-11 04:22:40.754156700"),
        "h_11.bin": ("2026-09-11 04:22:40.766373400", "2026-09-11 04:22:40.766531400",
                     "2026-09-11 04:22:40.766373400"),
    }

    def epoch(text):
        base, frac = text.split(".")
        dt = datetime.strptime(base, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        return dt.timestamp() + int(frac) / 10 ** len(frac)

    def matches(got, want):
        return all(abs(g - epoch(w)) < 1e-6 for g, w in zip(got, want))

    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    w = NtfsWalker(img, 0)
    failures, checked, seen = [], 0, set()
    for path, ino, size, mtime in collect(w, w.root):
        if size is None:
            continue
        got = w.stamps(ino)
        checked += 1
        if got[1] != mtime:
            failures.append(f"{path}: stamps() modified {got[1]} is not entry()'s {mtime}")
        if path in live:
            seen.add(path)
            if not matches(got, live[path]):
                failures.append(f"{path}: stamps() {got} is not istat's {live[path]}")
    for e in w.deleted_files():
        if e.name in deleted:
            seen.add(e.name)
            got = (e.created, e.modified, e.accessed)
            if not matches(got, deleted[e.name]):
                failures.append(f"deleted {e.name}: {got} is not istat's {deleted[e.name]}")
    for name in (set(live) | set(deleted)) - seen:
        failures.append(f"{name}: not found in the fixture, so nothing was compared")
    return failures, checked


def _exfat_orphan_image():
    """An exFAT volume of forty 512-byte clusters with a live tree and, beside
    it, directory clusters that are allocated and that nothing links. Returns
    (image bytes, {name: content written}). The layout, by cluster number:

      2 bitmap, 3 root, 4 up-case table, 5 LIVE.TXT, 6 LIVEDIR, 7 its INNER.TXT
      10 -> 11   an orphan directory of two clusters, linked in the FAT
      12, 13     ORPHAN.BIN, one run
      14         the orphan directory SUB, holding DEEP.TXT (15) and NEST (16)
      16         the orphan directory NEST, holding LEAF.TXT (17)
      18 -> 20   CHAIN.BIN, a FAT chain around the free cluster 19
      21         SHORT.BIN, a chain of one cluster for a size that needs two
      22         a second copy of the ORPHAN.BIN entry set, and nothing else
      23         FREE.BIN's cluster, not allocated
      25         DEL.TXT, deleted from the root, its cluster free
      30         a free cluster holding a valid entry set, which must be ignored

    The set checksum is written here from the specification's formula and not
    with the reader's function, so a wrong reader does not pass against itself.
    """
    sec, clusters, heap_sector, fat_sector = 512, 40, 8, 4
    buf = bytearray((heap_sector + clusters) * sec)
    buf[3:11] = b"EXFAT   "
    struct.pack_into("<I", buf, 80, fat_sector)
    struct.pack_into("<I", buf, 84, 1)               # one sector of FAT
    struct.pack_into("<I", buf, 88, heap_sector)
    struct.pack_into("<I", buf, 92, clusters)
    struct.pack_into("<I", buf, 96, 3)               # root directory cluster
    buf[108], buf[109], buf[110] = 9, 0, 1
    buf[510:512] = b"\x55\xaa"

    def at(clus):
        return heap_sector * sec + (clus - 2) * sec

    def entry_set(name, first, size, *, is_dir=False, contiguous=True, in_use=True,
                  good_sum=True):
        ent = bytearray(96)
        ent[0], ent[1] = 0x85, 2
        ent[4] = 0x10 if is_dir else 0x20
        struct.pack_into("<I", ent, 12, (22209 << 16) | 24576)   # modified
        ent[23] = 0x80 | 16                          # its UTC offset field
        ent[32], ent[33], ent[35] = 0xC0, 0x03 if contiguous else 0x01, len(name)
        struct.pack_into("<Q", ent, 40, size)
        struct.pack_into("<I", ent, 52, first)
        struct.pack_into("<Q", ent, 56, size)
        ent[64] = 0xC1
        ent[66:66 + 2 * len(name)] = name.encode("utf-16-le")
        total = 0
        for i, byte in enumerate(ent):
            if i not in (2, 3):
                total = ((0x8000 if total & 1 else 0) + (total >> 1) + byte) & 0xFFFF
        struct.pack_into("<H", ent, 2, total if good_sum else total ^ 0x0101)
        if not in_use:
            ent[0], ent[32], ent[64] = 0x05, 0x40, 0x41
        return bytes(ent)

    content = {}

    def data(name, clus_list, size):
        body = bytes((len(name) * 7 + i * 13) % 251 for i in range(size))
        content[name] = body
        for n, clus in enumerate(clus_list):
            piece = body[n * sec:(n + 1) * sec]
            buf[at(clus):at(clus) + len(piece)] = piece

    for clus, nxt in ((3, 0xFFFFFFFF), (2, 0xFFFFFFFF), (4, 0xFFFFFFFF),
                      (6, 0xFFFFFFFF), (10, 11), (11, 0xFFFFFFFF), (14, 0xFFFFFFFF),
                      (18, 20), (20, 0xFFFFFFFF), (21, 0xFFFFFFFF)):
        struct.pack_into("<I", buf, fat_sector * sec + clus * 4, nxt)
    for clus in (2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 18, 20, 21, 22):
        buf[at(2) + ((clus - 2) >> 3)] |= 1 << ((clus - 2) & 7)

    root = bytearray(sec)
    root[0] = 0x81                                   # allocation bitmap
    struct.pack_into("<I", root, 20, 2)
    struct.pack_into("<Q", root, 24, (clusters + 7) // 8)
    root[32] = 0x82                                  # up-case table
    struct.pack_into("<I", root, 52, 4)
    struct.pack_into("<Q", root, 56, sec)
    root[64:160] = entry_set("LIVE.TXT", 5, sec)
    root[160:256] = entry_set("LIVEDIR", 6, 0, is_dir=True, contiguous=False)
    root[256:352] = entry_set("DEL.TXT", 25, 300, in_use=False)
    buf[at(3):at(3) + sec] = root
    buf[at(6):at(6) + 96] = entry_set("INNER.TXT", 7, 200)
    data("INNER.TXT", [7], 200)
    data("DEL.TXT", [25], 300)
    # valid, in-use entry sets where the search must not look: in the up-case
    # table, in a live file's content and in a free cluster
    buf[at(4):at(4) + 96] = entry_set("UPCASE.X", 12, 700)
    content["LIVE.TXT"] = entry_set("INLIVE.X", 12, 700) + bytes(sec - 96)
    buf[at(5):at(5) + sec] = content["LIVE.TXT"]
    buf[at(30):at(30) + 96] = entry_set("INFREE.X", 12, 700)

    orphan_set = entry_set("ORPHAN.BIN", 12, 700)
    orphan_dir = (orphan_set
                  + entry_set("SUB", 14, 0, is_dir=True, contiguous=False)
                  + entry_set("TAKEN.BIN", 5, 300)
                  + entry_set("GONE.TXT", 12, 700, in_use=False)
                  + entry_set("BADSUM.BIN", 12, 700, good_sum=False)
                  + entry_set("CHAIN.BIN", 18, 900, contiguous=False)   # crosses 10 | 11
                  + entry_set("SAME.TXT", 5, sec)
                  + entry_set("FREE.BIN", 23, 100)
                  + entry_set("SHORT.BIN", 21, 1000, contiguous=False))
    buf[at(10):at(10) + len(orphan_dir)] = orphan_dir
    buf[at(14):at(14) + 192] = (entry_set("DEEP.TXT", 15, 100)
                                + entry_set("NEST", 16, sec, is_dir=True))
    buf[at(16):at(16) + 96] = entry_set("LEAF.TXT", 17, 10)
    buf[at(22):at(22) + 96] = orphan_set
    data("ORPHAN.BIN", [12, 13], 700)
    data("DEEP.TXT", [15], 100)
    data("LEAF.TXT", [17], 10)
    data("CHAIN.BIN", [18, 20], 900)
    data("SHORT.BIN", [21], 512)
    data("FREE.BIN", [23], 100)
    return bytes(buf), content


def _exfat_orphan_check():
    """recover_deleted() on the image above. Returns the problems found."""
    import io
    raw, content = _exfat_orphan_image()
    problems = []
    w = ExfatWalker(io.BytesIO(raw), 0)
    live = sorted(n for n, _c in w.listdir(w.root))
    if live != ["LIVE.TXT", "LIVEDIR"]:
        problems.append(f"the live root lists {live}")
    got = [(e.parent_path, e.name, e.recoverable) for e in w.recover_deleted()]
    want = [("SUB", "DEEP.TXT", True), ("SUB/NEST", "LEAF.TXT", True),
            (None, "CHAIN.BIN", True), (None, "FREE.BIN", False),
            (None, "ORPHAN.BIN", True), (None, "SAME.TXT", False),
            (None, "SHORT.BIN", False), (None, "TAKEN.BIN", False)]
    if got != want:
        problems.append(f"recover_deleted() gave {got}")
        return problems
    by_name = {e.name: e for e in w.recover_deleted()}
    for name, e in by_name.items():
        if e.kind != "exfat" or e.is_dir or "an orphan entry" not in e.note:
            problems.append(f"{name}: kind {e.kind!r}, note {e.note!r}")
        if e.recoverable:
            if b"".join(w.read_deleted(e)) != content[name]:
                problems.append(f"{name}: read_deleted() is not the bytes written")
            if b"".join(w.read_deleted(e, 7)) != content[name][:7]:
                problems.append(f"{name}: read_deleted(size=7) is not the first 7 bytes")
        else:
            try:
                b"".join(w.read_deleted(e))
                problems.append(f"{name} is refused but read_deleted() read it")
            except NtfsUnreadable:
                pass
    orphan = by_name["ORPHAN.BIN"]
    if (orphan.ident, orphan.size, orphan.parent, orphan.mtime, orphan.mode) != (
            12, 700, 10, None, None):
        problems.append(f"ORPHAN.BIN fields: {orphan.ident}, {orphan.size}, "
                        f"{orphan.parent}, {orphan.mtime}, {orphan.mode}")
    if (orphan.times["modified"], orphan.times["modified utc offset"]) != (
            "2023-06-01 12:00:00", "+04:00"):
        problems.append(f"ORPHAN.BIN times: {orphan.times}")
    if "in 2 such clusters" not in orphan.note or "in 2 such" in by_name["DEEP.TXT"].note:
        problems.append("the copy of the ORPHAN.BIN entry set is not counted once")
    reasons = {n: by_name[n].reason for n in ("TAKEN.BIN", "SAME.TXT", "FREE.BIN",
                                              "SHORT.BIN")}
    if reasons != {
            "TAKEN.BIN": "1 of the 1 clusters it names belong to live files or directories",
            "SAME.TXT": "a live file has the same first cluster and size",
            "FREE.BIN": "1 of the 1 clusters it names are free in the allocation bitmap",
            "SHORT.BIN": "it names 1 of the 2 clusters its size needs"}:
        problems.append(f"reasons: {reasons}")
    # the records deleted_files() gives still read through the same method
    gone = [e for e in w.deleted_files()]
    if ([(e.name, e.recoverable, e.first_cluster) for e in gone] != [("DEL.TXT", True, 25)]
            or b"".join(w.read_deleted(gone[0])) != content["DEL.TXT"]):
        problems.append("the deleted entry in the live root no longer reads")
    # Controls. Link the orphan directory into the root and its files are
    # live, so only the stray copy of one entry set is left, naming a live
    # file. Free the second cluster of ORPHAN.BIN and it is refused.
    heap = 8 * 512
    linked = bytearray(raw)
    was = bytearray(linked[heap + 512 + 160:heap + 512 + 256])       # LIVEDIR's set
    struct.pack_into("<I", was, 52, 10)
    total = 0
    for i, byte in enumerate(was):
        if i not in (2, 3):
            total = ((0x8000 if total & 1 else 0) + (total >> 1) + byte) & 0xFFFF
    struct.pack_into("<H", was, 2, total)
    linked[heap + 512 + 256:heap + 512 + 352] = was
    got = [(e.parent_path, e.name, e.recoverable, e.reason)
           for e in ExfatWalker(io.BytesIO(bytes(linked)), 0).recover_deleted()]
    if got != [(None, "ORPHAN.BIN", False,
                "a live file has the same first cluster and size")]:
        problems.append(f"with the orphan directory linked into the root: {got}")
    freed = bytearray(raw)
    freed[heap + ((13 - 2) >> 3)] &= ~(1 << ((13 - 2) & 7)) & 0xFF
    got = {e.name: (e.recoverable, e.reason)
           for e in ExfatWalker(io.BytesIO(bytes(freed)), 0).recover_deleted()}
    if got.get("ORPHAN.BIN") != (
            False, "1 of the 2 clusters it names are free in the allocation bitmap"):
        problems.append(f"with ORPHAN.BIN's second cluster freed: {got.get('ORPHAN.BIN')}")
    return problems


def _exfat_fixture_orphan_check(image_gz):
    """The exFAT fixture a driver wrote: every in-use file entry in its root
    directory has to carry the checksum this reader computes, and the volume
    has to hold no orphan entry. Returns (ok, detail)."""
    import gzip, io
    with gzip.open(image_gz, "rb") as gz:
        w = ExfatWalker(io.BytesIO(gz.read()), 0)
    raw = w._read(w.root_clus, 0, False)             # pylint: disable=protected-access
    in_use = 0
    for i in range(0, len(raw), 32):
        if raw[i] == 0x00:
            break
        in_use += raw[i] == 0x85
    sets, cut = w._entry_sets(raw, len(raw))         # pylint: disable=protected-access
    orphans = len(list(w.recover_deleted()))
    ok = in_use > 0 and len(sets) == in_use and not cut and not orphans
    return ok, (f"{len(sets)} of {in_use} entry sets match the checksum the driver "
                f"wrote, {orphans} orphan entries")


def _fat16_fixture_checks(here):
    """The FAT16 and FAT12 checks that need the three committed volumes, as
    (passed, sentence) pairs, or None when the fixtures are not beside this file.

    All three were written by macOS, and each listing was hashed from the
    mounted volume, so the expected content comes from the driver that wrote it.
    At build time The Sleuth Kit listed the same live and deleted files and
    icat returned the same bytes for each. The TFAT16 volume has 2,048-byte
    sectors, its files under a root folder named as Windows CE's
    transaction-safe FAT names its redirected root, and the "TFAT16  " type
    string: tools/make_fat16_fixtures.sh says exactly which bytes that script
    set, and it is not a volume Windows CE wrote.
    """
    import gzip, io
    import hashlib
    plain = os.path.join(here, "fat16-fixture.img.gz")
    tfat = os.path.join(here, "tfat16-fixture.img.gz")
    twelve = os.path.join(here, "fat12-fixture.img.gz")
    if not (os.path.isfile(plain) and os.path.isfile(tfat) and os.path.isfile(twelve)):
        return None

    def listing(fix):
        want = {}
        with open(fix[:-len(".img.gz")] + ".sha256", encoding="utf-8") as fh:
            for line in fh:
                if line.strip():
                    want[line.rstrip("\n").split("  ", 1)[1]] = line.split("  ", 1)[0]
        return want

    def reads_right(walker, want):
        """How many of the listed files the walker returns with the listed bytes."""
        good = 0
        try:
            have = {path: (ino, sz) for path, ino, sz, _m in collect(walker, walker.root)}
        except Exception:                            # pylint: disable=broad-except
            return 0
        for path, digest in want.items():
            if path not in have:
                continue
            try:
                data = b"".join(walker.read_file(*have[path]))
            except Exception:                        # pylint: disable=broad-except
                continue
            if hashlib.sha256(data).hexdigest() == digest:
                good += 1
        return good

    out = []
    for label, fix in (("FAT16", plain), ("TFAT16", tfat), ("FAT12", twelve)):
        lst = fix[:-len(".img.gz")] + ".sha256"
        kind, got, want, miss, diff = _ext_fixture_check(fix, lst)
        out.append((kind == ("fat12" if label == "FAT12" else "fat16")
                    and got and got == want and not miss and not diff,
                    f"every file of the {label} volume a driver wrote reads back as the "
                    f"bytes it wrote ({kind}, {got} of {want}"
                    + (f", {miss} missing" if miss else "")
                    + (f", {diff} different" if diff else "") + ")"))
    with gzip.open(plain, "rb") as gz:
        raw = gz.read()
    with gzip.open(tfat, "rb") as gz:
        traw = gz.read()
    with gzip.open(twelve, "rb") as gz:
        raw12 = gz.read()

    # The control: the same volume read with FAT32's entry width and root. If
    # that listed the files too, the checks above would not show that the
    # 16-bit table and the fixed root are what is being read.
    want = {}
    with open(plain[:-len(".img.gz")] + ".sha256", encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                want[line.rstrip("\n").split("  ", 1)[1]] = line.split("  ", 1)[0]
    try:
        w32 = Fat32Walker(io.BytesIO(raw), 0)
        seen32 = sum(1 for path, _i, _s, _m in collect(w32, w32.root) if path in want)
    except Exception:                                # pylint: disable=broad-except
        seen32 = 0
    out.append((seen32 == 0,
                f"and read as FAT32 the same volume lists none of them "
                f"({seen32} of {len(want)})"))

    # free space: the table's own count, and no live file inside a free run
    w = Fat16Walker(io.BytesIO(raw), 0)
    runs = w.free_extents()
    count = (w.total_sectors - (w.reserved + w.nfats * w.spf)
             - w.root_dir_bytes // w.bps) // w.spc
    table = read_at(w.fh, w.fat_start, (count + 2) * 2)
    zero = sum(1 for c in range(2, count + 2) if table[c * 2:c * 2 + 2] == b"\x00\x00")
    inside = 0
    for _path, node, mode, _sz, _mt, _rec in walk_all(w):
        if mode & S_IFMT == S_IFDIR or not _sz:
            continue
        for c in w._chain(node[0]):                  # pylint: disable=protected-access
            off = w._cluster_off(c)                  # pylint: disable=protected-access
            if any(start <= off < start + length for start, length in runs):
                inside += 1
    free_bytes = sum(length for _start, length in runs)
    out.append((bool(runs) and free_bytes == zero * w.cluster_bytes and not inside,
                f"a FAT16 volume reads its free clusters out of its 16-bit table "
                f"({human(free_bytes)} in {len(runs)} run(s), {zero:,} zero entries, "
                f"{inside} live cluster(s) inside a free run)"))

    # identification: what it says about the transaction-safe volume, what it
    # refuses, and that neither boot sector is taken for a partition table
    tfh = io.BytesIO(traw)
    tid = identify_fat(tfh, 0)
    tlines = tid[1] if tid else []
    tw = Fat16Walker(tfh, 0)
    out.append((bool(tid) and tid[0] == "fat16" and tw.bps == 2048
                and any(l.startswith("type string  TFAT16") for l in tlines)
                and any(l.startswith("FAT copies   2, the first two identical") for l in tlines),
                f"a TFAT16 boot sector with 2,048-byte sectors is read as FAT16 and "
                f"named for what it says it is ({'; '.join(tlines[-2:]) or 'not recognised'})"))
    top = [name for name, child in tw.listdir(tw.root) if tw.entry(child)[0] & S_IFMT == S_IFDIR]
    out.append(("__TFAT_HIDDEN_ROOT_DIR__" in top,
                f"the folder a transaction-safe volume keeps its files under is listed "
                f"as stored ({len(top)} folder(s) in the fixed root)"))
    # a second table that disagrees is counted, and the first is still the one read
    spoiled = bytearray(traw)
    second = tw.fat_start + tw.spf * tw.bps
    for c in (2000, 2001, 2002):
        struct.pack_into("<H", spoiled, second + c * 2, 0xFFFF)
    sid = identify_fat(io.BytesIO(bytes(spoiled)), 0)
    slines = sid[1] if sid else []
    try:
        sw = Fat16Walker(io.BytesIO(bytes(spoiled)), 0)
        same_listing = (sorted(p for p, _i, _s, _m in collect(sw, sw.root))
                        == sorted(p for p, _i, _s, _m in collect(tw, tw.root)))
    except Exception:                                # pylint: disable=broad-except
        same_listing = False
    out.append((any("differ in 3 entries" in l for l in slines) and same_listing,
                f"when the two tables of a transaction-safe volume disagree the "
                f"difference is counted and the first table is the one read "
                f"({slines[-1] if slines else 'not recognised'})"))
    # FAT12: the control is the same volume read with a 16-bit table. The root
    # is where FAT16's is, so names are found, and a file of several clusters is
    # then followed through the wrong entries.
    want12 = listing(twelve)
    as16 = reads_right(Fat16Walker(io.BytesIO(raw12), 0), want12)
    out.append((0 < len(want12) and as16 < len(want12),
                f"and read with a 16-bit table the FAT12 volume gives back fewer of them "
                f"({as16} of {len(want12)})"))
    # free space against a second reading of the table: three bytes, two entries
    w12 = Fat12Walker(io.BytesIO(raw12), 0)
    count12 = (w12.total_sectors - (w12.reserved + w12.nfats * w12.spf)
               - w12.root_dir_bytes // w12.bps) // w12.spc
    tab = read_at(w12.fh, w12.fat_start, w12.spf * w12.bps)
    pairs = []
    for i in range(0, len(tab) - 2, 3):
        three = tab[i] | (tab[i + 1] << 8) | (tab[i + 2] << 16)
        pairs += [three & 0xFFF, three >> 12]
    zero12 = sum(1 for c in range(2, count12 + 2) if pairs[c] == 0)
    free12 = sum(length for _start, length in w12.free_extents())
    out.append((bool(zero12) and free12 == zero12 * w12.cluster_bytes,
                f"a FAT12 volume reads its free clusters out of its 12-bit table "
                f"({human(free12)}, {zero12:,} zero entries by a second unpacking)"))
    # The cluster count types the volume and the string does not: the FAT12
    # volume with "FAT16   " written over its type string is still FAT12, says
    # so, and still reads.
    mislabelled = bytearray(raw12)
    mislabelled[54:62] = b"FAT16   "
    mfh = io.BytesIO(bytes(mislabelled))
    mid = identify_fat(mfh, 0)
    mgood = reads_right(walker_for(mid[0], mfh, 0), want12) if mid else 0
    out.append((bool(mid) and mid[0] == "fat12" and mgood == len(want12)
                and any("the cluster count makes it FAT12" in l for l in mid[1]),
                f"a volume that says FAT16 and has FAT12's cluster count is read as "
                f"FAT12, and says both ({mgood} of {len(want12)} files)"))
    # a BPB the count cannot be computed from is not claimed
    odd = bytearray(raw[:512])
    odd[13] = 3                                      # sectors per cluster: not a power of two
    out.append((identify_fat(io.BytesIO(bytes(odd)), 0) is None,
                "a boot sector that says FAT16 over a BPB that cannot be one is not claimed"))
    out.append((parse_mbr(io.BytesIO(raw)) is None and parse_mbr(io.BytesIO(traw)) is None
                and parse_mbr(io.BytesIO(raw12)) is None,
                "a FAT16, TFAT16 or FAT12 boot sector is not read as a partition table"))
    # TFAT32: FAT32's own structures under another type string
    t32 = bytearray(512)
    struct.pack_into("<H", t32, 11, 2048)
    t32[13] = 1
    struct.pack_into("<H", t32, 14, 32)
    t32[16] = 2
    struct.pack_into("<I", t32, 32, 4096)
    struct.pack_into("<I", t32, 36, 2)
    struct.pack_into("<I", t32, 44, 2)
    t32[82:90] = b"TFAT32  "
    t32[510:512] = b"\x55\xaa"
    body = bytes(t32) + b"\x00" * (2048 * 40)
    got32 = identify_fat(io.BytesIO(body), 0)
    out.append((bool(got32) and got32[0] == "fat32"
                and any(l.startswith("type string  TFAT32") for l in got32[1])
                and parse_mbr(io.BytesIO(body)) is None,
                "a TFAT32 boot sector is read as FAT32 and not as a partition table"))
    return out


def _fat_listing_check(image_gz, wcls):
    """print_tree() on a FAT32 or exFAT fixture prints each file's modified
    reading as stored and never 1970-01-01, which is what the zero mtime
    entry() returns for those walkers formats to. The zero is asserted first,
    so the check proves the substitution and not the absence of a zero.
    Returns (ok, detail)."""
    import contextlib, gzip, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    w = wcls(img, 0)
    files = [(n, i, r) for n, i, r in w.listdir_records(w.root) if not (w.entry(i)[0] & S_IFDIR)]
    if not files:
        return False, "no files in the fixture"
    if any(w.entry(i)[2] != 0 for _n, i, _r in files):
        return False, "premise failed: entry() mtime is not 0, so the check proves nothing"
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        print_tree(w, w.root, 1, 3, [1000])
    out = buf.getvalue()
    if "1970-01-01" in out:
        return False, "a zero mtime was printed as 1970-01-01"
    missing = [n for n, _i, r in files
               if r.get("modified") and f"modified {r['modified']} (as stored" not in out]
    if missing:
        return False, f"reading not printed for {missing[:3]}"
    return True, f"{len(files)} files, readings printed as stored"


def _ntfs_listing_check(image_gz):
    """The control: an NTFS listing, whose times are instants, still prints a
    date for a file. Returns (ok, detail)."""
    import contextlib, gzip, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    w = NtfsWalker(img, 0)
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        print_tree(w, w.root, 1, 2, [5000])
    line = next((l for l in buf.getvalue().splitlines() if " mid.txt" in l), "")
    return ("2026-09-11" in line), (line.strip() or "dir/mid.txt not listed")


def _tree_walk_for_check(w):
    """walk_all's generic route, forced, whatever the walker offers.

    Written out here rather than reached by a flag so the comparison below is
    against a second implementation of the traversal and not against the same
    code with a branch turned off, which would agree with itself.
    """
    seen = set()

    def walk(node, prefix, depth):
        if depth > 64:
            return
        key = node[0] if isinstance(node, tuple) else node
        if key in seen:
            return
        seen.add(key)
        if hasattr(w, "listdir_records"):
            listing = w.listdir_records(node)
        else:
            listing = [(n, i, None) for n, i in w.listdir(node)]
        for name, ino, recorded in listing:
            ent = w.entry(ino)
            if not ent:
                continue
            mode, size, mtime = ent
            path = f"{prefix}/{name}" if prefix else name
            yield (path, mode, size, mtime, recorded)
            if mode & S_IFMT == S_IFDIR:
                for item in walk(ino, path, depth + 1):
                    yield item

    return walk(w.root, "", 0)


def _flash_listing(path, style):
    """{path: (mode, size or None, mtime, target or None)} from an oracle list.

    style "stat" is the fixture scripts' own "octal-mode size mtime path" (from
    Python's lstat on the source tree, or from YAFFS reading its image back);
    style "lln" is unsquashfs -lln, whose times are to the minute, whose device
    lines carry "major, minor" where the size goes, and whose paths start
    "squashfs-root"."""
    types = {"d": S_IFDIR, "-": S_IFREG, "l": S_IFLNK, "c": 0o020000,
             "b": 0o060000, "p": 0o010000, "s": 0o140000}
    out = {}
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line:
                continue
            if style == "stat":
                mode, size, mtime, name = line.split(" ", 3)
                out[name] = (int(mode, 8), int(size), int(mtime), None)
                continue
            perms, _owner, rest = line.split(None, 2)
            if perms[0] in "cb":
                _maj, _min, day, hm, name = rest.split(None, 4)
                size = None
            else:
                size, day, hm, name = rest.split(None, 3)
                size = int(size)
            target = None
            if " -> " in name:
                name, target = name.split(" -> ", 1)
            name = "" if name == "squashfs-root" else name[len("squashfs-root/"):]
            bits = sum(1 << (8 - i) for i, c in enumerate(perms[1:10]) if c != "-")
            when = datetime.datetime.strptime(f"{day} {hm}", "%Y-%m-%d %H:%M")
            out[name] = (types[perms[0]] | bits, size,
                         int(when.replace(tzinfo=datetime.timezone.utc).timestamp()), target)
    return out


def _flash_deleted_check(image_gz, want, churn_name, churn_hashes):
    """recover_deleted() on a history fixture, held against what the fixture's
    writer put in the files it deleted. `want` maps a deleted file's name to
    the bytes the writer gave it; `churn_name` tests a name for the churn files
    written and deleted to force garbage collection, whose possible contents
    are `churn_hashes`. Returns (problems, found, refused): every named file in
    `want` must come back recoverable with exactly those bytes, every other
    recovered file must be a churn file with churn content or be refused, and
    reading a refused one must raise."""
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        raw = gz.read()
    fh = io.BytesIO(raw)
    kind = (identify_fs(fh, 0, len(raw)) or (None,))[0]
    w = walker_for(kind, fh, 0, len(raw)) if kind else None
    if w is None or not hasattr(w, "recover_deleted"):
        return [f"identified as {kind}, with no recover_deleted()"], 0, 0
    problems, seen, found, n_refused = [], set(), 0, 0
    for e in w.recover_deleted():
        if not e.recoverable:
            n_refused += 1
            try:
                for _chunk in w.read_deleted(e):
                    pass
                problems.append(f"{e.name!r} is refused but read_deleted() read it")
            except Exception:                        # pylint: disable=broad-except
                pass
            if e.name in want:
                problems.append(f"{e.name!r} refused: {e.reason}")
            continue
        found += 1
        got = b"".join(w.read_deleted(e))
        if e.name in want:
            seen.add(e.name)
            if got != want[e.name]:
                problems.append(f"{e.name!r}: {len(got)} bytes, "
                                f"not the {len(want[e.name])} written")
        elif churn_name(e.name):
            if hashlib.sha256(got).hexdigest() not in churn_hashes:
                problems.append(f"{e.name!r} ({e.kind} {e.ident}) is not any churn file's content")
        else:
            problems.append(f"{e.name!r} recovered, and the fixture deleted no such file")
    problems += [f"{n!r} not recovered" for n in sorted(set(want) - seen)]
    return problems, found, n_refused


def _ntfs_windows_check(image_gz, known_tsv, break_it=None):
    """Read the NTFS volume Windows wrote (tools/make_ntfs_windows_fixture.cmd)
    and compare every file with what Windows itself reported for it.

    The manifest holds, per file, the length, size on disk and SHA-256 Windows
    gave, and whether Windows could read it with no cloud provider running. So
    the expected values come from the system that wrote the volume and none
    from this reader:

    * a file Windows hashed has to read to that hash, whichever way it is
      stored: plain, resident, sparse, NTFS compressed, overlay-compressed in
      each XPRESS chunk size, or a cloud file that is all there;
    * a file Windows refused to read has to be refused here, and has to be the
      only kind allocation() calls a placeholder;
    * an overlay-compressed LZX file has to be refused by name rather than
      read as the zeros of its unnamed stream;
    * for a sparse or compressed file whose content lies in clusters,
      allocation()'s stored figure has to be Windows's size on disk.

    ``break_it`` takes the walker and returns one with a rule broken, for the
    controls. Returns a dict of counts and a list of what went wrong.
    """
    import gzip, hashlib, io
    with gzip.open(image_gz, "rb") as gz:
        img = io.BytesIO(gz.read())
    size = len(img.getbuffer())
    want = {}
    with open(known_tsv, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line or line.startswith("#"):
                continue
            path, length, _attrs, disk, digest, windows = line.split("\t")
            want[path] = (int(length), int(disk), digest, windows)
    vols = [v for v in volumes(img, size) if v["kind"] == "ntfs" and v.get("walker")]
    if len(vols) != 1:
        return {}, [f"{len(vols)} NTFS volumes found, not the one written"]
    w = vols[0]["walker"]
    if break_it is not None:
        w = break_it(w)
    have = {path: (node, fsize) for path, node, fsize, _m in collect(w, w.root)}
    counts = {"files": len(want), "hashed": 0, "same": 0, "refused_by_windows": 0,
              "refused_here": 0, "lzx": 0, "lzx_refused": 0, "sized": 0, "sized_same": 0,
              "placeholders": 0}
    wrong = []
    for path, (length, disk, digest, windows) in sorted(want.items()):
        got = have.get(path)
        if got is None:
            wrong.append(f"{path}: not listed")
            continue
        node, fsize = got
        if fsize != length:
            wrong.append(f"{path}: listed at {fsize:,} bytes, Windows says {length:,}")
        report = allocation(w, node) or {}
        h, read, refusal = hashlib.sha256(), 0, None
        try:
            for chunk in w.read_file(node, fsize):
                h.update(chunk)
                read += len(chunk)
        except NtfsUnreadable as exc:
            refusal = str(exc)
        lzx = report.get("compression") == "wof-lzx"
        if report.get("placeholder"):
            counts["placeholders"] += 1
        if bool(report.get("placeholder")) != (windows == "refused"):
            wrong.append(f"{path}: placeholder is {report.get('placeholder')}, and Windows "
                         f"{'refused' if windows == 'refused' else 'read'} it")
        if windows == "refused":
            counts["refused_by_windows"] += 1
            if refusal is None:
                wrong.append(f"{path}: Windows would not read it and {read:,} bytes were "
                             "read here")
            else:
                counts["refused_here"] += 1
        elif lzx:
            counts["lzx"] += 1
            if refusal is None or "LZX" not in refusal:
                wrong.append(f"{path}: LZX, and it was not refused by name")
            else:
                counts["lzx_refused"] += 1
        else:
            counts["hashed"] += 1
            if refusal is None and read == length and h.hexdigest() == digest:
                counts["same"] += 1
            else:
                wrong.append(f"{path}: " + (f"refused ({refusal})" if refusal else
                                            "its bytes are not the ones Windows hashed"))
        # Windows reports whole clusters for a sparse or compressed file; for a
        # compressed stream small enough to be resident it still reports one
        # cluster, where stored is the stream's length.
        if (report.get("sparse") or report.get("compression")) and report.get("stored", 0) \
                and not report["stored"] % w.cluster:
            counts["sized"] += 1
            if report["stored"] == disk:
                counts["sized_same"] += 1
            else:
                wrong.append(f"{path}: {report['stored']:,} bytes stored, Windows says "
                             f"{disk:,} on disk")
    return counts, wrong


def _ntfs_lznt1_stop_check(image_gz, decoder=None):
    """Read lznt1/text_100000.txt from copies of the volume Windows wrote
    (tools/make_ntfs_windows_fixture.cmd) with one compression unit changed.

    The file is two units, each stored in two clusters. Three copies:

    * ``second``: the first two bytes of the second unit, its first chunk
      header, set to zero. NTFS's rule is that the unit then reads as zeros,
      so the file is its first 65,536 bytes and 34,464 zeros.
    * ``first``: the same done to the first unit. The file is 65,536 zeros
      and then its own last 34,464 bytes, which tests that the second unit
      still lands at its own offset.
    * ``refused``: the second unit begins with a chunk whose first item is a
      back reference, which has nothing to point back to. No reading of it is
      right, so the read has to raise.

    ``decoder`` stands in for _lznt1_decompress, for the control. Returns
    {"second": (length, sha256), "first": (length, sha256), "refused": bool}.
    """
    import gzip, hashlib, io
    global _lznt1_decompress                         # pylint: disable=global-statement
    with gzip.open(image_gz, "rb") as gz:
        plain = gz.read()

    def find(img):
        for v in volumes(img, len(img.getbuffer())):
            w = v.get("walker")
            if v["kind"] != "ntfs" or not w:
                continue
            for path, node, _s, _m in collect(w, w.root):
                if path.endswith("lznt1/text_100000.txt"):
                    return w, node
        raise ValueError("lznt1/text_100000.txt is not on the volume")

    w, node = find(io.BytesIO(plain))
    data = w._data_attr(node)                        # pylint: disable=protected-access
    units = [w.base + lcn * w.cluster for lcn, _count in data.runs if lcn is not None]
    if len(units) != 2:
        raise ValueError(f"the file is stored in {len(units)} runs, not two units")
    out = {}
    real = _lznt1_decompress
    if decoder is not None:
        _lznt1_decompress = decoder
    try:
        for label, offset, patch in (("second", units[1], b"\x00\x00"),
                                     ("first", units[0], b"\x00\x00"),
                                     ("refused", units[1], b"\x02\xb0\x01\x00\x00")):
            changed = bytearray(plain)
            changed[offset:offset + len(patch)] = patch
            w, node = find(io.BytesIO(bytes(changed)))
            try:
                got = b"".join(w.read_file(node, 100000))
            except NtfsUnreadable:
                out[label] = True if label == "refused" else (0, "refused")
                continue
            out[label] = False if label == "refused" else (
                len(got), hashlib.sha256(got).hexdigest())
    finally:
        _lznt1_decompress = real
    return out


def _flash_fixture_check(image_gz, hashes, listing=None, style="stat", prefix="",
                         loose_times=(), corrupt=None, allow_extra=(), front=None):
    """Read a committed flash filesystem fixture through identify_fs() and
    walker_for(), and hold it against its oracle lists. Returns a dict:

      kind        what identify_fs() called it
      files       [matched, expected, missing, different] against `hashes`,
                  a sha256sum list whose paths are taken under `prefix`
      entries     [agreeing, expected, first disagreements] against `listing`:
                  file type and permission bits, size (not for directories,
                  whose sizes the formats record differently or not at all),
                  modification time (to the minute for "lln"), symlink target
      extra       entries the reader lists under `prefix` that `listing` does
                  not have (a deleted or renamed-away name still showing),
                  other than those named in `allow_extra`
      corrupt     (needle, xor) flips one byte of the decompressed image at the
                  first occurrence of `needle` before it is read: the control
                  that shows the content check can report a difference.
      front       (block bytes, block numbers) moves those blocks, in that
                  order, to the start of the image before it is read. YAFFS2
                  orders blocks by sequence number, not by place, so the
                  image still holds the same filesystem.

    `loose_times` names entries whose time is not on the flash (a directory
    the reader's own writer invents at mount time) and so is not compared.
    """
    import gzip, hashlib, io as _io
    with gzip.open(image_gz, "rb") as gz:
        raw = bytearray(gz.read())
    if front is not None:
        bsize, first = front
        blocks = [bytes(raw[i:i + bsize]) for i in range(0, len(raw), bsize)]
        raw = bytearray(b"".join([blocks[i] for i in first]
                                 + [b for i, b in enumerate(blocks) if i not in first]))
    if corrupt is not None:
        at = raw.find(corrupt[0])
        if at >= 0:
            raw[at] ^= corrupt[1]
    img = _io.BytesIO(bytes(raw))
    size = len(raw)
    kind = (identify_fs(img, 0, size) or (None,))[0]
    w = walker_for(kind, img, 0, size) if kind else None
    res = dict(kind=kind, files=[0, 0, 0, 0], entries=[0, 0, []], extra=[])
    if w is None:
        return res
    got = {p: (node, mode, sz, mt) for p, node, mode, sz, mt, _r in walk_all(w)}
    want = {}
    with open(hashes, encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                digest, path = line.rstrip("\n").split("  ", 1)
                want[prefix + path] = digest
    files = res["files"]
    files[1] = len(want)
    for path, digest in want.items():
        g = got.get(path)
        if g is None:
            files[2] += 1
            continue
        h, n = hashlib.sha256(), 0
        try:
            for chunk in w.read_file(g[0], g[2]):
                h.update(chunk)
                n += len(chunk)
        except Exception:                            # pylint: disable=broad-except
            files[3] += 1
            continue
        if n == g[2] and h.hexdigest() == digest:
            files[0] += 1
        else:
            files[3] += 1
    if listing:
        exp = _flash_listing(listing, style)
        ent = res["entries"]
        ent[1] = len(exp)
        for path, (mode, sz, mt, target) in exp.items():
            g = got.get(prefix + path) if path else None
            if not path:
                root = w.entry(w.root)
                g = (w.root, root[0], root[1], root[2]) if root else None
            why = None
            if g is None:
                why = "missing"
            elif g[1] != mode:
                why = f"mode {g[1]:o}, not {mode:o}"
            elif sz is not None and mode & S_IFMT != S_IFDIR and g[2] != sz:
                why = f"size {g[2]}, not {sz}"
            elif path not in loose_times and (g[3] // 60 * 60 if style == "lln" else g[3]) != mt:
                why = f"time {g[3]}, not {mt}"
            elif target is not None and w.readlink(g[0]) != target:
                why = "symlink target"
            if why:
                if len(ent[2]) < 3:
                    ent[2].append(f"{path or '/'}: {why}")
            else:
                ent[0] += 1
        res["extra"] = sorted(p[len(prefix):] for p in got
                              if p.startswith(prefix) and p[len(prefix):] not in exp
                              and p[len(prefix):] not in allow_extra)
    return res


def _gpt_test_image(ss, volume, first_lba, name, type_guid, used=True):
    """A whole disk image with one GPT partition holding ``volume``, for the
    self-test: a protective MBR at LBA 0, the primary header at LBA 1 and its
    entry array from LBA 2, the partition at ``first_lba``, and the backup array
    and header at the end, every LBA counting ``ss``-byte sectors.

    The layout is UEFI 2.10 section 5.2.3 (Table 5.4, the protective MBR
    record) and section 5.3.2 (Table 5.5, the header; Table 5.6, an entry).
    The offsets are written out here rather than shared with read_gpt(), so the
    reader is checked against the table as the spec gives it. Its output was
    also read by The Sleuth Kit's mmls (-b 4096) and util-linux sfdisk
    (--sector-size 4096), which placed the partition where this says it is.
    """
    n_ent, ent_sz = 128, 128
    arr_lbas = -(-n_ent * ent_sz // ss)
    part_lbas = -(-len(volume) // ss)
    last_lba = first_lba + part_lbas - 1
    total = last_lba + 1 + arr_lbas + 1          # then the backup array and header
    img = bytearray(total * ss)

    # Table 5.4: type 0xEE from LBA 1 for the rest of the disk
    rec = bytearray(16)
    rec[1:4] = b"\x00\x02\x00"                    # StartingCHS 0x000200
    rec[4] = 0xEE
    rec[5:8] = b"\xff\xff\xff"
    struct.pack_into("<II", rec, 8, 1, min(total - 1, 0xFFFFFFFF))
    img[446:462] = rec
    img[510:512] = b"\x55\xaa"

    ent = bytearray(ent_sz)
    ent[0:16] = uuid.UUID(type_guid).bytes_le
    ent[16:32] = uuid.UUID("5a6b7c8d-0000-4000-8000-00000000c0de").bytes_le
    struct.pack_into("<QQQ", ent, 32, first_lba, last_lba, 0)
    ent[56:56 + 2 * len(name)] = name.encode("utf-16-le")
    # used=False leaves every entry zero: a valid table with no partition in it
    arr = (bytes(ent) if used else bytes(ent_sz)) + bytes(ent_sz * (n_ent - 1))

    def header(my_lba, alt_lba, arr_lba):
        h = bytearray(92)
        h[0:8] = b"EFI PART"
        struct.pack_into("<III", h, 8, 0x00010000, 92, 0)
        struct.pack_into("<QQQQ", h, 24, my_lba, alt_lba,
                         2 + arr_lbas, total - 2 - arr_lbas)
        h[56:72] = uuid.UUID("0d15c0de-0000-4000-8000-000000000001").bytes_le
        struct.pack_into("<QIII", h, 72, arr_lba, n_ent, ent_sz,
                         binascii.crc32(arr) & 0xFFFFFFFF)
        struct.pack_into("<I", h, 16, binascii.crc32(bytes(h)) & 0xFFFFFFFF)
        return bytes(h)

    img[ss:ss + 92] = header(1, total - 1, 2)
    img[2 * ss:2 * ss + len(arr)] = arr
    img[first_lba * ss:first_lba * ss + len(volume)] = volume
    back_arr = total - 1 - arr_lbas
    img[back_arr * ss:back_arr * ss + len(arr)] = arr
    img[(total - 1) * ss:(total - 1) * ss + 92] = header(total - 1, 1, back_arr)
    return img


def _walk_all_agreement(image_gz, break_it=None):
    """Compare walk_all() against a walk of the directory tree, on a fixture.

    Returns (volumes, rows, wrong, fast), where wrong counts every path only
    one of them found, every path the fast route reported twice, and every
    field the two disagree on. A walker that offers a fast route is the point
    of the check; ``fast`` says whether one was taken, so a route that stops
    being reached cannot pass by quietly turning into the slow one.

    ``break_it`` is for the control: it is handed each walker and may return a
    stand-in whose fast route is deliberately wrong, which must make this
    report a non-zero ``wrong``. A comparison that has never reported one is
    not evidence of anything.
    """
    import gzip, io as _io
    with gzip.open(image_gz, "rb") as gz:
        img = _io.BytesIO(gz.read())
    found = rows = wrong = 0
    fast = False
    for vol in volumes(img, image_size(img)):
        w = vol.get("walker")
        if w is None:
            continue
        found += 1
        tree = {}
        for path, mode, size, mtime, recorded in _tree_walk_for_check(w):
            tree[path] = (mode, size, mtime, recorded)
        subject = break_it(w) if break_it else w
        fast = fast or hasattr(subject, "listing") or hasattr(subject, "prime_records")
        seen = {}
        for path, _node, mode, size, mtime, recorded in walk_all(subject):
            if path in seen:
                wrong += 1                          # the same path reported twice
            seen[path] = (mode, size, mtime, recorded)
        rows += len(seen)
        wrong += len(set(seen) - set(tree)) + len(set(tree) - set(seen))
        for path in set(seen) & set(tree):
            if seen[path] != tree[path]:
                wrong += 1
    return found, rows, wrong, fast


def _apfs_unlock_checks(enc_path, conv_path, conv_sums):
    """[(passed, label)] for opening encrypted APFS volumes with a password, on the
    two fixtures macOS encrypted (tools/make_apfs_encrypted_fixture.sh and
    tools/make_apfs_converted_fixture.sh) and on copies of the first with one
    structure changed. The passwords and the hint are the fixtures' test values."""
    import hashlib
    pw, conv_pw = "qnxprobe-apfs-test", "qnxprobe-apfs-convert"
    pattern = bytes((i * 131 + 17) % 253 for i in range(262144))
    out = []

    class Patched:
        """The image with some byte ranges replaced, as a changed copy would read."""

        def __init__(self, fh, patches):
            self._fh, self._patches, self._pos = fh, sorted(patches.items()), 0
            self.size = image_size(fh)

        def seek(self, off, whence=0):
            self._pos = off if whence == 0 else self._pos + off if whence == 1 else self.size + off
            return self._pos

        def tell(self):
            return self._pos

        def read(self, n=-1):
            self._fh.seek(self._pos)
            data = bytearray(self._fh.read(n))
            for at, blob in self._patches:
                lo, hi = max(at, self._pos), min(at + len(blob), self._pos + len(data))
                if lo < hi:
                    data[lo - self._pos:hi - self._pos] = blob[lo - at:hi - at]
            self._pos += len(data)
            return bytes(data)

        def close(self):
            self._fh.close()

    def opened(fh, passwords):
        fh, found = unlock_apfs(fh, None, passwords)
        vol = [v for v in volumes(fh) if v["kind"] == "apfs"][0]
        w = vol["walker"]
        got = {p: (n, sz) for p, n, _m, sz, _t, _r in walk_all(w)}
        return fh, found, vol, w, got

    def read(w, got, path):
        return b"".join(w.read_file(*got[path])) if path in got else None

    def run_check(label, leg):
        """One check on its own, so one that raises does not hide the others."""
        try:
            got = leg()
            cond, detail = got if isinstance(got, tuple) else (got, "")
        except Exception as exc:                     # pylint: disable=broad-except
            cond, detail = False, f"raised {type(exc).__name__}: {exc}"
        out.append((bool(cond), label.format(detail) if "{}" in label else
                    label + (f" ({detail})" if detail else "")))

    def right_password():
        with open_image(enc_path) as h:
            fh, found, vol, w, got = opened(h, ["not-the-password", pw])
            lines = identify_fs(fh, vol["base"], vol["size"])[1]
            return ([w.encryption(i) for i in range(len(w.volumes))] == [None, "unlocked"]
                    and len(found) == 1 and found[0].unlocked_by == "password"
                    and read(w, got, "SECRETVOL/docs/readme.txt")
                    == b"known APFS test file in SECRETVOL\n"
                    and read(w, got, "SECRETVOL/docs/pattern.bin") == pattern
                    and read(w, got, "PLAINVOL/docs/pattern.bin") == pattern
                    and "SECRETVOL is encrypted and was opened with a password"
                    in (vol.get("note") or "")
                    and any("SECRETVOL" in ln and "opened with a password" in ln
                            for ln in lines))
    run_check("an APFS volume macOS encrypted opens with its password, tried after a wrong "
          "one, and its files are what macOS wrote", right_password)

    def wrong_password():
        with open_image(enc_path) as h:
            _fh, found, vol, w, got = opened(h, ["not-the-password"])
            return (w.encryption(1) == "locked" and found and found[0].vek is None
                    and found[0].tried and not any(p.startswith("SECRETVOL") for p in got)
                    and 1 not in w._state                            # pylint: disable=protected-access
                    and "SECRETVOL: none of the passwords given opens it"
                    in (vol.get("note") or ""))
    run_check("a wrong password leaves it locked, its tree never parsed, and says so",
          wrong_password)

    def converted():
        with open(conv_sums, encoding="utf-8") as handle:
            sums = {"CONVVOL/" + path: digest for digest, path in
                    (line.rstrip("\n").split("  ", 1) for line in handle if line.strip())}
        with open_image(conv_path) as h:
            _fh, found0, vol0, _w0, _g0 = opened(h, [])
        with open_image(conv_path) as h:
            _fh, found, _vol, w, got = opened(h, [conv_pw])
            matched = sum(1 for path, digest in sums.items()
                          if hashlib.sha256(read(w, got, path) or b"").hexdigest() == digest)
        hint = "the qnxprobe conversion test"
        return (matched == len(sums) == 3 and found and found[0].unlocked_by == "password"
                and found0 and found0[0].hint == hint
                and f'its passphrase hint, as stored: "{hint}"' in (vol0.get("note") or ""),
                f"{matched}/{len(sums)} files")
    run_check("a volume macOS encrypted after files were written opens with its password, "
          "and its hint is reported", converted)

    # a file's data moved, as a container shrink moves it: the extent's block
    # changes and its crypto_id does not, so the tweak must follow crypto_id
    def moved_extent():
        with open_image(enc_path) as h:
            fh, _found, _vol, w, got = opened(h, [pw])
            bs = w.block_size
            node = got["SECRETVOL/docs/pattern.bin"][0]
            w._open_volume(1)                                        # pylint: disable=protected-access
            private = w._dstream(node & APFS_OID_MASK)[1]            # pylint: disable=protected-access
            (_l, phys, length, crypto), = w._runs(private)           # pylint: disable=protected-access
            free = [(off, n) for off, n in w.free_extents(length)
                    if off > w.base + (phys + 64) * bs]
            new_blk = (free[0][0] - w.base) // bs
            patches = {w.base + new_blk * bs: read_at(fh, w.base + phys * bs, length)}
            for _first, blk in w._tree.leaves(_apfs_fs_key):         # pylint: disable=protected-access
                leaf = bytearray(w.block(blk))
                at = leaf.find(struct.pack("<QQ", phys, crypto))
                if at >= 0:
                    struct.pack_into("<Q", leaf, at, new_blk)
                    struct.pack_into("<Q", leaf, 0, _apfs_fletcher(leaf))
                    patches[w.base + blk * bs] = _xts_crypt(
                        w._dec[blk], bytes(leaf), blk * (bs // 512),  # pylint: disable=protected-access
                        encrypt=True)
        with open_image(enc_path) as h:
            _fh, _found, _vol, w2, got2 = opened(Patched(h, patches), [pw])
            w2._open_volume(1)                                       # pylint: disable=protected-access
            runs = w2._runs(private)                                 # pylint: disable=protected-access
            return (runs == [(0, new_blk, length, crypto)] and new_blk != crypto
                    and read(w2, got2, "SECRETVOL/docs/pattern.bin") == pattern,
                    f"block {phys} to {new_blk}, crypto_id {crypto}")
    run_check("a moved extent still reads, its tweak taken from crypto_id", moved_extent)

    # what is refused, each on a copy of the fixture with one structure changed
    def refusals():
        """[(label, patches by byte offset, the words the reason must hold)]"""
        with open_image(enc_path) as h:
            _fh, _found, _vol, w, _got = opened(h, [pw])
            bs, vblk = w.block_size, w.volumes[1][1]
            vsb = w.block(vblk)
            vol_omap_oid = struct.unpack_from("<Q", vsb, 128)[0]
            omap_blk = w.block(vol_omap_oid)
            kl = struct.unpack_from("<QQ", w._nx, APFS_NX_KEYLOCKER_OFF)   # pylint: disable=protected-access
            ckb = read_at(h, w.base + kl[0] * bs, bs)
            # the volume's own keybag, found as ApfsLock finds it
            entries = _apfs_keybag(w, kl, w.uuid, APFS_OBJECT_TYPE_CONTAINER_KEYBAG)
            where = next(d for u, t, d in entries if u == w.volume_uuids[1]
                         and t == APFS_KB_TAG_VOLUME_UNLOCK_RECORDS)
            vkb_blk = struct.unpack_from("<Q", where, 0)[0]
            vkb_raw = read_at(h, w.base + vkb_blk * bs, bs)
            vuuid, base = w.volume_uuids[1], w.base

        def sealed(block):
            block = bytearray(block)
            struct.pack_into("<Q", block, 0, _apfs_fletcher(block))
            return bytes(block)

        def with_field(block, off, fmt, fn):
            block = bytearray(block)
            struct.pack_into(fmt, block, off, fn(struct.unpack_from(fmt, block, off)[0]))
            return sealed(block)

        def value(buf, start, end, tag):
            """(offset, length) of one packed value inside buf[start:end], as
            _apfs_packed reads them, or (-1, 0)."""
            i = start
            while i + 2 <= end:
                t, ln = buf[i], buf[i + 1]
                i += 2
                if ln & 0x80:
                    k = ln & 0x7F
                    ln = int.from_bytes(buf[i:i + k], "big")
                    i += k
                if t == tag:
                    return i, ln
                i += ln
            return -1, 0

        # the first unlock record's flags (the 0x82 value inside its 0x30 and 0xa3
        # values) set to the CoreStorage-compatible form, in a copy of the keybag
        uu = (_BDE_AES.new(vuuid.bytes, _BDE_AES.MODE_ECB),) * 2
        vkb = bytearray(_xts_crypt(uu, vkb_raw, vkb_blk * (bs // 512)))
        keylen = struct.unpack_from("<H", vkb, 48 + 18)[0]
        s30, l30 = value(vkb, 72, 72 + keylen, 0x30)
        sa3, la3 = value(vkb, s30, s30 + l30, 0xA3)
        rec_at, _ln = value(vkb, sa3, sa3 + la3, 0x82)
        vkb[rec_at] |= APFS_KEK_COMPAT_FLAG
        vkb_ct = _xts_crypt(uu, sealed(vkb), vkb_blk * (bs // 512), encrypt=True)
        shapes = [
            ("per-file keys (APFS_FS_ONEKEY clear)", vblk,
             with_field(vsb, APFS_FS_FLAGS_OFF, "<Q", lambda f: f & ~APFS_FS_ONEKEY),
             "per-file keys"),
            ("an encryption change in progress (apfs_er_state_oid set)", vblk,
             with_field(vsb, APFS_ER_STATE_OFF, "<Q", lambda _f: 1),
             "being encrypted, decrypted or given a new key"),
            ("an encryption change in progress (its object map's om_flags)", vol_omap_oid,
             with_field(omap_blk, APFS_OMAP_FLAGS_OFF, "<I", lambda f: f | APFS_OMAP_ENCRYPTING),
             "being encrypted, decrypted or given a new key"),
            ("a container keybag that does not decrypt", kl[0],
             ckb[:100] + bytes([ckb[100] ^ 1]) + ckb[101:],
             "container's keybag does not decrypt"),
            ("an unlock record in the CoreStorage-compatible form", vkb_blk, vkb_ct,
             "CoreStorage-compatible form"),
        ]
        return [(label, {base + blk * bs: blob}, want) for label, blk, blob, want in shapes]

    def is_refused(patches, want):
        with open_image(enc_path) as h:
            _fh, found, vol, w3, got3 = opened(Patched(h, patches), [pw])
            return (len(found) == 1 and found[0].vek is None and want in found[0].why
                    and w3.encryption(1) == "locked"
                    and not any(p.startswith("SECRETVOL") for p in got3)
                    and want in (vol.get("note") or ""))

    try:
        built = refusals()
    except Exception as exc:                         # pylint: disable=broad-except
        built = []
        out.append((False, f"the refused shapes could not be built: "
                           f"{type(exc).__name__}: {exc}"))
    for label, patches, want in built:
        run_check(f"a volume with {label} is refused, and the report says why",
                  lambda patches=patches, want=want: is_refused(patches, want))

    def locked_read():
        with open_image(enc_path) as h:
            _fh, _found, _vol, _w, got = opened(h, [pw])
            node, size = got["SECRETVOL/docs/readme.txt"]
        with open_image(enc_path) as h:              # a later session, without the key
            _fh, _found, _vol, w2, _got = opened(h, [])
            try:
                data = b"".join(w2.read_file(node, size))
            except ApfsUnreadable as exc:
                return "SECRETVOL is encrypted and locked here" in str(exc), str(exc)
            return False, f"read {len(data)} bytes"
    run_check("a file of a volume left locked is refused, not read as empty", locked_read)

    def without_pycryptodome():
        held = globals()["_BDE_AES"]
        globals()["_BDE_AES"] = None
        try:
            with open_image(enc_path) as h:
                _fh, found, _vol, w3, _got = opened(h, [pw])
                return (found and found[0].vek is None and "pycryptodome" in found[0].why
                        and w3.encryption(1) == "locked")
        finally:
            globals()["_BDE_AES"] = held
    run_check("without pycryptodome it stays locked and says what it needs", without_pycryptodome)
    return out


def _efs_fixture_check(raw, known, order):
    """Read an EFS fixture (tools/make_efs_fixtures.py) and hold it against what
    its writer recorded writing. raw is the image, known the parsed
    efs.known.json, order the byte order the image was written in. Returns
    (problems, live entries, deleted-data entries): the partitions have to be
    found where they were put, the live tree has to be the files, directories
    and links written, and recover_deleted() has to return the deleted files
    and the deleted and superseded extents written, each at its offsets, and
    nothing else. A refused entry has to refuse the read."""
    import hashlib, io
    fh = io.BytesIO(raw)
    vols = volumes(fh, len(raw))
    got = [(v["base"], v["size"], v["kind"]) for v in vols]
    want = [(p["base"], p["size"], "efs") for p in known["partitions"]]
    if got != want:
        return [f"volumes() found {got}, and the partitions written are {want}"], 0, 0
    problems, n_live, n_del = [], 0, 0
    kinds = (("a deleted file", "deleted file"),
             ("deleted or superseded extents of a file that still exists",
              "extents of a live file"),
             ("deleted or superseded extents of a deleted file", "extents of a deleted file"),
             ("deleted or superseded file extents no directory entry", "extents with no name"))
    for v, part in zip(vols, known["partitions"]):
        w, at = v.get("walker"), f"partition at {v['base']:#x}"
        if w is None:
            problems.append(f"{at}: {v.get('note')}")
            continue
        if (w.e, w.boot["unit_index"], w.unit_size) != (order, part["unit_index"],
                                                         part["unit_size"]):
            problems.append(f"{at}: byte order {w.e!r}, boot unit {w.boot['unit_index']}, "
                            f"unit size {w.unit_size}")
        files, dirs, links, stack = {}, {}, {}, [(w.root, "")]
        while stack:
            node, path = stack.pop()
            for name, child in w.listdir(node):
                mode, size, mtime = w.entry(child)
                cpath = f"{path}/{name}" if path else name
                n_live += 1
                if mode & S_IFMT == S_IFDIR:
                    dirs[cpath] = dict(mode=mode, mtime=mtime)
                    stack.append((child, cpath))
                    continue
                data = b"".join(w.read_file(child, size))
                if mode & S_IFMT == S_IFLNK:
                    links[cpath] = dict(mode=mode, mtime=mtime, target=data.decode())
                else:
                    files[cpath] = dict(mode=mode, mtime=mtime, size=len(data),
                                        sha256=hashlib.sha256(data).hexdigest())
        for label, have, wanted in (("files", files, part["files"]),
                                    ("directories", dirs, part["dirs"]),
                                    ("symlinks", links, part["symlinks"])):
            if have != wanted:
                problems.append(f"{at}: live {label} read as {sorted(have)}, written "
                                f"{sorted(wanted)}, or a mode, time, size or hash differs")
        deleted = []
        for e in w.recover_deleted():
            n_del += 1
            kind = next((k for prefix, k in kinds if e.note.startswith(prefix)), e.note)
            if e.recoverable:
                data = b"".join(w.read_deleted(e))
            else:
                data = b""
                try:
                    for _chunk in w.read_deleted(e):
                        pass
                    problems.append(f"{at}: {e.name!r} is refused but read_deleted() read it")
                except ValueError:
                    pass
            deleted.append(dict(kind=kind, name=e.name, parent_path=e.parent_path,
                                recoverable=e.recoverable, mode=e.mode, mtime=e.mtime,
                                size=e.size, sha256=hashlib.sha256(data).hexdigest(),
                                extents=[list(x) for x in w.deleted_extents(e)]))
        order_key = lambda d: (d["kind"], d["name"], d["extents"])
        if sorted(deleted, key=order_key) != sorted(part["deleted"], key=order_key):
            problems.append(f"{at}: recover_deleted() gave "
                            f"{sorted((d['kind'], d['name'], d['size']) for d in deleted)}, "
                            f"written {sorted((d['kind'], d['name'], d['size']) for d in part['deleted'])}"
                            ", or a field of one differs")
        stray = w.unaccounted()[1]
        if stray:
            problems.append(f"{at}: {stray} bytes that are not 0xFF lie where no extent is")
    return problems, n_live, n_del


def _efs_qnx_image_check(raw, tar_gz):
    """Read the EFS image QNX itself wrote and hold it against its own record.

    tests/fixtures/efs-qnx.img.gz is test_image.bin from
    NetherlandsForensicInstitute/qnxmount (Apache-2.0, LICENSE-qnxmount) at
    commit 11c8a7f9ee9b945d584263743f6ea8524e8776d2, gzipped here and otherwise
    unchanged (SHA-256 0b0dc3a5...f92b3 unpacked); efs-qnx.tar.gz is its
    test_image.tar.gz as committed. mkefs formatted the image, the devf-ram
    flash driver mounted it, and tests/qnx_efs/test_data/make_test_fs.sh wrote
    to it, then archived the mounted tree with tar. So nothing expected here
    comes from this reader:

    * every live entry's kind, permission bits, mtime, and content or link
      target has to be the tar's;
    * the script wrote 16 random bytes to this_file_is_removed, copied it to
      this_file_is_a_copy and removed it, so recover_deleted() has to return a
      deleted file of that name whose bytes are the copy's;
    * the script rewrote 10 blocks of 1 KiB at block 5 of this_file_is_large,
      so that file's superseded extents have to hold 10,240 bytes that are not
      what the file holds there now;
    * recover_deleted() has to return nothing else, and unaccounted() no
      programmed byte.

    Returns (problems, live entries, bytes of the removed file, superseded
    bytes)."""
    import io, tarfile
    want = {}
    with tarfile.open(tar_gz) as tf:
        for m in tf.getmembers():
            kind = (S_IFDIR if m.isdir() else S_IFLNK if m.issym() else 0o010000 if m.isfifo()
                    else S_IFREG)
            body = (tf.extractfile(m).read() if m.isfile()
                    else m.linkname.encode() if m.issym() else None)
            want[m.name.strip("/")] = (kind, m.mode & 0o7777, m.mtime, body)
    vols = volumes(io.BytesIO(raw), len(raw))
    if [v["kind"] for v in vols] != ["efs"] or "walker" not in vols[0]:
        return [f"volumes() gave {[(v['kind'], v.get('note')) for v in vols]}"], 0, 0, 0
    w = vols[0]["walker"]
    got, stack, problems = {}, [(w.root, "")], []
    while stack:
        node, path = stack.pop()
        for name, child in w.listdir(node):
            mode, size, mtime = w.entry(child)
            cpath = f"{path}/{name}" if path else name
            body = (b"".join(w.read_file(child, size))
                    if mode & S_IFMT in (S_IFREG, S_IFLNK) else None)
            got[cpath] = (mode & S_IFMT, mode & 0o7777, mtime, body)
            if mode & S_IFMT == S_IFDIR:
                stack.append((child, cpath))
    if got != want:
        problems.append("the live tree is not the tar's: "
                        f"{sorted(k for k in set(got) | set(want) if got.get(k) != want.get(k))}")
    entries = list(w.recover_deleted())
    removed = [e for e in entries if e.name == "this_file_is_removed"
               and e.note.startswith("a deleted file")]
    copy = got.get("this_file_is_a_copy", (0, 0, 0, None))[3]
    n_removed = 0
    if (len(removed) != 1 or not removed[0].recoverable or not copy
            or b"".join(w.read_deleted(removed[0])) != copy):
        problems.append("this_file_is_removed did not come back with its copy's bytes")
    else:
        n_removed = removed[0].size
    large = got.get("this_file_is_large", (0, 0, 0, b""))[3] or b""
    old = [e for e in entries if e.name == "this_file_is_large"]
    old_bytes = b"".join(b"".join(w.read_deleted(e)) for e in old)
    states = {state for e in old for _off, _n, state in w.deleted_extents(e)}
    if (len(old_bytes) != 10 * 1024 or states != {"allocated, superseded"}
            or old_bytes == large[5 * 1024:15 * 1024]):
        problems.append(f"this_file_is_large: {len(old_bytes)} superseded bytes in "
                        f"{len(old)} entries, states {sorted(states)}")
    other = [e for e in entries if e not in removed and e not in old]
    if other:
        problems.append(f"{len(other)} entries the script's history does not account for")
    stray = w.unaccounted()[1]
    if stray:
        problems.append(f"{stray} bytes that are not 0xFF lie where no extent is")
    return problems, len(got), n_removed, len(old_bytes)


def self_test():
    """Prove the detector reports BOTH ways before you trust a run.

    Builds three throwaway images in a temp directory, checks them, and removes
    the directory. Nothing outside that directory is touched.
    """
    import tempfile, shutil, gzip

    # These two literals are deliberately NOT QNX6_MAGIC. A self-test that
    # builds its fixtures from the constant it is verifying is circular: it
    # passes even when the constant is wrong. Measured 2026-08-26, an earlier
    # version of this function passed with QNX6_MAGIC set to 0x68191123.
    # If you change these, change them to the value in
    # linux/include/uapi/linux/magic.h and nowhere else.
    TRUE_MAGIC_LE = b"\x22\x11\x19\x68"   # 0x68191122, little endian on disk
    TRUE_MAGIC_BE = b"\x68\x19\x11\x22"   # 0x68191122, big endian on disk

    d = tempfile.mkdtemp(prefix="qnxprobe_selftest_")
    try:
        ok = True
        if struct.pack("<I", QNX6_MAGIC) != TRUE_MAGIC_LE:
            print(f"  [FAIL] QNX6_MAGIC is 0x{QNX6_MAGIC:08x}, expected 0x68191122")
            print("\n  SELF-TEST FAILED. Do not trust results from this build.")
            return 1

        # positive 1: MBR, little endian, superblock at partition + 0x2000,
        # with fully consistent fields
        img = bytearray(SECTOR * 2048 + 6 * 1024 * 1024)
        ent = bytearray(16)
        ent[4] = 0xb1
        struct.pack_into("<II", ent, 8, 2048, 8192)
        img[446:462] = ent
        img[510:512] = b"\x55\xaa"
        o = 2048 * SECTOR + BOOTBLOCK_SIZE
        img[o:o + 4] = TRUE_MAGIC_LE
        struct.pack_into("<I", img, o + 16, 1521471625)   # ctime 2018-03-19
        struct.pack_into("<I", img, o + 20, 1712222868)   # atime 2024-04-04
        struct.pack_into("<H", img, o + 28, 4)
        struct.pack_into("<H", img, o + 30, 3)
        struct.pack_into("<I", img, o + 48, 4096)         # blocksize
        struct.pack_into("<I", img, o + 52, 20000)        # num_inodes
        struct.pack_into("<I", img, o + 56, 15000)        # free_inodes
        struct.pack_into("<I", img, o + 60, 1020)         # num_blocks
        struct.pack_into("<I", img, o + 64, 966)          # free_blocks
        a = os.path.join(d, "positive_le.img")
        open(a, "wb").write(img)

        # positive 2: no partition table, big endian, superblock at offset 0
        img2 = bytearray(64 * 1024)
        img2[0:4] = TRUE_MAGIC_BE
        struct.pack_into(">I", img2, 16, 1521471625)
        struct.pack_into(">I", img2, 20, 1712222868)
        struct.pack_into(">I", img2, 48, 4096)
        struct.pack_into(">I", img2, 52, 128)
        struct.pack_into(">I", img2, 56, 101)
        struct.pack_into(">I", img2, 60, 1020)
        struct.pack_into(">I", img2, 64, 966)
        b = os.path.join(d, "positive_be.img")
        open(b, "wb").write(img2)

        # negative: deterministic bytes that provably do not contain the magic
        neg = bytes(((i * 7 + 13) & 0xFF) for i in range(2 * 1024 * 1024))
        assert TRUE_MAGIC_LE not in neg and TRUE_MAGIC_BE not in neg
        c = os.path.join(d, "negative.img")
        open(c, "wb").write(neg)

        for path, want, label in ((a, True,  "positive, little endian, MBR +0x2000"),
                                  (b, True,  "positive, big endian, no MBR, +0"),
                                  (c, False, "negative, no magic anywhere")):
            with open(path, "rb") as fh:
                hit = None
                for base in (0, 2048 * SECTOR):
                    for rel in (BOOTBLOCK_SIZE, 0):
                        r = check(fh, base + rel)
                        if r and not r[2]:
                            hit = r
                            break
                    if hit:
                        break
            got = hit is not None
            mark = "PASS" if got == want else "FAIL"
            if got != want:
                ok = False
            print(f"  [{mark}] {label}: detected={got}, expected={want}")

        # positive 3: no partition table, but sector 0 is boot code ending in
        # 0x55AA, the shape of qnxmount's qnx6 reference image. Two superblock
        # copies: serial 1 at 0x2000 and serial 2 where the kernel puts the
        # second copy, 0x2000 + 0x1000 + num_blocks * blocksize (fs/qnx6/inode.c
        # qnx6_fill_super). The junk at 446..510 is deterministic and parses as
        # entries with non-zero type and count starting far past the image.
        img3 = bytearray(64 * 1024)
        img3[0:446] = bytes(((i * 11 + 5) & 0xFF) for i in range(446))
        img3[446:510] = bytes(((i * 13 + 7) & 0xFF) for i in range(64))
        img3[510:512] = b"\x55\xaa"

        def q6sb(o, serial, free_inodes):
            img3[o:o + 4] = TRUE_MAGIC_LE
            struct.pack_into("<Q", img3, o + 8, serial)
            struct.pack_into("<I", img3, o + 16, 1521471625)
            struct.pack_into("<I", img3, o + 20, 1712222868)
            struct.pack_into("<H", img3, o + 28, 4)
            struct.pack_into("<H", img3, o + 30, 3)
            struct.pack_into("<I", img3, o + 48, 1024)        # blocksize
            struct.pack_into("<I", img3, o + 52, 48)          # num_inodes
            struct.pack_into("<I", img3, o + 56, free_inodes)
            struct.pack_into("<I", img3, o + 60, 48)          # num_blocks, 48 KiB
            struct.pack_into("<I", img3, o + 64, 40)          # free_blocks
        q6sb(0x2000, 1, 46)
        q6sb(0x2000 + 0x1000 + 48 * 1024, 2, 30)              # 0xF000
        p3 = os.path.join(d, "qnx6_bootblock.img"); open(p3, "wb").write(img3)

        # and the same junk sector on an image holding no filesystem at all
        junk = bytearray(64 * 1024)
        junk[0:512] = img3[0:512]
        pj = os.path.join(d, "junk_mbr.img"); open(pj, "wb").write(junk)

        import io, contextlib
        with open(p3, "rb") as fh:
            got3 = parse_mbr(fh)
        with open(a, "rb") as fh:
            gota = parse_mbr(fh)
        with open(pj, "rb") as fh:
            gotj = parse_mbr(fh)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            main(p3)
        rep = buf.getvalue()
        listed = ("CONFIRMED qnx6 filesystem on whole image" in rep
                  and "ACTIVE   serial 2" in rep and "PREVIOUS serial 1" in rep)
        for label, cond in (
                ("qnx6 boot block ending in 0x55AA is not read as a partition table",
                 got3 is None),
                ("the real MBR on the positive_le image still parses",
                 gota == [(1, 0xb1, 2048, 8192)]),
                ("a 0x55AA sector whose entries all start past the image end is declined",
                 gotj is None),
                ("the boot-block image reports as a whole-image volume, serial 2 active",
                 listed)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # FAT and exFAT detection, both ways, from synthetic boot sectors. The
        # type strings are written as literals here, deliberately not by
        # reference to identify_fat's own comparisons, for the same circularity
        # reason as TRUE_MAGIC_LE above: Microsoft's specifications spell them
        # "FAT32   " at offset 82 and "EXFAT   " at offset 3.
        fat = bytearray(64 * 1024)
        fat[82:90] = b"FAT32   "
        struct.pack_into("<H", fat, 11, 512); fat[13] = 1
        struct.pack_into("<I", fat, 32, 96)
        fat[510:512] = b"\x55\xaa"
        fp = os.path.join(d, "fat32.img"); open(fp, "wb").write(fat)

        exf = bytearray(64 * 1024)
        exf[3:11] = b"EXFAT   "
        exf[108] = 9; exf[109] = 0
        struct.pack_into("<Q", exf, 72, 128)
        struct.pack_into("<I", exf, 92, 16)
        exf[510:512] = b"\x55\xaa"
        xp = os.path.join(d, "exfat.img"); open(xp, "wb").write(exf)

        for path, want_kind, label in (
                (fp, "fat32", "fat32 boot sector recognised"),
                (xp, "exfat", "exfat boot sector recognised"),
                (c, None, "no filesystem claimed on the empty image")):
            with open(path, "rb") as fh:
                r = identify_fat(fh, 0)
            got = r[0] if r else None
            mark = "PASS" if got == want_kind else "FAIL"
            if got != want_kind:
                ok = False
            print(f"  [{mark}] {label}: got={got}")

        # A FAT boot sector must not parse as an MBR: its boot code sits where
        # partition entries would be and yields nonsense regions otherwise.
        for path, label in ((fp, "fat32"), (xp, "exfat")):
            with open(path, "rb") as fh:
                r = parse_mbr(fh)
            mark = "PASS" if r is None else "FAIL"
            if r is not None:
                ok = False
            print(f"  [{mark}] parse_mbr declines the {label} boot sector")

        # ETFS and EFS, the QNX flash filesystems. The reserved names and the
        # F3S signature are spelled here as independent literals, deliberately
        # NOT read from ETFS_RESERVED or EFS_SIG, for the same circularity
        # reason as TRUE_MAGIC_LE above: a fixture built from the constant under
        # test cannot go red when that constant is wrong. Break a name or the
        # signature and this self-test exits 1. Change these only to the values
        # in QNX's fs/etfs.h and fs/f3s_spec.h.
        TRUE_RESERVED = {1: ".filetable", 2: ".badblks", 3: ".counts",
                         4: ".lost+found", 5: ".reserved"}
        TRUE_F3S_SIG = b"QSSL_F3S"
        if ETFS_RESERVED != TRUE_RESERVED:
            print(f"  [FAIL] ETFS_RESERVED {ETFS_RESERVED} != {TRUE_RESERVED}")
            ok = False
        if EFS_SIG != TRUE_F3S_SIG:
            print(f"  [FAIL] EFS_SIG {EFS_SIG!r} != {TRUE_F3S_SIG!r}")
            ok = False

        # A synthetic ETFS image: 1024-byte pages, each with a 16-byte spare
        # transaction. One .filetable page (fid 1) carries the reserved entries
        # and a test file at fid 6; a second page carries that file's data.
        Pz = 1024

        def _tr(fid, cluster, seq):               # an "ok" transaction record
            return struct.pack("<IIHBBI", fid, cluster, 1, 0, 0, seq)

        def _fe(pfid, mode, mtime, size, name):    # a 64-byte file-table entry
            return (struct.pack("<HH", 0x0000, pfid)
                    + struct.pack("<7I", mode, 0, 0, 0, mtime, 0, size)
                    + name.encode("utf-8")[:32].ljust(32, b"\x00"))

        payload = b"ETFS self-test payload\n"
        ftbl = bytearray()
        ftbl += _fe(0x0000, S_IFDIR | 0o755, 0, 0, "")                # fid 0 root
        for fid in range(1, 6):
            m = (S_IFDIR | 0o755) if fid == 4 else 0o100444
            ftbl += _fe(0x0000, m, 0, 0, TRUE_RESERVED[fid])          # fids 1..5
        ftbl += _fe(0x0000, 0o100644, 1712000000, len(payload), "selftest.txt")
        ftbl += b"\xff" * (Pz - len(ftbl))         # remaining entries invalid
        etfs_img = (bytes(ftbl) + _tr(ETFS_FID_FTABLE, 0, 5)
                    + payload.ljust(Pz, b"\x00") + _tr(6, 0, 6))
        ep = os.path.join(d, "etfs.bin"); open(ep, "wb").write(etfs_img)

        with open(ep, "rb") as fh:
            det = identify_etfs(fh, 0, len(etfs_img))
            kind = det[0] if det else None
            got = b""
            if kind == "etfs":
                w = walker_for("etfs", fh, 0, len(etfs_img))
                kids = dict(w.listdir(w.root))
                node = kids.get("selftest.txt")
                if node is not None:
                    got = b"".join(w.read_file(node, w.entry(node)[1]))
        mark = "PASS" if (kind == "etfs" and got == payload) else "FAIL"
        if kind != "etfs" or got != payload:
            ok = False
        print(f"  [{mark}] synthetic ETFS recognised and one file round-tripped: "
              f"kind={kind}")

        # A synthetic EFS image: one erase unit whose unit_info sizes it, whose
        # boot record carries the QSSL_F3S signature, and whose header 2
        # (F3S_BOOT_INDEX) points at that record. Detection only, the same
        # depth as the FAT legs above; the full walk is proven by the round-trip
        # against qnxmount's committed images and by the fixtures below.
        us_pow2 = 16
        efs_img = bytearray(b"\xff" * (1 << us_pow2))
        struct.pack_into("<H", efs_img, 0, 0x10)          # unit_info struct_size
        efs_img[2] = 0x00                                 # endian
        efs_img[3] = 0xFF                                 # pad
        struct.pack_into("<H", efs_img, 4, us_pow2)       # unit_pow2
        efs_img[6:8] = b"\xff\xff"                        # reserve
        struct.pack_into("<I", efs_img, 8, 0)             # erase_count
        bo = 0x100                                        # boot_info offset
        struct.pack_into("<HBB", efs_img, bo, 0x18, 3, 0)
        efs_img[bo + 4:bo + 12] = TRUE_F3S_SIG
        struct.pack_into("<HHHH", efs_img, bo + 12, 0, 1, 0, 2)   # idx,total,spare,align
        struct.pack_into("<HH", efs_img, bo + 20, 1, 0)          # root ptr
        eh = (1 << us_pow2) - 32 * 3                      # header 2: text offset >> align
        efs_img[eh + 19] = 0
        struct.pack_into("<HH", efs_img, eh + 20, bo >> 2, 24)
        efp = os.path.join(d, "efs.bin"); open(efp, "wb").write(bytes(efs_img))
        with open(efp, "rb") as fh:
            det = identify_efs(fh, 0, len(efs_img))
        got_kind = det[0] if det else None
        mark = "PASS" if got_kind == "efs" else "FAIL"
        if got_kind != "efs":
            ok = False
        print(f"  [{mark}] synthetic EFS boot record recognised: kind={got_kind}")
        # The same record with no header pointing at it is not a boot record:
        # the signature string occurs elsewhere in flash images too.
        efs_img[eh + 20:eh + 22] = b"\xff\xff"
        with io.BytesIO(bytes(efs_img)) as fh:
            det = identify_efs(fh, 0, len(efs_img))
        mark = "PASS" if det is None else "FAIL"
        if det is not None:
            ok = False
        print(f"  [{mark}] a QSSL_F3S record that its unit's header 2 does not point at is declined")

        # Neither flash detector may fire on data that is not its filesystem.
        for path, label in ((c, "random"), (fp, "fat32"), (xp, "exfat")):
            sz = os.path.getsize(path)
            with open(path, "rb") as fh:
                e1 = identify_etfs(fh, 0, sz)
                e2 = identify_efs(fh, 0, sz)
            mark = "PASS" if (e1 is None and e2 is None) else "FAIL"
            if e1 is not None or e2 is not None:
                ok = False
            print(f"  [{mark}] ETFS and EFS decline the {label} image")

        # EFS found anywhere in a flash image, in both byte orders, with its
        # deleted and superseded data. tools/make_efs_fixtures.py wrote the two
        # images from one model, one per byte order, and recorded what it wrote;
        # qnxmount, the reference reader, reads the little-endian one's live
        # files as written (it reads neither big-endian nor deleted data). Each
        # image opens with 16 KiB that is not EFS and holds two partitions, the
        # first with its boot record in physical unit 2.
        efs_fx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
        efs_known_path = os.path.join(efs_fx, "efs.known.json")
        if not os.path.isfile(efs_known_path):
            print("  [SKIP] the EFS fixtures are not beside this script, so finding a "
                  "partition by its boot record, the big-endian reading and "
                  "recover_deleted() on EFS were not checked")
        else:
            import gzip
            with open(efs_known_path, encoding="utf-8") as fh:
                efs_known = json.load(fh)
            efs_raw = {}
            for stem, order, word in (("efs-le", "<", "little"), ("efs-be", ">", "big")):
                with gzip.open(os.path.join(efs_fx, stem + ".img.gz"), "rb") as gz:
                    efs_raw[order] = gz.read()
                problems, n_live, n_del = _efs_fixture_check(efs_raw[order], efs_known, order)
                mark = "PASS" if not problems and n_live and n_del else "FAIL"
                if mark == "FAIL":
                    ok = False
                    for line in problems:
                        print("      " + line)
                print(f"  [{mark}] EFS {word}-endian: {len(efs_known['partitions'])} partitions "
                      f"found by their boot records, {n_live} live entries and {n_del} "
                      "entries of deleted and superseded data as written, nothing "
                      "unaccounted for")
            # Three controls, so the checks above can be seen to fail. The
            # placement uses unit_index: with it zeroed, the first partition is
            # no longer where it was written. The comparison reads content: one
            # changed byte of a deleted extent fails it. And unaccounted() sees
            # text no header covers: a deleted extent's header set to free
            # leaves exactly that extent's bytes unaccounted for.
            part_a = efs_known["partitions"][0]
            clean = EfsWalker(io.BytesIO(efs_raw[">"]), part_a["base"], part_a["size"])
            sig = part_a["base"] + clean.boot["sig_at"]
            moved = bytearray(efs_raw[">"])
            moved[sig + 8:sig + 10] = b"\x00\x00"
            moved_at = [p["base"] for p in efs_partitions(io.BytesIO(bytes(moved)), len(moved))]
            victim = next(d for d in part_a["deleted"] if d["name"] == "old.log")
            off, length, _state = victim["extents"][0]
            bent = bytearray(efs_raw[">"])
            bent[off + 5] ^= 0x01
            bent_problems = _efs_fixture_check(bytes(bent), efs_known, ">")[0]
            entry = next(e for e in clean.recover_deleted() if e.name == "old.log")
            ext = entry._plan[0]                     # pylint: disable=protected-access
            head = (part_a["base"] + ext["u"] * clean.unit_size
                    + clean.unit_size - EFS_EXTHDR * (ext["i"] + 1))
            freed = bytearray(efs_raw[">"])
            struct.pack_into(">I", freed, head, ext["s0"] | EFS_FREE)
            stray = EfsWalker(io.BytesIO(bytes(freed)), part_a["base"],
                              part_a["size"]).unaccounted()[1]
            cond = (part_a["base"] not in moved_at and len(bent_problems) == 1
                    and stray == length)
            mark = "PASS" if cond else "FAIL"
            if not cond:
                ok = False
            print(f"  [{mark}] EFS controls: a zeroed unit_index moves the partition, a "
                  f"changed byte of a deleted extent is caught, and a header set to "
                  f"free leaves its {length} bytes unaccounted for ({stray})")

        # And EFS as QNX wrote it: qnxmount's committed test image, with a
        # removed file and an overwrite in its history (_efs_qnx_image_check).
        # The control cuts the removed file's directory entry loose from its
        # data by setting its first extent's header to free, which has to cost
        # the deleted file.
        qnx_img = os.path.join(efs_fx, "efs-qnx.img.gz")
        qnx_tar = os.path.join(efs_fx, "efs-qnx.tar.gz")
        if not (os.path.isfile(qnx_img) and os.path.isfile(qnx_tar)):
            print("  [SKIP] the QNX-written EFS image is not beside this script, so the "
                  "reader was not held against a filesystem QNX wrote")
        else:
            import gzip
            with gzip.open(qnx_img, "rb") as gz:
                qnx_raw = gz.read()
            problems, n_live, n_removed, n_old = _efs_qnx_image_check(qnx_raw, qnx_tar)
            mark = "PASS" if not problems else "FAIL"
            if problems:
                ok = False
                for line in problems:
                    print("      " + line)
            print(f"  [{mark}] EFS written by QNX: {n_live} live entries as QNX's own tar has "
                  f"them, the removed file's {n_removed} bytes equal its copy's, and "
                  f"{n_old:,} superseded bytes of the overwritten file")
            qw = EfsWalker(io.BytesIO(qnx_raw), 0, len(qnx_raw))
            gone = next(e for e in qw.recover_deleted() if e.name == "this_file_is_removed")
            ext = gone._plan[0]                      # pylint: disable=protected-access
            head = ext["u"] * qw.unit_size + qw.unit_size - EFS_EXTHDR * (ext["i"] + 1)
            cut = bytearray(qnx_raw)
            struct.pack_into(qw.e + "I", cut, head, ext["s0"] | EFS_FREE)
            cut_problems = _efs_qnx_image_check(bytes(cut), qnx_tar)[0]
            cond = any("this_file_is_removed" in line for line in cut_problems)
            mark = "PASS" if cond else "FAIL"
            if not cond:
                ok = False
            print(f"  [{mark}] EFS written by QNX, control: with its extent's header set to "
                  "free the removed file no longer comes back, and the check says so")

        # QNX IFS. The UCL decompressor and the imagefs layout are proven byte
        # for byte against real Ford Sync G4 images; these legs are the both-ways
        # regression guard, built from synthetic bytes so no evidence travels.
        #
        # The UCL stream below is a fixed synthetic block that exercises a literal
        # run, a back reference, a reuse of the last offset, a gamma-coded length
        # and the end marker. The expected output is written out by hand rather
        # than taken from the decoder, so a regression fails against a fixed
        # target instead of against itself. It reads: literals "abcXYZ", copy 3
        # from 6 back ("abc"), then copy 7 from 6 back ("XYZabcX").
        UCL_BLOCK = bytes.fromhex("fd61626358595ac40510000000000048ff")
        UCL_WANT = b"abcXYZabcXYZabcX"
        try:
            got = ucl_nrv2b_decompress(UCL_BLOCK)
        except Exception:
            got = None
        mark = "PASS" if got == UCL_WANT else "FAIL"
        if got != UCL_WANT:
            ok = False
        print(f"  [{mark}] UCL NRV2B decompresses a known block to {got!r}")

        broken = bytearray(UCL_BLOCK); broken[1] ^= 0xFF
        try:
            bad = ucl_nrv2b_decompress(bytes(broken))
        except Exception:
            bad = None
        mark = "PASS" if bad != UCL_WANT else "FAIL"
        if bad == UCL_WANT:
            ok = False
        print(f"  [{mark}] a corrupted UCL block does not reproduce it")

        framed = (struct.pack(">H", len(UCL_BLOCK)) + UCL_BLOCK) * 2 + b"\x00\x00"
        try:
            got = ifs_decompress_blocks(framed, ucl_nrv2b_decompress)
        except Exception:
            got = None
        mark = "PASS" if got == UCL_WANT * 2 else "FAIL"
        if got != UCL_WANT * 2:
            ok = False
        print(f"  [{mark}] block framing concatenates two blocks and stops at 0")

        # A small uncompressed imagefs: root dir, a top-level file, a file in an
        # implicit subdirectory, and a symlink. Built from the image.h structs so
        # the walker's dirent parse, implicit-directory synthesis, file read and
        # trailer checksum are all exercised. The trailer is set over the clean
        # image; the sabotaged copy flips one data byte afterwards, so its stored
        # checksum can no longer balance.
        def _ifs_image(corrupt=False):
            f2, f1, tgt = b"second file\n", b"hello d/f1\n", b"/etc/target"
            def attr(size, ino, mode):
                return struct.pack("<HHIIIII", size, 0, ino, mode, 0, 0, 0x5000)
            def d_dir(p, ino):
                t = p + b"\x00"; return attr(24 + len(t), ino, IFS_S_IFDIR | 0o755) + t
            def d_file(p, ino, off, sz):
                t = struct.pack("<II", off, sz) + p + b"\x00"
                return attr(24 + len(t), ino, IFS_S_IFREG | 0o644) + t
            def d_link(p, target, ino):
                nm = p + b"\x00"; t = nm + target + b"\x00"
                return (attr(24 + 4 + len(t), ino, IFS_S_IFLNK | 0o777)
                        + struct.pack("<HH", len(nm), len(target)) + t)
            def table(o2, o1):
                return (d_dir(b"", 1) + d_file(b"f2", 2, o2, len(f2))
                        + d_file(b"d/f1", 3, o1, len(f1))
                        + d_link(b"d/l1", tgt, 4) + struct.pack("<H", 0))
            dir_off = 92
            hdr_dir = dir_off + len(table(0, 0)) - 2
            data = (dir_off + len(table(0, 0)) + 3) & ~3
            o2, o1 = data, data + len(f2)
            img = bytearray(88)
            img[0:7] = b"imagefs"
            struct.pack_into("<I", img, 16, dir_off)
            img += b"/\x00\x00\x00"
            img += table(o2, o1)
            img += b"\x00" * (o2 - len(img))
            img += f2 + f1
            while len(img) % 4:
                img.append(0)
            struct.pack_into("<I", img, 8, len(img) + 4)
            struct.pack_into("<I", img, 12, hdr_dir)
            body = sum(struct.unpack_from("<%dI" % (len(img) // 4), img, 0))
            img += struct.pack("<I", (-body) & 0xFFFFFFFF)
            if corrupt:
                img[o2 + 1] ^= 0xFF
            hdr = bytearray(256)
            struct.pack_into("<I", hdr, 0, QNX_IFS_SIG)
            struct.pack_into("<H", hdr, 4, 1); hdr[6] = 0x01
            struct.pack_into("<H", hdr, 8, 256)
            struct.pack_into("<H", hdr, 10, 183)
            struct.pack_into("<I", hdr, 32, 512)
            struct.pack_into("<I", hdr, 36, 512 + len(img))
            struct.pack_into("<I", hdr, 44, len(img))
            return bytes(hdr) + b"\x00" * (512 - 256) + bytes(img)

        ip = os.path.join(d, "ifs_ok.img"); open(ip, "wb").write(_ifs_image())
        try:
            with open(ip, "rb") as fh:
                det = identify_ifs(fh, 0)
                w = IfsWalker(fh, 0)
                files = {p: (node, sz) for p, node, sz, _ in collect(w, w.root)}
                f2ok = b"".join(w.read_file(*files.get("f2", (None, 0)))) == b"second file\n"
                f1ok = b"".join(w.read_file(*files.get("d/f1", (None, 0)))) == b"hello d/f1\n"
                good = (det is not None and w.compress == "none" and w.cksum_ok is True
                        and f2ok and f1ok and "d" in w.nodes
                        and w.links.get("d/l1") == "/etc/target")
        except Exception:
            good = False
        mark = "PASS" if good else "FAIL"
        if not good:
            ok = False
        print(f"  [{mark}] synthetic IFS: header, tree, subdir, files, symlink, checksum")

        cp = os.path.join(d, "ifs_bad.img"); open(cp, "wb").write(_ifs_image(corrupt=True))
        try:
            with open(cp, "rb") as fh:
                balanced = IfsWalker(fh, 0).cksum_ok
        except Exception:
            balanced = None
        mark = "PASS" if balanced is False else "FAIL"
        if balanced is not False:
            ok = False
        print(f"  [{mark}] a flipped imagefs byte breaks the image checksum")

        # QNX4. The root name, the .bitmap name and the xblk signature are
        # spelled here as independent literals, deliberately NOT read from the
        # code under test, for the same circularity reason as TRUE_MAGIC_LE
        # above. Change these only to the values in the Linux kernel's
        # fs/qnx4 driver and include/uapi/linux/qnx4_fs.h.
        TRUE_QNX4_ROOT = b"/\x00"          # fs/qnx4/inode.c qnx4_checkroot
        TRUE_QNX4_BITMAP = b".bitmap"      # fs/qnx4/inode.c QNX4_BMNAME
        TRUE_QNX4_XBLK = b"IamXblk"        # fs/qnx4/inode.c:110
        if QNX4_XBLK_SIG != TRUE_QNX4_XBLK:
            print(f"  [FAIL] QNX4_XBLK_SIG {QNX4_XBLK_SIG!r} != {TRUE_QNX4_XBLK!r}")
            ok = False

        # A synthetic QNX4 image: superblock at block 2, root dir at block 3
        # carrying .bitmap, a short-named file, a long name linked through
        # .inodes, and a two-extent file resolved through an "IamXblk" block.
        def _q4_ino(name, size, xblk1, xsz1, xblk, nx, mode, mtime, status):
            e = bytearray(64)
            e[0:16] = name[:16].ljust(16, b"\x00")
            struct.pack_into("<I", e, 16, size)
            struct.pack_into("<II", e, 20, xblk1, xsz1)
            struct.pack_into("<I", e, 28, xblk)
            struct.pack_into("<I", e, 36, mtime)
            struct.pack_into("<H", e, 48, nx)
            struct.pack_into("<H", e, 50, mode)
            e[63] = status
            return bytes(e)

        q4_pay = b"qnx4 self-test payload\n"
        q4_long = b"content behind a link entry\n"
        q4_multi = bytes(((i * 31 + 7) & 0xFF) for i in range(700))
        q4 = bytearray(512 * 12)
        # block 2: RootDir "/" (dir at block 3, 1 block) + .inodes entry
        q4[512:512 + 64] = _q4_ino(TRUE_QNX4_ROOT.rstrip(b"\x00"), 512, 3, 1,
                                   0, 1, S_IFDIR | 0o755, 1712000000, 0x21)
        q4[512 + 64:512 + 128] = _q4_ino(b"", 512, 4, 1, 0, 1,
                                         0o100444, 1712000000, 0x11)
        # block 3: the root directory
        root = bytearray(512)
        root[0:64] = _q4_ino(TRUE_QNX4_BITMAP, 64, 5, 1, 0, 1,
                             0o100444, 1712000000, 0x01)
        root[64:128] = _q4_ino(b"selftest.txt", len(q4_pay), 6, 1, 0, 1,
                               0o100644, 1712000001, 0x01)
        lnk = bytearray(64)
        lnk[0:48] = b"a_longer_name_than_sixteen.txt".ljust(48, b"\x00")
        struct.pack_into("<I", lnk, 48, 4)     # inode at block 4, index 1
        lnk[52] = 1
        lnk[63] = 0x08                          # QNX4_FILE_LINK
        root[128:192] = bytes(lnk)
        root[192:256] = _q4_ino(b"multi.bin", len(q4_multi), 8, 1, 9, 2,
                                0o100644, 1712000003, 0x01)
        q4[1024:1536] = bytes(root)
        # block 4: .inodes (signature slot, then the long name's inode)
        q4[1536:1536 + 16] = b"IamTHE.inodeFILE"
        q4[1536 + 64:1536 + 128] = _q4_ino(b"a_longer_name_th", len(q4_long),
                                           7, 1, 0, 1, 0o100600, 1712000002,
                                           0x01)
        # blocks 5..8: bitmap bytes, two file payloads, first half of multi
        q4[2048:2048 + 64] = b"\xff" * 3 + b"\x00" * 61
        q4[2560:2560 + len(q4_pay)] = q4_pay
        q4[3072:3072 + len(q4_long)] = q4_long
        q4[3584:3584 + 512] = q4_multi[:512]
        # block 9: the xblk carrying the second extent (block 10)
        xb = bytearray(512)
        xb[8] = 1
        struct.pack_into("<I", xb, 12, 1)
        struct.pack_into("<II", xb, 16, 10, 1)
        xb[496:496 + 7] = TRUE_QNX4_XBLK
        q4[4096:4608] = bytes(xb)
        q4[4608:4608 + len(q4_multi) - 512] = q4_multi[512:]
        qp = os.path.join(d, "qnx4.img")
        open(qp, "wb").write(bytes(q4))

        with open(qp, "rb") as fh:
            det = identify_qnx4(fh, 0, len(q4))
            kind = det[0] if det else None
            got = got_long = got_multi = b""
            if kind == "qnx4":
                w = walker_for("qnx4", fh, 0, len(q4))
                kids = dict(w.listdir(w.root))
                for nm, dest in (("selftest.txt", "got"),
                                 ("a_longer_name_than_sixteen.txt", "got_long"),
                                 ("multi.bin", "got_multi")):
                    node = kids.get(nm)
                    if node is not None:
                        data = b"".join(w.read_file(node, w.entry(node)[1]))
                        if dest == "got":
                            got = data
                        elif dest == "got_long":
                            got_long = data
                        else:
                            got_multi = data
        good = (kind == "qnx4" and got == q4_pay and got_long == q4_long
                and got_multi == q4_multi)
        mark = "PASS" if good else "FAIL"
        if not good:
            ok = False
        print(f"  [{mark}] synthetic QNX4: root, .bitmap, link entry, "
              f"two-extent xblk file all read: kind={kind}")

        # Sabotage: break the .bitmap name and detection must refuse, exactly
        # as the kernel refuses to mount without it (qnx4_checkroot).
        sab = bytearray(q4)
        sab[1024:1024 + 7] = b".botmap"
        sp_ = os.path.join(d, "qnx4_sab.img")
        open(sp_, "wb").write(bytes(sab))
        with open(sp_, "rb") as fh:
            det = identify_qnx4(fh, 0, len(sab))
        mark = "PASS" if det is None else "FAIL"
        if det is not None:
            ok = False
        print(f"  [{mark}] a broken .bitmap name is declined, as the kernel "
              f"declines it")

        # A QNX4 boot block ending 0x55AA must not parse as an MBR (the same
        # shared-magic hazard as FAT above), and must still identify as qnx4.
        mbrish = bytearray(q4)
        mbrish[446 + 4] = 0x83
        struct.pack_into("<II", mbrish, 446 + 8, 1, 8)
        mbrish[510:512] = b"\x55\xaa"
        mp = os.path.join(d, "qnx4_mbr.img")
        open(mp, "wb").write(bytes(mbrish))
        with open(mp, "rb") as fh:
            r = parse_mbr(fh)
            det = identify_qnx4(fh, 0, len(mbrish))
        goodm = r is None and det is not None
        mark = "PASS" if goodm else "FAIL"
        if not goodm:
            ok = False
        print(f"  [{mark}] parse_mbr declines a QNX4 boot block ending 0x55AA")

        # Mutual declines: qnx4 fires on none of the other synthetic images,
        # and none of the other detectors fires on the qnx4 image.
        for path, label in ((c, "random"), (fp, "fat32"), (xp, "exfat"),
                            (ep, "etfs"), (efp, "efs"), (a, "qnx6 le"),
                            (b, "qnx6 be"), (ip, "ifs")):
            sz = os.path.getsize(path)
            with open(path, "rb") as fh:
                det = identify_qnx4(fh, 0, sz)
            mark = "PASS" if det is None else "FAIL"
            if det is not None:
                ok = False
            print(f"  [{mark}] QNX4 declines the {label} image")
        with open(qp, "rb") as fh:
            others = (identify_fat(fh, 0), identify_etfs(fh, 0, len(q4)),
                      identify_efs(fh, 0, len(q4)), identify_ifs(fh, 0))
        mark = "PASS" if all(o is None for o in others) else "FAIL"
        if not all(o is None for o in others):
            ok = False
        print(f"  [{mark}] FAT, exFAT, ETFS, EFS and IFS all decline the "
              f"qnx4 image")

        # A cut image. The first segment of a split acquisition (.001 of an
        # FTK Imager raw set) carries the partition table and the boot volumes,
        # so it identifies cleanly, and every volume past the cut reads as empty
        # because read_at() answers a seek past the end of the file with empty
        # bytes. Measured 2026-09-04 on a Ford Sync G4 image cut at 1,500 MB: the
        # boot partitions extracted in full and the 28.8 GiB storage volume
        # walked to 0 files with nothing raised. The probe has to say the file is
        # shorter than its table, and a file whose blocks lie past the cut has to
        # be counted SHORT and stored under a name that says so.
        cut = os.path.join(d, "positive_le_cut.img.001")
        with open(a, "rb") as src, open(cut, "wb") as dst:
            dst.write(src.read(3 * 1024 * 1024))
        reps = {}
        for name, path in (("cut", cut), ("full", a)):
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                main(path)
            reps[name] = buf.getvalue()
        after = reps["cut"].split("IMAGE IS SHORTER THAN ITS PARTITION TABLE", 1)
        warned = len(after) == 2 and "MBR part 1" in after[1][:600]
        quiet = "SHORTER THAN" not in reps["full"]
        for label, cond in (
                ("a 3 MiB cut of the 7 MiB positive image is reported shorter than "
                 "its partition table, naming MBR part 1", warned),
                ("the full positive image draws no such warning", quiet)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # The qnx4 fixture behind an MBR whose partition reaches past the cut.
        # multi.bin's second extent is qnx4 block 10 (offset 4608); the image
        # ends there, after the xblk that points to it, so the walk still finds
        # the file and its tail is past the end.
        mimg = bytearray(2048 * SECTOR + 4608)
        ent = bytearray(16)
        ent[4] = 0x4d
        struct.pack_into("<II", ent, 8, 2048, 32)      # 16 KiB declared, 4.5 KiB here
        mimg[446:462] = ent
        mimg[510:512] = b"\x55\xaa"
        mimg[2048 * SECTOR:] = q4[:4608]
        q4cut = os.path.join(d, "qnx4_behind_mbr_cut.img")
        open(q4cut, "wb").write(bytes(mimg))
        q4zip = os.path.join(d, "qnx4_cut.zip")
        man = []
        buf = io.StringIO()
        with zipfile.ZipFile(q4zip, "w") as zf, contextlib.redirect_stdout(buf):
            main(q4cut, extract=q4zip, zf=zf, manifest=man)
        rep_q4 = buf.getvalue()
        names = zipfile.ZipFile(q4zip).namelist()
        vol = "p1_lba2048"
        short_named = [n for n in names
                       if n.startswith(f"{vol}/multi.bin.SHORT-512-of-700")]
        entry = man[0] if man else {}
        for label, cond in (
                ("a file reaching past the cut is counted SHORT in the report and "
                 "the manifest, beside the 3 whole files",
                 "1 SHORT" in rep_q4 and entry.get("short") == 1
                 and entry.get("files") == 3
                 and entry.get("extends_past_image_by_bytes", 0) > 0),
                ("the short file is stored under a name saying how much of it is "
                 "here, and the whole files keep theirs",
                 len(short_named) == 1 and f"{vol}/selftest.txt" in names
                 and f"{vol}/multi.bin" not in names)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # A split image, joined by the reader. FTK Imager and its peers write a
        # raw image as numbered segments, and since 1.13 a run on any one of
        # them reads the whole set. The qnx4 fixture behind an MBR, cut into
        # three unequal, unaligned segments (one cut inside the gap before the
        # partition, one inside a file's extent), must report and extract
        # exactly as the one file does, from the .001 and from the .002, with
        # no short-image warning. The byte level check comes first, reads at
        # and across every boundary against the same slice of the one file
        # through one open handle at a time, so the join is proven
        # independently of any walker. A hole in the numbering, a set with no
        # first segment and a set numbered at two widths are refused by name,
        # and a lone first segment is still read as the one file it is.
        whole = bytearray(2048 * SECTOR + len(q4))
        ent = bytearray(16)
        ent[4] = 0x4d
        struct.pack_into("<II", ent, 8, 2048, -(-len(q4) // SECTOR))
        whole[446:462] = ent
        whole[510:512] = b"\x55\xaa"
        whole[2048 * SECTOR:] = q4
        whole = bytes(whole)
        cuts = (1000 * SECTOR + 7, 2048 * SECTOR + 4700)
        bounds = (0,) + cuts + (len(whole),)
        seg = [os.path.join(d, f"qnx4_split.img.{i + 1:03d}") for i in range(3)]
        for i, sp in enumerate(seg):
            open(sp, "wb").write(whole[bounds[i]:bounds[i + 1]])
        wp = os.path.join(d, "qnx4_split_whole.img")
        open(wp, "wb").write(whole)
        probes = [(c + k, 4096) for c in cuts for k in (-4096, -1, 0, 1)]
        probes += [(off, n) for off in range(0, len(whole), 1234 * 7)
                   for n in (1, 512, 4096)]
        with SegmentedImage(seg) as si:
            si.MAX_OPEN = 1                            # every crossing reopens
            byte_exact = (si.size == len(whole)
                          and all(read_at(si, off, n) == whole[off:off + n]
                                  for off, n in probes)
                          and read_at(si, len(whole) - 10, 100) == whole[-10:]
                          and read_at(si, len(whole) + 5, 10) == b"")
        whole_set = split_segments(seg[1], allow_unequal=True) == seg
        step = -(-len(whole) // 3)
        # Segments of unequal size (these are, so every join above is proven at an
        # unaligned boundary) are refused unless the caller says the set is whole:
        # one cut short reads every byte after it at the wrong offset. Segments of
        # one size and a shorter last one, as the tools write them, join as given.
        try:
            split_segments(seg[1])
            unequal_msg = ""
        except SplitImageError as exc:
            unequal_msg = str(exc)
        even = [os.path.join(d, f"qnx4_even.img.{i + 1:03d}") for i in range(3)]
        for i, sp in enumerate(even):
            open(sp, "wb").write(whole[i * step:(i + 1) * step])
        even_joined = split_segments(even[0]) == even
        cut_mid = [os.path.join(d, f"qnx4_cutmid.img.{i + 1:03d}") for i in range(3)]
        for i, sp in enumerate(cut_mid):
            open(sp, "wb").write(whole[i * step:(i + 1) * step - (16384 if i == 1 else 0)])
        try:
            split_segments(cut_mid[2])
            cut_mid_msg = ""
        except SplitSegmentSizeError as exc:
            cut_mid_msg = str(exc)
        try:
            split_segments(cut_mid[0])
            cut_mid_odd = []
        except SplitSegmentSizeError as exc:
            cut_mid_odd = [os.path.basename(exc.segments[i]) for i in exc.odd]
        cut_mid_allowed = (split_segments(cut_mid[2], allow_unequal=True) == cut_mid
                           and cut_mid_odd == ["qnx4_cutmid.img.002"])
        for sp in even + cut_mid:
            os.remove(sp)

        def run_extract(path, tag):
            zp = os.path.join(d, f"{tag}.zip")
            man, buf = [], io.StringIO()
            with zipfile.ZipFile(zp, "w") as zf, contextlib.redirect_stdout(buf):
                main(path, extract="split.zip", zf=zf, manifest=man,
                     allow_unequal_segments=True)
            with zipfile.ZipFile(zp) as z:
                files = {n: z.read(n) for n in z.namelist()}
            rep = buf.getvalue()
            return rep.split("=" * 78)[2], files, man, rep   # body after the header

        w_body, w_files, w_man, _ = run_extract(wp, "split_whole")
        s1_body, s1_files, s1_man, s1_rep = run_extract(seg[0], "split_first")
        s2_body, s2_files, s2_man, s2_rep = run_extract(seg[1], "split_second")
        os.remove(wp)
        names = [os.path.basename(p) for p in seg]
        sizes = [bounds[i + 1] - bounds[i] for i in range(3)]
        # The three segments stay as the fixture the build's discovery check opens
        # (since 1.75 as segments of one size, the shape a split acquisition has, so
        # they join without --allow-unequal-segments)
        for i, sp in enumerate(seg):
            open(sp, "wb").write(whole[i * step:(i + 1) * step])
        fixture_joins = split_segments(seg[0]) == seg

        def refusal(path):
            try:
                main(path)
            except SplitImageError as exc:
                return str(exc)
            return ""
        gap = [os.path.join(d, f"qnx4_gap.img.{n:03d}") for n in (1, 3)]
        nofirst = [os.path.join(d, f"qnx4_nofirst.img.{n:03d}") for n in (2, 3)]
        widths = [os.path.join(d, n) for n in ("qnx4_width.img.001", "qnx4_width.img.0002")]
        for p in gap + nofirst + widths:
            open(p, "wb").write(whole[:SECTOR])
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            gap_msg, nofirst_msg, width_msg = (refusal(gap[0]), refusal(nofirst[0]),
                                               refusal(widths[0]))
        for p in gap + nofirst + widths:
            os.remove(p)
        for label, cond in (
                ("reads at and across every segment boundary equal the one file, "
                 "through one open handle at a time, and past the end read empty",
                 byte_exact),
                ("any segment names the whole set, in order", whole_set),
                ("the split set reports and extracts exactly as the one file, from "
                 "the .001 and from the .002",
                 w_body == s1_body == s2_body and w_files == s1_files == s2_files
                 and len(w_files) >= 3),
                ("the joined run draws no short-image warning and names its segments",
                 "SHORTER THAN" not in s1_rep and "SHORTER THAN" not in s2_rep
                 and "3 segments joined" in s1_rep and "3 segments joined" in s2_rep),
                ("volumes.json names the first segment as the image and lists every "
                 "segment with its size; the one file carries no segment list",
                 bool(s1_man) and bool(s2_man)
                 and all(m["image"] == names[0]
                         and [e["name"] for e in m["image_segments"]] == names
                         and [e["bytes"] for e in m["image_segments"]] == sizes
                         for m in s1_man + s2_man)
                 and bool(w_man) and all("image_segments" not in m for m in w_man)),
                ("a hole in the numbering is refused naming the missing segment",
                 "qnx4_gap.img.002 is missing" in gap_msg),
                ("a set with no first segment is refused naming it",
                 "qnx4_nofirst.img.001" in nofirst_msg),
                ("segments numbered at two widths are refused",
                 "different number of digits" in width_msg),
                ("a lone first segment is read as the one file it is",
                 split_segments(cut) == []),
                ("segments of unequal size are refused naming them, unless the set "
                 "is said to be whole",
                 "not one size" in unequal_msg and names[0] in unequal_msg
                 and "--allow-unequal-segments" in unequal_msg),
                ("a set of one segment size with a shorter last segment joins, and "
                 "the split set left as a fixture is one",
                 even_joined and fixture_joins),
                ("a middle segment cut short by 16 KiB is refused naming it, and "
                 "joins only when allowed",
                 "qnx4_cutmid.img.002" in cut_mid_msg and cut_mid_allowed)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # An EnCase/EWF acquisition is read through the vendored ewfprobe. The
        # case that matters is the negative one: an .E01 must never be opened as
        # raw bytes, because a container read that way holds no filesystem the
        # walkers can see and the run would report an empty image rather than
        # say it could not read the container.
        # This literal is deliberately NOT EWF_SIGNATURE. A fixture built from
        # the constant it is meant to verify moves with it, so the check passes
        # on a build whose signature is wrong. It is the EWF file signature from
        # the format documentation, written out again here on purpose.
        TRUE_EWF_SIG = b"\x45\x56\x46\x09\x0d\x0a\xff\x00"    # "EVF\t\r\n\xff\0"
        if EWF_SIGNATURE != TRUE_EWF_SIG:
            ok = False
            print(f"  [FAIL] EWF_SIGNATURE is {EWF_SIGNATURE!r}, "
                  f"expected {TRUE_EWF_SIG!r}")
        ewf_fake = os.path.join(d, "fake.E01")
        with open(ewf_fake, "wb") as fh:
            fh.write(TRUE_EWF_SIG + b"\x01\x01\x00\x00\x00" + b"\x00" * 4096)
        # Deliberately not named *.img: this is not an image, and the build
        # workflow harvests the self-test's synthetic images by that glob to
        # smoke-test the frozen executables.
        not_ewf = os.path.join(d, "not_an_acquisition.dat")
        with open(not_ewf, "wb") as fh:
            fh.write(b"PK\x03\x04not an acquisition" + b"\x00" * 512)

        def _opened_as_raw(path):
            """True when open_image handed back a plain file over the container."""
            try:
                handle = open_image(path)
            except Exception:
                return False
            try:
                return isinstance(handle, io.IOBase) and not hasattr(handle, "media_size")
            finally:
                try:
                    handle.close()
                except Exception:
                    pass

        saved_reader = ewfprobe
        try:
            globals()["ewfprobe"] = None
            try:
                open_image(ewf_fake)
                refused_without_reader = False
            except ImageUnreadable as exc:
                refused_without_reader = "ewfprobe" in str(exc)
            except Exception:
                refused_without_reader = False
        finally:
            globals()["ewfprobe"] = saved_reader

        for label, cond in (
                ("the EWF signature is recognised, and other bytes are not",
                 looks_like_ewf(ewf_fake) and not looks_like_ewf(not_ewf)),
                ("an .E01 is never opened as raw bytes",
                 not _opened_as_raw(ewf_fake)),
                ("a file that is not an acquisition still opens normally",
                 _opened_as_raw(not_ewf)),
                ("without the vendored reader an .E01 is refused, saying what "
                 "is missing", refused_without_reader),
                ("with the reader present a damaged acquisition is refused by "
                 "it, not read",
                 saved_reader is None or _ewf_refused_by_reader(ewf_fake))):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # The other containers ewfprobe reads, and the logical evidence it
        # does not hand over as a disk. As above, every signature is written out
        # again from the format sources rather than taken from the constants.
        TRUE_SIGS = {
            "EWF2_SIGNATURE": (EWF2_SIGNATURE, b"EVF2\r\n\x81\x00"),
            "AFF_SIGNATURE": (AFF_SIGNATURE, b"AFF10\r\n\x00"),
            "L01_SIGNATURE": (L01_SIGNATURE, b"LVF\t\r\n\xff\x00"),
            "LX01_SIGNATURE": (LX01_SIGNATURE, b"LEF2\r\n\x81\x00"),
            "UDIF_TRAILER": (UDIF_TRAILER, b"koly"),
            "SPARSEIMAGE_SIGNATURE": (SPARSEIMAGE_SIGNATURE, b"sprs"),
            "DMG_ENCRYPTED_SIGNATURE": (DMG_ENCRYPTED_SIGNATURE, b"encrcdsa"),
            "ADCRYPT_SIGNATURE": (ADCRYPT_SIGNATURE, b"ADCRYPT\x00"),
            "AD1_SIGNATURE": (AD1_SIGNATURE, b"ADSEGMENTEDFILE\x00"),
            "SPARSEBUNDLE_TYPE": (SPARSEBUNDLE_TYPE, "com.apple.diskimage.sparsebundle"),
            "VHD_COOKIE": (VHD_COOKIE, b"conectix"),
            "VHDX_SIGNATURE": (VHDX_SIGNATURE, b"vhdxfile"),
            "VMDK_DESCRIPTOR_START": (VMDK_DESCRIPTOR_START, b"# Disk DescriptorFile"),
            "VMDK_SPARSE_MAGIC": (VMDK_SPARSE_MAGIC, b"KDMV"),
            "VMDK_COWD_MAGIC": (VMDK_COWD_MAGIC, b"COWD"),
            "QCOW_MAGIC": (QCOW_MAGIC, b"QFI\xfb"),
        }
        for const, (have, want) in TRUE_SIGS.items():
            if have != want:
                ok = False
                print(f"  [FAIL] {const} is {have!r}, expected {want!r}")

        def _fake(name, signature):
            path = os.path.join(d, name)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "wb") as fh:
                fh.write(signature + b"\x00" * 4096)
            return path

        ex01_fake = _fake("fake.Ex01", TRUE_SIGS["EWF2_SIGNATURE"][1])
        aff_fake = _fake("fake.aff", TRUE_SIGS["AFF_SIGNATURE"][1])
        afd_dir = os.path.join(d, "fake.afd")
        afd_member = _fake(os.path.join("fake.afd", "file_000.aff"),
                           TRUE_SIGS["AFF_SIGNATURE"][1])
        afd_stray = _fake(os.path.join("fake.afd", "copy.bin"),
                          TRUE_SIGS["AFF_SIGNATURE"][1])
        not_afd_dir = os.path.join(d, "not_an_afd")
        _fake(os.path.join("not_an_afd", "file_000.aff"), TRUE_SIGS["AFF_SIGNATURE"][1])
        empty_afd = os.path.join(d, "empty.afd")
        os.makedirs(empty_afd, exist_ok=True)
        l01_fake = _fake("fake.L01", TRUE_SIGS["L01_SIGNATURE"][1])
        lx01_fake = _fake("fake.Lx01", TRUE_SIGS["LX01_SIGNATURE"][1])
        dmg_fake = os.path.join(d, "fake.dmg")      # a trailer and nothing valid before it
        with open(dmg_fake, "wb") as fh:
            fh.write(b"\x00" * 4096 + TRUE_SIGS["UDIF_TRAILER"][1] + b"\x00" * 508)
        sparse_fake = _fake("fake.sparseimage", TRUE_SIGS["SPARSEIMAGE_SIGNATURE"][1])
        enc_fake = _fake("enc.dmg", TRUE_SIGS["DMG_ENCRYPTED_SIGNATURE"][1])
        ad_first = _fake("ad_fake.0001", TRUE_SIGS["ADCRYPT_SIGNATURE"][1])
        ad_second = _fake("ad_fake.0002", b"\x5a" * 8)
        plain_second = _fake("plain_fake.0002", b"\x00" * 8)
        ad1_fake = _fake(os.path.join("ad1", "fake.ad1"), TRUE_SIGS["AD1_SIGNATURE"][1])
        ad1_second = _fake(os.path.join("ad1", "fake.ad2"), TRUE_SIGS["AD1_SIGNATURE"][1])
        ad1_enc = _fake(os.path.join("ad1enc", "enc.AD1"), TRUE_SIGS["ADCRYPT_SIGNATURE"][1])
        ad1_enc_second = _fake(os.path.join("ad1enc", "enc.ad2"), b"\x5a" * 16)
        ad1_lone = _fake(os.path.join("ad1lone", "lone.ad2"), b"\x5a" * 16)
        # Virtual machine disks: each begins, or for a fixed VHD ends, with its own
        # bytes; everything else in these files is zeros, so each is damaged.
        vhd_fixed_fake = os.path.join(d, "vd", "fixed.vhd")
        os.makedirs(os.path.dirname(vhd_fixed_fake), exist_ok=True)
        with open(vhd_fixed_fake, "wb") as fh:
            fh.write(b"\x00" * 4096 + TRUE_SIGS["VHD_COOKIE"][1] + b"\x00" * 504)
        vhd_dynamic_fake = _fake(os.path.join("vd", "dynamic.vhd"), TRUE_SIGS["VHD_COOKIE"][1])
        vhdx_fake = _fake(os.path.join("vd", "fake.vhdx"), TRUE_SIGS["VHDX_SIGNATURE"][1])
        vmdk_desc_fake = _fake(os.path.join("vd", "fake.vmdk"),
                               TRUE_SIGS["VMDK_DESCRIPTOR_START"][1] + b"\n")
        vmdk_sparse_fake = _fake(os.path.join("vd", "fake-s001.vmdk"),
                                 TRUE_SIGS["VMDK_SPARSE_MAGIC"][1])
        vmdk_cowd_fake = _fake(os.path.join("vd", "fake-cowd.vmdk"),
                               TRUE_SIGS["VMDK_COWD_MAGIC"][1])
        qcow_fake = _fake(os.path.join("vd", "fake.qcow2"),
                          TRUE_SIGS["QCOW_MAGIC"][1] + b"\x00\x00\x00\x03")
        qcow_other = _fake(os.path.join("vd", "other.qcow2"),
                           TRUE_SIGS["QCOW_MAGIC"][1] + b"\x00\x00\x00\x09")
        virtual_fakes = (vhd_fixed_fake, vhd_dynamic_fake, vhdx_fake, vmdk_desc_fake,
                         vmdk_sparse_fake, vmdk_cowd_fake, qcow_fake)
        virtual_kinds = ["VHD", "VHD", "VHDX", "VMDK", "VMDK", "VMDK", "QCOW"]

        class _KeyOnly:
            """A stand-in for the reader, whose image opens only with a private key."""
            class EwfError(Exception):
                pass

            class EwfPasswordError(EwfError):
                pass

            class EwfWrongPasswordError(EwfPasswordError):
                pass

            class EwfPasswordRequiredError(EwfPasswordError):
                def __init__(self, message, needs="password"):
                    super().__init__(message)
                    self.needs = needs

            def open_ewf(self, path, password=None, private_key=None):
                raise self.EwfPasswordRequiredError("sealed", needs="private key")

        def _needs_from(reader):
            saved = ewfprobe
            try:
                globals()["ewfprobe"] = reader
                try:
                    open_image(ewf_fake)
                except ImagePasswordError as exc:
                    return exc.wrong, exc.needs
                return None
            finally:
                globals()["ewfprobe"] = saved

        class _Opened:
            """A stand-in for an AFF a private key opened."""
            format, paths = "AFF", ["x.aff"]
            encryption = {"cipher": "AES-256-CBC", "opened_with": "private key (affkey_evp0)"}

        class _Chain:
            """A stand-in for a reader's image read over a parent."""

            def __init__(self, fmt, paths, parent=None):
                self.format, self.paths, self.parent = fmt, paths, parent

        def _kinds_without_reader(paths):
            saved = ewfprobe
            try:
                globals()["ewfprobe"] = None
                return [acquisition_format(q) for q in paths]
            finally:
                globals()["ewfprobe"] = saved

        class _InnerLogical:
            """A stand-in for the reader whose AD-encrypted set decrypts to an L01 or
            an AD1, to reach open_image's own check after it is opened."""
            EwfPasswordError = EwfWrongPasswordError = Exception

            def __init__(self, fmt):
                self.fmt, self.closed = fmt, False

            def open_ewf(self, path, password=None):
                outer = self

                class _Image:
                    format = outer.fmt

                    def close(self):
                        outer.closed = True
                return _Image()

        def _inner_refusal(fmt):
            reader = _InnerLogical(fmt)
            saved = ewfprobe
            try:
                globals()["ewfprobe"] = reader
                try:
                    open_image(ad1_enc, password="x")
                except ImageUnreadable as exc:
                    return str(exc) if reader.closed else None
                return None
            finally:
                globals()["ewfprobe"] = saved
        _fake("plain_fake.0001", b"\x00" * 8)

        def _bundle(name, token=b"", kind=None):
            folder = os.path.join(d, name)
            os.makedirs(os.path.join(folder, "bands"), exist_ok=True)
            info = {"band-size": 1 << 20, "bundle-backingstore-version": 1,
                    "diskimage-bundle-type": kind or TRUE_SIGS["SPARSEBUNDLE_TYPE"][1],
                    "size": 1 << 20}
            with open(os.path.join(folder, "Info.plist"), "wb") as fh:
                plistlib.dump(info, fh)
            with open(os.path.join(folder, "token"), "wb") as fh:
                fh.write(token)
            return folder

        bundle_fake = _bundle("fake.sparsebundle")
        bundle_enc = _bundle("enc.sparsebundle",
                             token=TRUE_SIGS["DMG_ENCRYPTED_SIGNATURE"][1] + bytes(64))
        bundle_other = _bundle("other.sparsebundle", kind="com.example.other")

        def _refusal(path, reader):
            """The ImageUnreadable message open_image gives with or without the
            vendored reader, or None when it did not refuse that way."""
            saved = ewfprobe
            try:
                globals()["ewfprobe"] = reader
                try:
                    handle = open_image(path)
                except ImageUnreadable as exc:
                    return str(exc)
                except Exception:
                    return None
                handle.close()
                return None
            finally:
                globals()["ewfprobe"] = saved

        for label, cond in (
                ("an Ex01 is an EWF set, and an AFF or L01 is not",
                 looks_like_ewf(ex01_fake) and not looks_like_ewf(aff_fake)
                 and not looks_like_ewf(l01_fake)),
                ("each container is named by its own signature",
                 [acquisition_format(q) for q in (ewf_fake, ex01_fake, aff_fake,
                                                  l01_fake, lx01_fake, not_ewf)]
                 == ["EWF", "EWF2", "AFF", "L01", "Lx01", None]),
                ("an AFD is recognised from its folder and from a file in it",
                 acquisition_format(afd_dir) == "AFD"
                 and acquisition_format(afd_member) == "AFD"),
                ("a folder not named .afd, or an .afd with no AFF file, is not one",
                 acquisition_format(not_afd_dir) is None
                 and acquisition_format(empty_afd) is None),
                ("a folder that is not a sparse bundle or an AFD is refused naming it, "
                 "and an empty .afd is refused as not an AFD, not ended in a traceback",
                 (_refusal(not_afd_dir, ewfprobe) or "").startswith(
                     f"{not_afd_dir} is a folder, not a disk image")
                 and "is not an AFD" in (_refusal(empty_afd, ewfprobe) or "")
                 and "is a folder, not a disk image" in (_refusal(not_afd_dir, None) or "")),
                ("an AFF file not named .aff is read alone, as ewfprobe opens it",
                 acquisition_format(afd_stray) == "AFF"),
                ("an Ex01, an AFF and an AFD are never opened as raw bytes",
                 not any(_opened_as_raw(q) for q in (ex01_fake, aff_fake, afd_member))),
                ("without the vendored reader each is refused, saying what is missing",
                 all("ewfprobe" in (_refusal(q, None) or "")
                     for q in (ex01_fake, aff_fake, afd_dir))),
                ("L01 and Lx01 are refused as logical evidence, with or without "
                 "the reader",
                 all("logical evidence" in (_refusal(q, r) or "")
                     for q in (l01_fake, lx01_fake) for r in (None, saved_reader))),
                ("with the reader present a damaged Ex01 or AFF is refused by it",
                 saved_reader is None or (_ewf_refused_by_reader(ex01_fake)
                                          and _ewf_refused_by_reader(aff_fake))),
                ("an Apple disk image is named by its trailer or its header",
                 [acquisition_format(q) for q in (dmg_fake, sparse_fake, enc_fake)]
                 == ["UDIF", "SPARSEIMAGE", "DMG_ENCRYPTED"]),
                ("a .dmg or .sparseimage is never opened as raw bytes",
                 not any(_opened_as_raw(q) for q in (dmg_fake, sparse_fake))),
                ("without the vendored reader a .dmg is refused, saying what is missing",
                 all("ewfprobe" in (_refusal(q, None) or "")
                     for q in (dmg_fake, sparse_fake))),
                ("without the vendored reader an encrypted image is refused, saying "
                 "what is missing",
                 all("ewfprobe" in (_refusal(q, None) or "") for q in (enc_fake, bundle_enc))),
                ("with the reader present an encrypted image with a damaged header is "
                 "refused by it, not read",
                 saved_reader is None or (_ewf_refused_by_reader(enc_fake)
                                          and _ewf_refused_by_reader(bundle_enc))),
                ("an AD-encrypted set is named by its first file's header, from any "
                 "of its numbered files, and a plain numbered set is not one",
                 [acquisition_format(q) for q in (ad_first, ad_second, plain_second)]
                 == ["AD_ENCRYPTED", "AD_ENCRYPTED", None]
                 and not needs_password(plain_second)
                 # its header is only a signature, so the reader refuses it on opening
                 # and nothing is asked for first
                 and (saved_reader is None or not needs_password(ad_second))),
                ("without the vendored reader an AD-encrypted set is refused, saying "
                 "what is missing",
                 "ewfprobe" in (_refusal(ad_second, None) or "")),
                ("an AD1 is named from any of its files, an AD-encrypted one by its .ad1 "
                 "whatever its case, and a lone .ad2 is not one",
                 [acquisition_format(q) for q in (ad1_fake, ad1_second, ad1_enc,
                                                  ad1_enc_second, ad1_lone)]
                 == ["AD1", "AD1", "AD_ENCRYPTED", "AD_ENCRYPTED", None]
                 and not needs_password(ad1_second)
                 and (saved_reader is None or not needs_password(ad1_enc_second))),
                ("an AD1 is refused as FTK Imager logical evidence, with or without "
                 "the reader",
                 all("FTK Imager logical evidence" in (_refusal(q, r) or "")
                     for q in (ad1_fake, ad1_second) for r in (None, saved_reader))),
                ("an AD-encrypted set that decrypts to an L01 or an AD1 is closed and "
                 "refused as logical evidence",
                 all("logical evidence (" + k + "), encrypted" in (_inner_refusal(f) or "")
                     for f, k in (("EWF-L01", "L01"), ("AD1", "AD1")))),
                ("a sparse bundle is named by its Info.plist, an encrypted one by its "
                 "token, and a folder of another type is not one",
                 [acquisition_format(q) for q in (bundle_fake, bundle_enc, bundle_other)]
                 == ["SPARSEBUNDLE", "DMG_ENCRYPTED", None]),
                ("without the vendored reader a sparse bundle is refused, saying what "
                 "is missing",
                 "ewfprobe" in (_refusal(bundle_fake, None) or "")),
                ("a VHD (by the footer at its end or the copy at its start), a VHDX, a "
                 "VMDK descriptor or sparse extent and a QCOW are each named by their "
                 "own bytes, with and without the reader, and a QCOW of an unknown "
                 "version is not one",
                 [acquisition_format(q) for q in virtual_fakes + (qcow_other,)]
                 == virtual_kinds + [None]
                 and _kinds_without_reader(virtual_fakes + (qcow_other,))
                 == virtual_kinds + [None]),
                ("a virtual disk is never opened as raw bytes",
                 not any(_opened_as_raw(q) for q in virtual_fakes)),
                ("without the vendored reader a virtual disk is refused, saying what is "
                 "missing",
                 all("ewfprobe" in (_refusal(q, None) or "") for q in virtual_fakes)),
                ("with the reader present a damaged virtual disk is refused by it, not "
                 "read",
                 saved_reader is None or all(_ewf_refused_by_reader(q)
                                             for q in virtual_fakes)),
                ("an image the reader says opens only with a private key is refused "
                 "saying so, and one a key opened is described as opened with it",
                 _needs_from(_KeyOnly()) == (False, "private key")
                 and describe_acquisition(_Opened()).endswith(
                     "encrypted (AES-256-CBC) and opened with its private key")),
                ("a disk read over parents names each, nearest first, and records "
                 "every parent file with its size",
                 describe_acquisition(_Chain("QCOW", [vhd_dynamic_fake], _Chain(
                     "QCOW", [qcow_fake], _Chain("QCOW", [vhdx_fake, vmdk_desc_fake]))))
                 == ("a QCOW virtual disk of one file, over its parents fake.qcow2, "
                     "fake.vhdx (nearest first)")
                 and describe_acquisition(_Chain("VHD", [vhd_dynamic_fake],
                                                 _Chain("VHD", [vhdx_fake])))
                 == "a VHD virtual disk of one file, over its parent fake.vhdx"
                 and image_parents(_Chain("VMDK", [vmdk_desc_fake], _Chain(
                     "VMDK", [vmdk_sparse_fake, vmdk_cowd_fake])))
                 == [{"name": "fake-s001.vmdk", "bytes": 4100},
                     {"name": "fake-cowd.vmdk", "bytes": 4100}]
                 and image_parents(_Chain("VHD", [vhd_dynamic_fake])) == [])):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # A fixed and a dynamic VHD built by hand around a known 1 MiB disk, so the
        # route to the reader is tested on bytes it did not write. The layout is
        # written out again here from Microsoft's Virtual Hard Disk Image Format
        # Specification rather than taken from the reader: a big-endian 512-byte
        # footer (a dynamic disk's copy of it first in the file), a 1,024-byte
        # dynamic header, a table of 32-bit block sector offsets, and a block of a
        # sector bitmap (most significant bit first) and its data. Each checksum is
        # the one's complement of the sum of the structure's bytes.
        if saved_reader is None:
            print("  [SKIP] a hand-built VHD reads as its disk (needs the vendored ewfprobe)")
        else:
            vd_disk = bytearray(1 << 20)
            vd_disk[0:512] = bytes(range(256)) * 2
            vd_disk[700 * 512:701 * 512] = b"qnxprobe" * 64

            def _vhd_sum(data):
                return (~sum(data)) & 0xFFFFFFFF

            def _vhd_footer(disk_type, data_offset):
                f = bytearray(512)
                struct.pack_into(">8sIIQIIII", f, 0, b"conectix", 2, 0x00010000,
                                 data_offset, 0, 0, 0, 0)
                struct.pack_into(">QQHBBI", f, 40, len(vd_disk), len(vd_disk), 30, 4, 17,
                                 disk_type)
                f[68:84] = bytes(range(16))
                struct.pack_into(">I", f, 64, _vhd_sum(f))
                return bytes(f)

            vd_fixed = os.path.join(d, "vd", "built-fixed.vhd")
            with open(vd_fixed, "wb") as fh:
                fh.write(bytes(vd_disk) + _vhd_footer(2, 0xFFFFFFFFFFFFFFFF))
            block = 2 << 20
            footer = _vhd_footer(3, 512)
            header = bytearray(1024)
            struct.pack_into(">8sQQIII", header, 0, b"cxsparse", 0xFFFFFFFFFFFFFFFF, 1536,
                             0x00010000, 1, block)
            struct.pack_into(">I", header, 36, _vhd_sum(header))
            bat = struct.pack(">I", 2048 // 512).ljust(512, b"\xff")
            bitmap = bytearray(512)                       # 4,096 sectors in a block
            for sector in (0, 700):                       # the two sectors written
                bitmap[sector >> 3] |= 0x80 >> (sector & 7)
            data = bytes(vd_disk).ljust(block, b"\x00")
            vd_dynamic = os.path.join(d, "vd", "built-dynamic.vhd")
            with open(vd_dynamic, "wb") as fh:
                fh.write(footer + bytes(header) + bat + bytes(bitmap) + data + footer)

            def _reads_as_disk(path):
                try:
                    with open_image(path) as handle:
                        handle.seek(0)
                        return (image_size(handle) == len(vd_disk)
                                and handle.read(len(vd_disk)) == bytes(vd_disk))
                except Exception:           # pylint: disable=broad-exception-caught
                    return False

            for label, cond in (
                    ("a hand-built fixed and dynamic VHD are named VHD and read through "
                     "the reader as the 1 MiB disk they hold, not as their files' bytes",
                     [acquisition_format(q) for q in (vd_fixed, vd_dynamic)]
                     == ["VHD", "VHD"]
                     and _reads_as_disk(vd_fixed) and _reads_as_disk(vd_dynamic)),):
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # An AFF encrypted with a passphrase and an AFM, built by hand from AFFLIB's
        # layout (include/afflib/afflib.h, lib/crypto.cpp, lib/afflib.cpp and
        # lib/vnode_afm.cpp at v3.7.22), written out again here rather than taken from
        # the reader: big-endian segments "AFF\0", name and data lengths, an argument,
        # the name, the data and "ATT\0" with the segment's length; an encrypted one
        # named <name>/aes256, AES-256-CBC with the name (15 bytes at most, then
        # zeros) as its IV, its length the padded length plus the remainder of the
        # plain length mod 16; the file key in affkey_aes256, version 1, then the key
        # and a block of zeros each AES-256-ECB under the SHA-256 of the passphrase.
        def _aff_seg(name, data=b"", arg=0):
            raw = name.encode()
            body = struct.pack(">4sIII", b"AFF\x00", len(raw), len(data), arg) + raw + data
            return body + struct.pack(">4sI", b"ATT\x00", len(body) + 8)

        aff_disk = bytes((i * 7 + 3) & 0xFF for i in range(8190))  # a short last page
        aff_quad = struct.pack(">II", len(aff_disk), 0)            # low word, then high
        aff_cipher = getattr(saved_reader, "_AES", None) if saved_reader is not None else None
        # the header-lost shape needs no reader to be recognised
        lost = os.path.join(d, "vd", "lost-header.aff")
        with open(lost, "wb") as fh:
            fh.write(_aff_seg("badsectors/aes256", bytes(24), 2) + _aff_seg("x", b"y"))
        not_lost = os.path.join(d, "vd", "not-aff.bin")
        with open(not_lost, "wb") as fh:
            fh.write(b"AFF\x00" + bytes(60))
        for label, cond in (
                ("an AFF whose header a segment overwrote (as affcrypto -e leaves one) "
                 "is named AFF with and without the reader, and bytes that only begin "
                 "like a segment are not",
                 [acquisition_format(q) for q in (lost, not_lost)] == ["AFF", None]
                 and _kinds_without_reader((lost, not_lost)) == ["AFF", None]),):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")
        if aff_cipher is None:
            print("  [SKIP] an encrypted AFF opens with its passphrase, and an AFM reads "
                  "from its raw file (needs the vendored ewfprobe and pycryptodome)")
        else:
            import hashlib                  # pylint: disable=import-outside-toplevel
            aff_pw = "qnxprobe-aff"
            file_key = bytes(range(32, 64))

            def _aff_cbc(name, data):
                extra = len(data) % 16
                padded = data + bytes([16]) * ((16 - extra) % 16)
                ecb = aff_cipher.new(file_key, aff_cipher.MODE_ECB)
                out, prev = bytearray(), name.encode()[:15].ljust(16, b"\x00")
                for i in range(0, len(padded), 16):
                    prev = ecb.encrypt(bytes(a ^ b for a, b in zip(padded[i:i + 16], prev)))
                    out += prev
                return bytes(out) + bytes(extra)       # AFFLIB writes the remainder after

            wrap = aff_cipher.new(hashlib.sha256(aff_pw.encode()).digest(),
                                  aff_cipher.MODE_ECB)
            enc_aff = os.path.join(d, "vd", "built-encrypted.aff")
            with open(enc_aff, "wb") as fh:
                fh.write(b"AFF10\r\n\x00" + _aff_seg("pagesize", b"", 4096)
                         + _aff_seg("sectorsize", b"", 512)
                         + _aff_seg("affkey_aes256", struct.pack(">I", 1)
                                    + wrap.encrypt(file_key) + wrap.encrypt(bytes(16)))
                         + _aff_seg("page0/aes256", _aff_cbc("page0", aff_disk[:4096]))
                         + _aff_seg("page1/aes256", _aff_cbc("page1", aff_disk[4096:]))
                         + _aff_seg("imagesize/aes256", _aff_cbc("imagesize", aff_quad), 2))
            afm = os.path.join(d, "vd", "built.afm")
            with open(afm, "wb") as fh:
                fh.write(b"AFF10\r\n\x00" + _aff_seg("aff_file_type", b"AFM")
                         + _aff_seg("raw_image_file_extension", b"000")
                         + _aff_seg("pagesize", b"", 4096) + _aff_seg("sectorsize", b"", 512)
                         + _aff_seg("pages_per_raw_image_file", bytes(8), 2)
                         + _aff_seg("imagesize", aff_quad, 2))
            with open(os.path.join(d, "vd", "built.000"), "wb") as fh:
                fh.write(aff_disk)

            def _described(path):
                with open_image(path) as handle:
                    return describe_acquisition(handle)

            def _aff_refusal(password):
                try:
                    open_image(enc_aff, password=password).close()
                except ImagePasswordError as exc:
                    return exc.wrong, exc.needs
                return None

            def _reads_aff(path, password=None):
                try:
                    with open_image(path, password=password) as handle:
                        handle.seek(0)
                        return (image_size(handle) == len(aff_disk)
                                and handle.read(len(aff_disk)) == aff_disk, handle.format)
                except Exception:           # pylint: disable=broad-exception-caught
                    return False, None

            for label, cond in (
                    ("a hand-built encrypted AFF needs its passphrase, refuses a wrong one, "
                     "and with it reads as the disk it holds, a short last page included",
                     needs_password(enc_aff) and not needs_private_key(enc_aff)
                     and _aff_refusal(None) == (False, "password")
                     and _aff_refusal("not it") == (True, "password")
                     and _reads_aff(enc_aff, aff_pw) == (True, "AFF")),
                    ("a hand-built AFM reads from the raw file beside it, and the report "
                     "names it as an AFM of two files",
                     _reads_aff(afm) == (True, "AFM")
                     and _described(afm).startswith("an AFM acquisition of 2 files"))):
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # An encrypted image built by hand (encrcdsa version 2, AES-128, the keys
        # wrapped with AES-192 as current hdiutil writes them), so opening with and
        # without its password is tested against bytes ewfprobe did not write. The
        # layout values are written out again here rather than taken from the
        # reader. Reading one needs the optional cipher package, and so does this.
        cipher = getattr(saved_reader, "_AES", None) if saved_reader is not None else None
        if cipher is None:
            print("  [SKIP] an encrypted image opens with its password (needs the "
                  "vendored ewfprobe and the pycryptodome package)")
        else:
            import hashlib                  # pylint: disable=import-outside-toplevel
            import hmac                     # pylint: disable=import-outside-toplevel
            enc_disk = bytes(range(256)) * 16            # 4 KiB: eight 512-byte blocks
            aes_key, hmac_key = bytes(range(16)), bytes(range(100, 120))
            salt, wrap_iv = bytes(range(20)), bytes(range(8))
            enc_password = "qnxprobe-self-test"

            def _cbc(key, iv, data):
                ecb = cipher.new(key, cipher.MODE_ECB)
                out, prev = bytearray(), iv
                for i in range(0, len(data), 16):
                    prev = ecb.encrypt(bytes(a ^ b for a, b in zip(data[i:i + 16], prev)))
                    out += prev
                return bytes(out)

            keydata = aes_key + hmac_key + b"CKIE\x00" + bytes([7]) * 7   # to 48 bytes
            derived = hashlib.pbkdf2_hmac("sha1", enc_password.encode(), salt, 1000, 32)
            blob = _cbc(derived[:24], wrap_iv + bytes(8), keydata)
            item = struct.pack(">LQL32sL32s5L", 0x67, 1000, 20, salt, 8, wrap_iv, 192,
                               0x80000001, 7, 6, len(blob)) + blob
            head = (struct.pack(">8s7L16sLQQL", b"encrcdsa", 2, 16, 5, 0x80000001, 128,
                                0x5B, 160, bytes(16), 512, len(enc_disk), 4096, 1)
                    + struct.pack(">LQQ", 1, 0x60, len(item)) + item)
            body = b"".join(
                _cbc(aes_key, hmac.new(hmac_key, struct.pack(">L", n), "sha1").digest()[:16],
                     enc_disk[n * 512:(n + 1) * 512]) for n in range(len(enc_disk) // 512))
            enc_real = os.path.join(d, "enc_real.dmg")
            with open(enc_real, "wb") as fh:
                fh.write(head.ljust(4096, b"\0") + body)

            def _opened_with(passwords):
                try:
                    with open_image_trying(enc_real, None, passwords) as handle:
                        handle.seek(0)
                        return handle.read(len(enc_disk)) == enc_disk
                except ImagePasswordError as exc:
                    return "wrong" if exc.wrong else "required"

            for label, cond in (
                    ("an encrypted image opens with its password and reads its disk",
                     _opened_with([enc_password]) is True),
                    ("without a password it is refused as needing one",
                     _opened_with([]) == "required"),
                    ("with a wrong password it is refused as a wrong one",
                     _opened_with(["not it"]) == "wrong"),
                    ("of several passwords, the one that opens it is used",
                     _opened_with(["not it", enc_password.encode()]) is True)):
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

            # The same image sealed only to a certificate, built by hand as hdiutil
            # -certificate writes the key item (unlock type 2): the 20-byte SHA-1 of
            # the RSA public key in PKCS#1 form in a 32-byte field, algorithm 42
            # (RSA), padding 10 (PKCS#1), a zero, the wrapped length, then the AES
            # and HMAC keys and "CKIE\0" wrapped with RSA PKCS#1 v1.5.
            rsa_mod = getattr(saved_reader, "_RSA", None)
            pkcs1 = getattr(saved_reader, "_PKCS1", None)
            if rsa_mod is None or pkcs1 is None:
                print("  [SKIP] an image sealed to a certificate opens with its private "
                      "key (needs the pycryptodome package)")
            else:
                def _der_len(n):
                    if n < 128:
                        return bytes([n])
                    raw = n.to_bytes((n.bit_length() + 7) // 8, "big")
                    return bytes([0x80 | len(raw)]) + raw

                def _der_int(v):
                    raw = v.to_bytes(v.bit_length() // 8 + 1, "big")
                    return b"\x02" + _der_len(len(raw)) + raw

                sealer, stranger = rsa_mod.generate(1024), rsa_mod.generate(1024)
                pub = _der_int(sealer.n) + _der_int(sealer.e)
                key_id = hashlib.sha1(b"\x30" + _der_len(len(pub)) + pub).digest()
                wrapped = pkcs1.new(sealer.publickey()).encrypt(
                    aes_key + hmac_key + b"CKIE\x00")
                cert_item = (struct.pack(">L32sLLLL", 20, key_id, 42, 10, 0, len(wrapped))
                             + wrapped.ljust(512, b"\0"))
                cert_head = (struct.pack(">8s7L16sLQQL", b"encrcdsa", 2, 16, 5, 0x80000001,
                                         128, 0x5B, 160, bytes(16), 512, len(enc_disk),
                                         4096, 1)
                             + struct.pack(">LQQ", 2, 0x60, len(cert_item)) + cert_item)
                cert_real = os.path.join(d, "cert_real.dmg")
                with open(cert_real, "wb") as fh:
                    fh.write(cert_head.ljust(4096, b"\0") + body)

                def _keyed(keys, passwords=()):
                    try:
                        with open_image_trying(cert_real, None, passwords, keys) as handle:
                            handle.seek(0)
                            return handle.read(len(enc_disk)) == enc_disk
                    except ImagePasswordError as exc:
                        return ("wrong" if exc.wrong else "required", exc.needs)

                for label, cond in (
                        ("an image sealed only to a certificate needs its private key, not "
                         "a password, and opens with it, the first of several that does",
                         needs_private_key(cert_real) and not needs_password(cert_real)
                         and _keyed([]) == ("required", "private key")
                         and _keyed([], ["a password"]) == ("required", "private key")
                         and _keyed([stranger.export_key()]) == ("wrong", "password")
                         and _keyed([stranger.export_key(), sealer.export_key()]) is True),):
                    if not cond:
                        ok = False
                    print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

            # An AD-encrypted raw set of two files, built by hand the way FTK Imager
            # writes one, with the layout values written out again here: AES-CTR
            # with a little-endian counter, file i under i << 64, the header in the
            # first file only, the file key encrypted under PBKDF2-HMAC-SHA1 of the
            # password's SHA-512. Numbered with four digits, so the build's count
            # of the .001 images the self-test leaves behind is unchanged.
            ad_disk = bytes(range(256)) * 12                 # 3 KiB, two files
            ad_key, ad_salt = bytes(range(32, 64)), bytes(range(16))
            ecb_for = lambda key: cipher.new(key, cipher.MODE_ECB)   # noqa: E731

            def _ctr(key, data, first):
                ecb = ecb_for(key)
                stream = b"".join(ecb.encrypt((first + i).to_bytes(16, "little"))
                                  for i in range(-(-len(data) // 16)))
                return bytes(a ^ b for a, b in zip(data, stream))

            made = hashlib.pbkdf2_hmac("sha1", hashlib.sha512(enc_password.encode()).digest(),
                                       ad_salt, 1000, 32)
            wrapped = _ctr(made, ad_key, 0)
            ad_head = (struct.pack("<8sIIhhh2sIIIIII", b"ADCRYPT\x00", 1, 512, -1, -1, -1,
                                   b"\x00\x00", 3, 2, 1000, 16, 32, 64)
                       + ad_salt + wrapped + hmac.new(made, wrapped, "sha512").digest())
            ad_paths = [os.path.join(d, "ad_real.0001"), os.path.join(d, "ad_real.0002")]
            with open(ad_paths[0], "wb") as fh:
                fh.write(ad_head.ljust(512, b"\0") + _ctr(ad_key, ad_disk[:2048], 0))
            with open(ad_paths[1], "wb") as fh:
                fh.write(_ctr(ad_key, ad_disk[2048:], 1 << 64))

            def _ad_opened_with(passwords):
                try:
                    with open_image_trying(ad_paths[1], None, passwords) as handle:
                        handle.seek(0)
                        return handle.read(len(ad_disk) + 1) == ad_disk
                except ImagePasswordError as exc:
                    return "wrong" if exc.wrong else "required"

            globals()["ewfprobe"] = None            # without the reader, as before 1.49:
            try:                                    # ask for the password, then refuse
                ad_asks_without_reader = needs_password(ad_paths[1])
            finally:
                globals()["ewfprobe"] = saved_reader
            for label, cond in (
                    ("an AD-encrypted raw set opens from its second file with its "
                     "password and reads the disk across both files",
                     _ad_opened_with([enc_password]) is True
                     and needs_password(ad_paths[1]) and not needs_private_key(ad_paths[1])
                     and ad_asks_without_reader),
                    ("without its password it is refused as needing one, and with a "
                     "wrong one as a wrong one",
                     _ad_opened_with([]) == "required"
                     and _ad_opened_with(["not it"]) == "wrong")):
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

            # The same set sealed to a certificate as FTK Imager seals one: the salt
            # wrapped with the RSA public key (PKCS#1 v1.5), one RSA block, and the key
            # made from the empty password rather than a password's hash.
            ad_rsa = getattr(saved_reader, "_RSA", None)
            ad_pkcs1 = getattr(saved_reader, "_PKCS1", None)
            if ad_rsa is None or ad_pkcs1 is None:
                print("  [SKIP] an AD-encrypted set sealed to a certificate opens with its "
                      "private key (needs the pycryptodome package)")
            else:
                ad_sealer, ad_stranger = ad_rsa.generate(1024), ad_rsa.generate(1024)
                sealed_made = hashlib.pbkdf2_hmac("sha1", b"", ad_salt, 1000, 32)
                sealed_wrapped = _ctr(sealed_made, ad_key, 0)
                sealed_salt = ad_pkcs1.new(ad_sealer.publickey()).encrypt(ad_salt)
                sealed_head = (struct.pack("<8sIIhhh2sIIIIII", b"ADCRYPT\x00", 1, 512,
                                           -1, -1, -1, b"\x00\x00", 3, 2, 1000,
                                           len(sealed_salt), 32, 64)
                               + sealed_salt + sealed_wrapped
                               + hmac.new(sealed_made, sealed_wrapped, "sha512").digest())
                sealed_paths = [os.path.join(d, "ad_sealed.0001"),
                                os.path.join(d, "ad_sealed.0002")]
                with open(sealed_paths[0], "wb") as fh:
                    fh.write(sealed_head.ljust(512, b"\0") + _ctr(ad_key, ad_disk[:2048], 0))
                with open(sealed_paths[1], "wb") as fh:
                    fh.write(_ctr(ad_key, ad_disk[2048:], 1 << 64))

                def _ad_sealed(keys, passwords=()):
                    try:
                        with open_image_trying(sealed_paths[1], None, passwords,
                                               keys) as handle:
                            handle.seek(0)
                            return handle.read(len(ad_disk) + 1) == ad_disk
                    except ImagePasswordError as exc:
                        return ("wrong" if exc.wrong else "required", exc.needs)

                for label, cond in (
                        ("an AD-encrypted set sealed to a certificate needs its private "
                         "key, not a password, and opens with it, the first of several "
                         "that does",
                         needs_private_key(sealed_paths[0])
                         and not needs_password(sealed_paths[0])
                         and _ad_sealed([]) == ("required", "private key")
                         and _ad_sealed([], ["a password"]) == ("required", "private key")
                         and _ad_sealed([ad_stranger.export_key()]) == ("wrong", "password")
                         and _ad_sealed([ad_stranger.export_key(),
                                         ad_sealer.export_key()]) is True),):
                    if not cond:
                        ok = False
                    print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # ---- APFS ----------------------------------------------------
        # A container superblock built by hand, so identification is tested
        # against bytes this file did not read from a container it also wrote.
        apfs_head = bytearray(4096)
        struct.pack_into("<Q", apfs_head, 16, 7)                  # transaction id
        struct.pack_into("<I", apfs_head, 24, APFS_OBJECT_TYPE_NX_SUPERBLOCK)
        apfs_head[32:36] = APFS_NX_MAGIC
        struct.pack_into("<I", apfs_head, 36, 4096)               # block size
        struct.pack_into("<Q", apfs_head, 40, 256)                # block count
        apfs_img = os.path.join(d, "apfs_head.img")
        open(apfs_img, "wb").write(bytes(apfs_head) + b"\x00" * (1 << 20))
        with open(apfs_img, "rb") as ah:
            apfs_named = identify_apfs(ah, 0)
        apfs_bad = bytearray(apfs_head)
        struct.pack_into("<I", apfs_bad, 36, 3000)                # not a power of two
        apfs_bad_img = os.path.join(d, "apfs_bad.img")
        open(apfs_bad_img, "wb").write(bytes(apfs_bad) + b"\x00" * 4096)
        with open(apfs_bad_img, "rb") as ah:
            apfs_refused = identify_apfs(ah, 0) is None

        # A file-system key is the object id in its low sixty bits and the record
        # type in its high four, and the tree is sorted by the id first.
        fs_key_ok = (_apfs_fs_key(struct.pack("<Q", (APFS_TYPE_DIR_REC << 60) | 4242))
                     == (4242, APFS_TYPE_DIR_REC))

        # The checksum covers everything after itself, in 32-bit words. A block
        # whose checksum is right must pass and one byte later must not.
        good = bytearray(4096)
        struct.pack_into("<Q", good, 8, 1234)
        lo = hi = 0
        for off in range(8, len(good) - 3, 4):
            lo = (lo + struct.unpack_from("<I", good, off)[0]) % 0xFFFFFFFF
            hi = (hi + lo) % 0xFFFFFFFF
        c1 = (0xFFFFFFFF - ((lo + hi) % 0xFFFFFFFF)) % 0xFFFFFFFF
        c2 = (0xFFFFFFFF - ((lo + c1) % 0xFFFFFFFF)) % 0xFFFFFFFF
        struct.pack_into("<Q", good, 0, (c2 << 32) | c1)
        torn = bytearray(good)
        torn[100] ^= 0x01
        checksum_ok = _apfs_fletcher_ok(bytes(good)) and not _apfs_fletcher_ok(bytes(torn))

        # A sealed system volume's tree, built by hand: a root that declares
        # itself hashed and a leaf under it, with the child pointer stored
        # RELATIVE to the tree's root id the way macOS 11 and later write it.
        # The root id, the relative pointer and the id they must add up to are
        # written out separately here on purpose, so the test cannot agree with
        # the code by sharing its arithmetic.
        SEALED_ROOT_OID = 437419        # the tree's own id
        SEALED_REL      = 3108          # what the index node stores
        SEALED_CHILD    = 440527        # 437419 + 3108, stated, not computed
        if SEALED_ROOT_OID + SEALED_REL != SEALED_CHILD:
            raise AssertionError("the sealed-tree test constants disagree")

        def _apfs_node(level, flags, records, root_info=None):
            """One B-tree node laid out the way records() reads it."""
            node = bytearray(4096)
            struct.pack_into("<HHI", node, APFS_OBJ_HDR, flags, level, len(records))
            struct.pack_into("<HH", node, APFS_OBJ_HDR + 8, 0, len(records) * 8)
            toc_at = APFS_OBJ_HDR + 24
            keys_at = toc_at + len(records) * 8
            ends_at = 4096 - (APFS_BTREE_INFO if flags & APFS_BTNODE_ROOT else 0)
            koff, voff = 0, 0
            for i, (k, v) in enumerate(records):
                voff += len(v)
                struct.pack_into("<HHHH", node, toc_at + i * 8,
                                 koff, len(k), voff, len(v))
                node[keys_at + koff:keys_at + koff + len(k)] = k
                node[ends_at - voff:ends_at - voff + len(v)] = v
                koff += len(k)
            if root_info is not None:
                struct.pack_into("<I", node, 4096 - APFS_BTREE_INFO, root_info)
            return bytes(node)

        leaf_key = struct.pack("<Q", (APFS_TYPE_DIR_REC << 60) | 7)
        leaf = _apfs_node(0, APFS_BTNODE_LEAF, [(leaf_key, b"leafvalue")])
        # An index value in a hashed tree is the child pointer and then a hash,
        # so it is forty bytes where an ordinary one is eight.
        index_val = struct.pack("<Q", SEALED_REL) + bytes(range(32))
        root = _apfs_node(1, APFS_BTNODE_ROOT | 0x0008 | 0x0010,
                          [(struct.pack("<Q", 0), index_val)],
                          root_info=APFS_BTREE_HASHED)

        class _SealedVol:
            """Only what a B-tree asks of a volume: blocks, and id to block."""
            fixed_key_size = fixed_val_size = 0

            def block(self, n):
                return {10: root, 20: leaf}.get(n, bytes(4096))

            def resolve(self, oid):
                return {SEALED_CHILD: 20}.get(oid)

        _sv = _SealedVol()
        sealed_found = _ApfsBtree(_sv, 10, base_oid=SEALED_ROOT_OID).leaves(_apfs_fs_key)
        sealed_blind = _ApfsBtree(_sv, 10).leaves(_apfs_fs_key)
        # Read as a plain tree the pointer names an id the map does not hold, so
        # nothing is found. That is the shape of the defect this guards.
        sealed_ok = (sealed_found == [((7, APFS_TYPE_DIR_REC), 20)]
                     and sealed_blind == [])

        # The declaration is what marks the tree, and it is read from the
        # btree_info in the root node's last forty bytes.
        plain_root = _apfs_node(1, APFS_BTNODE_ROOT, [(struct.pack("<Q", 0), b"")],
                                root_info=0x00000042)
        sealed_flag_ok = (
            struct.unpack_from("<I", root, 4096 - APFS_BTREE_INFO)[0] & APFS_BTREE_HASHED
            and not struct.unpack_from("<I", plain_root, 4096 - APFS_BTREE_INFO)[0]
            & APFS_BTREE_HASHED)

        # A sealed volume's object ids run to sixty bits, so a walker node has
        # to carry one whole beside its volume index.
        _big = (5 << APFS_VOL_SHIFT) | 0x0FFFFFFF00001234
        wide_oid_ok = (_big >> APFS_VOL_SHIFT == 5
                       and _big & APFS_OID_MASK == 0x0FFFFFFF00001234
                       and _big != APFS_CONTAINER)

        # The space manager, built by hand. It is an ephemeral object, so it is
        # reached through a checkpoint map rather than the object map. The
        # descriptor area carries a superblock copy first and a STALE map second,
        # so both the type check and the transaction check have something to
        # reject, and the first chunk does not start at block zero, so a run's
        # base has to come from its chunk. The used blocks are one statement and
        # the runs they leave are another, and the check is on run positions,
        # because a free-block count cannot tell one bit order from the other.
        SM_BLOCK, SM_XID, SM_OID = 4096, 9, 1024
        SM_TOTAL = 48
        SM_USED = {0, 1, 2, 3, 4, 5, 6, 7, 9, 20, 21, 22, 23}
        # by hand: chunk one covers blocks 0..23 with a bitmap, chunk two 24..45
        # with a bitmap and nothing used, chunk three has no bitmap and so is
        # wholly free. Chunk three claims eight blocks from 46 where the
        # container has only two left, which is what a corrupt or truncated
        # container looks like, and the answer must stop at the container's own
        # block count rather than running past the end of the image. Free runs
        # are 8, 10..19, and 24..47 once the last two chunks' runs are joined.
        SM_WANT = [(8, 1), (10, 10), (24, 24)]
        _sb = bytearray(64 * SM_BLOCK)

        def _obj(at, xid, otype):
            struct.pack_into("<Q", _sb, at + 16, xid)
            struct.pack_into("<I", _sb, at + 24, otype)

        _obj(0, SM_XID, APFS_OBJECT_TYPE_NX_SUPERBLOCK)
        _sb[32:36] = APFS_NX_MAGIC
        struct.pack_into("<I", _sb, 36, SM_BLOCK)
        struct.pack_into("<Q", _sb, 40, SM_TOTAL)
        struct.pack_into("<I", _sb, 104, 3)          # nx_xp_desc_blocks
        struct.pack_into("<Q", _sb, 112, 1)          # nx_xp_desc_base, block 1
        struct.pack_into("<Q", _sb, APFS_NX_SPACEMAN_OID_OFF, SM_OID)

        # block 1: a superblock copy carrying this transaction id, with bytes
        # that would read as a mapping to a decoy if its type went unchecked
        _obj(1 * SM_BLOCK, SM_XID, APFS_OBJECT_TYPE_NX_SUPERBLOCK)
        struct.pack_into("<I", _sb, 1 * SM_BLOCK + 36, SM_BLOCK)   # its block size
        struct.pack_into("<QQ", _sb, 1 * SM_BLOCK + 40 + 24, SM_OID, 50)

        def _cpmap(block_no, xid, oid, paddr):
            at = block_no * SM_BLOCK
            _obj(at, xid, APFS_OBJECT_TYPE_CHECKPOINT_MAP)
            struct.pack_into("<I", _sb, at + 36, 1)  # one mapping
            struct.pack_into("<QQ", _sb, at + 40 + 24, oid, paddr)

        _cpmap(2, SM_XID - 1, SM_OID, 50)            # stale, names a decoy
        _cpmap(3, SM_XID, SM_OID, 4)                 # current

        def _spaceman(block_no, cib_block):
            at = block_no * SM_BLOCK
            _obj(at, SM_XID, APFS_OBJECT_TYPE_SPACEMAN)
            dev = at + APFS_SM_DEV_MAIN_OFF
            struct.pack_into("<II", _sb, dev + 16, 1, 0)   # one cib, no cab
            struct.pack_into("<I", _sb, dev + 32, 200)     # sm_addr_offset
            struct.pack_into("<Q", _sb, at + 200, cib_block)

        _spaceman(4, 7)                              # the real one, cib at block 7
        _spaceman(50, 51)                            # the decoy, outside the container

        def _cib(block_no, chunks):
            at = block_no * SM_BLOCK
            struct.pack_into("<I", _sb, at + 36, len(chunks))
            for i, (addr, count, free, bm) in enumerate(chunks):
                o = at + 40 + i * APFS_CI_SIZE
                struct.pack_into("<Q", _sb, o + 8, addr)
                struct.pack_into("<II", _sb, o + 16, count, free)
                struct.pack_into("<Q", _sb, o + 24, bm)

        _cib(7, [(0, 24, 11, 5), (24, 22, 22, 6), (46, 8, 8, 0)])
        _cib(51, [(0, 48, 48, 0)])                   # the decoy says everything is free
        for _b in SM_USED:                           # least significant bit first
            if _b < 24:
                _sb[5 * SM_BLOCK + (_b >> 3)] |= 1 << (_b & 7)
            elif _b < 46:
                _i = _b - 24
                _sb[6 * SM_BLOCK + (_i >> 3)] |= 1 << (_i & 7)

        class _SpacemanOnly:
            """Only what free_extents asks of an APFS walker."""
            free_extents = ApfsWalker.free_extents   # pylint: disable=protected-access
            _ephemeral = ApfsWalker._ephemeral       # pylint: disable=protected-access
            base = 0
            block_size = SM_BLOCK
            block_count = SM_TOTAL
            xid = SM_XID

            def __init__(self, buf):
                self._buf = bytes(buf)
                self._nx = self._buf[0:SM_BLOCK]

            def block(self, n):
                return self._buf[n * SM_BLOCK:(n + 1) * SM_BLOCK]

        _smgot = _SpacemanOnly(_sb).free_extents()
        apfs_free_ok = _smgot == [(c * SM_BLOCK, n * SM_BLOCK) for c, n in SM_WANT]
        apfs_free_floor_ok = (_SpacemanOnly(_sb).free_extents(min_bytes=11 * SM_BLOCK)
                              == [(24 * SM_BLOCK, 24 * SM_BLOCK)])
        # a container whose space manager cannot be found says nothing rather
        # than saying nothing is free
        _nosm = bytearray(_sb)
        struct.pack_into("<Q", _nosm, APFS_NX_SPACEMAN_OID_OFF, 0)
        apfs_no_spaceman_ok = _SpacemanOnly(_nosm).free_extents() == []
        # nor may it read whatever the checkpoint map happens to point at: a
        # mapping that names a block which is not a space manager is refused
        _wrongobj = bytearray(_sb)
        struct.pack_into("<I", _wrongobj, 4 * SM_BLOCK + 24,
                         APFS_OBJECT_TYPE_CHECKPOINT_MAP)
        apfs_wrong_object_ok = _SpacemanOnly(_wrongobj).free_extents() == []

        for label, cond in (
                ("an APFS container superblock is identified by its own geometry",
                 bool(apfs_named) and apfs_named[0] == "apfs"),
                ("a container superblock with an impossible block size is refused",
                 apfs_refused),
                ("a file-system key splits into an object id and a record type",
                 fs_key_ok),
                ("a block's Fletcher-64 checksum is checked, and a torn one fails",
                 checksum_ok),
                ("a sealed volume's tree declares itself hashed in its btree_info",
                 bool(sealed_flag_ok)),
                ("a sealed volume's child pointer is followed relative to the "
                 "tree's root id", sealed_ok),
                ("a walker node carries a whole sixty-bit object id beside its "
                 "volume index", wide_oid_ok),
                ("the space manager is found through the current checkpoint map "
                 "and reads back as the runs of free space it describes",
                 apfs_free_ok),
                ("an APFS free-space floor drops the short runs",
                 apfs_free_floor_ok),
                ("a container whose space manager cannot be found reports "
                 "nothing rather than nothing free", apfs_no_spaceman_ok),
                ("a checkpoint mapping naming something that is not a space "
                 "manager is refused rather than read", apfs_wrong_object_ok)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        apfs_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "tests", "fixtures", "apfs-fixture.img.gz")
        apfs_want = apfs_fix[:-len(".img.gz")] + ".sha256"
        if os.path.isfile(apfs_fix) and os.path.isfile(apfs_want):
            try:
                got, want, missing, differ = _apfs_fixture_check(apfs_fix, apfs_want)
                broke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                # A reader that raises on a volume it cannot parse must fail this
                # check, not take the whole self-test down with it: a run that
                # stops early prints no FAIL line and reads as a pass.
                got = want = missing = differ = 0
                broke = f"; the walk raised {type(exc).__name__}: {exc}"
            cond = got and not missing and not differ and not broke
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] every file of the APFS "
                  f"fixture matches what an independent reader recorded "
                  f"({got} of {want}"
                  + (f", {missing} missing" if missing else "")
                  + (f", {differ} different" if differ else "") + ")" + broke)
        else:
            print("  [SKIP] the APFS fixture is not beside this script, so the "
                  "walk was not compared against it")

        # ---- HFS+ ----------------------------------------------------
        # A volume header built by hand, so identification is tested against
        # bytes this file did not read from a volume it also wrote.
        def _hfs_header(sig, block_size=4096, total=6144):
            vh = bytearray(512)
            struct.pack_into(">HH", vh, 0, sig, 4)
            struct.pack_into(">II", vh, 16, 3900000000, 3900000000)   # created, modified
            struct.pack_into(">II", vh, 32, 413, 6)                   # files, folders
            struct.pack_into(">III", vh, 40, block_size, total, 100)
            return bytes(vh)

        hfs_img = os.path.join(d, "hfs_header.img")
        open(hfs_img, "wb").write(b"\x00" * HFSP_VH_OFF + _hfs_header(HFSP_SIG)
                                  + b"\x00" * (1 << 20))
        hfsx_img = os.path.join(d, "hfsx_header.img")
        open(hfsx_img, "wb").write(b"\x00" * HFSP_VH_OFF + _hfs_header(HFSX_SIG)
                                   + b"\x00" * (1 << 20))
        hfs_bad = os.path.join(d, "hfs_bad.img")
        open(hfs_bad, "wb").write(b"\x00" * HFSP_VH_OFF
                                  + _hfs_header(HFSP_SIG, block_size=3000)
                                  + b"\x00" * 4096)
        with open(hfs_img, "rb") as hh:
            hfs_named = identify_hfsplus(hh, 0)
        with open(hfsx_img, "rb") as hh:
            hfsx_named = identify_hfsplus(hh, 0)
        with open(hfs_bad, "rb") as hh:
            hfs_refused = identify_hfsplus(hh, 0) is None

        # A fork record: a size, a clump, a block count, then eight extent
        # descriptors of which only the used ones count.
        fork = bytearray(80)
        struct.pack_into(">QII", fork, 0, 12345, 0, 4)
        struct.pack_into(">II", fork, 16, 100, 3)
        struct.pack_into(">II", fork, 24, 200, 1)
        fork_ok = _hfs_fork(bytes(fork), 0) == (12345, [(100, 3), (200, 1)])

        # A name is a count of UTF-16 units and then that many, big endian.
        name_bytes = struct.pack(">H", 3) + "abc".encode("utf-16-be")
        name_ok = _hfs_name(name_bytes, 0) == ("abc", 8)
        # A catalog name holding '/' is a POSIX name holding ':' ("a:b.txt" made at
        # the POSIX layer is stored as "a/b.txt"), and the other way round.
        slash = struct.pack(">H", 7) + "a/b:c.d".encode("utf-16-be")
        name_ok = name_ok and _hfs_name(slash, 0, posix=True) == ("a:b/c.d", 16) \
            and _hfs_name(slash, 0) == ("a/b:c.d", 16)

        # One B-tree node: a descriptor, two records, and the offset array at the
        # very end that says where they are, counted backwards.
        node = bytearray(512)
        struct.pack_into(">IIbBH", node, 0, 7, 0, HFSP_LEAF, 1, 2)
        r1 = struct.pack(">H", 4) + b"KEY1" + b"DATA-ONE"
        r2 = struct.pack(">H", 4) + b"KEY2" + b"DATA-TWO"
        node[14:14 + len(r1)] = r1
        node[14 + len(r1):14 + len(r1) + len(r2)] = r2
        struct.pack_into(">H", node, 510, 14)
        struct.pack_into(">H", node, 508, 14 + len(r1))
        struct.pack_into(">H", node, 506, 14 + len(r1) + len(r2))
        desc, recs = _HfsTree.records(bytes(node))
        node_ok = (desc == (HFSP_LEAF, 7) and len(recs) == 2
                   and recs[0] == (b"KEY1", b"DATA-ONE")
                   and recs[1] == (b"KEY2", b"DATA-TWO"))

        # HFS+ keeps an allocation file, one bit per block, and the bits run
        # MOST significant first, the opposite way round from NTFS and exFAT.
        # A count of free blocks cannot tell the two orders apart, because a
        # byte holds the same number of zero bits either way, so the fixture is
        # built with the used blocks in one statement and the runs they leave in
        # another, and the check is on the run POSITIONS.
        HFS_BLOCK = 4096
        HFS_TOTAL = 38                              # not a multiple of eight
        HFS_USED = {0, 1, 2, 9, 20, 21, 22, 23}
        # by hand from that set, over blocks 0 to 37: free runs are 3..8,
        # 10..19, 24..37
        HFS_WANT = [(3, 6), (10, 10), (24, 14)]
        _hbits = bytearray((HFS_TOTAL + 7) // 8)
        for _b in HFS_USED:
            _hbits[_b >> 3] |= 0x80 >> (_b & 7)     # most significant bit first
        _hbuf = bytearray(4 * HFS_BLOCK)
        _hvh = bytearray(512)
        struct.pack_into(">HH", _hvh, 0, HFSP_SIG, 4)
        struct.pack_into(">III", _hvh, 40, HFS_BLOCK, HFS_TOTAL, len(HFS_USED))
        struct.pack_into(">QII", _hvh, HFSP_ALLOC_FORK, len(_hbits), 0, 1)
        struct.pack_into(">II", _hvh, HFSP_ALLOC_FORK + 16, 1, 1)   # one extent, block 1
        _hbuf[HFSP_VH_OFF:HFSP_VH_OFF + 512] = _hvh
        _hbuf[HFS_BLOCK:HFS_BLOCK + len(_hbits)] = _hbits

        class _AllocOnly:
            """Only what free_extents asks of an HFS+ walker."""
            free_extents = HfsPlusWalker.free_extents    # pylint: disable=protected-access
            _read_extents = HfsPlusWalker._read_extents  # pylint: disable=protected-access
            base = 0
            block_size = HFS_BLOCK
            total_blocks = HFS_TOTAL

            def __init__(self):
                self.fh = io.BytesIO(bytes(_hbuf))

            def _overflow(self, _cnid, _resource=False):
                return []                            # the header holds the whole fork

        _hgot = _AllocOnly().free_extents()
        hfs_free_ok = _hgot == [(c * HFS_BLOCK, n * HFS_BLOCK) for c, n in HFS_WANT]
        # the same bitmap read the other way round must NOT give this answer,
        # which is what a free-block count alone can never establish
        _lsb = bytearray((HFS_TOTAL + 7) // 8)
        for _b in HFS_USED:
            _lsb[_b >> 3] |= 1 << (_b & 7)
        hfs_bit_order_ok = bytes(_lsb) != bytes(_hbits) and sum(
            bin(x).count("1") for x in _lsb) == sum(bin(x).count("1") for x in _hbits)
        hfs_free_floor_ok = (_AllocOnly().free_extents(min_bytes=11 * HFS_BLOCK)
                             == [(24 * HFS_BLOCK, 14 * HFS_BLOCK)])

        # A B-tree that is allocated but holds nothing says root 0, depth 0 in
        # its header, and node 0 is that header rather than a leaf. Every HFS+
        # volume with no extended attributes and no fragmented file has exactly
        # that shape, so this is the ordinary case: nps-2009-hfsjtest1 has it,
        # and descending into the header read its own records as index pointers
        # and raised. Two fixtures, because two separate guards stand here and
        # one fixture would let either of them look load-bearing on its own.
        class _TinyVol:
            block_size = 4096
            base = 0

            def __init__(self, buf):
                self.fh = io.BytesIO(bytes(buf))

        def _hfs_node(buf, at, kind, records):
            """One B-tree node: a descriptor, the records, and the offset array."""
            struct.pack_into(">bBH", buf, at + 8, kind, 0, len(records))
            pos, offs = 14, []
            for rec in records:
                offs.append(pos)
                buf[at + pos:at + pos + len(rec)] = rec
                pos += len(rec)
            offs.append(pos)
            for i, off in enumerate(offs):
                struct.pack_into(">H", buf, at + 4096 - 2 * (i + 1), off)

        # empty tree: header node only, root 0 and depth 0, and its first record
        # carries no four byte pointer, which is what raised on the real volume
        # the real shape, read off nps-2009-hfsjtest1: three records, the last
        # of them carrying a long key and NO data, which is the one the descent
        # tried to read a node pointer out of
        _empty = bytearray(2 * 4096)
        # the last record's key length swallows the whole record, so its data
        # is empty, exactly as the real header node's third record is
        _hfs_node(_empty, 0, HFSP_HEADER,
                  [struct.pack(">H", 0) + bytes(102),
                   struct.pack(">H", 0) + bytes(124),
                   struct.pack(">H", 200) + bytes(198)])
        struct.pack_into(">HI", _empty, 14, 0, 0)        # depth 0, root 0
        struct.pack_into(">H", _empty, 14 + 16, 4096)    # node size
        _t_empty = _HfsTree(_TinyVol(_empty), len(_empty), [(0, 1)], "attributes")

        # a tree whose root points at a map node, which is neither index nor leaf
        _mapped = bytearray(3 * 4096)
        _hfs_node(_mapped, 0, HFSP_HEADER, [b""])
        struct.pack_into(">HI", _mapped, 14, 1, 1)       # depth 1, root node 1
        struct.pack_into(">H", _mapped, 14 + 16, 4096)
        _hfs_node(_mapped, 4096, HFSP_MAP, [b"\x00\x00"])
        _t_mapped = _HfsTree(_TinyVol(_mapped), len(_mapped), [(0, 1), (1, 1)], "attributes")

        def _finds_nothing(tree):
            # key_of answers below the wanted key for every record, the way the
            # real attribute keys do for a file id that is not in the tree, so
            # the descent walks the whole record list and reaches the last one
            try:
                return tree.find(1, lambda key: 0) is None
            except Exception:                            # pylint: disable=broad-except
                return False                             # raising is the defect

        empty_tree_ok = (_t_empty.root == 0 and _t_empty.depth == 0
                         and _finds_nothing(_t_empty))
        odd_node_ok = _t_mapped.root == 1 and _finds_nothing(_t_mapped)

        for label, cond in (
                ("an HFS+ volume header is identified by its own geometry",
                 bool(hfs_named) and hfs_named[0] == "hfs+"),
                ("HFSX is recognised as the case-sensitive variant it is",
                 bool(hfsx_named) and hfsx_named[0] == "hfsx"),
                ("a volume header with an impossible block size is refused",
                 hfs_refused),
                ("a fork record yields its size and only its used extents", fork_ok),
                ("a catalog name decodes from UTF-16 big endian, with "
                 "'/' and ':' swapped as macOS shows it", name_ok),
                ("a B-tree node's records are found through its offset array",
                 node_ok),
                ("the allocation file reads back as the runs of free space it "
                 "describes, most significant bit first", hfs_free_ok),
                ("the two bit orders hold the same number of free blocks, so a "
                 "count cannot tell them apart", hfs_bit_order_ok),
                ("an HFS+ free-space floor drops the short runs",
                 hfs_free_floor_ok),
                ("a B-tree that is allocated but empty is read as holding "
                 "nothing, not descended into", empty_tree_ok),
                ("a descent that reaches a node which is neither index nor leaf "
                 "stops rather than reading it as a pointer", odd_node_ok)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        hfs_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", "hfsplus-fixture.img.gz")
        hfs_want = hfs_fix[:-len(".img.gz")] + ".sha256"
        if os.path.isfile(hfs_fix) and os.path.isfile(hfs_want):
            try:
                got, want, missing, differ = _hfs_fixture_check(hfs_fix, hfs_want)
                broke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                # A reader that raises on a volume it cannot parse must fail this
                # check, not take the whole self-test down with it: a run that
                # stops early prints no FAIL line and reads as a pass.
                got = want = missing = differ = 0
                broke = f"; the walk raised {type(exc).__name__}: {exc}"
            cond = got and not missing and not differ and not broke
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] every file of the HFS+ "
                  f"fixture matches what an independent reader recorded "
                  f"({got} of {want}"
                  + (f", {missing} missing" if missing else "")
                  + (f", {differ} different" if differ else "") + ")" + broke)
        else:
            print("  [SKIP] the HFS+ fixture is not beside this script, so the "
                  "walk was not compared against it")

        # ---- ext, APFS and HFS+ times() -------------------------------
        # Known data from debugfs (ext) and from macOS's own reading of the
        # images it wrote (APFS, HFS+), never from this reader.
        times_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
        if all(os.path.isfile(os.path.join(times_dir, n)) for n in (
                "ext-times.json", "mac-times.json", "ext4-times.img.gz",
                "ext2-times128.img.gz", "apfs-times.img.gz", "hfsplus-times.img.gz")):
            try:
                times_checks = _times_fixture_checks(times_dir)
            except Exception as exc:                 # pylint: disable=broad-except
                times_checks = [(f"the times() checks ran ({type(exc).__name__}: {exc})", False)]
            for label, cond in times_checks:
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")
        else:
            print("  [SKIP] the times fixtures are not beside this script, so times() "
                  "was not compared against them")

        # ---- NTFS ----------------------------------------------------
        # A boot sector built by hand, so identification is tested against bytes
        # this file did not read from a volume it also wrote.
        ntfs_boot = bytearray(512)
        ntfs_boot[3:11] = b"NTFS    "
        struct.pack_into("<H", ntfs_boot, 11, 512)        # bytes per sector
        ntfs_boot[13] = 8                                 # sectors per cluster
        struct.pack_into("<Q", ntfs_boot, 40, 100000)     # total sectors
        struct.pack_into("<Q", ntfs_boot, 48, 4)          # $MFT cluster
        struct.pack_into("<Q", ntfs_boot, 56, 2)          # $MFTMirr cluster
        struct.pack_into("<b", ntfs_boot, 64, -10)        # 1024-byte records
        struct.pack_into("<b", ntfs_boot, 68, -12)        # 4096-byte index blocks
        ntfs_boot[510:512] = b"\x55\xaa"
        ntfs_img = os.path.join(d, "ntfs_boot.img")
        open(ntfs_img, "wb").write(bytes(ntfs_boot) + b"\x00" * (1 << 20))
        with open(ntfs_img, "rb") as nfh:
            ntfs_named = identify_ntfs(nfh, 0)
            ntfs_declined_by_mbr = parse_mbr(nfh) is None
        bad_boot = bytearray(ntfs_boot)
        bad_boot[13] = 7                                  # not a power of two
        bad_img = os.path.join(d, "ntfs_bad.img")
        open(bad_img, "wb").write(bytes(bad_boot) + b"\x00" * 4096)
        with open(bad_img, "rb") as nfh:
            ntfs_refused = identify_ntfs(nfh, 0) is None

        # A mapping-pair list worked out by hand from the documented encoding.
        # 0x31: a one-byte length and a three-byte offset, so 8 clusters at LCN
        # 0x0C0000. 0x11: one and one, length 4 and offset 0xF8, which is -8
        # SIGNED, so the next run starts BEFORE the last one, at 786,424. Read
        # unsigned it would land at 786,680, which is the whole point of the
        # case. 0x01: a length and no offset at all, which is a sparse run.
        run_bytes = (
            "3108" + "00000c"      # 8 clusters at LCN 0x0c0000
            + "1104" + "f8"        # 4 more, offset -8, so LCN 786,424
            + "0105"               # 5 clusters with no offset at all: sparse
            + "00")                # end of list
        runs = _ntfs_runs(bytes.fromhex(run_bytes), 0, 0)
        runs_ok = runs == [(786432, 8), (786424, 4), (None, 5)]

        # A real LZNT1 chunk lifted out of a volume written by mkntfs and
        # ntfs-3g, with the plaintext it has to produce written out here rather
        # than taken from the decoder.
        lz_hex = (
            "62b10061206c696e6520740068617420726570650061747320616e642000736f"
            "20636f6d7072006573736573207765f86c6c0affab5f055f055f055f05ff5f05"
            "5f055f055f055f055f055f055f05ff5f055f055f055f055f055f055f055f05ff"
            "5f055f055f055f055f055f055f055f05ff5f05af02af02af02af02af02af02af"
            "02ffaf02af02af02af02af02af02af02af02ffaf02af02af02af02af02af02af"
            "02af02ffaf02af02af02af02af02af02af02af02ffaf02af02af02af02af02af"
            "02af02af02ffaf02af02af02af02af02af02af02af02ffaf02af02af02af02af"
            "02af02af02af02ffaf02af02af02af02af02af02af02af02ffaf02af02af02af"
            "02af02af02af02af02ffaf02af02af02af02af02af02af02af02ffaf02af02af"
            "02af02af02af02af02af02ffaf02af02af02af02af02af02af02af02ffaf02af"
            "02af02af02af02af02af02af02ffaf02af02af02af02af02af02af02af0207af"
            "02af02a402")
        lz_chunk = bytes.fromhex(lz_hex)
        lz_line = b"a line that repeats and so compresses well\n"
        lz_plain = (lz_line * (4096 // len(lz_line) + 2))[:4096]
        lz_ok = _lznt1_decompress(lz_chunk, 4096) == lz_plain
        # A unit can stop early, and what is left of it is zeros: at a header
        # of zero, at the end of the stored bytes, and after a compressed chunk
        # that inflates to fewer than 4096 bytes. The short chunk here is three
        # literals, "abc", and the real chunk after it has to land at 4096.
        lz_short = b"\x03\xb0\x00abc"
        lz_stop_ok = (
            _lznt1_decompress(lz_chunk + b"\x00\x00" + lz_chunk, 12288)
            == lz_plain + bytes(8192)
            and _lznt1_decompress(b"\x00\x00" + lz_chunk, 8192) == bytes(8192)
            and _lznt1_decompress(lz_chunk, 8192) == lz_plain + bytes(4096)
            and _lznt1_decompress(lz_short + lz_chunk, 8192)
            == b"abc" + bytes(4093) + lz_plain)
        # Bytes that are not an LZNT1 stream are refused, not read as an empty
        # unit: a chunk longer than what is stored, a stored chunk that is not
        # 4096 bytes, and a back reference with nothing behind it.
        lz_refused = 0
        for lz_bad in (lz_chunk[:-1], b"\x02\x30abc", b"\x02\xb0\x01\x00\x00"):
            try:
                _lznt1_decompress(lz_bad, 4096)
            except ValueError:
                lz_refused += 1
        lz_refuse_ok = lz_refused == 3

        # A record whose last sector was not written with the rest must be
        # refused rather than parsed with the stamp still in it.
        rec = bytearray(1024)
        rec[0:4] = b"FILE"
        struct.pack_into("<HH", rec, 4, 0x30, 3)          # usa at 0x30, two sectors
        rec[0x30:0x32] = b"\xaa\x55"                      # the stamp
        rec[0x32:0x36] = b"\x01\x02\x03\x04"             # what the sectors really hold
        rec[510:512] = b"\xaa\x55"
        rec[1022:1024] = b"\xaa\x55"
        fixed = _ntfs_fixup(bytes(rec), 512, NTFS_FILE)
        torn = bytearray(rec)
        torn[1022:1024] = b"\x00\x00"                     # one sector missed the write
        fixup_ok = (fixed is not None and fixed[510:512] == b"\x01\x02"
                    and fixed[1022:1024] == b"\x03\x04"
                    and _ntfs_fixup(bytes(torn), 512, NTFS_FILE) is None)

        # A directory index whose entry names a record that has since been freed
        # and handed out again. The reference carries the generation the entry
        # was written for, in its top 16 bits, so the two can be told apart.
        # Built by hand here, with the generation numbers written out rather
        # than taken from the code under test.
        def _idx_entry(rec, seq, name):
            nm = name.encode("utf-16-le")
            elen = 0x52 + len(nm)
            elen += (-elen) % 8
            e = bytearray(elen)
            struct.pack_into("<Q", e, 0, (seq << 48) | rec)   # the file reference
            struct.pack_into("<HHH", e, 8, elen, 0x42 + len(nm), 0)
            struct.pack_into("<Q", e, 0x10, 5)                # parent, unused here
            e[0x50] = len(name)
            e[0x51] = 1                                       # a long name, not 8.3
            e[0x52:0x52 + len(nm)] = nm
            return bytes(e)

        live = _idx_entry(70, 3, "live.txt")          # generation 3, and the record is 3
        stale = _idx_entry(71, 9, "stale.txt")        # generation 9, the record is 4
        last = bytearray(0x18)                        # the end marker carries no name
        struct.pack_into("<HHH", last, 8, 0x18, 0, 0x02)
        body = live + stale + bytes(last)
        idx = bytearray(16) + body
        struct.pack_into("<II", idx, 0, 16, 16 + len(body))

        # The index reader is exercised as it ships, on a stub that answers only
        # the one question it asks of a walker.
        class _SeqOnly:
            """Only what _index_entries asks of a walker: each record's generation."""
            _index_entries = NtfsWalker._index_entries  # pylint: disable=protected-access

            def _seq(self, num):
                return {70: 3, 71: 4}.get(num)

        found = []
        _SeqOnly()._index_entries(bytes(idx), 0, found, set())  # pylint: disable=protected-access
        stale_ok = found == [("live.txt", 70)]

        # $Bitmap read back as free runs. The bitmap is built here bit by bit and
        # the runs it must produce are written out separately as literals, so the
        # test cannot agree with the code by sharing its arithmetic. The last
        # cluster is deliberately FREE, so the run reaching the end of the volume
        # is exercised; a reader that only closes a run when it meets a used
        # cluster loses it, and a fixture ending in a used cluster never notices.
        # The bits past the volume's last cluster are left free here, which real
        # NTFS does not do, so that a reader failing to stop at the volume's end
        # runs off it and is caught.
        FREE_CLUSTER_SIZE = 4096
        FREE_TOTAL = 40                      # clusters the volume has
        FREE_USED = {0, 1, 2, 9, 20, 21, 22, 23}
        # by hand from that set: free runs are 3..8, 10..19, 24..39
        FREE_WANT_CLUSTERS = [(3, 6), (10, 10), (24, 16)]
        FREE_BASE = 1 << 20

        _bm = bytearray((FREE_TOTAL + 7) // 8 + 2)     # spare bytes, left free
        for _c in FREE_USED:
            _bm[_c >> 3] |= 1 << (_c & 7)

        class _BitmapOnly:
            """Only what free_extents asks of a walker."""
            free_extents = NtfsWalker.free_extents  # pylint: disable=protected-access
            base = FREE_BASE
            cluster = FREE_CLUSTER_SIZE
            bps = 512
            total_sectors = FREE_TOTAL * FREE_CLUSTER_SIZE // 512

            def _data_attr(self, _num):
                attr = _NtfsAttr(NTFS_DATA, "", 0, False)
                attr.data_size = len(_bm)
                return attr

            def read_file(self, _num, _size):
                yield bytes(_bm)

        _got = _BitmapOnly().free_extents()
        _want = [(FREE_BASE + c * FREE_CLUSTER_SIZE, n * FREE_CLUSTER_SIZE)
                 for c, n in FREE_WANT_CLUSTERS]
        _volume_end = FREE_BASE + FREE_TOTAL * FREE_CLUSTER_SIZE
        free_ok = (_got == _want
                   and all(at + n <= _volume_end for at, n in _got))
        # a floor drops the runs too short to hold anything worth recovering
        free_floor_ok = (_BitmapOnly().free_extents(min_bytes=11 * FREE_CLUSTER_SIZE)
                         == [(FREE_BASE + 24 * FREE_CLUSTER_SIZE, 16 * FREE_CLUSTER_SIZE)])

        # FAT32 says what is free in the file allocation table itself: an entry
        # of zero is a free cluster. A volume is built here by hand, small
        # enough that the answer can be written out rather than computed, and
        # the used clusters and the runs they leave are two separate statements
        # so the test cannot agree with the code by construction.
        FAT_BPS, FAT_SPC, FAT_RSVD, FAT_NFATS = 512, 1, 32, 1
        FAT_DATA_CLUSTERS = 40
        FAT_USED = {2, 3, 4, 11, 22, 23, 24, 25}
        # by hand from that set: free runs are 5..10, 12..21, 26..41
        FAT_WANT = [(5, 6), (12, 10), (26, 16)]
        FAT_SPF = 4                                  # 4 sectors holds 512 entries
        _fatbuf = bytearray(FAT_RSVD * FAT_BPS + FAT_NFATS * FAT_SPF * FAT_BPS
                            + FAT_DATA_CLUSTERS * FAT_SPC * FAT_BPS)
        struct.pack_into("<H", _fatbuf, 11, FAT_BPS)
        _fatbuf[13] = FAT_SPC
        struct.pack_into("<H", _fatbuf, 14, FAT_RSVD)
        _fatbuf[16] = FAT_NFATS
        struct.pack_into("<I", _fatbuf, 32,
                         FAT_RSVD + FAT_NFATS * FAT_SPF + FAT_DATA_CLUSTERS * FAT_SPC)
        struct.pack_into("<I", _fatbuf, 36, FAT_SPF)
        struct.pack_into("<I", _fatbuf, 44, 2)       # root cluster
        _fat_at = FAT_RSVD * FAT_BPS
        struct.pack_into("<I", _fatbuf, _fat_at, 0x0FFFFFF8)      # media descriptor
        struct.pack_into("<I", _fatbuf, _fat_at + 4, 0x0FFFFFFF)  # end of chain
        for _c in FAT_USED:
            struct.pack_into("<I", _fatbuf, _fat_at + _c * 4, 0x0FFFFFFF)
        # one 8.3 entry in the root, so collect() has something to carry times
        # for. The date and time words are written out here rather than built by
        # the code under test, and the reading they encode is stated separately.
        _de = _fat_at + FAT_NFATS * FAT_SPF * FAT_BPS      # cluster 2's data
        _fatbuf[_de:_de + 11] = b"HELLO   TXT"
        _fatbuf[_de + 11] = 0x20                           # an ordinary file
        struct.pack_into("<H", _fatbuf, _de + 24, (2023 - 1980) << 9 | (6 << 5) | 1)
        struct.pack_into("<H", _fatbuf, _de + 22, (12 << 11) | (30 << 5) | 15)
        struct.pack_into("<H", _fatbuf, _de + 26, 11)      # first cluster, a used one
        struct.pack_into("<I", _fatbuf, _de + 28, 512)     # size
        FAT_ENTRY_WRITTEN = "2023-06-01 12:30:30"
        # and a subdirectory holding one file, so the walk down carries the
        # readings too rather than only reporting the root's
        _fatbuf[_de + 32:_de + 43] = b"SUB        "
        _fatbuf[_de + 43] = 0x10                           # a directory
        struct.pack_into("<H", _fatbuf, _de + 32 + 26, 22) # first cluster, a used one
        _sub = _de + (22 - 2) * FAT_BPS
        _fatbuf[_sub:_sub + 11] = b"DEEP    TXT"
        _fatbuf[_sub + 11] = 0x20
        struct.pack_into("<H", _fatbuf, _sub + 24, (1999 - 1980) << 9 | (12 << 5) | 31)
        struct.pack_into("<H", _fatbuf, _sub + 22, (23 << 11) | (59 << 5) | 29)
        struct.pack_into("<H", _fatbuf, _sub + 26, 23)     # first cluster, a used one
        struct.pack_into("<I", _fatbuf, _sub + 28, 64)
        FAT_DEEP_WRITTEN = "1999-12-31 23:59:58"

        _fatw = Fat32Walker(io.BytesIO(bytes(_fatbuf)), 0)
        _fat_data = _fat_at + FAT_NFATS * FAT_SPF * FAT_BPS
        fat_free_ok = (_fatw.free_extents()
                       == [(_fat_data + (c - 2) * FAT_BPS, n * FAT_BPS)
                           for c, n in FAT_WANT])
        fat_floor_ok = (_fatw.free_extents(min_bytes=11 * FAT_BPS)
                        == [(_fat_data + 24 * FAT_BPS, 16 * FAT_BPS)])

        # Entries 0 and 1 are the media descriptor and the end-of-chain marker,
        # not clusters, and a volume whose table has been wiped holds zero in
        # both. Read as clusters they would be reported free at offsets that
        # land two clusters before the data area, which is inside the table
        # itself, so a carve would scan the allocation table as free space.
        _wiped = bytearray(_fatbuf)
        struct.pack_into("<I", _wiped, _fat_at, 0)
        struct.pack_into("<I", _wiped, _fat_at + 4, 0)
        _wiped_runs = Fat32Walker(io.BytesIO(bytes(_wiped)), 0).free_extents()
        fat_reserved_ok = bool(_wiped_runs) and all(at >= _fat_data
                                                    for at, _n in _wiped_runs)

        # exFAT does not use its FAT for this. It keeps an allocation bitmap and
        # names it with a 0x81 entry in the root directory, so the entry has to
        # be found before a bit can be read. Same shape of volume, built by hand.
        EX_BPS_SHIFT, EX_SPC_SHIFT = 9, 0            # 512 byte clusters
        # 38, not a multiple of eight, so the bitmap's last byte carries two
        # padding bits. They are zero, and a reader that trusts the bitmap's
        # length instead of the volume's cluster count reports them as two free
        # clusters sitting past the end of the heap.
        EX_CLUSTERS = 38
        EX_HEAP_SECTOR = 8
        EX_BITMAP_CLUS, EX_ROOT_CLUS = 2, 3
        EX_USED = {2, 3, 4, 11, 22, 23, 24, 25}      # bitmap, root, and files
        # by hand from that set, over clusters 2 to 39: free runs are 5..10,
        # 12..21, 26..39
        EX_WANT = [(5, 6), (12, 10), (26, 14)]
        _exbuf = bytearray((EX_HEAP_SECTOR + EX_CLUSTERS + 2) * 512)
        _exbuf[3:11] = b"EXFAT   "
        struct.pack_into("<I", _exbuf, 80, 4)        # FatOffset, sector 4
        struct.pack_into("<I", _exbuf, 88, EX_HEAP_SECTOR)
        struct.pack_into("<I", _exbuf, 92, EX_CLUSTERS)
        struct.pack_into("<I", _exbuf, 96, EX_ROOT_CLUS)
        _exbuf[108] = EX_BPS_SHIFT
        _exbuf[109] = EX_SPC_SHIFT
        _exbuf[510:512] = b"\x55\xaa"
        _ex_heap = EX_HEAP_SECTOR * 512
        _ex_root = _ex_heap + (EX_ROOT_CLUS - 2) * 512
        # A TexFAT volume carries two bitmaps and the first entry in the root can
        # be the second of them, flagged in BitmapFlags bit 0. It describes the
        # other allocation, so a reader that takes the first 0x81 it meets reads
        # the wrong one. This one points at a cluster holding all-ones.
        _exbuf[_ex_root] = 0x81
        _exbuf[_ex_root + 1] = 0x01                               # the second bitmap
        struct.pack_into("<I", _exbuf, _ex_root + 20, EX_CLUSTERS + 1)
        struct.pack_into("<Q", _exbuf, _ex_root + 24, (EX_CLUSTERS + 7) // 8)
        _ex_decoy = _ex_heap + (EX_CLUSTERS + 1 - 2) * 512
        for _b in range((EX_CLUSTERS + 7) // 8):
            _exbuf[_ex_decoy + _b] = 0xFF
        _ex_root += 32                                            # the real one next
        _exbuf[_ex_root] = 0x81                                   # allocation bitmap
        struct.pack_into("<I", _exbuf, _ex_root + 20, EX_BITMAP_CLUS)
        struct.pack_into("<Q", _exbuf, _ex_root + 24, (EX_CLUSTERS + 7) // 8)
        _ex_bits = _ex_heap + (EX_BITMAP_CLUS - 2) * 512
        for _c in EX_USED:
            _exbuf[_ex_bits + ((_c - 2) >> 3)] |= 1 << ((_c - 2) & 7)
        _exw = ExfatWalker(io.BytesIO(bytes(_exbuf)), 0)
        exfat_free_ok = (_exw.free_extents()
                         == [(_ex_heap + (c - 2) * 512, n * 512) for c, n in EX_WANT])
        # a volume whose root names no bitmap must say nothing, not say nothing is free
        _nobm = bytearray(_exbuf)
        _nobm[_ex_root] = 0x85                       # an ordinary file entry instead
        _nobm[_ex_root - 32] = 0x85                  # and the TexFAT one with it
        exfat_no_bitmap_ok = ExfatWalker(io.BytesIO(bytes(_nobm)), 0).free_extents() == []

        # A file's size is in its directory entry and its clusters are in the
        # FAT, and a volume can hold the two in disagreement. Three files in the
        # exFAT root, each recorded as four clusters less ten bytes: one whose
        # chain stops after two clusters, one whose chain is whole, and one
        # that sets NoFatChain and so has no chain at all. The whole one is the
        # control: a check that called every file short would fail on it. A
        # fourth is empty, with no first cluster, and must read as no bytes.
        _exsf = bytearray(_exbuf)
        _ex_fat = 4 * 512
        EX_FILE_BYTES = 4 * 512 - 10

        def _ex_file(at, name, first, flags, size):
            _exsf[at] = 0x85
            _exsf[at + 1] = 2                        # stream extension and one name
            _exsf[at + 4] = 0x20
            _exsf[at + 32] = 0xC0
            _exsf[at + 33] = flags
            _exsf[at + 35] = len(name)
            struct.pack_into("<Q", _exsf, at + 40, size)
            struct.pack_into("<I", _exsf, at + 52, first)
            struct.pack_into("<Q", _exsf, at + 56, size)
            _exsf[at + 64] = 0xC1
            _exsf[at + 66:at + 66 + 2 * len(name)] = name.encode("utf-16-le")

        _ex_file(_ex_root + 32, "CUT", 5, 0x01, EX_FILE_BYTES)
        _ex_file(_ex_root + 128, "WHOLE", 12, 0x01, EX_FILE_BYTES)
        _ex_file(_ex_root + 224, "RUN", 26, 0x03, EX_FILE_BYTES)
        _ex_file(_ex_root + 320, "EMPTY", 0, 0x03, 0)
        for _c, _next in ((5, 6), (6, 0xFFFFFFFF),
                          (12, 13), (13, 14), (14, 15), (15, 0xFFFFFFFF)):
            struct.pack_into("<I", _exsf, _ex_fat + _c * 4, _next)
        for _c in list(range(5, 9)) + list(range(12, 16)) + list(range(26, 30)):
            _at = _ex_heap + (_c - 2) * 512
            _exsf[_at:_at + 512] = bytes([_c]) * 512
        _exsw = ExfatWalker(io.BytesIO(bytes(_exsf)), 0)
        _exs = {n: nd for n, nd in _exsw.listdir(_exsw.root)}
        _exs_len = {n: len(b"".join(_exsw.read_file(nd, nd[1]))) for n, nd in _exs.items()}
        exfat_empty_ok = (_exsw.chain_shortfall(_exs["EMPTY"]) is None
                          and _exs_len["EMPTY"] == 0)
        exfat_chain_ok = (sorted(_exs) == ["CUT", "EMPTY", "RUN", "WHOLE"]
                          and _exsw.chain_shortfall(_exs["CUT"]) == (2, 4)
                          and _exs_len["CUT"] == 2 * 512
                          and _exsw.chain_shortfall(_exs["WHOLE"]) is None
                          and _exs_len["WHOLE"] == EX_FILE_BYTES
                          and _exsw.chain_shortfall(_exs["RUN"]) is None
                          and _exs_len["RUN"] == EX_FILE_BYTES
                          and chain_shortfall(_exsw, _exs["CUT"]) == (2, 4)
                          and chain_shortfall(object(), _exs["CUT"]) is None)
        try:
            exfat_orphan_problems = _exfat_orphan_check()
        except Exception as exc:                     # pylint: disable=broad-except
            exfat_orphan_problems = [f"the check raised {type(exc).__name__}: {exc}"]
        # FAT32 keeps the same two records apart. HELLO.TXT is one cluster and
        # its chain is one cluster; recorded as three clusters it is two short.
        _fatw = Fat32Walker(io.BytesIO(bytes(_fatbuf)), 0)
        _fat_hello = dict(_fatw.listdir(_fatw.root))["HELLO.TXT"]
        _fatcut = bytearray(_fatbuf)
        struct.pack_into("<I", _fatcut, _de + 28, 3 * 512)
        _fatcw = Fat32Walker(io.BytesIO(bytes(_fatcut)), 0)
        _fat_cut = dict(_fatcw.listdir(_fatcw.root))["HELLO.TXT"]
        fat_chain_ok = (_fatw.chain_shortfall(_fat_hello) is None
                        and _fatcw.chain_shortfall(_fat_cut) == (1, 3)
                        and len(b"".join(_fatcw.read_file(_fat_cut, 3 * 512))) == 512)

        # A qnx6 volume's free space. 512-byte blocks, 4,997 of them, so the
        # bitmap is 625 bytes: two blocks, reached through one indirect block.
        # That indirect block is stored block 0, as it is on the Ford Sync G4
        # storage volume, and the volume starts 4,096 bytes into the image so an
        # offset into the volume cannot pass for one into the image. The bytes
        # that decide the bit order are written out, not built with the shift the
        # reader uses: block 7 is the top bit of byte 0, blocks 8 and 9 the two
        # low bits of byte 1. A reader counting from the top of each byte calls
        # block 0 and blocks 14 and 15 free instead. The three bits past the last
        # block are set, as the kernel's qnx6.rst says a real bitmap has them.
        Q6_BASE, Q6_BS, Q6_BLOCKS, Q6_DATA = 4096, 512, 4997, 0x3000
        Q6_WANT = [(7, 3), (4000, 201), (4990, 7)]             # (first block, blocks)

        def _q6_image(free_blocks=211, padding_set=True, second_ptr=11, cut=None,
                      blocks=Q6_BLOCKS, bitmap_bytes=625, whole=False):
            # whole: the image holds every block, each filled with its own number
            img = bytearray(Q6_BASE + Q6_DATA + (Q6_BLOCKS if whole else 16) * Q6_BS)
            if whole:
                for blk in range(Q6_BLOCKS):
                    at = Q6_BASE + Q6_DATA + blk * Q6_BS
                    img[at:at + Q6_BS] = struct.pack("<I", blk) * (Q6_BS // 4)
            sbo = Q6_BASE + BOOTBLOCK_SIZE
            img[sbo:sbo + 4] = TRUE_MAGIC_LE
            struct.pack_into("<I", img, sbo + 48, Q6_BS)
            struct.pack_into("<II", img, sbo + 60, blocks, free_blocks)
            struct.pack_into("<Q", img, sbo + 152, bitmap_bytes)   # Bitmap root node: size,
            struct.pack_into("<16I", img, sbo + 160, 0, *([0xFFFFFFFF] * 15))
            img[sbo + 152 + 72] = 1                            # sixteen pointers, levels
            at = Q6_BASE + Q6_DATA
            img[at:at + Q6_BS] = bytes(Q6_BS)
            struct.pack_into("<128I", img, Q6_BASE + Q6_DATA, 3, second_ptr,
                             *([0xFFFFFFFF] * 126))
            bm = bytearray(b"\xff" * 625)
            bm[0], bm[1] = 0x7F, 0xFC
            for blk in list(range(4000, 4201)) + list(range(4990, 4997)):
                bm[blk >> 3] &= ~(1 << (blk & 7)) & 0xFF
            if not padding_set:
                bm[624] &= 0x1F                                # bits 4997..4999 clear
            at = Q6_BASE + Q6_DATA + 3 * Q6_BS
            img[at:at + 512] = bm[:512]
            at = Q6_BASE + Q6_DATA + 11 * Q6_BS
            img[at:at + Q6_BS] = bm[512:] + bytes(Q6_BS - 113)
            return Qnx6Walker(io.BytesIO(bytes(img[:cut])), Q6_BASE, BOOTBLOCK_SIZE)

        _q6_runs = [(Q6_BASE + Q6_DATA + b * Q6_BS, n * Q6_BS) for b, n in Q6_WANT]
        qnx6_free_ok = _q6_image().free_extents() == _q6_runs
        qnx6_floor_ok = _q6_image().free_extents(min_bytes=4 * Q6_BS) == _q6_runs[1:]
        # bits past the last block are not blocks, whatever they hold
        qnx6_padding_ok = _q6_image(padding_set=False).free_extents() == _q6_runs
        # and when the last block is the last bit of the bitmap, a run that is
        # still open there ends at it: 5,000 blocks, those three bits now blocks
        qnx6_last_bit_ok = (_q6_image(free_blocks=214, padding_set=False, blocks=5000)
                            .free_extents()
                            == _q6_runs[:2] + [(Q6_BASE + Q6_DATA + 4990 * Q6_BS, 10 * Q6_BS)])
        # a bitmap at odds with its superblock, one whose root node is too short
        # for the volume, one whose second block is not mapped, and one the image
        # ends before, each say nothing
        qnx6_refused_ok = (_q6_image(free_blocks=212).free_extents() == []
                           and _q6_image(bitmap_bytes=624).free_extents() == []
                           and _q6_image(second_ptr=0xFFFFFFFF).free_extents() == []
                           and _q6_image(cut=Q6_BASE + Q6_DATA + 11 * Q6_BS + 100)
                           .free_extents() == [])

        # --unallocated, on that volume. The map is written out here as the
        # text it must be: block 7 is 16,384 + 7 * 512 bytes into the image.
        import hashlib as _hl

        def _q6_vol(walker, kind="qnx6"):
            return dict(label="GPT part 2 store", name="p2_lba8_store", kind=kind,
                        lba=8, base=Q6_BASE, walker=walker)

        def _unalloc(folder, walker, **kw):
            out = os.path.join(d, folder)
            os.makedirs(out, exist_ok=True)
            size = walker.fh.getbuffer().nbytes if hasattr(walker, "fh") else 0
            recs = write_unallocated(getattr(walker, "fh", None), size,
                                     [_q6_vol(walker, kw.pop("kind", "qnx6"))], out,
                                     "disk.img", say=lambda *_a: None, **kw)
            return out, recs

        _ua_want = b"".join(struct.pack("<I", blk) * 128 for blk in
                            list(range(7, 10)) + list(range(4000, 4201))
                            + list(range(4990, 4997)))
        _ua_dir, _ua_recs = _unalloc("ua_whole", _q6_image(whole=True))
        _ua_stem = os.path.join(_ua_dir, "disk.img.p2_lba8_store.unallocated")
        try:
            with open(_ua_stem + ".bin", "rb") as _f:
                _ua_bin = _f.read()
            with open(_ua_stem + ".tsv", "rb") as _f:
                _ua_map = _f.read()
        except OSError:
            _ua_bin = _ua_map = b""
        unalloc_written_ok = (
            _ua_bin == _ua_want and len(_ua_want) == 108032
            and _ua_map == (b"offset_in_file\toffset_in_image\tlength\n"
                            b"0\t19968\t1536\n1536\t2064384\t102912\n"
                            b"104448\t2571264\t3584\n")
            and len(_ua_recs) == 1 and _ua_recs[0]["status"] == "written"
            and _ua_recs[0]["bytes"] == 108032 and _ua_recs[0]["runs"] == 3
            and _ua_recs[0]["sha256"] == _hl.sha256(_ua_want).hexdigest())
        # the same volume on an image that stops after sixteen blocks: the run at
        # block 7 is written, and the 208 free blocks past the end are counted
        _ua_dir2, _ua_recs2 = _unalloc("ua_cut", _q6_image())
        unalloc_cut_ok = (
            len(_ua_recs2) == 1 and _ua_recs2[0]["status"] == "written"
            and _ua_recs2[0]["bytes"] == 1536
            and _ua_recs2[0].get("past_end_of_image_bytes_not_written") == 106496
            and os.path.getsize(os.path.join(
                _ua_dir2, "disk.img.p2_lba8_store.unallocated.bin")) == 1536)
        # no file, and the reason, for: a reader with no free_extents, an empty
        # answer, a file already there, and a volume --only leaves out
        _ua_d3, _ua_r3 = _unalloc("ua_none", object(), kind="ext4")
        _ua_d4, _ua_r4 = _unalloc("ua_empty", _q6_image(free_blocks=212, whole=True))
        _ua_d5, _ua_r5 = _unalloc("ua_whole", _q6_image(whole=True, padding_set=False))
        _ua_d6, _ua_r6 = _unalloc("ua_only", _q6_image(whole=True), only="storage")
        unalloc_refused_ok = (
            "does not report free space" in _ua_r3[0]["status"] and os.listdir(_ua_d3) == []
            and "no free space reported" in _ua_r4[0]["status"] and os.listdir(_ua_d4) == []
            and "already exists" in _ua_r5[0]["status"]
            and sorted(os.listdir(_ua_d5)) == ["disk.img.p2_lba8_store.unallocated.bin",
                                               "disk.img.p2_lba8_store.unallocated.tsv"]
            and os.path.getsize(_ua_stem + ".bin") == 108032
            and _ua_r6 == [] and os.listdir(_ua_d6) == []
            and all(r["status"].startswith("not written") for r in _ua_r3 + _ua_r4 + _ua_r5))

        # The first segment of a split acquisition holds the boot sector and
        # stops. Both FAT readers follow a chain by reading four bytes per
        # cluster, and past the end of the file that read comes back short, so
        # each must answer rather than raise.
        # collect() carries the readings only when asked, and its own result is
        # unchanged either way, because four other call sites read that tuple.
        _times = {}
        _with = collect(_fatw, _fatw.root, times=_times)
        _without = collect(_fatw, _fatw.root)
        # neither entry carries a creation time or an access date, and a reading
        # the entry does not hold must be absent rather than present and empty
        collect_times_ok = (_times.get("HELLO.TXT", {}).get("modified") == FAT_ENTRY_WRITTEN
                            and _times.get("SUB/DEEP.TXT", {}).get("modified") == FAT_DEEP_WRITTEN
                            and set(_times.get("HELLO.TXT", {})) == {"modified"}
                            and _with == _without
                            and all(len(e) == 4 for e in _with)
                            and len(_with) == 2)

        # Cut each image so the read of the next FAT entry falls off the end.
        try:
            _cut_fat = Fat32Walker(io.BytesIO(bytes(_fatbuf)[:_fat_at + 8]), 0)
            _cut_ex = ExfatWalker(io.BytesIO(bytes(_exbuf)[:1024]), 0)
            fat_truncated_ok = (list(_cut_fat._chain(2)) == [2]      # pylint: disable=protected-access
                                and _cut_ex.free_extents() == []
                                and isinstance(_cut_fat.free_extents(), list))
        except Exception:                            # pylint: disable=broad-except
            fat_truncated_ok = False

        # FAT keeps a wall-clock reading and no zone. The expected strings are
        # written out here rather than built from the same packing the code
        # uses, so the test cannot agree with the decoder by construction.
        stamp_ok = (_dos_stamp((2023 - 1980) << 9 | (6 << 5) | 1, (12 << 11) | (30 << 5) | 15)
                    == "2023-06-01 12:30:30"
                    and _dos_stamp((1980 - 1980) << 9 | (1 << 5) | 1, 0) == "1980-01-01 00:00:00"
                    and _dos_stamp(0, 0) == ""
                    and _dos_stamp((2024 - 1980) << 9 | (2 << 5) | 29,
                                   (23 << 11) | (59 << 5) | 29, 199)
                    == "2024-02-29 23:59:59.99")
        stamp_date_ok = (_dos_date((2021 - 1980) << 9 | (5 << 5) | 5) == "2021-05-05"
                         and _dos_date(0) == "")
        # month 0 and day 0 are what an unwritten or damaged entry holds
        stamp_junk_ok = (_dos_stamp((2023 - 1980) << 9, 0) == ""
                         and _dos_stamp((2023 - 1980) << 9 | (13 << 5) | 1, 0) == ""
                         and _dos_date((2023 - 1980) << 9 | (1 << 5)) == "")
        # 0x80 says the field was written, the low seven bits are signed steps
        # of fifteen minutes: +4 is 16 steps, -5 is 108 as two's complement
        offset_ok = (_exfat_offset(0x80 | 16) == "+04:00"
                     and _exfat_offset(0x80 | 108) == "-05:00"
                     and _exfat_offset(0x80) == "+00:00"
                     and _exfat_offset(0x00) == ""
                     and _exfat_offset(0x10) == "")

        for label, cond in (
                ("an NTFS boot sector is identified by its own geometry",
                 bool(ntfs_named) and ntfs_named[0] == "ntfs"),
                ("an NTFS boot sector is not read as a partition table",
                 ntfs_declined_by_mbr),
                ("a boot sector naming NTFS with impossible geometry is refused",
                 ntfs_refused),
                ("a run list decodes, including a run that steps backwards and "
                 "a sparse one", runs_ok),
                ("an LZNT1 chunk inflates to the bytes it was made from", lz_ok),
                ("an LZNT1 unit that stops early is filled with zeros: at a zero "
                 "header, at the end of its stored bytes, and after a chunk that "
                 "inflates short", lz_stop_ok),
                ("bytes that are not an LZNT1 stream are refused: a chunk past the "
                 "stored bytes, a stored chunk that is not 4096 bytes, a back "
                 "reference with nothing behind it", lz_refuse_ok),
                ("a record's sector fixups are applied, and a torn one is "
                 "refused", fixup_ok),
                ("an index entry naming a record of a different generation is "
                 "not followed", stale_ok),
                ("the cluster bitmap reads back as the runs of free space it "
                 "describes", free_ok),
                ("a free-space floor drops the runs too short to be worth "
                 "carving", free_floor_ok),
                ("a FAT32 volume reads its free clusters out of the allocation "
                 "table", fat_free_ok),
                ("a FAT32 free-space floor drops the short runs", fat_floor_ok),
                ("the two reserved FAT entries are not reported as free space "
                 "inside the allocation table", fat_reserved_ok),
                ("an exFAT volume finds its allocation bitmap and reads the free "
                 "clusters out of it", exfat_free_ok),
                ("an exFAT volume whose root names no bitmap reports nothing "
                 "rather than nothing free", exfat_no_bitmap_ok),
                ("an exFAT file whose FAT chain ends before its recorded size "
                 "says so, and a whole chain or a NoFatChain run does not",
                 exfat_chain_ok),
                ("an empty exFAT file reads as no bytes, not as a cluster of the "
                 "volume's own", exfat_empty_ok),
                ("exFAT orphan entries: in-use entry sets in allocated clusters the "
                 "tree does not reach come back with their directory names and "
                 "bytes, one that names a live file's clusters, a free cluster or "
                 "a short chain is refused, and a deleted entry, a bad checksum, "
                 "the up-case table, a live file's content and a free cluster "
                 "give none" + "".join(f"; {p}" for p in exfat_orphan_problems),
                 not exfat_orphan_problems),
                ("a FAT32 file whose cluster chain ends before its recorded size "
                 "says so, and a whole chain does not", fat_chain_ok),
                ("a qnx6 volume reads its free blocks out of the bitmap tree, least "
                 "significant bit first, as offsets into the image", qnx6_free_ok),
                ("a qnx6 free-space floor drops the short runs", qnx6_floor_ok),
                ("qnx6 bitmap bits past the last block are never reported, set or "
                 "clear", qnx6_padding_ok),
                ("a qnx6 free run still open at the bitmap's last bit ends at the "
                 "last block", qnx6_last_bit_ok),
                ("a qnx6 bitmap that disagrees with its superblock, is too short, is "
                 "not mapped, or is cut off reports nothing rather than nothing free",
                 qnx6_refused_ok),
                ("--unallocated writes a volume's free runs in order, with a map back "
                 "to the image and the hash of what it wrote", unalloc_written_ok),
                ("--unallocated cuts a run at the end of a partial image and counts "
                 "what it left out", unalloc_cut_ok),
                ("--unallocated writes no file for a reader that reports no free "
                 "space, an empty answer, a file already there, or a volume --only "
                 "leaves out, and says which", unalloc_refused_ok),
                ("a FAT or exFAT volume cut short by a split acquisition answers "
                 "rather than raising", fat_truncated_ok),
                ("a FAT date and time decode to the reading they store, with no "
                 "zone put on them", stamp_ok),
                ("a FAT last-access date is given as a date, not as midnight",
                 stamp_date_ok),
                ("an impossible FAT date is reported as nothing rather than as "
                 "a wrong reading", stamp_junk_ok),
                ("an exFAT UTC offset decodes both ways from its stored steps, "
                 "and an unset one says nothing", offset_ok),
                ("collect carries the recorded readings when asked, and returns "
                 "the same tuples either way", collect_times_ok)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # ext: sparse files and the classic block map. Both fixtures were built
        # from one tree with mke2fs -d, so one hash list serves both, and it was
        # written by sha256sum over that tree, not by any reader of the image.
        ext_want = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "tests", "fixtures", "ext-sparse.sha256")
        for stem, want_kind in (("ext4-sparse", "ext4"), ("ext2-sparse", "ext2")):
            ext_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                   "tests", "fixtures", stem + ".img.gz")
            if not (os.path.isfile(ext_fix) and os.path.isfile(ext_want)):
                print(f"  [SKIP] the {stem} fixture is not beside this script, so the "
                      "walk was not compared against it")
                continue
            try:
                ekind, egot, ewant, emiss, ediff = _ext_fixture_check(ext_fix, ext_want)
                ebroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                ekind, egot, ewant, emiss, ediff = None, 0, 0, 0, 0
                ebroke = f"; the walk raised {type(exc).__name__}: {exc}"
            econd = (ekind == want_kind and egot and egot == ewant and not emiss
                     and not ediff and not ebroke)
            if not econd:
                ok = False
            print(f"  [{'PASS' if econd else 'FAIL'}] every file of the {stem} fixture, "
                  f"holes included, matches what sha256sum recorded over its source tree "
                  f"({egot} of {ewant}, identified as {ekind}"
                  + (f", {emiss} missing" if emiss else "")
                  + (f", {ediff} different" if ediff else "") + ")" + ebroke)

        # LVM2: lvm2's own tools wrote the fixtures, and lvm2's own report (lvs,
        # pvs, saved beside them as lvm-fixture.lvs.json) is the layout they are
        # checked against; the file hashes come from sha256sum over the source
        # trees (tools/make_lvm_fixtures.sh).
        # What every walker's extraction shares: safe zip member names, and
        # damage a walker recorded counted where a listing or extraction shows it.
        try:
            shared_checks = _shared_extract_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            shared_checks = [(f"the shared extraction checks ran ({type(exc).__name__}: {exc})", False)]
        for label, cond in shared_checks:
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        try:
            lvm_checks = _lvm_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks = [(f"the LVM2 checks ran ({type(exc).__name__}: {exc})", False)]
        try:
            lvm_checks += _luks_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the LUKS checks ran ({type(exc).__name__}: {exc})", False)]
        try:
            lvm_checks += _encryption_message_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the locked LUKS and BitLocker report checks ran "
                            f"({type(exc).__name__}: {exc})", False)]
        # XFS: mkfs.xfs wrote the fixtures from a source tree whose listing and
        # hashes were recorded beside them, with xfs_db's and xfs_logprint's own
        # reading of each image (tools/make_xfs_fixtures.sh).
        try:
            lvm_checks += _xfs_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the XFS checks ran ({type(exc).__name__}: {exc})", False)]
        try:
            lvm_checks += _btrfs_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the Btrfs checks ran ({type(exc).__name__}: {exc})", False)]
        try:
            lvm_checks += _refs_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the ReFS checks ran ({type(exc).__name__}: {exc})", False)]
        # decmpfs: LZVN and LZFSE streams from Apple's encoder, and APFS and HFS+
        # volumes macOS wrote and read back (tools/make_decmpfs_streams.py,
        # tools/make_decmpfs_fixture.py).
        try:
            lvm_checks += _decmpfs_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the decmpfs checks ran ({type(exc).__name__}: {exc})", False)]
        # RAID: arrays mdadm, lvm2 and the kernel wrote, read back to the bytes the
        # kernel presented while it ran them (tools/make_raid_fixtures.sh).
        try:
            lvm_checks += _raid_self_checks()
        except Exception as exc:                     # pylint: disable=broad-except
            lvm_checks += [(f"the RAID checks ran ({type(exc).__name__}: {exc})", False)]
        for label, cond in lvm_checks:
            if cond is None:
                print(f"  [SKIP] {label}")
                continue
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # GPT at 512 and 4096 bytes a sector. A 4Kn drive or a UFS LUN image
        # keeps its GPT header at byte 4096 and counts every LBA in 4096-byte
        # sectors; read as 512 it shows no partition table at all. The same
        # ext4 fixture goes into a GPT built for each size and has to be found
        # at the byte its entry names, identified, and walked with every file
        # matching what sha256sum recorded over its source tree.
        #
        # 0xCBF43926 is the check value the CRC RevEng catalogue gives for
        # CRC-32/ISO-HDLC over "123456789". It is written out so that a wrong
        # CRC shared by _gpt_test_image and read_gpt cannot pass the rest.
        crc_ok = binascii.crc32(b"123456789") == 0xCBF43926
        if not crc_ok:
            ok = False
        print(f"  [{'PASS' if crc_ok else 'FAIL'}] the GPT CRC is CRC-32/ISO-HDLC "
              "(check value 0xCBF43926)")
        gpt_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", "ext4-sparse.img.gz")
        if not (os.path.isfile(gpt_fix) and os.path.isfile(ext_want)):
            print("  [SKIP] the ext4-sparse fixture is not beside this script, so the "
                  "4096-byte-sector GPT was not built")
        else:
            import hashlib
            with gzip.open(gpt_fix, "rb") as gz:
                gvol = gz.read()
            gwant = {}
            with open(ext_want, encoding="utf-8") as lf:
                for line in lf:
                    line = line.rstrip("\n")
                    if line and not line.startswith("#"):
                        digest, path = line.split("  ", 1)
                        gwant[path] = digest
            LINUX_FS = "0fc63daf-8483-4772-8e79-3d69d8477de4"   # Linux filesystem data

            def gpt_walk(img_bytes):
                """(table, rejected, [GPT volumes], files matching the list)."""
                gfh = io.BytesIO(bytes(img_bytes))
                gtab, grej = read_gpt(gfh)
                gvols = [v for v in volumes(gfh, len(img_bytes))
                         if v["label"].startswith("GPT part")]
                matched = 0
                for v in gvols:
                    w = v.get("walker")
                    if w is None:
                        continue
                    for path, ino, sz, _mt in collect(w, w.root):
                        if sz is None or path not in gwant:
                            continue
                        h = hashlib.sha256()
                        for chunk in w.read_file(ino, sz):
                            h.update(chunk)
                        matched += h.hexdigest() == gwant[path]
                return gtab, grej, gvols, matched

            # sector size, first LBA, last LBA and the partition's byte offset,
            # written out rather than computed from the builder
            for gss, gfirst, glast, gbase in ((4096, 300, 6443, 1228800),
                                              (512, 2048, 51199, 1048576)):
                gimg = _gpt_test_image(gss, gvol, gfirst, "sparse", LINUX_FS)
                try:
                    gtab, grej, gvols, gmatch = gpt_walk(gimg)
                    gregs = partition_regions(io.BytesIO(bytes(gimg)), len(gimg))[0]
                    gcond = (gtab == [(1, "sparse", LINUX_FS, gfirst, glast)]
                             and gtab.sector_size == gss and gtab.header_lba == 1
                             and not grej and len(gvols) == 1
                             and gvols[0]["base"] == gbase
                             and gvols[0]["size"] == len(gvol)
                             and gvols[0]["kind"] == "ext4"
                             and gvols[0]["lba"] == gfirst
                             and gvols[0]["name"].startswith(f"p1_lba{gfirst}_")
                             and gmatch == len(gwant)
                             # the protective MBR record counts the same sectors
                             and gregs[0][:2] == ("MBR part 1", gss))
                    gdetail = (f"at byte {gvols[0]['base']:,}, {gmatch} of "
                               f"{len(gwant)} files match" if gvols else "no volume")
                except Exception as exc:             # pylint: disable=broad-except
                    gcond, gdetail = False, f"raised {type(exc).__name__}: {exc}"
                if not gcond:
                    ok = False
                print(f"  [{'PASS' if gcond else 'FAIL'}] a GPT of {gss}-byte sectors "
                      f"puts the ext4 fixture at LBA {gfirst}, byte {gbase:,}, and it "
                      f"walks ({gdetail})")

            g4k = _gpt_test_image(4096, gvol, 300, "sparse", LINUX_FS)
            # the fixture really needs the 4096 probe: at 512 there is no header
            at512 = _gpt_at(io.BytesIO(bytes(g4k)), 512, 1)
            n4k = len(g4k) // 4096
            back = (n4k - 1) * 4096

            def spoiled(*cuts, mbr_type=None, my_lba=None):
                """A copy of the 4096-byte image with bytes flipped at each offset,
                the protective record's type changed, or the primary's MyLBA
                rewritten with its CRC recomputed so only MyLBA is wrong."""
                bad = bytearray(g4k)
                for at in cuts:
                    bad[at] ^= 0xFF
                if mbr_type is not None:
                    bad[446 + 4] = mbr_type
                if my_lba is not None:
                    struct.pack_into("<Q", bad, 4096 + 24, my_lba)
                    struct.pack_into("<I", bad, 4096 + 16, 0)
                    struct.pack_into("<I", bad, 4096 + 16, binascii.crc32(
                        bytes(bad[4096:4096 + 92])) & 0xFFFFFFFF)
                return bad

            def refused_as(bad, want_lba, *reasons):
                """The table read from want_lba (None: no table at all), with every
                reason named among the refusals, and the fixture still at byte
                1,228,800 whenever a table is used."""
                gtab, grej, gvols, gmatch = gpt_walk(bad)
                said = " / ".join(why for _at, why in grej)
                if want_lba is None:
                    good = gtab is None and not gvols
                else:
                    good = (gtab is not None and gtab.header_lba == want_lba
                            and gtab.sector_size == 4096 and len(gvols) == 1
                            and gvols[0]["base"] == 1228800 and gmatch == len(gwant))
                return good and all(r in said for r in reasons), said

            cases = [
                ("read as 512-byte sectors the 4096 image has no header at LBA 1",
                 at512 == (None, None), ""),
            ]
            for label, bad, want_lba, reasons in (
                    ("a primary header that fails its CRC is not used, and the "
                     "backup at the last LBA is", spoiled(4096 + 40), n4k - 1,
                     ("HeaderCRC32",)),
                    ("a primary entry array that fails its CRC is not used, and the "
                     "backup is", spoiled(2 * 4096 + 60), n4k - 1,
                     ("PartitionEntryArrayCRC32",)),
                    ("a primary header whose MyLBA is not 1 is not used",
                     spoiled(my_lba=2), n4k - 1, ("MyLBA is 2",)),
                    ("with both headers spoiled there is no table",
                     spoiled(4096 + 40, back + 40), None,
                     ("HeaderCRC32",)),
                    ("without a 0xEE record in sector 0 the backup is not read, "
                     "since it may be a stale GPT", spoiled(4096 + 40, mbr_type=0x83),
                     None, ("HeaderCRC32",))):
                try:
                    good, said = refused_as(bad, want_lba, *reasons)
                except Exception as exc:             # pylint: disable=broad-except
                    good, said = False, f"raised {type(exc).__name__}: {exc}"
                cases.append((label, good, said))
            # The first segment of a split image: the primary validates, the
            # partition runs past the end of the file, and that is reported as
            # missing bytes, not as a disk with no partition table.
            try:
                g4k_cut = bytes(g4k[:2 << 20])
                cvols = [v for v in volumes(io.BytesIO(g4k_cut), len(g4k_cut))
                         if v["label"].startswith("GPT part")]
                cgood = (len(cvols) == 1 and cvols[0]["base"] == 1228800
                         and cvols[0]["missing_past_end"] == 1228800 + len(gvol) - len(g4k_cut))
                csaid = (f"{cvols[0]['missing_past_end']:,} bytes past the end"
                         if cvols else "no GPT volume")
            except Exception as exc:                 # pylint: disable=broad-except
                cgood, csaid = False, f"raised {type(exc).__name__}: {exc}"
            cases.append(("a 4096 GPT cut short still names its partition, reaching "
                          "past the end of the file", cgood, csaid))
            # A valid 4096 GPT with no used entry is still a 4096 disk. An empty
            # GptTable is falsy, so a truthiness test counted this disk in 512
            # and looked for a hybrid MBR record's volume at an eighth of its
            # offset.
            try:
                gempty = _gpt_test_image(4096, gvol, 300, "sparse", LINUX_FS, used=False)
                ghyb = bytearray(16)
                ghyb[4] = 0x83
                struct.pack_into("<II", ghyb, 8, 300, len(gvol) // 4096)
                gempty[462:478] = ghyb
                efh = io.BytesIO(bytes(gempty))
                etab = parse_gpt(efh)
                evols = [v for v in volumes(efh, len(gempty)) if v["label"] == "MBR part 2"]
                egood = (etab is not None and etab == [] and etab.sector_size == 4096
                         and disk_sector_size(efh) == 4096 and len(evols) == 1
                         and evols[0]["base"] == 1228800 and evols[0]["kind"] == "ext4"
                         and evols[0]["lba"] == 300)
                esaid = (f"the hybrid record's volume at byte {evols[0]['base']:,}, "
                         f"{evols[0]['kind']}" if evols else "no MBR volume")
            except Exception as exc:                 # pylint: disable=broad-except
                egood, esaid = False, f"raised {type(exc).__name__}: {exc}"
            cases.append(("a valid 4096 GPT with no used entry still counts the MBR in "
                          "4096-byte sectors", egood, esaid))
            for label, cond, said in cases:
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}"
                      + (f" ({said})" if said else ""))

        # F2FS detection rejects the negatives: an all-zero region, the right
        # magic with a wrong reserved inode number, and the right magic with an
        # impossible block size. Each must return None, so a chance 4-byte match
        # cannot be read as a filesystem.
        _bad = bytearray(3072)
        struct.pack_into("<I", _bad, 0, F2FS_MAGIC)
        struct.pack_into("<I", _bad, 16, 12)      # log_blocksize 4K
        struct.pack_into("<I", _bad, 20, 9)       # log_blocks_per_seg
        struct.pack_into("<I", _bad, 96, 3)       # root_ino ok
        struct.pack_into("<I", _bad, 100, 1)
        struct.pack_into("<I", _bad, 104, 2)
        _wrong_root = bytearray(_bad)
        struct.pack_into("<I", _wrong_root, 96, 99)   # root_ino must be 3
        _wrong_bs = bytearray(_bad)
        struct.pack_into("<I", _wrong_bs, 16, 20)     # log_blocksize out of range
        f2fs_neg_ok = (identify_f2fs(io.BytesIO(bytes(3072)), 0) is None
                       and identify_f2fs(io.BytesIO(bytes(_wrong_root)), 0) is None
                       and identify_f2fs(io.BytesIO(bytes(_wrong_bs)), 0) is None)
        if not f2fs_neg_ok:
            ok = False
        print(f"  [{'PASS' if f2fs_neg_ok else 'FAIL'}] F2FS detection rejects an "
              "all-zero region, a wrong reserved inode and an impossible block size")

        # F2FS: the same reader over an image f2fs-tools wrote. The source-tree
        # hashes cover the inline and in-inode files (and the symlink and the
        # multi-block directory); the nodes list covers the one file large
        # enough to reach direct and single-indirect node blocks, checked
        # against what dump.f2fs extracts (see _f2fs_fixture_check).
        f2fs_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "tests", "fixtures", "f2fs-fixture.img.gz")
        for want_name, what in (("f2fs-fixture.src.sha256",
                                 "sha256sum recorded over its source tree"),
                                ("f2fs-fixture.nodes.sha256",
                                 "dump.f2fs extracted from the image")):
            f2fs_want = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "tests", "fixtures", want_name)
            if not (os.path.isfile(f2fs_fix) and os.path.isfile(f2fs_want)):
                print(f"  [SKIP] the {want_name} F2FS fixture is not beside this "
                      "script, so the walk was not compared against it")
                continue
            try:
                fkind, fgot, fwant, fmiss, fdiff = _f2fs_fixture_check(f2fs_fix, f2fs_want)
                fbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                fkind, fgot, fwant, fmiss, fdiff = None, 0, 0, 0, 0
                fbroke = f"; the walk raised {type(exc).__name__}: {exc}"
            fcond = (fkind == "f2fs" and fgot and fgot == fwant and not fmiss
                     and not fdiff and not fbroke)
            if not fcond:
                ok = False
            print(f"  [{'PASS' if fcond else 'FAIL'}] every file in {want_name} "
                  f"matches what {what} "
                  f"({fgot} of {fwant}, identified as {fkind}"
                  + (f", {fmiss} missing" if fmiss else "")
                  + (f", {fdiff} different" if fdiff else "") + ")" + fbroke)

        # F2FS holes, against the Linux kernel driver as a third oracle. sload.f2fs
        # allocates every block, so this second image is built by mounting a fresh
        # volume with the kernel and writing sparse files (a leading hole, a middle
        # hole, a trailing hole, and one file that is all hole); the recorded hashes
        # are what the kernel read back. See tools/make_f2fs_hole_fixture.sh.
        f2fs_holes = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                  "tests", "fixtures", "f2fs-fixture-holes.img.gz")
        f2fs_holes_want = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                       "tests", "fixtures", "f2fs-fixture.holes.sha256")
        if os.path.isfile(f2fs_holes) and os.path.isfile(f2fs_holes_want):
            try:
                hkind, hgot, hwant, hmiss, hdiff = _f2fs_fixture_check(f2fs_holes, f2fs_holes_want)
                hbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                hkind, hgot, hwant, hmiss, hdiff = None, 0, 0, 0, 0
                hbroke = f"; the walk raised {type(exc).__name__}: {exc}"
            hcond = (hkind == "f2fs" and hgot and hgot == hwant and not hmiss
                     and not hdiff and not hbroke)
            if not hcond:
                ok = False
            print(f"  [{'PASS' if hcond else 'FAIL'}] every F2FS file with holes reads "
                  f"back the bytes the Linux kernel driver read from the same image "
                  f"({hgot} of {hwant}, identified as {hkind}"
                  + (f", {hmiss} missing" if hmiss else "")
                  + (f", {hdiff} different" if hdiff else "") + ")" + hbroke)
        else:
            print("  [SKIP] the F2FS holes fixture is not beside this script, so the "
                  "hole path was not compared against the kernel driver")

        # F2FS free space, first on a SIT written out by hand. Segment 0 has
        # blocks {0, 1, 2, 9, 20..23} in use and segment 1 is empty, so the free
        # runs are 3..8, 10..19 and 24..1023, the last one crossing the segment
        # boundary; those are written out here, not computed. The used bits are
        # set the way F2FS sets them (bit 0 is the most significant bit), and the
        # first copy of the SIT block is entirely in use while the version bitmap's
        # byte is 0x80, so only a reader that takes bit 0 from the top of the byte
        # reaches the second copy and the expected runs; one that reads
        # little-endian lands on the first copy and reports nothing free.
        SIT_BS, SIT_SEG = 4096, 512
        SIT_BASE, SIT_MAIN, SIT_ADDR = 1 << 20, 4096, 100
        SIT_USED = {0, 1, 2, 9, 20, 21, 22, 23}
        SIT_WANT = [(3, 6), (10, 10), (24, 1000)]
        _seg0 = bytearray(74)
        for _b in SIT_USED:
            _seg0[2 + (_b >> 3)] |= 1 << (7 - (_b & 7))
        struct.pack_into("<H", _seg0, 0, len(SIT_USED))
        _copy2 = bytes(_seg0) + bytes(74) + bytes(SIT_BS - 148)       # seg 1 all free
        _full = bytearray(74)
        _full[2:66] = b"\xff" * 64
        _copy1 = bytes(_full) * 2 + bytes(SIT_BS - 148)               # everything used
        _ck = bytearray(SIT_BS)
        struct.pack_into("<I", _ck, 132, F2FS_CP_UMOUNT)
        struct.pack_into("<I", _ck, 136, 8)                           # cp_pack_total_block_count
        struct.pack_into("<I", _ck, 156, 64)                          # sit_ver_bitmap_bytesize
        struct.pack_into("<I", _ck, 160, 64)
        _ck[192] = 0x80                                               # SIT block 0: second copy

        class _SitOnly:
            """Only what free_extents asks of an F2FS walker."""
            free_extents = F2fsWalker.free_extents
            _load_sit_journal = F2fsWalker._load_sit_journal   # pylint: disable=protected-access
            _sit_entry = F2fsWalker._sit_entry                 # pylint: disable=protected-access
            _sit_bitmap = F2fsWalker._sit_bitmap               # pylint: disable=protected-access
            _f2fs_test_bit = staticmethod(F2fsWalker._f2fs_test_bit)  # pylint: disable=protected-access
            bs, seg_blocks, base = SIT_BS, SIT_SEG, SIT_BASE
            main_blkaddr, main_segs = SIT_MAIN, 2
            sit_blkaddr, sit_segs_total = SIT_ADDR, 2          # one copy is 512 blocks
            cp_flags, cp_payload, feature = F2FS_CP_UMOUNT, 0, 0
            ckpt, start_cp, cp_total = bytes(_ck), 512, 8
            short = False

            def block(self, addr):
                if self.short:
                    return b""
                if addr == SIT_ADDR:
                    return _copy1
                if addr == SIT_ADDR + SIT_SEG:
                    return _copy2
                return bytes(SIT_BS)                              # the journal block: no entries

        _sgot = _SitOnly().free_extents()
        _swant = [(SIT_BASE + (SIT_MAIN + b) * SIT_BS, n * SIT_BS) for b, n in SIT_WANT]
        sit_free_ok = _sgot == _swant
        sit_floor_ok = (_SitOnly().free_extents(min_bytes=11 * SIT_BS)
                        == [(SIT_BASE + (SIT_MAIN + 24) * SIT_BS, 1000 * SIT_BS)])
        _cut = _SitOnly()
        _cut.short = True
        sit_cut_ok = _cut.free_extents() == []
        for label, cond in (
                ("an F2FS SIT reads back as the runs of free space it describes, "
                 "the used bits taken from the top of each byte and the current SIT "
                 "copy chosen the same way", sit_free_ok),
                ("an F2FS free-space floor drops the short runs", sit_floor_ok),
                ("an F2FS volume cut short before its SIT answers nothing rather than "
                 "raising", sit_cut_ok)):
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        # The two-session fixture (tools/make_f2fs_free_fixture.sh): the kernel
        # rewrote NAT block 0, so the checkpoint's NAT version bitmap carries a set
        # bit and which copy is current is decided by bit order for real; the 1.28
        # reader, little-endian there, finds no files on this volume at all. Every
        # file must read back as the kernel read it, the bitmap must actually have
        # a set bit (else this leg has lost its point), and all 256 blocks of the
        # file deleted before the last checkpoint must sit in reported free space
        # with their bytes intact.
        f2fs_free_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "tests", "fixtures", "f2fs-fixture-free.img.gz")
        f2fs_free_want = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                      "tests", "fixtures", "f2fs-fixture.free.sha256")
        if os.path.isfile(f2fs_free_fix) and os.path.isfile(f2fs_free_want):
            try:
                vk, vgot, vwant, vmiss, vdiff = _f2fs_fixture_check(f2fs_free_fix, f2fs_free_want)
                vbit, vfound, vfree = _f2fs_marker_check(f2fs_free_fix)
                vbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                vk, vgot, vwant, vmiss, vdiff, vbit, vfound, vfree = None, 0, 0, 0, 0, False, 0, 0
                vbroke = f"; raised {type(exc).__name__}: {exc}"
            vcond = (vk == "f2fs" and vgot and vgot == vwant and not vmiss and not vdiff
                     and vbit and vfound == 256 and vfree == 256 and not vbroke)
            if not vcond:
                ok = False
            print(f"  [{'PASS' if vcond else 'FAIL'}] on the volume the kernel wrote twice, "
                  f"whose NAT version bitmap {'carries a' if vbit else 'CARRIES NO'} set bit, "
                  f"every file reads back as the kernel read it ({vgot} of {vwant}"
                  + (f", {vmiss} missing" if vmiss else "")
                  + (f", {vdiff} different" if vdiff else "")
                  + f") and the deleted marker's blocks lie in free space ({vfree} of "
                  f"{vfound} found, 256 written)" + vbroke)
        else:
            print("  [SKIP] the two-session F2FS fixture is not beside this script, so the "
                  "NAT copy selection and the deleted-file control were not checked")

        # Then on the committed images: the checkpoint's own count, and position.
        for stem in ("f2fs-fixture", "f2fs-fixture-holes", "f2fs-fixture-free"):
            fx = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              "tests", "fixtures", stem + ".img.gz")
            if not os.path.isfile(fx):
                print(f"  [SKIP] the {stem} fixture is not beside this script, so its free "
                      "space was not checked")
                continue
            try:
                fk, ffree, fmain, fvalid, fnamed, fbad = _f2fs_free_check(fx)
                fbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                fk, ffree, fmain, fvalid, fnamed, fbad = None, 0, 0, 0, 0, 0
                fbroke = f"; raised {type(exc).__name__}: {exc}"
            fcond = (fk == "f2fs" and fmain and ffree == fmain - fvalid
                     and fnamed == fvalid and fbad == 0 and not fbroke)
            if not fcond:
                ok = False
            print(f"  [{'PASS' if fcond else 'FAIL'}] {stem}: free space plus the blocks "
                  f"live files and nodes occupy tile the main area, and none of those "
                  f"blocks is reported free ({ffree:,} free + {fnamed:,} named = "
                  f"{fmain:,}; checkpoint says {fvalid:,} valid"
                  + (f"; {fbad} live blocks in free runs" if fbad else "") + ")" + fbroke)

        ntfs_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                "tests", "fixtures", "ntfs-fixture.img.gz")
        ntfs_want = ntfs_fix[:-len(".img.gz")] + ".sha256"
        if os.path.isfile(ntfs_fix) and os.path.isfile(ntfs_want):
            try:
                got, want, missing, differ = _ntfs_fixture_check(ntfs_fix, ntfs_want)
                broke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                # A reader that raises on a volume it cannot parse must fail this
                # check, not take the whole self-test down with it: a run that
                # stops early prints no FAIL line and reads as a pass.
                got = want = missing = differ = 0
                broke = f"; the walk raised {type(exc).__name__}: {exc}"
            cond = got and not missing and not differ and not broke
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] every file of the NTFS "
                  f"fixture matches what an independent reader recorded "
                  f"({got} of {want}"
                  + (f", {missing} missing" if missing else "")
                  + (f", {differ} different" if differ else "") + ")" + broke)
        else:
            # Said plainly rather than silently: a check that did not run is not
            # a check that passed. The frozen executable carries no fixtures.
            print("  [SKIP] the NTFS fixture is not beside this script, so the "
                  "walk was not compared against it")

        ntfs_del = ntfs_fix[:-len(".img.gz")] + ".deleted.sha256"
        if os.path.isfile(ntfs_fix) and os.path.isfile(ntfs_del):
            try:
                dgot, dwant, dmiss, ddiff = _ntfs_deleted_check(ntfs_fix, ntfs_del)
                dbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                dgot = dwant = dmiss = ddiff = 0
                dbroke = f"; the sweep raised {type(exc).__name__}: {exc}"
            dcond = dgot and dgot == dwant and not dmiss and not ddiff and not dbroke
            if not dcond:
                ok = False
            print(f"  [{'PASS' if dcond else 'FAIL'}] deleted files recovered "
                  f"from the MFT match the bytes written before deletion "
                  f"({dgot} of {dwant}"
                  + (f", {dmiss} missing" if dmiss else "")
                  + (f", {ddiff} different" if ddiff else "") + ")" + dbroke)
        elif os.path.isfile(ntfs_fix):
            print("  [SKIP] the NTFS deleted-files listing is not beside this "
                  "script, so recovery was not compared against it")

        if os.path.isfile(ntfs_fix):
            try:
                tfail, tchecked = _ntfs_times_check(ntfs_fix)
            except Exception as exc:                 # pylint: disable=broad-except
                tfail, tchecked = [f"the check raised {type(exc).__name__}: {exc}"], 0
            tcond = tchecked and not tfail
            if not tcond:
                ok = False
            print(f"  [{'PASS' if tcond else 'FAIL'}] created, modified and accessed of "
                  f"live and deleted NTFS files match what istat recorded "
                  f"({tchecked} live files checked"
                  + (f"; {tfail[0]}" if tfail else "") + ")")

        # Alternate data streams, from a second NTFS fixture built for them (see
        # tools/make_ntfs_streams_fixture.sh), then the same comparison with each
        # hole rule broken in turn: a check that cannot fail proves nothing.
        ads_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", "ntfs-streams.img.gz")
        ads_want = ads_fix[:-len(".img.gz")] + ".sha256"

        def _no_front_skip(w):
            """The walker, reading a stream's front hole as zeros."""
            real = w._stream                         # pylint: disable=protected-access

            def _stream(ref):
                got = real(ref)
                if got is None or not got[1]:
                    return got
                return got[0], 0, got[2] + got[1]
            w._stream = _stream                      # pylint: disable=protected-access
            return w

        def _list_all_hole(w):
            """The walker, listing a stream that stores nothing."""
            real = w._stream                         # pylint: disable=protected-access

            def _stream(ref):
                got = real(ref)
                if got is not None:
                    return got
                data = w._data_attr(ref.record, ref.name)   # pylint: disable=protected-access
                return None if data is None else (data, 0, data.data_size)
            w._stream = _stream                      # pylint: disable=protected-access
            return w

        # A directory's $I30 index allocation, read through directory_index(): the
        # same fixture as the walk above, five of whose nine directories have
        # grown one, then the same check with the call finding none.
        idx_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", "ntfs-fixture.img.gz")

        def _no_index_allocation(w):
            """The walker, finding no $INDEX_ALLOCATION on any record."""
            w._index_allocation = lambda num: None   # pylint: disable=protected-access
            return w

        if os.path.isfile(idx_fix):
            try:
                iheld, idirs, ifail = _ntfs_directory_index_check(idx_fix)
            except Exception as exc:                 # pylint: disable=broad-except
                iheld = idirs = 0
                ifail = [f"the check raised {type(exc).__name__}: {exc}"]
            icond = iheld == 5 and idirs == 9 and not ifail
            if not icond:
                ok = False
            print(f"  [{'PASS' if icond else 'FAIL'}] directory_index() reads the $I30 index "
                  f"allocation of each NTFS fixture directory that has one as whole INDX "
                  f"blocks holding, with the index root, the entries listdir() gives, and "
                  f"streams() does not list it ({iheld} of {idirs} directories"
                  + (f"; {ifail[0]}" if ifail else "") + ")")
            try:
                bheld = _ntfs_directory_index_check(idx_fix, break_it=_no_index_allocation)[0]
            except Exception:                        # pylint: disable=broad-except
                bheld = -1
            if bheld != 0:
                ok = False
            print(f"  [{'PASS' if bheld == 0 else 'FAIL'}] control: a walker that finds no "
                  f"$INDEX_ALLOCATION gives no directory index, so the check above can "
                  f"fail ({bheld} given)")

        if os.path.isfile(ads_fix) and os.path.isfile(ads_want):
            try:
                sgot, swant, smiss, sextra, sdiff, sfail = _ntfs_streams_check(ads_fix, ads_want)
            except Exception as exc:                 # pylint: disable=broad-except
                sgot = swant = smiss = sextra = sdiff = 0
                sfail = [f"the check raised {type(exc).__name__}: {exc}"]
            scond = sgot and sgot == swant and not (smiss or sextra or sdiff or sfail)
            if not scond:
                ok = False
            print(f"  [{'PASS' if scond else 'FAIL'}] every alternate data stream of the "
                  f"NTFS stream fixture matches what icat read from its first stored "
                  f"cluster, and no stream that stores nothing is listed "
                  f"({sgot} of {swant}"
                  + (f", {smiss} missing" if smiss else "")
                  + (f", {sextra} listed that should not be" if sextra else "")
                  + (f", {sdiff} different" if sdiff else "")
                  + (f"; {sfail[0]}" if sfail else "") + ")")
            for label, broken, key in (
                    ("reads the hole at the front of a stream", _no_front_skip, 4),
                    ("lists a stream that stores nothing", _list_all_hole, 3)):
                try:
                    bad = _ntfs_streams_check(ads_fix, ads_want, break_it=broken)[key]
                except Exception:                    # pylint: disable=broad-except
                    bad = 0
                ccond = bad > 0
                if not ccond:
                    ok = False
                print(f"  [{'PASS' if ccond else 'FAIL'}] and that check fails for a "
                      f"reader that {label} ({bad} found)")
        else:
            print("  [SKIP] the NTFS stream fixture is not beside this script, so "
                  "alternate data streams were not compared against it")

        # A volume Windows itself wrote (tools/make_ntfs_windows_fixture.cmd),
        # holding what mkntfs and ntfs-3g cannot make: overlay-compressed files
        # in each algorithm, cloud placeholders written by the Cloud Files
        # filter, and sparse files whose size on disk Windows reported. Every
        # expected value is Windows's own. Then the same comparison with each
        # rule switched off, because a check that cannot fail proves nothing.
        win_fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", "ntfs-windows.img.gz")
        win_want = win_fix[:-len(".img.gz")] + ".known.tsv"

        def _no_overlay(w):
            """The walker, reading an overlay-compressed file's unnamed stream."""
            w._wof = lambda num: None                # pylint: disable=protected-access
            real = w.reparse

            def reparse(num):
                got = real(num)
                return None if got and got[0] == IO_REPARSE_TAG_WOF else got
            w.reparse = reparse
            return w

        def _no_placeholder_rule(w):
            """The walker, reading a cloud placeholder's hole as its content."""
            real = w.reparse

            def reparse(num):
                got = real(num)
                if got and got[0] & IO_REPARSE_TAG_CLOUD_MASK == IO_REPARSE_TAG_CLOUD:
                    return None
                return got
            w.reparse = reparse
            return w

        def _one_chunk_size(w):
            """The walker, taking every XPRESS file to be in 4 KiB chunks."""
            real = w._wof                            # pylint: disable=protected-access

            def _wof(num):
                got = real(num)
                if got is None or WOF_ALGORITHMS.get(got[1], ("",))[0] == "lzx":
                    return got
                return got[0], 0, got[2]
            w._wof = _wof                            # pylint: disable=protected-access
            return w

        if os.path.isfile(win_fix) and os.path.isfile(win_want):
            try:
                wc, wwrong = _ntfs_windows_check(win_fix, win_want)
            except Exception as exc:                 # pylint: disable=broad-except
                wc, wwrong = {}, [f"the check raised {type(exc).__name__}: {exc}"]
            wcond = bool(wc) and not wwrong and wc["hashed"] and wc["same"] == wc["hashed"]
            if not wcond:
                ok = False
            print(f"  [{'PASS' if wcond else 'FAIL'}] every file of the volume Windows wrote "
                  f"that Windows could hash reads to the same SHA-256: plain, resident, "
                  f"sparse, NTFS compressed, overlay-compressed with XPRESS in 4K, 8K and "
                  f"16K chunks, and a cloud file that is all there "
                  f"({wc.get('same', 0)} of {wc.get('hashed', 0)}"
                  + (f"; {wwrong[0]}" if wwrong else "") + ")")
            pcond = bool(wc) and wc["refused_by_windows"] == 3 == wc["refused_here"] \
                and wc["placeholders"] == 3
            if not pcond:
                ok = False
            print(f"  [{'PASS' if pcond else 'FAIL'}] the cloud placeholders Windows would "
                  f"not read are refused, and are the only files allocation() calls a "
                  f"placeholder ({wc.get('refused_here', 0)} of "
                  f"{wc.get('refused_by_windows', 0)} refused, "
                  f"{wc.get('placeholders', 0)} placeholders)")
            lcond = bool(wc) and wc["lzx"] == 5 == wc["lzx_refused"]
            if not lcond:
                ok = False
            print(f"  [{'PASS' if lcond else 'FAIL'}] a file overlay-compressed with LZX "
                  f"is refused by name rather than read as zeros "
                  f"({wc.get('lzx_refused', 0)} of {wc.get('lzx', 0)})")
            acond = bool(wc) and wc["sized"] >= 20 and wc["sized_same"] == wc["sized"]
            if not acond:
                ok = False
            print(f"  [{'PASS' if acond else 'FAIL'}] allocation() gives Windows's own size "
                  f"on disk for every sparse or compressed file whose content lies in "
                  f"clusters ({wc.get('sized_same', 0)} of {wc.get('sized', 0)})")
            for label, broken, expect in (
                    ("reads an overlay-compressed file's unnamed stream", _no_overlay, 15),
                    ("reads a cloud placeholder's hole as its content",
                     _no_placeholder_rule, 3),
                    ("takes every XPRESS file to be in 4 KiB chunks", _one_chunk_size, 5)):
                try:
                    bad = len(_ntfs_windows_check(win_fix, win_want, break_it=broken)[1])
                except Exception:                    # pylint: disable=broad-except
                    bad = 0
                ccond = bad >= expect
                if not ccond:
                    ok = False
                print(f"  [{'PASS' if ccond else 'FAIL'}] and that comparison fails for a "
                      f"reader that {label} ({bad} files wrong)")

            # An NTFS compression unit that stops early. The two digests are
            # written out: they are what The Sleuth Kit 4.15.0 (icat) read from
            # the same changed copies, and what the file's own bytes give with
            # the unit replaced by zeros.
            stop_second = "2178bd1ed448997552310b525dd2f83a6049978b291fe6afd0f8cb4ee2cc40b1"
            stop_first = "1d86e973f642b6762f8bf3fc24b47f366a4caef494338b4c1ff6148030171679"

            def _stops_at_zero(src, limit, real=_lznt1_decompress):
                """The decoder as it was until 1.57: a unit ends where its
                chunks do, and is returned at that length."""
                pos = chunks = 0
                while pos + 2 <= len(src):
                    header = struct.unpack_from("<H", src, pos)[0]
                    if header == 0:
                        break
                    pos += 3 + (header & 0x0FFF)
                    chunks += 1
                return real(src, limit)[:min(limit, chunks * 4096)]

            try:
                st = _ntfs_lznt1_stop_check(win_fix)
            except Exception as exc:                 # pylint: disable=broad-except
                st = {"error": f"{type(exc).__name__}: {exc}"}
            scond = (st.get("second") == (100000, stop_second)
                     and st.get("first") == (100000, stop_first))
            if not scond:
                ok = False
            print(f"  [{'PASS' if scond else 'FAIL'}] an NTFS-compressed file with a unit "
                  f"that stops at a zero chunk header reads at its full length, that "
                  f"unit as zeros and the other unit at its own offset, as The Sleuth "
                  f"Kit read the same two volumes"
                  + (f" ({st['error']})" if "error" in st else ""))
            rcond = st.get("refused") is True
            if not rcond:
                ok = False
            print(f"  [{'PASS' if rcond else 'FAIL'}] and a unit that is not an LZNT1 "
                  f"stream is refused rather than read as zeros")
            try:
                old = _ntfs_lznt1_stop_check(win_fix, decoder=_stops_at_zero)
            except Exception:                        # pylint: disable=broad-except
                old = {}
            ocond = (old.get("second", (0,))[0] == 65536
                     and old.get("first", (0,))[0] == 65536
                     and old.get("second", (0, ""))[1] != stop_second
                     and old.get("first", (0, ""))[1] != stop_first)
            if not ocond:
                ok = False
            print(f"  [{'PASS' if ocond else 'FAIL'}] and that comparison fails for a "
                  f"reader that ends the unit at the zero header: both files come "
                  f"back 65,536 bytes long")
        else:
            print("  [SKIP] the Windows-written NTFS fixture is not beside this script, so "
                  "overlay compression, cloud placeholders and allocation were not "
                  "compared against it")

        # APFS says how much of a sparse file it stores in two fields that have
        # to be read together. The committed APFS fixture holds a file whose
        # only data is 18 bytes written past a megabyte of hole, and one whose
        # content is a compressed attribute.
        apfs_alloc = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                  "tests", "fixtures", "apfs-fixture.img.gz")
        if os.path.isfile(apfs_alloc):
            try:
                with gzip.open(apfs_alloc, "rb") as gz:
                    aimg = io.BytesIO(gz.read())
                found = {}
                for v in volumes(aimg, len(aimg.getbuffer())):
                    if v["kind"] != "apfs" or not v.get("walker"):
                        continue
                    for path, node, _s, _m in collect(v["walker"], v["walker"].root):
                        found[path.rsplit("/", 1)[-1]] = allocation(v["walker"], node)
                sp, dc, sm = found.get("sparse.bin"), found.get("decmpfs.txt"), \
                    found.get("small.txt")
                apcond = bool(sp and dc and sm
                              and sp["sparse"] and sp["size"] == 1048594
                              and sp["stored"] == 4096
                              and dc["compression"] == "decmpfs" and 0 < dc["stored"] < dc["size"]
                              and not sm["sparse"] and sm["stored"] == 4096
                              and not any(a and a["placeholder"] for a in found.values()))
                adetail = (f"sparse.bin {sp and sp['stored']:,} of {sp and sp['size']:,} "
                           f"bytes stored") if sp else "sparse.bin not found"
            except Exception as exc:                 # pylint: disable=broad-except
                apcond, adetail = False, f"the check raised {type(exc).__name__}: {exc}"
            if not apcond:
                ok = False
            print(f"  [{'PASS' if apcond else 'FAIL'}] allocation() on APFS counts a sparse "
                  f"file's stored blocks and not its holes, and a compressed file's "
                  f"compressed bytes ({adetail})")
        else:
            print("  [SKIP] the APFS fixture is not beside this script, so allocation() "
                  "was not checked on APFS")

        try:
            f16 = _fat16_fixture_checks(os.path.join(
                os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures"))
        except Exception as exc:                     # pylint: disable=broad-except
            f16 = [(False, f"the FAT16 checks raised {type(exc).__name__}: {exc}")]
        if f16 is None:
            print("  [SKIP] the FAT16 and FAT12 fixtures are not beside this script, so "
                  "FAT16, TFAT16 and FAT12 were not read")
        else:
            for f16cond, f16text in f16:
                if not f16cond:
                    ok = False
                print(f"  [{'PASS' if f16cond else 'FAIL'}] {f16text}")

        for label, stem, wcls in (("FAT32", "fat32-deleted", Fat32Walker),
                                  ("FAT16", "fat16-fixture", Fat16Walker),
                                  ("TFAT16", "tfat16-fixture", Fat16Walker),
                                  ("FAT12", "fat12-fixture", Fat12Walker),
                                  ("exFAT", "exfat-deleted", ExfatWalker)):
            fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", stem + ".img.gz")
            lst = fix[:-len(".img.gz")] + ".deleted.sha256"
            if not (os.path.isfile(fix) and os.path.isfile(lst)):
                print(f"  [SKIP] the {label} deleted-files fixture is not beside this "
                      "script, so recovery was not compared against it")
                continue
            try:
                fgot, fwant, fmiss, fdiff = _fat_deleted_check(fix, lst, wcls)
                fbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                fgot = fwant = fmiss = fdiff = 0
                fbroke = f"; the sweep raised {type(exc).__name__}: {exc}"
            fcond = fgot and fgot == fwant and not fmiss and not fdiff and not fbroke
            if not fcond:
                ok = False
            print(f"  [{'PASS' if fcond else 'FAIL'}] deleted files recovered from the "
                  f"{label} directory entries match the bytes written before deletion "
                  f"({fgot} of {fwant}"
                  + (f", {fmiss} missing" if fmiss else "")
                  + (f", {fdiff} different" if fdiff else "") + ")" + fbroke)

        fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "tests", "fixtures", "exfat-deleted.img.gz")
        if os.path.isfile(fix):
            try:
                ook, odetail = _exfat_fixture_orphan_check(fix)
            except Exception as exc:                 # pylint: disable=broad-except
                ook, odetail = False, f"the check raised {type(exc).__name__}: {exc}"
            if not ook:
                ok = False
            print(f"  [{'PASS' if ook else 'FAIL'}] the exFAT fixture a driver wrote "
                  f"carries the entry set checksum this reader computes, and has no "
                  f"orphan entry ({odetail})")
        else:
            print("  [SKIP] the exFAT fixture is not beside this script, so the entry "
                  "set checksum was not held against a driver's")

        for label, stem, wcls in (("FAT32", "fat32-deleted", Fat32Walker),
                                  ("FAT16", "fat16-fixture", Fat16Walker),
                                  ("TFAT16", "tfat16-fixture", Fat16Walker),
                                  ("FAT12", "fat12-fixture", Fat12Walker),
                                  ("exFAT", "exfat-deleted", ExfatWalker)):
            fix = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "tests", "fixtures", stem + ".img.gz")
            if not os.path.isfile(fix):
                print(f"  [SKIP] the {label} fixture is not beside this script, so "
                      "its listing was not checked")
                continue
            try:
                lok, ldetail = _fat_listing_check(fix, wcls)
            except Exception as exc:                 # pylint: disable=broad-except
                lok, ldetail = False, f"the check raised {type(exc).__name__}: {exc}"
            if not lok:
                ok = False
            print(f"  [{'PASS' if lok else 'FAIL'}] a {label} listing prints each file's "
                  f"modified reading as stored and never 1970-01-01 ({ldetail})")
        if os.path.isfile(ntfs_fix):
            try:
                nok, ndetail = _ntfs_listing_check(ntfs_fix)
            except Exception as exc:                 # pylint: disable=broad-except
                nok, ndetail = False, f"the check raised {type(exc).__name__}: {exc}"
            if not nok:
                ok = False
            print(f"  [{'PASS' if nok else 'FAIL'}] an NTFS listing still prints an "
                  f"instant's date ({ndetail})")

        # volumes(): the callable form of the report's discovery. The names and
        # kinds below are written out, not read back from volume_name() or from
        # main(), so a wrong region, a wrong kind or a missing walker each fails.
        def _vol_view(path):
            with open(path, "rb") as fh:
                return [(v["kind"], v["name"], "walker" in v, v["missing_past_end"])
                        for v in volumes(fh, os.path.getsize(path))]
        vol_checks = (
            ("volumes() names the qnx6 behind an MBR by its partition and LBA",
             a, [("qnx6", "p1_lba2048", True, 0)]),
            ("volumes() names a whole-image big-endian qnx6 lba0",
             b, [("qnx6", "lba0", True, 0)]),
            ("volumes() reports an unrecognised image as one region without a walker",
             c, [("not recognised", "lba0", False, 0)]),
            ("volumes() recognises a synthetic FAT32 boot sector",
             fp, [("fat32", "lba0", True, 0)]),
            ("volumes() recognises a synthetic exFAT boot sector",
             xp, [("exfat", "lba0", True, 0)]),
        )
        for label, path, want in vol_checks:
            try:
                got = _vol_view(path)
                vbroke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                got, vbroke = None, f"; raised {type(exc).__name__}: {exc}"
            cond = got == want and not vbroke
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}"
                  + ("" if cond else f"  (got {got}{vbroke})"))
        # A region the file does not hold in full reports how much is missing:
        # the first segment of a split image has exactly this shape.
        try:
            with open(cut, "rb") as fh:
                cut_vols = volumes(fh, os.path.getsize(cut))
            cut_cond = (len(cut_vols) == 1 and cut_vols[0]["kind"] == "qnx6"
                        and cut_vols[0]["missing_past_end"] > 0)
            cut_detail = (f"{cut_vols[0]['missing_past_end']:,} bytes past the end"
                          if cut_vols else "no volume found")
        except Exception as exc:                     # pylint: disable=broad-except
            cut_cond, cut_detail = False, f"raised {type(exc).__name__}: {exc}"
        if not cut_cond:
            ok = False
        print(f"  [{'PASS' if cut_cond else 'FAIL'}] volumes() reports a volume the "
              f"image is too short for as missing bytes ({cut_detail})")

        # The Linux flash filesystems, each against oracles its reader never
        # touches: sha256sum over the tree the image was built from, that tree's
        # own stat listing (or unsquashfs -lln for SquashFS), and for the YAFFS
        # image with history, what YAFFS's own code reads back from it. Every
        # compressor each writer offers has an image; see tools/make_*.sh.
        fx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tests", "fixtures")
        sq = [(f"squashfs-{c}", "squashfs", "squashfs.src.sha256", "squashfs.lln", "lln", "", (),
               f"SquashFS {what}")
              for c, what in (("gzip", "gzip"), ("xz", "xz with an ARM BCJ filter"),
                              ("lzma", "legacy lzma"), ("lzo", "lzo"), ("lz4", "lz4 (HC)"),
                              ("zstd", "zstd"), ("none", "uncompressed"),
                              ("small", "4 KiB blocks, gzip"))]
        jf = [(f"jffs2-{c}", "jffs2", "jffs2.src.sha256", "jffs2.src.stat", "stat", "", ("dev",),
               f"JFFS2 {what}")
              for c, what in (("le-zlib", "little endian, zlib"), ("be-zlib", "big endian, zlib"),
                              ("le-lzo", "lzo"), ("le-lzma", "OpenWrt lzma"),
                              ("le-rtime", "rtime"), ("le-none", "uncompressed"),
                              ("le-sum", "with erase block summary nodes"))]
        ub = [("ubifs-lzo", "ubifs", "ubifs.src.sha256", "ubifs.src.stat", "stat", "", (),
               "UBIFS bare mkfs.ubifs image, lzo")]
        for c, what in (("nand-lzo", "NAND, lzo"), ("nand-zlib", "NAND, zlib"),
                        ("nand-zstd", "NAND, zstd"), ("nand-none", "NAND, uncompressed"),
                        ("nor", "NOR, lzo")):
            ub += [(f"ubi-{c}", "ubi", "ubifs.src.sha256", "ubifs.src.stat", "stat", "rootfs_data/",
                    (), f"UBI {what}: the UBIFS volume"),
                   (f"ubi-{c}", "ubi", "ubi.rootfs.sha256", None, "stat", "rootfs/", (),
                    f"UBI {what}: the SquashFS static volume"),
                   (f"ubi-{c}", "ubi", "ubi.kernel.sha256", None, "stat", "", (),
                    f"UBI {what}: the raw static volume")]
        ya = [(f"yaffs2-{c}", "yaffs2", "yaffs.src.sha256", "yaffs.src.stat", "stat", "", (),
               f"YAFFS2 {what}")
              for c, what in (("le", "mkyaffs2image"),
                              ("be", "mkyaffs2image convert (big-endian headers)"),
                              ("oob2", "tags at spare offset 2"))]
        ya += [("yaffs1", "yaffs1", "yaffs.src.sha256", "yaffs.src.stat", "stat", "", (),
                "YAFFS1 mkyaffsimage"),
               ("yaffs2-history", "yaffs2", "yaffs2.history.sha256", "yaffs2.history.stat", "stat",
                "", ("lost+found",),
                "YAFFS2 with history (overwrites, a shrink then a write past the old data, "
                "holes, deletion, garbage collection, a file never closed), against YAFFS's "
                "own read-back"),
               ("yaffs1-history", "yaffs1", "yaffs1.history.sha256", "yaffs1.history.stat", "stat",
                "", ("lost+found",),
                "YAFFS1 with the same history, ending in a power cut during garbage "
                "collection, against YAFFS's own read-back"),
               ("yaffs1cut-history", "yaffs1", "yaffs1cut.history.sha256",
                "yaffs1cut.history.stat", "stat", "", ("lost+found",),
                "YAFFS1 power cut in a rewrite: two live copies with different bytes that "
                "only their serial numbers order, against YAFFS's own read-back")]
        # And images the Linux kernel's own drivers wrote with history and read
        # back (tools/make_kernel_flash_fixtures.sh): JFFS2 on NOR, where the
        # kernel marks superseded nodes obsolete, JFFS2 on NAND, where it cannot
        # and only version numbers order them, and UBIFS in UBI imaged while
        # mounted, so the history since the last commit is in the journal. The
        # two NAND images were taken with nanddump --oob.
        kh = [("jffs2-nor-history", "jffs2", "jffs2-nor.history.sha256",
               "jffs2-nor.history.stat", "stat", "", (),
               "JFFS2 on NOR written with history by the Linux kernel, against the "
               "kernel's own read-back"),
              ("jffs2-nand-history", "jffs2", "jffs2-nand.history.sha256",
               "jffs2-nand.history.stat", "stat", "", (),
               "JFFS2 on NAND written with history by the Linux kernel and taken with "
               "nanddump --oob, against the kernel's own read-back"),
              ("ubi-nand-history", "ubi", "ubi-nand.history.sha256", "ubi-nand.history.stat",
               "stat", "rootfs_data/", (),
               "UBIFS written with history by the Linux kernel and taken with nanddump "
               "--oob while mounted, against the kernel's own read-back"),
              ("ubi-nand-history", "ubi", "ubi-nand.history.kernel.sha256", None, "stat", "",
               (), "a static UBI volume the kernel wrote with ubiupdatevol, from the same image")]
        # A zstd SquashFS on a Python with no zstd lists nothing, since its
        # directory tables are compressed too, and the walker answers an empty
        # listing rather than raising. volumes() has to say why beside the
        # volume, or it reads as an empty filesystem. The missing module is
        # simulated, so this runs on every Python.
        zst_img = os.path.join(fx, "squashfs-zstd.img.gz")
        if not os.path.isfile(zst_img):
            print("  [SKIP] squashfs-zstd is not beside this script, so the note a "
                  "Python without zstd gives was not checked")
        else:
            with gzip.open(zst_img, "rb") as gz:
                zst_bytes = gz.read()
            zst_globals = globals()
            zst_real = zst_globals["_zstd_module"]
            try:
                zst_globals["_zstd_module"] = lambda: None
                zst_hidden = volumes(io.BytesIO(zst_bytes), len(zst_bytes))
            finally:
                zst_globals["_zstd_module"] = zst_real
            zst_shown = volumes(io.BytesIO(zst_bytes), len(zst_bytes))
            zst_cond = (len(zst_hidden) == 1 and zst_hidden[0]["kind"] == "squashfs"
                        and zst_hidden[0].get("note") == SQUASHFS_NO_ZSTD_NOTE
                        and len(zst_shown) == 1
                        and (zst_shown[0].get("note") is None) == (zst_real() is not None))
            if not zst_cond:
                ok = False
            print(f"  [{'PASS' if zst_cond else 'FAIL'}] a zstd SquashFS on a Python "
                  f"without zstd carries a note saying why it lists nothing, and none "
                  f"where zstd is present")
        for stem, want_kind, hashes, listing, style, prefix, loose, label in sq + jf + ub + ya + kh:
            img = os.path.join(fx, stem + ".img.gz")
            if not (os.path.isfile(img) and os.path.isfile(os.path.join(fx, hashes))):
                print(f"  [SKIP] {stem} is not beside this script, so {label} was not checked")
                continue
            if (stem.endswith("zstd") and _zstd_module() is None
                    and (not stem.startswith("ubi-") or prefix == "rootfs_data/")):
                print(f"  [SKIP] {label}: this Python has no zstd (3.14 adds compression.zstd)")
                continue
            # Names the reader lists that the source tree cannot: device nodes
            # mkfs.jffs2 made from its device table, and the lost+found YAFFS
            # lists on every volume.
            allow = (("dev/null", "dev/sda") if stem.startswith("jffs2-le-") or stem == "jffs2-be-zlib"
                     else ("lost+found",) if stem in ("yaffs1", "yaffs2-le", "yaffs2-be", "yaffs2-oob2")
                     else ())
            try:
                r = _flash_fixture_check(img, os.path.join(fx, hashes),
                                         os.path.join(fx, listing) if listing else None,
                                         style, prefix, loose, allow_extra=allow)
                broke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                r = dict(kind=None, files=[0, 0, 0, 0], entries=[0, 0, []], extra=[])
                broke = f"; raised {type(exc).__name__}: {exc}"
            (got, want, miss, diff), (eok, ewant, ebad) = r["files"], r["entries"]
            cond = (r["kind"] == want_kind and want and got == want and eok == ewant
                    and not r["extra"] and not broke)
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}: {got} of {want} files match "
                  f"{hashes}" + (f", {eok} of {ewant} entries agree with {listing}"
                                 if listing else "")
                  + f" (identified as {r['kind']}"
                  + (f", {miss} missing" if miss else "") + (f", {diff} different" if diff else "")
                  + ")" + ("; " + "; ".join(ebad) if ebad else "")
                  + (f"; listed but not in {listing}: " + ", ".join(r["extra"][:3])
                     if r["extra"] else "") + broke)

        # A JFFS2 LZMA node must decode to exactly the size it records: a stream
        # cut short, or a node claiming one byte more or one byte less than its
        # stream holds, is refused rather than read as a different file. The node is the first
        # LZMA node OpenWrt's mkfs.jffs2 wrote into the fixture.
        lz_fx = os.path.join(fx, "jffs2-le-lzma.img.gz")
        if os.path.isfile(lz_fx):
            with gzip.open(lz_fx, "rb") as gz:
                lz_raw = gz.read()
            lz_node, lz_i = None, 0
            while lz_node is None and lz_i + 68 <= len(lz_raw):
                lz_magic, lz_ntype, lz_tlen = struct.unpack_from("<HHI", lz_raw, lz_i)
                if lz_magic != 0x1985 or lz_tlen < 12:
                    lz_i += 4
                    continue
                if lz_ntype == 0xE002 and lz_raw[lz_i + 56] == 8:
                    lz_csize, lz_dsize = struct.unpack_from("<II", lz_raw, lz_i + 48)
                    lz_node = (lz_raw[lz_i + 68:lz_i + 68 + lz_csize], lz_dsize)
                lz_i += (lz_tlen + 3) & ~3

            def _refused(src, lz_dsize):
                try:
                    jffs2_decompress(8, src, lz_dsize)
                except DecompressError:
                    return True
                return False
            cond = (lz_node is not None and len(jffs2_decompress(8, *lz_node)) == lz_node[1]
                    and _refused(lz_node[0][:len(lz_node[0]) // 2], lz_node[1])
                    and _refused(lz_node[0], lz_node[1] + 1)
                    and _refused(lz_node[0], lz_node[1] - 1))
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] a JFFS2 LZMA node decodes to exactly the "
                  "size it records, and one cut short or claiming a byte more or less is refused")

        def _sha_match(walker, hashes, prefix=""):
            """{path: None if it matches, else what went wrong} for every file
            in a sha256sum list, read through `walker`."""
            import hashlib
            got = {p_: (n_, sz_) for p_, n_, _m, sz_, _t, _r in walk_all(walker)}
            ub_res = {}
            with open(hashes, encoding="utf-8") as hf:
                for line in hf:
                    if not line.strip():
                        continue
                    digest, path = line.rstrip("\n").split("  ", 1)
                    g = got.get(prefix + path)
                    if g is None:
                        ub_res[path] = "not listed"
                        continue
                    try:
                        h = hashlib.sha256(b"".join(walker.read_file(*g))).hexdigest()
                        ub_res[path] = None if h == digest else "different bytes"
                    except Exception as exc:         # pylint: disable=broad-except
                        ub_res[path] = str(exc)
            return ub_res

        # A raw NAND dump holds bits before the controller's ECC corrected them,
        # so a node can fail its CRC by one flipped bit. Flipped here in the bare
        # UBIFS fixture: one bit in a data node, one in the root index node, one
        # in another data node's stored CRC, and one in each master node (read
        # by scanning its LEB, the path the journal replay also takes). Each
        # must read with the bit restored. A data node with two bits flipped
        # must be refused with that reason, never read with a wrong bit "fixed",
        # and one whose place reads as erased flash refused as erased.
        ub_fx = os.path.join(fx, "ubifs-lzo.img.gz")
        if os.path.isfile(ub_fx) and os.path.isfile(os.path.join(fx, "ubifs.src.sha256")):
            with gzip.open(ub_fx, "rb") as gz:
                ub_img = bytearray(gz.read())
            ub_w0 = UbifsWalker(io.BytesIO(bytes(ub_img)), 0)
            ub_lsz = ub_w0.leb_size
            ub_by_size = sorted((lz_i for lz_i, ub_d in ub_w0.data.items() if 0 in ub_d),
                             key=lambda lz_i: -len(ub_w0.data[lz_i]))
            ub_a, ub_b, ub_c, ub_d = (ub_w0.data[lz_i][0] for lz_i in ub_by_size[:4])
            ub_root = ub_w0.master["root"]
            # mkfs.ubifs writes each master node at the start of LEB 1 and LEB 2
            ub_masters = [(ub_ln, 0) for ub_ln in (1, 2)
                          if struct.unpack_from("<I", ub_img, ub_ln * ub_lsz)[0] == UBIFS_MAGIC
                          and ub_img[ub_ln * ub_lsz + 20] == UBIFS_MST_NODE]
            ub_mid_a, ub_mid_c = 48 + (ub_a[2] - 48) // 2, 48 + (ub_c[2] - 48) // 2   # inside the data
            ub_flips = [(ub_a[0], ub_a[1], ub_mid_a, 0x04), (ub_root[0], ub_root[1], 40, 0x10),
                     (ub_b[0], ub_b[1], 5, 0x01), (ub_c[0], ub_c[1], ub_mid_c, 0x01),
                     (ub_c[0], ub_c[1], ub_mid_c + 1, 0x80)]
            ub_flips += [(ub_ln, ub_o, 60, 0x02) for ub_ln, ub_o in ub_masters]
            for ub_ln, ub_o, ub_at, ub_x in ub_flips:
                ub_img[ub_ln * ub_lsz + ub_o + ub_at] ^= ub_x
            ub_img[ub_d[0] * ub_lsz + ub_d[1]:ub_d[0] * ub_lsz + ub_d[1] + 4] = b"\xff" * 4
            try:
                ub_w1 = UbifsWalker(io.BytesIO(bytes(ub_img)), 0)
                ub_res = _sha_match(ub_w1, os.path.join(fx, "ubifs.src.sha256"))
                ub_paths = {n_: p_ for p_, n_, *_x in walk_all(ub_w1)}
                ub_path_c, ub_path_d = ub_paths.get(ub_by_size[2]), ub_paths.get(ub_by_size[3])
                ub_bad = {p_: why for p_, why in ub_res.items() if why}
                ub_repaired = ub_w1.bit_repairs
                ub_broke = ""
            except Exception as exc:                 # pylint: disable=broad-except
                ub_res, ub_bad, ub_repaired, ub_broke = {}, {}, set(), f"; raised {exc}"
                ub_path_c = ub_path_d = None
            ub_want_rep = {(ub_a[0], ub_a[1]), (ub_root[0], ub_root[1]), (ub_b[0], ub_b[1]), ub_masters[0]}
            cond = (len(ub_masters) == 2 and ub_res and None not in (ub_path_c, ub_path_d)
                    and set(ub_bad) == {ub_path_c, ub_path_d}
                    and "more than one flipped bit" in ub_bad.get(ub_path_c, "")
                    and "is erased flash" in ub_bad.get(ub_path_d, "")
                    and ub_repaired == ub_want_rep and not ub_broke)
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] UBIFS nodes one flipped bit off their CRC "
                  f"(data, index, stored CRC, master) read with the bit restored: "
                  f"{len(ub_res) - len(ub_bad)} of {len(ub_res)} files match, {len(ub_repaired)} nodes "
                  f"repaired of {len(ub_want_rep)} expected; the node with two bits flipped is "
                  f"refused ({ub_bad.get(ub_path_c, 'NOT REFUSED')}), and the erased one "
                  f"({ub_bad.get(ub_path_d, 'NOT REFUSED')})" + ub_broke)

        # A file whose read fails partway must not reach the zip. zipfile cannot
        # take a member back once it is written, and until 1.53 a file on a volume
        # not expected to be short was streamed straight in, so an error after the
        # first block left a member holding only the bytes read so far under the
        # file's real name. Here many_blocks.txt's block 1 is erased in the UBIFS
        # fixture and the image is extracted the way --extract does it: that file
        # must be absent, under its own name or any other, and counted as failed,
        # and the zip must hold every other file, matching the source hashes, and
        # the manifest, and nothing else.
        pe_fx = os.path.join(fx, "ubifs-lzo.img.gz")
        pe_src = os.path.join(fx, "ubifs.src.sha256")
        if os.path.isfile(pe_fx) and os.path.isfile(pe_src):
            import hashlib as _hl_pe          # pylint: disable=import-outside-toplevel
            with gzip.open(pe_fx, "rb") as gz:
                pe_img = bytearray(gz.read())
            pe_w0 = UbifsWalker(io.BytesIO(bytes(pe_img)), 0)
            pe_target = "dir/many_blocks.txt"
            pe_ino = next((n_ for p_, n_, *_x in walk_all(pe_w0) if p_ == pe_target), None)
            pe_blocks = pe_w0.data.get(pe_ino, {})
            pe_detail = ""
            pe_cond = pe_ino is not None and len(pe_blocks) >= 3 and 1 in pe_blocks
            if pe_cond:
                pe_ln, pe_of = pe_blocks[1][0], pe_blocks[1][1]
                pe_at = pe_ln * pe_w0.leb_size + pe_of
                pe_img[pe_at:pe_at + 4] = b"\xff" * 4
                # Both files are removed again: CI keeps the *.img files this
                # function leaves behind as fixtures for the executables, and
                # counts them.
                pe_path = os.path.join(d, "ubifs_block1_erased.img")
                pe_zip = os.path.join(d, "ubifs_block1_erased.zip")
                pe_man = []
                pe_buf = io.StringIO()
                pe_want = {}
                pe_leaked, pe_ok, pe_bad = [], 0, 0
                try:
                    with open(pe_path, "wb") as pe_fh:
                        pe_fh.write(bytes(pe_img))
                    with zipfile.ZipFile(pe_zip, "w") as zf, contextlib.redirect_stdout(pe_buf):
                        main(pe_path, extract=pe_zip, zf=zf, manifest=pe_man)
                    with open(pe_src, encoding="utf-8") as pe_hf:
                        for pe_line in pe_hf:
                            if pe_line.strip():
                                pe_dg, pe_p = pe_line.rstrip("\n").split("  ", 1)
                                pe_want[pe_p] = pe_dg
                    with zipfile.ZipFile(pe_zip) as pe_zr:
                        pe_members = {i_.filename: i_ for i_ in pe_zr.infolist()}
                        # anything but the other files and the manifest: the damaged
                        # file under its own name, a marker, or a stray
                        pe_leaked = sorted(set(pe_members) - {"volumes.json"}
                                           - {f"lba0/{p_}" for p_ in pe_want if p_ != pe_target})
                        for pe_p, pe_dg in pe_want.items():
                            if pe_p == pe_target:
                                continue
                            pe_i = pe_members.get(f"lba0/{pe_p}")
                            if (pe_i is not None and
                                    _hl_pe.sha256(pe_zr.read(pe_i)).hexdigest() == pe_dg):
                                pe_ok += 1
                            else:
                                pe_bad += 1
                finally:
                    for pe_rm in (pe_path, pe_zip):
                        if os.path.exists(pe_rm):
                            os.remove(pe_rm)
                pe_entry = pe_man[0] if pe_man else {}
                pe_cond = (not pe_leaked and pe_bad == 0 and pe_ok == len(pe_want) - 1
                           and pe_entry.get("failed") == 1
                           and f"could not extract lba0/{pe_target}" in pe_buf.getvalue()
                           and "is erased flash" in pe_buf.getvalue())
                pe_detail = (f"{pe_ok} of {len(pe_want) - 1} other files match their source hash, "
                             f"{pe_entry.get('failed')} failed, other members: "
                             f"{pe_leaked or 'none'}")
            else:
                pe_detail = f"{pe_target} not found with a block 1 in the fixture"
            if not pe_cond:
                ok = False
            print(f"  [{'PASS' if pe_cond else 'FAIL'}] a file whose read fails partway is left "
                  f"out of the zip, not stored with the bytes read so far ({pe_detail})")

        # CRC32_ONE_BIT_MAX rests on the shortest weight-3 codeword of CRC-32
        # (x^a + x^b + 1 divisible by 0x104C11DB7): found here, not assumed.
        cw_pow, cw_seen, cw_len = 1, {1: 0}, None
        for cw_i in range(1, 100_000):
            cw_pow <<= 1
            if cw_pow >> 32:
                cw_pow ^= 0x104C11DB7
            cw_a = cw_seen.get(cw_pow ^ 1)
            if cw_a:
                cw_len = cw_i + 1
                break
            cw_seen.setdefault(cw_pow, cw_i)
        cond = cw_len == 91640 and CRC32_ONE_BIT_MAX * 8 + 32 < cw_len
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] the shortest weight-3 CRC-32 codeword is "
              f"{cw_len} bits, so a one-bit repair of up to {CRC32_ONE_BIT_MAX:,} bytes cannot "
              "mistake two flipped bits for one")

        # UBI checks a copy's data CRC only against another copy of the same LEB;
        # a LEB whose one copy on the flash is marked as a copy with a bad data
        # CRC is still attached. Here that is the UBIFS superblock's LEB, so the
        # volume opens only if it is.
        un_fx = os.path.join(fx, "ubi-nor.img.gz")
        if os.path.isfile(un_fx) and os.path.isfile(os.path.join(fx, "ubifs.src.sha256")):
            with gzip.open(un_fx, "rb") as gz:
                ub_img = bytearray(gz.read())
            un_u0 = UbiWalker(io.BytesIO(bytes(ub_img)), 0, len(ub_img))
            un_vol0 = next(v for v in un_u0.ubi.volumes if v["name"] == "rootfs_data")
            un_peb = un_u0.ubi.map[(un_vol0["id"], 0)]["peb"]
            ub_at = un_peb * un_u0.ubi.peb + un_u0.ubi.vid_off
            un_hdr = bytearray(ub_img[ub_at:ub_at + 64])
            un_hdr[6] = 1                                    # copy_flag
            struct.pack_into(">I", un_hdr, 20, 4096)         # data_size
            struct.pack_into(">I", un_hdr, 32, _ubi_crc(bytes(4096)) ^ 1)   # a data CRC that fails
            struct.pack_into(">I", un_hdr, 60, _ubi_crc(bytes(un_hdr[:60])))
            ub_img[ub_at:ub_at + 64] = un_hdr
            un_u1 = UbiWalker(io.BytesIO(bytes(ub_img)), 0, len(ub_img))
            ub_res = _sha_match(un_u1, os.path.join(fx, "ubifs.src.sha256"), "rootfs_data/")
            un_lone = un_u1.ubi.stats["copy with a bad data CRC, the only copy, used"]
            cond = bool(ub_res) and not any(ub_res.values()) and un_lone == 1
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] a UBI LEB whose only copy is marked as a "
                  f"copy with a bad data CRC is still read, as the kernel attaches it: "
                  f"{sum(1 for v in ub_res.values() if v is None)} of {len(ub_res)} files match "
                  f"({un_lone} such LEB counted)")

        # Two JFFS2 partitions side by side in a dump with no partition table:
        # both number their inodes from 2, so read as one filesystem a name from
        # one shows the other's file of the same number. mkfs.jffs2's image
        # (padded to one 64 KiB erase block, as a partition is) then the
        # kernel-written NOR image. Read as one region, some files must come out
        # wrong (the fixture reaches the defect); split, each piece must match
        # its own list, both for a dump opening with the first filesystem
        # (raw_flash_layout) and for one behind a block of zeros (flash_regions).
        # The erased blocks between the two hold no node, so the boundary may
        # fall anywhere from the end of the first image to the second's first
        # block that holds one.
        js_a, js_b, js_n = (os.path.join(fx, f"{n}.img.gz")
                            for n in ("jffs2-le-zlib", "jffs2-nor-history", "jffs2-nand-history"))
        js_ha, js_hb, js_hn = (os.path.join(fx, n) for n in ("jffs2.src.sha256", "jffs2-nor.history.sha256",
                                                             "jffs2-nand.history.sha256"))
        if all(os.path.isfile(f) for f in (js_a, js_b, js_n, js_ha, js_hb, js_hn)):
            with gzip.open(js_a, "rb") as gz:
                js_first = gz.read()
            with gzip.open(js_b, "rb") as gz:
                js_second = gz.read()
            js_first += b"\xff" * (-len(js_first) % 65536)
            js_bw = Jffs2Walker(io.BytesIO(js_second), 0, len(js_second))
            js_first_node = min([n["off"] for ns in js_bw.inodes.values() for n in ns]
                                + [o for o, *_r in js_bw.dirent_nodes]
                                + [o for o, *_r in js_bw.obsolete])
            js_first_node -= js_first_node % 65536
            js_merged = _sha_match(walker_for("jffs2", io.BytesIO(js_first + js_second), 0,
                                              len(js_first) + len(js_second)), js_ha)
            js_wrong = sum(1 for v in js_merged.values() if v)
            # The NAND leg: mkfs.jffs2's image laid out as a raw NAND dump
            # (2048-byte pages, 64 spare bytes, 64 pages an erase block), then the
            # kernel-written NAND dump, whose offsets map back through the spare.
            with gzip.open(js_n, "rb") as gz:
                js_nand = gz.read()
            js_pg, js_sp = 2048, 64
            with gzip.open(js_a, "rb") as gz:
                js_a2 = gz.read()
            js_a2 += b"\xff" * (-len(js_a2) % (64 * js_pg))
            js_first_nand = b"".join(js_a2[i:i + js_pg] + b"\xff" * js_sp
                                     for i in range(0, len(js_a2), js_pg))
            js_nw = Jffs2Walker(io.BytesIO(js_nand), 0, len(js_nand))
            js_nfirst = min(n["off"] for ns in js_nw.inodes.values() for n in ns)
            js_nfirst = (js_nfirst // js_pg) * (js_pg + js_sp)
            js_results = []
            for js_lead, js_one, js_two, js_limit, hashes in (
                    (b"", js_first, js_second, js_first_node, (js_ha, js_hb)),
                    (bytes(65536), js_first, js_second, js_first_node, (js_ha, js_hb)),
                    (b"", js_first_nand, js_nand, js_nfirst, (js_ha, js_hn))):
                js_img = js_lead + js_one + js_two
                js_fh = io.BytesIO(js_img)
                js_layout = raw_flash_layout(js_fh, len(js_img))
                js_bases = [b for _l, b, _s in js_layout]
                js_lo = len(js_lead) + len(js_one)
                js_ok = (len(js_bases) == 2 and js_bases[0] == len(js_lead)
                         and js_lo <= js_bases[1] <= js_lo + js_limit)
                if js_ok:
                    for (_l, b, s), hl in zip(js_layout, hashes):
                        res = _sha_match(walker_for("jffs2", js_fh, b, s), hl)
                        js_ok = js_ok and bool(res) and not any(res.values())
                js_results.append((js_ok, js_bases))
            cond = js_wrong > 0 and all(r[0] for r in js_results)
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] two JFFS2 partitions side by side are read "
                  f"as two filesystems, each matching its own list (read as one, {js_wrong} "
                  f"files come out wrong); split at "
                  + " and ".join(str(r[1]) for r in js_results))

        # Where conflicts alone allow more than one cut, the links decide. Three
        # 4 KiB erase blocks written here from the node layouts cited above:
        # block 0 holds root names a (inode 2) and c (inode 5) and inode 2's
        # data, block 1 inode 5's data and nothing that conflicts with either
        # side, block 2 another filesystem's root name b (inode 2, version 1)
        # and its own inode 2. Only the link from c to inode 5 puts block 1 with
        # block 0; cut after block 0 instead, c would lose its content.
        def _jn(ntype, body):
            head = struct.pack("<HHI", JFFS2_MAGIC, ntype, 12 + len(body))
            node = head + struct.pack("<I", _kcrc32(head)) + body
            return node + b"\xff" * (-len(node) % 4)

        def _jdirent(pino, version, ino, name):
            b = struct.pack("<IIIIBBH", pino, version, ino, 0, len(name), 8, 0)
            head = struct.pack("<HHI", JFFS2_MAGIC, JFFS2_DIRENT, 40 + len(name))
            head += struct.pack("<I", _kcrc32(head))
            return _jn(JFFS2_DIRENT, b + struct.pack("<II", _kcrc32(head + b), _kcrc32(name))
                       + name)

        def _jinode(ino, version, data, mode=S_IFREG | 0o644, hole=0, isize=None):
            dsize, compr = (hole, 1) if hole else (len(data), 0)     # 1: JFFS2_COMPR_ZERO
            b = struct.pack("<IIIHHIIIIIIIBBH", ino, version, mode, 0, 0,
                            dsize if isize is None else isize, 0, 0, 0, 0, len(data), dsize,
                            compr, 0, 0)
            head = struct.pack("<HHI", JFFS2_MAGIC, JFFS2_INODE, 68 + len(data))
            head += struct.pack("<I", _kcrc32(head))
            return _jn(JFFS2_INODE, b + struct.pack("<II", _kcrc32(data), _kcrc32(head + b))
                       + data)

        def _jblock(*nodes):
            blk = _jn(JFFS2_CLEANMARKER, b"") + b"".join(nodes)
            return blk + b"\xff" * (4096 - len(blk))
        jl_img = (_jblock(_jdirent(1, 1, 2, b"a"), _jinode(2, 1, b"one"), _jdirent(1, 2, 5, b"c"))
                  + _jblock(_jinode(5, 1, b"five"))
                  + _jblock(_jdirent(1, 1, 2, b"b"), _jinode(2, 1, b"two")))
        jl_fh = io.BytesIO(jl_img)
        jl_layout = raw_flash_layout(jl_fh, len(jl_img))
        jl_read = []
        for _l, b, s in jl_layout:
            jw = walker_for("jffs2", jl_fh, b, s)
            jl_read.append({p: b"".join(jw.read_file(n, sz)) for p, n, _m, sz, _t, _r
                            in walk_all(jw)})
        cond = ([b for _l, b, _s in jl_layout] == [0, 8192]
                and jl_read == [{"a": b"one", "c": b"five"}, {"b": b"two"}])
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] where conflicts allow more than one cut, the "
              f"one that keeps names with their inodes is taken: pieces at "
              f"{[b for _l, b, _s in jl_layout]}, holding {[sorted(r) for r in jl_read]}")

        # A node the kernel marked obsolete still belongs to the filesystem that
        # wrote it. Block 1 holds only an orphan inode (no name links it) and an
        # obsolete node that conflicts with block 2's, so only that node puts
        # block 1 with block 0.
        def _obsolete(node):
            return node[:2] + struct.pack("<H", JFFS2_INODE & ~JFFS2_ACCURATE) + node[4:]
        jo_img = (_jblock(_jdirent(1, 1, 2, b"a"), _jinode(2, 1, b"one"))
                  + _jblock(_obsolete(_jinode(2, 5, b"old")), _jinode(7, 1, b"orphan"))
                  + _jblock(_jdirent(1, 1, 2, b"b"), _jinode(2, 5, b"two")))
        jo_layout = raw_flash_layout(io.BytesIO(jo_img), len(jo_img))
        cond = [b for _l, b, _s in jo_layout] == [0, 8192]
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] an obsolete node keeps its block with the "
              f"filesystem that wrote it: pieces at {[b for _l, b, _s in jo_layout]}")

        # And one filesystem is never cut: garbage collection rewrites a partly
        # obsoleted hole with its own version and range but the mode bits of the
        # moment (gc.c:1030-1098), so after a chmod two nodes share a version and
        # differ in permission bits only.
        jh_img = (_jblock(_jdirent(1, 1, 2, b"a"),
                          _jinode(2, 1, b"", S_IFREG | 0o644, hole=8192),
                          _jinode(2, 2, b"tail", S_IFREG | 0o644, isize=8192))
                  + _jblock(_jinode(2, 1, b"", S_IFREG | 0o600, hole=8192, isize=8192),
                            _jinode(2, 3, b"", S_IFREG | 0o600, isize=8192)))
        jh_layout = raw_flash_layout(io.BytesIO(jh_img), len(jh_img))
        cond = jh_layout == []
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] a filesystem whose rewritten hole differs "
              f"from its first copy only in permission bits is left whole "
              f"({len(jh_layout) or 1} piece(s))")

        # YAFFS writes wherever garbage collection freed a block, so a real
        # partition can open on blocks holding only data chunks, or only
        # erased pages (the DFRWS 2011 Case 2 /cache partition: first object
        # header at page 3,968). The history image with such blocks moved to
        # its start holds the same filesystem, as YAFFS's own core reads it,
        # and must still be found and read.
        hist = os.path.join(fx, "yaffs2-history.img.gz")
        if os.path.isfile(hist):
            for first, what in (((1, 23, 25, 27, 28), "five blocks of data chunks and no header"),
                                ((8, 9, 10, 14, 15, 17, 19), "seven erased blocks")):
                r = _flash_fixture_check(hist, os.path.join(fx, "yaffs2.history.sha256"),
                                         os.path.join(fx, "yaffs2.history.stat"), "stat", "",
                                         ("lost+found",), front=(64 * 2112, first))
                (got, want, miss, diff), (eok, ewant, ebad) = r["files"], r["entries"]
                cond = (r["kind"] == "yaffs2" and want and got == want and eok == ewant
                        and not r["extra"])
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] YAFFS2 history image opening on {what}: "
                      f"{got} of {want} files match, {eok} of {ewant} entries agree "
                      f"(identified as {r['kind']})")

        # Deleted files, held against what each fixture's writer put in them.
        # tools/yaffs_history.c fills a file with numbered lines (text()); the
        # kernel history in tools/make_kernel_flash_fixtures.sh with a repeated
        # line, and each churn file with one block of random.Random(2026).
        import hashlib as _hl
        import random as _rnd

        def _ytext(n, tag):
            out, seed = bytearray(), 0
            while len(out) < n:
                out += f"{tag} line {seed:06d} of the yaffs history fixture\n".encode()
                seed += 1
            return bytes(out[:n])

        def _ktext(n, tag):
            line = (tag + " kernel history line\n").encode()
            return (line * (n // len(line) + 1))[:n]

        def _kchurn(n):
            r = _rnd.Random(2026)
            return {_hl.sha256(r.randbytes(4096) * 64).hexdigest() for _ in range(n)}

        kwant = {"gone.txt": _ktext(3000, "deleted"),
                 "target.txt": b"the file that gets replaced\n"}
        # The NAND image holds nothing partly erased; the other three each
        # hold at least one file whose pages were only partly erased.
        for stem, want, churn_name, churn, label, must_refuse in (
                ("yaffs2-history", {"deleted.txt": _ytext(30000, "deleted")},
                 lambda n: n.startswith("churn_"),
                 {_hl.sha256(_ytext(600000, "churn")).hexdigest()}, "YAFFS2", True),
                ("jffs2-nor-history", kwant, lambda n: n in ("churn.bin", ""), _kchurn(32),
                 "JFFS2 on NOR (freed nodes marked obsolete)", True),
                ("jffs2-nand-history", kwant, lambda n: n in ("churn.bin", ""), _kchurn(32),
                 "JFFS2 on NAND", False),
                ("ubi-nand-history", kwant, lambda n: n in ("churn.bin", ""), _kchurn(24),
                 "UBIFS in UBI", True)):
            img = os.path.join(fx, stem + ".img.gz")
            if not os.path.isfile(img):
                print(f"  [SKIP] {stem} is not beside this script, so {label} deleted-file "
                      f"recovery was not checked")
                continue
            problems, found, n_refused = _flash_deleted_check(img, want, churn_name, churn)
            cond = not problems and found >= len(want) and (n_refused or not must_refuse)
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] {label}: deleted files recovered with the "
                  f"bytes the writer gave them ({', '.join(sorted(want))}; {found} recovered, "
                  f"{n_refused} refused as partly erased)"
                  + ("; " + "; ".join(problems[:4]) if problems else "")
                  + ("" if n_refused or not must_refuse
                     else "; nothing was refused, so the refusal is untested"))

        # The kernel-written images are only worth having while they carry the
        # history they exist to test: superseded JFFS2 nodes marked obsolete on
        # NOR and left valid on NAND (more directory entry nodes than linked
        # names, none obsolete), a UBIFS journal with nodes to replay, and in
        # UBI the two older copies of the static volume's blocks.
        khist = [os.path.join(fx, f"{n}-history.img.gz") for n in ("jffs2-nor", "jffs2-nand", "ubi-nand")]
        if all(os.path.isfile(f) for f in khist):
            import gzip as _gz, io as _io
            kw = []
            for f, kind in zip(khist, ("jffs2", "jffs2", "ubi")):
                kimg = _io.BytesIO(_gz.open(f, "rb").read())
                kw.append(walker_for(kind, kimg, 0, len(kimg.getvalue())))
            nor_s, nand_w, ubi_w = kw[0].stats, kw[1], kw[2]
            nand_live = sum(1 for ents in nand_w.dirents.values() for v in ents.values() if v[1])
            ubifs = [w for _v, _vw, w, k in ubi_w.inner if k == "ubifs"]
            replayed = ubifs[0].stats["journal nodes replayed"] if ubifs else 0
            older = ubi_w.ubi.stats["an older copy of a block, not the one read"]
            hcond = (nor_s["obsolete"] > 0 and nand_w.nand == (2048, 64)
                     and nand_w.stats["obsolete"] == 0 and nand_w.stats["dirent"] > nand_live
                     and ubi_w.nand == (2048, 64) and replayed > 0 and older == 2)
            if not hcond:
                ok = False
            print(f"  [{'PASS' if hcond else 'FAIL'}] the kernel-written images carry history: "
                  f"JFFS2 on NOR has {nor_s['obsolete']} nodes marked obsolete, JFFS2 on NAND "
                  f"{nand_w.stats['dirent']} directory entry nodes for {nand_live} linked names "
                  f"with {nand_w.stats['obsolete']} obsolete, UBIFS {replayed} journal nodes "
                  f"to replay, and UBI {older} older copies of the static volume's blocks; both "
                  f"NAND dumps read as {nand_w.nand} and {ubi_w.nand} pages with the spare "
                  f"stripped")

        # JFFS2 device nodes come from a devtable, so the devtable is their
        # oracle: a character and a block device, with its permissions.
        jdev = os.path.join(fx, "jffs2-le-zlib.img.gz")
        if os.path.isfile(jdev):
            import gzip as _gz, io as _io
            dimg = _io.BytesIO(_gz.open(jdev, "rb").read())
            dw = walker_for("jffs2", dimg, 0, len(dimg.getvalue()))
            dnodes = dict(dw.listdir(dict(dw.listdir(dw.root))["dev"]))
            dmodes = {n: dw.entry(i)[0] for n, i in dnodes.items()}
            # collect() must count the block device as a special file, not
            # walk into it: its format bits share S_IFDIR's bit.
            dspecial = sorted(p for p, _i, sz, _m in collect(dw, dw.root)
                              if sz is None and p.startswith("dev/"))
            dcond = (dmodes == {"null": 0o020666, "sda": 0o060660}
                     and dspecial == ["dev/null", "dev/sda"])
            if not dcond:
                ok = False
            print(f"  [{'PASS' if dcond else 'FAIL'}] JFFS2 device nodes carry the type and "
                  f"permissions the devtable gave them (null a character device 0666, sda a "
                  f"block device 0660; got "
                  + ", ".join(f"{n} {m:o}" for n, m in sorted(dmodes.items()))
                  + f"), and collect() reports both as special files, not directories "
                  f"({', '.join(dspecial) or 'none'})")

        # A time the filesystem does not record is reported as none, never as
        # 1970-01-01: UBI keeps no time for a volume, and YAFFS makes its root and
        # lost+found at mount time when the flash holds no header for them.
        uraw, yraw = os.path.join(fx, "ubi-nand-lzo.img.gz"), os.path.join(fx, "yaffs2-le.img.gz")
        if os.path.isfile(uraw) and os.path.isfile(yraw):
            import contextlib as _ctx, gzip as _gz, io as _io
            uimg = _io.BytesIO(_gz.open(uraw, "rb").read())
            uw = walker_for("ubi", uimg, 0, len(uimg.getvalue()))
            k_mtime = uw.entry(dict(uw.listdir(uw.root))["kernel"])[2]
            yimg = _io.BytesIO(_gz.open(yraw, "rb").read())
            yw = walker_for("yaffs2", yimg, 0, len(yimg.getvalue()))
            lf_mtime = yw.entry(dict(yw.listdir(yw.root))["lost+found"])[2]
            shown = _io.StringIO()
            with _ctx.redirect_stdout(shown):
                print_tree(uw, uw.root, 1, 1, [50])
                print_tree(yw, yw.root, 1, 1, [50])
            kline = [ln for ln in shown.getvalue().splitlines() if " kernel " in ln]
            tcond = (k_mtime is None and lf_mtime is None and len(kline) == 1
                     and "1970" not in shown.getvalue()
                     and _zip_time(None) == (1980, 1, 1, 0, 0, 0))
            if not tcond:
                ok = False
            print(f"  [{'PASS' if tcond else 'FAIL'}] a raw UBI volume and YAFFS's lost+found, "
                  f"which record no time, report none (got {k_mtime!r} and {lf_mtime!r}), and "
                  f"the listing shows no date for them: "
                  f"{kline[0].strip() if kline else 'no kernel line'!r}")

        # A raw flash dump has no partition table and a bootloader at offset 0,
        # so its filesystems are found by their own headers (flash_regions). A
        # NOR dump is built here from two fixtures: 1.25 MiB of bytes no
        # filesystem claims, then the SquashFS image and the JFFS2 image each
        # at a 64 KiB boundary, then erased flash. volumes() must find exactly
        # those two, at those offsets, and read them. The control: the same
        # images with the SquashFS at offset 0, where it is recognised as the
        # whole image, must not be split, because discovery runs only when
        # nothing is recognised there.
        sqf, jff = os.path.join(fx, "squashfs-gzip.img.gz"), os.path.join(fx, "jffs2-le-zlib.img.gz")
        if os.path.isfile(sqf) and os.path.isfile(jff):
            import gzip as _gz, io as _io, random as _rnd
            sq_raw, jf_raw = _gz.open(sqf, "rb").read(), _gz.open(jff, "rb").read()
            padto = lambda b, a: b + b"\xff" * (-len(b) % a)
            lead = _rnd.Random(7).randbytes(0x140000)
            nor = lead + padto(sq_raw, 65536) + padto(jf_raw, 65536)
            nor += b"\xff" * ((4 << 20) - len(nor))
            want_at = {0x140000: "squashfs", 0x140000 + len(padto(sq_raw, 65536)): "jffs2"}
            vols = volumes(_io.BytesIO(nor), len(nor))
            got_at = {v["base"]: v["kind"] for v in vols}
            files_read = sum(1 for v in vols if v.get("walker")
                             for _e in collect(v["walker"], v["walker"].root))
            fcond = got_at == want_at and files_read == 612 + 3 + 310 + 3
            if not fcond:
                ok = False
            print(f"  [{'PASS' if fcond else 'FAIL'}] a raw NOR dump with no partition table "
                  f"has its SquashFS and JFFS2 found by their own headers at "
                  + ", ".join(f"{k} {b:#x}" for b, k in sorted(got_at.items()))
                  + f" ({files_read} entries collected)")
            whole = padto(sq_raw, 65536) + padto(jf_raw, 65536)
            wv = volumes(_io.BytesIO(whole), len(whole))
            wcond = [(v["label"], v["kind"]) for v in wv] == [("whole image", "squashfs")]
            if not wcond:
                ok = False
            print(f"  [{'PASS' if wcond else 'FAIL'}] and an image recognised at offset 0 is "
                  f"not searched for more ("
                  + ", ".join(f"{v['label']} {v['kind']}" for v in wv) + ")")

        # A flash chip carries configuration stores beside its filesystems: the
        # U-Boot environment and, on Belkin WeMo devices, a libnvram store. Built
        # here from made-up strings: random bytes, a single-copy environment
        # (8 KiB) at 0x10000, a redundant-layout one (4 KiB, flags byte 3) at
        # 0x14000, the JFFS2 fixture at 0x20000, a 32 KiB NVRM store straight
        # after it, then erased flash. volumes() must find the four, end the
        # JFFS2 where the store begins, read the JFFS2 whole, and hand back each
        # store's bytes exactly. The controls: one flipped data byte in a store,
        # a store whose strings never end, and a CRC over the wrong length each
        # leave the store unclaimed; an environment that is the whole file is
        # recognised as the whole image, and one that only begins a larger file
        # is not, so that file's other regions are still searched.
        if os.path.isfile(jff):
            import binascii as _ba, io as _io, random as _rnd, gzip as _gz
            jf_raw = _gz.open(jff, "rb").read()
            padto = lambda b, a: b + b"\xff" * (-len(b) % a)

            def _env(strings, size, hdr=4, flags=1, ended=True):
                data = b"\x00".join(strings) + (b"\x00\x00" if ended else b"\x00")
                data = data.ljust(size - hdr, b"\x00" if ended else b"x")
                return (struct.pack("<I", _ba.crc32(data))
                        + (bytes([flags]) if hdr == 5 else b"") + data)

            def _nvrm(strings, size):
                body = b"".join(s + b"\x00" for s in strings)
                data = (body + b"\x00").ljust(size - NVRM_HEADER, b"\xff")
                return (NVRM_MAGIC + struct.pack("<III", _ba.crc32(data), len(strings),
                                                 NVRM_HEADER + len(body)) + data)

            e1 = _env([b"bootdelay=1", b"baudrate=57600", b"ethaddr=00:11:22:33:44:55"], 0x2000)
            e2 = _env([b"example_addr=192.0.2.1", b"example_mode=test"], 0x1000, hdr=5, flags=3)
            nv = _nvrm([b"example_name=Test Plug", b"example_id=000TEST000",
                        b"example_zone=1.0"], 0x8000)
            jpad = padto(jf_raw, 65536)
            nor = bytearray(_rnd.Random(11).randbytes(0x20000))
            nor[0x10000:0x10000 + len(e1)] = e1
            nor[0x14000:0x14000 + len(e2)] = e2
            nor += jpad + nv
            nor += b"\xff" * ((2 << 20) - len(nor))
            nv_at = 0x20000 + len(jpad)
            want = [(0x10000, "uboot-env", len(e1)), (0x14000, "uboot-env", len(e2)),
                    (0x20000, "jffs2", len(jpad)), (nv_at, "nvram", len(nv))]
            vols = volumes(_io.BytesIO(bytes(nor)), len(nor))
            got = [(v["base"], v["kind"], v["size"]) for v in vols]
            reads = {}
            for v in vols:
                w = v.get("walker")
                if v["kind"] in CFG_KINDS and w:
                    [(fname, node)] = w.listdir(w.root)
                    reads[v["base"]] = (fname, b"".join(w.read_file(node, w.entry(node)[1])))
            jentries = sum(1 for v in vols if v["kind"] == "jffs2" and v.get("walker")
                           for _e in collect(v["walker"], v["walker"].root))
            ccond = (got == want and jentries == 310 + 3
                     and reads == {0x10000: ("uboot-env.bin", e1), 0x14000: ("uboot-env.bin", e2),
                                   nv_at: ("nvram.bin", nv)}
                     and uboot_env_store(_io.BytesIO(e2), 0, len(e2)) == (len(e2), 5, 3))
            if not ccond:
                ok = False
            print(f"  [{'PASS' if ccond else 'FAIL'}] a flash dump's U-Boot environments and "
                  f"libnvram store are found by their CRC-32, one of each layout, and each "
                  f"read back byte for byte; the JFFS2 before the store ends where it begins "
                  f"({', '.join(f'{k} {b:#x} {human(n)}' for b, k, n in got)}; "
                  f"{jentries} JFFS2 entries)")

            flipped = bytearray(nor)
            flipped[0x10000 + 40] ^= 1                  # a data byte of the first environment
            flipped[nv_at + NVRM_HEADER + 3] ^= 1        # a data byte of the store
            unended = bytearray(nor)
            unended[0x14000:0x14000 + len(e2)] = _env([b"example_addr=192.0.2.1"], 0x1000,
                                                       hdr=5, ended=False)
            short = bytearray(nor)                       # a CRC over less than the store
            sd = bytes(e1[4:0x1000])
            short[0x10000:0x10004] = struct.pack("<I", _ba.crc32(sd[:0x800]))
            kinds = lambda img: [(v["base"], v["kind"]) for v in volumes(_io.BytesIO(bytes(img)),
                                                                        len(img))]
            nk = [kinds(flipped), kinds(unended), kinds(short)]
            ncond = (not any(b == 0x10000 for b, _k in nk[0])
                     and not any(k == "nvram" for _b, k in nk[0])
                     and not any(b == 0x14000 for b, _k in nk[1])
                     and not any(b == 0x10000 for b, _k in nk[2]))
            if not ncond:
                ok = False
            print(f"  [{'PASS' if ncond else 'FAIL'}] and a store with one flipped data byte, "
                  f"one whose strings never end, or one whose CRC covers a shorter length is "
                  f"not claimed")

            alone = kinds(e1)
            leading = bytearray(e1) + _rnd.Random(12).randbytes(0x8000)
            leading[0x6000:0x6000 + len(e2)] = e2
            lead_kinds = kinds(leading)
            wcond = (alone == [(0, "uboot-env")]
                     and lead_kinds == [(0, "uboot-env"), (0x6000, "uboot-env")]
                     and [v["label"] for v in volumes(_io.BytesIO(bytes(leading)), len(leading))]
                     == ["flash @0x0 uboot-env", "flash @0x6000 uboot-env"])
            if not wcond:
                ok = False
            print(f"  [{'PASS' if wcond else 'FAIL'}] and an environment that is the whole file "
                  f"is that file ({alone}), while one that only begins a larger file leaves "
                  f"the rest to be searched ({lead_kinds})")

        # An eMMC image from an embedded device can hold ext filesystems with no
        # partition table in front of them. Built here: 1.25 MiB of random bytes,
        # then the ext4 fixture and the ext2 fixture at 4 KiB boundaries, then a
        # whole copy of the ext4 fixture whose superblock names block group 1, as
        # a backup copy does. The random bytes carry two more decoys: 64 random
        # 4 KiB blocks with the ext magic set, and the ext4 fixture's first 4 KiB
        # (an intact superblock) with nothing readable behind it. volumes() must
        # find exactly the two filesystems, at those offsets, and read their
        # files; no decoy may be claimed. The backup copy is what fails if the
        # block group check is removed, the lone superblock if the root check is.
        e4f, e2f = (os.path.join(fx, n) for n in ("ext4-sparse.img.gz", "ext2-sparse.img.gz"))
        if os.path.isfile(e4f) and os.path.isfile(e2f):
            import gzip as _gz, io as _io, random as _rnd
            e4, e2 = _gz.open(e4f, "rb").read(), _gz.open(e2f, "rb").read()
            rnd = _rnd.Random(11)
            lead = bytearray(rnd.randbytes(0x140000))
            m = EXT_SB_OFF + EXT_F["magic"]
            for blk in range(0x40000, 0x80000, 0x1000):        # random, with the magic
                lead[blk + m:blk + m + 2] = b"\x53\xef"
            lead[0x100000:0x101000] = e4[:0x1000]               # a superblock and no more
            lead[0x101000:0x140000] = bytes(0x3F000)
            backup = bytearray(e4)
            backup[EXT_SB_OFF + 0x5A:EXT_SB_OFF + 0x5C] = (1).to_bytes(2, "little")
            e4_at = len(lead)
            e2_at = e4_at + len(e4) + 0x3000
            mmc = (bytes(lead) + e4 + b"\x00" * 0x3000 + e2 + b"\x00" * 0x1000
                   + bytes(backup) + b"\x00" * 0x100000)
            want_at = {e4_at: "ext4", e2_at: "ext2"}
            vols = volumes(_io.BytesIO(mmc), len(mmc))
            got_at = {v["base"]: v["kind"] for v in vols}
            want_n = sum(len(collect(w, w.root)) for w in (ExtWalker(_io.BytesIO(e4), 0),
                                                            ExtWalker(_io.BytesIO(e2), 0)))
            got_n = sum(1 for v in vols if v.get("walker")
                        for _e in collect(v["walker"], v["walker"].root))
            mcond = got_at == want_at and got_n == want_n and want_n > 0
            if not mcond:
                ok = False
            print(f"  [{'PASS' if mcond else 'FAIL'}] an eMMC image with no partition table has "
                  f"its ext filesystems found by their superblocks at "
                  + ", ".join(f"{k} {b:#x}" for b, k in sorted(got_at.items()))
                  + f" ({got_n} of {want_n} files collected), and a backup superblock is "
                  "not taken for one")

        # A chip-off NAND dump keeps each page's spare (OOB) bytes after it. UBI
        # and JFFS2 lay data across pages, so they are read with the spare
        # stripped (NandDataView). Two such dumps are built here from the
        # fixtures, each 2048-byte page followed by 64 spare bytes holding a
        # bad-block marker and bytes standing in for ECC, and every file must
        # read back; the geometry is not given, the readers find it.
        ubf = os.path.join(fx, "ubi-nand-lzo.img.gz")
        if os.path.isfile(ubf) and os.path.isfile(jff):
            import gzip as _gz, io as _io, random as _rnd, hashlib as _hl
            r = _rnd.Random(11)

            def _with_oob(data, page=2048, spare=64):
                out = bytearray()
                for at in range(0, len(data), page):
                    pg = data[at:at + page].ljust(page, b"\xff")
                    out += pg + b"\xff\xff" + (r.randbytes(spare - 2) if pg.strip(b"\xff")
                                                 else b"\xff" * (spare - 2))
                return bytes(out)

            for label, raw, prefix, lst in (
                    ("UBI", _gz.open(ubf, "rb").read(), "rootfs_data/", "ubifs.src.sha256"),
                    ("JFFS2", padto(_gz.open(jff, "rb").read(), 65536), "", "jffs2.src.sha256")):
                dump = _with_oob(raw)
                vols = volumes(_io.BytesIO(dump), len(dump))
                w = vols[0].get("walker") if len(vols) == 1 else None
                want = {}
                with open(os.path.join(fx, lst), encoding="utf-8") as fh_:
                    for line in fh_:
                        digest, pth = line.rstrip("\n").split("  ", 1)
                        want[prefix + pth] = digest
                got = {pth: (i, sz) for pth, i, sz, _m in (collect(w, w.root) if w else [])
                       if sz is not None}
                okn = sum(1 for pth, digest in want.items() if pth in got and _hl.sha256(
                    b"".join(w.read_file(*got[pth]))).hexdigest() == digest)
                geo = getattr(w, "nand", None)
                ocond = okn == len(want) and geo == (2048, 64)
                if not ocond:
                    ok = False
                print(f"  [{'PASS' if ocond else 'FAIL'}] {label} in a raw NAND dump with its "
                      f"spare bytes: geometry found as {geo}, {okn} of {len(want)} files match")

        # The controls. Two bits of one byte of one file's stored bytes are
        # flipped in each family's uncompressed image, and exactly that file must
        # come back different: a content check that has never reported a
        # difference says nothing. Two bits, because a UBIFS node one bit off
        # its CRC is read with the bit restored. (In UBIFS the node's CRC catches
        # it and the file is refused;
        # in JFFS2 the node is dropped as the kernel drops it, and a file whose
        # only node that was is no longer listed; YAFFS keeps no data CRC, so
        # the bytes differ.)
        for stem, hashes, prefix, label in (
                ("squashfs-none", "squashfs.src.sha256", "", "SquashFS"),
                ("jffs2-le-none", "jffs2.src.sha256", "", "JFFS2"),
                ("ubi-nand-none", "ubifs.src.sha256", "rootfs_data/", "UBIFS in UBI"),
                ("yaffs2-le", "yaffs.src.sha256", "", "YAFFS2")):
            img = os.path.join(fx, stem + ".img.gz")
            if not os.path.isfile(img):
                continue
            try:
                r = _flash_fixture_check(img, os.path.join(fx, hashes), prefix=prefix,
                                         corrupt=(b"deep file\n", 0x21))
                got, want, miss, diff = r["files"]
            except Exception:                        # pylint: disable=broad-except
                got, want, miss, diff = 0, 0, 0, 0
            ccond = miss + diff == 1 and got == want - 1
            if not ccond:
                ok = False
            print(f"  [{'PASS' if ccond else 'FAIL'}] and the {label} check reports the one "
                  f"file whose stored bytes were altered ({diff} different, {miss} no longer "
                  f"listed, {got} of {want} still matching)")

        # walk_all() takes a faster route on the walkers that offer one. It has
        # to report exactly what a walk of the directory tree reports, so every
        # committed fixture is walked both ways and every field compared.
        here = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "tests", "fixtures")
        checked, all_rows, all_wrong, fast_seen = 0, 0, 0, []
        for stem in ("ntfs-fixture", "ntfs-streams", "ntfs-windows", "apfs-fixture",
                     "hfsplus-fixture",
                     "ext4-sparse", "ext2-sparse", "fat32-deleted",
                     "fat16-fixture", "tfat16-fixture", "fat12-fixture",
                     "exfat-deleted", "f2fs-fixture", "squashfs-gzip",
                     "jffs2-le-zlib", "ubi-nand-lzo", "yaffs2-history",
                     "yaffs1-history"):
            fix = os.path.join(here, stem + ".img.gz")
            if not os.path.isfile(fix):
                continue
            try:
                vols, rows, wrong, fast = _walk_all_agreement(fix)
            except Exception as exc:                 # pylint: disable=broad-except
                vols, rows, wrong, fast = 0, 0, 1, False
                print(f"       {stem}: raised {type(exc).__name__}: {exc}")
            checked += vols
            all_rows += rows
            all_wrong += wrong
            if fast:
                fast_seen.append(stem)
        # A fixture that is not beside this file cannot be walked, and that is
        # not a failure: a frozen build carries the script and not the test
        # data, which is exactly how the other fixture checks here behave. A
        # check that cannot run has to say so rather than report a defect.
        if not checked:
            print("  [SKIP] the fixtures are not beside this script, so walk_all() "
                  "was not compared against a walk of the directory tree")
        else:
            wcond = all_rows and not all_wrong
            if not wcond:
                ok = False
            print(f"  [{'PASS' if wcond else 'FAIL'}] walk_all() reports exactly what a "
                  f"walk of the directory tree reports, on every committed fixture "
                  f"({all_rows:,} entries over {checked} volume(s), {all_wrong} "
                  f"disagreement(s); the fast route was taken on "
                  f"{', '.join(fast_seen) or 'none'})")

        # The fast routes have to be reached, not merely present. A change that
        # leaves walk_all() correct by quietly falling back to the tree passes
        # the comparison above and is still a regression, so the routes are
        # asserted here: the MFT pass must report the volume, and the APFS
        # prime must hold records and must stand down when capped.
        apfs_fix2 = os.path.join(here, "apfs-fixture.img.gz")
        ntfs_fix2 = os.path.join(here, "ntfs-fixture.img.gz")
        if os.path.isfile(ntfs_fix2):
            try:
                with gzip.open(ntfs_fix2, "rb") as gz:
                    nimg = io.BytesIO(gz.read())
                nw = [v["walker"] for v in volumes(nimg, image_size(nimg)) if v.get("walker")][0]
                n_from_mft = sum(1 for _ in nw.listing())
                nfail = ""
            except Exception as exc:                 # pylint: disable=broad-except
                n_from_mft, nfail = 0, f" ({type(exc).__name__}: {exc})"
            cond = n_from_mft > 0
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] the NTFS listing is built from "
                  f"$MFT and not from the directory tree ({n_from_mft} entries"
                  f" from one pass){nfail}")

        if os.path.isfile(apfs_fix2):
            try:
                with gzip.open(apfs_fix2, "rb") as gz:
                    aimg = io.BytesIO(gz.read())
                aw = [v["walker"] for v in volumes(aimg, image_size(aimg)) if v.get("walker")][0]
                primed = aw.prime_records()
                held = sum(
                    len(t) for i in primed
                    for t in [aw._state[i]["primed"]] if t)   # pylint: disable=protected-access
                # Every type a listing asks for has to be in the table, or the
                # lookups it was built to answer go back to searching the tree.
                # These three numbers are written out and are deliberately NOT
                # APFS_PRIMED_TYPES: comparing the table against the same
                # constant that filled it passes whatever that constant says,
                # which is how narrowing it to inodes alone went unnoticed
                # here. They are apfs_fs_key's record types for an inode, an
                # extended attribute and a directory record.
                WANT_PRIMED = {3, 4, 9}
                kinds = {
                    k[1] for i in primed
                    for t in [aw._state[i]["primed"]] if t for k in t}  # pylint: disable=protected-access
                missing_kinds = sorted(WANT_PRIMED - kinds)
                # the same walker, asked again with a cap it cannot meet
                with gzip.open(apfs_fix2, "rb") as gz:
                    aimg2 = io.BytesIO(gz.read())
                aw2 = [v["walker"] for v in volumes(aimg2, image_size(aimg2)) if v.get("walker")][0]
                capped = aw2.prime_records(max_records=1)
                capped_rows = sum(1 for _ in walk_all(aw2))
                afail = ""
            except Exception as exc:                 # pylint: disable=broad-except
                primed, held, capped, capped_rows = [], 0, ["?"], 0
                missing_kinds = [-1]
                afail = f" ({type(exc).__name__}: {exc})"
            cond = (bool(primed) and held > 0 and not missing_kinds
                    and not capped and capped_rows > 0)
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] the APFS tree is primed in one "
                  f"pass, and a volume over the cap is walked instead of held "
                  f"({len(primed)} volume(s) primed holding {held} key(s) of "
                  f"{3 - len(missing_kinds)} of 3 record type(s); capped: "
                  f"{len(capped)} primed, {capped_rows} entries still "
                  f"reported){afail}")

        # Neither committed fixture holds a DOS 8.3 name or a padded
        # $FILE_NAME, because both were built on macOS. A real Windows volume
        # is full of the first (93,048 of 249,943 names on one acquisition), so
        # the rules that handle them are exercised here on records built for
        # the purpose rather than left to a fixture that cannot reach them.
        def _fn(parent, seq, name, namespace, tail=b""):
            v = bytearray(0x42)
            struct.pack_into("<Q", v, 0, (seq << 48) | parent)
            enc = name.encode("utf-16-le")
            v[0x40] = len(name)
            v[0x41] = namespace
            attr = _NtfsAttr(NTFS_FILE_NAME, "", 0, True)
            attr.value = bytes(v) + enc + tail
            return attr

        def _short(parent, name):
            """A record that declares a longer name than it holds."""
            a = _fn(parent, 1, name, 1)
            a.value = a.value[:-4]
            return a

        name_cases = [
            ("a long name is kept", [_fn(5, 1, "Microsoft.Ink.dll", 1)],
             [(5, "Microsoft.Ink.dll")]),
            ("its 8.3 twin is dropped", [_fn(5, 1, "MICROS~1.DLL", 2)], []),
            ("a name that is already 8.3 is kept", [_fn(5, 1, "SETUP.EXE", 3)],
             [(5, "SETUP.EXE")]),
            ("both links of a hard-linked file are kept",
             [_fn(7, 1, "http", 1), _fn(9, 1, "https", 1)],
             [(7, "http"), (9, "https")]),
            ("the DOS twin is dropped from beside its long name",
             [_fn(5, 1, "LongName.txt", 1), _fn(5, 1, "LONGNA~1.TXT", 2)],
             [(5, "LongName.txt")]),
            ("a name the record is too short to hold is dropped",
             [_short(5, "truncated.txt")], []),
            ("padding after the name is not read as part of it",
             [_fn(5, 1, "padded.txt", 1, b"\x00" * 6)], [(5, "padded.txt")]),
            ("the sequence number rides in the top of the reference",
             [_fn(0x1D419, 2, "x", 1)], [((2 << 48) | 0x1D419, "x")]),
            (". and .. are not children", [_fn(5, 1, ".", 1), _fn(5, 1, "..", 1)], []),
        ]
        for label, attrs, want in name_cases:
            try:
                got = _ntfs_file_names(attrs)
                # the reference is compared low-48 only except where the case
                # is about the sequence number itself
                if "sequence" not in label:
                    got = [(r & 0xFFFFFFFFFFFF, n) for r, n in got]
            except Exception as exc:                 # pylint: disable=broad-except
                got = f"raised {type(exc).__name__}: {exc}"
            cond = got == want
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] $FILE_NAME: {label}"
                  + ("" if cond else f"  (got {got}, wanted {want})"))

        # The control for that check. A fast route that drops one entry must
        # make it report a disagreement; a comparison that has never reported
        # one says nothing about the comparison.
        def _drop_one(w):
            real = getattr(w, "listing", None)
            if real is None:
                return w

            class _ShortOne:
                """The walker, with one entry missing from its fast route."""
                def __init__(self, inner):
                    self._inner = inner

                def __getattr__(self, name):
                    return getattr(self._inner, name)

                def listing(self):
                    return itertools.islice(real(), 1, None)

            return _ShortOne(w)

        ntfs_only = os.path.join(here, "ntfs-fixture.img.gz")
        if os.path.isfile(ntfs_only):
            try:
                _v, _r, broke_wrong, _f = _walk_all_agreement(ntfs_only, break_it=_drop_one)
            except Exception:                        # pylint: disable=broad-except
                broke_wrong = 0
            ccond = broke_wrong > 0
            if not ccond:
                ok = False
            print(f"  [{'PASS' if ccond else 'FAIL'}] and that comparison reports a "
                  f"disagreement when the fast route drops an entry "
                  f"({broke_wrong} found)")

        # BitLocker, on volumes tools/make_bitlocker_fixtures.py lays out around the
        # SquashFS fixture from the format document, not from this reader (which was
        # also checked against volumes Windows 11 wrote). The identifier and the test
        # secrets are written out again here, not taken from the reader or the tool.
        true_bde_guid = bytes.fromhex("3bd66749292ed84a8399f6a339e3d001")   # 4967d63b-2e29-...
        cond = BDE_GUID == true_bde_guid and BDE_SIGNATURE == b"-FVE-FS-"
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] the BitLocker identifier and signature are the "
              f"format's")
        rk_dash = bde_recovery_key("111111-222222-333333-444444-555555-666666-000011-000022")
        cond = (rk_dash is not None and rk_dash[:2] == b"\x75\x27"       # 111111 / 11 = 10101
                and bde_recovery_key("111111 222222 333333 444444 555555 666666 000011 000022") == rk_dash
                and bde_recovery_key("111112-222222-333333-444444-555555-666666-000011-000022") is None)
        if not cond:
            ok = False
        print(f"  [{'PASS' if cond else 'FAIL'}] a recovery password is read with or without its "
              f"dashes, and one whose group is not a multiple of 11 is not one")
        bde_first = os.path.join(here, "bitlocker-xts128.img.gz")
        if _BDE_AES is None or not os.path.isfile(bde_first):
            print("  [SKIP] BitLocker volumes open with their keys (needs the BitLocker "
                  "fixtures and the pycryptodome package)")
        else:
            import gzip as _gz, hashlib as _hl, io as _bio  # pylint: disable=import-outside-toplevel
            bde_pw = "qnxprobe-bde-test"
            bde_rec_a = "111111-222222-333333-444444-555555-666666-000011-000022"
            bde_rec_b = "000011-000022-000033-000044-000055-000066-000077-000088"
            with open(os.path.join(here, "bitlocker-xts128.BEK"), "rb") as handle:
                bde_bek = handle.read()
            with open(os.path.join(here, "squashfs.src.sha256"), encoding="utf-8") as handle:
                bde_sums = dict(reversed(line.rstrip("\n").split("  ", 1))
                                for line in handle if line.strip())

            def _bde(name, secrets=(), keys=()):
                with _gz.open(os.path.join(here, f"bitlocker-{name}.img.gz"), "rb") as g:
                    raw = g.read()
                fh, _found = unlock_bitlocker(_bio.BytesIO(raw), len(raw), secrets, keys)
                vol = volumes(fh, len(raw))[0]
                matched, walker = 0, vol.get("walker")
                if walker is not None:
                    got = {p: (n, sz) for p, n, _m, sz, _t, _r in walk_all(walker)}
                    for path, digest in bde_sums.items():
                        g = got.get(path)
                        if g and _hl.sha256(b"".join(walker.read_file(*g))).hexdigest() == digest:
                            matched += 1
                return vol, matched, raw

            def _opened(by):
                return lambda v, m: (v["kind"] == "squashfs" and m == len(bde_sums)
                                     and v.get("encryption", "").endswith(f"unlocked with its {by}"))

            bde_legs = [
                ("a locked volume is named, not walked, and says what opens it, with the "
                 "recovery password's protector id", "xts128", (), (),
                 lambda v, m: (v["kind"] == "bitlocker" and v.get("walker") is None
                               and "recovery password (protector id" in v.get("note", "")
                               and "startup key" in v.get("note", "")
                               and "none of the passwords" not in v.get("note", ""))),
                ("a wrong password leaves it locked, saying the keys given did not open it",
                 "xts128", ("not-the-password",), (),
                 lambda v, m: v["kind"] == "bitlocker" and "none of the passwords" in v.get("note", "")),
                ("its password opens AES-128-XTS", "xts128", (bde_pw,), (), _opened("password")),
                ("its recovery password opens it", "xts128", (bde_rec_a,), (),
                 _opened("recovery password")),
                ("its startup key (.BEK) opens it", "xts128", (), (bde_bek,), _opened("startup key")),
                ("a recovery password opens AES-256-CBC", "cbc256", (bde_rec_b,), (),
                 _opened("recovery password")),
                ("a suspended volume opens with the clear key it keeps (AES-256-XTS)", "clearkey",
                 (), (), _opened("clear key")),
                ("an unfinished conversion reads its unencrypted range as stored "
                 "(Encrypt-on-Write map)", "eow", (bde_pw,), (), _opened("password")),
                ("the To Go layout opens (constructed only; Windows 11 wrote none)", "togo",
                 (bde_pw,), (), _opened("password")),
                ("a volume protected only by a TPM says its key does not leave the device",
                 "tpm", (), (), lambda v, m: v["kind"] == "bitlocker" and "TPM" in v.get("note", "")),
                ("the Elephant diffuser is named as not read", "diffuser", (bde_pw,), (),
                 lambda v, m: "Elephant diffuser" in v.get("note", "")),
                ("the Windows Vista layout is named as not read", "vista", (bde_pw,), (),
                 lambda v, m: "Windows Vista" in v.get("note", "")),
            ]
            bde_raw = {}
            for label, name, secrets, keys, test in bde_legs:
                try:
                    vol, matched, raw = _bde(name, secrets, keys)
                    cond = bool(test(vol, matched))
                    detail = f"{vol['kind']}, {matched}/{len(bde_sums)} files"
                    bde_raw[name] = raw
                except Exception as exc:                 # pylint: disable=broad-except
                    cond, detail = False, f"raised {type(exc).__name__}: {exc}"
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] BitLocker: {label} ({detail})")
            if "xts128" in bde_raw and "vista" in bde_raw:
                win7, vista = _bio.BytesIO(bde_raw["xts128"]), _bio.BytesIO(bde_raw["vista"])
                cond = (identify_fat(win7, 0) is None and parse_mbr(win7) is None
                        and parse_mbr(vista) is None)
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] a BitLocker header (a FAT32 boot sector in "
                      f"all but its own fields, or Windows Vista's NTFS-like one) is taken for "
                      f"neither a FAT32 volume nor a partition table")

        # ---- BitLocker protectors Windows 11 wrote, TPM ones among them ---
        tpm_dir = os.path.join(here, "bitlocker-win11-tpm")
        if not os.path.isfile(os.path.join(tpm_dir, "manifest.json")):
            print("  [SKIP] BitLocker protectors Windows 11 wrote (fixtures not found)")
        else:
            class _Ranges:
                """The captured header and metadata at their volume offsets, zeros elsewhere."""

                def __init__(self, parts, size):
                    self.parts, self.size, self.pos = parts, size, 0

                def seek(self, off, whence=0):
                    self.pos = off if whence == 0 else self.pos + off if whence == 1 else self.size + off
                    return self.pos

                def tell(self):
                    return self.pos

                def read(self, n=-1):
                    end = self.size if n is None or n < 0 else min(self.size, self.pos + n)
                    out = bytearray(max(0, end - self.pos))
                    for start, data in self.parts:
                        lo, hi = max(start, self.pos), min(start + len(data), end)
                        if lo < hi:
                            out[lo - self.pos:hi - self.pos] = data[lo - start:hi - start]
                    self.pos = max(self.pos, end)
                    return bytes(out)

            with open(os.path.join(tpm_dir, "manifest.json"), encoding="utf-8") as handle:
                tpm_states = json.load(handle)["states"]
            windows_names = {"Numerical Password": "recovery password", "TPM": "TPM",
                             "TPM And PIN": "TPM and PIN", "TPM And Startup Key": "TPM and startup key",
                             "TPM And PIN And Startup Key": "TPM, PIN and startup key"}
            for state, info in sorted(tpm_states.items()):
                try:
                    with gzip.open(os.path.join(tpm_dir, f"{state}.bin.gz"), "rb") as g:
                        raw = g.read()
                    parts = [(0, raw[:512])] + [(off, raw[512 + i * 65536:512 + (i + 1) * 65536])
                                                for i, off in enumerate(info["metadata_offsets"])]
                    fh = _Ranges(parts, info["partition_size"])
                    facts = BitLocker.open(fh, 0, info["partition_size"]).facts()
                    got = sorted((p["id"], p["kind"], p["pcrs"]) for p in facts["protectors"])
                    want = sorted((w["id"], windows_names.get(w["type"]), w["pcrs"]) for w in info["windows"])
                    cond, detail = got == want, f"{len(got)} protector(s)"
                except Exception as exc:                 # pylint: disable=broad-except
                    cond, detail = False, f"raised {type(exc).__name__}: {exc}"
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] BitLocker {state}: every protector's kind, id "
                      f"and PCRs are what manage-bde printed ({detail})")

        # ---- AFF4 and encrypted APFS volumes --------------------------
        import hashlib as _hl4, io as _io4  # pylint: disable=import-outside-toplevel
        _gz4, _zf4 = gzip, zipfile
        sq_fix = os.path.join(here, "squashfs-small.img.gz")
        if (ewfprobe is None or not hasattr(ewfprobe, "is_aff4")
                or not os.path.isfile(sq_fix)):
            print("  [SKIP] an AFF4 acquisition reads as the image it holds (needs the "
                  "vendored ewfprobe and the SquashFS fixture)")
        else:
            with _gz4.open(sq_fix, "rb") as g:
                sq_raw = g.read()
            with open(os.path.join(here, "squashfs.src.sha256"), encoding="utf-8") as handle:
                sq_sums = dict(reversed(line.rstrip("\n").split("  ", 1))
                               for line in handle if line.strip())
            # A small AFF4 Standard v1.0 container written here, around the fixture:
            # stored chunks, a map of one range, and the metadata that names them.
            vol_u, st_u, map_u, img_u = (f"aff4://0a4f4000-0000-4000-8000-00000000000{k}"
                                         for k in "1234")
            chunk, per = 32768, 16
            parts = [sq_raw[i:i + chunk].ljust(chunk, b"\0")
                     for i in range(0, len(sq_raw), chunk)]
            aff4_path = os.path.join(d, "wrapped.aff4")
            with _zf4.ZipFile(aff4_path, "w", _zf4.ZIP_STORED) as z:
                z.writestr("container.description", vol_u)
                for b in range(0, len(parts), per):
                    name = st_u.replace("aff4://", "aff4%3A%2F%2F") + f"/{b // per:08d}"
                    z.writestr(name, b"".join(parts[b:b + per]))
                    z.writestr(name + ".index", b"".join(struct.pack("<QI", k * chunk, chunk)
                                                         for k in range(len(parts[b:b + per]))))
                mname = map_u.replace("aff4://", "aff4%3A%2F%2F")
                z.writestr(mname + "/map", struct.pack("<QQQI", 0, len(sq_raw), 0, 0))
                z.writestr(mname + "/idx", st_u + "\n")
                z.writestr("information.turtle", (
                    "@prefix aff4: <http://aff4.org/Schema#> .\n"
                    f"<{img_u}> a aff4:DiskImage, aff4:Image ; aff4:dataStream <{map_u}> .\n"
                    f"<{map_u}> a aff4:Map ; aff4:size {len(sq_raw)} .\n"
                    f"<{st_u}> a aff4:ImageStream ; aff4:size {len(sq_raw)} ; "
                    f"aff4:chunkSize {chunk} ; aff4:chunksInSegment {per} ; "
                    f"aff4:compressionMethod aff4:NullCompressor .\n"))
                z.comment = vol_u.encode()
            plain_zip = os.path.join(d, "plain.zip")
            with _zf4.ZipFile(plain_zip, "w") as z:
                z.writestr("information.turtle", "not AFF4")
            aff4_matched, aff4_desc, aff4_kind = 0, "", None
            try:
                with open_image(aff4_path) as handle:
                    aff4_desc = describe_acquisition(handle)
                    vol = volumes(handle)[0]
                    aff4_kind, walker = vol["kind"], vol.get("walker")
                    if walker is not None:
                        got = {p: (n, sz) for p, n, _m, sz, _t, _r in walk_all(walker)}
                        for path, digest in sq_sums.items():
                            g = got.get(path)
                            if g and _hl4.sha256(b"".join(walker.read_file(*g))).hexdigest() == digest:
                                aff4_matched += 1
            except Exception as exc:                 # pylint: disable=broad-except
                aff4_desc = f"raised {type(exc).__name__}: {exc}"
            for label, cond in (
                    ("an AFF4 container is recognised as one, and a ZIP that only looks "
                     "like it is not", acquisition_format(aff4_path) == "AFF4"
                     and acquisition_format(plain_zip) is None),
                    (f"an AFF4 acquisition reads as the image it holds ({aff4_kind}, "
                     f"{aff4_matched}/{len(sq_sums)} files)",
                     aff4_kind == "squashfs" and aff4_matched == len(sq_sums)
                     and aff4_desc.startswith("an AFF4 acquisition"))):
                if not cond:
                    ok = False
                print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        apfs_enc = os.path.join(here, "apfs-encrypted.sparseimage.gz")
        if ewfprobe is None or not os.path.isfile(apfs_enc):
            print("  [SKIP] an encrypted APFS volume is named, not walked (needs the "
                  "vendored ewfprobe and the encrypted APFS fixture)")
        else:
            enc_path = os.path.join(d, "apfs-encrypted.sparseimage")
            with _gz4.open(apfs_enc, "rb") as g, open(enc_path, "wb") as out:
                shutil.copyfileobj(g, out)
            with open(os.path.join(here, "apfs-encrypted.sha256"), encoding="utf-8") as handle:
                enc_sums = {"PLAINVOL/" + path: digest for digest, path in
                            (line.rstrip("\n").split("  ", 1) for line in handle if line.strip())}
            enc_states, enc_note, enc_matched, enc_secret = [], "", 0, -1
            enc_parsed, enc_report = True, []
            try:
                with open_image(enc_path) as handle:
                    vol = [v for v in volumes(handle) if v["kind"] == "apfs"][0]
                    w = vol["walker"]
                    enc_states = [w.encryption(i) for i in range(len(w.volumes))]
                    enc_note = vol.get("note", "")
                    enc_report = identify_fs(handle, vol["base"], vol["size"])[1]
                    got = {p: (n, sz) for p, n, _m, sz, _t, _r in walk_all(w)}
                    enc_secret = sum(1 for p in got if p.startswith("SECRETVOL"))
                    # its tree was never parsed: ciphertext read as a tree returns
                    # nothing, which is what hid it before
                    enc_parsed = 1 in w._state          # pylint: disable=protected-access
                    for path, digest in enc_sums.items():
                        g = got.get(path)
                        if g and _hl4.sha256(b"".join(w.read_file(*g))).hexdigest() == digest:
                            enc_matched += 1
            except Exception as exc:                 # pylint: disable=broad-except
                enc_note = f"raised {type(exc).__name__}: {exc}"
            cond = (enc_states == [None, "locked"] and enc_secret == 0 and not enc_parsed
                    and enc_matched == len(enc_sums) and enc_matched > 0
                    and "SECRETVOL is encrypted, and its blocks are ciphertext" in enc_note
                    and any("SECRETVOL" in ln and "locked" in ln for ln in enc_report)
                    and any(ln.startswith("note") and "ciphertext" in ln for ln in enc_report))
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] an APFS volume macOS encrypted is named "
                  f"locked and not walked, and the plain volume beside it reads "
                  f"({enc_matched}/{len(enc_sums)} files, {enc_states})")

            apfs_conv = os.path.join(here, "apfs-converted.sparseimage.gz")
            if not os.path.isfile(apfs_conv) or _BDE_AES is None:
                print("  [SKIP] an encrypted APFS volume opens with its password (needs the "
                      "converted APFS fixture and the pycryptodome package)")
            else:
                conv_path = os.path.join(d, "apfs-converted.sparseimage")
                with _gz4.open(apfs_conv, "rb") as g, open(conv_path, "wb") as out:
                    shutil.copyfileobj(g, out)
                try:
                    results = _apfs_unlock_checks(enc_path, conv_path,
                                                  os.path.join(here, "apfs-converted.sha256"))
                except Exception as exc:             # pylint: disable=broad-except
                    results = [(False, f"opening an encrypted APFS volume raised "
                                       f"{type(exc).__name__}: {exc}")]
                for cond, label in results:
                    if not cond:
                        ok = False
                    print(f"  [{'PASS' if cond else 'FAIL'}] {label}")

        apfs_fix = os.path.join(here, "apfs-fixture.img.gz")
        if not os.path.isfile(apfs_fix):
            print("  [SKIP] an APFS volume flagged encrypted but held in the clear is "
                  "read (needs the APFS fixture)")
        else:
            with _gz4.open(apfs_fix, "rb") as g:
                apfs_raw = bytearray(g.read())
            w0 = ApfsWalker(_io4.BytesIO(bytes(apfs_raw)), 0)
            bs, blk = w0.block_size, w0.volumes[0][1]
            sb = bytearray(apfs_raw[blk * bs:(blk + 1) * bs])
            flags = struct.unpack_from("<Q", sb, APFS_FS_FLAGS_OFF)[0]
            was_plain = bool(flags & APFS_FS_UNENCRYPTED)
            # the shape an acquisition through the Mac's own decryption leaves: the
            # flag says encrypted, the blocks are in the clear
            struct.pack_into("<Q", sb, APFS_FS_FLAGS_OFF, flags & ~APFS_FS_UNENCRYPTED)
            struct.pack_into("<Q", sb, 0, _apfs_fletcher(sb))
            apfs_raw[blk * bs:(blk + 1) * bs] = sb
            w1 = ApfsWalker(_io4.BytesIO(bytes(apfs_raw)), 0)
            n0 = sum(1 for _ in walk_all(w0))
            n1 = sum(1 for _ in walk_all(w1))
            cond = (was_plain and n0 > 0 and n1 == n0 and w1.encryption(0) == "clear"
                    and "flagged encrypted, but its blocks read in the clear" in (w1.note or ""))
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] an APFS volume flagged encrypted whose "
                  f"blocks the image holds in the clear is read ({n1} of {n0} entries)")
            # and the same volume with its tree's root node as ciphertext would be
            root = w1.fs_root_block
            noise = b"".join(_hl4.sha256(b"%d" % k).digest() for k in range(bs // 32))
            apfs_raw[root * bs:(root + 1) * bs] = noise
            try:
                w2 = ApfsWalker(_io4.BytesIO(bytes(apfs_raw)), 0)
                n2 = sum(1 for _ in walk_all(w2))
                cond = (w2.encryption(0) == "locked" and n2 == 0
                        and "ciphertext" in (w2.note or "")
                        and 0 not in w2._state)          # pylint: disable=protected-access
                detail = f"{n2} entries"
            except Exception as exc:                 # pylint: disable=broad-except
                cond, detail = False, f"raised {type(exc).__name__}: {exc}"
            if not cond:
                ok = False
            print(f"  [{'PASS' if cond else 'FAIL'}] an encrypted APFS volume whose tree does "
                  f"not pass its checksum is locked, as the first volume too ({detail})")

        print()
        print("  SELF-TEST PASSED. The detector reports positives and negatives"
              if ok else
              "  SELF-TEST FAILED. Do not trust results from this build.")
        return 0 if ok else 1
    finally:
        shutil.rmtree(d, ignore_errors=True)


EPILOG = """\
examples:
  # one image
  qnxprobe.py Dodge.img

  # several at once
  qnxprobe.py *.img *.bin

  # the members of a Linux md RAID set, or the disks of an LVM volume group:
  # each image is read, then each array or spanned volume assembled from them
  qnxprobe.py disk0.img disk1.img disk2.img disk3.img

  # a single partition already carved out
  qnxprobe.py partition2.dd

  # prove the detector works before you trust a negative result
  qnxprobe.py --self-test

  # widen the fallback brute scan for an image with an odd layout
  qnxprobe.py --scan-limit 2048 mmcblk0.img

  # list what is inside every filesystem it finds
  qnxprobe.py --list mmcblk0.img

  # copy the logical files out into a zip, ready for a LEAPP tool
  qnxprobe.py --extract sync_g4.zip mmcblk0.img

  # a split acquisition: name any one segment, the set beside it is joined
  qnxprobe.py --extract sync_g4.zip mmcblk0.img.001

  # just one partition, by name or label
  qnxprobe.py --extract storage.zip --only storage mmcblk0.img

  # go deeper, and raise the per-filesystem entry cap
  qnxprobe.py --list --depth 4 --list-max 3000 mmcblk0.img

deciding what to pull first:
  --triage ranks every volume it found by how much each has been written, and
  flags the ones that are not worth your time. It uses only what the probe
  already read: the qnx6 superblock serial is a commit counter, and ext
  exposes mount count and lifetime kilobytes written.

  It also samples filenames and says so when they are encrypted, because a
  volume whose names are encrypted will not yield to any parser without the
  keys. Measured on a 2024 BMW MGU: the busiest volume on the disk, /var/opt,
  is 36% encrypted names in a sample.

  Read the fill percentage alongside the ranking rather than sorting on size.
  On a Ford Sync G4 the 4 MiB manufacturing volume, last in the ranking with
  16 commits, is the one holding the unit's Bluetooth and WiFi addresses,
  serials and TLS keys. Activity finds the user data; it does not measure
  value per byte.

getting the files out, without mounting:
  --extract writes every regular file from every filesystem it identified into
  a zip, which is the shape a LEAPP tool expects. Directories are implied by
  the paths; symlinks and special files are counted and skipped. Entries are
  stamped with the file's own mtime, clamped to 1980 where the stored time
  predates what the zip format can hold.

  This exists because mounting is a Linux-only answer. macOS ships no qnx6
  driver, the WSL2 kernel is built with CONFIG_QNX6FS_FS unset, and the FUSE
  options are Linux-tested. --extract is standard library only, so it behaves
  the same on macOS, Windows and Linux, needs no administrator rights, no loop
  device and no virtual machine, and cannot write to the evidence.

  --only restricts --list and --extract to partitions whose name or label
  contains the text given, which matters because a whole head unit can run to
  tens of gigabytes.

  It refuses to overwrite an existing output file.

getting the free space out:
  --unallocated DIR writes, for every volume whose filesystem says what is free
  (qnx6, F2FS, FAT32, FAT16, FAT12, exFAT, NTFS, HFS+ and APFS), the free runs one after
  another into <image>.<volume>.unallocated.bin, with a .tsv beside it mapping
  each run back to its offset in the image, and unallocated.json naming every
  volume looked at and what was done with it. A volume whose filesystem does
  not report free space, or whose answer was empty, gets no file and is listed
  as such: an empty answer can mean the allocation map could not be read, so it
  is never called "nothing free". A run past the end of a partial image is cut
  there and the shortfall counted. An APFS container's free space is copied as
  stored, so what an encrypted volume wrote there stays encrypted; an opened
  BitLocker volume is read decrypted. Space outside every recognised volume is
  not written. DIR must be new or empty, and --only applies.

listing contents:
  --list walks each filesystem it identified and prints the tree. It handles
  qnx6, QNX4, ext2/3/4, FAT32, FAT16, FAT12, exFAT, NTFS, HFS+, APFS, the QNX flash
  filesystems ETFS and EFS, and QNX IFS boot images, follows qnx6 long filenames
  and ext4 extent trees, and reads only. --depth sets how far down it goes and
  --list-max caps the number of entries per filesystem so a large volume cannot
  flood the terminal. An NTFS or APFS listing also names anything held in a
  stream beside the file, and an HFS+ one names a resource fork that carries
  anything. An APFS container is listed as a directory of its volumes, so every
  volume in it is walked, except an encrypted one whose blocks are ciphertext in
  the image, which is named and not walked. An encrypted one the image holds
  decrypted (its tree's root node passes its checksum) is walked and said to be.

what it reports:
  Every superblock copy it can find, grouped into generations by serial. The
  highest serial is the active one; the generation below it is the previous
  committed state, still on disk. It then diffs the two, so you can see what
  one commit actually changed.

  Measured on a Ford Sync G4 image, a qnx6 filesystem carries FOUR copies, not
  two: the 0x1000 area reserved at 0x2000 holds slots at +0x2000 and +0x2e00,
  and a second reserved area near the end of the volume mirrors both. So the
  previous committed state is usually recoverable.

  A copy whose volume id, blocksize and block count match an already-confirmed
  superblock in the same partition is accepted as another copy of that
  filesystem even if its timestamps look wrong, and the run says how many were
  accepted that way. Recorded identity is a stronger signal than a date: on the
  Sync G4 image the previous generation of dps_os carries ctime 308 and atime 1,
  both unset because the build host had no clock, and a timestamp test alone
  rejects a genuine superblock.

  Time differences between generations are printed in whole units, seconds
  through years. Where one side is an unset placeholder rather than a date the
  difference is NOT a duration, and it is reported as the change it is instead
  of a meaningless span of years.

  After the qnx6 volumes it reports WHAT IS IN THE OTHER PARTITIONS, because a
  partition type byte is a label and not a fact. ext2, ext3 and ext4 are read
  in full: label, last mount point, UUID, creation and mount and write times,
  mount count, usage, lifetime bytes written, and whether the volume was
  cleanly unmounted. QNX IFS boot images report their startup header (version,
  target machine, startup code size, compression method), then the image
  filesystem is decompressed and listed and extracted like any other, with the
  image checksum reported as a decode self-check. The QNX flash filesystems
  ETFS and EFS are recognised too, and listed and extracted in full, and so is
  QNX4, the filesystem of QNX 4 systems, which the MBR type bytes 0x4d/0x4e/
  0x4f announce but never prove. Anything
  else is reported as its leading bytes plus any ASCII magic,
  so there is a lead to follow rather than a guess. On a 2024 BMW
  MGU image that turned twelve partitions all marked 0x83 "Linux" into ten
  ext4 volumes, one extended container, and one holding an ipk container with
  a Linux bzImage inside it.

  ETFS and EFS are usually imaged bare, with no partition table, so they arrive
  as the whole image and extract under the lba0 name. ETFS has no superblock, so
  its live state is rebuilt by replaying the transaction records in the spare
  area of every page, keeping the highest sequence number for each block; its
  extraction also carries the internal .filetable, .badblks, .counts and
  .reserved bookkeeping files, which are real entries in the filesystem. EFS is
  found by its QSSL_F3S boot record and walked through its extent chains, each
  file resolved to its current version through the superseding-extent pointers.
  It is read in either byte order. A raw NOR dump that holds several EFS
  partitions behind its boot code is searched for their boot records, and each
  partition is placed by the record's unit_index, since wear levelling moves
  the unit that holds the record.

  sb_ctime is written once, when the filesystem is made. sb_atime moves when
  the filesystem is COMMITTED, not when a file is read, so do not report it as
  when a person last used the device. serial counts commits and is the better
  measure of how much a volume has been written. Measured across three volumes
  of a Ford Sync G4 image: 15 commits on manufacturing data, 1,713 on the OS,
  411,711 on user storage.

  The field names sb_ctime and sb_atime come from comments in the Linux
  header. QNX does not publish the on-disk superblock layout, so treat the
  names as labels and report what moved rather than what someone did.

what it checks, and where the constants come from:
  QNX6_SUPER_MAGIC   0x68191122   linux/include/uapi/linux/magic.h:55
  QNX6_BOOTBLOCK_SIZE    0x2000   linux/include/linux/qnx6_fs.h:23
  struct qnx6_super_block          linux/include/linux/qnx6_fs.h:94

  fs/qnx6/inode.c reads superblock #1 at +0x2000 from the start of the
  partition and retries at +0 if the magic is wrong. Little endian is tried
  first, then big endian. This tool does the same, for the whole image, for
  every MBR primary, every logical volume in the extended chain, and every
  GPT partition, on disks of 512-byte or 4096-byte sectors.

  A bare 4-byte magic match is not a finding: expect roughly one by chance
  per 256 MiB scanned. Every candidate is parsed as a superblock and its
  fields checked for consistency before it is reported CONFIRMED.

  For the ext side:
  EXT2_SUPER_MAGIC       0xEF53   linux/include/uapi/linux/magic.h:24
  struct ext4_super_block         linux/fs/ext4/ext4.h
  struct ext4_group_desc          linux/fs/ext4/ext4.h
  struct ext4_inode               linux/fs/ext4/ext4.h
  struct ext4_dir_entry_2         linux/fs/ext4/ext4.h
  EXT4_EXT_MAGIC         0xf30a   linux/fs/ext4/ext4_extents.h

  The ext field offsets were derived from that header and cross-checked
  against its own /*NN*/ offset markers, all fifteen of which agreed, with the
  struct totalling the expected 1024 bytes.

  For QNX IFS boot images:
  STARTUP_HDR_SIGNATURE  0x00ff7eeb   qnx sys/startup.h:88
  STARTUP_HDR_VERSION             1   qnx sys/startup.h:89
  struct startup_header               qnx sys/startup.h, and QNX's own
                                      "The startup header" documentation page,
                                      which lists the same fields in the same
                                      order

  Those field widths sum to 256 bytes, which each image's own header_size
  field confirms. The machine field is documented as an ELF machine type and
  is reported through EM_386 3, EM_ARM 40, EM_X86_64 62 and EM_AARCH64 183
  from linux/include/uapi/linux/elf-em.h. The image filesystem begins at
  startup_size, and stored_size minus startup_size against imagefs_size says
  whether it is stored compressed.

  The image filesystem and its compression come from QNX's own dumpifs and
  sys/image.h. startup_header flags1 carries the method (none, zlib, lzo or
  ucl). A compressed imagefs is a run of blocks, each a 2-byte big-endian
  compressed length then that many bytes, decompressing to at most 64 KiB and
  ending at a zero length. Each ucl block is UCL NRV2B, the _8 variant dumpifs
  links as ucl_nrv2b_decompress_8; it is carried here as a small pure-Python
  decoder ported from Markus Oberhumer's UCL (src/n2b_d.c, src/getbit.h), so
  nothing has to be installed. The decompressed image is walked from its
  image_header and a flat table of image_dirent records: each carries an inode,
  mode, mtime and a full path, and a file points at an offset and size inside
  the image. zlib images are read through the standard library.

  This is proven byte for byte against the Ford Sync G4 ifs_a, ifs_b and
  ifs_recovery volumes. Each decompressed to exactly the imagefs_size its own
  header records, the 32-bit words from the header through the image_trailer
  summed to zero (the trailer holds a checksum), and the extracted files were
  valid, including the AArch64 ELF kernel whose machine matched the startup
  header. That checksum is printed on every run as a decode self-check.

  lzo-compressed images and the Harman Becker HBCIFS container are recognised
  but not read here, since no sample exists to validate a reader against, and a
  big-endian image is declined the same way. In each case the header is still
  reported and the walk is declined out loud. Nothing is invented.

  For the QNX flash filesystems ETFS and EFS:
  struct etfs_trans, the fid scheme, ftable and directory entry layouts, and
  the F3S extent, unit and boot structures are transcribed from the Kaitai
  .ksy specs in NetherlandsForensicInstitute/qnxmount (Apache-2.0), whose ETFS
  spec cross-references QNX's own fs/etfs.h and whose EFS spec fs/f3s_spec.h.
  The Kaitai runtime is not a dependency; only the field layouts are copied,
  into the same hand-written struct style as everything above, so this stays
  standard library only. Both readers were validated by extracting qnxmount's
  own committed test images and comparing every name, mode, owner, timestamp,
  symlink target and byte of file content against the tar archive built from
  the same live filesystem, which qnxmount produced on QNX independently of
  this implementation: ETFS matched 32 of 32 entries and EFS 31 of 31.

  ETFS has no magic number. It is claimed only when the region divides evenly
  into (page + 16)-byte pages AND its .filetable carries the fixed reserved
  names .filetable/.badblks/.counts/.lost+found/.reserved at their fixed file
  ids, so a chance page-count match cannot pass. EFS is claimed by its
  QSSL_F3S boot record with a valid F3S revision, in a unit that opens with a
  unit_info of the same byte order and whose header 2 points at the record.
  Neither fired on the u-boot, boot_fs or ext partitions of the two vehicle
  images tested. The extent status bits and the endian byte are from
  fs/f3s_spec.h as qnxmount's spec pins it (RunZeJustin/qnx660 at 47c4158e).

  For QNX4, the filesystem of QNX 4 (distinct from qnx6):
  QNX4_SUPER_MAGIC       0x002f   linux/include/uapi/linux/magic.h:54
  struct qnx4_inode_entry         linux/include/uapi/linux/qnx4_fs.h:44
  struct qnx4_link_info           linux/include/uapi/linux/qnx4_fs.h:63
  struct qnx4_xblk ("IamXblk")    linux/include/uapi/linux/qnx4_fs.h:71
  field widths                    linux/include/uapi/linux/qnxtypes.h
  directory entry union           linux/fs/qnx4/qnx4.h:75

  The 0x002f magic is simply the "/" name of the root directory inode at the
  start of the superblock, which is block 1, 512 bytes into the volume. The
  walk follows the kernel's own read-only driver: inline 64-byte inode
  entries for names up to 16 bytes, link entries resolving longer names
  (up to 48) through the .inodes file, and extents 2..n of a file through
  the "IamXblk" chain that fs/qnx4/inode.c qnx4_block_map() follows.
  Detection requires what the kernel itself requires to mount: the "/" root
  inode with a directory mode, and a ".bitmap" entry in the root directory
  (fs/qnx4/inode.c qnx4_checkroot). A QNX4 boot block can end in 0x55AA, so
  the MBR parser declines a sector whose following sector is a QNX4 root
  superblock, the same shared-magic rule applied to FAT above.

  The QNX4 reader was validated by round-trip against the Linux kernel
  driver itself: a fixture populated with nested directories, a multi-extent
  file, a name over 16 bytes, a symlink, an empty file and distinct modes,
  owners and mtimes was mounted read-only with fs/qnx4 on kernel 7.0.0, and
  every path, type, permission, owner, size, mtime, symlink target and byte
  of file content the kernel reported matched what this walker reads, 15 of
  15 entries. The fixture was written by a separate generator program, not
  by this parser, so the two sides are independent. Synthetic-only
  validation: no confirmed real QNX4 volume exists in the test corpus, and
  the one candidate partition (a Ford Sync G4 slot named boot_fs) turned out
  to carry a RAW0 container, not QNX4.

  For the Linux flash filesystems, from the Linux kernel at v7.0 (commit
  028ef9c96e96197026887c0f092424679298aae8):
  SQUASHFS_MAGIC     0x73717368   linux/include/uapi/linux/magic.h:20
  struct squashfs_super_block     linux/fs/squashfs/squashfs_fs.h:241
  JFFS2_MAGIC_BITMASK    0x1985   linux/include/uapi/linux/jffs2.h:25
  struct jffs2_raw_inode          linux/include/uapi/linux/jffs2.h:135
  UBI_EC_HDR_MAGIC   0x55424923   linux/drivers/mtd/ubi/ubi-media.h:29
  UBI_VID_HDR_MAGIC  0x55424921   linux/drivers/mtd/ubi/ubi-media.h:31
  struct ubi_vtbl_record          linux/drivers/mtd/ubi/ubi-media.h:355
  UBIFS_NODE_MAGIC   0x06101831   linux/fs/ubifs/ubifs-media.h:25

  How each reader chooses among versions and copies follows the code that
  makes the choice: fs/jffs2/readinode.c for JFFS2, drivers/mtd/ubi/attach.c
  ubi_compare_lebs for UBI, fs/ubifs/replay.c for the UBIFS journal. LZO1X
  is decoded from lib/lzo/lzo1x_decompress_safe.c and LZ4 from lz4's
  lz4_Block_format.md at v1.10.0, both carried as pure Python; zstd needs
  Python 3.14 (compression.zstd). SquashFS 4.0 is walked, 1.x to 3.x only
  reported.

  For YAFFS1 and YAFFS2, from Aleph One's yaffs2 at commit
  474b3acb927d27b2305618aaf24456b9d33fe91b:
  object ids, root 1 .. 0x10      yaffs2/core/yaffs_guts.h:94-100
  struct yaffs_spare              yaffs2/core/yaffs_guts.h:225
  struct yaffs_obj_hdr            yaffs2/core/yaffs_guts.h:330
  YAFFS2 packed tags              yaffs2/core/yaffs_packedtags2.c
  YAFFS2 scan rules               yaffs2/core/yaffs_yaffs2.c yaffs2_scan_chunk

  YAFFS records no page size, spare size or tag position, so eleven common
  page and spare sizes, and for YAFFS2 every tag offset and both byte orders,
  are tried; a layout is kept only when 90% of the used spares hold plausible
  tags and 90% of the pages they call headers parse as headers.

  Each flash reader is validated against images the format's own tools wrote
  (squashfs-tools 4.7.5, mtd-utils 2.3.0, yaffs2's image makers) and against
  oracles it never touches: sha256sum and stat over the source tree, and
  unsquashfs -lln. Those tools leave no history, so JFFS2, UBI and UBIFS are
  also validated against images the Linux kernel's own drivers wrote with
  history (overwrites, deletion, renames, truncation, garbage collection, a
  UBIFS journal not yet committed, older copies of UBI blocks) and read back,
  and YAFFS against images YAFFS's own code wrote and read back the same way.
  The NAND ones come from the kernel's simulated chip (nandsim), taken with
  nanddump --oob. None has yet been run against flash from a real device.

  A flash dump with no partition table and nothing recognised at offset 0 is
  searched at every 4 KiB boundary for SquashFS, UBI and JFFS2, each reported
  under FLASH as its own volume. For UBI and JFFS2 in a NAND dump that still
  carries its spare bytes, the common page and spare sizes are tried and the
  spare is stripped.

  For BitLocker, from Joachim Metz's BDE format document in libyal/libbde at
  commit 96e3c5dce6143c2702c90f3903018fb8c12a8956:
  volume header, FVE metadata     documentation/...BDE) format.asciidoc
  recovery password, user key     sections "Recovery key", "User key"
  AES-CBC IV, AES-XTS tweak       sections "AES-CBC", "AES-XTS"
  sector read-back rules          libbde/libbde_sector_data.c:274-420
  Encrypt-on-Write map            libbde/libbde_volume.c:1668
  Checked against 13 volumes Windows 11 wrote (NTFS, FAT32, exFAT; AES-CBC
  and AES-XTS at 128 and 256 bits; password, recovery password, startup key,
  clear key; conversions paused while encrypting and decrypting).

  For APFS encryption, from Apple's Apple File System Reference (2020-06-22):
  the volume flags, APFS_FS_UNENCRYPTED    apfs_superblock_t, "Volume Flags"
  An encrypted volume is told locked or in the clear by its tree's root node's
  Fletcher-64 checksum, checked against a volume macOS encrypted and against
  Digital Collector's AFF4 of an Apple silicon Mac.
  Opening one with its password, from the same reference and libfsapfs:
  keybags, KEK, VEK, APFS_FS_ONEKEY  "Encryption", "Accessing Encrypted Objects"
  OMAP_VAL_ENCRYPTED, om_flags       "Object Maps"
  keybag AES-XTS, KEK record fields  libfsapfs "Apple File System (APFS).asciidoc"
  data tweak from crypto_id          libfsapfs_file_system_data_handle.c:274-307
  (libfsapfs at commit f63c83b462275214fc5e4b0919540d892f50b467). Checked
  against two volumes macOS 26 encrypted, one encrypted as it was made and one
  encrypted in place after files were written.

  For NTFS reparse points, cloud placeholders and overlay compression, from
  Microsoft: reparse tags [MS-FSCC] 2.1.2.1; file attributes [MS-FSCC] 2.6;
  the overlay's reparse data WOF_EXTERNAL_INFO and
  FILE_PROVIDER_EXTERNAL_INFO_V1; chunk sizes WOF_FILE_COMPRESSION_INFO_V1;
  the LZ77+Huffman block [MS-XCA] 2.1. The algorithm numbers, the chunk table
  and the decoder are checked against files Windows 11 wrote and Windows's own
  hashes of them. SF_DATALESS is from macOS's sys/stat.h and is not exercised.

  --list walks qnx6 through the same block resolution the kernel uses in
  qnx6_block_map(), including multi-level indirect trees and long filenames
  held out of line in the Longfile tree, and walks ext through its extent
  trees. Both are read-only.

note:
  The image is opened read-only and is never written to. The Linux qnx6 driver
  has no write path at all, so mounting a qnx6 volume on Linux cannot alter
  these timestamps either.
"""


if __name__ == "__main__":
    import argparse
    ap = argparse.ArgumentParser(
        prog="qnxprobe.py",
        description="Read QNX6, QNX4, ETFS, EFS, ext2/3/4, Btrfs, F2FS, FAT32, FAT16, FAT12, exFAT, NTFS, ReFS, HFS+, "
                    "APFS and XFS filesystems, the Linux flash filesystems SquashFS, JFFS2, "
                    "UBI/UBIFS and YAFFS1/YAFFS2, QNX IFS boot images, and the U-Boot "
                    "environment and Belkin libnvram stores a flash chip carries, out of "
                    "raw disk images and flash dumps, the logical volumes of an LVM2 "
                    "physical volume (linear, striped, RAID1, RAID4/5/6/10) and Linux md "
                    "RAID arrays (linear, RAID0/1/4/5/6/10, from members given together) "
                    "included: identify each by its own on-disk structure rather "
                    "than trusting a partition type byte, list, and extract to a "
                    "zip with a provenance manifest. No mounting, no admin "
                    "rights, standard library only.",
        epilog=EPILOG,
        formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("image", nargs="*",
                    help="disk image, partition image, or raw dump to examine; give every "
                         "member image of a RAID set to read the array, or one of them "
                         "with --find-members")
    ap.add_argument("--scan-limit", type=int, default=256, metavar="MiB",
                    help="how far to brute scan when no superblock sits at the "
                         "offsets the kernel checks (default: 256)")
    ap.add_argument("--self-test", action="store_true",
                    help="build throwaway positive and negative images, confirm "
                         "the detector reports both ways, then delete them")
    ap.add_argument("--list", action="store_true",
                    help="walk each filesystem found and list its contents "
                         "(qnx6, qnx4, ext2/3/4, Btrfs, FAT32, FAT16, FAT12, exFAT, NTFS, ReFS, HFS+, APFS, XFS, ETFS and EFS)")
    ap.add_argument("--depth", type=int, default=2, metavar="N",
                    help="how deep to walk with --list (default: 2)")
    ap.add_argument("--list-max", type=int, default=400, metavar="N",
                    help="stop after this many entries per filesystem (default: 400)")
    ap.add_argument("--allow-unequal-segments", action="store_true",
                    help="join a split image (.001, .002 ...) whose segments before the "
                         "last are not one size, or whose last is the largest. Without "
                         "it such a set is refused: a segment cut short or padded reads "
                         "every byte after it at the wrong offset. Use it only for a set "
                         "known to be whole as it is")
    ap.add_argument("--extract", metavar="OUT.zip",
                    help="copy the logical files out of every filesystem found "
                         "into a zip, ready for a LEAPP tool. No mounting, no "
                         "administrator rights, same on macOS, Windows and Linux")
    ap.add_argument("--unallocated", metavar="DIR",
                    help="write the free space of every volume whose filesystem "
                         "reports it (qnx6, F2FS, FAT32, FAT16, FAT12, exFAT, NTFS, HFS+, APFS) into "
                         "DIR: one .bin per volume, a .tsv mapping it back to the "
                         "image, and unallocated.json. DIR must be new or empty")
    ap.add_argument("--exclude", metavar="TEXT", action="append",
                    help="skip any path containing TEXT when extracting. "
                         "Repeatable. Use it to leave out encrypted subtrees "
                         "and bulk payloads that no parser can read")
    ap.add_argument("--only", metavar="TEXT",
                    help="restrict --list, --extract and --unallocated to "
                         "partitions whose name or label contains TEXT")
    ap.add_argument("--triage", action="store_true",
                    help="rank the volumes found by how much each has been "
                         "written, and flag encrypted or bulk ones, so you know "
                         "what to extract first")
    ap.add_argument("--progress", action="store_true",
                    help="while extracting, emit one JSON progress object per line on "
                         "stderr, for a caller driving this as a subprocess. stdout, "
                         "the human readable report, is unchanged")
    ap.add_argument("--password-file", metavar="FILE", action="append", default=[],
                    help="for an encrypted image (an Apple disk image, an AD-encrypted "
                         "FTK Imager acquisition or an encrypted AFF), a BitLocker "
                         "volume, an encrypted APFS volume or a LUKS container: a password or "
                         "recovery password (for APFS, the personal recovery key), the "
                         "first line of FILE. Repeatable; each opens with the first one "
                         "that opens it")
    ap.add_argument("--password-env", metavar="NAME", action="append", default=[],
                    help="for an encrypted image, a BitLocker volume, an encrypted "
                         "APFS volume or a LUKS container: a password, "
                         "from the environment variable NAME. Repeatable. Without either, "
                         "qnxprobe asks at a terminal for an encrypted image's password. "
                         "A password is never taken as an argument, which would show in "
                         "the process list")
    ap.add_argument("--bitlocker-key", metavar="FILE", action="append", default=[],
                    help="a BitLocker startup key (a .BEK file), tried against every "
                         "BitLocker volume. Repeatable")
    ap.add_argument("--private-key", metavar="FILE", action="append", default=[],
                    help="for an AFF, an Apple disk image or an AD-encrypted set sealed "
                         "to a certificate: the certificate's RSA "
                         "private key, unencrypted, as PEM or DER. Repeatable; each "
                         "image opens with the first one that opens it")
    ap.add_argument("--find-members", action="store_true",
                    help="for an image that holds a Linux md member or an LVM2 physical "
                         "volume: look in its folder (not subfolders) for the other members "
                         "by the identity each file records (md array uuid; LVM volume group "
                         "id and a physical volume id its metadata lists), name every file "
                         "added and why each other file was not, then read them as though "
                         "they had been given")
    ap.add_argument("--version", action="version",
                    version=f"qnxprobe {QNXPROBE_VERSION}")
    args = ap.parse_args()

    if args.self_test:
        print("\nqnxprobe self-test\n")
        sys.exit(self_test())

    if not args.image:
        ap.print_help()
        sys.exit(2)

    missing = [p for p in args.image if not os.path.exists(p)]
    if missing:
        sys.exit("not found: " + ", ".join(missing))

    given_passwords = _cli_passwords(args.password_file, args.password_env)

    reporter = ProgressEmitter() if args.progress else None
    manifest = []
    zf = None
    if args.extract:
        if os.path.exists(args.extract):
            sys.exit(f"refusing to overwrite an existing file: {args.extract}")
        zf = zipfile.ZipFile(args.extract, "w", zipfile.ZIP_DEFLATED,
                             allowZip64=True)
    unalloc_log = []
    if args.unallocated:
        if os.path.exists(args.unallocated) and (not os.path.isdir(args.unallocated)
                                                 or os.listdir(args.unallocated)):
            if zf is not None:
                zf.close()
                os.remove(args.extract)
            sys.exit(f"refusing to write into an existing file or a folder that is "
                     f"not empty: {args.unallocated}")
        os.makedirs(args.unallocated, exist_ok=True)
    refused = []
    run_images = (_cli_find_members(args.image, given_passwords, args.private_key)
                  if args.find_members else list(args.image))
    # Two paths that open one disk (two segments of one EWF or split raw set, a
    # link, the same path twice) are read once, as the first, and said so.
    given_order = same_disk_paths(run_images)
    run_images = [img for img, first in given_order if first is None]
    # RAID members among the images, whole disks or partitions, assembled into
    # arrays (raid_assemble); each array is read after the images, as an image
    # of its own. An image that holds no member is read exactly as before.
    raidset = raid_open(run_images, given_passwords, args.private_key)
    try:
        for p, same_as in given_order:
            if same_as is not None:
                print("=" * 78)
                print(p)
                print(f"  {same_disk_note(p, same_as)}")
                print("=" * 78)
                print()
                continue
            try:
                asked, tries = [], 0
                while True:
                    try:
                        main(p, scan_limit_mib=args.scan_limit, do_list=args.list,
                             list_depth=args.depth, list_max=args.list_max,
                             extract=args.extract, only=args.only, zf=zf,
                             do_triage=args.triage, exclude=args.exclude,
                             reporter=reporter, manifest=manifest,
                             passwords=given_passwords or asked,
                             key_files=args.bitlocker_key, private_keys=args.private_key,
                             unallocated=args.unallocated, unallocated_log=unalloc_log,
                             allow_unequal_segments=args.allow_unequal_segments)
                        break
                    except ImagePasswordError as exc:
                        if exc.needs == "private key":
                            if args.private_key:
                                raise
                            raise ImagePasswordError(
                                f"{exc}; give that key with --private-key", False,
                                "private key") from None
                        # asked for at a terminal only when none was given, three
                        # tries; otherwise refused like any image that will not open
                        if given_passwords or not sys.stdin.isatty() or tries == 3:
                            if not given_passwords and not exc.wrong:
                                raise ImagePasswordError(
                                    f"{exc}; give it with --password-file or "
                                    f"--password-env, or run qnxprobe at a terminal "
                                    f"to be asked for it", False) from None
                            raise
                        if exc.wrong:
                            print("that password does not open the image",
                                  file=sys.stderr)
                        asked = [getpass.getpass(
                            f"password for {os.path.basename(os.path.normpath(p))}: ")]
                        tries += 1
            except (SplitImageError, ImageUnreadable,
                    *((ewfprobe.EwfError,) if ewfprobe is not None else ())) as exc:
                # a segment set that is not whole, an image this tool cannot open,
                # or an acquisition its reader refuses as damaged or incomplete:
                # said out loud and left unread, never joined around, and the
                # exit status says so
                print("=" * 78)
                print(p)
                print(f"  REFUSED: {exc}")
                print("=" * 78)
                refused.append(p)
        refused += raid_run(raidset, len(run_images), lambda raid_arr: main(
            raid_arr.safe_name, scan_limit_mib=args.scan_limit, do_list=args.list,
            list_depth=args.depth, list_max=args.list_max,
            extract=args.extract, only=args.only, zf=zf,
            do_triage=args.triage, exclude=args.exclude,
            reporter=reporter, manifest=manifest, passwords=given_passwords,
            key_files=args.bitlocker_key, private_keys=args.private_key,
            unallocated=args.unallocated, unallocated_log=unalloc_log,
            image=raid_arr.image, name_prefix=raid_arr.safe_name + "_",
            image_info={"raid": raid_arr.describe()}), find_members=args.find_members)
    finally:
        raidset.close()
        if zf is not None:
            # The provenance record. For a standalone image the directory names
            # are otherwise the only statement of where a file came from; this
            # ties every volume back to the image by LBA and recorded volume id,
            # so the extraction can be checked against any partition tool
            # without trusting the names.
            if manifest:
                zf.writestr("volumes.json", json.dumps(
                    {"written_by": f"qnxprobe {QNXPROBE_VERSION}",
                     "volumes": manifest}, indent=2) + "\n")
            zf.close()
            print(f"\nwrote {args.extract}  "
                  f"({os.path.getsize(args.extract):,} bytes)")
        if args.unallocated:
            with open(os.path.join(args.unallocated, "unallocated.json"), "w",
                      encoding="utf-8") as ujs:
                json.dump({"written_by": f"qnxprobe {QNXPROBE_VERSION}",
                           "offsets": "bytes into the image as read (for an acquisition "
                                      "container or a split set, the disk it holds)",
                           "not_included": "space no recognised volume covers",
                           "volumes": unalloc_log}, ujs, indent=2)
                ujs.write("\n")
            ua_written = [r for r in unalloc_log if r["status"] == "written"]
            print(f"\nwrote free space of {len(ua_written)} of {len(unalloc_log)} volumes to "
                  f"{args.unallocated}  ({sum(r['bytes'] for r in ua_written):,} bytes)")
    if refused:
        sys.exit(1)
